class _OverviewIdentitySpeculation:
    """An identity lookup started before its route proof finished.

    Its result is only ever used when the validation that follows is usable
    and nothing about the execution changed in between; otherwise it is
    cancelled and nothing from it - IP, profile or evidence - is published.
    """

    def __init__(
        self,
        *,
        execution_epoch: tuple[int, ...],
        route_epoch: int,
        selector_intent: int,
    ) -> None:
        self.execution_epoch = execution_epoch
        self.route_epoch = route_epoch
        self.selector_intent = selector_intent
        self.started_at = time.monotonic()
        self.release = threading.Event()
        self.cancel = threading.Event()
        self.done = threading.Event()
        self.route_before: dict[str, Any] = {}
        self.result: dict[str, Any] | None = None
        self.error = ""

    def abandon(self) -> None:
        self.release.set()
        self.cancel.set()


def _overview_provider_outcomes(identity: dict[str, Any]) -> list[str]:
    """Summarise identity attempts without addresses or error text.

    Each entry is ``<source>v<family>:<status>[:<latency ms>][:<class>]`` where
    the class is an exception class name or ``http<status>``.
    """
    outcomes: list[str] = []
    for family in ("ipv4", "ipv6"):
        payload = identity.get(family)
        if not isinstance(payload, dict):
            continue
        for source in payload.get("evidence") or []:
            if not isinstance(source, dict):
                continue
            name = re.sub(r"[^A-Za-z0-9_.-]", "", str(source.get("source") or "?"))[:24] or "?"
            label = f"{name}v{family[-1]}"
            for attempt in source.get("attempts") or []:
                if not isinstance(attempt, dict):
                    continue
                for transport in [*(attempt.get("transport_retries") or []), attempt]:
                    if not isinstance(transport, dict):
                        continue
                    parts = [label, str(transport.get("status") or "unknown")[:12]]
                    latency = transport.get("latency_ms")
                    if isinstance(latency, (int, float)) and not isinstance(latency, bool):
                        parts.append(str(int(latency)))
                    http_status = transport.get("http_status")
                    error_class = str(transport.get("error") or "").split(":", 1)[0].strip()
                    if isinstance(http_status, int) and not isinstance(http_status, bool):
                        parts.append(f"http{http_status}")
                    elif _EXCEPTION_CLASS_TOKEN.fullmatch(error_class):
                        parts.append(error_class[:40])
                    outcomes.append(":".join(parts))
    return outcomes


class RecoverableCoreStartError(RuntimeError):
    """Core startup failed safely; the desktop runtime can keep collecting."""


RUNTIME_LISTENER_CONFLICT_MESSAGE = (
    "启动所需的网络资源正被占用，请停止占用后重试。"
)
RUNTIME_LISTENER_SETUP_MESSAGE = "无法启动，请检查网络设置后重试。"


class RuntimeListenerPreflightError(RuntimeError):
    """A required local listener is already owned by another process."""

    def __init__(self, conflicts: tuple[tuple[str, str, str, int], ...]) -> None:
        self.conflicts = tuple(conflicts)
        entries = self._diagnostic_endpoints(self.conflicts)
        self.diagnostic = {
            "code": "runtime_listener_conflict",
            # B-26(3) whitelist: {conflicts:[{kind,transport,host,port}]}.
            "params": {"conflicts": entries} if entries else {},
            "message": RUNTIME_LISTENER_CONFLICT_MESSAGE,
        }
        super().__init__(RUNTIME_LISTENER_CONFLICT_MESSAGE)

    @staticmethod
    def _diagnostic_endpoints(endpoints: Any) -> list[dict[str, Any]]:
        """Keep only kind/transport/IP-or-localhost host/port; no free text."""

        entries: list[dict[str, Any]] = []
        for item in tuple(endpoints or ())[:64]:
            try:
                kind, transport, host, port = item
            except (TypeError, ValueError):
                continue
            if not isinstance(kind, str) or not re.fullmatch(r"[a-z][a-z_]{0,31}", kind):
                continue
            if transport not in ("tcp", "udp"):
                continue
            if isinstance(port, bool) or not isinstance(port, int) or not 1 <= port <= 65535:
                continue
            entry: dict[str, Any] = {"kind": kind, "transport": transport}
            text = host.strip().strip("[]").split("%", 1)[0] if isinstance(host, str) else ""
            if text.casefold() == "localhost":
                entry["host"] = "localhost"
            else:
                try:
                    entry["host"] = str(ipaddress.ip_address(text))
                except ValueError:
                    pass
            entry["port"] = port
            if entry not in entries:
                entries.append(entry)
            if len(entries) >= 16:
                break
        return entries


def _runtime_start_failure_params(exc: BaseException) -> dict[str, Any]:
    """Facts that let the log say why a start failed, not just that it did."""

    params: dict[str, Any] = {"reason": str(exc) or type(exc).__name__}
    conflicts = getattr(exc, "conflicts", None)
    if isinstance(conflicts, tuple) and conflicts:
        params["endpoints"] = ", ".join(
            f"{host}:{port}" for _kind, _transport, host, port in conflicts
        )
    return params


class RuntimeListenerSetupError(RuntimeError):
    """A required listener could not be prepared without proven occupancy."""

    def __init__(
        self,
        result: RuntimeListenerPreflightResult | None = None,
        fault_kind: str | None = None,
    ) -> None:
        self.result = result
        # Failed probes are not proven occupancy: never reported as conflicts.
        specs = [
            spec
            for spec in (
                getattr(failure, "spec", None)
                for failure in (getattr(result, "failures", None) or ())
            )
            if spec is not None
        ]
        if not specs and isinstance(fault_kind, str):
            # Core reported this kind's bind failure but the re-preflight found
            # no failed probe: the configured endpoints of that kind are the
            # ones that could not be prepared.
            specs = [
                spec
                for spec in (getattr(result, "specs", None) or ())
                if getattr(spec, "kind", None) == fault_kind
            ]
        entries = RuntimeListenerPreflightError._diagnostic_endpoints(
            [
                tuple(getattr(spec, name, None) for name in ("kind", "transport", "host", "port"))
                for spec in specs
            ]
        )
        self.diagnostic = {
            "code": "runtime_listener_unavailable",
            "params": {"unavailable": entries} if entries else {},
            "message": RUNTIME_LISTENER_SETUP_MESSAGE,
        }
        super().__init__(RUNTIME_LISTENER_SETUP_MESSAGE)


