class _RuntimeAbortHandle:
    """Thread-safe owner for the one close callback registered with a probe."""

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._resource: Any | None = None
        self._aborted = False

    def bind(self, resource: Any) -> None:
        close_now = False
        with self._lock:
            if self._aborted:
                close_now = True
            else:
                self._resource = resource
        if close_now:
            self._close(resource)

    @staticmethod
    def _close(resource: Any) -> None:
        # close() alone does not wake a Windows recv while a makefile() still
        # owns the socket. Shutdown first so cancellation releases its slot.
        if isinstance(resource, socket.socket):
            try:
                resource.shutdown(socket.SHUT_RDWR)
            except OSError:
                pass
        try:
            if callable(resource):
                resource()
            else:
                resource.close()
        except Exception:
            pass

    def clear(self, resource: Any) -> None:
        with self._lock:
            if self._resource is resource:
                self._resource = None

    def abort(self) -> None:
        with self._lock:
            self._aborted = True
            resource = self._resource
        if resource is not None:
            self._close(resource)


