        self._tier3_egress_activation_pending_mode = ""
        self._tier3_egress_activation_active_mode = ""
        self._tier3_egress_activation_pending_key: tuple[Any, ...] | None = None
        self._tier3_initial_activation_trace_lock = threading.Lock()
