    def _ensure_authoritative_monitor_log_handler(self) -> dict[str, object]:
        expected_path = self.app_paths.log_file
        status = authoritative_log_handler_status(self.logger, expected_path)
        if bool(status.get("valid")):
            return status
        log_raw_diagnostic(
            self.logger,
            "error",
            "Authoritative monitor log handler drift detected "
            "(expected=%s count=%s actual=%s)",
            status.get("expected_path"),
            status.get("handler_count"),
            status.get("actual_paths"),
        )
        self.logger = setup_logging(
            log_file=str(expected_path),
            level=self.alerts_config.get("level", "INFO"),
        )
        repaired = authoritative_log_handler_status(self.logger, expected_path)
        log_raw_diagnostic(
            self.logger,
            "error",
            "Authoritative monitor log handler repaired "
            "(expected=%s valid=%s)",
            repaired.get("expected_path"),
            repaired.get("valid"),
        )
        flush_logging_handlers(self.logger)
        return repaired

    def _close_authoritative_monitor_log_handler(self) -> int:
        """Release the runtime-owned file sink after a successful stop."""

        expected_path = str(self.app_paths.log_file.resolve())
        closed = 0
        for handler in tuple(self.logger.handlers):
            if not getattr(handler, "_tesseract_authoritative_file_handler", False):
                continue
            configured_path = str(
                getattr(handler, "_tesseract_authoritative_log_path", "")
                or getattr(handler, "baseFilename", "")
                or ""
            ).strip()
            try:
                configured_path = str(Path(configured_path).resolve())
            except OSError:
                pass
            if configured_path != expected_path:
                continue
            try:
                handler.flush()
            finally:
                handler.close()
                self.logger.removeHandler(handler)
                closed += 1
        return closed

    def alert_delivery_records(self, limit: int = 200) -> list[dict[str, Any]]:
        return self.alert_delivery_store.recent(limit=max(1, int(limit)))

    def delete_alert_delivery_records(self, channel_id: str) -> int:
        return self.alert_delivery_store.delete_channel(channel_id)

    def alert_channel_health(self) -> list[dict[str, Any]]:
        return self.alert_delivery_store.health_for_entries(
            normalized_notification_channels(self.alerts_config)
        )

    def _write_runtime_lifecycle_journal(
        self,
        event: str,
        *,
        nonblocking: bool = False,
        core_process_running: bool | None = None,
        **details: Any,
    ) -> None:
        if core_process_running is None:
            core_process_running = bool(
                self.core_runner and self.core_runner.is_running()
            )
        payload = {
            "schema_version": 1,
            "event": str(event or "unknown"),
            "at": utc_now_iso(),
            "runtime_generation": int(self._runtime_generation),
            "runtime_service_running": bool(self.running),
            "stop_requested": bool(self.stop_event.is_set()),
            "core_process_running": bool(core_process_running),
            "last_runtime_stop": dict(self._last_runtime_stop),
            **details,
        }
        path = self._runtime_lifecycle_journal_path
        path.parent.mkdir(parents=True, exist_ok=True)
        temporary = path.with_name(
            f".{path.name}.{os.getpid()}.{threading.get_ident()}.tmp"
        )
        acquired = self._runtime_lifecycle_journal_lock.acquire(
            blocking=not bool(nonblocking)
        )
        if not acquired:
            return
        try:
            try:
                temporary.write_text(
                    json.dumps(payload, ensure_ascii=False, indent=2),
                    encoding="utf-8",
                )
                replace_with_retry(temporary, path)
            except OSError:
                try_log_nowait(
                    self.logger,
                    "warning",
                    "Failed to persist desktop runtime lifecycle journal",
                    exc_info=True,
                    extra=_RAW_ONLY_LOG_EXTRA,
                )
                try:
                    temporary.unlink(missing_ok=True)
                except OSError:
                    pass
        finally:
            self._runtime_lifecycle_journal_lock.release()

    def _write_runtime_lifecycle_heartbeat_if_due(self) -> None:
        now = time.monotonic()
        if now - self._runtime_lifecycle_last_heartbeat_at < 5.0:
            return
        self._runtime_lifecycle_last_heartbeat_at = now
        self._write_runtime_lifecycle_journal("heartbeat")

    def _record_recoverable_core_start_error(
        self,
        exc: RecoverableCoreStartError,
        *,
        update_last_error: bool,
    ) -> str:
        error = str(exc)
        from bridge_messages import startup_diagnostic
        previous_failure = getattr(self, "_bridge_start_failure_record", None)
        known_diagnostic = (previous_failure[2] if previous_failure
                            and previous_failure[:2] == (int(self._runtime_generation), error)
                            else None)
        self._bridge_start_failure_record = (
            int(self._runtime_generation), error,
            startup_diagnostic(exc, diagnostic=known_diagnostic))
        manager = self.manager
        live_reason = self._tier3_startup_live_collection_reason(manager) if manager else ""
        self._start_deferred_reason = live_reason or error
        self._start_deferred_is_live = bool(live_reason)
        if update_last_error and not live_reason:
            self.last_error = error
        elif live_reason:
            self.last_error = None
        self._set_effective_egress_state(False, error)
        if live_reason:
            self.logger.info(
                "Desktop core start deferred while Bastion Layer recovers: %s",
                exc,
            )
        else:
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Desktop core start deferred while Bastion Layer recovers: %s",
                exc,
            )
        return error

    def _set_tier3_startup_gate_required(self, required: bool) -> None:
        manager = self.manager
        marker = getattr(manager, "mark_tier3_startup_gate_required", None) if manager else None
        if callable(marker):
            try:
                marker(bool(required))
            except Exception:
                log_raw_diagnostic(
                    self.logger,
                    "warning",
                    "Failed to update Bastion Layer startup gate requirement",
                    exc_info=True,
                )

    def _quiesce_tier3_for_runtime_recovery(self) -> dict[str, Any]:
        """Publish recovery pressure before any activation/recovery dial.

        Manager owns the collector and validator workers.  The callback only
        closes their admission gates and waits for the bounded drain contract;
        it never cancels a node result or mutates the durable pool.
        """

        manager = getattr(self, "manager", None)
        setter = getattr(manager, "set_runtime_recovery_pressure", None)
        if callable(setter):
            result = setter(True)
            return dict(result) if isinstance(result, dict) else {"active": True}
        return {"active": False, "reason": "manager_unavailable"}

    def _resume_tier3_after_runtime_recovery(self) -> dict[str, Any]:
        manager = getattr(self, "manager", None)
        setter = getattr(manager, "set_runtime_recovery_pressure", None)
        if callable(setter):
            result = setter(False)
            return dict(result) if isinstance(result, dict) else {"active": False}
        return {"active": False, "reason": "manager_unavailable"}

    def _reset_runtime_recovery_pressure_lifecycle(self) -> None:
        coordinator = getattr(self, "_runtime_recovery_pressure", None)
        if coordinator is None:
            return
        snapshot = coordinator.snapshot()
        coordinator.reset_for_lifecycle(snapshot.lifecycle_generation + 1)

    def _cancel_runtime_background_work(self) -> None:
        """Close background registration gates and publish local cancellation."""

        cancel_event = getattr(
            self,
            "_exit_quality_static_refresh_cancel_event",
            None,
        )
        if cancel_event is not None:
            cancel_event.set()
        probe_broker = getattr(self, "_runtime_probe_broker", None)
        if probe_broker is not None:
            probe_broker.stop(cancel_active=True)
        recovery_pressure = getattr(self, "_runtime_recovery_pressure", None)
        if recovery_pressure is not None:
            recovery_pressure.stop(timeout_seconds=0.5)
        self._runtime_egress_coordinator.stop()
        clear_runtime_health = getattr(
            self.manager,
            "clear_runtime_health_observations",
            None,
        ) if self.manager is not None else None
        if callable(clear_runtime_health):
            try:
                clear_runtime_health()
            except Exception:
                pass
        with self._tier3_egress_activation_lock:
            self._tier3_egress_activation_pending = False
            self._tier3_egress_activation_pending_mode = ""
            self._tier3_egress_activation_pending_key = None
            self._tier3_egress_activation_active_key = None
            self._tier3_egress_activation_generation += 1
        with self._tier3_pool_sync_lock:
            self._tier3_pool_sync_pending = False
            self._tier3_pool_sync_last_requested_at = 0.0
            self._tier3_pool_sync_oldest_requested_at = 0.0
            self._tier3_pool_sync_pending_commit_count = 0
            self._tier3_pool_sync_pending_immediate = False
            self._tier3_pool_sync_pending_event = "append_only"
            self._tier3_pool_sync_pending_key = None
            self._tier3_pool_sync_active_key = None
            self._tier3_pool_sync_parked_key = None
            self._tier3_pool_sync_parked_event = "append_only"
            self._tier3_pool_sync_last_attempted_key = None
        with self._tier3_core_gate_lock:
            self._tier3_core_gate_pending = False
            self._tier3_core_gate_requested_at = None
            self._tier3_core_gate_generation += 1
            self._tier3_core_gate_pending_generation = (
                self._tier3_core_gate_generation
            )

    def begin_session_end(self, *, request_core_exit: bool = False) -> None:
        """Publish irreversible RT-2 intent without lifecycle/manager teardown.

        The caller revokes both final write authorities before recovering, then
        calls again to signal only this runtime's Core after owned recovery.
        """
        with self._runtime_intent_lock:
            self._session_end_requested = True
            self._desired_running = False
            self._stop_request_pending = True
            self.stop_event.set()
            runner = self.core_runner if request_core_exit else None
        if request_core_exit:
            self._stop_runtime_post_dial_observer("session_end")
        if runner is not None:
            runner.request_stop()

    def request_stop(
        self,
        *,
        actor: str = "api",
        reason: str = "runtime stop requested",
        expected_generation: int | None = None,
    ) -> RuntimeStopIntent:
        """Publish a stop intent without waiting for lifecycle teardown.

        This path is intentionally limited to in-memory state plus cooperative
        cancellation signals.  The caller must schedule ``stop()`` to restore
        OS state and reap processes.
        """

        actor = str(actor or "api")
        reason = str(reason or "runtime stop requested")
        manager: Any | None = None
        runner: Any | None = None
        created = False
        with self._runtime_intent_lock:
            generation = int(self._runtime_generation)
            if expected_generation is not None and int(expected_generation) != generation:
                return RuntimeStopIntent(
                    intent_id=int(
                        self._active_stop_intent.intent_id
                        if self._active_stop_intent is not None
                        else self._stop_intent_sequence
                    ),
                    lifecycle_revision=int(self._lifecycle_revision),
                    generation=generation,
                    actor=actor,
                    reason=reason,
                    requested_at=utc_now_iso(),
                    accepted=False,
                    skipped_reason="stale_runtime_generation",
                )
            active = self._active_stop_intent
            if (
                self._stop_request_pending
                and active is not None
                and active.generation == generation
            ):
                intent = active
            else:
                self._lifecycle_revision += 1
                self._stop_intent_sequence += 1
                self._desired_running = False
                self._stop_request_pending = True
                self.stop_event.set()
                intent = RuntimeStopIntent(
                    intent_id=self._stop_intent_sequence,
                    lifecycle_revision=self._lifecycle_revision,
                    generation=generation,
                    actor=actor,
                    reason=reason,
                    requested_at=utc_now_iso(),
                )
                self._active_stop_intent = intent
                self._last_runtime_stop = {
                    "actor": actor,
                    "reason": reason,
                    "generation": generation,
                    "intent_id": intent.intent_id,
                    "lifecycle_revision": intent.lifecycle_revision,
                    "requested_at": intent.requested_at,
                    "completed_at": None,
                    "result": "stopping",
                }
                manager = self.manager or self._offline_subscription_manager
                runner = self.core_runner
                created = True

        if created:
            self._cancel_runtime_background_work()
            self._runtime_initial_activation_generation = -1
            self._publish_runtime_egress_readiness(
                RuntimeEgressReadinessState.FAIL_CLOSED,
                validation_active=False,
                reason=reason,
                expected_lifecycle_revision=intent.lifecycle_revision,
                effective_ok=False,
            )
            request_core_stop = getattr(runner, "request_stop", None)
            if callable(request_core_stop):
                try:
                    request_core_stop()
                except Exception:
                    try_log_nowait(
                        self.logger,
                        "warning",
                        "Failed to signal mihomo during stop request",
                        exc_info=True,
                        extra=_RAW_ONLY_LOG_EXTRA,
                    )
            if manager is not None:
                request_manager_stop = getattr(manager, "request_stop", None)
                if callable(request_manager_stop):
                    try:
                        request_manager_stop()
                    except Exception:
                        try_log_nowait(
                            self.logger,
                            "warning",
                            "Failed to broadcast manager cancellation during stop request",
                            exc_info=True,
                            extra=_RAW_ONLY_LOG_EXTRA,
                        )
        return intent

    def _stop_intent_is_current(self, intent: RuntimeStopIntent) -> bool:
        with self._runtime_intent_lock:
            active = self._active_stop_intent
            return bool(
                intent.accepted
                and self._stop_request_pending
                and active is not None
                and active.intent_id == intent.intent_id
                and active.lifecycle_revision == intent.lifecycle_revision
                and active.generation == intent.generation
            )

    def _finish_stop_intent(
        self,
        intent: RuntimeStopIntent,
        *,
        result: str,
        error: str | None = None,
        error_code: str = "",
        error_details: dict[str, Any] | None = None,
    ) -> None:
        with self._runtime_intent_lock:
            active = self._active_stop_intent
            if (
                active is None
                or active.intent_id != intent.intent_id
                or active.lifecycle_revision != intent.lifecycle_revision
            ):
                return
            self._stop_request_pending = False
            self._active_stop_intent = None
            self._desired_running = False
            self._last_runtime_stop["completed_at"] = utc_now_iso()
            self._last_runtime_stop["result"] = str(result)
            if error:
                self._last_runtime_stop["error"] = str(error)
            else:
                self._last_runtime_stop.pop("error", None)
            if error_code:
                self._last_runtime_stop["error_code"] = str(error_code)
            else:
                self._last_runtime_stop.pop("error_code", None)
            if error_details:
                self._last_runtime_stop["error_details"] = copy.deepcopy(
                    error_details
                )
            else:
                self._last_runtime_stop.pop("error_details", None)

    def _start_intent_is_current(self, lifecycle_revision: int) -> bool:
        with self._runtime_intent_lock:
            return bool(
                self._desired_running
                and not self._stop_request_pending
                and self._lifecycle_revision == int(lifecycle_revision)
                and not self.stop_event.is_set()
            )

    def _require_current_start_intent(self, lifecycle_revision: int) -> None:
        if not self._start_intent_is_current(lifecycle_revision):
            raise RuntimeStartCancelled(
                f"runtime start revision {lifecycle_revision} was superseded"
            )

    def _commit_runtime_started(self, lifecycle_revision: int) -> None:
        """Atomically publish the final start state against a stop request."""

        with self._runtime_intent_lock:
            if not (
                self._desired_running
                and not self._stop_request_pending
                and self._lifecycle_revision == int(lifecycle_revision)
                and not self.stop_event.is_set()
            ):
                raise RuntimeStartCancelled(
                    f"runtime start revision {lifecycle_revision} was superseded"
                )
            self.running = True
            monitor_thread = threading.Thread(
                target=self._monitor_loop,
                name="desktop-monitor-loop",
                daemon=True,
            )
            self.monitor_thread = monitor_thread
            # Thread.start() is a short, local operation. Keeping it inside the
            # intent commit means a stop can never publish between the final
            # revision check and monitor ownership becoming visible.
            monitor_thread.start()
        # Initial egress admission has one owner.  Core startup/promotion may
        # finish before the runtime lifecycle commit (the normal cold-start
        # order), while a Tier3 pool commit may finish afterwards.  Both
        # paths therefore converge here/on _request_initial_egress_admission
        # instead of transferring a mutable ``deferred`` flag between two
        # workers.  The queue itself deduplicates the immutable Core/provider
        # authority key.
        self._request_initial_egress_admission()

    def _preempt_runtime_io_for_stop(self) -> None:
        """Remove OS routing, then signal Mihomo, without lifecycle-lock waits."""

        try:
            result = self.restore_system_proxy()
            if isinstance(result, dict) and result.get("state") in {
                "failed", "unknown", "not_owned",
            }:
                raise RuntimeError(str(
                    result.get("error_code") or result.get("last_error") or result["state"]
                ))
        except Exception as exc:
            self.last_error = str(exc)
            try_log_nowait(
                self.logger,
                "error",
                "Failed to restore system proxy during stop preemption: %s",
                exc,
                extra=_RAW_ONLY_LOG_EXTRA,
            )
        runner = self.core_runner
        request_core_stop = getattr(runner, "request_stop", None) if runner else None
        if callable(request_core_stop):
            try:
                request_core_stop()
            except Exception:
                try_log_nowait(
                    self.logger,
                    "warning",
                    "Failed to signal mihomo during stop preemption",
                    exc_info=True,
                    extra=_RAW_ONLY_LOG_EXTRA,
                )

    def start(self, *, start_core: bool = True) -> dict[str, Any]:
        with self._runtime_lifecycle_lock:
            with self._runtime_intent_lock:
                if self._stop_request_pending:
                    return self.status(include_runtime_nodes=False)
                if not self.running:
                    background_activity = self._runtime_background_activity()
                    last_stop_failed = (
                        str(self._last_runtime_stop.get("result") or "")
                        == "failed"
                    )
                    if last_stop_failed or any(background_activity.values()):
                        cleanup_status = self.status(
                            include_runtime_nodes=False
                        )
                        if (
                            cleanup_status.get("shutdown_cleanup_pending")
                            or any(background_activity.values())
                        ):
                            from bridge_messages import startup_diagnostic
                            self._bridge_start_cleanup_failure_record = (
                                self._runtime_generation, self._lifecycle_revision,
                                startup_diagnostic(diagnostic={"reason_code": "cleanup_pending"}),
                            )
                            cleanup_status["start_blocked_by_cleanup"] = True
                            cleanup_status["start_blocked_reason"] = (
                                "shutdown_cleanup_pending"
                            )
                            cleanup_owners = {
                                name
                                for name, active in background_activity.items()
                                if active
                            }
                            if (
                                cleanup_status.get("core_running")
                                or cleanup_status.get("core_cleanup_pending")
                            ):
                                cleanup_owners.add("mihomo_core")
                            if self.manager is not None:
                                cleanup_owners.add("manager")
                            if (
                                self.monitor_thread is not None
                                and self.monitor_thread.is_alive()
                            ):
                                cleanup_owners.add("runtime_monitor")
                            cleanup_status["start_blocked_owners"] = sorted(
                                cleanup_owners
                            )
                            return cleanup_status
                    self._lifecycle_revision += 1
                    self._desired_running = True
                    self.stop_event.clear()
                    self._exit_quality_static_refresh_cancel_event.clear()
                else:
                    self._desired_running = True
                lifecycle_revision = int(self._lifecycle_revision)
            self._monitor_log_handler_status = (
                self._ensure_authoritative_monitor_log_handler()
            )
            if not self.running:
                with self._runtime_intent_lock:
                    self._runtime_generation += 1
                    runtime_generation = int(self._runtime_generation)
                self._reset_runtime_recovery_pressure_lifecycle()
                self._reset_runtime_failure_monitor_state()
                self._route_lease_reset_for_start()
                self._route_lease_ensure_thread()
                self._reset_runtime_source_transport(
                    runtime_generation=runtime_generation,
                )
                # One Tier3 naming and provider lane per runtime session:
                # reload_config swaps self.config without a Core config load,
                # so a changed switch applies at the next start.
                self._tier3_verified_provider_writes_latched = (
                    self._tier3_verified_provider_writes_configured()
                )
                # The verified lane's per-session state starts fresh too: the
                # retry backoff, kicked-pick stamps and their re-run signature
                # belong to the previous session's Core.
                self._tier3_online_growth_waits = 0
                self._tier3_online_growth_waited_at = 0.0
                self._tier3_kicked_pick_since = {}
                self._tier3_kicked_pick_retry_signature = None
                log_event(
                    self.logger,
                    "INFO",
                    "runtime.start_requested",
                    "Desktop runtime start requested "
                    f"(generation={self._runtime_generation} start_core={bool(start_core)})",
                    params={"generation": int(self._runtime_generation)},
                )
                flush_logging_handlers(self.logger)
                self._write_runtime_lifecycle_journal(
                    "start_requested",
                    start_core=bool(start_core),
                )
            return self._start_locked(
                start_core=start_core,
                lifecycle_revision=lifecycle_revision,
            )

    def _new_proxy_tier_manager(self) -> ProxyTierManager:
        kwargs: dict[str, Any] = {
            "config": self.config,
            "logger": self.logger,
            "alerts": self.alerts,
            "kill_switch": self.kill_switch,
        }
        try:
            parameters = inspect.signature(ProxyTierManager).parameters.values()
        except (TypeError, ValueError):
            parameters = ()
        if any(
            parameter.kind == inspect.Parameter.VAR_KEYWORD
            or parameter.name == "subscription_operation_coordinator"
            for parameter in parameters
        ):
            kwargs["subscription_operation_coordinator"] = (
                self.subscription_operation_coordinator
            )
        manager = ProxyTierManager(**kwargs)
        # Compatibility for a Manager implementation predating the injectable
        # constructor.  No subscription operation starts during construction,
        # so binding immediately afterwards preserves the same ownership.
        if (
            getattr(manager, "subscription_operation_coordinator", None)
            is not self.subscription_operation_coordinator
        ):
            manager.subscription_operation_coordinator = (
                self.subscription_operation_coordinator
            )
        return manager

    def _start_locked(
        self,
        *,
        start_core: bool = True,
        lifecycle_revision: int,
    ) -> dict[str, Any]:
        self._require_current_start_intent(lifecycle_revision)
        if self.running:
            if start_core:
                try:
                    self._preflight_runtime_listeners()
                    self.start_core()
                    self._require_current_start_intent(lifecycle_revision)
                    self.last_error = None
                    self._start_deferred_reason = None
                    self._start_deferred_is_live = False
                except RecoverableCoreStartError as exc:
                    self._record_recoverable_core_start_error(exc, update_last_error=True)
                except Exception as exc:
                    self.last_error = str(exc)
                    from bridge_messages import startup_diagnostic
                    self._bridge_start_failure_record = (
                        int(self._runtime_generation), self.last_error, startup_diagnostic(exc))
                    log_event(
                        self.logger,
                        "ERROR",
                        "runtime.mihomo_failed",
                        "Desktop core start failed",
                        exc_info=True,
                    )
                    raise
            return self.status()

        core_start_error: str | None = None
        try:
            build_unkill_script(str(self.app_paths.unkill_script_path))
            self._require_current_start_intent(lifecycle_revision)
            build_restore_proxy_script(str(self.app_paths.restore_proxy_script_path))
            self._require_current_start_intent(lifecycle_revision)
            self.recover_stale_system_proxy()
            self._require_current_start_intent(lifecycle_revision)
            if start_core:
                self._preflight_runtime_listeners()
                self._require_current_start_intent(lifecycle_revision)
            self.kill_switch = KillSwitchManager(
                config=killswitch_block(self.config),
                tier1_nodes=self._tier_nodes_config("tier1"),
                core_program_path=self._core_program_path_for_killswitch(),
            )
            self.kill_switch.cleanup_stale_rules()
            self._require_current_start_intent(lifecycle_revision)
            self._warn_if_killswitch_unavailable()
            if self.manager:
                try:
                    self._detach_manager_runtime_hooks(self.manager)
                    self.manager.close()
                except Exception:
                    log_raw_diagnostic(
                        self.logger,
                        "warning",
                        "Failed to close pre-start manager",
                        exc_info=True,
                    )
            self.manager = self._new_proxy_tier_manager()
            self._require_current_start_intent(lifecycle_revision)
            self._clear_tier3_core_export_override()
            self._attach_manager_runtime_hooks(self.manager)
            self._start_subscription_server()
            self._require_current_start_intent(lifecycle_revision)
            tier3_enabled = getattr(self.manager, "_tier3_enabled", None)
            if callable(tier3_enabled) and tier3_enabled():
                # Expansion starts before the potentially slow Tier1/Tier2
                # checks. Publish the conservative gate truth first so this
                # generation never inherits a stale pre-gate state. Admission
                # remains independently owned by the validated-pass committer.
                self._tier3_required_for_start = True
                self._set_tier3_startup_gate_required(True)
            self._start_tier3_expansion_before_primary_checks(
                self.manager,
                lifecycle_revision=lifecycle_revision,
            )
            if start_core:
                try:
                    self.start_core()
                    self._require_current_start_intent(lifecycle_revision)
                except RecoverableCoreStartError as exc:
                    core_start_error = self._record_recoverable_core_start_error(
                        exc,
                        update_last_error=False,
                    )
                    self._require_current_start_intent(lifecycle_revision)
            self._commit_runtime_started(lifecycle_revision)
            self.last_error = None if self._start_deferred_is_live else core_start_error
            runtime_marker = tier3_runtime_feature_report()
            runtime_components = runtime_marker.get("build_components")
            runtime_components = (
                dict(runtime_components)
                if isinstance(runtime_components, dict)
                else {}
            )
            log_event(
                self.logger,
                "INFO",
                "runtime.desktop_started",
                "Desktop runtime started in native app mode "
                f"(runtime_marker={runtime_marker.get('feature_marker')} "
                f"runtime_manager_sha={runtime_marker.get('manager_sha256')} "
                f"runtime_protocol_sha={runtime_components.get('tier3_validation_protocol.py')} "
                f"runtime_scheduler_sha={runtime_components.get('tier3_candidate_scheduler.py')} "
                f"runtime_desktop_sha={runtime_components.get('desktop_runtime.py')} "
                f"runtime_recovery_sha={runtime_components.get('runtime_egress_recovery.py')} "
                f"runtime_exe_sha={runtime_marker.get('executable_sha256')} "
                f"runtime_packaged={runtime_marker.get('packaged')} "
                f"runtime_executable={runtime_marker.get('executable')})",
            )
            self._write_runtime_lifecycle_journal(
                "started",
                startup_deferred=bool(self._start_deferred_is_live),
            )
            return self.status()
        except RuntimeStartCancelled as exc:
            from bridge_messages import startup_diagnostic
            self._bridge_start_failure_record = (
                int(self._runtime_generation), None, startup_diagnostic(exc))
            manager = self.manager
            request_manager_stop = getattr(manager, "request_stop", None) if manager else None
            if callable(request_manager_stop):
                try:
                    request_manager_stop()
                except Exception:
                    pass
            runner = self.core_runner
            request_core_stop = getattr(runner, "request_stop", None) if runner else None
            if callable(request_core_stop):
                try:
                    request_core_stop()
                except Exception:
                    pass
            self.running = False
            self.last_error = None
            return self.status(include_runtime_nodes=False)
        except Exception as exc:
            error = str(exc)
            from bridge_messages import startup_diagnostic
            self._bridge_start_failure_record = (
                int(self._runtime_generation), error, startup_diagnostic(exc))
            log_event(
                self.logger,
                "ERROR",
                "runtime.desktop_failed",
                "Desktop runtime start failed",
                params=_runtime_start_failure_params(exc),
                exc_info=True,
            )
            self._write_runtime_lifecycle_journal(
                "start_failed",
                error=error,
            )
            self._rollback_failed_start()
            self.last_error = error
            self._close_authoritative_monitor_log_handler()
            raise

    def _notify_tier3_pool_alive_change(self, manager: Any, previous_alive: int, alive_count: int) -> None:
        if alive_count == previous_alive:
            return
        try:
            manager.last_pool_alive_count = alive_count
        except Exception as exc:
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Failed to update Bastion Layer alive counter",
                exc_info=True,
            )

    def _attach_manager_runtime_hooks(self, manager: Any | None) -> None:
        if manager is None:
            return
        try:
            binder = getattr(manager, "bind_runtime_generation", None)
            if callable(binder):
                binder(
                    self._runtime_generation,
                    self._tier3_runtime_truth_snapshot,
                )
            manager.on_tier3_pool_committed = self._on_tier3_pool_committed
            manager.on_runtime_source_transport_failure = (
                self._recover_runtime_source_transport_failure
            )
            if hasattr(manager, "on_runtime_source_supply_observed"):
                manager.on_runtime_source_supply_observed = (
                    self._on_runtime_source_supply_observed
                )
            if hasattr(manager, "on_runtime_leaf_recheck_result"):
                manager.on_runtime_leaf_recheck_result = (
                    self._on_runtime_leaf_recheck_result
                )
            manager.runtime_source_fetch_proxy_provider = (
                self._runtime_source_supply_proxy_provider
            )
            manager.runtime_source_fetch_endpoint_provider = (
                self._runtime_source_fetch_endpoints_provider
            )
            manager.runtime_source_route_demand = self._request_runtime_source_qualification
            manager.tier3_core_sync_ledger_provider = (
                self._tier3_core_sync_owner_snapshot
            )
        except Exception:
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Failed to attach Bastion Layer runtime hooks",
                exc_info=True,
            )

    def _tier3_runtime_truth_snapshot(self) -> dict[str, Any]:
        manager = self.manager
        runner = self.core_runner
        core_process_running = False
        if runner is not None:
            try:
                core_process_running = bool(runner.is_running())
            except Exception:
                try:
                    status = runner.status()
                    core_process_running = bool(
                        status.get("running")
                        if isinstance(status, dict)
                        else False
                    )
                except Exception:
                    core_process_running = False
        core_inventory_verified = False
        core_inventory_members: list[dict[str, str]] = []
        core_inventory_semantic_digest = ""
        core_inventory_route_epoch = 0
        if core_process_running:
            with self._runtime_route_snapshot_lock:
                route_snapshot = self._runtime_route_snapshot
                inventory_snapshot = self._runtime_core_inventory_snapshot
            coordinator_snapshot = (
                self._runtime_egress_coordinator.current_route_snapshot()
            )
            if (
                route_snapshot is not None
                and inventory_snapshot is not None
                and coordinator_snapshot is not None
                and coordinator_snapshot.snapshot_key
                == route_snapshot.snapshot_key
                and int(inventory_snapshot.process_pid)
                == int(route_snapshot.process_pid)
                and int(inventory_snapshot.process_generation)
                == int(route_snapshot.process_generation)
                and int(inventory_snapshot.core_generation)
                == int(route_snapshot.core_generation)
                and str(inventory_snapshot.semantic_digest)
                == str(route_snapshot.semantic_digest)
                and int(inventory_snapshot.route_epoch)
                == int(route_snapshot.route_epoch)
            ):
                core_inventory_members = [
                    {
                        "tier": ref.tier,
                        "pool_kind": ref.pool_kind,
                        "identity": ref.identity,
                        "proxy_name": ref.proxy_name,
                    }
                    for ref in inventory_snapshot.members
                ]
                core_inventory_verified = bool(
                    route_snapshot.group_state("TIER3-AUTO") is not None
                )
                core_inventory_semantic_digest = str(
                    inventory_snapshot.semantic_digest or ""
                )
                core_inventory_route_epoch = int(
                    inventory_snapshot.route_epoch
                )
        return {
            "runtime_generation": int(self._runtime_generation),
            "runtime_service_running": bool(self.running),
            "startup_gate_satisfied": bool(
                getattr(manager, "tier3_startup_gate_satisfied", False)
            )
            if manager is not None
            else False,
            "core_process_running": core_process_running,
            "effective_egress_ok": (
                getattr(manager, "effective_egress_ok", False)
                if manager is not None and core_process_running
                else False
            ),
            "traffic_capture_active": bool(
                getattr(manager, "tier3_traffic_capture_active", False)
            )
            if manager is not None and core_process_running
            else False,
            "runtime_qualified_count": int(
                getattr(manager, "tier3_runtime_qualified_count", 0) or 0
            )
            if manager is not None and core_process_running
            else 0,
            "runtime_exported_count": int(
                getattr(manager, "tier3_runtime_exported_count", 0) or 0
            )
            if manager is not None and core_process_running
            else 0,
            "source_control_egress_ready": bool(
                core_process_running
                and self._source_control_final_exit_ready(manager)
            ),
            "initial_activation": (
                self._tier3_initial_activation_trace_snapshot()
            ),
            # This is an in-process owner handoff, not report/UI payload. The
            # Manager consumes the exact binding immediately and exposes only
            # aggregate counts below.
            "core_inventory_verified": core_inventory_verified,
            "core_inventory_members": core_inventory_members,
            "core_inventory_semantic_digest": core_inventory_semantic_digest,
            "core_inventory_route_epoch": core_inventory_route_epoch,
        }

    def _detach_manager_runtime_hooks(self, manager: Any | None = None) -> None:
        manager = manager if manager is not None else self.manager
        if manager is None:
            return
        try:
            if getattr(manager, "on_tier3_pool_committed", None) == self._on_tier3_pool_committed:
                manager.on_tier3_pool_committed = None
            if (
                getattr(manager, "on_runtime_source_transport_failure", None)
                == self._recover_runtime_source_transport_failure
            ):
                manager.on_runtime_source_transport_failure = None
            if (
                getattr(manager, "on_runtime_leaf_recheck_result", None)
                == self._on_runtime_leaf_recheck_result
            ):
                manager.on_runtime_leaf_recheck_result = None
            if (
                getattr(manager, "runtime_source_fetch_proxy_provider", None)
                == self._runtime_source_supply_proxy_provider
            ):
                manager.runtime_source_fetch_proxy_provider = None
            if (
                getattr(manager, "runtime_source_fetch_endpoint_provider", None)
                == self._runtime_source_fetch_endpoints_provider
            ):
                manager.runtime_source_fetch_endpoint_provider = None
            if (
                getattr(manager, "runtime_source_route_demand", None)
                == self._request_runtime_source_qualification
            ):
                manager.runtime_source_route_demand = None
            if (
                getattr(manager, "tier3_core_sync_ledger_provider", None)
                == self._tier3_core_sync_owner_snapshot
            ):
                manager.tier3_core_sync_ledger_provider = None
            if hasattr(manager, "tier3_runtime_truth_provider"):
                manager.tier3_runtime_truth_provider = None
            self._clear_tier3_core_export_override()
            self._clear_runtime_audit_export_overlay()
        except Exception:
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Failed to detach Bastion Layer runtime hooks",
                exc_info=True,
            )

    def _rollback_failed_start(self) -> None:
        """Undo partial startup so the UI never sees a false running state."""
        self.stop_event.set()
        try:
            self.restore_system_proxy()
        except Exception:
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Failed to restore system proxy during startup rollback",
                exc_info=True,
            )
        try:
            self.stop_core(actor="startup_rollback", reason="runtime startup failed")
        except Exception:
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Failed to stop mihomo during startup rollback",
                exc_info=True,
            )
        if (
            self.monitor_thread
            and self.monitor_thread.is_alive()
            and self.monitor_thread is not threading.current_thread()
        ):
            if self.manager:
                self.manager.close()
            self.monitor_thread.join(timeout=5)
        if self.subscription_server:
            try:
                self.subscription_server.stop()
            except Exception:
                log_raw_diagnostic(
                    self.logger,
                    "warning",
                    "Failed to stop subscription server during startup rollback",
                    exc_info=True,
                )
        if self.kill_switch:
            try:
                self.kill_switch.cleanup()
            except Exception:
                log_raw_diagnostic(
                    self.logger,
                    "warning",
                    "Failed to cleanup kill switch during startup rollback",
                    exc_info=True,
                )
        if self.manager:
            try:
                self.manager.close()
            except Exception:
                log_raw_diagnostic(
                    self.logger,
                    "warning",
                    "Failed to close manager during startup rollback",
                    exc_info=True,
                )
        self.subscription_server = None
        self.manager = None
        self.kill_switch = None
        self.monitor_thread = None
        self._clear_tier3_core_export_override()
        self._clear_runtime_audit_export_overlay()
        self._start_deferred_reason = None
        self._start_deferred_is_live = False
        self.running = False

    def stop(
        self,
        *,
        actor: str = "api",
        reason: str = "runtime stop requested",
        expected_generation: int | None = None,
        stop_intent: RuntimeStopIntent | None = None,
    ) -> dict[str, Any]:
        actor = str(actor or "api")
        reason = str(reason or "runtime stop requested")
        intent = stop_intent or self.request_stop(
            actor=actor,
            reason=reason,
            expected_generation=expected_generation,
        )
        if not intent.accepted:
            self.logger.info(
                "Desktop runtime stop ignored (actor=%s reason=%s expected_generation=%s current_generation=%s result=%s)",
                actor,
                reason,
                expected_generation,
                intent.generation,
                intent.skipped_reason or "stale_stop_intent",
            )
            payload = self.status()
            payload["stop_skipped"] = True
            payload["stop_skipped_reason"] = (
                intent.skipped_reason or "stale_stop_intent"
            )
            return payload
        if not self._stop_intent_is_current(intent):
            payload = self.status()
            payload["stop_skipped"] = True
            payload["stop_skipped_reason"] = "stale_stop_intent"
            return payload

        actor = intent.actor
        reason = intent.reason
        self._preempt_runtime_io_for_stop()
        with self._runtime_lifecycle_lock:
            generation = self._runtime_generation
            if (
                generation != intent.generation
                or not self._stop_intent_is_current(intent)
            ):
                payload = self.status()
                payload["stop_skipped"] = True
                payload["stop_skipped_reason"] = "stale_stop_intent"
                return payload

            try_log_nowait(
                self.logger,
                "info",
                "Desktop runtime stop requested (actor=%s reason=%s generation=%s)",
                actor,
                reason,
                generation,
            )
            self._write_runtime_lifecycle_journal(
                "stop_requested",
                actor=actor,
                reason=reason,
            )
            stop_payload: dict[str, Any] = {}
            try:
                stop_payload = self._stop_locked(actor=actor, reason=reason)
            except Exception as exc:
                self._finish_stop_intent(intent, result="failed", error=str(exc))
                try_log_nowait(
                    self.logger,
                    "exception",
                    "Desktop runtime stop failed (actor=%s reason=%s generation=%s)",
                    actor,
                    reason,
                    generation,
                    extra=_RAW_ONLY_LOG_EXTRA,
                )
                raise

            validator_stop_status = str(
                (
                    stop_payload.get("validator_stop_status")
                    if isinstance(stop_payload, dict)
                    else ""
                )
                or ""
            )
            if validator_stop_status == "STOP_FAILED_STREAM_ACTIVE":
                self._last_runtime_stop["result"] = "stopping"
                payload = self.status()
                payload["validator_stop_status"] = validator_stop_status
                payload["stop_skipped"] = False
                payload["stop_skipped_reason"] = ""
                return payload
            if self._validator_stop_incomplete(validator_stop_status):
                error = "Tier3 validation workers did not stop before the deadline"
                self.last_error = error
                self._finish_stop_intent(
                    intent,
                    result="failed",
                    error=error,
                    error_code=STOP_ERROR_TIER3_VALIDATION_ACTIVE,
                    error_details={
                        "validator_stop_status": validator_stop_status,
                    },
                )
                payload = self.status()
                for key in (
                    "validator_stop_status",
                    "core_stop_status",
                    "kill_switch_cleanup_completed",
                    "alert_dispatch_drained",
                    "shutdown_exit_code",
                ):
                    if key in stop_payload:
                        payload[key] = stop_payload[key]
                payload["stop_skipped"] = False
                payload["stop_skipped_reason"] = ""
                return payload

            core_stop_status = str(
                stop_payload.get("core_stop_status")
                if isinstance(stop_payload, dict)
                else ""
            )
            if core_stop_status == "STOP_FAILED_CORE_ACTIVE":
                error = str(
                    stop_payload.get("core_stop_error")
                    or "Mihomo process is still running after the stop deadline"
                )
                error_code = str(
                    stop_payload.get("core_stop_error_code")
                    or STOP_ERROR_CORE_PROCESS_ACTIVE
                )
                core_stop_pid = stop_payload.get("core_stop_pid")
                self.last_error = error
                self._finish_stop_intent(
                    intent,
                    result="failed",
                    error=error,
                    error_code=error_code,
                    error_details=(
                        {"pid": core_stop_pid}
                        if core_stop_pid not in (None, "")
                        else None
                    ),
                )
                payload = self.status()
                for key in (
                    "validator_stop_status",
                    "core_stop_status",
                    "core_stop_error",
                    "core_stop_error_code",
                    "core_stop_pid",
                    "kill_switch_cleanup_completed",
                    "alert_dispatch_drained",
                    "shutdown_exit_code",
                ):
                    if key in stop_payload:
                        payload[key] = stop_payload[key]
                payload["stop_skipped"] = False
                payload["stop_skipped_reason"] = ""
                return payload
            runtime_stop_status = str(
                stop_payload.get("runtime_stop_status")
                if isinstance(stop_payload, dict)
                else ""
            )
            if runtime_stop_status == "STOP_FAILED_MONITOR_ACTIVE":
                error = "Runtime monitor thread did not stop before the deadline"
                self.last_error = error
                self._finish_stop_intent(
                    intent,
                    result="failed",
                    error=error,
                    error_code=STOP_ERROR_RUNTIME_MONITOR_ACTIVE,
                )
                payload = self.status()
                for key in (
                    "validator_stop_status",
                    "core_stop_status",
                    "runtime_stop_status",
                    "kill_switch_cleanup_completed",
                    "alert_dispatch_drained",
                    "shutdown_exit_code",
                ):
                    if key in stop_payload:
                        payload[key] = stop_payload[key]
                payload["stop_skipped"] = False
                payload["stop_skipped_reason"] = ""
                return payload
            if runtime_stop_status in {
                "STOP_FAILED_BACKGROUND_ACTIVE",
                "STOP_FAILED_EXIT_QUALITY_ACTIVE",
            }:
                background_activity = (
                    dict(stop_payload.get("runtime_background_activity") or {})
                    if isinstance(stop_payload, dict)
                    else {}
                )
                active_workers = sorted(
                    str(name)
                    for name, active in background_activity.items()
                    if active
                )
                if runtime_stop_status == "STOP_FAILED_BACKGROUND_ACTIVE":
                    error = (
                        "Runtime background workers did not stop before the "
                        "deadline"
                    )
                    error_code = STOP_ERROR_RUNTIME_BACKGROUND_ACTIVE
                else:
                    error = (
                        "Exit-quality data refresh did not stop before the "
                        "deadline"
                    )
                    error_code = STOP_ERROR_EXIT_QUALITY_REFRESH_ACTIVE
                self.last_error = error
                self._finish_stop_intent(
                    intent,
                    result="failed",
                    error=error,
                    error_code=error_code,
                    error_details={"workers": active_workers},
                )
                payload = self.status()
                for key in (
                    "validator_stop_status",
                    "core_stop_status",
                    "runtime_stop_status",
                    "runtime_background_activity",
                    "kill_switch_cleanup_completed",
                    "alert_dispatch_drained",
                    "shutdown_exit_code",
                ):
                    if key in stop_payload:
                        payload[key] = stop_payload[key]
                payload["stop_skipped"] = False
                payload["stop_skipped_reason"] = ""
                return payload

            self._finish_stop_intent(intent, result="stopped")
            try_log_nowait(
                self.logger,
                "info",
                "Desktop runtime stop completed (actor=%s reason=%s generation=%s)",
                actor,
                reason,
                generation,
            )
            self._write_runtime_lifecycle_journal(
                "stopped",
                actor=actor,
                reason=reason,
            )
            self._close_authoritative_monitor_log_handler()
            payload = self.status()
            if isinstance(stop_payload, dict):
                for key in (
                    "validator_stop_status",
                    "core_stop_status",
                    "shutdown_exit_code",
                ):
                    if key in stop_payload:
                        payload[key] = stop_payload[key]
            payload["stop_skipped"] = False
            payload["stop_skipped_reason"] = ""
            return payload

    @staticmethod
    def _validator_stop_incomplete(status: str) -> bool:
        normalized = str(status or "").strip()
        return normalized not in {"", "not_started", "STOPPED"}

    def _stop_locked(self, *, actor: str, reason: str) -> dict[str, Any]:
        deadline = time.monotonic() + 3.0
        stop_started = time.monotonic()

        def remaining() -> float:
            return max(0.0, deadline - time.monotonic())

        def log_stage(stage: str) -> None:
            if isinstance(self._last_runtime_stop, dict):
                stages = self._last_runtime_stop.setdefault("stages", [])
                if isinstance(stages, list):
                    stages.append(
                        {
                            "stage": str(stage),
                            "elapsed_ms": int((time.monotonic() - stop_started) * 1000),
                            "remaining_ms": int(remaining() * 1000),
                        }
                    )
            # This journal is the authority when the UI audit must force-kill a
            # process after its bounded exit grace. It lets packaged failures
            # identify the exact owner without relying on a contended logger.
            self._write_runtime_lifecycle_journal(
                "stop_progress",
                nonblocking=True,
                # Stop diagnostics must not call into the core runner while a
                # different lifecycle owner may be tearing it down.
                core_process_running=bool(self.core_runner),
                actor=actor,
                reason=reason,
                stop_stage=str(stage),
            )

        self.stop_event.set()
        log_stage("stop_event")
        validator_stop_status = "not_started"
        alert_dispatch_drained = True
        manager = self.manager
        request_manager_stop = getattr(manager, "request_stop", None) if manager else None
        if callable(request_manager_stop):
            try:
                request_manager_stop()
            except Exception:
                try_log_nowait(
                    self.logger,
                    "warning",
                    "Failed to refresh manager cancellation during runtime stop",
                    exc_info=True,
                    extra=_RAW_ONLY_LOG_EXTRA,
                )
        log_stage("manager_stop_requested")
        # Remove OS routing and the Core/TUN process before waiting for source
        # and validator cleanup. A bounded UI shutdown may otherwise be forced
        # to terminate while Mihomo still owns its virtual adapter and DNS.
        try:
            result = self.restore_system_proxy()
            if isinstance(result, dict) and result.get("state") in {
                "failed", "unknown", "not_owned",
            }:
                raise RuntimeError(str(
                    result.get("error_code") or result.get("last_error") or result["state"]
                ))
        except Exception as exc:
            self.last_error = str(exc)
            try_log_nowait(
                self.logger,
                "error",
                "Failed to restore system proxy during stop: %s",
                exc,
                extra=_RAW_ONLY_LOG_EXTRA,
            )
        log_stage("system_proxy")
        # Route lease: DELETE our own automatic pins (bounded, never raises)
        # so Mihomo's cache.db does not restore them on the next start.
        self._route_lease_release_for_shutdown(remaining())
        core_stop_result = self.stop_core(
            actor=actor,
            reason=reason,
            timeout=remaining(),
            stage_observer=lambda stage: log_stage(f"core:{stage}"),
        )
        core_stop_incomplete = bool(
            isinstance(core_stop_result, dict)
            and (
                core_stop_result.get("still_running")
                or core_stop_result.get("running")
                or core_stop_result.get("cleanup_pending")
                or core_stop_result.get("reader_drained") is False
                or (
                    "stopped" in core_stop_result
                    and not core_stop_result.get("stopped")
                )
            )
        )
        core_process_still_running = bool(
            isinstance(core_stop_result, dict)
            and (
                core_stop_result.get("still_running")
                or core_stop_result.get("running")
            )
        )
        core_stop_pid = (
            core_stop_result.get("pid")
            if isinstance(core_stop_result, dict)
            else None
        )
        if core_stop_pid in (None, ""):
            core_stop_pid = self._last_core_stop.get("pid")
        core_stop_error_code = (
            STOP_ERROR_CORE_PROCESS_ACTIVE
            if core_process_still_running
            else STOP_ERROR_CORE_OUTPUT_READER_ACTIVE
            if core_stop_incomplete
            else ""
        )
        core_stop_error = (
            (
                f"Mihomo process {core_stop_pid} is still running "
                "after the stop deadline"
                if core_stop_pid not in (None, "")
                else "Mihomo process is still running after the stop deadline"
            )
            if core_process_still_running
            else (
                "Mihomo exited, but its output reader did not finish "
                "before the stop deadline"
                if core_stop_incomplete
                else ""
            )
        )
        log_stage("core")
        if self.manager:
            self._detach_manager_runtime_hooks(self.manager)
            manager = self.manager
            manager.tier3_close_stage_observer = lambda entry: log_stage(
                f"manager:{entry.get('stage', 'unknown')}"
            )
            try:
                validator_stop_status = str(
                    _call_with_optional_timeout(
                        manager.close,
                        keyword="timeout_seconds",
                        timeout=remaining(),
                    )
                    or ""
                )
            finally:
                manager.tier3_close_stage_observer = None
        log_stage("manager")
        if actor == "app_exit":
            alert_dispatch_drained = bool(
                self.alerts.close(timeout=remaining())
            )
            log_stage(
                "alerts_drained"
                if alert_dispatch_drained
                else "alerts_drain_timed_out"
            )
            if not alert_dispatch_drained:
                try_log_nowait(
                    self.logger,
                    "warning",
                    "Alert delivery workers did not drain before the "
                    "application-exit deadline",
                    extra=_RAW_ONLY_LOG_EXTRA,
                )
        if self._validator_stop_incomplete(validator_stop_status):
            if validator_stop_status == "STOP_FAILED_STREAM_ACTIVE":
                self._schedule_runtime_stop_completion(
                    manager,
                    generation=self._runtime_generation,
                    actor=actor,
                    reason=reason,
                )
            payload = self.status()
            payload["validator_stop_status"] = validator_stop_status
            payload["core_stop_status"] = (
                "STOP_FAILED_CORE_ACTIVE" if core_stop_incomplete else "STOPPED"
            )
            if core_stop_error:
                payload["core_stop_error"] = core_stop_error
                payload["core_stop_error_code"] = core_stop_error_code
                payload["core_stop_pid"] = core_stop_pid
            payload["kill_switch_cleanup_completed"] = False
            payload["alert_dispatch_drained"] = alert_dispatch_drained
            if actor == "app_exit":
                payload["shutdown_exit_code"] = 74
            return payload
        monitor_still_running = False
        if self.monitor_thread and self.monitor_thread.is_alive():
            self.monitor_thread.join(timeout=remaining())
            if self.monitor_thread.is_alive():
                monitor_still_running = True
                try_log_nowait(
                    self.logger,
                    "warning",
                    "Monitor thread did not stop before timeout",
                    extra=_RAW_ONLY_LOG_EXTRA,
                )
        log_stage("monitor")
        if monitor_still_running:
            payload = self.status()
            payload["validator_stop_status"] = validator_stop_status
            payload["core_stop_status"] = (
                "STOP_FAILED_CORE_ACTIVE" if core_stop_incomplete else "STOPPED"
            )
            if core_stop_error:
                payload["core_stop_error"] = core_stop_error
                payload["core_stop_error_code"] = core_stop_error_code
                payload["core_stop_pid"] = core_stop_pid
            payload["runtime_stop_status"] = "STOP_FAILED_MONITOR_ACTIVE"
            payload["kill_switch_cleanup_completed"] = False
            payload["alert_dispatch_drained"] = alert_dispatch_drained
            if actor == "app_exit":
                payload["shutdown_exit_code"] = 74
            return payload
        background_activity = self._wait_for_runtime_background_work(
            timeout=min(1.0, remaining())
        )
        active_runtime_background_workers = sorted(
            name
            for name, active in background_activity.items()
            if active and name != "exit_quality_refresh"
        )
        exit_quality_refresh_active = bool(
            background_activity.get("exit_quality_refresh")
        )
        log_stage(
            "background_workers_active"
            if active_runtime_background_workers
            else "background_workers_drained"
        )
        log_stage(
            "exit_quality_refresh_active"
            if exit_quality_refresh_active
            else "exit_quality_refresh_drained"
        )
        if self.subscription_server:
            _call_with_optional_timeout(
                self.subscription_server.stop,
                keyword="timeout",
                timeout=remaining(),
            )
            try_log_nowait(self.logger, "info", "Subscription server stopped")
        log_stage("subscription")
        log_stage("kill_switch_started")
        kill_switch_cleanup_completed = self._cleanup_kill_switch_bounded(
            timeout=min(0.75, remaining())
        )
        log_stage(
            "kill_switch_completed"
            if kill_switch_cleanup_completed
            else "kill_switch_timed_out"
        )
        if core_stop_incomplete:
            self.subscription_server = None
            self.manager = None
            self.kill_switch = None
            self.monitor_thread = None
            payload = self.status()
            payload["validator_stop_status"] = validator_stop_status
            payload["core_stop_status"] = "STOP_FAILED_CORE_ACTIVE"
            payload["core_stop_error"] = core_stop_error
            payload["core_stop_error_code"] = core_stop_error_code
            payload["core_stop_pid"] = core_stop_pid
            payload["kill_switch_cleanup_completed"] = (
                kill_switch_cleanup_completed
            )
            payload["alert_dispatch_drained"] = alert_dispatch_drained
            if actor == "app_exit":
                payload["shutdown_exit_code"] = 74
            return payload
        if active_runtime_background_workers or exit_quality_refresh_active:
            payload = self.status()
            payload["validator_stop_status"] = validator_stop_status
            payload["core_stop_status"] = "STOPPED"
            payload["runtime_stop_status"] = (
                "STOP_FAILED_BACKGROUND_ACTIVE"
                if active_runtime_background_workers
                else "STOP_FAILED_EXIT_QUALITY_ACTIVE"
            )
            payload["runtime_background_activity"] = dict(
                background_activity
            )
            payload["kill_switch_cleanup_completed"] = (
                kill_switch_cleanup_completed
            )
            payload["alert_dispatch_drained"] = alert_dispatch_drained
            if actor == "app_exit":
                payload["shutdown_exit_code"] = 74
            return payload
        log_stage("references_clear_started")
        self.subscription_server = None
        self.manager = None
        self.kill_switch = None
        log_stage("references_cleared")
        self.running = False
        self._start_deferred_reason = None
        self._start_deferred_is_live = False
        # Proxy records are removed only by verified proxy recovery. A
        # completed runtime stop is not proof of host registry restoration.
        log_stage("runtime_state_recovery_record_preserved")
        log_stage("runtime_overlay_clear_started")
        self._clear_runtime_audit_export_overlay()
        log_stage("runtime_overlay_cleared")
        # Per the project's "ephemeral session" policy, clear traffic and
        # protocol counters from disk on graceful shutdown so a fresh
        # launch never resurrects yesterday's chart. Cache files used for
        # restart-time recovery (tier2_cache, exit_cache, observation
        # cache, runtime-state) are intentionally NOT removed here.
        log_stage("session_artifacts_clear_started")
        self._clear_session_artifacts()
        log_stage("session_artifacts")
        log_event(
            self.logger,
            "INFO",
            "runtime.desktop_stopped",
            "Desktop runtime stopped",
        )
        log_stage("status_started")
        payload = self.status()
        log_stage("status_completed")
        payload["validator_stop_status"] = validator_stop_status
        payload["core_stop_status"] = "STOPPED"
        payload["kill_switch_cleanup_completed"] = kill_switch_cleanup_completed
        payload["alert_dispatch_drained"] = alert_dispatch_drained
        if actor == "app_exit" and self._validator_stop_incomplete(
            validator_stop_status
        ):
            payload["shutdown_exit_code"] = 74
            self._write_runtime_lifecycle_journal(
                "validator_stop_failed",
                actor=actor,
                reason=reason,
            )
            try_log_nowait(
                self.logger,
                "critical",
                "Tier3 validator cleanup remained incomplete during application exit; "
                "requesting fail-fast exit code 74",
                extra=_RAW_ONLY_LOG_EXTRA,
            )
        return payload

    def _schedule_runtime_stop_completion(
        self,
        manager: ProxyTierManager,
        *,
        generation: int,
        actor: str,
        reason: str,
    ) -> None:
        current = self._runtime_stop_completion_thread
        if current is not None and current.is_alive():
            return

        def complete_when_quiescent() -> None:
            while self.manager is manager and self._runtime_generation == generation:
                with manager._tier3_active_stream_lock:
                    sessions = list(manager._tier3_active_stream_sessions.values())
                if not sessions or all(event.is_set() for event in sessions):
                    try:
                        self.stop(
                            actor=f"{actor}:cleanup",
                            reason=f"{reason}; stream cleanup completed",
                            expected_generation=generation,
                        )
                    except Exception:
                        try_log_nowait(
                            self.logger,
                            "exception",
                            "Deferred runtime stop completion failed",
                            extra=_RAW_ONLY_LOG_EXTRA,
                        )
                    return
                time.sleep(0.1)

        self._runtime_stop_completion_thread = threading.Thread(
            target=complete_when_quiescent,
            name="desktop-runtime-stop-completion",
            daemon=True,
        )
        self._runtime_stop_completion_thread.start()

    def _cleanup_kill_switch_bounded(self, *, timeout: float) -> bool:
        kill_switch = self.kill_switch
        if kill_switch is None:
            return True
        timeout = max(0.0, float(timeout))
        if timeout <= 0.0:
            return False
        callback = getattr(kill_switch, "close", None)
        if not callable(callback):
            callback = getattr(kill_switch, "cleanup", None)
        if not callable(callback):
            return True
        if isinstance(kill_switch, KillSwitchManager):
            try:
                _call_with_optional_timeout(
                    callback,
                    keyword="timeout",
                    timeout=timeout,
                )
            except Exception as exc:
                try_log_nowait(
                    self.logger,
                    "warning",
                    "Kill switch cleanup failed during runtime stop: %s",
                    exc,
                    extra=_RAW_ONLY_LOG_EXTRA,
                )
                return False
            return True
        completed = threading.Event()
        errors: list[Exception] = []

        def cleanup() -> None:
            try:
                _call_with_optional_timeout(
                    callback,
                    keyword="timeout",
                    timeout=timeout,
                )
            except Exception as exc:
                errors.append(exc)
            finally:
                completed.set()

        thread = threading.Thread(
            target=cleanup,
            name="desktop-kill-switch-cleanup",
            daemon=True,
        )
        thread.start()
        completed.wait(timeout=timeout)
        if not completed.is_set():
            try_log_nowait(
                self.logger,
                "warning",
                "Kill switch cleanup exceeded the bounded runtime stop budget",
                extra=_RAW_ONLY_LOG_EXTRA,
            )
            return False
        if errors:
            try_log_nowait(
                self.logger,
                "warning",
                "Kill switch cleanup failed during runtime stop: %s",
                errors[-1],
                extra=_RAW_ONLY_LOG_EXTRA,
            )
            return False
        return True

    def _clear_session_artifacts(self) -> None:
        candidates: list[Path] = [
            self.app_paths.data_dir / "traffic-history.json",
        ]
        for path in candidates:
            try:
                if path.exists():
                    path.unlink()
            except OSError as exc:
                self.logger.debug("Could not remove %s: %s", path, exc)

    def _wait_for_core_proxy_or_stop(
        self,
        runner: Any,
        *,
        host: str,
        port: int,
        timeout: float,
        cause: BaseException | None = None,
    ) -> None:
        wait_kwargs: dict[str, Any] = {
            "host": host,
            "port": port,
            "timeout": timeout,
        }
        try:
            wait_parameters = inspect.signature(runner.wait_for_proxy).parameters.values()
        except (TypeError, ValueError):
            wait_parameters = ()
        if any(
            parameter.kind is inspect.Parameter.VAR_KEYWORD
            or parameter.name == "cancel_event"
            for parameter in wait_parameters
        ):
            wait_kwargs["cancel_event"] = self.stop_event
        if runner.wait_for_proxy(**wait_kwargs):
            return
        if self.stop_event.is_set():
            request_stop = getattr(runner, "request_stop", None)
            if callable(request_stop):
                request_stop()
            raise RuntimeStartCancelled("runtime stop requested while waiting for mihomo")
        error = runner.status().get("last_health_error") or f"timed out waiting for {host}:{port}"
        runner.stop()
        timeout_error = TimeoutError(str(error))
        if cause is not None:
            raise timeout_error from cause
        raise timeout_error

    def _restart_core_after_runtime_config_update(
        self,
        runner: Any,
        *,
        host: str,
        port: int,
        timeout: float,
        log_message: str,
        cause: BaseException | None = None,
    ) -> None:
        self.logger.info(log_message)
        runner.stop()
        self.write_mihomo_runtime_config()
        runner.start()
        self._wait_for_core_proxy_or_stop(runner, host=host, port=port, timeout=timeout, cause=cause)

    def _require_tier3_ready_for_core_start(self) -> None:
        if not self._tier3_required_for_start:
            return
        manager = self.manager
        if not manager:
            raise RuntimeError("manager service is not running")
        required = self._tier3_startup_target_alive(manager)
        current = count_healthy_nodes(manager.runtime_nodes.get("tier3", []))
        if (
            current < required
            and self._tier3_startup_supply_terminal(manager)
            and self._fail_terminal_tier3_bootstrap(manager)
        ):
            raise RecoverableCoreStartError(
                self._last_tier3_startup_error
                or self._tier3_terminal_startup_error(current, required, manager)
            )
        live_reason = self._tier3_startup_live_collection_reason(manager)
        if current < required and live_reason:
            raise RecoverableCoreStartError(
                "Bastion Layer startup deferred while source refill continues: "
                f"{live_reason}"
            )
        marker = self._tier3_core_sync_marker()
        if not marker:
            error = tier3_startup_readiness_error(
                required_for_start=True,
                core_sync_marker=marker,
                current_healthy_count=0,
                required_healthy_count=required,
                failure_detail=self._tier3_startup_failure_detail,
            )
            if error:
                raise RecoverableCoreStartError(error)
        error = tier3_startup_readiness_error(
            required_for_start=True,
            core_sync_marker=marker,
            current_healthy_count=current,
            required_healthy_count=required,
            failure_detail=self._tier3_startup_failure_detail,
        )
        if error:
            raise RecoverableCoreStartError(error)

    def _apply_system_proxy_capture_after_core_start(self, runner: Any) -> None:
        if self.stop_event.is_set():
            raise RuntimeStartCancelled(
                "runtime stop requested before system proxy capture"
            )
        plan = system_proxy_capture_plan(
            network_mode=self.network_mode,
            system_proxy_enabled=self.system_proxy.enabled,
            active=self.system_proxy.active,
        )
        if plan.wanted:
            try:
                self.enable_system_proxy()
            except Exception:
                raise
            if self.stop_event.is_set():
                self.restore_system_proxy()
                raise RuntimeStartCancelled(
                    "runtime stop requested during system proxy capture"
                )
            if not self.system_proxy.is_target_active():
                # ``SystemProxyManager.active`` records that our write returned;
                # it is not proof that the authoritative Windows settings now
                # point at this Core.  Never publish READY from the in-memory
                # marker alone.
                try:
                    self.restore_system_proxy()
                except Exception:
                    pass
                raise RuntimeError(
                    "Windows system proxy did not retain the Tesseract target"
                )
            return
        self.logger.info(
            "Skipping system proxy activation (network_mode=%s)", self.network_mode
        )

    def _system_proxy_capture_proof_required(self) -> bool:
        proxy_manager = getattr(self, "system_proxy", None)
        return bool(
            str(getattr(self, "network_mode", "") or "") == "system_proxy"
            and bool(getattr(proxy_manager, "enabled", False))
        )

    def _system_proxy_host_probe_uses_wininet_preconfig(self) -> bool:
        """Return whether the host proof can exercise the real Windows path.

        Production uses :class:`system_proxy.WinRegProxyBackend`; narrow tests
        and non-Windows adapters use an in-memory backend and retain the
        explicit local-proxy probe.  This distinction keeps unit tests
        hermetic while ensuring READY means a normal WinINet application can
        actually consume the settings we just wrote.
        """

        proxy_manager = getattr(self, "system_proxy", None)
        backend = getattr(proxy_manager, "backend", None)
        backend_type = type(backend)
        return bool(
            str(getattr(proxy_manager, "platform_name", "") or "").casefold()
            == "windows"
            and str(getattr(backend_type, "__module__", "") or "")
            == "system_proxy"
            and str(getattr(backend_type, "__name__", "") or "")
            == "WinRegProxyBackend"
        )

    @staticmethod
    def _abortable_https_204_via_wininet_preconfig(
        *,
        probe_url: str,
        timeout_seconds: float,
        abort_owner: _RuntimeAbortHandle,
    ) -> tuple[int, bytes]:
        """Issue one fresh HTTPS request using Windows' PRECONFIG settings.

        A successful explicit CONNECT to Mihomo does not prove that browsers
        and other WinINet consumers see the same proxy.  A new PRECONFIG
        session consumes the authoritative HKCU settings, rejects redirects,
        bypasses caches and exposes both handles to the probe broker so the
        absolute deadline remains enforceable.
        """

        parsed = urlsplit(str(probe_url or ""))
        if parsed.scheme.casefold() != "https" or not parsed.hostname:
            raise RuntimeError("FINAL-EXIT host probe URL must be HTTPS")

        import ctypes.wintypes as wintypes

        wininet = ctypes.WinDLL("wininet", use_last_error=True)
        handle_type = ctypes.c_void_p
        wininet.InternetOpenW.argtypes = (
            wintypes.LPCWSTR,
            wintypes.DWORD,
            wintypes.LPCWSTR,
            wintypes.LPCWSTR,
            wintypes.DWORD,
        )
        wininet.InternetOpenW.restype = handle_type
        wininet.InternetOpenUrlW.argtypes = (
            handle_type,
            wintypes.LPCWSTR,
            wintypes.LPCWSTR,
            wintypes.DWORD,
            wintypes.DWORD,
            ctypes.c_size_t,
        )
        wininet.InternetOpenUrlW.restype = handle_type
        wininet.InternetSetOptionW.argtypes = (
            handle_type,
            wintypes.DWORD,
            wintypes.LPVOID,
            wintypes.DWORD,
        )
        wininet.InternetSetOptionW.restype = wintypes.BOOL
        wininet.HttpQueryInfoW.argtypes = (
            handle_type,
            wintypes.DWORD,
            wintypes.LPVOID,
            ctypes.POINTER(wintypes.DWORD),
            ctypes.POINTER(wintypes.DWORD),
        )
        wininet.HttpQueryInfoW.restype = wintypes.BOOL
        wininet.InternetReadFile.argtypes = (
            handle_type,
            wintypes.LPVOID,
            wintypes.DWORD,
            ctypes.POINTER(wintypes.DWORD),
        )
        wininet.InternetReadFile.restype = wintypes.BOOL
        wininet.InternetCloseHandle.argtypes = (handle_type,)
        wininet.InternetCloseHandle.restype = wintypes.BOOL

        INTERNET_OPEN_TYPE_PRECONFIG = 0
        INTERNET_OPTION_CONNECT_TIMEOUT = 2
        INTERNET_OPTION_SEND_TIMEOUT = 5
        INTERNET_OPTION_RECEIVE_TIMEOUT = 6
        INTERNET_OPTION_DATA_SEND_TIMEOUT = 7
        INTERNET_OPTION_DATA_RECEIVE_TIMEOUT = 8
        INTERNET_FLAG_RELOAD = 0x80000000
        INTERNET_FLAG_NO_CACHE_WRITE = 0x04000000
        INTERNET_FLAG_SECURE = 0x00800000
        INTERNET_FLAG_NO_AUTO_REDIRECT = 0x00200000
        INTERNET_FLAG_NO_COOKIES = 0x00080000
        INTERNET_FLAG_NO_UI = 0x00000200
        INTERNET_FLAG_PRAGMA_NOCACHE = 0x00000100
        HTTP_QUERY_STATUS_CODE = 19
        HTTP_QUERY_FLAG_NUMBER = 0x20000000

        def raise_last_error(operation: str) -> None:
            error_code = int(ctypes.get_last_error() or 0)
            detail = ctypes.FormatError(error_code).strip() if error_code else ""
            raise OSError(
                error_code,
                f"{operation} failed"
                + (f": {detail}" if detail else ""),
            )

        close_lock = threading.Lock()
        handles: dict[str, int | None] = {"request": None, "session": None}

        def close_handles() -> None:
            with close_lock:
                request_handle = handles.pop("request", None)
                session_handle = handles.pop("session", None)
            for handle in (request_handle, session_handle):
                if handle:
                    try:
                        wininet.InternetCloseHandle(handle_type(handle))
                    except Exception:
                        pass

        try:
            session = wininet.InternetOpenW(
                "Tesseract/1.0",
                INTERNET_OPEN_TYPE_PRECONFIG,
                None,
                None,
                0,
            )
            if not session:
                raise_last_error("InternetOpenW")
            session_value = int(session)
            with close_lock:
                handles["session"] = session_value
            abort_owner.bind(close_handles)

            timeout_ms = wintypes.DWORD(
                max(50, min(1500, int(float(timeout_seconds) * 1000.0)))
            )
            for option in (
                INTERNET_OPTION_CONNECT_TIMEOUT,
                INTERNET_OPTION_SEND_TIMEOUT,
                INTERNET_OPTION_RECEIVE_TIMEOUT,
                INTERNET_OPTION_DATA_SEND_TIMEOUT,
                INTERNET_OPTION_DATA_RECEIVE_TIMEOUT,
            ):
                wininet.InternetSetOptionW(
                    handle_type(session_value),
                    option,
                    ctypes.byref(timeout_ms),
                    ctypes.sizeof(timeout_ms),
                )

            headers = (
                "Accept: */*\r\n"
                "Cache-Control: no-cache\r\n"
                "Pragma: no-cache\r\n"
                "Connection: close\r\n"
            )
            flags = (
                INTERNET_FLAG_RELOAD
                | INTERNET_FLAG_NO_CACHE_WRITE
                | INTERNET_FLAG_SECURE
                | INTERNET_FLAG_NO_AUTO_REDIRECT
                | INTERNET_FLAG_NO_COOKIES
                | INTERNET_FLAG_NO_UI
                | INTERNET_FLAG_PRAGMA_NOCACHE
            )
            request = wininet.InternetOpenUrlW(
                handle_type(session_value),
                str(probe_url),
                headers,
                len(headers),
                flags,
                0,
            )
            if not request:
                raise_last_error("InternetOpenUrlW")
            request_value = int(request)
            with close_lock:
                handles["request"] = request_value

            status = wintypes.DWORD(0)
            status_size = wintypes.DWORD(ctypes.sizeof(status))
            status_index = wintypes.DWORD(0)
            if not wininet.HttpQueryInfoW(
                handle_type(request_value),
                HTTP_QUERY_STATUS_CODE | HTTP_QUERY_FLAG_NUMBER,
                ctypes.byref(status),
                ctypes.byref(status_size),
                ctypes.byref(status_index),
            ):
                raise_last_error("HttpQueryInfoW")

            buffer = ctypes.create_string_buffer(128)
            bytes_read = wintypes.DWORD(0)
            if not wininet.InternetReadFile(
                handle_type(request_value),
                buffer,
                len(buffer),
                ctypes.byref(bytes_read),
            ):
                raise_last_error("InternetReadFile")
            return int(status.value), bytes(buffer.raw[: int(bytes_read.value)])
        finally:
            abort_owner.clear(close_handles)
            close_handles()

    def _verify_system_proxy_host_capture(
        self,
        *,
        deadline_monotonic: float,
        priority: ProbePriority = ProbePriority.ACTIVATION,
        recovery_ticket: _RuntimeRecoveryTicket | None = None,
    ) -> dict[str, Any]:
        """Prove one fresh HTTPS request through the read-back Windows target.

        The route verifier intentionally uses the mixed port directly.  This
        second contract closes the separate host-capture gap: the registry must
        still contain our exact target, and a fresh socket through that target
        must produce an empty 204 before READY/recovery is reported.
        """

        if not self._system_proxy_capture_proof_required():
            return {"required": False, "verified": True}
        if self.stop_event.is_set():
            raise RuntimeStartCancelled(
                "runtime stop requested before system proxy capture proof"
            )
        if not self.system_proxy.is_target_active():
            raise RuntimeError("Windows system proxy capture is inactive")
        backend = getattr(self.system_proxy, "backend", None)
        read = getattr(backend, "read", None)
        if not callable(read):
            raise RuntimeError("Windows system proxy target cannot be read back")
        current = read()
        expected_server = str(self.system_proxy.proxy_server() or "")
        if not bool(getattr(current, "enabled", False)) or str(
            getattr(current, "server", "") or ""
        ) != expected_server:
            raise RuntimeError("Windows system proxy target changed before proof")
        remaining = float(deadline_monotonic) - time.monotonic()
        if remaining <= 0.05:
            raise TimeoutError("system proxy capture proof deadline expired")
        probe_url = ""
        for raw_url in self._default_probe_urls():
            try:
                parsed = urlsplit(raw_url)
            except ValueError:
                continue
            if parsed.scheme.casefold() == "https" and parsed.hostname:
                probe_url = raw_url
                break
        if not probe_url:
            raise RuntimeError("Windows host proof has no HTTPS probe URL")
        probe_label = self._safe_probe_endpoint_label(probe_url)
        proxy_host = str(getattr(self.system_proxy, "host", "127.0.0.1") or "127.0.0.1")
        if proxy_host in {"0.0.0.0", "::"}:
            proxy_host = "127.0.0.1"
        proxy_port = int(getattr(self.system_proxy, "port", 0) or 0)
        if proxy_port <= 0:
            raise RuntimeError("Windows system proxy target has no valid port")
        # WinINet applies connect/send/receive timeouts per operation.  A
        # healthy 2--3 s proxy path can therefore complete after the old 1.5 s
        # broker deadline even though every operation remains bounded.  Keep a
        # 3 s startup proof window inside the outer admission lease.
        execution_deadline = time.monotonic() + min(3.0, remaining)

        def probe(context: ProbeExecutionContext | None) -> dict[str, Any]:
            timeout_seconds = max(
                0.05,
                min(3.0, execution_deadline - time.monotonic()),
            )
            self._register_runtime_internal_probe(
                probe_url,
                timeout_seconds=timeout_seconds,
            )
            abort_owner = self._prepare_abortable_probe(
                context,
                recovery_ticket=recovery_ticket,
                deadline_monotonic=deadline_monotonic,
            )
            started = time.perf_counter()
            if self._system_proxy_host_probe_uses_wininet_preconfig():
                status_code, body = (
                    self._abortable_https_204_via_wininet_preconfig(
                        probe_url=probe_url,
                        timeout_seconds=timeout_seconds,
                        abort_owner=abort_owner,
                    )
                )
                probe_transport = "wininet_preconfig"
            else:
                status_code, body = self._abortable_https_204_via_http_proxy(
                    proxy_host=proxy_host,
                    proxy_port=proxy_port,
                    probe_url=probe_url,
                    timeout_seconds=timeout_seconds,
                    abort_owner=abort_owner,
                )
                probe_transport = "explicit_proxy_adapter"
            if status_code != 204 or not self._probe_response_body_ok(
                status_code,
                body,
            ):
                raise RuntimeError(
                    f"{probe_label}: unexpected status {status_code}"
                )
            return {
                "required": True,
                "verified": True,
                "status": status_code,
                "url": probe_label,
                "proxy": expected_server,
                "transport": probe_transport,
                "latency_ms": round(
                    (time.perf_counter() - started) * 1000.0,
                    2,
                ),
            }

        return self._run_brokered_runtime_probe(
            probe,
            priority=priority,
            queue_timeout_seconds=min(0.5, remaining),
            socket_start_timeout_seconds=min(0.5, remaining),
            execution_deadline_monotonic=execution_deadline,
        )

    def _runtime_traffic_capture_wanted(self) -> bool:
        """Return whether the selected client mode needs a capture config.

        TUN and mixed modes need Mihomo's capture phase even when the HKCU
        system proxy toggle is off.  A disabled system-proxy-only mode can
        remain on the authenticated no-capture Core after FINAL-EXIT passes.
        """

        if self.network_mode in {"tun", "mixed"}:
            return True
        return bool(
            system_proxy_capture_plan(
                network_mode=self.network_mode,
                system_proxy_enabled=self.system_proxy.enabled,
                active=self.system_proxy.active,
            ).wanted
        )

    def _runtime_core_capture_reload_required(self) -> bool:
        """Return whether host capture needs a different loaded Core graph.

        The already-verified no-capture graph exposes the same mixed-port,
        rules, provider and private source listeners needed by Windows system
        proxy.  Reapplying the staged formal payload only to toggle HKCU is a
        harmful semantic no-op: Mihomo rebuilds fallback health/selection and
        can discard the route just proved by admission.  TUN and mixed modes
        do require their removed capture surfaces and therefore still replay
        the staged payload before host capture is published.
        """

        mode = str(getattr(self, "network_mode", "") or "").strip().lower()
        if not mode:
            # Keep narrow injected lifecycle adapters on the conservative
            # path; production always has an explicit normalized mode.
            return True
        return mode in {"tun", "mixed"}

    def _hot_reload_runtime_config_phase(
        self,
        runner: Any,
        *,
        capture_enabled: bool,
        expected_activation_generation: int | None = None,
        expected_core_generation: int | None = None,
        deadline_monotonic: float | None = None,
    ) -> Path:
        if deadline_monotonic is None:
            with self._core_transition_lock:
                return self._hot_reload_runtime_config_phase_locked(
                    runner,
                    capture_enabled=capture_enabled,
                    expected_activation_generation=expected_activation_generation,
                    expected_core_generation=expected_core_generation,
                    deadline_monotonic=deadline_monotonic,
                )
        remaining = float(deadline_monotonic) - time.monotonic()
        if remaining <= 0.0 or not self._core_transition_lock.acquire(
            timeout=remaining
        ):
            raise TimeoutError(
                "initial egress admission expired waiting for Core mutation ownership"
            )
        try:
            return self._hot_reload_runtime_config_phase_locked(
                runner,
                capture_enabled=capture_enabled,
                expected_activation_generation=expected_activation_generation,
                expected_core_generation=expected_core_generation,
                deadline_monotonic=deadline_monotonic,
            )
        finally:
            self._core_transition_lock.release()

    def _hot_reload_runtime_config_phase_locked(
        self,
        runner: Any,
        *,
        capture_enabled: bool,
        expected_activation_generation: int | None = None,
        expected_core_generation: int | None = None,
        deadline_monotonic: float | None = None,
    ) -> Path:
        def remaining_budget() -> float:
            if deadline_monotonic is None:
                return float("inf")
            return float(deadline_monotonic) - time.monotonic()

        if capture_enabled and remaining_budget() <= 3.25:
            raise TimeoutError(
                "initial egress admission has insufficient budget for capture reload"
            )
        if self.stop_event.is_set():
            raise RuntimeStartCancelled(
                "runtime stop requested before staged Mihomo reload"
            )
        if self.core_runner is not runner or not runner.is_running():
            raise RuntimeStartCancelled(
                "Mihomo core changed before staged configuration reload"
            )
        if expected_core_generation is not None:
            with self._core_lifecycle_lock:
                current_core_generation = self._core_generation
            if int(current_core_generation) != int(expected_core_generation):
                raise RuntimeStartCancelled(
                    "Mihomo core generation changed before staged configuration reload"
                )
        if (
            expected_activation_generation is not None
            and not self._tier3_egress_activation_is_current(
                expected_activation_generation,
                runner,
            )
        ):
            raise RuntimeStartCancelled(
                "Mihomo activation was superseded before staged configuration reload"
            )
        # T-P2-RT2 (Fallback 特许): the mode this reload renders; recorded as
        # the Core-loaded mode only after the reload below succeeds.
        loaded_network_mode = self._hot_reload_loaded_network_mode(capture_enabled)
        if capture_enabled:
            with self._core_lifecycle_lock:
                staged_payload = self._staged_capture_runtime_config_payload
                staged_path = self._staged_capture_runtime_config_path
                staged_export_contract = copy.deepcopy(
                    self._staged_capture_runtime_export_contract
                )
            if staged_payload is not None and staged_path is not None:
                staged_contract = (
                    staged_export_contract
                    if isinstance(staged_export_contract, dict)
                    else self._runtime_export_contract_for_payload(staged_payload)
                )
                runtime_config = self._write_mihomo_runtime_payload(
                    staged_payload,
                    staged_path,
                )
                self._record_pending_runtime_export_contract(
                    staged_payload,
                    runtime_config,
                    contract=staged_contract,
                )
            else:
                runtime_config = self.write_mihomo_runtime_config()
        else:
            runtime_config = self.write_mihomo_no_capture_runtime_config()
        self._ensure_geodata_ready_for_core_start(runtime_config)
        controller = self._mihomo_controller_config()
        if not mihomo_controller_enabled(controller):
            raise RuntimeError(
                "mihomo controller is required for same-process staged activation"
            )
        reload_kwargs = hot_reload_kwargs_from_controller(controller)
        remaining = remaining_budget()
        if capture_enabled and remaining <= 3.0:
            raise TimeoutError(
                "initial egress admission expired before capture reload"
            )
        if deadline_monotonic is not None:
            reload_kwargs["timeout"] = max(
                0.10,
                min(float(reload_kwargs.get("timeout") or 5.0), remaining - 3.0),
            )
        result = runner.hot_reload(**reload_kwargs)
        reload_crossed_deadline = bool(
            deadline_monotonic is not None
            and time.monotonic() >= float(deadline_monotonic)
        )
        if not isinstance(result, dict) or not result.get("reloaded"):
            reason = result.get("reason") if isinstance(result, dict) else result
            raise RuntimeError(f"mihomo staged hot reload failed: {reason}")
        self._mark_loaded_runtime_export_contract()
        self._mark_runtime_source_transport_loaded()
        self._disarm_runtime_recovery("Mihomo configuration reloaded")
        # ApplyConfig may rebuild fallback/selector state while retaining the
        # same process PID.  The pre-reload route snapshot is therefore no
        # longer an attribution or readiness authority even when the semantic
        # graph looks similar.  Revoke it synchronously; activation will read
        # back the new graph and verify it before publishing capture.
        route_lock = getattr(self, "_runtime_route_snapshot_lock", None)
        if route_lock is not None:
            with route_lock:
                self._runtime_route_epoch = int(
                    getattr(self, "_runtime_route_epoch", 0) or 0
                ) + 1
                self._node_judgement_arm_epoch("hot_reload_runtime_config_phase_locked")
                self._mark_runtime_route_attribution_barrier_locked()
                self._runtime_route_snapshot = None
                self._runtime_route_snapshot_payload = None
                self._runtime_core_inventory_snapshot = None
                self._runtime_route_selection_signature = ()
                self._runtime_confirmed_fail_closed_snapshot_key = None
        coordinator = getattr(self, "_runtime_egress_coordinator", None)
        set_snapshot = getattr(coordinator, "set_current_snapshot", None)
        if callable(set_snapshot):
            set_snapshot(None)
        self._set_core_runtime_phase(
            "formal_capture" if capture_enabled else "formal_no_capture"
        )
        with self._core_lifecycle_lock:
            self._core_loaded_network_mode = loaded_network_mode
        if capture_enabled:
            with self._core_lifecycle_lock:
                self._staged_capture_runtime_config_payload = None
                self._staged_capture_runtime_config_path = None
                self._staged_capture_runtime_export_contract = None
                self._staged_capture_runtime_network_mode = None
        self._invalidate_exit_route_context()
        try:
            self._refresh_node_diagnostic_core_binding()
        except Exception:
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Could not refresh node-diagnostic binding after staged Mihomo reload",
                exc_info=True,
            )
        if reload_crossed_deadline:
            # ApplyConfig may already have committed. Publish its real phase
            # first so the caller's safety rollback can restore no-capture.
            raise TimeoutError(
                "initial egress admission expired during capture reload"
            )
        return runtime_config

    def _verify_capture_route_after_reload(
        self,
        *,
        lease_record: dict[str, Any] | None,
        route_intent: StartupRouteIntent | None = None,
        preferred_leaf_ref: RuntimeNodeRef | None = None,
        preferred_probe_group: str = "",
        expected_gateway_key: tuple[str, str, str, str] | None = None,
        timeout_seconds: float = 3.0,
        deadline_monotonic: float | None = None,
    ) -> dict[str, Any]:
        """Rebuild route authority and prove the post-ApplyConfig data plane.

        Startup always replays its policy-level route intent because Mihomo
        may reset selector ``now`` during ApplyConfig even when admission did
        not mutate a leaf. A legacy incident fixed lease remains supported for
        non-startup recovery, but startup never pins a concrete fallback leaf.
        """

        now = time.monotonic()
        deadline = now + max(0.0, min(6.0, float(timeout_seconds)))
        if deadline_monotonic is not None:
            deadline = min(deadline, float(deadline_monotonic))
        if deadline <= now:
            raise TimeoutError("post-reload FINAL-EXIT verification expired")

        def remaining_timeout(cap: float) -> float:
            remaining = deadline - time.monotonic()
            if remaining <= 0.0:
                raise TimeoutError(
                    "post-reload FINAL-EXIT verification expired"
                )
            return min(max(0.001, remaining), max(0.001, float(cap)))

        selector_revision = int(
            getattr(self, "_runtime_selector_intent_revision", 0) or 0
        )
        with self._core_lifecycle_lock:
            current_core_generation = int(self._core_generation)
        startup_lease_current = bool(
            not isinstance(lease_record, dict)
            or not bool(lease_record.get("startup_admission"))
            or (
                int(lease_record.get("activation_generation") or 0)
                == int(self._tier3_egress_activation_generation)
                and int(lease_record.get("lifecycle_revision") or 0)
                == int(getattr(self, "_lifecycle_revision", 0) or 0)
                and int(lease_record.get("runtime_generation") or 0)
                == int(getattr(self, "_runtime_generation", 0) or 0)
                and int(lease_record.get("core_generation") or 0)
                == current_core_generation
            )
        )
        snapshot = self._refresh_runtime_route_snapshot(
            timeout_seconds=remaining_timeout(0.5)
        )
        snapshot, payload = self._runtime_route_snapshot_state()
        if snapshot is None or not isinstance(payload, dict):
            raise RuntimeError(
                "post-reload FINAL-EXIT route snapshot is unavailable"
            )

        if route_intent is not None:
            if int(route_intent.selector_intent_revision) != selector_revision:
                raise RuntimeError(
                    "user selector intent superseded startup capture replay"
                )
            snapshot, payload, _intent_commits = (
                self._apply_startup_route_intent(
                    route_intent,
                    snapshot,
                    payload,
                    deadline_monotonic=deadline,
                    worker_token=None,
                )
            )
            if isinstance(preferred_leaf_ref, RuntimeNodeRef):
                rebound_ref = next(
                    (
                        ref
                        for ref in snapshot.proxy_nodes
                        if ref.key == preferred_leaf_ref.key
                        and ref.proxy_name == preferred_leaf_ref.proxy_name
                    ),
                    None,
                )
                health_group = str(preferred_probe_group or "").strip()
                if not health_group:
                    health_group = self._startup_native_fallback_health_group(
                        snapshot,
                        route_intent,
                    )
                if health_group:
                    probe_url, _expected_status = (
                        self._runtime_group_probe_contract(
                            snapshot,
                            health_group,
                        )
                    )
                    remaining = deadline - time.monotonic()
                    # ApplyConfig resets the fallback's URLTest state.  An
                    # individual member delay does not necessarily repopulate
                    # AliveForTestUrl for the owning fallback group, so warm
                    # that group itself and let Mihomo choose in loaded order.
                    # No concrete leaf is selected or fixed here.
                    probe_budget = min(5.0, max(0.0, remaining - 2.5))
                    if self._node_judgement_policy().group_round_native_timeout:
                        # P0-2: the exact contract at the native timeout, or
                        # one round right after READY; never a shortened one.
                        native_timeout_ms = (
                            self._runtime_group_native_timeout_ms(health_group)
                        )
                        native_window = (
                            native_timeout_ms / 1000.0
                            + _NATIVE_GROUP_ROUND_SLACK_SECONDS
                        )
                        if max(0.0, remaining - 2.5) >= native_window:
                            try:
                                self._run_native_group_round(
                                    health_group,
                                    probe_url=probe_url,
                                    expected_status=_expected_status,
                                    timeout_ms=native_timeout_ms,
                                    admission_seconds=max(
                                        0.0,
                                        remaining
                                        - 2.5
                                        - native_window
                                        - _NATIVE_GROUP_ROUND_DISPATCH_SECONDS,
                                    ),
                                )
                            except Exception as exc:
                                if self._native_group_round_not_issued(exc):
                                    self._defer_native_group_round(
                                        group=health_group,
                                        probe_url=probe_url,
                                        expected_status=_expected_status,
                                        timeout_ms=native_timeout_ms,
                                        source="post_capture_queue",
                                    )
                                else:
                                    log_raw_diagnostic(
                                        self.logger,
                                        "warning",
                                        "Post-capture fallback healthcheck did not complete: %s",
                                        redact_diagnostic_text(exc),
                                    )
                        else:
                            self._defer_native_group_round(
                                group=health_group,
                                probe_url=probe_url,
                                expected_status=_expected_status,
                                timeout_ms=native_timeout_ms,
                                source="post_capture",
                            )
                    elif probe_budget > 0.10:
                        try:
                            self.test_group_delay(
                                health_group,
                                url=probe_url,
                                timeout_ms=max(
                                    100,
                                    int(probe_budget * 1000.0),
                                ),
                            )
                        except Exception as exc:
                            log_raw_diagnostic(
                                self.logger,
                                "warning",
                                "Post-capture fallback healthcheck did not complete: %s",
                                redact_diagnostic_text(exc),
                            )
                elif rebound_ref is not None:
                    # Direct managed branches have no native fallback URLTest.
                    # Reprove the exact leaf without changing selection.
                    remaining = deadline - time.monotonic()
                    probe_budget = min(2.0, max(0.0, remaining - 2.5))
                    if probe_budget > 0.10:
                        self._probe_runtime_leaf(
                            rebound_ref,
                            payload,
                            timeout_ms=max(100, int(probe_budget * 1000.0)),
                            probe_priority=ProbePriority.ACTIVATION,
                        )
                if rebound_ref is not None or health_group:
                    refreshed = self._refresh_loaded_runtime_authority(
                        timeout_seconds=remaining_timeout(0.75),
                        require_managed_final_exit=True,
                        worker_token=None,
                    )
                    if refreshed is None:
                        raise RuntimeControllerReadbackError(
                            "post-capture fallback prewarm has no route readback"
                        )
                    snapshot, payload, _rebound_binding = refreshed

        active_lease = (
            dict(lease_record)
            if isinstance(lease_record, dict)
            and route_intent is None
            and startup_lease_current
            and str(lease_record.get("to") or "").upper() != "REJECT"
            and int(
                lease_record.get(
                    "selector_intent_revision",
                    selector_revision,
                )
                or 0
            )
            == selector_revision
            else None
        )
        if active_lease is not None:
            raw_actions = active_lease.get("initial_actions")
            replay_actions = (
                [dict(item) for item in raw_actions if isinstance(item, dict)]
                if isinstance(raw_actions, (list, tuple))
                else []
            )
            if not replay_actions:
                replay_actions = [
                    {
                        "group": str(active_lease.get("group") or ""),
                        "target": str(
                            active_lease.get("target_member") or ""
                        ),
                        "previous": "",
                        "mode": str(active_lease.get("mode") or "selector"),
                        "alternative_leaf": str(
                            active_lease.get("to") or ""
                        ),
                    }
                ]
            if len(replay_actions) > 2:
                raise RuntimeError(
                    "post-reload automatic route lease exceeds replay budget"
                )
            for action in replay_actions:
                group = str(action.get("group") or "")
                target = str(action.get("target") or "")
                mode = str(action.get("mode") or "selector")
                if not group or not target:
                    raise RuntimeError(
                        "post-reload automatic route lease is incomplete"
                    )
                group_state = snapshot.group_state(group)
                already_selected = bool(
                    group_state is not None
                    and group_state.now == target
                    and (mode != "fixed" or group_state.fixed == target)
                )
                if not already_selected:
                    prewarm_kwargs: dict[str, Any] = {
                        "deadline_monotonic": deadline,
                    }
                    try:
                        prewarm_parameters = inspect.signature(
                            self._prewarm_runtime_switch_target
                        ).parameters.values()
                    except (TypeError, ValueError):
                        prewarm_parameters = ()
                    if any(
                        parameter.kind is inspect.Parameter.VAR_KEYWORD
                        or parameter.name == "probe_priority"
                        for parameter in prewarm_parameters
                    ):
                        prewarm_kwargs["probe_priority"] = (
                            ProbePriority.ACTIVATION
                        )
                    self._prewarm_runtime_switch_target(
                        snapshot,
                        action,
                        **prewarm_kwargs,
                    )
                    if int(
                        getattr(
                            self,
                            "_runtime_selector_intent_revision",
                            0,
                        )
                        or 0
                    ) != selector_revision:
                        raise RuntimeError(
                            "user selector intent superseded post-reload lease replay"
                        )
                    self._apply_runtime_automatic_selection(
                        action,
                        deadline_monotonic=deadline,
                    )
                    self._refresh_runtime_route_snapshot(
                        timeout_seconds=remaining_timeout(0.5)
                    )
                    snapshot, payload = self._runtime_route_snapshot_state()
                    if snapshot is None or not isinstance(payload, dict):
                        raise RuntimeError(
                            "post-reload automatic route readback is unavailable"
                        )
                    group_state = snapshot.group_state(group)
                if group_state is None or group_state.now != target:
                    raise RuntimeError(
                        "post-reload automatic route target was not selected"
                    )
                if mode == "fixed" and group_state.fixed != target:
                    raise RuntimeError(
                        "post-reload fallback target was not fixed"
                    )

        final_binding = self._runtime_route_binding_for_outbound(
            snapshot,
            payload,
            "FINAL-EXIT",
        )
        if final_binding is None:
            raise RuntimeError("post-reload FINAL-EXIT is not a managed route")
        if (
            route_intent is not None
            and route_intent.top_level_target
            not in tuple(final_binding.route_chain)
        ):
            raise RuntimeError(
                "post-reload FINAL-EXIT left the startup policy branch"
            )
        intent_gateway_key = (
            route_intent.expected_gateway_key
            if route_intent is not None
            else expected_gateway_key
        )
        if (
            intent_gateway_key is not None
            and tuple(final_binding.node.key) != tuple(intent_gateway_key)
        ):
            raise RuntimeError("Gateway identity changed during capture reload")
        if expected_gateway_key is not None and active_lease is not None:
            expected_underlay_key = active_lease.get("expected_underlay_key")
            if isinstance(expected_underlay_key, (list, tuple)):
                underlay_binding = self._runtime_gateway_underlay_binding(
                    snapshot,
                    payload,
                    final_binding.node,
                )
                if (
                    underlay_binding is None
                    or tuple(underlay_binding.node.key)
                    != tuple(expected_underlay_key)
                ):
                    raise RuntimeError(
                        "Gateway underlay changed during capture reload"
                    )
        if (
            active_lease is not None
            and expected_gateway_key is None
            and str(active_lease.get("to") or "")
            and final_binding.node.proxy_name
            != str(active_lease.get("to") or "")
        ):
            raise RuntimeError(
                "post-reload FINAL-EXIT did not retain the verified replacement"
            )

        remaining = max(0.0, deadline - time.monotonic())
        if remaining <= 0.0:
            raise TimeoutError("post-reload FINAL-EXIT verification expired")
        verified = self._verify_runtime_final_exit(
            expected_snapshot=snapshot,
            timeout_seconds=min(5.5, remaining),
            required_successes=2,
            parallel_probes=True,
            total_timeout_cap_seconds=min(5.5, remaining),
            per_probe_timeout_cap_seconds=min(5.0, remaining),
        )
        if active_lease is not None:
            with self._runtime_failure_monitor_lock:
                current = self._runtime_route_mutation_lease
                if (
                    isinstance(current, dict)
                    and str(current.get("incident_id") or "")
                    == str(active_lease.get("incident_id") or "")
                    and int(
                        current.get(
                            "selector_intent_revision",
                            selector_revision,
                        )
                        or 0
                    )
                    == selector_revision
                ):
                    current["route_epoch"] = int(snapshot.route_epoch)
                    current["verified_at_monotonic"] = time.monotonic()
        return verified

    def _rollback_to_formal_no_capture(
        self,
        runner: Any,
        reason: str,
        *,
        deadline_monotonic: float | None = None,
        admission_lease: _InitialEgressAdmissionLease | None = None,
        allow_cancelled_owner: bool = False,
    ) -> None:
        def rollback_owner_is_current() -> bool:
            return bool(
                admission_lease is None
                or self._initial_egress_admission_lease_is_current(
                    admission_lease,
                    runner,
                )
                or (
                    allow_cancelled_owner
                    and self._cancelled_initial_egress_admission_still_owns_core(
                        admission_lease,
                        runner,
                    )
                )
            )

        if not rollback_owner_is_current():
            return

        def remaining_timeout(cap: float) -> float:
            if deadline_monotonic is None:
                return max(0.001, float(cap))
            remaining = float(deadline_monotonic) - time.monotonic()
            if remaining <= 0.0:
                return 0.0
            return min(max(0.001, remaining), max(0.001, float(cap)))

        # A failed qualification while the Core is already running the exact
        # no-capture configuration is not a configuration transition.  A
        # second ApplyConfig here used to reset fallback health every retry,
        # keeping the first (bad/unqualified) member selected indefinitely.
        # Keep the loaded graph and its connection pools intact; the
        # activation worker may verify/select another already-loaded member.
        if self._current_core_runtime_phase() == "formal_no_capture":
            self.logger.info(
                "Keeping the loaded no-capture Mihomo standby after activation "
                "verification failure (no reload): %s",
                reason,
            )
            if not hasattr(self, "_runtime_route_snapshot_lock"):
                # Narrow partial-runtime diagnostics exercise only the
                # no-reload contract and do not own a controller snapshot.
                return
            timeout = remaining_timeout(0.75)
            authority = (
                self._refresh_loaded_runtime_authority(
                    timeout_seconds=timeout,
                    require_managed_final_exit=True,
                )
                if timeout > 0.0
                else None
            )
            if authority is None:
                self._publish_tier3_controller_hold(
                    "Mihomo no-capture route could not be read back after rollback"
                )
            return
        if not rollback_owner_is_current():
            return
        try:
            self.restore_system_proxy()
        except Exception:
            # Capture rollback must continue even when the Windows proxy
            # backend is temporarily unavailable. Leaving the Core in capture
            # mode while aborting the rollback is a worse and less truthful
            # state than a fail-closed local proxy setting.
            log_raw_diagnostic(
                self.logger,
                "error",
                "Could not restore the pre-start system proxy during FINAL-EXIT rollback",
                exc_info=True,
            )
        if not rollback_owner_is_current():
            return
        try:
            self.traffic_monitor.stop()
        except Exception:
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Could not stop the traffic monitor during FINAL-EXIT rollback",
                exc_info=True,
            )
        if not rollback_owner_is_current():
            return
        try:
            if remaining_timeout(0.75) <= 0.0:
                raise TimeoutError(
                    "initial egress admission expired before no-capture rollback"
                )
            self._hot_reload_runtime_config_phase(
                runner,
                capture_enabled=False,
                expected_activation_generation=(
                    admission_lease.activation_generation
                    if admission_lease is not None
                    else None
                ),
                expected_core_generation=(
                    admission_lease.core_generation
                    if admission_lease is not None
                    else None
                ),
                deadline_monotonic=deadline_monotonic,
            )
            timeout = remaining_timeout(0.75)
            authority = (
                self._refresh_loaded_runtime_authority(
                    timeout_seconds=timeout,
                    require_managed_final_exit=True,
                )
                if timeout > 0.0
                else None
            )
            if authority is None:
                self._publish_tier3_controller_hold(
                    "Mihomo no-capture route could not be read back after rollback"
                )
        except Exception:
            log_raw_diagnostic(
                self.logger,
                "error",
                "Failed to restore no-capture Mihomo standby after activation error: %s",
                reason,
                exc_info=True,
            )
            stop_result = _call_with_optional_timeout(
                runner.stop,
                keyword="timeout",
                # Cleanup may continue briefly after the six-second admission
                # terminal is already visible, but it remains bounded.
                timeout=max(0.05, remaining_timeout(0.5) or 0.5),
            )
            try:
                still_running = bool(runner.is_running())
            except Exception:
                still_running = bool(
                    isinstance(stop_result, dict)
                    and (
                        stop_result.get("running")
                        or stop_result.get("still_running")
                        or stop_result.get("cleanup_pending")
                    )
                )
            if still_running:
                # Never claim `stopped` while the same process still owns the
                # loaded capture graph. Startup remains fail-closed and a later
                # explicit stop/restart can finish cleanup truthfully.
                self._set_core_runtime_phase("formal_capture")
            else:
                self._set_core_runtime_phase("stopped")

    def _promote_bootstrap_core_once(self) -> dict[str, object]:
        runner = self._get_core_runner()
        manager = self.manager
        if manager is not None and self._fail_terminal_tier3_bootstrap(manager):
            raise RecoverableCoreStartError(
                self._last_tier3_startup_error
                or "Bastion Layer startup source supply is exhausted"
            )
        if not runner.is_running():
            raise RecoverableCoreStartError(
                "Mihomo bootstrap core is not available for promotion"
            )
        phase = self._current_core_runtime_phase()
        if phase == "formal_no_capture":
            # A concurrent lifecycle owner already completed the only legal
            # promotion.  Treat that as idempotent success and make sure the
            # committed runtime owns one admission request; never turn this
            # stale observation into a failed Core start.
            self._request_initial_egress_admission()
            return runner.status()
        if phase != "bootstrap":
            raise RecoverableCoreStartError(
                "Mihomo bootstrap core is not available for promotion"
            )
        try:
            self._hot_reload_runtime_config_phase(
                runner,
                capture_enabled=False,
            )
        except Exception as exc:
            self._set_effective_egress_state(
                False,
                f"Mihomo bootstrap promotion failed before capture: {exc}",
            )
            raise RecoverableCoreStartError(str(exc)) from exc
        with self._core_lifecycle_lock:
            core_generation = self._core_generation
        self._mark_tier3_core_process_ready(core_generation=core_generation)
        self._request_initial_egress_admission()
        self.logger.info(
            "Mihomo bootstrap core promoted to formal no-capture standby; "
            "FINAL-EXIT 204 verification is pending"
        )
        return runner.status()

    def start_core(self) -> dict[str, object]:
        with self._core_transition_lock:
            return self._start_core_serialized()

    def _start_core_for_runtime_recovery(self) -> dict[str, object]:
        """Emergency restart from canonical health without startup self-checks."""

        with self._core_transition_lock:
            if self.stop_event.is_set():
                return self.stop_core()
            if not self.manager:
                raise RuntimeError("manager service is not running")
            if self.core_runner and self.core_runner.is_running():
                return self.core_runner.status()
            # Runtime recovery already has an incident-bound authoritative
            # PASS and Manager overlay. Re-running Tier1/Tier2/Tier3 discovery
            # here added 4-6 seconds while no data plane existed.
            return self._start_core_once()

    def _start_core_serialized(self) -> dict[str, object]:
        if self.stop_event.is_set():
            return self.stop_core()
        if not self.manager:
            raise RuntimeError("manager service is not running")
        with self._core_lifecycle_lock:
            previous_core_generation = self._core_generation
        attempts = self._tier3_core_start_attempt_count()
        last_recoverable_error: RecoverableCoreStartError | None = None
        for attempt_index in range(attempts):
            self._prime_tier3_pool_before_core_start()
            if self.stop_event.is_set():
                return self.stop_core()
            if self.core_runner and self.core_runner.is_running():
                if self._current_core_runtime_phase() == "bootstrap":
                    self._require_tier3_ready_for_core_start()
                    result = self._promote_bootstrap_core_once()
                    log_event(
                        self.logger,
                        "INFO",
                        "runtime.mihomo_started",
                        "Mihomo bootstrap core promoted and awaiting FINAL-EXIT verification",
                    )
                    return result
                if self._current_core_runtime_phase() == "formal_no_capture":
                    self._request_initial_egress_admission()
                self._clear_last_error_if_runtime_healthy()
                return self.core_runner.status()
            self._require_tier3_ready_for_core_start()
            marker = self._tier3_core_sync_marker()
            if self._tier3_core_sync_failure_is_recent(marker):
                raise RecoverableCoreStartError(
                    "Bastion Layer core start is waiting for a new committed pool update"
                )
            try:
                result = self._start_core_once()
                restarted = previous_core_generation > 0
                log_event(
                    self.logger,
                    "INFO",
                    "runtime.mihomo_restarted" if restarted else "runtime.mihomo_started",
                    "Mihomo core restarted and awaiting egress verification"
                    if restarted
                    else "Mihomo core started and awaiting egress verification",
                )
                return result
            except RecoverableCoreStartError as exc:
                last_recoverable_error = exc
                if not self._should_retry_tier3_core_start(attempt_index=attempt_index, attempts=attempts):
                    raise
                if not self._recover_tier3_pool_after_core_start_failure(str(exc), attempt_index=attempt_index + 1):
                    raise
                self.logger.info(
                    "Retrying Bastion Layer core start after collecting replacement candidates (%s/%s)",
                    attempt_index + 2,
                    attempts,
                )
        if last_recoverable_error is not None:
            raise last_recoverable_error
        raise RecoverableCoreStartError("Bastion Layer core start did not complete")

    def _prepare_unverified_core_start(self) -> None:
        """Detach user traffic before a replacement Core process can listen.

        An unexpected Mihomo exit can leave the Windows proxy pointing at the
        old mixed-port.  Starting a new formal-no-capture process under that
        setting would expose user requests before this Core generation passes
        the admission contract.  Restore only Tesseract-owned capture state;
        unrelated system proxy settings remain the backend's saved baseline.
        """

        proxy = getattr(self, "system_proxy", None)
        active = bool(getattr(proxy, "active", False))
        target_active = False
        target_probe = getattr(proxy, "is_target_active", None)
        if callable(target_probe):
            try:
                target_active = bool(target_probe())
            except Exception:
                target_active = active
        manager = getattr(self, "manager", None)
        manager_capture_active = bool(
            getattr(manager, "tier3_traffic_capture_active", False)
            if manager is not None
            else False
        )
        if active or target_active or manager_capture_active:
            monitor = getattr(self, "traffic_monitor", None)
            stop_monitor = getattr(monitor, "stop", None)
            if callable(stop_monitor):
                _call_with_optional_timeout(
                    stop_monitor,
                    keyword="timeout",
                    timeout=0.25,
                )
        if not (active or target_active):
            return
        self.restore_system_proxy()
        if callable(target_probe):
            try:
                target_active = bool(target_probe())
            except Exception:
                target_active = bool(getattr(proxy, "active", False))
        else:
            target_active = bool(getattr(proxy, "active", False))
        if target_active:
            raise RuntimeError(
                "System proxy capture remained active before FINAL-EXIT admission"
            )

    def _start_core_once(self) -> dict[str, object]:
        if not self.manager:
            raise RuntimeError("manager service is not running")
        if self.stop_event.is_set():
            raise RuntimeStartCancelled("runtime stop requested before core start")
        self._prepare_unverified_core_start()
        # A formal start already has a usable pool, so it must not wait on
        # network probes: render with the current plan (or the configured
        # policy) now and let the qualification apply itself by a hot reload.
        self._schedule_dns_resolver_plan(reason="core_start")
        runner = self._get_core_runner()
        runner.get_version()
        proxy_config = self._system_proxy_config()
        host = str(proxy_config.get("host", "127.0.0.1"))
        port = self._client_mixed_port()
        runtime_config: Path | None = None
        last_start_error: Exception | None = None
        # T-P2-RT2: the mode this launch renders (Core-loaded network mode).
        loaded_network_mode = str(getattr(self, "network_mode", "") or "").strip().lower()
        for listener_attempt in range(
            max(
                1,
                min(
                    RUNTIME_SOURCE_MAX_ROUTE_ATTEMPTS,
                    int(self._runtime_source_listener_allocation_attempts),
                ),
            )
        ):
            if listener_attempt:
                self._runtime_source_transport_for_config(force_reallocate=True)
            # The first formal load is deliberately capture-free.  The exact
            # nodes and rule graph are exercised through the mixed-port before
            # any host traffic-capture surface can be considered.
            runtime_config = self.write_mihomo_no_capture_runtime_config()
            if self.stop_event.is_set():
                raise RuntimeStartCancelled(
                    "runtime stop requested before geodata check"
                )
            self._ensure_geodata_ready_for_core_start(runtime_config)
            if self.stop_event.is_set():
                raise RuntimeStartCancelled(
                    "runtime stop requested before mihomo launch"
                )
            self.logger.info("Wrote mihomo runtime config to %s", runtime_config)
            try:
                runner.start()
                if self.stop_event.is_set():
                    request_stop = getattr(runner, "request_stop", None)
                    if callable(request_stop):
                        request_stop()
                    raise RuntimeStartCancelled(
                        "runtime stop requested during mihomo launch"
                    )
                timeout = self._core_startup_timeout(proxy_config, runtime_config)
                self._wait_for_core_proxy_or_stop(
                    runner,
                    host=host,
                    port=port,
                    timeout=timeout,
                )
                self._wait_for_runtime_source_listeners_or_stop(
                    runner,
                    timeout=min(
                        max(
                            0.25,
                            float(self._runtime_source_listener_ready_timeout_seconds),
                        ),
                        max(0.25, float(timeout)),
                    ),
                )
                self._mark_runtime_source_transport_loaded()
                last_start_error = None
                break
            except RuntimeStartCancelled:
                raise
            except Exception as exc:
                last_start_error = exc
                authoritative_listener_error = (
                    self._authoritative_runtime_listener_start_error(runner)
                )
                if authoritative_listener_error is not None:
                    raise authoritative_listener_error from exc
                listener_conflict = self._runtime_source_listener_bind_conflict(
                    runner,
                    exc,
                )
                if listener_conflict:
                    try:
                        runner.stop()
                    except Exception:
                        log_raw_diagnostic(
                            self.logger,
                            "warning",
                            "Could not stop Mihomo after private source listener bind failure",
                            exc_info=True,
                        )
                if (
                    listener_attempt + 1
                    >= int(self._runtime_source_listener_allocation_attempts)
                    or not listener_conflict
                ):
                    raise
                log_raw_diagnostic(
                    self.logger,
                    "warning",
                    "Retrying initial Mihomo load with fresh private source listener ports "
                    "(attempt=%s/%s)",
                    listener_attempt + 2,
                    self._runtime_source_listener_allocation_attempts,
                )
        if runtime_config is None or last_start_error is not None:
            raise RuntimeError("Mihomo private source listeners did not become ready")
        with self._core_lifecycle_lock:
            self._core_generation += 1
            core_generation = self._core_generation
            self._bridge_core_launch_fact = (int(self._core_generation), str(getattr(self, "network_mode", "") or ""), time.time_ns() // 1_000_000)
        self._set_core_runtime_phase("formal_no_capture")
        with self._core_lifecycle_lock:
            # A stop that already cleared the field (phase stopped) wins.
            if self._core_runtime_phase == "formal_no_capture":
                self._core_loaded_network_mode = loaded_network_mode
        if self.stop_event.is_set():
            raise RuntimeStartCancelled("runtime stop requested after mihomo readiness")
        if self._tier3_is_primary_export():
            self._mark_tier3_core_process_ready(core_generation=core_generation)
            self._request_initial_egress_admission()
            return runner.status()
        # Tier1/Tier2/Gateway startup must publish the accepted render receipt
        # too. Admission reads only the loaded contract; leaving it pending
        # makes a healthy, listening Core remain in controller hold forever.
        self._mark_core_export_sync_success()
        # Tier3 is only one standby layer when another layer owns the current
        # route.  Its periodic self-check may warm that pool later, but startup
        # must proceed directly to the global FINAL-EXIT transaction so a bad
        # selected Tier1/Tier2/Exit leaf can switch without waiting on an
        # unrelated group warmup.
        if self.stop_event.is_set():
            raise RuntimeStartCancelled(
                "runtime stop requested during standby warmup"
            )
        self._set_effective_egress_readiness_state(
            None,
            "Mihomo core is ready; egress verification is pending",
        )
        self._publish_runtime_egress_readiness(
            RuntimeEgressReadinessState.ACTIVATION_HOLD,
            validation_active=False,
            reason="Egress verification is queued after runtime startup",
        )
        self._request_initial_egress_admission()
        return runner.status()

    def _tier3_core_start_attempt_count(self) -> int:
        tier3 = self._tier_config("tier3")
        try:
            retries = max(0, int(tier3.get("startup_core_recovery_retries", 2) or 0))
        except (TypeError, ValueError):
            retries = 2
        return retries + 1

    def _should_retry_tier3_core_start(self, *, attempt_index: int, attempts: int) -> bool:
        return bool(self._tier3_required_for_start and attempt_index + 1 < attempts and self.manager)

    def _tier3_startup_gate_timeout_seconds(self, manager: Any) -> float:
        tier3_config_getter = getattr(manager, "_tier3_config", None)
        tier3_config = tier3_config_getter() if callable(tier3_config_getter) else {}
        tier3_config = tier3_config if isinstance(tier3_config, dict) else {}
        return coerce_float(
            tier3_config.get("startup_gate_timeout"),
            max(45.0, self._startup_probe_timeout_seconds() * 3),
            minimum=1.0,
        )

    @staticmethod
    def _tier3_collect_action_running(manager: Any) -> bool:
        actions = getattr(manager, "background_actions", {})
        action = actions.get("tier3_collect", {}) if isinstance(actions, dict) else {}
        return bool(isinstance(action, dict) and action.get("running"))

    @staticmethod
    def _tier3_terminal_marker(value: Any) -> bool:
        if isinstance(value, bool):
            return value
        if isinstance(value, (int, float)):
            return value != 0
        if isinstance(value, str):
            return value.strip().lower() in {
                "1",
                "true",
                "yes",
                "terminal",
                "exhausted",
                "complete",
                "completed",
            }
        if isinstance(value, dict):
            return any(
                DesktopRuntime._tier3_terminal_marker(value.get(key))
                for key in ("terminal", "exhausted", "value", "state", "status")
                if key in value
            )
        return False

    def _tier3_startup_supply_terminal(
        self,
        manager: Any,
        metadata: dict[str, Any] | None = None,
    ) -> bool:
        payloads: list[dict[str, Any]] = []
        if isinstance(metadata, dict):
            payloads.append(metadata)
            for nested_key in ("report", "collection", "source_supply"):
                nested = metadata.get(nested_key)
                if isinstance(nested, dict):
                    payloads.append(nested)
        for candidate in (
            getattr(manager, "tier3_last_collection_report", None),
            getattr(manager, "tier3_refresh_progress", None),
        ):
            if isinstance(candidate, dict):
                payloads.append(candidate)
        for payload in payloads:
            if any(
                self._tier3_terminal_marker(payload.get(key))
                for key in ("startup_supply_exhausted", "source_supply_terminal")
                if key in payload
            ):
                return True
        return any(
            self._tier3_terminal_marker(getattr(manager, key, None))
            for key in ("startup_supply_exhausted", "source_supply_terminal")
        )

    def _tier3_terminal_startup_error(
        self,
        healthy: int,
        required: int,
        manager: Any | None = None,
    ) -> str:
        report = (
            getattr(manager, "tier3_last_collection_report", {})
            if manager is not None
            else {}
        )
        report = report if isinstance(report, dict) else {}

        def safe_count(key: str, fallback: int = 0) -> int:
            try:
                return max(0, int(report.get(key, fallback) or 0))
            except (TypeError, ValueError):
                return max(0, int(fallback or 0))

        cache_healthy = safe_count("cache_local_healthy_count", healthy)
        cache_required = max(
            1,
            safe_count("cache_local_required_count", required),
        )
        failure_count = max(
            safe_count("source_supply_blocked_count"),
            safe_count("failed_sources"),
            safe_count("source_fetch_failed"),
        )
        failure_class = str(
            report.get("source_supply_terminal_reason") or ""
        ).strip().lower()
        if failure_class == "no_egress":
            detail = str(report.get("startup_failure_detail") or "sources_unreachable")
            rung = str(report.get("dns_resolver_rung") or "")
            return (
                "Bastion Layer startup failed: no source egress is usable on this "
                f"network (detail={detail}; resolver={rung or 'unknown'}); "
                f"minimum healthy-node floor {max(0, int(healthy))}/{max(1, int(required))} "
                "was not reached; automatic retry is scheduled"
            )
        if failure_class not in {"rule_blocked", "no_proxy", "transport_failed"}:
            blocked_reason = str(
                report.get("source_retry_blocked_reason") or ""
            ).strip().lower()
            if blocked_reason in {
                "prerequisite_missing",
                "rule_blocked",
                "runtime_source_retry_disabled",
            }:
                failure_class = "rule_blocked"
            elif blocked_reason in {
                "blocked_no_route",
                "runtime_proxy_unavailable_after_recovery",
            }:
                failure_class = "no_proxy"
            elif failure_count > 0:
                failure_class = "transport_failed"
            else:
                failure_class = ""
        classified_count = max(1, failure_count) if failure_class else 0
        class_counts = {
            "rule_blocked": classified_count if failure_class == "rule_blocked" else 0,
            "no_proxy": classified_count if failure_class == "no_proxy" else 0,
            "transport_failed": (
                classified_count if failure_class == "transport_failed" else 0
            ),
        }
        return (
            "Bastion Layer startup failed: source supply was exhausted before "
            "the minimum healthy-node floor was reached "
            f"({max(0, int(healthy))}/{max(1, int(required))}); "
            f"cache/local={cache_healthy}/{cache_required}; "
            "source_failures "
            f"rule_blocked={class_counts['rule_blocked']} "
            f"no_proxy={class_counts['no_proxy']} "
            f"transport_failed={class_counts['transport_failed']}"
        )

    def _clear_tier3_terminal_startup_failure(self) -> None:
        previous_error = self._last_tier3_startup_error
        self._tier3_startup_terminal_failure = False
        self._last_tier3_startup_error = None
        if previous_error and self.last_error == previous_error:
            self.last_error = None

    def _fail_terminal_tier3_bootstrap(
        self,
        manager: Any,
        metadata: dict[str, Any] | None = None,
    ) -> bool:
        """Stop only an under-floor bootstrap Core after source supply ends."""
        if self.stop_event.is_set() or not self._tier3_required_for_start:
            return False
        required = self._tier3_startup_target_alive(manager)
        healthy = count_healthy_nodes(
            getattr(manager, "runtime_nodes", {}).get("tier3", [])
        )
        if (
            healthy >= required
            or not self._tier3_startup_supply_terminal(manager, metadata)
        ):
            return False

        reason = self._tier3_terminal_startup_error(
            healthy,
            required,
            manager,
        )
        runner_still_running = False
        stopped_bootstrap = False
        with self._core_transition_lock:
            healthy = count_healthy_nodes(
                getattr(manager, "runtime_nodes", {}).get("tier3", [])
            )
            if healthy >= required or not self._tier3_startup_supply_terminal(
                manager,
                metadata,
            ):
                return False
            phase = self._current_core_runtime_phase()
            # A formal Core may be serving another usable layer.  Terminal
            # bootstrap supply must never tear it down.
            if phase in {"formal_no_capture", "formal_capture"}:
                return False
            runner = self.core_runner
            if phase == "bootstrap" and runner is not None and runner.is_running():
                try:
                    runner.stop()
                except Exception:
                    log_raw_diagnostic(
                        self.logger,
                        "error",
                        "Failed to stop exhausted Mihomo bootstrap core",
                        exc_info=True,
                    )
                runner_still_running = bool(runner.is_running())
                stopped_bootstrap = not runner_still_running
            elif phase == "bootstrap":
                stopped_bootstrap = True

            if stopped_bootstrap or phase == "stopped":
                self._set_core_runtime_phase("stopped")
                with self._core_lifecycle_lock:
                    self._staged_capture_runtime_config_payload = None
                    self._staged_capture_runtime_config_path = None
                    self._staged_capture_runtime_export_contract = None
                    self._staged_capture_runtime_network_mode = None

            with self._tier3_core_gate_lock:
                self._tier3_core_gate_pending = False
                self._tier3_core_gate_requested_at = None
                self._tier3_core_gate_generation += 1
                self._tier3_core_gate_pending_generation = (
                    self._tier3_core_gate_generation
                )
            with self._tier3_pool_sync_lock:
                self._tier3_pool_sync_pending = False
                self._tier3_pool_sync_oldest_requested_at = 0.0
                self._tier3_pool_sync_pending_commit_count = 0
                self._tier3_pool_sync_pending_immediate = False
                self._tier3_pool_sync_pending_event = "append_only"
                self._tier3_pool_sync_pending_key = None
                self._tier3_pool_sync_active_key = None
                self._tier3_pool_sync_parked_key = None
                self._tier3_pool_sync_parked_event = "append_only"
                self._tier3_pool_sync_last_attempted_key = None
            with self._tier3_egress_activation_lock:
                self._tier3_egress_activation_pending = False
                self._tier3_egress_activation_pending_mode = ""
                self._tier3_egress_activation_pending_key = None
                self._tier3_egress_activation_active_key = None
                self._tier3_egress_activation_generation += 1

        if runner_still_running:
            reason += "; isolated bootstrap shutdown did not complete"
        self._tier3_startup_terminal_failure = True
        self._last_tier3_startup_error = reason
        self.last_error = reason
        self._start_deferred_reason = None
        self._start_deferred_is_live = False
        self._invalidate_exit_route_context()
        self._set_effective_egress_state(False, reason)
        lock = getattr(manager, "lock", None)
        with lock if lock is not None else nullcontext():
            report = ensure_tier3_collection_report(manager)
            report["core_process_running"] = runner_still_running
            report["core_standby"] = False
            report["traffic_capture_active"] = False
            report["runtime_source_bootstrap_status"] = "unavailable"
            report["runtime_source_bootstrap_ready"] = False
            report["runtime_source_bootstrap_reason"] = "source_supply_terminal"
            report["startup_failed"] = True
            report["startup_failure_reason"] = "source_supply_terminal"
            from bridge_messages import startup_diagnostic
            self._bridge_start_failure_record = (
                int(self._runtime_generation), reason, startup_diagnostic(diagnostic={
                    "reason_code": "source_supply_terminal",
                    "source_supply_terminal_reason": report.get("source_supply_terminal_reason"),
                    "source_retry_blocked_reason": report.get("source_retry_blocked_reason"),
                    "source_supply_blocked_count": report.get("source_supply_blocked_count"),
                    "failed_sources": report.get("failed_sources"),
                    "source_fetch_failed": report.get("source_fetch_failed"),
                }))
        log_raw_diagnostic(self.logger, "warning", "%s", reason)
        return True

    def _tier3_startup_live_collection_reason(self, manager: Any) -> str:
        if self._tier3_startup_supply_terminal(manager):
            return ""
        try:
            report = ensure_tier3_collection_report(manager)
        except Exception:
            report = getattr(manager, "tier3_last_collection_report", {}) or {}
        report = report if isinstance(report, dict) else {}
        progress = getattr(manager, "tier3_refresh_progress", {}) or {}
        progress = progress if isinstance(progress, dict) else {}

        def _count(*keys: str) -> int:
            values: list[int] = []
            for key in keys:
                for payload in (report, progress):
                    try:
                        values.append(max(0, int(payload.get(key) or 0)))
                    except (TypeError, ValueError):
                        continue
            return max(values, default=0)

        input_exhausted = bool(report.get("input_exhausted"))
        if bool(report.get("source_retry_due")) or _count("source_retry_due_count", "retryable_failed_sources") > 0:
            return str(report.get("startup_deferred_reason") or report.get("source_stream_sampling_diagnosis") or "pre_gate_source_retry_due")
        if _count(
            "source_fetch_pending",
            "source_stream_source_fetch_pending",
            "pending_source_units",
            "source_stream_pending_source_unit_count",
            "retry_due_source_units",
            "source_stream_retry_due_source_unit_count",
        ) > 0:
            if _count("pending_source_units", "source_stream_pending_source_unit_count") > 0:
                return "source_unit_coverage_pending"
            return "source_fetch_pending"
        if _count(
            "validation_backlog_remaining",
            "source_stream_responsive_backlog_count",
            "source_stream_outstanding_full_validation_count",
            "source_stream_fair_backlog_count",
            "source_stream_backlog_count",
        ) > 0:
            return "validation_backlog_remaining"
        if (
            bool(report.get("background_expansion_due"))
            and not input_exhausted
            and _count("source_count", "source_stream_source_count") > 0
        ):
            return str(report.get("source_stream_sampling_diagnosis") or "background_expansion_due")
        configured_sources = max(
            _count("configured_source_count", "source_count", "source_stream_source_count"),
            max(0, int(getattr(manager, "tier3_source_count", 0) or 0)),
        )
        if configured_sources > 0 and self._tier3_collect_action_running(manager):
            return "source_unit_coverage_pending"
        return ""

    def _wait_for_tier3_startup_gate(self, manager: Any, required: int) -> int:
        deadline = time.monotonic() + self._tier3_startup_gate_timeout_seconds(manager)
        last_seen = -1
        last_catchup_trigger_at = 0.0
        while not self.stop_event.is_set():
            now = time.monotonic()
            current = count_healthy_nodes(getattr(manager, "runtime_nodes", {}).get("tier3", []))
            if current >= required:
                return current
            last_seen = current
            if now >= deadline:
                return current
            if not self._tier3_collect_action_running(manager):
                live_reason = self._tier3_startup_live_collection_reason(manager)
                if live_reason:
                    if now - last_catchup_trigger_at >= 0.5:
                        last_catchup_trigger_at = now
                        self.logger.info(
                            "Bastion Layer startup gate still below target (%s/%s); continuing catch-up collection (%s)",
                            current,
                            required,
                            live_reason,
                        )
                        self._trigger_tier3_background_collect(manager, startup_mode=True)
                    time.sleep(0.2)
                    continue
                return current
            time.sleep(0.2)
        return max(0, last_seen)

    def _trigger_tier3_background_collect(self, manager: Any, *, startup_mode: bool) -> bool:
        trigger = getattr(manager, "trigger_tier3_collect", None)
        if callable(trigger):
            try:
                result = trigger(startup_mode=startup_mode)
                if isinstance(result, dict):
                    return bool(result.get("accepted") or result.get("status") == "running")
                return True
            except Exception:
                log_raw_diagnostic(
                    self.logger,
                    "warning",
                    "Failed to trigger Bastion Layer background collection",
                    exc_info=True,
                )
                return False
        refresher = getattr(manager, "refresh_tier3", None)
        if callable(refresher):
            refresher(suppress_intervention_alert=True, startup_mode=startup_mode)
            return False
        return False

    def _start_tier3_expansion_before_primary_checks(
        self,
        manager: Any,
        *,
        lifecycle_revision: int,
    ) -> None:
        tier3_enabled = getattr(manager, "_tier3_enabled", None)
        if not callable(tier3_enabled) or not tier3_enabled():
            return
        # Create the expansion and its source supervisor before waiting for the
        # no-capture route. The expansion may observe an empty route and keep
        # its roots pending; the route wake below dispatches them as soon as the
        # private listeners are ready. Both steps still precede Tier1/Tier2
        # checks, so those checks cannot hold the Core transition lock first.
        started = self._trigger_tier3_background_collect(
            manager,
            startup_mode=True,
        )
        if started:
            wait_until_ready = getattr(
                manager,
                "wait_for_tier3_expansion_ready",
                None,
            )
            if callable(wait_until_ready):
                readiness = wait_until_ready(timeout_seconds=0.5)
                if not bool(dict(readiness or {}).get("ready")):
                    log_event(
                        self.logger,
                        "ERROR",
                        "tier3.expansion_start_liveness_violation",
                        "Bastion expansion control plane was not ready within 500ms "
                        f"(state={dict(readiness or {})})",
                    )
        trigger_user_health = getattr(
            manager,
            "trigger_tier3a_health_check",
            None,
        )
        if callable(trigger_user_health):
            trigger_user_health()
        self._require_current_start_intent(lifecycle_revision)
        if not started:
            return
        # Qualify resolvers off the Core transition lock; the bootstrap writer
        # below then reuses this plan instead of probing under the lock.
        try:
            self._prepare_dns_resolver_plan(reason="tier3_expansion_start")
        except Exception:
            log_raw_diagnostic(
                self.logger, "warning", "DNS resolver plan preparation failed", exc_info=True,
            )
        self._require_current_start_intent(lifecycle_revision)
        bootstrap_ready = False
        try:
            self._ensure_bootstrap_core_proxy()
            bootstrap_ready = True
        except Exception:
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Bastion no-capture source bootstrap is not ready yet; "
                "source leases will remain pending",
                exc_info=True,
            )
        if bootstrap_ready:
            notify_source_supply = getattr(
                manager,
                "notify_tier3_source_supply_route_changed",
                None,
            )
            if callable(notify_source_supply):
                notify_source_supply("bootstrap_source_control_ready")
        self._require_current_start_intent(lifecycle_revision)

    def _recover_tier3_pool_after_core_start_failure(self, reason: str, *, attempt_index: int) -> bool:
        manager = self.manager
        if not manager:
            return False
        required = self._tier3_startup_target_alive(manager)
        current = count_healthy_nodes(manager.runtime_nodes.get("tier3", []))
        failed_marker = self._tier3_core_sync_marker()
        log_raw_diagnostic(
            self.logger,
            "warning",
            "Bastion Layer core verification left %s/%s startup nodes; deferring retry %s until the committed pool changes: %s",
            current,
            required,
            attempt_index + 1,
            reason,
        )
        background_started = False
        trigger = getattr(manager, "trigger_tier3_collect", None)
        if callable(trigger):
            try:
                result = trigger(startup_mode=False)
                if isinstance(result, dict):
                    background_started = bool(result.get("accepted") or result.get("status") == "running")
                else:
                    background_started = True
            except Exception:
                log_raw_diagnostic(
                    self.logger,
                    "warning",
                    "Bastion Layer retry collection trigger failed after core verification failure",
                    exc_info=True,
                )
                return False
        else:
            try:
                with manager.lock:
                    manager.last_collect_tier3 = 0.0
                    report = ensure_tier3_collection_report(manager)
                    report["background_expansion_due"] = True
            except Exception:
                log_raw_diagnostic(
                    self.logger,
                    "warning",
                    "Failed to mark Bastion Layer background expansion due after core verification failure",
                    exc_info=True,
                )
        if failed_marker is not None:
            self._mark_tier3_core_sync_failure(failed_marker)
        if not background_started:
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Bastion Layer retry collection did not start; core start remains deferred until the next committed pool update"
            )
        return False

    def _core_startup_timeout(self, proxy_config: dict[str, Any], runtime_config_path: Path) -> float:
        uses_geodata = self._runtime_config_uses_geodata(runtime_config_path)
        missing = self._missing_geodata_assets() if uses_geodata else []
        timeout = core_startup_timeout_plan(
            proxy_config,
            uses_geodata=uses_geodata,
            missing_assets=missing,
            geo_config=geo_update_block(self.config),
        )
        if timeout.extended:
            self.logger.info(
                "Extending mihomo startup timeout to %.0fs while missing GeoData initializes: %s",
                timeout.seconds,
                ", ".join(missing),
            )
        return timeout.seconds

    def _ensure_geodata_ready_for_core_start(self, runtime_config_path: Path) -> None:
        if not self._runtime_config_uses_geodata(runtime_config_path):
            return
        missing = self._missing_geodata_assets()
        if not missing:
            return
        geo_config = geo_update_block(self.config)
        if not coerce_bool(geo_config.get("enabled", True), True):
            raise RuntimeError(
                "Required GeoData is missing and the GeoData updater is disabled: "
                + ", ".join(missing)
            )
        explicit_proxy = egress_proxy_block(self.config)
        download_policy: GeoDownloadPolicy | None = None
        download_assets: list[str] | None = None
        if proxy_url_from_config(explicit_proxy, purpose="collection"):
            geo_proxy = explicit_proxy
            route_label = "explicit egress proxy"
        else:
            # First run: the only proxy is the Bastion Layer pool the running
            # bootstrap Core has just been supplied with.  Its private
            # FINAL-EXIT source listener routes through that pool, never
            # DIRECT, so GeoData keeps its proxy-only rule.
            geo_proxy = self._bootstrap_pool_geodata_proxy()
            route_label = "Bastion Layer pool"
            # A retry after one asset arrived fetches only what is missing.
            download_assets = list(missing)
            if geo_proxy is not None:
                # That source listener leaves through the pool's first member
                # only.  This run's GeoData listener takes the next member on
                # every connection, so a member that carries bulk data slowly
                # costs one short attempt instead of the whole Core start.
                rotating_proxy = self._bootstrap_geodata_rotating_proxy()
                if rotating_proxy is not None:
                    geo_proxy = rotating_proxy
                    download_policy = GeoDownloadPolicy()
        if geo_proxy is None:
            raise RuntimeError(
                "Required GeoData is missing before Mihomo startup; preflight download "
                "requires an explicit egress proxy or a running Bastion Layer pool: "
                + ", ".join(missing)
            )
        self.logger.info(
            "Preparing Mihomo GeoData before core launch through the %s: %s",
            route_label,
            ", ".join(missing),
        )
        try:
            self.geo_updater.reconfigure(
                geo_config,
                egress_proxy=geo_proxy,
            )
            # This runs under the Core transition lock: a stop request ends
            # the download between two reads instead of waiting for it.
            status = self.geo_updater.update_now(
                force=True,
                policy=download_policy,
                cancel=self.stop_event.is_set,
                assets=download_assets,
            )
        except Exception as exc:
            raise RuntimeError(
                f"GeoData preflight through the {route_label} failed: {exc}"
            ) from exc
        finally:
            if geo_proxy is not explicit_proxy:
                # The private listener credentials belong to this Core run
                # only; the monitor loop installs the formal route later.
                try:
                    self.geo_updater.reconfigure(geo_config, egress_proxy={})
                except Exception:
                    pass
        errors = status.get("errors", {}) if isinstance(status, dict) else {}
        remaining = self._missing_geodata_assets()
        if remaining and self.stop_event.is_set():
            raise RuntimeStartCancelled(
                "runtime stop requested during the GeoData preflight"
            )
        if remaining:
            raise GeoDataPreflightError(
                f"Required GeoData is still missing after {route_label} preflight: "
                + ", ".join(remaining)
            )
        self._geodata_preflight_retries = 0
        if errors:
            self.logger.info("GeoData preflight completed with non-blocking optional errors: %s", ", ".join(map(str, errors.keys())))

    def _bootstrap_geodata_rules_deferred(self) -> bool:
        """Whether the bootstrap Core must start without GEOIP/GEOSITE rules.

        True only while GeoData is not on disk and no explicit collection
        proxy can download it before launch -- a first run.  Otherwise the
        bootstrap renders the full rule list exactly as before.
        """

        try:
            if self._valid_explicit_collection_proxy():
                return False
            return bool(self._missing_geodata_assets())
        except Exception:
            return False

    def _bootstrap_geodata_listener_spec(
        self,
        *,
        allocate: bool,
    ) -> dict[str, Any] | None:
        """Port and credentials of this run's first-run GeoData listener.

        Stable for one runtime generation, so the bootstrap writer and the
        export-contract snapshot render the same bytes.  Only the writer
        allocates; a reader gets ``None`` until it has.
        """

        lock = getattr(self, "_runtime_source_transport_lock", None)
        with lock if lock is not None else nullcontext():
            generation = int(getattr(self, "_runtime_generation", 0) or 0)
            spec = getattr(self, "_bootstrap_geodata_listener", None)
            if isinstance(spec, dict) and spec.get("runtime_generation") == generation:
                return spec
            if not allocate:
                return None
            # The listener is an extra: whatever goes wrong here leaves the
            # bootstrap exactly as it is without it.
            try:
                excluded = set(self._runtime_source_excluded_ports())
                transport = getattr(self, "_runtime_source_transport", None)
                if transport is not None:
                    excluded.update(int(item.port) for item in transport.listeners)
                port = 0
                for _attempt in range(3):
                    candidate = int(self._runtime_source_candidate_ports(1)[0])
                    if candidate not in excluded:
                        port = candidate
                        break
            except Exception:
                port = 0
            if not port:
                return None
            credentials = RuntimeSourceListenerCredentials.generate()
            spec = {
                "runtime_generation": generation,
                "port": port,
                "username": credentials.username,
                "password": credentials.password,
            }
            self._bootstrap_geodata_listener = spec
            return spec

    def _bootstrap_geodata_rotating_proxy(self) -> dict[str, Any] | None:
        """This run's GeoData listener as a proxy, when the Core serves it.

        ``None`` when this run rendered none, or when the port does not answer
        as an authenticated Mihomo listener (it failed to bind, or the loaded
        config predates it).  The caller then keeps the pool's source
        listener.
        """

        from types import SimpleNamespace

        spec = self._bootstrap_geodata_listener_spec(allocate=False)
        if spec is None:
            return None
        try:
            answers = self._runtime_source_listener_requires_auth(
                SimpleNamespace(host="127.0.0.1", port=int(spec["port"]))
            )
        except Exception:
            answers = False
        if not answers:
            return None
        return {
            "enabled": True,
            "scheme": "http",
            "server": "127.0.0.1",
            "port": int(spec["port"]),
            "username": str(spec["username"]),
            "password": str(spec["password"]),
            "use_for": {"collection": True},
        }

    def _bootstrap_pool_geodata_proxy(self) -> dict[str, Any] | None:
        """Return the bootstrap Core's pool-routed listener as a GeoData proxy.

        Available only while the running Core is still the bootstrap Core,
        its private listeners are loaded, and the Bastion Layer pool it routes
        through holds at least one healthy node.  That listener is bound to
        PROXY-FALLBACK in the bootstrap render, so it never exits DIRECT.
        """

        runner = self.core_runner
        manager = self.manager
        if (
            runner is None
            or manager is None
            or not runner.is_running()
            or self._current_core_runtime_phase() != "bootstrap"
        ):
            return None
        try:
            healthy = count_healthy_nodes(
                getattr(manager, "runtime_nodes", {}).get("tier3", [])
            )
        except Exception:
            healthy = 0
        if healthy <= 0:
            return None
        transport = self._runtime_source_loaded_transport_snapshot()
        if transport is None:
            return None
        listener = next(
            (
                item
                for item in transport.listeners
                if item.route_kind is RuntimeSourceRouteKind.FINAL_EXIT
            ),
            None,
        )
        if listener is None:
            return None
        return {
            "enabled": True,
            "scheme": "http",
            "server": listener.listen,
            "port": int(listener.port),
            "username": listener.credentials.username,
            "password": listener.credentials.password,
            "use_for": {"collection": True},
        }

    def _runtime_config_uses_geodata(self, runtime_config_path: Path) -> bool:
        return runtime_config_uses_geodata(runtime_config_path)

    def _missing_geodata_assets(self) -> list[str]:
        work_dir = self._resolve_path(mihomo_client_paths(self._client_config()).work_dir)
        return missing_geodata_assets(work_dir, asset_filenames=ASSET_FILENAMES)

    def _primary_layers_configured(self) -> bool:
        return primary_layers_configured(self.config)

    def _tier3_cached_nodes_verified_for_start(self, manager: Any) -> list[Any]:
        nodes = list(getattr(manager, "runtime_nodes", {}).get("tier3", []))
        report = getattr(manager, "tier3_last_collection_report", {}) or {}
        verification = tier3_cached_start_verification(nodes, report)
        if verification.discarded_count:
            self.logger.info(
                "Ignoring %s TCP-only cached Bastion candidate(s) during startup; core verification is required",
                verification.discarded_count,
            )
            with manager.lock:
                replace_pool = getattr(manager, "_replace_tier3_pool_locked", None)
                if callable(replace_pool):
                    replace_pool(
                        list(verification.nodes),
                        actor="snapshot_migration",
                        reason="discard TCP-only cached startup candidates",
                        allow_total_decrease=True,
                    )
                else:
                    manager.runtime_nodes["tier3"] = list(verification.nodes)
            if isinstance(report, dict):
                report["discarded_tcp_candidate_cache_count"] = verification.discarded_count
        return verification.nodes

    @staticmethod
    def _tier3_core_verification_retry_pending(manager: Any) -> bool:
        report = getattr(manager, "tier3_last_collection_report", {}) or {}
        report = report if isinstance(report, dict) else {}
        failed = report.get("startup_core_verification_failed", {})
        return bool(isinstance(failed, dict) and failed.get("will_retry_collection"))

    @staticmethod
    def _clear_tier3_core_verification_retry_pending(manager: Any) -> None:
        report = getattr(manager, "tier3_last_collection_report", {}) or {}
        if isinstance(report, dict):
            report.pop("startup_core_verification_failed", None)

    def _primary_runtime_healthy_count(self) -> int:
        manager = self.manager
        if not manager:
            return 0
        runtime_nodes = getattr(manager, "runtime_nodes", {})
        return primary_runtime_healthy_count(runtime_nodes)

    def _primary_layers_ready_for_start(self) -> bool:
        if not self._primary_layers_configured():
            self._primary_startup_error = "no primary layers are configured"
            return False
        manager = self.manager
        if not manager:
            self._primary_startup_error = "manager service is not running"
            return False
        if self._primary_runtime_healthy_count() > 0:
            self._primary_startup_error = None
            return True

        failures: list[str] = []
        self.logger.info("Checking Vanguard/Sentinel before deciding whether Bastion fallback is required")
        try:
            checker = getattr(manager, "check_tier1", None)
            if callable(checker):
                checker()
        except Exception as exc:
            failures.append(f"tier1={exc}")
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Vanguard startup check failed",
                exc_info=True,
            )
        try:
            checker = getattr(manager, "check_tier2", None)
            if callable(checker):
                checker(force_remote_refresh=True)
        except Exception as exc:
            failures.append(f"tier2={exc}")
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Sentinel startup check failed",
                exc_info=True,
            )

        healthy_count = self._primary_runtime_healthy_count()
        if healthy_count > 0:
            self._primary_startup_error = None
            self.logger.info("Primary layers have %s validated node(s); Bastion will collect in the background", healthy_count)
            return True
        self._primary_startup_error = primary_startup_unhealthy_message(failures)
        log_raw_diagnostic(
            self.logger,
            "warning",
            "%s; falling back to Bastion Layer",
            self._primary_startup_error,
        )
        return False

    def _tier3_is_primary_export(self) -> bool:
        return tier3_is_primary_export(
            primary_configured=self._primary_layers_configured(),
            tier3_required_for_start=self._tier3_required_for_start,
            core_sync_marker=self._tier3_core_sync_marker(),
        )

    def _tier3_enabled_without_primary(self) -> bool:
        manager = self.manager
        tier3_enabled = getattr(manager, "_tier3_enabled", None)
        return tier3_enabled_without_primary(
            tier3_enabled=bool(manager and callable(tier3_enabled) and tier3_enabled()),
            primary_configured=self._primary_layers_configured(),
        )

    def _should_keep_existing_core_for_empty_tier3_export(self) -> bool:
        manager = self.manager
        tier3_enabled = getattr(manager, "_tier3_enabled", None)
        return should_keep_existing_core_for_empty_tier3_export(
            tier3_enabled=bool(manager and callable(tier3_enabled) and tier3_enabled()),
            primary_configured=self._primary_layers_configured(),
            tier3_required_for_start=self._tier3_required_for_start,
            primary_healthy_count=self._primary_runtime_healthy_count(),
        )

    def _testing_block(self) -> dict[str, Any]:
        return testing_block(self.config)

    def _as_string_list(self, value: Any) -> list[str]:
        return as_string_list(value)

    def _default_probe_urls(self) -> list[str]:
        return default_probe_urls(self.config)

    def _bootstrap_source_probe_urls(self) -> list[str]:
        """Configured HTTPS probe URLs, in order, without duplicates.

        The private bootstrap proof tunnels through the source listener with
        CONNECT, so only HTTPS endpoints are usable for it.
        """

        urls: list[str] = []
        for candidate in self._default_probe_urls():
            value = str(candidate or "").strip()
            if not value or value in urls:
                continue
            if urlsplit(value).scheme.casefold() != "https":
                continue
            urls.append(value)
        if not urls:
            urls.append(str(self._default_probe_urls()[0]))
        return urls

    def _default_probe_url(self) -> str:
        return default_probe_url(self.config)

    def _default_probe_expected_statuses(self) -> set[int]:
        return default_probe_expected_statuses(self.config)

    def _default_probe_timeout_ms(self) -> int:
        return default_probe_timeout_ms(self.config)

    def _startup_probe_timeout_seconds(self) -> float:
        return startup_probe_timeout_seconds(self.config)

    def _probe_response_body_ok(self, status_code: int, body: bytes) -> bool:
        if status_code == 204:
            return body == b""
        return True

    @staticmethod
    def _safe_probe_endpoint_label(value: Any) -> str:
        try:
            parsed = urlsplit(str(value or "").strip())
            hostname = str(parsed.hostname or "").strip()
            port = parsed.port
        except (TypeError, ValueError):
            return "configured-probe"
        if not hostname:
            return "configured-probe"
        try:
            address = ipaddress.ip_address(hostname)
        except ValueError:
            try:
                normalized = hostname.rstrip(".").encode("idna").decode("ascii").lower()
            except (UnicodeError, ValueError):
                return "configured-probe"
            authority = normalized or "configured-probe"
        else:
            compressed = address.compressed
            authority = f"[{compressed}]" if address.version == 6 else compressed
        return f"{authority}:{port}" if port is not None else authority

    @staticmethod
    def _mihomo_selected_routes_ready(payload: Any) -> dict[str, Any]:
        """Inspect the controller graph without causing any proxy traffic.

        Mihomo versions before 1.19.27 can briefly publish ``COMPATIBLE`` as the current
        selection of an otherwise fail-closed empty group.  Following ``now``
        directly (including groups whose ``all`` list is still empty) avoids
        mistaking that initialization state for a usable proxy route.
        """

        if not isinstance(payload, dict):
            return {
                "ready": False,
                "reason": "controller /proxies payload is not a mapping",
                "routes": {},
            }
        raw_entries = payload.get("proxies")
        if raw_entries is None:
            raw_entries = payload
        if not isinstance(raw_entries, dict):
            return {
                "ready": False,
                "reason": "controller /proxies entries are unavailable",
                "routes": {},
            }
        entries = {
            str(name): entry
            for name, entry in raw_entries.items()
            if isinstance(entry, dict)
        }
        routes: dict[str, Any] = {}

        for start in ("FINAL-EXIT", "PROXY-FALLBACK"):
            current = start
            chain: list[str] = []
            visited: set[str] = set()
            for _depth in range(32):
                normalized = str(current or "").strip().upper()
                if not normalized:
                    return {
                        "ready": False,
                        "reason": f"{start} has no current selection",
                        "routes": routes,
                    }
                chain.append(str(current))
                terminal_kind = builtin_terminal_kind(normalized)
                if terminal_kind == "unsafe_direct":
                    return {
                        "ready": False,
                        "reason": f"{start} still selects unsafe {normalized}",
                        "routes": {**routes, start: chain},
                    }
                if terminal_kind == "fail_closed":
                    routes[start] = {
                        "chain": chain,
                        "leaf": normalized,
                        "terminal": "fail_closed",
                    }
                    break
                if current in visited:
                    return {
                        "ready": False,
                        "reason": f"{start} route contains a selection cycle",
                        "routes": {**routes, start: chain},
                    }
                visited.add(current)
                entry = entries.get(current)
                if entry is None:
                    return {
                        "ready": False,
                        "reason": f"{start} current selection is not loaded",
                        "routes": {**routes, start: chain},
                    }
                entry_type = str(
                    entry.get("type") or entry.get("typeName") or ""
                ).strip().lower()
                group_entry = bool(
                    "now" in entry
                    or "selected" in entry
                    or "all" in entry
                    or "select" in entry_type
                    or "fallback" in entry_type
                    or "urltest" in entry_type.replace("-", "")
                    or "loadbalance" in entry_type.replace("-", "")
                )
                if group_entry:
                    selected = str(
                        entry.get("now") or entry.get("selected") or ""
                    ).strip()
                    if not selected:
                        return {
                            "ready": False,
                            "reason": f"{start} group selection is not initialized",
                            "routes": {**routes, start: chain},
                        }
                    current = selected
                    continue
                routes[start] = {
                    "chain": chain,
                    "leaf": str(current),
                    "terminal": "proxy",
                }
                break
            else:
                return {
                    "ready": False,
                    "reason": f"{start} route exceeded the recursion limit",
                    "routes": {**routes, start: chain},
                }

        return {
            "ready": True,
            "reason": "selected routes are initialized without direct terminals",
            "routes": routes,
        }

    def _current_mihomo_runtime_config_path(self) -> Path:
        return self._resolve_path(
            mihomo_client_paths(self._client_config()).runtime_config_path
        )

    @staticmethod
    def _mihomo_runtime_graph_ready(
        controller_payload: Any,
        runtime_config_path: Path,
        provider_base_dir: Path | None = None,
    ) -> dict[str, Any]:
        """Confirm /proxies represents the config just written, not an old graph."""

        path = Path(runtime_config_path)
        if not path.is_file():
            return {"ready": False, "reason": "loaded Mihomo runtime config is unavailable"}
        try:
            expected = yaml.safe_load(path.read_text(encoding="utf-8"))
        except Exception as exc:
            return {
                "ready": False,
                "reason": f"Mihomo runtime graph could not be read ({exc.__class__.__name__})",
            }
        if not isinstance(expected, dict):
            return {"ready": False, "reason": "Mihomo runtime graph is not a mapping"}
        raw_entries = (
            controller_payload.get("proxies")
            if isinstance(controller_payload, dict)
            else None
        )
        if not isinstance(raw_entries, dict):
            return {"ready": False, "reason": "controller proxy graph is unavailable"}

        expected_proxy_names = {
            str(proxy.get("name") or "")
            for proxy in expected.get("proxies", [])
            if isinstance(proxy, dict) and str(proxy.get("name") or "").strip()
        }
        missing_proxies = sorted(expected_proxy_names.difference(map(str, raw_entries)))
        if missing_proxies:
            return {
                "ready": False,
                "reason": "controller has not loaded every configured proxy",
            }

        groups = expected.get("proxy-groups")
        if groups is None:
            groups = []
        if not isinstance(groups, list):
            return {"ready": False, "reason": "configured proxy groups are invalid"}
        providers = expected.get("proxy-providers")
        providers = providers if isinstance(providers, dict) else {}
        for group in groups:
            if not isinstance(group, dict):
                return {"ready": False, "reason": "configured proxy group is invalid"}
            name = str(group.get("name") or "").strip()
            candidates = group.get("proxies")
            if candidates is None:
                candidates = []
            if not name or not isinstance(candidates, list):
                return {"ready": False, "reason": "configured proxy group is incomplete"}
            expected_candidates = [str(candidate) for candidate in candidates]
            provider_names = group.get("use")
            if provider_names is None:
                provider_names = []
            if not isinstance(provider_names, list):
                return {
                    "ready": False,
                    "reason": "configured proxy group provider set is invalid",
                }
            for raw_provider_name in provider_names:
                provider_name = str(raw_provider_name or "").strip()
                provider = providers.get(provider_name)
                if not provider_name or not isinstance(provider, dict):
                    return {
                        "ready": False,
                        "reason": "configured proxy group provider is unavailable",
                    }
                if str(provider.get("type") or "").strip().lower() != "file":
                    return {
                        "ready": False,
                        "reason": "runtime graph cannot prove a non-file proxy provider",
                    }
                raw_provider_path = str(provider.get("path") or "").strip()
                provider_path = Path(raw_provider_path) if raw_provider_path else None
                if provider_path is None:
                    return {
                        "ready": False,
                        "reason": "configured file proxy provider has no path",
                    }
                if not provider_path.is_absolute():
                    provider_path = Path(
                        provider_base_dir
                        if provider_base_dir is not None
                        else path.parent
                    ) / provider_path
                try:
                    provider_document = yaml.safe_load(
                        provider_path.read_text(encoding="utf-8")
                    )
                except Exception:
                    return {
                        "ready": False,
                        "reason": "configured file proxy provider is unreadable",
                    }
                provider_proxies = (
                    provider_document.get("proxies")
                    if isinstance(provider_document, dict)
                    else None
                )
                if not isinstance(provider_proxies, list):
                    return {
                        "ready": False,
                        "reason": "configured file proxy provider is invalid",
                    }
                provider_members = [
                    str(proxy.get("name") or "").strip()
                    for proxy in provider_proxies
                    if isinstance(proxy, dict)
                    and str(proxy.get("name") or "").strip()
                ]
                if len(provider_members) != len(provider_proxies):
                    return {
                        "ready": False,
                        "reason": "configured file proxy provider has unnamed members",
                    }
                expected_candidates.extend(provider_members)
            loaded_group = raw_entries.get(name)
            loaded_candidates = (
                loaded_group.get("all")
                if isinstance(loaded_group, dict)
                else None
            )
            if not isinstance(loaded_candidates, list) or [
                str(candidate) for candidate in loaded_candidates
            ] != expected_candidates:
                return {
                    "ready": False,
                    "reason": "controller proxy groups still represent an older config",
                }
        return {"ready": True, "reason": "controller graph matches runtime config"}

    def _mihomo_rule_providers_ready(
        self,
        runtime_config_path: Path,
    ) -> dict[str, Any]:
        """Require every configured rule provider to be loaded before use."""

        path = Path(runtime_config_path)
        if not path.is_file():
            return {
                "ready": False,
                "reason": "loaded Mihomo runtime config is unavailable",
                "providers": [],
            }
        try:
            payload = yaml.safe_load(path.read_text(encoding="utf-8"))
        except Exception as exc:
            return {
                "ready": False,
                "reason": f"Mihomo rule-provider config could not be read ({exc.__class__.__name__})",
                "providers": [],
            }
        providers = payload.get("rule-providers") if isinstance(payload, dict) else None
        if not isinstance(providers, dict) or not providers:
            return {"ready": True, "reason": "no rule providers configured", "providers": []}

        work_dir = self._resolve_path(
            mihomo_client_paths(self._client_config()).work_dir
        )
        expected_names: list[str] = []
        missing_assets: list[str] = []
        for raw_name, raw_provider in providers.items():
            name = str(raw_name)
            expected_names.append(name)
            if not isinstance(raw_provider, dict):
                missing_assets.append(name)
                continue
            provider_type = str(raw_provider.get("type") or "").strip().lower()
            raw_path = str(raw_provider.get("path") or "").strip()
            provider_path = Path(raw_path) if raw_path else None
            if provider_path is not None and not provider_path.is_absolute():
                provider_path = work_dir / provider_path
            if provider_type not in {"file", "http"}:
                missing_assets.append(name)
                continue
            # HTTP providers may legally omit path; Mihomo then derives a
            # cache filename from the URL.  Controller presence below is the
            # authoritative loaded-state check for that form.  Explicit paths
            # and local providers must exist before the route is exposed.
            if (
                (provider_type == "file" and not provider_path)
                or (provider_path is not None and not provider_path.is_file())
            ):
                missing_assets.append(name)
        if missing_assets:
            return {
                "ready": False,
                "reason": "rule-provider assets are still initializing",
                "providers": expected_names,
            }

        try:
            controller_payload = self._require_api_client().providers_rules()
        except Exception as exc:
            return {
                "ready": False,
                "reason": f"controller rule-provider query failed ({exc.__class__.__name__})",
                "providers": expected_names,
            }
        loaded = (
            controller_payload.get("providers")
            if isinstance(controller_payload, dict)
            else None
        )
        if not isinstance(loaded, dict):
            return {
                "ready": False,
                "reason": "controller rule-provider state is unavailable",
                "providers": expected_names,
            }
        missing_loaded = [name for name in expected_names if name not in loaded]
        if missing_loaded:
            return {
                "ready": False,
                "reason": "controller has not loaded every rule provider",
                "providers": expected_names,
            }
        uninitialized: list[str] = []
        for name in expected_names:
            entry = loaded.get(name)
            updated_text = str(
                entry.get("updatedAt") or entry.get("updated-at") or ""
            ).strip() if isinstance(entry, dict) else ""
            try:
                updated_at = datetime.fromisoformat(
                    updated_text.replace("Z", "+00:00")
                )
            except (TypeError, ValueError):
                updated_at = None
            if updated_at is None or updated_at.year <= 1:
                uninitialized.append(name)
        if uninitialized:
            return {
                "ready": False,
                "reason": "controller rule providers are still initializing",
                "providers": expected_names,
            }
        return {
            "ready": True,
            "reason": "rule providers are loaded",
            "providers": expected_names,
        }

    def _wait_for_mihomo_route_ready(
        self,
        *,
        timeout: float | None = None,
        poll_interval: float = 0.05,
        runtime_config_path: Path | None = None,
    ) -> dict[str, Any]:
        """Wait for controller selections only; never issue a public probe."""

        timeout_seconds = (
            self._startup_probe_timeout_seconds()
            if timeout is None
            else max(0.0, float(timeout))
        )
        deadline = time.monotonic() + timeout_seconds
        last_reason = "controller route state is unavailable"
        while True:
            if self.stop_event.is_set():
                raise RuntimeError("mihomo route readiness cancelled")
            try:
                controller_payload = self._require_api_client().proxies()
                state = self._mihomo_selected_routes_ready(controller_payload)
            except Exception as exc:
                state = {
                    "ready": False,
                    "reason": f"controller route query failed ({exc.__class__.__name__})",
                    "routes": {},
                }
            if state.get("ready") is True:
                resolved_runtime_path = (
                    runtime_config_path or self._current_mihomo_runtime_config_path()
                )
                graph_state = self._mihomo_runtime_graph_ready(
                    controller_payload,
                    resolved_runtime_path,
                    provider_base_dir=self._resolve_path(
                        mihomo_client_paths(self._client_config()).work_dir
                    ),
                )
                if graph_state.get("ready") is not True:
                    state = {
                        "ready": False,
                        "reason": graph_state.get("reason"),
                        "routes": state.get("routes", {}),
                        "runtime_graph": graph_state,
                    }
                else:
                    state["runtime_graph"] = graph_state
            if state.get("ready") is True:
                provider_state = self._mihomo_rule_providers_ready(
                    runtime_config_path or self._current_mihomo_runtime_config_path()
                )
                if provider_state.get("ready") is True:
                    state["rule_providers"] = provider_state
                    # Decision D option A: the controller view the following
                    # FINAL-EXIT probe runs on (a reload's proof reads it).
                    self._route_ready_view = controller_payload
                    return state
                state = {
                    "ready": False,
                    "reason": provider_state.get("reason"),
                    "routes": state.get("routes", {}),
                    "rule_providers": provider_state,
                }
            last_reason = str(state.get("reason") or last_reason)
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                raise RuntimeError(
                    "mihomo selected routes did not become fail-closed ready: "
                    + last_reason
                )
            if self.stop_event.wait(min(max(0.01, poll_interval), remaining)):
                raise RuntimeError("mihomo route readiness cancelled")

    def _run_brokered_runtime_probe(
        self,
        callback: Callable[[ProbeExecutionContext | None], Any],
        *,
        priority: ProbePriority,
        queue_timeout_seconds: float,
        socket_start_timeout_seconds: float | None = None,
        execution_deadline_monotonic: float | None = None,
    ) -> Any:
        broker = getattr(self, "_runtime_probe_broker", None)
        if broker is not None:
            result = broker.run(
                priority,
                callback,
                queue_timeout_seconds=max(0.0, float(queue_timeout_seconds)),
                socket_start_timeout_seconds=socket_start_timeout_seconds,
                cancel_event=getattr(self, "stop_event", None),
                execution_deadline_monotonic=execution_deadline_monotonic,
            )
            if result.disposition is not ProbeDisposition.EXECUTED:
                reason = getattr(result, "indeterminate_reason", None)
                raise _RuntimeProbeBudgetUnavailable(
                    "runtime data-plane probe is indeterminate"
                    + (f" ({reason.value})" if reason is not None else ""),
                    probe_indeterminate_reason=(reason.value if reason is not None else ""),
                )
            if result.error is not None:
                raise result.error
            return result.value

        # Compatibility for narrow adapters/tests created without the broker.
        semaphore = getattr(self, "_runtime_probe_semaphore", None)
        acquired = True
        if semaphore is not None:
            acquired = bool(
                semaphore.acquire(timeout=max(0.0, float(queue_timeout_seconds)))
            )
        if not acquired:
            raise _RuntimeProbeBudgetUnavailable(
                "runtime data-plane probe budget is saturated"
            )
        try:
            return callback(None)
        finally:
            if semaphore is not None:
                semaphore.release()

    @staticmethod
    def _mark_runtime_probe_socket_started(
        context: ProbeExecutionContext | None,
    ) -> None:
        if context is not None and not context.mark_socket_started():
            raise _RuntimeProbeBudgetUnavailable(
                "runtime data-plane probe expired before socket start"
            )

    def _mark_runtime_probe_socket_started_for_ticket(
        self,
        context: ProbeExecutionContext | None,
        *,
        recovery_ticket: _RuntimeRecoveryTicket | None = None,
        deadline_monotonic: float | None = None,
    ) -> None:
        """Linearize an actual socket start with one open incident ticket."""

        if not isinstance(recovery_ticket, _RuntimeRecoveryTicket):
            self._mark_runtime_probe_socket_started(context)
            return
        monitor_lock = getattr(self, "_runtime_failure_monitor_lock", None)
        if monitor_lock is None:
            raise _RuntimeProbeBudgetUnavailable(
                "runtime recovery probe lost incident admission"
            )
        with monitor_lock:
            if not self._runtime_recovery_ticket_matches_locked(
                recovery_ticket,
                require_open=True,
                deadline_monotonic=deadline_monotonic,
            ):
                raise _RuntimeProbeBudgetUnavailable(
                    "runtime recovery probe was superseded before socket start"
                )
            # This mark is the admission linearization point.  A terminal
            # outcome published after it observes an already-started request;
            # a terminal published before it prevents the dial entirely.
            self._mark_runtime_probe_socket_started(context)

    def _prepare_abortable_probe(
        self,
        context: ProbeExecutionContext | None,
        *,
        recovery_ticket: _RuntimeRecoveryTicket | None = None,
        deadline_monotonic: float | None = None,
    ) -> _RuntimeAbortHandle:
        owner = _RuntimeAbortHandle()
        if context is not None and context.execution_deadline_monotonic is not None:
            if not context.register_abort_callback(owner.abort):
                raise _RuntimeProbeBudgetUnavailable(
                    "runtime data-plane probe expired before abort registration"
                )
        self._mark_runtime_probe_socket_started_for_ticket(
            context,
            recovery_ticket=recovery_ticket,
            deadline_monotonic=deadline_monotonic,
        )
        return owner

    @staticmethod
    def _abortable_https_204_via_http_proxy(
        *,
        proxy_host: str,
        proxy_port: int,
        probe_url: str,
        timeout_seconds: float,
        abort_owner: _RuntimeAbortHandle,
        proxy_authorization: str = "",
        on_tunnel_established: Callable[[], None] | None = None,
    ) -> tuple[int, bytes]:
        """Issue one fresh HTTPS request through the local HTTP proxy.

        The socket owner is published before CONNECT/TLS/read, so the probe
        broker can actively close a blocked production request at its absolute
        deadline. Redirects are naturally rejected because this adapter never
        follows them.  ``on_tunnel_established`` is called once the local
        proxy answered CONNECT with 200, before the TLS handshake.
        """

        parsed = urlsplit(str(probe_url or ""))
        if "\r" in proxy_authorization or "\n" in proxy_authorization:
            raise ValueError("invalid proxy authorization header")
        if parsed.scheme.casefold() != "https" or not parsed.hostname:
            raise RuntimeError("FINAL-EXIT probe URL must be HTTPS")
        target_host = str(parsed.hostname)
        target_port = int(parsed.port or 443)
        request_target = parsed.path or "/"
        if parsed.query:
            request_target += "?" + parsed.query
        connect_host = (
            f"[{target_host}]"
            if ":" in target_host and not target_host.startswith("[")
            else target_host
        )
        host_header = connect_host
        if target_port != 443:
            host_header = f"{host_header}:{target_port}"
        timeout = max(0.05, float(timeout_seconds))
        deadline = time.monotonic() + timeout

        def remaining_timeout() -> float:
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                raise TimeoutError("HTTPS proxy probe deadline expired")
            return remaining
        raw_socket: socket.socket | None = None
        tls_socket: ssl.SSLSocket | None = None
        response: http.client.HTTPResponse | None = None
        try:
            raw_socket = socket.create_connection(
                (str(proxy_host), int(proxy_port)),
                timeout=timeout,
            )
            raw_socket.settimeout(timeout)
            abort_owner.bind(raw_socket)
            # CONNECT authority-form always includes the destination port,
            # including the HTTPS default.  Omitting ``:443`` makes Mihomo
            # accept a tunnel to an ambiguous authority and then return
            # plaintext on the socket, which surfaces as TLS
            # WRONG_VERSION_NUMBER even while native group health is green.
            connect_target = f"{connect_host}:{target_port}"
            proxy_auth_header = (
                f"Proxy-Authorization: {proxy_authorization}\r\n"
                if proxy_authorization else ""
            )
            raw_socket.sendall(
                (
                    f"CONNECT {connect_target} HTTP/1.1\r\n"
                    f"Host: {connect_target}\r\n"
                    f"{proxy_auth_header}"
                    "Proxy-Connection: keep-alive\r\n"
                    "Connection: keep-alive\r\n\r\n"
                ).encode("ascii", errors="strict")
            )
            # A successful CONNECT response switches protocols immediately
            # after the header terminator.  ``HTTPResponse.begin()`` applies
            # ordinary response-body framing to the 200 and can leave the
            # socket in the wrong state for the following TLS ClientHello.
            # Mirror ``HTTPConnection._tunnel`` instead: read only the status
            # line and bounded headers, then hand the untouched tunnel socket
            # to TLS.
            connect_response = http.client.HTTPResponse(raw_socket)
            try:
                _version, connect_status, _reason = (
                    connect_response._read_status()
                )
                header_count = 0
                max_header_line = 65536
                max_header_count = 100
                while True:
                    line = connect_response.fp.readline(
                        max_header_line + 1
                    )
                    if len(line) > max_header_line:
                        raise http.client.LineTooLong(
                            "CONNECT response header line"
                        )
                    if line in (b"\r\n", b"\n"):
                        break
                    if not line:
                        raise ConnectionError(
                            "local proxy closed during CONNECT headers"
                        )
                    header_count += 1
                    if header_count > max_header_count:
                        raise http.client.HTTPException(
                            "too many CONNECT response headers"
                        )
            finally:
                connect_response.close()
            connect_status = int(connect_status)
            if connect_status != 200:
                raise RuntimeError(
                    f"local proxy CONNECT returned {connect_status}"
                )
            if on_tunnel_established is not None:
                try:
                    on_tunnel_established()
                except Exception:
                    pass
            # Shared per factory: building a context loads the trust store,
            # which used to be charged to this probe's transport budget.
            context = shared_contract_context()
            raw_socket.settimeout(remaining_timeout())
            tls_socket = context.wrap_socket(
                raw_socket,
                server_hostname=target_host,
                do_handshake_on_connect=False,
            )
            # wrap_socket detaches the raw socket. Publish the TLS owner before
            # a potentially blocked handshake so broker cancellation can wake it.
            abort_owner.bind(tls_socket)
            tls_socket.settimeout(remaining_timeout())
            tls_socket.do_handshake()
            tls_socket.settimeout(remaining_timeout())
            tls_socket.sendall(
                (
                    f"GET {request_target} HTTP/1.1\r\n"
                    f"Host: {host_header}\r\n"
                    "User-Agent: Tesseract/1.0\r\n"
                    "Accept: */*\r\n"
                    "Connection: close\r\n\r\n"
                ).encode("ascii", errors="strict")
            )
            response = http.client.HTTPResponse(tls_socket)
            response.begin()
            status_code = int(response.status)
            body = response.read(128)
            return status_code, body
        finally:
            for resource in (response, tls_socket, raw_socket):
                if resource is None:
                    continue
                abort_owner.clear(resource)
                try:
                    resource.close()
                except Exception:
                    pass

    def _probe_mihomo_mixed_port(
        self,
        *,
        require_route_readback: bool = True,
    ) -> dict[str, Any]:
        """Authoritatively verify FINAL-EXIT with an empty HTTP 204 response.

        Configurable 200-compatible status sets remain available to ordinary
        node health checks.  They are deliberately not accepted here because
        this result enables host traffic capture and source refreshes.
        """
        timeout_seconds = self._startup_probe_timeout_seconds()
        if require_route_readback:
            # Runtime revalidation binds this probe to controller authority.
            # Initial startup passes False: the full proxy socket contract is
            # authoritative for READY, while controller metadata only arms
            # later sudden-failure attribution.
            self._wait_for_mihomo_route_ready(
                timeout=timeout_seconds,
                runtime_config_path=self._current_mihomo_runtime_config_path(),
            )

        def probe(context: ProbeExecutionContext | None) -> dict[str, Any]:
            if context is None:
                return self._probe_mihomo_mixed_port_leased(
                    route_ready_confirmed=True,
                )
            return self._probe_mihomo_mixed_port_leased(
                execution_context=context,
                route_ready_confirmed=True,
            )

        return self._run_brokered_runtime_probe(
            probe,
            priority=ProbePriority.ACTIVATION,
            queue_timeout_seconds=timeout_seconds,
            socket_start_timeout_seconds=timeout_seconds,
            execution_deadline_monotonic=(
                time.monotonic() + min(1.5, timeout_seconds)
            ),
        )

    def _probe_mihomo_mixed_port_leased(
        self,
        *,
        execution_context: ProbeExecutionContext | None = None,
        route_ready_confirmed: bool = False,
    ) -> dict[str, Any]:
        """Run the complete FINAL-EXIT contract while holding one probe slot."""

        if not route_ready_confirmed:
            self._wait_for_mihomo_route_ready(
                timeout=self._startup_probe_timeout_seconds(),
                runtime_config_path=self._current_mihomo_runtime_config_path(),
            )
        client_config = self._client_config()
        proxy_config = self._system_proxy_config()
        host = str(proxy_config.get("host", "127.0.0.1") or "127.0.0.1")
        if host in {"0.0.0.0", "::"}:
            host = "127.0.0.1"
        proxy_url = f"http://{host}:{self._client_mixed_port(client_config)}"
        opener = None
        if not (
            execution_context is not None
            and execution_context.execution_deadline_monotonic is not None
            and build_opener is _stdlib_build_opener
        ):
            opener = build_opener(
                ProxyHandler({"http": proxy_url, "https": proxy_url}),
                _RejectAuthoritativeProbeRedirects(),
            )
        timeout_seconds = self._startup_probe_timeout_seconds()
        failures: list[str] = []
        abort_owner = self._prepare_abortable_probe(execution_context)
        use_abortable_transport = bool(
            execution_context is not None
            and execution_context.execution_deadline_monotonic is not None
            and (opener is None or isinstance(opener, OpenerDirector))
        )
        for probe_url in self._default_probe_urls():
            probe_label = self._safe_probe_endpoint_label(probe_url)
            started = time.perf_counter()
            self._register_runtime_internal_probe(
                probe_url,
                timeout_seconds=timeout_seconds,
            )
            try:
                request_timeout = timeout_seconds
                if (
                    execution_context is not None
                    and execution_context.execution_deadline_monotonic is not None
                ):
                    remaining = max(
                        0.0,
                        execution_context.execution_deadline_monotonic
                        - time.monotonic(),
                    )
                    cleanup_grace = min(
                        0.25,
                        max(0.12, remaining * 0.08),
                    )
                    request_timeout = max(
                        0.05,
                        min(
                            request_timeout,
                            remaining - cleanup_grace,
                        ),
                    )
                if use_abortable_transport:
                    status_code, body = (
                        self._abortable_https_204_via_http_proxy(
                            proxy_host=host,
                            proxy_port=self._client_mixed_port(client_config),
                            probe_url=probe_url,
                            timeout_seconds=request_timeout,
                            abort_owner=abort_owner,
                        )
                    )
                else:
                    request = Request(
                        probe_url,
                        headers={"User-Agent": "Tesseract/1.0"},
                        method="GET",
                    )
                    with opener.open(request, timeout=request_timeout) as response:
                        status_code = int(
                            getattr(response, "status", None)
                            or response.getcode()
                        )
                        body = response.read(128)
                latency_ms = round((time.perf_counter() - started) * 1000, 2)
                if status_code == 204 and self._probe_response_body_ok(status_code, body):
                    return {
                        "url": probe_label,
                        "status": status_code,
                        "latency_ms": latency_ms,
                        "proxy": proxy_url,
                    }
                failures.append(f"{probe_label}: unexpected status {status_code}")
            except Exception as exc:
                failures.append(
                    f"{probe_label}: {exc.__class__.__name__}"
                )
        raise RuntimeError("; ".join(failures[:3]) or "mixed-port probe failed")

    def _probe_mihomo_mixed_port_once(
        self,
        *,
        timeout_seconds: float,
        excluded_destination: str = "",
        probe_priority: ProbePriority = ProbePriority.RUNTIME_MANUAL,
        recovery_ticket: _RuntimeRecoveryTicket | None = None,
        recovery_deadline_monotonic: float | None = None,
    ) -> dict[str, Any]:
        """Run one bounded neutral FINAL-EXIT probe for circuit confirmation."""

        total_budget = max(0.1, float(timeout_seconds))
        if recovery_deadline_monotonic is not None:
            total_budget = min(total_budget, self._runtime_recovery_remaining(recovery_deadline_monotonic))
            if total_budget < 0.1:
                raise _RuntimeProbeBudgetUnavailable("runtime FINAL-EXIT transaction budget exhausted")

        def probe(context: ProbeExecutionContext | None) -> dict[str, Any]:
            kwargs: dict[str, Any] = {
                "timeout_seconds": total_budget,
                "excluded_destination": excluded_destination,
            }
            if context is not None:
                kwargs["execution_context"] = context
            if isinstance(recovery_ticket, _RuntimeRecoveryTicket):
                kwargs["recovery_ticket"] = recovery_ticket
            if recovery_deadline_monotonic is not None:
                kwargs["recovery_deadline_monotonic"] = (
                    recovery_deadline_monotonic
                )
            return self._probe_mihomo_mixed_port_once_leased(**kwargs)

        return self._run_brokered_runtime_probe(
            probe,
            priority=probe_priority,
            queue_timeout_seconds=min(1.5, total_budget),
            socket_start_timeout_seconds=min(0.5, total_budget),
            execution_deadline_monotonic=time.monotonic() + total_budget,
        )

    def _probe_mihomo_mixed_port_once_leased(
        self,
        *,
        timeout_seconds: float,
        excluded_destination: str = "",
        probe_url: str = "",
        execution_context: ProbeExecutionContext | None = None,
        recovery_ticket: _RuntimeRecoveryTicket | None = None,
        recovery_deadline_monotonic: float | None = None,
        on_tunnel_established: Callable[[], None] | None = None,
    ) -> dict[str, Any]:
        client_config = self._client_config()
        proxy_config = self._system_proxy_config()
        host = str(proxy_config.get("host", "127.0.0.1") or "127.0.0.1")
        if host in {"0.0.0.0", "::"}:
            host = "127.0.0.1"
        proxy_url = f"http://{host}:{self._client_mixed_port(client_config)}"
        # The bounded transport below owns CONNECT/TLS itself. Constructing an
        # unused urllib HTTPS handler first loads the Windows trust store and
        # can exhaust the socket-start lease before any socket is attempted.
        opener = None
        if not (
            execution_context is not None
            and execution_context.execution_deadline_monotonic is not None
            and build_opener is _stdlib_build_opener
        ):
            opener = build_opener(
                ProxyHandler({"http": proxy_url, "https": proxy_url}),
                _RejectAuthoritativeProbeRedirects(),
            )
        if not probe_url:
            excluded = str(excluded_destination or "").strip().lower()
            urls = [
                url
                for url in self._default_probe_urls()
                if str(urlsplit(url).hostname or "").strip().lower() != excluded
            ]
            probe_url = (urls or self._default_probe_urls())[0]
        probe_url = str(probe_url)
        probe_label = self._safe_probe_endpoint_label(probe_url)
        started = time.perf_counter()
        self._register_runtime_internal_probe(
            probe_url,
            timeout_seconds=timeout_seconds,
        )
        request = Request(
            probe_url,
            headers={"User-Agent": "Tesseract/1.0"},
            method="GET",
        )
        abort_owner = self._prepare_abortable_probe(
            execution_context,
            recovery_ticket=recovery_ticket,
            deadline_monotonic=recovery_deadline_monotonic,
        )
        if (
            execution_context is not None
            and execution_context.execution_deadline_monotonic is not None
            and (opener is None or isinstance(opener, OpenerDirector))
        ):
            # Let the socket's own bounded timeout fire before the broker's
            # absolute deadline.  On Windows, closing a socket from the
            # broker thread at the exact deadline does not guarantee that a
            # TLS syscall exits inside the broker's 100 ms poison audit.  A
            # normal slow/dead public leaf could therefore poison both global
            # probe slots and make every later healthy fallback impossible.
            # Reserve cleanup time while keeping the caller's wall-clock
            # budget authoritative.
            remaining = max(
                0.0,
                float(execution_context.execution_deadline_monotonic)
                - time.monotonic(),
            )
            cleanup_grace = min(
                0.25,
                max(0.12, remaining * 0.08),
            )
            transport_timeout = max(
                0.05,
                min(
                    float(timeout_seconds),
                    remaining - cleanup_grace,
                ),
            )
            tunnel_kwargs: dict[str, Any] = (
                {"on_tunnel_established": on_tunnel_established}
                if on_tunnel_established is not None
                and self._abortable_https_204_via_http_proxy
                is DesktopRuntime._abortable_https_204_via_http_proxy
                else {}
            )
            status_code, body = self._abortable_https_204_via_http_proxy(
                proxy_host=host,
                proxy_port=self._client_mixed_port(client_config),
                probe_url=probe_url,
                timeout_seconds=transport_timeout,
                abort_owner=abort_owner,
                **tunnel_kwargs,
            )
        else:
            with opener.open(
                request,
                timeout=max(0.1, float(timeout_seconds)),
            ) as response:
                status_code = int(
                    getattr(response, "status", None) or response.getcode()
                )
                body = response.read(128)
        if status_code != 204 or not self._probe_response_body_ok(
            status_code,
            body,
        ):
            raise RuntimeError(f"{probe_label}: unexpected status {status_code}")
        return {
            "url": probe_label,
            "status": status_code,
            "latency_ms": round(
                (time.perf_counter() - started) * 1000.0,
                2,
            ),
            "proxy": proxy_url,
        }

    def _verify_runtime_final_exit(
        self,
        *,
        expected_worker_token: tuple[int, ...] | None = None,
        expected_snapshot: CoreLoadedRouteSnapshot | None = None,
        timeout_seconds: float = 3.0,
        require_controller_ready: bool = True,
        required_successes: int = 1,
        parallel_probes: bool = False,
        total_timeout_cap_seconds: float = 3.0,
        per_probe_timeout_cap_seconds: float = 1.5,
        recovery_ticket: _RuntimeRecoveryTicket | None = None,
        recovery_deadline_monotonic: float | None = None,
    ) -> dict[str, Any]:
        """Bounded verifier for an already-running FINAL-EXIT.

        Cold-start qualification deliberately keeps its larger budget. Runtime
        reload/recovery verification hedges two neutral destinations and never
        waits for an identity endpoint or the rest of a Tier3 batch.
        """

        deadline = time.monotonic() + max(
            0.2,
            min(
                max(0.2, float(total_timeout_cap_seconds)),
                float(timeout_seconds),
            ),
        )
        if recovery_deadline_monotonic is not None:
            remaining = self._runtime_recovery_remaining(recovery_deadline_monotonic)
            if remaining <= 0.0:
                raise TimeoutError("runtime FINAL-EXIT transaction deadline expired")
            deadline = min(deadline, time.monotonic() + remaining)
        if require_controller_ready:
            ready_budget = max(0.0, min(0.35, deadline - time.monotonic()))
            if ready_budget <= 0.0:
                raise TimeoutError("runtime FINAL-EXIT readiness deadline expired")
            try:
                self._wait_for_mihomo_route_ready(
                    timeout=ready_budget,
                    runtime_config_path=self._current_mihomo_runtime_config_path(),
                    poll_interval=0.02,
                )
            except TypeError:
                # Keep compatibility with narrow test doubles and older
                # embedded runtime shims while production uses fast polling.
                try:
                    self._wait_for_mihomo_route_ready(
                        timeout=ready_budget,
                        runtime_config_path=self._current_mihomo_runtime_config_path(),
                    )
                except Exception as exc:
                    raise RuntimeControllerReadbackError(
                        "runtime FINAL-EXIT route readiness is unavailable"
                    ) from exc
            except Exception as exc:
                raise RuntimeControllerReadbackError(
                    "runtime FINAL-EXIT route readiness is unavailable"
                ) from exc
        if (
            expected_worker_token is not None
            and not self._runtime_worker_token_is_current(expected_worker_token)
        ):
            raise RuntimeControllerReadbackError(
                "runtime FINAL-EXIT verifier was superseded"
            )
        if expected_snapshot is not None:
            current = self._runtime_egress_coordinator.current_route_snapshot()
            if (
                current is None
                or current.snapshot_key != expected_snapshot.snapshot_key
            ):
                raise RuntimeControllerReadbackError(
                    "runtime FINAL-EXIT route changed before verification"
                )

        urls = list(self._default_probe_urls())
        if not urls:
            raise RuntimeControllerReadbackError(
                "runtime FINAL-EXIT has no neutral probe URL"
            )
        first_host = str(urlsplit(urls[0]).hostname or "").strip().lower()
        exclusions = [""]
        if len(urls) > 1 and first_host:
            exclusions.append(first_host)
        failures: list[str] = []
        successes: list[dict[str, Any]] = []
        attempted = 0
        required = max(1, int(required_successes))
        if parallel_probes and required > 1:
            # Startup admission has one six-second wall-clock lease.  The two
            # independent 204 contracts must therefore run concurrently: a
            # healthy high-latency leaf must not consume the lease twice just
            # because the proofs are independent.  Runtime incident handling
            # keeps the default sequential 1.5-second behavior below.
            selected_exclusions = exclusions[:required]
            observed: list[dict[str, Any] | None] = [
                None
            ] * len(selected_exclusions)
            observed_failures: list[str] = [""] * len(selected_exclusions)
            finished = [threading.Event() for _item in selected_exclusions]

            def probe(index: int, excluded_destination: str) -> None:
                try:
                    remaining = max(0.0, deadline - time.monotonic())
                    if remaining <= 0.0:
                        observed_failures[index] = (
                            "runtime FINAL-EXIT probe deadline expired"
                        )
                        return
                    value = self._probe_mihomo_mixed_port_once(
                        timeout_seconds=max(
                            0.1,
                            min(
                                max(
                                    0.1,
                                    float(per_probe_timeout_cap_seconds),
                                ),
                                remaining,
                            ),
                        ),
                        excluded_destination=excluded_destination,
                        recovery_ticket=recovery_ticket,
                        recovery_deadline_monotonic=(
                            recovery_deadline_monotonic
                        ),
                    )
                    observed[index] = (
                        dict(value)
                        if isinstance(value, dict)
                        else {"result": value}
                    )
                except Exception as exc:
                    observed_failures[index] = str(exc)
                finally:
                    finished[index].set()

            threads = [
                threading.Thread(
                    target=probe,
                    args=(index, excluded_destination),
                    name="initial-final-exit-204",
                    daemon=True,
                )
                for index, excluded_destination in enumerate(
                    selected_exclusions
                )
            ]
            for thread in threads:
                thread.start()
            for event in finished:
                remaining = max(0.0, deadline - time.monotonic())
                if remaining <= 0.0 or not event.wait(remaining):
                    break
            if (
                expected_worker_token is not None
                and not self._runtime_worker_token_is_current(
                    expected_worker_token
                )
            ):
                raise RuntimeControllerReadbackError(
                    "runtime FINAL-EXIT verifier was superseded"
                )
            if expected_snapshot is not None:
                current = self._runtime_egress_coordinator.current_route_snapshot()
                if (
                    current is None
                    or current.snapshot_key != expected_snapshot.snapshot_key
                ):
                    raise RuntimeControllerReadbackError(
                        "runtime FINAL-EXIT route changed during verification"
                    )
            successes = [
                dict(value)
                for value in observed
                if isinstance(value, dict)
            ]
            if len(successes) >= required:
                result = dict(successes[-1])
                result["runtime_verifier"] = True
                result["hedged_destinations"] = len(exclusions)
                result["attempted_destinations"] = len(
                    selected_exclusions
                )
                result["successful_destinations"] = len(successes)
                result["probe_results"] = successes
                return result
            raise RuntimeError(
                "; ".join(
                    value for value in observed_failures if value
                )[:512]
                or (
                    "runtime FINAL-EXIT did not complete the required "
                    f"independent 204 probes ({len(successes)}/{required})"
                )
            )
        # Do not leave a losing hedge running after the caller has committed a
        # route lease.  That orphan used to retain one global socket slot and
        # race the incident's follow-up confirmation.  A selected replacement
        # already has exact member evidence, so one full-chain 204 is enough;
        # the second destination is a sequential fallback only when the first
        # request fails.
        for excluded_destination in exclusions:
            remaining = max(0.0, deadline - time.monotonic())
            if remaining <= 0.0:
                break
            attempted += 1
            try:
                value = self._probe_mihomo_mixed_port_once(
                    timeout_seconds=max(0.1, min(1.5, remaining)),
                    excluded_destination=excluded_destination,
                    recovery_ticket=recovery_ticket,
                    recovery_deadline_monotonic=(
                        recovery_deadline_monotonic
                    ),
                )
            except _RuntimeProbeBudgetUnavailable:
                # No neutral socket started. Scheduling saturation is not a
                # transport verdict and must not rotate/fail-close a route.
                raise
            except Exception as exc:
                failures.append(str(exc))
                continue
            if (
                expected_worker_token is not None
                and not self._runtime_worker_token_is_current(
                    expected_worker_token
                )
            ):
                raise RuntimeControllerReadbackError(
                    "runtime FINAL-EXIT verifier was superseded"
                )
            if expected_snapshot is not None:
                current = self._runtime_egress_coordinator.current_route_snapshot()
                if (
                    current is None
                    or current.snapshot_key != expected_snapshot.snapshot_key
                ):
                    raise RuntimeControllerReadbackError(
                        "runtime FINAL-EXIT route changed during verification"
                    )
            result = dict(value) if isinstance(value, dict) else {"result": value}
            result["runtime_verifier"] = True
            result["hedged_destinations"] = len(exclusions)
            result["attempted_destinations"] = attempted
            successes.append(result)
            if len(successes) >= required:
                result["successful_destinations"] = len(successes)
                if len(successes) > 1:
                    result["probe_results"] = successes
                return result
        raise RuntimeError(
            "; ".join(failures[:2])
            or (
                "runtime FINAL-EXIT did not complete the required independent "
                f"204 probes ({len(successes)}/{required})"
            )
        )

    def _tier3_proxy_name_pairs(self) -> list[tuple[str, Any]]:
        manager = self.manager
        if not manager:
            return []
        limit = self._mihomo_tier3_export_limit()
        # The names the Core loaded: the renderer's own naming
        # (subscription._render_clash_config -> build_full_clash_config) over
        # one frozen export view, i.e. the reserved seed, Tier1 and Tier2
        # first, the export limit and the view's Tier3 naming (base·digest
        # on the verified lane).  An empty seed probes names the Core lacks,
        # or another proxy that has the name (DIRECT answers a delay test).
        try:
            view = self._manager_for_mihomo_runtime_config()
        except RuntimeError:
            return []  # the manager stopped meanwhile
        quiet = logging.Logger("tier3-proxy-name-pairs")  # the render logs skips
        quiet.addHandler(logging.NullHandler())
        seen_names: set[str] = set(MIHOMO_RESERVED_PROXY_NAMES)
        for tier_id in ("tier1", "tier2"):
            build_clash_proxy_list(
                view.get_nodes_for_subscription(tier_id, limit=None),
                logger=quiet,
                seen_names=seen_names,
            )
        rendered: list[tuple[Any, dict[str, Any]]] = []
        build_clash_proxy_list(
            view.get_nodes_for_subscription("tier3", limit=limit),
            logger=self.logger,
            seen_names=seen_names,
            rendered_pairs=rendered,
            stable_names=bool(getattr(view, "stable_tier3_names", False)),
        )
        return [(str(proxy["name"]), node) for node, proxy in rendered if proxy.get("name")]

    def _probe_urls_for_node(self, node: Any) -> list[str]:
        return tier3_probe_urls_for_node(node, self._default_probe_urls())

    def _startup_core_probe_limit(self) -> int:
        return startup_core_probe_limit(self.config)

    def _startup_core_probe_concurrency(self) -> int:
        return startup_core_probe_concurrency(self.config)

    def _configured_tier3_export_limit(self) -> int:
        return configured_tier3_export_limit(self.config)

    def _mihomo_tier3_export_limit(self) -> int:
        return tier3_runtime_export_limit(
            configured_limit=self._configured_tier3_export_limit(),
            startup_probe_limit=self._startup_core_probe_limit(),
            tier3_required_for_start=self._tier3_required_for_start,
            primary_configured=self._primary_layers_configured(),
            uses_tcp_prelaunch_validation=self._tier3_export_uses_tcp_prelaunch_validation(),
        )

    def _node_identity_text(self, node: Any) -> str:
        manager = self.manager
        identity_getter = getattr(manager, "_node_identity", None)
        if callable(identity_getter):
            return str(identity_getter(node))
        return "|".join(map(str, getattr(node, "dedupe_key", ())))

    def _set_tier3_core_export_override(self, nodes: list[Any]) -> None:
        with self._tier3_core_export_override_lock:
            self._tier3_core_export_override_nodes = self._clone_runtime_nodes(list(nodes))

    def _clear_tier3_core_export_override(self) -> None:
        with self._tier3_core_export_override_lock:
            self._tier3_core_export_override_nodes = []

    def _tier3_core_export_override_snapshot(self) -> list[Any]:
        with self._tier3_core_export_override_lock:
            return self._clone_runtime_nodes(self._tier3_core_export_override_nodes)

    def _runtime_audit_export_exclusion_clear_reason(self, identity: str, entry: dict[str, Any], *, now: float) -> str:
        try:
            expires_at = float(entry.get("expires_at_monotonic", 0.0) or 0.0)
        except (TypeError, ValueError):
            expires_at = 0.0
        if (
            expires_at
            and expires_at <= now
            and not bool(entry.get("require_health_recheck"))
        ):
            return "ttl_expired"
        node = self._runtime_node_for_identity(identity)
        if node is None:
            return "node_missing"
        try:
            excluded_at = float(entry.get("excluded_at_monotonic", 0.0) or 0.0)
        except (TypeError, ValueError):
            excluded_at = 0.0
        if now - excluded_at < RUNTIME_AUDIT_EXPORT_EXCLUSION_HEALTH_RELEASE_GRACE_SECONDS:
            return ""
        if entry.get("release_on_healthy", True) and getattr(node, "status", None) in {
            NodeStatus.ALIVE,
            NodeStatus.SLOW,
        }:
            checked_at = str(getattr(node, "last_checked_at", None) or "")
            excluded_checked_at = str(entry.get("node_last_checked_at") or "")
            if checked_at and checked_at != excluded_checked_at:
                return "node_recovered"
        return ""

    def _runtime_node_for_identity(self, identity: str) -> Any | None:
        manager = self.manager
        if not manager:
            return None
        runtime_nodes = getattr(manager, "runtime_nodes", {})
        for nodes in getattr(runtime_nodes, "values", lambda: [])():
            for node in list(nodes or []):
                if self._node_identity_text(node) == identity:
                    return node
        return None

    def _prune_runtime_audit_export_overlay(self, *, now: float | None = None) -> dict[str, str]:
        current = time.monotonic() if now is None else float(now)
        cleared: dict[str, str] = {}
        with self._runtime_audit_export_overlay_lock:
            for identity, entry in list(self._runtime_audit_export_excluded_identities.items()):
                reason = self._runtime_audit_export_exclusion_clear_reason(identity, entry, now=current)
                if not reason:
                    continue
                self._runtime_audit_export_excluded_identities.pop(identity, None)
                cleared[identity] = reason
        return cleared

    def _runtime_audit_export_excluded_snapshot(self) -> set[str]:
        self._prune_runtime_audit_export_overlay()
        with self._runtime_audit_export_overlay_lock:
            return set(self._runtime_audit_export_excluded_identities)

    def _exclude_runtime_audit_export_identity(
        self,
        identity: str,
        *,
        ttl_seconds: float | None = None,
        reason: str = "runtime_audit",
        release_on_healthy: bool = True,
        require_health_recheck: bool = False,
    ) -> None:
        identity = str(identity or "").strip()
        if not identity:
            return
        now = time.monotonic()
        ttl = RUNTIME_AUDIT_EXPORT_EXCLUSION_TTL_SECONDS if ttl_seconds is None else float(ttl_seconds)
        node = self._runtime_node_for_identity(identity)
        with self._runtime_audit_export_overlay_lock:
            self._runtime_audit_export_excluded_identities[identity] = {
                "excluded_at_monotonic": now,
                "expires_at_monotonic": now + max(1.0, ttl),
                "reason": str(reason or "runtime_audit"),
                "release_on_healthy": bool(release_on_healthy),
                "require_health_recheck": bool(require_health_recheck),
                "node_last_checked_at": str(
                    getattr(node, "last_checked_at", None) or ""
                ),
            }

    def _record_runtime_audit_export_failure(
        self,
        identity: str,
        *,
        definitive: bool,
        reason: str,
        ttl_seconds: float | None = None,
    ) -> bool:
        identity = str(identity or "").strip()
        if not identity or not definitive:
            return False
        now = time.monotonic()
        with self._runtime_audit_export_overlay_lock:
            previous = self._runtime_audit_deterministic_failures.get(identity, {})
            if int(previous.get("config_generation", -1)) == int(
                self._tier3_runtime_config_generation
            ):
                count = int(previous.get("count", 0) or 0) + 1
            else:
                count = 1
            self._runtime_audit_deterministic_failures[identity] = {
                "config_generation": int(self._tier3_runtime_config_generation),
                "count": count,
                "last_failure_monotonic": now,
                "reason": str(reason or "runtime_audit"),
            }
        if count < 2:
            return False
        quarantine_ttl = RUNTIME_AUDIT_EXPORT_EXCLUSION_TTL_SECONDS
        if ttl_seconds is not None:
            quarantine_ttl = min(
                quarantine_ttl,
                max(1.0, float(ttl_seconds)),
            )
        self._exclude_runtime_audit_export_identity(
            identity,
            ttl_seconds=quarantine_ttl,
            reason=reason,
            release_on_healthy=True,
        )
        return True

    def _clear_runtime_audit_export_identity(self, identity: str) -> bool:
        identity = str(identity or "").strip()
        if not identity:
            return False
        with self._runtime_audit_export_overlay_lock:
            changed = bool(
                identity in self._runtime_audit_export_excluded_identities
                or identity in self._runtime_audit_deterministic_failures
            )
            self._runtime_audit_export_excluded_identities.pop(identity, None)
            self._runtime_audit_deterministic_failures.pop(identity, None)
        return changed

    def _clear_runtime_audit_export_overlay(self) -> None:
        with self._runtime_audit_export_overlay_lock:
            self._runtime_audit_export_excluded_identities.clear()
            self._runtime_audit_deterministic_failures.clear()

    def _tier3_nodes_for_core_export(self, limit: int | None = None) -> list[Any]:
        manager = self.manager
        if not manager:
            return []
        durable_nodes = list(getattr(manager, "runtime_nodes", {}).get("tier3", []))
        is_auto_pool = getattr(manager, "_is_tier3_auto_pool_node", None)
        canonical_nodes = [
            node
            for node in durable_nodes
            if not callable(is_auto_pool) or bool(is_auto_pool(node))
        ]
        # Admission is the membership authority. A transient health result may
        # change runtime qualification, but it must not remove a durable Tier3B
        # member and trigger a Core reload. Deterministic runtime exclusions are
        # applied by the generation-scoped overlay below.
        # The manager's public view intentionally re-ranks nodes by current
        # health/latency. Mihomo's fallback membership needs a different
        # contract: already-loaded identities keep their order, while new
        # admissions append in the durable pool order. Otherwise metadata or
        # latency updates can silently change the selected leaf on every hot
        # reload even though no rendered proxy changed.
        previous_order = {
            self._node_identity_text(node): index
            for index, node in enumerate(self._last_synced_tier3_nodes)
        }
        durable_order = {
            self._node_identity_text(node): index
            for index, node in enumerate(
                durable_nodes
            )
        }
        durable_admission_order = {
            self._node_identity_text(node): max(
                0,
                int(
                    getattr(node, "extra", {}).get(
                        "tier3_admission_pool_revision",
                        0,
                    )
                    or 0
                ),
            )
            for node in canonical_nodes
        }
        current_order = {
            self._node_identity_text(node): index
            for index, node in enumerate(canonical_nodes)
        }
        canonical_nodes.sort(
            key=lambda node: (
                0
                if self._node_identity_text(node) in previous_order
                else 1,
                previous_order.get(
                    self._node_identity_text(node),
                    (
                        durable_admission_order.get(
                            self._node_identity_text(node),
                            0,
                        )
                        or durable_order.get(
                            self._node_identity_text(node),
                            current_order.get(self._node_identity_text(node), 0),
                        )
                    ),
                ),
            )
        )
        override_nodes = self._tier3_core_export_override_snapshot()
        if override_nodes:
            canonical_by_identity = {
                self._node_identity_text(node): node
                for node in canonical_nodes
            }
            ordered: list[Any] = []
            seen: set[str] = set()
            for override_node in override_nodes:
                identity = self._node_identity_text(override_node)
                current = canonical_by_identity.get(identity)
                if current is None or identity in seen:
                    continue
                ordered.append(current)
                seen.add(identity)
            # Legacy repair may provide a preferred order, but it has no
            # authority to shrink durable membership. Append every omitted
            # admitted member in its stable admission order.
            ordered.extend(
                node
                for node in canonical_nodes
                if self._node_identity_text(node) not in seen
            )
            canonical_nodes = ordered
        # Runtime quarantine changes selection/health eligibility, not durable
        # Core membership.  Keeping the exact proxy definition loaded lets
        # existing connections drain naturally and makes later event-driven
        # promotion possible without an ApplyConfig reload.  Only the Manager
        # pool gateway (legal eviction) may remove a Tier3B definition here.
        return canonical_nodes[:limit] if limit else canonical_nodes

    def _tier3_core_membership_snapshot(self) -> Tier3CoreMembershipSnapshot:
        manager = self.manager
        nodes = self._tier3_nodes_for_core_export(self._mihomo_tier3_export_limit())
        return Tier3CoreMembershipSnapshot(
            pool_revision=max(
                0,
                int(getattr(manager, "tier3_pool_revision", 0) or 0)
                if manager is not None
                else 0,
            ),
            identities=tuple(self._node_identity_text(node) for node in nodes),
            proxy_signatures=tuple(tier3_export_signature(nodes)),
        )

    def _manager_for_mihomo_runtime_config(self) -> Any:
        manager = self.manager
        if not manager:
            raise RuntimeError("manager service is not running")
        excluded = self._runtime_audit_export_excluded_snapshot()
        with self._runtime_failure_monitor_lock:
            failback_holds = set(self._runtime_failback_export_holds)
        return _Tier3CoreExportManagerView(
            manager,
            self._tier3_nodes_for_core_export,
            excluded_identities=excluded,
            identity_fn=self._node_identity_text,
            excluded_leaf_keys=failback_holds,
            pool_kind_fn=self._runtime_pool_kind,
            stable_tier3_names=self._tier3_verified_provider_writes_enabled(),
        ).freeze_nodes()

    def _probe_tier3_proxy_delay_candidate(
        self,
        proxy_name: str,
        node: Any,
        timeout_ms: int,
    ) -> tuple[bool, float, Any, str, str, list[str]]:
        failures: list[str] = []
        for probe_url in self._probe_urls_for_node(node):
            try:
                # `test_proxy_delay` delegates to the one brokered URLTest
                # implementation; this helper must not acquire a second slot.
                # Keeping the public seam also lets isolated Core adapters
                # supply an equivalent one-socket probe without bypassing the
                # inventory transaction.
                result = self.test_proxy_delay(
                    proxy_name,
                    url=probe_url,
                    timeout_ms=timeout_ms,
                )
                delay = tier3_core_delay_from_probe_result(result)
                return True, delay, node, proxy_name, probe_url, failures
            except _RuntimeProbeBudgetUnavailable:
                # No URLTest socket started, so this is neither a failed node
                # nor a completed qualification observation.
                raise
            except Exception as exc:
                failures.append(
                    "proxy_hash=hmac:"
                    f"{runtime_scoped_hmac(proxy_name, namespace='proxy-name')} "
                    "probe_hash=hmac:"
                    f"{runtime_scoped_hmac(probe_url, namespace='probe-endpoint')}: "
                    f"{redact_diagnostic_text(exc)}"
                )
        return False, 0.0, node, proxy_name, "", failures

    def _build_tier3_core_repair_plan(
        self,
        *,
        prune_to_successful: bool = False,
        target_alive: int | None = None,
        minimum_alive: int | None = None,
    ) -> _Tier3CoreRepairPlan | None:
        manager = self.manager
        if not manager:
            return None
        pairs = self._tier3_proxy_name_pairs()[: self._startup_core_probe_limit()]
        if not pairs:
            return None
        timeout_ms = int(self._startup_probe_timeout_seconds() * 1000)
        slow_threshold = slow_threshold_ms_from_testing(self._testing_block())
        repair_targets = tier3_core_repair_targets(
            prune_to_successful=prune_to_successful,
            target_alive=target_alive,
            minimum_alive=minimum_alive,
            default_target_alive=(
                self._tier3_startup_target_alive(manager)
                if prune_to_successful and target_alive is None
                else 1
            ),
        )
        target_verified = repair_targets.target_verified
        minimum_verified = repair_targets.minimum_verified
        probe_run = run_tier3_core_probe(
            pairs,
            timeout_ms=timeout_ms,
            # The process-wide RuntimeProbeBroker owns the real ceiling.  Keep
            # the executor at that same limit so queued qualification futures
            # cannot occupy threads and expire while recovery owns the slots.
            configured_concurrency=min(
                2,
                self._startup_core_probe_concurrency(),
            ),
            # A repair plan owns the complete Core-loaded inventory/report,
            # not merely the minimum number needed to open capture.  Keep the
            # process-wide socket ceiling at two, but roll that window across
            # every exported candidate.  Stopping after the first successful
            # batch made a healthy 16-member Manager pool look like a
            # two-member Core pool and could permanently hide later fallbacks.
            prune_to_successful=False,
            target_verified=target_verified,
            probe_candidate=self._probe_tier3_proxy_delay_candidate,
        )
        successful = probe_run.successful_results
        if probe_run.indeterminate_proxy_names:
            # A repair plan is an atomic inventory observation.  Even one
            # candidate that never opened a socket makes a successful-only
            # export incomplete and therefore unsafe to commit.
            raise _RuntimeProbeBudgetUnavailable(
                "Bastion Layer qualification is waiting for probe capacity"
            )
        failures = probe_run.failures
        tested_proxy_names = probe_run.tested_proxy_names
        concurrency = probe_run.concurrency
        insufficient_success = prune_to_successful and len(successful) < minimum_verified
        if insufficient_success:
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Bastion Layer live core repair found only %s/%s required working exported node(s)",
                len(successful),
                minimum_verified,
            )
        elif prune_to_successful and len(successful) < target_verified:
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Bastion Layer live core repair found only %s/%s desired working exported node(s); continuing because minimum is %s",
                len(successful),
                target_verified,
                minimum_verified,
            )

        applied = None
        evicted_nodes: list[Any] = []
        failed_tested_identities: set[str] = set()
        with manager.lock:
            current_nodes = self._clone_runtime_nodes(list(manager.runtime_nodes.get("tier3", [])))
            successful_identities = {self._node_identity_text(node) for _delay, node, _name, _url in successful}
            tested_nodes = [
                node
                for proxy_name, node in pairs
                if proxy_name in tested_proxy_names
            ]
            failed_tested_identities = {
                self._node_identity_text(node)
                for node in tested_nodes
                if self._node_identity_text(node) not in successful_identities
            }
            failure_threshold = 3
            threshold_getter = getattr(manager, "_tier3_pool_eviction_failure_threshold", None)
            if callable(threshold_getter):
                try:
                    failure_threshold = max(1, int(threshold_getter()))
                except (TypeError, ValueError):
                    failure_threshold = 3
            applied = apply_tier3_core_repair_results(
                current_nodes,
                successful,
                prune_to_successful=False,
                slow_threshold_ms=slow_threshold,
                identity_fn=self._node_identity_text,
                now_iso_fn=utc_now_iso,
                failed_tested_identities=failed_tested_identities,
                retain_failed_until_threshold=False,
                failure_threshold=failure_threshold,
            )
            evicted_getter = getattr(manager, "_tier3_evicted_pool_nodes", None)
            if callable(evicted_getter):
                evicted_nodes = evicted_getter(
                    current_nodes,
                    list(applied.pool_nodes),
                    applied.observed_failed_nodes,
                )
        report = build_tier3_startup_core_repair_report(
            tested_count=len(tested_proxy_names),
            candidate_count=len(pairs),
            concurrency=concurrency,
            working_count=applied.working_count,
            current_node_count=applied.current_node_count,
            retained_node_count=applied.retained_node_count,
            prune_to_successful=prune_to_successful,
            target_verified_count=target_verified,
            minimum_verified_count=minimum_verified,
            selected=(
                "hmac:"
                + runtime_scoped_hmac(
                    applied.selected_proxy_name,
                    namespace="proxy-name",
                )
                if applied.selected_proxy_name
                else ""
            ),
            delay_ms=applied.selected_delay_ms,
            failed_tested_count=applied.failed_tested_count,
            retained_failed_count=applied.retained_failed_count,
            evicted_failed_count=applied.evicted_failed_count,
        )
        report["pruned_count"] = 0
        report["export_pruned_count"] = 0
        report["preferred_export_order_count"] = max(
            0,
            int(applied.working_count or 0),
        )
        report["durable_membership_preserved"] = True
        report["pool_mutation"] = "none"
        report["targeted_recheck_queued_count"] = len(failed_tested_identities)
        core_audit = {
            "tested_count": len(tested_proxy_names),
            "core_verified_count": applied.working_count,
            "core_failed_count": applied.failed_tested_count,
            "retained_failed_count": applied.retained_failed_count,
            "evicted_failed_count": applied.evicted_failed_count,
            "targeted_recheck_queued_count": len(failed_tested_identities),
            "pool_mutation": "none",
            "probe_url_hashes": [
                "hmac:"
                + runtime_scoped_hmac(url, namespace="probe-endpoint")
                for url in self._default_probe_urls()
            ],
        }
        export_nodes = tuple(
            node
            for node in applied.nodes
            if self._node_identity_text(node) in successful_identities
        )
        return _Tier3CoreRepairPlan(
            applied=applied,
            export_nodes=export_nodes,
            report=report,
            core_audit=core_audit,
            evicted_nodes=evicted_nodes,
            failed_identities=tuple(sorted(failed_tested_identities)),
            successful_count=len(successful),
            failure_summary="; ".join(failures[:3]) or "all probes failed",
            insufficient_success=insufficient_success,
        )

    def _record_tier3_core_repair_plan_report(self, plan: _Tier3CoreRepairPlan) -> None:
        manager = self.manager
        if not manager:
            return
        with manager.lock:
            report = ensure_tier3_collection_report(manager)
            report["startup_core_repair"] = dict(plan.report)
            report["core_audit"] = dict(plan.core_audit)
            if count_healthy_nodes(manager.runtime_nodes.get("tier3", [])) < self._tier3_background_target_alive(manager):
                report["background_expansion_due"] = True
                manager.last_collect_tier3 = 0.0

    def _commit_tier3_core_repair_plan(
        self,
        plan: _Tier3CoreRepairPlan,
        *,
        save_snapshot: bool = True,
    ) -> None:
        manager = self.manager
        if not manager:
            return
        with manager.lock:
            report = ensure_tier3_collection_report(manager)
            report["startup_core_repair"] = dict(plan.report)
            report["core_audit"] = dict(plan.core_audit)
            if count_healthy_nodes(manager.runtime_nodes.get("tier3", [])) < self._tier3_background_target_alive(manager):
                report["background_expansion_due"] = True
                manager.last_collect_tier3 = 0.0

    def _queue_tier3_core_repair_targeted_rechecks(self, plan: _Tier3CoreRepairPlan) -> None:
        manager = self.manager
        if not manager:
            return
        enqueue = getattr(manager, "enqueue_tier3_targeted_recheck", None)
        for identity in plan.failed_identities:
            if callable(enqueue):
                try:
                    enqueue(
                        identity,
                        reason="core repair readiness probe failed",
                        source="core_repair",
                    )
                except Exception as exc:
                    log_raw_diagnostic(
                        self.logger,
                        "warning",
                        "Failed to enqueue Bastion Layer targeted recheck for "
                        "identity_hash=%s: %s",
                        runtime_identity_hash(identity),
                        redact_diagnostic_text(exc).replace(
                            str(identity),
                            runtime_identity_hash(identity),
                        ),
                    )

    def _prepare_tier3_core_repair_override(
        self,
        *,
        prune_to_successful: bool = False,
        target_alive: int | None = None,
        minimum_alive: int | None = None,
    ) -> _Tier3CoreRepairPlan | None:
        plan = self._build_tier3_core_repair_plan(
            prune_to_successful=prune_to_successful,
            target_alive=target_alive,
            minimum_alive=minimum_alive,
        )
        if plan is None:
            return None
        self._record_tier3_core_repair_plan_report(plan)
        if plan.successful_count <= 0:
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Bastion Layer live core repair found no working exported node: %s",
                plan.failure_summary,
            )
            return None
        self._set_tier3_core_export_override(list(plan.export_nodes))
        self._queue_tier3_core_repair_targeted_rechecks(plan)
        self.logger.info(
            "Bastion Layer live core repair selected proxy_hash=hmac:%s "
            "(%sms, failed=%s queued_recheck=%s)",
            runtime_scoped_hmac(
                plan.applied.selected_proxy_name,
                namespace="proxy-name",
            ),
            round(plan.applied.selected_delay_ms, 2),
            plan.applied.failed_tested_count,
            len(plan.failed_identities),
        )
        if plan.insufficient_success:
            self._clear_tier3_core_export_override()
            return None
        return plan

    def _repair_tier3_export_order_from_core_delays(
        self,
        *,
        prune_to_successful: bool = False,
        target_alive: int | None = None,
        minimum_alive: int | None = None,
        save_snapshot: bool = True,
        commit: bool = True,
    ) -> bool:
        plan = self._prepare_tier3_core_repair_override(
            prune_to_successful=prune_to_successful,
            target_alive=target_alive,
            minimum_alive=minimum_alive,
        )
        if plan is None:
            return False
        if commit:
            self._commit_tier3_core_repair_plan(plan, save_snapshot=save_snapshot)
        return True

    def _save_tier3_verified_snapshot(self) -> None:
        manager = self.manager
        if not manager:
            return
        snapshot_saver = getattr(manager, "_save_tier3_snapshot", None)
        if not callable(snapshot_saver):
            return
        with manager.lock:
            nodes = list(manager.runtime_nodes.get("tier3", []))
        snapshot_saver(
            nodes,
            getattr(manager, "tier3_source_count", 0),
            collected_at=getattr(manager, "tier3_last_collection_at", None),
        )

    def _warm_tier3_group_after_core_start(self, *, strict: bool = False) -> bool:
        if not self._tier3_is_primary_export():
            return False
        route_error: str | None = None
        try:
            result = self._probe_mihomo_mixed_port()
            self.logger.info(
                "Verified Bastion Layer route through mihomo mixed-port (%s, %sms)",
                result.get("url"),
                result.get("latency_ms"),
            )
            return True
        except Exception as exc:
            if self.stop_event.is_set():
                raise RuntimeStartCancelled(
                    "runtime stop requested during Bastion route verification"
                ) from exc
            route_error = str(exc)
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Bastion Layer mixed-port verification failed: %s",
                exc,
            )

        controller = self._mihomo_controller_config()
        group_errors: list[str] = []
        if (
            self._node_judgement_policy().group_round_native_timeout
            and mihomo_controller_enabled(controller, default=False)
        ):
            # P0-2: the neutral-URL warm never reached the contract key the
            # fallback consults (M6).  Run the owning group's contract round.
            contract_error = self._warm_tier3_group_contract_round()
            if contract_error is None:
                return True
            group_errors.append(contract_error)
        elif mihomo_controller_enabled(controller, default=False):
            timeout_ms = int(self._startup_probe_timeout_seconds() * 1000)
            for probe_url in self._default_probe_urls():
                if self.stop_event.is_set():
                    raise RuntimeStartCancelled(
                        "runtime stop requested during Bastion group warmup"
                    )
                try:
                    self.test_group_delay("TIER3-AUTO", url=probe_url, timeout_ms=timeout_ms)
                    self.logger.info("Pre-warmed Bastion Layer health check via Mihomo group delay")
                    return True
                except Exception as exc:
                    if self.stop_event.is_set():
                        raise RuntimeStartCancelled(
                            "runtime stop requested during Bastion group warmup"
                        ) from exc
                    group_errors.append(f"{probe_url}: {exc}")
                    log_raw_diagnostic(
                        self.logger,
                        "warning",
                        "Bastion Layer group-delay warmup failed for %s: %s",
                        probe_url,
                        exc,
                    )

        details = []
        if route_error:
            details.append(f"mixed-port probe failed ({route_error})")
        if group_errors:
            details.append("group-delay probe failed (" + "; ".join(group_errors[:2]) + ")")
        message = "Could not verify fallback after core launch"
        if details:
            message += ": " + "; ".join(details)
        if strict:
            raise RuntimeError(message)
        log_raw_diagnostic(self.logger, "warning", message)
        return False

    def _warm_tier3_group_contract_round(self) -> str | None:
        """One TIER3-AUTO round on its loaded contract (P0-2); None on success."""

        snapshot: CoreLoadedRouteSnapshot | None = None
        try:
            snapshot = self._refresh_runtime_route_snapshot(timeout_seconds=0.5)
        except Exception:
            snapshot = None
        if snapshot is None:
            try:
                snapshot, _payload = self._runtime_route_snapshot_state()
            except Exception:
                snapshot = None
        state = (
            snapshot.group_state("TIER3-AUTO")
            if isinstance(snapshot, CoreLoadedRouteSnapshot)
            else None
        )
        if state is None or not str(state.test_url or "").strip():
            # Never fall back to a neutral URL: it is not the key the
            # fallback group consults and writes only global liveness.
            return "TIER3-AUTO contract unavailable"
        probe_url, expected_status = self._runtime_group_probe_contract(
            snapshot,
            "TIER3-AUTO",
        )
        if self.stop_event.is_set():
            raise RuntimeStartCancelled(
                "runtime stop requested during Bastion group warmup"
            )
        try:
            self._run_native_group_round(
                "TIER3-AUTO",
                probe_url=probe_url,
                expected_status=expected_status,
                timeout_ms=self._runtime_group_native_timeout_ms("TIER3-AUTO"),
            )
        except Exception as exc:
            if self.stop_event.is_set():
                raise RuntimeStartCancelled(
                    "runtime stop requested during Bastion group warmup"
                ) from exc
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Bastion Layer contract round failed: %s",
                type(exc).__name__,
            )
            return f"contract round: {type(exc).__name__}"
        self.logger.info(
            "Pre-warmed Bastion Layer health check via the TIER3-AUTO contract round"
        )
        return None

    def _verify_tier3_final_exit_for_activation(
        self,
        *,
        preserve_prior_on_probe_failure: bool = False,
        binding_state: tuple[
            RuntimeRouteBinding,
            CoreLoadedRouteSnapshot,
            dict[str, Any],
        ] | None = None,
        known_probe_failure: Exception | None = None,
    ) -> dict[str, Any]:
        """Verify the formal route through mixed-port before capture."""
        qualification = self._refresh_tier3_runtime_qualification()
        manager = self.manager
        required = max(
            1,
            int(
                getattr(manager, "_tier3_min_alive_nodes", lambda: 1)()
                if manager is not None
                else 1
            ),
        )
        if qualification.qualified_count < required:
            self._set_tier3_runtime_final_exit_qualification(False)
            raise Tier3RuntimeQualificationError(
                "Bastion Layer runtime qualification is below the safety "
                f"floor ({qualification.qualified_count}/{required}; "
                f"exported={qualification.exported_count})"
            )
        with self._tier3_runtime_qualification_lock:
            prior_final_exit_ok = bool(self._tier3_runtime_final_exit_ok)
        probe_started = time.monotonic()
        try:
            if known_probe_failure is not None:
                raise known_probe_failure
            result = self._probe_mihomo_mixed_port()
        except _RuntimeProbeBudgetUnavailable:
            self._record_tier3_core_sync_ledger(
                "final_exit_probe",
                event="activation_probe_indeterminate",
                semantic_digest=qualification.config_digest,
                detail="probe_budget_unavailable",
            )
            # Preserve existing qualification/readiness: no probe socket was
            # opened, so there is no new route, node, or facility evidence.
            raise
        except Exception as exc:
            self._record_tier3_core_sync_ledger(
                "final_exit_probe",
                event="activation_probe",
                semantic_digest=qualification.config_digest,
                detail=f"failed:{type(exc).__name__}",
            )
            if not (
                preserve_prior_on_probe_failure
                and prior_final_exit_ok
            ):
                self._set_tier3_runtime_final_exit_qualification(False)
            # A cold/no-capture activation failure is real FINAL-EXIT
            # data-plane evidence.  Previously it was consumed only by the
            # 1/2/5-second standby retry loop, so every retry tested the same
            # selected leaf and an otherwise healthy loaded pool could become
            # permanently event-gated.  Feed the failure into the canonical
            # coordinator as well: it will bind the current Core-loaded leaf,
            # compare it with managed alternatives, and mutate the selector
            # only after differential proof. The activation owner waits on
            # that same incident: only a fully verified replacement may
            # consume this exception and continue; every other terminal state
            # remains a truthful hold/failure.
            try:
                failure_submitter = self._submit_current_route_probe_failure
                try:
                    submitter_parameters = inspect.signature(
                        failure_submitter
                    ).parameters.values()
                except (TypeError, ValueError):
                    submitter_parameters = ()
                submission_kwargs: dict[str, Any] = {
                    "source": "activation_final_exit",
                }
                if any(
                    parameter.kind is inspect.Parameter.VAR_KEYWORD
                    or parameter.name == "binding_state"
                    for parameter in submitter_parameters
                ):
                    submission_kwargs["binding_state"] = binding_state
                submission = failure_submitter(
                    "Bastion activation FINAL-EXIT 204 failed: "
                    f"{type(exc).__name__}",
                    **submission_kwargs,
                )
                if isinstance(submission, _RuntimeRecoveryTicket):
                    outcome = self._wait_runtime_recovery_outcome(submission)
                    if outcome is None:
                        raise _RuntimeProbeBudgetUnavailable(
                            "activation recovery has no authoritative terminal "
                            "outcome inside the incident deadline"
                        ) from exc
                    if outcome.status is not RuntimeRecoveryStatus.RECOVERED:
                        raise RuntimeActivationRecoveryError(outcome) from exc
                    rebound = self._current_runtime_failure_binding_state(
                        timeout_seconds=0.35,
                        refresh=True,
                    )
                    if rebound is None:
                        raise RuntimeControllerReadbackError(
                            "Recovered FINAL-EXIT route has no authoritative "
                            "controller readback"
                        ) from exc
                    (
                        rebound_binding,
                        rebound_snapshot,
                        rebound_payload,
                    ) = rebound
                    if submission.from_ref.pool_kind == "gateway":
                        if not (
                            isinstance(binding_state, tuple)
                            and len(binding_state) == 3
                            and isinstance(
                                binding_state[0],
                                RuntimeRouteBinding,
                            )
                            and isinstance(
                                binding_state[1],
                                CoreLoadedRouteSnapshot,
                            )
                            and isinstance(binding_state[2], dict)
                        ):
                            raise RuntimeControllerReadbackError(
                                "Recovered Gateway route lost its original "
                                "controller binding"
                            ) from exc
                        (
                            original_gateway_binding,
                            original_snapshot,
                            original_payload,
                        ) = binding_state
                        original_underlay = (
                            self._runtime_gateway_underlay_binding(
                                original_snapshot,
                                original_payload,
                                original_gateway_binding.node,
                            )
                        )
                        rebound_underlay = (
                            self._runtime_gateway_underlay_binding(
                                rebound_snapshot,
                                rebound_payload,
                                rebound_binding.node,
                            )
                        )
                        gateway_recovery_valid = bool(
                            original_gateway_binding.node.pool_kind
                            == "gateway"
                            and original_gateway_binding.node.key
                            == submission.from_ref.key
                            and rebound_binding.node.key
                            == submission.from_ref.key
                            and original_underlay is not None
                            and rebound_underlay is not None
                            and original_underlay.node.key
                            != rebound_underlay.node.key
                            and outcome.to_ref is not None
                            and rebound_underlay.node.key
                            == outcome.to_ref.key
                            and int(rebound_binding.route_epoch)
                            == int(outcome.route_epoch)
                            and int(rebound_binding.route_epoch)
                            > int(original_gateway_binding.route_epoch)
                        )
                        if not gateway_recovery_valid:
                            raise RuntimeControllerReadbackError(
                                "Recovered Gateway underlay lost its "
                                "route-epoch CAS"
                            ) from exc
                    elif (
                        rebound_binding.node.key == submission.from_ref.key
                        or outcome.to_ref is None
                        or rebound_binding.node.key != outcome.to_ref.key
                        or int(rebound_binding.route_epoch)
                        != int(outcome.route_epoch)
                    ):
                        raise RuntimeControllerReadbackError(
                            "Recovered FINAL-EXIT route lost its route-epoch CAS"
                        ) from exc
                    verified_route = getattr(
                        self,
                        "_runtime_last_verified_route",
                        None,
                    )
                    verified_result = (
                        verified_route.get("result")
                        if isinstance(verified_route, dict)
                        else None
                    )
                    if not (
                        isinstance(verified_route, dict)
                        and str(verified_route.get("incident_id") or "")
                        == submission.incident_id
                        and isinstance(verified_result, dict)
                        and int(verified_result.get("status") or 0) == 204
                    ):
                        raise RuntimeControllerReadbackError(
                            "Recovered FINAL-EXIT route has no incident-owned "
                            "204 proof"
                        ) from exc
                    result = (
                        dict(verified_result)
                        if isinstance(verified_result, dict)
                        else {}
                    )
                    result["runtime_recovery_outcome"] = outcome.to_dict()
                if not isinstance(submission, _RuntimeRecoveryTicket):
                    if submission is False:
                        # No incident ticket means no fallback transaction was
                        # admitted.  Preserve the authoritative, already
                        # redacted mixed-port failure: admission refusal is not
                        # probe-capacity evidence and must not replace the real
                        # cause with an internal controller/broker diagnosis.
                        raise exc
                    raise exc
            except (
                _RuntimeProbeBudgetUnavailable,
                RuntimeActivationRecoveryError,
                RuntimeControllerReadbackError,
            ):
                raise
            except Exception:
                # Failure submission is evidence plumbing, never a reason to
                # hide or replace the authoritative mixed-port exception.
                log_raw_diagnostic(
                    self.logger,
                    "warning",
                    "Bastion activation failure could not be submitted to "
                    "the runtime egress coordinator",
                    exc_info=True,
                )
                raise exc
        self._set_tier3_runtime_final_exit_qualification(True)
        self._queue_selected_tier3_leaf_qualification(
            probe_endpoint=str(result.get("url") or "FINAL-EXIT"),
        )
        self._record_tier3_core_sync_ledger(
            "final_exit_probe",
            event="append_only",
            semantic_digest=qualification.config_digest,
            detail=(
                f"passed:{int((time.monotonic() - probe_started) * 1000)}ms"
            ),
        )
        self.logger.info(
            "Verified Bastion Layer FINAL-EXIT connectivity through mihomo mixed-port (%s, %sms)",
            result.get("url"),
            result.get("latency_ms"),
        )
        return result

    def _mark_tier3_export_verification_failed(self, reason: str, *, retain_core_verified: bool = False) -> None:
        manager = self.manager
        if not manager:
            return
        reason_text = str(reason or "Bastion Layer egress verification failed")
        try:
            with manager.lock:
                current_nodes = list(manager.runtime_nodes.get("tier3", []))
                if retain_core_verified:
                    rejected_count = sum(
                        1 for node in current_nodes if not node_has_startup_core_verification(node)
                    )
                else:
                    rejected_count = len(current_nodes)
                manager.last_collect_tier3 = 0.0
                report = ensure_tier3_collection_report(manager)
                repair = report.get("startup_core_repair", {})
                repair = repair if isinstance(repair, dict) else {}
                report["startup_core_verification_failed"] = build_tier3_startup_core_verification_failed_report(
                    reason=reason_text,
                    rejected_count=max(rejected_count, int(repair.get("pruned_count", 0) or 0)),
                )
                report["background_expansion_due"] = True
        except Exception:
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Failed to clear failed Bastion Layer export candidates",
                exc_info=True,
            )
            return
        try:
            self._mark_tier3_core_sync_failure(self._tier3_core_sync_marker())
        except Exception:
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Failed to mark Bastion Layer core verification failure marker",
                exc_info=True,
            )

    def _prime_tier3_pool_before_core_start(self) -> None:
        self._recover_tier3_pool_before_core_start()

    def _recover_tier3_pool_before_core_start(self) -> None:
        """Use Bastion as the same recovery path whenever primary layers are unavailable."""
        manager = self.manager
        self._tier3_required_for_start = False
        self._set_tier3_startup_gate_required(False)
        self._clear_tier3_terminal_startup_failure()
        self._primary_startup_error = None
        if not manager:
            return
        primary_ready = self._primary_layers_ready_for_start()
        if primary_ready:
            return
        tier3_enabled = getattr(manager, "_tier3_enabled", None)
        if not callable(tier3_enabled):
            return
        cached_nodes_for_start = self._tier3_cached_nodes_verified_for_start(manager)
        committed_healthy = count_healthy_nodes(cached_nodes_for_start)
        cached_revalidation_count = sum(
            1 for node in cached_nodes_for_start if node_has_tier3_cache_revalidation_pending(node)
        )
        snapshot_revalidation_count = 0
        snapshot_counter = getattr(manager, "_tier3_snapshot_revalidation_backlog_count", None)
        if callable(snapshot_counter):
            try:
                snapshot_revalidation_count = int(snapshot_counter() or 0)
            except Exception:
                snapshot_revalidation_count = 0
        cached_revalidation_count += max(0, snapshot_revalidation_count)
        target_healthy = self._tier3_startup_target_alive(manager)
        self._tier3_required_for_start = True
        self._set_tier3_startup_gate_required(True)
        if (
            committed_healthy < target_healthy
            and self._fail_terminal_tier3_bootstrap(manager)
        ):
            return
        retry_after_core_verification_failure = self._tier3_core_verification_retry_pending(manager)
        if committed_healthy >= target_healthy and cached_revalidation_count <= 0 and not retry_after_core_verification_failure:
            self.logger.info(
                "Bastion Layer already has %s committed healthy node(s) for core launch",
                committed_healthy,
            )
            self._record_tier3_startup_background_expansion(
                manager,
                committed_healthy,
                mark_collect_complete_when_full=True,
            )
            if committed_healthy < self._tier3_background_target_alive(manager):
                try:
                    self._trigger_tier3_background_collect(manager, startup_mode=False)
                except Exception:
                    log_raw_diagnostic(
                        self.logger,
                        "warning",
                        "Failed to continue Bastion Layer background expansion after committed pool gate",
                        exc_info=True,
                    )
            return
        recovery_plan = tier3_start_recovery_plan(
            primary_ready=primary_ready,
            tier3_enabled=tier3_enabled(),
            cached_healthy_count=0,
            target_healthy_count=target_healthy,
            primary_failure=self._primary_startup_error,
            cached_revalidation_count=cached_revalidation_count,
        )
        self._tier3_required_for_start = recovery_plan.recovery_required
        self._set_tier3_startup_gate_required(self._tier3_required_for_start)
        if recovery_plan.action is Tier3StartRecoveryAction.UNAVAILABLE:
            self._last_tier3_startup_error = recovery_plan.reason
            log_raw_diagnostic(self.logger, "warning", self._last_tier3_startup_error)
            return
        if recovery_plan.action is Tier3StartRecoveryAction.REVALIDATE_CACHED_POOL:
            self.logger.info(
                "Bastion Layer has %s cached snapshot node(s); staging them for outside PI revalidation",
                cached_revalidation_count,
            )
            try:
                startup_revalidator = getattr(manager, "revalidate_tier3_startup_pool", None)
                if callable(startup_revalidator):
                    startup_revalidator(target_alive=target_healthy)
                elif not callable(getattr(manager, "trigger_tier3_collect", None)):
                    manager.check_tier3(force_collect=False)
            except Exception:
                log_raw_diagnostic(
                    self.logger,
                    "warning",
                    "Cached Bastion Layer snapshot staging failed",
                    exc_info=True,
                )
            if self.stop_event.is_set() or getattr(manager, "closed", False):
                self.logger.info("Bastion Layer startup recovery stopped before core launch")
                return
            staged_pool_healthy = count_healthy_nodes(manager.runtime_nodes.get("tier3", []))
            if staged_pool_healthy >= target_healthy:
                self.logger.info(
                    "Bastion Layer already has %s committed healthy node(s) after snapshot staging",
                    staged_pool_healthy,
                )
                self._record_tier3_startup_background_expansion(
                    manager,
                    staged_pool_healthy,
                    mark_collect_complete_when_full=True,
                )
                if staged_pool_healthy < self._tier3_background_target_alive(manager):
                    try:
                        self._trigger_tier3_background_collect(manager, startup_mode=False)
                    except Exception:
                        log_raw_diagnostic(
                            self.logger,
                            "warning",
                            "Failed to continue Bastion Layer background expansion after cache gate",
                            exc_info=True,
                        )
                return
            self.logger.info(
                "Bastion Layer snapshot cache is outside the committed pool (%s/%s); collecting and validating candidates before core launch",
                staged_pool_healthy,
                recovery_plan.target_healthy_count,
            )

        self.logger.info("Collecting and validating Bastion Layer candidates before core launch")
        try:
            background_started = self._trigger_tier3_background_collect(manager, startup_mode=True)
            if background_started:
                current_healthy = count_healthy_nodes(manager.runtime_nodes.get("tier3", []))
                if current_healthy < target_healthy:
                    self.logger.info(
                        "Bastion Layer startup service is running; core launch is deferred to the committed-pool gate"
                    )
                    return
        except Exception as exc:
            self._last_tier3_startup_error = str(exc)
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Bastion Layer startup collection failed",
                exc_info=True,
            )
        if self.stop_event.is_set() or getattr(manager, "closed", False):
            self.logger.info("Bastion Layer startup recovery stopped before core launch")
            return
        refreshed_healthy = count_healthy_nodes(manager.runtime_nodes.get("tier3", []))
        if refreshed_healthy > 0:
            collect_still_running = self._tier3_collect_action_running(manager)
            report = self._record_tier3_startup_background_expansion(
                manager,
                refreshed_healthy,
                mark_collect_complete_when_full=False,
            )
            validation = report.get("validation", {}) if isinstance(report, dict) else {}
            if isinstance(validation, dict) and validation.get("prelaunch_validation") == "tcp":
                self.logger.info(
                    "Bastion Layer startup prepared %s TCP-responsive candidate(s); core warmup will verify proxy egress",
                    refreshed_healthy,
                )
            elif refreshed_healthy < target_healthy and collect_still_running:
                self.logger.info(
                    "Bastion Layer startup gate is waiting for more validated nodes "
                    "(%s/%s); source collection is still running",
                    refreshed_healthy,
                    target_healthy,
                )
            elif refreshed_healthy < target_healthy:
                log_raw_diagnostic(
                    self.logger,
                    "warning",
                    "Bastion Layer startup collection completed below the startup gate "
                    "(%s/%s)",
                    refreshed_healthy,
                    target_healthy,
                )
            else:
                self.logger.info(
                    "Bastion Layer startup collection validated %s healthy node(s)",
                    refreshed_healthy,
                )
            return

        live_reason = self._tier3_startup_live_collection_reason(manager)
        if live_reason:
            self.logger.info(
                "Bastion Layer startup remains deferred with active work (%s)",
                live_reason,
            )
            return
        if self._fail_terminal_tier3_bootstrap(manager):
            return
        # Keep the background collector eager after a genuinely exhausted first attempt.
        with manager.lock:
            manager.last_collect_tier3 = 0.0
        log_raw_diagnostic(
            self.logger,
            "warning",
            "Bastion Layer startup collection found no validated nodes",
        )

    def _record_tier3_startup_background_expansion(
        self,
        manager: Any,
        healthy_count: int,
        *,
        mark_collect_complete_when_full: bool,
    ) -> dict[str, Any]:
        background_target = self._tier3_background_target_alive(manager)
        with manager.lock:
            report = ensure_tier3_collection_report(manager)
            report.setdefault("target_alive", background_target)
            report.setdefault("background_target_alive", background_target)
            report.setdefault("min_alive_nodes", self._tier3_startup_target_alive(manager))
            validation = report.get("validation")
            if isinstance(validation, dict):
                validation.setdefault("target_alive", background_target)
            decision = tier3_startup_background_expansion_decision(
                healthy_count=healthy_count,
                background_target=background_target,
                mark_collect_complete_when_full=mark_collect_complete_when_full,
                last_check_monotonic=getattr(manager, "last_check_monotonic", {}),
                fallback_now=time.monotonic(),
            )
            report["background_expansion_due"] = decision.background_expansion_due
            if decision.next_last_collect_tier3 is not None:
                manager.last_collect_tier3 = decision.next_last_collect_tier3
            return report

    def _tier3_startup_target_alive(self, manager: Any) -> int:
        return tier3_alive_target_from_manager(manager, default=1)

    def _tier3_background_target_alive(self, manager: Any) -> int:
        startup_target = self._tier3_startup_target_alive(manager)
        getter = getattr(manager, "_tier3_background_target_alive_nodes", None)
        if callable(getter):
            try:
                return max(startup_target, int(getter()))
            except (TypeError, ValueError):
                pass
        return tier3_alive_target_from_manager(
            manager,
            default=startup_target,
        )

    def _tier3_export_uses_tcp_prelaunch_validation(self) -> bool:
        manager = self.manager
        if not manager:
            return False
        report = getattr(manager, "tier3_last_collection_report", {}) or {}
        nodes = getattr(manager, "runtime_nodes", {}).get("tier3", [])
        return tier3_export_uses_tcp_prelaunch_validation(
            report=report,
            nodes=list(nodes),
        )

    def _tier3_core_repair_alive_target(self) -> int:
        manager = self.manager
        if not manager:
            return 1
        if tier3_core_repair_uses_startup_target(
            tier3_required_for_start=self._tier3_required_for_start,
            uses_tcp_prelaunch_validation=self._tier3_export_uses_tcp_prelaunch_validation(),
        ):
            return self._tier3_startup_target_alive(manager)
        return self._tier3_background_target_alive(manager)

    def _tier3_core_repair_target_alive(self) -> int:
        manager = self.manager
        if not manager:
            return 1
        if tier3_core_repair_uses_startup_target(
            tier3_required_for_start=self._tier3_required_for_start,
            uses_tcp_prelaunch_validation=self._tier3_export_uses_tcp_prelaunch_validation(),
        ):
            return self._tier3_startup_target_alive(manager)
        return self._tier3_core_repair_alive_target()

    def _tier3_core_repair_min_alive(self) -> int:
        manager = self.manager
        if manager and tier3_core_repair_uses_startup_target(
            tier3_required_for_start=self._tier3_required_for_start,
            uses_tcp_prelaunch_validation=self._tier3_export_uses_tcp_prelaunch_validation(),
        ):
            return self._tier3_startup_target_alive(manager)
        return self._tier3_core_repair_alive_target()

    def _tier3_startup_failure_detail(self) -> str:
        manager = self.manager
        if not manager:
            return self._last_tier3_startup_error or ""
        report = getattr(manager, "tier3_last_collection_report", {}) or {}
        nodes = list(getattr(manager, "runtime_nodes", {}).get("tier3", []))
        return tier3_startup_failure_detail(
            primary_startup_error=self._primary_startup_error,
            report=report,
            nodes=nodes,
            last_startup_error=self._last_tier3_startup_error,
        )

    def _tier3_export_signature(self) -> tuple[Any, ...]:
        manager = self.manager
        if not manager:
            return ()
        limit = self._mihomo_tier3_export_limit()
        nodes = self._tier3_nodes_for_core_export(limit)
        return tier3_export_signature(nodes)

    def _tier3_committed_pool_signature(self) -> tuple[Any, ...]:
        limit = self._mihomo_tier3_export_limit()
        return tier3_export_signature(self._tier3_nodes_for_core_export(limit))

    def _tier_export_signature(self, tier_id: str, *, limit: int | None = None) -> tuple[Any, ...]:
        manager = self.manager
        if not manager:
            return ()
        runtime_view = self._manager_for_mihomo_runtime_config()
        getter = getattr(runtime_view, "get_nodes_for_subscription", None)
        if callable(getter):
            nodes = getter(tier_id, limit=limit)
        else:
            nodes = list(getattr(runtime_view, "runtime_nodes", {}).get(tier_id, []))
            if limit is not None:
                nodes = nodes[:limit]
        return tier3_export_signature(list(nodes))

    def _core_export_sync_marker(self) -> tuple[Any, ...] | None:
        manager = self.manager
        if not manager:
            return None
        # The selection's key: a new node re-renders; a label-only change (a
        # bind) renders the same YAML, so the reload gate finds nothing to do.
        active_exit = selection_from_manager(manager).key
        overlay_membership = tuple(
            sorted(self._runtime_audit_export_excluded_snapshot())
        )
        semantic_digest = ""
        try:
            if self._current_core_runtime_phase() == "bootstrap":
                semantic_digest = self._bootstrap_source_export_contract_snapshot()["semantic_digest"]
            else:
                rendered_payload = self._render_mihomo_runtime_payload_snapshot()
                rendered_config = yaml.safe_load(rendered_payload) or {}
                semantic_digest = CoreExportSemanticDigest.from_rendered_config(
                    rendered_config,
                    overlay_membership=overlay_membership,
                ).digest
        except Exception:
            # Focused lifecycle adapters may not implement the complete
            # subscription renderer. Per-tier rendered proxy signatures below
            # remain a safe fallback marker for those adapters.
            semantic_digest = ""
        return (
            ("tier1", self._tier_export_signature("tier1")),
            ("tier2", self._tier_export_signature("tier2")),
            ("tier3", self._tier_export_signature("tier3", limit=self._mihomo_tier3_export_limit())),
            ("exit", self._tier_export_signature("exit")),
            ("active_exit", active_exit),
            ("runtime_audit_overlay", overlay_membership),
            ("core_semantic_digest", semantic_digest),
        )

    @staticmethod
    def _core_semantic_digest_from_marker(
        marker: tuple[Any, ...] | None,
    ) -> str:
        if isinstance(marker, tuple):
            for item in marker:
                if (
                    isinstance(item, tuple)
                    and len(item) == 2
                    and item[0] == "core_semantic_digest"
                ):
                    value = str(item[1] or "")
                    if value:
                        return value
        encoded = repr(marker).encode("utf-8")
        return hashlib.sha256(encoded).hexdigest()

    def _tier3_runtime_export_semantics(self) -> dict[str, tuple[Any, ...]]:
        return {
            self._node_identity_text(node): tier3_export_node_signature(node)
            for node in self._tier3_nodes_for_core_export(
                self._mihomo_tier3_export_limit()
            )
        }

    def _advance_tier3_runtime_config_generation(
        self,
        marker: tuple[Any, ...] | None = None,
        *,
        preserve_final_exit: bool = False,
    ) -> None:
        current_marker = self._core_export_sync_marker() if marker is None else marker
        digest = self._core_semantic_digest_from_marker(current_marker)
        semantics = self._tier3_runtime_export_semantics()
        changed = False
        with self._tier3_runtime_qualification_lock:
            if digest != self._tier3_runtime_config_digest:
                self._tier3_runtime_config_generation += 1
                self._tier3_runtime_config_digest = digest
                self._tier3_runtime_controller_snapshot = None
                if not preserve_final_exit:
                    self._tier3_runtime_final_exit_ok = False
                    self._tier3_runtime_final_exit_core_generation = -1
                    self._tier3_selected_leaf_evidence = None
                changed = True
            for identity, entry in list(self._tier3_runtime_qualified.items()):
                if (
                    identity not in semantics
                    or tuple(entry.get("proxy_signature") or ())
                    != tuple(semantics[identity])
                ):
                    self._tier3_runtime_qualified.pop(identity, None)
        if changed:
            with self._runtime_audit_export_overlay_lock:
                self._runtime_audit_deterministic_failures.clear()
            self._publish_tier3_runtime_qualification()

    def _tier3_selected_leaf_qualification_evidence(
        self,
    ) -> tuple[str, str, tuple[Any, ...]] | None:
        """Return stable evidence for the selected, already-qualified Tier3 leaf."""

        manager = self.manager
        if manager is None:
            return None
        lifecycle_lock = getattr(self, "_core_lifecycle_lock", None)
        with lifecycle_lock if lifecycle_lock is not None else nullcontext():
            core_generation = int(getattr(self, "_core_generation", 0) or 0)
        with self._tier3_runtime_qualification_lock:
            if (
                not self._tier3_runtime_final_exit_ok
                or int(
                    getattr(
                        self,
                        "_tier3_runtime_final_exit_core_generation",
                        -1,
                    )
                    or -1
                )
                != core_generation
            ):
                return None
        if not self._runtime_initial_activation_was_completed():
            return None
        try:
            route = inspect_runtime_route(self.mihomo_proxies())
            if route.get("facility_failure"):
                return None
            leaf = str(route.get("leaf_proxy") or "")
            leaf_info = self._runtime_proxy_name_map().get(leaf)
        except Exception:
            return None
        if not leaf or not isinstance(leaf_info, dict):
            return None
        if str(leaf_info.get("tier") or "") != "tier3":
            return None
        identity = str(leaf_info.get("identity") or "")
        node = leaf_info.get("node")
        signature = tier3_export_node_signature(node) if node is not None else ()
        if not identity or not signature:
            return None
        with self._tier3_runtime_qualification_lock:
            entry = self._tier3_runtime_qualified.get(identity)
            durable_evidence = self._tier3_selected_leaf_evidence
            if (
                not self._tier3_runtime_final_exit_ok
                or (
                    (
                        not isinstance(entry, dict)
                        or tuple(entry.get("proxy_signature") or ())
                        != tuple(signature)
                    )
                    and durable_evidence
                    != (leaf, identity, tuple(signature))
                )
            ):
                return None
        return leaf, identity, tuple(signature)

    def _capture_selected_tier3_leaf_qualification_binding(
        self,
    ) -> _Tier3LeafQualificationBinding | None:
        """Freeze the exact loaded leaf proven by the just-finished 204."""

        worker_token = self._runtime_worker_token()
        with self._tier3_runtime_qualification_lock:
            expected_generation = int(self._tier3_runtime_config_generation)
            expected_digest = str(self._tier3_runtime_config_digest)
            controller_snapshot = copy.deepcopy(
                self._tier3_runtime_controller_snapshot
            )
        if controller_snapshot is None or (
            int(controller_snapshot[0]) != expected_generation
            or str(controller_snapshot[1]) != expected_digest
        ):
            # Never fetch a controller view after the successful request and
            # then pretend that later selection was the route it proved.
            return None
        try:
            proxies_payload = controller_snapshot[2]
            route = inspect_runtime_route(proxies_payload)
            if route.get("facility_failure"):
                return None
            leaf = str(route.get("leaf_proxy") or "")
            proxies = (
                proxies_payload.get("proxies", {})
                if isinstance(proxies_payload, dict)
                else {}
            )
            controller_entry = (
                proxies.get(leaf) if isinstance(proxies, dict) else None
            )
        except Exception:
            return None
        if not leaf or not isinstance(controller_entry, dict):
            return None

        with self._runtime_route_snapshot_lock:
            route_epoch = int(self._runtime_route_epoch)
            route_snapshot = self._runtime_route_snapshot
            snapshot_key = (
                route_snapshot.snapshot_key
                if route_snapshot is not None
                else None
            )
            loaded_contract = self._runtime_loaded_export_contract
            loaded_revision = (
                int(loaded_contract.get("revision") or 0)
                if isinstance(loaded_contract, dict)
                else 0
            )
            loaded_semantic_digest = (
                str(loaded_contract.get("semantic_digest") or "")
                if isinstance(loaded_contract, dict)
                else ""
            )
            loaded_proxy_map = (
                loaded_contract.get("proxy_map")
                if isinstance(loaded_contract, dict)
                else None
            )
            leaf_info = (
                loaded_proxy_map.get(leaf)
                if isinstance(loaded_proxy_map, dict)
                else None
            )
        if not isinstance(leaf_info, dict):
            leaf_info = self._runtime_proxy_name_map().get(leaf)
        if (
            not isinstance(leaf_info, dict)
            or str(leaf_info.get("tier") or "") != "tier3"
        ):
            return None
        identity = str(leaf_info.get("identity") or "")
        node = leaf_info.get("node")
        signature = tier3_export_node_signature(node) if node is not None else ()
        current_signature = self._tier3_runtime_export_semantics().get(identity)
        if (
            not identity
            or not signature
            or tuple(current_signature or ()) != tuple(signature)
        ):
            return None
        return _Tier3LeafQualificationBinding(
            worker_token=worker_token,
            config_generation=expected_generation,
            config_digest=expected_digest,
            loaded_revision=loaded_revision,
            loaded_semantic_digest=loaded_semantic_digest,
            route_epoch=route_epoch,
            snapshot_key=snapshot_key,
            leaf_proxy=leaf,
            identity=identity,
            proxy_signature=tuple(signature),
        )

    def _tier3_leaf_qualification_binding_is_current(
        self,
        binding: _Tier3LeafQualificationBinding,
    ) -> bool:
        if not self._runtime_worker_token_is_current(binding.worker_token):
            return False
        with self._runtime_route_snapshot_lock:
            loaded_contract = self._runtime_loaded_export_contract
            loaded_revision = (
                int(loaded_contract.get("revision") or 0)
                if isinstance(loaded_contract, dict)
                else 0
            )
            loaded_digest = (
                str(loaded_contract.get("semantic_digest") or "")
                if isinstance(loaded_contract, dict)
                else ""
            )
            current_snapshot = self._runtime_route_snapshot
            if (
                int(self._runtime_route_epoch) != binding.route_epoch
                or loaded_revision != binding.loaded_revision
                or loaded_digest != binding.loaded_semantic_digest
                or (
                    binding.snapshot_key is not None
                    and (
                        current_snapshot is None
                        or current_snapshot.snapshot_key != binding.snapshot_key
                    )
                )
            ):
                return False
        with self._tier3_runtime_qualification_lock:
            controller_snapshot = self._tier3_runtime_controller_snapshot
            if controller_snapshot is None or (
                int(self._tier3_runtime_config_generation)
                != binding.config_generation
                or str(self._tier3_runtime_config_digest)
                != binding.config_digest
                or int(controller_snapshot[0]) != binding.config_generation
                or str(controller_snapshot[1]) != binding.config_digest
            ):
                return False
            try:
                route = inspect_runtime_route(controller_snapshot[2])
            except Exception:
                return False
            if (
                route.get("facility_failure")
                or str(route.get("leaf_proxy") or "")
                != binding.leaf_proxy
            ):
                return False
        current = self._runtime_proxy_name_map().get(binding.leaf_proxy)
        if not isinstance(current, dict):
            return False
        node = current.get("node")
        current_signature = (
            tier3_export_node_signature(node) if node is not None else ()
        )
        return bool(
            str(current.get("tier") or "") == "tier3"
            and str(current.get("identity") or "") == binding.identity
            and tuple(current_signature) == binding.proxy_signature
            and tuple(
                self._tier3_runtime_export_semantics().get(binding.identity)
                or ()
            )
            == binding.proxy_signature
        )

    def _record_selected_tier3_leaf_qualification(
        self,
        *,
        probe_endpoint: str,
        binding: _Tier3LeafQualificationBinding,
    ) -> bool:
        """Commit delayed Tier3 evidence only to the route proven by its 204."""

        if not self._tier3_leaf_qualification_binding_is_current(binding):
            return False
        now = time.monotonic()
        evidence = (
            binding.leaf_proxy,
            binding.identity,
            binding.proxy_signature,
        )
        # Recheck every mutable owner after computing current semantics.  The
        # qualification lock makes config/controller changes linear with this
        # commit; the route CAS above prevents an old callback from following
        # a selector or Core-load revision forward.
        with self._tier3_runtime_qualification_lock:
            controller_snapshot = self._tier3_runtime_controller_snapshot
            if controller_snapshot is None or (
                int(self._tier3_runtime_config_generation)
                != binding.config_generation
                or str(self._tier3_runtime_config_digest)
                != binding.config_digest
                or int(controller_snapshot[0]) != binding.config_generation
                or str(controller_snapshot[1]) != binding.config_digest
            ):
                return False
            try:
                current_leaf = str(
                    inspect_runtime_route(controller_snapshot[2]).get(
                        "leaf_proxy"
                    )
                    or ""
                )
            except Exception:
                return False
            if current_leaf != binding.leaf_proxy:
                return False
            self._tier3_runtime_qualified[binding.identity] = {
                "proxy_signature": binding.proxy_signature,
                "qualified_at_monotonic": now,
                "expires_at_monotonic": (
                    now + self._tier3_runtime_qualification_ttl_seconds
                ),
                "probe_endpoint": self._safe_probe_endpoint_label(
                    probe_endpoint
                ),
                "evidence": "final_exit_mixed_port",
            }
            self._tier3_selected_leaf_evidence = evidence
            self._tier3_runtime_qualification_monitor_at = (
                now + self._tier3_runtime_qualification_ttl_seconds
            )
            self._tier3_runtime_last_revalidation_key = None
        self._publish_tier3_runtime_qualification()
        return True

    def _queue_selected_tier3_leaf_qualification(
        self,
        *,
        probe_endpoint: str,
    ) -> None:
        """Bind Tier3 leaf evidence after effective egress is already open."""

        binding = self._capture_selected_tier3_leaf_qualification_binding()
        if binding is None:
            return

        def worker() -> None:
            self._record_selected_tier3_leaf_qualification(
                probe_endpoint=probe_endpoint,
                binding=binding,
            )

        threading.Thread(
            target=worker,
            name="runtime-tier3-leaf-qualification",
            daemon=True,
        ).start()

    def _tier3_preserved_leaf_qualification_evidence(
        self,
        evidence: tuple[str, str, tuple[Any, ...]] | None,
    ) -> tuple[str, str, tuple[Any, ...]] | None:
        """Confirm an already-qualified leaf survived an append-only reload."""

        manager = self.manager
        if evidence is None or manager is None:
            return None
        leaf, identity, signature = evidence
        current = self._runtime_proxy_name_map().get(str(leaf))
        if not isinstance(current, dict):
            return None
        node = current.get("node")
        if (
            str(current.get("tier") or "") != "tier3"
            or str(current.get("identity") or "") != str(identity)
            or node is None
            or tuple(tier3_export_node_signature(node)) != tuple(signature)
        ):
            return None
        try:
            payload = self.mihomo_proxies()
            entries = payload.get("proxies") if isinstance(payload, dict) else None
            if entries is None and isinstance(payload, dict):
                entries = payload
            controller_entry = (
                entries.get(str(leaf)) if isinstance(entries, dict) else None
            )
        except Exception:
            return None
        # This evidence is created only after a successful mixed-port
        # FINAL-EXIT probe.  Mihomo's controller ``alive`` bit is populated by
        # /delay and can remain false or stale while that authoritative data
        # plane request succeeds.  Requiring it here made every append-only
        # pool reload revoke the proven leaf and start another revalidation
        # cycle.  Presence plus an unchanged rendered signature is sufficient
        # to carry the successful FINAL-EXIT evidence across the reload; a
        # later real FINAL-EXIT failure still revokes it through the ordinary
        # qualification path.
        if not isinstance(controller_entry, dict):
            return None
        with self._tier3_runtime_qualification_lock:
            qualified = self._tier3_runtime_qualified.get(str(identity))
            durable_evidence = self._tier3_selected_leaf_evidence
            if (
                not self._tier3_runtime_final_exit_ok
                or (
                    (
                        not isinstance(qualified, dict)
                        or tuple(qualified.get("proxy_signature") or ())
                        != tuple(signature)
                    )
                    and durable_evidence
                    != (str(leaf), str(identity), tuple(signature))
                )
            ):
                return None
        return str(leaf), str(identity), tuple(signature)

    def _tier3_runtime_qualification_snapshot(
        self,
    ) -> Tier3RuntimeQualificationSnapshot:
        now = time.monotonic()
        semantics = self._tier3_runtime_export_semantics()
        lifecycle_lock = getattr(self, "_core_lifecycle_lock", None)
        with lifecycle_lock if lifecycle_lock is not None else nullcontext():
            core_generation = int(getattr(self, "_core_generation", 0) or 0)
        manager = self.manager
        admitted_count = 0
        if manager is not None:
            pool_snapshot = getattr(manager, "tier3_auto_pool_count_snapshot", None)
            if callable(pool_snapshot):
                admitted_count = int(pool_snapshot().healthy)
            else:
                admitted_count = count_healthy_nodes(
                    list(getattr(manager, "runtime_nodes", {}).get("tier3", []))
                )
        with self._tier3_runtime_qualification_lock:
            for identity, entry in list(self._tier3_runtime_qualified.items()):
                expires_at = float(entry.get("expires_at_monotonic", 0.0) or 0.0)
                if (
                    expires_at <= now
                    or identity not in semantics
                    or tuple(entry.get("proxy_signature") or ())
                    != tuple(semantics[identity])
                ):
                    self._tier3_runtime_qualified.pop(identity, None)
            identities = tuple(sorted(self._tier3_runtime_qualified))
            qualified_at = [
                float(entry.get("qualified_at_monotonic", now) or now)
                for entry in self._tier3_runtime_qualified.values()
            ]
            config_generation = int(self._tier3_runtime_config_generation)
            config_digest = str(self._tier3_runtime_config_digest)
            final_exit_ok = bool(
                self._tier3_runtime_final_exit_ok
                and int(
                    getattr(
                        self,
                        "_tier3_runtime_final_exit_core_generation",
                        -1,
                    )
                    or -1
                )
                == core_generation
            )
        traffic_capture_active = bool(
            getattr(manager, "tier3_traffic_capture_active", False)
            if manager is not None
            else False
        )
        return Tier3RuntimeQualificationSnapshot(
            config_generation=config_generation,
            config_digest=config_digest,
            admitted_count=max(0, admitted_count),
            exported_count=len(semantics),
            qualified_count=len(identities),
            qualified_identities=identities,
            final_exit_ok=final_exit_ok,
            traffic_capture_active=traffic_capture_active,
            observed_at_monotonic=now,
            oldest_qualification_monotonic=(
                min(qualified_at) if qualified_at else None
            ),
        )

    def _publish_tier3_runtime_qualification(
        self,
    ) -> Tier3RuntimeQualificationSnapshot:
        snapshot = self._tier3_runtime_qualification_snapshot()
        manager = self.manager
        publisher = getattr(
            manager,
            "update_tier3_runtime_qualification",
            None,
        ) if manager is not None else None
        if callable(publisher):
            publisher(snapshot)
        return snapshot

    def _set_tier3_runtime_final_exit_qualification(self, ok: bool) -> None:
        lifecycle_lock = getattr(self, "_core_lifecycle_lock", None)
        with lifecycle_lock if lifecycle_lock is not None else nullcontext():
            core_generation = int(getattr(self, "_core_generation", 0) or 0)
        with self._tier3_runtime_qualification_lock:
            self._tier3_runtime_final_exit_ok = bool(ok)
            self._tier3_runtime_final_exit_core_generation = (
                core_generation if ok else -1
            )
            if not ok:
                self._tier3_selected_leaf_evidence = None
                self._tier3_runtime_qualification_monitor_at = 0.0
                self._tier3_runtime_last_revalidation_key = None
        self._publish_tier3_runtime_qualification()

    def _clear_tier3_runtime_qualification(self) -> None:
        with self._tier3_runtime_qualification_lock:
            self._tier3_runtime_qualified.clear()
            self._tier3_runtime_controller_snapshot = None
            self._tier3_runtime_final_exit_ok = False
            self._tier3_runtime_final_exit_core_generation = -1
            self._tier3_selected_leaf_evidence = None
            self._tier3_runtime_qualification_monitor_at = 0.0
            self._tier3_runtime_last_revalidation_key = None
            self._tier3_runtime_config_digest = ""
            self._tier3_runtime_config_generation += 1
        if self.manager is not None:
            self._publish_tier3_runtime_qualification()

    def _refresh_tier3_runtime_qualification(
        self,
    ) -> Tier3RuntimeQualificationSnapshot:
        marker = self._core_export_sync_marker()
        self._advance_tier3_runtime_config_generation(marker)
        manager = self.manager
        required = max(
            1,
            int(
                getattr(manager, "_tier3_min_alive_nodes", lambda: 1)()
                if manager is not None
                else 1
            ),
        )
        current = self._tier3_runtime_qualification_snapshot()
        if current.qualified_count >= required:
            return self._publish_tier3_runtime_qualification()

        proxies_payload = self.mihomo_proxies()
        with self._tier3_runtime_qualification_lock:
            self._tier3_runtime_controller_snapshot = (
                int(self._tier3_runtime_config_generation),
                str(self._tier3_runtime_config_digest),
                proxies_payload,
            )
        proxies = (
            proxies_payload.get("proxies", {})
            if isinstance(proxies_payload, dict)
            else {}
        )
        loaded_names = set(proxies) if isinstance(proxies, dict) else set()
        semantics = self._tier3_runtime_export_semantics()
        already_qualified = set(current.qualified_identities)
        pairs = [
            (proxy_name, node)
            for proxy_name, node in self._tier3_proxy_name_pairs()
            if proxy_name in loaded_names
            and self._node_identity_text(node) not in already_qualified
        ]
        needed = max(0, required - current.qualified_count)
        if pairs and needed > 0:
            probe_run = run_tier3_core_probe(
                pairs,
                timeout_ms=int(self._startup_probe_timeout_seconds() * 1000),
                configured_concurrency=min(
                    2,
                    self._startup_core_probe_concurrency(),
                ),
                prune_to_successful=True,
                target_verified=needed,
                probe_candidate=self._probe_tier3_proxy_delay_candidate,
            )
            if (
                probe_run.indeterminate_proxy_names
                and current.qualified_count
                + len(probe_run.successful_results)
                < required
            ):
                raise _RuntimeProbeBudgetUnavailable(
                    "Bastion Layer qualification is waiting for probe capacity"
                )
            now = time.monotonic()
            with self._tier3_runtime_qualification_lock:
                for _delay, node, _proxy_name, probe_url in probe_run.successful_results:
                    identity = self._node_identity_text(node)
                    signature = semantics.get(identity)
                    if not signature:
                        continue
                    self._tier3_runtime_qualified[identity] = {
                        "proxy_signature": tuple(signature),
                        "qualified_at_monotonic": now,
                        "expires_at_monotonic": (
                            now + self._tier3_runtime_qualification_ttl_seconds
                        ),
                        "probe_endpoint": self._safe_probe_endpoint_label(probe_url),
                    }
        return self._publish_tier3_runtime_qualification()

    @staticmethod
    def _core_export_marker_tier_signatures(
        marker: tuple[Any, ...] | None,
    ) -> dict[str, set[str]]:
        signatures: dict[str, set[str]] = {
            "tier1": set(),
            "tier2": set(),
            "tier3": set(),
            "exit": set(),
        }
        if not isinstance(marker, tuple):
            return signatures
        for item in marker:
            if not isinstance(item, tuple) or len(item) != 2:
                continue
            tier_id, values = item
            if tier_id not in signatures or not isinstance(values, tuple):
                continue
            signatures[tier_id] = {repr(value) for value in values}
        return signatures

    def _core_export_removes_loaded_proxy(
        self,
        current_marker: tuple[Any, ...] | None,
    ) -> bool:
        previous = self._core_export_marker_tier_signatures(
            self._last_core_export_sync_marker
        )
        current = self._core_export_marker_tier_signatures(current_marker)
        return any(previous[tier_id] - current[tier_id] for tier_id in previous)

    def _tier3_export_removes_last_synced_proxy(self) -> bool:
        """Fallback stale-export guard when the full loaded marker is absent.

        ``_last_synced_tier3_nodes`` predates the full cross-tier marker and can
        still be the only trustworthy description of the Tier3 leaves loaded
        by an already-running Core.  A failed reload must not roll back to that
        config after one of those healthy leaves disappeared from the private
        ALIVE/SLOW export.
        """

        limit = self._mihomo_tier3_export_limit()
        previous_nodes = [
            node
            for node in self._last_synced_tier3_nodes
            if getattr(node, "status", None) in {NodeStatus.ALIVE, NodeStatus.SLOW}
        ]
        if limit is not None:
            previous_nodes = previous_nodes[:limit]
        if not previous_nodes:
            return False
        current_nodes = self._tier3_nodes_for_core_export(limit)

        def stable_identity(node: Any) -> tuple[Any, ...]:
            key = getattr(node, "dedupe_key", None)
            if isinstance(key, tuple):
                return key
            return tier3_export_signature([node])[0]

        previous = {stable_identity(node) for node in previous_nodes}
        current = {stable_identity(node) for node in current_nodes}
        return bool(previous - current)

    def _tier3_core_sync_marker(self) -> tuple[Any, ...] | None:
        manager = self.manager
        tier3_enabled = getattr(manager, "_tier3_enabled", None)
        if not manager or not callable(tier3_enabled) or not tier3_enabled():
            return None
        return self._tier3_committed_pool_signature()

    def _tier3_core_sync_retry_interval(self) -> float:
        return tier3_core_sync_retry_interval(self.config)

    def _tier3_core_sync_failure_is_recent(self, marker: tuple[Any, ...] | None) -> bool:
        return tier3_core_sync_failure_is_recent(
            marker=marker,
            last_failed_marker=self._last_failed_tier3_core_sync_marker,
            last_failed_at=self._last_failed_tier3_core_sync_at,
            now=time.monotonic(),
            retry_interval=self._tier3_core_sync_retry_interval(),
        )

    def _tier3_standby_activation_key(self) -> tuple[Any, ...]:
        """Return the immutable contract that owns one standby baseline."""

        runner = getattr(self, "core_runner", None)
        try:
            status = runner.status() if runner is not None else {}
        except Exception:
            status = {}
        lifecycle_lock = getattr(self, "_core_lifecycle_lock", None)
        with lifecycle_lock if lifecycle_lock is not None else nullcontext():
            core_generation = int(getattr(self, "_core_generation", 0) or 0)
        route_lock = getattr(self, "_runtime_route_snapshot_lock", None)
        with route_lock if route_lock is not None else nullcontext():
            snapshot = getattr(self, "_runtime_route_snapshot", None)
            payload = getattr(self, "_runtime_route_snapshot_payload", None)
            inventory = getattr(self, "_runtime_core_inventory_snapshot", None)
            loaded_contract = getattr(
                self,
                "_runtime_loaded_export_contract",
                None,
            )
            network_epoch = int(
                getattr(self, "_runtime_network_context_epoch", 0) or 0
            )
        contract = loaded_contract if isinstance(loaded_contract, dict) else {}
        semantic_digest = str(
            getattr(snapshot, "semantic_digest", "")
            or contract.get("semantic_digest")
            or ""
        )
        logical_route: tuple[Any, ...] = ()
        if isinstance(payload, dict):
            controller_payload = payload.get("proxies")
            proxy_map = payload.get("proxy_map")
            try:
                logical_route = self._runtime_final_exit_selection_signature(
                    controller_payload,
                    proxy_map if isinstance(proxy_map, dict) else {},
                )
            except Exception:
                logical_route = ()
        inventory_signature: tuple[Any, ...] = ("", ())
        if isinstance(inventory, CoreInventorySnapshot):
            inventory_signature = (
                str(inventory.provider_version or ""),
                tuple(ref.key for ref in inventory.members),
            )
        return (
            int(status.get("process_generation") or 0),
            core_generation,
            semantic_digest,
            logical_route,
            inventory_signature,
            network_epoch,
            int(getattr(self, "_runtime_selector_intent_revision", 0) or 0),
        )

    def _reset_tier3_standby_activation_failure(self) -> None:
        with self._tier3_egress_activation_lock:
            self._tier3_standby_activation_failure_key = None
            self._tier3_standby_activation_retry_stage = 0
            self._tier3_standby_activation_retry_at = 0.0
            self._tier3_standby_activation_facility_hold = False
            self._tier3_standby_activation_hold_kind = ""
            self._tier3_standby_activation_last_reason = ""
            self._tier3_runtime_qualification_retry_at = 0.0

    def _record_tier3_standby_activation_failure(
        self,
        reason: str,
        *,
        authority_key: tuple[Any, ...] | None = None,
    ) -> dict[str, Any]:
        """Event-gate one failed immutable activation contract."""

        failure_key = (
            tuple(authority_key)
            if isinstance(authority_key, tuple)
            else self._tier3_standby_activation_key()
        )
        local_fault = (
            self._runtime_facility_hold_reason()
            if self._runtime_local_data_plane_blocked()
            else ""
        )
        with self._tier3_egress_activation_lock:
            if self._tier3_standby_activation_failure_key != failure_key:
                self._tier3_standby_activation_failure_key = failure_key
                self._tier3_standby_activation_retry_stage = 0
                self._tier3_standby_activation_facility_hold = False
                self._tier3_standby_activation_hold_kind = ""
            if local_fault:
                hold_kind = "facility_hold"
            else:
                hold_kind = "activation_hold"
            # A failed immutable route has already consumed its activation
            # transaction.  Periodic monitor/heartbeat ticks are not new
            # evidence and therefore cannot schedule the former 1/2/5 replay.
            # `_maybe_retry_tier3_standby_activation` reopens this only after
            # the loaded route/Core/provider contract, network context, or
            # manual selector intent changes the complete failure key.
            retry_at = 0.0
            self._tier3_standby_activation_retry_stage = 0
            self._tier3_standby_activation_retry_at = 0.0
            self._tier3_standby_activation_facility_hold = True
            self._tier3_standby_activation_hold_kind = hold_kind
            self._tier3_standby_activation_last_reason = str(reason or "")
            self._tier3_runtime_qualification_retry_at = float("inf")
            return {
                "failure_key": failure_key,
                "retry_stage": int(self._tier3_standby_activation_retry_stage),
                "retry_at": float(retry_at),
                "facility_hold": True,
                "hold_kind": hold_kind,
                "reason": local_fault or str(reason or ""),
            }

    def _record_tier3_controller_hold(
        self,
        reason: str,
        *,
        authority_key: tuple[Any, ...] | None = None,
    ) -> dict[str, Any]:
        """Event-gate activation after a bounded controller readback failure."""

        failure_key = (
            tuple(authority_key)
            if isinstance(authority_key, tuple)
            else self._tier3_standby_activation_key()
        )
        activation_lock = getattr(self, "_tier3_egress_activation_lock", None)
        with activation_lock if activation_lock is not None else nullcontext():
            self._tier3_standby_activation_failure_key = failure_key
            self._tier3_standby_activation_retry_at = 0.0
            self._tier3_standby_activation_facility_hold = True
            self._tier3_standby_activation_hold_kind = "controller_hold"
            self._tier3_standby_activation_last_reason = str(reason or "")
            self._tier3_runtime_qualification_retry_at = float("inf")
            return {
                "failure_key": failure_key,
                "retry_stage": int(
                    getattr(self, "_tier3_standby_activation_retry_stage", 0)
                    or 0
                ),
                "retry_at": 0.0,
                "facility_hold": False,
                "hold_kind": "controller_hold",
                "reason": str(reason or ""),
            }

    def _record_tier3_standby_activation_indeterminate(
        self,
        reason: str,
        *,
        authority_key: tuple[Any, ...] | None = None,
    ) -> dict[str, Any]:
        """Event-gate an indeterminate immutable activation contract."""

        failure_key = (
            tuple(authority_key)
            if isinstance(authority_key, tuple)
            else self._tier3_standby_activation_key()
        )
        with self._tier3_egress_activation_lock:
            same_key = self._tier3_standby_activation_failure_key == failure_key
            if not same_key:
                self._tier3_standby_activation_failure_key = failure_key
                self._tier3_standby_activation_retry_stage = 0
                self._tier3_standby_activation_facility_hold = False
                self._tier3_standby_activation_hold_kind = ""
            # Capacity/controller uncertainty is neutral evidence, but polling
            # the same route every 250 ms does not make it authoritative.  Keep
            # one terminal wait state until the complete failure key changes.
            facility_hold = True
            retry_at = 0.0
            self._tier3_standby_activation_retry_at = 0.0
            self._tier3_standby_activation_facility_hold = True
            self._tier3_standby_activation_hold_kind = "activation_hold"
            self._tier3_standby_activation_last_reason = str(reason or "")
            self._tier3_runtime_qualification_retry_at = float("inf")
            return {
                "failure_key": failure_key,
                "retry_stage": int(self._tier3_standby_activation_retry_stage),
                "retry_at": retry_at,
                "facility_hold": facility_hold,
                "reason": str(reason or ""),
                "indeterminate": True,
            }

    def _publish_tier3_controller_hold(
        self,
        reason: str,
        *,
        authority_key: tuple[Any, ...] | None = None,
    ) -> dict[str, Any]:
        public_reason = str(reason or "Mihomo route state is unavailable")
        state = self._record_tier3_controller_hold(
            public_reason,
            authority_key=authority_key,
        )
        non_gateway_serving = self._runtime_non_gateway_serving_active()
        if non_gateway_serving:
            self._publish_non_gateway_serving(
                "Automatic switching is waiting for route ownership"
            )
        else:
            self._set_effective_egress_readiness_state(None, public_reason)
            self._publish_runtime_egress_readiness(
                RuntimeEgressReadinessState.CONTROLLER_HOLD,
                validation_active=False,
                reason=public_reason,
            )
        manager = getattr(self, "manager", None)
        runner = getattr(self, "core_runner", None)
        if manager is not None:
            with manager.lock:
                report = ensure_tier3_collection_report(manager)
                report["core_process_running"] = bool(
                    runner is not None and runner.is_running()
                )
                report["core_standby"] = bool(
                    not non_gateway_serving
                    and runner is not None
                    and runner.is_running()
                )
                report["traffic_capture_active"] = bool(
                    non_gateway_serving
                    and self._revalidation_capture_active(
                        self._current_core_runtime_phase()
                    )
                )
                report["core_standby_reason"] = public_reason
                report["controller_hold"] = True
                report["activation_hold"] = False
                report["facility_hold"] = False
        return state

    def _publish_tier3_standby_activation_failure(
        self,
        exc: Exception,
        *,
        authority_key: tuple[Any, ...] | None = None,
    ) -> dict[str, Any]:
        """Publish standby readiness without changing layer or node health."""

        reason = (
            "Bastion Layer standby verification pending "
            f"({type(exc).__name__})"
        )
        state = self._record_tier3_standby_activation_failure(
            reason,
            authority_key=authority_key,
        )
        public_reason = str(state.get("reason") or reason)
        non_gateway_serving = self._runtime_non_gateway_serving_active()
        if non_gateway_serving:
            self._publish_non_gateway_serving(
                "Automatic switching is temporarily unavailable"
            )
        else:
            self._set_effective_egress_readiness_state(None, public_reason)
        hold_kind = str(state.get("hold_kind") or "")
        if hold_kind == "facility_hold":
            readiness_state = RuntimeEgressReadinessState.FACILITY_HOLD
        elif hold_kind == "activation_hold":
            readiness_state = RuntimeEgressReadinessState.ACTIVATION_HOLD
        else:
            readiness_state = RuntimeEgressReadinessState.DATA_PLANE_FAILED
        if not non_gateway_serving:
            self._publish_runtime_egress_readiness(
                readiness_state,
                validation_active=False,
                reason=public_reason,
            )
        manager = self.manager
        runner = self.core_runner
        if manager:
            with manager.lock:
                report = ensure_tier3_collection_report(manager)
                report["core_process_running"] = bool(
                    runner is not None and runner.is_running()
                )
                report["core_standby"] = bool(
                    not non_gateway_serving
                    and runner is not None
                    and runner.is_running()
                )
                report["traffic_capture_active"] = bool(
                    non_gateway_serving
                    and self._revalidation_capture_active(
                        self._current_core_runtime_phase()
                    )
                )
                report["core_standby_reason"] = public_reason
                report["facility_hold"] = bool(
                    hold_kind == "facility_hold"
                )
                report["activation_hold"] = bool(
                    hold_kind == "activation_hold"
                )
                report["controller_hold"] = False
                report["standby_rebase_stage"] = int(state["retry_stage"])
                if isinstance(exc, Tier3RuntimeQualificationError):
                    # Qualification loss is an inventory fact. Ordinary
                    # transport/facility failures must not wake the collector
                    # or manufacture a replacement demand signal.
                    report["background_expansion_due"] = True
                    manager.last_collect_tier3 = 0.0
        return state

    def _record_tier3_initial_activation_stage(
        self,
        stage: str,
        **details: Any,
    ) -> dict[str, Any]:
        """Record bounded, generation-scoped startup activation truth."""

        event = {
            "stage": str(stage or "unknown"),
            "recorded_at_utc": datetime.now(timezone.utc).isoformat(
                timespec="milliseconds"
            )
            .replace("+00:00", "Z"),
            "recorded_at_monotonic": time.monotonic(),
            "runtime_generation": int(
                getattr(self, "_runtime_generation", 0) or 0
            ),
            "core_generation": int(
                getattr(self, "_core_generation", 0) or 0
            ),
        }
        for key, value in details.items():
            if isinstance(value, (str, int, float, bool)) or value is None:
                normalized_key = str(key)
                if normalized_key == "reason" and value is not None:
                    value = redact_diagnostic_text(value)
                event[normalized_key] = value
        event.setdefault("failure_stage", event["stage"])
        event.setdefault("error_type", "")
        event.setdefault("reason", "")
        lock = getattr(self, "_tier3_initial_activation_trace_lock", None)
        with lock if lock is not None else nullcontext():
            current = getattr(self, "_tier3_initial_activation_trace", None)
            trace = dict(current) if isinstance(current, dict) else {}
            events = trace.get("events")
            events = list(events) if isinstance(events, list) else []
            events.append(event)
            trace.update(
                {
                    "path_revision": (
                        _INITIAL_FINAL_EXIT_ACTIVATION_PATH_REVISION
                    ),
                    "revision": int(trace.get("revision", 0) or 0) + 1,
                    "stage": event["stage"],
                    "events": events[-32:],
                }
            )
            self._tier3_initial_activation_trace = trace
            result = copy.deepcopy(trace)
        logger = getattr(self, "logger", None)
        if isinstance(logger, logging.Logger):
            log_raw_diagnostic(
                logger,
                "info",
                "Initial FINAL-EXIT admission stage=%s failure_stage=%s "
                "error_type=%s reason=%s runtime_generation=%d "
                "core_generation=%d activation_generation=%d",
                event["stage"],
                str(event.get("failure_stage") or event["stage"]),
                str(event.get("error_type") or "none"),
                str(event.get("reason") or "none"),
                int(event["runtime_generation"]),
                int(event["core_generation"]),
                int(event.get("activation_generation", 0) or 0),
            )
        return result

    def _tier3_initial_activation_trace_snapshot(self) -> dict[str, Any]:
        lock = getattr(self, "_tier3_initial_activation_trace_lock", None)
        with lock if lock is not None else nullcontext():
            trace = getattr(self, "_tier3_initial_activation_trace", None)
            if not isinstance(trace, dict):
                return {
                    "path_revision": (
                        _INITIAL_FINAL_EXIT_ACTIVATION_PATH_REVISION
                    ),
                    "revision": 0,
                    "stage": "unavailable",
                    "events": [],
                }
            return copy.deepcopy(trace)

    def _mark_tier3_core_process_ready(self, *, core_generation: int) -> None:
        self._record_tier3_initial_activation_stage(
            "formal_no_capture_loaded",
            core_generation=int(core_generation),
        )
        self._reset_tier3_standby_activation_failure()
        marker = self._tier3_core_sync_marker()
        self._mark_tier3_export_sync_complete(marker)
        self._start_deferred_reason = None
        self._start_deferred_is_live = False
        self.last_error = None
        manager = self.manager
        marker_fn = getattr(manager, "mark_tier3_core_running", None) if manager else None
        if callable(marker_fn):
            try:
                marker_fn(effective_egress_ok=None, traffic_capture_active=False)
            except TypeError:
                marker_fn(effective_egress_ok=None)
        self._set_effective_egress_readiness_state(
            None,
            "Bastion Layer core is ready; FINAL-EXIT verification is pending",
        )
        self._publish_runtime_egress_readiness(
            RuntimeEgressReadinessState.ACTIVATION_HOLD,
            validation_active=False,
            reason=(
                "Bastion Layer core is ready; FINAL-EXIT verification is "
                "queued after runtime startup"
            ),
        )
        if manager:
            with manager.lock:
                report = ensure_tier3_collection_report(manager)
                report["core_process_running"] = True
                report["core_generation"] = int(core_generation)
                report["core_standby"] = True
                report["traffic_capture_active"] = False

    def _mark_tier3_export_sync_complete(
        self,
        marker: tuple[Any, ...] | None = None,
    ) -> None:
        current_marker = self._tier3_core_sync_marker() if marker is None else marker
        self._last_tier3_core_sync_marker = current_marker
        self._last_failed_tier3_core_sync_marker = None
        self._last_failed_tier3_core_sync_at = 0.0
        self._mark_core_export_sync_success()
        manager = self.manager
        if manager:
            self._last_synced_tier3_nodes = self._clone_runtime_nodes(
                self._tier3_nodes_for_core_export(
                    self._mihomo_tier3_export_limit()
                )
            )

    def _mark_tier3_provider_sync_complete(
        self,
        marker: tuple[Any, ...] | None = None,
        *,
        notify_route: bool = True,
    ) -> None:
        """Commit a provider-only inventory update without faking a Core load.

        A provider PUT changes neither the main config nor runtime-source
        listener ownership.  In particular it must not call
        ``_mark_runtime_source_transport_loaded`` through the generic
        full-config success path.  ``notify_route`` wakes the Tier3 source
        supply (which also resets its retry backoff); a verified write that
        kept the live pick changed no route, so it does not.
        """

        current_marker = self._tier3_core_sync_marker() if marker is None else marker
        self._last_tier3_core_sync_marker = current_marker
        self._last_failed_tier3_core_sync_marker = None
        self._last_failed_tier3_core_sync_at = 0.0
        self._last_core_export_sync_marker = self._core_export_sync_marker()
        self._last_failed_core_export_sync_marker = None
        self._last_failed_core_export_sync_at = 0.0
        manager = self.manager
        if manager:
            self._last_synced_tier3_nodes = self._clone_runtime_nodes(
                self._tier3_nodes_for_core_export(
                    self._mihomo_tier3_export_limit()
                )
            )
            notify_source_supply = getattr(
                manager,
                "notify_tier3_source_supply_route_changed",
                None,
            )
            if notify_route and callable(notify_source_supply):
                notify_source_supply("core_provider_sync_succeeded")
        try:
            self._queue_node_diagnostic_core_binding_refresh()
        except Exception:
            self._invalidate_node_diagnostic_core_binding()

    def _queue_tier3_egress_activation(self) -> None:
        if not self._runtime_initial_activation_complete():
            self._record_tier3_initial_activation_stage(
                "activation_queued",
                phase=self._current_core_runtime_phase(),
            )
        self._queue_egress_revalidation("activation")

    def _request_initial_egress_admission(self) -> bool:
        """Queue the sole startup admission after the runtime commit.

        Core loading intentionally precedes ``running=True``.  Older recovery
        revisions tried to bridge that ordering with a deferred boolean and a
        Core-generation side channel.  Two concurrent bootstrap promoters
        could then leave a formal no-capture Core with no verifier at all.
        The Core phase is durable authority; before the commit this method is
        a no-op, and after the commit every trigger safely converges on the
        same deduplicated activation request.
        """

        intent_lock = getattr(self, "_runtime_intent_lock", None)
        with intent_lock if intent_lock is not None else nullcontext():
            if not bool(getattr(self, "running", False)):
                return False
            if (
                not bool(getattr(self, "_desired_running", True))
                or bool(getattr(self, "_stop_request_pending", False))
                or self.stop_event.is_set()
            ):
                return False
            self._initial_egress_activation_deferred = False
            self._initial_egress_activation_deferred_core_generation = -1
        runner = getattr(self, "core_runner", None)
        if (
            runner is None
            or not runner.is_running()
            or self._current_core_runtime_phase() != "formal_no_capture"
            or self._runtime_initial_activation_was_completed()
        ):
            return False
        self._queue_tier3_egress_activation()
        return True

    def _start_deferred_initial_egress_admission(
        self,
        *,
        lifecycle_revision: int,
    ) -> bool:
        """Compatibility alias for the single committed-runtime admission."""

        with self._runtime_intent_lock:
            if not (
                self.running
                and self._desired_running
                and not self._stop_request_pending
                and not self.stop_event.is_set()
                and int(self._lifecycle_revision) == int(lifecycle_revision)
            ):
                return False
            self._initial_egress_activation_deferred = False
            self._initial_egress_activation_deferred_core_generation = -1
        return self._request_initial_egress_admission()

    def _maybe_retry_tier3_standby_activation(self) -> None:
        if self._runtime_uses_early_single_coordinator():
            # The repair profile is event-driven.  A failed immutable startup
            # lease is terminal until provider version, Core generation or a
            # user validation request supplies new evidence.
            return
        manager = self.manager
        runner = self.core_runner
        now = time.monotonic()
        if (
            manager is None
            or runner is None
            or not runner.is_running()
            or self._current_core_runtime_phase() != "formal_no_capture"
            or not bool(getattr(manager, "tier3_startup_gate_satisfied", False))
            or self._egress_revalidation_active()
        ):
            return
        if (
            not self._runtime_traffic_capture_wanted()
            and (
                bool(self._tier3_runtime_final_exit_ok)
                or bool(getattr(manager, "effective_egress_ok", False))
            )
        ):
            return
        failure_key = self._tier3_standby_activation_key()
        with self._tier3_egress_activation_lock:
            recorded_key = self._tier3_standby_activation_failure_key
            if recorded_key is not None and recorded_key != failure_key:
                self._tier3_standby_activation_failure_key = None
                self._tier3_standby_activation_retry_stage = 0
                self._tier3_standby_activation_retry_at = 0.0
                self._tier3_standby_activation_facility_hold = False
                self._tier3_standby_activation_hold_kind = ""
                self._tier3_standby_activation_last_reason = ""
                self._tier3_runtime_qualification_retry_at = 0.0
                recorded_key = None
            retry_at = float(self._tier3_standby_activation_retry_at)
            facility_hold = bool(
                self._tier3_standby_activation_facility_hold
            )
        if recorded_key is not None and now < retry_at:
            return
        if recorded_key is not None and facility_hold and retry_at <= 0.0:
            return
        if self._runtime_local_data_plane_blocked():
            state = self._record_tier3_standby_activation_failure(
                "local Mihomo listener facility is unavailable"
            )
            self._set_effective_egress_readiness_state(
                None,
                str(state.get("reason") or "runtime facility hold"),
            )
            return
        self._queue_tier3_egress_activation()

    def _maybe_revalidate_tier3_runtime_qualification(self) -> None:
        if self._runtime_uses_early_single_coordinator():
            # Layer health checks remain Manager-owned.  The rollback profile
            # does not turn the selected-leaf qualification TTL into a
            # periodic FINAL-EXIT 204 loop while the application is idle.
            return
        runner = self.core_runner
        now = time.monotonic()
        phase = self._current_core_runtime_phase()
        phase_is_qualified_runtime = bool(
            phase == "formal_capture"
            or (
                phase == "formal_no_capture"
                and not self._runtime_traffic_capture_wanted()
            )
        )
        if (
            runner is None
            or not runner.is_running()
            or not self._tier3_is_primary_export()
            or not phase_is_qualified_runtime
            or self._egress_revalidation_active()
        ):
            return
        with self._tier3_runtime_qualification_lock:
            evidence = self._tier3_selected_leaf_evidence
            config_digest = str(self._tier3_runtime_config_digest)
            monitor_at = float(
                self._tier3_runtime_qualification_monitor_at or 0.0
            )
        if evidence is None:
            return
        if monitor_at <= 0.0:
            monitor_at = now + self._tier3_runtime_qualification_ttl_seconds
            with self._tier3_runtime_qualification_lock:
                self._tier3_runtime_qualification_monitor_at = monitor_at
        if now < monitor_at:
            return
        with self._core_lifecycle_lock:
            core_generation = int(self._core_generation)
        revalidation_key = (core_generation, config_digest, evidence)
        with self._tier3_runtime_qualification_lock:
            if self._tier3_runtime_last_revalidation_key == revalidation_key:
                return
            self._tier3_runtime_last_revalidation_key = revalidation_key
            self._tier3_runtime_qualification_monitor_at = (
                now + self._tier3_runtime_qualification_ttl_seconds
            )
        self._queue_incremental_egress_recheck()

    def _queue_incremental_egress_recheck(self) -> None:
        if self._runtime_uses_early_single_coordinator():
            phase, capture_active = self._revalidation_runtime_capture_state()
            if (phase == "formal_capture") != bool(capture_active):
                self._record_revalidation_lifecycle_diagnostic(
                    "Core revalidation lifecycle invariant failed "
                    f"(source=rollback_settle phase={phase} "
                    f"capture_active={capture_active})",
                    fail_closed=True,
                )
                return
            # The stability rollback has no steady-state automatic
            # revalidation.  Settle the mutation as an explicit, non-busy
            # terminal state so an old route-change request cannot leave the
            # UI or stop path waiting for a verifier that will never run.
            reason = (
                "FINAL-EXIT route changed; automatic runtime revalidation "
                "is disabled"
            )
            self._set_effective_egress_readiness_state(None, reason)
            self._publish_runtime_egress_readiness(
                RuntimeEgressReadinessState.CONTROLLER_HOLD,
                validation_active=False,
                reason=reason,
            )
            return
        if not self._runtime_recovery_is_armed():
            if self._runtime_initial_activation_was_completed():
                self._queue_egress_revalidation("incremental")
                return
            if self._runtime_initial_activation_complete():
                self._queue_runtime_route_snapshot_refresh()
            return
        self._queue_egress_revalidation("incremental")

    def _revalidation_capture_active(self, phase: str) -> bool:
        """Return the independently published capture truth when available."""
        manager = self.manager
        if (
            manager is not None
            and self._tier3_is_primary_export()
            and hasattr(manager, "tier3_traffic_capture_active")
        ):
            return bool(getattr(manager, "tier3_traffic_capture_active", False))
        # Non-Tier3-primary runtimes do not publish the Tier3 capture bit.  In
        # that case the runtime-owned phase remains the capture authority.
        return str(phase) == "formal_capture"

    def _revalidation_runtime_capture_state(self) -> tuple[str, bool]:
        # System-proxy admission can publish capture without ApplyConfig.
        # Read the phase and Manager capture bit under the same lock used by
        # that commit so a provider callback cannot observe half of it.
        manager = getattr(self, "manager", None)
        manager_lock = getattr(manager, "lock", None)
        with manager_lock if manager_lock is not None else nullcontext():
            phase = self._current_core_runtime_phase()
            return phase, self._revalidation_capture_active(phase)

    def _record_revalidation_lifecycle_diagnostic(
        self,
        reason: str,
        *,
        fail_closed: bool,
    ) -> None:
        message = str(reason or "Core revalidation lifecycle invariant failed")
        log_raw_diagnostic(
            self.logger,
            "error",
            "%s",
            message,
        )
        manager = self.manager
        if manager is not None:
            try:
                lock = getattr(manager, "lock", nullcontext())
                with lock:
                    report = ensure_tier3_collection_report(manager)
                    key = (
                        "core_revalidation_invariant_error"
                        if fail_closed
                        else "core_revalidation_mode_correction"
                    )
                    report[key] = message
            except Exception:
                log_raw_diagnostic(
                    self.logger,
                    "warning",
                    "Could not publish Core revalidation lifecycle diagnostic",
                    exc_info=True,
                )
        if fail_closed:
            self.last_error = message
            self._set_effective_egress_state(False, message)

    def _revalidation_mode_for_runtime_state(
        self,
        requested_mode: str,
        *,
        source: str,
    ) -> str | None:
        requested = "activation" if str(requested_mode) == "activation" else "incremental"
        phase, capture_active = self._revalidation_runtime_capture_state()
        if phase == "formal_no_capture" and not capture_active:
            required = (
                "incremental"
                if self._runtime_initial_activation_was_completed()
                else "activation"
            )
        elif phase == "formal_capture" and capture_active:
            required = "incremental"
        else:
            self._record_revalidation_lifecycle_diagnostic(
                "Core revalidation lifecycle invariant failed "
                f"(source={source} phase={phase} capture_active={capture_active})",
                fail_closed=True,
            )
            return None
        if requested != required:
            self._record_revalidation_lifecycle_diagnostic(
                "Core revalidation request corrected to the lifecycle-owned mode "
                f"(source={source} requested={requested} mode={required} "
                f"phase={phase} capture_active={capture_active} "
                f"capture_wanted={self._runtime_traffic_capture_wanted()})",
                fail_closed=False,
            )
        return required

    def _queue_egress_revalidation(self, mode: str) -> None:
        requested_mode = self._revalidation_mode_for_runtime_state(
            mode,
            source="queue",
        )
        if requested_mode is None:
            return
        if (
            self._runtime_uses_early_single_coordinator()
            and requested_mode != "activation"
        ):
            return
        authority_key = self._tier3_standby_activation_key()
        request_key = (requested_mode, authority_key)
        thread: threading.Thread | None = None
        activation_generation = -1
        with self._tier3_egress_activation_lock:
            if self.stop_event.is_set():
                self._tier3_egress_activation_pending = False
                self._tier3_egress_activation_pending_mode = ""
                self._tier3_egress_activation_pending_key = None
                return
            if (
                self._tier3_standby_activation_failure_key == authority_key
                and self._tier3_standby_activation_facility_hold
            ):
                # This immutable authority already owns a terminal/neutral
                # result. Polling, heartbeat and unchanged pool callbacks are
                # not new evidence and must not reopen the transaction.
                return
            if (
                self._tier3_egress_activation_pending
                and getattr(
                    self,
                    "_tier3_egress_activation_pending_key",
                    None,
                )
                == request_key
            ):
                return
            if (
                self._tier3_egress_activation_worker_running
                and getattr(
                    self,
                    "_tier3_egress_activation_active_key",
                    None,
                )
                == request_key
            ):
                return
            self._tier3_egress_activation_pending = True
            # The lifecycle contract already picked the only legal mode for
            # the current phase.  In particular, an activation request can no
            # longer override a pending incremental recheck on a live Core.
            self._tier3_egress_activation_pending_mode = requested_mode
            self._tier3_egress_activation_pending_key = request_key
            if self._tier3_egress_activation_worker_running:
                # A provider/authority refresh is a successor request, not a
                # cancellation authority.  Advancing the active generation
                # here used to abort the only startup lease and leave the UI
                # permanently validating.  The worker advances the generation
                # only when it actually claims this successor.
                return
            self._tier3_egress_activation_generation += 1
            activation_generation = int(
                self._tier3_egress_activation_generation
            )
            self._tier3_egress_activation_worker_running = True
            thread = threading.Thread(
                target=self._tier3_egress_activation_worker,
                name="desktop-tier3-egress-activation",
                daemon=True,
            )
            self._tier3_egress_activation_thread = thread
        if thread is None:
            return
        try:
            thread.start()
        except Exception as exc:
            with self._tier3_egress_activation_lock:
                if (
                    self._tier3_egress_activation_thread is thread
                    and int(self._tier3_egress_activation_generation)
                    == activation_generation
                ):
                    self._tier3_egress_activation_pending = False
                    self._tier3_egress_activation_pending_mode = ""
                    self._tier3_egress_activation_pending_key = None
                    self._tier3_egress_activation_worker_running = False
                    self._tier3_egress_activation_thread = None
            reason = (
                "FINAL-EXIT verification worker could not start "
                f"({type(exc).__name__})"
            )
            self._publish_runtime_egress_readiness(
                RuntimeEgressReadinessState.DATA_PLANE_FAILED,
                validation_active=False,
                reason=reason,
                expected_activation_generation=activation_generation,
                require_no_activation_successor=True,
                effective_ok=False,
            )
            self._record_tier3_initial_activation_stage(
                "worker_start_failed",
                activation_generation=activation_generation,
                error_type=type(exc).__name__,
            )

    def _coalesce_pre_ready_activation_successor(
        self,
        admission_lease: _InitialEgressAdmissionLease,
    ) -> bool:
        """Consume pre-READY refresh requests already covered by READY.

        Provider append and authority refresh callbacks may arrive while the
        sole startup lease is proving the route.  They are not cancellation
        authorities and, once that lease has committed a verified route, must
        not be reclassified as a steady-state incremental validation that can
        immediately downgrade READY again.  Inventory publication itself has
        already happened before these callbacks queue activation; only the
        redundant verifier request is removed here.
        """

        if not self._runtime_uses_early_single_coordinator():
            return False
        activation_lock = getattr(self, "_tier3_egress_activation_lock", None)
        if activation_lock is None:
            # Narrow injected activation fixtures may execute the transaction
            # directly without installing the worker lifecycle.  They have no
            # successor to coalesce.
            return False
        coalesced = False
        with activation_lock:
            if (
                int(self._tier3_egress_activation_active_generation)
                != int(admission_lease.activation_generation)
            ):
                return False
            if self._tier3_egress_activation_pending:
                self._tier3_egress_activation_pending = False
                self._tier3_egress_activation_pending_mode = ""
                self._tier3_egress_activation_pending_key = None
                coalesced = True
        if coalesced:
            self._record_tier3_initial_activation_stage(
                "ready_successor_coalesced",
                activation_generation=admission_lease.activation_generation,
            )
        return coalesced

    def _wait_for_tier3_egress_activation(self, timeout: float = 5.0) -> bool:
        # Pool/Core mutation can publish its marker immediately before it
        # queues the verifier. A single read of the previous worker handle can
        # therefore return while effective egress is still the intentional
        # `None` mutation state. Re-read the lifecycle until both the mutation
        # and its current verifier settle under one shared deadline.
        deadline = time.monotonic() + max(0.0, float(timeout))
        while True:
            with self._tier3_egress_activation_lock:
                thread = self._tier3_egress_activation_thread
                activation_pending = bool(
                    self._tier3_egress_activation_pending
                    or self._tier3_egress_activation_worker_running
                    or self._tier3_egress_activation_active_mode
                )
            with self._tier3_pool_sync_lock:
                pool_sync_pending = bool(
                    self._tier3_pool_sync_pending
                    or self._tier3_pool_sync_worker_running
                )
            mutation_pending = self._core_route_mutation_is_pending()
            if (
                not activation_pending
                and not pool_sync_pending
                and not mutation_pending
            ):
                return True
            if thread is threading.current_thread():
                return False
            remaining = deadline - time.monotonic()
            if remaining <= 0.0:
                return False
            if thread is not None and thread.is_alive():
                thread.join(timeout=min(0.05, remaining))
            else:
                self.stop_event.wait(min(0.01, remaining))

    def _egress_revalidation_active(self) -> bool:
        with self._tier3_egress_activation_lock:
            return bool(
                self._tier3_egress_activation_pending
                or bool(
                    getattr(
                        self,
                        "_tier3_egress_activation_worker_running",
                        False,
                    )
                )
                or self._tier3_egress_activation_active_mode
            )

    def _tier3_egress_activation_is_current(
        self,
        activation_generation: int,
        runner: Any,
        core_generation: int | None = None,
    ) -> bool:
        with self._tier3_egress_activation_lock:
            generation_current = (
                int(activation_generation)
                == int(self._tier3_egress_activation_generation)
            )
        with self._core_lifecycle_lock:
            core_generation_current = self._core_generation
        return bool(
            generation_current
            and (
                core_generation is None
                or int(core_generation) == int(core_generation_current)
            )
            and not self.stop_event.is_set()
            and self.core_runner is runner
            and runner.is_running()
        )

    @staticmethod
    def _background_thread_is_alive(thread: Any | None) -> bool:
        if thread is None:
            return False
        try:
            return bool(thread.is_alive())
        except Exception:
            return True

    def _runtime_background_activity(self) -> dict[str, bool]:
        with self._tier3_egress_activation_lock:
            egress_thread = self._tier3_egress_activation_thread
            egress_running = bool(self._tier3_egress_activation_worker_running)
        with self._tier3_pool_sync_lock:
            pool_thread = self._tier3_pool_sync_thread
            pool_running = bool(self._tier3_pool_sync_worker_running)
        with self._tier3_core_gate_lock:
            gate_thread = self._tier3_core_gate_thread
            gate_running = bool(self._tier3_core_gate_worker_running)
        with self._exit_quality_static_refresh_lock:
            exit_quality_thread = self._exit_quality_static_refresh_thread
        with self._runtime_failure_monitor_lock:
            failure_monitor_thread = self._runtime_failure_monitor_thread
            failure_recovery_threads = tuple(
                self._runtime_failure_recovery_threads
            )
        return {
            "tier3_egress_activation": bool(
                egress_running
                or self._background_thread_is_alive(egress_thread)
            ),
            "tier3_pool_sync": bool(
                pool_running
                or self._background_thread_is_alive(pool_thread)
            ),
            "tier3_core_gate": bool(
                gate_running
                or self._background_thread_is_alive(gate_thread)
            ),
            "exit_quality_refresh": self._background_thread_is_alive(
                exit_quality_thread
            ),
            "runtime_failure_monitor": self._background_thread_is_alive(
                failure_monitor_thread
            ),
            "runtime_failure_recovery": any(
                self._background_thread_is_alive(worker)
                for worker in failure_recovery_threads
            ),
        }

    def _wait_for_runtime_background_work(
        self,
        *,
        timeout: float,
    ) -> dict[str, bool]:
        self._cancel_runtime_background_work()
        deadline = time.monotonic() + max(0.0, float(timeout))
        with self._tier3_egress_activation_lock:
            egress_thread = self._tier3_egress_activation_thread
        with self._tier3_pool_sync_lock:
            pool_thread = self._tier3_pool_sync_thread
        with self._tier3_core_gate_lock:
            gate_thread = self._tier3_core_gate_thread
        with self._exit_quality_static_refresh_lock:
            exit_quality_thread = self._exit_quality_static_refresh_thread
        with self._runtime_failure_monitor_lock:
            failure_monitor_thread = self._runtime_failure_monitor_thread
            failure_recovery_threads = tuple(
                self._runtime_failure_recovery_threads
            )
        seen: set[int] = set()
        for worker in (
            egress_thread,
            pool_thread,
            gate_thread,
            exit_quality_thread,
            failure_monitor_thread,
            *failure_recovery_threads,
        ):
            if worker is None or worker is threading.current_thread():
                continue
            identity = id(worker)
            if identity in seen:
                continue
            seen.add(identity)
            if not self._background_thread_is_alive(worker):
                continue
            remaining = max(0.0, deadline - time.monotonic())
            if remaining <= 0.0:
                break
            try:
                worker.join(timeout=remaining)
            except Exception:
                break
        return self._runtime_background_activity()

    def _publish_verified_incremental_egress(
        self,
        *,
        mutation_binding: CurrentMutationBinding | None,
        facility_epoch: int,
        recovery_ticket: _RuntimeRecoveryTicket | None = None,
        deadline_monotonic: float | None = None,
    ) -> float | None:
        """Publish readiness without racing a new facility transition."""

        monitor_lock = getattr(self, "_runtime_failure_monitor_lock", None)
        if monitor_lock is None:
            monitor_lock = threading.RLock()
            self._runtime_failure_monitor_lock = monitor_lock
        with monitor_lock:
            if (
                int(getattr(self, "_runtime_facility_epoch", 0) or 0)
                != int(facility_epoch)
                or self._runtime_facility_hold_reason()
                or (
                    mutation_binding is not None
                    and not self._runtime_mutation_binding_is_current(
                        mutation_binding
                    )
                )
                or (
                    recovery_ticket is not None
                    and not self._runtime_recovery_ticket_is_current(
                        recovery_ticket,
                        require_open=True,
                        deadline_monotonic=deadline_monotonic,
                    )
                )
            ):
                return None
            published_at = self._runtime_recovery_now()
            self._set_effective_egress_state(True, "")
            self._publish_runtime_egress_readiness(
                RuntimeEgressReadinessState.READY,
                validation_active=False,
            )
            return published_at

    def _runtime_fixed_gateway_route_active(self) -> bool:
        """Return whether policy or loaded authority owns a fixed Gateway."""

        if self._active_gateway_policy_enabled():
            return True
        route_lock = getattr(self, "_runtime_route_snapshot_lock", None)
        with route_lock if route_lock is not None else nullcontext():
            snapshot = getattr(self, "_runtime_route_snapshot", None)
            payload = getattr(self, "_runtime_route_snapshot_payload", None)
            payload = copy.deepcopy(payload) if isinstance(payload, dict) else None
        if not isinstance(snapshot, CoreLoadedRouteSnapshot) or not isinstance(
            payload,
            dict,
        ):
            return False
        try:
            binding = self._runtime_route_binding_for_outbound(
                snapshot,
                payload,
                "FINAL-EXIT",
            )
        except Exception:
            return False
        return bool(binding is not None and binding.node.pool_kind == "gateway")

    def _runtime_non_gateway_serving_active(self) -> bool:
        """Return whether user traffic is attached independently of fallback arm."""

        if self._runtime_fixed_gateway_route_active():
            return False
        if not self._runtime_initial_activation_was_completed():
            return False
        runner = getattr(self, "core_runner", None)
        if runner is None or not runner.is_running():
            return False
        phase = self._current_core_runtime_phase()
        if self._runtime_traffic_capture_wanted():
            return bool(
                phase == "formal_capture"
                and self._revalidation_capture_active(phase)
            )
        return phase in {"formal_no_capture", "formal_capture"}

    def _publish_non_gateway_serving(
        self,
        reason: str = "Automatic switching is preparing",
    ) -> RuntimeEgressReadiness:
        """Preserve an admitted non-Gateway data plane while fallback is unarmed."""

        self._set_effective_egress_readiness_state(True, "")
        return self._publish_runtime_egress_readiness(
            RuntimeEgressReadinessState.SERVING,
            validation_active=False,
            reason=str(reason or "Automatic switching is preparing"),
        )

    def _run_initial_non_gateway_serving(
        self,
        *,
        runner: Any,
        activation_generation: int,
        core_generation: int,
        selector_intent_revision: int,
        worker_token: tuple[int, ...],
    ) -> dict[str, Any]:
        """Compatibility entrypoint for the authority-first startup path."""

        return self._run_initial_egress_activation(
            runner=runner,
            activation_generation=activation_generation,
            core_generation=core_generation,
            selector_intent_revision=selector_intent_revision,
            worker_token=worker_token,
        )
    def _recover_initial_final_exit(
        self,
        *,
        binding_state: tuple[
            RuntimeRouteBinding,
            CoreLoadedRouteSnapshot,
            dict[str, Any],
        ],
        probe_failure: Exception,
        owner: _RuntimeActivationRecoveryOwner,
    ) -> tuple[
        dict[str, Any],
        tuple[
            RuntimeRouteBinding,
            CoreLoadedRouteSnapshot,
            dict[str, Any],
        ],
    ]:
        """Run the canonical incident transaction for the first 204 failure."""

        original_binding, original_snapshot, original_payload = binding_state
        if self._runtime_facility_hold_reason():
            raise RuntimeActivationRecoveryError(
                RuntimeRecoveryOutcome(
                    status=RuntimeRecoveryStatus.FACILITY_HOLD,
                    incident_id="",
                    route_epoch=int(original_binding.route_epoch),
                    budget_ms=0,
                    reason="local_facility_unavailable",
                    from_ref=original_binding.node,
                )
            ) from probe_failure
        if not self._runtime_activation_recovery_owner_is_current(
            owner,
            binding=original_binding,
            snapshot=original_snapshot,
        ):
            raise RuntimeStartCancelled(
                "initial FINAL-EXIT recovery authority was superseded"
            ) from probe_failure
        submission = self._submit_current_route_probe_failure(
            "Initial FINAL-EXIT 204 failed: "
            f"{type(probe_failure).__name__}",
            source="activation_final_exit",
            binding_state=binding_state,
            binding_captured=True,
            activation_owner=owner,
        )
        if not isinstance(submission, _RuntimeRecoveryTicket):
            if not self._runtime_activation_recovery_owner_is_current(
                owner,
                binding=original_binding,
                snapshot=original_snapshot,
            ):
                raise RuntimeStartCancelled(
                    "initial FINAL-EXIT recovery authority was superseded"
                ) from probe_failure
            raise RuntimeControllerReadbackError(
                "Initial FINAL-EXIT failure did not obtain one recovery ticket"
            ) from probe_failure
        outcome = self._wait_runtime_recovery_outcome(submission)
        if outcome is None:
            raise RuntimeControllerReadbackError(
                "Initial FINAL-EXIT recovery reached no authoritative outcome"
            ) from probe_failure
        if outcome.status is not RuntimeRecoveryStatus.RECOVERED:
            raise RuntimeActivationRecoveryError(outcome) from probe_failure

        remaining = max(
            0.0,
            min(0.35, owner.deadline_monotonic - self._runtime_recovery_now()),
        )
        if remaining <= 0.0:
            raise RuntimeControllerReadbackError(
                "Initial FINAL-EXIT recovery expired before route readback"
            ) from probe_failure
        rebound = self._refresh_loaded_runtime_authority(
            timeout_seconds=remaining,
            require_managed_final_exit=True,
            worker_token=self._runtime_worker_token(),
        )
        if rebound is None:
            raise RuntimeControllerReadbackError(
                "Recovered FINAL-EXIT route could not be rebound"
            ) from probe_failure
        rebound_snapshot, rebound_payload, rebound_binding = rebound
        if (
            self._runtime_uses_early_single_coordinator()
            and original_binding.node.pool_kind == "gateway"
        ):
            original_underlay = self._runtime_gateway_underlay_binding(
                original_snapshot,
                original_payload,
                original_binding.node,
            )
            rebound_underlay = self._runtime_gateway_underlay_binding(
                rebound_snapshot,
                rebound_payload,
                rebound_binding.node,
            )
            valid_rebound = bool(
                rebound_binding.node.key == original_binding.node.key
                and original_underlay is not None
                and rebound_underlay is not None
                and original_underlay.node.key != rebound_underlay.node.key
                and outcome.to_ref is not None
                and rebound_underlay.node.key == outcome.to_ref.key
                and int(rebound_binding.route_epoch) == int(outcome.route_epoch)
            )
        elif submission.from_ref.pool_kind == "gateway":
            original_underlay = self._runtime_gateway_underlay_binding(
                original_snapshot,
                original_payload,
                original_binding.node,
            )
            rebound_underlay = self._runtime_gateway_underlay_binding(
                rebound_snapshot,
                rebound_payload,
                rebound_binding.node,
            )
            valid_rebound = bool(
                rebound_binding.node.key == submission.from_ref.key
                and original_underlay is not None
                and rebound_underlay is not None
                and original_underlay.node.key != rebound_underlay.node.key
                and outcome.to_ref is not None
                and rebound_underlay.node.key == outcome.to_ref.key
                and int(rebound_binding.route_epoch) == int(outcome.route_epoch)
            )
        else:
            valid_rebound = bool(
                rebound_binding.node.key != submission.from_ref.key
                and outcome.to_ref is not None
                and rebound_binding.node.key == outcome.to_ref.key
                and int(rebound_binding.route_epoch) == int(outcome.route_epoch)
            )
        if not valid_rebound:
            raise RuntimeControllerReadbackError(
                "Recovered FINAL-EXIT route lost its route-epoch CAS"
            ) from probe_failure
        verified_route = getattr(self, "_runtime_last_verified_route", None)
        verified_result = (
            verified_route.get("result")
            if isinstance(verified_route, dict)
            else None
        )
        if not (
            isinstance(verified_route, dict)
            and str(verified_route.get("incident_id") or "")
            == submission.incident_id
            and isinstance(verified_result, dict)
            and int(verified_result.get("status") or 0) == 204
        ):
            raise RuntimeControllerReadbackError(
                "Recovered FINAL-EXIT route has no incident-owned 204 proof"
            ) from probe_failure
        result = dict(verified_result)
        result["runtime_recovery_outcome"] = outcome.to_dict()
        return result, (rebound_binding, rebound_snapshot, rebound_payload)

    def _startup_route_intent_from_snapshot(
        self,
        snapshot: CoreLoadedRouteSnapshot,
    ) -> StartupRouteIntent | None:
        """Freeze the configured startup branch without pinning a fallback leaf."""

        states = {state.name: state for state in snapshot.group_states}
        refs = {ref.proxy_name: ref for ref in snapshot.proxy_nodes}
        final_state = states.get("FINAL-EXIT")
        if final_state is None:
            return None

        def descendants(
            name: str,
            visited: frozenset[str] = frozenset(),
        ) -> tuple[str, ...]:
            normalized = str(name or "").strip()
            if not normalized or builtin_terminal_kind(normalized):
                return ()
            if normalized in refs:
                return (normalized,)
            state = states.get(normalized)
            if state is None or state.name in visited:
                return ()
            next_visited = frozenset((*visited, state.name))
            ordered: list[str] = []
            for member in state.members:
                for leaf in descendants(str(member), next_visited):
                    if leaf not in ordered:
                        ordered.append(leaf)
            return tuple(ordered)

        active_gateway = self._active_gateway_policy_enabled()
        expected_gateway: RuntimeNodeRef | None = None
        selected_gateway_name = ""
        if active_gateway:
            # The member the loaded EXIT-SELECT holds for the saved node.
            selection = self._gateway_selection()
            if selection is None or not selection.active:
                return None
            exit_state = states.get("EXIT-SELECT")
            selected_gateway_name = self._loaded_gateway_member(
                selection,
                members=exit_state.members if exit_state is not None else None,
            )
            if not selected_gateway_name:
                return None
            candidate = refs.get(selected_gateway_name)
            if candidate is None or candidate.pool_kind != "gateway":
                return None
            expected_gateway = candidate

        top_target = ""
        loaded_order: tuple[str, ...] = ()
        for raw_member in final_state.members:
            member = str(raw_member or "").strip()
            if not member or builtin_terminal_kind(member):
                continue
            ordered = descendants(member)
            if active_gateway:
                if selected_gateway_name not in ordered:
                    continue
            elif not any(
                refs.get(name) is not None
                and refs[name].pool_kind != "gateway"
                for name in ordered
            ):
                continue
            top_target = member
            loaded_order = ordered
            break
        if not top_target:
            return None

        selector_actions: list[tuple[str, str, str]] = []

        def selector_path_to(
            group_name: str,
            target_leaf: str,
            visited: frozenset[str] = frozenset(),
        ) -> list[tuple[str, str, str]] | None:
            state = states.get(group_name)
            if state is None or state.name in visited:
                return None
            next_visited = frozenset((*visited, state.name))
            for raw_member in state.members:
                member = str(raw_member or "").strip()
                if member == target_leaf:
                    path: list[tuple[str, str, str]] = []
                elif member in states:
                    path = selector_path_to(member, target_leaf, next_visited)
                    if path is None:
                        continue
                else:
                    continue
                type_name = str(state.type_name or "").casefold()
                if "select" in type_name or "selector" in type_name:
                    path.append((state.name, member, "selector"))
                return path
            return None

        if active_gateway and expected_gateway is not None:
            path = selector_path_to("FINAL-EXIT", expected_gateway.proxy_name)
            if path is None:
                return None
            selector_actions.extend(path)
        else:
            # FINAL-EXIT is the application-owned policy gate. Inner fallback
            # groups remain entirely native so their loaded member order and
            # health semantics are never flattened into startup leaf writes.
            selector_actions.append(("FINAL-EXIT", top_target, "selector"))
        if not selector_actions or len(selector_actions) > 2:
            return None

        provider_version = ""
        route_lock = getattr(self, "_runtime_route_snapshot_lock", None)
        with route_lock if route_lock is not None else nullcontext():
            inventory = getattr(self, "_runtime_core_inventory_snapshot", None)
            if (
                isinstance(inventory, CoreInventorySnapshot)
                and int(inventory.core_generation) == int(snapshot.core_generation)
            ):
                provider_version = str(inventory.provider_version or "")
            if not provider_version:
                contract = getattr(self, "_runtime_loaded_export_contract", None)
                if isinstance(contract, dict):
                    provider_version = str(
                        contract.get("provider_semantic_digest") or ""
                    )

        return StartupRouteIntent(
            actions=tuple(selector_actions),
            top_level_group="FINAL-EXIT",
            top_level_target=top_target,
            expected_gateway_key=(
                tuple(expected_gateway.key)
                if expected_gateway is not None
                else None
            ),
            selector_intent_revision=int(
                getattr(self, "_runtime_selector_intent_revision", 0) or 0
            ),
            provider_version=provider_version,
            loaded_order=tuple(loaded_order),
            snapshot_key=tuple(snapshot.snapshot_key),
        )

    @staticmethod
    def _startup_intent_reaches_group(
        snapshot: CoreLoadedRouteSnapshot,
        intent: StartupRouteIntent,
        expected_group: str,
    ) -> bool:
        graph = {name: tuple(members) for name, members in snapshot.group_graph}
        target = str(expected_group or "")

        def reaches(name: str, visited: frozenset[str]) -> bool:
            normalized = str(name or "").strip()
            if normalized == target:
                return True
            if normalized in visited:
                return False
            members = graph.get(normalized)
            if members is None:
                return False
            next_visited = frozenset((*visited, normalized))
            return any(reaches(str(member), next_visited) for member in members)

        return reaches(intent.top_level_target, frozenset())

    def _apply_startup_route_intent(
        self,
        intent: StartupRouteIntent,
        snapshot: CoreLoadedRouteSnapshot,
        snapshot_payload: dict[str, Any],
        *,
        deadline_monotonic: float,
        worker_token: tuple[int, ...] | None,
        ensure_current: Callable[[str], None] | None = None,
    ) -> tuple[CoreLoadedRouteSnapshot, dict[str, Any], int]:
        """Apply at most two selector branches and authoritatively read them back."""

        if int(
            getattr(self, "_runtime_selector_intent_revision", 0) or 0
        ) != int(intent.selector_intent_revision):
            raise RuntimeStartCancelled(
                "user selector intent superseded startup route intent"
            )
        current_snapshot = snapshot
        current_payload = snapshot_payload
        commits = 0
        for group, target, mode in intent.actions:
            if callable(ensure_current):
                ensure_current("startup route intent replay")
            state = current_snapshot.group_state(group)
            if state is None:
                raise RuntimeControllerReadbackError(
                    f"startup route group {group!r} is absent from Core readback"
                )
            if state.now != target:
                self._apply_runtime_automatic_selection(
                    {
                        "group": group,
                        "target": target,
                        "previous": str(state.now or ""),
                        "mode": mode,
                        "alternative_leaf": "",
                    },
                    deadline_monotonic=deadline_monotonic,
                )
                commits += 1
                authority = self._refresh_loaded_runtime_authority(
                    timeout_seconds=min(
                        0.75,
                        max(0.05, deadline_monotonic - time.monotonic()),
                    ),
                    require_managed_final_exit=False,
                    worker_token=worker_token,
                )
                if authority is None:
                    raise RuntimeControllerReadbackError(
                        "startup route intent has no authoritative readback"
                    )
                current_snapshot, current_payload, _binding = authority
                state = current_snapshot.group_state(group)
            if state is None or state.now != target:
                raise RuntimeControllerReadbackError(
                    f"startup route group {group!r} did not select {target!r}"
                )
        return current_snapshot, current_payload, commits

    def _trigger_startup_native_fallback_health(
        self,
        snapshot: CoreLoadedRouteSnapshot,
        intent: StartupRouteIntent,
        *,
        deadline_monotonic: float,
    ) -> str:
        """Run one native health round without selecting a concrete leaf."""

        if self._node_judgement_policy().group_round_native_timeout:
            return self._trigger_startup_native_fallback_health_native(
                snapshot,
                intent,
                deadline_monotonic=deadline_monotonic,
            )
        remaining = deadline_monotonic - time.monotonic()
        reserve = 5.0 if self._runtime_traffic_capture_wanted() else 1.0
        budget = min(5.0, max(0.0, remaining - reserve))
        if budget < 0.10:
            return "budget_exhausted"
        health_group = self._startup_native_fallback_health_group(
            snapshot,
            intent,
        )
        if not health_group:
            # A direct managed leaf has no native group health state to warm;
            # the mandatory dual mixed-port 204 below is its authority.
            return "direct_leaf"
        try:
            probe_url, _expected_status = self._runtime_group_probe_contract(
                snapshot,
                health_group,
            )
            self.test_group_delay(
                health_group,
                url=probe_url,
                timeout_ms=max(100, int(budget * 1000.0)),
            )
        except Exception as exc:
            logger = getattr(self, "logger", None)
            if isinstance(logger, logging.Logger):
                log_raw_diagnostic(
                    logger,
                    "warning",
                    "Startup fallback healthcheck did not complete: %s",
                    redact_diagnostic_text(exc),
                )
        return "group_healthcheck"

    def _trigger_startup_native_fallback_health_native(
        self,
        snapshot: CoreLoadedRouteSnapshot,
        intent: StartupRouteIntent,
        *,
        deadline_monotonic: float,
    ) -> str:
        """P0-2: the owning group's exact contract at its native timeout.

        The round is never shortened to fit the admission budget.  When the
        budget cannot hold the native timeout plus the reply slack, one round
        runs asynchronously right after READY instead.
        """

        health_group = self._startup_native_fallback_health_group(
            snapshot,
            intent,
        )
        if not health_group:
            # A direct managed leaf has no native group health state to warm;
            # the mandatory dual mixed-port 204 below is its authority.
            return "direct_leaf"
        probe_url, expected_status = self._runtime_group_probe_contract(
            snapshot,
            health_group,
        )
        timeout_ms = self._runtime_group_native_timeout_ms(health_group)
        reserve = 5.0 if self._runtime_traffic_capture_wanted() else 1.0
        available = max(0.0, deadline_monotonic - time.monotonic() - reserve)
        window = timeout_ms / 1000.0 + _NATIVE_GROUP_ROUND_SLACK_SECONDS
        if available < window:
            self._defer_native_group_round(
                group=health_group,
                probe_url=probe_url,
                expected_status=expected_status,
                timeout_ms=timeout_ms,
                source="startup",
            )
            return "group_healthcheck_deferred"
        try:
            self._run_native_group_round(
                health_group,
                probe_url=probe_url,
                expected_status=expected_status,
                timeout_ms=timeout_ms,
                # Queue only as long as the whole round still fits the budget.
                admission_seconds=max(
                    0.0,
                    available - window - _NATIVE_GROUP_ROUND_DISPATCH_SECONDS,
                ),
            )
        except Exception as exc:
            if self._native_group_round_not_issued(exc):
                # The probe slots stayed busy: the budget no longer holds the
                # native window, so one round runs right after READY instead.
                self._defer_native_group_round(
                    group=health_group,
                    probe_url=probe_url,
                    expected_status=expected_status,
                    timeout_ms=timeout_ms,
                    source="startup_queue",
                )
                return "group_healthcheck_deferred"
            logger = getattr(self, "logger", None)
            if isinstance(logger, logging.Logger):
                log_raw_diagnostic(
                    logger,
                    "warning",
                    "Startup fallback healthcheck did not complete: %s",
                    redact_diagnostic_text(exc),
                )
        return "group_healthcheck"

    def _startup_native_fallback_health_group(
        self,
        snapshot: CoreLoadedRouteSnapshot,
        intent: StartupRouteIntent,
        binding: RuntimeRouteBinding | None = None,
    ) -> str:
        """Return the loaded fallback group whose URL contract owns liveness.

        The Tier3B file provider intentionally has no independent health
        contract; ``TIER3-AUTO`` owns the URLTest used by its fallback.  A
        provider healthcheck request can therefore finish (or time out)
        without producing the AliveForTestUrl evidence the group consults.
        Always warm the loaded fallback group itself.
        """

        preferred_chain = (
            tuple(binding.route_chain)
            if isinstance(binding, RuntimeRouteBinding)
            else ()
        )
        for group_name in reversed(preferred_chain):
            state = snapshot.group_state(str(group_name))
            type_name = str(getattr(state, "type_name", "") or "").casefold()
            if state is not None and "fallback" in type_name:
                return str(state.name)
        if self._startup_intent_reaches_group(
            snapshot,
            intent,
            "TIER3-AUTO",
        ):
            return "TIER3-AUTO"
        state = snapshot.group_state(intent.top_level_target)
        type_name = str(getattr(state, "type_name", "") or "").casefold()
        if state is not None and "fallback" in type_name:
            return str(state.name)
        return ""

    def _activate_startup_native_fallback(
        self,
        *,
        snapshot: CoreLoadedRouteSnapshot,
        snapshot_payload: dict[str, Any],
        intent: StartupRouteIntent,
        admission_lease: _InitialEgressAdmissionLease,
        ensure_current: Callable[[str], None],
    ) -> tuple[
        RuntimeRouteBinding,
        CoreLoadedRouteSnapshot,
        dict[str, Any],
        int,
    ]:
        """Let Mihomo select a healthy fallback member in loaded policy order."""

        current_snapshot, current_payload, commits = (
            self._apply_startup_route_intent(
                intent,
                snapshot,
                snapshot_payload,
                deadline_monotonic=admission_lease.deadline_monotonic,
                worker_token=tuple(admission_lease.worker_token),
                ensure_current=ensure_current,
            )
        )
        ensure_current("native fallback healthcheck")
        health_source = self._trigger_startup_native_fallback_health(
            current_snapshot,
            intent,
            deadline_monotonic=admission_lease.deadline_monotonic,
        )
        if health_source == "direct_leaf":
            direct_binding = self._runtime_route_binding_for_outbound(
                current_snapshot,
                current_payload,
                "FINAL-EXIT",
            )
            if isinstance(direct_binding, RuntimeRouteBinding):
                self._record_tier3_initial_activation_stage(
                    "native_fallback_selected",
                    health_source=health_source,
                    selector_commits=int(commits),
                    loaded_candidate_count=len(intent.loaded_order),
                )
                return (
                    direct_binding,
                    current_snapshot,
                    current_payload,
                    commits,
                )
        ensure_current("native fallback route readback")
        reserve_after_readback = (
            4.75 if self._runtime_traffic_capture_wanted() else 0.50
        )
        readback_deadline = min(
            admission_lease.deadline_monotonic - reserve_after_readback,
            time.monotonic() + 3.0,
        )
        authority = None
        readback_delays = iter((0.0, 0.05, 0.15, 0.30, 0.50, 0.75, 1.0))
        while authority is None and time.monotonic() < readback_deadline:
            delay = next(readback_delays, 0.25)
            if delay > 0.0 and self.stop_event.wait(
                min(delay, max(0.0, readback_deadline - time.monotonic()))
            ):
                raise RuntimeStartCancelled(
                    "runtime stop requested during native fallback readback"
                )
            ensure_current("native fallback route readback")
            try:
                authority = self._refresh_loaded_runtime_authority(
                    timeout_seconds=min(
                        _INITIAL_EGRESS_AUTHORITY_READBACK_SECONDS,
                        max(0.05, readback_deadline - time.monotonic()),
                    ),
                    require_managed_final_exit=True,
                    worker_token=tuple(admission_lease.worker_token),
                )
            except RuntimeControllerReadbackError:
                authority = None
        if authority is None:
            raise RuntimeControllerReadbackError(
                "native fallback did not expose a managed FINAL-EXIT route"
            )
        current_snapshot, current_payload, binding = authority
        if not isinstance(binding, RuntimeRouteBinding):
            raise RuntimeControllerReadbackError(
                "native fallback route readback has no managed leaf"
            )
        if intent.top_level_target not in tuple(binding.route_chain):
            raise RuntimeControllerReadbackError(
                "native fallback left the frozen startup policy branch"
            )
        if (
            intent.expected_gateway_key is not None
            and tuple(binding.node.key) != tuple(intent.expected_gateway_key)
        ):
            raise RuntimeControllerReadbackError(
                "Gateway identity changed during native fallback admission"
            )
        self._record_tier3_initial_activation_stage(
            "native_fallback_selected",
            health_source=health_source,
            selector_commits=int(commits),
            loaded_candidate_count=len(intent.loaded_order),
        )
        return binding, current_snapshot, current_payload, commits

    def _runtime_initial_candidate_plans(
        self,
        snapshot: CoreLoadedRouteSnapshot,
        snapshot_payload: dict[str, Any],
    ) -> list[dict[str, Any]]:
        """Resolve Core-loaded leaves and required selector writes in policy order."""

        states = {state.name: state for state in snapshot.group_states}
        refs = {ref.proxy_name: ref for ref in snapshot.proxy_nodes}
        active_gateway = self._active_gateway_policy_enabled()
        expected_gateway: RuntimeNodeRef | None = None
        if active_gateway:
            exit_state = states.get("EXIT-SELECT")
            if exit_state is None:
                return []
            manager = getattr(self, "manager", None)
            selected_getter = getattr(manager, "active_exit_selection", None)
            if not callable(selected_getter):
                selected_getter = getattr(manager, "active_exit_proxy_name", None)
            selected_name = ""
            if callable(selected_getter):
                selection = self._gateway_selection()
                if selection is None or not selection.active:
                    return []
                # The member this snapshot's EXIT-SELECT holds for the saved node.
                selected_name = self._loaded_gateway_member(
                    selection,
                    snapshot_payload.get("proxy_map"),
                    members=exit_state.members,
                )
                if not selected_name:
                    return []
            allowed_names = tuple(
                str(member or "").strip()
                for member in exit_state.members
                if str(member or "").strip()
                and not builtin_terminal_kind(str(member or "").strip())
            )
            if selected_name:
                candidate = refs.get(selected_name)
                if selected_name not in allowed_names:
                    return []
                if candidate is not None and candidate.pool_kind == "gateway":
                    expected_gateway = candidate
            elif not callable(selected_getter):
                allowed_gateways = [
                    refs[name]
                    for name in allowed_names
                    if name in refs and refs[name].pool_kind == "gateway"
                ]
                if len(allowed_gateways) == 1:
                    expected_gateway = allowed_gateways[0]
            if expected_gateway is None:
                # Other loaded exit proxies are inventory, not authority to
                # replace the user's exact configured Gateway identity.
                return []
        plans: list[dict[str, Any]] = []
        seen_leaves: set[tuple[str, str, str, str]] = set()

        def path_actions(
            path: tuple[tuple[str, str, CoreLoadedGroupState], ...],
        ) -> list[dict[str, Any]]:
            actions: list[dict[str, Any]] = []
            for group, target, state in path:
                type_name = str(state.type_name or "").casefold()
                mode = (
                    "selector"
                    if "select" in type_name or "selector" in type_name
                    else "fixed"
                )
                selected = str(state.now or "")
                if selected == target:
                    continue
                actions.append(
                    {
                        "group": group,
                        "target": target,
                        "previous": selected,
                        "mode": mode,
                    }
                )
            return actions

        def add_plan(
            *,
            probe_ref: RuntimeNodeRef,
            final_ref: RuntimeNodeRef,
            probe_group: str,
            outer_path: tuple[
                tuple[str, str, CoreLoadedGroupState], ...
            ],
            leaf_path: tuple[
                tuple[str, str, CoreLoadedGroupState], ...
            ],
        ) -> None:
            if probe_ref.key in seen_leaves:
                return
            # Paths are recorded root-first.  Applying the combined path in
            # reverse establishes the deepest underlay before exposing the
            # fixed Gateway (or ordinary leaf) to FINAL-EXIT.
            actions = path_actions((*outer_path, *leaf_path))
            if not actions or len(actions) > 2:
                return
            for action in actions:
                action["alternative_leaf"] = probe_ref.proxy_name
            seen_leaves.add(probe_ref.key)
            plans.append(
                {
                    "ref": final_ref,
                    "probe_ref": probe_ref,
                    "probe_group": str(probe_group or "FINAL-EXIT"),
                    "actions": tuple(reversed(actions)),
                    "expected_underlay_key": (
                        tuple(probe_ref.key)
                        if final_ref.pool_kind == "gateway"
                        else None
                    ),
                }
            )

        def visit_underlay(
            name: str,
            *,
            gateway_ref: RuntimeNodeRef,
            dialer_group: str,
            outer_path: tuple[
                tuple[str, str, CoreLoadedGroupState], ...
            ],
            path: tuple[tuple[str, str, CoreLoadedGroupState], ...],
            visited_groups: frozenset[str],
        ) -> None:
            normalized = str(name or "").strip()
            if not normalized or builtin_terminal_kind(normalized):
                return
            ref = refs.get(normalized)
            if ref is not None:
                if ref.pool_kind == "gateway":
                    return
                probe_group = path[-1][0] if path else dialer_group
                add_plan(
                    probe_ref=ref,
                    final_ref=gateway_ref,
                    probe_group=probe_group,
                    outer_path=outer_path,
                    leaf_path=path,
                )
                return
            state = states.get(normalized)
            if state is None or state.name in visited_groups:
                return
            next_visited = frozenset((*visited_groups, state.name))
            for member in state.members:
                visit_underlay(
                    str(member),
                    gateway_ref=gateway_ref,
                    dialer_group=dialer_group,
                    outer_path=outer_path,
                    path=(*path, (state.name, str(member), state)),
                    visited_groups=next_visited,
                )

        def visit(
            name: str,
            path: tuple[tuple[str, str, CoreLoadedGroupState], ...],
            visited_groups: frozenset[str],
        ) -> None:
            normalized = str(name or "").strip()
            if not normalized or builtin_terminal_kind(normalized):
                return
            ref = refs.get(normalized)
            if ref is not None:
                if active_gateway:
                    if expected_gateway is None or ref.key != expected_gateway.key:
                        return
                    info = self._runtime_proxy_info_for_ref(
                        snapshot_payload,
                        expected_gateway,
                    )
                    proxy = info.get("proxy") if isinstance(info, dict) else None
                    dialer_group = (
                        str(proxy.get("dialer-proxy") or "").strip()
                        if isinstance(proxy, dict)
                        else ""
                    )
                    if not dialer_group:
                        return
                    visit_underlay(
                        dialer_group,
                        gateway_ref=expected_gateway,
                        dialer_group=dialer_group,
                        outer_path=path,
                        path=(),
                        visited_groups=frozenset(),
                    )
                    return
                elif ref.pool_kind == "gateway":
                    return
                add_plan(
                    probe_ref=ref,
                    final_ref=ref,
                    probe_group=path[-1][0] if path else "FINAL-EXIT",
                    outer_path=(),
                    leaf_path=path,
                )
                return
            state = states.get(normalized)
            if state is None or state.name in visited_groups:
                return
            next_visited = frozenset((*visited_groups, state.name))
            for member in state.members:
                visit(
                    member,
                    (*path, (state.name, str(member), state)),
                    next_visited,
                )

        visit("FINAL-EXIT", (), frozenset())
        return plans[:4]

    def _probe_initial_candidate_plans(
        self,
        plans: list[dict[str, Any]],
        snapshot: CoreLoadedRouteSnapshot,
        snapshot_payload: dict[str, Any],
        *,
        deadline_monotonic: float,
        excluded_probe_keys: set[tuple[str, str, str, str]] | None = None,
    ) -> dict[str, Any] | None:
        """Probe two candidates at a time and choose the first PASS by order."""

        excluded = set(excluded_probe_keys or set())
        eligible_plans: list[dict[str, Any]] = []
        for plan in plans[:4]:
            probe_ref = plan.get("probe_ref")
            if not isinstance(probe_ref, RuntimeNodeRef):
                probe_ref = plan.get("ref")
            if (
                isinstance(probe_ref, RuntimeNodeRef)
                and tuple(probe_ref.key) not in excluded
            ):
                eligible_plans.append(plan)
        for offset in range(0, len(eligible_plans), 2):
            batch = eligible_plans[offset : offset + 2]
            observed: list[dict[str, Any] | None] = [None] * len(batch)
            finished = [threading.Event() for _item in batch]

            def probe(index: int, plan: dict[str, Any]) -> None:
                try:
                    actions = tuple(plan.get("actions") or ())
                    if not actions:
                        return
                    probe_ref = plan.get("probe_ref")
                    if not isinstance(probe_ref, RuntimeNodeRef):
                        probe_ref = plan.get("ref")
                    if not isinstance(probe_ref, RuntimeNodeRef):
                        return
                    probe_url, expected_status = (
                        self._runtime_group_probe_contract(
                            snapshot,
                            str(plan.get("probe_group") or "FINAL-EXIT"),
                        )
                    )
                    current_core_evidence = (
                        self._initial_core_loaded_probe_evidence(
                            snapshot,
                            snapshot_payload,
                            probe_ref,
                            str(plan.get("probe_group") or "FINAL-EXIT"),
                        )
                    )
                    if current_core_evidence is not None:
                        observed[index] = current_core_evidence
                        return
                    remaining = max(
                        0.0,
                        deadline_monotonic - time.monotonic(),
                    )
                    if remaining <= 0.0:
                        return
                    timeout_ms = max(
                        100,
                        min(2500, int(remaining * 1000.0)),
                    )
                    value = self._probe_runtime_leaf(
                        probe_ref,
                        snapshot_payload,
                        timeout_ms=timeout_ms,
                        probe_url=probe_url,
                        expected_status=expected_status,
                        probe_priority=ProbePriority.ACTIVATION,
                    )
                    observed[index] = (
                        dict(value) if isinstance(value, dict) else {"result": value}
                    )
                except Exception:
                    observed[index] = None
                finally:
                    finished[index].set()

            threads = [
                threading.Thread(
                    target=probe,
                    args=(index, plan),
                    name="initial-egress-candidate-probe",
                    daemon=True,
                )
                for index, plan in enumerate(batch)
            ]
            for thread in threads:
                thread.start()
            for event in finished:
                remaining = max(
                    0.0,
                    deadline_monotonic - time.monotonic(),
                )
                if remaining <= 0.0 or not event.wait(remaining):
                    break
            for index, plan in enumerate(batch):
                if observed[index] is not None:
                    return {
                        **plan,
                        "probe_result": observed[index],
                    }
            if time.monotonic() >= deadline_monotonic:
                break
        return None

    def _initial_core_loaded_probe_evidence(
        self,
        snapshot: CoreLoadedRouteSnapshot,
        snapshot_payload: dict[str, Any],
        ref: RuntimeNodeRef,
        probe_group: str,
    ) -> dict[str, Any] | None:
        """Reuse only current-Core liveness for the exact group contract.

        A freshly started Mihomo fallback performs its own member URLTest. If
        that current-generation controller readback already marks the exact
        member alive for the same group URL/status contract, another member
        delay request only wastes the finite startup lease. Manager health is
        deliberately not consulted here.
        """

        state = snapshot.group_state(str(probe_group or ""))
        if state is None or not str(state.test_url or "").strip():
            return None
        probe_url, expected_status = self._runtime_group_probe_contract(
            snapshot,
            state.name,
        )
        if (
            str(state.test_url or "").strip() != str(probe_url or "").strip()
            or str(state.expected_status or "204").strip()
            != str(expected_status or "204").strip()
        ):
            return None
        proxies_payload = snapshot_payload.get("proxies")
        entries = (
            proxies_payload.get("proxies")
            if isinstance(proxies_payload, dict)
            else None
        )
        if not isinstance(entries, dict) and isinstance(proxies_payload, dict):
            entries = proxies_payload
        raw = entries.get(ref.proxy_name) if isinstance(entries, dict) else None
        # Top-level ``alive`` is the member's latest URLTest for any URL (a
        # neutral diagnostic delay or another group).  Mihomo's fallback reads
        # the per-URL verdict, which also carries the expected-status result.
        extra = raw.get("extra") if isinstance(raw, dict) else None
        url_state = (
            extra.get(str(state.test_url or "").strip())
            if isinstance(extra, dict)
            else None
        )
        if not isinstance(url_state, dict) or url_state.get("alive") is not True:
            return None
        return {
            "alive": True,
            "evidence_source": "current_core_group_urltest",
            "probe_url": str(probe_url),
            "expected_status": str(expected_status),
            "snapshot_key": tuple(snapshot.snapshot_key),
        }

    def _activate_initial_unbound_candidate(
        self,
        *,
        snapshot: CoreLoadedRouteSnapshot,
        snapshot_payload: dict[str, Any],
        admission_lease: _InitialEgressAdmissionLease,
        ensure_current: Callable[[str], None],
        excluded_probe_keys: set[tuple[str, str, str, str]] | None = None,
        remaining_selection_commits: int = 2,
        from_proxy: str = "REJECT",
    ) -> tuple[
        RuntimeRouteBinding,
        CoreLoadedRouteSnapshot,
        dict[str, Any],
    ]:
        """Recover a REJECT/unbound startup route without inventing health."""

        plans = self._runtime_initial_candidate_plans(
            snapshot,
            snapshot_payload,
        )
        plans = [
            plan
            for plan in plans
            if 0 < len(tuple(plan.get("actions") or ()))
            <= max(0, int(remaining_selection_commits))
        ]
        accepted = self._probe_initial_candidate_plans(
            plans,
            snapshot,
            snapshot_payload,
            deadline_monotonic=admission_lease.deadline_monotonic,
            excluded_probe_keys=excluded_probe_keys,
        )
        if accepted is None:
            raise RuntimeError(
                "Initial FINAL-EXIT has no verified Core-loaded candidate"
            )
        ref = accepted["ref"]
        probe_ref = accepted.get("probe_ref")
        if not isinstance(probe_ref, RuntimeNodeRef):
            probe_ref = ref
        actions = tuple(accepted.get("actions") or ())[:2]
        if not actions or len(actions) > max(0, int(remaining_selection_commits)):
            raise RuntimeError(
                "Initial FINAL-EXIT candidate exceeds the remaining selector budget"
            )
        current_snapshot = snapshot
        current_payload = snapshot_payload
        selection_results: list[dict[str, Any]] = []
        # The accepted member delay used the exact group URL/status contract,
        # so it is already the fallback prewarm.  Repeating that same network
        # request here consumed another 1.15 seconds and rejected otherwise
        # healthy 1.7-3.0 second leaves before selector commit.
        if not isinstance(accepted.get("probe_result"), dict):
            for action in actions:
                ensure_current("candidate prewarm")
                self._prewarm_runtime_switch_target(
                    current_snapshot,
                    action,
                    deadline_monotonic=admission_lease.deadline_monotonic,
                    probe_priority=ProbePriority.ACTIVATION,
                )
        ensure_current("candidate mutation ownership")
        with self._bounded_core_transition(
            admission_lease.deadline_monotonic,
            "initial candidate selection",
        ):
            ensure_current("candidate mutation commit")
            for action in actions:
                selection_results.append(
                    self._apply_runtime_automatic_selection(
                        action,
                        deadline_monotonic=admission_lease.deadline_monotonic,
                    )
                )
                ensure_current("candidate selector readback")
                authority = self._refresh_loaded_runtime_authority(
                    timeout_seconds=min(
                        0.75,
                        max(
                            0.05,
                            admission_lease.deadline_monotonic - time.monotonic(),
                        ),
                    ),
                    require_managed_final_exit=False,
                    worker_token=admission_lease.worker_token,
                )
                if authority is None:
                    raise RuntimeControllerReadbackError(
                        "Initial candidate selection has no authoritative readback"
                    )
                current_snapshot, current_payload, _binding = authority

            authority = self._refresh_loaded_runtime_authority(
                timeout_seconds=min(
                    0.75,
                    max(
                        0.05,
                        admission_lease.deadline_monotonic - time.monotonic(),
                    ),
                ),
                require_managed_final_exit=True,
                worker_token=admission_lease.worker_token,
            )
            if authority is None:
                raise RuntimeControllerReadbackError(
                    "Initial candidate did not become the managed FINAL-EXIT route"
                )
            current_snapshot, current_payload, binding = authority
        if binding is None or binding.node.key != ref.key:
            raise RuntimeControllerReadbackError(
                "Initial candidate selector readback resolved another leaf"
            )
        if ref.pool_kind == "gateway":
            underlay = self._runtime_gateway_underlay_binding(
                current_snapshot,
                current_payload,
                ref,
            )
            if underlay is None or underlay.node.key != probe_ref.key:
                raise RuntimeControllerReadbackError(
                    "Initial Gateway selector readback resolved another underlay"
                )
        first_action = actions[-1]
        managed_lease = ManagedFixedLease(
            incident_id=(
                "initial-admission:"
                f"{admission_lease.runtime_generation}:"
                f"{admission_lease.core_generation}:"
                f"{admission_lease.activation_generation}"
            ),
            group=str(first_action.get("group") or ""),
            from_proxy=str(from_proxy or "REJECT"),
            to_proxy=ref.proxy_name,
            target_member=str(first_action.get("target") or ""),
            mode=str(first_action.get("mode") or "selector"),
            route_epoch=int(current_snapshot.route_epoch),
            owner_token=(
                "initial-egress:"
                f"{admission_lease.lifecycle_revision}:"
                f"{admission_lease.activation_generation}"
            ),
            minimum_dwell_until=time.monotonic(),
            user_intent_revision=admission_lease.selector_intent_revision,
            verified_at_monotonic=0.0,
        ).to_dict()
        managed_lease["initial_actions"] = [dict(action) for action in actions]
        managed_lease["selection_results"] = selection_results
        managed_lease["startup_admission"] = True
        managed_lease["activation_generation"] = int(
            admission_lease.activation_generation
        )
        managed_lease["lifecycle_revision"] = int(
            admission_lease.lifecycle_revision
        )
        managed_lease["runtime_generation"] = int(
            admission_lease.runtime_generation
        )
        managed_lease["core_generation"] = int(admission_lease.core_generation)
        if ref.pool_kind == "gateway":
            managed_lease["expected_underlay_key"] = list(probe_ref.key)
        with self._runtime_failure_monitor_lock:
            self._runtime_route_mutation_lease = managed_lease
        return binding, current_snapshot, current_payload

    @contextmanager
    def _bounded_core_transition(
        self,
        deadline_monotonic: float,
        stage: str,
    ):
        remaining = float(deadline_monotonic) - time.monotonic()
        if remaining <= 0.0 or not self._core_transition_lock.acquire(
            timeout=remaining
        ):
            raise TimeoutError(f"{stage} exceeded its route mutation deadline")
        try:
            yield
        finally:
            self._core_transition_lock.release()

    def _run_initial_egress_activation_serialized(
        self,
        *,
        runner: Any,
        activation_generation: int,
        core_generation: int,
        selector_intent_revision: int,
        worker_token: tuple[int, ...],
        admission_lease: _InitialEgressAdmissionLease,
    ) -> dict[str, Any]:
        """Run admission while serializing only actual Core route mutations."""

        return self._run_initial_egress_activation(
            runner=runner,
            activation_generation=activation_generation,
            core_generation=core_generation,
            selector_intent_revision=selector_intent_revision,
            worker_token=worker_token,
            admission_lease=admission_lease,
        )

    def _run_initial_egress_activation_rollback(
        self,
        *,
        runner: Any,
        activation_generation: int,
        core_generation: int,
        selector_intent_revision: int,
        admission_lease: _InitialEgressAdmissionLease,
    ) -> dict[str, Any]:
        """Run one finite verify-before-capture startup admission.

        This path deliberately does *not* re-enable the superseded steady
        state recovery machine.  It reads one immutable Core authority,
        verifies the selected leaf, and only when necessary tries the
        Core-loaded alternatives in policy order.  It may commit at most two
        selector actions and never mutates Manager health, creates REJECT,
        acquires recovery pressure, reloads for health, or schedules a retry.
        """

        deadline = float(admission_lease.deadline_monotonic)
        capture_wanted = bool(self._runtime_traffic_capture_wanted())
        core_capture_reload_required = bool(
            capture_wanted and self._runtime_core_capture_reload_required()
        )
        host_capture_preverified = False

        def ensure_current(stage: str) -> None:
            if time.monotonic() >= deadline:
                raise TimeoutError(
                    f"initial egress admission expired during {stage}"
                )
            if self.stop_event.is_set():
                raise RuntimeStartCancelled(
                    f"runtime stop requested during {stage}"
                )
            if self.core_runner is not runner or not runner.is_running():
                raise RuntimeStartCancelled(
                    f"Mihomo Core changed during {stage}"
                )
            with self._core_lifecycle_lock:
                live_core_generation = int(self._core_generation)
            if live_core_generation != int(core_generation):
                raise RuntimeStartCancelled(
                    f"Mihomo Core generation changed during {stage}"
                )
            if int(getattr(self, "_lifecycle_revision", 0) or 0) != int(
                admission_lease.lifecycle_revision
            ) or int(getattr(self, "_runtime_generation", 0) or 0) != int(
                admission_lease.runtime_generation
            ):
                raise RuntimeStartCancelled(
                    f"runtime lifecycle changed during {stage}"
                )
            if int(
                getattr(self, "_runtime_selector_intent_revision", 0) or 0
            ) != int(selector_intent_revision):
                raise RuntimeStartCancelled(
                    f"user selector intent changed during {stage}"
                )
            status = runner.status()
            if (
                int(status.get("pid") or 0) != int(admission_lease.process_pid)
                or int(status.get("process_generation") or 0)
                != int(admission_lease.process_generation)
            ):
                raise RuntimeStartCancelled(
                    f"Mihomo process changed during {stage}"
                )

        def verify_data_plane(
            stage: str,
            *,
            expected_snapshot: CoreLoadedRouteSnapshot,
        ) -> dict[str, Any]:
            ensure_current(stage)
            remaining = deadline - time.monotonic()
            reserve = 4.75 if capture_wanted else 0.50
            probe_budget = min(5.5, max(0.0, remaining - reserve))
            if probe_budget <= 0.10:
                raise TimeoutError(
                    f"initial egress admission expired during {stage}"
                )
            return self._verify_runtime_final_exit(
                expected_worker_token=tuple(admission_lease.worker_token),
                expected_snapshot=expected_snapshot,
                timeout_seconds=probe_budget,
                require_controller_ready=True,
                required_successes=2,
                parallel_probes=True,
                total_timeout_cap_seconds=probe_budget,
                per_probe_timeout_cap_seconds=min(5.0, probe_budget),
            )

        def probe_key_for_binding(
            binding: RuntimeRouteBinding,
            snapshot: CoreLoadedRouteSnapshot,
            payload: dict[str, Any],
        ) -> tuple[str, str, str, str]:
            return tuple(
                probe_binding_for(binding, snapshot, payload).node.key
            )

        def probe_binding_for(
            binding: RuntimeRouteBinding,
            snapshot: CoreLoadedRouteSnapshot,
            payload: dict[str, Any],
        ) -> RuntimeRouteBinding:
            if binding.node.pool_kind == "gateway":
                underlay = self._runtime_gateway_underlay_binding(
                    snapshot,
                    payload,
                    binding.node,
                )
                if underlay is not None:
                    return underlay
            return binding

        def native_group_has_alternative(
            snapshot: CoreLoadedRouteSnapshot,
            group_name: str,
            current_probe_key: tuple[str, str, str, str],
        ) -> bool:
            """Return whether the loaded fallback graph has another managed leaf."""

            states = {state.name: state for state in snapshot.group_states}
            refs = {ref.proxy_name: ref for ref in snapshot.proxy_nodes}

            def managed_keys(
                name: str,
                visited: frozenset[str] = frozenset(),
            ) -> tuple[tuple[str, str, str, str], ...]:
                normalized = str(name or "").strip()
                ref = refs.get(normalized)
                if ref is not None:
                    return (tuple(ref.key),)
                state = states.get(normalized)
                if state is None or normalized in visited:
                    return ()
                next_visited = frozenset((*visited, normalized))
                ordered: list[tuple[str, str, str, str]] = []
                for member in state.members:
                    for key in managed_keys(str(member), next_visited):
                        if key not in ordered:
                            ordered.append(key)
                return tuple(ordered)

            return any(
                key != tuple(current_probe_key)
                for key in managed_keys(group_name)
            )

        self._disarm_runtime_recovery("stability rollback admission")
        self._record_tier3_initial_activation_stage(
            "rollback_admission_started",
            activation_generation=int(activation_generation),
            capture_wanted=capture_wanted,
        )
        self._publish_runtime_egress_readiness(
            RuntimeEgressReadinessState.ACTIVATION_HOLD,
            validation_active=True,
            reason="FINAL-EXIT data-plane verification is running",
            deadline_monotonic=deadline,
            expected_activation_generation=admission_lease.activation_generation,
            expected_active_activation_generation=(
                admission_lease.activation_generation
            ),
            expected_lifecycle_revision=admission_lease.lifecycle_revision,
            expected_selector_intent_revision=(
                admission_lease.selector_intent_revision
            ),
            effective_ok=None,
        )

        ensure_current("no-capture authority readback")
        authority_timeout = min(
            _INITIAL_EGRESS_AUTHORITY_READBACK_SECONDS,
            max(0.05, deadline - time.monotonic()),
        )
        snapshot, snapshot_payload, binding = (
            self._tier3_activation_authority_state(
                worker_token=tuple(admission_lease.worker_token),
                timeout_seconds=authority_timeout,
                require_managed_final_exit=False,
            )
        )
        route_intent = self._startup_route_intent_from_snapshot(snapshot)
        if route_intent is None:
            raise RuntimeControllerReadbackError(
                "Core-loaded policy has no admissible FINAL-EXIT startup branch"
            )
        binding, snapshot, snapshot_payload, selection_commits = (
            self._activate_startup_native_fallback(
                snapshot=snapshot,
                snapshot_payload=snapshot_payload,
                intent=route_intent,
                admission_lease=admission_lease,
                ensure_current=ensure_current,
            )
        )
        result: dict[str, Any] | None = None
        attempted_probe_keys: set[tuple[str, str, str, str]] = set()
        last_chain_failure: Exception | None = None
        for candidate_attempt in range(4):
            current_probe_binding = probe_binding_for(
                binding,
                snapshot,
                snapshot_payload,
            )
            current_probe_key = probe_key_for_binding(
                binding,
                snapshot,
                snapshot_payload,
            )
            if current_probe_key in attempted_probe_keys:
                break
            attempted_probe_keys.add(current_probe_key)
            try:
                result = verify_data_plane(
                    "native fallback no-capture verification",
                    expected_snapshot=snapshot,
                )
                if capture_wanted and not core_capture_reload_required:
                    # For Windows system proxy the verified mixed-port is the
                    # final Core data plane.  Prove the actual HKCU/WinINet path
                    # while this native candidate still owns the loop; a host
                    # failure can then advance the same bounded fallback rather
                    # than publishing READY after one lucky explicit probe.
                    ensure_current("system proxy activation")
                    self._apply_system_proxy_capture_after_core_start(runner)
                    try:
                        ensure_current("system proxy host-path proof")
                        self._verify_system_proxy_host_capture(
                            deadline_monotonic=deadline,
                            priority=ProbePriority.ACTIVATION,
                        )
                    except Exception:
                        if bool(
                            getattr(self.system_proxy, "active", False)
                        ):
                            try:
                                self.restore_system_proxy()
                            except Exception:
                                pass
                        raise
                    host_capture_preverified = True
                break
            except Exception as chain_failure:
                last_chain_failure = chain_failure
                remaining = deadline - time.monotonic()
                reserve = 4.75 if capture_wanted else 0.50
                confirmation_budget = min(
                    1.5,
                    max(0.0, remaining - reserve),
                )
                if confirmation_budget <= 0.10:
                    break
                health_group = self._startup_native_fallback_health_group(
                    snapshot,
                    route_intent,
                    current_probe_binding,
                )
                if not health_group:
                    break
                if not native_group_has_alternative(
                    snapshot,
                    health_group,
                    current_probe_key,
                ):
                    # A single-member fallback cannot advance.  Do not spend
                    # the admission deadline reproving a leaf when there is no
                    # native successor to adopt.
                    break
                probe_url, expected_status = (
                    self._runtime_group_probe_contract(
                        snapshot,
                        health_group,
                    )
                )
                try:
                    self._probe_runtime_leaf(
                        current_probe_binding.node,
                        snapshot_payload,
                        timeout_ms=max(
                            100,
                            int(confirmation_budget * 1000.0),
                        ),
                        probe_url=probe_url,
                        expected_status=expected_status,
                        probe_priority=ProbePriority.ACTIVATION,
                    )
                except Exception:
                    pass
                else:
                    # The exact member still satisfies the fallback contract;
                    # a full-chain failure is destination/Core/facility
                    # evidence, not authority to rotate the leaf.
                    break

                next_authority = None
                change_deadline = min(
                    deadline - reserve,
                    time.monotonic() + 1.0,
                )
                for delay in (0.0, 0.05, 0.15, 0.30, 0.50):
                    if time.monotonic() >= change_deadline:
                        break
                    if delay > 0.0 and self.stop_event.wait(
                        min(
                            delay,
                            max(0.0, change_deadline - time.monotonic()),
                        )
                    ):
                        raise RuntimeStartCancelled(
                            "runtime stop requested during native fallback advance"
                        )
                    ensure_current("native fallback candidate advance")
                    try:
                        candidate_authority = (
                            self._refresh_loaded_runtime_authority(
                                timeout_seconds=min(
                                    0.50,
                                    max(
                                        0.05,
                                        change_deadline - time.monotonic(),
                                    ),
                                ),
                                require_managed_final_exit=True,
                                worker_token=tuple(
                                    admission_lease.worker_token
                                ),
                            )
                        )
                    except RuntimeControllerReadbackError:
                        candidate_authority = None
                    if candidate_authority is None:
                        continue
                    (
                        candidate_snapshot,
                        candidate_payload,
                        candidate_binding,
                    ) = candidate_authority
                    if not isinstance(
                        candidate_binding,
                        RuntimeRouteBinding,
                    ):
                        continue
                    candidate_probe_key = probe_key_for_binding(
                        candidate_binding,
                        candidate_snapshot,
                        candidate_payload,
                    )
                    if candidate_probe_key == current_probe_key:
                        continue
                    if route_intent.top_level_target not in tuple(
                        candidate_binding.route_chain
                    ):
                        raise RuntimeControllerReadbackError(
                            "native fallback candidate left startup branch"
                        )
                    if (
                        route_intent.expected_gateway_key is not None
                        and tuple(candidate_binding.node.key)
                        != tuple(route_intent.expected_gateway_key)
                    ):
                        raise RuntimeControllerReadbackError(
                            "Gateway identity changed during fallback advance"
                        )
                    next_authority = candidate_authority
                    break
                if next_authority is None:
                    break
                snapshot, snapshot_payload, binding = next_authority
                self._record_tier3_initial_activation_stage(
                    "native_fallback_advanced",
                    candidate_attempt=int(candidate_attempt + 1),
                    attempted_count=len(attempted_probe_keys),
                )

        if result is None:
            if last_chain_failure is not None:
                raise last_chain_failure
            raise RuntimeControllerReadbackError(
                "native fallback did not yield a verified FINAL-EXIT route"
            )

        capture_preferred_binding = binding
        if binding.node.pool_kind == "gateway":
            underlay_binding = self._runtime_gateway_underlay_binding(
                snapshot,
                snapshot_payload,
                binding.node,
            )
            if underlay_binding is not None:
                capture_preferred_binding = underlay_binding
        capture_probe_group = self._startup_native_fallback_health_group(
            snapshot,
            route_intent,
            capture_preferred_binding,
        )

        self._record_tier3_initial_activation_stage(
            "rollback_no_capture_verified",
            activation_generation=int(activation_generation),
            controller_inventory_observed=True,
            controller_inventory_gated=True,
            selector_commits=int(selection_commits),
        )
        self._set_tier3_source_control_qualification(snapshot, binding)

        core_capture_reloaded = False
        system_proxy_capture_phase_published = False
        traffic_monitor_started = False
        try:
            if capture_wanted:
                if core_capture_reload_required:
                    ensure_current("capture reload")
                    self._hot_reload_runtime_config_phase(
                        runner,
                        capture_enabled=True,
                        expected_activation_generation=activation_generation,
                        expected_core_generation=core_generation,
                        deadline_monotonic=deadline,
                    )
                    core_capture_reloaded = True
                    ensure_current("post-capture verification")
                    result = self._verify_capture_route_after_reload(
                        lease_record=None,
                        route_intent=route_intent,
                        preferred_leaf_ref=capture_preferred_binding.node,
                        preferred_probe_group=capture_probe_group,
                        expected_gateway_key=route_intent.expected_gateway_key,
                        timeout_seconds=min(
                            5.5,
                            max(
                                0.05,
                                deadline
                                - time.monotonic()
                                - (
                                    0.75
                                    if self._system_proxy_capture_proof_required()
                                    else 0.0
                                ),
                            ),
                        ),
                        deadline_monotonic=deadline,
                    )
                    self._refresh_tier3_source_control_qualification()
                else:
                    self._record_tier3_initial_activation_stage(
                        "core_capture_reload_skipped",
                        reason="system_proxy_uses_verified_mixed_port",
                    )
                if not host_capture_preverified:
                    ensure_current("system proxy activation")
                    self._apply_system_proxy_capture_after_core_start(runner)
                    ensure_current("system proxy host-path proof")
                    self._verify_system_proxy_host_capture(
                        deadline_monotonic=deadline,
                        priority=ProbePriority.ACTIVATION,
                    )

            # The activation lease is the transaction authority. Keep the
            # intent/failure locks for the local generation commit only; every
            # operation below may call into Manager or a readiness projector
            # and therefore must run without either runtime lock held. Pool
            # admission takes Manager.lock and may concurrently read runtime
            # readiness, so holding these locks across that callback creates a
            # real Manager <-> runtime lock inversion during fast admission
            # bursts.
            with self._runtime_intent_lock:
                with self._runtime_failure_monitor_lock:
                    ensure_current("READY preparation")

            if capture_wanted:
                self.traffic_monitor.start()
                traffic_monitor_started = True
            manager = self.manager
            capture_marker = (
                getattr(
                    manager,
                    "mark_tier3_traffic_capture_active",
                    None,
                )
                if manager is not None
                else None
            )
            manager_lock = getattr(manager, "lock", None)
            with manager_lock if manager_lock is not None else nullcontext():
                ensure_current("capture state publication")
                if capture_wanted and not core_capture_reload_required:
                    # The verified mixed-port graph also serves Windows
                    # capture. Skipping ApplyConfig must not leave its
                    # lifecycle at no-capture after the host proof passed.
                    self._set_core_runtime_phase("formal_capture")
                    system_proxy_capture_phase_published = True
                if callable(capture_marker):
                    capture_marker(capture_wanted)
            self._mark_tier3_core_sync_success(
                traffic_capture_active=capture_wanted,
            )
            arm_method = self._try_arm_runtime_recovery
            try:
                arm_prepared = arm_method(
                    allow_pre_ready=True,
                    admission_lease=admission_lease,
                )
            except TypeError:
                arm_prepared = arm_method()
            if not arm_prepared:
                raise RuntimeControllerReadbackError(
                    "verified FINAL-EXIT could not prepare bounded "
                    "runtime recovery"
                )

            with self._runtime_intent_lock:
                with self._runtime_failure_monitor_lock:
                    ensure_current("READY generation commit")
                    self._runtime_initial_activation_generation = int(
                        core_generation
                    )

            published = self._publish_runtime_egress_readiness(
                RuntimeEgressReadinessState.READY,
                validation_active=False,
                expected_activation_generation=(
                    admission_lease.activation_generation
                ),
                expected_active_activation_generation=(
                    admission_lease.activation_generation
                ),
                expected_lifecycle_revision=(
                    admission_lease.lifecycle_revision
                ),
                expected_selector_intent_revision=(
                    admission_lease.selector_intent_revision
                ),
                effective_ok=True,
            )
            if (
                not isinstance(published, RuntimeEgressReadiness)
                or published.state is not RuntimeEgressReadinessState.READY
                or published.validation_active
            ):
                raise RuntimeControllerReadbackError(
                    "verified FINAL-EXIT READY publication lost authority"
                )
            if not self._runtime_recovery_is_armed():
                raise RuntimeControllerReadbackError(
                    "verified FINAL-EXIT could not arm bounded runtime recovery"
                )
            self._commit_runtime_monitoring_lease()
            self._reset_tier3_standby_activation_failure()
            self._record_tier3_initial_activation_stage(
                "ready",
                activation_generation=int(activation_generation),
                source_control_egress_ready=(
                    self._tier3_source_control_qualification_is_current()
                ),
                recovery_profile="bounded_single_coordinator",
            )
            self._coalesce_pre_ready_activation_successor(admission_lease)
            self._start_runtime_failure_monitor()
            return result
        except Exception:
            if traffic_monitor_started:
                self.traffic_monitor.stop()
            self._runtime_initial_activation_generation = -1
            if capture_wanted and runner.is_running():
                stop_already_owns_proxy_restore = bool(
                    self.stop_event.is_set()
                    or getattr(self, "_stop_request_pending", False)
                )
                if (
                    (
                        not stop_already_owns_proxy_restore
                        or not core_capture_reloaded
                    )
                    and bool(getattr(self.system_proxy, "active", False))
                ):
                    try:
                        self.restore_system_proxy()
                    except Exception:
                        pass
            if core_capture_reloaded and runner.is_running():
                try:
                    self._rollback_to_formal_no_capture(
                        runner,
                        "initial data-plane admission did not commit",
                        deadline_monotonic=deadline,
                        admission_lease=admission_lease,
                    )
                except Exception:
                    pass
            elif (
                system_proxy_capture_phase_published
                and self.core_runner is runner
                and runner.is_running()
                and not bool(getattr(self.system_proxy, "active", False))
            ):
                manager = self.manager
                manager_lock = getattr(manager, "lock", None)
                with manager_lock if manager_lock is not None else nullcontext():
                    with self._core_lifecycle_lock:
                        same_core = int(self._core_generation) == int(core_generation)
                    status = runner.status()
                    same_process = bool(
                        int(status.get("pid") or 0) == admission_lease.process_pid
                        and int(status.get("process_generation") or 0)
                        == admission_lease.process_generation
                    )
                    if (
                        same_core
                        and same_process
                        and self._current_core_runtime_phase() == "formal_capture"
                    ):
                        self._set_core_runtime_phase("formal_no_capture")
                        capture_marker = getattr(
                            manager, "mark_tier3_traffic_capture_active", None
                        )
                        if callable(capture_marker):
                            capture_marker(False)
            raise

    def _run_initial_egress_activation(
        self,
        *,
        runner: Any,
        activation_generation: int,
        core_generation: int,
        selector_intent_revision: int,
        worker_token: tuple[int, ...],
        admission_lease: _InitialEgressAdmissionLease | None = None,
    ) -> dict[str, Any]:
        """Prove startup traffic before capture is exposed to the host."""

        if admission_lease is None:
            status = runner.status()
            authority_key = self._tier3_standby_activation_key()
            admission_lease = _InitialEgressAdmissionLease(
                activation_generation=int(activation_generation),
                lifecycle_revision=int(
                    getattr(self, "_lifecycle_revision", 0) or 0
                ),
                runtime_generation=int(
                    getattr(self, "_runtime_generation", 0) or 0
                ),
                core_generation=int(core_generation),
                process_pid=int(status.get("pid") or 0),
                process_generation=int(
                    status.get("process_generation") or 0
                ),
                selector_intent_revision=int(selector_intent_revision),
                worker_token=tuple(worker_token),
                deadline_monotonic=(
                    time.monotonic()
                    + _INITIAL_EGRESS_ADMISSION_DEADLINE_SECONDS
                ),
                authority_key=tuple(authority_key),
            )
        if self._runtime_uses_early_single_coordinator():
            return self._run_initial_egress_activation_rollback(
                runner=runner,
                activation_generation=activation_generation,
                core_generation=core_generation,
                selector_intent_revision=selector_intent_revision,
                admission_lease=admission_lease,
            )
        deadline = float(admission_lease.deadline_monotonic)
        capture_wanted = bool(self._runtime_traffic_capture_wanted())
        facility_epoch = int(getattr(self, "_runtime_facility_epoch", 0) or 0)
        self._disarm_runtime_recovery("initial activation")
        self._record_tier3_initial_activation_stage(
            "authority_wait",
            activation_generation=int(activation_generation),
            capture_wanted=capture_wanted,
        )
        self._publish_runtime_egress_readiness(
            RuntimeEgressReadinessState.ACTIVATION_HOLD,
            validation_active=True,
            reason="Egress verification is running",
            deadline_monotonic=deadline,
            expected_activation_generation=admission_lease.activation_generation,
            expected_active_activation_generation=(
                admission_lease.activation_generation
            ),
            expected_lifecycle_revision=admission_lease.lifecycle_revision,
            expected_selector_intent_revision=(
                admission_lease.selector_intent_revision
            ),
            effective_ok=None,
        )

        def ensure_current(stage: str) -> None:
            if time.monotonic() >= deadline:
                raise TimeoutError(
                    f"initial egress admission expired during {stage}"
                )
            if not self._tier3_egress_activation_is_current(
                admission_lease.activation_generation,
                runner,
                admission_lease.core_generation,
            ):
                raise RuntimeStartCancelled(
                    f"initial egress activation was superseded during {stage}"
                )
            if not self._runtime_worker_token_is_current(
                tuple(admission_lease.worker_token)
            ):
                raise RuntimeStartCancelled(
                    f"initial egress activation lost coordinator ownership during {stage}"
                )
            if int(getattr(self, "_lifecycle_revision", 0) or 0) != int(
                admission_lease.lifecycle_revision
            ) or int(getattr(self, "_runtime_generation", 0) or 0) != int(
                admission_lease.runtime_generation
            ):
                raise RuntimeStartCancelled(
                    "initial egress activation crossed a runtime lifecycle"
                )
            status = runner.status()
            if (
                int(status.get("pid") or 0) != admission_lease.process_pid
                or int(status.get("process_generation") or 0)
                != admission_lease.process_generation
            ):
                raise RuntimeStartCancelled(
                    "initial egress activation crossed a Core process"
                )
            if int(
                getattr(self, "_runtime_selector_intent_revision", 0) or 0
            ) != int(admission_lease.selector_intent_revision):
                raise RuntimeStartCancelled(
                    "initial egress activation was superseded by user selection"
                )
            if self._runtime_facility_hold_reason():
                raise RuntimeError("local network facility is not ready")

        def ensure_verified_authority(stage: str) -> None:
            ensure_current(stage)
            current_snapshot, current_payload = self._runtime_route_snapshot_state()
            coordinator_snapshot = (
                self._runtime_egress_coordinator.current_route_snapshot()
            )
            current_binding = (
                self._runtime_route_binding_for_outbound(
                    current_snapshot,
                    current_payload,
                    "FINAL-EXIT",
                )
                if current_snapshot is not None
                and coordinator_snapshot is not None
                and isinstance(current_payload, dict)
                else None
            )
            if (
                current_snapshot is None
                or coordinator_snapshot is None
                or current_binding is None
                or tuple(current_snapshot.snapshot_key)
                != tuple(activation_snapshot.snapshot_key)
                or tuple(coordinator_snapshot.snapshot_key)
                != tuple(activation_snapshot.snapshot_key)
                or tuple(current_binding.node.key)
                != tuple(activation_binding.node.key)
            ):
                raise RuntimeStartCancelled(
                    f"verified FINAL-EXIT authority changed during {stage}"
                )

        ensure_current("authority readback")
        activation_snapshot, activation_payload, activation_binding = (
            self._tier3_activation_authority_state(
                worker_token=worker_token,
                timeout_seconds=min(3.0, max(0.05, deadline - time.monotonic())),
                require_managed_final_exit=False,
            )
        )
        initially_unbound = activation_binding is None
        result: dict[str, Any] | None = None
        if activation_binding is None:
            self._record_tier3_initial_activation_stage(
                "unbound_inventory",
                activation_generation=int(activation_generation),
                route_epoch=int(activation_snapshot.route_epoch),
            )
            excluded_probe_keys: set[tuple[str, str, str, str]] = set()
            selection_commits = 0
            last_chain_failure: Exception | None = None
            while result is None:
                (
                    activation_binding,
                    activation_snapshot,
                    activation_payload,
                ) = self._activate_initial_unbound_candidate(
                    snapshot=activation_snapshot,
                    snapshot_payload=activation_payload,
                    admission_lease=admission_lease,
                    ensure_current=ensure_current,
                    excluded_probe_keys=excluded_probe_keys,
                    remaining_selection_commits=max(0, 2 - selection_commits),
                )
                with self._runtime_failure_monitor_lock:
                    route_lease = getattr(
                        self,
                        "_runtime_route_mutation_lease",
                        None,
                    )
                    lease_actions = (
                        tuple(route_lease.get("initial_actions") or ())
                        if isinstance(route_lease, dict)
                        else ()
                    )
                    expected_underlay_key = (
                        route_lease.get("expected_underlay_key")
                        if isinstance(route_lease, dict)
                        else None
                    )
                selection_commits += len(lease_actions)
                probe_key = (
                    tuple(str(item) for item in expected_underlay_key)
                    if isinstance(expected_underlay_key, (list, tuple))
                    and len(expected_underlay_key) == 4
                    else tuple(activation_binding.node.key)
                )
                ensure_current("unbound candidate full-chain probe")
                try:
                    result = self._verify_runtime_final_exit(
                        expected_worker_token=worker_token,
                        expected_snapshot=activation_snapshot,
                        timeout_seconds=max(
                            0.05,
                            min(3.0, deadline - time.monotonic()),
                        ),
                        required_successes=2,
                    )
                except (
                    _RuntimeProbeBudgetUnavailable,
                    RuntimeControllerReadbackError,
                ):
                    with self._runtime_failure_monitor_lock:
                        if self._runtime_route_mutation_lease is route_lease:
                            self._runtime_route_mutation_lease = None
                    raise
                except Exception as exc:
                    last_chain_failure = exc
                    excluded_probe_keys.add(probe_key)
                    with self._runtime_failure_monitor_lock:
                        if self._runtime_route_mutation_lease is route_lease:
                            self._runtime_route_mutation_lease = None
                    if (
                        selection_commits >= 2
                        or len(excluded_probe_keys) >= 4
                        or time.monotonic() >= deadline
                    ):
                        raise RuntimeError(
                            "Core-loaded candidates did not satisfy the full "
                            "FINAL-EXIT contract within the selector budget"
                        ) from last_chain_failure
                    continue
                with self._runtime_failure_monitor_lock:
                    if self._runtime_route_mutation_lease is route_lease and isinstance(
                        route_lease,
                        dict,
                    ):
                        route_lease["verified_at_monotonic"] = time.monotonic()
        gateway_policy_active = self._active_gateway_policy_enabled()
        if bool(activation_binding.node.pool_kind == "gateway") != bool(
            gateway_policy_active
        ):
            raise RuntimeControllerReadbackError(
                "Gateway policy and loaded FINAL-EXIT authority disagree"
            )
        self._record_tier3_initial_activation_stage(
            "binding_ready",
            activation_generation=int(activation_generation),
            route_epoch=int(activation_snapshot.route_epoch),
        )
        binding_state = (
            activation_binding,
            activation_snapshot,
            activation_payload,
        )
        ensure_current("no-capture probe")
        if result is None:
            try:
                result = self._verify_runtime_final_exit(
                    expected_worker_token=worker_token,
                    expected_snapshot=activation_snapshot,
                    timeout_seconds=max(
                        0.05,
                        min(3.0, deadline - time.monotonic()),
                    ),
                    required_successes=2,
                )
            except (
                _RuntimeProbeBudgetUnavailable,
                RuntimeControllerReadbackError,
            ):
                raise
            except Exception as probe_failure:
            # The cold-recovery clock begins when the failed leaf is bound to
            # its incident, not while the initial healthy fast path is being
            # checked.
                owner = _RuntimeActivationRecoveryOwner(
                    activation_generation=int(activation_generation),
                    worker_token=tuple(worker_token),
                    snapshot_key=tuple(activation_snapshot.snapshot_key),
                    binding_key=tuple(activation_binding.node.key),
                    facility_epoch=facility_epoch,
                    selector_intent_revision=int(selector_intent_revision),
                    lifecycle_revision=int(
                        getattr(self, "_lifecycle_revision", 0) or 0
                    ),
                    deadline_monotonic=deadline,
                )
                self._publish_runtime_egress_readiness(
                    RuntimeEgressReadinessState.ACTIVATION_HOLD,
                    validation_active=True,
                    reason="Egress recovery is running",
                    deadline_monotonic=owner.deadline_monotonic,
                    expected_activation_generation=(
                        admission_lease.activation_generation
                    ),
                    expected_lifecycle_revision=(
                        admission_lease.lifecycle_revision
                    ),
                    expected_active_activation_generation=(
                        admission_lease.activation_generation
                    ),
                    expected_selector_intent_revision=(
                        admission_lease.selector_intent_revision
                    ),
                    effective_ok=None,
                )
                result, binding_state = self._recover_initial_final_exit(
                    binding_state=binding_state,
                    probe_failure=probe_failure,
                    owner=owner,
                )
                # Recovery and capture publication share the admission lease's
                # original six-second deadline. A failed first leaf must not
                # turn one startup attempt into fresh clocks.
                (
                    activation_binding,
                    activation_snapshot,
                    activation_payload,
                ) = binding_state
        if result is None:
            raise RuntimeControllerReadbackError(
                "Initial FINAL-EXIT verification produced no data-plane result"
            )
        ensure_current("no-capture verification")
        self._record_tier3_initial_activation_stage(
            "final_exit_verified",
            activation_generation=int(activation_generation),
            status=int(result.get("status") or 0),
        )
        self._set_tier3_source_control_qualification(
            activation_snapshot,
            activation_binding,
        )

        if capture_wanted:
            try:
                expected_gateway_key = (
                    tuple(activation_binding.node.key)
                    if activation_binding.node.pool_kind == "gateway"
                    else None
                )
                with self._runtime_failure_monitor_lock:
                    route_lease = getattr(
                        self,
                        "_runtime_route_mutation_lease",
                        None,
                    )
                    pre_capture_lease = (
                        dict(route_lease)
                        if isinstance(route_lease, dict)
                        else None
                    )
                with self._bounded_core_transition(
                    deadline,
                    "initial capture reload",
                ):
                    ensure_current("capture mutation ownership")
                    self._hot_reload_runtime_config_phase(
                        runner,
                        capture_enabled=True,
                        expected_activation_generation=activation_generation,
                        expected_core_generation=core_generation,
                        deadline_monotonic=deadline,
                    )
                    ensure_current("capture reload")
                    remaining = max(0.0, deadline - time.monotonic())
                    if remaining <= 0.0:
                        raise TimeoutError(
                            "initial capture verification exceeded its deadline"
                        )
                    result = self._verify_capture_route_after_reload(
                        lease_record=pre_capture_lease,
                        expected_gateway_key=expected_gateway_key,
                        timeout_seconds=min(3.0, remaining),
                        deadline_monotonic=deadline,
                    )
                ensure_current("capture verification")
                post_capture_snapshot, post_capture_payload = (
                    self._runtime_route_snapshot_state()
                )
                post_capture_coordinator = (
                    self._runtime_egress_coordinator.current_route_snapshot()
                )
                post_capture_binding = (
                    self._runtime_route_binding_for_outbound(
                        post_capture_snapshot,
                        post_capture_payload,
                        "FINAL-EXIT",
                    )
                    if post_capture_snapshot is not None
                    and post_capture_coordinator is not None
                    and isinstance(post_capture_payload, dict)
                    else None
                )
                if (
                    post_capture_snapshot is None
                    or post_capture_coordinator is None
                    or post_capture_binding is None
                    or tuple(post_capture_snapshot.snapshot_key)
                    != tuple(post_capture_coordinator.snapshot_key)
                ):
                    raise RuntimeStartCancelled(
                        "capture verification lost its loaded FINAL-EXIT authority"
                    )
                activation_snapshot = post_capture_snapshot
                activation_payload = post_capture_payload
                activation_binding = post_capture_binding
                self._set_tier3_source_control_qualification(
                    activation_snapshot,
                    activation_binding,
                )
                self._apply_system_proxy_capture_after_core_start(runner)
                ensure_current("local capture publication")
                self._record_tier3_initial_activation_stage(
                    "capture_ready",
                    activation_generation=int(activation_generation),
                )
            except Exception:
                if (
                    self._initial_egress_admission_lease_is_current(
                        admission_lease,
                        runner,
                    )
                    and
                    runner.is_running()
                    and self._current_core_runtime_phase() == "formal_capture"
                ):
                    self._rollback_to_formal_no_capture(
                        runner,
                        "initial capture activation was not committed",
                        deadline_monotonic=deadline,
                        admission_lease=admission_lease,
                    )
                raise

        committed = False
        monitor_started = False
        try:
            with self._runtime_intent_lock:
                with self._runtime_failure_monitor_lock:
                    ensure_verified_authority("READY publication")
                    if capture_wanted:
                        self.traffic_monitor.start()
                        monitor_started = True
                    manager = self.manager
                    capture_marker = (
                        getattr(
                            manager,
                            "mark_tier3_traffic_capture_active",
                            None,
                        )
                        if manager is not None
                        else None
                    )
                    if callable(capture_marker):
                        capture_marker(capture_wanted)
                    self._mark_tier3_core_sync_success(
                        traffic_capture_active=capture_wanted,
                    )
                    ensure_verified_authority("READY state commit")
                    arm_method = self._try_arm_runtime_recovery
                    try:
                        arm_prepared = arm_method(
                            allow_pre_ready=True,
                            admission_lease=admission_lease,
                        )
                    except TypeError:
                        # Compatibility for focused adapters replacing the
                        # no-argument helper. Production takes the strict path.
                        arm_prepared = arm_method()
                    if not arm_prepared:
                        raise RuntimeControllerReadbackError(
                            "verified FINAL-EXIT could not prepare runtime recovery"
                        )
                    self._runtime_initial_activation_generation = int(
                        core_generation
                    )
                    self._publish_runtime_egress_readiness(
                        RuntimeEgressReadinessState.READY,
                        validation_active=False,
                        expected_activation_generation=(
                            admission_lease.activation_generation
                        ),
                        expected_lifecycle_revision=(
                            admission_lease.lifecycle_revision
                        ),
                        expected_active_activation_generation=(
                            admission_lease.activation_generation
                        ),
                        expected_selector_intent_revision=(
                            admission_lease.selector_intent_revision
                        ),
                        effective_ok=True,
                    )
                    if not self._runtime_recovery_is_armed(activation_snapshot):
                        raise RuntimeControllerReadbackError(
                            "verified FINAL-EXIT could not arm runtime recovery"
                        )
                    self._commit_runtime_monitoring_lease()
                    self._reset_tier3_standby_activation_failure()
                    self._record_tier3_initial_activation_stage(
                        "ready",
                        activation_generation=int(activation_generation),
                        source_control_egress_ready=(
                            self._tier3_source_control_qualification_is_current()
                        ),
                    )
                    committed = True
        except Exception:
            cleanup_owned = self._initial_egress_admission_lease_is_current(
                admission_lease,
                runner,
            )
            if cleanup_owned:
                self._runtime_initial_activation_generation = -1
                if monitor_started:
                    self.traffic_monitor.stop()
                if (
                    capture_wanted
                    and runner.is_running()
                    and self._current_core_runtime_phase() == "formal_capture"
                ):
                    self._rollback_to_formal_no_capture(
                        runner,
                        "initial READY publication was not committed",
                        deadline_monotonic=deadline,
                        admission_lease=admission_lease,
                    )
            raise
        if not committed:
            raise RuntimeError("initial egress activation was not committed")

        # READY proves this exact loaded FINAL-EXIT contract. Background capacity
        # remains deferred until an authorized reload or incident-owned rebase.
        # This is deliberately asynchronous.  A delayed `/proxies` response
        # may postpone sudden-failure recovery, but it cannot revoke proven
        # startup connectivity or produce a false controller hold.
        self._queue_runtime_route_snapshot_refresh()
        if not self._runtime_uses_early_single_coordinator():
            self._resume_deferred_runtime_failbacks()
        return result

    def _tier3_activation_authority_state(
        self,
        *,
        worker_token: tuple[int, ...],
        timeout_seconds: float = 0.75,
        require_managed_final_exit: bool = True,
    ) -> tuple[
        CoreLoadedRouteSnapshot,
        dict[str, Any],
        RuntimeRouteBinding | None,
    ]:
        """Return one complete immutable authority tuple for activation.

        The coordinator snapshot, locally retained payload and FINAL-EXIT leaf
        must all describe the same controller readback.  Any incomplete or
        mixed revision gets exactly one bounded authoritative refresh; callers
        must enter controller hold when that refresh cannot produce a complete
        tuple and may never probe an unknown selected leaf.
        """

        def payload_matches_snapshot(
            candidate_snapshot: CoreLoadedRouteSnapshot,
            candidate_payload: dict[str, Any],
        ) -> bool:
            proxies_payload = candidate_payload.get("proxies")
            graph, _selection, group_states = (
                self._runtime_group_graph_and_selection(proxies_payload)
            )
            expected_states = tuple(
                sorted(
                    candidate_snapshot.group_states,
                    key=lambda state: state.name,
                )
            )
            return bool(
                graph == tuple(candidate_snapshot.group_graph)
                and tuple(state.signature for state in group_states)
                == tuple(state.signature for state in expected_states)
            )

        coordinator_snapshot = (
            self._runtime_egress_coordinator.current_route_snapshot()
        )
        runtime_snapshot, runtime_payload = self._runtime_route_snapshot_state()
        runtime_binding: RuntimeRouteBinding | None = None
        if (
            coordinator_snapshot is not None
            and runtime_snapshot is not None
            and isinstance(runtime_payload, dict)
            and tuple(coordinator_snapshot.snapshot_key)
            == tuple(runtime_snapshot.snapshot_key)
            and payload_matches_snapshot(runtime_snapshot, runtime_payload)
        ):
            try:
                runtime_binding = self._runtime_route_binding_for_outbound(
                    runtime_snapshot,
                    runtime_payload,
                    "FINAL-EXIT",
                )
            except Exception:
                runtime_binding = None
            if (
                (
                    runtime_binding is not None
                    and runtime_snapshot.owns(runtime_binding)
                )
                or (
                    not require_managed_final_exit
                    and runtime_binding is None
                )
            ):
                return runtime_snapshot, runtime_payload, runtime_binding

        bounded_timeout = max(0.05, float(timeout_seconds))
        authority = self._refresh_loaded_runtime_authority(
            timeout_seconds=bounded_timeout,
            require_managed_final_exit=require_managed_final_exit,
            worker_token=worker_token,
        )
        if authority is None:
            raise _InitialActivationBindingPending(
                "FINAL-EXIT route readback did not complete within "
                f"{int(round(bounded_timeout * 1000.0))} ms"
            )
        refreshed_snapshot, refreshed_payload, refreshed_binding = authority
        refreshed_coordinator = (
            self._runtime_egress_coordinator.current_route_snapshot()
        )
        if (
            refreshed_coordinator is None
            or not isinstance(refreshed_snapshot, CoreLoadedRouteSnapshot)
            or not isinstance(refreshed_payload, dict)
            or not payload_matches_snapshot(
                refreshed_snapshot,
                refreshed_payload,
            )
            or (
                require_managed_final_exit
                and not isinstance(refreshed_binding, RuntimeRouteBinding)
            )
            or tuple(refreshed_coordinator.snapshot_key)
            != tuple(refreshed_snapshot.snapshot_key)
            or (
                isinstance(refreshed_binding, RuntimeRouteBinding)
                and not refreshed_snapshot.owns(refreshed_binding)
            )
        ):
            raise _InitialActivationBindingPending(
                "FINAL-EXIT route readback returned mixed authority revisions"
            )
        return refreshed_snapshot, refreshed_payload, refreshed_binding

    def _initial_egress_admission_lease_is_current(
        self,
        admission_lease: _InitialEgressAdmissionLease,
        runner: Any | None,
        *,
        strict_selector_intent: bool = True,
        require_no_successor: bool = False,
    ) -> bool:
        """Return whether a pre-READY lease may still publish a terminal."""

        if not isinstance(admission_lease, _InitialEgressAdmissionLease):
            return False
        with self._tier3_egress_activation_lock:
            if (
                int(self._tier3_egress_activation_generation)
                != int(admission_lease.activation_generation)
                or int(self._tier3_egress_activation_active_generation)
                != int(admission_lease.activation_generation)
                or (
                    require_no_successor
                    and bool(self._tier3_egress_activation_pending)
                )
            ):
                return False
        if (
            self.stop_event.is_set()
            or self.core_runner is not runner
            or int(getattr(self, "_lifecycle_revision", 0) or 0)
            != int(admission_lease.lifecycle_revision)
            or int(getattr(self, "_runtime_generation", 0) or 0)
            != int(admission_lease.runtime_generation)
            or (
                strict_selector_intent
                and int(
                    getattr(self, "_runtime_selector_intent_revision", 0) or 0
                )
                != int(admission_lease.selector_intent_revision)
            )
        ):
            return False
        with self._core_lifecycle_lock:
            if int(self._core_generation) != int(admission_lease.core_generation):
                return False
        try:
            if runner is None or not runner.is_running():
                return False
            status = runner.status()
        except Exception:
            return False
        return bool(
            int(status.get("pid") or 0) == int(admission_lease.process_pid)
            and int(status.get("process_generation") or 0)
            == int(admission_lease.process_generation)
        )

    def _cancelled_initial_egress_admission_still_owns_core(
        self,
        admission_lease: _InitialEgressAdmissionLease,
        runner: Any | None,
    ) -> bool:
        """Allow cleanup after cancellation without granting publish authority."""

        if not isinstance(admission_lease, _InitialEgressAdmissionLease):
            return False
        with self._tier3_egress_activation_lock:
            if (
                bool(self._tier3_egress_activation_pending)
                or int(self._tier3_egress_activation_active_generation)
                != int(admission_lease.activation_generation)
            ):
                return False
        if (
            self.core_runner is not runner
            or int(getattr(self, "_runtime_generation", 0) or 0)
            != int(admission_lease.runtime_generation)
        ):
            return False
        with self._core_lifecycle_lock:
            if int(self._core_generation) != int(admission_lease.core_generation):
                return False
        try:
            if runner is None or not runner.is_running():
                return False
            status = runner.status()
        except Exception:
            return False
        return bool(
            int(status.get("pid") or 0) == int(admission_lease.process_pid)
            and int(status.get("process_generation") or 0)
            == int(admission_lease.process_generation)
        )

    def _finish_cancelled_initial_egress_admission(
        self,
        *,
        admission_lease: _InitialEgressAdmissionLease | None,
        runner: Any | None,
        reason: str,
    ) -> bool:
        """Hand cancellation to one successor or publish a non-busy terminal."""

        activation_generation = int(
            getattr(admission_lease, "activation_generation", 0) or 0
        )
        successor_pending = bool(
            getattr(self, "_tier3_egress_activation_pending", False)
        )
        self._record_tier3_initial_activation_stage(
            "cancelled",
            activation_generation=activation_generation,
            successor_pending=successor_pending,
        )
        if not isinstance(admission_lease, _InitialEgressAdmissionLease):
            return False
        if not self._initial_egress_admission_lease_is_current(
            admission_lease,
            runner,
            strict_selector_intent=False,
            require_no_successor=True,
        ):
            proxy = getattr(self, "system_proxy", None)
            manager = getattr(self, "manager", None)
            uncommitted_capture_present = bool(
                self._current_core_runtime_phase() == "formal_capture"
                or getattr(proxy, "active", False)
                or (
                    getattr(manager, "tier3_traffic_capture_active", False)
                    if manager is not None
                    else False
                )
            )
            if (
                uncommitted_capture_present
                and self._cancelled_initial_egress_admission_still_owns_core(
                    admission_lease,
                    runner,
                )
            ):
                self._runtime_initial_activation_generation = -1
                self._rollback_to_formal_no_capture(
                    runner,
                    "cancelled initial admission did not commit capture",
                    admission_lease=admission_lease,
                    allow_cancelled_owner=True,
                )
            return successor_pending
        readiness = getattr(self, "_runtime_egress_readiness", None)
        if (
            not bool(getattr(readiness, "validation_active", False))
            or int(getattr(readiness, "lifecycle_revision", -1))
            != int(admission_lease.lifecycle_revision)
        ):
            return False
        terminal_reason = str(
            reason
            or "Initial FINAL-EXIT verification was cancelled without a successor"
        )
        self._publish_runtime_egress_readiness(
            RuntimeEgressReadinessState.DATA_PLANE_FAILED,
            validation_active=False,
            reason=terminal_reason,
            expected_activation_generation=admission_lease.activation_generation,
            expected_active_activation_generation=(
                admission_lease.activation_generation
            ),
            expected_lifecycle_revision=admission_lease.lifecycle_revision,
            require_no_activation_successor=True,
            effective_ok=False,
        )
        return False

    def _finish_unstarted_initial_egress_admission(
        self,
        *,
        activation_generation: int,
        reason: str,
    ) -> bool:
        """End inherited busy state when a claimed successor cannot start."""

        with self._tier3_egress_activation_lock:
            if self._tier3_egress_activation_pending:
                return True
            if int(self._tier3_egress_activation_active_generation) != int(
                activation_generation
            ):
                return False
        readiness = getattr(self, "_runtime_egress_readiness", None)
        if not bool(getattr(readiness, "validation_active", False)):
            return False
        terminal_reason = str(
            reason
            or "Initial FINAL-EXIT verification could not start"
        )
        self._publish_runtime_egress_readiness(
            RuntimeEgressReadinessState.DATA_PLANE_FAILED,
            validation_active=False,
            reason=terminal_reason,
            expected_activation_generation=activation_generation,
            expected_active_activation_generation=activation_generation,
            require_no_activation_successor=True,
            effective_ok=False,
        )
        return False

    def _start_initial_egress_admission_watchdog(
        self,
        admission_lease: _InitialEgressAdmissionLease,
    ) -> None:
        """Make the bounded startup deadline visible even if a callback stalls.

        Python cannot safely kill a thread blocked in an injected OS/Manager
        callback. The watchdog therefore revokes that worker's publication CAS
        at the absolute deadline, ends UI busy immediately, and starts at most
        one already-queued successor. Actual Core mutations use their own
        bounded lock windows, so a stalled non-Core callback cannot monopolize
        route ownership.
        """

        def watchdog() -> None:
            remaining = max(
                0.0,
                float(admission_lease.deadline_monotonic) - time.monotonic(),
            )
            if self.stop_event.wait(remaining):
                return
            successor_thread: threading.Thread | None = None
            terminal_generation = -1
            with self._tier3_egress_activation_lock:
                if int(self._tier3_egress_activation_active_generation) != int(
                    admission_lease.activation_generation
                ):
                    return
                readiness = getattr(self, "_runtime_egress_readiness", None)
                if (
                    getattr(readiness, "state", None)
                    is RuntimeEgressReadinessState.READY
                    and not bool(getattr(readiness, "validation_active", False))
                    and int(
                        getattr(
                            self,
                            "_runtime_initial_activation_generation",
                            -1,
                        )
                        or -1
                    )
                    == int(admission_lease.core_generation)
                ):
                    return
                successor_pending = bool(self._tier3_egress_activation_pending)
                self._tier3_egress_activation_generation += 1
                terminal_generation = int(
                    self._tier3_egress_activation_generation
                )
                self._tier3_egress_activation_active_generation = 0
                self._tier3_egress_activation_active_mode = ""
                self._tier3_egress_activation_active_key = None
                self._tier3_egress_activation_worker_running = False
                if successor_pending and not self.stop_event.is_set():
                    self._tier3_egress_activation_worker_running = True
                    successor_thread = threading.Thread(
                        target=self._tier3_egress_activation_worker,
                        name="desktop-tier3-egress-activation-successor",
                        daemon=True,
                    )
                    self._tier3_egress_activation_thread = successor_thread
            if successor_thread is not None:
                self._record_tier3_initial_activation_stage(
                    "deadline_successor_handoff",
                    activation_generation=admission_lease.activation_generation,
                )
                try:
                    successor_thread.start()
                except Exception as exc:
                    with self._tier3_egress_activation_lock:
                        if (
                            self._tier3_egress_activation_thread
                            is successor_thread
                            and int(self._tier3_egress_activation_generation)
                            == terminal_generation
                        ):
                            self._tier3_egress_activation_pending = False
                            self._tier3_egress_activation_pending_mode = ""
                            self._tier3_egress_activation_pending_key = None
                            self._tier3_egress_activation_worker_running = False
                            self._tier3_egress_activation_thread = None
                    reason = (
                        "Initial FINAL-EXIT verification successor could not start "
                        f"({type(exc).__name__})"
                    )
                    self._runtime_initial_activation_generation = -1
                    self._publish_runtime_egress_readiness(
                        RuntimeEgressReadinessState.DATA_PLANE_FAILED,
                        validation_active=False,
                        reason=reason,
                        expected_activation_generation=terminal_generation,
                        require_no_activation_successor=True,
                        effective_ok=False,
                    )
                    self._record_tier3_initial_activation_stage(
                        "deadline_successor_start_failed",
                        activation_generation=(
                            admission_lease.activation_generation
                        ),
                        error_type=type(exc).__name__,
                    )
                return
            self._runtime_initial_activation_generation = -1
            reason = (
                "Initial FINAL-EXIT verification reached its bounded deadline"
            )
            # Publish local terminal truth first. The publisher stores the
            # readiness object before any optional Manager notification, so a
            # blocked observer cannot keep the UI busy.
            self._publish_runtime_egress_readiness(
                RuntimeEgressReadinessState.DATA_PLANE_FAILED,
                validation_active=False,
                reason=reason,
                expected_activation_generation=terminal_generation,
                expected_lifecycle_revision=admission_lease.lifecycle_revision,
                require_no_activation_successor=True,
                effective_ok=False,
            )
            self._record_tier3_initial_activation_stage(
                "deadline_terminal",
                activation_generation=admission_lease.activation_generation,
            )

        threading.Thread(
            target=watchdog,
            name="desktop-initial-egress-admission-watchdog",
            daemon=True,
        ).start()

    def _tier3_egress_activation_worker_early(self) -> None:
        """Run one activation/revalidation per external authority change."""

        claimed_request = False
        try:
            while True:
                with self._tier3_egress_activation_lock:
                    if not self._tier3_egress_activation_pending:
                        self._tier3_egress_activation_worker_running = False
                        self._tier3_egress_activation_active_mode = ""
                        self._tier3_egress_activation_active_key = None
                        self._tier3_egress_activation_active_generation = 0
                        return
                    if claimed_request:
                        self._tier3_egress_activation_generation += 1
                    self._tier3_egress_activation_pending = False
                    mode = self._tier3_egress_activation_pending_mode or "activation"
                    self._tier3_egress_activation_pending_mode = ""
                    self._tier3_egress_activation_active_key = (
                        self._tier3_egress_activation_pending_key
                    )
                    active_request_key = self._tier3_egress_activation_active_key
                    self._tier3_egress_activation_pending_key = None
                    activation_generation = int(
                        self._tier3_egress_activation_generation
                    )
                    self._tier3_egress_activation_active_generation = (
                        activation_generation
                    )
                    self._tier3_egress_activation_active_mode = mode
                    claimed_request = True
                admission_lease: _InitialEgressAdmissionLease | None = None
                try:
                    if self.stop_event.is_set():
                        if mode == "activation":
                            self._record_tier3_initial_activation_stage(
                                "cancelled",
                                activation_generation=activation_generation,
                                reason="runtime stop was already requested",
                            )
                            self._finish_unstarted_initial_egress_admission(
                                activation_generation=activation_generation,
                                reason="runtime stop was already requested",
                            )
                        continue
                    runner = self.core_runner
                    if runner is None or not runner.is_running():
                        if mode == "activation":
                            self._record_tier3_initial_activation_stage(
                                "cancelled",
                                activation_generation=activation_generation,
                                reason="Core stopped before admission began",
                            )
                            self._finish_unstarted_initial_egress_admission(
                                activation_generation=activation_generation,
                                reason="Core stopped before admission began",
                            )
                        continue
                    requested_mode = mode
                    mode = self._revalidation_mode_for_runtime_state(
                        mode,
                        source="early_worker",
                    )
                    if mode is None:
                        if requested_mode == "activation":
                            self._finish_unstarted_initial_egress_admission(
                                activation_generation=activation_generation,
                                reason=(
                                    "Initial FINAL-EXIT verification no longer "
                                    "matches the current runtime state"
                                ),
                            )
                        continue
                    with self._core_lifecycle_lock:
                        core_generation = int(self._core_generation)
                    worker_token = self._runtime_worker_token()
                    selector_revision = int(
                        getattr(self, "_runtime_selector_intent_revision", 0)
                        or 0
                    )
                    if mode == "activation":
                        runner_status = runner.status()
                        admission_lease = _InitialEgressAdmissionLease(
                            activation_generation=activation_generation,
                            lifecycle_revision=int(
                                getattr(self, "_lifecycle_revision", 0) or 0
                            ),
                            runtime_generation=int(
                                getattr(self, "_runtime_generation", 0) or 0
                            ),
                            core_generation=core_generation,
                            process_pid=int(runner_status.get("pid") or 0),
                            process_generation=int(
                                runner_status.get("process_generation") or 0
                            ),
                            selector_intent_revision=selector_revision,
                            worker_token=tuple(worker_token),
                            deadline_monotonic=(
                                time.monotonic()
                                + _INITIAL_EGRESS_ADMISSION_DEADLINE_SECONDS
                            ),
                            authority_key=(
                                tuple(active_request_key[1])
                                if isinstance(active_request_key, tuple)
                                and len(active_request_key) == 2
                                and isinstance(active_request_key[1], tuple)
                                else tuple(self._tier3_standby_activation_key())
                            ),
                        )
                        self._record_tier3_initial_activation_stage(
                            "lease_started",
                            activation_generation=activation_generation,
                            core_generation=core_generation,
                        )
                        self._start_initial_egress_admission_watchdog(
                            admission_lease
                        )
                        self._run_initial_egress_activation_serialized(
                            runner=runner,
                            activation_generation=activation_generation,
                            core_generation=core_generation,
                            selector_intent_revision=selector_revision,
                            worker_token=worker_token,
                            admission_lease=admission_lease,
                        )
                        continue
                    binding_state = self._current_runtime_failure_binding_state(
                        timeout_seconds=0.75,
                        refresh=True,
                    )
                    if binding_state is None:
                        try:
                            refreshed_authority = (
                                self._refresh_loaded_runtime_authority(
                                    timeout_seconds=0.75,
                                    require_managed_final_exit=True,
                                    worker_token=worker_token,
                                )
                            )
                        except TypeError:
                            refreshed_authority = (
                                self._refresh_loaded_runtime_authority()
                            )
                        except Exception:
                            refreshed_authority = None
                        if (
                            isinstance(refreshed_authority, tuple)
                            and len(refreshed_authority) == 3
                            and isinstance(
                                refreshed_authority[0],
                                CoreLoadedRouteSnapshot,
                            )
                            and isinstance(refreshed_authority[1], dict)
                            and isinstance(
                                refreshed_authority[2], RuntimeRouteBinding
                            )
                        ):
                            refreshed_snapshot, refreshed_payload, refreshed_binding = (
                                refreshed_authority
                            )
                            binding_state = (
                                refreshed_binding,
                                refreshed_snapshot,
                                refreshed_payload,
                            )
                    if binding_state is None:
                        reason = (
                            "FINAL-EXIT revalidation has no stable managed "
                            "route binding"
                        )
                        self._set_effective_egress_readiness_state(False, reason)
                        self._publish_runtime_egress_readiness(
                            RuntimeEgressReadinessState.CONTROLLER_HOLD,
                            validation_active=False,
                            reason=reason,
                        )
                        continue
                    expected_snapshot = (
                        binding_state[1] if binding_state is not None else None
                    )
                    try:
                        result = self._verify_runtime_final_exit(
                            expected_worker_token=worker_token,
                            expected_snapshot=expected_snapshot,
                            timeout_seconds=3.0,
                            require_controller_ready=True,
                        )
                    except Exception as probe_failure:
                        submission: bool | _RuntimeRecoveryTicket = False
                        if binding_state is not None:
                            self._try_arm_runtime_recovery()
                            submission = self._submit_current_route_probe_failure(
                                "Incremental FINAL-EXIT 204 failed: "
                                f"{type(probe_failure).__name__}",
                                source="runtime_probe",
                                binding_state=binding_state,
                                binding_captured=True,
                            )
                        outcome = (
                            self._wait_runtime_recovery_outcome(submission)
                            if isinstance(submission, _RuntimeRecoveryTicket)
                            else None
                        )
                        if not (
                            isinstance(outcome, RuntimeRecoveryOutcome)
                            and outcome.status is RuntimeRecoveryStatus.RECOVERED
                        ):
                            reason = (
                                "FINAL-EXIT revalidation ended without a "
                                "verified replacement"
                            )
                            self._record_tier3_standby_activation_indeterminate(
                                reason,
                                authority_key=self._tier3_standby_activation_key(),
                            )
                            self._set_effective_egress_readiness_state(
                                False,
                                reason,
                            )
                            self._publish_runtime_egress_readiness(
                                RuntimeEgressReadinessState.DATA_PLANE_FAILED,
                                validation_active=False,
                                reason=reason,
                            )
                            continue
                        result = {
                            "runtime_recovery_outcome": outcome.to_dict()
                        }
                    del result
                    self._reset_tier3_standby_activation_failure()
                    self._set_effective_egress_state(True, "")
                    self._publish_runtime_egress_readiness(
                        RuntimeEgressReadinessState.READY,
                        validation_active=False,
                    )
                    if not self._try_arm_runtime_recovery():
                        reason = (
                            "FINAL-EXIT revalidation could not arm its managed "
                            "route binding"
                        )
                        self._set_effective_egress_readiness_state(False, reason)
                        self._publish_runtime_egress_readiness(
                            RuntimeEgressReadinessState.CONTROLLER_HOLD,
                            validation_active=False,
                            reason=reason,
                        )
                except RuntimeStartCancelled as exc:
                    if mode == "activation":
                        self._finish_cancelled_initial_egress_admission(
                            admission_lease=admission_lease,
                            runner=locals().get("runner"),
                            reason=str(exc),
                        )
                    continue
                except Exception as exc:
                    if mode == "activation":
                        with self._tier3_egress_activation_lock:
                            successor_pending = bool(
                                self._tier3_egress_activation_pending
                            )
                        if successor_pending:
                            self._record_tier3_initial_activation_stage(
                                "successor_handoff",
                                activation_generation=int(
                                    activation_generation
                                ),
                                error_type=type(exc).__name__,
                            )
                            continue
                    if mode == "activation" and (
                        not isinstance(admission_lease, _InitialEgressAdmissionLease)
                    ):
                        self._finish_unstarted_initial_egress_admission(
                            activation_generation=activation_generation,
                            reason=str(exc),
                        )
                        self._record_tier3_initial_activation_stage(
                            "terminal_unstarted",
                            activation_generation=int(activation_generation),
                            error_type=type(exc).__name__,
                        )
                        continue
                    if mode == "activation" and (
                        not self._initial_egress_admission_lease_is_current(
                            admission_lease,
                            locals().get("runner"),
                        )
                    ):
                        self._finish_cancelled_initial_egress_admission(
                            admission_lease=admission_lease,
                            runner=locals().get("runner"),
                            reason=str(exc),
                        )
                        self._record_tier3_initial_activation_stage(
                            "terminal_superseded",
                            activation_generation=int(activation_generation),
                            error_type=type(exc).__name__,
                        )
                        continue
                    if (
                        mode == "activation"
                        and isinstance(exc, _InitialActivationBindingPending)
                    ):
                        reason = (
                            "Initial FINAL-EXIT activation is waiting for one "
                            "stable loaded route binding"
                        )
                        self._record_tier3_initial_activation_stage(
                            "binding_pending",
                            activation_generation=int(activation_generation),
                            retryable=True,
                        )
                        self._record_tier3_controller_hold(
                            reason,
                            authority_key=tuple(admission_lease.authority_key),
                        )
                        # Controller uncertainty is neutral and retryable. Keep
                        # the Core in no-capture standby; provider/config events
                        # will enqueue one successor for the changed authority.
                        self._publish_runtime_egress_readiness(
                            RuntimeEgressReadinessState.CONTROLLER_HOLD,
                            validation_active=False,
                            reason=reason,
                            expected_activation_generation=(
                                admission_lease.activation_generation
                            ),
                            expected_active_activation_generation=(
                                admission_lease.activation_generation
                            ),
                            expected_lifecycle_revision=(
                                admission_lease.lifecycle_revision
                            ),
                            expected_selector_intent_revision=(
                                admission_lease.selector_intent_revision
                            ),
                            require_no_activation_successor=True,
                            effective_ok=False,
                        )
                        continue
                    reason = (
                        "FINAL-EXIT activation ended without a verified route "
                        f"({type(exc).__name__})"
                    )
                    self._record_tier3_standby_activation_indeterminate(
                        reason,
                        authority_key=(
                            tuple(admission_lease.authority_key)
                            if isinstance(
                                admission_lease,
                                _InitialEgressAdmissionLease,
                            )
                            else self._tier3_standby_activation_key()
                        ),
                    )
                    # An unexpected revalidation failure is not evidence that
                    # the previously selected non-Gateway route is still
                    # usable.  Reasserting SERVING here recreated the exact
                    # split-brain this admission gate is meant to prevent:
                    # source traffic could reopen while no current-generation
                    # binding had completed a data-plane proof.
                    if mode == "activation":
                        self._publish_runtime_egress_readiness(
                            RuntimeEgressReadinessState.DATA_PLANE_FAILED,
                            validation_active=False,
                            reason=reason,
                            expected_activation_generation=(
                                admission_lease.activation_generation
                            ),
                            expected_active_activation_generation=(
                                admission_lease.activation_generation
                            ),
                            expected_lifecycle_revision=(
                                admission_lease.lifecycle_revision
                            ),
                            expected_selector_intent_revision=(
                                admission_lease.selector_intent_revision
                            ),
                            require_no_activation_successor=True,
                            effective_ok=False,
                        )
                    else:
                        self._set_effective_egress_readiness_state(False, reason)
                        self._publish_runtime_egress_readiness(
                            RuntimeEgressReadinessState.DATA_PLANE_FAILED,
                            validation_active=False,
                            reason=reason,
                        )
                    if mode == "activation":
                        self._record_tier3_initial_activation_stage(
                            "terminal",
                            activation_generation=int(
                                activation_generation
                            ),
                            failure_stage="activation",
                            error_type=type(exc).__name__,
                            reason=str(exc),
                        )
                finally:
                    with self._tier3_egress_activation_lock:
                        if int(
                            self._tier3_egress_activation_active_generation
                        ) != int(activation_generation):
                            return
                        self._tier3_egress_activation_active_mode = ""
                        self._tier3_egress_activation_active_key = None
                        self._tier3_egress_activation_active_generation = 0
                    if mode == "activation":
                        self._wake_parked_tier3_pool_sync_if_causal_key_changed()
        finally:
            with self._tier3_egress_activation_lock:
                if (
                    self._tier3_egress_activation_thread
                    is threading.current_thread()
                    and not self._tier3_egress_activation_pending
                ):
                    self._tier3_egress_activation_worker_running = False
                    self._tier3_egress_activation_active_mode = ""
                    self._tier3_egress_activation_active_key = None
                    self._tier3_egress_activation_active_generation = 0

    def _tier3_egress_activation_worker(self) -> None:
        if self._runtime_uses_early_single_coordinator():
            self._tier3_egress_activation_worker_early()
            return
        claimed_request = False
        try:
            while True:
                with self._tier3_egress_activation_lock:
                    if not self._tier3_egress_activation_pending:
                        self._tier3_egress_activation_worker_running = False
                        self._tier3_egress_activation_active_mode = ""
                        self._tier3_egress_activation_active_generation = 0
                        return
                    if claimed_request:
                        self._tier3_egress_activation_generation += 1
                    self._tier3_egress_activation_pending = False
                    activation_mode = (
                        self._tier3_egress_activation_pending_mode
                        or "activation"
                    )
                    self._tier3_egress_activation_pending_mode = ""
                    activation_request_key = getattr(
                        self,
                        "_tier3_egress_activation_pending_key",
                        None,
                    )
                    self._tier3_egress_activation_pending_key = None
                    self._tier3_egress_activation_active_key = (
                        activation_request_key
                    )
                    activation_generation = self._tier3_egress_activation_generation
                    self._tier3_egress_activation_active_generation = int(
                        activation_generation
                    )
                    claimed_request = True
                    activation_terminal_authority_key = (
                        tuple(activation_request_key[1])
                        if isinstance(activation_request_key, tuple)
                        and len(activation_request_key) == 2
                        and isinstance(activation_request_key[1], tuple)
                        else None
                    )
                pressure_lease = None
                runtime_worker_token: tuple[int, ...] | None = None
                runtime_initial_activation_path = False
                activation_selector_intent_revision = int(
                    getattr(
                        self,
                        "_runtime_selector_intent_revision",
                        0,
                    )
                    or 0
                )
                try:
                    if self.stop_event.is_set():
                        continue
                    runner = self.core_runner
                    if runner is None or not runner.is_running():
                        if activation_mode == "incremental":
                            self._set_effective_egress_state(
                                False,
                                "Mihomo configuration changed but the core stopped before FINAL-EXIT recheck",
                            )
                        continue
                    activation_mode = self._revalidation_mode_for_runtime_state(
                        activation_mode,
                        source="worker",
                    )
                    if activation_mode is None:
                        continue
                    with self._tier3_egress_activation_lock:
                        self._tier3_egress_activation_active_mode = activation_mode
                    with self._core_lifecycle_lock:
                        activation_core_generation = self._core_generation
                    pressure = getattr(self, "_runtime_recovery_pressure", None)
                    if (
                        pressure is not None
                        and not self._runtime_uses_early_single_coordinator()
                    ):
                        pressure_lease = pressure.acquire(
                            (
                                "activation:"
                                f"{activation_core_generation}:"
                                f"{activation_generation}"
                            ),
                            RuntimeRecoveryPressurePriority.ACTIVATION,
                            lifecycle_generation=pressure.lifecycle_generation,
                        )
                        if pressure_lease is None:
                            raise _RuntimeProbeBudgetUnavailable(
                                "runtime recovery pressure is owned by a newer transaction"
                            )
                    runtime_worker_token = self._runtime_worker_token()
                    activation_selector_intent_revision = int(
                        getattr(
                            self,
                            "_runtime_selector_intent_revision",
                            0,
                        )
                        or 0
                    )
                    if (
                        activation_mode == "activation"
                        and hasattr(self, "_runtime_recovery_arm")
                    ):
                        runtime_initial_activation_path = True
                        runner_status = runner.status()
                        admission_lease = _InitialEgressAdmissionLease(
                            activation_generation=int(activation_generation),
                            lifecycle_revision=int(
                                getattr(self, "_lifecycle_revision", 0) or 0
                            ),
                            runtime_generation=int(
                                getattr(self, "_runtime_generation", 0) or 0
                            ),
                            core_generation=int(activation_core_generation),
                            process_pid=int(runner_status.get("pid") or 0),
                            process_generation=int(
                                runner_status.get("process_generation") or 0
                            ),
                            selector_intent_revision=(
                                activation_selector_intent_revision
                            ),
                            worker_token=tuple(runtime_worker_token),
                            deadline_monotonic=time.monotonic() + 6.0,
                            authority_key=(
                                tuple(activation_terminal_authority_key)
                                if isinstance(
                                    activation_terminal_authority_key,
                                    tuple,
                                )
                                else tuple(self._tier3_standby_activation_key())
                            ),
                        )
                        self._run_initial_egress_activation(
                            runner=runner,
                            activation_generation=activation_generation,
                            core_generation=activation_core_generation,
                            selector_intent_revision=(
                                activation_selector_intent_revision
                            ),
                            worker_token=runtime_worker_token,
                            admission_lease=admission_lease,
                        )
                        self.logger.info(
                            "Initial egress activation completed after full 204 verification "
                            "(generation=%s)",
                            activation_generation,
                        )
                        continue
                    (
                        activation_snapshot,
                        activation_payload,
                        activation_binding,
                    ) = self._tier3_activation_authority_state(
                        worker_token=runtime_worker_token,
                    )
                    activation_binding_state = (
                        activation_binding,
                        activation_snapshot,
                        activation_payload,
                    )
                    authoritative_request_key = (
                        activation_mode,
                        self._tier3_standby_activation_key(),
                    )
                    with self._tier3_egress_activation_lock:
                        pending_key = getattr(
                            self,
                            "_tier3_egress_activation_pending_key",
                            None,
                        )
                        coordinator_snapshot = (
                            self._runtime_egress_coordinator.current_route_snapshot()
                        )
                        frozen_authority_is_current = bool(
                            coordinator_snapshot is not None
                            and tuple(coordinator_snapshot.snapshot_key)
                            == tuple(activation_snapshot.snapshot_key)
                            and self._runtime_worker_token_is_current(
                                runtime_worker_token
                            )
                            and int(
                                getattr(
                                    self,
                                    "_runtime_selector_intent_revision",
                                    0,
                                )
                                or 0
                            )
                            == activation_selector_intent_revision
                        )
                        if (
                            frozen_authority_is_current
                            and
                            self._tier3_egress_activation_pending
                            and pending_key == authoritative_request_key
                        ):
                            # A tick can observe K1 after this worker's bounded
                            # K0->K1 readback but before it rebinds active_key.
                            # Consume that identical pending request here and
                            # let this worker own its latest generation; do not
                            # run the same authoritative 204/recovery twice.
                            activation_generation = int(
                                self._tier3_egress_activation_generation
                            )
                            self._tier3_egress_activation_pending = False
                            self._tier3_egress_activation_pending_mode = ""
                            self._tier3_egress_activation_pending_key = None
                            self._tier3_egress_activation_active_key = (
                                authoritative_request_key
                            )
                        elif (
                            frozen_authority_is_current
                            and
                            int(activation_generation)
                            == int(self._tier3_egress_activation_generation)
                        ):
                            # The bounded authority refresh above may be the
                            # first readback that fills the route signature.
                            # Rebind this transaction to that exact signature
                            # so ticks arriving during its probe coalesce with
                            # it instead of manufacturing a second generation.
                            self._tier3_egress_activation_active_key = (
                                authoritative_request_key
                            )
                        active_key = getattr(
                            self,
                            "_tier3_egress_activation_active_key",
                            None,
                        )
                        if (
                            active_key == authoritative_request_key
                            and isinstance(authoritative_request_key[1], tuple)
                        ):
                            # Bind every terminal/hold publication to the same
                            # immutable authority this worker owns. A K2 route
                            # or health change arriving while K1 is probing
                            # must remain queueable instead of being mislabeled
                            # as K1's terminal result.
                            activation_terminal_authority_key = tuple(
                                authoritative_request_key[1]
                            )
                    if activation_mode == "incremental":
                        no_capture_incremental = (
                            self._current_core_runtime_phase()
                            == "formal_no_capture"
                            and not self._runtime_traffic_capture_wanted()
                        )
                        last_probe_error: Exception | None = None
                        qualification_probe_endpoint = ""
                        # One full 204 failure enters the canonical incident
                        # transaction immediately. Candidate confirmation and
                        # selector recovery already own the bounded retry
                        # budget; an outer 250 ms loop only repeats the failed
                        # leaf and can supersede its own recovery generation.
                        max_attempts = 1
                        for attempt in range(1, max_attempts + 1):
                            try:
                                (
                                    runtime_probe_hold_epoch,
                                    runtime_probe_facility_epoch,
                                ) = self._runtime_facility_hold_cas_token()
                                runtime_snapshot = activation_snapshot
                                runtime_mutation_binding = (
                                    self._runtime_mutation_binding_for_snapshot(
                                        runtime_snapshot
                                    )
                                )
                                try:
                                    result = self._verify_runtime_final_exit(
                                        expected_worker_token=runtime_worker_token,
                                        expected_snapshot=runtime_snapshot,
                                        timeout_seconds=3.0,
                                    )
                                except _RuntimeProbeBudgetUnavailable:
                                    raise
                                except RuntimeControllerReadbackError:
                                    raise
                                except Exception as initial_probe_error:
                                    # The recheck already owns one complete
                                    # immutable controller binding. Feed its
                                    # first real 204 failure into the same
                                    # canonical recovery transaction in both
                                    # standby and formal capture; probing again
                                    # here would create a second observation
                                    # against a possibly newer leaf.
                                    activation_result = (
                                        self._verify_tier3_final_exit_for_activation(
                                            binding_state=activation_binding_state,
                                            known_probe_failure=initial_probe_error,
                                        )
                                    )
                                    recovery_result = (
                                        activation_result.get(
                                            "runtime_recovery_outcome"
                                        )
                                        if isinstance(activation_result, dict)
                                        else None
                                    )
                                    if not (
                                        isinstance(recovery_result, dict)
                                        and str(
                                            recovery_result.get("status") or ""
                                        )
                                        == RuntimeRecoveryStatus.RECOVERED.value
                                    ):
                                        raise RuntimeControllerReadbackError(
                                            "FINAL-EXIT recovery did not "
                                            "return an authoritative recovered outcome"
                                        ) from initial_probe_error
                                    rebound_authority = (
                                        self._refresh_loaded_runtime_authority(
                                            timeout_seconds=0.35,
                                            require_managed_final_exit=True,
                                            worker_token=(
                                                self._runtime_worker_token()
                                            ),
                                        )
                                    )
                                    if rebound_authority is None:
                                        raise RuntimeControllerReadbackError(
                                            "Recovered route could not be rebound"
                                        ) from initial_probe_error
                                    (
                                        activation_snapshot,
                                        activation_payload,
                                        activation_binding,
                                    ) = rebound_authority
                                    activation_binding_state = (
                                        activation_binding,
                                        activation_snapshot,
                                        activation_payload,
                                    )
                                    runtime_snapshot = activation_snapshot
                                    runtime_mutation_binding = (
                                        self._runtime_mutation_binding_for_snapshot(
                                            runtime_snapshot
                                        )
                                    )
                                    (
                                        runtime_probe_hold_epoch,
                                        runtime_probe_facility_epoch,
                                    ) = self._runtime_facility_hold_cas_token()
                                    result = activation_result
                                facility_hold = self._runtime_facility_hold_reason()
                                if facility_hold:
                                    if not self._release_runtime_network_context_hold_after_verified_probe(
                                        expected_mutation_binding=(
                                            runtime_mutation_binding
                                        ),
                                        expected_hold_epoch=(
                                            runtime_probe_hold_epoch
                                        ),
                                        expected_facility_epoch=(
                                            runtime_probe_facility_epoch
                                        ),
                                    ):
                                        raise RuntimeError(
                                            "runtime facility hold changed during "
                                            "FINAL-EXIT verification"
                                        )
                                    current_snapshot = (
                                        self._runtime_egress_coordinator.current_route_snapshot()
                                    )
                                    runtime_mutation_binding = (
                                        self._runtime_mutation_binding_for_snapshot(
                                            current_snapshot
                                        )
                                        if current_snapshot is not None
                                        else None
                                    )
                                if (
                                    runtime_mutation_binding is not None
                                    and not self._runtime_mutation_binding_is_current(
                                        runtime_mutation_binding
                                    )
                                ) or self._runtime_facility_hold_reason():
                                    raise RuntimeError(
                                        "runtime FINAL-EXIT verification binding "
                                        "was superseded before publication"
                                    )
                                runtime_publish_facility_epoch = int(
                                    getattr(
                                        self,
                                        "_runtime_facility_epoch",
                                        0,
                                    )
                                    or 0
                                )
                                if self._tier3_is_primary_export():
                                    controller_payload = (
                                        activation_payload.get("proxies")
                                    )
                                    if isinstance(controller_payload, dict):
                                        with self._tier3_runtime_qualification_lock:
                                            self._tier3_runtime_controller_snapshot = (
                                                int(
                                                    self._tier3_runtime_config_generation
                                                ),
                                                str(
                                                    self._tier3_runtime_config_digest
                                                ),
                                                controller_payload,
                                            )
                                    self._set_tier3_runtime_final_exit_qualification(
                                        True
                                    )
                                    qualification_probe_endpoint = str(
                                        result.get("url") or "FINAL-EXIT"
                                    )
                            except _RuntimeProbeBudgetUnavailable:
                                # No socket verdict exists.  Let the outer
                                # activation owner record an indeterminate
                                # capacity wait; continuing this block would
                                # publish readiness with uninitialised/stale
                                # route CAS state and can self-drive the
                                # activation failure loop.
                                raise
                            except Exception as exc:
                                last_probe_error = exc
                                if not self._tier3_egress_activation_is_current(
                                    activation_generation,
                                    runner,
                                    activation_core_generation,
                                ):
                                    break
                                if attempt >= max_attempts:
                                    raise
                                if self.stop_event.wait(
                                    max(
                                        0.0,
                                        float(
                                            self._incremental_egress_recheck_retry_delay_seconds
                                        ),
                                    )
                                ):
                                    break
                                continue
                            last_probe_error = None
                            break
                        if last_probe_error is not None:
                            if not self._tier3_egress_activation_is_current(
                                activation_generation,
                                runner,
                                activation_core_generation,
                            ):
                                continue
                            raise last_probe_error
                        if not self._tier3_egress_activation_is_current(
                            activation_generation,
                            runner,
                            activation_core_generation,
                        ):
                            continue
                        if (
                            self._current_core_runtime_phase()
                            == "formal_no_capture"
                            and not self._runtime_traffic_capture_wanted()
                        ):
                            manager = self.manager
                            capture_marker = (
                                getattr(
                                    manager,
                                    "mark_tier3_traffic_capture_active",
                                    None,
                                )
                                if manager is not None
                                else None
                            )
                            if callable(capture_marker):
                                capture_marker(False)
                        if self._publish_verified_incremental_egress(
                            mutation_binding=runtime_mutation_binding,
                            facility_epoch=runtime_publish_facility_epoch,
                        ) is None:
                            raise RuntimeError(
                                "runtime FINAL-EXIT verification was superseded "
                                "before readiness publication"
                            )
                        # A manual/config route mutation revokes the previous
                        # live-failure arm.  Re-arm only after the replacement
                        # route has passed the complete FINAL-EXIT check and
                        # its readiness publication CAS above.
                        if not self._try_arm_runtime_recovery():
                            self._queue_runtime_route_snapshot_refresh()
                        self._reset_tier3_standby_activation_failure()
                        self._resume_deferred_runtime_failbacks()
                        if qualification_probe_endpoint:
                            # Controller/leaf evidence can require another
                            # `/proxies` read. It enriches Tier3 bookkeeping but
                            # must never delay publication of the proven 204
                            # data plane used by real application connections.
                            self._queue_selected_tier3_leaf_qualification(
                                probe_endpoint=qualification_probe_endpoint,
                            )
                        self.logger.info(
                            "Verified FINAL-EXIT 204 connectivity after incremental Mihomo reload "
                            "(generation=%s)",
                            activation_generation,
                        )
                        continue
                    activation_mutation_binding = (
                        self._runtime_mutation_binding_for_snapshot(
                            activation_snapshot
                        )
                    )
                    (
                        activation_probe_hold_epoch,
                        activation_probe_facility_epoch,
                    ) = self._runtime_facility_hold_cas_token()
                    self._publish_runtime_egress_readiness(
                        RuntimeEgressReadinessState.ACTIVATION_HOLD,
                        validation_active=True,
                        reason="FINAL-EXIT data-plane verification is running",
                        deadline_monotonic=time.monotonic() + 6.0,
                    )
                    activation_verifier = (
                        self._verify_tier3_final_exit_for_activation
                    )
                    try:
                        verifier_parameters = inspect.signature(
                            activation_verifier
                        ).parameters.values()
                    except (TypeError, ValueError):
                        verifier_parameters = ()
                    if any(
                        parameter.kind is inspect.Parameter.VAR_KEYWORD
                        or parameter.name == "binding_state"
                        for parameter in verifier_parameters
                    ):
                        activation_result = activation_verifier(
                            binding_state=activation_binding_state,
                        )
                    else:
                        activation_result = activation_verifier()
                    recovery_result = (
                        activation_result.get("runtime_recovery_outcome")
                        if isinstance(activation_result, dict)
                        else None
                    )
                    if (
                        isinstance(recovery_result, dict)
                        and str(recovery_result.get("status") or "")
                        == RuntimeRecoveryStatus.RECOVERED.value
                    ):
                        # The successful recovery deliberately advanced the
                        # route epoch. Rebind activation publication to that
                        # exact readback instead of rejecting the valid CAS as
                        # a change relative to the failed leaf.
                        rebound_authority = self._refresh_loaded_runtime_authority(
                            timeout_seconds=0.35,
                            require_managed_final_exit=True,
                            worker_token=self._runtime_worker_token(),
                        )
                        if rebound_authority is None:
                            raise RuntimeControllerReadbackError(
                                "Recovered activation route could not be rebound"
                            )
                        (
                            activation_snapshot,
                            activation_payload,
                            _activation_binding,
                        ) = rebound_authority
                        activation_mutation_binding = (
                            self._runtime_mutation_binding_for_snapshot(
                                activation_snapshot
                            )
                        )
                        (
                            activation_probe_hold_epoch,
                            activation_probe_facility_epoch,
                        ) = self._runtime_facility_hold_cas_token()
                    facility_hold = self._runtime_facility_hold_reason()
                    if facility_hold:
                        if (
                            activation_mutation_binding is None
                            or not self._release_runtime_network_context_hold_after_verified_probe(
                                expected_mutation_binding=(
                                    activation_mutation_binding
                                ),
                                expected_hold_epoch=(
                                    activation_probe_hold_epoch
                                ),
                                expected_facility_epoch=(
                                    activation_probe_facility_epoch
                                ),
                            )
                        ):
                            raise RuntimeError(
                                "runtime facility hold changed during Bastion "
                                "activation verification"
                            )
                    elif (
                        activation_mutation_binding is not None
                        and not self._runtime_mutation_binding_is_current(
                            activation_mutation_binding
                        )
                    ):
                        raise RuntimeError(
                            "Bastion activation route changed during verification"
                        )
                    activation_publish_facility_epoch = int(
                        getattr(self, "_runtime_facility_epoch", 0) or 0
                    )
                    if not self._tier3_egress_activation_is_current(
                        activation_generation,
                        runner,
                        activation_core_generation,
                    ):
                        continue
                    pre_capture_snapshot, pre_capture_payload = (
                        self._runtime_route_snapshot_state()
                    )
                    pre_capture_binding = (
                        self._runtime_route_binding_for_outbound(
                            pre_capture_snapshot,
                            pre_capture_payload,
                            "FINAL-EXIT",
                        )
                        if pre_capture_snapshot is not None
                        and isinstance(pre_capture_payload, dict)
                        else None
                    )
                    expected_gateway_key = (
                        tuple(pre_capture_binding.node.key)
                        if pre_capture_binding is not None
                        and pre_capture_binding.node.pool_kind == "gateway"
                        else None
                    )
                    with self._runtime_failure_monitor_lock:
                        route_lease = getattr(
                            self,
                            "_runtime_route_mutation_lease",
                            None,
                        )
                        pre_capture_lease = (
                            dict(route_lease)
                            if isinstance(route_lease, dict)
                            else None
                        )
                    self._hot_reload_runtime_config_phase(
                        runner,
                        capture_enabled=True,
                        expected_activation_generation=activation_generation,
                        expected_core_generation=activation_core_generation,
                    )
                    self._verify_capture_route_after_reload(
                        lease_record=pre_capture_lease,
                        expected_gateway_key=expected_gateway_key,
                        timeout_seconds=3.0,
                    )
                    if not self._tier3_egress_activation_is_current(
                        activation_generation,
                        runner,
                        activation_core_generation,
                    ):
                        self._rollback_to_formal_no_capture(
                            runner,
                            "activation superseded after capture config reload",
                        )
                        continue
                    self._apply_system_proxy_capture_after_core_start(runner)
                    activation_committed = False
                    traffic_monitor_started = False
                    try:
                        # Linearize the final local traffic start and business
                        # state publication against request_stop(). The work
                        # inside this lock is memory-only plus Thread.start().
                        # Runtime start/stop already linearizes as
                        # intent -> failure-monitor. Preserve that global lock
                        # order here while still holding the facility lock for
                        # the final epoch check and readiness publication.
                        with self._runtime_intent_lock:
                            with self._runtime_failure_monitor_lock:
                                if self._tier3_egress_activation_is_current(
                                    activation_generation,
                                    runner,
                                    activation_core_generation,
                                ) and (
                                    not self._runtime_facility_hold_reason()
                                    and int(
                                        getattr(
                                            self,
                                            "_runtime_facility_epoch",
                                            0,
                                        )
                                        or 0
                                    )
                                    == activation_publish_facility_epoch
                                ):
                                    self.traffic_monitor.start()
                                    traffic_monitor_started = True
                                    manager = self.manager
                                    capture_marker = (
                                        getattr(
                                            manager,
                                            "mark_tier3_traffic_capture_active",
                                            None,
                                        )
                                        if manager
                                        else None
                                    )
                                    if callable(capture_marker):
                                        capture_marker(True)
                                    self._mark_tier3_core_sync_success()
                                    self._set_effective_egress_state(True, "")
                                    self._publish_runtime_egress_readiness(
                                        RuntimeEgressReadinessState.READY,
                                        validation_active=False,
                                    )
                                    self._reset_tier3_standby_activation_failure()
                                    self._publish_tier3_runtime_qualification()
                                    if manager:
                                        with manager.lock:
                                            report = ensure_tier3_collection_report(
                                                manager
                                            )
                                            report["core_standby"] = False
                                            report[
                                                "core_activation_generation"
                                            ] = activation_generation
                                    activation_committed = True
                    except Exception:
                        if traffic_monitor_started:
                            self.traffic_monitor.stop()
                        raise
                    if not activation_committed:
                        self._rollback_to_formal_no_capture(
                            runner,
                            "activation superseded before traffic capture commit",
                        )
                        continue
                    self.logger.info(
                        "Bastion Layer standby core activated after FINAL-EXIT verification "
                        "(generation=%s)",
                        activation_generation,
                    )
                    if not self._runtime_uses_early_single_coordinator():
                        self._resume_deferred_runtime_failbacks()
                except Exception as exc:
                    if self.stop_event.is_set():
                        continue
                    if (
                        activation_mode == "activation"
                        and runtime_initial_activation_path
                    ):
                        activation_still_current = bool(
                            isinstance(runtime_worker_token, tuple)
                            and self._runtime_worker_token_is_current(
                                runtime_worker_token
                            )
                            and int(
                                getattr(
                                    self,
                                    "_runtime_selector_intent_revision",
                                    0,
                                )
                                or 0
                            )
                            == activation_selector_intent_revision
                            and self._tier3_egress_activation_is_current(
                                activation_generation,
                                runner,
                                activation_core_generation,
                            )
                        )
                        if not activation_still_current:
                            continue
                        if isinstance(exc, RuntimeStartCancelled):
                            continue
                        reason = (
                            "Initial egress verification failed "
                            f"({type(exc).__name__})"
                        )
                        if (
                            runner is not None
                            and runner.is_running()
                            and self._current_core_runtime_phase()
                            == "formal_capture"
                            and not self._runtime_uses_early_single_coordinator()
                        ):
                            self._rollback_to_formal_no_capture(runner, reason)
                        self._disarm_runtime_recovery(reason)
                        authority_key = self._tier3_standby_activation_key()
                        if isinstance(exc, RuntimeControllerReadbackError):
                            self._publish_tier3_controller_hold(
                                reason,
                                authority_key=authority_key,
                            )
                        elif isinstance(exc, RuntimeActivationRecoveryError):
                            status = exc.outcome.status
                            if status is RuntimeRecoveryStatus.CONTROLLER_HOLD:
                                self._publish_tier3_controller_hold(
                                    reason,
                                    authority_key=authority_key,
                                )
                            elif status is RuntimeRecoveryStatus.FACILITY_HOLD:
                                self._record_tier3_standby_activation_failure(
                                    reason,
                                    authority_key=authority_key,
                                )
                                self._set_effective_egress_readiness_state(
                                    None,
                                    reason,
                                )
                                self._publish_runtime_egress_readiness(
                                    RuntimeEgressReadinessState.FACILITY_HOLD,
                                    validation_active=False,
                                    reason=reason,
                                )
                            elif status in {
                                RuntimeRecoveryStatus.STALE,
                                RuntimeRecoveryStatus.MANUAL_SUPERSEDED,
                            }:
                                self._record_tier3_standby_activation_indeterminate(
                                    reason,
                                    authority_key=authority_key,
                                )
                                self._set_effective_egress_readiness_state(
                                    None,
                                    reason,
                                )
                                self._queue_runtime_route_snapshot_refresh()
                            else:
                                # Only the coordinator's confirmed fixed
                                # Gateway branch may ever produce FAIL_CLOSED.
                                self._record_tier3_standby_activation_failure(
                                    reason,
                                    authority_key=authority_key,
                                )
                                manager = self.manager
                                capture_marker = (
                                    getattr(
                                        manager,
                                        "mark_tier3_traffic_capture_active",
                                        None,
                                    )
                                    if manager is not None
                                    else None
                                )
                                if callable(capture_marker):
                                    capture_marker(False)
                                self._set_effective_egress_state(False, reason)
                                self._publish_runtime_egress_readiness(
                                    RuntimeEgressReadinessState.FAIL_CLOSED,
                                    validation_active=False,
                                    reason=reason,
                                )
                        elif isinstance(exc, _RuntimeProbeBudgetUnavailable):
                            self._record_tier3_standby_activation_indeterminate(
                                reason,
                                authority_key=authority_key,
                            )
                            self._set_effective_egress_readiness_state(
                                None,
                                reason,
                            )
                        else:
                            self._record_tier3_standby_activation_failure(
                                reason,
                                authority_key=authority_key,
                            )
                            self._set_effective_egress_state(False, reason)
                            self._publish_runtime_egress_readiness(
                                RuntimeEgressReadinessState.DATA_PLANE_FAILED,
                                validation_active=False,
                                reason=reason,
                            )
                        log_raw_diagnostic(
                            self.logger,
                            "warning",
                            "%s",
                            reason,
                        )
                        continue
                    current_authority_key = self._tier3_standby_activation_key()
                    with self._tier3_egress_activation_lock:
                        active_request_key = getattr(
                            self,
                            "_tier3_egress_activation_active_key",
                            None,
                        )
                        active_authority_key = (
                            tuple(active_request_key[1])
                            if isinstance(active_request_key, tuple)
                            and len(active_request_key) == 2
                            and isinstance(active_request_key[1], tuple)
                            else None
                        )
                        transaction_is_current = bool(
                            isinstance(
                                activation_terminal_authority_key,
                                tuple,
                            )
                            and active_authority_key
                            == activation_terminal_authority_key
                            and tuple(current_authority_key)
                            == activation_terminal_authority_key
                            and int(activation_generation)
                            == int(self._tier3_egress_activation_generation)
                        )
                        newer_request_pending = bool(
                            self._tier3_egress_activation_pending
                        )
                    if not transaction_is_current:
                        # The failed K1 worker no longer owns route/health
                        # authority. Preserve an already queued K2. A loaded
                        # route/provider change in the same live Core may
                        # create K2 here, while Core/network/user generations
                        # must be reopened only by their owning lifecycle event.
                        if not newer_request_pending:
                            lifecycle_owner_is_current = bool(
                                isinstance(runtime_worker_token, tuple)
                                and self._runtime_worker_token_is_current(
                                    runtime_worker_token
                                )
                                and int(
                                    getattr(
                                        self,
                                        "_runtime_selector_intent_revision",
                                        0,
                                    )
                                    or 0
                                )
                                == activation_selector_intent_revision
                            )
                            if lifecycle_owner_is_current:
                                self._queue_egress_revalidation(
                                    activation_mode
                                )
                        continue
                    if isinstance(exc, RuntimeActivationRecoveryError):
                        recovery_status = exc.outcome.status
                        if recovery_status is RuntimeRecoveryStatus.CONTROLLER_HOLD:
                            self._publish_tier3_controller_hold(
                                "Activation recovery is waiting for authoritative "
                                "controller readback",
                                authority_key=activation_terminal_authority_key,
                            )
                            continue
                        if recovery_status in {
                            RuntimeRecoveryStatus.FACILITY_HOLD,
                            RuntimeRecoveryStatus.STALE,
                            RuntimeRecoveryStatus.MANUAL_SUPERSEDED,
                        }:
                            state = self._record_tier3_standby_activation_indeterminate(
                                "Activation recovery was superseded by a newer "
                                "facility, route, or user intent",
                                authority_key=activation_terminal_authority_key,
                            )
                            self._set_effective_egress_readiness_state(
                                None,
                                str(state["reason"]),
                            )
                            self._queue_runtime_route_snapshot_refresh()
                            continue
                    if isinstance(exc, _RuntimeProbeBudgetUnavailable):
                        state = self._record_tier3_standby_activation_indeterminate(
                            "Bastion Layer verification is waiting for probe capacity",
                            authority_key=activation_terminal_authority_key,
                        )
                        self._set_effective_egress_readiness_state(
                            None,
                            str(state["reason"]),
                        )
                        log_raw_diagnostic(
                            self.logger,
                            "info",
                            "Bastion Layer verification deferred because the "
                            "global probe budget is occupied",
                        )
                        continue
                    if isinstance(exc, RuntimeControllerReadbackError):
                        self._publish_tier3_controller_hold(
                            str(exc),
                            authority_key=activation_terminal_authority_key,
                        )
                        log_raw_diagnostic(
                            self.logger,
                            "warning",
                            "Bastion activation entered controller hold "
                            "after bounded route readback: %s",
                            exc,
                        )
                        continue
                    if activation_mode == "incremental":
                        if self._runtime_non_gateway_serving_active():
                            reason = (
                                "Automatic switching is temporarily unavailable "
                                f"({type(exc).__name__})"
                            )
                            self._record_tier3_standby_activation_failure(
                                reason,
                                authority_key=(
                                    activation_terminal_authority_key
                                ),
                            )
                            self._publish_non_gateway_serving(reason)
                            log_raw_diagnostic(
                                self.logger,
                                "warning",
                                "%s",
                                reason,
                            )
                            continue
                        if self._current_core_runtime_phase() == "formal_no_capture":
                            state = self._publish_tier3_standby_activation_failure(
                                exc,
                                authority_key=activation_terminal_authority_key,
                            )
                            log_raw_diagnostic(
                                self.logger,
                                "warning",
                                "Bastion Layer no-capture baseline failed "
                                "(error_type=%s retry_stage=%s facility_hold=%s)",
                                type(exc).__name__,
                                state.get("retry_stage"),
                                state.get("facility_hold"),
                            )
                            continue
                        reason = (
                            "Runtime route verification failed after the bounded "
                            f"recovery transaction ({type(exc).__name__})"
                        )
                        if (
                            isinstance(exc, Tier3RuntimeQualificationError)
                            and runner is not None
                            and runner.is_running()
                        ):
                            self._rollback_to_formal_no_capture(runner, reason)
                            manager = self.manager
                            capture_marker = getattr(
                                manager,
                                "mark_tier3_traffic_capture_active",
                                None,
                            ) if manager is not None else None
                            if callable(capture_marker):
                                capture_marker(False)
                        # A previous leaf qualification is not live data-plane
                        # evidence.  Once this incident's full 204 and recovery
                        # both fail, keep the immutable failure key terminal and
                        # publish an explicit hold; only a material authority
                        # change may schedule another transaction.
                        self._record_tier3_standby_activation_failure(
                            reason,
                            authority_key=activation_terminal_authority_key,
                        )
                        self._set_effective_egress_readiness_state(None, reason)
                        readiness_state = (
                            RuntimeEgressReadinessState.FAIL_CLOSED
                            if isinstance(exc, RuntimeActivationRecoveryError)
                            and exc.outcome.status
                            is RuntimeRecoveryStatus.FAIL_CLOSED
                            else RuntimeEgressReadinessState.DATA_PLANE_FAILED
                        )
                        self._publish_runtime_egress_readiness(
                            readiness_state,
                            validation_active=False,
                            reason=reason,
                        )
                        log_raw_diagnostic(
                            self.logger,
                            "warning",
                            "%s",
                            reason,
                        )
                        continue
                    reason = (
                        "Bastion Layer standby verification pending "
                        f"({type(exc).__name__})"
                    )
                    if runner is not None and runner.is_running():
                        self._rollback_to_formal_no_capture(runner, reason)
                    state = self._publish_tier3_standby_activation_failure(
                        exc,
                        authority_key=activation_terminal_authority_key,
                    )
                    log_raw_diagnostic(
                        self.logger,
                        "warning",
                        "Bastion Layer core remains in standby after FINAL-EXIT "
                        "verification failure (error_type=%s retry_stage=%s "
                        "facility_hold=%s)",
                        type(exc).__name__,
                        state.get("retry_stage"),
                        state.get("facility_hold"),
                    )
                finally:
                    if pressure_lease is not None:
                        pressure_lease.release()
                    with self._tier3_egress_activation_lock:
                        self._tier3_egress_activation_active_mode = ""
                        self._tier3_egress_activation_active_key = None
        finally:
            with self._tier3_egress_activation_lock:
                if self._tier3_egress_activation_pending:
                    rerun = True
                else:
                    self._tier3_egress_activation_worker_running = False
                    self._tier3_egress_activation_active_mode = ""
                    self._tier3_egress_activation_active_key = None
                    self._tier3_egress_activation_active_generation = 0
                    rerun = False
            if rerun:
                self._tier3_egress_activation_worker()

    def _mark_tier3_core_sync_success(
        self,
        marker: tuple[Any, ...] | None = None,
        *,
        core_gate_latency_ms: int | None = None,
        traffic_capture_active: bool | None = None,
    ) -> None:
        live_marker = self._tier3_core_sync_marker()
        current_marker = live_marker if live_marker is not None else marker
        self._last_tier3_core_sync_marker = current_marker
        self._last_failed_tier3_core_sync_marker = None
        self._last_failed_tier3_core_sync_at = 0.0
        self._mark_core_export_sync_success()
        manager = self.manager
        marker_fn = getattr(manager, "mark_tier3_core_running", None) if manager else None
        if current_marker is not None and self._tier3_is_primary_export() and callable(marker_fn):
            try:
                if traffic_capture_active is None:
                    traffic_capture_active = bool(
                        self._current_core_runtime_phase() == "formal_capture"
                    )
                marker_fn(
                    core_gate_latency_ms=core_gate_latency_ms,
                    effective_egress_ok=True,
                    traffic_capture_active=traffic_capture_active,
                )
            except Exception:
                log_raw_diagnostic(
                    self.logger,
                    "warning",
                    "Failed to mark Bastion Layer startup gate satisfied",
                    exc_info=True,
                )
        manager = self.manager
        if manager:
            self._clear_tier3_core_verification_retry_pending(manager)
            self._last_synced_tier3_nodes = self._clone_runtime_nodes(
                self._tier3_nodes_for_core_export(
                    self._mihomo_tier3_export_limit()
                )
            )

    def _mark_tier3_core_sync_failure(self, marker: tuple[Any, ...] | None) -> None:
        if marker is None:
            return
        self._last_failed_tier3_core_sync_marker = marker
        self._last_failed_tier3_core_sync_at = time.monotonic()

    def _node_diagnostic_binding_lock_ref(self) -> threading.RLock:
        lock = getattr(self, "_node_diagnostic_binding_lock", None)
        if lock is None:
            lock = threading.RLock()
            self._node_diagnostic_binding_lock = lock
        return lock

    def _invalidate_node_diagnostic_core_binding(self) -> None:
        with self._node_diagnostic_binding_lock_ref():
            self._node_diagnostic_binding_generation = (
                int(getattr(self, "_node_diagnostic_binding_generation", 0) or 0) + 1
            )
            self._node_diagnostic_core_binding = None
            self._node_diagnostic_binding_client = None
            self._node_diagnostic_binding_runner = None

    def _refresh_node_diagnostic_core_binding(self) -> NodeDiagnosticCoreBinding:
        """Capture the exact runtime config only after the regular load succeeded."""
        with self._node_diagnostic_binding_lock_ref():
            # Invalidate first so a parse/read failure can never leave a stale
            # binding associated with a newly loaded core configuration.
            self._node_diagnostic_core_binding = None
            self._node_diagnostic_binding_client = None
            self._node_diagnostic_binding_runner = None
            runtime_config_path = self._runtime_config_path_for_client()
            raw_config = runtime_config_path.read_bytes()
            generation = int(getattr(self, "_node_diagnostic_binding_generation", 0) or 0) + 1
            binding = build_node_diagnostic_core_binding(
                raw_config,
                generation=generation,
                core_generation=int(getattr(self, "_core_generation", 0) or 0),
            )
            # The runtime file is replaced atomically, but verify it once more
            # before publishing the captured binding.
            if hashlib.sha256(runtime_config_path.read_bytes()).hexdigest() != binding.runtime_config_digest:
                raise RuntimeError("mihomo runtime config changed while capturing diagnostic binding")
            self._node_diagnostic_binding_generation = generation
            self._node_diagnostic_core_binding = binding
            self._node_diagnostic_binding_client = self.api_client
            self._node_diagnostic_binding_runner = self.core_runner
            return binding

    def _queue_node_diagnostic_core_binding_refresh(self) -> None:
        """Publish the just-loaded config binding without delaying core state commits."""
        with self._node_diagnostic_binding_lock_ref():
            self._node_diagnostic_core_binding = None
            self._node_diagnostic_binding_client = None
            self._node_diagnostic_binding_runner = None
            raw_config = getattr(self, "_node_diagnostic_pending_runtime_config", None)
            runtime_config_path = getattr(
                self,
                "_node_diagnostic_pending_runtime_config_path",
                None,
            )
            if not isinstance(raw_config, bytes) or not isinstance(runtime_config_path, Path):
                return
            generation = int(getattr(self, "_node_diagnostic_binding_generation", 0) or 0) + 1
            self._node_diagnostic_binding_generation = generation
            core_generation = int(getattr(self, "_core_generation", 0) or 0)
            client = self.api_client
            runner = self.core_runner

        def publish() -> None:
            try:
                binding = build_node_diagnostic_core_binding(
                    raw_config,
                    generation=generation,
                    core_generation=core_generation,
                )
                current_path = self._runtime_config_path_for_client()
                if current_path.resolve() != runtime_config_path.resolve():
                    return
                if hashlib.sha256(current_path.read_bytes()).hexdigest() != binding.runtime_config_digest:
                    return
            except Exception:
                return
            with self._node_diagnostic_binding_lock_ref():
                if int(getattr(self, "_node_diagnostic_binding_generation", 0) or 0) != generation:
                    return
                if int(getattr(self, "_core_generation", 0) or 0) != core_generation:
                    return
                if getattr(self, "_node_diagnostic_pending_runtime_config", None) != raw_config:
                    return
                if getattr(self, "_node_diagnostic_pending_runtime_config_path", None) != runtime_config_path:
                    return
                if self.api_client is not client or self.core_runner is not runner:
                    return
                self._node_diagnostic_core_binding = binding
                self._node_diagnostic_binding_client = client
                self._node_diagnostic_binding_runner = runner

        threading.Thread(
            target=publish,
            name="desktop-node-diagnostic-binding",
            daemon=True,
        ).start()

    def _loaded_core_protocol_counts_snapshot(self, *, core_running: bool) -> dict[str, int]:
        """Return protocol counts from the exact config loaded by this core generation."""

        if not core_running:
            return {}
        with self._node_diagnostic_binding_lock_ref():
            binding = getattr(self, "_node_diagnostic_core_binding", None)
            if not isinstance(binding, NodeDiagnosticCoreBinding):
                return {}
            if binding.core_generation != int(getattr(self, "_core_generation", 0) or 0):
                return {}
            client = getattr(self, "_node_diagnostic_binding_client", None)
            runner = getattr(self, "_node_diagnostic_binding_runner", None)
        valid, _reason = self._validate_node_diagnostic_core_binding(
            binding,
            client=client,
            runner=runner,
        )
        return binding.protocol_counts() if valid else {}

    def _validate_node_diagnostic_core_binding(
        self,
        expected: NodeDiagnosticCoreBinding,
        *,
        client: Any,
        runner: Any,
    ) -> tuple[bool, str | None]:
        if client is None or runner is None:
            return False, "mihomo controller or core runner changed"
        if self.api_client is not client or self.core_runner is not runner:
            return False, "mihomo controller or core runner changed"
        try:
            if not runner.is_running():
                return False, "mihomo core is not running"
        except Exception:
            return False, "mihomo core state is unavailable"
        try:
            current_digest = hashlib.sha256(
                self._runtime_config_path_for_client().read_bytes()
            ).hexdigest()
        except Exception:
            return False, "mihomo runtime config is unavailable"
        with self._node_diagnostic_binding_lock_ref():
            current = getattr(self, "_node_diagnostic_core_binding", None)
            if current != expected:
                return False, "loaded Mihomo configuration binding changed"
            if getattr(self, "_node_diagnostic_binding_client", None) is not client:
                return False, "mihomo controller changed"
            if getattr(self, "_node_diagnostic_binding_runner", None) is not runner:
                return False, "mihomo core runner changed"
            if current_digest != expected.runtime_config_digest:
                return False, "mihomo runtime config changed without a successful load"
        return True, None

    def _node_diagnostic_core_binding_state(
        self,
        *,
        client: Any,
        runner: Any,
    ) -> tuple[NodeDiagnosticCoreBinding | None, str | None]:
        with self._node_diagnostic_binding_lock_ref():
            binding = getattr(self, "_node_diagnostic_core_binding", None)
        if binding is None:
            return None, "loaded Mihomo configuration binding is unavailable"
        valid, reason = self._validate_node_diagnostic_core_binding(
            binding,
            client=client,
            runner=runner,
        )
        return (binding, None) if valid else (None, reason)

    def _mark_loaded_runtime_export_contract(self) -> None:
        """Commit only the exact config contract accepted by Core."""

        route_lock = getattr(self, "_runtime_route_snapshot_lock", None)
        if route_lock is None:
            return
        loaded_provider_projection: Tier3CoreProviderProjection | None = None
        with route_lock:
            pending_contract = getattr(
                self,
                "_runtime_pending_export_contract",
                None,
            )
            if isinstance(pending_contract, dict):
                candidate_projection = pending_contract.get(
                    "provider_projection"
                )
                if isinstance(
                    candidate_projection,
                    Tier3CoreProviderProjection,
                ):
                    loaded_provider_projection = candidate_projection
                self._runtime_loaded_export_revision = int(
                    getattr(self, "_runtime_loaded_export_revision", 0) or 0
                ) + 1
                self._runtime_loaded_export_contract = {
                    "semantic_digest": str(
                        pending_contract.get("semantic_digest") or ""
                    ),
                    "main_semantic_digest": str(
                        pending_contract.get("main_semantic_digest") or ""
                    ),
                    "provider_semantic_digest": str(
                        pending_contract.get("provider_semantic_digest") or ""
                    ),
                    "proxy_map": copy.deepcopy(
                        pending_contract.get("proxy_map") or {}
                    ),
                    "runtime_config_path": str(
                        pending_contract.get("runtime_config_path") or ""
                    ),
                    "loaded_at_monotonic": time.monotonic(),
                    "revision": int(self._runtime_loaded_export_revision),
                }
                loaded_digest = str(
                    self._runtime_loaded_export_contract.get(
                        "semantic_digest",
                        "",
                    )
                    or ""
                )
            else:
                loaded_digest = ""
        self._tier3_core_provider_last_projection = loaded_provider_projection
        self._tier3_core_provider_pending_projection = None
        reload_gate = getattr(self, "_runtime_reload_gate", None)
        if reload_gate is not None and loaded_digest:
            sync_if_idle = getattr(
                reload_gate,
                "set_loaded_semantic_digest_if_idle",
                None,
            )
            if callable(sync_if_idle):
                # During a real ApplyConfig the active reload lease owns the
                # digest commit.  Publishing the loaded route contract here is
                # still required, but it must not raise merely because that
                # lease has not reached complete_reload() yet.
                sync_if_idle(loaded_digest)
            else:
                gate_snapshot = getattr(reload_gate, "snapshot", lambda: None)()
                if not (
                    getattr(gate_snapshot, "active_reload_reason", "")
                    or getattr(
                        gate_snapshot,
                        "active_recovery_transaction_id",
                        "",
                    )
                ):
                    reload_gate.set_loaded_semantic_digest(loaded_digest)
        self._wake_parked_tier3_pool_sync_if_causal_key_changed()

    def _mark_core_export_sync_success(self, marker: tuple[Any, ...] | None = None) -> None:
        current_marker = marker if marker is not None else self._core_export_sync_marker()
        self._last_core_export_sync_marker = current_marker
        self._last_failed_core_export_sync_marker = None
        self._last_failed_core_export_sync_at = 0.0
        self._mark_loaded_runtime_export_contract()
        self._mark_runtime_source_transport_loaded()
        # Generic Core sync and diagnostic tests may exercise this callback on
        # a deliberately minimal runtime. Tier3 generation ownership only
        # exists after the manager has been attached.
        if getattr(self, "manager", None) is not None and self._tier3_is_primary_export():
            self._advance_tier3_runtime_config_generation(current_marker)
        manager = getattr(self, "manager", None)
        notify_source_supply = getattr(
            manager,
            "notify_tier3_source_supply_route_changed",
            None,
        ) if manager is not None else None
        if callable(notify_source_supply):
            notify_source_supply("core_export_sync_succeeded")
        try:
            self._queue_node_diagnostic_core_binding_refresh()
        except Exception:
            # Diagnostic attribution is strictly best-effort. A missing or
            # unparsable tracking snapshot must not add latency, logging I/O,
            # or failure semantics to the authoritative core-sync path.
            self._invalidate_node_diagnostic_core_binding()
        self._queue_runtime_route_snapshot_refresh()

    def _mark_core_export_sync_failure(self, marker: tuple[Any, ...] | None) -> None:
        self._invalidate_node_diagnostic_core_binding()
        if marker is None:
            return
        self._last_failed_core_export_sync_marker = marker
        self._last_failed_core_export_sync_at = time.monotonic()

    def _core_export_sync_failure_is_recent(self, marker: tuple[Any, ...] | None) -> bool:
        return tier3_core_sync_failure_is_recent(
            marker=marker,
            last_failed_marker=self._last_failed_core_export_sync_marker,
            last_failed_at=self._last_failed_core_export_sync_at,
            now=time.monotonic(),
            retry_interval=self._tier3_core_sync_retry_interval(),
        )

    @staticmethod
    def _clone_runtime_nodes(nodes: list[Any]) -> list[Any]:
        cloned: list[Any] = []
        for node in nodes:
            try:
                cloned.append(node.clone())
            except Exception:
                cloned.append(node)
        return cloned

    def _tier3_core_gate_check(
        self,
        nodes: list[Any] | None = None,
    ) -> tuple[bool, int, int, str]:
        if self.stop_event.is_set():
            return False, 0, 0, "runtime_stop_requested"
        startup_gate_allowed = bool(self._tier3_required_for_start and not self.running)
        if not self.running and not startup_gate_allowed:
            return False, 0, 0, "runtime_not_running"
        manager = self.manager
        if not manager:
            return False, 0, 0, "manager_missing"
        if bool(getattr(manager, "closed", False)):
            return False, 0, self._tier3_startup_target_alive(manager), "manager_closed"
        current_nodes = list(nodes) if nodes is not None else list(getattr(manager, "runtime_nodes", {}).get("tier3", []))
        auto_counter = getattr(manager, "_tier3_auto_pool_healthy_count", None)
        if callable(auto_counter):
            healthy = int(auto_counter(current_nodes))
        else:
            healthy = count_healthy_nodes(current_nodes)
        required = self._tier3_startup_target_alive(manager)
        if (
            healthy < required
            and self._tier3_startup_supply_terminal(manager)
        ):
            return False, healthy, required, "startup_supply_exhausted"
        marker = self._tier3_core_sync_marker()
        if not marker:
            return False, healthy, required, "empty_core_export_marker"
        if (
            self.core_runner
            and self.core_runner.is_running()
            and self._current_core_runtime_phase() != "bootstrap"
        ):
            return False, healthy, required, "core_already_running"
        if healthy < required:
            return False, healthy, required, "below_min_alive_nodes"
        return True, healthy, required, "ready"

    def _committed_tier3_pool_ready_for_core(self, nodes: list[Any] | None = None) -> bool:
        ready, _healthy, _required, _reason = self._tier3_core_gate_check(nodes)
        return ready

    def _start_core_from_committed_tier3_pool(self) -> dict[str, object]:
        manager = self.manager
        if not manager:
            raise RuntimeError("manager service is not running")
        if self._primary_runtime_healthy_count() <= 0:
            self._tier3_required_for_start = True
            if not self._primary_startup_error:
                self._primary_startup_error = "primary layers are not ready"
        self._require_tier3_ready_for_core_start()
        # The phase check belongs inside the transition lock.  The previous
        # check-then-lock sequence let the UI start and Tier3 gate both observe
        # ``bootstrap``; the loser then attempted a second promotion after the
        # winner had already loaded ``formal_no_capture``.
        with self._core_transition_lock:
            if self.core_runner and self.core_runner.is_running():
                phase = self._current_core_runtime_phase()
                if phase == "bootstrap":
                    return self._promote_bootstrap_core_once()
                if phase == "formal_no_capture":
                    self._request_initial_egress_admission()
                    return self.core_runner.status()
                if phase == "formal_capture":
                    return self.core_runner.status()
            return self._start_core_once()

    def _attempt_deferred_tier3_core_start(
        self,
        marker: tuple[Any, ...] | None,
        *,
        committed_pool_only: bool = False,
        gate_generation: int | None = None,
    ) -> bool:
        gate_running = self.running or bool(committed_pool_only and self._tier3_required_for_start)
        if not should_attempt_deferred_tier3_core_start(
            running=gate_running,
            marker=marker,
            last_marker=self._last_tier3_core_sync_marker,
        ):
            return False
        manager = self.manager
        if (
            self.core_runner
            and self.core_runner.is_running()
            and self._current_core_runtime_phase() != "bootstrap"
        ):
            if self._current_core_runtime_phase() == "formal_no_capture":
                self._request_initial_egress_admission()
            self._clear_last_error_if_runtime_healthy()
            return False
        if manager is not None and (
            bool(getattr(manager, "tier3_core_running", False))
            or (
                bool(getattr(manager, "tier3_startup_gate_satisfied", False))
                and getattr(manager, "effective_egress_ok", None) is True
            )
        ):
            self._clear_last_error_if_runtime_healthy()
            self.logger.info(
                "Bastion Layer deferred core gate ignored stale result "
                "(reason=core_already_running_or_gate_satisfied generation=%s)",
                gate_generation,
            )
            return False
        if self._tier3_core_sync_failure_is_recent(marker):
            return False
        ready, healthy, required, reason = self._tier3_core_gate_check()
        if not ready:
            with self._tier3_core_gate_lock:
                stale_generation = (
                    gate_generation is not None
                    and int(gate_generation) < int(self._tier3_core_gate_generation)
                )
            if stale_generation:
                self.logger.info(
                    "Bastion Layer deferred core gate ignored stale blocked result "
                    "(healthy=%s required=%s reason=%s generation=%s current_generation=%s)",
                    healthy,
                    required,
                    reason,
                    gate_generation,
                    self._tier3_core_gate_generation,
                )
                return False
            self.logger.info(
                "Bastion Layer deferred core gate check blocked "
                "(healthy=%s required=%s reason=%s)",
                healthy,
                required,
                reason,
            )
            return False
        self.logger.info(
            "Bastion Layer deferred core gate attempting core start "
            "(healthy=%s required=%s reason=%s)",
            healthy,
            required,
            reason,
        )
        try:
            if committed_pool_only:
                self._start_core_from_committed_tier3_pool()
            else:
                self.start_core()
        except Exception as exc:
            if self.stop_event.is_set() and isinstance(
                exc.__cause__ if isinstance(exc, RecoverableCoreStartError) else exc,
                RuntimeStartCancelled,
            ):
                # The stop request ended it; nothing failed and nothing is retried.
                self.logger.info("Deferred core start ended by the stop request")
                return False
            self._mark_tier3_core_sync_failure(marker)
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Deferred core start failed; will retry after the Tier3 sync cooldown or next pool change",
                exc_info=True,
            )
            if self._caused_by_geodata_preflight(exc):
                self._schedule_geodata_preflight_retry()
            return False
        if self.stop_event.is_set():
            return False
        self.last_error = None
        self._start_deferred_reason = None
        self._start_deferred_is_live = False
        self._mark_tier3_pool_sync_formal_baseline_loaded()
        return True

    @staticmethod
    def _caused_by_geodata_preflight(error: BaseException | None) -> bool:
        for _depth in range(8):
            if error is None:
                return False
            if isinstance(error, GeoDataPreflightError):
                return True
            error = error.__cause__ or error.__context__
        return False

    def _schedule_geodata_preflight_retry(self) -> None:
        """Try the deferred Core start again soon after a failed GeoData download.

        A deferred start is otherwise retried when the pool changes, and a
        small pool that has settled does not change: the start would wait on
        a download that only needed another try (11-10: nothing for 150 s
        after a failed first-run download with three settled members).  The
        pool is the same one, so the failed-marker cooldown is lifted for
        this retry only.  One retry is pending at a time; the delay doubles
        from 15 s to at most 60 s and starts over once a download succeeds.
        """

        generation = int(getattr(self, "_runtime_generation", 0) or 0)
        lock = getattr(self, "_tier3_core_gate_lock", None)
        with lock if lock is not None else nullcontext():
            pending = getattr(self, "_geodata_preflight_retry", None)
            if pending is not None:
                if pending[0] == generation:
                    return
                # Left over from an earlier run: it would do nothing anyway.
                pending[1].cancel()
                self._geodata_preflight_retries = 0
            retries = int(getattr(self, "_geodata_preflight_retries", 0) or 0) + 1
            self._geodata_preflight_retries = retries
            delay = min(60.0, 15.0 * (2 ** min(retries - 1, 2)))
            timer = threading.Timer(
                delay,
                self._retry_core_start_after_geodata_preflight,
                args=(generation,),
            )
            timer.daemon = True
            timer.name = "desktop-geodata-preflight-retry"
            self._geodata_preflight_retry = (generation, timer)
        self.logger.info(
            "GeoData download will be tried again in %.0f s", delay,
        )
        timer.start()

    def _retry_core_start_after_geodata_preflight(self, runtime_generation: int) -> None:
        lock = getattr(self, "_tier3_core_gate_lock", None)
        with lock if lock is not None else nullcontext():
            pending = getattr(self, "_geodata_preflight_retry", None)
            if pending is not None and pending[0] == int(runtime_generation):
                self._geodata_preflight_retry = None
        try:
            if (
                self.stop_event.is_set()
                or not self.running
                or int(self._runtime_generation) != int(runtime_generation)
                or self._current_core_runtime_phase() != "bootstrap"
            ):
                return
            # Only the download failed; the same pool may carry it now.
            self._last_failed_tier3_core_sync_marker = None
            self._queue_tier3_core_gate_attempt()
        except Exception:
            log_raw_diagnostic(
                self.logger,
                "warning",
                "GeoData preflight retry could not be queued",
                exc_info=True,
            )

    def _on_tier3_pool_committed(self, nodes: list[Any], metadata: dict[str, Any] | None = None) -> None:
        if self.stop_event.is_set():
            return
        overlay_changed = False
        # A Tier3 targeted PASS is only eligibility evidence. The matching
        # incident callback owns releasing the exact export hold and failback;
        # clearing here creates a second Core reload lane before that token is
        # checked and was the source of the formal_no_capture self-race.
        manager = self.manager
        if manager is not None and self._fail_terminal_tier3_bootstrap(
            manager,
            metadata,
        ):
            return
        runner = self.core_runner
        core_running_before = bool(runner and runner.is_running())
        membership_removed = bool(
            core_running_before
            and self._tier3_export_removes_last_synced_proxy()
        )
        ready, healthy, required, reason = self._tier3_core_gate_check(nodes)
        admission_identity = ""
        if isinstance(metadata, dict):
            admission_identity = str(metadata.get("admission_identity") or "")
        self.logger.info(
            "Bastion Layer core gate check after pool commit "
            "(healthy=%s required=%s reason=%s admission_identity=%s)",
            healthy,
            required,
            reason,
            (
                runtime_identity_hash(admission_identity)
                if admission_identity
                else "unknown"
            ),
        )
        if ready:
            self._record_tier3_core_sync_event("gate_crossing")
            if self._tier3_startup_terminal_failure:
                self._clear_tier3_terminal_startup_failure()
            self._queue_tier3_core_gate_attempt()
        elif reason == "startup_supply_exhausted" and not (
            core_running_before
            and self._current_core_runtime_phase() in {"formal_capture", "formal_no_capture"}
            and self._tier3_verified_lane_open()
        ):
            # Source exhaustion below the Tier3 floor is a bootstrap concern.
            # A formal Core serving another layer is left untouched.  On the
            # verified lane a formal Core still follows the pool: an eviction
            # below the floor must leave the Core too.
            return
        elif (
            core_running_before
            and self._current_core_runtime_phase() == "bootstrap"
            and bool(self._tier3_core_sync_marker())
        ):
            # A DIRECT-resolved source may admit the first healthy node below
            # floor. Reload bootstrap immediately so subsequent PROXY sources
            # can borrow that node instead of waiting for the formal Core.
            self._queue_tier3_pool_sync_after_commit(
                immediate=True,
                sync_event=(
                    "semantic_change"
                    if overlay_changed or membership_removed
                    else "append_only"
                ),
            )
        elif (
            core_running_before
            and self._current_core_runtime_phase() != "bootstrap"
        ):
            self._queue_tier3_pool_sync_after_commit(
                immediate=bool(overlay_changed or membership_removed),
                sync_event=(
                    "semantic_change"
                    if overlay_changed or membership_removed
                    else "append_only"
                ),
            )

    def _record_tier3_core_sync_event(self, event: str) -> None:
        """Publish a bounded diagnostic classification for the latest Core sync."""

        event_name = str(event or "semantic_change")
        if event_name not in {
            "gate_crossing",
            "append_only",
            "semantic_change",
            "selected_leaf_change",
        }:
            event_name = "semantic_change"
        manager = self.manager
        if manager is None:
            return
        lock = getattr(manager, "lock", None)
        if lock is None:
            return
        with lock:
            report = getattr(manager, "tier3_last_collection_report", None)
            if not isinstance(report, dict):
                return
            counts = dict(report.get("core_sync_event_counts") or {})
            counts[event_name] = max(0, int(counts.get(event_name, 0) or 0)) + 1
            report["core_sync_last_event"] = event_name
            report["core_sync_event_counts"] = counts
            report["core_sync_last_event_monotonic_ns"] = time.monotonic_ns()

    def _record_tier3_core_sync_ledger(
        self,
        kind: str,
        *,
        event: str = "append_only",
        semantic_digest: str = "",
        detail: str = "",
    ) -> None:
        """Record actual Core work separately from logical sync requests."""

        entry_kind = str(kind or "request")
        if entry_kind not in {
            "request",
            "semantic_noop",
            "config_apply",
            "provider_update",
            "final_exit_probe",
        }:
            entry_kind = "request"
        with self._tier3_core_sync_ledger_lock:
            self._tier3_core_sync_ledger_sequence += 1
            entry = {
                "sequence": int(self._tier3_core_sync_ledger_sequence),
                "kind": entry_kind,
                "event": str(event or "append_only"),
                "semantic_digest": str(semantic_digest or "")[:64],
                "detail": str(detail or "")[:96],
                "core_generation": int(self._core_generation),
                "config_generation": int(
                    self._tier3_runtime_config_generation
                ),
                "monotonic_ns": time.monotonic_ns(),
            }
            self._tier3_core_sync_ledger_counts[entry_kind] = max(
                0,
                int(self._tier3_core_sync_ledger_counts.get(entry_kind, 0) or 0),
            ) + 1
            self._tier3_core_sync_last_actual_kind = entry_kind
            if entry_kind == "semantic_noop":
                self._tier3_core_sync_last_semantic_noop = dict(entry)
            else:
                self._tier3_core_sync_ledger.append(entry)
                del self._tier3_core_sync_ledger[:-64]
            ledger = [dict(item) for item in self._tier3_core_sync_ledger]
            counts = dict(self._tier3_core_sync_ledger_counts)
            last_semantic_noop = dict(
                self._tier3_core_sync_last_semantic_noop
            )
        manager = self.manager
        lock = getattr(manager, "lock", None) if manager is not None else None
        if lock is None:
            return
        with lock:
            report = ensure_tier3_collection_report(manager)
            report["core_sync_ledger_counts"] = counts
            report["core_sync_ledger"] = ledger
            report["core_sync_last_semantic_noop"] = last_semantic_noop
            report["core_sync_last_actual_kind"] = entry_kind

    def _tier3_core_sync_owner_snapshot(self) -> dict[str, Any]:
        with self._tier3_core_sync_ledger_lock:
            ledger = [dict(item) for item in self._tier3_core_sync_ledger]
            counts = dict(self._tier3_core_sync_ledger_counts)
            sequence = int(self._tier3_core_sync_ledger_sequence)
            last_semantic_noop = dict(
                self._tier3_core_sync_last_semantic_noop
            )
            last_actual_kind = str(self._tier3_core_sync_last_actual_kind)
        return {
            "core_sync_ledger": ledger,
            "core_sync_ledger_counts": counts,
            "core_sync_ledger_sequence": sequence,
            "core_sync_last_semantic_noop": last_semantic_noop,
            "core_sync_last_actual_kind": last_actual_kind,
        }

    def _tier3_runtime_qualification_stable(self) -> bool:
        lifecycle_lock = getattr(self, "_core_lifecycle_lock", None)
        with lifecycle_lock if lifecycle_lock is not None else nullcontext():
            core_generation = int(getattr(self, "_core_generation", 0) or 0)
        activation_completed = self._runtime_initial_activation_was_completed()
        with self._tier3_runtime_qualification_lock:
            return bool(
                self._tier3_runtime_final_exit_ok
                and int(
                    getattr(
                        self,
                        "_tier3_runtime_final_exit_core_generation",
                        -1,
                    )
                    or -1
                )
                == core_generation
                and activation_completed
                and self._tier3_selected_leaf_evidence is not None
            )

    def _tier3_pool_sync_formal_baseline_loaded(self) -> bool:
        runner = self.core_runner
        if (
            runner is None
            or not runner.is_running()
            or self._current_core_runtime_phase()
            not in {"formal_no_capture", "formal_capture"}
        ):
            return False
        with self._core_lifecycle_lock:
            core_generation = int(self._core_generation)
        return bool(
            int(self._tier3_pool_sync_formal_baseline_core_generation)
            == core_generation
        )

    def _mark_tier3_pool_sync_formal_baseline_loaded(self) -> None:
        runner = self.core_runner
        if (
            runner is None
            or not runner.is_running()
            or self._current_core_runtime_phase()
            not in {"formal_no_capture", "formal_capture"}
        ):
            return
        with self._core_lifecycle_lock:
            self._tier3_pool_sync_formal_baseline_core_generation = int(
                self._core_generation
            )

    def _tier3_pool_target_reached(self) -> bool:
        manager = self.manager
        if manager is None:
            return False
        try:
            snapshot = manager.tier3_auto_pool_count_snapshot()
            target_getter = getattr(
                manager,
                "_tier3_background_target_alive_nodes",
                None,
            )
            target = (
                int(target_getter())
                if callable(target_getter)
                else int(getattr(manager, "tier3_target_alive", 0) or 0)
            )
            return target > 0 and int(snapshot.healthy) >= target
        except Exception:
            return False

    def _tier3_provider_sync_key(self) -> DeferredProviderSyncKey:
        """Capture the causal facts that may authorize one provider attempt."""

        manager = self.manager
        manager_lock = getattr(manager, "lock", None) if manager is not None else None
        try:
            with manager_lock if manager_lock is not None else nullcontext():
                pool_revision = int(
                    getattr(manager, "tier3_pool_revision", 0) or 0
                )
            # Export rendering may acquire runtime/controller locks.  Never do
            # that while holding Manager.lock: activation publishes route truth
            # in the opposite direction and the two paths otherwise form a
            # lock-order cycle during rapid startup admissions.
            pool_marker = self._tier3_core_sync_marker()
        except Exception:
            pool_revision = int(
                getattr(manager, "tier3_pool_revision", 0) or 0
            )
            pool_marker = None
        try:
            core_export_marker = self._core_export_sync_marker()
        except Exception:
            core_export_marker = None
        provider_digest = hashlib.sha256(
            repr((pool_marker, core_export_marker)).encode("utf-8")
        ).hexdigest()

        lifecycle_lock = getattr(self, "_core_lifecycle_lock", None)
        with lifecycle_lock if lifecycle_lock is not None else nullcontext():
            core_generation = int(getattr(self, "_core_generation", 0) or 0)

        route_lock = getattr(self, "_runtime_route_snapshot_lock", None)
        with route_lock if route_lock is not None else nullcontext():
            contract = getattr(self, "_runtime_loaded_export_contract", None)
            loaded_digest = (
                str(
                    contract.get("provider_semantic_digest")
                    or contract.get("semantic_digest")
                    or ""
                )
                if isinstance(contract, dict)
                else ""
            )
            network_epoch = int(
                getattr(self, "_runtime_network_context_epoch", 0) or 0
            )

        if self._tier3_verified_provider_writes_enabled():
            # The pool revision moves on every latency or status commit; the
            # marker above already captures membership and definitions, so
            # health churn alone must not start a provider attempt.
            pool_revision = 0
        return DeferredProviderSyncKey(
            runtime_generation=int(
                getattr(self, "_runtime_generation", 0) or 0
            ),
            core_generation=core_generation,
            pool_revision=pool_revision,
            provider_digest=provider_digest,
            loaded_digest=loaded_digest,
            network_epoch=network_epoch,
            facility_epoch=int(
                getattr(self, "_runtime_facility_epoch", 0) or 0
            ),
            serving=self._runtime_initial_activation_was_completed(),
        )

    def _tier3_initial_activation_transaction_active(self) -> bool:
        """Return whether startup admission currently owns Core mutation."""

        if self._runtime_initial_activation_was_completed():
            return False
        activation_lock = getattr(self, "_tier3_egress_activation_lock", None)
        if activation_lock is None:
            return False
        with activation_lock:
            pending_mode = str(
                getattr(self, "_tier3_egress_activation_pending_mode", "") or ""
            )
            active_mode = str(
                getattr(self, "_tier3_egress_activation_active_mode", "") or ""
            )
            return bool(
                (
                    getattr(self, "_tier3_egress_activation_pending", False)
                    and (not pending_mode or pending_mode == "activation")
                )
                or active_mode == "activation"
                or int(
                    getattr(
                        self,
                        "_tier3_egress_activation_active_generation",
                        0,
                    )
                    or 0
                )
                > 0
            )

    def _tier3_online_provider_cohort_frozen(self) -> bool:
        """Keep the exact Core-loaded provider cohort stable while online.

        Manager may continue collecting and recording health in the
        background.  Ordinary pool growth must not mutate a formal Core graph
        or reopen route activation; only an explicitly incident-owned rebase
        may cross this boundary.
        """

        runner = getattr(self, "core_runner", None)
        if runner is None:
            return False
        try:
            if not bool(runner.is_running()):
                return False
        except Exception:
            return False
        phase_getter = getattr(self, "_current_core_runtime_phase", None)
        if not callable(phase_getter):
            return False
        try:
            phase = str(phase_getter() or "").strip().lower()
        except Exception:
            return False
        if (
            self._runtime_uses_early_single_coordinator()
            and phase == "formal_no_capture"
            and not self._runtime_initial_activation_was_completed()
        ):
            # Startup standby may accept strictly append-only capacity only
            # between admission attempts.  While one immutable activation lease
            # is proving the loaded route, that lease is the sole Core mutation
            # owner.  A concurrent provider PUT used to invalidate its readback
            # and could strand the monitor and Tier3 feedback path together.
            return self._tier3_initial_activation_transaction_active()
        return phase in {"formal_capture", "formal_no_capture"}

    def _tier3_online_growth_enabled(self) -> bool:
        try:
            block = self._tier_config("tier3")
        except Exception:
            return False
        value = block.get("online_core_growth", True) if isinstance(block, dict) else True
        if isinstance(value, str):
            return value.strip().casefold() not in {"", "0", "false", "no", "off"}
        return bool(value)

    def _tier3_online_growth_state(self) -> tuple[bool, str]:
        """Whether ordinary Tier3B growth may cross the online cohort freeze.

        Only capacity growth qualifies: while the published TIER3-AUTO keeps
        fewer alive members than the background target, and never while an
        initial activation, a recovery transaction, a judgement or a ladder
        owns the route, or while the group carries a fixed selection.  No
        I/O: the provider transaction re-proves an append-only projection and
        an unfixed first-member pick against a fresh controller read before it
        writes anything (``_update_running_tier3_core_provider_leased``).
        """

        if not self._tier3_online_growth_enabled():
            return False, "disabled"
        stop_event = getattr(self, "stop_event", None)
        if stop_event is not None and stop_event.is_set():
            return False, "stopping"
        try:
            if self._current_core_runtime_phase() not in {
                "formal_capture",
                "formal_no_capture",
            }:
                return False, "not_online"
            if not self._runtime_initial_activation_was_completed():
                return False, "activation_pending"
            if self._tier3_initial_activation_transaction_active():
                return False, "activation_active"
            if self._runtime_recovery_transaction_active():
                return False, "recovery_active"
            judge = getattr(self._node_judgement_state(), "judge", None)
            if judge is not None and (judge.judging() or judge.ladder_in_flight()):
                return False, "judging"
            view = self._published_tier3_route_view()
            if view is None or not view["loaded"]:
                return False, "no_route_view"
            if view["fixed"]:
                return False, "fixed_selection"
            manager = self.manager
            if manager is None:
                return False, "manager_missing"
            if int(view["alive"]) >= int(self._tier3_background_target_alive(manager)):
                return False, "target_alive_reached"
        except Exception:
            return False, "unavailable"
        return True, "eligible"

    def _tier3_verified_online_write_state(self) -> tuple[bool, str]:
        """Whether a pool change may write the online provider now (verified lane).

        No alive-target, fixed-pin, first-member or empty-group gate: a write
        that keeps the live pick first is safe in each of them, and kicks and
        dead-member replacement must not wait on capacity.  Only another
        owner of the Core route defers it: an activation, a recovery, a
        judgement, a ladder or a facility hold.  No I/O.
        """

        if not self._tier3_verified_lane_open():
            return False, "lane_closed"
        stop_event = getattr(self, "stop_event", None)
        if stop_event is not None and stop_event.is_set():
            return False, "stopping"
        try:
            if self._current_core_runtime_phase() not in {"formal_capture", "formal_no_capture"}:
                return False, "not_online"
            if self._tier3_initial_activation_transaction_active():
                return False, "activation_active"
            if self._runtime_recovery_transaction_active():
                return False, "recovery_active"
            judge = getattr(self._node_judgement_state(), "judge", None)
            if judge is not None and (judge.judging() or judge.ladder_in_flight()):
                return False, "judging"
            if self._runtime_facility_hold_reason():
                # The rebaseline owns the route (the provider lane defers
                # inside a hold): park once instead of an attempt per tick.
                return False, "facility_hold"
        except Exception:
            return False, "unavailable"
        return True, "eligible"

    def _published_tier3_route_view(self) -> dict[str, Any] | None:
        snapshot, payload = self._runtime_post_dial_route_refs()
        if snapshot is None or not isinstance(payload, dict):
            return None
        return self._runtime_tier3_route_view(snapshot, payload.get("proxies"))

    def _tier3_online_growth_surplus(self) -> int:
        """Committed healthy Tier3B nodes that the loaded TIER3-AUTO lacks."""

        try:
            healthy = int(self._tier3_core_gate_check()[1])
            view = self._published_tier3_route_view()
        except Exception:
            return 0
        loaded = int(view["loaded"]) if view else 0
        return max(0, healthy - loaded)

    def _tier3_online_growth_retry_due(self) -> bool:
        waited_at = float(getattr(self, "_tier3_online_growth_waited_at", 0.0) or 0.0)
        if not waited_at:
            return True
        waits = max(1, int(getattr(self, "_tier3_online_growth_waits", 0) or 0))
        if self._tier3_verified_lane_open():
            base, cap = _TIER3_VERIFIED_WRITE_RETRY_SECONDS, _TIER3_VERIFIED_WRITE_RETRY_CAP_SECONDS
        else:
            base, cap = _TIER3_ONLINE_GROWTH_RETRY_SECONDS, _TIER3_ONLINE_GROWTH_RETRY_CAP_SECONDS
        delay = min(cap, base * (2 ** min(waits - 1, 8)))
        return time.monotonic() - waited_at >= delay

    def _retry_parked_tier3_online_growth(self) -> bool:
        """Re-queue parked pool work once online growth may cross the freeze.

        A parked key is only re-queued by a new causal key, so growth that
        waited on the route (or was parked before the Core went online) would
        otherwise sleep until the next admission.  Bounded by the growth
        retry backoff and by a real surplus of unloaded healthy nodes.
        """

        if not hasattr(self, "_tier3_pool_sync_lock"):
            return False
        with self._tier3_pool_sync_lock:
            if (
                self._tier3_pool_sync_pending
                or self._tier3_pool_sync_worker_running
                or getattr(self, "_tier3_pool_sync_parked_key", None) is None
            ):
                return False
        if self._tier3_verified_lane_open():
            # A parked verified write may be a removal or a dead-member
            # replacement, not only growth: retry it whenever its owner gate
            # is open again, on the short verified backoff.
            if not (
                self._tier3_online_growth_retry_due()
                and self._tier3_verified_online_write_state()[0]
            ):
                return False
        elif (
            not self._tier3_online_growth_retry_due()
            or not self._tier3_online_growth_state()[0]
            or self._tier3_online_growth_surplus() <= 0
        ):
            return False
        with self._tier3_pool_sync_lock:
            if (
                self._tier3_pool_sync_pending
                or self._tier3_pool_sync_worker_running
                or getattr(self, "_tier3_pool_sync_parked_key", None) is None
            ):
                return False
            self._tier3_pool_sync_parked_key = None
            self._tier3_pool_sync_parked_event = "append_only"
            self._tier3_pool_sync_last_attempted_key = None
        return self._queue_tier3_pool_sync_after_commit(
            immediate=True,
            sync_event="append_only",
        )

    def _retry_kicked_tier3_pick(self) -> bool:
        """Re-run the verified write that kept a kicked pick in the provider.

        Its grace is judged only inside a write, and the write that kept the
        member changed no causal key, so a stable pool would keep serving (or
        return to) a member the Manager removed.  Due once the grace has
        passed, or once traffic moved off the member natively; an owned pin
        keeps its member until it is released.
        """

        kicked = dict(getattr(self, "_tier3_kicked_pick_since", None) or {})
        if not kicked or not hasattr(self, "_tier3_pool_sync_lock"):
            return False
        try:
            view = self._published_tier3_route_view() or {}
        except Exception:
            return False
        fixed = str(view.get("fixed") or "")
        if fixed in kicked and self._tier3_pin_owner("TIER3-AUTO"):
            return False
        pick = fixed or str(view.get("now") or "")
        now = time.monotonic()
        by_grace = any(
            now - since >= _TIER3_VERIFIED_KICKED_PICK_GRACE_SECONDS for since in kicked.values()
        )
        moved_off = bool(pick) and pick not in kicked
        if not (by_grace or moved_off) or not self._tier3_verified_online_write_state()[0]:
            return False
        # Once per state: a re-run that changed nothing (a stale published
        # view) is not repeated every tick.  The kick stamps make it once per
        # kick episode: a member kicked again under the same stable name
        # (same definition, same name) gets its own re-run.
        signature = (pick, tuple(sorted(kicked.items())), by_grace)
        if signature == getattr(self, "_tier3_kicked_pick_retry_signature", None):
            return False
        with self._tier3_pool_sync_lock:
            if (
                self._tier3_pool_sync_pending
                or self._tier3_pool_sync_worker_running
                or getattr(self, "_tier3_pool_sync_parked_key", None) is not None
            ):
                return False
            # The key did not change: let the same key run once more.
            self._tier3_pool_sync_last_attempted_key = None
        queued = self._queue_tier3_pool_sync_after_commit(
            immediate=True,
            sync_event="semantic_change",
        )
        if queued:
            self._tier3_kicked_pick_retry_signature = signature
        return queued

    def _wake_parked_tier3_pool_sync_if_causal_key_changed(self) -> bool:
        """Wake a parked sync only after a real owner epoch/digest changed."""

        if (
            not hasattr(self, "_tier3_pool_sync_lock")
            or not hasattr(self, "stop_event")
            or self.stop_event.is_set()
            or (
                self._tier3_online_provider_cohort_frozen()
                and not (
                    self._tier3_verified_online_write_state()[0]
                    if self._tier3_verified_lane_open()
                    else self._tier3_online_growth_state()[0]
                )
            )
        ):
            return False
        current_key = self._tier3_provider_sync_key()
        startup_owner_released = bool(
            self._runtime_uses_early_single_coordinator()
            and self._current_core_runtime_phase() == "formal_no_capture"
            and not self._runtime_initial_activation_was_completed()
            and not self._tier3_initial_activation_transaction_active()
        )
        with self._tier3_pool_sync_lock:
            parked_key = getattr(self, "_tier3_pool_sync_parked_key", None)
            if parked_key is None:
                return False
            if parked_key == current_key and not startup_owner_released:
                return False
            parked_event = str(
                getattr(
                    self,
                    "_tier3_pool_sync_parked_event",
                    "append_only",
                )
                or "append_only"
            )
            if parked_key == current_key:
                # Releasing the startup admission lease is itself a causal
                # owner transition even when the pool/config digest did not
                # change. Clear the token so this immutable request can now be
                # claimed by the provider transaction.
                self._tier3_pool_sync_parked_key = None
                self._tier3_pool_sync_parked_event = "append_only"
        return self._queue_tier3_pool_sync_after_commit(
            immediate=True,
            sync_event=parked_event,
            _sync_key=current_key,
        )

    def _queue_tier3_pool_sync_after_commit(
        self,
        *,
        immediate: bool = False,
        sync_event: str = "append_only",
        _sync_key: DeferredProviderSyncKey | None = None,
    ) -> bool:
        event_name = (
            sync_event
            if sync_event in {"append_only", "semantic_change", "selected_leaf_change"}
            else "semantic_change"
        )
        event_priority = {
            "append_only": 0,
            "semantic_change": 1,
            "selected_leaf_change": 2,
        }
        immediate = bool(immediate or self._tier3_pool_target_reached())
        sync_key = _sync_key or self._tier3_provider_sync_key()
        frozen = self._tier3_online_provider_cohort_frozen()
        verified_lane = frozen and self._tier3_verified_lane_open()
        if verified_lane:
            # Every membership change, removals included, goes out at once;
            # the worker's write spacing batches what lands meanwhile.
            gate_open = self._tier3_verified_online_write_state()[0]
            immediate = True
        else:
            gate_open = self._tier3_online_growth_state()[0]
        if frozen and not gate_open:
            with self._tier3_pool_sync_lock:
                previous_key = getattr(
                    self,
                    "_tier3_pool_sync_parked_key",
                    None,
                )
                previous_event = str(
                    getattr(
                        self,
                        "_tier3_pool_sync_parked_event",
                        "append_only",
                    )
                    or "append_only"
                )
                changed = bool(
                    previous_key != sync_key
                    or event_priority[event_name]
                    > event_priority.get(previous_event, 0)
                )
                self._tier3_pool_sync_pending = False
                self._tier3_pool_sync_pending_key = None
                self._tier3_pool_sync_oldest_requested_at = 0.0
                self._tier3_pool_sync_pending_commit_count = 0
                self._tier3_pool_sync_pending_immediate = False
                self._tier3_pool_sync_pending_event = "append_only"
                self._tier3_pool_sync_parked_key = sync_key
                if event_priority[event_name] >= event_priority.get(
                    previous_event,
                    0,
                ):
                    self._tier3_pool_sync_parked_event = event_name
            if changed:
                self._record_tier3_core_sync_ledger(
                    "capacity_deferred",
                    event=event_name,
                )
            return False
        if (
            frozen
            and not verified_lane
            and not immediate
            and self._tier3_online_growth_retry_due()
            and self._tier3_online_growth_surplus() >= _TIER3_ONLINE_GROWTH_MIN_BATCH
        ):
            # Online growth with a whole batch already committed: push it now
            # rather than after the stable-batch hard limit.
            immediate = True
        thread: threading.Thread | None = None
        with self._tier3_pool_sync_lock:
            if self.stop_event.is_set():
                self._tier3_pool_sync_pending = False
                self._tier3_pool_sync_oldest_requested_at = 0.0
                self._tier3_pool_sync_pending_commit_count = 0
                self._tier3_pool_sync_pending_immediate = False
                self._tier3_pool_sync_pending_event = "append_only"
                self._tier3_pool_sync_pending_key = None
                self._tier3_pool_sync_active_key = None
                self._tier3_pool_sync_parked_key = None
                self._tier3_pool_sync_parked_event = "append_only"
                return False
            now = time.monotonic()
            pending_key = getattr(self, "_tier3_pool_sync_pending_key", None)
            active_key = getattr(self, "_tier3_pool_sync_active_key", None)
            parked_key = getattr(self, "_tier3_pool_sync_parked_key", None)
            last_attempted_key = getattr(
                self,
                "_tier3_pool_sync_last_attempted_key",
                None,
            )

            if pending_key == sync_key:
                # Duplicate callbacks may still satisfy the existing batch-size
                # debounce, but they never create a second immutable attempt.
                self._tier3_pool_sync_pending_commit_count += 1
                self._tier3_pool_sync_pending_immediate = bool(
                    self._tier3_pool_sync_pending_immediate or immediate
                )
                if event_priority[event_name] > event_priority.get(
                    self._tier3_pool_sync_pending_event,
                    0,
                ):
                    self._tier3_pool_sync_pending_event = event_name
                return False
            if sync_key in {active_key, parked_key, last_attempted_key}:
                return False

            if not self._tier3_pool_sync_pending:
                self._tier3_pool_sync_oldest_requested_at = now
                self._tier3_pool_sync_pending_commit_count = 0
                self._tier3_pool_sync_pending_immediate = False
                self._tier3_pool_sync_pending_event = "append_only"
            self._tier3_pool_sync_pending = True
            self._tier3_pool_sync_pending_key = sync_key
            self._tier3_pool_sync_parked_key = None
            self._tier3_pool_sync_parked_event = "append_only"
            self._tier3_pool_sync_last_requested_at = now
            self._tier3_pool_sync_pending_commit_count += 1
            self._tier3_pool_sync_pending_immediate = bool(
                self._tier3_pool_sync_pending_immediate or immediate
            )
            if event_priority[event_name] > event_priority.get(
                self._tier3_pool_sync_pending_event,
                0,
            ):
                self._tier3_pool_sync_pending_event = event_name
            if self._tier3_pool_sync_worker_running:
                accepted = True
            else:
                self._tier3_pool_sync_worker_running = True
                thread = threading.Thread(
                    target=self._tier3_pool_sync_worker,
                    name="desktop-tier3-pool-sync",
                    daemon=True,
                )
                self._tier3_pool_sync_thread = thread
                accepted = True
        self._record_tier3_core_sync_ledger(
            "request",
            event=event_name,
        )
        if thread is not None:
            thread.start()
        return accepted

    def _tier3_pool_sync_worker(self) -> None:
        successor: threading.Thread | None = None
        try:
            while True:
                while True:
                    if self.stop_event.is_set():
                        return
                    with self._tier3_pool_sync_lock:
                        if (
                            not self._tier3_pool_sync_pending
                            or self._tier3_pool_sync_pending_key is None
                        ):
                            # A boolean without its immutable key is not work.
                            self._tier3_pool_sync_pending = False
                            self._tier3_pool_sync_pending_key = None
                            self._tier3_pool_sync_worker_running = False
                            if self._tier3_pool_sync_thread is threading.current_thread():
                                self._tier3_pool_sync_thread = None
                            return
                    qualification_stable = (
                        self._tier3_runtime_qualification_stable()
                    )
                    formal_baseline_loaded = (
                        self._tier3_pool_sync_formal_baseline_loaded()
                    )
                    with self._tier3_pool_sync_lock:
                        requested_at = self._tier3_pool_sync_last_requested_at
                        oldest_requested_at = (
                            self._tier3_pool_sync_oldest_requested_at
                            or requested_at
                        )
                        pending_commit_count = max(
                            0,
                            int(self._tier3_pool_sync_pending_commit_count),
                        )
                        immediate = bool(self._tier3_pool_sync_pending_immediate)
                        cooldown_until = self._tier3_pool_sync_cooldown_until
                    if immediate:
                        ready_at = max(
                            oldest_requested_at
                            + min(0.05, self._tier3_pool_sync_debounce_seconds),
                            cooldown_until,
                        )
                    elif pending_commit_count >= self._tier3_pool_sync_batch_size:
                        ready_at = max(
                            oldest_requested_at
                            + min(0.05, self._tier3_pool_sync_debounce_seconds),
                            cooldown_until,
                        )
                    elif qualification_stable or formal_baseline_loaded:
                        ready_at = max(
                            oldest_requested_at
                            + self._tier3_pool_sync_stable_hard_limit_seconds,
                            cooldown_until,
                        )
                    else:
                        ready_at = max(
                            oldest_requested_at
                            + self._tier3_pool_sync_max_wait_seconds,
                            cooldown_until,
                        )
                    remaining = ready_at - time.monotonic()
                    if remaining <= 0:
                        break
                    if self.stop_event.wait(min(0.1, remaining)):
                        return
                with self._tier3_pool_sync_lock:
                    sync_key = self._tier3_pool_sync_pending_key
                    if not self._tier3_pool_sync_pending or sync_key is None:
                        self._tier3_pool_sync_pending = False
                        self._tier3_pool_sync_pending_key = None
                        self._tier3_pool_sync_worker_running = False
                        if self._tier3_pool_sync_thread is threading.current_thread():
                            self._tier3_pool_sync_thread = None
                        return
                    self._tier3_pool_sync_pending = False
                    self._tier3_pool_sync_pending_key = None
                    self._tier3_pool_sync_active_key = sync_key
                    self._tier3_pool_sync_last_attempted_key = sync_key
                    batch_size = max(
                        1,
                        int(self._tier3_pool_sync_pending_commit_count),
                    )
                    sync_event = self._tier3_pool_sync_pending_event
                    self._tier3_pool_sync_pending_commit_count = 0
                    self._tier3_pool_sync_oldest_requested_at = 0.0
                    self._tier3_pool_sync_pending_immediate = False
                    self._tier3_pool_sync_pending_event = "append_only"
                if self.stop_event.is_set():
                    continue
                started = time.monotonic()
                try:
                    sync_callback = self._sync_core_config_after_pool_update
                    try:
                        sync_parameters = inspect.signature(
                            sync_callback
                        ).parameters.values()
                    except (TypeError, ValueError):
                        sync_parameters = ()
                    if any(
                        parameter.kind is inspect.Parameter.VAR_KEYWORD
                        or parameter.name == "expected_key"
                        for parameter in sync_parameters
                    ):
                        raw_outcome = sync_callback(expected_key=sync_key)
                    else:
                        raw_outcome = sync_callback()
                except Exception as exc:
                    log_raw_diagnostic(
                        self.logger,
                        "warning",
                        "Bastion Layer runtime sync after pool commit failed",
                        exc_info=True,
                    )
                    outcome = _ProviderSyncOutcome(
                        ProviderSyncDisposition.UNKNOWN,
                        str(exc),
                    )
                else:
                    if isinstance(raw_outcome, _ProviderSyncOutcome):
                        outcome = raw_outcome
                    elif isinstance(raw_outcome, ProviderSyncDisposition):
                        outcome = _ProviderSyncOutcome(raw_outcome)
                    elif raw_outcome is False:
                        outcome = _ProviderSyncOutcome(ProviderSyncDisposition.NOOP)
                    elif raw_outcome is None or raw_outcome is True:
                        # Keep focused lifecycle adapters compatible while the
                        # production path always returns an explicit outcome.
                        outcome = _ProviderSyncOutcome(
                            ProviderSyncDisposition.COMMITTED
                        )
                    else:
                        outcome = _ProviderSyncOutcome(
                            ProviderSyncDisposition.UNKNOWN,
                            "provider sync returned an invalid disposition",
                        )

                with self._tier3_pool_sync_lock:
                    if self._tier3_pool_sync_active_key == sync_key:
                        self._tier3_pool_sync_active_key = None

                if self.stop_event.is_set():
                    continue
                elapsed_seconds = max(0.0, time.monotonic() - started)
                if outcome.disposition is ProviderSyncDisposition.PARKED:
                    current_key = self._tier3_provider_sync_key()
                    if current_key != sync_key:
                        # The causal owner may have advanced just before the
                        # parked result was published. Do not strand the old
                        # key if that owner's one wake call raced this worker.
                        self._queue_tier3_pool_sync_after_commit(
                            immediate=True,
                            sync_event=sync_event,
                            _sync_key=current_key,
                        )
                        continue
                    with self._tier3_pool_sync_lock:
                        parked_registered = not self._tier3_pool_sync_pending
                        if parked_registered:
                            self._tier3_pool_sync_parked_key = sync_key
                            self._tier3_pool_sync_parked_event = sync_event
                    if parked_registered:
                        self.logger.info(
                            "Bastion Layer provider sync parked "
                            "(runtime_generation=%s core_generation=%s "
                            "pool_revision=%s network_epoch=%s facility_epoch=%s "
                            "reason=%s)",
                            sync_key.runtime_generation,
                            sync_key.core_generation,
                            sync_key.pool_revision,
                            sync_key.network_epoch,
                            sync_key.facility_epoch,
                            str(outcome.reason or "causal owner is unavailable")[:160],
                        )
                    continue

                if outcome.disposition is ProviderSyncDisposition.SUPERSEDED:
                    current_key = self._tier3_provider_sync_key()
                    if current_key != sync_key:
                        self._queue_tier3_pool_sync_after_commit(
                            immediate=True,
                            sync_event=sync_event,
                            _sync_key=current_key,
                        )
                    continue

                if outcome.disposition is ProviderSyncDisposition.UNKNOWN:
                    log_raw_diagnostic(
                        self.logger,
                        "warning",
                        "Bastion Layer provider sync ended with unknown state "
                        "(pool_revision=%s reason=%s)",
                        sync_key.pool_revision,
                        str(outcome.reason or "unverified provider state")[:160],
                    )
                    continue

                self._mark_tier3_pool_sync_formal_baseline_loaded()
                if elapsed_seconds > self._tier3_pool_sync_slow_threshold_seconds:
                    with self._tier3_pool_sync_lock:
                        self._tier3_pool_sync_cooldown_until = max(
                            self._tier3_pool_sync_cooldown_until,
                            time.monotonic() + self._tier3_pool_sync_slow_cooldown_seconds,
                        )
                self.logger.info(
                    "Bastion Layer runtime sync after pool commit completed "
                    "(runtime_reload_elapsed_ms=%s mode=incremental_export "
                    "sync_event=%s batch_size=%s disposition=%s slow=%s)",
                    int(round(elapsed_seconds * 1000)),
                    sync_event,
                    batch_size,
                    outcome.disposition.value,
                    elapsed_seconds > self._tier3_pool_sync_slow_threshold_seconds,
                )
                if outcome.disposition is ProviderSyncDisposition.COMMITTED:
                    self._record_tier3_core_sync_event(sync_event)
        finally:
            with self._tier3_pool_sync_lock:
                if self._tier3_pool_sync_thread is threading.current_thread():
                    self._tier3_pool_sync_active_key = None
                    if self.stop_event.is_set():
                        self._tier3_pool_sync_pending = False
                        self._tier3_pool_sync_pending_key = None
                        self._tier3_pool_sync_worker_running = False
                    elif self._tier3_pool_sync_worker_running:
                        # Only unexpected worker exits need a successor. Normal
                        # completion clears the running bit before returning.
                        self._tier3_pool_sync_worker_running = False
                        if (
                            self._tier3_pool_sync_pending
                            and self._tier3_pool_sync_pending_key is not None
                        ):
                            self._tier3_pool_sync_worker_running = True
                            successor = threading.Thread(
                                target=self._tier3_pool_sync_worker,
                                name="desktop-tier3-pool-sync",
                                daemon=True,
                            )
                            self._tier3_pool_sync_thread = successor
                    if successor is None:
                        self._tier3_pool_sync_thread = None
            if successor is not None:
                successor.start()

    def _queue_tier3_core_gate_attempt(self) -> bool:
        with self._tier3_core_gate_lock:
            if self.stop_event.is_set():
                self._tier3_core_gate_pending = False
                self._tier3_core_gate_requested_at = None
                return False
            self._tier3_core_gate_pending = True
            self._tier3_core_gate_generation += 1
            self._tier3_core_gate_pending_generation = self._tier3_core_gate_generation
            if self._tier3_core_gate_requested_at is None:
                self._tier3_core_gate_requested_at = time.monotonic()
            if self._tier3_core_gate_worker_running:
                return True
            self._tier3_core_gate_worker_running = True
            thread = threading.Thread(
                target=self._tier3_core_gate_worker,
                name="desktop-tier3-core-gate",
                daemon=True,
            )
            self._tier3_core_gate_thread = thread
            thread.start()
        return True

    def _tier3_core_gate_worker(self) -> None:
        try:
            while True:
                with self._tier3_core_gate_lock:
                    if not self._tier3_core_gate_pending:
                        self._tier3_core_gate_worker_running = False
                        self._tier3_core_gate_requested_at = None
                        return
                    self._tier3_core_gate_pending = False
                    requested_at = self._tier3_core_gate_requested_at
                    gate_generation = self._tier3_core_gate_pending_generation
                    self._tier3_core_gate_requested_at = None
                ready, healthy, required, reason = self._tier3_core_gate_check()
                if not ready:
                    manager = self.manager
                    if (
                        reason == "startup_supply_exhausted"
                        and manager is not None
                    ):
                        self._fail_terminal_tier3_bootstrap(manager)
                    self.logger.info(
                        "Bastion Layer core gate worker skipped committed pool "
                        "(healthy=%s required=%s reason=%s)",
                        healthy,
                        required,
                        reason,
                    )
                    continue
                marker = self._tier3_core_sync_marker()
                core_gate_latency_ms = (
                    int(round(max(0.0, time.monotonic() - requested_at) * 1000))
                    if requested_at is not None
                    else None
                )
                self.logger.info(
                    "Bastion Layer core gate processing committed pool "
                    "(healthy=%s required=%s reason=%s core_gate_latency_ms=%s)",
                    healthy,
                    required,
                    reason,
                    core_gate_latency_ms,
                )
                if self._attempt_deferred_tier3_core_start(
                    marker,
                    committed_pool_only=True,
                    gate_generation=gate_generation,
                ) and not self.stop_event.is_set():
                    manager = self.manager
                    marker_fn = getattr(manager, "mark_tier3_core_running", None) if manager else None
                    if callable(marker_fn):
                        try:
                            marker_fn(
                                core_gate_latency_ms=core_gate_latency_ms,
                                effective_egress_ok=False,
                                traffic_capture_active=False,
                            )
                        except TypeError:
                            marker_fn(
                                core_gate_latency_ms=core_gate_latency_ms,
                                effective_egress_ok=False,
                            )
        finally:
            with self._tier3_core_gate_lock:
                if self._tier3_core_gate_pending:
                    rerun = True
                else:
                    self._tier3_core_gate_worker_running = False
                    rerun = False
            if rerun:
                self._tier3_core_gate_worker()

    def _reload_running_tier3_core_config_for_marker(self, marker: tuple[Any, ...] | None) -> bool:
        if not should_reload_tier3_core_config_for_marker(
            marker=marker,
            last_marker=self._last_tier3_core_sync_marker,
        ):
            self._record_tier3_core_sync_ledger(
                "semantic_noop",
                semantic_digest=self._core_semantic_digest_from_marker(marker),
            )
            return False
        if self._tier3_core_sync_failure_is_recent(marker):
            return False
        if self.stop_event.is_set():
            return False
        self.logger.info(
            "Bastion Layer healthy export changed; reloading mihomo runtime config"
        )
        try:
            result = self.reload_core_config(
                mode="incremental_export",
                reason=RuntimeReloadReason.MEMBERSHIP_UNREPRESENTABLE,
            )
        except Exception:
            self._mark_tier3_core_sync_failure(marker)
            raise
        if reload_core_config_succeeded(result):
            self._mark_tier3_export_sync_complete()
            self._record_tier3_core_sync_ledger(
                "config_apply",
                semantic_digest=self._core_semantic_digest_from_marker(marker),
            )
            return True
        self._mark_tier3_core_sync_failure(marker)
        return False

    def _reload_running_core_config_for_export_marker(self, marker: tuple[Any, ...] | None) -> bool:
        if marker is None:
            return False
        if self._last_core_export_sync_marker is None:
            self._last_core_export_sync_marker = marker
            return False
        if marker == self._last_core_export_sync_marker:
            self._record_tier3_core_sync_ledger(
                "semantic_noop",
                semantic_digest=self._core_semantic_digest_from_marker(marker),
            )
            return False
        if (
            self._core_semantic_digest_from_marker(marker)
            == self._core_semantic_digest_from_marker(
                self._last_core_export_sync_marker
            )
        ):
            # Keep the newest diagnostic marker without creating a config
            # generation or hot reload when rendered Mihomo semantics did not
            # change.
            self._last_core_export_sync_marker = marker
            self._record_tier3_core_sync_ledger(
                "semantic_noop",
                semantic_digest=self._core_semantic_digest_from_marker(marker),
            )
            return False
        if self._core_export_sync_failure_is_recent(marker):
            return False
        if self.stop_event.is_set():
            return False
        self.logger.info("Runtime proxy export changed; reloading mihomo runtime config")
        try:
            result = self.reload_core_config(
                mode="incremental_export",
                reason=RuntimeReloadReason.MEMBERSHIP_UNREPRESENTABLE,
            )
        except Exception:
            self._mark_core_export_sync_failure(marker)
            raise
        if reload_core_config_succeeded(result):
            self._mark_core_export_sync_success(marker)
            self._record_tier3_core_sync_ledger(
                "config_apply",
                semantic_digest=self._core_semantic_digest_from_marker(marker),
            )
            return True
        self._mark_core_export_sync_failure(marker)
        return False

    def _runtime_recovery_transaction_active(self) -> bool:
        if self._runtime_egress_coordinator.core_mutation_active():
            return True
        with self._runtime_failure_monitor_lock:
            return any(
                state in {"pending", "recovering"}
                for state in self._runtime_incident_recovery_state.values()
            )

    def _runtime_incident_provider_rebase_conflicts(
        self,
        ticket: _RuntimeRecoveryTicket,
    ) -> bool:
        if self._runtime_egress_coordinator.core_mutation_active():
            return True
        with self._runtime_failure_monitor_lock:
            return any(
                incident_id != ticket.incident_id
                and state in {"pending", "recovering"}
                for incident_id, state in self._runtime_incident_recovery_state.items()
            )

    def _runtime_provider_timeout(
        self,
        deadline_monotonic: float | None,
        *,
        cap: float,
    ) -> float:
        """Return a controller timeout that can never cross an incident clock."""

        if deadline_monotonic is None:
            return max(0.05, float(cap))
        remaining = float(deadline_monotonic) - self._runtime_recovery_now()
        if remaining <= 0.05:
            raise TimeoutError("provider transaction deadline expired")
        return max(0.05, min(float(cap), remaining))

    def _tier3_provider_mutation_binding(
        self,
        expected_pool_marker: tuple[Any, ...] | None = None,
        *,
        recovery_ticket: _RuntimeRecoveryTicket | None = None,
        deadline_monotonic: float | None = None,
    ) -> dict[str, Any] | None:
        if isinstance(recovery_ticket, _RuntimeRecoveryTicket) and not (
            self._runtime_recovery_ticket_is_current(
                recovery_ticket,
                require_open=True,
                deadline_monotonic=deadline_monotonic,
            )
        ):
            return None
        runner = self.core_runner
        if runner is None or not runner.is_running():
            return None
        try:
            status = runner.status()
        except Exception:
            return None
        pid = int(status.get("pid") or 0)
        process_generation = int(status.get("process_generation") or 0)
        if pid <= 0 or process_generation <= 0:
            return None
        # Route selection may have changed autonomously inside Mihomo since
        # the last application snapshot.  Bind the provider transaction to a
        # fresh controller read before touching the provider file, otherwise
        # a pre-existing fallback change is misreported as provider drift and
        # every subsequent update rolls back against the same stale guard.
        try:
            refreshed = self._refresh_runtime_route_snapshot(
                timeout_seconds=self._runtime_provider_timeout(
                    deadline_monotonic,
                    cap=0.35,
                )
            )
        except Exception:
            return None
        if refreshed is None:
            return None
        with self._core_lifecycle_lock:
            core_generation = int(self._core_generation)
            phase = str(self._core_runtime_phase or "")
        with self._runtime_route_snapshot_lock:
            contract = self._runtime_loaded_export_contract
            if not isinstance(contract, dict):
                return None
            contract_revision = int(contract.get("revision") or 0)
            contract_identity = id(contract)
            semantic_digest = str(contract.get("semantic_digest") or "")
            route_epoch = int(self._runtime_route_epoch)
            route_guard = self._tier3_provider_route_guard(
                self._runtime_route_snapshot_payload
            )
        manager = self.manager
        manager_lock = getattr(manager, "lock", None) if manager is not None else None
        if manager_lock is None:
            return None
        with manager_lock:
            pool_revision = int(
                getattr(manager, "tier3_pool_revision", 0) or 0
            )
        pool_marker = self._tier3_core_sync_marker()
        if (
            expected_pool_marker is not None
            and pool_marker != expected_pool_marker
        ):
            return None
        binding = {
            "pid": pid,
            "process_generation": process_generation,
            "core_generation": core_generation,
            "phase": phase,
            "contract_revision": contract_revision,
            "contract_identity": contract_identity,
            "semantic_digest": semantic_digest,
            "route_epoch": route_epoch,
            "network_context_epoch": int(
                getattr(self, "_runtime_network_context_epoch", 0) or 0
            ),
            "facility_epoch": int(
                getattr(self, "_runtime_facility_epoch", 0) or 0
            ),
            "selector_intent_revision": int(
                getattr(self, "_runtime_selector_intent_revision", 0) or 0
            ),
            "tier3_pool_revision": pool_revision,
            "tier3_pool_marker": pool_marker,
            "route_guard": route_guard,
            "route_authority_semantic_digest": str(
                getattr(refreshed, "semantic_digest", "") or ""
            ),
        }
        if isinstance(recovery_ticket, _RuntimeRecoveryTicket):
            binding.update(
                {
                    "recovery_incident_id": recovery_ticket.incident_id,
                    "recovery_ticket_generation": recovery_ticket.generation,
                    "recovery_deadline_monotonic": float(
                        deadline_monotonic
                        if deadline_monotonic is not None
                        else recovery_ticket.deadline_monotonic
                    ),
                }
            )
        return binding

    @staticmethod
    def _tier3_pool_marker_extends(current: Any, bound: Any) -> bool:
        """``current`` is ``bound`` with later admissions appended in order."""

        return (
            isinstance(current, tuple)
            and isinstance(bound, tuple)
            and len(current) >= len(bound)
            and current[: len(bound)] == bound
        )

    def _tier3_pool_binding_holds(
        self,
        binding: dict[str, Any],
        pool_revision: int,
    ) -> bool:
        """Pool CAS of one provider transaction.

        Exact by default.  An online-growth transaction (``pool_growth_tolerant``)
        loads an append-only prefix of the committed export order, so an
        admission that only appends to that order cannot invalidate it; any
        removal, reorder or rewritten member still does.
        """

        current_marker = self._tier3_core_sync_marker()
        bound_marker = binding.get("tier3_pool_marker")
        if bool(binding.get("pool_growth_tolerant")):
            return current_marker == bound_marker or self._tier3_pool_marker_extends(
                current_marker,
                bound_marker,
            )
        return (
            int(pool_revision) == int(binding.get("tier3_pool_revision") or 0)
            and current_marker == bound_marker
        )

    def _tier3_provider_mutation_binding_is_current(
        self,
        binding: dict[str, Any] | None,
    ) -> bool:
        if (
            not isinstance(binding, dict)
            or self.stop_event.is_set()
            or (
                self._runtime_facility_hold_reason()
                and not bool(binding.get("allow_facility_hold_append"))
            )
        ):
            return False
        incident_id = str(binding.get("recovery_incident_id") or "")
        if incident_id:
            with self._runtime_failure_monitor_lock:
                ticket = self._runtime_recovery_tickets.get(incident_id)
                if not (
                    isinstance(ticket, _RuntimeRecoveryTicket)
                    and ticket.generation
                    == int(binding.get("recovery_ticket_generation") or 0)
                    and self._runtime_recovery_ticket_matches_locked(
                        ticket,
                        require_open=True,
                        deadline_monotonic=float(
                            binding.get("recovery_deadline_monotonic") or 0.0
                        ),
                    )
                ):
                    return False
        runner = self.core_runner
        if runner is None or not runner.is_running():
            return False
        try:
            status = runner.status()
        except Exception:
            return False
        if (
            int(status.get("pid") or 0) != int(binding.get("pid") or 0)
            or int(status.get("process_generation") or 0)
            != int(binding.get("process_generation") or 0)
        ):
            return False
        with self._core_lifecycle_lock:
            if (
                int(self._core_generation)
                != int(binding.get("core_generation") or 0)
                or str(self._core_runtime_phase or "")
                != str(binding.get("phase") or "")
            ):
                return False
        ignore_route_selection = bool(binding.get("ignore_route_selection"))
        with self._runtime_route_snapshot_lock:
            contract = self._runtime_loaded_export_contract
            if not isinstance(contract, dict):
                return False
            expected_revision = int(binding.get("contract_revision") or 0)
            if (
                (
                    not ignore_route_selection
                    and int(self._runtime_route_epoch)
                    != int(binding.get("route_epoch") or 0)
                )
                or str(contract.get("semantic_digest") or "")
                != str(binding.get("semantic_digest") or "")
                or (
                    expected_revision > 0
                    and int(contract.get("revision") or 0) != expected_revision
                )
                or (
                    expected_revision <= 0
                    and id(contract) != int(binding.get("contract_identity") or 0)
                )
            ):
                return False
        if "tier3_pool_marker" in binding:
            manager = self.manager
            manager_lock = getattr(manager, "lock", None) if manager is not None else None
            if manager_lock is None:
                return False
            with manager_lock:
                pool_revision = int(
                    getattr(manager, "tier3_pool_revision", 0) or 0
                )
            if not self._tier3_pool_binding_holds(binding, pool_revision):
                return False
        if ignore_route_selection:
            return True
        return bool(
            int(getattr(self, "_runtime_network_context_epoch", 0) or 0)
            == int(binding.get("network_context_epoch") or 0)
            and int(getattr(self, "_runtime_facility_epoch", 0) or 0)
            == int(binding.get("facility_epoch") or 0)
            and int(getattr(self, "_runtime_selector_intent_revision", 0) or 0)
            == int(binding.get("selector_intent_revision") or 0)
        )

    def _commit_tier3_provider_contract_from_readback(
        self,
        *,
        contract: dict[str, Any],
        proxies_payload: dict[str, Any],
        mutation_binding: dict[str, Any],
        provider_version: str = "",
        preserve_route_authority: bool = False,
    ) -> CoreLoadedRouteSnapshot | None:
        """Atomically publish one provider contract and its proven route graph.

        ``proxies_payload`` is the same controller response that already
        proved exact provider membership and selector/fixed readback.  This
        helper performs no network I/O: either that response, the candidate
        contract, and every CAS owner become current together, or the previous
        loaded contract and snapshot remain untouched.
        """

        if (
            not isinstance(contract, dict)
            or not isinstance(proxies_payload, dict)
            or not isinstance(mutation_binding, dict)
        ):
            return None
        semantic_digest = str(contract.get("semantic_digest") or "")
        route_authority_semantic_digest = semantic_digest
        if preserve_route_authority:
            route_authority_semantic_digest = str(
                mutation_binding.get("route_authority_semantic_digest") or ""
            )
        proxy_map = contract.get("proxy_map")
        if (
            not semantic_digest
            or not route_authority_semantic_digest
            or not isinstance(proxy_map, dict)
        ):
            return None
        runner = getattr(self, "core_runner", None)
        if runner is None or not runner.is_running():
            return None
        try:
            status = runner.status()
        except Exception:
            status = {}
        pid = int(status.get("pid") or 0)
        process_generation = int(status.get("process_generation") or 0)
        if (
            pid <= 0
            and process_generation <= 0
            and "pid" not in mutation_binding
            and "process_generation" not in mutation_binding
        ):
            # Compatibility for narrow in-process test/embedding runners. A
            # production mutation binding always carries both Core owners.
            pid = 1
            process_generation = 1
        if pid <= 0 or process_generation <= 0:
            return None
        if (
            "pid" in mutation_binding
            and pid != int(mutation_binding.get("pid") or 0)
        ) or (
            "process_generation" in mutation_binding
            and process_generation
            != int(mutation_binding.get("process_generation") or 0)
        ):
            return None

        lifecycle_lock = getattr(self, "_core_lifecycle_lock", None)
        with lifecycle_lock if lifecycle_lock is not None else nullcontext():
            core_generation = int(getattr(self, "_core_generation", 0) or 0)
            phase = str(getattr(self, "_core_runtime_phase", "") or "")
        if (
            "core_generation" in mutation_binding
            and core_generation
            != int(mutation_binding.get("core_generation") or 0)
        ) or (
            "phase" in mutation_binding
            and phase != str(mutation_binding.get("phase") or "")
        ):
            return None

        try:
            graph, _selection, group_states = (
                self._runtime_group_graph_and_selection(proxies_payload)
            )
            selection = self._runtime_final_exit_selection_signature(
                proxies_payload,
                proxy_map,
            )
        except Exception:
            return None
        refs = tuple(
            RuntimeNodeRef(
                tier=str(info.get("tier") or ""),
                pool_kind=str(info.get("pool_kind") or ""),
                identity=str(info.get("identity") or ""),
                proxy_name=str(proxy_name),
            )
            for proxy_name, info in proxy_map.items()
            if isinstance(info, dict) and str(info.get("identity") or "")
        )

        manager = getattr(self, "manager", None)
        manager_lock = getattr(manager, "lock", None) if manager is not None else None
        route_lock = getattr(self, "_runtime_route_snapshot_lock", None)
        if manager_lock is None or route_lock is None:
            return None
        with manager_lock:
            if bool(mutation_binding.get("pool_growth_tolerant")):
                if "tier3_pool_marker" in mutation_binding and not (
                    self._tier3_pool_binding_holds(
                        mutation_binding,
                        int(getattr(manager, "tier3_pool_revision", 0) or 0),
                    )
                ):
                    return None
            elif (
                "tier3_pool_revision" in mutation_binding
                and int(getattr(manager, "tier3_pool_revision", 0) or 0)
                != int(mutation_binding.get("tier3_pool_revision") or 0)
            ) or (
                "tier3_pool_marker" in mutation_binding
                and self._tier3_core_sync_marker()
                != mutation_binding.get("tier3_pool_marker")
            ):
                return None
            with route_lock:
                current_contract = getattr(
                    self,
                    "_runtime_loaded_export_contract",
                    None,
                )
                if not isinstance(current_contract, dict):
                    return None
                expected_revision = int(
                    mutation_binding.get("contract_revision") or 0
                )
                if (
                    "route_epoch" in mutation_binding
                    and int(getattr(self, "_runtime_route_epoch", 0) or 0)
                    != int(mutation_binding.get("route_epoch") or 0)
                ) or (
                    "semantic_digest" in mutation_binding
                    and str(current_contract.get("semantic_digest") or "")
                    != str(mutation_binding.get("semantic_digest") or "")
                ) or (
                    expected_revision > 0
                    and int(current_contract.get("revision") or 0)
                    != expected_revision
                ) or (
                    "contract_identity" in mutation_binding
                    and expected_revision <= 0
                    and id(current_contract)
                    != int(mutation_binding.get("contract_identity") or 0)
                ) or (
                    "network_context_epoch" in mutation_binding
                    and int(
                        getattr(self, "_runtime_network_context_epoch", 0) or 0
                    )
                    != int(mutation_binding.get("network_context_epoch") or 0)
                ) or (
                    "facility_epoch" in mutation_binding
                    and int(getattr(self, "_runtime_facility_epoch", 0) or 0)
                    != int(mutation_binding.get("facility_epoch") or 0)
                ) or (
                    "selector_intent_revision" in mutation_binding
                    and int(
                        getattr(self, "_runtime_selector_intent_revision", 0)
                        or 0
                    )
                    != int(
                        mutation_binding.get("selector_intent_revision") or 0
                    )
                ):
                    return None
                if self._runtime_facility_hold_reason() and not bool(
                    mutation_binding.get("allow_facility_hold_append")
                ):
                    return None

                previous_selection = tuple(
                    getattr(self, "_runtime_route_selection_signature", ())
                    or ()
                )
                previous_snapshot = getattr(
                    self,
                    "_runtime_route_snapshot",
                    None,
                )
                selection_changed = bool(
                    isinstance(previous_snapshot, CoreLoadedRouteSnapshot)
                    and previous_selection
                    and selection != previous_selection
                )
                published_selection = (
                    previous_selection
                    if not isinstance(
                        previous_snapshot,
                        CoreLoadedRouteSnapshot,
                    )
                    and previous_selection
                    else selection
                )
                if selection_changed:
                    self._runtime_route_epoch = int(
                        getattr(self, "_runtime_route_epoch", 0) or 0
                    ) + 1
                    self._node_judgement_arm_epoch("commit_tier3_provider_contract_from_readback")
                    self._mark_runtime_route_attribution_barrier_locked()
                route_epoch = int(
                    getattr(self, "_runtime_route_epoch", 0) or 0
                )
                self._runtime_loaded_export_revision = int(
                    getattr(self, "_runtime_loaded_export_revision", 0) or 0
                ) + 1
                committed_contract = {
                    **copy.deepcopy(contract),
                    "loaded_at_monotonic": time.monotonic(),
                    "revision": int(self._runtime_loaded_export_revision),
                }
                if preserve_route_authority:
                    committed_contract["route_authority_semantic_digest"] = (
                        route_authority_semantic_digest
                    )
                snapshot = CoreLoadedRouteSnapshot(
                    process_pid=pid,
                    process_generation=process_generation,
                    core_generation=core_generation,
                    semantic_digest=route_authority_semantic_digest,
                    route_epoch=route_epoch,
                    network_context_epoch=int(
                        getattr(self, "_runtime_network_context_epoch", 0) or 0
                    ),
                    group_graph=graph,
                    group_states=group_states,
                    proxy_nodes=refs,
                    loaded_at_monotonic=time.monotonic(),
                )
                self._runtime_loaded_export_contract = committed_contract
                self._runtime_pending_export_contract = None
                self._runtime_route_selection_signature = published_selection
                self._runtime_route_snapshot = snapshot
                self._runtime_route_snapshot_payload = {
                    "proxies": copy.deepcopy(proxies_payload),
                    "proxy_map": copy.deepcopy(proxy_map),
                }
                self._runtime_core_inventory_snapshot = (
                    self._core_inventory_from_route_snapshot(
                        snapshot,
                        provider_version=str(provider_version or ""),
                    )
                )
                self._runtime_unknown_provider_refresh_key = None
                coordinator = getattr(
                    self,
                    "_runtime_egress_coordinator",
                    None,
                )
                set_snapshot = getattr(coordinator, "set_current_snapshot", None)
                if callable(set_snapshot):
                    set_snapshot(snapshot)
                return snapshot

    @staticmethod
    def _tier3_provider_member_names_from_bytes(payload: bytes) -> tuple[str, ...]:
        try:
            document = yaml.safe_load(payload.decode("utf-8"))
        except Exception:
            return ()
        proxies = document.get("proxies") if isinstance(document, dict) else None
        if not isinstance(proxies, list):
            return ()
        names: list[str] = []
        for proxy in proxies:
            name = (
                str(proxy.get("name") or "").strip()
                if isinstance(proxy, dict)
                else ""
            )
            if not name or name in names:
                return ()
            names.append(name)
        return tuple(names)

    def _tier3_provider_route_guard(
        self,
        snapshot_payload: dict[str, Any] | None,
    ) -> dict[str, Any]:
        """Capture selection state that a provider refresh must not drift."""

        if not isinstance(snapshot_payload, dict):
            return {}
        controller_payload = snapshot_payload.get("proxies")
        if not isinstance(controller_payload, dict):
            return {}
        entries = controller_payload.get("proxies")
        if not isinstance(entries, dict):
            entries = controller_payload
        tier3_group = entries.get("TIER3-AUTO") if isinstance(entries, dict) else None
        final_route = inspect_runtime_route(
            controller_payload,
            start="FINAL-EXIT",
        )
        return {
            "tier3_now": (
                str(tier3_group.get("now") or "")
                if isinstance(tier3_group, dict)
                else ""
            ),
            "tier3_fixed_observed": bool(
                isinstance(tier3_group, dict) and "fixed" in tier3_group
            ),
            "tier3_fixed": (
                str(tier3_group.get("fixed") or "")
                if isinstance(tier3_group, dict)
                else ""
            ),
            "final_chain": tuple(
                str(item)
                for item in final_route.get("selected_chain", []) or []
            ),
            "final_leaf": str(final_route.get("leaf_proxy") or ""),
            "final_facility_failure": str(
                final_route.get("facility_failure") or ""
            ),
        }

    def _settle_unfixed_tier3_provider_pick(
        self,
        previous_route_guard: dict[str, Any],
        current_route_guard: dict[str, Any],
        proxies_payload: dict[str, Any],
        *,
        expected_group_members: list[str] | tuple[str, ...],
        deadline_monotonic: float | None = None,
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        """Wait, bounded, for Mihomo to restore an unfixed TIER3-AUTO pick.

        A provider PUT rebuilds every provider member with fresh health
        state, so an unfixed fallback natively returns its first member until
        the provider's post-update URLTest round (the group's own URL/status)
        re-marks the members ahead of the previous pick.  Under the real-site
        TIER3-AUTO contract that first member is often alive only for the
        neutral probes, so the immediate readback reported the reset as route
        drift and the equally resetting rollback could never verify.  Nothing
        is probed or selected here, and only a readback equal to the previous
        guard is accepted: fixed selections, any other FINAL-EXIT change, a
        previous pick that is no longer loaded and a pick that does not return
        in time still fail the caller's exact comparison.
        """

        def without_native_pick(guard: dict[str, Any]) -> dict[str, Any]:
            chain = tuple(guard.get("final_chain") or ())
            leaf = str(guard.get("final_leaf") or "")
            if "TIER3-AUTO" in chain:
                chain = chain[: chain.index("TIER3-AUTO") + 1]
                leaf = ""
            return {
                **guard,
                "tier3_now": "",
                "final_chain": chain,
                "final_leaf": leaf,
            }

        members = [str(name) for name in expected_group_members]
        previous_pick = str(previous_route_guard.get("tier3_now") or "")
        if (
            str(previous_route_guard.get("tier3_fixed") or "")
            or str(current_route_guard.get("tier3_fixed") or "")
            or not previous_pick
            or builtin_terminal_kind(previous_pick)
            or previous_pick not in members
            or without_native_pick(current_route_guard)
            != without_native_pick(previous_route_guard)
        ):
            return current_route_guard, proxies_payload
        stop_event = getattr(self, "stop_event", None)
        settle_until = time.monotonic() + _TIER3_PROVIDER_ROUTE_SETTLE_SECONDS

        def remaining() -> float:
            value = settle_until - time.monotonic()
            if deadline_monotonic is not None:
                value = min(
                    value,
                    float(deadline_monotonic)
                    - self._runtime_recovery_now()
                    - _TIER3_PROVIDER_ROUTE_SETTLE_RESERVE_SECONDS,
                )
            return value

        delays = iter((0.05, 0.10, 0.15))
        while remaining() > 0.05:
            delay = min(next(delays, 0.25), remaining())
            if stop_event is not None:
                if stop_event.wait(delay):
                    break
            else:
                time.sleep(delay)
            budget = remaining()
            if budget <= 0.05:
                break
            try:
                payload = self.mihomo_proxies(timeout_seconds=min(0.75, budget))
            except Exception:
                break
            entries = payload.get("proxies") if isinstance(payload, dict) else None
            group = entries.get("TIER3-AUTO") if isinstance(entries, dict) else None
            observed_members = [
                str(name)
                for name in (
                    group.get("all", []) if isinstance(group, dict) else []
                )
            ]
            if observed_members != members:
                break
            settled_guard = self._tier3_provider_route_guard({"proxies": payload})
            if settled_guard == previous_route_guard:
                return settled_guard, payload
        return current_route_guard, proxies_payload

    def _rollback_tier3_provider_transaction(
        self,
        *,
        provider_path: Path,
        provider_name: str,
        previous_exists: bool,
        previous_bytes: bytes,
        previous_provider_members: tuple[str, ...],
        previous_group_members: tuple[str, ...],
        client: MihomoAPIClient,
        previous_route_guard: dict[str, Any] | None = None,
        deadline_monotonic: float | None = None,
    ) -> tuple[bool, str]:
        """Restore both file and controller state, then prove the rollback."""

        if not previous_exists or not previous_provider_members:
            return False, "no previously verified provider file is available"
        try:
            atomic_replace_if_changed(provider_path, previous_bytes)
            client.update_proxy_provider(
                provider_name,
                timeout=self._runtime_provider_timeout(
                    deadline_monotonic,
                    cap=1.5,
                ),
            )
            provider_readback = client.proxy_provider(
                provider_name,
                timeout=self._runtime_provider_timeout(
                    deadline_monotonic,
                    cap=0.75,
                ),
            )
            validation = validate_proxy_provider_readback(
                provider_readback,
                provider_name=provider_name,
                expected_proxy_names=previous_provider_members,
            )
            if not validation.valid:
                return False, f"provider rollback readback mismatch: {validation.reason}"
            proxies_payload = self.mihomo_proxies(
                timeout_seconds=self._runtime_provider_timeout(
                    deadline_monotonic,
                    cap=0.75,
                )
            )
            entries = (
                proxies_payload.get("proxies")
                if isinstance(proxies_payload, dict)
                else None
            )
            group = entries.get("TIER3-AUTO") if isinstance(entries, dict) else None
            observed_group = tuple(
                str(name)
                for name in (
                    group.get("all", []) if isinstance(group, dict) else []
                )
            )
            if observed_group != tuple(previous_group_members):
                return False, "TIER3-AUTO rollback membership readback mismatch"
            if isinstance(previous_route_guard, dict) and previous_route_guard:
                rollback_route_guard = self._tier3_provider_route_guard(
                    {"proxies": proxies_payload}
                )
                if rollback_route_guard != previous_route_guard:
                    # The restoring PUT resets member health exactly like the
                    # rejected one; judge the pick Mihomo re-settles on.
                    rollback_route_guard, _settled_payload = (
                        self._settle_unfixed_tier3_provider_pick(
                            previous_route_guard,
                            rollback_route_guard,
                            proxies_payload,
                            expected_group_members=previous_group_members,
                            deadline_monotonic=deadline_monotonic,
                        )
                    )
                if rollback_route_guard != previous_route_guard:
                    return False, "provider rollback route readback mismatch"
        except Exception as exc:
            return False, f"provider rollback verification failed: {exc}"
        return True, "provider file and Core membership restored"

    def _runtime_route_depends_on_tier3_provider(self) -> bool:
        snapshot, snapshot_payload = self._runtime_route_snapshot_state()
        if snapshot is None or not isinstance(snapshot_payload, dict):
            return False
        proxies_payload = snapshot_payload.get("proxies")
        route = inspect_runtime_route(proxies_payload, start="FINAL-EXIT")
        chain = tuple(str(item) for item in route.get("selected_chain", []) or [])
        if "TIER3-AUTO" in chain:
            return True
        leaf = str(route.get("leaf_proxy") or "")
        proxy_map = snapshot_payload.get("proxy_map")
        leaf_info = proxy_map.get(leaf) if isinstance(proxy_map, dict) else None
        proxy = leaf_info.get("proxy") if isinstance(leaf_info, dict) else None
        dialer_group = str(proxy.get("dialer-proxy") or "") if isinstance(proxy, dict) else ""
        if not dialer_group:
            return False
        underlay = inspect_runtime_route(proxies_payload, start=dialer_group)
        underlay_chain = tuple(
            str(item) for item in underlay.get("selected_chain", []) or []
        )
        return "TIER3-AUTO" in underlay_chain

    def _handle_unknown_tier3_provider_state(self, reason: str) -> None:
        """Revoke stale controller attribution without changing data plane.

        A lost provider PUT/readback is a three-state control-plane outcome:
        Core may still own the previous provider or may already own the new
        one.  It is neither proof of a WAN failure nor authority to replace a
        still-serving FINAL-EXIT with REJECT.  The old implementation entered
        facility hold and then selected REJECT; provider repair was blocked by
        that hold and the hold itself required a 204 through REJECT to clear,
        forming a permanent self-lock.
        """

        # A repeated report for the same already-invalidated authority is not
        # a new provider incident.  Do not advance route epoch or enqueue
        # another controller read when no causal input changed.
        current_authority_key = self._tier3_standby_activation_key()
        route_lock = getattr(self, "_runtime_route_snapshot_lock", None)
        with route_lock if route_lock is not None else nullcontext():
            already_invalidated = bool(
                getattr(self, "_runtime_route_snapshot", None) is None
                and getattr(self, "_runtime_route_snapshot_payload", None) is None
            )
        if (
            already_invalidated
            and getattr(self, "_runtime_unknown_provider_refresh_key", None)
            == current_authority_key
        ):
            return

        # Decide whether traffic is already admitted before revoking the
        # stale controller attribution.  Clearing the snapshot first can make
        # an otherwise healthy non-Gateway route look unowned and incorrectly
        # downgrade the user-visible connection.
        non_gateway_serving = self._runtime_non_gateway_serving_active()
        transition_lock = getattr(self, "_core_transition_lock", None)
        route_lock = getattr(self, "_runtime_route_snapshot_lock", None)
        with transition_lock if transition_lock is not None else nullcontext():
            if route_lock is not None:
                with route_lock:
                    self._runtime_route_epoch = int(
                        getattr(self, "_runtime_route_epoch", 0) or 0
                    ) + 1
                    self._node_judgement_arm_epoch("handle_unknown_tier3_provider_state")
                    self._mark_runtime_route_attribution_barrier_locked()
                    self._runtime_route_snapshot = None
                    self._runtime_route_snapshot_payload = None
                    self._runtime_core_inventory_snapshot = None
                    self._runtime_route_selection_signature = ()
                    self._runtime_confirmed_fail_closed_snapshot_key = None
            coordinator = getattr(self, "_runtime_egress_coordinator", None)
            set_snapshot = getattr(coordinator, "set_current_snapshot", None)
            if callable(set_snapshot):
                set_snapshot(None)

        # Keep the last physical route and every established connection in
        # place. A non-Gateway runtime remains SERVING; only its automatic
        # fallback arm is revoked until a materially new controller snapshot
        # arrives. A fixed Gateway retains the strict hold semantics.
        authority_key = self._tier3_standby_activation_key()
        self._record_tier3_controller_hold(
            "Bastion provider inventory readback is pending",
            authority_key=authority_key,
        )
        if non_gateway_serving:
            self._publish_non_gateway_serving(
                "Automatic switching is waiting for route ownership"
            )
        else:
            set_readiness = getattr(
                self,
                "_set_effective_egress_readiness_state",
                None,
            )
            if callable(set_readiness):
                set_readiness(
                    None,
                    "Bastion provider inventory readback is pending",
                )
        queue_snapshot = getattr(
            self,
            "_queue_runtime_route_snapshot_refresh",
            None,
        )
        previous_refresh_key = getattr(
            self,
            "_runtime_unknown_provider_refresh_key",
            None,
        )
        refresh_needed = previous_refresh_key != authority_key
        if refresh_needed:
            self._runtime_unknown_provider_refresh_key = authority_key
        if callable(queue_snapshot) and refresh_needed:
            queue_snapshot()
        if not non_gateway_serving:
            queue_revalidation = getattr(
                self,
                "_queue_egress_revalidation",
                None,
            )
            if callable(queue_revalidation):
                queue_revalidation("incremental")
        logger = getattr(self, "logger", None)
        if logger is not None:
            log_raw_diagnostic(
                logger,
                "warning",
                "Tier3B provider ownership is indeterminate; preserving the last "
                "physical route while controller readback is rebuilt (%s)",
                str(reason or "unknown provider state"),
            )

    def _tier3_verified_provider_writes_enabled(self) -> bool:
        # Latched at runtime start: reload_config swaps self.config without a
        # Core config load, and Tier3 naming and the provider lanes must keep
        # matching what the loaded Core was rendered with.
        latched = getattr(self, "_tier3_verified_provider_writes_latched", None)
        if latched is not None:
            return bool(latched)
        return self._tier3_verified_provider_writes_configured()

    def _tier3_verified_provider_writes_configured(self) -> bool:
        try:
            return verified_tier3_provider_writes(self.config)
        except Exception:
            return False

    def _tier3_verified_lane_open(self) -> bool:
        """Whether ordinary online provider writes use the verified lane.

        Only after this Core generation completed its initial activation
        (READY once): before that, startup admission owns the provider and
        the append-only standby lane stays as it was.  Losing READY later
        (an unknown outcome, a capture loss) does not close the lane: writes
        that keep the live pick first are safe whatever the readiness.
        """

        if not self._tier3_verified_provider_writes_enabled():
            return False
        lifecycle_lock = getattr(self, "_core_lifecycle_lock", None)
        with lifecycle_lock if lifecycle_lock is not None else nullcontext():
            core_generation = int(getattr(self, "_core_generation", 0) or 0)
        activated = int(getattr(self, "_runtime_initial_activation_generation", -1) or -1)
        return core_generation > 0 and activated == core_generation

    def _tier3_auto_contract(self, proxies_payload: Any) -> tuple[str, str]:
        """TIER3-AUTO's own test URL and expected status, exactly as loaded."""

        group = mihomo_proxies_entries(proxies_payload).get("TIER3-AUTO")
        if not isinstance(group, dict):
            return "", ""
        url = str(group.get("testUrl") or group.get("test-url") or group.get("url") or "")
        expected = str(group.get("expectedStatus") or group.get("expected-status") or "")
        return url, ("" if expected == "*" else expected)

    def _observe_tier3_member_verdicts(self, proxies_payload: Any, test_url: str) -> int:
        """Fold Mihomo's own contract verdicts for TIER3-AUTO members into the ledger."""

        if not test_url:
            return 0
        entries = mihomo_proxies_entries(proxies_payload)
        group = entries.get("TIER3-AUTO")
        members = group.get("all") if isinstance(group, dict) else None
        if not isinstance(members, list):
            return 0
        provider_like = {
            "proxies": [
                {**entries[name], "name": str(name)}
                for name in members
                if isinstance(entries.get(name), dict) and not builtin_terminal_kind(str(name))
            ]
        }
        return self._tier3_health_ledger.observe_payload(
            provider_like, test_url, lambda name: name
        )

    def _overlay_tier3_route_payload(self, proxies_payload: Any) -> Any:
        """/proxies payload with ledger verdicts in TIER3-AUTO members that have none.

        For counting and truth consumers only (route view, growth and fix-1
        gates, successors, lease pin checks): a rebuilt member reads
        alive-by-default in Mihomo, which is what native-pick predictors must
        keep seeing, so they read the raw payload.
        """

        if not self._tier3_verified_provider_writes_enabled():
            return proxies_payload
        test_url, _expected = self._tier3_auto_contract(proxies_payload)
        if not test_url:
            return proxies_payload
        wrapper = isinstance(proxies_payload, dict) and isinstance(proxies_payload.get("proxies"), dict)
        entries = mihomo_proxies_entries(proxies_payload)
        group = entries.get("TIER3-AUTO")
        members = group.get("all") if isinstance(group, dict) else None
        if not isinstance(members, list):
            return proxies_payload
        provider_like = {
            "proxies": [
                {**entries[name], "name": str(name)}
                for name in members
                if isinstance(entries.get(name), dict) and not builtin_terminal_kind(str(name))
            ]
        }
        ledger = self._tier3_health_ledger
        patched = tier3_overlay_provider_payload(provider_like, test_url, ledger.entry)
        if patched is provider_like:
            return proxies_payload
        new_entries = dict(entries)
        for member in patched.get("proxies", []):
            name = str(member.get("name") or "")
            if name in new_entries:
                new_entries[name] = {**entries[name], "extra": member.get("extra")}
        if wrapper:
            return {**proxies_payload, "proxies": new_entries}
        return new_entries

    def _tier3_provider_identity_is_current(self, binding: dict[str, Any] | None) -> bool:
        """The Core-identity half of the provider mutation CAS.

        A verified write commits whenever the same Core process, generation,
        phase and loaded contract still own the provider: pool, route-epoch,
        network, facility and selector drift do not undo a load that was
        proven by readback (the publication is left to a fresh refresh).
        """

        if not isinstance(binding, dict) or self.stop_event.is_set():
            return False
        runner = self.core_runner
        if runner is None or not runner.is_running():
            return False
        try:
            status = runner.status()
        except Exception:
            return False
        if (
            int(status.get("pid") or 0) != int(binding.get("pid") or 0)
            or int(status.get("process_generation") or 0)
            != int(binding.get("process_generation") or 0)
        ):
            return False
        with self._core_lifecycle_lock:
            if (
                int(self._core_generation) != int(binding.get("core_generation") or 0)
                or str(self._core_runtime_phase or "") != str(binding.get("phase") or "")
            ):
                return False
        with self._runtime_route_snapshot_lock:
            contract = self._runtime_loaded_export_contract
            if not isinstance(contract, dict):
                return False
            expected_revision = int(binding.get("contract_revision") or 0)
            return not (
                str(contract.get("semantic_digest") or "")
                != str(binding.get("semantic_digest") or "")
                or (
                    expected_revision > 0
                    and int(contract.get("revision") or 0) != expected_revision
                )
                or (
                    expected_revision <= 0
                    and id(contract) != int(binding.get("contract_identity") or 0)
                )
            )

    @staticmethod
    def _tier3_provider_core_identity(binding: dict[str, Any]) -> tuple[int, int, int]:
        """The Core a provider binding belongs to: pid, process and Core generation."""

        return (
            int(binding.get("pid") or 0),
            int(binding.get("process_generation") or 0),
            int(binding.get("core_generation") or 0),
        )

    def _commit_tier3_provider_contract_only(
        self,
        contract: dict[str, Any],
        binding: dict[str, Any],
        *,
        preserve_route_authority: bool,
    ) -> bool:
        """Commit a proven provider load whose route publication drifted.

        The contract (membership, proxy map, digest, revision) becomes the
        loaded one under the identity CAS; the route snapshot is not touched
        and is republished by the next refresh, which owns the drifted epoch.
        """

        manager = getattr(self, "manager", None)
        manager_lock = getattr(manager, "lock", None) if manager is not None else None
        with manager_lock if manager_lock is not None else nullcontext():
            with self._runtime_route_snapshot_lock:
                current = self._runtime_loaded_export_contract
                expected_revision = int(binding.get("contract_revision") or 0)
                if not isinstance(current, dict) or (
                    str(current.get("semantic_digest") or "")
                    != str(binding.get("semantic_digest") or "")
                ) or (
                    expected_revision > 0
                    and int(current.get("revision") or 0) != expected_revision
                ):
                    return False
                self._runtime_loaded_export_revision = int(
                    getattr(self, "_runtime_loaded_export_revision", 0) or 0
                ) + 1
                committed = {
                    **copy.deepcopy(contract),
                    "loaded_at_monotonic": time.monotonic(),
                    "revision": int(self._runtime_loaded_export_revision),
                }
                if preserve_route_authority:
                    committed["route_authority_semantic_digest"] = str(
                        binding.get("route_authority_semantic_digest") or ""
                    )
                self._runtime_loaded_export_contract = committed
                self._runtime_pending_export_contract = None
        return True

    def _tier3_pick_first_projection(
        self,
        projection: Tier3CoreProviderProjection,
    ) -> Tier3CoreProviderProjection:
        """Order a full-load projection with the published pick first.

        Uses the last published route snapshot (no controller call: full
        loads render under their own locks).  A stale pick is no worse than
        today's loaded-first order, and the startup check re-tests it at once.
        """

        try:
            _snapshot, snapshot_payload = self._runtime_route_snapshot_state()
            route_payload = (
                snapshot_payload.get("proxies") if isinstance(snapshot_payload, dict) else None
            )
            entries = mihomo_proxies_entries(route_payload)
            group = entries.get("TIER3-AUTO")
            names = [name for name in projection.proxy_names if not builtin_terminal_kind(name)]
            if not isinstance(group, dict) or not names:
                return projection
            fixed = str(group.get("fixed") or "")
            pick = fixed if fixed in names else str(group.get("now") or "")
            test_url, _expected = self._tier3_auto_contract(route_payload)
            pick_alive = pick in names and (
                not test_url or node_judgement_member_alive(entries.get(pick), test_url)
            )
            ledger = self._tier3_health_ledger
            ordered = order_tier3_members(
                names,
                names,
                pick=pick if pick_alive else None,
                pick_alive=pick_alive,
                state_of=ledger.state,
                dead_settled=ledger.dead_settled,
                always=True,
            )
            terminal = [name for name in projection.proxy_names if builtin_terminal_kind(name)]
            return reorder_tier3b_projection(projection, [*ordered, *terminal])
        except Exception:
            log_raw_diagnostic(
                self.logger,
                "debug",
                "Pick-first ordering of a full Tier3B load was skipped",
                exc_info=True,
            )
            return projection

    def _tier3_pin_owner(self, group: str = "TIER3-AUTO") -> str:
        """Who owns a pin on ``group`` in this process ('' when nobody does).

        A user pick (selector intent), the incident mutation lease, or a live
        route-lease clock (a Core restart inside this run keeps its clock).
        Anything else on the group is a pin Mihomo restored from cache.db.
        """

        counters = getattr(self, "_route_lease_counters", None)
        user_groups = counters.get("_user_groups") if isinstance(counters, dict) else None
        if isinstance(user_groups, set) and {"*", group} & user_groups:
            return "user"
        mutation_lease = getattr(self, "_runtime_route_mutation_lease", None)
        if isinstance(mutation_lease, dict) and str(mutation_lease.get("group") or "") == group:
            return "mutation_lease"
        clocks = getattr(self, "_route_lease_clocks", None)
        clock = clocks.get(group) if isinstance(clocks, dict) else None
        if clock is not None and bool(getattr(clock, "live", False)):
            return "route_lease"
        return ""

    def _tier3_provider_member_tester(
        self,
        client: MihomoAPIClient,
        provider_name: str,
        test_url: str,
        expected_status: str,
    ) -> Callable[[str], None]:
        expected: str | None = expected_status or None

        def run(name: str) -> None:
            try:
                client.provider_member_healthcheck(
                    provider_name,
                    name,
                    url=test_url,
                    timeout_ms=_TIER3_PROVIDER_VERIFY_TIMEOUT_MS,
                    expected_status=expected,
                )
            except MihomoDelayTestFailed:
                return  # a negative verdict; it is read back from extra[url]
            except MihomoAPIError as exc:
                if "HTTP 404" in str(exc):
                    return  # rebuilt away by a later write: reads as orphaned
                raise

        return run

    def _update_running_tier3_core_provider_verified(
        self,
        *,
        marker: tuple[Any, ...] | None,
        projection: Tier3CoreProviderProjection,
        rendered_proxy_map: dict[str, Any],
        loaded_contract: dict[str, Any],
        loaded_main_payload: str,
        loaded_main_digest: str,
        direct_members: list[str],
        runtime_config_path: Path,
        provider_path: Path,
        automatic_lease: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Verified Tier3B provider write: single-provider parity (11-02).

        Any byte change of the provider rebuilds every member alive-by-default
        and an unfixed fallback then serves its first member, while Mihomo's
        own post-write test may be skipped.  So:

        * a stale pin is cleared before the write, never after;
        * the live pick goes first and the rest follow the health ledger, so
          the rebuild keeps serving it (no first-member precondition);
        * the write is proven by readback, never undone after a transport
          failure, and restored only after a real parse rejection;
        * a write that must move the pick (all dead, empty group, kicked
          pick past its grace) verifies the new pick before committing;
        * the commit CAS is the Core identity: pool, epoch and selector drift
          commit the proven contract and leave publication to a refresh.

        Members are then tested explicitly outside every lock
        (``_verify_tier3_provider_after_write``).
        """

        client = self._require_api_client()
        provider_name = projection.provider_name
        loaded_proxy_map = (
            loaded_contract.get("proxy_map")
            if isinstance(loaded_contract.get("proxy_map"), dict)
            else {}
        )

        def deferred(reason: str, **extra: Any) -> dict[str, Any]:
            return {"updated": False, "deferred": True, "verified_write": True, "reason": reason, **extra}

        judgement_state = getattr(self, "_node_judgement_state", None)
        judge = getattr(judgement_state(), "judge", None) if callable(judgement_state) else None
        if judge is not None and (judge.judging() or judge.ladder_in_flight()):
            # Re-checked under the Core lock with the busy flag already up: a
            # judgement admitted before the flag owns the route until it ends.
            return deferred("a node judgement owns the Core route")

        binding = self._tier3_provider_mutation_binding(None)
        if binding is None:
            return deferred("Core provider mutation binding is unavailable")
        try:
            loaded_readback = client.proxy_provider(provider_name, timeout=0.75)
            loaded_members = tuple(
                str(item.get("name") or "")
                for item in (loaded_readback.get("proxies") or [])
                if isinstance(item, dict) and str(item.get("name") or "")
            )
        except Exception as exc:
            return deferred(f"Core-loaded provider membership is unavailable: {exc}")
        loaded_group_members = [*direct_members, *loaded_members]
        guard = binding.get("route_guard") if isinstance(binding.get("route_guard"), dict) else {}
        fixed = str(guard.get("tier3_fixed") or "")
        if fixed and fixed not in loaded_group_members:
            # A stale pin serves proxies[0] with no alive check, and a later
            # admission under that name would re-attach to it untested.  The
            # DELETE persists the clear to cache.db.
            try:
                client.unfix_proxy("TIER3-AUTO", timeout=1.5)
            except Exception as exc:
                return deferred(f"stale TIER3-AUTO pin could not be cleared: {exc}")
            self.logger.info("Bastion Layer cleared a stale TIER3-AUTO pin before a provider write")
            binding = self._tier3_provider_mutation_binding(None)
            if binding is None:
                return deferred("Core provider mutation binding is unavailable")
            guard = binding.get("route_guard") if isinstance(binding.get("route_guard"), dict) else {}
            fixed = str(guard.get("tier3_fixed") or "")
        # Membership truth comes from the controller, not the pool marker.
        binding.pop("tier3_pool_marker", None)
        binding.pop("tier3_pool_revision", None)
        snapshot, snapshot_payload = self._runtime_route_snapshot_state()
        route_payload = (
            snapshot_payload.get("proxies") if isinstance(snapshot_payload, dict) else None
        )
        test_url, expected_status = self._tier3_auto_contract(route_payload)
        if not test_url:
            return deferred("TIER3-AUTO test contract is unavailable")
        self._observe_tier3_member_verdicts(route_payload, test_url)
        entries = mihomo_proxies_entries(route_payload)
        now_name = str(guard.get("tier3_now") or "")
        pick = fixed if fixed and fixed in loaded_members else now_name
        if not pick or builtin_terminal_kind(pick) or pick not in loaded_members:
            pick = ""
        pick_alive = bool(pick) and node_judgement_member_alive(entries.get(pick), test_url)

        ledger = self._tier3_health_ledger
        candidates = [name for name in projection.proxy_names if not builtin_terminal_kind(name)]
        loaded_managed = [name for name in loaded_members if not builtin_terminal_kind(name)]
        # A pin someone in this process owns (a user pick, a lease) keeps its
        # member first whatever its health or export: a pinned member is never
        # removed (Mihomo itself moves off a dead pin to the next alive one).
        pin_owner = self._tier3_pin_owner("TIER3-AUTO") if fixed and pick == fixed else ""
        keep_pick = bool(pick) and (pick_alive or bool(pin_owner))
        kicked_pick = keep_pick and pick not in set(candidates)
        now_mono = time.monotonic()
        self._tier3_kicked_pick_since = {
            name: since
            for name, since in self._tier3_kicked_pick_since.items()
            if name in loaded_managed and name not in candidates
        }
        if kicked_pick:
            since = self._tier3_kicked_pick_since.setdefault(pick, now_mono)
            loaded_info = loaded_proxy_map.get(pick)
            pick_proxy = loaded_info.get("proxy") if isinstance(loaded_info, dict) else None
            if pin_owner and not isinstance(pick_proxy, dict):
                return deferred("Tier3B provider projection would remove the pinned TIER3-AUTO member")
            if not pin_owner and (
                now_mono - since >= _TIER3_VERIFIED_KICKED_PICK_GRACE_SECONDS
                or not isinstance(pick_proxy, dict)
            ):
                # The Manager removed the serving member and traffic did not
                # move off it within the grace: move it to a verified member.
                keep_pick = False
            else:
                projection = extend_tier3b_projection(projection, [pick_proxy])
                rendered_proxy_map = {**rendered_proxy_map, pick: copy.deepcopy(loaded_info)}
                candidates.append(pick)
        ordered = order_tier3_members(
            candidates,
            loaded_managed,
            pick=pick if keep_pick else None,
            pick_alive=keep_pick,
            state_of=ledger.state,
            dead_settled=ledger.dead_settled,
        )
        if [name for name in projection.proxy_names if name not in set(ordered)]:
            return deferred("verified Tier3B provider order lost a projected member")
        projection = reorder_tier3b_projection(projection, ordered)

        def same_definition(name: str) -> bool:
            loaded_info = loaded_proxy_map.get(name)
            rendered_info = rendered_proxy_map.get(name)
            return (
                isinstance(loaded_info, dict)
                and isinstance(rendered_info, dict)
                and loaded_info.get("proxy") == rendered_info.get("proxy")
            )

        if tuple(projection.proxy_names) == tuple(loaded_managed) and all(
            same_definition(name) for name in loaded_managed
        ):
            if not self._tier3_provider_identity_is_current(binding):
                return {**deferred("Core provider mutation binding changed before the semantic no-op could be accepted"), "stale": True}
            return {
                "updated": False,
                "unchanged": True,
                "reloaded": False,
                "verified_write": True,
                "semantic_digest": str(loaded_contract.get("semantic_digest") or ""),
                "reason": "Tier3B provider inventory is already loaded",
            }
        if self._tier3_rejected_provider_digests.get(projection.provider_digest) == (
            self._tier3_provider_core_identity(binding)
        ):
            return deferred("Mihomo already rejected this exact Tier3B provider projection", rejected=True)
        lease = automatic_lease if isinstance(automatic_lease, dict) else {}
        lease_target = str(lease.get("target_member") or "")
        if (
            str(lease.get("group") or "") == "TIER3-AUTO"
            and str(lease.get("mode") or "") == "fixed"
            and lease_target in set(loaded_members)
            and lease_target not in set(projection.provider_member_names)
        ):
            # Only a loaded target is protected: a stale one is not a member to
            # remove, and refusing on it froze the lane until the lease TTL.
            return deferred("Tier3B provider projection would remove the incident-owned fixed route target")
        expected_group_members = [*direct_members, *projection.provider_member_names]
        if len(expected_group_members) != len(set(expected_group_members)):
            return deferred("Core-loaded TIER3-AUTO and provider membership overlap")
        if fixed and fixed not in set(expected_group_members):
            # An unowned pin on a member this write removes (a kicked pick
            # past its grace) would name a non-member after the rebuild, which
            # Mihomo serves as proxies[0] with no alive check: clear it first
            # (the DELETE persists the clear to cache.db).
            try:
                client.unfix_proxy("TIER3-AUTO", timeout=1.5)
            except Exception as exc:
                return deferred(f"TIER3-AUTO pin could not be cleared before its member is removed: {exc}")
            self.logger.info("Bastion Layer cleared the TIER3-AUTO pin of a member this write removes")
            binding = self._tier3_provider_mutation_binding(None)
            if binding is None:
                return deferred("Core provider mutation binding is unavailable")
            binding.pop("tier3_pool_marker", None)
            binding.pop("tier3_pool_revision", None)
            fixed = ""
        candidate_contract = self._runtime_export_contract_for_payload(
            loaded_main_payload,
            provider_payload=projection.provider_yaml,
            rendered_proxy_map=rendered_proxy_map,
        )
        candidate_contract["provider_projection"] = projection
        pick_preserving = bool(keep_pick) and bool(projection.proxy_names) and projection.proxy_names[0] == pick
        if not self._tier3_provider_identity_is_current(binding):
            return {**deferred("Core provider mutation binding changed before the provider file write"), "stale": True}

        self._tier3_provider_write_generation = int(self._tier3_provider_write_generation) + 1

        def activate() -> None:
            client.update_proxy_provider(provider_name, timeout=1.5)

        def readback() -> dict[str, Any]:
            return client.proxy_provider(provider_name, timeout=0.75)

        write = write_provider_file_verified(
            provider_path,
            projection.provider_yaml,
            provider_name=provider_name,
            expected_proxy_names=projection.provider_member_names,
            previous_proxy_names=loaded_members,
            activate=activate,
            readback=readback,
            # Mihomo answers 503 for any provider.Update() error; only a parse
            # error means it refused the bytes (a read error is retried).
            is_rejection=lambda exc: isinstance(exc, MihomoProviderUpdateRejected),
        )
        if write.rejected:
            # Remembered for this Core only: a restart or an upgrade parses
            # the bytes again.  Entries of older Cores are dropped here.
            core = self._tier3_provider_core_identity(binding)
            self._tier3_rejected_provider_digests = {
                digest: owner
                for digest, owner in self._tier3_rejected_provider_digests.items()
                if owner == core
            }
            self._tier3_rejected_provider_digests[projection.provider_digest] = core
            return deferred(str(write.error or "Mihomo rejected the Tier3B provider file"), rejected=True)
        if not write.applied:
            return {
                "updated": False,
                "unknown": True,
                "verified_write": True,
                "reason": str(write.error or "Tier3B provider load was not proven"),
            }
        try:
            proxies_payload = self.mihomo_proxies(timeout_seconds=0.75)
        except Exception as exc:
            return {"updated": False, "unknown": True, "verified_write": True,
                    "reason": f"TIER3-AUTO membership readback failed: {exc}"}
        group = mihomo_proxies_entries(proxies_payload).get("TIER3-AUTO")
        observed_members = [str(name) for name in (group.get("all", []) if isinstance(group, dict) else [])]
        if observed_members != expected_group_members:
            return {"updated": False, "unknown": True, "verified_write": True,
                    "reason": "TIER3-AUTO group membership did not exactly match the projected provider order"}

        if not pick_preserving:
            order = list(projection.proxy_names)

            def first_alive_settled(verdicts: dict[str, tuple[bool, float]]) -> bool:
                for name in order:
                    if name not in verdicts:
                        return False
                    if verdicts[name][0]:
                        return True
                return True

            pick_check = tier3_verify_provider_members(
                order,
                test_member=self._tier3_provider_member_tester(
                    client, provider_name, test_url, expected_status
                ),
                read_provider=lambda: client.proxy_provider(provider_name, timeout=0.75),
                test_url=test_url,
                started_wall=write.write_started_wall,
                deadline_monotonic=time.monotonic() + _TIER3_PROVIDER_PICK_VERIFY_SECONDS,
                stop_when=first_alive_settled,
            )
            if pick_check.provider_payload is not None:
                # Mihomo's own check also tests the terminal REJECT: never a member.
                ledger.observe_payload(
                    pick_check.provider_payload,
                    test_url,
                    lambda name: None if builtin_terminal_kind(name) else name,
                )
            try:
                proxies_payload = self.mihomo_proxies(timeout_seconds=0.75)
            except Exception as exc:
                return {"updated": False, "unknown": True, "verified_write": True,
                        "reason": f"TIER3-AUTO pick readback failed: {exc}"}

        contract = dict(candidate_contract)
        provider_validation = write.validation
        if provider_validation is not None:
            contract["provider_member_digest"] = str(provider_validation.observed_member_digest or "")
            contract["provider_controller_version"] = (
                str(provider_validation.observed_version)
                if provider_validation.observed_version is not None
                else None
            )
            contract["provider_verification_basis"] = str(provider_validation.verification_basis or "")
        if loaded_main_digest:
            contract["main_semantic_digest"] = loaded_main_digest
            contract["semantic_digest"] = self._runtime_combined_semantic_digest(
                loaded_main_digest,
                str(contract.get("provider_semantic_digest") or ""),
            )
        committed_map = copy.deepcopy(loaded_proxy_map)
        for proxy_name in loaded_managed:
            committed_map.pop(str(proxy_name), None)
        candidate_map = contract.get("proxy_map")
        if isinstance(candidate_map, dict):
            for proxy_name in projection.proxy_names:
                if proxy_name in candidate_map:
                    committed_map[str(proxy_name)] = copy.deepcopy(candidate_map[proxy_name])
        contract["proxy_map"] = committed_map
        contract["runtime_config_path"] = str(runtime_config_path)
        provider_version = (
            str(provider_validation.observed_version)
            if provider_validation is not None and provider_validation.observed_version is not None
            else ""
        )
        contract_only = False
        committed_snapshot = None
        if self._tier3_provider_mutation_binding_is_current(binding):
            committed_snapshot = self._commit_tier3_provider_contract_from_readback(
                contract=contract,
                proxies_payload=proxies_payload,
                mutation_binding=binding,
                provider_version=provider_version,
                preserve_route_authority=pick_preserving,
            )
        if committed_snapshot is None:
            if not (
                self._tier3_provider_identity_is_current(binding)
                and self._commit_tier3_provider_contract_only(
                    contract, binding, preserve_route_authority=pick_preserving
                )
            ):
                return {
                    "updated": False,
                    "stale": True,
                    "deferred": True,
                    "verified_write": True,
                    "reason": "Core identity changed during the verified Tier3B provider write",
                }
            contract_only = True
        self._tier3_core_provider_last_projection = projection
        # A kicked member this write removed needs no timed re-run any more.
        self._tier3_kicked_pick_since = {
            name: since
            for name, since in self._tier3_kicked_pick_since.items()
            if name in set(projection.proxy_names)
        }
        if pick_preserving and fixed and fixed == pick and not self._tier3_pin_owner("TIER3-AUTO"):
            # A pin nobody in this process owns was restored from cache.db
            # (a crash leaves app pins behind; Mihomo's own in-memory clear of
            # a dead pin is never persisted).  The pinned member is first now,
            # so releasing it moves nothing, and the DELETE also clears
            # cache.db, so the next config load cannot re-apply it blind.
            try:
                client.unfix_proxy("TIER3-AUTO", timeout=1.0)
                self.logger.info("Bastion Layer released a restored TIER3-AUTO pin nobody owns")
            except Exception:
                log_raw_diagnostic(
                    self.logger,
                    "debug",
                    "Could not release a restored TIER3-AUTO pin",
                    exc_info=True,
                )
        self._wake_runtime_facility_rebaseline("Tier3B provider committed and read back")
        if not self._runtime_initial_activation_complete():
            self._reset_tier3_standby_activation_failure()
            self._queue_tier3_egress_activation()
        loaded_set = set(loaded_managed)
        return {
            "updated": True,
            "reloaded": False,
            "verified_write": True,
            "provider_name": provider_name,
            "member_count": len(projection.proxy_names),
            "provider_member_digest": str(
                provider_validation.observed_member_digest if provider_validation is not None else ""
            ),
            "provider_version": provider_version or None,
            "semantic_digest": str(contract.get("semantic_digest") or ""),
            "route_refresh_error": "",
            "marker": marker,
            "write_started_wall": float(write.write_started_wall),
            "member_names": list(projection.proxy_names),
            "new_names": [name for name in projection.proxy_names if name not in loaded_set],
            "removed_names": [name for name in loaded_managed if name not in set(projection.proxy_names)],
            "pick": pick if keep_pick else "",
            "pick_moving": not pick_preserving,
            "contract_only": contract_only,
            "test_url": test_url,
            "expected_status": expected_status,
        }

    def _verify_tier3_provider_after_write(self, result: dict[str, Any]) -> dict[str, Any]:
        """Phase B of a verified provider write: explicit member tests, no lock held.

        Mihomo's own post-write check often tests every refused or alive
        member within milliseconds; it may also be skipped entirely (1 s
        singledo, in-flight or dial-triggered check).  After a short settle
        this fills the gaps through the provider-scoped member endpoint,
        which bypasses the singledo.  A freshly verified pick is not retested.
        Never raises, never reports an unknown provider state: the write is
        already committed, and an interrupted round only leaves members on
        their carried ledger verdicts.  A later write or Core change orphans
        it (per-member history check), and the round stops.
        """

        summary: dict[str, Any] = {"outcome": "skipped"}
        names = [str(name) for name in result.get("member_names") or [] if str(name or "")]
        test_url = str(result.get("test_url") or "")
        expected_status = str(result.get("expected_status") or "")
        if not names or not test_url:
            return summary
        generation = int(self._tier3_provider_write_generation)
        lifecycle_lock = getattr(self, "_core_lifecycle_lock", None)
        with lifecycle_lock if lifecycle_lock is not None else nullcontext():
            core_generation = int(getattr(self, "_core_generation", 0) or 0)
        started_wall = float(result.get("write_started_wall") or time.time())
        floor = started_wall - TIER3_VERDICT_CLOCK_SKEW_SECONDS
        provider_name = str(result.get("provider_name") or self._tier3_core_provider_name)
        started = time.monotonic()

        def interrupted() -> str:
            if self.stop_event.is_set():
                return "stopping"
            if int(self._tier3_provider_write_generation) != generation:
                return "superseded"
            with lifecycle_lock if lifecycle_lock is not None else nullcontext():
                if int(getattr(self, "_core_generation", 0) or 0) != core_generation:
                    return "core_changed"
            if self._runtime_facility_hold_reason():
                return "facility_hold"
            return ""

        try:
            client = self._require_api_client()
            if self.stop_event.wait(_TIER3_PROVIDER_VERIFY_SETTLE_SECONDS):
                summary["outcome"] = "stopping"
                return summary
            reason = interrupted()
            if reason:
                summary["outcome"] = reason
                return summary
            payload = client.proxy_provider(provider_name, timeout=0.75)
            # Mihomo's own post-write check also tests the terminal REJECT:
            # only the projected members are counted and folded in.
            member_set = set(names)
            fresh = {
                name: verdict
                for name, verdict in tier3_member_verdicts(payload, test_url, newer_than_wall=floor).items()
                if name in member_set
            }
            ledger = self._tier3_health_ledger
            pick = str(result.get("pick") or "")
            skip: set[str] = set()
            pick_entry = ledger.entry(pick) if pick else None
            if pick and pick not in fresh and pick_entry is not None and (
                pick_entry.state == TIER3_MEMBER_ALIVE
                and time.time() - pick_entry.verdict_wall < _TIER3_PROVIDER_PICK_FRESH_SECONDS
            ):
                skip.add(pick)
            gaps = [
                name
                for name in tier3_verification_order(names, pick=pick or None, new=result.get("new_names") or ())
                if name not in fresh and name not in skip
            ]
            if pick and pick in gaps:
                # Test a stale-verdict pick last: its successors decide where
                # traffic goes if it fails, so they are proven first.
                gaps = [name for name in gaps if name != pick] + [pick]
            outcome = None
            if gaps:
                rounds = (len(gaps) + 15) // 16
                outcome = tier3_verify_provider_members(
                    gaps,
                    test_member=self._tier3_provider_member_tester(
                        client, provider_name, test_url, expected_status
                    ),
                    read_provider=lambda: client.proxy_provider(provider_name, timeout=0.75),
                    test_url=test_url,
                    started_wall=started_wall,
                    deadline_monotonic=time.monotonic() + rounds * (_TIER3_PROVIDER_VERIFY_TIMEOUT_MS / 1000.0) + 1.5,
                    stop_when=lambda _verdicts: bool(interrupted()),
                    read_every=0.5,
                )
                payload = outcome.provider_payload or payload
            verdicts = dict(fresh)
            if outcome is not None:
                verdicts.update(outcome.verdicts)
            any_alive = any(alive for alive, _stamp in verdicts.values())
            for name, (alive, stamp) in verdicts.items():
                # A round where nothing passed says more about the uplink than
                # about the members: keep their carried verdicts.
                if alive or any_alive:
                    ledger.observe(name, alive, stamp)
            reason = interrupted()
            untested = [name for name in names if name not in verdicts and name not in skip]
            summary = {
                "outcome": reason or ("complete" if not untested else "incomplete"),
                "members": len(names),
                "tested": len(verdicts),
                "alive": sum(1 for alive, _stamp in verdicts.values() if alive),
                "dead": sum(1 for alive, _stamp in verdicts.values() if not alive),
                "untested": len(untested),
                "pick_skipped": bool(skip),
                "ms": int((time.monotonic() - started) * 1000),
            }
            log_raw_diagnostic(
                self.logger,
                "info",
                "Bastion Layer provider verification (members=%d tested=%d alive=%d "
                "dead=%d untested=%d pick_skipped=%s ms=%d outcome=%s)",
                summary["members"],
                summary["tested"],
                summary["alive"],
                summary["dead"],
                summary["untested"],
                summary["pick_skipped"],
                summary["ms"],
                summary["outcome"],
            )
        except Exception as exc:
            summary = {"outcome": "error", "error": str(exc)[:200]}
            log_raw_diagnostic(
                self.logger,
                "info",
                "Bastion Layer provider verification was incomplete: %s",
                str(exc)[:200],
            )
        if not self.stop_event.is_set():
            try:
                refreshed = self._refresh_runtime_route_snapshot(timeout_seconds=0.75)
                if refreshed is not None:
                    self._try_arm_runtime_recovery()
                    self._maybe_carry_runtime_ready("provider_verify")
            except Exception:
                log_raw_diagnostic(
                    self.logger,
                    "debug",
                    "Route refresh after a verified provider write was skipped",
                    exc_info=True,
                )
        return summary

    def _update_running_tier3_core_provider(
        self,
        marker: tuple[Any, ...] | None,
        *,
        recovery_ticket: _RuntimeRecoveryTicket | None = None,
        deadline_monotonic: float | None = None,
        preserve_route_authority: bool = False,
        online_growth: bool = False,
    ) -> dict[str, Any]:
        """Serialize one provider mutation against recovery and Core reloads."""

        incident_rebase = isinstance(recovery_ticket, _RuntimeRecoveryTicket)
        if incident_rebase and not self._runtime_recovery_ticket_is_current(
            recovery_ticket,
            require_open=True,
            deadline_monotonic=deadline_monotonic,
        ):
            return {
                "updated": False,
                "stale": True,
                "reason": "incident-owned provider rebase lost its ticket",
            }

        reload_gate = getattr(self, "_runtime_reload_gate", None)
        if reload_gate is None:
            return {
                "updated": False,
                "deferred": True,
                "reason": "runtime reload gate is unavailable",
            }
        transaction_key = hashlib.sha256(
            repr(("tier3-provider", marker)).encode("utf-8")
        ).hexdigest()[:16]
        if self._tier3_verified_provider_writes_enabled():
            # One id per attempt: begin_recovery is re-entrant by id, so two
            # writers with the same pool marker used to share one lease and a
            # later commit then read as lost Core mutation authority.
            self._tier3_provider_write_attempts = (
                int(getattr(self, "_tier3_provider_write_attempts", 0) or 0) + 1
            )
            transaction_key = f"{transaction_key}-{self._tier3_provider_write_attempts}"
        recovery_lease = reload_gate.begin_recovery(
            f"tier3-provider:{transaction_key}"
        )
        if recovery_lease is None:
            return {
                "updated": False,
                "deferred": True,
                "reason": "another Core recovery or reload transaction is active",
            }
        result: dict[str, Any] | None = None
        lease_released = False
        try:
            with self._core_transition_lock:
                recovery_active = self._runtime_recovery_transaction_active()
                if recovery_active and (
                    not incident_rebase
                    or self._runtime_incident_provider_rebase_conflicts(
                        recovery_ticket
                    )
                ):
                    result = {
                        "updated": False,
                        "deferred": True,
                        "reason": "runtime egress recovery transaction is active",
                    }
                else:
                    result = self._update_running_tier3_core_provider_leased(
                        marker,
                        recovery_ticket=recovery_ticket,
                        deadline_monotonic=deadline_monotonic,
                        preserve_route_authority=preserve_route_authority,
                        **({"online_growth": True} if online_growth else {}),
                    )
        finally:
            if isinstance(result, dict) and result.get("updated"):
                settle_dynamic = getattr(
                    reload_gate,
                    "end_recovery_with_loaded_semantic_digest",
                    None,
                )
                if callable(settle_dynamic):
                    lease_released = bool(
                        settle_dynamic(
                            recovery_lease,
                            str(result.get("semantic_digest") or ""),
                        )
                    )
                else:
                    lease_released = bool(
                        reload_gate.end_recovery(recovery_lease)
                    )
                    if lease_released:
                        sync_if_idle = getattr(
                            reload_gate,
                            "set_loaded_semantic_digest_if_idle",
                            None,
                        )
                        if callable(sync_if_idle):
                            lease_released = bool(
                                sync_if_idle(
                                    str(result.get("semantic_digest") or "")
                                )
                            )
                        else:
                            reload_gate.set_loaded_semantic_digest(
                                str(result.get("semantic_digest") or "")
                            )
            else:
                lease_released = bool(reload_gate.end_recovery(recovery_lease))
        assert isinstance(result, dict)
        if result.get("verified_write"):
            if result.get("updated") and not lease_released:
                # A reload took the gate after the proven commit; it renders
                # and republishes its own contract.
                self._queue_runtime_route_snapshot_refresh()
                return {
                    **result,
                    "updated": False,
                    "stale": True,
                    "deferred": True,
                    "reason": "a Core reload took over after the verified Tier3B provider write",
                }
            if result.get("unknown"):
                # Neither membership was proven, but the data plane was not
                # touched beyond the write itself (no restore, no rollback):
                # re-read the route instead of revoking readiness.
                self._queue_runtime_route_snapshot_refresh()
            return result
        if result.get("updated"):
            if not lease_released:
                self._handle_unknown_tier3_provider_state(
                    "Tier3B provider commit lost its Core mutation lease"
                )
                return {
                    **result,
                    "updated": False,
                    "unknown": True,
                    "reason": "provider commit lost Core mutation authority",
                }
        elif result.get("unknown"):
            self._handle_unknown_tier3_provider_state(
                str(result.get("reason") or "Tier3B provider state is unknown")
            )
        return result

    def _update_running_tier3_core_provider_leased(
        self,
        marker: tuple[Any, ...] | None,
        *,
        recovery_ticket: _RuntimeRecoveryTicket | None = None,
        deadline_monotonic: float | None = None,
        preserve_route_authority: bool = False,
        online_growth: bool = False,
    ) -> dict[str, Any]:
        """Apply a committed Tier3B inventory without a Core config reload.

        ``online_growth`` is ordinary pool growth crossing the online cohort
        freeze.  It is restricted to an append-only projection applied while
        the unfixed TIER3-AUTO already selects its first member: the PUT's
        health reset then natively re-selects that same member, so no blind
        pick exists to settle or roll back.  Admissions that only extend the
        committed pool while the transaction runs do not invalidate it.
        """

        incident_rebase = isinstance(recovery_ticket, _RuntimeRecoveryTicket)
        if incident_rebase and not self._runtime_recovery_ticket_is_current(
            recovery_ticket,
            require_open=True,
            deadline_monotonic=deadline_monotonic,
        ):
            return {
                "updated": False,
                "stale": True,
                "reason": "incident-owned provider rebase lost its ticket",
            }

        if (
            self.stop_event.is_set()
            or self.core_runner is None
            or not self.core_runner.is_running()
        ):
            return {
                "updated": False,
                "reason": "Core is not available for provider update",
            }
        phase = self._current_core_runtime_phase()
        if phase not in {"formal_capture", "formal_no_capture"}:
            return {
                "updated": False,
                "reason": f"provider update is unavailable in Core phase {phase}",
            }
        recovery_active = self._runtime_recovery_transaction_active()
        if recovery_active and (
            not incident_rebase
            or self._runtime_incident_provider_rebase_conflicts(recovery_ticket)
        ):
            return {
                "updated": False,
                "deferred": True,
                "reason": "runtime recovery transaction is active",
            }
        # Incident rebases, the pre-READY standby lane and facility holds keep
        # their append-only provider lane; ordinary online writes are verified.
        verified_lane = bool(
            not incident_rebase
            and self._tier3_verified_lane_open()
            and not self._runtime_facility_hold_reason()
        )
        if verified_lane and not getattr(self, "_tier3_provider_write_busy", False):
            # The lane opened after the caller chose its lane (the caller
            # raises the write-in-progress flag on that lane only): the judges
            # would not see this write or its member tests.  Park; the retry
            # takes the verified lane with its flag.
            return {
                "updated": False,
                "deferred": True,
                "verified_write": True,
                "reason": "verified Tier3B provider write waits for its busy flag",
            }
        marker_owner = getattr(self.manager, "_tier3_enabled", None)
        if marker is not None and callable(marker_owner):
            current_pool_marker = self._tier3_core_sync_marker()
            if current_pool_marker != marker and not (
                online_growth
                and self._tier3_pool_marker_extends(current_pool_marker, marker)
            ):
                return {
                    "updated": False,
                    "stale": True,
                    "deferred": True,
                    "reason": "Tier3B pool changed before provider projection began",
                }

        rendered = self._render_mihomo_runtime_payload_base_with_provider(
            include_proxy_map=True,
        )
        if len(rendered) == 3:
            (
                _rendered_main_payload,
                projection,
                rendered_proxy_map,
            ) = rendered
        else:
            # Compatibility for narrow test/embedding shims that replace the
            # legacy two-value renderer.  The real renderer always returns an
            # immutable receipt on this production call path.
            _rendered_main_payload, projection = rendered
            rendered_proxy_map = self._runtime_proxy_name_map()
        if projection is None:
            return {
                "updated": False,
                "reason": "Tier3B provider has no routable members",
            }
        # A provider transaction is not authorized to change the main Core
        # graph.  In particular, the canonical renderer above always produces
        # the formal/capture document while the running Core may currently own
        # the capture-disabled form of that graph.  Build the candidate
        # contract from the exact main document accepted by this Core process,
        # and use the fresh render only as the source of provider members.
        with self._runtime_route_snapshot_lock:
            loaded_contract = copy.deepcopy(
                self._runtime_loaded_export_contract
                if isinstance(self._runtime_loaded_export_contract, dict)
                else {}
            )
        loaded_main_digest = str(
            loaded_contract.get("main_semantic_digest") or ""
        )
        runtime_config_path_text = str(
            loaded_contract.get("runtime_config_path") or ""
        ).strip()
        try:
            runtime_config_path = (
                Path(runtime_config_path_text)
                if runtime_config_path_text
                else self._runtime_config_path_for_client()
            )
            if not runtime_config_path.is_absolute():
                runtime_config_path = self._resolve_path(runtime_config_path)
            loaded_main_payload = runtime_config_path.read_text(encoding="utf-8")
        except (OSError, ValueError) as exc:
            return {
                "updated": False,
                "deferred": True,
                "reason": (
                    "Core-loaded main graph is unavailable for provider update: "
                    f"{exc}"
                ),
            }
        observed_loaded_main_digest = hashlib.sha256(
            loaded_main_payload.replace("\n", os.linesep).encode("utf-8")
        ).hexdigest()
        if (
            not loaded_main_digest
            or observed_loaded_main_digest != loaded_main_digest
        ):
            return {
                "updated": False,
                "stale": True,
                "deferred": True,
                "reason": (
                    "Runtime config file no longer matches the Core-loaded "
                    "main graph"
                ),
            }
        candidate_contract = self._runtime_export_contract_for_payload(
            loaded_main_payload,
            provider_payload=projection.provider_yaml,
            rendered_proxy_map=rendered_proxy_map,
        )
        candidate_contract["provider_projection"] = projection
        expected_group_members = list(projection.provider_member_names)
        try:
            candidate_document = yaml.safe_load(loaded_main_payload)
            if not isinstance(candidate_document, dict):
                raise ValueError("Core-loaded main graph is not a mapping")
            configured_providers = candidate_document.get("proxy-providers")
            configured_provider = (
                configured_providers.get(projection.provider_name)
                if isinstance(configured_providers, dict)
                else None
            )
            if not isinstance(configured_provider, dict):
                raise ValueError(
                    "Core-loaded main graph does not own the Tier3B provider"
                )
            configured_provider_path = str(
                configured_provider.get("path") or ""
            ).strip()
            configured_provider_type = str(
                configured_provider.get("type") or ""
            ).strip().casefold()
            if configured_provider_type != "file" or not configured_provider_path:
                raise ValueError(
                    "Core-loaded Tier3B provider is not a local file provider"
                )
            configured_path = Path(configured_provider_path)
            if not configured_path.is_absolute():
                work_dir = self._resolve_path(
                    mihomo_client_paths(self._client_config()).work_dir
                )
                configured_path = work_dir / configured_path
            if (
                configured_path.resolve()
                != self._tier3_core_provider_file_path().resolve()
            ):
                raise ValueError(
                    "Core-loaded Tier3B provider path does not match the "
                    "runtime provider file"
                )
            candidate_groups = (
                candidate_document.get("proxy-groups")
                if isinstance(candidate_document, dict)
                else None
            )
            candidate_group = next(
                (
                    item
                    for item in (candidate_groups or [])
                    if isinstance(item, dict)
                    and str(item.get("name") or "") == "TIER3-AUTO"
                ),
                None,
            )
            configured_use = (
                [str(item) for item in candidate_group.get("use", [])]
                if isinstance(candidate_group, dict)
                and isinstance(candidate_group.get("use"), list)
                else []
            )
            if projection.provider_name not in configured_use:
                raise ValueError(
                    "Core-loaded TIER3-AUTO does not consume the Tier3B provider"
                )
            direct_members = (
                [str(item) for item in candidate_group.get("proxies", [])]
                if isinstance(candidate_group, dict)
                and isinstance(candidate_group.get("proxies"), list)
                else []
            )
            expected_group_members = [
                *direct_members,
                *projection.provider_member_names,
            ]
            if len(expected_group_members) != len(set(expected_group_members)):
                raise ValueError(
                    "Core-loaded TIER3-AUTO and provider membership overlap"
                )
        except (OSError, TypeError, ValueError, yaml.YAMLError) as exc:
            return {
                "updated": False,
                "deferred": True,
                "reason": f"Core-loaded provider graph is invalid: {exc}",
            }
        failure_lock = getattr(self, "_runtime_failure_monitor_lock", None)
        if failure_lock is None:
            automatic_lease = dict(
                getattr(self, "_runtime_route_mutation_lease", None) or {}
            )
        else:
            with failure_lock:
                automatic_lease = dict(
                    getattr(self, "_runtime_route_mutation_lease", None) or {}
                )
        if (
            not verified_lane
            and str(automatic_lease.get("group") or "") == "TIER3-AUTO"
            and str(automatic_lease.get("mode") or "") == "fixed"
            and str(automatic_lease.get("target_member") or "")
            not in set(expected_group_members)
        ):
            return {
                "updated": False,
                "deferred": True,
                "reason": (
                    "Tier3B provider projection would remove the incident-owned "
                    "fixed route target"
                ),
            }
        candidate_main_digest = str(
            candidate_contract.get("main_semantic_digest") or ""
        )
        if (
            loaded_main_digest
            and candidate_main_digest
            and loaded_main_digest != candidate_main_digest
        ):
            return {
                "updated": False,
                "reason": (
                    "Tier3B provider update would also change the loaded Core "
                    "graph; a provider transaction cannot claim that mutation"
                ),
            }
        provider_path = self._tier3_core_provider_file_path()
        if verified_lane:
            # Membership truth is read from the controller there, so a provider
            # file that drifted from the contract (an unproven write, a reload
            # lane's fswatch load) is rewritten instead of wedging the lane.
            return self._update_running_tier3_core_provider_verified(
                marker=marker,
                projection=projection,
                rendered_proxy_map=dict(rendered_proxy_map or {}),
                loaded_contract=loaded_contract,
                loaded_main_payload=loaded_main_payload,
                loaded_main_digest=loaded_main_digest,
                direct_members=list(direct_members),
                runtime_config_path=runtime_config_path,
                provider_path=provider_path,
                automatic_lease=automatic_lease,
            )
        loaded_provider_digest = str(
            loaded_contract.get("provider_semantic_digest") or ""
        )
        try:
            loaded_provider_payload = provider_path.read_text(encoding="utf-8")
        except (OSError, ValueError) as exc:
            return {
                "updated": False,
                "deferred": True,
                "reason": (
                    "Core-loaded provider file is unavailable for update: "
                    f"{exc}"
                ),
            }
        observed_loaded_provider_digest = hashlib.sha256(
            loaded_provider_payload.replace("\n", os.linesep).encode("utf-8")
        ).hexdigest()
        if (
            not loaded_provider_digest
            or observed_loaded_provider_digest != loaded_provider_digest
        ):
            return {
                "updated": False,
                "stale": True,
                "deferred": True,
                "reason": (
                    "Runtime provider file no longer matches the Core-loaded "
                    "provider contract"
                ),
            }
        if self._tier3_verified_provider_writes_enabled():
            # Verified writes and full loads order the provider by the live
            # pick and health, not by the Manager's export order: judge these
            # lanes against the Core-loaded order (loaded members in place,
            # new ones appended), so an order difference alone never reads as
            # a rebase and growth stays append-only.
            loaded_order = [
                name
                for name in self._tier3_provider_member_names_from_bytes(
                    loaded_provider_payload.encode("utf-8")
                )
                if not builtin_terminal_kind(name)
            ]
            loaded_order_set = set(loaded_order)
            if loaded_order_set <= set(projection.proxy_names):
                reordered = reorder_tier3b_projection(
                    projection,
                    [
                        *loaded_order,
                        *(
                            name
                            for name in projection.proxy_names
                            if name not in loaded_order_set
                        ),
                    ],
                )
                if reordered is not projection:
                    projection = reordered
                    candidate_contract = self._runtime_export_contract_for_payload(
                        loaded_main_payload,
                        provider_payload=projection.provider_yaml,
                        rendered_proxy_map=rendered_proxy_map,
                    )
                    candidate_contract["provider_projection"] = projection
                    expected_group_members = [
                        *direct_members,
                        *projection.provider_member_names,
                    ]
        candidate_provider_digest = str(
            candidate_contract.get("provider_semantic_digest") or ""
        )
        mutation_binding: dict[str, Any] | None = None
        if (
            loaded_main_digest
            and candidate_main_digest == loaded_main_digest
            and loaded_provider_digest
            and candidate_provider_digest == loaded_provider_digest
        ):
            mutation_binding = (
                self._tier3_provider_mutation_binding(
                    marker,
                    recovery_ticket=recovery_ticket,
                    deadline_monotonic=deadline_monotonic,
                )
                if incident_rebase
                else self._tier3_provider_mutation_binding(
                    None if online_growth else marker
                )
            )
            if mutation_binding is None:
                return {
                    "updated": False,
                    "deferred": True,
                    "reason": "Core provider mutation binding is unavailable",
                }
            if online_growth:
                mutation_binding["pool_growth_tolerant"] = True
            if not self._tier3_provider_mutation_binding_is_current(
                mutation_binding
            ):
                return {
                    "updated": False,
                    "stale": True,
                    "deferred": True,
                    "reason": (
                        "Core provider mutation binding changed before the "
                        "semantic no-op could be accepted"
                    ),
                }
            return {
                "updated": False,
                "unchanged": True,
                "reloaded": False,
                "semantic_digest": str(
                    loaded_contract.get("semantic_digest") or ""
                ),
                "reason": "Tier3B provider inventory is already loaded",
            }
        # Mihomo v1.19.27's provider API exposes ordered member names but no
        # content digest/version.  A same-name proxy whose transport/secret
        # changed is therefore observationally indistinguishable from the old
        # object after a lost PUT response.  Do not publish such a candidate as
        # the exact Core-loaded proxy map.  New names and unchanged definitions
        # remain safe to update through the provider lane; a renamed/content-
        # addressed admission can be applied on the next durable snapshot.
        loaded_proxy_map_for_guard = (
            loaded_contract.get("proxy_map")
            if isinstance(loaded_contract.get("proxy_map"), dict)
            else {}
        )
        candidate_proxy_map_for_guard = (
            candidate_contract.get("proxy_map")
            if isinstance(candidate_contract.get("proxy_map"), dict)
            else {}
        )
        for proxy_name in projection.proxy_names:
            loaded_info = loaded_proxy_map_for_guard.get(str(proxy_name))
            candidate_info = candidate_proxy_map_for_guard.get(str(proxy_name))
            if not isinstance(loaded_info, dict) or not isinstance(candidate_info, dict):
                continue
            loaded_proxy = loaded_info.get("proxy")
            candidate_proxy = candidate_info.get("proxy")
            if (
                isinstance(loaded_proxy, dict)
                and isinstance(candidate_proxy, dict)
                and loaded_proxy != candidate_proxy
            ):
                return {
                    "updated": False,
                    "reason": (
                        "Tier3B provider member changed configuration without "
                        "a content-addressed Core name; names-only controller "
                        "readback cannot prove the new proxy semantics"
                    ),
                    "unverified_proxy_name": str(proxy_name),
                }
        mutation_binding = (
            self._tier3_provider_mutation_binding(
                marker,
                recovery_ticket=recovery_ticket,
                deadline_monotonic=deadline_monotonic,
            )
            if incident_rebase
            else self._tier3_provider_mutation_binding(
                None if online_growth else marker
            )
        )
        if mutation_binding is None:
            return {
                "updated": False,
                "deferred": True,
                "reason": "Core provider mutation binding is unavailable",
            }
        loaded_provider_members = self._tier3_provider_member_names_from_bytes(
            loaded_provider_payload.encode("utf-8")
        )
        candidate_provider_members = tuple(projection.provider_member_names)
        loaded_managed_members = tuple(
            name
            for name in loaded_provider_members
            if not builtin_terminal_kind(name)
        )
        candidate_managed_members = tuple(
            name
            for name in candidate_provider_members
            if not builtin_terminal_kind(name)
        )
        loaded_terminal_members = tuple(
            name
            for name in loaded_provider_members
            if builtin_terminal_kind(name)
        )
        candidate_terminal_members = tuple(
            name
            for name in candidate_provider_members
            if builtin_terminal_kind(name)
        )
        standby_append_only = bool(
            self._runtime_uses_early_single_coordinator()
            and phase == "formal_no_capture"
            and not self._runtime_initial_activation_was_completed()
        )
        append_only_growth = bool(
            loaded_terminal_members == candidate_terminal_members
            and len(candidate_managed_members) > len(loaded_managed_members)
            and candidate_managed_members[: len(loaded_managed_members)]
            == loaded_managed_members
        )
        if (incident_rebase or standby_append_only) and not append_only_growth:
            return {
                "updated": False,
                "deferred": True,
                "reason": (
                    "pre-READY provider mutation is restricted to one "
                    "append-only capacity expansion"
                    if standby_append_only
                    else "incident-owned provider rebase is restricted to one "
                    "append-only capacity expansion"
                ),
            }
        if online_growth:
            # The PUT rebuilds every member with fresh health, after which an
            # unfixed fallback natively serves its first member.  Growth
            # therefore needs that member to already be the current pick (the
            # binding's fresh controller read) behind an unchanged prefix, so
            # no blind pick is ever served and nothing has to settle.
            growth_guard = mutation_binding.get("route_guard")
            growth_guard = growth_guard if isinstance(growth_guard, dict) else {}
            first_member = next(
                (
                    str(name)
                    for name in expected_group_members
                    if not builtin_terminal_kind(name)
                ),
                "",
            )
            growth_wait = ""
            if not append_only_growth:
                growth_wait = "online growth waits for an append-only Tier3B projection"
            elif str(growth_guard.get("tier3_fixed") or ""):
                growth_wait = "online growth waits while TIER3-AUTO has a fixed selection"
            elif (
                not first_member
                or str(growth_guard.get("tier3_now") or "") != first_member
            ):
                growth_wait = (
                    "online growth waits until TIER3-AUTO selects its first member"
                )
            if growth_wait:
                return {
                    "updated": False,
                    "deferred": True,
                    "growth_wait": True,
                    "reason": growth_wait,
                }
            mutation_binding["pool_growth_tolerant"] = True
        if standby_append_only:
            # Preserve the exact selected route while publishing the larger
            # Core inventory.  Admission consumes the new inventory through a
            # successor lease; it is not cancelled in place.
            preserve_route_authority = True
            mutation_binding["ignore_route_selection"] = True
        elif append_only_growth and self._tier3_source_control_qualification_is_current():
            # Capacity growth does not invalidate an already verified leaf.
            # Keep the route proof, not the inventory digest; the strict
            # selection readback and all mutation CAS checks still apply.
            preserve_route_authority = True
        facility_hold_reason = self._runtime_facility_hold_reason()
        allow_facility_hold_append = bool(
            facility_hold_reason
            and not self._runtime_local_data_plane_blocked()
            and loaded_terminal_members == candidate_terminal_members
            and len(candidate_managed_members) > len(loaded_managed_members)
            and candidate_managed_members[: len(loaded_managed_members)]
            == loaded_managed_members
        )
        mutation_binding["allow_facility_hold_append"] = (
            allow_facility_hold_append
        )
        if facility_hold_reason and not allow_facility_hold_append:
            return {
                "updated": False,
                "deferred": True,
                "reason": "runtime facility hold is active",
            }
        previous_route_guard = mutation_binding.get("route_guard")
        if isinstance(previous_route_guard, dict):
            protected_members = {
                str(previous_route_guard.get("tier3_now") or ""),
                str(previous_route_guard.get("tier3_fixed") or ""),
            }
            protected_members.discard("")
            protected_members.discard("REJECT")
            missing_protected = sorted(
                protected_members.difference(expected_group_members)
            )
            if missing_protected:
                return {
                    "updated": False,
                    "deferred": True,
                    "reason": (
                        "Tier3B provider projection would remove the current "
                        "or fixed Core route member"
                    ),
                }
        if not self._tier3_provider_mutation_binding_is_current(
            mutation_binding
        ):
            return {
                "updated": False,
                "stale": True,
                "deferred": True,
                "reason": (
                    "Core provider mutation binding changed before the "
                    "provider file write"
                ),
            }
        try:
            previous_bytes = provider_path.read_bytes()
            previous_exists = True
        except FileNotFoundError:
            previous_bytes = b""
            previous_exists = False
        previous_provider_members = self._tier3_provider_member_names_from_bytes(
            previous_bytes
        )
        previous_group_members = tuple(
            [*direct_members, *previous_provider_members]
        )
        client = self._require_api_client()

        def activate() -> None:
            client.update_proxy_provider(
                projection.provider_name,
                timeout=self._runtime_provider_timeout(
                    deadline_monotonic,
                    cap=1.5,
                ),
            )

        def readback() -> dict[str, Any]:
            return client.proxy_provider(
                projection.provider_name,
                timeout=self._runtime_provider_timeout(
                    deadline_monotonic,
                    cap=0.75,
                ),
            )

        transaction = replace_provider_file_transactionally(
            provider_path,
            projection.provider_yaml,
            provider_name=projection.provider_name,
            expected_proxy_names=projection.provider_member_names,
            activate=activate,
            readback=readback,
            rollback_activate=activate,
        )
        if not transaction.committed:
            rollback_verified, rollback_reason = (
                self._rollback_tier3_provider_transaction(
                    provider_path=provider_path,
                    provider_name=projection.provider_name,
                    previous_exists=previous_exists,
                    previous_bytes=previous_bytes,
                    previous_provider_members=previous_provider_members,
                    previous_group_members=previous_group_members,
                    client=client,
                    previous_route_guard=previous_route_guard,
                    deadline_monotonic=deadline_monotonic,
                )
            )
            return {
                "updated": False,
                "unknown": not rollback_verified,
                "rollback_verified": rollback_verified,
                "rollback_reason": rollback_reason,
                "provider_update": asdict(transaction),
                "reason": str(
                    transaction.error
                    or "Tier3B provider update was not committed"
                ),
            }

        membership_error = ""
        try:
            proxies_payload = self.mihomo_proxies(
                timeout_seconds=self._runtime_provider_timeout(
                    deadline_monotonic,
                    cap=0.75,
                )
            )
            entries = (
                proxies_payload.get("proxies")
                if isinstance(proxies_payload, dict)
                else None
            )
            group = entries.get("TIER3-AUTO") if isinstance(entries, dict) else None
            observed_members = [
                str(name)
                for name in (
                    group.get("all", []) if isinstance(group, dict) else []
                )
            ]
            if observed_members != expected_group_members:
                membership_error = (
                    "TIER3-AUTO group membership did not exactly match the "
                    "projected provider order"
                )
        except Exception as exc:
            membership_error = f"TIER3-AUTO membership readback failed: {exc}"
        if membership_error:
            rollback_verified, rollback_reason = (
                self._rollback_tier3_provider_transaction(
                    provider_path=provider_path,
                    provider_name=projection.provider_name,
                    previous_exists=previous_exists,
                    previous_bytes=previous_bytes,
                    previous_provider_members=previous_provider_members,
                    previous_group_members=previous_group_members,
                    client=client,
                    previous_route_guard=previous_route_guard,
                    deadline_monotonic=deadline_monotonic,
                )
            )
            return {
                "updated": False,
                "unknown": not rollback_verified,
                "rolled_back": rollback_verified,
                "rollback_verified": rollback_verified,
                "rollback_reason": rollback_reason,
                "provider_update": asdict(transaction),
                "reason": membership_error,
            }

        current_route_guard = self._tier3_provider_route_guard(
            {"proxies": proxies_payload}
        )
        if (
            isinstance(previous_route_guard, dict)
            and previous_route_guard
            and current_route_guard != previous_route_guard
            and not bool(mutation_binding.get("ignore_route_selection"))
        ):
            # The PUT itself resets provider member health; publish (and
            # judge) the pick Mihomo re-settles on, not that transient.
            current_route_guard, proxies_payload = (
                self._settle_unfixed_tier3_provider_pick(
                    previous_route_guard,
                    current_route_guard,
                    proxies_payload,
                    expected_group_members=expected_group_members,
                    deadline_monotonic=deadline_monotonic,
                )
            )
        if (
            isinstance(previous_route_guard, dict)
            and previous_route_guard
            and current_route_guard != previous_route_guard
            and not bool(mutation_binding.get("ignore_route_selection"))
        ):
            rollback_verified, rollback_reason = (
                self._rollback_tier3_provider_transaction(
                    provider_path=provider_path,
                    provider_name=projection.provider_name,
                    previous_exists=previous_exists,
                    previous_bytes=previous_bytes,
                    previous_provider_members=previous_provider_members,
                    previous_group_members=previous_group_members,
                    client=client,
                    previous_route_guard=previous_route_guard,
                    deadline_monotonic=deadline_monotonic,
                )
            )
            return {
                "updated": False,
                "unknown": not rollback_verified,
                "rolled_back": rollback_verified,
                "rollback_verified": rollback_verified,
                "rollback_reason": rollback_reason,
                "provider_update": asdict(transaction),
                "reason": (
                    "Tier3B provider update changed fixed/selected route state"
                ),
            }

        if not self._tier3_provider_mutation_binding_is_current(mutation_binding):
            rollback_verified, rollback_reason = (
                self._rollback_tier3_provider_transaction(
                    provider_path=provider_path,
                    provider_name=projection.provider_name,
                    previous_exists=previous_exists,
                    previous_bytes=previous_bytes,
                    previous_provider_members=previous_provider_members,
                    previous_group_members=previous_group_members,
                    client=client,
                    previous_route_guard=previous_route_guard,
                    deadline_monotonic=deadline_monotonic,
                )
            )
            return {
                "updated": False,
                "stale": True,
                "unknown": not rollback_verified,
                "rolled_back": rollback_verified,
                "rollback_verified": rollback_verified,
                "rollback_reason": rollback_reason,
                "provider_update": asdict(transaction),
                "reason": (
                    "Core process, loaded contract, route, network context, "
                    "user selector intent, or Tier3B pool revision changed "
                    "during provider update"
                ),
            }

        contract = dict(candidate_contract)
        provider_validation = transaction.validation
        if provider_validation is not None:
            contract["provider_member_digest"] = str(
                provider_validation.observed_member_digest or ""
            )
            contract["provider_controller_version"] = (
                str(provider_validation.observed_version)
                if provider_validation.observed_version is not None
                else None
            )
            contract["provider_verification_basis"] = str(
                provider_validation.verification_basis or ""
            )
        if loaded_main_digest:
            contract["main_semantic_digest"] = loaded_main_digest
            contract["semantic_digest"] = self._runtime_combined_semantic_digest(
                loaded_main_digest,
                str(contract.get("provider_semantic_digest") or ""),
            )
        loaded_proxy_map = copy.deepcopy(
            loaded_contract.get("proxy_map")
            if isinstance(loaded_contract.get("proxy_map"), dict)
            else {}
        )
        previous_projection = getattr(
            self,
            "_tier3_core_provider_last_projection",
            None,
        )
        for proxy_name in (
            previous_projection.proxy_names
            if isinstance(previous_projection, Tier3CoreProviderProjection)
            else ()
        ):
            loaded_proxy_map.pop(str(proxy_name), None)
        candidate_proxy_map = contract.get("proxy_map")
        if isinstance(candidate_proxy_map, dict):
            for proxy_name in projection.proxy_names:
                if proxy_name in candidate_proxy_map:
                    loaded_proxy_map[str(proxy_name)] = copy.deepcopy(
                        candidate_proxy_map[proxy_name]
                    )
        contract["proxy_map"] = loaded_proxy_map
        contract["runtime_config_path"] = str(runtime_config_path)
        provider_version = (
            str(provider_validation.observed_version)
            if provider_validation is not None
            and provider_validation.observed_version is not None
            else ""
        )
        committed_snapshot = self._commit_tier3_provider_contract_from_readback(
            contract=contract,
            proxies_payload=proxies_payload,
            mutation_binding=mutation_binding,
            provider_version=provider_version,
            preserve_route_authority=preserve_route_authority,
        )
        if committed_snapshot is None:
            rollback_verified, rollback_reason = (
                self._rollback_tier3_provider_transaction(
                    provider_path=provider_path,
                    provider_name=projection.provider_name,
                    previous_exists=previous_exists,
                    previous_bytes=previous_bytes,
                    previous_provider_members=previous_provider_members,
                    previous_group_members=previous_group_members,
                    client=client,
                    previous_route_guard=previous_route_guard,
                    deadline_monotonic=deadline_monotonic,
                )
            )
            return {
                "updated": False,
                "stale": True,
                "deferred": bool(rollback_verified),
                "unknown": not rollback_verified,
                "rolled_back": rollback_verified,
                "rollback_verified": rollback_verified,
                "rollback_reason": rollback_reason,
                "provider_update": asdict(transaction),
                "reason": (
                    "Tier3B provider authority changed before its contract "
                    "and route snapshot could be atomically published"
                ),
            }
        route_refresh_error = ""
        self._tier3_core_provider_last_projection = projection
        if not incident_rebase:
            self._wake_runtime_facility_rebaseline(
                "Tier3B provider committed and read back"
            )
        activation_lock = getattr(
            self,
            "_tier3_egress_activation_lock",
            None,
        )
        if activation_lock is None:
            activation_hold_kind = ""
            activation_active = False
        else:
            with activation_lock:
                activation_hold_kind = str(
                    self._tier3_standby_activation_hold_kind or ""
                )
                activation_active = bool(
                    getattr(self, "_tier3_egress_activation_pending", False)
                    or getattr(
                        self,
                        "_tier3_egress_activation_worker_running",
                        False,
                    )
                    or getattr(
                        self,
                        "_tier3_egress_activation_active_mode",
                        "",
                    )
                )
        if not incident_rebase and not self._runtime_initial_activation_complete():
            # A committed provider version is the only automatic event allowed
            # to reopen startup admission.  The queue coalesces it with an
            # active request and never cancels that request in place.
            del activation_active, activation_hold_kind
            self._reset_tier3_standby_activation_failure()
            self._queue_tier3_egress_activation()
        return {
            "updated": True,
            "reloaded": False,
            "provider_update": asdict(transaction),
            "provider_name": projection.provider_name,
            "member_count": len(projection.proxy_names),
            "provider_member_digest": str(
                provider_validation.observed_member_digest
                if provider_validation is not None
                else ""
            ),
            "provider_version": (
                str(provider_validation.observed_version)
                if provider_validation is not None
                and provider_validation.observed_version is not None
                else None
            ),
            "semantic_digest": str(contract.get("semantic_digest") or ""),
            "route_refresh_error": route_refresh_error,
            "marker": marker,
        }

    def _sync_core_config_after_pool_update(
        self,
        *,
        expected_key: DeferredProviderSyncKey | None = None,
        allow_live_rebase: bool = False,
    ) -> _ProviderSyncOutcome:
        stop_requested = self.stop_event.is_set()
        if stop_requested:
            return _ProviderSyncOutcome(
                ProviderSyncDisposition.SUPERSEDED,
                "runtime stop superseded provider sync",
            )
        if (
            expected_key is not None
            and self._tier3_provider_sync_key() != expected_key
        ):
            return _ProviderSyncOutcome(
                ProviderSyncDisposition.SUPERSEDED,
                "provider sync causal key changed before execution",
            )
        online_growth = False
        if (
            self._tier3_online_provider_cohort_frozen()
            and not allow_live_rebase
            and self._tier3_verified_lane_open()
        ):
            eligible, why = self._tier3_verified_online_write_state()
            if not eligible:
                self._tier3_online_growth_waited_at = time.monotonic()
                self._tier3_online_growth_waits = (
                    int(getattr(self, "_tier3_online_growth_waits", 0) or 0) + 1
                )
                return _ProviderSyncOutcome(
                    ProviderSyncDisposition.PARKED,
                    f"verified Tier3B provider write waits ({why})",
                )
        elif (
            self._tier3_online_provider_cohort_frozen()
            and not allow_live_rebase
        ):
            if not self._tier3_online_growth_state()[0]:
                reason = (
                    "initial activation owns the Core-loaded provider transaction"
                    if self._tier3_initial_activation_transaction_active()
                    else "Core-loaded provider cohort is frozen while traffic is online"
                )
                return _ProviderSyncOutcome(
                    ProviderSyncDisposition.PARKED,
                    reason,
                )
            # Capacity growth below the alive target; the provider
            # transaction admits only an append-only projection whose first
            # member is the current unfixed TIER3-AUTO pick.
            online_growth = True
        runner = self.core_runner
        if (
            runner is not None
            and runner.is_running()
            and self._current_core_runtime_phase() == "formal_no_capture"
            and not self._runtime_initial_activation_was_completed()
            and self._tier3_initial_activation_transaction_active()
            and not allow_live_rebase
        ):
            return _ProviderSyncOutcome(
                ProviderSyncDisposition.PARKED,
                "initial activation owns the Core-loaded provider transaction",
            )
        # Manager health and pool state may commit while a runtime incident is
        # moving the selected route. Park this immutable key; never synthesize
        # another pending request or open a second reload lane inside it.
        if self._runtime_recovery_transaction_active() and not allow_live_rebase:
            return _ProviderSyncOutcome(
                ProviderSyncDisposition.PARKED,
                "runtime recovery transaction is active",
            )
        manager = self.manager
        core_running = bool(self.core_runner and self.core_runner.is_running())
        if (
            manager is not None
            and self.running
            and not core_running
            and self._primary_runtime_healthy_count() > 0
        ):
            primary_marker = self._core_export_sync_marker()
            if self._core_export_sync_failure_is_recent(primary_marker):
                return _ProviderSyncOutcome(
                    ProviderSyncDisposition.NOOP,
                    "primary Core start is inside its failure cooldown",
                )
            self._tier3_required_for_start = False
            self._set_tier3_startup_gate_required(False)
            self._clear_tier3_terminal_startup_failure()
            self._primary_startup_error = None
            try:
                self.start_core()
            except Exception:
                self._mark_core_export_sync_failure(primary_marker)
                raise
            self._mark_core_export_sync_success(primary_marker)
            return _ProviderSyncOutcome(
                ProviderSyncDisposition.COMMITTED,
                "primary Core started from the committed export",
            )
        if (
            self.core_runner
            and self.core_runner.is_running()
            and self._current_core_runtime_phase() == "bootstrap"
        ):
            ready, _healthy, _required, reason = self._tier3_core_gate_check()
            if ready:
                queued = self._queue_tier3_core_gate_attempt()
                return _ProviderSyncOutcome(
                    (
                        ProviderSyncDisposition.COMMITTED
                        if queued
                        else ProviderSyncDisposition.NOOP
                    ),
                    "Tier3 Core gate attempt queued" if queued else reason,
                )
            elif reason == "startup_supply_exhausted" and self.manager is not None:
                self._fail_terminal_tier3_bootstrap(self.manager)
                return _ProviderSyncOutcome(
                    ProviderSyncDisposition.COMMITTED,
                    "terminal Tier3 bootstrap state published",
                )
            else:
                reloaded = self._reload_running_core_config_for_export_marker(
                    self._core_export_sync_marker()
                )
                return _ProviderSyncOutcome(
                    (
                        ProviderSyncDisposition.COMMITTED
                        if reloaded
                        else ProviderSyncDisposition.NOOP
                    ),
                    reason,
                )
        if (
            self.core_runner
            and self.core_runner.is_running()
            and self._current_core_runtime_phase()
            in {"formal_capture", "formal_no_capture"}
        ):
            verified = self._tier3_verified_lane_open()
            write_generation = int(getattr(self, "_tier3_provider_write_generation", 0) or 0)
            if verified:
                # The previous write's member tests finish before the next
                # write rebuilds the members again (a test lands on the object
                # that existed when it started).  The wait comes before the
                # pool marker is taken, so what lands meanwhile is batched
                # into this write instead of superseding it.
                spacing = (
                    float(getattr(self, "_tier3_provider_write_finished_at", 0.0) or 0.0)
                    + _TIER3_VERIFIED_WRITE_SPACING_SECONDS
                    - time.monotonic()
                )
                if spacing > 0 and self.stop_event.wait(spacing):
                    return _ProviderSyncOutcome(
                        ProviderSyncDisposition.SUPERSEDED,
                        "runtime stop superseded provider sync",
                    )
                if (
                    expected_key is not None
                    and self._tier3_provider_sync_key() != expected_key
                ):
                    return _ProviderSyncOutcome(
                        ProviderSyncDisposition.SUPERSEDED,
                        "provider sync causal key changed during the write spacing",
                    )
                # A judgement admitted inside the spacing owns the route until
                # it ends: park without raising the flag, which would only
                # stand it down for a write that parks anyway.  Otherwise busy
                # first, then the judge again: one admitted between the two
                # checks is seen here, one admitted later sees the flag (the
                # write re-checks under the Core lock too).
                eligible, why = self._tier3_verified_online_write_state()
                if eligible:
                    self._tier3_provider_write_busy = True
                    eligible, why = self._tier3_verified_online_write_state()
                    if not eligible:
                        self._tier3_provider_write_busy = False
                if not eligible:
                    self._tier3_online_growth_waited_at = time.monotonic()
                    self._tier3_online_growth_waits = (
                        int(getattr(self, "_tier3_online_growth_waits", 0) or 0) + 1
                    )
                    return _ProviderSyncOutcome(
                        ProviderSyncDisposition.PARKED,
                        f"verified Tier3B provider write waits ({why})",
                    )
            try:
                # Inside the try: the finally lowers the busy flag whatever
                # raises, the marker read included.
                marker = self._tier3_core_sync_marker()
                provider_result = (
                    self._update_running_tier3_core_provider(
                        marker,
                        online_growth=True,
                    )
                    if online_growth
                    else self._update_running_tier3_core_provider(marker)
                )
                if provider_result.get("updated") and provider_result.get("verified_write"):
                    # A pick-moving write carries READY on its own pre-commit
                    # pick check, before Phase B tests the members.
                    self._maybe_carry_runtime_ready("provider_commit")
                    provider_result = {
                        **provider_result,
                        "verification": self._verify_tier3_provider_after_write(provider_result),
                    }
            finally:
                if verified:
                    self._tier3_provider_write_busy = False
                    if int(getattr(self, "_tier3_provider_write_generation", 0) or 0) != write_generation:
                        # Only an attempt that wrote the file spaces the next.
                        self._tier3_provider_write_finished_at = time.monotonic()
            if provider_result.get("updated"):
                if provider_result.get("verified_write") and not provider_result.get("pick_moving"):
                    # The live pick kept serving: no route changed, so the
                    # source supply (and its retry backoff) is left alone.
                    self._mark_tier3_provider_sync_complete(marker, notify_route=False)
                else:
                    self._mark_tier3_provider_sync_complete(marker)
                self._record_tier3_core_sync_ledger(
                    "provider_update",
                    semantic_digest=str(
                        provider_result.get("semantic_digest") or ""
                    ),
                )
                if provider_result.get("verified_write"):
                    self._tier3_online_growth_waited_at = 0.0
                    self._tier3_online_growth_waits = 0
                    self.logger.info(
                        "Bastion Layer verified provider write committed "
                        "(members=%s new=%s removed=%s pick_moving=%s contract_only=%s)",
                        provider_result.get("member_count"),
                        len(provider_result.get("new_names") or ()),
                        len(provider_result.get("removed_names") or ()),
                        bool(provider_result.get("pick_moving")),
                        bool(provider_result.get("contract_only")),
                    )
                if online_growth:
                    self._tier3_online_growth_waited_at = 0.0
                    self._tier3_online_growth_waits = 0
                    self.logger.info(
                        "Bastion Layer online growth committed "
                        "(members=%s target_alive=%s)",
                        provider_result.get("member_count"),
                        (
                            self._tier3_background_target_alive(self.manager)
                            if self.manager is not None
                            else "unknown"
                        ),
                    )
                return _ProviderSyncOutcome(
                    ProviderSyncDisposition.COMMITTED,
                    "Tier3B provider inventory committed and read back",
                )
            elif provider_result.get("unchanged"):
                self._mark_tier3_provider_sync_complete(marker)
                self._record_tier3_core_sync_ledger(
                    "semantic_noop",
                    semantic_digest=str(
                        provider_result.get("semantic_digest") or ""
                    ),
                )
                return _ProviderSyncOutcome(
                    ProviderSyncDisposition.NOOP,
                    str(
                        provider_result.get("reason")
                        or "Tier3B provider inventory is already loaded"
                    ),
                )
            elif provider_result.get("deferred"):
                # On the verified lane every deferral backs off, including the
                # append-only lanes' (incident, standby, facility hold) ones.
                if (
                    provider_result.get("growth_wait")
                    or provider_result.get("verified_write")
                    or verified
                ):
                    self._tier3_online_growth_waited_at = time.monotonic()
                    self._tier3_online_growth_waits = (
                        int(getattr(self, "_tier3_online_growth_waits", 0) or 0) + 1
                    )
                if (
                    expected_key is not None
                    and self._tier3_provider_sync_key() != expected_key
                ):
                    return _ProviderSyncOutcome(
                        ProviderSyncDisposition.SUPERSEDED,
                        str(
                            provider_result.get("reason")
                            or "provider sync causal key changed"
                        ),
                    )
                return _ProviderSyncOutcome(
                    ProviderSyncDisposition.PARKED,
                    str(
                        provider_result.get("reason")
                        or "provider mutation owner is unavailable"
                    ),
                )
            elif provider_result.get("verified_write"):
                # No failure mark: the Core still serves (nothing was restored
                # or rolled back), so a restart must not be refused for it.
                log_raw_diagnostic(
                    self.logger,
                    "warning",
                    "Bastion Layer verified provider write was not proven: %s",
                    str(provider_result.get("reason") or "unverified update"),
                )
                reason = str(
                    provider_result.get("reason")
                    or "provider update was not verified"
                )
                if provider_result.get("stale"):
                    return _ProviderSyncOutcome(ProviderSyncDisposition.SUPERSEDED, reason)
                # Park on the verified backoff: the sync key no longer moves
                # with health commits, so nothing else would retry it.  The
                # retry reads membership from the controller again, and the
                # same bytes are a no-op for Mihomo.
                self._tier3_online_growth_waited_at = time.monotonic()
                self._tier3_online_growth_waits = (
                    int(getattr(self, "_tier3_online_growth_waits", 0) or 0) + 1
                )
                return _ProviderSyncOutcome(ProviderSyncDisposition.PARKED, reason)
            else:
                self._mark_tier3_core_sync_failure(marker)
                log_raw_diagnostic(
                    self.logger,
                    "warning",
                    "Bastion Layer provider update retained the previous Core inventory: %s",
                    str(provider_result.get("reason") or "unverified update"),
                )
                return _ProviderSyncOutcome(
                    (
                        ProviderSyncDisposition.SUPERSEDED
                        if provider_result.get("stale")
                        else ProviderSyncDisposition.UNKNOWN
                    ),
                    str(
                        provider_result.get("reason")
                        or "provider update was not verified"
                    ),
                )
            # Never silently fall back to a full Core reload for Tier3B
            # admission/eviction.  The last verified provider remains loaded.
        marker = self._tier3_core_sync_marker()
        action = tier3_core_sync_action_after_pool_update(
            stop_requested=stop_requested,
            runtime_running=self.running,
            core_running=bool(self.core_runner and self.core_runner.is_running()),
            marker=marker,
            last_marker=self._last_tier3_core_sync_marker,
        )
        if action is Tier3CoreSyncAction.DEFERRED_START:
            started = self._attempt_deferred_tier3_core_start(marker)
            return _ProviderSyncOutcome(
                (
                    ProviderSyncDisposition.COMMITTED
                    if started
                    else ProviderSyncDisposition.NOOP
                ),
                "deferred Tier3 Core start committed" if started else "Core start not due",
            )
        if action is Tier3CoreSyncAction.RELOAD_RUNNING_CORE:
            reloaded = self._reload_running_tier3_core_config_for_marker(marker)
            return _ProviderSyncOutcome(
                (
                    ProviderSyncDisposition.COMMITTED
                    if reloaded
                    else ProviderSyncDisposition.NOOP
                ),
                "Tier3 Core export reloaded" if reloaded else "Tier3 export unchanged",
            )
        if action is Tier3CoreSyncAction.NONE and self.core_runner and self.core_runner.is_running():
            reloaded = self._reload_running_core_config_for_export_marker(
                self._core_export_sync_marker()
            )
            return _ProviderSyncOutcome(
                (
                    ProviderSyncDisposition.COMMITTED
                    if reloaded
                    else ProviderSyncDisposition.NOOP
                ),
                "Core export reloaded" if reloaded else "Core export unchanged",
            )
        return _ProviderSyncOutcome(
            ProviderSyncDisposition.NOOP,
            "no Core/provider synchronization action is due",
        )

    def _revoke_core_provider_authority(self, reason: str) -> None:
        self._set_core_runtime_phase("stopping")
        self._disarm_runtime_recovery(reason)
        # Revoke the immutable loaded-route owner before Core shutdown begins.
        # Any stdout item, probe or recovery worker already in flight must fail
        # its snapshot/worker CAS instead of acting on the disappearing process.
        with self._runtime_route_snapshot_lock:
            self._runtime_route_epoch += 1
            self._node_judgement_arm_epoch("revoke_core_provider_authority")
            self._mark_runtime_route_attribution_barrier_locked()
            self._runtime_route_snapshot = None
            self._runtime_route_snapshot_payload = None
            self._runtime_core_inventory_snapshot = None
            self._runtime_route_selection_signature = ()
            self._runtime_confirmed_fail_closed_snapshot_key = None
        self._runtime_egress_coordinator.set_current_snapshot(None)
        with self._tier3_egress_activation_lock:
            self._tier3_egress_activation_pending = False
            self._tier3_egress_activation_pending_mode = ""
            self._tier3_egress_activation_generation += 1
            self._tier3_egress_activation_active_generation = 0
        self._initial_egress_activation_deferred = False
        self._initial_egress_activation_deferred_core_generation = -1
        manager = self.manager
        capture_marker = (
            getattr(manager, "mark_tier3_traffic_capture_active", None)
            if manager
            else None
        )
        if callable(capture_marker):
            try:
                capture_marker(False)
            except Exception:
                pass
        elif manager is not None and hasattr(manager, "tier3_traffic_capture_active"):
            manager.tier3_traffic_capture_active = False
        if manager is not None:
            lock = getattr(manager, "lock", nullcontext())
            with lock:
                report = getattr(manager, "tier3_last_collection_report", None)
                if isinstance(report, dict):
                    report["traffic_capture_active"] = False
        self._set_effective_egress_state(False, reason)
        self._publish_runtime_egress_readiness(
            RuntimeEgressReadinessState.FAIL_CLOSED,
            validation_active=False,
            reason=reason,
        )

    def stop_core(
        self,
        *,
        actor: str = "runtime",
        reason: str = "requested",
        timeout: float = 5.0,
        stage_observer: Callable[[str], None] | None = None,
    ) -> dict[str, object]:
        self._revoke_core_provider_authority(
            f"Mihomo core stop in progress: {reason}"
        )
        deadline = time.monotonic() + max(0.0, float(timeout))

        def remaining() -> float:
            return max(0.0, deadline - time.monotonic())

        def mark_stage(stage: str) -> None:
            if not callable(stage_observer):
                return
            try:
                stage_observer(str(stage))
            except Exception:
                pass

        mark_stage("traffic_monitor_started")
        _call_with_optional_timeout(
            self.traffic_monitor.stop,
            keyword="timeout",
            timeout=min(0.25, remaining()),
        )
        mark_stage("traffic_monitor_completed")
        with self._tier3_egress_activation_lock:
            self._tier3_egress_activation_pending = False
        egress_activation_drained = self._wait_for_tier3_egress_activation(
            timeout=min(0.25, remaining())
        )
        mark_stage(
            "egress_activation_completed"
            if egress_activation_drained
            else "egress_activation_active"
        )
        if not self.core_runner:
            self._set_core_runtime_phase("stopped")
            self._last_tier3_core_sync_marker = None
            self._last_core_export_sync_marker = None
            self._clear_tier3_runtime_qualification()
            mark_stage("runner_missing")
            return {
                "running": False,
                "pid": None,
                "recent_logs": [],
                "runtime_background_active": not egress_activation_drained,
                "egress_activation_active": not egress_activation_drained,
            }
        status_before = self.core_runner.status()
        mark_stage("runner_status_completed")
        pid = status_before.get("pid") if isinstance(status_before, dict) else None
        with self._core_lifecycle_lock:
            generation = self._core_generation
        mark_stage("runner_stop_started")
        result = _call_with_optional_timeout(
            self.core_runner.stop,
            keyword="timeout",
            timeout=remaining(),
        )
        if isinstance(result, dict) and not egress_activation_drained:
            result = {
                **result,
                "runtime_background_active": True,
                "egress_activation_active": True,
            }
        mark_stage("runner_stop_completed")
        stop_incomplete = bool(
            isinstance(result, dict)
            and (
                result.get("still_running")
                or result.get("running")
                or result.get("cleanup_pending")
                or result.get("reader_drained") is False
                or ("stopped" in result and not result.get("stopped"))
            )
        )
        process_still_running = bool(
            isinstance(result, dict)
            and (result.get("still_running") or result.get("running"))
        )
        self._last_core_stop = {
            "actor": str(actor or "runtime"),
            "reason": str(reason or "requested"),
            "generation": generation,
            "pid": pid,
            "at": utc_now_iso(),
            "result": "failed" if stop_incomplete else "stopped",
        }
        if stop_incomplete:
            failure_detail = (
                "Mihomo process is still running after stop deadline"
                if process_still_running
                else "Mihomo output reader did not stop before the cleanup deadline"
            )
            try_log_nowait(
                self.logger,
                "error",
                "%s "
                "(actor=%s reason=%s generation=%s pid=%s)",
                failure_detail,
                self._last_core_stop["actor"],
                self._last_core_stop["reason"],
                generation,
                pid,
                extra=_RAW_ONLY_LOG_EXTRA,
            )
            mark_stage("runner_still_active")
            return result
        self._set_core_runtime_phase("stopped")
        self._last_tier3_core_sync_marker = None
        self._last_core_export_sync_marker = None
        self._clear_tier3_runtime_qualification()
        with self._core_lifecycle_lock:
            self._staged_capture_runtime_config_payload = None
            self._staged_capture_runtime_config_path = None
            self._staged_capture_runtime_export_contract = None
            self._staged_capture_runtime_network_mode = None
        manager = self.manager
        marker = getattr(manager, "mark_tier3_core_stopped", None) if manager else None
        if callable(marker):
            marker(f"{self._last_core_stop['actor']}: {self._last_core_stop['reason']}")
        mark_stage("manager_state_completed")
        log_event(
            self.logger,
            "INFO",
            "runtime.mihomo_stopped",
            "Mihomo core stopped "
            f"(actor={self._last_core_stop['actor']} "
            f"reason={self._last_core_stop['reason']} "
            f"generation={generation} pid={pid})",
        )
        return result

    def restart_core(self) -> dict[str, object]:
        # Publish cancellation before waiting for a route mutation. Otherwise
        # a blocked admission could keep applying capture and later announce
        # READY while the user-visible restart is still queued on this lock.
        self._revoke_core_provider_authority("Mihomo core restart in progress")
        with self._core_transition_lock:
            return self._restart_core_serialized(authority_revoked=True)

    def _restart_core_serialized(
        self,
        *,
        authority_revoked: bool = False,
    ) -> dict[str, object]:
        if self.stop_event.is_set():
            return self.stop_core()
        if not self.manager:
            raise RuntimeError("manager service is not running")
        if not authority_revoked:
            self._revoke_core_provider_authority("Mihomo core restart in progress")
        with self._tier3_egress_activation_lock:
            self._tier3_egress_activation_pending = False
            self._tier3_egress_activation_pending_mode = ""
            self._tier3_egress_activation_generation += 1
        self.traffic_monitor.stop()
        self.restore_system_proxy()
        stop_result = self._get_core_runner().stop()
        if (
            not bool(stop_result.get("stopped"))
            or bool(stop_result.get("still_running"))
            or bool(stop_result.get("cleanup_pending"))
        ):
            self.last_error = str(
                stop_result.get("restart_error")
                or "Mihomo restart aborted because the previous core did not stop cleanly"
            )
            return stop_result
        self._set_core_runtime_phase("stopped")
        if self.stop_event.is_set():
            return stop_result
        return self.start_core()

    def _client_config(self) -> dict[str, Any]:
        return client_config_block(self.config)

    def _tiers_config(self) -> dict[str, Any]:
        return tiers_block(self.config)

    def _tier_config(self, tier_id: str) -> dict[str, Any]:
        return tier_block(self.config, tier_id)

    def _tier_nodes_config(self, tier_id: str) -> list[Any]:
        nodes = self._tier_config(tier_id).get("nodes", [])
        if not isinstance(nodes, list):
            return []
        return [node for node in nodes if config_entry_enabled(node)]

    def _mihomo_controller_config(self) -> dict[str, Any]:
        return mihomo_controller_block(self.config)

    def _system_proxy_config(self) -> dict[str, Any]:
        return system_proxy_block(self.config)

    def _runtime_config_path_for_client(self) -> Path:
        return self._resolve_path(mihomo_client_paths(self._client_config()).runtime_config_path)

    def _restore_previous_runtime_config(
        self,
        runtime_config_path: Path,
        previous_config_text: str | None,
    ) -> bool:
        return restore_runtime_config_text(runtime_config_path, previous_config_text)

    def _restore_previous_provider_config(
        self,
        reload_context: CoreReloadContext,
    ) -> bool:
        provider_path = reload_context.provider_path
        if provider_path is None:
            self._tier3_core_provider_pending_projection = None
            return True
        try:
            if reload_context.previous_provider_exists:
                atomic_replace_if_changed(
                    provider_path,
                    reload_context.previous_provider_bytes,
                )
            else:
                provider_path.unlink(missing_ok=True)
        except OSError:
            return False
        self._tier3_core_provider_pending_projection = (
            reload_context.previous_provider_projection
            if isinstance(
                reload_context.previous_provider_projection,
                Tier3CoreProviderProjection,
            )
            else None
        )
        return True

    def _keep_existing_core_after_reload_failure(
        self,
        runner: Any,
        controller: dict[str, Any],
        runtime_config_path: Path,
        previous_config_text: str | None,
        reason: str,
    ) -> dict[str, Any]:
        restored = self._restore_previous_runtime_config(runtime_config_path, previous_config_text)
        restore_reload: dict[str, Any] = {"reloaded": False}
        if restored and runner.is_running() and mihomo_controller_enabled(controller):
            try:
                restore_reload = runner.hot_reload(**hot_reload_kwargs_from_controller(controller))
            except Exception as exc:
                restore_reload = {"reloaded": False, "reason": str(exc)}
        log_raw_diagnostic(
            self.logger,
            "warning",
            "Keeping existing mihomo core after failed reload: %s (restored_config=%s, restore_reload=%s)",
            reason,
            restored,
            restore_reload.get("reloaded"),
        )
        if runner.is_running():
            self._invalidate_exit_route_context()
            self._set_effective_egress_state(
                None,
                f"{reason}; FINAL-EXIT identity verification after rollback is pending",
            )
            self._queue_incremental_egress_recheck()
        else:
            self._set_effective_egress_state(False, f"{reason}; mihomo core is not running")
        return build_keep_existing_core_reload_failure_result(
            reason=reason,
            restored_config=restored,
            restore_reload=restore_reload,
            core_status=runner.status(),
        )

    def _keep_existing_tier3_core_after_reload_failure(
        self,
        *,
        runner: Any,
        controller: dict[str, Any],
        runtime_config_path: Path,
        previous_config_text: str | None,
        rollback_tier3_nodes: list[Any],
        reason: str,
    ) -> dict[str, Any]:
        self._clear_tier3_core_export_override()
        if self._current_tier3_pool_has_tcp_prelaunch_nodes():
            self._restore_tier3_pool_after_failed_reload(rollback_tier3_nodes)
        return self._keep_existing_core_after_reload_failure(
            runner,
            controller,
            runtime_config_path,
            previous_config_text,
            reason,
        )

    def _current_tier3_pool_has_tcp_prelaunch_nodes(self) -> bool:
        manager = self.manager
        if not manager:
            return False
        with manager.lock:
            nodes = list(getattr(manager, "runtime_nodes", {}).get("tier3", []))
        return any(
            isinstance(getattr(node, "extra", None), dict)
            and node.extra.get("startup_prelaunch_validation") == "tcp"
            for node in nodes
        )

    def _keep_existing_core_reload_context(
        self,
        *,
        runner: Any,
        reload_context: CoreReloadContext,
        reason: str,
    ) -> dict[str, Any]:
        restored_provider = self._restore_previous_provider_config(
            reload_context
        )
        result = self._keep_existing_tier3_core_after_reload_failure(
            runner=runner,
            controller=reload_context.controller,
            runtime_config_path=reload_context.runtime_config_path,
            previous_config_text=reload_context.previous_config_text,
            rollback_tier3_nodes=reload_context.rollback_tier3_nodes,
            reason=reason,
        )
        result["restored_provider"] = restored_provider
        return result

    def _keep_existing_core_after_incremental_export_failure(
        self,
        *,
        runner: Any,
        reload_context: CoreReloadContext,
        reason: str,
    ) -> dict[str, Any]:
        restored_provider = self._restore_previous_provider_config(
            reload_context
        )
        restored = self._restore_previous_runtime_config(
            reload_context.runtime_config_path,
            reload_context.previous_config_text,
        )
        restore_reload: dict[str, Any] = {"reloaded": False}
        if restored and runner.is_running() and mihomo_controller_enabled(
            reload_context.controller
        ):
            try:
                restore_reload = runner.hot_reload(
                    **hot_reload_kwargs_from_controller(reload_context.controller)
                )
            except Exception as exc:
                restore_reload = {"reloaded": False, "reason": str(exc)}
        log_raw_diagnostic(
            self.logger,
            "warning",
            "Keeping existing mihomo export after incremental Tier3 reload failure: %s "
            "(restored_config=%s restore_reload=%s)",
            reason,
            restored,
            restore_reload.get("reloaded"),
        )
        result = build_keep_existing_core_reload_failure_result(
            reason=reason,
            restored_config=restored,
            restore_reload=restore_reload,
            core_status=runner.status(),
        )
        result["restored_provider"] = restored_provider
        return result

    def _fail_closed_after_core_export_removal_failure(
        self,
        *,
        runner: Any,
        reason: str,
    ) -> dict[str, Any]:
        """Retire a loaded export that still contains a now-invalid proxy.

        Rolling the runtime file back is unsafe after a node has been removed
        from the private ALIVE/SLOW view: Mihomo would keep dialing that stale
        leaf even though the public inventory correctly marks it unhealthy.
        """

        failure_reason = f"{reason}; retiring unsafe loaded proxy export"
        with self._tier3_egress_activation_lock:
            self._tier3_egress_activation_pending = False
            self._tier3_egress_activation_pending_mode = ""
            self._tier3_egress_activation_generation += 1
        self._invalidate_exit_route_context()
        # Automatic failure must leave proxy clients on the closed local path.
        # Restoring the user's pre-start settings here can silently enable DIRECT.
        try:
            stop_result = self.stop_core(
                actor="core_export_sync",
                reason=failure_reason,
                timeout=2.0,
            )
        except Exception as exc:
            stop_result = {
                "running": bool(runner.is_running()),
                "stop_error": str(exc),
            }
            log_raw_diagnostic(
                self.logger,
                "error",
                "Failed to stop Mihomo after unsafe export reload failure",
                exc_info=True,
            )
        core_status = runner.status()
        core_stopped = core_status.get("running") is False
        if not core_stopped:
            failure_reason += "; Core stop is unconfirmed"
        self.last_error = failure_reason
        self._set_effective_egress_state(False, failure_reason)
        return {
            "reloaded": False,
            "reason": failure_reason,
            "kept_existing_core": not core_stopped,
            "fail_closed": core_stopped,
            "capture_enabled": False,
            "core": core_status,
            "stop": stop_result,
        }

    def _core_reload_unavailable(self, runner: Any, reason: str) -> dict[str, Any]:
        return build_core_reload_unavailable_result(
            reason=reason,
            core_status=runner.status(),
        )

    def _stop_sensitive_reload_failure_response(
        self,
        *,
        runner: Any,
        reload_result: Any,
        keep_existing: Callable[[str], dict[str, Any]],
    ) -> dict[str, Any]:
        action = stop_sensitive_core_reload_failure_action(
            reload_result,
            stop_requested=self.stop_event.is_set(),
        )
        if action.unavailable_reason is not None:
            return self._core_reload_unavailable(runner, action.unavailable_reason)
        return keep_existing(str(action.keep_existing_reason))

    def _restore_tier3_pool_after_failed_reload(self, previous_nodes: list[Any]) -> None:
        manager = self.manager
        if not manager or not should_restore_tier3_pool_after_failed_reload(previous_nodes):
            return
        with manager.lock:
            report = getattr(manager, "tier3_last_collection_report", {})
            if isinstance(report, dict):
                report.update(
                    build_tier3_core_reload_rollback_report(
                        retained_count=len(previous_nodes),
                    )
                )
                report["pool_mutation"] = "none"
                report["core_reload_export_rollback_only"] = True
        self.logger.info(
            "Retained canonical Bastion Layer pool after failed hot reload; "
            "rollback is limited to the core export"
        )

    def _reload_pruned_primary_tier3_export(
        self,
        runner: Any,
        controller: dict[str, Any],
    ) -> dict[str, Any]:
        plan = self._prepare_tier3_core_repair_override(
            prune_to_successful=True,
            target_alive=self._tier3_core_repair_target_alive(),
            minimum_alive=self._tier3_core_repair_min_alive(),
        )
        if plan is None:
            return build_tier3_core_reload_failure_result(
                reason="could not verify exported Bastion Layer node through Mihomo",
                stop_sensitive=False,
            )
        # T-P2-RT3 fix 1: the mode this re-render loads (recorded by the caller).
        loaded_network_mode = str(getattr(self, "network_mode", "") or "").strip().lower()
        try:
            self.write_mihomo_runtime_config()
            pruned_reload = runner.hot_reload(**hot_reload_kwargs_from_controller(controller))
        except Exception as exc:
            self._clear_tier3_core_export_override()
            return build_tier3_core_reload_failure_result(
                reason=f"hot reload after applying Bastion Layer core verification order failed: {exc}",
                stop_sensitive=True,
            )
        if pruned_reload.get("reloaded"):
            pruned_reload["_tier3_core_repair_plan"] = plan
            pruned_reload["_loaded_network_mode"] = loaded_network_mode
            return pruned_reload
        self._clear_tier3_core_export_override()
        return build_tier3_core_reload_failure_result(
            reason=f"hot reload after applying Bastion Layer core verification order failed: {pruned_reload.get('reason')}",
            stop_sensitive=True,
            reload_result=pruned_reload,
        )

    def _runtime_proxy_name_map(
        self,
        *,
        include_runtime_unusable: bool = False,
        runtime_view: Any | None = None,
    ) -> dict[str, dict[str, Any]]:
        manager = self.manager
        if not manager:
            return {}
        runtime_view = runtime_view or (
            manager
            if include_runtime_unusable
            else self._manager_for_mihomo_runtime_config()
        )
        getter = getattr(runtime_view, "get_nodes_for_subscription", None)
        # This must use the exact seed owned by the real renderer. Starting
        # from an empty set renames collisions differently and can make every
        # healthy loaded leaf disappear from the immutable export contract.
        seen_names: set[str] = set(MIHOMO_RESERVED_PROXY_NAMES)
        # And the renderer's Tier3 naming: by definition on the verified lane.
        stable_tier3 = bool(getattr(runtime_view, "stable_tier3_names", False)) or bool(
            include_runtime_unusable and self._tier3_verified_provider_writes_enabled()
        )
        mapping: dict[str, dict[str, Any]] = {}
        for tier_id in ("tier1", "tier2", "tier3", "exit"):
            if include_runtime_unusable:
                nodes = list(getattr(manager, "runtime_nodes", {}).get(tier_id, []))
            elif callable(getter):
                nodes = list(getter(tier_id, limit=None))
            else:
                nodes = list(getattr(runtime_view, "runtime_nodes", {}).get(tier_id, []))
            pairs: list[tuple[Any, dict[str, Any]]] = []
            build_clash_proxy_list(
                nodes,
                logger=self.logger,
                seen_names=seen_names,
                rendered_pairs=pairs,
                stable_names=tier_id == "tier3" and stable_tier3,
            )
            for node, proxy in pairs:
                if not proxy or not proxy.get("name"):
                    continue
                proxy_name = str(proxy["name"])
                mapping[proxy_name] = {
                    "proxy_name": proxy_name,
                    "tier": tier_id,
                    "pool_kind": self._runtime_pool_kind(tier_id, node),
                    "identity": self._node_identity_text(node),
                    "node": node,
                    "proxy": dict(proxy),
                }
        return mapping

    def _runtime_proxy_map_from_render_receipt(
        self,
        receipt: dict[str, Any],
    ) -> dict[str, dict[str, Any]]:
        """Bind identities to the proxy objects emitted by the real renderer."""

        entries = receipt.get("proxies") if isinstance(receipt, dict) else None
        if not isinstance(entries, (list, tuple)):
            return {}
        mapping: dict[str, dict[str, Any]] = {}
        for raw in entries:
            if not isinstance(raw, dict):
                continue
            tier_id = str(raw.get("tier") or "")
            node = raw.get("node")
            proxy = raw.get("proxy")
            if node is None or not isinstance(proxy, dict):
                continue
            proxy_name = str(proxy.get("name") or "")
            if not proxy_name:
                continue
            clone = getattr(node, "clone", None)
            mapping[proxy_name] = {
                "proxy_name": proxy_name,
                "tier": tier_id,
                "pool_kind": self._runtime_pool_kind(tier_id, node),
                "identity": self._node_identity_text(node),
                "node": clone() if callable(clone) else copy.deepcopy(node),
                "proxy": copy.deepcopy(proxy),
            }
        selection = receipt.get("exit_selection")
        if isinstance(selection, dict):
            entry = mapping.get(str(selection.get("member") or ""))
            requested = str(selection.get("requested") or "")
            key = str(selection.get("key") or ("name:" + requested if requested else ""))
            if isinstance(entry, dict) and entry.get("tier") == "exit" and key:
                # The saved Gateway selection (its key) the renderer chose this
                # EXIT-SELECT member for (_runtime_export_contract_for_payload
                # keeps it with the main graph it was rendered into).
                entry["selected_for"] = key
        return mapping

    def _runtime_pool_kind(self, tier_id: str, node: Any) -> str:
        if tier_id == "tier1":
            return "tier1_variant"
        if tier_id == "tier2":
            return "tier2"
        if tier_id == "exit":
            return "gateway"
        if tier_id == "tier3":
            detector = getattr(self.manager, "_is_tier3_auto_pool_node", None)
            if callable(detector):
                try:
                    return "tier3b" if bool(detector(node)) else "tier3a"
                except Exception:
                    pass
            extra = getattr(node, "extra", {})
            if isinstance(extra, dict) and bool(extra.get("tier3_auto_pool")):
                return "tier3b"
            return "tier3a"
        return str(tier_id or "")

    def _runtime_loaded_semantic_digest(self) -> str:
        with self._runtime_route_snapshot_lock:
            loaded = self._runtime_loaded_export_contract
            if isinstance(loaded, dict) and loaded.get("semantic_digest"):
                return str(loaded["semantic_digest"])
        try:
            return hashlib.sha256(
                self._runtime_config_path_for_client().read_bytes()
            ).hexdigest()
        except (OSError, ValueError):
            marker = (
                int(self._core_generation),
                str(self._tier3_runtime_config_digest or ""),
                self._core_export_sync_marker(),
            )
            return hashlib.sha256(repr(marker).encode("utf-8")).hexdigest()

    def _carry_loaded_gateway_entries(
        self,
        exact_map: dict[str, dict[str, Any]],
        document: Any,
        main_semantic_digest: str,
    ) -> None:
        """Keep the loaded Gateway entries a provider-only commit would drop.

        A provider-only commit rebuilds the map from a fresh render over the
        unchanged loaded main payload; when exit names moved meanwhile (a
        latency swap, a positional collider leaving), the fresh definitions
        differ and every exit entry falls out.  The main graph is the loaded
        one, so its exit entries still describe what Core serves.
        """

        loaded = getattr(self, "_runtime_loaded_export_contract", None)
        if (
            not isinstance(loaded, dict)
            or str(loaded.get("main_semantic_digest") or "") != main_semantic_digest
        ):
            return
        proxies = document.get("proxies") if isinstance(document, dict) else None
        main_names = {
            str(proxy.get("name") or "")
            for proxy in (proxies or [])
            if isinstance(proxy, dict)
        }
        for name, info in (loaded.get("proxy_map") or {}).items():
            if (
                not isinstance(info, dict)
                or str(info.get("tier") or "") != "exit"
                or str(name) not in main_names
                or str(name) in exact_map
            ):
                continue
            copied = dict(info)
            node = copied.get("node")
            clone = getattr(node, "clone", None)
            copied["node"] = clone() if callable(clone) else copy.deepcopy(node)
            copied["proxy"] = copy.deepcopy(info.get("proxy"))
            exact_map[str(name)] = copied

    def _keep_gateway_selection_decision(
        self,
        exact_map: dict[str, dict[str, Any]],
        document: Any,
        main_semantic_digest: str,
    ) -> None:
        """Keep the renderer's Gateway decision on this main graph's member.

        ``selected_for`` names the saved Gateway selection the main graph's
        EXIT-SELECT member was rendered for.  A provider-only commit keeps
        the loaded main graph, so it keeps the loaded decision even when its
        fresh render decided otherwise (a colliding Bastion member left).
        No other entry carries one.  Readers use it instead of replaying the
        naming over a later or partial node list.
        """

        groups = document.get("proxy-groups") if isinstance(document, dict) else None
        exit_group = next(
            (
                group
                for group in (groups or [])
                if isinstance(group, dict) and str(group.get("name") or "") == "EXIT-SELECT"
            ),
            None,
        )
        member = next(
            (
                str(name)
                for name in (exit_group.get("proxies") or [] if isinstance(exit_group, dict) else [])
                if not builtin_terminal_kind(str(name or ""))
            ),
            "",
        )
        info = exact_map.get(member) if member else None
        decided = ""
        if isinstance(info, dict) and str(info.get("tier") or "") == "exit":
            decided = str(info.get("selected_for") or "")
            if not decided:
                loaded = getattr(self, "_runtime_loaded_export_contract", None)
                if (
                    isinstance(loaded, dict)
                    and str(loaded.get("main_semantic_digest") or "") == main_semantic_digest
                ):
                    previous = (loaded.get("proxy_map") or {}).get(member)
                    if isinstance(previous, dict):
                        decided = str(previous.get("selected_for") or "")
        for name, entry in exact_map.items():
            if name == member and decided:
                entry["selected_for"] = decided
            else:
                entry.pop("selected_for", None)

    def _runtime_export_contract_for_payload(
        self,
        payload: str,
        *,
        provider_payload: str | None = None,
        rendered_proxy_map: dict[str, dict[str, Any]] | None = None,
    ) -> dict[str, Any]:
        """Capture the exact managed proxy map rendered into one Core config."""

        encoded = payload.replace("\n", os.linesep).encode("utf-8")
        try:
            document = yaml.safe_load(payload)
        except Exception:
            document = None
        if provider_payload is None and isinstance(document, dict):
            providers = document.get("proxy-providers")
            provider_name = str(
                getattr(
                    self,
                    "_tier3_core_provider_name",
                    "TIER3B-RUNTIME",
                )
                or "TIER3B-RUNTIME"
            )
            if isinstance(providers, dict) and provider_name in providers:
                try:
                    provider_payload = self._tier3_core_provider_file_path().read_text(
                        encoding="utf-8"
                    )
                except (OSError, ValueError):
                    provider_payload = None
        provider_encoded = (
            str(provider_payload).replace("\n", os.linesep).encode("utf-8")
            if provider_payload
            else b""
        )
        main_semantic_digest = hashlib.sha256(encoded).hexdigest()
        provider_semantic_digest = hashlib.sha256(provider_encoded).hexdigest()
        semantic_digest = self._runtime_combined_semantic_digest(
            main_semantic_digest,
            provider_semantic_digest,
        )
        loaded_proxies = (
            document.get("proxies")
            if isinstance(document, dict)
            else None
        )
        provider_document: Any = None
        if provider_payload:
            try:
                provider_document = yaml.safe_load(provider_payload)
            except Exception:
                provider_document = None
        provider_proxies = (
            provider_document.get("proxies")
            if isinstance(provider_document, dict)
            else None
        )
        loaded_by_name = {
            str(proxy.get("name") or ""): dict(proxy)
            for proxy in [*(loaded_proxies or []), *(provider_proxies or [])]
            if isinstance(proxy, dict) and str(proxy.get("name") or "")
        }
        current_map = (
            rendered_proxy_map
            if isinstance(rendered_proxy_map, dict)
            else self._runtime_proxy_name_map()
        )
        exact_map: dict[str, dict[str, Any]] = {}
        for proxy_name, info in current_map.items():
            rendered = info.get("proxy") if isinstance(info, dict) else None
            loaded_proxy = loaded_by_name.get(str(proxy_name))
            if not isinstance(rendered, dict) or loaded_proxy != rendered:
                continue
            copied = dict(info)
            node = copied.get("node")
            clone = getattr(node, "clone", None)
            if callable(clone):
                copied["node"] = clone()
            copied["proxy"] = dict(loaded_proxy)
            exact_map[str(proxy_name)] = copied
        self._carry_loaded_gateway_entries(
            exact_map,
            document,
            main_semantic_digest,
        )
        self._keep_gateway_selection_decision(
            exact_map,
            document,
            main_semantic_digest,
        )
        return {
            "semantic_digest": semantic_digest,
            "main_semantic_digest": main_semantic_digest,
            "provider_semantic_digest": provider_semantic_digest,
            "proxy_map": exact_map,
            "provider_projection": (
                getattr(self, "_tier3_core_provider_pending_projection", None)
                if provider_payload
                else None
            ),
            "captured_at_monotonic": time.monotonic(),
        }

    @staticmethod
    def _runtime_combined_semantic_digest(
        main_semantic_digest: str,
        provider_semantic_digest: str,
    ) -> str:
        payload = (
            "main="
            + str(main_semantic_digest or "")
            + "\nprovider="
            + str(provider_semantic_digest or "")
        ).encode("ascii", errors="strict")
        return hashlib.sha256(payload).hexdigest()

    def _record_pending_runtime_export_contract(
        self,
        payload: str,
        runtime_config_path: Path,
        *,
        contract: dict[str, Any] | None = None,
    ) -> None:
        contract = dict(
            contract
            if isinstance(contract, dict)
            else self._runtime_export_contract_for_payload(payload)
        )
        contract["runtime_config_path"] = str(runtime_config_path)
        with self._runtime_route_snapshot_lock:
            self._runtime_pending_export_contract = contract

    @staticmethod
    def _runtime_group_graph_and_selection(
        proxies_payload: Any,
    ) -> tuple[
        tuple[tuple[str, tuple[str, ...]], ...],
        tuple[Any, ...],
        tuple[CoreLoadedGroupState, ...],
    ]:
        if not isinstance(proxies_payload, dict):
            return (), (), ()
        entries = proxies_payload.get("proxies")
        if not isinstance(entries, dict):
            entries = proxies_payload
        graph: list[tuple[str, tuple[str, ...]]] = []
        selection: list[tuple[Any, ...]] = []
        group_states: list[CoreLoadedGroupState] = []
        for raw_name, raw_entry in entries.items():
            if not isinstance(raw_entry, dict):
                continue
            name = str(raw_name)
            members = raw_entry.get("all")
            if members is None:
                members = raw_entry.get("proxies")
            if not isinstance(members, (list, tuple)):
                continue
            normalized_members = tuple(
                str(member) for member in members if str(member or "").strip()
            )
            graph.append((name, normalized_members))
            state = CoreLoadedGroupState(
                name=name,
                type_name=str(
                    raw_entry.get("typeName") or raw_entry.get("type") or ""
                ),
                members=normalized_members,
                now=str(raw_entry.get("now") or raw_entry.get("selected") or ""),
                fixed=str(raw_entry.get("fixed") or ""),
                test_url=str(
                    raw_entry.get("testUrl")
                    or raw_entry.get("test-url")
                    or raw_entry.get("url")
                    or ""
                ),
                expected_status=str(
                    raw_entry.get("expectedStatus")
                    or raw_entry.get("expected-status")
                    or ""
                ),
            )
            group_states.append(state)
            selection.append(state.signature)
        graph.sort(key=lambda item: item[0])
        selection.sort(key=lambda item: item[0])
        group_states.sort(key=lambda item: item.name)
        return tuple(graph), tuple(selection), tuple(group_states)

    def _runtime_final_exit_selection_signature(
        self,
        proxies_payload: Any,
        proxy_map: dict[str, Any],
    ) -> tuple[Any, ...]:
        """Fingerprint only the selected FINAL-EXIT route and Gateway underlay.

        Controller telemetry for unrelated groups must not revoke an incident
        or manufacture a selected-leaf change. Process/generation/config
        ownership remains in the separate CAS fields on the route snapshot.
        """

        def selected_path(start: str) -> tuple[Any, ...]:
            route = inspect_runtime_route(proxies_payload, start=start)
            layers = tuple(
                (
                    str(layer.get("name") or ""),
                    str(layer.get("type") or ""),
                    str(layer.get("now") or ""),
                )
                for layer in (route.get("layers") or ())
                if isinstance(layer, dict)
            )
            return (
                str(start),
                tuple(str(item) for item in (route.get("selected_chain") or ())),
                str(route.get("leaf_proxy") or ""),
                str(route.get("facility_failure") or ""),
                layers,
            )

        final_path = selected_path("FINAL-EXIT")
        leaf = str(final_path[2] or "")
        leaf_info = proxy_map.get(leaf)
        leaf_proxy = (
            leaf_info.get("proxy") if isinstance(leaf_info, dict) else None
        )
        dialer_proxy = (
            str(leaf_proxy.get("dialer-proxy") or "").strip()
            if isinstance(leaf_proxy, dict)
            else ""
        )
        underlay_path: tuple[Any, ...] = ()
        if dialer_proxy:
            underlay_path = selected_path(dialer_proxy)
        return (
            ("user_intent_revision", int(
                getattr(self, "_runtime_selector_intent_revision", 0) or 0
            )),
            ("final_exit", final_path),
            ("gateway_underlay", underlay_path),
        )

    def _refresh_runtime_route_snapshot(
        self,
        *,
        worker_token: tuple[int, ...] | None = None,
        timeout_seconds: float | None = None,
    ) -> CoreLoadedRouteSnapshot | None:
        """Capture the route graph that the current Mihomo process actually loaded."""

        if timeout_seconds is None:
            with self._runtime_route_snapshot_refresh_lock:
                return self._refresh_runtime_route_snapshot_serialized(
                    worker_token=worker_token,
                    timeout_seconds=None,
                )
        deadline = time.monotonic() + max(0.0, float(timeout_seconds))
        acquired = self._runtime_route_snapshot_refresh_lock.acquire(
            timeout=max(0.0, float(timeout_seconds))
        )
        if not acquired:
            return None
        try:
            remaining = deadline - time.monotonic()
            if remaining <= 0.0:
                return None
            return self._refresh_runtime_route_snapshot_serialized(
                worker_token=worker_token,
                timeout_seconds=remaining,
            )
        finally:
            self._runtime_route_snapshot_refresh_lock.release()

    @staticmethod
    def _core_inventory_from_route_snapshot(
        snapshot: CoreLoadedRouteSnapshot,
        *,
        provider_version: str = "",
    ) -> CoreInventorySnapshot:
        """Project the exact TIER3-AUTO membership accepted by this Core.

        The Manager's durable pool is deliberately not consulted here.  A
        missing group/readback therefore remains an empty, unverified runtime
        inventory instead of silently turning 10 loaded leaves into 11/11.
        """

        refs_by_name = {
            ref.proxy_name: ref
            for ref in snapshot.proxy_nodes
            if str(ref.tier or "").casefold() == "tier3"
        }
        groups = {state.name: state for state in snapshot.group_states}
        members: list[RuntimeNodeRef] = []
        seen_groups: set[str] = set()
        seen_refs: set[tuple[str, str, str, str]] = set()

        def collect(name: str) -> None:
            member_name = str(name or "").strip()
            if not member_name or builtin_terminal_kind(member_name):
                return
            ref = refs_by_name.get(member_name)
            if ref is not None:
                if ref.key not in seen_refs:
                    seen_refs.add(ref.key)
                    members.append(ref)
                return
            if member_name in seen_groups:
                return
            group = groups.get(member_name)
            if group is None:
                return
            seen_groups.add(member_name)
            for child in group.members:
                collect(child)

        root = groups.get("TIER3-AUTO")
        if root is not None:
            seen_groups.add(root.name)
            for child in root.members:
                collect(child)
        return CoreInventorySnapshot(
            process_pid=int(snapshot.process_pid),
            process_generation=int(snapshot.process_generation),
            core_generation=int(snapshot.core_generation),
            semantic_digest=str(snapshot.semantic_digest),
            route_epoch=int(snapshot.route_epoch),
            provider_version=str(provider_version or ""),
            members=tuple(members),
            captured_at_monotonic=time.monotonic(),
        )

    def _refresh_loaded_runtime_authority(
        self,
        *,
        timeout_seconds: float = 0.75,
        require_managed_final_exit: bool = True,
        worker_token: tuple[int, ...] | None = None,
    ) -> tuple[
        CoreLoadedRouteSnapshot,
        dict[str, Any],
        RuntimeRouteBinding | None,
    ] | None:
        """Bounded controller readback after Core load/ApplyConfig.

        The retry cadence is intentionally small and finite.  A caller must
        publish a terminal controller hold when this returns ``None``; it may
        not start a neutral probe against an unknown leaf.
        """

        deadline = time.monotonic() + max(
            0.05,
            min(
                _INITIAL_EGRESS_AUTHORITY_READBACK_SECONDS,
                float(timeout_seconds),
            ),
        )
        retry_delays = (0.0, 0.05, 0.15, 0.30, 0.50)
        for delay in retry_delays:
            if delay > 0.0:
                remaining = deadline - time.monotonic()
                if remaining <= 0.0:
                    break
                stop_event = getattr(self, "stop_event", None)
                if stop_event is not None and stop_event.wait(min(delay, remaining)):
                    return None
            remaining = deadline - time.monotonic()
            if remaining <= 0.0:
                break
            try:
                refreshed = self._refresh_runtime_route_snapshot(
                    worker_token=worker_token,
                    timeout_seconds=min(0.30, remaining),
                )
            except Exception:
                refreshed = None
            snapshot, payload = self._runtime_route_snapshot_state()
            if (
                refreshed is None
                or snapshot is None
                or not isinstance(payload, dict)
                or tuple(refreshed.snapshot_key) != tuple(snapshot.snapshot_key)
            ):
                continue
            binding = self._runtime_route_binding_for_outbound(
                snapshot,
                payload,
                "FINAL-EXIT",
            )
            if require_managed_final_exit and binding is None:
                continue
            return snapshot, payload, binding
        return None

    def _refresh_runtime_route_snapshot_serialized(
        self,
        *,
        worker_token: tuple[int, ...] | None = None,
        timeout_seconds: float | None = None,
    ) -> CoreLoadedRouteSnapshot | None:

        runner = self.core_runner
        if runner is None or not runner.is_running():
            return None
        status = runner.status()
        pid = int(status.get("pid") or 0)
        process_generation = int(status.get("process_generation") or 0)
        if pid <= 0 or process_generation <= 0:
            return None
        with self._runtime_route_snapshot_lock:
            loaded_contract_owner = self._runtime_loaded_export_contract
            loaded_contract = copy.deepcopy(
                loaded_contract_owner
            )
            route_authority_epoch = int(self._runtime_route_epoch)
        if not isinstance(loaded_contract, dict):
            return None
        loaded_revision = int(loaded_contract.get("revision") or 0)
        loaded_owner_id = id(loaded_contract_owner)
        proxies_payload = self._mihomo_proxies_bounded(timeout_seconds)
        if worker_token is not None and not self._runtime_worker_token_is_current(
            worker_token
        ):
            return None
        latest_status = runner.status()
        if (
            int(latest_status.get("pid") or 0) != pid
            or int(latest_status.get("process_generation") or 0)
            != process_generation
        ):
            return None
        proxy_map = loaded_contract.get("proxy_map")
        if not isinstance(proxy_map, dict):
            return None
        graph, selection, group_states = self._runtime_group_graph_and_selection(
            proxies_payload
        )
        selection = self._runtime_final_exit_selection_signature(
            proxies_payload,
            proxy_map,
        )
        # An incident-owned append-only Provider rebase expands candidate
        # capacity without changing the selected logical route.  Preserve the
        # pre-rebase route authority key across subsequent controller readback;
        # the full combined digest remains in the loaded contract for inventory
        # auditing and is replaced normally on the next Core reload.
        semantic_digest = str(
            loaded_contract.get("route_authority_semantic_digest")
            or loaded_contract.get("semantic_digest")
            or ""
        )
        if not semantic_digest:
            return None
        with self._core_lifecycle_lock:
            core_generation = int(self._core_generation)
        with self._runtime_route_snapshot_lock:
            current_contract = self._runtime_loaded_export_contract
            if (
                int(self._runtime_route_epoch) != route_authority_epoch
                or not isinstance(current_contract, dict)
                or (
                    loaded_revision > 0
                    and int(current_contract.get("revision") or 0)
                    != loaded_revision
                )
                or (
                    loaded_revision <= 0
                    and id(current_contract) != loaded_owner_id
                )
            ):
                # `/proxies` and the exact loaded export contract were not
                # observed in the same successful Core-load/route-authority
                # revision.  In particular, a selector write or Core stop may
                # have revoked this read while the controller was blocked.
                return None
            previous = self._runtime_route_snapshot
            previous_selection = self._runtime_route_selection_signature
            ownership_changed = bool(
                previous is None
                or previous.process_pid != pid
                or previous.process_generation != process_generation
                or previous.core_generation != core_generation
            )
            if (
                self._runtime_route_epoch <= 0
                or ownership_changed
                or selection != previous_selection
            ):
                self._runtime_route_epoch += 1
                self._node_judgement_arm_epoch("refresh_runtime_route_snapshot_serialized")
            selection_changed = bool(
                previous_selection and selection != previous_selection
            )
            now = time.monotonic()
            if selection_changed:
                self._runtime_route_attribution_barrier_until = now + 2.0
            if (
                selection_changed
                or float(
                    getattr(
                        self,
                        "_runtime_route_attribution_barrier_until",
                        0.0,
                    )
                    or 0.0
                )
                > now
            ):
                # Carry an application-owned mutation barrier across the
                # snapshot invalidation/refresh epoch. Late errors from dials
                # created on the old selection must not punish the new leaf.
                self._runtime_route_attribution_barrier_epoch = int(
                    self._runtime_route_epoch
                )
            self._runtime_route_selection_signature = selection
            refs = tuple(
                RuntimeNodeRef(
                    tier=str(info.get("tier") or ""),
                    pool_kind=str(info.get("pool_kind") or ""),
                    identity=str(info.get("identity") or ""),
                    proxy_name=str(proxy_name),
                )
                for proxy_name, info in proxy_map.items()
                if str(info.get("identity") or "")
            )
            snapshot = CoreLoadedRouteSnapshot(
                process_pid=pid,
                process_generation=process_generation,
                core_generation=core_generation,
                semantic_digest=semantic_digest,
                route_epoch=int(self._runtime_route_epoch),
                network_context_epoch=int(
                    getattr(self, "_runtime_network_context_epoch", 0) or 0
                ),
                group_graph=graph,
                group_states=group_states,
                proxy_nodes=refs,
                loaded_at_monotonic=time.monotonic(),
            )
            self._runtime_route_snapshot = snapshot
            self._runtime_route_snapshot_payload = {
                "proxies": copy.deepcopy(proxies_payload),
                "proxy_map": dict(proxy_map),
            }
            self._runtime_unknown_provider_refresh_key = None
            self._runtime_core_inventory_snapshot = (
                self._core_inventory_from_route_snapshot(
                    snapshot,
                    provider_version=str(
                        loaded_contract.get("provider_semantic_digest")
                        or loaded_contract.get("provider_version")
                        or ""
                    ),
                )
            )
            self._runtime_egress_coordinator.set_current_snapshot(snapshot)
        if selection_changed and not self._runtime_uses_early_single_coordinator():
            self._disarm_runtime_recovery(
                "Core FINAL-EXIT logical selection changed"
            )
            self._wake_runtime_facility_rebaseline(
                "FINAL-EXIT logical selection changed"
            )
        activation_lock = getattr(self, "_tier3_egress_activation_lock", None)
        if activation_lock is None:
            controller_hold_was_active = False
            controller_hold_failure_key = None
        else:
            with activation_lock:
                controller_hold_was_active = bool(
                    getattr(
                        self,
                        "_tier3_standby_activation_hold_kind",
                        "",
                    )
                    == "controller_hold"
                )
                controller_hold_failure_key = getattr(
                    self,
                    "_tier3_standby_activation_failure_key",
                    None,
                )
        stop_event = getattr(self, "stop_event", None)
        if (
            controller_hold_was_active
            and not (stop_event is not None and stop_event.is_set())
            and controller_hold_failure_key
            != self._tier3_standby_activation_key()
        ):
            # Only a materially different immutable authority may reopen a
            # controller hold. Re-reading the same route is useful telemetry,
            # but it must not recreate the same recovery transaction on every
            # monitor tick.
            self._reset_tier3_standby_activation_failure()
            self._queue_tier3_egress_activation()
        self._observe_published_runtime_route_view(snapshot, proxies_payload)
        return snapshot

    def _runtime_tier3_route_view(
        self,
        snapshot: CoreLoadedRouteSnapshot,
        proxies_payload: Any,
    ) -> dict[str, Any] | None:
        """TIER3-AUTO as the loaded Core reports it (P0-3 / P0-5; no I/O)."""

        state = snapshot.group_state("TIER3-AUTO")
        if state is None:
            return None
        # Either the controller response (publication hooks) or the stored
        # publication wrapper (admission): one accessor for both.
        raw_entries = mihomo_proxies_entries(proxies_payload)
        # Counts read the ledger overlay: a member rebuilt by a provider write
        # reads alive-by-default in Mihomo until it is tested, which must
        # neither inflate the count nor (carried) collapse it.  Narrow
        # embedders without the verified-write helpers read the raw payload.
        overlay = getattr(self, "_overlay_tier3_route_payload", None)
        verified_check = getattr(self, "_tier3_verified_provider_writes_enabled", None)
        verified = bool(callable(verified_check) and callable(overlay) and verified_check())
        entries = (
            mihomo_proxies_entries(overlay(proxies_payload)) if verified else raw_entries
        )
        members = node_judgement_contract_order(state.members)
        test_url = str(state.test_url or "")
        alive = sum(
            1
            for member in members
            if node_judgement_member_alive(entries.get(member), test_url)
        )
        verdict_seen = not verified or any(
            isinstance(raw_entries.get(member), dict)
            and isinstance(
                ((raw_entries[member].get("extra") or {}).get(test_url) or {}).get("alive"),
                bool,
            )
            for member in members
        )
        fixed = str(state.fixed or "")
        return {
            "group": str(state.name),
            "now": str(state.now or ""),
            "fixed": fixed,
            "members": tuple(state.members),
            "alive": int(alive),
            "loaded": len(members),
            # Mihomo never health-checks a pin that names a non-member: it
            # serves proxies[0] blind until a DELETE (Conf-7).
            "stale_fixed": bool(fixed) and fixed not in tuple(state.members),
            # Every loaded member Core-dead for the contract: Mihomo serves
            # proxies[0] regardless (F13).  Not before any real verdict exists
            # (a fresh Core whose startup check has not run yet).
            "exhausted": bool(members) and alive == 0 and verdict_seen,
        }

    def _observe_published_runtime_route_view(
        self,
        snapshot: CoreLoadedRouteSnapshot,
        proxies_payload: Any,
    ) -> None:
        """Node-judgement hooks at route-snapshot publication; never raises.

        Runs under the snapshot refresh lock, so it only reads the payload that
        was just published: the evidence line (P0-5) and the decision to queue
        one stale-pin release (P0-3) cost no controller call.
        """

        try:
            # Route lease: keep the published fixed/alive state (never raises).
            # A pinned member rebuilt by a provider write reads its carried
            # verdict, not Mihomo's alive-by-default (the pin's own truth).
            overlay = getattr(self, "_overlay_tier3_route_payload", None)
            self._route_lease_observe_snapshot(
                snapshot,
                overlay(proxies_payload) if callable(overlay) else proxies_payload,
            )
            self._node_judgement_arm_observe("publish")
            policy = self._node_judgement_policy()
            if policy.ladder_on:
                # Tier ladder view line and overshoot detection (no I/O).
                self._runtime_ladder_observe_publish(snapshot, proxies_payload, policy)
            if policy.acts and policy.exhausted_pool_reexport:
                # Fix 1 (10-28; judge act + exhausted_pool_reexport): exhausted /
                # frozen group.
                self._runtime_pool_reexport_observe(snapshot, proxies_payload, policy)
            # A stale pin serves proxies[0] with no alive check; verified
            # provider writes always release it (the policy switch predates
            # them and stays the legacy default).
            verified_check = getattr(self, "_tier3_verified_provider_writes_enabled", None)
            release_stale = bool(
                policy.release_stale_fallback_pins
                or (callable(verified_check) and verified_check())
            )
            if not (policy.evidence_log or release_stale):
                return
            view = self._runtime_tier3_route_view(snapshot, proxies_payload)
            if view is None:
                return
            if policy.evidence_log:
                self._log_runtime_route_view(snapshot, view)
            if release_stale and view["stale_fixed"]:
                self._queue_stale_fallback_pin_release(snapshot, view)
        except Exception:
            logger = getattr(self, "logger", None)
            if isinstance(logger, logging.Logger):
                log_raw_diagnostic(
                    logger,
                    "debug",
                    "Runtime route view evidence was skipped",
                    exc_info=True,
                )

    # -- Fixes 1 and 2 (10-28): exhausted / frozen TIER3-AUTO, own keys --

    def _runtime_post_dial_exhausted_admission(
        self,
        judge: PostDialJudgeService,
        leaf: str,
    ) -> bool:
        """Fix 2: True (and the EXHAUSTED hold is set) when the published
        TIER3-AUTO view that loads ``leaf`` has no alive member.

        Called only from the act admission; no I/O.  Fix 1's re-export is
        what then refreshes the group; an answered TIER3 user connection
        releases the hold as for a verdict hold."""

        try:
            policy = self._node_judgement_policy()
            if not (policy.acts and policy.exhausted_hold):
                return False
            snapshot, payload = self._runtime_post_dial_route_refs()
            if snapshot is None or not isinstance(payload, dict):
                return False
            # ``payload`` is the stored publication wrapper
            # {"proxies": <GET /proxies response>, "proxy_map": ...}; hand the
            # view the controller response it is published with (10-30 fix:
            # the wrapper itself made every member read dead, so every act
            # trigger was gated exhausted_hold in ship2).
            view = self._runtime_tier3_route_view(snapshot, payload.get("proxies"))
            if view is None or not view["exhausted"] or leaf not in view["members"]:
                return False
            judge.enter_exhausted_hold(leaf, "group_exhausted")
            return True
        except Exception:
            return False

    def _runtime_pool_reexport_observe(
        self,
        snapshot: CoreLoadedRouteSnapshot,
        proxies_payload: Any,
        policy: Any,
    ) -> None:
        """Fix 1: at publication (under the snapshot lock, no I/O), start one
        bounded re-export of the Tier3 pool when the loaded TIER3-AUTO group
        is exhausted, or keeps <= POOL_REEXPORT_MAX_ALIVE alive members (the
        worker then also needs the healthy pool to exceed the loaded members
        by POOL_REEXPORT_MIN_SURPLUS).  At most once per
        POOL_REEXPORT_INTERVAL_S; never probes."""

        view = self._runtime_tier3_route_view(snapshot, proxies_payload)
        if view is None or not view["loaded"]:
            return
        constants = policy.constants()
        if not (
            view["exhausted"]
            or int(view["alive"]) <= int(constants.pool_reexport_max_alive)
        ):
            return
        now = self._runtime_recovery_now()
        lock = self.__dict__.setdefault("_runtime_pool_reexport_lock", threading.Lock())
        with lock:
            last = self.__dict__.get("_runtime_pool_reexport_at")
            if last is not None and now - float(last) < float(constants.pool_reexport_interval_s):
                return
            running = self.__dict__.get("_runtime_pool_reexport_thread")
            if running is not None and running.is_alive():
                return
            self._runtime_pool_reexport_at = now
            thread = threading.Thread(
                target=self._runtime_pool_reexport_worker,
                args=(dict(view), constants),
                name="desktop-post-dial-pool-reexport",
                daemon=True,
            )
            self._runtime_pool_reexport_thread = thread
        thread.start()

    def _runtime_pool_reexport_worker(self, view: dict[str, Any], constants: Any) -> None:
        """Fix 1 worker: the existing provider sync (``semantic_change``),
        through ``_sync_core_config_after_pool_update`` as the pool sync
        worker runs it.  ``allow_live_rebase`` passes the online cohort
        freeze only; an initial activation, a runtime recovery transaction or
        an open judgement / ladder skips it, and the provider update keeps
        its own reload-gate lease and recovery check."""

        record: dict[str, Any] = {
            "ev": "pool_reexport",
            "t": round(time.time(), 3),
            "alive": int(view["alive"]),
            "loaded": int(view["loaded"]),
            "exhausted": bool(view["exhausted"]),
        }
        try:
            healthy = -1
            try:
                healthy = int(self._tier3_core_gate_check()[1])
            except Exception:
                healthy = -1
            record["healthy"] = healthy
            state = self._node_judgement_state()
            judge = getattr(state, "judge", None)
            frozen = healthy - int(view["loaded"]) >= int(constants.pool_reexport_min_surplus)
            if not (view["exhausted"] or frozen):
                record["outcome"] = "skipped_pool_not_larger"
            elif self.stop_event.is_set():
                record["outcome"] = "skipped_stopping"
            elif not (
                self._current_core_runtime_phase() in {"formal_capture", "formal_no_capture"}
                and self._runtime_initial_activation_was_completed()
            ):
                record["outcome"] = "skipped_not_online"
            elif self._tier3_initial_activation_transaction_active():
                record["outcome"] = "skipped_initial_activation"
            elif self._runtime_recovery_transaction_active():
                record["outcome"] = "skipped_recovery_active"
            elif judge is not None and (judge.judging() or judge.ladder_in_flight()):
                record["outcome"] = "skipped_judging"
            elif callable(getattr(self, "_tier3_verified_lane_open", None)) and self._tier3_verified_lane_open():
                # Verified lane: the pool-sync worker is the only online
                # provider writer, and it already replaces dead members and
                # moves off a dead pick.  Fix 1 only asks it to run now.
                queued = self._queue_tier3_pool_sync_after_commit(
                    immediate=True,
                    sync_event="semantic_change",
                )
                record["outcome"] = "queued" if queued else "already_current"
            else:
                outcome = self._sync_core_config_after_pool_update(allow_live_rebase=True)
                disposition = getattr(outcome, "disposition", None)
                record["outcome"] = str(getattr(disposition, "value", disposition) or "unknown")
                if disposition is ProviderSyncDisposition.COMMITTED:
                    self._record_tier3_core_sync_event("semantic_change")
        except Exception as exc:
            record["outcome"] = "error_" + type(exc).__name__
        self._log_runtime_post_dial_record("info", record)

    def _log_runtime_route_view(
        self,
        snapshot: CoreLoadedRouteSnapshot,
        view: dict[str, Any],
    ) -> None:
        """One hashed route-view line, only when the view changes (P0-5)."""

        state = self._node_judgement_state()
        key = (
            int(snapshot.process_pid),
            int(snapshot.core_generation),
            view["now"],
            view["fixed"],
            view["alive"],
            view["loaded"],
            view["stale_fixed"],
            view["exhausted"],
        )
        with state.lock:
            if state.route_view_key == key:
                return
            state.route_view_key = key
        logger = getattr(self, "logger", None)
        if not isinstance(logger, logging.Logger):
            return
        tokenizer = state.tokenizer
        log_raw_diagnostic(
            logger,
            "info",
            "Runtime route view (group=%s now=%s fixed=%s alive=%d/%d "
            "stale_fixed=%s exhausted=%s core_generation=%d)",
            view["group"],
            tokenizer.leaf(view["now"]) if view["now"] else "none",
            tokenizer.leaf(view["fixed"]) if view["fixed"] else "none",
            int(view["alive"]),
            int(view["loaded"]),
            bool(view["stale_fixed"]),
            bool(view["exhausted"]),
            int(snapshot.core_generation),
        )

    # -- Tier ladder: route view line and overshoot_repair (spec §4.11, §6.2) --

    def _runtime_ladder_observe_publish(
        self,
        snapshot: CoreLoadedRouteSnapshot,
        proxies_payload: Any,
        policy: NodeJudgementPolicy | None = None,
    ) -> None:
        """``tier_ladder_judge`` on only; runs under the snapshot refresh lock.

        O(groups), no I/O and no lock beyond the caller's: the
        ``Runtime ladder view`` line on each change of (PF now, PF fixed,
        path codes, leaf), and the overshoot candidate test (attribute reads
        and one Event set; never a thread start).
        """

        try:
            if policy is None:
                policy = self._node_judgement_policy()
            if not policy.ladder_on or snapshot is None:
                return
            graph = dict(snapshot.group_graph)
            names = frozenset(graph)
            pf = snapshot.group_state(tier_ladder.PROXY_FALLBACK)
            route = inspect_runtime_route(proxies_payload, start="FINAL-EXIT")
            chain = tuple(str(item) for item in (route.get("selected_chain") or ()))
            leaf = str(route.get("leaf_proxy") or "")
            pf_now = str(getattr(pf, "now", "") or "")
            pf_fixed = str(getattr(pf, "fixed", "") or "")
            path = tuple(tier_ladder.group_code(name, group_names=names) for name in chain)
            key = (pf_now, pf_fixed, path, leaf)
            if self.__dict__.get("_runtime_ladder_view_key") != key:
                self._runtime_ladder_view_key = key
                logger = getattr(self, "logger", None)
                if isinstance(logger, logging.Logger):
                    tokenizer = self._node_judgement_state().tokenizer
                    log_raw_diagnostic(
                        logger,
                        "info",
                        "Runtime ladder view (pf_now=%s pf_fixed=%s path=%s leaf=%s "
                        "core_generation=%d route_epoch=%d)",
                        tier_ladder.group_code(pf_now, group_names=names) if pf_now else "none",
                        tier_ladder.group_code(pf_fixed, group_names=names) if pf_fixed else "none",
                        ",".join(path) or "-",
                        tokenizer.leaf(leaf) if leaf else "none",
                        int(snapshot.core_generation),
                        int(snapshot.route_epoch),
                    )
            previous = self.__dict__.get("_runtime_ladder_pf_seen")
            self._runtime_ladder_pf_seen = (int(snapshot.core_generation), pf_now)
            if (
                policy.overshoot_on
                and isinstance(previous, tuple)
                and previous[0] == int(snapshot.core_generation)
                and previous[1]
                and pf_now
                and previous[1] != pf_now
            ):
                self._runtime_overshoot_detect(snapshot, pf, chain, graph, previous[1], pf_now)
        except Exception:
            return

    def _runtime_overshoot_detect(
        self,
        snapshot: CoreLoadedRouteSnapshot,
        pf: Any,
        chain: tuple[str, ...],
        graph: dict[str, Any],
        previous: str,
        new: str,
    ) -> bool:
        """Spec §6.2 detection: lock-free; a candidate sets the pending
        tuple and the worker's Event (never starts the worker)."""

        readiness = getattr(self, "_runtime_egress_readiness", None)
        if getattr(readiness, "state", None) is not RuntimeEgressReadinessState.READY:
            return False
        if int(getattr(self, "_runtime_initial_activation_generation", -1) or -1) != int(
            snapshot.core_generation
        ):
            return False
        if chain[:2] != (tier_ladder.FINAL_EXIT, tier_ladder.PROXY_FALLBACK) or any(
            part in _POST_DIAL_GATEWAY_GROUPS for part in chain
        ):
            return False
        if pf is None or str(pf.fixed or ""):
            return False
        viable = tier_ladder.viable_members(tier_ladder.PROXY_FALLBACK, graph)
        if previous not in viable or new not in viable or viable.index(new) <= viable.index(previous):
            return False
        episode = (int(snapshot.route_epoch), previous, new)
        seen = self.__dict__.get("_runtime_overshoot_seen")
        if not isinstance(seen, dict):
            seen = self.__dict__.setdefault("_runtime_overshoot_seen", {})
        if episode in seen:
            return False
        if len(seen) >= 64:
            seen.pop(next(iter(seen)), None)
        seen[episode] = True
        # ``judge.ladder_in_flight()`` without its lock: a plain attribute read.
        judge = getattr(self.__dict__.get("_node_judgement_runtime_state"), "judge", None)
        self._runtime_overshoot_pending = (
            previous,
            new,
            episode,
            time.monotonic(),
            getattr(judge, "_ladder_job", None) is not None,
        )
        event = self.__dict__.get("_runtime_overshoot_event")
        if event is None:
            event = self.__dict__.setdefault("_runtime_overshoot_event", threading.Event())
        event.set()
        return True

    def _runtime_overshoot_ensure_worker(self) -> bool:
        """Start ``runtime-post-dial-overshoot`` if needed (observer thread or
        ``ladder_end``; never the publish path).  Never raises."""

        try:
            if not self._node_judgement_policy().overshoot_on:
                return False
            stop_event = getattr(self, "stop_event", None)
            if stop_event is not None and stop_event.is_set():
                return False
            lock = self.__dict__.get("_runtime_overshoot_lock")
            if lock is None:
                lock = self.__dict__.setdefault("_runtime_overshoot_lock", threading.Lock())
            with lock:
                thread = self.__dict__.get("_runtime_overshoot_thread")
                event = self.__dict__.get("_runtime_overshoot_event")
                if event is None:
                    event = self.__dict__.setdefault("_runtime_overshoot_event", threading.Event())
                if thread is not None and thread.is_alive():
                    old_token = self.__dict__.get("_runtime_overshoot_thread_token")
                    if old_token is not None and self._runtime_worker_token_is_current(old_token):
                        return True
                    # A stale parked worker: wake it (it exits without
                    # consuming the wake) and start a current one.
                    event.set()
                token = tuple(self._runtime_worker_token())
                if not self._runtime_worker_token_is_current(token):
                    return False  # a worker would exit at its first wake
                thread = threading.Thread(
                    target=self._runtime_overshoot_run,
                    args=(token, event),
                    name="runtime-post-dial-overshoot",
                    daemon=True,
                )
                self._runtime_overshoot_thread = thread
                self._runtime_overshoot_thread_token = token
                pending = self.__dict__.get("_runtime_overshoot_pending")
                if pending is not None and pending is not self.__dict__.get("_runtime_overshoot_handled"):
                    event.set()
                thread.start()
            return True
        except Exception:
            return False

    def _runtime_overshoot_run(self, token: tuple[int, ...], event: threading.Event) -> None:
        """The worker: waits with no timeout; exits on stop, a new worker
        token or ``overshoot_repair`` off at a wake."""

        stop_event = getattr(self, "stop_event", None)
        while True:
            event.wait()
            cleared = False
            try:
                if (
                    (stop_event is not None and stop_event.is_set())
                    or not self._runtime_worker_token_is_current(token)
                    or not self._node_judgement_policy().overshoot_on
                ):
                    # Exit without clearing: the wake stays for the next worker.
                    return
                event.clear()
                cleared = True
                pending = self.__dict__.get("_runtime_overshoot_pending")
                if pending is not None and pending is not self.__dict__.get("_runtime_overshoot_handled"):
                    self._runtime_overshoot_evaluate(pending, stop_event, token)
            except Exception:
                if not cleared:
                    event.clear()
                logger = getattr(self, "logger", None)
                if isinstance(logger, logging.Logger):
                    log_raw_diagnostic(logger, "debug", "Overshoot repair step failed", exc_info=True)

    def _runtime_overshoot_wait(self, seconds: float, stop_event: Any) -> bool:
        """Sleep ``seconds``; True when the runtime stopped meanwhile."""

        if seconds <= 0.0:
            return False
        if stop_event is not None:
            return bool(stop_event.wait(seconds))
        time.sleep(seconds)
        return False

    def _runtime_overshoot_evaluate(
        self, pending: tuple[Any, ...], stop_event: Any, token: tuple[int, ...] | None = None
    ) -> None:
        """Worker steps 1-7 for one candidate (spec §6.2)."""

        previous, new, episode, detected_at, _during_ladder = pending
        if self._route_lease_ladder_in_flight():
            # Kept: ``ladder_end`` signals the Event again.
            return
        # max(t, ladder_end_t) whether the ladder was in flight at detection
        # or started after it (``ladder_end_t`` older than t changes nothing).
        settle_from = max(
            float(detected_at),
            float(self.__dict__.get("_runtime_overshoot_ladder_end_t") or detected_at),
        )
        if self._runtime_overshoot_wait(settle_from + 1.0 - time.monotonic(), stop_event):
            return
        if token is not None and not self._runtime_worker_token_is_current(token):
            return  # a stale worker: the current worker evaluates the candidate
        if self.__dict__.get("_runtime_overshoot_pending") is not pending:
            return  # a newer candidate replaced it; its own wake handles it
        if self._route_lease_ladder_in_flight():
            return
        # Claimed once under the lock (a replacement worker may be in the
        # same settle wait); marked handled, never cleared: detection
        # (lock-free, the only writer of ``_runtime_overshoot_pending``) can
        # never be overwritten.
        lock = self.__dict__.get("_runtime_overshoot_lock")
        if lock is None:
            lock = self.__dict__.setdefault("_runtime_overshoot_lock", threading.Lock())
        with lock:
            if self.__dict__.get("_runtime_overshoot_handled") is pending:
                return
            self._runtime_overshoot_handled = pending
        decision = self._runtime_overshoot_decide(previous, new, episode, detected_at, stop_event)
        state, reason, probe_class, elapsed_ms, now_after = decision
        snapshot, _payload = self._runtime_post_dial_route_refs()
        names = frozenset(dict(getattr(snapshot, "group_graph", ()) or ()))
        self._log_runtime_post_dial_record(
            "info",
            {
                "ev": "overshoot_repair",
                "t": round(time.time(), 3),
                "state": state,
                "reason": reason,
                "from": tier_ladder.group_code(previous, group_names=names),
                "to": tier_ladder.group_code(new, group_names=names),
                "class": probe_class,
                "ms": elapsed_ms,
                "now_after": now_after,
                "episode": int(episode[0]),
            },
        )

    def _runtime_overshoot_decide(
        self,
        previous: str,
        new: str,
        episode: tuple[Any, ...],
        detected_at: float,
        stop_event: Any,
    ) -> tuple[str, str, str, Any, str]:
        """``(state, reason, class, ms, now_after)`` for the record."""

        skipped = ("skipped", "", "-", None, "-")
        snapshot, payload = self._runtime_post_dial_route_refs()
        pf = snapshot.group_state(tier_ladder.PROXY_FALLBACK) if snapshot is not None else None
        if pf is None or not isinstance(payload, dict) or str(pf.now or "") != new or str(pf.fixed or ""):
            return ("skipped", "superseded") + skipped[2:]
        last_probe = self.__dict__.get("_runtime_overshoot_last_judge_pf_probe")
        if last_probe is not None and float(last_probe) >= float(detected_at) - 10.0:
            return ("skipped", "judge_pf_probe") + skipped[2:]
        lock = getattr(self, "_runtime_failure_monitor_lock", None)
        with lock if lock is not None else nullcontext():
            lease = getattr(self, "_runtime_route_mutation_lease", None)
        if (
            isinstance(lease, dict) and str(lease.get("group") or "") == tier_ladder.PROXY_FALLBACK
        ) or self._runtime_post_dial_d4_txn_busy() is not None:
            return ("skipped", "d4_busy") + skipped[2:]
        now_mono = time.monotonic()
        history = [
            at for at in list(self.__dict__.get("_runtime_overshoot_history") or ())
            if now_mono - float(at) < 600.0
        ]
        done = self.__dict__.get("_runtime_overshoot_done")
        if not isinstance(done, dict):
            done = self.__dict__.setdefault("_runtime_overshoot_done", {})
        if (history and now_mono - float(history[-1]) < 30.0) or len(history) >= 6 or episode in done:
            return ("skipped", "cap") + skipped[2:]
        route = inspect_runtime_route(payload.get("proxies"), start=previous)
        leaf = str(route.get("leaf_proxy") or "")
        owning = None
        for layer in reversed(list(route.get("layers") or [])):
            state = snapshot.group_state(str(layer.get("name") or ""))
            if state is not None and tier_ladder.is_fallback(state.type_name):
                owning = state
                break
        if not leaf or owning is None or not str(owning.test_url or ""):
            return ("skipped", "subtree_dead") + skipped[2:]
        try:
            entry = self._require_api_client().proxy(leaf, timeout=_POST_DIAL_CONTROLLER_TIMEOUT_SECONDS)
        except Exception:
            entry = None
        if not node_judgement_member_alive(entry, str(owning.test_url)):
            return ("skipped", "subtree_dead") + skipped[2:]
        timeouts = self._runtime_loaded_group_timeouts(snapshot)
        timeout_ms = timeouts.get(tier_ladder.PROXY_FALLBACK) if isinstance(timeouts, dict) else None
        if (
            type(timeout_ms) is not int
            or timeout_ms <= 0
            or not str(pf.test_url or "")
            or not str(pf.expected_status or "")
        ):
            return ("skipped", "contract_unavailable") + skipped[2:]
        if not self._node_judgement_policy().acts:
            return ("would_probe", "shadow", "-", None, "-")
        if len(done) >= 64:
            done.pop(next(iter(done)), None)
        done[episode] = True
        history.append(now_mono)
        self._runtime_overshoot_history = history
        probe_class, elapsed_ms = self._runtime_overshoot_probe(previous, pf, int(timeout_ms))
        before = self.__dict__.get("_runtime_route_snapshot")
        deadline = time.monotonic() + 5.0
        while self.__dict__.get("_runtime_route_snapshot") is before and time.monotonic() < deadline:
            if self._runtime_overshoot_wait(0.25, stop_event):
                break
        if self.__dict__.get("_runtime_route_snapshot") is before:
            # No publication within 5 s: the pre-probe PF member is not a
            # post-probe fact (spec §4.11 ``now_after=-``).
            return ("probed", "subtree_alive", probe_class, elapsed_ms, "-")
        after, _after_payload = self._runtime_post_dial_route_refs()
        after_pf = after.group_state(tier_ladder.PROXY_FALLBACK) if after is not None else None
        after_now = str(getattr(after_pf, "now", "") or "")
        names = frozenset(dict(getattr(after, "group_graph", ()) or ()))
        now_after = tier_ladder.group_code(after_now, group_names=names) if after_now else "none"
        return ("probed", "subtree_alive", probe_class, elapsed_ms, now_after)

    def _runtime_overshoot_probe(self, member: str, pf: Any, timeout_ms: int) -> tuple[str, Any]:
        """One brokered no-write PF-contract probe of ``member`` (1.9 s
        admission, RUNTIME_MANUAL): ``(class, elapsed ms)``."""

        window = tier_ladder.probe_request_window_s(timeout_ms) + _POST_DIAL_PROBE_CLEANUP_SECONDS
        admission = tier_ladder.LADDER_PROBE_ADMISSION_S
        issued = time.monotonic()
        admitted: list[float] = []

        def run(execution: ProbeExecutionContext | None) -> dict[str, Any]:
            admitted.append(time.monotonic())
            return self._probe_proxy_delay_with_urls_leased(
                str(member),
                [str(pf.test_url)],
                timeout_ms=int(timeout_ms),
                request_timeout_seconds=window,
                expected_status=str(pf.expected_status),
                execution_context=execution,
            )

        try:
            result = self._run_brokered_runtime_probe(
                run,
                priority=ProbePriority.RUNTIME_MANUAL,
                queue_timeout_seconds=admission,
                socket_start_timeout_seconds=0.5,
                execution_deadline_monotonic=(
                    issued + admission + window + _NATIVE_GROUP_ROUND_DISPATCH_SECONDS
                ),
            )
            probe = (
                NodeJudgementProbeClass.PASS
                if isinstance(result, dict)
                else NodeJudgementProbeClass.INDETERMINATE
            )
        except MihomoDelayStatusMismatch:
            probe = NodeJudgementProbeClass.HTTP_ANSWER
        except MihomoDelayTransportFailed:
            probe = NodeJudgementProbeClass.TRANSPORT_FAIL
        except MihomoDelayTimeout:
            probe = NodeJudgementProbeClass.TIMEOUT
        except Exception:
            probe = NodeJudgementProbeClass.INDETERMINATE
        started = admitted[0] if admitted else issued
        elapsed = round((time.monotonic() - started) * 1000.0, 1) if admitted else None
        return str(getattr(probe, "value", probe)), elapsed

    def _queue_stale_fallback_pin_release(
        self,
        snapshot: CoreLoadedRouteSnapshot,
        view: dict[str, Any],
    ) -> bool:
        """Queue one release of a TIER3-AUTO pin naming a non-member (P0-3).

        Once per (Core generation, group, name).  Only after READY: startup
        admission owns route writes until then and takes no Core mutation
        lease.  A pin that names a member is never touched.
        """

        fixed = str(view.get("fixed") or "")
        group = str(view.get("group") or "")
        if not fixed or not group or fixed in tuple(view.get("members") or ()):
            return False
        stop_event = getattr(self, "stop_event", None)
        if stop_event is not None and stop_event.is_set():
            return False
        try:
            ready = self._runtime_initial_activation_complete()
        except Exception:
            ready = False
        if not ready:
            return False
        key = (int(snapshot.core_generation), group, fixed)
        # The selector intent this publication was read under.  A user
        # selection declares a newer intent before it waits for the Core
        # lock, so the release can never erase a pin set after this point.
        selector_intent_revision = int(
            getattr(self, "_runtime_selector_intent_revision", 0) or 0
        )
        state = self._node_judgement_state()
        with state.lock:
            if (
                key in state.stale_pin_released
                or key in state.stale_pin_inflight
                or state.stale_pin_retry_after.get(key, 0.0) > time.monotonic()
            ):
                return False
            state.stale_pin_inflight.add(key)
        try:
            threading.Thread(
                target=self._release_stale_fallback_pin,
                args=(snapshot, key),
                kwargs={"selector_intent_revision": selector_intent_revision},
                name="runtime-stale-pin-release",
                daemon=True,
            ).start()
        except Exception:
            with state.lock:
                state.stale_pin_inflight.discard(key)
            raise
        return True

    def _release_stale_fallback_pin(
        self,
        snapshot: CoreLoadedRouteSnapshot,
        key: tuple[int, str, str],
        *,
        selector_intent_revision: int | None = None,
    ) -> str:
        """One DELETE plus readback, serialised like every automatic write.

        The Core mutation lease and then the shared Core lock are both taken
        without waiting (the existing order: lease, then lock); either one
        busy backs off.  User selections and reloads take only the Core lock,
        so holding it makes the pre-read and the DELETE one step for them.
        Immediately before the pre-read and again before the DELETE the
        selector intent captured at publication, the lease and the published
        snapshot must all still be current, so a pin set by a user or a reload
        after the publication is never erased.
        """

        _core_generation, group, fixed = key
        state = self._node_judgement_state()
        intent_revision = (
            int(getattr(self, "_runtime_selector_intent_revision", 0) or 0)
            if selector_intent_revision is None
            else int(selector_intent_revision)
        )
        # ``settled``: this key is decided for this Core generation (released,
        # attempted, or no longer a stale non-member pin).  Anything else is
        # retried at a later publication after a short back-off.
        settled = False
        delete_attempted = False
        outcome = "skipped"
        try:
            current, payload = self._runtime_route_snapshot_state()
            if (
                current is None
                or not isinstance(payload, dict)
                or tuple(current.snapshot_key) != tuple(snapshot.snapshot_key)
                or int(getattr(self, "_runtime_selector_intent_revision", 0) or 0)
                != intent_revision
            ):
                outcome = "superseded"
                return outcome
            binding = self._runtime_route_binding_for_outbound(
                current,
                payload,
                "FINAL-EXIT",
            )
            if not isinstance(binding, RuntimeRouteBinding):
                outcome = "unbound"
                return outcome
            coordinator = self._runtime_egress_coordinator
            lease = coordinator.begin_core_mutation(
                binding,
                expected_snapshot=current,
                timeout_seconds=0.0,
            )
            if lease is None:
                # A Core transaction owns the route: never wait on it here.
                outcome = "lease_busy"
                return outcome
            request_error = ""
            client: Any = None
            try:
                core_lock = getattr(self, "_core_transition_lock", None)
                if core_lock is not None and not core_lock.acquire(
                    blocking=False
                ):
                    # A user selection or reload owns the Core: back off.
                    outcome = "core_busy"
                    return outcome
                try:

                    def still_owned() -> bool:
                        if int(
                            getattr(self, "_runtime_selector_intent_revision", 0)
                            or 0
                        ) != intent_revision:
                            return False
                        if not coordinator.core_mutation_lease_is_current(lease):
                            return False
                        with self._runtime_route_snapshot_lock:
                            loaded = self._runtime_route_snapshot
                            return bool(
                                loaded is not None
                                and tuple(loaded.snapshot_key)
                                == tuple(snapshot.snapshot_key)
                            )

                    if not still_owned():
                        outcome = "superseded"
                        return outcome
                    client = self._require_api_client()
                    before = client.proxy(group, timeout=0.35)
                    before_members = (
                        before.get("all") if isinstance(before, dict) else None
                    )
                    if (
                        not isinstance(before, dict)
                        or str(before.get("fixed") or "") != fixed
                        or not isinstance(before_members, (list, tuple))
                        or fixed in [str(item) for item in before_members]
                    ):
                        # The pin changed, or it names a member: never touched.
                        settled = True
                        outcome = "not_stale"
                        return outcome
                    if not still_owned():
                        # A newer selector intent or route landed during the
                        # pre-read: its pin is not ours to clear.
                        outcome = "superseded"
                        return outcome
                    settled = True
                    delete_attempted = True
                    try:
                        try:
                            client.unfix_proxy(group, timeout=0.35)
                        except TypeError:
                            client.unfix_proxy(group)
                    except Exception as exc:
                        # DELETE may have committed; the one readback decides.
                        request_error = type(exc).__name__
                    # An application-owned selection change: revoke the
                    # snapshot exactly as the automatic fixed-route release
                    # does, so late dial errors from the old pick are not
                    # charged to the new one.
                    with self._runtime_route_snapshot_lock:
                        self._runtime_route_epoch += 1
                        self._node_judgement_arm_epoch("release_stale_fallback_pin")
                        self._mark_runtime_route_attribution_barrier_locked()
                        self._runtime_route_snapshot = None
                        self._runtime_route_snapshot_payload = None
                        self._runtime_core_inventory_snapshot = None
                        self._runtime_route_selection_signature = ()
                    coordinator.set_current_snapshot(None)
                finally:
                    if core_lock is not None:
                        core_lock.release()
            finally:
                coordinator.end_core_mutation(lease)
            # The readback only reports the outcome, so it runs after both
            # locks are released: a concurrent D4 transaction is blocked for
            # the pre-read and the DELETE alone.
            readback: Any = None
            try:
                readback = client.proxy(group, timeout=0.35)
            except Exception:
                readback = None
            if not isinstance(readback, dict) or "fixed" not in readback:
                outcome = "unknown"
            elif str(readback.get("fixed") or ""):
                outcome = "not_committed"
            else:
                outcome = "released"
            if request_error and outcome != "released":
                outcome = f"{outcome}:{request_error}"
            self._queue_runtime_route_snapshot_refresh()
            return outcome
        except Exception as exc:
            outcome = f"error:{type(exc).__name__}"
            return outcome
        finally:
            with state.lock:
                state.stale_pin_inflight.discard(key)
                if settled:
                    if len(state.stale_pin_released) >= _STALE_FALLBACK_PIN_KEYS_MAX:
                        state.stale_pin_released.clear()
                    state.stale_pin_released.add(key)
                    state.stale_pin_retry_after.pop(key, None)
                else:
                    if len(state.stale_pin_retry_after) >= _STALE_FALLBACK_PIN_KEYS_MAX:
                        state.stale_pin_retry_after.clear()
                    state.stale_pin_retry_after[key] = (
                        time.monotonic() + _STALE_FALLBACK_PIN_RETRY_SECONDS
                    )
            logger = getattr(self, "logger", None)
            if isinstance(logger, logging.Logger) and outcome not in {
                "superseded",
                "lease_busy",
                "core_busy",
            }:
                log_raw_diagnostic(
                    logger,
                    "info",
                    "Stale fallback pin release (group=%s fixed=%s outcome=%s)",
                    group,
                    state.tokenizer.leaf(fixed),
                    outcome,
                )

    def _queue_runtime_route_snapshot_refresh(self) -> None:
        route_lock = getattr(self, "_runtime_route_snapshot_lock", None)
        if route_lock is None:
            return
        with route_lock:
            if getattr(self, "_runtime_route_snapshot_refresh_running", False):
                return
            self._runtime_route_snapshot_refresh_running = True
            self._runtime_route_snapshot_refresh_starts = (
                int(getattr(self, "_runtime_route_snapshot_refresh_starts", 0) or 0) + 1
            )
        # A post-dial refresh's cause, set just before this call (diagnostic).
        post_dial_origin = self._take_post_dial_refresh_origin()
        worker_token = self._runtime_worker_token()

        def worker() -> None:
            try:
                if self._runtime_worker_token_is_current(worker_token):
                    refreshed = self._refresh_runtime_route_snapshot(
                        worker_token=worker_token,
                        timeout_seconds=0.75,
                    )
                    if refreshed is not None and post_dial_origin:
                        self._count_post_dial_refresh("judge_refresh_worker_started")
                    if refreshed is not None:
                        self._try_arm_runtime_recovery()
                        self._maybe_carry_runtime_ready("route_refresh")
            except Exception:
                log_raw_diagnostic(
                    self.logger,
                    "warning",
                    "Could not refresh the Core-loaded runtime route snapshot",
                    exc_info=True,
                )
            finally:
                with self._runtime_route_snapshot_lock:
                    self._runtime_route_snapshot_refresh_running = False

        threading.Thread(
            target=worker,
            name="runtime-route-snapshot-refresh",
            daemon=True,
        ).start()

    def _runtime_route_snapshot_state(
        self,
    ) -> tuple[CoreLoadedRouteSnapshot | None, dict[str, Any] | None]:
        with self._runtime_route_snapshot_lock:
            payload = self._runtime_route_snapshot_payload
            return (
                self._runtime_route_snapshot,
                copy.deepcopy(payload) if isinstance(payload, dict) else None,
            )

    def _mark_runtime_route_attribution_barrier_locked(self) -> None:
        """Start the old-flow attribution guard while holding the route lock."""

        self._runtime_route_attribution_barrier_epoch = int(
            getattr(self, "_runtime_route_epoch", 0) or 0
        )
        self._runtime_route_attribution_barrier_until = time.monotonic() + 2.0

    def _runtime_route_attribution_barrier_active(
        self,
        snapshot: CoreLoadedRouteSnapshot,
        observed_at_monotonic: float,
    ) -> bool:
        route_lock = getattr(self, "_runtime_route_snapshot_lock", None)
        if route_lock is None:
            return False
        with route_lock:
            return bool(
                int(snapshot.route_epoch)
                == int(
                    getattr(
                        self,
                        "_runtime_route_attribution_barrier_epoch",
                        0,
                    )
                    or 0
                )
                and float(observed_at_monotonic)
                <= float(
                    getattr(
                        self,
                        "_runtime_route_attribution_barrier_until",
                        0.0,
                    )
                    or 0.0
                )
            )

    @staticmethod
    def _runtime_snapshot_node(
        snapshot: CoreLoadedRouteSnapshot,
        proxy_name: str,
    ) -> RuntimeNodeRef | None:
        matches = [
            ref for ref in snapshot.proxy_nodes if ref.proxy_name == str(proxy_name)
        ]
        return matches[0] if len(matches) == 1 else None

    def _runtime_route_binding_for_outbound(
        self,
        snapshot: CoreLoadedRouteSnapshot,
        snapshot_payload: dict[str, Any],
        outbound: str,
        *,
        require_final_exit: bool = True,
    ) -> RuntimeRouteBinding | None:
        proxies_payload = snapshot_payload.get("proxies")
        route = inspect_runtime_route(proxies_payload, start=str(outbound or "FINAL-EXIT"))
        if route.get("facility_failure"):
            return None
        chain = tuple(str(item) for item in route.get("selected_chain", []) or [])
        if require_final_exit and "FINAL-EXIT" not in chain and str(outbound) != "FINAL-EXIT":
            return None
        leaf = str(route.get("leaf_proxy") or "")
        if not leaf or builtin_terminal_kind(leaf):
            return None
        ref = self._runtime_snapshot_node(snapshot, leaf)
        if ref is None:
            return None
        return RuntimeRouteBinding(
            process_pid=snapshot.process_pid,
            process_generation=snapshot.process_generation,
            core_generation=snapshot.core_generation,
            semantic_digest=snapshot.semantic_digest,
            route_epoch=snapshot.route_epoch,
            observed_outbound=str(outbound or "FINAL-EXIT"),
            route_chain=chain,
            node=ref,
            network_context_epoch=snapshot.network_context_epoch,
        )

    def _bind_runtime_transport_failure(
        self,
        parsed: Any,
        snapshot: CoreLoadedRouteSnapshot,
        snapshot_payload: dict[str, Any],
    ) -> BoundRuntimeFailure | None:
        outbound = str(getattr(parsed, "observed_outbound", "") or "")
        binding = self._runtime_route_binding_for_outbound(
            snapshot,
            snapshot_payload,
            outbound,
        )
        if binding is None and outbound:
            # Mihomo may log only the inner dialer-proxy group used by a fixed
            # Gateway.  Bind that signal only when the immutable loaded graph
            # proves the currently selected Gateway depends on this exact
            # underlay; arbitrary listener/source groups remain unowned.
            final_binding = self._runtime_route_binding_for_outbound(
                snapshot,
                snapshot_payload,
                "FINAL-EXIT",
            )
            if (
                final_binding is not None
                and final_binding.node.pool_kind == "gateway"
            ):
                underlay = self._runtime_gateway_underlay_binding(
                    snapshot,
                    snapshot_payload,
                    final_binding.node,
                )
                if underlay is not None and underlay.observed_outbound == outbound:
                    binding = underlay
        if binding is None:
            return None
        return BoundRuntimeFailure.from_parsed(parsed, binding)

    def _reset_runtime_failure_monitor_state(self) -> None:
        probe_broker = getattr(self, "_runtime_probe_broker", None)
        if probe_broker is None or bool(getattr(probe_broker, "stopped", False)):
            self._runtime_probe_broker = RuntimeProbeBroker(
                max_active_sockets=2,
            )
        local_facility_state = getattr(
            self,
            "_runtime_local_facility_state",
            None,
        )
        if local_facility_state is not None:
            with getattr(
                self,
                "_runtime_local_facility_lock",
                nullcontext(),
            ):
                local_facility_state.reset()
        with self._runtime_failure_monitor_lock:
            self._runtime_recovery_arm = None
            self._runtime_monitoring_lease = None
            self._runtime_passive_refresh_key = None
            self._runtime_passive_refresh_until = 0.0
            self._runtime_passive_recheck_times = {}
            self._runtime_route_mutation_lease = None
            self._runtime_recovery_arm_refresh_at = 0.0
            self._runtime_initial_activation_generation = -1
            self._initial_egress_activation_deferred = False
            self._initial_egress_activation_deferred_core_generation = -1
            self._runtime_failure_guard_probe_last_at = 0.0
            self._runtime_path_watch_last_at = 0.0
            self._runtime_internal_probe_windows.clear()
            self._runtime_failure_probe_bindings.clear()
            self._runtime_failure_recovery_bindings.clear()
            self._runtime_facility_confirmation_tokens.clear()
            self._runtime_facility_fail_closed_running = False
            self._runtime_facility_fail_closed_pending = None
            self._runtime_incident_bindings.clear()
            self._runtime_incident_route_payloads.clear()
            self._runtime_recheck_retry_attempts.clear()
            self._runtime_incident_recovery_state.clear()
            self._runtime_incident_provider_rebases.clear()
            self._runtime_core_stopped_recovery_owners.clear()
            self._runtime_pending_recovered_payloads.clear()
            self._runtime_fail_closed_admissions.clear()
            self._runtime_failback_export_holds.clear()
            self._runtime_deferred_failbacks.clear()
            self._runtime_deferred_provisional_confirmations.clear()
            self._runtime_origin_diagnostic_bindings.clear()
            self._runtime_pending_confirmed_incidents.clear()
            with self._runtime_route_snapshot_lock:
                with self._runtime_hot_standby_lock:
                    self._runtime_hot_standby_evidence.clear()
                    self._runtime_hot_standby_last_probe_at = 0.0
                    self._runtime_hot_standby_next_index = 0
                    self._runtime_hot_standby_last_traffic_totals = (0, 0)
                    self._runtime_hot_standby_was_active = False
                    self._runtime_hot_standby_pending_unknown_activity = False
                    # Zero means that no real business traffic or maintenance
                    # loop has been observed. A slow bootstrap must not look
                    # like user activity or a sleep/resume gap.
                    self._runtime_hot_standby_last_active_at = 0.0
                    self._runtime_hot_standby_last_loop_at = 0.0
                    self._runtime_local_facility_fault_reason = ""
                    self._runtime_network_context_signature_value = ""
                    self._runtime_network_context_candidate_signature = ""
                    self._runtime_network_context_candidate_count = 0
                    self._runtime_network_context_invalid_observed = False
                    self._runtime_network_context_hold_active = False
                    self._runtime_network_context_hold_pending_candidate = False
                    self._runtime_network_context_hold_reason = ""
                    self._runtime_network_context_hold_epoch = 0
                    self._runtime_network_context_rebase_stage = 0
                    self._runtime_network_context_rebase_at = 0.0
                    self._runtime_facility_epoch = int(
                        getattr(self, "_runtime_facility_epoch", 0) or 0
                    ) + 1
                    self._runtime_network_context_epoch = int(
                        getattr(self, "_runtime_network_context_epoch", 0) or 0
                    ) + 1
                    self._runtime_route_attribution_barrier_epoch = 0
                    self._runtime_route_attribution_barrier_until = 0.0
                    self._runtime_route_snapshot = None
                    self._runtime_route_snapshot_payload = None
                    self._runtime_core_inventory_snapshot = None
                    self._runtime_route_selection_signature = ()
                    self._runtime_confirmed_fail_closed_snapshot_key = None
                    self._runtime_pending_export_contract = None
                    self._runtime_loaded_export_contract = None
        # Node judgement P1-3: the observer never outlives its monitoring
        # lease.  It was normally signalled when its Core stopped; this joins
        # it.  After the lease is cleared, so a racing commit of the old lease
        # cannot start a new observer behind this stop.
        self._stop_runtime_post_dial_observer(
            "monitor_reset",
            join_timeout=_POST_DIAL_OBSERVER_JOIN_SECONDS,
        )
        qualification_lock = getattr(
            self,
            "_tier3_runtime_qualification_lock",
            None,
        )
        if qualification_lock is not None:
            with qualification_lock:
                self._tier3_runtime_final_exit_ok = False
                self._tier3_runtime_final_exit_core_generation = -1
                self._tier3_selected_leaf_evidence = None
                self._tier3_runtime_qualification_monitor_at = 0.0
                self._tier3_runtime_last_revalidation_key = None
        self._reset_tier3_standby_activation_failure()
        self._runtime_egress_coordinator.restart(current_snapshot=None)
        reload_gate = getattr(self, "_runtime_reload_gate", None)
        if reload_gate is not None:
            reload_gate.reset_for_new_core("")
            self._runtime_reload_gate_core_generation = -1
        manager = self.manager
        clear = getattr(manager, "clear_runtime_health_observations", None)
        if callable(clear):
            try:
                clear()
            except Exception:
                log_raw_diagnostic(
                    self.logger,
                    "warning",
                    "Could not clear obsolete runtime health observations",
                    exc_info=True,
                )

    def _node_judgement_arm_trace(self, key: str, value: Any) -> None:
        local = self.__dict__.get("_node_judgement_arm_local")
        trace = getattr(local, "trace", None)
        if isinstance(trace, dict):
            trace[key] = value

    @contextmanager
    def _node_judgement_arm_capture(self):
        local = self.__dict__.setdefault("_node_judgement_arm_local", threading.local())
        previous = getattr(local, "trace", None)
        trace: dict[str, Any] = {}
        local.trace = trace
        try:
            yield trace
        finally:
            local.trace = previous

    def _node_judgement_arm_initial_check(self) -> str | None:
        with self._node_judgement_arm_capture() as trace:
            ready = self._runtime_initial_activation_complete()
        return None if ready else str(trace.get("initial_check") or "override_unknown")

    def _node_judgement_arm_reject(self, check: str, **facts: Any) -> bool:
        self._node_judgement_arm_trace("refusal", str(check))
        self._node_judgement_arm_trace("refusal_facts", facts)
        return False

    def _node_judgement_arm_begin(self):
        """A token before an existing read; no policy or runtime-lock access."""
        try:
            life = self.__dict__.setdefault("_node_judgement_arm_lifecycle",
                {"lock": threading.Lock(), "generation": 0, "mode_enabled": None})
            with life["lock"]:
                return life, life["generation"]
        except Exception:
            return None

    def _node_judgement_arm_disable_locked(self, life: Any) -> None:
        life["generation"] += 1
        state = self.__dict__.get("_node_judgement_arm_diagnostics_state")
        if state is not None:
            state["enabled"] = False
            state["generation"] = life["generation"]
            state["queue"].clear()
            for scope in state["scopes"].values():
                scope["bad"] = True
            state["scopes"].clear()
            state.update(arm={}, refusal=None, cache={}, suppressed=0)
            state["wakeup"].set()

    def _node_judgement_arm_mode_observed(self, enabled: bool, read_token: Any = None) -> None:
        """Bind the original mode result to its pre-read diagnostic generation."""
        try:
            token = read_token if read_token is not None else self._node_judgement_arm_begin()
            if token is None:
                return
            life, generation = token
            with life["lock"]:
                if not enabled:
                    life["mode_enabled"] = False
                    self._node_judgement_arm_disable_locked(life)
                elif generation == life["generation"]:
                    if life["mode_enabled"] is False:
                        life["generation"] += 1
                    life["mode_enabled"] = True
        except Exception:
            pass

    def _node_judgement_arm_permit(self):
        """One existing diagnostic policy read, yielding an immutable ticket."""
        try:
            token = self._node_judgement_arm_begin()
            if token is None:
                return None
            life, generation = token
            enabled = self._node_judgement_policy().observer_enabled
            with life["lock"]:
                if not enabled:
                    self._node_judgement_arm_disable_locked(life)
                    return None
                if generation != life["generation"] or life["mode_enabled"] is False:
                    return None
                state = self.__dict__.get("_node_judgement_arm_diagnostics_state")
                if state is None:
                    state = {"lock": life["lock"], "enabled": False, "worker": None,
                             "queue": [], "scopes": {}, "seq": 0, "loss": 0,
                             "wakeup": threading.Event()}
                    self.__dict__["_node_judgement_arm_diagnostics_state"] = state
                if not state["enabled"]:
                    state["queue"].clear()
                    state["scopes"].clear()
                    state.update(enabled=True, generation=generation,
                                 instance="rt-" + os.urandom(8).hex(), seq=0, loss=0,
                                 arm={}, refusal=None, cache={}, suppressed=0, announced=False)
                return state, generation, state["instance"]
        except Exception:
            return None

    def _node_judgement_arm_diagnostics(self) -> dict[str, Any] | None:
        ticket = self._node_judgement_arm_permit()
        return None if ticket is None else ticket[0]

    @staticmethod
    def _node_judgement_arm_valid_locked(ticket: Any, scope: Any = None) -> bool:
        if ticket is None:
            return False
        state, generation, instance = ticket
        valid = (state["enabled"] and state["generation"] == generation
                 and state["instance"] == instance)
        if scope is not None:
            valid = (valid and scope["state"] is state
                     and scope["ticket"][1:] == ticket[1:])
            if not valid:
                scope["bad"] = True
        return bool(valid)

    def _node_judgement_arm_scope(self) -> dict[str, Any] | None:
        try:
            ticket = self._node_judgement_arm_permit()
            if ticket is None:
                return None
            state = ticket[0]
            with state["lock"]:
                if not self._node_judgement_arm_valid_locked(ticket):
                    return None
                scope = {"state": state, "ticket": ticket, "instance": ticket[2],
                         "observer": "ob-" + os.urandom(8).hex(),
                         "scope": "sc-" + os.urandom(8).hex(), "produced": 0,
                         "emitted": 0, "contiguous": 0, "acked": set(), "loss": 0,
                         "active": 0, "retired": False, "fenced": False,
                         "source_started": False,
                         "bad": len(state["scopes"]) >= 16, "last": {},
                         "policy_revision": 0, "actual_rules": ()}
                if not scope["bad"]:
                    state["scopes"][scope["scope"]] = scope
                return scope
        except Exception:
            return None

    def _node_judgement_arm_prepare(self, record: dict[str, Any], scope: Any = None,
                                    *, ticket: Any = False):
        if ticket is False:
            ticket = self._node_judgement_arm_permit()
        if ticket is None:
            return None
        state = ticket[0]
        with state["lock"]:
            if not self._node_judgement_arm_valid_locked(ticket, scope):
                return None
            if not state["announced"]:
                state["announced"] = True
                state["seq"] += 1
                state["queue"].append((ticket, {"ev": "arm_diagnostics_state", "v": 1,
                    "t": round(time.time(), 3), "mono_ns": time.monotonic_ns(),
                    "instance": ticket[2], "seq": state["seq"],
                    "state": "started", "loss_total": state["loss"]}, None, 0))
            state["seq"] += 1
            fields = dict(record)
            fields.setdefault("t", round(time.time(), 3))
            fields.update(v=1, mono_ns=time.monotonic_ns(), instance=ticket[2],
                          seq=state["seq"], loss_total=state["loss"])
            number = 0
            if scope is not None:
                scope["produced"] += 1
                number = scope["produced"]
                if scope["retired"] and not scope["active"]:
                    scope["bad"] = True
                fields.update(observer=scope["observer"], scope=scope["scope"], scope_seq=number)
            if fields.get("ev") in {"trigger", "would_trigger"} and "mode" in fields:
                fields["mode"] = fields.pop("mode")
            return ticket, fields, scope, number

    def _node_judgement_arm_ack(self, ticket: Any, scope: Any, number: int, ok: bool) -> None:
        state = ticket[0]
        with state["lock"]:
            if not self._node_judgement_arm_valid_locked(ticket, scope):
                return
            if not ok:
                state["loss"] += 1
            if scope is None:
                return
            if not ok:
                scope["loss"] += 1
                return
            scope["emitted"] += 1
            if len(scope["acked"]) >= 1024:
                scope["bad"] = True
            else:
                scope["acked"].add(number)
                while scope["contiguous"] + 1 in scope["acked"]:
                    scope["contiguous"] += 1
                    scope["acked"].remove(scope["contiguous"])

    @staticmethod
    def _node_judgement_arm_keepalive_locked(state: Any) -> bool:
        # Only registered sources/producers of this generation can keep a
        # worker waiting. Allocating a scope alone is not a source start.
        return any(scope["ticket"][1:] == (state["generation"], state["instance"])
                   and ((scope["source_started"] and not scope["retired"])
                        or scope["active"] > 0)
                   for scope in state["scopes"].values())

    def _node_judgement_arm_kick(self, state: Any) -> None:
        # One bounded retry only when a failed start straddled a generation.
        for _attempt in range(2):
            with state["lock"]:
                state["wakeup"].set()
                if not state["enabled"] or state["worker"] is not None:
                    return
                if not state["queue"] and not self._node_judgement_arm_keepalive_locked(state) and not any(
                        scope["retired"] and not scope["active"] and not scope["fenced"]
                        for scope in state["scopes"].values()):
                    return
                generation = state["generation"]
                worker = threading.Thread(target=self._node_judgement_arm_drain, args=(state,),
                                          name="post-dial-arm-diagnostics", daemon=True)
                state["worker"] = worker
            try:
                worker.start()
                return
            except Exception:
                with state["lock"]:
                    if state["worker"] is not worker:
                        return
                    state["worker"] = None
                    if state["generation"] == generation:
                        state["loss"] += len(state["queue"])
                        for _ticket, _fields, scope, _number in state["queue"]:
                            if scope is not None:
                                scope["loss"] += 1
                        state["queue"].clear()
                        return
                    # A new generation's pending queue belongs to that
                    # generation. The failed old start may not erase it.

    def _node_judgement_arm_submit(self, record: dict[str, Any], scope: Any = None,
                                  *, ticket: Any = False) -> None:
        try:
            prepared = self._node_judgement_arm_prepare(record, scope, ticket=ticket)
            if prepared is None:
                return
            ticket, fields, scope, number = prepared
            state = ticket[0]
            with state["lock"]:
                if not self._node_judgement_arm_valid_locked(ticket, scope):
                    return
                full = len(state["queue"]) >= 1024
                if not full:
                    state["queue"].append((ticket, fields, scope, number))
            if full:
                self._node_judgement_arm_ack(ticket, scope, number, False)
            self._node_judgement_arm_kick(state)
        except Exception:
            return

    def _node_judgement_arm_drain(self, state: Any) -> None:
        """Dispatch under the diagnostic lock; logger and ack stay separate."""
        worker = threading.current_thread()
        while True:
            with state["lock"]:
                if not state["enabled"]:
                    if state["worker"] is worker:
                        state["worker"] = None
                    return
                fence = None
                waiting = False
                if state["queue"]:
                    ticket, fields, scope, number = state["queue"].pop(0)
                    if not self._node_judgement_arm_valid_locked(ticket, scope):
                        continue
                else:
                    for candidate in state["scopes"].values():
                        if candidate["retired"] and not candidate["active"] and not candidate["fenced"]:
                            fence = candidate
                            break
                    if fence is None:
                        if self._node_judgement_arm_keepalive_locked(state):
                            state["wakeup"].clear()
                            waiting = True
                        else:
                            if state["worker"] is worker:
                                state["worker"] = None
                            return
                    else:
                        ticket = fence["ticket"]
                        if not self._node_judgement_arm_valid_locked(ticket, fence):
                            state["scopes"].pop(fence["scope"], None)
                            continue
                        fence["fenced"] = True
                        state["seq"] += 1
                        fields = {"ev": "admission_fence", "v": 1,
                                  "t": round(time.time(), 3), "mono_ns": time.monotonic_ns(),
                                  "seq": state["seq"], "instance": ticket[2],
                                  "observer": fence["observer"], "scope": fence["scope"],
                                  "cut_t": fence["cut_t"], "cut_mono_ns": fence["cut_mono_ns"],
                                  "final_produced_seq": fence["produced"],
                                  "final_emitted_seq": fence["contiguous"],
                                  "emitted_count": fence["emitted"], "loss_total": fence["loss"],
                                  "inflight_before_cut": 0, "closed": True,
                                  "complete": not fence["bad"] and not fence["loss"]
                                  and fence["contiguous"] == fence["produced"]}
                        scope, number = None, 0
            if waiting:
                state["wakeup"].wait()
                continue
            ok = False
            try:
                self._log_runtime_post_dial_record("info", {**fields, "_arm_enveloped": True})
                ok = True
            except Exception:
                pass
            if fence is None:
                self._node_judgement_arm_ack(ticket, scope, number, ok)
            else:
                with state["lock"]:
                    if (self._node_judgement_arm_valid_locked(ticket, fence)
                            and state["scopes"].get(fence["scope"]) is fence):
                        state["scopes"].pop(fence["scope"], None)
                    fence["last"].clear()

    def _node_judgement_arm_retire(self, scope: Any) -> None:
        if scope is None:
            return
        state = scope["state"]
        with state["lock"]:
            scope.update(retired=True, cut_t=round(time.time(), 3), cut_mono_ns=time.monotonic_ns())
            self._node_judgement_arm_valid_locked(scope["ticket"], scope)
        self._node_judgement_arm_kick(state)

    def _node_judgement_arm_observer_emit(self, level: str, record: Any, scope: Any) -> None:
        original = dict(record)
        event = original.get("ev")
        diagnostic = event in {"observer_started_context", "observer_policy"}
        if scope is None or event not in {
            "observer_started_context", "observer_stopped", "trigger", "would_trigger", "observer_policy"
        }:
            if not diagnostic:
                self._log_runtime_post_dial_record(level, {**original, "_arm_enveloped": True})
            return
        prepared = None
        try:
            ticket = self._node_judgement_arm_permit()
            if ticket is not None:
                state = ticket[0]
                with state["lock"]:
                    valid = self._node_judgement_arm_valid_locked(ticket, scope)
                    if valid:
                        fields = dict(original)
                        if event == "observer_started_context":
                            scope["source_started"] = True
                        if event == "observer_policy":
                            scope["policy_revision"] = int(fields.get("policy_revision") or 0)
                            scope["actual_rules"] = tuple(fields.get("actual_rules") or ())
                        if event in {"trigger", "would_trigger"}:
                            fields.update(actual_rules=scope["actual_rules"], policy_revision=scope["policy_revision"])
                if valid:
                    if event == "observer_policy":
                        self._node_judgement_arm_submit(fields, scope, ticket=ticket)
                        return
                    prepared = self._node_judgement_arm_prepare(fields, scope, ticket=ticket)
                    if prepared is not None:
                        # This lock boundary grants the synchronous metadata
                        # dispatch; an old business line itself is never lost.
                        with state["lock"]:
                            if not self._node_judgement_arm_valid_locked(ticket, scope):
                                prepared = None
        except Exception:
            prepared = None
        # A cancelled new context has no original business line to preserve.
        if diagnostic and prepared is None:
            return
        if prepared is None:
            self._log_runtime_post_dial_record(level, {**original, "_arm_enveloped": True})
            return
        ticket, fields, owner, number = prepared
        ok = False
        try:
            self._log_runtime_post_dial_record(level, {**fields, "_arm_enveloped": True})
            ok = True
        finally:
            try:
                self._node_judgement_arm_ack(ticket, owner, number, ok)
            except Exception:
                pass

    def _node_judgement_arm_trigger(self, scope: Any, trigger: Any, mode: str, tokenizer: Any) -> None:
        local = self.__dict__.setdefault("_node_judgement_arm_local", threading.local())
        previous = getattr(local, "scope", None)
        local.scope = scope
        if scope is not None:
            with scope["state"]["lock"]:
                scope["active"] += 1
                if scope["active"] > 1024 or scope["retired"]:
                    scope["bad"] = True
                self._node_judgement_arm_valid_locked(scope["ticket"], scope)
        try:
            self._on_runtime_post_dial_trigger(trigger, mode=mode, tokenizer=tokenizer)
        finally:
            local.scope = previous
            if scope is not None:
                with scope["state"]["lock"]:
                    scope["active"] -= 1
                    if scope["retired"] and not scope["active"]:
                        scope.update(cut_t=round(time.time(), 3), cut_mono_ns=time.monotonic_ns())
                self._node_judgement_arm_kick(scope["state"])

    def _node_judgement_arm_observe(self, site: str, *, armed: bool | None = None,
                                   check: str | None = None, captured: bool = False,
                                   ticket: Any = False) -> None:
        try:
            if ticket is False:
                # A captured old bool must never acquire a new-generation identity.
                ticket = None if captured else self._node_judgement_arm_permit()
            if ticket is None:
                return
            state = ticket[0]
            if not captured:
                snapshot, payload = self._runtime_post_dial_route_refs()
                with self._node_judgement_arm_capture() as trace:
                    armed = bool(self._runtime_recovery_is_armed(snapshot, route_state=(snapshot, payload)))
                check = str(trace.get("arm_check") or ("armed" if armed else "override_unknown"))
            check = check or ("armed" if armed else "override_unknown")
            now = time.monotonic()
            value = (armed, check)
            with state["lock"]:
                if not self._node_judgement_arm_valid_locked(ticket):
                    return
                previous = state["arm"].get("codex_arm")
                if previous is not None and previous[0] == value:
                    return
                since = 0.0 if previous is None else max(0.0, (now - previous[1]) * 1000.0)
                state["arm"]["codex_arm"] = (value, now)
            arm = getattr(self, "_runtime_recovery_arm", None)
            self._node_judgement_arm_submit({"ev": "arm_state", "armed": armed if armed is not None else "unknown",
                "check": check, "site": site, "route_epoch": int(getattr(self, "_runtime_route_epoch", 0) or 0),
                "arm_route_epoch": int(getattr(arm, "route_epoch", -1)), "predicate": "codex_arm",
                "since_ms": round(since, 1)}, ticket=ticket)
        except Exception:
            return

    def _node_judgement_arm_epoch(self, site: str) -> None:
        try:
            ticket = self._node_judgement_arm_permit()
            if ticket is None:
                return
            new = int(getattr(self, "_runtime_route_epoch", 0) or 0)
            arm = getattr(self, "_runtime_recovery_arm", None)
            self._node_judgement_arm_submit({"ev": "route_epoch", "site": site,
                "old": new - 1, "new": new, "armed_before": "unknown",
                "armed_before_check": "not_sampled_under_route_lock",
                "arm_route_epoch": int(getattr(arm, "route_epoch", -1))}, ticket=ticket)
        except Exception:
            return

    def _node_judgement_arm_try_result(self, result: bool, trace: dict[str, Any],
                                     *, ticket: Any = False) -> None:
        try:
            if ticket is False:
                ticket = self._node_judgement_arm_permit()
            if ticket is None:
                return
            state = ticket[0]
            if not result:
                check = str(trace.get("refusal") or "installed_then_unarmed:" + str(trace.get("arm_check") or "override_unknown"))
                now = time.monotonic()
                with state["lock"]:
                    if not self._node_judgement_arm_valid_locked(ticket):
                        return
                    previous = state["refusal"]
                    if previous is not None and previous[0] == check and now - previous[1] < 5.0:
                        state["refusal"] = (check, previous[1], previous[2] + 1)
                        state["suppressed"] += 1
                        emit = False
                        suppressed = 0
                    else:
                        suppressed = previous[2] if previous is not None and previous[0] == check else 0
                        state["refusal"] = (check, now, 0)
                        emit = True
                if emit:
                    arm = getattr(self, "_runtime_recovery_arm", None)
                    self._node_judgement_arm_submit({"ev": "arm_refused", "check": check,
                        "site": "try_arm", "route_epoch": int(getattr(self, "_runtime_route_epoch", 0) or 0),
                        "arm_route_epoch": int(getattr(arm, "route_epoch", -1)),
                        "suppressed": suppressed, **trace.get("refusal_facts", {})}, ticket=ticket)
            if "installed_armed" in trace:
                self._node_judgement_arm_observe("try_arm", armed=trace["installed_armed"],
                    check=trace.get("installed_check") or "armed", captured=True, ticket=ticket)
            elif "arm_check" in trace:
                self._node_judgement_arm_observe("try_arm", armed=trace["arm_check"] is None,
                    check=trace["arm_check"] or "armed", captured=True, ticket=ticket)
            else:
                self._node_judgement_arm_observe("try_arm", ticket=ticket)
        except Exception:
            return

    def _node_judgement_arm_admission(self, trigger: Any, judge: Any, reason: Any,
                                     *, check: str, source: str, evaluated: bool,
                                     ticket: Any = False) -> None:
        try:
            if ticket is False:
                ticket = self._node_judgement_arm_permit()
            if ticket is None:
                return
            state = ticket[0]
            local = self.__dict__.get("_node_judgement_arm_local")
            scope = getattr(local, "scope", None)
            leaf = judge.tokenizer.leaf(str(trigger.leaf))
            rule = str(trigger.kind)
            episode = int(getattr(trigger, "episode", 0) or 0)
            value = (episode, str(reason or "none"), check)
            with state["lock"]:
                if not self._node_judgement_arm_valid_locked(ticket, scope):
                    return
                if scope is not None:
                    key = (leaf, rule)
                    if scope["last"].get(key) == value:
                        return
                    scope["last"].pop(key, None)
                    if len(scope["last"]) >= 256:
                        scope["last"].pop(next(iter(scope["last"])))
                    scope["last"][key] = value
                revision = 0 if scope is None else scope["policy_revision"]
            self._node_judgement_arm_submit({"ev": "admission", "mode": "act", "leaf": leaf,
                "rule": rule, "episode": episode, "result": "active" if reason is None else "gated",
                "reason": str(reason or "none"), "predicate": "codex_arm",
                "arm_evaluated": bool(evaluated), "arm_check": check, "source": source,
                "observer": "unknown", "scope": "unknown", "scope_seq": 0,
                "policy_revision": revision}, scope, ticket=ticket)
        except Exception:
            return

    def _runtime_initial_activation_complete(self) -> bool:
        check = self._node_judgement_arm_initial_refusal()
        self._node_judgement_arm_trace("initial_check", check)
        return check is None

    def _node_judgement_arm_initial_refusal(self) -> str | None:
        readiness = getattr(self, "_runtime_egress_readiness", None)
        state = getattr(readiness, "state", None)
        if state is not RuntimeEgressReadinessState.READY:
            return "readiness_state"
        if bool(getattr(readiness, "validation_active", False)):
            return "validation_active"
        lifecycle_lock = getattr(self, "_core_lifecycle_lock", None)
        with lifecycle_lock if lifecycle_lock is not None else nullcontext():
            core_generation = int(getattr(self, "_core_generation", 0) or 0)
        if core_generation <= 0 or int(
            getattr(self, "_runtime_initial_activation_generation", -1) or -1
        ) != core_generation:
            # A replacement proof obtained inside startup admission is not yet
            # authority to expose capture or the live stdout circuit.
            return "activation_generation"
        manager = getattr(self, "manager", None)
        if manager is not None and hasattr(manager, "effective_egress_ok"):
            effective = getattr(manager, "effective_egress_ok", None)
            if effective is not True:
                return "effective_egress_ok_none" if effective is None else "effective_egress_ok_false"
        return None

    def _runtime_initial_activation_was_completed(self) -> bool:
        # A generation marker is only one field in the READY transaction. It
        # must never make standby look online before readiness, verified route
        # authority and effective data-plane truth have all committed.
        return self._runtime_initial_activation_complete()

    def _runtime_uses_early_single_coordinator(self) -> bool:
        """Whether production recovery is using the bounded rollback profile."""

        return bool(
            getattr(self, "_runtime_egress_recovery_profile", "")
            == _RUNTIME_EGRESS_RECOVERY_PROFILE_EARLY
        )

    def _disarm_runtime_recovery(self, reason: str = "") -> None:
        """Revoke live-failure authority without changing the physical route."""

        diag_ticket = self._node_judgement_arm_permit()
        lock = getattr(self, "_runtime_failure_monitor_lock", None)
        if lock is None:
            self._runtime_recovery_arm = None
        else:
            with lock:
                self._runtime_recovery_arm = None
        self._revoke_tier3_source_control_qualification(
            "verified_final_exit_revoked"
        )
        self._node_judgement_arm_observe("disarm", armed=False, check="no_arm", captured=True,
                                         ticket=diag_ticket)
        del reason

    def _commit_runtime_monitoring_lease(self) -> bool:
        """Commit observation permission only after the initial READY proof."""
        if not hasattr(self, "_runtime_monitoring_lease"):
            return False  # Older embedders do not install passive monitoring.
        if not self._runtime_initial_activation_complete():
            return False
        arm = getattr(self, "_runtime_recovery_arm", None)
        if not isinstance(arm, _RuntimeRecoveryArm) or not self._runtime_recovery_is_armed():
            return False
        # Node judgement P0-2: a native group round deferred by startup or the
        # post-capture replay runs once, right after READY.  Without a
        # deferred round this is a single attribute lookup.
        self._start_deferred_native_group_round()
        token = self._runtime_worker_token()
        lease = _RuntimeMonitoringLease(
            runtime_generation=int(self._runtime_generation),
            core_generation=int(self._core_generation),
            process_pid=int(token[3]),
            process_generation=int(token[4]),
            lifecycle_revision=int(getattr(self, "_lifecycle_revision", 0) or 0),
            admitted_at_monotonic=time.monotonic(),
        )
        with self._runtime_failure_monitor_lock:
            old = getattr(self, "_runtime_monitoring_lease", None)
            if isinstance(old, _RuntimeMonitoringLease) and (
                old.runtime_generation, old.core_generation, old.process_pid,
                old.process_generation, old.lifecycle_revision,
            ) == (
                lease.runtime_generation, lease.core_generation, lease.process_pid,
                lease.process_generation, lease.lifecycle_revision,
            ):
                committed = old
            else:
                self._runtime_monitoring_lease = lease
                committed = lease
        # Node judgement P1-3: the post-dial observer lives for exactly this
        # lease (shadow/act only).  Idempotent for an unchanged lease.
        self._ensure_runtime_post_dial_observer(committed)
        return True

    def _runtime_monitoring_is_active(self) -> bool:
        """Accept real errors while the admitted route is degraded or changed."""
        if not hasattr(self, "_runtime_monitoring_lease"):
            # Narrow embedders predating passive monitoring retain their arm.
            return self._runtime_recovery_is_armed()
        lease = self._runtime_monitoring_lease
        if (
            not isinstance(lease, _RuntimeMonitoringLease)
            or self.stop_event.is_set()
            or not egress_recovery_policy(self.config).enabled
            or int(getattr(self, "_runtime_generation", -1)) != lease.runtime_generation
            or int(getattr(self, "_core_generation", -1)) != lease.core_generation
            or int(getattr(self, "_lifecycle_revision", 0) or 0) != lease.lifecycle_revision
            or int(getattr(self, "_runtime_initial_activation_generation", -1))
            != lease.core_generation
        ):
            return False
        runner = getattr(self, "core_runner", None)
        try:
            status = runner.status() if runner is not None and runner.is_running() else {}
        except Exception:
            return False
        return bool(
            int(status.get("pid") or 0) == lease.process_pid
            and int(status.get("process_generation") or 0) == lease.process_generation
        )

    def _runtime_recovery_is_armed(
        self,
        snapshot: CoreLoadedRouteSnapshot | None = None,
        *,
        route_state: tuple[
            CoreLoadedRouteSnapshot | None,
            dict[str, Any] | None,
        ] | None = None,
    ) -> bool:
        check = self._node_judgement_arm_refusal(snapshot, route_state=route_state)
        self._node_judgement_arm_trace("arm_check", check)
        return check is None

    def _node_judgement_arm_refusal(
        self,
        snapshot: CoreLoadedRouteSnapshot | None = None,
        *,
        route_state: tuple[
            CoreLoadedRouteSnapshot | None,
            dict[str, Any] | None,
        ] | None = None,
    ) -> str | None:
        # ``route_state``: the published (snapshot, payload) the caller already
        # took under the route lock, read without a copy (the post-dial judge's
        # gates); omitted, the published state is read and copied here.
        if not hasattr(self, "_runtime_recovery_arm"):
            # Compatibility for narrow embedders/test doubles constructed
            # without DesktopRuntime.__init__. Real runtimes always own the
            # explicit arm and therefore always take the strict READY gate.
            return None
        lock = getattr(self, "_runtime_failure_monitor_lock", None)
        if lock is None:
            arm = getattr(self, "_runtime_recovery_arm", None)
        else:
            with lock:
                arm = getattr(self, "_runtime_recovery_arm", None)
        if not isinstance(arm, _RuntimeRecoveryArm):
            return "no_arm"
        initial_check = self._node_judgement_arm_initial_check()
        if initial_check is not None:
            return "initial_activation:" + initial_check
        if int(getattr(self, "_runtime_route_epoch", 0) or 0) != arm.route_epoch:
            return "route_epoch"
        if (
            not self._runtime_uses_early_single_coordinator()
            and int(getattr(self, "_runtime_facility_epoch", 0) or 0)
            != arm.facility_epoch
        ):
            return "facility_epoch"
        if int(
            getattr(self, "_runtime_selector_intent_revision", 0) or 0
        ) != arm.selector_intent_revision:
            return "selector_intent"
        if int(getattr(self, "_lifecycle_revision", 0) or 0) != arm.lifecycle_revision:
            return "lifecycle"
        if not self._runtime_worker_token_is_current(arm.worker_token):
            return "worker_token"
        local_snapshot, payload = (
            route_state
            if route_state is not None
            else self._runtime_route_snapshot_state()
        )
        coordinator_snapshot = self._runtime_egress_coordinator.current_route_snapshot()
        if local_snapshot is None or coordinator_snapshot is None or not isinstance(payload, dict):
            return "snapshot_missing"
        if tuple(local_snapshot.snapshot_key) != arm.snapshot_key:
            return "snapshot_key_local"
        if tuple(coordinator_snapshot.snapshot_key) != arm.snapshot_key:
            return "snapshot_key_coordinator"
        if snapshot is not None and tuple(snapshot.snapshot_key) != arm.snapshot_key:
            return "snapshot_key_caller"
        binding = self._runtime_route_binding_for_outbound(
            local_snapshot,
            payload,
            "FINAL-EXIT",
        )
        if binding is None:
            return "binding_none"
        if not local_snapshot.owns(binding):
            return "binding_not_owned"
        if tuple(binding.node.key) != arm.binding_key:
            return "binding_key"
        return None

    def _node_judgement_stale_arm_refresh_refusal(self, intent_revision: int) -> str | None:
        """Why a ``not_armed`` act admission may NOT queue a re-arming refresh.

        ``rearm_on_stale_route``: None only when the installed arm is stale
        by route epoch alone (a native leaf move published since it was
        installed) and ``_try_arm_runtime_recovery`` would accept a fresh
        route: no user selection (the admission's and the current intent
        revision both equal the arm's), same lifecycle, worker token and
        facility, no open recovery incident, no Tier3 controller hold.  A
        pure read: one failure-monitor lock acquisition for the arm and the
        incident states, every other read after it, no trace writes, no
        controller call.  The sole authority of the decision; the F01
        ``arm_check`` is only logged.
        """

        if not hasattr(self, "_runtime_recovery_arm"):
            return "compat"
        lock = getattr(self, "_runtime_failure_monitor_lock", None)
        with lock if lock is not None else nullcontext():
            arm = getattr(self, "_runtime_recovery_arm", None)
            states = tuple(
                str(value or "")
                for value in getattr(self, "_runtime_incident_recovery_state", {}).values()
            )
        if not isinstance(arm, _RuntimeRecoveryArm):
            return "no_arm"
        initial = self._node_judgement_arm_initial_refusal()
        if initial is not None:
            return "initial:" + initial
        if int(getattr(self, "_runtime_route_epoch", 0) or 0) == arm.route_epoch:
            return "epoch_current"
        if (
            not self._runtime_uses_early_single_coordinator()
            and int(getattr(self, "_runtime_facility_epoch", 0) or 0) != arm.facility_epoch
        ):
            return "facility_epoch"
        current_intent = int(getattr(self, "_runtime_selector_intent_revision", 0) or 0)
        if (
            arm.selector_intent_revision != int(intent_revision)
            or arm.selector_intent_revision != current_intent
        ):
            return "selector_intent"
        if int(getattr(self, "_lifecycle_revision", 0) or 0) != arm.lifecycle_revision:
            return "lifecycle"
        if not self._runtime_worker_token_is_current(arm.worker_token):
            return "worker_token"
        if any(state in {"pending", "recovering"} for state in states):
            return "incident"
        # Unlocked atomic read: never block the observer on the activation lock.
        if getattr(self, "_tier3_standby_activation_hold_kind", "") == "controller_hold":
            return "activation_hold"
        return None

    def _maybe_carry_runtime_ready(self, source: str) -> bool:
        """Decision D: carry the published READY to the route epoch a move produced.

        After READY the early profile never re-publishes readiness, so the
        first change of the serving node (Mihomo's own failover, a lease
        release, a verified pick-moving write) left the service sample stale
        until stop: the bridge held settings, the notice tracker and the
        tier topics.  This re-stamps the same READY (same Core owner,
        lifecycle, network context and user intent) at the new epoch once
        Mihomo's own self-check already calls the serving path alive (the
        nearest tested group's verdict, at its test URL, for the member it
        serves through).  It sends no request and writes nothing but the
        readiness record: no probe, no Mihomo, ledger or Manager state, no
        effective egress, arm or lease.  Without a verdict it waits.

        Call only from a thread that holds no runtime lock and is not inside
        a Core transaction.  The planner takes each lock alone; the commit
        holds only ``_core_transition_lock`` (never waited for) and under it
        takes the route, lifecycle, monitor, coordinator-state, reload-gate
        and activation locks one at a time, edges production already has.
        Never raises.
        """

        try:
            if not self._runtime_uses_early_single_coordinator():
                return False
            ready = getattr(self, "_runtime_egress_readiness", None)
            # Steady state: two attribute reads, no lock.
            if (
                not isinstance(ready, RuntimeEgressReadiness)
                or ready.state is not RuntimeEgressReadinessState.READY
                or ready.validation_active
                or int(ready.route_epoch)
                >= int(getattr(self, "_runtime_route_epoch", 0) or 0)
            ):
                return False
            if str(source).startswith("coordinator"):
                rate = getattr(self, "_runtime_ready_carry_rate", None)
                if rate is None:
                    rate = {}
                    self._runtime_ready_carry_rate = rate
                key = (
                    int(getattr(self, "_runtime_egress_readiness_publication_revision", 0) or 0),
                    int(getattr(self, "_runtime_route_epoch", 0) or 0),
                    id(getattr(self, "_runtime_route_snapshot", None)),
                )
                now = time.monotonic()
                last = rate.get("coordinator")
                if (
                    last is not None
                    and last[0] == key
                    and now - last[1] < _RUNTIME_READY_CARRY_RATE_SECONDS
                ):
                    return False
                rate["coordinator"] = (key, now)
            refusal, plan = self._runtime_ready_carry_plan()
            if plan is None:
                self._note_runtime_ready_carry(source, refusal or "refused")
                return False
            lock = self._core_transition_lock
            owned = getattr(lock, "_is_owned", None)
            if callable(owned) and owned():
                # Inside this thread's own Core transaction: never commit there.
                self._note_runtime_ready_carry(source, "reentrant")
                return False
            if not lock.acquire(blocking=False):
                self._note_runtime_ready_carry(source, "core_transition_busy")
                return False
            try:
                refusal = self._runtime_ready_carry_commit(plan)
            finally:
                lock.release()
            if refusal is not None:
                self._note_runtime_ready_carry(source, refusal)
                return False
            ready_before, _revision, snapshot, epoch, _network, _physical = plan
            proxies = (getattr(self, "_runtime_route_snapshot_payload", None) or {}).get("proxies")
            leaf = str(inspect_runtime_route(proxies, start="FINAL-EXIT").get("leaf_proxy") or "")
            self._note_runtime_ready_carry(source, "carried")
            log_raw_diagnostic(
                self.logger,
                "info",
                "Runtime READY carried forward (source=%s route_epoch=%d->%d leaf=%s)",
                str(source),
                int(ready_before.route_epoch),
                int(epoch),
                runtime_identity_hash(leaf) if leaf else "-",
            )
            return True
        except Exception:
            log_raw_diagnostic(
                self.logger,
                "debug",
                "Runtime READY carry was skipped",
                exc_info=True,
            )
            return False

    def _runtime_ready_carry_plan(self) -> tuple[str | None, tuple[Any, ...] | None]:
        """Decision D planner: a pure read, cheapest checks first.

        Returns ``(None, plan)`` when a carry may commit, else
        ``(reason, None)``.  No lock is held across calls and nothing is
        written except the evidence memo.
        """

        if not self._runtime_uses_early_single_coordinator():
            return "profile", None
        if self.stop_event.is_set() or not bool(getattr(self, "running", False)):
            return "stopping", None
        with self._tier3_egress_activation_lock:
            ready = self._runtime_egress_readiness
            revision = int(self._runtime_egress_readiness_publication_revision or 0)
            projected = int(
                getattr(self, "_runtime_egress_readiness_projected_revision", 0) or 0
            )
            activation_pending = bool(getattr(self, "_tier3_egress_activation_pending", False))
            activation_running = bool(
                getattr(self, "_tier3_egress_activation_worker_running", False)
            )
            hold_kind = str(getattr(self, "_tier3_standby_activation_hold_kind", "") or "")
        if (
            not isinstance(ready, RuntimeEgressReadiness)
            or ready.state is not RuntimeEgressReadinessState.READY
            or ready.validation_active
        ):
            return "readiness_state", None
        if projected != revision:
            return "projection_pending", None
        if activation_pending or activation_running:
            return "activation", None
        if hold_kind == "controller_hold":
            return "controller_hold", None
        with self._runtime_route_snapshot_lock:
            snapshot = self._runtime_route_snapshot
            payload = self._runtime_route_snapshot_payload
            epoch = int(self._runtime_route_epoch)
            network_epoch = int(self._runtime_network_context_epoch)
            fail_closed_key = getattr(self, "_runtime_confirmed_fail_closed_snapshot_key", None)
            digest = self._runtime_ready_carry_contract_digest()
            physical = _route_physical_signature(
                getattr(self, "_runtime_route_selection_signature", ())
            )
        if (
            not isinstance(snapshot, CoreLoadedRouteSnapshot)
            or not isinstance(payload, dict)
            or int(snapshot.route_epoch) != epoch
        ):
            return "snapshot_missing", None
        if int(ready.route_epoch) >= epoch:
            return "fresh", None
        if fail_closed_key:
            return "fail_closed", None
        if not digest or digest != str(snapshot.semantic_digest):
            return "contract_moved", None
        if int(getattr(self, "_lifecycle_revision", 0) or 0) != int(ready.lifecycle_revision):
            return "lifecycle", None
        if (
            int(ready.network_context_epoch) != network_epoch
            or int(snapshot.network_context_epoch) != network_epoch
        ):
            return "network", None
        # T-P1-10: only the Core owner that READY was proved on may carry it.
        owner = tuple(int(item) for item in (ready.route_owner or ()))
        if not owner:
            return "owner_unknown", None
        if (
            int(snapshot.process_pid),
            int(snapshot.process_generation),
            int(snapshot.core_generation),
        ) != owner:
            return "owner_changed", None
        core = self.core_fact()
        if not core["running"] or (
            int(core["pid"] or 0),
            int(core["process_generation"] or 0),
            int(core["core_generation"] or 0),
        ) != owner:
            return "core_owner", None
        initial = self._node_judgement_arm_initial_refusal()
        if initial is not None:
            return "initial:" + initial, None
        if int(getattr(self, "_runtime_selector_intent_revision", 0) or 0) != int(
            ready.selector_intent_revision
        ):
            return "selector_intent", None
        # Route-mutation owners publish their own readiness when they end.
        # Test-only work (judge, Phase B, D4 confirmation probes) is no gate:
        # any move it causes is Mihomo's own and carries on its verdict.
        if self._core_route_mutation_is_pending():
            return "route_mutation", None
        if self._runtime_recovery_transaction_active():
            return "recovery", None
        gate = self._runtime_reload_gate.snapshot()
        if gate.active_reload_reason or gate.active_recovery_transaction_id:
            return "reload_gate", None
        d4 = self._runtime_post_dial_d4_txn_busy()
        if d4 is not None and d4 != "d4_txn_busy:provider_write":
            return d4, None
        if self._runtime_facility_hold_reason():
            return "facility_hold", None
        # A stale fallback-pin release takes the Core lock without waiting and
        # backs off 5 s when it is busy: never make it compete with a carry.
        judgement = self._node_judgement_state()
        with judgement.lock:
            releasing = bool(judgement.stale_pin_inflight)
        if releasing:
            return "stale_pin_release", None
        current = self._runtime_egress_coordinator.current_route_snapshot()
        if current is None or current.snapshot_key != snapshot.snapshot_key:
            return "coordinator_snapshot", None
        ledger = getattr(self, "_tier3_health_ledger", None)
        ledger_revision = int(getattr(ledger, "revision", 0) or 0) if ledger is not None else 0
        memo = getattr(self, "_runtime_ready_carry_memo", None)
        if (
            memo is not None
            and memo[0] is snapshot
            and memo[1] == ledger_revision
            and memo[2] is ready
        ):
            evidence = memo[3]
        else:
            evidence = self._runtime_ready_carry_evidence_refusal(snapshot, payload)
            self._runtime_ready_carry_memo = (snapshot, ledger_revision, ready, evidence)
        # The same physical route READY was proved or carried on (only the
        # user intent, or an invalidation and re-read, moved the epoch): no
        # traffic moved, so a missing verdict is no reason to wait.  Negative
        # evidence (a dead leaf, an exhausted pool, a stale pin) still holds.
        same_route = bool(ready.route_physical) and tuple(ready.route_physical) == physical
        if evidence is not None and not (
            same_route and evidence in _RUNTIME_READY_CARRY_SAME_ROUTE_WAIVED
        ):
            return "evidence:" + evidence, None
        return None, (ready, revision, snapshot, epoch, network_epoch, physical)

    def _runtime_ready_carry_contract_digest(self) -> str:
        """The loaded contract's route-authority digest, as the readback uses it."""

        contract = getattr(self, "_runtime_loaded_export_contract", None)
        if not isinstance(contract, dict):
            return ""
        return str(
            contract.get("route_authority_semantic_digest")
            or contract.get("semantic_digest")
            or ""
        )

    def _runtime_ready_carry_evidence_refusal(
        self,
        snapshot: CoreLoadedRouteSnapshot,
        payload: dict[str, Any],
    ) -> str | None:
        """Why Mihomo's own self-check does not (yet) vouch for the serving path.

        Reads only the published controller response (``payload["proxies"]``)
        and, for TIER3-AUTO members rebuilt by a provider write, the ledger
        overlay.  Never the global alive flag, never a verdict for another
        URL, and never a request.
        """

        binding = self._runtime_route_binding_for_outbound(snapshot, payload, "FINAL-EXIT")
        if binding is None:
            return "binding_none"
        if not snapshot.owns(binding):
            return "binding_not_owned"
        proxies = payload.get("proxies")
        refusal = self._runtime_ready_carry_path_refusal(snapshot, proxies, "FINAL-EXIT")
        if refusal is not None:
            return refusal
        if binding.node.pool_kind == "gateway":
            info = self._runtime_proxy_info_for_ref(payload, binding.node)
            proxy = info.get("proxy") if isinstance(info, dict) else None
            if isinstance(proxy, dict) and str(proxy.get("dialer-proxy") or "").strip():
                underlay = self._runtime_gateway_underlay_binding(snapshot, payload, binding.node)
                if underlay is None:
                    return "underlay_none"
                refusal = self._runtime_ready_carry_path_refusal(
                    snapshot,
                    proxies,
                    underlay.observed_outbound,
                )
                if refusal is not None:
                    return "underlay_" + refusal
        return None

    def _runtime_ready_carry_path_refusal(
        self,
        snapshot: CoreLoadedRouteSnapshot,
        proxies: Any,
        start: str,
    ) -> str | None:
        """The nearest tested group's own verdict for the member it serves through.

        Mihomo records a check on the proxy it was called on: the group's
        selected member, which is the leaf itself or a Selector wrapper whose
        dial reaches the leaf.  The leaf's own record behind a wrapper is only
        written by direct tests and can be arbitrarily old (review 11-04).
        """

        route = inspect_runtime_route(proxies, start=str(start))
        leaf = str(route.get("leaf_proxy") or "")
        if route.get("facility_failure") or not leaf or builtin_terminal_kind(leaf):
            return "route_unresolved"
        tested = [
            layer
            for layer in (route.get("layers") or ())
            if isinstance(layer, dict) and str(layer.get("type") or "") != "select"
        ]
        if not tested:
            # A selector-only path is user intent; the intent check covers it.
            return None
        group = str(tested[-1].get("name") or "")
        member = str(tested[-1].get("now") or "")
        if not member or builtin_terminal_kind(member):
            return "route_unresolved"
        state = snapshot.group_state(group)
        if state is None or not str(state.test_url or ""):
            return "no_contract"
        if state.fixed and state.fixed not in state.members:
            return "stale_pin"
        source = (
            self._overlay_tier3_route_payload(proxies)
            if group == "TIER3-AUTO"
            else proxies
        )
        entry = mihomo_proxies_entries(source).get(member)
        extra = entry.get("extra") if isinstance(entry, dict) else None
        verdict = extra.get(str(state.test_url)) if isinstance(extra, dict) else None
        if (
            not isinstance(verdict, dict)
            or not isinstance(verdict.get("alive"), bool)
            or not verdict.get("history")
        ):
            return "unverdicted"
        if verdict.get("alive") is not True:
            return "not_alive"
        if group == "TIER3-AUTO":
            view = self._runtime_tier3_route_view(snapshot, proxies)
            if view is not None and (view.get("exhausted") or view.get("stale_fixed")):
                return "tier3_view"
        return None

    def _runtime_ready_carry_commit(self, plan: tuple[Any, ...]) -> str | None:
        """Swap the carried READY in; the caller holds ``_core_transition_lock``.

        The route and activation locks are never nested.  Only the readiness
        record and its revisions change: effective egress, the activation
        generation, the arm, the lease, source control and the Manager
        report are left exactly as the READY's own publication left them.
        """

        ready, revision, snapshot, epoch, network_epoch, physical = plan
        route_lock = self._runtime_route_snapshot_lock
        # Never wait on the route lock while holding the Core lock: a busy
        # route (a readback copying its payload) defers to the next trigger.
        if not route_lock.acquire(blocking=False):
            return "route_busy"
        try:
            moved = (
                self._runtime_route_snapshot is not snapshot
                or int(self._runtime_route_epoch) != int(epoch)
                or int(self._runtime_network_context_epoch) != int(network_epoch)
                or self._runtime_ready_carry_contract_digest() != str(snapshot.semantic_digest)
                or _route_physical_signature(
                    getattr(self, "_runtime_route_selection_signature", ())
                )
                != tuple(physical)
            )
        finally:
            route_lock.release()
        if moved:
            return "route_moved"
        # No transaction can start now; one that started before must not be
        # overtaken.
        if (
            self._core_route_mutation_is_pending()
            or self._node_judgement_arm_initial_refusal() is not None
            or self._runtime_recovery_transaction_active()
        ):
            return "transaction"
        gate = self._runtime_reload_gate.snapshot()
        if gate.active_reload_reason or gate.active_recovery_transaction_id:
            return "transaction"
        carried = _dataclass_replace(
            ready,
            route_epoch=int(epoch),
            updated_at_monotonic=time.monotonic(),
            # The route this carry vouched for (or found unchanged).
            route_physical=tuple(physical),
        )
        with self._tier3_egress_activation_lock:
            if (
                self._runtime_egress_readiness is not ready
                or int(self._runtime_egress_readiness_publication_revision or 0) != int(revision)
                or int(getattr(self, "_runtime_egress_readiness_projected_revision", 0) or 0)
                != int(revision)
                or bool(getattr(self, "_tier3_egress_activation_pending", False))
                or bool(getattr(self, "_tier3_egress_activation_worker_running", False))
                or str(getattr(self, "_tier3_standby_activation_hold_kind", "") or "")
                == "controller_hold"
                or int(getattr(self, "_lifecycle_revision", 0) or 0) != int(ready.lifecycle_revision)
                or int(getattr(self, "_runtime_selector_intent_revision", 0) or 0)
                != int(ready.selector_intent_revision)
                # Unlocked re-read: READY is never stamped with an epoch it
                # did not evaluate.
                or int(getattr(self, "_runtime_route_epoch", 0) or 0) != int(epoch)
            ):
                return "publication_moved"
            self._runtime_egress_readiness = carried
            revision = int(revision) + 1
            self._runtime_egress_readiness_publication_revision = revision
            self._runtime_egress_readiness_projected_revision = revision
        return None

    def _note_runtime_ready_carry(self, source: str, outcome: str) -> None:
        """Count every carry outcome; log each refusal once per (reason, READY, epoch)."""

        counts = getattr(self, "_runtime_ready_carry_counts", None)
        if counts is None:
            counts = {}
            self._runtime_ready_carry_counts = counts
        counts[str(outcome)] = int(counts.get(str(outcome), 0)) + 1
        if outcome == "carried":
            return
        noted = (
            str(outcome),
            int(getattr(self, "_runtime_egress_readiness_publication_revision", 0) or 0),
            int(getattr(self, "_runtime_route_epoch", 0) or 0),
        )
        if noted == getattr(self, "_runtime_ready_carry_noted", None):
            return
        self._runtime_ready_carry_noted = noted
        log_raw_diagnostic(
            self.logger,
            "debug",
            "Runtime READY not carried yet (source=%s reason=%s route_epoch=%d)",
            str(source),
            str(outcome),
            noted[2],
        )

    def _runtime_activation_recovery_owner_is_current(
        self,
        owner: _RuntimeActivationRecoveryOwner,
        *,
        binding: RuntimeRouteBinding | None = None,
        snapshot: CoreLoadedRouteSnapshot | None = None,
    ) -> bool:
        """Validate the one pre-READY authority without widening live arm."""

        if not isinstance(owner, _RuntimeActivationRecoveryOwner):
            return False
        if self._runtime_initial_activation_complete():
            return False
        if self._runtime_recovery_now() >= owner.deadline_monotonic:
            return False
        if int(
            getattr(self, "_tier3_egress_activation_generation", -1)
        ) != int(owner.activation_generation):
            return False
        active_mode = str(
            getattr(self, "_tier3_egress_activation_active_mode", "") or ""
        )
        if active_mode and active_mode != "activation":
            return False
        if not self._runtime_worker_token_is_current(owner.worker_token):
            return False
        if (
            not self._runtime_uses_early_single_coordinator()
            and int(getattr(self, "_runtime_facility_epoch", 0) or 0)
            != int(owner.facility_epoch)
        ):
            return False
        if int(
            getattr(self, "_runtime_selector_intent_revision", 0) or 0
        ) != int(owner.selector_intent_revision):
            return False
        if int(getattr(self, "_lifecycle_revision", 0) or 0) != int(
            owner.lifecycle_revision
        ):
            return False
        local_snapshot, payload = self._runtime_route_snapshot_state()
        coordinator_snapshot = (
            self._runtime_egress_coordinator.current_route_snapshot()
        )
        if (
            local_snapshot is None
            or coordinator_snapshot is None
            or not isinstance(payload, dict)
            or tuple(local_snapshot.snapshot_key) != tuple(owner.snapshot_key)
            or tuple(coordinator_snapshot.snapshot_key)
            != tuple(owner.snapshot_key)
            or (
                snapshot is not None
                and tuple(snapshot.snapshot_key) != tuple(owner.snapshot_key)
            )
        ):
            return False
        current_binding = binding or self._runtime_route_binding_for_outbound(
            local_snapshot,
            payload,
            "FINAL-EXIT",
        )
        return bool(
            current_binding is not None
            and local_snapshot.owns(current_binding)
            and tuple(current_binding.node.key) == tuple(owner.binding_key)
        )

    def _try_arm_runtime_recovery(
        self,
        *,
        allow_pre_ready: bool = False,
        admission_lease: _InitialEgressAdmissionLease | None = None,
    ) -> bool:
        diag_ticket = self._node_judgement_arm_permit()
        with self._node_judgement_arm_capture() as trace:
            result = self._node_judgement_arm_try(
                allow_pre_ready=allow_pre_ready, admission_lease=admission_lease,
            )
        self._node_judgement_arm_try_result(result, trace, ticket=diag_ticket)
        return result

    def _node_judgement_arm_try(
        self,
        *,
        allow_pre_ready: bool = False,
        admission_lease: _InitialEgressAdmissionLease | None = None,
    ) -> bool:
        """Arm live recovery only after READY and one coherent route readback."""

        if allow_pre_ready:
            if not isinstance(admission_lease, _InitialEgressAdmissionLease):
                return self._node_judgement_arm_reject("pre_ready_lease:missing")
            with self._core_lifecycle_lock:
                core_generation = int(self._core_generation)
            runner = getattr(self, "core_runner", None)
            try:
                runner_status = runner.status() if runner is not None else {}
                runner_live = bool(runner is not None and runner.is_running())
            except Exception:
                return self._node_judgement_arm_reject("pre_ready_lease:runner_exception")
            if core_generation <= 0 or core_generation != int(admission_lease.core_generation):
                return self._node_judgement_arm_reject("pre_ready_lease:core_generation")
            if int(getattr(self, "_runtime_generation", 0) or 0) != int(admission_lease.runtime_generation):
                return self._node_judgement_arm_reject("pre_ready_lease:runtime_generation")
            if int(getattr(self, "_lifecycle_revision", 0) or 0) != int(admission_lease.lifecycle_revision):
                return self._node_judgement_arm_reject("pre_ready_lease:lifecycle")
            if int(getattr(self, "_tier3_egress_activation_generation", -1) or -1) != int(admission_lease.activation_generation):
                return self._node_judgement_arm_reject("pre_ready_lease:activation_generation")
            if int(getattr(self, "_runtime_selector_intent_revision", 0) or 0) != int(admission_lease.selector_intent_revision):
                return self._node_judgement_arm_reject("pre_ready_lease:selector_intent")
            if not runner_live:
                return self._node_judgement_arm_reject("pre_ready_lease:runner_not_live")
            if int(runner_status.get("pid") or 0) != int(admission_lease.process_pid):
                return self._node_judgement_arm_reject("pre_ready_lease:process_pid")
            if int(runner_status.get("process_generation") or 0) != int(admission_lease.process_generation):
                return self._node_judgement_arm_reject("pre_ready_lease:process_generation")
            if not self._runtime_worker_token_is_current(admission_lease.worker_token):
                return self._node_judgement_arm_reject("pre_ready_lease:worker_token")
        else:
            initial_check = self._node_judgement_arm_initial_check()
            if initial_check is not None:
                return self._node_judgement_arm_reject("not_ready", initial_check=initial_check)
        if (
            not self._runtime_uses_early_single_coordinator()
            and self._runtime_facility_hold_reason()
        ):
            return self._node_judgement_arm_reject("facility_hold")
        with self._runtime_failure_monitor_lock:
            states = tuple(
                str(value or "")
                for value in getattr(
                    self,
                    "_runtime_incident_recovery_state",
                    {},
                ).values()
            )
            incident_ids = tuple(
                key for key, state in zip(getattr(self, "_runtime_incident_recovery_state", {}).keys(), states)
                if state in {"pending", "recovering"}
            )[:8]
        if any(state in {"pending", "recovering"} for state in states):
            return self._node_judgement_arm_reject("incident_active",
                pending=states.count("pending"), recovering=states.count("recovering"),
                incidents=tuple(runtime_identity_hash(str(key)) for key in incident_ids))
        snapshot, payload = self._runtime_route_snapshot_state()
        coordinator_snapshot = self._runtime_egress_coordinator.current_route_snapshot()
        if snapshot is None or coordinator_snapshot is None or not isinstance(payload, dict):
            return self._node_judgement_arm_reject("snapshot_missing")
        if tuple(snapshot.snapshot_key) != tuple(coordinator_snapshot.snapshot_key):
            return self._node_judgement_arm_reject("snapshot_key_mismatch")
        binding = self._runtime_route_binding_for_outbound(
            snapshot,
            payload,
            "FINAL-EXIT",
        )
        if binding is None:
            return self._node_judgement_arm_reject("binding_none")
        if not snapshot.owns(binding):
            return self._node_judgement_arm_reject("binding_not_owned")
        worker_token = self._runtime_worker_token()
        if not self._runtime_worker_token_is_current(worker_token):
            return self._node_judgement_arm_reject("worker_token")
        arm = _RuntimeRecoveryArm(
            worker_token=worker_token,
            snapshot_key=tuple(snapshot.snapshot_key),
            binding_key=tuple(binding.node.key),
            route_epoch=int(snapshot.route_epoch),
            facility_epoch=int(getattr(self, "_runtime_facility_epoch", 0) or 0),
            selector_intent_revision=int(
                getattr(self, "_runtime_selector_intent_revision", 0) or 0
            ),
            lifecycle_revision=int(getattr(self, "_lifecycle_revision", 0) or 0),
            armed_at_monotonic=time.monotonic(),
        )
        with self._runtime_failure_monitor_lock:
            if not allow_pre_ready:
                initial_check = self._node_judgement_arm_initial_check()
                if initial_check is not None:
                    return self._node_judgement_arm_reject("lock_recheck:initial_activation:" + initial_check)
            if allow_pre_ready and (
                not isinstance(admission_lease, _InitialEgressAdmissionLease)
                or int(
                    getattr(self, "_tier3_egress_activation_generation", -1)
                    or -1
                )
                != int(admission_lease.activation_generation)
            ):
                return self._node_judgement_arm_reject("lock_recheck:pre_ready_lease")
            existing = getattr(self, "_runtime_recovery_arm", None)
            if (
                isinstance(existing, _RuntimeRecoveryArm)
                and existing.worker_token == arm.worker_token
                and existing.snapshot_key == arm.snapshot_key
                and existing.binding_key == arm.binding_key
                and existing.route_epoch == arm.route_epoch
                and existing.facility_epoch == arm.facility_epoch
                and existing.selector_intent_revision
                == arm.selector_intent_revision
                and existing.lifecycle_revision == arm.lifecycle_revision
            ):
                # A monitor tick for an unchanged authority is not a new
                # preparation transaction.  Keep the original arm (and its
                # timestamp) so one runtime signature has one bounded owner.
                arm = existing
            self._runtime_recovery_arm = arm
        if allow_pre_ready:
            # The arm is installed before READY becomes observable. It remains
            # inert because _runtime_recovery_is_armed() retains the strict
            # READY/effective-egress gate.
            return True
        with self._node_judgement_arm_capture() as installed_trace:
            armed = self._runtime_recovery_is_armed(snapshot)
        installed_check = installed_trace.get("arm_check", None if armed else "override_unknown")
        self._node_judgement_arm_trace("installed_armed", bool(armed))
        self._node_judgement_arm_trace("installed_check", installed_check)
        self._node_judgement_arm_trace("arm_check", installed_check)
        if armed:
            self._commit_runtime_monitoring_lease()
            manager = getattr(self, "manager", None)
            try:
                source_ready = self._source_control_final_exit_ready(manager)
            except (AttributeError, TypeError):
                # Narrow embedders may exercise the recovery arm without the
                # full lifecycle/source-control surface. Production runtimes
                # always take the strict source proof path.
                source_ready = False
            source_was_ready = bool(
                getattr(self, "_source_control_final_exit_was_ready", False)
            )
            self._source_control_final_exit_was_ready = source_ready
            if source_ready and not source_was_ready:
                notify = getattr(
                    manager,
                    "notify_tier3_source_supply_route_changed",
                    None,
                ) if manager is not None else None
                if callable(notify):
                    try:
                        notify("verified_final_exit_ready")
                    except Exception:
                        log_raw_diagnostic(
                            self.logger,
                            "warning",
                            "Could not notify source supply that FINAL-EXIT is ready",
                            exc_info=True,
                        )
        return armed

    def _runtime_worker_token(self) -> tuple[int, ...]:
        queue_state = self._runtime_egress_coordinator.queue_snapshot()
        runner = self.core_runner
        try:
            status = runner.status() if runner is not None else {}
        except Exception:
            status = {}
        return (
            int(self._runtime_generation),
            int(queue_state.coordinator_epoch),
            int(self._core_generation),
            int(status.get("pid") or 0),
            int(status.get("process_generation") or 0),
            int(getattr(self, "_runtime_facility_epoch", 0) or 0),
        )

    def _runtime_worker_token_is_current(
        self,
        token: tuple[int, ...],
    ) -> bool:
        queue_state = self._runtime_egress_coordinator.queue_snapshot()
        current = self._runtime_worker_token()
        return bool(
            not self.stop_event.is_set()
            and queue_state.running
            and tuple(token) == current
        )

    def _register_runtime_internal_probe(
        self,
        probe_url: str,
        *,
        timeout_seconds: float,
    ) -> None:
        """Suppress only Core lines emitted by a known application probe."""

        destination = str(urlsplit(str(probe_url or "")).hostname or "").strip()
        token = runtime_destination_token(destination)
        if not token:
            return
        started = time.monotonic()
        expires = started + max(0.1, float(timeout_seconds)) + 1.0
        with self._runtime_failure_monitor_lock:
            previous = self._runtime_internal_probe_windows.get(token)
            if previous is not None and previous[1] >= started:
                started = min(started, float(previous[0]))
                expires = max(expires, float(previous[1]))
            self._runtime_internal_probe_windows[token] = (started, expires)

    def _runtime_transport_failure_is_internal_probe(self, parsed: Any) -> bool:
        destination_token = str(
            getattr(parsed, "destination_token", "") or ""
        )
        if not destination_token:
            return False
        observed = float(
            getattr(parsed, "observed_at_monotonic", 0.0) or 0.0
        )
        now = time.monotonic()
        with self._runtime_failure_monitor_lock:
            expired = [
                token
                for token, (_started, expires) in (
                    self._runtime_internal_probe_windows.items()
                )
                if float(expires) + 5.0 < now
            ]
            for token in expired:
                self._runtime_internal_probe_windows.pop(token, None)
            window = self._runtime_internal_probe_windows.get(
                destination_token
            )
        return bool(
            window is not None
            and float(window[0]) - 0.05 <= observed <= float(window[1])
        )

    def _runtime_local_facility_state_for_use(
        self,
    ) -> tuple[threading.RLock, RuntimeLocalFacilityState]:
        lock = getattr(self, "_runtime_local_facility_lock", None)
        if lock is None:
            lock = threading.RLock()
            self._runtime_local_facility_lock = lock
        state = getattr(self, "_runtime_local_facility_state", None)
        if state is None:
            state = RuntimeLocalFacilityState()
            self._runtime_local_facility_state = state
        return lock, state

    def _runtime_local_facility_snapshot(self) -> Any:
        lock, state = self._runtime_local_facility_state_for_use()
        with lock:
            return state.snapshot()

    def _runtime_local_listener_fault_from_core_output(
        self,
        raw_line: str,
        *,
        observed_at_monotonic: float | None = None,
    ) -> RuntimeListenerFault | None:
        try:
            client = self._client_config()
        except Exception:
            client = {}
        try:
            controller = self._mihomo_controller_config()
        except Exception:
            controller = {}
        try:
            controller_url = urlsplit(
                build_mihomo_controller_base_url(controller)
            )
            controller_endpoint = (
                f"{controller_url.hostname or '127.0.0.1'}:"
                f"{int(controller_url.port or 9090)}"
            )
        except Exception:
            controller_endpoint = "127.0.0.1:9090"
        dns = client_dns_block(client)
        dns_endpoint = str(dns.get("listen") or "127.0.0.1:1053")
        try:
            source_transport = self._runtime_source_transport_snapshot()
        except Exception:
            source_transport = None
        source_endpoints = tuple(
            f"{listener.listen}:{int(listener.port)}"
            for listener in (
                source_transport.listeners
                if source_transport is not None
                else ()
            )
        )
        return classify_runtime_listener_fault(
            raw_line,
            runtime_generation=int(
                getattr(self, "_runtime_generation", 0) or 0
            ),
            core_generation=int(getattr(self, "_core_generation", 0) or 0),
            observed_at_monotonic=(
                time.monotonic()
                if observed_at_monotonic is None
                else float(observed_at_monotonic)
            ),
            network_mode=str(getattr(self, "network_mode", "system_proxy")),
            mixed_endpoint=(
                f"{self._core_proxy_host() if hasattr(self, 'config') else '127.0.0.1'}:"
                f"{self._client_mixed_port(client)}"
            ),
            controller_endpoint=controller_endpoint,
            dns_endpoint=dns_endpoint,
            source_endpoints=source_endpoints,
        )

    def _on_core_output_event(self, event: CoreOutputEvent) -> None:
        """Reader-thread callback: filter and enqueue only; never probe or log."""

        if self.stop_event.is_set():
            return
        lowered = str(event.raw_line or "").casefold()
        if "dns resolve failed" in lowered:
            # Resolution faults are counted in every phase (a counter only, no
            # probing here): they are the escalation evidence for the resolver
            # ladder, and before admission nothing else would see them.
            self._note_dns_resolver_fault(event)
        if not self._runtime_monitoring_is_active():
            # Startup owns the first 204 and READY publication.  Reader noise
            # before that point must never create a health incident or mutate
            # the route that startup is still proving.
            return
        local_fault = self._runtime_local_listener_fault_from_core_output(
            event.raw_line,
            observed_at_monotonic=event.received_at_monotonic,
        )
        if local_fault is not None:
            facility_lock, facility_state = (
                self._runtime_local_facility_state_for_use()
            )
            with facility_lock:
                observed = facility_state.observe(local_fault)
                local_snapshot = facility_state.snapshot()
                self._runtime_local_facility_fault_reason = (
                    local_snapshot.blocking_reason
                )
            if (
                observed
                and local_fault.blocks_node_attribution
                and not self._runtime_uses_early_single_coordinator()
            ):
                # Revoke probes/callbacks that crossed a control/data-plane
                # listener failure. Capture-only DNS and private source lanes
                # do not invalidate a healthy FINAL-EXIT binding.
                with self._runtime_failure_monitor_lock:
                    self._runtime_facility_epoch = int(
                        getattr(self, "_runtime_facility_epoch", 0) or 0
                    ) + 1
                    self._defer_current_runtime_provisional_locked(
                        local_fault.reason
                    )
                    origin_map = getattr(
                        self,
                        "_runtime_origin_diagnostic_bindings",
                        None,
                    )
                    if isinstance(origin_map, dict):
                        origin_map.clear()
            if (
                local_fault.blocks_data_plane
                and not self._runtime_uses_early_single_coordinator()
            ):
                self._runtime_egress_coordinator.request_guard(
                    "local_data_plane_listener_bind_failed"
                )
            return
        # Node judgement P1-1: the post-dial tap.  Substring tests and one
        # bounded append only; the observer thread parses.  Without a running
        # observer this is a single dictionary lookup, and the line still
        # takes the unchanged path below.
        post_dial_tap = self.__dict__.get("_runtime_post_dial_tap")
        if (
            post_dial_tap is not None
            and "level=info" in lowered
            and "[tcp] " in lowered
            and " using " in lowered
        ):
            post_dial_tap.offer(event)
        if "dial " not in lowered or "error" not in lowered:
            return
        # The stdout reader must remain non-blocking.  Snapshot publication is
        # append/replace-only, so taking the current immutable snapshot and its
        # never-mutated payload owner under the lock is sufficient; a deep copy
        # of the complete `/proxies` graph here would put burst latency on the
        # Core pipe reader.
        with self._runtime_route_snapshot_lock:
            snapshot = self._runtime_route_snapshot
            payload = self._runtime_route_snapshot_payload
        if snapshot is None or payload is None:
            if not self._runtime_uses_early_single_coordinator():
                self._runtime_egress_coordinator.request_guard(
                    "snapshot_unavailable"
                )
                return
            # An admitted Core may lose its cached route during a manual or
            # native selection. The consumer obtains fresh local authority.
            payload = {}
        if (
            snapshot is not None and (
                int(event.pid) != snapshot.process_pid
                or int(event.process_generation) != snapshot.process_generation
            )
        ):
            return
        lease = getattr(self, "_runtime_monitoring_lease", None)
        if isinstance(lease, _RuntimeMonitoringLease) and (
            int(event.pid) != lease.process_pid
            or int(event.process_generation) != lease.process_generation
            or float(event.received_at_monotonic) < lease.admitted_at_monotonic
        ):
            return
        if self._runtime_uses_early_single_coordinator():
            facility_epoch_after = 0
            facility_hold_active = False
        else:
            facility_epoch_before = int(
                getattr(self, "_runtime_facility_epoch", 0) or 0
            )
            facility_hold_active = bool(
                self._runtime_facility_hold_reason()
                or self._runtime_node_attribution_hold_reason()
            )
            facility_epoch_after = int(
                getattr(self, "_runtime_facility_epoch", 0) or 0
            )
            if facility_epoch_before != facility_epoch_after:
                # A facility transition raced the reader callback. Mark this
                # envelope as crossing the boundary even if the hold has already
                # been released by the time the second epoch is observed.
                facility_hold_active = True
        self._runtime_egress_coordinator.submit_ingress(
            _RuntimeOutputIngress(
                event=event,
                snapshot=snapshot,
                snapshot_payload=payload,
                facility_epoch=facility_epoch_after,
                facility_hold_active=facility_hold_active,
                selector_intent_revision=int(
                    getattr(self, "_runtime_selector_intent_revision", 0) or 0
                ),
            )
        )

    def _start_runtime_failure_monitor(self) -> None:
        with self._runtime_failure_monitor_lock:
            current = getattr(self, "_runtime_failure_monitor_thread", None)
            if current is not None and current.is_alive():
                return
            queue_state = self._runtime_egress_coordinator.queue_snapshot()
            if queue_state.running:
                self._runtime_egress_coordinator.set_current_snapshot(
                    self._runtime_route_snapshot
                )
            else:
                self._runtime_egress_coordinator.restart(
                    current_snapshot=self._runtime_route_snapshot
                )
            worker = threading.Thread(
                target=self._runtime_failure_monitor_loop,
                name="runtime-egress-coordinator",
                daemon=True,
            )
            self._runtime_failure_monitor_thread = worker
            worker.start()
        if not self._runtime_uses_early_single_coordinator():
            self._queue_runtime_route_snapshot_refresh()
            self._start_runtime_hot_standby_maintenance()

    def _runtime_network_context_signature(
        self,
    ) -> _RuntimeNetworkContextObservation:
        """Best-effort NIC/default-route/DNS signature; never mutates the OS."""

        values: list[str] = []
        validity: dict[str, bool] = {}
        try:
            values.extend(
                f"if:{index}:{name}"
                for index, name in socket.if_nameindex()
            )
            validity["interfaces"] = True
        except OSError:
            validity["interfaces"] = False
        try:
            values.extend(
                f"addr:{item[4][0]}"
                for item in socket.getaddrinfo(socket.gethostname(), None)
                if item and item[4]
            )
            validity["addresses"] = True
        except OSError:
            validity["addresses"] = False
        if os.name == "nt":
            creationflags = int(getattr(subprocess, "CREATE_NO_WINDOW", 0))
            for component, command, markers in (
                ("default_route", ("route.exe", "print", "-4"), ("0.0.0.0",)),
                ("dns", ("ipconfig.exe", "/all"), ("dns servers", "dns 服务器")),
            ):
                try:
                    completed = subprocess.run(
                        list(command),
                        capture_output=True,
                        text=True,
                        encoding="utf-8",
                        errors="replace",
                        timeout=0.75,
                        check=False,
                        creationflags=creationflags,
                    )
                except (OSError, subprocess.SubprocessError):
                    validity[component] = False
                    continue
                validity[component] = completed.returncode == 0
                matched = False
                for raw_line in completed.stdout.splitlines():
                    line = " ".join(raw_line.strip().split())
                    lowered = line.casefold()
                    if line and any(marker in lowered for marker in markers):
                        values.append(f"{component}:{line[:240]}")
                        matched = True
                if validity[component] and not matched:
                    values.append(f"{component}:none")
        encoded = "\n".join(sorted(set(values))).encode("utf-8")
        required = {"interfaces", "addresses"}
        if os.name == "nt":
            required.update({"default_route", "dns"})
        valid = bool(required and all(validity.get(key, False) for key in required))
        return _RuntimeNetworkContextObservation(
            signature=hashlib.sha256(encoded).hexdigest() if valid else "",
            valid=valid,
            components=tuple(sorted(validity.items())),
        )

    def _runtime_facility_hold_reason(self) -> str:
        local_state = getattr(self, "_runtime_local_facility_state", None)
        if local_state is not None:
            local_fault = str(
                self._runtime_local_facility_snapshot().blocking_reason or ""
            )
        else:
            # Compatibility for narrow adapters that pre-date typed listener
            # state. Production never treats the mirror as authoritative.
            local_fault = str(
                getattr(self, "_runtime_local_facility_fault_reason", "") or ""
            )
        if local_fault:
            return local_fault
        hot_standby_lock = getattr(self, "_runtime_hot_standby_lock", None)
        if hot_standby_lock is None:
            if bool(
                getattr(self, "_runtime_network_context_hold_active", False)
            ):
                return str(
                    getattr(self, "_runtime_network_context_hold_reason", "")
                    or "runtime network context is stabilizing"
                )
            return ""
        with hot_standby_lock:
            if bool(
                getattr(self, "_runtime_network_context_hold_active", False)
            ):
                return str(
                    getattr(self, "_runtime_network_context_hold_reason", "")
                    or "runtime network context is stabilizing"
                )
        return ""

    def _runtime_local_data_plane_blocked(self) -> bool:
        if getattr(self, "_runtime_local_facility_state", None) is not None:
            return bool(
                self._runtime_local_facility_snapshot().data_plane_blocked
            )
        return bool(
            str(
                getattr(self, "_runtime_local_facility_fault_reason", "") or ""
            )
        )

    def _runtime_node_attribution_hold_reason(self) -> str:
        local_state = getattr(self, "_runtime_local_facility_state", None)
        if local_state is None:
            return str(
                getattr(self, "_runtime_local_facility_fault_reason", "") or ""
            )
        return str(
            self._runtime_local_facility_snapshot().attribution_reason or ""
        )

    @staticmethod
    def _runtime_listener_endpoint_parts(endpoint: str) -> tuple[str, int] | None:
        host, separator, raw_port = str(endpoint or "").rpartition(":")
        if not separator:
            return None
        try:
            port = int(raw_port)
        except (TypeError, ValueError):
            return None
        host = host.strip().strip("[]") or "127.0.0.1"
        if not 1 <= port <= 65535:
            return None
        return host, port

    @staticmethod
    def _runtime_dns_listener_responds(
        host: str,
        port: int,
        *,
        timeout_seconds: float = 0.35,
    ) -> bool:
        # One ordinary A query proves that the local UDP facility is useful;
        # merely seeing the port occupied would repeat the original false
        # positive when another process owns a dead socket.
        transaction = int(time.monotonic_ns() & 0xFFFF).to_bytes(2, "big")
        header = transaction + b"\x01\x00\x00\x01\x00\x00\x00\x00\x00\x00"
        qname = b"\x03www\x07gstatic\x03com\x00"
        query = header + qname + b"\x00\x01\x00\x01"
        family = socket.AF_INET6 if ":" in host else socket.AF_INET
        try:
            with socket.socket(family, socket.SOCK_DGRAM) as client:
                client.settimeout(max(0.05, float(timeout_seconds)))
                client.sendto(query, (host, int(port)))
                response, _peer = client.recvfrom(512)
        except OSError:
            return False
        return bool(
            len(response) >= 12
            and response[:2] == transaction
            and response[2] & 0x80
        )

    def _runtime_listener_endpoint_ready(
        self,
        fault: RuntimeListenerFault,
    ) -> bool:
        parts = self._runtime_listener_endpoint_parts(fault.endpoint)
        if parts is None:
            return False
        host, port = parts
        if fault.kind is RuntimeListenerKind.MIXED:
            runner = self.core_runner
            return bool(
                runner is not None and self._core_mixed_port_is_ready(runner)
            )
        if fault.kind is RuntimeListenerKind.DNS:
            return self._runtime_dns_listener_responds(host, port)
        if fault.kind is RuntimeListenerKind.SOURCE_PRIVATE:
            try:
                transport = self._runtime_source_loaded_transport_snapshot()
            except Exception:
                transport = None
            for listener in (
                transport.listeners if transport is not None else ()
            ):
                if (
                    str(listener.listen) == host
                    and int(listener.port) == int(port)
                ):
                    endpoint = listener.endpoint(
                        ready=True,
                        priority=0,
                        stagger_ms=0,
                    )
                    return self._runtime_source_listener_requires_auth(endpoint)
            return False
        # Controller and unknown listener ownership cannot be proven safely by
        # connecting to a port that may belong to the conflicting process.
        # Their attribution barrier is runtime-scoped and is discarded when a
        # new Core generation publishes a fresh controller snapshot.
        return False

    def _maybe_recheck_runtime_local_facilities(self) -> None:
        state = getattr(self, "_runtime_local_facility_state", None)
        if state is None:
            return
        lock, state = self._runtime_local_facility_state_for_use()
        now = time.monotonic()
        with lock:
            state.discard_stale(
                runtime_generation=int(
                    getattr(self, "_runtime_generation", 0) or 0
                ),
                core_generation=int(getattr(self, "_core_generation", 0) or 0),
            )
            due = state.due(now)
            snapshot_before = state.snapshot()
            self._runtime_local_facility_fault_reason = (
                snapshot_before.blocking_reason
            )
        if not due:
            return
        # One listener proof per maintenance turn prevents a local bind burst
        # from competing with real runtime/manual recovery.
        fault = due[0]
        endpoint_ready = self._runtime_listener_endpoint_ready(fault)
        final_exit_verified = False
        if endpoint_ready and fault.blocks_data_plane:
            try:
                result = self._probe_mihomo_mixed_port_once(
                    timeout_seconds=1.5,
                    probe_priority=ProbePriority.ACTIVATION,
                )
                final_exit_verified = bool(
                    isinstance(result, dict)
                    and int(result.get("status") or 0) == 204
                )
            except _RuntimeProbeBudgetUnavailable:
                # Saturated evidence capacity is indeterminate, never a new
                # listener or leaf failure. Leave the original retry deadline
                # intact so the next maintenance turn can retry promptly.
                return
            except Exception:
                final_exit_verified = False
        with lock:
            cleared = state.record_probe(
                fault.token,
                now_monotonic=time.monotonic(),
                endpoint_ready=endpoint_ready,
                final_exit_verified=final_exit_verified,
            )
            snapshot_after = state.snapshot()
            self._runtime_local_facility_fault_reason = (
                snapshot_after.blocking_reason
            )
        if not cleared:
            return
        with self._runtime_failure_monitor_lock:
            self._runtime_facility_epoch = int(
                getattr(self, "_runtime_facility_epoch", 0) or 0
            ) + 1
        release_hold_epoch, release_facility_epoch = (
            self._runtime_facility_hold_cas_token()
        )
        if fault.blocks_data_plane and final_exit_verified:
            released = self._release_runtime_network_context_hold_after_verified_probe(
                expected_hold_epoch=release_hold_epoch,
                expected_facility_epoch=release_facility_epoch,
            )
            self._reset_tier3_standby_activation_failure()
            if self._current_core_runtime_phase() == "formal_no_capture":
                self._queue_tier3_egress_activation()
            elif not self._runtime_facility_hold_reason():
                self._set_effective_egress_readiness_state(True, "")
            if not released and not self._runtime_facility_hold_reason():
                self._resume_runtime_deferred_after_facility_release()
        elif not self._runtime_facility_hold_reason():
            # Attribution-only listener faults may clear without a network
            # hold or mixed-port proof. Their deferred recovery mailboxes still
            # need the same event-driven wakeup.
            self._resume_runtime_deferred_after_facility_release()
        wake_provider = getattr(
            self,
            "_wake_parked_tier3_pool_sync_if_causal_key_changed",
            None,
        )
        if callable(wake_provider):
            wake_provider()

    def _defer_current_runtime_provisional_locked(self, reason: str) -> None:
        """Capture the one provisional owner before facility evidence revokes it."""

        lease_record = getattr(self, "_runtime_route_mutation_lease", None)
        if not (
            isinstance(lease_record, dict)
            and bool(lease_record.get("provisional"))
        ):
            return
        incident_id = str(lease_record.get("incident_id") or "")
        if not incident_id:
            return
        deferred = getattr(
            self,
            "_runtime_deferred_provisional_confirmations",
            None,
        )
        if not isinstance(deferred, dict):
            deferred = {}
            self._runtime_deferred_provisional_confirmations = deferred
        origin_map = getattr(self, "_runtime_origin_diagnostic_bindings", {})
        origin = origin_map.get(incident_id) if isinstance(origin_map, dict) else None
        incident_bindings = getattr(self, "_runtime_incident_bindings", {})
        origin_binding = (
            origin.binding
            if isinstance(origin, OriginDiagnosticBinding)
            else incident_bindings.get(incident_id)
            if isinstance(incident_bindings, dict)
            else None
        )
        route_payloads = getattr(self, "_runtime_incident_route_payloads", {})
        route_payload = (
            route_payloads.get(incident_id)
            if isinstance(route_payloads, dict)
            else None
        )
        deferred[incident_id] = {
            "incident_id": incident_id,
            "binding": origin_binding,
            "snapshot_payload": (
                route_payload if isinstance(route_payload, dict) else None
            ),
            "owner_token": str(lease_record.get("owner_token") or ""),
            "selector_intent_revision": int(
                lease_record.get(
                    "selector_intent_revision",
                    getattr(self, "_runtime_selector_intent_revision", 0),
                )
                or 0
            ),
            "from_proxy": str(lease_record.get("from") or ""),
            "to_proxy": str(lease_record.get("to") or ""),
            "reason": str(reason or "runtime_facility_hold"),
        }

    def _resume_runtime_deferred_after_facility_release(self) -> None:
        if bool(getattr(self, "_runtime_deferred_failbacks", None)):
            self._resume_deferred_runtime_failbacks()
        if bool(
            getattr(
                self,
                "_runtime_deferred_provisional_confirmations",
                None,
            )
        ):
            self._resume_deferred_runtime_provisional_confirmations()

    def _enter_runtime_facility_hold(
        self,
        reason: str,
        *,
        publish_readiness: bool = True,
    ) -> bool:
        """Freeze leaf attribution until one neutral baseline is verified.

        Facility evidence is intentionally runtime-scoped.  Repeated stdout
        errors must not keep extending the first 1/2/5-second rebaseline
        deadline or turn a WAN/Core outage into node strikes.
        """

        canonical_reason = str(reason or "runtime egress facility degraded")
        now = time.monotonic()
        monitor_lock = getattr(self, "_runtime_failure_monitor_lock", None)
        if monitor_lock is None:
            monitor_lock = threading.RLock()
            self._runtime_failure_monitor_lock = monitor_lock
        route_lock = getattr(self, "_runtime_route_snapshot_lock", None)
        if route_lock is None:
            route_lock = threading.RLock()
            self._runtime_route_snapshot_lock = route_lock
        hot_standby_lock = getattr(self, "_runtime_hot_standby_lock", None)
        if hot_standby_lock is None:
            hot_standby_lock = threading.RLock()
            self._runtime_hot_standby_lock = hot_standby_lock
        with monitor_lock:
            with route_lock:
                network_epoch = int(
                    getattr(self, "_runtime_network_context_epoch", 0) or 0
                )
                with hot_standby_lock:
                    if bool(
                        getattr(
                            self,
                            "_runtime_network_context_hold_active",
                            False,
                        )
                    ):
                        if not str(
                            getattr(
                                self,
                                "_runtime_network_context_hold_reason",
                                "",
                            )
                            or ""
                        ):
                            self._runtime_network_context_hold_reason = (
                                canonical_reason
                            )
                        return False
                    self._runtime_facility_epoch = int(
                        getattr(self, "_runtime_facility_epoch", 0) or 0
                    ) + 1
                    self._runtime_network_context_hold_active = True
                    self._runtime_network_context_hold_pending_candidate = False
                    self._runtime_network_context_hold_reason = canonical_reason
                    self._runtime_network_context_hold_epoch = network_epoch
                    self._runtime_network_context_rebase_stage = 0
                    self._runtime_network_context_rebase_at = now + 1.0
            self._defer_current_runtime_provisional_locked(canonical_reason)
            origin_map = getattr(self, "_runtime_origin_diagnostic_bindings", None)
            if isinstance(origin_map, dict):
                origin_map.clear()
        if publish_readiness:
            self._set_effective_egress_readiness_state(
                None,
                canonical_reason,
            )
        return True

    def _wake_runtime_facility_rebaseline(self, reason: str) -> bool:
        """Wake one event-gated facility baseline without clearing the hold."""

        del reason
        if self._runtime_uses_early_single_coordinator():
            return False
        if self._runtime_local_data_plane_blocked():
            return False
        with self._runtime_failure_monitor_lock:
            with self._runtime_route_snapshot_lock:
                with self._runtime_hot_standby_lock:
                    if (
                        not bool(
                            getattr(
                                self,
                                "_runtime_network_context_hold_active",
                                False,
                            )
                        )
                        or bool(
                            getattr(
                                self,
                                "_runtime_network_context_hold_pending_candidate",
                                False,
                            )
                        )
                    ):
                        return False
                    self._runtime_network_context_rebase_stage = 0
                    self._runtime_network_context_rebase_at = time.monotonic()
                    return True

    def _observe_runtime_network_context(
        self,
        observation: _RuntimeNetworkContextObservation | str,
    ) -> bool:
        """Debounce valid context changes; invalid samples never advance epochs."""

        monitor_lock = getattr(self, "_runtime_failure_monitor_lock", None)
        if monitor_lock is None:
            monitor_lock = threading.RLock()
            self._runtime_failure_monitor_lock = monitor_lock
        route_lock = getattr(self, "_runtime_route_snapshot_lock", None)
        if route_lock is None:
            route_lock = threading.RLock()
            self._runtime_route_snapshot_lock = route_lock
        hot_lock = getattr(self, "_runtime_hot_standby_lock", None)
        if hot_lock is None:
            hot_lock = threading.RLock()
            self._runtime_hot_standby_lock = hot_lock

        if isinstance(observation, _RuntimeNetworkContextObservation):
            signature = str(observation.signature or "")
            valid = bool(observation.valid)
        else:
            signature = str(observation or "")
            valid = bool(signature)
        if not valid or not signature:
            # Unknown interface/default-route/DNS state is facility evidence,
            # not proof that the selected proxy leaf failed. Keep the network
            # epoch unchanged until a valid, debounced context exists, while
            # immediately revoking in-flight leaf attribution.
            with monitor_lock:
                with route_lock:
                    with hot_lock:
                        self._runtime_network_context_invalid_observed = True
            self._enter_runtime_facility_hold(
                "runtime network context is unavailable"
            )
            return False
        now = time.monotonic()
        commit_change = False
        entered_facility_hold = False
        with monitor_lock:
            with route_lock:
                with hot_lock:
                    recovered_from_invalid = bool(
                        getattr(
                            self,
                            "_runtime_network_context_invalid_observed",
                            False,
                        )
                    )
                    self._runtime_network_context_invalid_observed = False
                    committed = str(
                        getattr(
                            self,
                            "_runtime_network_context_signature_value",
                            "",
                        )
                        or ""
                    )
                    if not committed:
                        self._runtime_network_context_signature_value = signature
                        self._runtime_network_context_candidate_signature = ""
                        self._runtime_network_context_candidate_count = 0
                        return False
                    if signature == committed:
                        if self._runtime_network_context_candidate_signature:
                            # A one-off different sample did not repeat. Keep
                            # attribution held until a neutral baseline proves
                            # the committed context is usable again.
                            self._runtime_network_context_candidate_signature = ""
                            self._runtime_network_context_candidate_count = 0
                            self._runtime_network_context_hold_pending_candidate = False
                            self._runtime_network_context_rebase_at = now
                        elif recovered_from_invalid and bool(
                            getattr(
                                self,
                                "_runtime_network_context_hold_active",
                                False,
                            )
                        ):
                            # After the bounded baseline becomes event-gated,
                            # a fresh valid observation is the recovery event.
                            self._runtime_network_context_hold_pending_candidate = False
                            self._runtime_network_context_rebase_stage = 0
                            self._runtime_network_context_rebase_at = now
                        return False
                    if (
                        signature
                        == self._runtime_network_context_candidate_signature
                    ):
                        self._runtime_network_context_candidate_count += 1
                    else:
                        self._runtime_network_context_candidate_signature = signature
                        self._runtime_network_context_candidate_count = 1
                    if not bool(
                        getattr(
                            self,
                            "_runtime_network_context_hold_active",
                            False,
                        )
                    ):
                        self._runtime_facility_epoch = int(
                            getattr(self, "_runtime_facility_epoch", 0) or 0
                        ) + 1
                        entered_facility_hold = True
                    self._runtime_network_context_hold_active = True
                    self._runtime_network_context_hold_pending_candidate = True
                    self._runtime_network_context_hold_reason = (
                        "runtime network context change is stabilizing"
                    )
                    self._runtime_network_context_hold_epoch = int(
                        getattr(self, "_runtime_network_context_epoch", 0) or 0
                    )
                    if self._runtime_network_context_candidate_count >= 2:
                        self._runtime_network_context_signature_value = signature
                        self._runtime_network_context_candidate_signature = ""
                        self._runtime_network_context_candidate_count = 0
                        self._runtime_network_context_hold_pending_candidate = False
                        commit_change = True
        if entered_facility_hold:
            self._set_effective_egress_readiness_state(
                None,
                "runtime network context change is stabilizing",
            )
        if commit_change:
            self._advance_runtime_network_context_epoch(
                "nic_route_or_dns_change"
            )
        return commit_change

    def _advance_runtime_network_context_epoch(self, reason: str) -> int:
        """Revoke probes/readiness after sleep, NIC, route or DNS changes."""

        self._disarm_runtime_recovery(reason)
        self._enter_runtime_facility_hold(
            str(reason or "runtime network context is stabilizing")
        )
        with self._runtime_failure_monitor_lock:
            with self._runtime_route_snapshot_lock:
                # Node judgement P1-3: when the epoch changed (the observer's
                # 15 s evidence quiet window starts here).  Stored before the
                # epoch advances: the observer reads without this lock, epoch
                # first, so it never pairs the new epoch with an older time.
                self._runtime_network_context_epoch_changed_wall = time.time()
                self._runtime_network_context_epoch = int(
                    getattr(self, "_runtime_network_context_epoch", 0) or 0
                ) + 1
                epoch = self._runtime_network_context_epoch
                self._runtime_route_epoch += 1
                self._node_judgement_arm_epoch("advance_runtime_network_context_epoch")
                self._runtime_route_attribution_barrier_epoch = 0
                self._runtime_route_attribution_barrier_until = 0.0
                self._runtime_route_snapshot = None
                self._runtime_route_snapshot_payload = None
                self._runtime_core_inventory_snapshot = None
                self._runtime_route_selection_signature = ()
                with self._runtime_hot_standby_lock:
                    self._runtime_hot_standby_evidence.clear()
                    self._runtime_hot_standby_last_probe_at = 0.0
                    self._runtime_network_context_hold_active = True
                    self._runtime_network_context_hold_pending_candidate = False
                    self._runtime_network_context_hold_reason = str(
                        reason or "runtime network context is stabilizing"
                    )
                    self._runtime_network_context_hold_epoch = int(epoch)
                    self._runtime_network_context_rebase_stage = 0
                    self._runtime_network_context_rebase_at = time.monotonic() + 1.0
            self._defer_current_runtime_provisional_locked(
                str(reason or "network_context_change")
            )
            self._runtime_origin_diagnostic_bindings.clear()
        self._runtime_egress_coordinator.set_current_snapshot(None)
        self._runtime_route_stable_since = time.monotonic()
        self.logger.info(
            "Runtime network context changed; invalidated egress evidence "
            "(epoch=%s reason=%s)",
            epoch,
            reason,
        )
        self._queue_runtime_route_snapshot_refresh()
        self._wake_parked_tier3_pool_sync_if_causal_key_changed()
        return epoch

    def _runtime_facility_hold_cas_token(self) -> tuple[int, int]:
        """Freeze the hold and facility epochs under their canonical locks."""

        monitor_lock = getattr(self, "_runtime_failure_monitor_lock", None)
        if monitor_lock is None:
            monitor_lock = threading.RLock()
            self._runtime_failure_monitor_lock = monitor_lock
        route_lock = getattr(self, "_runtime_route_snapshot_lock", None)
        if route_lock is None:
            route_lock = threading.RLock()
            self._runtime_route_snapshot_lock = route_lock
        hot_lock = getattr(self, "_runtime_hot_standby_lock", None)
        if hot_lock is None:
            hot_lock = threading.RLock()
            self._runtime_hot_standby_lock = hot_lock
        with monitor_lock:
            with route_lock:
                with hot_lock:
                    return (
                        int(
                            getattr(
                                self,
                                "_runtime_network_context_hold_epoch",
                                0,
                            )
                            or 0
                        ),
                        int(
                            getattr(self, "_runtime_facility_epoch", 0) or 0
                        ),
                    )

    def _release_runtime_network_context_hold_after_verified_probe(
        self,
        *,
        expected_mutation_binding: CurrentMutationBinding | None = None,
        expected_hold_epoch: int | None = None,
        expected_facility_epoch: int | None = None,
        readiness: bool | None = True,
        readiness_reason: str = "",
        require_current_snapshot: bool = True,
        preserve_fail_closed_snapshot_key: tuple[Any, ...] | None = None,
    ) -> bool:
        """Close one facility interval without inventing route readiness.

        A verified ordinary 204 passes ``readiness=True``.  A controller-only
        proof of an incident-owned REJECT (or a stopped Core) may release node
        attribution while keeping effective egress false.  In both cases the
        boundary is serialized by monitor -> route -> hot-standby locks.
        """

        monitor_lock = getattr(self, "_runtime_failure_monitor_lock", None)
        if monitor_lock is None:
            monitor_lock = threading.RLock()
            self._runtime_failure_monitor_lock = monitor_lock
        route_lock = getattr(self, "_runtime_route_snapshot_lock", None)
        if route_lock is None:
            route_lock = threading.RLock()
            self._runtime_route_snapshot_lock = route_lock
        hot_lock = getattr(self, "_runtime_hot_standby_lock", None)
        if hot_lock is None:
            hot_lock = threading.RLock()
            self._runtime_hot_standby_lock = hot_lock
        if (
            expected_mutation_binding is not None
            and not self._runtime_mutation_binding_is_current(
                expected_mutation_binding
            )
        ):
            return False
        if self._runtime_local_data_plane_blocked():
            return False
        with monitor_lock:
            if (
                expected_mutation_binding is not None
                and not self._runtime_mutation_binding_is_current(
                    expected_mutation_binding
                )
            ):
                return False
            coordinator = getattr(self, "_runtime_egress_coordinator", None)
            current_snapshot = getattr(coordinator, "current_route_snapshot", None)
            snapshot = current_snapshot() if callable(current_snapshot) else None
            with route_lock:
                network_epoch = int(
                    getattr(self, "_runtime_network_context_epoch", 0) or 0
                )
                with hot_lock:
                    current_hold_epoch = int(
                        getattr(
                            self,
                            "_runtime_network_context_hold_epoch",
                            0,
                        )
                        or 0
                    )
                    current_facility_epoch = int(
                        getattr(self, "_runtime_facility_epoch", 0) or 0
                    )
                    if (
                        not bool(
                            getattr(
                                self,
                                "_runtime_network_context_hold_active",
                                False,
                            )
                        )
                        or bool(
                            getattr(
                                self,
                                "_runtime_network_context_hold_pending_candidate",
                                False,
                            )
                        )
                        or current_hold_epoch != network_epoch
                        or (
                            expected_hold_epoch is not None
                            and current_hold_epoch != int(expected_hold_epoch)
                        )
                        or (
                            expected_facility_epoch is not None
                            and current_facility_epoch
                            != int(expected_facility_epoch)
                        )
                        or (
                            require_current_snapshot
                            and (
                                snapshot is None
                                or int(snapshot.network_context_epoch)
                                != network_epoch
                            )
                        )
                    ):
                        return False
                    self._runtime_network_context_hold_active = False
                    self._runtime_network_context_hold_reason = ""
                    self._runtime_network_context_invalid_observed = False
                    self._runtime_network_context_rebase_stage = 0
                    self._runtime_network_context_rebase_at = 0.0
                    self._runtime_facility_epoch = int(
                        getattr(self, "_runtime_facility_epoch", 0) or 0
                    ) + 1
                if preserve_fail_closed_snapshot_key is not None:
                    self._runtime_confirmed_fail_closed_snapshot_key = tuple(
                        preserve_fail_closed_snapshot_key
                    )
            # Keep the monitor lock through publication so a new facility
            # transition cannot interleave between the epoch CAS and UI truth.
            self._set_effective_egress_readiness_state(
                readiness,
                str(readiness_reason or ""),
            )
        self._wake_parked_tier3_pool_sync_if_causal_key_changed()
        # A recovered leaf may have completed its authoritative PASS while a
        # facility epoch was open.  The old failback worker is correctly
        # revoked by that epoch, but the PASS must not be lost forever.  Resume
        # only after the hold and its locks are fully released so the new
        # worker receives a fresh CAS token.
        self._resume_runtime_deferred_after_facility_release()
        return True

    def _schedule_runtime_network_rebaseline_retry(
        self,
        expected_epoch: int,
        *,
        advance_failure_stage: bool,
    ) -> None:
        with self._runtime_failure_monitor_lock:
            with self._runtime_route_snapshot_lock:
                with self._runtime_hot_standby_lock:
                    if (
                        int(
                            getattr(
                                self,
                                "_runtime_network_context_hold_epoch",
                                0,
                            )
                            or 0
                        )
                        != int(expected_epoch)
                        or not bool(
                            getattr(
                                self,
                                "_runtime_network_context_hold_active",
                                False,
                            )
                        )
                    ):
                        return
                    stage = int(
                        getattr(self, "_runtime_network_context_rebase_stage", 0)
                        or 0
                    )
                    if advance_failure_stage:
                        delays = (2.0, 5.0, 30.0, 60.0, 120.0, 300.0)
                        delay = delays[min(stage, len(delays) - 1)]
                        self._runtime_network_context_rebase_stage = min(
                            stage + 1,
                            len(delays),
                        )
                    else:
                        # Probe capacity was unavailable; no socket verdict was
                        # produced and the real baseline stage is unchanged.
                        delay = 0.5
                    self._runtime_network_context_rebase_at = (
                        time.monotonic() + delay
                    )

    def _runtime_incident_owned_reject_rebaseline(
        self,
    ) -> CoreLoadedRouteSnapshot | None:
        """Read back the same incident's physical REJECT without external I/O."""

        monitor_lock = getattr(self, "_runtime_failure_monitor_lock", None)
        if monitor_lock is None:
            monitor_lock = threading.RLock()
            self._runtime_failure_monitor_lock = monitor_lock
        route_lock = getattr(self, "_runtime_route_snapshot_lock", None)
        if route_lock is None:
            route_lock = threading.RLock()
            self._runtime_route_snapshot_lock = route_lock
        with monitor_lock:
            lease = getattr(self, "_runtime_route_mutation_lease", None)
            lease_record = dict(lease) if isinstance(lease, dict) else None
            selector_revision = int(
                getattr(self, "_runtime_selector_intent_revision", 0) or 0
            )
        with route_lock:
            prior_fail_closed_key = getattr(
                self,
                "_runtime_confirmed_fail_closed_snapshot_key",
                None,
            )
        if not (
            lease_record is not None
            and str(lease_record.get("incident_id") or "")
            and str(lease_record.get("to") or "").upper() == "REJECT"
            and float(lease_record.get("verified_at_monotonic", 0.0) or 0.0)
            > 0.0
            and int(
                lease_record.get(
                    "selector_intent_revision",
                    selector_revision,
                )
                or 0
            )
            == selector_revision
            and prior_fail_closed_key is not None
        ):
            return None
        try:
            snapshot = self._refresh_runtime_route_snapshot(timeout_seconds=0.35)
        except Exception:
            return None
        current_snapshot, payload = self._runtime_route_snapshot_state()
        controller_payload = (
            payload.get("proxies") if isinstance(payload, dict) else None
        )
        if (
            snapshot is None
            or current_snapshot is None
            or tuple(snapshot.snapshot_key) != tuple(current_snapshot.snapshot_key)
            or int(snapshot.network_context_epoch)
            != int(getattr(self, "_runtime_network_context_epoch", 0) or 0)
            or not self._runtime_payload_has_reject_final_exit(controller_payload)
        ):
            return None
        with monitor_lock:
            current_lease = getattr(self, "_runtime_route_mutation_lease", None)
            if not (
                isinstance(current_lease, dict)
                and str(current_lease.get("incident_id") or "")
                == str(lease_record.get("incident_id") or "")
                and str(current_lease.get("to") or "").upper() == "REJECT"
                and int(
                    getattr(self, "_runtime_selector_intent_revision", 0) or 0
                )
                == selector_revision
            ):
                return None
        return snapshot

    def _maybe_rebaseline_runtime_network_context(self) -> None:
        if self._runtime_local_data_plane_blocked():
            return
        now = time.monotonic()
        monitor_lock = getattr(self, "_runtime_failure_monitor_lock", None)
        if monitor_lock is None:
            monitor_lock = threading.RLock()
            self._runtime_failure_monitor_lock = monitor_lock
        route_lock = getattr(self, "_runtime_route_snapshot_lock", None)
        if route_lock is None:
            route_lock = threading.RLock()
            self._runtime_route_snapshot_lock = route_lock
        hot_lock = getattr(self, "_runtime_hot_standby_lock", None)
        if hot_lock is None:
            hot_lock = threading.RLock()
            self._runtime_hot_standby_lock = hot_lock
        with monitor_lock:
            with route_lock:
                with hot_lock:
                    if (
                        not bool(
                            getattr(
                                self,
                                "_runtime_network_context_hold_active",
                                False,
                            )
                        )
                        or bool(
                            getattr(
                                self,
                                "_runtime_network_context_hold_pending_candidate",
                                False,
                            )
                        )
                        or now
                        < float(
                            getattr(
                                self,
                                "_runtime_network_context_rebase_at",
                                0.0,
                            )
                            or 0.0
                        )
                    ):
                        return
                    expected_epoch = int(
                        getattr(
                            self,
                            "_runtime_network_context_hold_epoch",
                            0,
                        )
                        or 0
                    )
                    expected_facility_epoch = int(
                        getattr(self, "_runtime_facility_epoch", 0) or 0
                    )
        runner_missing = not hasattr(self, "core_runner")
        runner = getattr(self, "core_runner", None)
        try:
            core_running = bool(
                runner_missing
                or (runner is not None and runner.is_running())
            )
        except Exception:
            core_running = False
        if not core_running:
            self._release_runtime_network_context_hold_after_verified_probe(
                expected_hold_epoch=expected_epoch,
                expected_facility_epoch=expected_facility_epoch,
                readiness=False,
                readiness_reason="Mihomo Core is stopped; route recovery is pending",
                require_current_snapshot=False,
            )
            return

        reject_snapshot = self._runtime_incident_owned_reject_rebaseline()
        if reject_snapshot is not None:
            if self._release_runtime_network_context_hold_after_verified_probe(
                expected_hold_epoch=expected_epoch,
                expected_facility_epoch=expected_facility_epoch,
                readiness=False,
                readiness_reason="FINAL-EXIT remains safely fail-closed; recovery is pending",
                preserve_fail_closed_snapshot_key=reject_snapshot.snapshot_key,
            ):
                return

        try:
            self._probe_mihomo_mixed_port_once(timeout_seconds=1.5)
        except _RuntimeProbeBudgetUnavailable:
            self._schedule_runtime_network_rebaseline_retry(
                expected_epoch,
                advance_failure_stage=False,
            )
            return
        except Exception:
            # If the controller can now bind a managed current leaf in the
            # stable network epoch, release facility attribution only and feed
            # the failed 204 back through the ordinary current-vs-alternative
            # differential circuit. This prevents an early unbound snapshot
            # from permanently excluding every healthy fallback.
            current_state = self._current_runtime_failure_binding_state(
                timeout_seconds=0.25,
            )
            if current_state is not None:
                current_binding, current_snapshot, _payload = current_state
                mutation_binding = self._runtime_mutation_binding_for_snapshot(
                    current_snapshot
                )
                if self._release_runtime_network_context_hold_after_verified_probe(
                    expected_mutation_binding=mutation_binding,
                    expected_hold_epoch=expected_epoch,
                    expected_facility_epoch=expected_facility_epoch,
                    readiness=None,
                    readiness_reason=(
                        "Runtime route is bound; differential verification is pending"
                    ),
                ):
                    self._submit_current_route_probe_failure(
                        "FINAL-EXIT facility baseline failed after route rebinding",
                        source="facility_rebaseline",
                    )
                    return
            self._schedule_runtime_network_rebaseline_retry(
                expected_epoch,
                advance_failure_stage=True,
            )
            return
        # A successful 204 is data-plane evidence, but it cannot release a
        # facility interval while ApplyConfig/controller churn has left the
        # route owner unknown. Rebuild the immutable snapshot first, then use
        # its mutation CAS for the release.
        authority = self._refresh_loaded_runtime_authority(
            timeout_seconds=0.75,
            require_managed_final_exit=True,
            worker_token=self._runtime_worker_token(),
        )
        if authority is None:
            self._schedule_runtime_network_rebaseline_retry(
                expected_epoch,
                advance_failure_stage=False,
            )
            return
        refreshed_snapshot, _refreshed_payload, _refreshed_binding = authority
        mutation_binding = self._runtime_mutation_binding_for_snapshot(
            refreshed_snapshot
        )
        if not self._release_runtime_network_context_hold_after_verified_probe(
            expected_mutation_binding=mutation_binding,
            expected_hold_epoch=expected_epoch,
            expected_facility_epoch=expected_facility_epoch,
        ):
            self._schedule_runtime_network_rebaseline_retry(
                expected_epoch,
                advance_failure_stage=True,
            )

    def _runtime_hot_standby_traffic_totals(self) -> tuple[int, int]:
        try:
            snapshot = self.traffic_monitor.snapshot()
            session = snapshot.get("session") if isinstance(snapshot, dict) else {}
            return (
                int((session or {}).get("upload_bytes") or 0),
                int((session or {}).get("download_bytes") or 0),
            )
        except Exception:
            return tuple(self._runtime_hot_standby_last_traffic_totals)

    def _runtime_traffic_active_for_hot_standby(self, now: float) -> bool:
        totals = self._runtime_hot_standby_traffic_totals()
        internal_probe_active = False
        with self._runtime_failure_monitor_lock:
            expired = [
                token
                for token, (_started, expires) in (
                    self._runtime_internal_probe_windows.items()
                )
                if float(expires) + 5.0 < now
            ]
            for token in expired:
                self._runtime_internal_probe_windows.pop(token, None)
            internal_probe_active = any(
                float(started) - 0.05 <= now <= float(expires)
                for started, expires in self._runtime_internal_probe_windows.values()
            )
        with self._runtime_hot_standby_lock:
            if totals != self._runtime_hot_standby_last_traffic_totals:
                self._runtime_hot_standby_last_traffic_totals = totals
                if internal_probe_active:
                    # `/traffic` cannot split application bytes from an
                    # overlapping internal request. Preserve that delta as
                    # unknown instead of discarding possible real activity.
                    self._runtime_hot_standby_pending_unknown_activity = True
                else:
                    self._runtime_hot_standby_last_active_at = now
                    self._runtime_hot_standby_pending_unknown_activity = False
            elif (
                not internal_probe_active
                and bool(
                    getattr(
                        self,
                        "_runtime_hot_standby_pending_unknown_activity",
                        False,
                    )
                )
            ):
                # No bytes arrived after the internal-probe window.  The only
                # observed delta therefore remains internal/unknown and cannot
                # manufacture sixty seconds of business activity.
                self._runtime_hot_standby_pending_unknown_activity = False
            last_active_at = float(self._runtime_hot_standby_last_active_at)
            return bool(
                last_active_at > 0.0 and now - last_active_at <= 60.0
            )

    def _refresh_one_runtime_hot_standby(self) -> None:
        if self._runtime_facility_hold_reason():
            return
        snapshot, payload = self._runtime_route_snapshot_state()
        if snapshot is None or not isinstance(payload, dict):
            return
        binding = self._runtime_route_binding_for_outbound(
            snapshot,
            payload,
            "FINAL-EXIT",
        )
        if binding is None:
            return
        final_binding = binding
        # A fixed Gateway is never itself an automatic selector candidate.
        # Keep the first two members of its dialer-proxy chain warm instead,
        # so a failed underlay can divert new dials without changing Gateway
        # identity. The immutable route snapshot binds this evidence to both
        # the selected Gateway and its exact underlay member.
        if binding.node.pool_kind == "gateway":
            underlay = self._runtime_gateway_underlay_binding(
                snapshot,
                payload,
                binding.node,
            )
            if underlay is None:
                return
            binding = underlay
        failure = BoundRuntimeFailure(
            binding=binding,
            protocol="PROBE",
            observed_outbound=binding.observed_outbound,
            destination_token=runtime_destination_token("hot-standby"),
            error_type="hot_standby_refresh",
            observed_at_monotonic=time.monotonic(),
        )
        candidates = self._runtime_ordered_alternative_refs(
            failure,
            snapshot,
            payload,
        )
        monitor_lock = getattr(self, "_runtime_failure_monitor_lock", None)
        if monitor_lock is None:
            automatic_lease = None
        else:
            with monitor_lock:
                route_lease = getattr(
                    self,
                    "_runtime_route_mutation_lease",
                    None,
                )
                automatic_lease = (
                    dict(route_lease)
                    if isinstance(route_lease, dict)
                    else None
                )
        promotion_keys: set[tuple[str, str, str, str]] = set()
        if (
            automatic_lease is not None
            and final_binding.node.pool_kind != "gateway"
        ):
            promotion_refs = self._runtime_higher_priority_promotion_refs(
                snapshot,
                payload,
                final_binding.node,
            )
            promotion_keys = {item.key for item in promotion_refs}
            candidates = promotion_refs + [
                ref
                for ref in candidates
                if ref.key not in promotion_keys
            ]
        candidates = candidates[:2]
        if not candidates:
            return
        with self._runtime_hot_standby_lock:
            index = self._runtime_hot_standby_next_index % len(candidates)
            self._runtime_hot_standby_next_index = (index + 1) % len(candidates)
        ref = candidates[index]
        action = self._runtime_alternative_switch_action(failure, ref, payload)
        if action is None:
            return
        selection_group = str(action.get("group") or "")
        selection_target = str(action.get("target") or "")
        selection_mode = str(action.get("mode") or "")
        probe_url = ""
        expected_status = ""
        if selection_mode == "fixed":
            probe_url, expected_status = self._runtime_group_probe_contract(
                snapshot,
                selection_group,
            )
        started = time.monotonic()
        probed_proxy_name = ref.proxy_name
        try:
            if (
                selection_mode == "fixed"
                and selection_target
                and selection_target != ref.proxy_name
            ):
                result = self._prewarm_runtime_switch_target(
                    snapshot,
                    action,
                    deadline_monotonic=(
                        time.monotonic()
                        + self._runtime_confirmation_timeout_ms(ref, payload)
                        / 1000.0
                    ),
                    probe_priority=ProbePriority.HOT_STANDBY,
                )
                probed_proxy_name = selection_target
            else:
                result = self._probe_runtime_leaf(
                    ref,
                    payload,
                    timeout_ms=self._runtime_confirmation_timeout_ms(ref, payload),
                    probe_url=probe_url or None,
                    expected_status=expected_status or None,
                    probe_priority=ProbePriority.HOT_STANDBY,
                )
        except _RuntimeProbeBudgetUnavailable:
            # Saturation is a probe-facility condition, not negative evidence
            # about a previously verified standby.
            return
        except Exception:
            with self._runtime_hot_standby_lock:
                self._runtime_hot_standby_evidence.pop(ref.key, None)
            return
        current = self._runtime_egress_coordinator.current_route_snapshot()
        if current is None or current.snapshot_key != snapshot.snapshot_key:
            return
        latency = result.get("delay") if isinstance(result, dict) else None
        if not isinstance(latency, (int, float)):
            latency = (time.monotonic() - started) * 1000.0
        evidence = _HotStandbyEvidence(
            ref=ref,
            action=dict(action),
            snapshot_key=snapshot.snapshot_key,
            network_context_epoch=snapshot.network_context_epoch,
            verified_at_monotonic=time.monotonic(),
            latency_ms=float(latency),
            probe_result=dict(result) if isinstance(result, dict) else {},
            selection_group=selection_group,
            selection_target=selection_target,
            selection_mode=selection_mode,
            probe_url=probe_url,
            expected_status=expected_status,
            probed_proxy_name=probed_proxy_name,
        )
        with self._runtime_hot_standby_lock:
            self._runtime_hot_standby_evidence[ref.key] = evidence
        if (
            self._runtime_policy_rank(ref)
            < self._runtime_policy_rank(final_binding.node)
            and self._runtime_hot_standby_contract_matches(
                evidence,
                snapshot,
                action,
            )
        ):
            self._maybe_start_higher_priority_failback(
                ref,
                current_ref=final_binding.node,
            )

    def _fresh_runtime_hot_standby(
        self,
        failure: BoundRuntimeFailure,
        snapshot: CoreLoadedRouteSnapshot,
        snapshot_payload: dict[str, Any],
    ) -> _HotStandbyEvidence | None:
        candidates = self._runtime_ordered_alternative_refs(
            failure,
            snapshot,
            snapshot_payload,
        )
        if not candidates:
            return None
        # Hot evidence is still policy evidence.  If the first eligible
        # candidate has no current authoritative proof, cold-confirm it; a
        # later standby may not overtake that indeterminate predecessor.
        ref = candidates[0]
        now = self._runtime_recovery_now()
        with self._runtime_hot_standby_lock:
            evidence = self._runtime_hot_standby_evidence.get(ref.key)
        action = self._runtime_alternative_switch_action(
            failure,
            ref,
            snapshot_payload,
        )
        if (
            evidence is not None
            and action is not None
            and evidence.snapshot_key == snapshot.snapshot_key
            and evidence.network_context_epoch
            == int(self._runtime_network_context_epoch)
            and now - evidence.verified_at_monotonic <= 45.0
            and self._runtime_hot_standby_contract_matches(
                evidence,
                snapshot,
                action,
            )
        ):
            return evidence
        return None

    def _start_runtime_hot_standby_maintenance(self) -> None:
        with self._runtime_hot_standby_lock:
            current = self._runtime_hot_standby_thread
            if current is not None and current.is_alive():
                return

        def worker() -> None:
            last_context_check = 0.0
            try:
                # Establish the scheduler/traffic baseline only after this
                # worker is genuinely running. A slow Core bootstrap must not
                # be interpreted as sleep/resume or as business activity.
                started = time.monotonic()
                baseline_totals = self._runtime_hot_standby_traffic_totals()
                with self._runtime_hot_standby_lock:
                    self._runtime_hot_standby_last_loop_at = started
                    self._runtime_hot_standby_last_probe_at = started
                    self._runtime_hot_standby_last_traffic_totals = baseline_totals
                    self._runtime_hot_standby_last_active_at = 0.0
                    self._runtime_hot_standby_was_active = False
                    self._runtime_hot_standby_pending_unknown_activity = False
                while not self.stop_event.wait(1.0):
                    now = time.monotonic()
                    with self._runtime_hot_standby_lock:
                        previous_loop = self._runtime_hot_standby_last_loop_at
                        self._runtime_hot_standby_last_loop_at = now
                    if previous_loop > 0.0 and now - previous_loop > 10.0:
                        self._advance_runtime_network_context_epoch(
                            "sleep_or_scheduler_resume",
                        )
                    if now - last_context_check >= 10.0:
                        observation = self._runtime_network_context_signature()
                        self._observe_runtime_network_context(observation)
                        last_context_check = now
                    self._maybe_recheck_runtime_local_facilities()
                    self._maybe_rebaseline_runtime_network_context()
                    active = self._runtime_traffic_active_for_hot_standby(now)
                    interval = 15.0 if active else 120.0
                    with self._runtime_hot_standby_lock:
                        became_active = bool(
                            active and not self._runtime_hot_standby_was_active
                        )
                        self._runtime_hot_standby_was_active = active
                        due = (
                            became_active
                            or now - self._runtime_hot_standby_last_probe_at
                            >= interval
                        )
                        if due:
                            self._runtime_hot_standby_last_probe_at = now
                    if due:
                        self._refresh_one_runtime_hot_standby()
            finally:
                with self._runtime_hot_standby_lock:
                    if self._runtime_hot_standby_thread is threading.current_thread():
                        self._runtime_hot_standby_thread = None

        thread = threading.Thread(
            target=worker,
            name="runtime-egress-hot-standby",
            daemon=True,
        )
        with self._runtime_hot_standby_lock:
            self._runtime_hot_standby_thread = thread
        thread.start()

    def _runtime_failure_monitor_loop(self) -> None:
        try:
            while not self.stop_event.is_set():
                queued = self._runtime_egress_coordinator.next_ingress(
                    timeout_seconds=0.25
                )
                if queued is None:
                    if not self._runtime_uses_early_single_coordinator():
                        self._maybe_probe_runtime_failure_guard()
                    else:
                        self._maybe_carry_runtime_ready("coordinator_idle")
                    continue
                try:
                    if isinstance(queued, _RuntimeOutputIngress):
                        self._handle_runtime_output_event(
                            queued.event,
                            queued.snapshot,
                            queued.snapshot_payload,
                            ingress_facility_epoch=queued.facility_epoch,
                            ingress_facility_hold_active=(
                                queued.facility_hold_active
                            ),
                            ingress_selector_intent_revision=queued.selector_intent_revision,
                        )
                    else:
                        # Compatibility for a pre-existing in-memory item
                        # during a source upgrade and narrow test doubles.
                        event, snapshot, payload = queued
                        self._handle_runtime_output_event(
                            event,
                            snapshot,
                            payload,
                        )
                except Exception:
                    log_raw_diagnostic(
                        self.logger,
                        "warning",
                        "Runtime egress event processing failed safely",
                        exc_info=True,
                    )
                finally:
                    # Overflow is sticky: schedule the one neutral guard as
                    # soon as the consumer makes progress, even when a burst
                    # keeps the queue continuously non-empty.
                    if not self._runtime_uses_early_single_coordinator():
                        self._maybe_probe_runtime_failure_guard()
                    else:
                        self._maybe_carry_runtime_ready("coordinator_event")
        finally:
            with self._runtime_failure_monitor_lock:
                if self._runtime_failure_monitor_thread is threading.current_thread():
                    self._runtime_failure_monitor_thread = None

    def _maybe_watch_runtime_path(self) -> None:
        """Compatibility hook: idle monitoring performs no external probes."""
        return None

    def _enqueue_passive_node_health_check(
        self, ref: RuntimeNodeRef, *, reason: str,
    ) -> None:
        """Request an authoritative check without inventing a failed verdict."""
        enqueue = getattr(getattr(self, "manager", None), "enqueue_node_health_check", None)
        if callable(enqueue):
            now = time.monotonic()
            key = (
                int(getattr(self, "_runtime_generation", -1)),
                int(getattr(self, "_runtime_selector_intent_revision", 0) or 0),
                ref.key, str(reason),
            )
            with self._runtime_failure_monitor_lock:
                checks = getattr(self, "_runtime_passive_recheck_times", {})
                if now - checks.get(key, -float("inf")) < 2.0:
                    return
                self._runtime_passive_recheck_times = {
                    item: checked_at for item, checked_at in checks.items()
                    if now - checked_at < 2.0
                }
                self._runtime_passive_recheck_times[key] = now
            enqueue(ref, reason=reason, source="runtime_transport")

    def _handle_runtime_output_event_passive(
        self,
        event: CoreOutputEvent,
        snapshot: CoreLoadedRouteSnapshot | None,
        snapshot_payload: dict[str, Any],
        *,
        ingress_selector_intent_revision: int | None = None,
    ) -> None:
        """Refresh local authority once per error burst, then confirm the leaf.

        A route change invalidates attribution, not observation permission.
        Old leaves receive an ordinary identity-bound check; they cannot lend
        their error to the replacement leaf or mutate its route directly.
        """
        if not self._runtime_monitoring_is_active():
            return
        lease = self._runtime_monitoring_lease
        observed = float(event.received_at_monotonic)
        now = time.monotonic()
        if (
            observed < lease.admitted_at_monotonic
            or now - observed >= 6.0
            or int(event.pid) != lease.process_pid
            or int(event.process_generation) != lease.process_generation
        ):
            return
        selector_revision = int(getattr(self, "_runtime_selector_intent_revision", 0) or 0)
        if ingress_selector_intent_revision not in (None, -1, selector_revision):
            return
        parsed = runtime_transport_failure_from_log(
            event.raw_line, observed_at_monotonic=observed,
        )
        if (
            parsed is None or parsed.facility_hint
            or self._runtime_transport_failure_is_internal_probe(parsed)
        ):
            return
        worker_token = self._runtime_worker_token()
        refresh_key = (worker_token, selector_revision)
        try:
            live_snapshot, live_payload = self._runtime_route_snapshot_state()
            if (
                self._runtime_passive_refresh_key == refresh_key
                and now < self._runtime_passive_refresh_until
                and live_snapshot is not None and isinstance(live_payload, dict)
            ):
                fresh = (live_snapshot, live_payload, None)
            else:
                fresh = self._refresh_loaded_runtime_authority(
                    timeout_seconds=min(0.5, max(0.05, observed + 6.0 - now)),
                    require_managed_final_exit=True,
                    worker_token=worker_token,
                )
                if fresh is not None:
                    self._runtime_passive_refresh_key = refresh_key
                    self._runtime_passive_refresh_until = time.monotonic() + 0.25
        except Exception:
            return  # Controller uncertainty never becomes node failure.
        if (
            fresh is None or not self._runtime_monitoring_is_active()
            or not self._runtime_worker_token_is_current(worker_token)
            or int(getattr(self, "_runtime_selector_intent_revision", 0) or 0)
            != selector_revision
        ):
            return
        current_snapshot, current_payload, _ = fresh
        failure = self._bind_runtime_transport_failure(parsed, current_snapshot, current_payload)
        if failure is None:
            return
        old_failure = (
            self._bind_runtime_transport_failure(parsed, snapshot, snapshot_payload)
            if isinstance(snapshot, CoreLoadedRouteSnapshot) else None
        )
        route_changed = bool(
            snapshot is None
            or snapshot.snapshot_key != current_snapshot.snapshot_key
            or self._runtime_route_attribution_barrier_active(current_snapshot, observed)
        )
        if (
            old_failure is not None
            and old_failure.binding.node.key != failure.binding.node.key
            and snapshot.core_generation == current_snapshot.core_generation
            and snapshot.semantic_digest == current_snapshot.semantic_digest
            and snapshot.network_context_epoch == current_snapshot.network_context_epoch
            and any(ref.key == old_failure.binding.node.key for ref in current_snapshot.proxy_nodes)
        ):
            self._enqueue_passive_node_health_check(
                old_failure.binding.node, reason="native_route_drift",
            )
        # Even when the original line belongs to a retired route, a real error
        # permits bounded confirmation of the current route. Only the ensuing
        # independent A/B probes can establish that its leaf is unhealthy.
        gateway_ref = None
        if failure.binding.node.pool_kind == "gateway":
            gateway_ref = failure.binding.node
            underlay = self._runtime_gateway_underlay_binding(
                current_snapshot, current_payload, gateway_ref,
            )
            if underlay is None:
                self._enqueue_passive_node_health_check(
                    gateway_ref, reason="gateway_runtime_error",
                )
                return
            failure = BoundRuntimeFailure.from_parsed(parsed, underlay)
        if route_changed:
            failure = BoundRuntimeFailure(
                binding=failure.binding,
                protocol="PROBE",
                observed_outbound=failure.binding.observed_outbound,
                destination_token=parsed.destination_token,
                error_type="route_changed_after_transport_failure",
                observed_at_monotonic=observed,
            )
        decision = self._runtime_egress_coordinator.observe(
            failure, current_snapshot=current_snapshot,
        )
        if decision.accepted and decision.start_probe:
            self._start_runtime_early_confirmation(
                failure, current_snapshot, current_payload,
                probe_token=decision.probe_token,
                incident_id=decision.incident_id,
                gateway_ref=gateway_ref,
            )

    def _handle_runtime_output_event_early(
        self,
        event: CoreOutputEvent,
        snapshot: CoreLoadedRouteSnapshot,
        snapshot_payload: dict[str, Any],
        *,
        ingress_selector_intent_revision: int | None = None,
    ) -> None:
        """Consume one stdout error without facility/guard retry ownership."""

        if hasattr(self, "_runtime_monitoring_lease"):
            self._handle_runtime_output_event_passive(
                event, snapshot, snapshot_payload,
                ingress_selector_intent_revision=ingress_selector_intent_revision,
            )
            return

        if not self._runtime_recovery_is_armed(snapshot):
            return
        monitor_lock = getattr(self, "_runtime_failure_monitor_lock", None)
        if monitor_lock is None:
            arm = getattr(self, "_runtime_recovery_arm", None)
        else:
            with monitor_lock:
                arm = getattr(self, "_runtime_recovery_arm", None)
        if (
            isinstance(arm, _RuntimeRecoveryArm)
            and float(event.received_at_monotonic)
            < float(arm.armed_at_monotonic)
        ):
            # A pre-READY line may remain in the bounded queue until after the
            # verified route is armed. It is evidence about the old startup
            # window and can never create a live leaf incident.
            return
        parsed = runtime_transport_failure_from_log(
            event.raw_line,
            observed_at_monotonic=event.received_at_monotonic,
        )
        if parsed is None or self._runtime_transport_failure_is_internal_probe(
            parsed
        ):
            return
        current = self._runtime_egress_coordinator.current_route_snapshot()
        if (
            current is None
            or tuple(current.snapshot_key) != tuple(snapshot.snapshot_key)
        ):
            # Missing or changed authority is attribution-neutral.  A future
            # real event may try again after a fresh snapshot publication, but
            # this event creates no hold, guard, epoch, or retry timer.
            return
        if self._runtime_route_attribution_barrier_active(
            snapshot,
            event.received_at_monotonic,
        ):
            return
        failure = self._bind_runtime_transport_failure(
            parsed,
            snapshot,
            snapshot_payload,
        )
        if failure is None:
            return
        if failure.binding.node.pool_kind == "gateway":
            underlay = self._runtime_gateway_underlay_binding(
                snapshot,
                snapshot_payload,
                failure.binding.node,
            )
            if underlay is None:
                return
            failure = BoundRuntimeFailure(
                binding=underlay,
                protocol=failure.protocol,
                observed_outbound=underlay.observed_outbound,
                destination_token=failure.destination_token,
                error_type=failure.error_type,
                observed_at_monotonic=failure.observed_at_monotonic,
                flow_token=failure.flow_token,
                mux_token=failure.mux_token,
                failure_phase=failure.failure_phase,
                deterministic_proxy_endpoint=(
                    failure.deterministic_proxy_endpoint
                ),
                facility_hint=failure.facility_hint,
            )
        decision = self._runtime_egress_coordinator.observe(
            failure,
            current_snapshot=snapshot,
        )
        if not decision.accepted:
            return
        if decision.facility:
            self._runtime_egress_coordinator.finish_indeterminate(
                failure.binding,
                incident_id=decision.incident_id,
                quarantine_token=decision.probe_token,
            )
            return
        if decision.start_probe:
            self._start_runtime_early_confirmation(
                failure,
                snapshot,
                snapshot_payload,
                probe_token=decision.probe_token,
                incident_id=decision.incident_id,
            )

    def _handle_runtime_output_event(
        self,
        event: CoreOutputEvent,
        snapshot: CoreLoadedRouteSnapshot,
        snapshot_payload: dict[str, Any],
        *,
        ingress_facility_epoch: int | None = None,
        ingress_facility_hold_active: bool = False,
        ingress_selector_intent_revision: int | None = None,
    ) -> None:
        if self._runtime_uses_early_single_coordinator():
            self._handle_runtime_output_event_early(
                event,
                snapshot,
                snapshot_payload,
                ingress_selector_intent_revision=ingress_selector_intent_revision,
            )
            return
        if not self._runtime_recovery_is_armed(snapshot):
            # Recheck at consumption time: a queued K1 line cannot cross a
            # manual selection, reload, facility epoch, or Core generation.
            return
        if (
            bool(ingress_facility_hold_active)
            or (
                ingress_facility_epoch is not None
                and int(ingress_facility_epoch)
                != int(getattr(self, "_runtime_facility_epoch", 0) or 0)
            )
        ):
            # Do not re-enter a hold after recovery merely because an old WAN
            # burst was waiting in the bounded queue.
            return
        facility_hold = self._runtime_facility_hold_reason()
        if facility_hold:
            # A listener/DNS facility failure can cause every downstream dial
            # to fail.  Once that evidence exists, queued transport lines are
            # facility evidence, never additional votes against a leaf.
            self._record_runtime_facility_degradation(facility_hold)
            return
        attribution_hold = self._runtime_node_attribution_hold_reason()
        if attribution_hold:
            # The already-loaded proxy path may still be serving traffic, but
            # controller/unknown listener ownership is insufficient to bind a
            # business error to a managed leaf or to commit a selector write.
            self._queue_runtime_route_snapshot_refresh()
            return
        parsed = runtime_transport_failure_from_log(
            event.raw_line,
            observed_at_monotonic=event.received_at_monotonic,
        )
        if parsed is None:
            return
        if self._runtime_transport_failure_is_internal_probe(parsed):
            return
        # The stdout reader captured this immutable loaded snapshot alongside
        # the line.  Do not put a controller round-trip in front of every real
        # business failure: the coordinator's current snapshot is the CAS.
        current_snapshot = self._runtime_egress_coordinator.current_route_snapshot()
        if current_snapshot is None:
            self._start_runtime_facility_confirmation(
                "Core-loaded route snapshot is unavailable for log attribution"
            )
            return
        if current_snapshot.snapshot_key != snapshot.snapshot_key:
            # Fallback/selector ownership changed while the line was queued.
            # Confirm the new route neutrally; never assign the old line to
            # whichever leaf took over afterwards.
            self._submit_current_route_probe_failure(
                "Core route changed while a transport failure was being attributed",
                source="route_change_guard",
            )
            return
        if self._runtime_route_attribution_barrier_active(
            snapshot,
            event.received_at_monotonic,
        ):
            # Existing sockets cannot be migrated by a selector write. Mihomo
            # may emit an old terminal line after the new route is visible;
            # without a connection-to-route proof, never charge the new leaf.
            self._start_runtime_facility_confirmation(
                "Transport error arrived inside the route-mutation attribution barrier"
            )
            return
        failure = self._bind_runtime_transport_failure(
            parsed,
            snapshot,
            snapshot_payload,
        )
        if failure is None:
            route = inspect_runtime_route(
                snapshot_payload.get("proxies"),
                start=str(getattr(parsed, "observed_outbound", "") or ""),
            )
            chain = {
                str(item)
                for item in (route.get("selected_chain") or [])
            }
            if (
                "FINAL-EXIT" not in chain
                and str(getattr(parsed, "observed_outbound", ""))
                != "FINAL-EXIT"
            ):
                return
            self._start_runtime_facility_confirmation(
                "Mihomo transport failure could not be bound to the loaded managed route"
            )
            return
        decision = self._runtime_egress_coordinator.observe(
            failure,
            current_snapshot=snapshot,
        )
        provisional_started = False
        if (
            decision.divert_recommended
            and not decision.confirmed
            and failure.binding.node.pool_kind != "gateway"
        ):
            hot_standby = self._fresh_runtime_hot_standby(
                failure,
                snapshot,
                snapshot_payload,
            )
            if hot_standby is not None:
                provisional_started = self._start_runtime_provisional_diversion(
                    failure,
                    snapshot,
                    snapshot_payload,
                    incident_id=decision.incident_id,
                    probe_token=decision.probe_token,
                    evidence=hot_standby,
                )
        # One incident has one probe phase at a time.  Starting confirmation
        # here as well would let its current+alternative pair consume both
        # global slots while the provisional selector transaction waits for
        # its post-switch 204 pair, guaranteeing self-starvation under the
        # bounded fast-path deadline.
        monitor_lock = getattr(self, "_runtime_failure_monitor_lock", None)
        if monitor_lock is None:
            provisional_active = False
        else:
            with monitor_lock:
                provisional_active = (
                    ("provisional", *failure.circuit_key)
                    in self._runtime_failure_recovery_bindings
                )
        if (
            (decision.start_probe or decision.confirmed)
            and not provisional_started
            and not provisional_active
        ):
            self._start_runtime_independent_probe(
                failure,
                snapshot,
                snapshot_payload,
                probe_token=decision.probe_token,
            )

    @staticmethod
    def _runtime_proxy_info_for_ref(
        snapshot_payload: dict[str, Any],
        ref: RuntimeNodeRef,
    ) -> dict[str, Any]:
        proxy_map = snapshot_payload.get("proxy_map")
        if not isinstance(proxy_map, dict):
            return {}
        info = proxy_map.get(ref.proxy_name)
        return dict(info) if isinstance(info, dict) else {}

    def _probe_runtime_leaf(
        self,
        ref: RuntimeNodeRef,
        snapshot_payload: dict[str, Any],
        *,
        timeout_ms: int = 1500,
        probe_url: str | None = None,
        expected_status: str | int | None = None,
        probe_priority: ProbePriority = ProbePriority.RUNTIME_MANUAL,
        recovery_ticket: _RuntimeRecoveryTicket | None = None,
        recovery_deadline_monotonic: float | None = None,
    ) -> dict[str, Any]:
        info = self._runtime_proxy_info_for_ref(snapshot_payload, ref)
        node = info.get("node")
        urls = [str(probe_url)] if probe_url else (
            self._probe_urls_for_node(node)
            if node is not None
            else self._default_probe_urls()
        )
        return self._probe_proxy_delay_with_urls(
            ref.proxy_name,
            list(urls)[:1],
            timeout_ms=timeout_ms,
            request_timeout_seconds=max(0.1, float(timeout_ms) / 1000.0) + 0.25,
            expected_status=expected_status,
            probe_priority=probe_priority,
            recovery_ticket=recovery_ticket,
            recovery_deadline_monotonic=recovery_deadline_monotonic,
        )

    def _runtime_confirmation_timeout_ms(
        self,
        ref: RuntimeNodeRef,
        snapshot_payload: dict[str, Any],
    ) -> int:
        """Adaptive confirmation deadline: clamp(3*healthy RTT+200, 500, 1500)."""

        info = self._runtime_proxy_info_for_ref(snapshot_payload, ref)
        node = info.get("node")
        candidates = (
            getattr(node, "latency", None),
            getattr(node, "latency_ms", None),
            getattr(node, "delay_ms", None),
        )
        recent_rtt = next(
            (
                float(value)
                for value in candidates
                if isinstance(value, (int, float)) and float(value) > 0.0
            ),
            100.0,
        )
        return int(max(500.0, min(1500.0, 3.0 * recent_rtt + 200.0)))

    def _runtime_recovery_now(self) -> float:
        """Return the injectable monotonic clock used by recovery budgets."""

        clock = getattr(self, "_runtime_recovery_monotonic", None)
        return float(clock() if callable(clock) else time.monotonic())

    def _runtime_recovery_remaining(
        self,
        deadline_monotonic: float,
        *,
        cap: float | None = None,
    ) -> float:
        remaining = max(
            0.0,
            float(deadline_monotonic) - self._runtime_recovery_now(),
        )
        return min(remaining, max(0.0, float(cap))) if cap is not None else remaining

    def _runtime_candidate_health_snapshot(self) -> Any | None:
        """Freeze Manager health once without coupling Manager to Core types.

        Production Manager exposes an immutable exact-key snapshot.  Narrow
        legacy fixtures predate that contract and intentionally return
        ``None`` here; the loaded Core snapshot still remains authoritative in
        those fixtures.  A production snapshot failure is fail-closed.
        """

        manager = getattr(self, "manager", None)
        getter = getattr(manager, "runtime_candidate_snapshot", None)
        if not callable(getter):
            return None
        try:
            return getter()
        except Exception:
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Runtime candidate health snapshot could not be frozen",
                exc_info=True,
            )
            return False

    @staticmethod
    def _runtime_candidate_health_key(value: Any) -> tuple[str, str, str]:
        key = getattr(value, "key", None)
        if isinstance(key, (tuple, list)) and len(key) >= 3:
            return tuple(str(item) for item in key[:3])  # type: ignore[return-value]
        return (
            str(getattr(value, "tier", "") or ""),
            str(getattr(value, "pool_kind", "") or ""),
            str(getattr(value, "identity", "") or ""),
        )

    def _runtime_candidate_is_eligible(
        self,
        health_snapshot: Any | None,
        ref: RuntimeNodeRef,
    ) -> bool:
        if health_snapshot is None:
            # Compatibility only.  Production always has Manager's immutable
            # candidate snapshot and therefore never enters this branch.
            return True
        if health_snapshot is False:
            return False
        candidates = getattr(health_snapshot, "candidates", ())
        # Manager owns health; the frozen Core-loaded graph owns proxy names.
        # Re-generating aliases from mutable Manager rows can make every
        # otherwise healthy candidate disappear after filtering/reordering.
        exact = (str(ref.tier), str(ref.pool_kind), str(ref.identity))
        matches = [
            item
            for item in tuple(candidates or ())
            if self._runtime_candidate_health_key(item) == exact
        ]
        if len(matches) != 1:
            return False
        entry = matches[0]
        eligible = getattr(entry, "eligible", None)
        if eligible is not None:
            return bool(eligible)
        raw = getattr(entry, "raw_status", "")
        raw_text = str(getattr(raw, "value", raw) or "").strip().upper()
        effective_usable = bool(
            getattr(entry, "usable", getattr(entry, "effective_usable", False))
        )
        incident_active = bool(
            getattr(
                entry,
                "incident_active",
                getattr(entry, "active_incident", False),
            )
        )
        pending_recheck = bool(
            getattr(
                entry,
                "pending_recheck",
                getattr(entry, "recheck_pending", False),
            )
        )
        return bool(
            raw_text in {"ALIVE", "SLOW"}
            and effective_usable
            and not incident_active
            and not pending_recheck
        )

    def _runtime_candidate_health_revision_is_current(
        self,
        frozen: Any | None,
    ) -> bool:
        if frozen is None:
            return True
        if frozen is False:
            return False
        manager = getattr(self, "manager", None)
        getter = getattr(manager, "runtime_candidate_snapshot", None)
        if not callable(getter):
            return False
        try:
            current = getter()
        except Exception:
            return False
        return bool(
            int(getattr(current, "revision", -1))
            == int(getattr(frozen, "revision", -2))
            and int(getattr(current, "runtime_generation", -1))
            == int(getattr(frozen, "runtime_generation", -2))
        )

    def _try_runtime_incident_provider_rebase(
        self,
        failure: BoundRuntimeFailure,
        snapshot: CoreLoadedRouteSnapshot,
        snapshot_payload: dict[str, Any],
        *,
        recovery_ticket: _RuntimeRecoveryTicket,
        deadline_monotonic: float,
    ) -> tuple[
        CoreLoadedRouteSnapshot | None,
        dict[str, Any] | None,
        dict[str, Any],
    ]:
        """Append new Tier3B capacity once after loaded candidates are exhausted."""

        result: dict[str, Any] = {
            "attempted": False,
            "updated": False,
            "reason": "no eligible unloaded capacity",
        }
        if not isinstance(recovery_ticket, _RuntimeRecoveryTicket):
            result["reason"] = "recovery ticket is unavailable"
            return None, None, result
        remaining = self._runtime_recovery_remaining(deadline_monotonic)
        if remaining < 1.0:
            result["reason"] = "incident budget cannot safely admit a provider rebase"
            return None, None, result
        if not self._runtime_recovery_ticket_is_current(
            recovery_ticket,
            require_open=True,
            deadline_monotonic=deadline_monotonic,
        ):
            result["reason"] = "recovery ticket was superseded"
            return None, None, result
        if not any(
            str(group_name) == "TIER3-AUTO"
            for group_name, _members in snapshot.group_graph
        ):
            result["reason"] = "loaded route has no expandable Tier3 provider"
            return None, None, result

        health_snapshot = self._runtime_candidate_health_snapshot()
        if health_snapshot is False:
            result.update(
                {
                    "indeterminate": True,
                    "reason": "candidate health snapshot is unavailable",
                }
            )
            return None, None, result
        loaded_identities = {
            (ref.tier, ref.pool_kind, ref.identity)
            for ref in snapshot.proxy_nodes
        }
        unloaded_eligible = tuple(
            candidate
            for candidate in getattr(health_snapshot, "candidates", ())
            if bool(getattr(candidate, "eligible", False))
            and str(getattr(candidate, "pool_kind", "")) == "tier3b"
            and self._runtime_candidate_health_key(candidate)
            not in loaded_identities
        )
        if not unloaded_eligible:
            return None, None, result

        incident_id = recovery_ticket.incident_id
        with self._runtime_failure_monitor_lock:
            rebases = getattr(self, "_runtime_incident_provider_rebases", None)
            if not isinstance(rebases, dict):
                rebases = {}
                self._runtime_incident_provider_rebases = rebases
            if incident_id in rebases:
                result["reason"] = "incident provider rebase already has a terminal result"
                return None, None, result
            if not self._runtime_recovery_ticket_matches_locked(
                recovery_ticket,
                require_open=True,
                deadline_monotonic=deadline_monotonic,
            ):
                result["reason"] = "recovery ticket was superseded"
                return None, None, result
            rebases[incident_id] = (recovery_ticket.generation, "running")

        result["attempted"] = True
        # Reserve 500 ms for the first newly loaded candidate. The caller has
        # already reserved a separate tail for selector readback and final 204.
        provider_deadline = float(deadline_monotonic) - 0.5
        try:
            provider_result = self._update_running_tier3_core_provider(
                self._tier3_core_sync_marker(),
                recovery_ticket=recovery_ticket,
                deadline_monotonic=provider_deadline,
                preserve_route_authority=True,
            )
        except Exception as exc:
            provider_result = {
                "updated": False,
                "unknown": True,
                "reason": type(exc).__name__,
            }
        result.update(
            {
                "updated": bool(provider_result.get("updated")),
                "unknown": bool(provider_result.get("unknown")),
                "stale": bool(provider_result.get("stale")),
                "reason": str(
                    provider_result.get("reason")
                    or "incident provider rebase did not commit"
                ),
            }
        )

        refreshed_snapshot: CoreLoadedRouteSnapshot | None = None
        refreshed_payload: dict[str, Any] | None = None
        if provider_result.get("updated"):
            candidate_snapshot, candidate_payload = self._runtime_route_snapshot_state()
            if (
                isinstance(candidate_snapshot, CoreLoadedRouteSnapshot)
                and isinstance(candidate_payload, dict)
                and tuple(candidate_snapshot.snapshot_key)
                == tuple(snapshot.snapshot_key)
                and self._runtime_recovery_ticket_is_current(
                    recovery_ticket,
                    require_open=True,
                    deadline_monotonic=deadline_monotonic,
                )
            ):
                newly_loaded = {
                    (ref.tier, ref.pool_kind, ref.identity)
                    for ref in candidate_snapshot.proxy_nodes
                }.difference(loaded_identities)
                expected_loaded = {
                    self._runtime_candidate_health_key(candidate)
                    for candidate in unloaded_eligible
                }
                if newly_loaded.intersection(expected_loaded):
                    refreshed_snapshot = candidate_snapshot
                    refreshed_payload = candidate_payload

        if refreshed_snapshot is None:
            result["updated"] = False
            if provider_result.get("updated"):
                result["unknown"] = True
                result["reason"] = (
                    "provider rebase committed without stable route authority readback"
                )
        elif "FINAL-EXIT" not in failure.binding.route_chain:
            before_gateway = self._runtime_route_binding_for_outbound(
                snapshot,
                snapshot_payload,
                "FINAL-EXIT",
            )
            after_gateway = self._runtime_route_binding_for_outbound(
                refreshed_snapshot,
                refreshed_payload,
                "FINAL-EXIT",
            )
            if (
                before_gateway is None
                or before_gateway.node.pool_kind != "gateway"
                or after_gateway is None
                or tuple(after_gateway.node.key) != tuple(before_gateway.node.key)
            ):
                refreshed_snapshot = None
                refreshed_payload = None
                result.update(
                    {
                        "updated": False,
                        "unknown": True,
                        "reason": "fixed Gateway identity changed during capacity rebase",
                    }
                )

        with self._runtime_failure_monitor_lock:
            current = self._runtime_incident_provider_rebases.get(incident_id)
            if current == (recovery_ticket.generation, "running"):
                terminal = "committed" if refreshed_snapshot is not None else "failed"
                self._runtime_incident_provider_rebases[incident_id] = (
                    recovery_ticket.generation,
                    terminal,
                )
        self._log_runtime_recovery_phase(
            "capacity_rebase",
            ticket=recovery_ticket,
            candidate_index=0,
            candidate_total=len(unloaded_eligible),
            budget_ms=max(0, int(remaining * 1000.0)),
            reason_code=(
                "committed" if refreshed_snapshot is not None else "not_committed"
            ),
        )
        return refreshed_snapshot, refreshed_payload, result

    def _probe_managed_alternative(
        self,
        failure: BoundRuntimeFailure,
        snapshot: CoreLoadedRouteSnapshot,
        snapshot_payload: dict[str, Any],
        *,
        max_parallel: int = 2,
        deadline_monotonic: float | None = None,
        recovery_ticket: _RuntimeRecoveryTicket | None = None,
    ) -> tuple[RuntimeNodeRef | None, dict[str, Any] | None]:
        health_snapshot = self._runtime_candidate_health_snapshot()
        if health_snapshot is False:
            return None, {"probe_indeterminate": True}
        orderer = self._runtime_ordered_alternative_refs
        try:
            orderer_parameters = inspect.signature(orderer).parameters.values()
        except (TypeError, ValueError):
            orderer_parameters = ()
        if any(
            parameter.kind is inspect.Parameter.VAR_KEYWORD
            or parameter.name == "_candidate_health_snapshot"
            for parameter in orderer_parameters
        ):
            candidates = orderer(
                failure,
                snapshot,
                snapshot_payload,
                _candidate_health_snapshot=health_snapshot,
            )
        else:
            # Compatibility for focused fixtures replacing the orderer.
            candidates = orderer(failure, snapshot, snapshot_payload)
        candidates = list(candidates)
        if self._runtime_uses_early_single_coordinator():
            candidates = candidates[:4]
        if not candidates:
            return None, None
        def probe_contract_for(ref: RuntimeNodeRef) -> tuple[str, str]:
            action = self._runtime_alternative_switch_action(
                failure,
                ref,
                snapshot_payload,
            )
            group = (
                str(action.get("group") or "")
                if isinstance(action, dict)
                else failure.binding.observed_outbound
            )
            return self._runtime_group_probe_contract(snapshot, group)
        coordinator = getattr(self, "_runtime_egress_coordinator", None)
        current_for = getattr(coordinator, "current_snapshot_for", None)
        if recovery_ticket is None and callable(current_for):
            try:
                incident = current_for(failure.binding)
                incident_id = str(getattr(incident, "incident_id", "") or "")
                lock = getattr(self, "_runtime_failure_monitor_lock", None)
                if lock is not None and incident_id:
                    with lock:
                        value = getattr(
                            self,
                            "_runtime_recovery_tickets",
                            {},
                        ).get(incident_id)
                    if isinstance(value, _RuntimeRecoveryTicket):
                        recovery_ticket = value
            except Exception:
                recovery_ticket = None

        # Candidate order is policy. Probe at most two concurrently, and wait
        # for both members of a wave before choosing the lowest-index PASS;
        # network latency must never reorder tiers or protocol variants.
        deadline = (
            float(deadline_monotonic)
            if deadline_monotonic is not None
            else self._runtime_recovery_now() + 6.0
        )
        wave_size = max(1, min(2, int(max_parallel)))
        for wave_start in range(0, len(candidates), wave_size):
            wave = candidates[wave_start : wave_start + wave_size]
            now = self._runtime_recovery_now()
            remaining = deadline - now
            # A cold candidate is never issued with less than the documented
            # 500 ms minimum.  Running it anyway would turn deadline pressure
            # into a false negative and allow a lower-priority candidate to
            # overtake missing evidence.
            if remaining < 0.5:
                return None, {"probe_indeterminate": True}
            timeouts_ms = {
                ref.key: min(
                    self._runtime_confirmation_timeout_ms(ref, snapshot_payload),
                    max(1, int(remaining * 1000.0)),
                )
                for ref in wave
            }
            wave_deadline = min(
                deadline,
                now + max(timeouts_ms.values()) / 1000.0,
            )
            if wave_size == 1:
                ref = wave[0]
                self._log_runtime_recovery_phase(
                    "candidate_probe",
                    ticket=recovery_ticket,
                    candidate=ref,
                    candidate_index=wave_start + 1,
                    candidate_total=len(candidates),
                    budget_ms=timeouts_ms[ref.key],
                )
                try:
                    probe_url, expected_status = probe_contract_for(ref)
                    value = self._probe_runtime_leaf(
                        ref,
                        snapshot_payload,
                        timeout_ms=timeouts_ms[ref.key],
                        probe_url=probe_url,
                        expected_status=expected_status,
                        recovery_ticket=recovery_ticket,
                        recovery_deadline_monotonic=deadline,
                    )
                except _RuntimeProbeBudgetUnavailable:
                    self._log_runtime_recovery_phase(
                        "candidate_indeterminate",
                        ticket=recovery_ticket,
                        candidate=ref,
                        candidate_index=wave_start + 1,
                        candidate_total=len(candidates),
                        budget_ms=timeouts_ms[ref.key],
                        reason_code="probe_budget_unavailable",
                    )
                    return None, {"probe_indeterminate": True}
                except Exception as exc:
                    if isinstance(exc, (TypeError, AttributeError)) or (
                        self._proxy_delay_failure_is_transient(exc)
                    ):
                        self._log_runtime_recovery_phase(
                            "candidate_indeterminate",
                            ticket=recovery_ticket,
                            candidate=ref,
                            candidate_index=wave_start + 1,
                            candidate_total=len(candidates),
                            budget_ms=timeouts_ms[ref.key],
                            reason_code="controller_probe_indeterminate",
                        )
                        return None, {"probe_indeterminate": True}
                    value = None
                if value is not None:
                    if not self._runtime_candidate_health_revision_is_current(
                        health_snapshot
                    ):
                        return None, {"probe_indeterminate": True}
                    self._log_runtime_recovery_phase(
                        "candidate_accepted",
                        ticket=recovery_ticket,
                        candidate=ref,
                        candidate_index=wave_start + 1,
                        candidate_total=len(candidates),
                        budget_ms=timeouts_ms[ref.key],
                    )
                    return ref, value
                self._log_runtime_recovery_phase(
                    "candidate_rejected",
                    ticket=recovery_ticket,
                    candidate=ref,
                    candidate_index=wave_start + 1,
                    candidate_total=len(candidates),
                    budget_ms=timeouts_ms[ref.key],
                    reason_code="authoritative_probe_failed",
                )
                if self._runtime_recovery_now() >= deadline:
                    break
                continue
            results: queue.Queue[
                tuple[int, RuntimeNodeRef, dict[str, Any] | None]
            ] = queue.Queue(maxsize=len(wave))

            def probe(index: int, ref: RuntimeNodeRef) -> None:
                try:
                    probe_url, expected_status = probe_contract_for(ref)
                    value = self._probe_runtime_leaf(
                        ref,
                        snapshot_payload,
                        timeout_ms=timeouts_ms[ref.key],
                        probe_url=probe_url,
                        expected_status=expected_status,
                        recovery_ticket=recovery_ticket,
                        recovery_deadline_monotonic=deadline,
                    )
                except _RuntimeProbeBudgetUnavailable:
                    value = {"probe_indeterminate": True}
                except Exception as exc:
                    value = (
                        {"probe_indeterminate": True}
                        if isinstance(exc, (TypeError, AttributeError))
                        or self._proxy_delay_failure_is_transient(exc)
                        else None
                    )
                try:
                    results.put_nowait((index, ref, value))
                except queue.Full:
                    pass

            for index, ref in enumerate(wave, start=wave_start):
                self._log_runtime_recovery_phase(
                    "candidate_probe",
                    ticket=recovery_ticket,
                    candidate=ref,
                    candidate_index=index + 1,
                    candidate_total=len(candidates),
                    budget_ms=timeouts_ms[ref.key],
                )
                threading.Thread(
                    target=probe,
                    args=(index, ref),
                    name="runtime-egress-alternative-probe",
                    daemon=True,
                ).start()

            observed: dict[int, tuple[RuntimeNodeRef, dict[str, Any] | None]] = {}
            while len(observed) < len(wave):
                remaining = wave_deadline - self._runtime_recovery_now()
                if remaining <= 0.0:
                    break
                try:
                    index, ref, value = results.get(timeout=remaining)
                except queue.Empty:
                    break
                observed[index] = (ref, value)
            for index in range(wave_start, wave_start + len(wave)):
                if index not in observed:
                    # The companion did not finish inside the evidence
                    # deadline. Its socket may still be queued or in flight;
                    # absence of a result is never proof of candidate failure.
                    self._log_runtime_recovery_phase(
                        "candidate_indeterminate",
                        ticket=recovery_ticket,
                        candidate=candidates[index],
                        candidate_index=index + 1,
                        candidate_total=len(candidates),
                        budget_ms=timeouts_ms[candidates[index].key],
                        reason_code="probe_deadline_missing",
                    )
                    return None, {"probe_indeterminate": True}
                ref, value = observed[index]
                if bool(
                    isinstance(value, dict)
                    and value.get("probe_indeterminate")
                ):
                    self._log_runtime_recovery_phase(
                        "candidate_indeterminate",
                        ticket=recovery_ticket,
                        candidate=ref,
                        candidate_index=index + 1,
                        candidate_total=len(candidates),
                        budget_ms=timeouts_ms[ref.key],
                        reason_code="probe_budget_unavailable",
                    )
                    return None, {"probe_indeterminate": True}
                if value is not None:
                    if not self._runtime_candidate_health_revision_is_current(
                        health_snapshot
                    ):
                        return None, {"probe_indeterminate": True}
                    self._log_runtime_recovery_phase(
                        "candidate_accepted",
                        ticket=recovery_ticket,
                        candidate=ref,
                        candidate_index=index + 1,
                        candidate_total=len(candidates),
                        budget_ms=timeouts_ms[ref.key],
                    )
                    return ref, value
                self._log_runtime_recovery_phase(
                    "candidate_rejected",
                    ticket=recovery_ticket,
                    candidate=ref,
                    candidate_index=index + 1,
                    candidate_total=len(candidates),
                    budget_ms=timeouts_ms[ref.key],
                    reason_code="authoritative_probe_failed",
                )
            if self._runtime_recovery_now() >= deadline:
                break
        if not self._runtime_candidate_health_revision_is_current(
            health_snapshot
        ):
            return None, {"probe_indeterminate": True}
        return None, None

    def _runtime_ordered_alternative_refs(
        self,
        failure: BoundRuntimeFailure,
        snapshot: CoreLoadedRouteSnapshot,
        snapshot_payload: dict[str, Any],
        *,
        _candidate_health_snapshot: Any = _RUNTIME_CANDIDATE_SNAPSHOT_UNSET,
    ) -> list[RuntimeNodeRef]:
        """Return eligible managed alternatives in loaded policy order.

        Every layer is traversed from the selected member forward.  Earlier
        members are never revisited after a failure and the search is not
        truncated, so a healthy fifth-or-later member remains reachable.
        """

        if failure.binding.node.pool_kind == "gateway":
            # A fixed Gateway is not an ordinary exit candidate. Its exact
            # underlay may recover independently, but Gateway itself remains
            # fail-closed.
            return []

        proxies_payload = snapshot_payload.get("proxies")
        route = inspect_runtime_route(
            proxies_payload,
            start=failure.binding.observed_outbound,
        )
        attempted: set[str] = {failure.binding.node.proxy_name}
        candidates: list[RuntimeNodeRef] = []
        health_snapshot = (
            self._runtime_candidate_health_snapshot()
            if _candidate_health_snapshot is _RUNTIME_CANDIDATE_SNAPSHOT_UNSET
            else _candidate_health_snapshot
        )
        if health_snapshot is False:
            return []
        layers = list(route.get("layers") or [])
        for layer in reversed(layers):
            current = str(layer.get("now") or "")
            members = [
                str(item or "").strip()
                for item in list(layer.get("candidates") or [])
                if str(item or "").strip()
            ]
            try:
                current_index = members.index(current)
            except ValueError:
                # A missing controller selection makes this layer
                # non-authoritative; do not wrap to its first member.
                continue
            for raw_candidate in members[current_index + 1 :]:
                candidate = str(raw_candidate or "").strip()
                if not candidate or builtin_terminal_kind(candidate):
                    continue
                candidate_route = inspect_runtime_route(
                    proxies_payload,
                    start=candidate,
                )
                if candidate_route.get("facility_failure"):
                    continue
                leaf = str(candidate_route.get("leaf_proxy") or candidate)
                if leaf in attempted or builtin_terminal_kind(leaf):
                    continue
                attempted.add(leaf)
                ref = self._runtime_snapshot_node(snapshot, leaf)
                if ref is None:
                    continue
                if not self._runtime_candidate_is_eligible(
                    health_snapshot,
                    ref,
                ):
                    continue
                candidates.append(ref)
        return candidates

    def _runtime_early_differential_plans(
        self,
        failure: BoundRuntimeFailure,
        snapshot: CoreLoadedRouteSnapshot,
        snapshot_payload: dict[str, Any],
    ) -> list[dict[str, Any]]:
        """Freeze ordered A/B probes with one exact group contract per pair."""

        health_snapshot = self._runtime_candidate_health_snapshot()
        if health_snapshot is False:
            return []
        orderer = self._runtime_ordered_alternative_refs
        try:
            candidates = orderer(
                failure,
                snapshot,
                snapshot_payload,
                _candidate_health_snapshot=health_snapshot,
            )
        except TypeError:
            candidates = orderer(failure, snapshot, snapshot_payload)
        plans: list[dict[str, Any]] = []
        for ref in candidates:
            if not isinstance(ref, RuntimeNodeRef):
                continue
            action = self._runtime_alternative_switch_action(
                failure,
                ref,
                snapshot_payload,
            )
            if not isinstance(action, dict):
                continue
            group = str(action.get("group") or "")
            if not group:
                continue
            probe_url, expected_status = self._runtime_group_probe_contract(
                snapshot,
                group,
            )
            plans.append(
                {
                    "ref": ref,
                    "action": dict(action),
                    "probe_url": probe_url,
                    "expected_status": expected_status,
                }
            )
        return plans

    @staticmethod
    def _runtime_policy_rank(ref: RuntimeNodeRef) -> tuple[int, int]:
        """Coarse loaded-policy rank used only after a fixed lease is released.

        Exact member ordering remains Mihomo's loaded group contract.  This
        rank answers the narrower question whether its natural winner belongs
        to a layer that is at least as preferred as the recovered incident
        leaf; it never chooses a member itself.
        """

        tier_rank = {
            "exit": 0,
            "tier1": 10,
            "tier2": 20,
            "tier3": 30,
        }.get(str(ref.tier or "").casefold(), 100)
        pool_rank = {
            "gateway": 0,
            "tier1_variant": 0,
            "tier2": 0,
            "tier3a": 0,
            "tier3b": 1,
        }.get(str(ref.pool_kind or "").casefold(), 9)
        return tier_rank, pool_rank

    def _runtime_higher_priority_promotion_refs(
        self,
        snapshot: CoreLoadedRouteSnapshot,
        snapshot_payload: dict[str, Any],
        current_ref: RuntimeNodeRef,
    ) -> list[RuntimeNodeRef]:
        """Resolve earlier loaded fallback members without changing selection.

        A diversion can pin a lower layer long after Tier1/Tier2 becomes
        healthy.  Only members preceding the current member of a loaded
        fallback group are promotion candidates; selector order remains user
        intent and is never reinterpreted here.
        """

        if current_ref.pool_kind == "gateway":
            return []
        route = inspect_runtime_route(
            snapshot_payload.get("proxies"),
            start="FINAL-EXIT",
        )
        seen: set[tuple[str, str, str, str]] = set()
        candidates: list[RuntimeNodeRef] = []
        for layer in list(route.get("layers") or []):
            if str(layer.get("type") or "").casefold() != "fallback":
                continue
            members = [
                str(item or "").strip()
                for item in list(layer.get("candidates") or [])
                if str(item or "").strip()
            ]
            selected = str(layer.get("now") or "").strip()
            try:
                selected_index = members.index(selected)
            except ValueError:
                continue
            for member in members[:selected_index]:
                member_route = inspect_runtime_route(
                    snapshot_payload.get("proxies"),
                    start=member,
                )
                if member_route.get("facility_failure"):
                    continue
                leaf = str(member_route.get("leaf_proxy") or member)
                if builtin_terminal_kind(leaf):
                    continue
                ref = self._runtime_snapshot_node(snapshot, leaf)
                if (
                    ref is None
                    or ref.key in seen
                    or self._runtime_policy_rank(ref)
                    >= self._runtime_policy_rank(current_ref)
                ):
                    continue
                seen.add(ref.key)
                candidates.append(ref)
                if len(candidates) >= 2:
                    return candidates
        return candidates

    def _maybe_start_higher_priority_failback(
        self,
        ref: RuntimeNodeRef,
        *,
        current_ref: RuntimeNodeRef,
    ) -> None:
        """Turn a fresh higher-layer standby PASS into event-driven promotion."""

        if self._runtime_policy_rank(ref) >= self._runtime_policy_rank(
            current_ref
        ):
            return
        now = time.monotonic()
        with self._runtime_failure_monitor_lock:
            lease = self._runtime_route_mutation_lease
            if not isinstance(lease, dict):
                return
            incident_id = str(lease.get("incident_id") or "")
            selector_revision = int(
                getattr(self, "_runtime_selector_intent_revision", 0) or 0
            )
            if (
                not incident_id
                or str(lease.get("to") or "").upper() == "REJECT"
                or int(
                    lease.get(
                        "selector_intent_revision",
                        selector_revision,
                    )
                    or 0
                )
                != selector_revision
                or incident_id not in self._runtime_incident_bindings
                or not isinstance(
                    self._runtime_incident_route_payloads.get(incident_id),
                    dict,
                )
            ):
                return
            history = self._runtime_failback_pass_history.setdefault(
                ref.key,
                [],
            )
            history.append(now)
            self._runtime_failback_pass_history[ref.key] = history[-4:]
        self._start_runtime_failback(
            {
                "incident_id": incident_id,
                "tier": ref.tier,
                "pool_kind": ref.pool_kind,
                "identity": ref.identity,
                "proxy_name": ref.proxy_name,
                "transition": {"action": "recovered"},
                "promotion_source": "hot_standby_higher_priority",
            },
            ref,
        )

    def _runtime_natural_winner_is_acceptable(
        self,
        winner: RuntimeNodeRef,
        recovered: RuntimeNodeRef,
    ) -> bool:
        if winner.key == recovered.key:
            return True
        # Gateway identity is an external user contract.  Its underlay may
        # recover naturally, but no automatic route transaction may accept a
        # different Gateway as an equivalent winner.
        if recovered.pool_kind == "gateway" or winner.pool_kind == "gateway":
            return False
        return self._runtime_policy_rank(winner) < self._runtime_policy_rank(
            recovered
        )

    @staticmethod
    def _runtime_proxy_entries(snapshot_payload: dict[str, Any]) -> dict[str, Any]:
        return mihomo_proxies_entries(snapshot_payload)

    def _runtime_alternative_switch_action(
        self,
        failure: BoundRuntimeFailure,
        alternative: RuntimeNodeRef,
        snapshot_payload: dict[str, Any],
        *,
        allow_pf_subtree_select: bool = False,
    ) -> dict[str, Any] | None:
        """Find the deepest loaded group that can select the proven route.

        With ``tier_ladder_judge`` on (any judge mode) and
        ``allow_pf_subtree_select`` false, select groups below
        PROXY-FALLBACK are skipped (spec §2.3 D4 select-write guard).
        """

        if failure.binding.node.pool_kind == "gateway":
            # A fixed Gateway is never replaced automatically. Its managed
            # dialer-proxy may arrive here as a separate non-gateway binding.
            return None
        proxies_payload = snapshot_payload.get("proxies")
        entries = self._runtime_proxy_entries(snapshot_payload)
        route = inspect_runtime_route(
            proxies_payload,
            start=failure.binding.observed_outbound,
        )
        pf_subtree: frozenset[str] | None = None
        if not allow_pf_subtree_select:
            policy = self._node_judgement_policy()
            if policy.enabled and policy.tier_ladder_judge:
                pf_subtree = tier_ladder.descendant_groups_of_payload(entries)
        for layer in reversed(list(route.get("layers") or [])):
            group = str(layer.get("name") or "")
            entry = entries.get(group)
            if not group or not isinstance(entry, dict):
                continue
            if pf_subtree is not None and group in pf_subtree:
                layer_type = str(entry.get("typeName") or entry.get("type") or "").casefold()
                if "select" in layer_type or "selector" in layer_type:
                    continue
            current = str(layer.get("now") or "")
            for raw_candidate in list(layer.get("candidates") or []):
                candidate = str(raw_candidate or "").strip()
                if (
                    not candidate
                    or candidate == current
                    or builtin_terminal_kind(candidate)
                ):
                    continue
                candidate_route = inspect_runtime_route(
                    proxies_payload,
                    start=candidate,
                )
                if candidate_route.get("facility_failure"):
                    continue
                leaf = str(candidate_route.get("leaf_proxy") or candidate)
                if leaf != alternative.proxy_name:
                    continue
                type_name = str(
                    entry.get("typeName") or entry.get("type") or ""
                ).casefold()
                mode = (
                    "selector"
                    if "select" in type_name or "selector" in type_name
                    else "fixed"
                )
                if (
                    self._active_gateway_policy_enabled()
                    and group == "FINAL-EXIT"
                ):
                    continue
                return {
                    "group": group,
                    "target": candidate,
                    "previous": current,
                    "mode": mode,
                    "alternative_leaf": alternative.proxy_name,
                }
        return None

    def _node_judgement_policy(self) -> NodeJudgementPolicy:
        """Design v3 P0-6: ``client.egress_recovery.node_judgement``.

        Parsed from the live config on every use, exactly like
        ``egress_recovery_policy``, so a config reload takes effect at the
        next decision and there is no cached copy to refresh.
        ``enabled: false`` turns every flag off (today's code paths).
        """

        return node_judgement_policy(getattr(self, "config", None))

    def _node_judgement_state(self) -> _NodeJudgementRuntimeState:
        state = self.__dict__.get("_node_judgement_runtime_state")
        if not isinstance(state, _NodeJudgementRuntimeState):
            state = self.__dict__.setdefault(
                "_node_judgement_runtime_state",
                _NodeJudgementRuntimeState(),
            )
        return state

    # -- Node judgement P1-3: post-dial observer (design v3 §18.4) ----------

    def _ensure_runtime_post_dial_observer(self, lease: Any) -> bool:
        """Run one observer for the committed monitoring lease; never raises.

        Only when ``node_judgement.enabled`` and ``post_dial_judge`` is
        ``shadow`` or ``act`` (and egress recovery is on).  An observer of an
        older lease is replaced; the same lease keeps its observer.  A late
        call for a lease that is no longer the committed one, or one racing a
        Core stop, leaves the slot alone.
        """

        lock = self.__dict__.get("_runtime_post_dial_observer_lock")
        if lock is None:
            # Narrow embedders predating the observer install no tap.
            return False
        try:
            mode, _act_rules = self._runtime_post_dial_mode()
            if mode not in {"shadow", "act"} or not isinstance(
                lease, _RuntimeMonitoringLease
            ):
                self._stop_runtime_post_dial_observer("disabled")
                return False
            with lock:
                # Checked under the observer lock: every revocation (a new
                # commit, the monitor reset, the stopping/stopped phase)
                # changes this state first and then takes this lock to stop
                # the slot, so it either sees the revocation here or stops
                # the observer started here.  The phase is read without
                # ``_core_lifecycle_lock`` (a plain attribute read) so this
                # lock never nests inside it.
                phase = str(self.__dict__.get("_core_runtime_phase") or "")
                if phase in {"stopping", "stopped"} or not (
                    self._runtime_post_dial_observer_is_current(lease)
                ):
                    return False
                current = self.__dict__.get("_runtime_post_dial_observer")
                if (
                    current is not None
                    and self.__dict__.get("_runtime_post_dial_observer_lease")
                    is lease
                ):
                    if current.is_alive():
                        return True
                    if current.stop_reason != "disabled":
                        # One observer per lease: one that ended on its own
                        # (no controller, an error) is not restarted by the
                        # re-arm ticks that commit this lease again.
                        return False
                runner = self._build_runtime_post_dial_observer(lease)
                self._runtime_post_dial_observer = runner
                self._runtime_post_dial_observer_lease = lease
                self._runtime_post_dial_tap = runner.tap
                runner.start()
            if current is not None:
                current.stop("lease_replaced")
            return True
        except Exception:
            logger = getattr(self, "logger", None)
            if isinstance(logger, logging.Logger):
                log_raw_diagnostic(
                    logger,
                    "warning",
                    "Post-dial observer could not start",
                    exc_info=True,
                )
            return False

    def _stop_runtime_post_dial_observer(
        self,
        reason: str,
        *,
        join_timeout: float = 0.0,
    ) -> bool:
        """Detach the tap and signal the observer; optionally join it."""

        lock = self.__dict__.get("_runtime_post_dial_observer_lock")
        if lock is None:
            return False
        with lock:
            runner = self.__dict__.get("_runtime_post_dial_observer")
            self._runtime_post_dial_observer = None
            self._runtime_post_dial_observer_lease = None
            self._runtime_post_dial_tap = None
        overshoot_event = self.__dict__.get("_runtime_overshoot_event")
        if overshoot_event is not None:
            # overshoot_repair worker: re-checks its exit conditions.
            overshoot_event.set()
        if runner is None:
            return False
        runner.stop(str(reason or "stopped"))
        if join_timeout > 0.0:
            runner.join(float(join_timeout))
        return True

    def _build_runtime_post_dial_observer(
        self,
        lease: _RuntimeMonitoringLease,
    ) -> PostDialObserverRunner:
        policy = self._node_judgement_policy()
        tokenizer = self._node_judgement_state().tokenizer
        for warning in node_judgement_config_warnings(getattr(self, "config", None)):
            if warning == "overshoot_repair_requires_tier_ladder_judge":
                # Once per observer build (spec §2.1); the config stays valid.
                self._log_runtime_post_dial_record(
                    "info",
                    {
                        "ev": "config_warning",
                        "key": "overshoot_repair",
                        "reason": "requires_tier_ladder_judge",
                    },
                )
        core = PostDialObserverCore(
            tokenizer=tokenizer,
            constants=policy.constants(),
            act_rules=policy.act_rule_ids,
            gateway_groups=_POST_DIAL_GATEWAY_GROUPS,
        )
        tap = PostDialTap(
            pid=int(lease.process_pid),
            process_generation=int(lease.process_generation),
            maxlen=int(core.constants.tap_maxlen),
        )

        arm_scope = self._node_judgement_arm_scope()

        def on_trigger(trigger: Any, mode: str) -> None:
            self._node_judgement_arm_trigger(arm_scope, trigger, mode, tokenizer)

        # P2: exoneration, hold release and the demotion-watch closes.  In
        # shadow mode no judgement ever runs, so these are no-ops.
        judge = self._runtime_post_dial_judge()
        return PostDialObserverRunner(
            tap=tap,
            core=core,
            # Built on the observer thread: keeps the READY path cheap.
            origin_rules_factory=self._runtime_post_dial_origin_rules,
            controller_factory=self._runtime_post_dial_controller,
            is_current=lambda: self._runtime_post_dial_observer_is_current(lease),
            mode=self._runtime_post_dial_mode,
            route_snapshot=lambda: getattr(self, "_runtime_route_snapshot", None),
            route_context_for=self._runtime_post_dial_route_context_for,
            network_epoch=self._runtime_post_dial_network_epoch,
            on_trigger=on_trigger,
            emit=lambda level, record: self._node_judgement_arm_observer_emit(level, record, arm_scope),
            on_diagnostics_retired=lambda: self._node_judgement_arm_retire(arm_scope),
            diagnostics_emit=(lambda level, record: self._node_judgement_arm_observer_emit(
                level, record, arm_scope)) if arm_scope is not None else None,
            is_exonerated=judge.is_exonerated,
            on_snapshot=judge.on_snapshot,
            on_watch=judge.on_watch_step,
        )

    def _runtime_post_dial_mode(self) -> tuple[str, frozenset[str]]:
        """``(post_dial_judge, act rule ids)``; ``off`` whenever disabled."""

        diag_read_token = self._node_judgement_arm_begin()
        policy = self._node_judgement_policy()
        if not policy.observer_enabled:
            self._node_judgement_arm_mode_observed(False, diag_read_token)
            return "off", frozenset()
        try:
            recovery_enabled = egress_recovery_policy(
                getattr(self, "config", None) or {}
            ).enabled
        except Exception:
            recovery_enabled = False
        if not recovery_enabled:
            self._node_judgement_arm_mode_observed(False, diag_read_token)
            return "off", frozenset()
        self._node_judgement_arm_mode_observed(True, diag_read_token)
        return str(policy.post_dial_judge), frozenset(policy.act_rule_ids)

    def _runtime_post_dial_observer_is_current(
        self,
        lease: _RuntimeMonitoringLease,
    ) -> bool:
        """In-memory lease check (no controller call, no runner status)."""

        stop_event = getattr(self, "stop_event", None)
        if stop_event is not None and stop_event.is_set():
            return False
        if getattr(self, "_runtime_monitoring_lease", None) is not lease:
            return False
        return bool(
            int(getattr(self, "_runtime_generation", -1)) == lease.runtime_generation
            and int(getattr(self, "_core_generation", -1)) == lease.core_generation
            and int(getattr(self, "_lifecycle_revision", 0) or 0)
            == lease.lifecycle_revision
        )

    def _runtime_post_dial_controller(self) -> Any:
        """The observer's single keep-alive controller connection (P0-1)."""

        client = getattr(self, "api_client", None)
        if client is None:
            return None
        return MihomoControllerKeepAlive.from_client(client)

    def _runtime_post_dial_origin_rules(self) -> OriginRules:
        """System rules as the loaded config renders them (Conf-3, Conf-5).

        The same URL set clash_formatter compiles into FINAL-EXIT system rules:
        every configured probe URL plus the geodata download URLs.
        """

        config = getattr(self, "config", None) or {}
        urls = list(default_probe_urls(config))
        try:
            geo = geo_update_block(config)
            geox = geo.get("geox_url") or geo.get("geox-url") or None
            urls.extend(_clash_normalize_geox_url(geox).values())
        except Exception:
            pass
        inbounds = list(_POST_DIAL_USER_INBOUNDS)
        # The TUN inbound carries user traffic in mixed mode (TUN + system
        # proxy) exactly as in tun mode.
        if str(getattr(self, "network_mode", "") or "") in {"tun", "mixed"}:
            inbounds.append(_POST_DIAL_TUN_INBOUND)
        return OriginRules.from_system_rules(
            build_final_exit_system_rules(urls),
            user_inbound_names=inbounds,
        )

    @staticmethod
    def _runtime_post_dial_route_context(
        snapshot: Any,
    ) -> PostDialRouteContext | None:
        """TIER3-AUTO ``all`` minus Reject from a published route snapshot."""

        group_state = getattr(snapshot, "group_state", None)
        if not callable(group_state):
            return None
        state = group_state("TIER3-AUTO")
        members = (
            node_judgement_contract_order(state.members)
            if state is not None
            else ()
        )
        return PostDialRouteContext(
            tier3_members=frozenset(members),
            gateway_groups=frozenset(_POST_DIAL_GATEWAY_GROUPS),
        )

    def _runtime_post_dial_network_epoch(self) -> tuple[int, float | None]:
        # Epoch first, then its timestamp: the writer stores the timestamp
        # before it advances the epoch, so a new epoch is never paired with
        # the previous change's time.
        epoch = int(getattr(self, "_runtime_network_context_epoch", 0) or 0)
        changed = getattr(self, "_runtime_network_context_epoch_changed_wall", None)
        return epoch, float(changed) if changed is not None else None

    def _on_runtime_post_dial_trigger(
        self,
        trigger: Any,
        *,
        mode: str,
        tokenizer: PostDialTokenizer,
    ) -> None:
        """The act-rule trigger seam (FAST/AGED), on the observer thread.

        The ``trigger`` (act) or ``would_trigger`` (shadow) line is logged
        once per episode.  Shadow mode (act is the default) then logs one
        ``would_judge`` and does nothing else: no probe, close or route
        change.  Act mode passes every evaluation to the judge, because a
        gate may clear while the episode still matches.
        """

        if bool(getattr(trigger, "new_episode", False)):
            record = dict(post_dial_trigger_record(trigger, tokenizer, mode=mode))
            record["mode"] = str(mode)
            self._log_runtime_post_dial_record("info", record)
        self._start_runtime_post_dial_judgement(trigger, mode=str(mode))

    # -- Node judgement P2-2: post-dial judge (design v3 §18.5-18.7) --------

    def _runtime_post_dial_judge(self) -> PostDialJudgeService:
        """The runtime's one judge service (gates, worker, watch closes)."""

        state = self._node_judgement_state()
        with state.lock:
            judge = state.judge
            if judge is None:
                # Tier ladder hooks (spec §4.7), passed only to a hooks type
                # that declares them; a legacy judgement never calls them.
                hook_fields = getattr(PostDialJudgeHooks, "__dataclass_fields__", {})
                ladder_hooks = {
                    name: hook
                    for name, hook in (
                        ("ladder_check", self._runtime_post_dial_ladder_check),
                        ("ladder_escalate", self._runtime_post_dial_ladder_escalate),
                        ("ladder_end", self._runtime_post_dial_ladder_end),
                        ("provisional_move", self._runtime_post_dial_provisional_move),
                        ("successor_history", self._runtime_post_dial_successor_history),
                    )
                    if name in hook_fields
                }
                judge = PostDialJudgeService(
                    hooks=PostDialJudgeHooks(
                        probe=self._runtime_post_dial_contract_probe,
                        read_route=self._runtime_post_dial_route_read,
                        read_leaf=self._runtime_post_dial_leaf_read,
                        commit=self._runtime_post_dial_native_commit,
                        finish=self._runtime_post_dial_finish,
                        close=self._runtime_post_dial_close,
                        close_enabled=self._runtime_post_dial_close_enabled,
                        route_moved=self._runtime_post_dial_route_moved,
                        **ladder_hooks,
                    ),
                    tokenizer=state.tokenizer,
                    emit=self._log_runtime_post_dial_record,
                    clock=self._runtime_recovery_now,
                )
                state.judge = judge
        return judge

    def _start_runtime_post_dial_judgement(self, trigger: Any, *, mode: str) -> bool:
        """Design v3 §18.5: the §3.3 gates, then one judgement (act mode only).

        Never raises.  Shadow mode logs ``would_judge`` once per episode with
        the first gate that would block, evaluated read-only (no ticket, no
        refresh), and stops.  Act mode checks the gates in order (armed,
        judging, facility/exhausted hold, D4 on the binding, leaf back-off,
        per-leaf and global caps, status-failure sample), binds the trigger
        to the published FINAL-EXIT route (L must be its TIER3-AUTO leaf),
        registers the judge's own recovery ticket (6 s cap; the registry is
        keyed by incident, so it sits beside an open D4 ticket without
        touching it) and starts the judge worker.  A blocked trigger is
        logged ``gated`` once per episode and reason.
        """

        try:
            policy = self._node_judgement_policy()
            if mode == "act" and policy.acts:
                return self._start_runtime_post_dial_judgement_act(trigger)
            if mode == "shadow" and bool(getattr(trigger, "new_episode", False)):
                self._log_runtime_post_dial_would_judge(trigger)
        except Exception as exc:
            logger = getattr(self, "logger", None)
            if isinstance(logger, logging.Logger):
                log_raw_diagnostic(
                    logger,
                    "warning",
                    "Post-dial judgement could not start (error_type=%s)",
                    type(exc).__name__,
                )
        return False

    def _start_runtime_post_dial_judgement_act(self, trigger: Any) -> bool:
        diag_ticket = self._node_judgement_arm_permit()
        judge = self._runtime_post_dial_judge()
        leaf = str(trigger.leaf)
        episode = int(getattr(trigger, "episode", 0) or 0)
        now = self._runtime_recovery_now()
        source, arm_check, evaluated = "cheap", "not_evaluated", False
        # 10-28 ship2 fix keys 2 and 3 (each default False), read per trigger.
        fix_policy = self._node_judgement_policy()
        judge.backoff_override_on = bool(fix_policy.not_reproduced_override)
        judge.successor_timeout_hold = bool(fix_policy.exhausted_hold)
        # 10-28 seamless keys (each default False), read per trigger.
        judge.provisional_move_on = bool(fix_policy.post_dial_provisional_move)
        judge.successor_history_on = bool(fix_policy.post_dial_successor_from_history)
        judge.fast_successor_on = bool(fix_policy.post_dial_fast_successor)
        observer = self.__dict__.get("_runtime_post_dial_observer")
        observer_core = getattr(observer, "core", None)
        if observer_core is not None and hasattr(observer_core, "close_frozen_streams"):
            observer_core.close_frozen_streams = bool(fix_policy.post_dial_close_frozen_streams)
        reason = (
            judge.blocked_cheap(leaf, now, trigger)
            if judge.backoff_override_on
            else judge.blocked_cheap(leaf, now)
        )
        if reason is None and self._runtime_post_dial_exhausted_admission(judge, leaf):
            # Fix 2 (10-28; judge act + exhausted_hold): the published
            # TIER3-AUTO view is exhausted.
            reason = "exhausted_hold"
        if reason is None:
            # Keyed on the published snapshot object, read before the gates:
            # any publication in between only causes one more evaluation.
            route_key = self._runtime_post_dial_route_refs()[0]
            cached, cached_reason = judge.recent_gate(leaf, episode, now, route_key)
            cache_key = (leaf, episode, id(route_key))
            if cached:
                source = "cached"
                reason = cached_reason
                diag_state = None if diag_ticket is None else diag_ticket[0]
                if diag_state is not None:
                    with diag_state["lock"]:
                        if self._node_judgement_arm_valid_locked(diag_ticket):
                            arm_check = diag_state["cache"].get(cache_key, "cached_unknown")
            else:
                source, evaluated = "checked", True
                refresh_outcome: dict[str, Any] = {}
                with self._node_judgement_arm_capture() as gate_trace:
                    job, reason = self._runtime_post_dial_admission(
                        trigger,
                        judge,
                        now=now,
                        register=True,
                        outcome=refresh_outcome,
                    )
                arm_check = str(gate_trace.get("admission_arm_check") or "override_unknown")
                diag_state = None if diag_ticket is None else diag_ticket[0]
                if diag_state is not None:
                    with diag_state["lock"]:
                        if self._node_judgement_arm_valid_locked(diag_ticket):
                            if len(diag_state["cache"]) >= 256:
                                diag_state["cache"].pop(next(iter(diag_state["cache"])))
                            diag_state["cache"][cache_key] = arm_check
                # A re-arming refresh is in flight (rearm_on_stale_route): a
                # cached not_armed would outlive the re-arm a few ms later.
                if not refresh_outcome.get("hold_cache"):
                    judge.remember_gate(leaf, episode, now, reason, route_key)
                if reason is None and job is not None:
                    if judge.start(job):
                        self._node_judgement_arm_admission(trigger, judge, None,
                            check=arm_check, source=source, evaluated=evaluated, ticket=diag_ticket)
                        return True
                    reason = "judging"
                    self._runtime_post_dial_finish(job, "superseded")
        if reason is not None:
            judge.note_gated(trigger, reason, arm_check=arm_check if reason == "not_armed" else None)
        self._node_judgement_arm_admission(trigger, judge, reason,
            check=arm_check, source=source, evaluated=evaluated, ticket=diag_ticket)
        return False

    def _log_runtime_post_dial_would_judge(self, trigger: Any) -> None:
        judge = self._runtime_post_dial_judge()
        leaf = str(trigger.leaf)
        now = self._runtime_recovery_now()
        ladder_on = bool(self._node_judgement_policy().ladder_on)
        gate_outcome: dict[str, Any] = {}
        reason = judge.blocked_cheap(leaf, now)
        if reason is None:
            if ladder_on:
                _job, reason = self._runtime_post_dial_admission(
                    trigger,
                    judge,
                    now=now,
                    register=False,
                    outcome=gate_outcome,
                )
            else:
                _job, reason = self._runtime_post_dial_admission(
                    trigger,
                    judge,
                    now=now,
                    register=False,
                )
        record = {
            "ev": "would_judge",
            "t": round(time.time(), 3),
            "rule": str(getattr(trigger, "kind", "") or ""),
            "leaf": judge.tokenizer.leaf(leaf),
            "episode": int(getattr(trigger, "episode", 0) or 0),
            "gate": reason or "open",
            "mode": "shadow",
        }
        if ladder_on:
            # Spec §2.1/§4.4: the rung gate's count, key on only.
            record["ladder"] = 1
            record["rungs"] = int(gate_outcome.get("ladder_rungs", 0) or 0)
        self._log_runtime_post_dial_record("info", record)

    def _runtime_post_dial_admission(
        self,
        trigger: Any,
        judge: PostDialJudgeService,
        *,
        now: float,
        register: bool,
        outcome: dict[str, Any] | None = None,
    ) -> tuple[PostDialJudgeJob | None, str | None]:
        """The state-reading gates and, when ``register``, the ticket.

        Returns ``(job, None)`` for an admitted judgement, else
        ``(None, first blocking gate)``.  With ``register`` False nothing is
        written: no ticket, no queued refresh.  ``outcome`` (optional) gets
        ``hold_cache`` True while a ``rearm_on_stale_route`` refresh is in
        flight, so the caller does not cache this ``not_armed``.

        Every gate reads one published (snapshot, payload) pair, without a
        copy: armed is checked against the very snapshot the judgement binds
        to.  The selector intent revision and facility epoch are read before
        the armed gate and the ticket must carry the same values (both only
        grow), so a user selection or facility change declared at any point
        from the gates to the commit is seen by the rebind and ticket checks.
        A stale published route is refreshed only when it is the last gate
        still blocking.
        """

        if self._node_judgement_policy().ladder_on:
            return self._runtime_post_dial_ladder_admission(
                trigger,
                judge,
                now=now,
                register=register,
                outcome=outcome,
            )
        diag_ticket = self._node_judgement_arm_permit()
        leaf = str(trigger.leaf)
        intent_revision = int(getattr(self, "_runtime_selector_intent_revision", 0) or 0)
        facility_epoch = int(getattr(self, "_runtime_facility_epoch", 0) or 0)
        snapshot, payload = self._runtime_post_dial_route_refs()
        with self._node_judgement_arm_capture() as arm_trace:
            armed = bool(
                self._runtime_recovery_is_armed(snapshot, route_state=(snapshot, payload))
            )
        arm_check = str(arm_trace.get("arm_check") or ("armed" if armed else "override_unknown"))
        self._node_judgement_arm_trace("admission_arm_check", arm_check)
        self._node_judgement_arm_observe("admission", armed=armed, check=arm_check, captured=True,
                                         ticket=diag_ticket)
        d4_busy = self._runtime_post_dial_d4_busy(leaf)
        route_reason, binding, group = self._runtime_post_dial_route_gate(
            leaf,
            snapshot,
            payload,
        )
        status_failure = bool(
            group is not None
            and isinstance(payload, dict)
            and judge.latest_sample_is_status_failure(
                leaf,
                self._runtime_proxy_entries(payload).get(leaf),
                str(group.test_url or ""),
            )
        )
        reason = judge.blocked(
            leaf,
            now,
            armed=armed,
            d4_busy=d4_busy,
            status_failure=status_failure,
            **_post_dial_override_kwargs(judge, trigger),
        ) or route_reason
        if reason is None and getattr(self, "_tier3_provider_write_busy", False):
            # A verified provider write is rebuilding and re-testing members
            # (the flag is raised on that lane only): defer, as the ladder's
            # d4_txn_busy gate does.  Its other D4 checks stay ladder-only.
            reason = "d4_txn_busy_provider_write"
        if register and reason == "route_binding_mismatch" and snapshot is not None:
            source_was_ready = bool(getattr(self, "_source_control_final_exit_was_ready", False))
            refresh_epochs = self._post_dial_refresh_epochs()
            disposition = self._queue_post_dial_binding_refresh(
                leaf,
                snapshot,
                cause=_JUDGE_REFRESH_CAUSE_MISMATCH,
            )
            self._log_post_dial_judge_refresh(
                trigger,
                judge,
                cause=_JUDGE_REFRESH_CAUSE_MISMATCH,
                disposition=disposition,
                snapshot=snapshot,
                arm_check=arm_check,
                key_on=None,
                ticket=diag_ticket,
                source_was_ready=source_was_ready,
                epochs=refresh_epochs,
            )
        elif register and reason == "not_armed":
            self._runtime_post_dial_stale_arm_refresh(
                trigger,
                judge,
                now=now,
                snapshot=snapshot,
                payload=payload,
                route_reason=route_reason,
                d4_busy=d4_busy,
                status_failure=status_failure,
                intent_revision=intent_revision,
                arm_check=arm_check,
                outcome=outcome,
                ticket=diag_ticket,
            )
        if reason is not None or not register:
            return None, reason
        assert snapshot is not None and isinstance(payload, dict)
        assert binding is not None and group is not None
        tokens = tuple(str(token) for token in (getattr(trigger, "tokens", ()) or ()))
        kind = str(getattr(trigger, "kind", "") or "post_dial")
        failure = BoundRuntimeFailure(
            binding=binding,
            protocol="TCP",
            observed_outbound=binding.observed_outbound,
            destination_token=runtime_destination_token(
                "post-dial:" + (tokens[0] if tokens else kind)
            ),
            error_type=f"post_dial_{kind.lower()}",
            observed_at_monotonic=self._runtime_recovery_now(),
        )
        incident_id = "post-dial-" + os.urandom(8).hex()
        ticket = self._ensure_runtime_recovery_ticket(failure, snapshot, incident_id)
        if not isinstance(ticket, _RuntimeRecoveryTicket):
            return None, "ticket_unavailable"
        if (
            int(ticket.selector_intent_revision) != intent_revision
            or int(ticket.facility_epoch) != facility_epoch
        ):
            # Declared between the gates and the ticket: settle it unjudged.
            self._complete_runtime_recovery_hold(
                ticket,
                reason_code="post_dial_authority_changed",
            )
            return None, "authority_changed"
        context = _PostDialJudgeContext(
            incident_id=incident_id,
            quarantine_token=f"{incident_id}:judge",
            snapshot=snapshot,
            # The one copy, taken only for an admitted judgement.
            payload=copy.deepcopy(payload),
            binding=binding,
            failure=failure,
            ticket=ticket,
            # The CAS baseline is the ticket's (the gates') intent revision and
            # facility epoch, not a later re-read.
            mutation_binding=_dataclass_replace(
                self._runtime_mutation_binding_for_snapshot(snapshot),
                facility_epoch=int(ticket.facility_epoch),
                selector_intent_revision=int(ticket.selector_intent_revision),
            ),
            provider_name=str(
                getattr(self, "_tier3_core_provider_name", "TIER3B-RUNTIME")
                or "TIER3B-RUNTIME"
            ),
        )
        return (
            PostDialJudgeJob(
                leaf=leaf,
                kind=kind,
                tokens=tokens,
                episode=int(getattr(trigger, "episode", 0) or 0),
                test_url=str(group.test_url),
                expected_status=str(group.expected_status),
                ticket_deadline=float(ticket.deadline_monotonic),
                runner=self.__dict__.get("_runtime_post_dial_observer"),
                context=context,
                # Read once per judgement: the verdict and commit lines and
                # ``native_commit``'s branch all use this one value.
                durable=bool(self._node_judgement_policy().durable_conviction),
            ),
            None,
        )

    def _runtime_post_dial_route_gate(
        self,
        leaf: str,
        snapshot: CoreLoadedRouteSnapshot | None,
        payload: dict[str, Any] | None,
    ) -> tuple[
        str | None,
        RuntimeRouteBinding | None,
        CoreLoadedGroupState | None,
    ]:
        """Bind L to the published route: FINAL-EXIT → … → TIER3-AUTO → L.

        L must be a TIER3-AUTO member (``all`` minus Reject), the group must
        carry its contract, and the published FINAL-EXIT binding must end on
        L through TIER3-AUTO with no Gateway group.  A published route that
        names another leaf is stale (Mihomo moved since the last refresh):
        ``route_binding_mismatch``, for which the admission queues a bounded
        refresh (``_queue_post_dial_binding_refresh``); a later trigger
        evaluation binds to the refreshed route.  Read-only.
        """

        if snapshot is None or not isinstance(payload, dict):
            return "route_unavailable", None, None
        group = snapshot.group_state("TIER3-AUTO")
        if group is None or leaf not in node_judgement_contract_order(group.members):
            return "non_member", None, None
        if not str(group.test_url or "") or not str(group.expected_status or ""):
            return "contract_unavailable", None, None
        binding = self._runtime_route_binding_for_outbound(snapshot, payload, "FINAL-EXIT")
        if binding is None or not snapshot.owns(binding):
            return "route_unbound", None, group
        chain = tuple(binding.route_chain)
        if (
            binding.node.proxy_name != leaf
            or binding.node.pool_kind == "gateway"
            or len(chain) < 2
            or chain[-1] != leaf
            or chain[-2] != "TIER3-AUTO"
            or any(part in _POST_DIAL_GATEWAY_GROUPS for part in chain)
            or str(group.now or "") != leaf
        ):
            return "route_binding_mismatch", None, group
        return None, binding, group

    def _runtime_post_dial_route_refs(
        self,
    ) -> tuple[CoreLoadedRouteSnapshot | None, dict[str, Any] | None]:
        """The published route snapshot and its payload owner, not copied.

        Publication replaces both under the route lock and never mutates a
        published payload in place, so the pair taken under the lock stays
        coherent; the judge's gates only read it.
        """

        route_lock = getattr(self, "_runtime_route_snapshot_lock", None)
        with route_lock if route_lock is not None else nullcontext():
            snapshot = getattr(self, "_runtime_route_snapshot", None)
            payload = getattr(self, "_runtime_route_snapshot_payload", None)
        return snapshot, payload if isinstance(payload, dict) else None

    def _queue_post_dial_binding_refresh(
        self,
        leaf: str,
        snapshot: CoreLoadedRouteSnapshot,
        *,
        cause: str = _JUDGE_REFRESH_CAUSE_MISMATCH,
    ) -> str:
        """Queue one existing route-snapshot refresh for a stale binding.

        Bounded per (leaf, snapshot key): at most
        ``_POST_DIAL_BINDING_REFRESH_ATTEMPTS`` in all, at least
        ``_POST_DIAL_BINDING_REFRESH_RETRY_SECONDS`` apart.  A refresh that
        failed, or did not start because another was running, leaves the key
        unchanged and is retried by a later trigger; one that published a new
        selection changes the key.  Both causes (a ``route_binding_mismatch``
        and a ``rearm_on_stale_route`` stale arm) share the key's bound.

        Returns the disposition: ``queued`` (a refresh worker started),
        ``single_flight`` (one was already running; the attempt still
        counts), ``bounded_attempts`` or ``bounded_retry``.
        """

        state = self._node_judgement_state()
        key = (str(leaf), tuple(snapshot.snapshot_key))
        now = self._runtime_recovery_now()
        bounded: str | None = None
        with state.lock:
            attempts, queued_at = state.binding_refresh_keys.get(key, (0, 0.0))
            if attempts >= _POST_DIAL_BINDING_REFRESH_ATTEMPTS:
                bounded = "bounded_attempts"
            elif attempts and now - queued_at < _POST_DIAL_BINDING_REFRESH_RETRY_SECONDS:
                bounded = "bounded_retry"
            else:
                if (
                    key not in state.binding_refresh_keys
                    and len(state.binding_refresh_keys) >= _POST_DIAL_BINDING_REFRESH_KEYS_MAX
                ):
                    state.binding_refresh_keys.clear()
                state.binding_refresh_keys[key] = (attempts + 1, now)
                state.refresh_origin_pending = str(cause)
            if bounded is not None:
                state.refresh_counts["judge_refresh_" + bounded] += 1
        if bounded is not None:
            return bounded
        starts_before = int(getattr(self, "_runtime_route_snapshot_refresh_starts", 0) or 0)
        try:
            self._queue_runtime_route_snapshot_refresh()
        finally:
            with state.lock:
                # Taken by the refresh it started; a dropped call leaves it.
                state.refresh_origin_pending = None
        started = int(getattr(self, "_runtime_route_snapshot_refresh_starts", 0) or 0) != starts_before
        disposition = "queued" if started else "single_flight"
        if not started:
            counter = "judge_refresh_single_flight"
        elif cause == _JUDGE_REFRESH_CAUSE_NOT_ARMED:
            counter = "judge_refresh_queued_not_armed"
        else:
            counter = "judge_refresh_queued_mismatch"
        with state.lock:
            state.refresh_counts[counter] += 1
        return disposition

    def _take_post_dial_refresh_origin(self) -> str | None:
        """Take (and clear) the cause of a post-dial refresh about to start."""

        try:
            state = self.__dict__.get("_node_judgement_runtime_state")
            if not isinstance(state, _NodeJudgementRuntimeState):
                return None
            with state.lock:
                origin = state.refresh_origin_pending
                state.refresh_origin_pending = None
            return origin
        except Exception:
            return None

    def _count_post_dial_refresh(self, counter: str) -> None:
        try:
            state = self.__dict__.get("_node_judgement_runtime_state")
            if isinstance(state, _NodeJudgementRuntimeState):
                with state.lock:
                    state.refresh_counts[counter] = int(state.refresh_counts.get(counter, 0)) + 1
        except Exception:
            return

    def _runtime_post_dial_stale_arm_refresh(
        self,
        trigger: Any,
        judge: PostDialJudgeService,
        *,
        now: float,
        snapshot: CoreLoadedRouteSnapshot | None,
        payload: dict[str, Any] | None,
        route_reason: str | None,
        d4_busy: bool,
        status_failure: bool,
        intent_revision: int,
        arm_check: str,
        outcome: dict[str, Any] | None,
        ticket: Any,
    ) -> None:
        """``rearm_on_stale_route`` for an act admission gated ``not_armed``.

        Eligible only when a refresh can fix the cause: the route gate passes
        or names another leaf, every other gate passes, and the arm is stale
        by route epoch alone (``_node_judgement_stale_arm_refresh_refusal``).
        Key off: ``would_queue``, nothing queued.  Key on: the bounded
        ``_queue_post_dial_binding_refresh``, whose worker re-arms through the
        unchanged ``_try_arm_runtime_recovery``.  Never raises.
        """

        leaf = str(trigger.leaf)
        source_was_ready = False
        epochs: tuple[int, int] | None = None
        try:
            epochs = self._post_dial_refresh_epochs()
            refresh_policy = self._node_judgement_policy()
            key_on = bool(refresh_policy.rearm_on_stale_route)
            ladder_on = bool(refresh_policy.ladder_on)
            if route_reason not in (None, _JUDGE_REFRESH_CAUSE_MISMATCH):
                disposition = "skipped_route:" + str(route_reason)
            elif snapshot is None or not isinstance(payload, dict):
                disposition = "skipped_route:route_unavailable"
            else:
                residual = judge.blocked(
                    leaf,
                    now,
                    armed=True,
                    d4_busy=d4_busy,
                    status_failure=status_failure,
                    **_post_dial_override_kwargs(judge, trigger),
                )
                refusal = (
                    None
                    if residual is not None
                    else self._node_judgement_stale_arm_refresh_refusal(intent_revision)
                )
                if residual is not None:
                    disposition = "skipped_residual:" + str(residual)
                elif refusal is not None:
                    disposition = "skipped_arm:" + refusal
                elif not (
                    key_on
                    # Spec §2.4 scoped rearm: ``queue_on = key_on or
                    # ladder_scope``; ``key_on`` itself stays the record field.
                    or (ladder_on and self._runtime_post_dial_ladder_rearm_scope(payload))
                ):
                    disposition = "would_queue"
                else:
                    source_was_ready = bool(
                        getattr(self, "_source_control_final_exit_was_ready", False)
                    )
                    disposition = self._queue_post_dial_binding_refresh(
                        leaf,
                        snapshot,
                        cause=_JUDGE_REFRESH_CAUSE_NOT_ARMED,
                    )
                    if outcome is not None and disposition in {
                        "queued",
                        "single_flight",
                        "bounded_retry",
                    }:
                        outcome["hold_cache"] = True
            counter = {
                "would_queue": "judge_refresh_would_queue",
                "skipped_arm:incident": "judge_refresh_skipped_incident",
                "skipped_arm:activation_hold": "judge_refresh_skipped_activation_hold",
            }.get(disposition)
            if source_was_ready and disposition == "queued":
                self._count_post_dial_refresh("judge_refresh_source_was_ready")
            if counter is not None:
                self._count_post_dial_refresh(counter)
        except Exception:
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Could not evaluate the post-dial stale-arm route refresh",
                exc_info=True,
            )
            return
        self._log_post_dial_judge_refresh(
            trigger,
            judge,
            cause=_JUDGE_REFRESH_CAUSE_NOT_ARMED,
            disposition=disposition,
            snapshot=snapshot,
            arm_check=arm_check,
            key_on=key_on,
            ticket=ticket,
            source_was_ready=source_was_ready,
            epochs=epochs,
        )

    def _post_dial_refresh_epochs(self) -> tuple[int, int]:
        """(current route epoch, installed arm's route epoch or -1), unlocked.

        Diagnostic only; never raises into the admission ((-1, -1) on error).
        """

        try:
            arm = getattr(self, "_runtime_recovery_arm", None)
            return (
                int(getattr(self, "_runtime_route_epoch", 0) or 0),
                int(getattr(arm, "route_epoch", -1)),
            )
        except Exception:
            return (-1, -1)

    def _log_post_dial_judge_refresh(
        self,
        trigger: Any,
        judge: PostDialJudgeService,
        *,
        cause: str,
        disposition: str,
        snapshot: CoreLoadedRouteSnapshot | None,
        arm_check: str,
        key_on: bool | None,
        ticket: Any,
        source_was_ready: bool = False,
        epochs: tuple[int, int] | None = None,
    ) -> None:
        """The async F01 ``ev=judge_refresh`` record; never raises.

        Only with a live F01 diagnostics ticket.  Queue-call dispositions are
        always emitted; ``would_queue`` and ``skipped_*`` once per (leaf,
        rule, episode, disposition).  ``epochs``: the (route, arm) epochs read
        before the queue call (a fast refresh may re-arm before this line).
        """

        try:
            if ticket is None:
                return
            leaf = str(trigger.leaf)
            leaf_token = judge.tokenizer.leaf(leaf)
            rule = str(getattr(trigger, "kind", "") or "")
            episode = int(getattr(trigger, "episode", 0) or 0)
            state = self._node_judgement_state()
            snapshot_key = tuple(snapshot.snapshot_key) if snapshot is not None else None
            with state.lock:
                if disposition == "would_queue" or disposition.startswith("skipped_"):
                    dedupe = (leaf_token, rule, episode, disposition)
                    if dedupe in state.refresh_dedupe:
                        return
                    if len(state.refresh_dedupe) >= 256:
                        state.refresh_dedupe.pop(next(iter(state.refresh_dedupe)))
                    state.refresh_dedupe[dedupe] = True
                attempt = (
                    0
                    if snapshot_key is None
                    else int(state.binding_refresh_keys.get((leaf, snapshot_key), (0, 0.0))[0])
                )
            record_policy = self._node_judgement_policy()
            if key_on is None:
                key_on = bool(record_policy.rearm_on_stale_route)
            local = self.__dict__.get("_node_judgement_arm_local")
            scope = getattr(local, "scope", None)
            diag_state = ticket[0]
            revision = 0
            if scope is not None:
                with diag_state["lock"]:
                    if self._node_judgement_arm_valid_locked(ticket, scope):
                        revision = scope["policy_revision"]
            route_epoch, arm_route_epoch = (
                epochs if epochs is not None else self._post_dial_refresh_epochs()
            )
            refresh_record = {"ev": "judge_refresh", "cause": cause,
                "leaf": leaf_token, "rule": rule, "episode": episode,
                "arm_check": str(arm_check),
                "route_epoch": int(route_epoch),
                "arm_route_epoch": int(arm_route_epoch),
                "snapshot_epoch": -1 if snapshot_key is None else int(snapshot_key[4]),
                "key_attempt": attempt, "disposition": disposition,
                "key_on": 1 if key_on else 0,
                "source_was_ready": 1 if source_was_ready else 0,
                "observer": "unknown", "scope": "unknown", "scope_seq": 0,
                "policy_revision": revision}
            if record_policy.ladder_on:
                # Spec §2.4: which key queues the re-arm (tier ladder only).
                refresh_record["rearm_source"] = "key" if key_on else "ladder"
            self._node_judgement_arm_submit(refresh_record, scope, ticket=ticket)
        except Exception:
            return

    def _runtime_post_dial_d4_busy(self, leaf: str) -> bool:
        """§3.3 gate 4: a D4 probe or recovery transaction is running on L.

        D4 keys its probe and recovery bindings by circuit key (snapshot key,
        node key, outbound, chain; ``provisional``/``failback`` prefixes for
        the transactions), so L's proxy name among a key's parts means D4
        owns L now.  A match on an unrelated part only defers the judge.
        """

        lock = getattr(self, "_runtime_failure_monitor_lock", None)
        with lock if lock is not None else nullcontext():
            keys = tuple(getattr(self, "_runtime_failure_probe_bindings", ()) or ()) + tuple(
                getattr(self, "_runtime_failure_recovery_bindings", ()) or ()
            )
        name = str(leaf)
        return any(
            isinstance(part, str) and part == name
            for key in keys
            if isinstance(key, tuple)
            for part in key
        )

    def _runtime_post_dial_close_enabled(self) -> bool:
        policy = self._node_judgement_policy()
        return bool(policy.acts and policy.close_stuck_connections)

    def _runtime_post_dial_contract_probe(
        self,
        job: PostDialJudgeJob,
        action: Any,
    ) -> PostDialProbeOutcome:
        """One judge contract probe (design v3 §5.1, §5.2), run to completion.

        ``GET /proxies/{leaf}/delay`` on the group's exact contract (its
        testUrl and expected status) with Mihomo's native timeout (5000 ms),
        through the 2-slot broker at RUNTIME_MANUAL.  The 5.65 s window
        starts at admission, so a queued probe is never issued short (one
        admitted too late is skipped: indeterminate), and the slot is held
        until Mihomo answers.  Classified by type: 200 with a passing readback
        is ``pass``; the readback's status mismatch ``http_answer``; 503
        ``transport_fail``; 504 ``timeout``; anything else ``indeterminate``,
        which never penalises.
        """

        context = job.context
        ticket = context.ticket
        timeout_ms = int(action.timeout_ms)
        window = float(action.request_timeout_s) + _POST_DIAL_PROBE_CLEANUP_SECONDS
        # Tier ladder probes carry their rung's contract and the 1.9 s
        # admission (spec §4.7); legacy actions carry None for all three.
        probe_url = getattr(action, "url", None) or job.test_url
        probe_expected = getattr(action, "expected", None) or job.expected_status
        admission_s = getattr(action, "admission_s", None) or _POST_DIAL_PROBE_ADMISSION_SECONDS
        ladder = getattr(job, "ladder", None)
        if ladder is not None:
            refused = self._runtime_post_dial_ladder_probe_refusal(job, action)
            if refused is not None:
                return refused
        elif getattr(self, "_tier3_provider_write_busy", False):
            # Admitted just before a verified provider write raised its flag
            # (the write then saw no judgement yet): stand down, as a ladder
            # unit does on d4_txn_busy.  Indeterminate never penalises.
            self._log_runtime_post_dial_record(
                "info",
                {
                    "ev": "probe_refused",
                    "t": round(time.time(), 3),
                    "name": str(getattr(action, "name", "") or ""),
                    "reason": "d4_txn_busy_provider_write",
                },
            )
            return PostDialProbeOutcome(NodeJudgementProbeClass.INDETERMINATE)
        issued = time.monotonic()
        admitted: list[float] = []

        def run(execution: ProbeExecutionContext | None) -> dict[str, Any]:
            admitted.append(time.monotonic())
            if (
                execution is not None
                and execution.execution_deadline_monotonic is not None
                and float(execution.execution_deadline_monotonic) - time.monotonic()
                < window
            ):
                raise _RuntimeProbeBudgetUnavailable(
                    "post-dial judge probe was admitted too late for its native timeout",
                    probe_indeterminate_reason="judge_probe_skipped_queue",
                )
            return self._probe_proxy_delay_with_urls_leased(
                str(action.leaf),
                [probe_url],
                timeout_ms=timeout_ms,
                request_timeout_seconds=window,
                expected_status=probe_expected,
                execution_context=execution,
                recovery_ticket=ticket,
                recovery_deadline_monotonic=float(ticket.deadline_monotonic),
            )

        try:
            result = self._run_brokered_runtime_probe(
                run,
                priority=ProbePriority.RUNTIME_MANUAL,
                queue_timeout_seconds=admission_s,
                socket_start_timeout_seconds=0.5,
                execution_deadline_monotonic=(
                    issued
                    + admission_s
                    + window
                    + _NATIVE_GROUP_ROUND_DISPATCH_SECONDS
                ),
            )
            probe = (
                NodeJudgementProbeClass.PASS
                if isinstance(result, dict)
                else NodeJudgementProbeClass.INDETERMINATE
            )
        except MihomoDelayStatusMismatch:
            probe = NodeJudgementProbeClass.HTTP_ANSWER
        except MihomoDelayTransportFailed:
            probe = NodeJudgementProbeClass.TRANSPORT_FAIL
        except MihomoDelayTimeout:
            probe = NodeJudgementProbeClass.TIMEOUT
        except Exception:
            probe = NodeJudgementProbeClass.INDETERMINATE
        ended = time.monotonic()
        started = admitted[0] if admitted else issued
        if ladder is not None and getattr(action, "group", None) == tier_ladder.PROXY_FALLBACK:
            # overshoot_repair step 3: a judge PF-contract probe resolved now.
            self._runtime_overshoot_last_judge_pf_probe = ended
        return PostDialProbeOutcome(
            probe,
            elapsed_ms=round((ended - started) * 1000.0, 1),
            queue_wait_ms=round((started - issued) * 1000.0, 1) if admitted else None,
        )

    def _runtime_post_dial_route_read(
        self,
        job: PostDialJudgeJob,
    ) -> PostDialRouteRead | None:
        """S4 ``GET /proxies/TIER3-AUTO``, S3 ``GET /providers/proxies/
        TIER3B-RUNTIME`` (never the all-provider read, which clears a dead
        ``fixed``, Conf-1) and S5 for prefix members, 0.35 s each."""

        ladder = getattr(job, "ladder", None)
        if ladder is not None:
            return self._runtime_post_dial_rung_read(job, self._runtime_ladder_current_rung(ladder))
        try:
            client = self._require_api_client()
        except Exception:
            return None
        timeout = _POST_DIAL_CONTROLLER_TIMEOUT_SECONDS
        try:
            group = client.proxy("TIER3-AUTO", timeout=timeout)
        except Exception:
            return None
        try:
            provider = client.provider_proxies_one(
                job.context.provider_name,
                timeout=timeout,
            )
        except Exception:
            provider = None
        if provider is not None and self._tier3_verified_provider_writes_enabled():
            # Successors are where traffic goes next: a member a rebuild left
            # untested ranks by its carried verdict, never as alive-by-default.
            provider = tier3_overlay_provider_payload(
                provider, str(job.test_url or ""), self._tier3_health_ledger.entry
            )
        return post_dial_route_read_from(
            group,
            provider,
            test_url=job.test_url,
            read_member=lambda name: client.proxy(name, timeout=timeout),
            read_at=self._runtime_recovery_now(),
            priority=(job.leaf,),
        )

    def _runtime_post_dial_leaf_read(
        self,
        job: PostDialJudgeJob,
        leaf: str,
    ) -> dict[str, Any] | None:
        """The deadline readback (§5.3): L's S3 entry, or S5 for a prefix member."""

        client = self._require_api_client()
        timeout = _POST_DIAL_CONTROLLER_TIMEOUT_SECONDS
        ladder = getattr(job, "ladder", None)
        if ladder is not None:
            rung = self._runtime_ladder_current_rung(ladder)
            if not (
                rung is not None
                and rung.group == "TIER3-AUTO"
                and rung.kind is tier_ladder.RungKind.LEAF
            ):
                # Inline leaf or group accused: its own entry (no provider).
                entry = client.proxy(str(leaf), timeout=timeout)
                return dict(entry) if isinstance(entry, dict) else None
        entry: Any = None
        try:
            entry = post_dial_provider_member(
                client.provider_proxies_one(job.context.provider_name, timeout=timeout),
                str(leaf),
            )
        except Exception:
            entry = None
        if entry is None:
            entry = client.proxy(str(leaf), timeout=timeout)
        return dict(entry) if isinstance(entry, dict) else None

    def _runtime_post_dial_native_commit(
        self,
        job: PostDialJudgeJob,
        done: Any,
    ) -> tuple[bool, str]:
        """Design v3 §18.7 ``native_commit`` (act mode, CONVICT_CONTRACT).

        Mihomo already moved TIER3-AUTO from L to the proven successor S on
        its own failed sample.  Refresh the published route snapshot and
        accept it only when that is the only change: the same process, Core
        generation, config digest, network context, selector intent and
        facility epoch, the route above TIER3-AUTO unchanged, L Core-dead and
        the group now on S (the rebind 校验 uses).  "Selection" is the one
        the route epoch tracks (``_runtime_final_exit_selection_signature``:
        the FINAL-EXIT path and its Gateway underlay), so groups off that
        path are not compared, as for every route epoch; TIER3-AUTO's own
        ``fixed`` may only stay or clear to empty (a disclosed looseness:
        Mihomo can drop a dead pick on its own).  Then rebind the failure
        and the judge's ticket to it (``force_rebind``, same deadline).  With
        ``durable_conviction`` (``job.durable``) run the existing
        ``_apply_confirmed_runtime_health``: the effective-SUSPICIOUS overlay
        plus the targeted recheck, which feed the existing strike and
        eviction rules.  Without it (move-only, the default) only that
        call's guards run (``_runtime_post_dial_rebind_guard``) and nothing
        durable is recorded about L.  No selector write, pin, reload,
        provider write or connection close, and no readiness publication.
        Settles the ticket (RECOVERED with ``put=False``, reason
        ``post_dial_native_commit`` / move-only ``post_dial_native_rebind``,
        else a controller hold) and re-arms recovery on the refreshed route,
        as every queued refresh does, in both modes.  Returns (accepted,
        reason).
        """

        if getattr(job, "ladder", None) is not None:
            return self._runtime_post_dial_rung_native_commit(job, done)
        context = job.context
        leaf = job.leaf
        deadline = float(context.ticket.deadline_monotonic)
        accepted = False
        reason = "commit_rejected"
        refreshed = False
        try:
            remaining = deadline - self._runtime_recovery_now()
            if not self._node_judgement_policy().acts:
                # A config reload left act mode while this judgement ran.
                reason = "act_mode_off"
            elif remaining <= 0.05:
                reason = "commit_late"
            else:
                refreshed = True
                end_state = self._current_runtime_failure_binding_state(
                    timeout_seconds=max(0.05, min(0.75, remaining - 0.05)),
                    refresh=True,
                )
                rebound = None
                if end_state is None:
                    reason = "route_refresh_unavailable"
                else:
                    plan = _ManualRouteContractPlan(
                        group="TIER3-AUTO",
                        leaf=leaf,
                        probe_url=job.test_url,
                        expected_status=job.expected_status,
                        neutral_url="",
                        neutral_contract_id="",
                    )
                    rebound = self._manual_route_contract_native_rebind(
                        plan,
                        (context.binding, context.snapshot, context.payload),
                        end_state,
                        context.mutation_binding,
                    )
                    if rebound is None:
                        reason = "rebind_rejected"
                if rebound is not None:
                    (rebound_binding, snapshot1, payload1), _mutation1, successor = rebound
                    if successor.proxy_name != str(getattr(done, "successor", "") or ""):
                        # A native pick that differs from the proven successor
                        # is logged, not corrected (§16 call 4: no app PUT).
                        reason = "native_pick_mismatch"
                    else:
                        ticket0 = context.ticket
                        failure1 = _dataclass_replace(context.failure, binding=rebound_binding)
                        ticket1 = self._register_runtime_recovery_ticket(
                            failure1,
                            snapshot1,
                            context.incident_id,
                            force_rebind=True,
                            deadline_monotonic=deadline,
                        )
                        context.ticket = ticket1
                        if (
                            int(ticket1.selector_intent_revision),
                            int(ticket1.facility_epoch),
                        ) != (
                            int(ticket0.selector_intent_revision),
                            int(ticket0.facility_epoch),
                        ):
                            # Declared after the rebind check but before the
                            # re-registered ticket copied them: the admission
                            # baseline no longer holds.
                            reason = "authority_changed"
                        elif not bool(getattr(job, "durable", False)):
                            # Move-only (``durable_conviction`` false): the
                            # route rebind alone.  No health observation,
                            # recheck, flap entry, revocation or incident
                            # binding; the health commit's guards are kept.
                            guard = self._runtime_post_dial_rebind_guard(
                                failure1,
                                snapshot1,
                                expected_facility_epoch=int(ticket0.facility_epoch),
                                expected_ticket=ticket1,
                                deadline_monotonic=deadline,
                            )
                            if guard is not None:
                                reason = f"rebind_{guard}"
                            else:
                                self._complete_runtime_recovery_outcome(
                                    context.incident_id,
                                    RuntimeRecoveryStatus.RECOVERED,
                                    reason_code="post_dial_native_rebind",
                                    to_ref=successor,
                                    route_epoch=int(snapshot1.route_epoch),
                                    expected_ticket=ticket1,
                                    deadline_monotonic=deadline,
                                    facts={"put": False, "readback": True, "final_204": False},
                                )
                                accepted = True
                                reason = "post_dial_native_rebind"
                        else:
                            health = self._apply_confirmed_runtime_health(
                                failure1,
                                snapshot1,
                                payload1,
                                incident_id=context.incident_id,
                                quarantine_token=context.quarantine_token,
                                expected_facility_epoch=int(ticket0.facility_epoch),
                                expected_ticket=ticket1,
                                deadline_monotonic=deadline,
                            )
                            if not bool(health.get("accepted")):
                                action = re.sub(
                                    r"[^a-z0-9_]",
                                    "_",
                                    str(health.get("action") or "rejected").lower(),
                                )[:32]
                                reason = f"health_{action}"
                            else:
                                self._complete_runtime_recovery_outcome(
                                    context.incident_id,
                                    RuntimeRecoveryStatus.RECOVERED,
                                    reason_code="post_dial_native_commit",
                                    to_ref=successor,
                                    route_epoch=int(snapshot1.route_epoch),
                                    expected_ticket=ticket1,
                                    deadline_monotonic=deadline,
                                    facts={"put": False, "readback": True, "final_204": False},
                                )
                                accepted = True
                                reason = "committed"
        except Exception as exc:
            reason = f"commit_error_{type(exc).__name__}"
        finally:
            if not accepted:
                self._runtime_post_dial_finish(job, reason)
            if refreshed:
                try:
                    self._try_arm_runtime_recovery()
                except Exception:
                    pass
        return accepted, reason

    def _runtime_post_dial_rebind_guard(
        self,
        failure: BoundRuntimeFailure,
        expected_snapshot: CoreLoadedRouteSnapshot,
        *,
        expected_facility_epoch: int,
        expected_ticket: _RuntimeRecoveryTicket,
        deadline_monotonic: float,
    ) -> str | None:
        """Move-only ``native_commit``: the guards of
        ``_apply_confirmed_runtime_health`` (direct binding), without its
        effects.  None when the rebound route may settle RECOVERED, else the
        rejection (``stale``, ``terminal`` or ``facility_hold``, the actions
        that call names).  Read-only.
        """

        with self._runtime_route_snapshot_lock:
            current_snapshot = self._runtime_route_snapshot
            if not (
                current_snapshot is not None
                and current_snapshot.snapshot_key == expected_snapshot.snapshot_key
                and current_snapshot.owns(failure.binding)
                and self._runtime_egress_coordinator.snapshot_ownership_matches(
                    failure.binding,
                    expected_snapshot=expected_snapshot,
                )
            ):
                return "stale"
        core_transition_lock = getattr(self, "_core_transition_lock", nullcontext())
        with core_transition_lock:
            with self._runtime_failure_monitor_lock:
                if (
                    not self._runtime_recovery_ticket_matches_locked(
                        expected_ticket,
                        require_open=True,
                        deadline_monotonic=deadline_monotonic,
                    )
                    or int(getattr(self, "_runtime_selector_intent_revision", 0) or 0)
                    != int(expected_ticket.selector_intent_revision)
                    or not self._runtime_worker_token_is_current(expected_ticket.worker_token)
                ):
                    return "terminal"
                if int(getattr(self, "_runtime_facility_epoch", 0) or 0) != int(
                    expected_facility_epoch
                ) or (
                    not self._runtime_uses_early_single_coordinator()
                    and bool(self._runtime_facility_hold_reason())
                ):
                    return "facility_hold"
                loaded_snapshot = getattr(self, "_runtime_route_snapshot", None)
                coordinator_snapshot = self._runtime_egress_coordinator.current_route_snapshot()
                if not (
                    isinstance(loaded_snapshot, CoreLoadedRouteSnapshot)
                    and tuple(loaded_snapshot.snapshot_key)
                    == tuple(expected_snapshot.snapshot_key)
                    and loaded_snapshot.owns(failure.binding)
                    and coordinator_snapshot is not None
                    and tuple(coordinator_snapshot.snapshot_key)
                    == tuple(expected_snapshot.snapshot_key)
                ):
                    return "stale"
        return None

    def _runtime_post_dial_finish(self, job: PostDialJudgeJob, reason: str) -> None:
        """Settle the judge's ticket without a commit (a controller hold).

        Idempotent: an outcome already recorded for this ticket is kept.
        """

        context = getattr(job, "context", None)
        if not isinstance(context, _PostDialJudgeContext):
            return
        code = re.sub(r"[^a-z0-9_]", "_", str(reason or "done").lower())[:48]
        try:
            self._complete_runtime_recovery_outcome(
                context.incident_id,
                RuntimeRecoveryStatus.CONTROLLER_HOLD,
                reason_code=f"post_dial_{code}",
                expected_ticket=context.ticket,
            )
        except Exception:
            pass

    def _runtime_post_dial_route_moved(self, job: PostDialJudgeJob) -> None:
        """Mihomo demoted L (read back) and the judgement is over, act mode.

        Unless something already republished the route the judgement bound
        to (``native_commit``'s own refresh), queue one existing route-snapshot
        refresh, so the next trigger on Mihomo's successor binds at once
        instead of spending a ``route_binding_mismatch`` round.  Read-only
        towards Mihomo (one ``GET /proxies``); never in shadow mode.
        """

        context = getattr(job, "context", None)
        if not isinstance(context, _PostDialJudgeContext):
            return
        if not self._node_judgement_policy().acts:
            return
        snapshot, _payload = self._runtime_post_dial_route_refs()
        if snapshot is not context.snapshot:
            return
        self._queue_runtime_route_snapshot_refresh()

    def _runtime_post_dial_close(
        self,
        job: PostDialJudgeJob,
        leaf: str,
        connection_ids: tuple[str, ...],
    ) -> tuple[str, ...]:
        """§6: exact ids through the existing exact-id close (only these ids,
        only on connections whose chain holds L), run to completion on the
        judge's own ``runtime-post-dial-close`` thread.

        Returns the ids whose DELETE succeeded, so the demotion watch retries
        the rest on its next step (a failed ``GET /connections``, the 2 s
        deadline or a failed DELETE closes nothing silently).
        """

        binding = getattr(job.context, "binding", None)
        if not isinstance(binding, RuntimeRouteBinding) or binding.node.proxy_name != str(leaf):
            return ()
        ordered = [str(item).strip() for item in connection_ids if str(item).strip()]
        ids = set(ordered)
        if not ids:
            return ()
        closed: set[str] = set()
        self._close_runtime_connections_for_binding(
            binding,
            terminal_connection_ids=ids,
            deadline_monotonic=time.monotonic() + 2.0,
            expected_worker_token=self._runtime_worker_token(),
            closed_connection_ids=closed,
        )
        return tuple(item for item in dict.fromkeys(ordered) if item in closed)

    # -- Tier ladder judge (spec_tier_ladder_v1 §4, §5.2): runtime side ----
    # Reached only while ``tier_ladder_judge`` is on: a ``ladder_on`` gate, or
    # a job that carries ``job.ladder``.  Key off, none of these runs.
    # ``job.ladder`` (``runtime_post_dial_judge.PostDialLadder``) is read
    # through the small accessors below: ``rungs``, ``current``, ``index``,
    # ``authority``, ``deadline``, ``ladder_id``, ``chain0``, ``lock``, the
    # per-rung maps ``accused_failed_known``, ``drop_consumed``,
    # ``baselines`` and ``passed_at(k)``; this side writes
    # ``set_rung_state``, ``deeper_moved``, ``drop_consumed`` and
    # ``note_commit``.

    @staticmethod
    def _runtime_ladder_current_rung(ladder: Any) -> Any:
        """The ladder's current ``Rung``; None when it cannot be named."""

        rungs = tuple(getattr(ladder, "rungs", ()) or ())
        current = getattr(ladder, "current", None)
        if callable(current):
            current = current()
        if isinstance(current, tier_ladder.Rung):
            return current
        if not isinstance(current, int) or isinstance(current, bool):
            current = getattr(ladder, "index", 0)
        try:
            index = int(current)
        except (TypeError, ValueError):
            return None
        return rungs[index] if 0 <= index < len(rungs) else None

    @staticmethod
    def _runtime_ladder_flag(ladder: Any, name: str, index: int) -> bool:
        value = getattr(ladder, name, None)
        if isinstance(value, dict):
            return bool(value.get(index))
        if isinstance(value, (set, frozenset, list, tuple)):
            return index in value
        return bool(value)

    @staticmethod
    def _runtime_ladder_item(ladder: Any, name: str, index: int, default: Any = None) -> Any:
        value = getattr(ladder, name, None)
        return value.get(index, default) if isinstance(value, dict) else default

    @staticmethod
    def _runtime_ladder_store(ladder: Any, name: str, index: int, value: Any) -> None:
        """``ladder.<name>[index] = value`` (under ``ladder.lock`` if any)."""

        lock = getattr(ladder, "lock", None)
        try:
            with lock if lock is not None else nullcontext():
                target = getattr(ladder, name, None)
                if isinstance(target, set):
                    if value:
                        target.add(index)
                    else:
                        target.discard(index)
                    return
                if not isinstance(target, dict):
                    target = {}
                    setattr(ladder, name, target)
                target[index] = value
        except Exception:
            return

    @staticmethod
    def _runtime_ladder_set(ladder: Any, name: str, value: Any) -> None:
        try:
            setattr(ladder, name, value)
        except Exception:
            return

    @staticmethod
    def _runtime_post_dial_new_ladder(
        rungs: Any,
        authority: Any,
        deadline: float,
        ladder_id: str,
        chain0: tuple[str, ...],
        *,
        lease: str = "none",
        group_names: Any = (),
    ) -> Any:
        import runtime_post_dial_judge as post_dial_judge_module

        factory = getattr(post_dial_judge_module, "PostDialLadder", None)
        if factory is None:
            return None
        # ``admitted_at`` is stamped by ``PostDialJudgeService.start``.
        return factory(
            rungs=tuple(rungs),
            authority=authority,
            deadline=float(deadline),
            ladder_id=str(ladder_id),
            chain0=tuple(chain0),
            lease=str(lease or "none"),
            group_names=frozenset(group_names),
        )

    def _runtime_group_timeouts_store(self) -> tuple[Any, dict[str, Any]]:
        lock = self.__dict__.get("_runtime_group_timeouts_lock")
        if lock is None:
            lock = self.__dict__.setdefault("_runtime_group_timeouts_lock", threading.Lock())
        cache = self.__dict__.get("_runtime_group_timeouts_cache")
        if not isinstance(cache, dict):
            cache = self.__dict__.setdefault("_runtime_group_timeouts_cache", {})
        return lock, cache

    def _runtime_loaded_group_timeouts(self, snapshot: Any) -> dict[str, int] | None:
        """Spec §4.1: the Core-loaded groups' ``timeout`` (ms), lazily.

        Only for a snapshot of the loaded export contract (combined or
        route-authority digest), from the loaded runtime config file whose
        sha256 equals the contract's main digest (the provider-update check).
        Cached per main digest (2 entries).  None on any mismatch or error.
        """

        try:
            if snapshot is None:
                return None
            route_lock = getattr(self, "_runtime_route_snapshot_lock", None)
            with route_lock if route_lock is not None else nullcontext():
                contract = getattr(self, "_runtime_loaded_export_contract", None)
                loaded = dict(contract) if isinstance(contract, dict) else None
            if loaded is None:
                return None
            digest = str(getattr(snapshot, "semantic_digest", "") or "")
            allowed = {
                str(loaded.get("semantic_digest") or ""),
                str(loaded.get("route_authority_semantic_digest") or ""),
            } - {""}
            if not digest or digest not in allowed:
                return None
            main = str(loaded.get("main_semantic_digest") or "")
            if not main:
                return None
            lock, cache = self._runtime_group_timeouts_store()
            with lock:
                cached = cache.get(main)
            if isinstance(cached, dict):
                return cached
            started = time.perf_counter()
            path_text = str(loaded.get("runtime_config_path") or "").strip()
            path = Path(path_text) if path_text else self._runtime_config_path_for_client()
            if not path.is_absolute():
                path = self._resolve_path(path)
            text = path.read_text(encoding="utf-8")
            observed = hashlib.sha256(text.replace("\n", os.linesep).encode("utf-8")).hexdigest()
            if observed != main:
                return None
            document = yaml.safe_load(text)
            if not isinstance(document, dict) or not isinstance(document.get("proxy-groups"), list):
                return None
            timeouts = {
                group["name"]: group["timeout"]
                for group in document["proxy-groups"]
                if isinstance(group, dict)
                and isinstance(group.get("name"), str)
                and type(group.get("timeout")) is int
            }
            with lock:
                for key in [key for key in cache if key != main][: max(0, len(cache) - 1)]:
                    cache.pop(key, None)
                cache[main] = timeouts
            self._runtime_group_timeouts_parse_ms = round((time.perf_counter() - started) * 1000.0, 3)
            return timeouts
        except Exception:
            return None

    def _runtime_post_dial_route_context_for(self, snapshot: Any) -> PostDialRouteContext | None:
        """The observer's judged-leaf set (spec §4.2).

        Key off: the legacy TIER3-AUTO members.  ``tier_ladder_judge`` on:
        every leaf reachable from PROXY-FALLBACK in the loaded group graph.
        """

        policy = self._node_judgement_policy()
        if not policy.ladder_on:
            return self._runtime_post_dial_route_context(snapshot)
        if policy.overshoot_on:
            # On the observer thread, no app lock held (never in publish).
            self._runtime_overshoot_ensure_worker()
        graph = getattr(snapshot, "group_graph", None)
        if snapshot is None or graph is None:
            return None
        return PostDialRouteContext(
            tier3_members=tier_ladder.judged_leaves(dict(graph)),
            gateway_groups=frozenset(_POST_DIAL_GATEWAY_GROUPS),
        )

    def _runtime_post_dial_rung_gate(
        self,
        leaf: str,
        snapshot: CoreLoadedRouteSnapshot | None,
        payload: dict[str, Any] | None,
    ) -> tuple[str | None, RuntimeRouteBinding | None, Any]:
        """Spec §4.3: bind L to the published FINAL-EXIT route and its rungs.

        Read-only; ``(reason, None, None)`` or ``(None, binding, RungsResult)``.
        """

        if snapshot is None or not isinstance(payload, dict):
            return "route_unavailable", None, None
        binding = self._runtime_route_binding_for_outbound(snapshot, payload, "FINAL-EXIT")
        if binding is None or not snapshot.owns(binding):
            return "route_unbound", None, None
        chain = tuple(binding.route_chain)
        if binding.node.pool_kind == "gateway" or any(
            part in _POST_DIAL_GATEWAY_GROUPS for part in chain
        ):
            # Spec §1.2: the published path passes through a Gateway.
            return "gateway_scope_off", None, None
        if binding.node.proxy_name != leaf or not chain or chain[-1] != leaf:
            return "route_binding_mismatch", None, None
        if len(chain) < 3 or chain[1] != tier_ladder.PROXY_FALLBACK:
            return "route_outside_ladder", None, None
        groups = {
            str(state.name): tier_ladder.GroupView.from_state(state)
            for state in tuple(snapshot.group_states)
        }
        result = tier_ladder.rungs(
            chain,
            groups,
            self._runtime_loaded_group_timeouts(snapshot),
            graph=dict(snapshot.group_graph),
        )
        if result.reason is not None:
            return str(result.reason), None, None
        return None, binding, result

    def _runtime_post_dial_ladder_admission(
        self,
        trigger: Any,
        judge: PostDialJudgeService,
        *,
        now: float,
        register: bool,
        outcome: dict[str, Any] | None = None,
    ) -> tuple[PostDialJudgeJob | None, str | None]:
        """Spec §4.4: today's admission order with the rung gate, then the
        ``d4_txn_busy`` check; a 20 s ticket and ``job.ladder``."""

        diag_ticket = self._node_judgement_arm_permit()
        leaf = str(trigger.leaf)
        intent_revision = int(getattr(self, "_runtime_selector_intent_revision", 0) or 0)
        facility_epoch = int(getattr(self, "_runtime_facility_epoch", 0) or 0)
        snapshot, payload = self._runtime_post_dial_route_refs()
        policy = self._node_judgement_policy()
        policy_key = tuple(policy.ladder_policy_key)
        with self._node_judgement_arm_capture() as arm_trace:
            armed = bool(
                self._runtime_recovery_is_armed(snapshot, route_state=(snapshot, payload))
            )
        arm_check = str(arm_trace.get("arm_check") or ("armed" if armed else "override_unknown"))
        self._node_judgement_arm_trace("admission_arm_check", arm_check)
        self._node_judgement_arm_observe("admission", armed=armed, check=arm_check, captured=True,
                                         ticket=diag_ticket)
        d4_busy = self._runtime_post_dial_d4_busy(leaf)
        route_reason, binding, gate = self._runtime_post_dial_rung_gate(leaf, snapshot, payload)
        first = gate.rungs[0] if gate is not None and gate.rungs else None
        if outcome is not None:
            outcome["ladder_rungs"] = len(gate.rungs) if gate is not None else 0
        status_failure = bool(
            first is not None
            and isinstance(payload, dict)
            and judge.latest_sample_is_status_failure(
                first.accused,
                self._runtime_proxy_entries(payload).get(first.accused),
                str(first.url or ""),
            )
        )
        reason = judge.blocked(
            leaf,
            now,
            armed=armed,
            d4_busy=d4_busy,
            status_failure=status_failure,
            **_post_dial_override_kwargs(judge, trigger),
        ) or route_reason
        if reason is None:
            busy = self._runtime_post_dial_d4_txn_busy()
            if busy is not None:
                reason = busy.replace(":", "_")
        if register and reason == "route_binding_mismatch" and snapshot is not None:
            source_was_ready = bool(getattr(self, "_source_control_final_exit_was_ready", False))
            refresh_epochs = self._post_dial_refresh_epochs()
            disposition = self._queue_post_dial_binding_refresh(
                leaf,
                snapshot,
                cause=_JUDGE_REFRESH_CAUSE_MISMATCH,
            )
            self._log_post_dial_judge_refresh(
                trigger,
                judge,
                cause=_JUDGE_REFRESH_CAUSE_MISMATCH,
                disposition=disposition,
                snapshot=snapshot,
                arm_check=arm_check,
                key_on=None,
                ticket=diag_ticket,
                source_was_ready=source_was_ready,
                epochs=refresh_epochs,
            )
        elif register and reason == "not_armed":
            self._runtime_post_dial_stale_arm_refresh(
                trigger,
                judge,
                now=now,
                snapshot=snapshot,
                payload=payload,
                route_reason=route_reason,
                d4_busy=d4_busy,
                status_failure=status_failure,
                intent_revision=intent_revision,
                arm_check=arm_check,
                outcome=outcome,
                ticket=diag_ticket,
            )
        if reason is not None or not register:
            return None, reason
        assert snapshot is not None and isinstance(payload, dict)
        assert binding is not None and gate is not None and first is not None
        tokens = tuple(str(token) for token in (getattr(trigger, "tokens", ()) or ()))
        kind = str(getattr(trigger, "kind", "") or "post_dial")
        failure = BoundRuntimeFailure(
            binding=binding,
            protocol="TCP",
            observed_outbound=binding.observed_outbound,
            destination_token=runtime_destination_token(
                "post-dial:" + (tokens[0] if tokens else kind)
            ),
            error_type=f"post_dial_{kind.lower()}",
            observed_at_monotonic=self._runtime_recovery_now(),
        )
        incident_id = "post-dial-" + os.urandom(8).hex()
        ticket = self._ensure_runtime_recovery_ticket(
            failure,
            snapshot,
            incident_id,
            window_s=tier_ladder.LADDER_CAP_S,
        )
        if not isinstance(ticket, _RuntimeRecoveryTicket):
            return None, "ticket_unavailable"
        if (
            int(ticket.selector_intent_revision) != intent_revision
            or int(ticket.facility_epoch) != facility_epoch
        ):
            self._complete_runtime_recovery_hold(
                ticket,
                reason_code="post_dial_authority_changed",
            )
            return None, "authority_changed"
        provider_name = str(
            getattr(self, "_tier3_core_provider_name", "TIER3B-RUNTIME")
            or "TIER3B-RUNTIME"
        )
        context = _PostDialJudgeContext(
            incident_id=incident_id,
            quarantine_token=f"{incident_id}:judge",
            snapshot=snapshot,
            payload=copy.deepcopy(payload),
            binding=binding,
            failure=failure,
            ticket=ticket,
            mutation_binding=_dataclass_replace(
                self._runtime_mutation_binding_for_snapshot(snapshot),
                facility_epoch=int(ticket.facility_epoch),
                selector_intent_revision=int(ticket.selector_intent_revision),
            ),
            # Only a TIER3-AUTO rung ① reads the provider (spec §4.4 step 10).
            provider_name=provider_name if first.group == "TIER3-AUTO" else "",
        )
        job = PostDialJudgeJob(
            leaf=leaf,
            kind=kind,
            tokens=tokens,
            episode=int(getattr(trigger, "episode", 0) or 0),
            test_url=str(first.url),
            expected_status=str(first.expected),
            ticket_deadline=float(ticket.deadline_monotonic),
            runner=self.__dict__.get("_runtime_post_dial_observer"),
            context=context,
            durable=bool(
                policy.durable_conviction
                and first.group == "TIER3-AUTO"
                and first.kind is tier_ladder.RungKind.LEAF
            ),
        )
        try:
            group_names = frozenset(name for name, _members in tuple(snapshot.group_graph))
            ladder = self._runtime_post_dial_new_ladder(
                gate.rungs,
                self._runtime_post_dial_ladder_authority(snapshot, policy_key),
                float(ticket.deadline_monotonic),
                tier_ladder.ladder_id(incident_id),
                tuple(binding.route_chain),
                lease=self._runtime_ladder_lease_field(group_names),
                group_names=group_names,
            )
            if ladder is None:
                raise LookupError("PostDialLadder")
            job.ladder = ladder
        except Exception:
            self._complete_runtime_recovery_hold(
                ticket,
                reason_code="post_dial_ladder_unavailable",
            )
            return None, "ladder_unavailable"
        return job, None

    def _runtime_post_dial_ladder_authority(
        self,
        snapshot: CoreLoadedRouteSnapshot,
        policy_key: tuple[bool, bool, bool],
    ) -> Any:
        """Spec §4.6: the authority a ladder is admitted under."""

        lock = getattr(self, "_runtime_failure_monitor_lock", None)
        with lock if lock is not None else nullcontext():
            lease = getattr(self, "_runtime_route_mutation_lease", None)
            lease_obj_id = id(lease) if isinstance(lease, dict) else None
            release_state = str(lease.get("release_state") or "") if isinstance(lease, dict) else ""
        lease_lock = self.__dict__.get("_route_lease_lock")
        with lease_lock if lease_lock is not None else nullcontext():
            clocks = getattr(self, "_route_lease_clocks", None)
            digest = tier_ladder.lease_digest(tuple(clocks.values()) if isinstance(clocks, dict) else ())
        return tier_ladder.LadderAuthority(
            pid=int(snapshot.process_pid),
            process_generation=int(snapshot.process_generation),
            core_generation=int(snapshot.core_generation),
            semantic_digest=str(snapshot.semantic_digest),
            network_context_epoch=int(snapshot.network_context_epoch),
            selector_intent_revision=int(getattr(self, "_runtime_selector_intent_revision", 0) or 0),
            facility_epoch=int(getattr(self, "_runtime_facility_epoch", 0) or 0),
            lifecycle_revision=int(getattr(self, "_lifecycle_revision", 0) or 0),
            worker_token=tuple(self._runtime_worker_token()),
            group_graph=tuple(snapshot.group_graph),
            policy_key=tuple(policy_key),
            lease_obj_id=lease_obj_id,
            lease_release_state=release_state,
            lease_digest=digest,
        )

    def _runtime_post_dial_ladder_check(self, job: PostDialJudgeJob) -> str | None:
        """``ladder_check`` hook (spec §4.6): before every probe unit and
        commit.  The outcome form: ``authority_changed_<field>`` or
        ``d4_txn_busy_<sub>``; None to go on."""

        ladder = getattr(job, "ladder", None)
        if ladder is None:
            return None
        try:
            snapshot, _payload = self._runtime_post_dial_route_refs()
            if snapshot is None:
                return "authority_changed_pid"
            current = self._runtime_post_dial_ladder_authority(
                snapshot,
                tuple(self._node_judgement_policy().ladder_policy_key),
            )
            changed = tier_ladder.authority_diff(ladder.authority, current)
            if changed is None:
                changed = self._runtime_post_dial_d4_txn_busy()
        except Exception as exc:
            changed = "authority_changed_" + type(exc).__name__.lower()
        return None if changed is None else str(changed).replace(":", "_")

    def _runtime_post_dial_d4_txn_busy(self) -> str | None:
        """Spec §5.2: a D4 transaction is in flight (global checks only).

        A settled fixed or selector lease does not block; recovery workers,
        a releasing lease, a running passive failback, a fail-closed lease
        and an open Core mutation transaction do.  ``d4_txn_busy:<sub>``.
        """

        busy: str | None = None
        lock = getattr(self, "_runtime_failure_monitor_lock", None)
        with lock if lock is not None else nullcontext():
            lease = getattr(self, "_runtime_route_mutation_lease", None)
            requests = getattr(self, "_runtime_passive_failback_requests", None) or {}
            if getattr(self, "_runtime_failure_recovery_bindings", None):
                busy = "d4_txn_busy:recovery_worker"
            elif isinstance(lease, dict) and str(lease.get("release_state") or "") == "releasing":
                busy = "d4_txn_busy:lease_releasing"
            elif any(
                isinstance(value, dict) and value.get("running")
                for value in (requests.values() if isinstance(requests, dict) else ())
            ):
                busy = "d4_txn_busy:passive_failback"
            elif self._route_lease_fail_closed(lease if isinstance(lease, dict) else None):
                busy = "d4_txn_busy:fail_closed"
        if busy is not None:
            return busy
        if getattr(self, "_tier3_provider_write_busy", False):
            # A verified provider write is rebuilding and re-testing members;
            # a judgement now would read untested state and race its tests.
            return "d4_txn_busy:provider_write"
        coordinator = getattr(self, "_runtime_egress_coordinator", None)
        active = getattr(coordinator, "core_mutation_active", None)
        try:
            if callable(active) and active():
                return "d4_txn_busy:core_mutation"
        except Exception:
            return "d4_txn_busy:core_mutation"
        return None

    def _runtime_post_dial_ladder_rearm_scope(self, payload: dict[str, Any] | None) -> bool:
        """Spec §2.4 ``ladder_scope``: FINAL-EXIT on PROXY-FALLBACK, no
        Gateway group on its chain and no fail-closed lease."""

        if not isinstance(payload, dict):
            return False
        entries = self._runtime_proxy_entries(payload)
        final_exit = entries.get("FINAL-EXIT")
        if not isinstance(final_exit, dict) or str(final_exit.get("now") or "") != tier_ladder.PROXY_FALLBACK:
            return False
        route = inspect_runtime_route(payload.get("proxies"), start="FINAL-EXIT")
        names = [str(layer.get("name") or "") for layer in list(route.get("layers") or [])]
        names.append(str(route.get("leaf_proxy") or ""))
        if any(name in _POST_DIAL_GATEWAY_GROUPS for name in names):
            return False
        lock = getattr(self, "_runtime_failure_monitor_lock", None)
        with lock if lock is not None else nullcontext():
            lease = getattr(self, "_runtime_route_mutation_lease", None)
        return not self._route_lease_fail_closed(lease if isinstance(lease, dict) else None)

    def _runtime_post_dial_ladder_probe_refusal(
        self,
        job: PostDialJudgeJob,
        action: Any,
    ) -> PostDialProbeOutcome | None:
        """Spec §4.7 off-path guard: a ladder probe on a non-rung group is
        refused (indeterminate) and logged ``probe_refused``."""

        ladder = job.ladder
        groups = {str(rung.group) for rung in tuple(getattr(ladder, "rungs", ()) or ())}
        if getattr(action, "group", None) in groups:
            return None
        self._log_runtime_post_dial_record(
            "info",
            {
                "ev": "probe_refused",
                "t": round(time.time(), 3),
                "ladder": str(getattr(ladder, "ladder_id", "") or ""),
                "name": str(getattr(action, "name", "") or ""),
                "reason": "off_path",
            },
        )
        return PostDialProbeOutcome(NodeJudgementProbeClass.INDETERMINATE)

    def _runtime_post_dial_fresh_state(
        self,
        timeout: float,
    ) -> tuple[RuntimeRouteBinding, CoreLoadedRouteSnapshot, dict[str, Any]] | None:
        """Spec §4.8: a refresh that itself succeeded, then the published
        binding state.  None when the refresh did not run (busy lock,
        timeout, failure): the old snapshot is never returned as fresh."""

        try:
            refreshed = self._refresh_runtime_route_snapshot(
                timeout_seconds=max(0.05, float(timeout))
            )
        except Exception:
            return None
        if refreshed is None:
            return None
        try:
            return self._current_runtime_failure_binding_state(refresh=False)
        except Exception:
            return None

    def _runtime_post_dial_rung_read(
        self,
        job: PostDialJudgeJob,
        rung: Any,
    ) -> PostDialRouteRead | None:
        """Spec §4.8: one rung's route read.

        TIER3-AUTO leaf rung: today's S4 + S3 (+ S5).  Other leaf rungs:
        the group plus up to 8 member reads.  Group rungs: one fresh full
        refresh and nothing else (a ``GET /proxies/<group>`` evaluates that
        group's selection).  Never ``GET /providers/proxies``.
        """

        ladder = getattr(job, "ladder", None)
        if ladder is None or rung is None:
            return None
        index = int(rung.index)
        if self._runtime_ladder_flag(ladder, "accused_failed_known", index):
            # Issued after the accused's failure was known: this read
            # evaluates the group and consumes a dead pin's drop (P3).
            self._runtime_ladder_store(ladder, "drop_consumed", index, True)
        read_at = self._runtime_recovery_now()
        if rung.kind is tier_ladder.RungKind.LEAF:
            try:
                client = self._require_api_client()
            except Exception:
                return None
            timeout = _POST_DIAL_CONTROLLER_TIMEOUT_SECONDS
            try:
                group = client.proxy(str(rung.group), timeout=timeout)
            except Exception:
                return None
            provider = None
            if rung.group == "TIER3-AUTO":
                try:
                    provider = client.provider_proxies_one(
                        job.context.provider_name,
                        timeout=timeout,
                    )
                except Exception:
                    provider = None
            return post_dial_route_read_from(
                group,
                provider,
                test_url=str(rung.url),
                read_member=lambda name: client.proxy(name, timeout=timeout),
                read_at=read_at,
                priority=(str(rung.accused),),
            )
        state = self._runtime_post_dial_fresh_state(tier_ladder.LADDER_REFRESH_ALLOWANCE_S)
        if state is None:
            return None
        entries = self._runtime_proxy_entries(state[2])

        def read_member(name: str) -> dict[str, Any]:
            entry = entries.get(name)
            if not isinstance(entry, dict):
                raise LookupError("member not in the refreshed payload")
            return entry

        return post_dial_route_read_from(
            entries.get(str(rung.group)),
            None,
            test_url=str(rung.url),
            read_member=read_member,
            read_at=read_at,
            max_prefix_reads=4096,
            priority=(str(rung.accused),),
        )

    def _runtime_post_dial_ladder_escalate(self, job: PostDialJudgeJob, k: int) -> str | None:
        """``ladder_escalate`` hook (spec §4.8): before rung ``k`` (k ≥ 1).

        A sacrificial read of rung k-1's group when its admission pin was
        the accused and the drop is not consumed; one fresh refresh; the
        authority check; the route above rung k unchanged.  Stores rung k's
        baseline and its alive map (the witness order) on the ladder.
        """

        try:
            ladder = getattr(job, "ladder", None)
            rungs = tuple(getattr(ladder, "rungs", ()) or ())
            k = int(k)
            if ladder is None or not 0 < k < len(rungs):
                return "refresh_unavailable"
            lower, rung = rungs[k - 1], rungs[k]
            if (
                lower.fixed0
                and lower.fixed0 == lower.accused
                and not self._runtime_ladder_flag(ladder, "drop_consumed", k - 1)
            ):
                try:
                    self._require_api_client().proxy(
                        str(lower.group),
                        timeout=_POST_DIAL_CONTROLLER_TIMEOUT_SECONDS,
                    )
                except Exception:
                    pass
                self._runtime_ladder_store(ladder, "drop_consumed", k - 1, True)
            state = self._runtime_post_dial_fresh_state(tier_ladder.LADDER_REFRESH_ALLOWANCE_S)
            if state is None:
                return "refresh_unavailable"
            refusal = self._runtime_post_dial_ladder_check(job)
            if refusal is not None:
                return refusal
            binding1, snapshot1, payload1 = state
            chain0 = tuple(getattr(ladder, "chain0", ()) or ())
            chain1 = tuple(binding1.route_chain)
            depth = int(rung.depth)
            if chain1[: depth + 1] != chain0[: depth + 1]:
                return "ladder_route_moved"
            deeper_moved = False
            for i in range(depth + 1, len(chain0) - 1):
                group_state = snapshot1.group_state(chain0[i])
                if group_state is not None and str(group_state.now or "") != chain0[i + 1]:
                    deeper_moved = True
                    break
            entries1 = self._runtime_proxy_entries(payload1)
            alive = {
                name: bool(node_judgement_member_alive(entries1.get(name), rung.url))
                for name in rung.members
                if isinstance(entries1.get(name), dict)
            }
            unknown = frozenset(name for name in rung.members if not isinstance(entries1.get(name), dict))
            set_rung_state = getattr(ladder, "set_rung_state", None)
            if callable(set_rung_state):
                set_rung_state(k, alive=alive, unknown=unknown, baseline=state)
            else:
                self._runtime_ladder_store(ladder, "baselines", k, state)
                self._runtime_ladder_store(ladder, "rung_alive", k, alive)
                self._runtime_ladder_store(ladder, "rung_unknown", k, unknown)
            self._runtime_ladder_set(ladder, "deeper_moved", deeper_moved)
            return None
        except Exception:
            return "refresh_unavailable"

    def _runtime_post_dial_rung_native_commit(
        self,
        job: PostDialJudgeJob,
        done: Any,
    ) -> tuple[bool, str]:
        """Spec §4.9: the rung commit with the sacrificial read (design §19.3).

        Mihomo already moved the rung group on its own failed sample.  A
        dead admission pin on the accused is cleared first by one discarded
        group read (unless a read after the failure already consumed it);
        then one fresh refresh (read 2: settled) must show the group on its
        expected native pick, not the accused, with the route above
        unchanged.  Only a pick proven in this rung (a passing successor or
        the passed witness) settles RECOVERED; otherwise a controller hold.
        Never writes.  Returns (accepted, reason).
        """

        context = job.context
        ladder = job.ladder
        rung = self._runtime_ladder_current_rung(ladder)
        deadline = float(getattr(ladder, "deadline", context.ticket.deadline_monotonic))
        accepted = False
        reason = "commit_rejected"
        refreshed = False
        pinned = bool(rung is not None and rung.fixed0 and rung.fixed0 == rung.accused)
        facts: dict[str, Any] = {"pick": "", "proven": False, "sacrificial": False, "fixed0": pinned}
        try:
            remaining = deadline - self._runtime_recovery_now()
            if not self._node_judgement_policy().acts:
                reason = "act_mode_off"
            elif remaining <= 0.05:
                reason = "commit_late"
            elif rung is None:
                reason = "commit_rejected"
            else:
                refusal = self._runtime_post_dial_ladder_check(job)
                if refusal is not None:
                    reason = refusal
                else:
                    if pinned and not self._runtime_ladder_flag(ladder, "drop_consumed", int(rung.index)):
                        # Read 1 clears the dead pin; it is discarded
                        # unconditionally (P3 finding 2).
                        facts["sacrificial"] = True
                        try:
                            self._require_api_client().proxy(
                                str(rung.group),
                                timeout=_POST_DIAL_CONTROLLER_TIMEOUT_SECONDS,
                            )
                        except Exception:
                            pass
                        self._runtime_ladder_store(ladder, "drop_consumed", int(rung.index), True)
                        remaining = deadline - self._runtime_recovery_now()
                    refreshed = True
                    state1 = self._runtime_post_dial_fresh_state(
                        max(0.05, min(0.75, remaining - 0.05))
                    )
                    if state1 is None:
                        reason = "route_refresh_unavailable"
                    else:
                        baseline = self._runtime_ladder_item(ladder, "baselines", int(rung.index))
                        if baseline is None:
                            baseline = (context.binding, context.snapshot, context.payload)
                        rebound = self._runtime_post_dial_rung_native_rebind(
                            rung,
                            ladder.authority,
                            baseline,
                            state1,
                            context.mutation_binding,
                            context.binding,
                            provisional=getattr(job, "provisional", None),
                        )
                        if isinstance(rebound, str):
                            reason = rebound
                            if reason in {"pin_drop_unsettled", "native_pick_mismatch"}:
                                self._queue_runtime_route_snapshot_refresh()
                        else:
                            (rebound_binding, snapshot1, payload1), _mutation1, pick, to_ref = rebound
                            facts["pick"] = str(pick.pick)
                            passed_at = getattr(ladder, "passed_at", None)
                            passed = set(
                                passed_at(int(rung.index))
                                if callable(passed_at)
                                else self._runtime_ladder_item(ladder, "passed", int(rung.index), ()) or ()
                            )
                            successor = str(getattr(done, "successor", "") or "")
                            if successor:
                                passed.add(successor)
                            facts["proven"] = str(pick.pick) in passed
                            if not facts["proven"]:
                                reason = "moved_unproven"
                            else:
                                accepted, reason = self._runtime_post_dial_rung_settle(
                                    job,
                                    rung,
                                    deadline,
                                    rebound_binding,
                                    snapshot1,
                                    payload1,
                                    to_ref,
                                )
        except Exception as exc:
            reason = f"commit_error_{type(exc).__name__}"
        finally:
            note_commit = getattr(ladder, "note_commit", None)
            if callable(note_commit):
                try:
                    note_commit(
                        pick=str(facts["pick"]) or None,
                        proven=bool(facts["proven"]),
                        sacrificial=bool(facts["sacrificial"]),
                    )
                except Exception:
                    pass
            if not accepted:
                self._runtime_post_dial_finish(job, reason)
            if refreshed:
                try:
                    self._try_arm_runtime_recovery()
                except Exception:
                    pass
        return accepted, reason

    def _runtime_post_dial_rung_settle(
        self,
        job: PostDialJudgeJob,
        rung: Any,
        deadline: float,
        rebound_binding: RuntimeRouteBinding,
        snapshot1: CoreLoadedRouteSnapshot,
        payload1: dict[str, Any],
        to_ref: RuntimeNodeRef,
    ) -> tuple[bool, str]:
        """Spec §4.9 step 5: rebind the ticket (20 s window kept) and settle."""

        context = job.context
        ticket0 = context.ticket
        failure1 = _dataclass_replace(context.failure, binding=rebound_binding)
        ticket1 = self._register_runtime_recovery_ticket(
            failure1,
            snapshot1,
            context.incident_id,
            force_rebind=True,
            deadline_monotonic=deadline,
            window_s=tier_ladder.LADDER_CAP_S,
        )
        context.ticket = ticket1
        if (
            int(ticket1.selector_intent_revision),
            int(ticket1.facility_epoch),
        ) != (
            int(ticket0.selector_intent_revision),
            int(ticket0.facility_epoch),
        ):
            return False, "authority_changed"
        facts = {
            "put": False,
            "readback": True,
            "final_204": False,
            "rung": int(rung.index) + 1,
            "depth": int(rung.depth),
            "kind": str(getattr(rung.kind, "value", rung.kind)),
        }
        if bool(getattr(job, "durable", False)):
            health = self._apply_confirmed_runtime_health(
                failure1,
                snapshot1,
                payload1,
                incident_id=context.incident_id,
                quarantine_token=context.quarantine_token,
                expected_facility_epoch=int(ticket0.facility_epoch),
                expected_ticket=ticket1,
                deadline_monotonic=deadline,
            )
            if not bool(health.get("accepted")):
                action = re.sub(
                    r"[^a-z0-9_]",
                    "_",
                    str(health.get("action") or "rejected").lower(),
                )[:32]
                return False, f"health_{action}"
            self._complete_runtime_recovery_outcome(
                context.incident_id,
                RuntimeRecoveryStatus.RECOVERED,
                reason_code="post_dial_native_commit",
                to_ref=to_ref,
                route_epoch=int(snapshot1.route_epoch),
                expected_ticket=ticket1,
                deadline_monotonic=deadline,
                facts=facts,
            )
            return True, "committed"
        guard = self._runtime_post_dial_rebind_guard(
            failure1,
            snapshot1,
            expected_facility_epoch=int(ticket0.facility_epoch),
            expected_ticket=ticket1,
            deadline_monotonic=deadline,
        )
        if guard is not None:
            return False, f"rebind_{guard}"
        self._complete_runtime_recovery_outcome(
            context.incident_id,
            RuntimeRecoveryStatus.RECOVERED,
            reason_code="post_dial_rung_native_rebind",
            to_ref=to_ref,
            route_epoch=int(snapshot1.route_epoch),
            expected_ticket=ticket1,
            deadline_monotonic=deadline,
            facts=facts,
        )
        return True, "post_dial_rung_native_rebind"

    def _runtime_post_dial_rung_native_rebind(
        self,
        rung: Any,
        authority: Any,
        baseline: tuple[RuntimeRouteBinding, CoreLoadedRouteSnapshot, Any],
        state1: tuple[RuntimeRouteBinding, CoreLoadedRouteSnapshot, dict[str, Any]],
        mutation_binding: CurrentMutationBinding | None,
        admission_binding: RuntimeRouteBinding,
        *,
        provisional: str | None = None,
    ) -> Any:
        """Spec §4.9 step 4 (sibling of ``_manual_route_contract_native_rebind``).

        ``provisional`` (key post_dial_provisional_move): the successor this
        judgement pinned the rung-1 group to; that pin is then also an
        accepted ``fixed``.

        ``((binding, snapshot, payload), mutation, NativePick, to_ref)`` or a
        reason: ``pin_drop_unsettled``, ``native_pick_mismatch`` or
        ``rebind_rejected``.  Read-only.
        """

        binding0, snapshot0, _payload0 = baseline
        binding1, snapshot1, payload1 = state1
        if mutation_binding is None:
            return "rebind_rejected"
        if (
            int(snapshot1.process_pid),
            int(snapshot1.process_generation),
            int(snapshot1.core_generation),
            str(snapshot1.semantic_digest),
            int(snapshot1.network_context_epoch),
        ) != (
            int(authority.pid),
            int(authority.process_generation),
            int(authority.core_generation),
            str(authority.semantic_digest),
            int(authority.network_context_epoch),
        ):
            return "rebind_rejected"
        if int(getattr(self, "_runtime_selector_intent_revision", 0) or 0) != int(
            mutation_binding.selector_intent_revision
        ) or int(getattr(self, "_runtime_facility_epoch", 0) or 0) != int(mutation_binding.facility_epoch):
            return "rebind_rejected"
        if tuple(snapshot1.group_graph) != tuple(authority.group_graph):
            return "rebind_rejected"
        group0 = snapshot0.group_state(str(rung.group))
        group1 = snapshot1.group_state(str(rung.group))
        if group0 is None or group1 is None:
            return "rebind_rejected"
        if (
            group1.type_name,
            tuple(group1.members),
            group1.test_url,
            group1.expected_status,
        ) != (
            group0.type_name,
            tuple(group0.members),
            group0.test_url,
            group0.expected_status,
        ):
            return "rebind_rejected"
        pinned = bool(rung.fixed0) and rung.fixed0 == rung.accused
        fixed1 = str(group1.fixed or "")
        if pinned and fixed1:
            return "pin_drop_unsettled"
        if not pinned and fixed1 not in {str(rung.fixed0 or ""), ""} and not (
            provisional and int(rung.index) == 0 and fixed1 == str(provisional)
        ):
            return "rebind_rejected"
        entries1 = self._runtime_proxy_entries(payload1)
        members1 = tuple(group1.members)
        pick = tier_ladder.expected_native_pick(
            members1,
            fixed1,
            tier_ladder.alive_at(entries1, str(rung.url), members1),
        )
        if not (str(group1.now or "") == pick.pick and pick.pick != rung.accused):
            return "pin_drop_unsettled" if pinned else "native_pick_mismatch"
        chain0 = tuple(binding0.route_chain)
        chain1 = tuple(binding1.route_chain)
        depth = int(rung.depth)
        if (
            len(chain1) <= depth
            or chain1[:depth] != chain0[:depth]
            or chain1[depth] != pick.pick
            or binding1.observed_outbound != "FINAL-EXIT"
            or binding1.node.pool_kind == "gateway"
        ):
            return "rebind_rejected"
        if node_judgement_member_alive(entries1.get(str(rung.accused)), str(rung.url)):
            return "rebind_rejected"
        rebound = _dataclass_replace(
            admission_binding,
            route_epoch=int(snapshot1.route_epoch),
            network_context_epoch=int(snapshot1.network_context_epoch),
        )
        rebound_mutation = self._runtime_mutation_binding_for_snapshot(snapshot1)
        if not self._runtime_mutation_binding_is_current(rebound_mutation):
            return "rebind_rejected"
        return (rebound, snapshot1, payload1), rebound_mutation, pick, binding1.node

    def _runtime_post_dial_successor_history(self, job: PostDialJudgeJob, successor: str) -> bool:
        """Key post_dial_successor_from_history (10-28): the successor's
        newest contract-URL history sample, from the side-effect-free
        ``GET /providers/proxies/<provider>`` only (never ``/proxies``), is
        alive with ``extra[url].alive`` true and at most
        SUCCESSOR_HISTORY_MAX_AGE_S old.  False on any doubt."""

        try:
            if not self._node_judgement_policy().post_dial_successor_from_history:
                return False
            provider_name = str(getattr(job.context, "provider_name", "") or "")
            if not provider_name:
                return False
            client = self._require_api_client()
            entry = post_dial_provider_member(
                client.provider_proxies_one(provider_name, timeout=_POST_DIAL_CONTROLLER_TIMEOUT_SECONDS),
                str(successor),
            )
            return post_dial_history_fresh(
                entry,
                str(job.test_url),
                now_wall=time.time(),
                max_age_s=float(self._runtime_post_dial_judge().constants.successor_history_max_age_s),
            )
        except Exception:
            return False

    def _runtime_post_dial_provisional_move(self, job: PostDialJudgeJob, successor: str) -> tuple[bool, str]:
        """Key post_dial_provisional_move (10-28): pin the rung-1 group
        (TIER3-AUTO, a leaf accused) to ``successor`` with the existing
        automatic fixed write, whose committed readback starts the route
        lease's TTL clock (so the pin is released by the lease's own rules:
        natural failback when A_C later passes).  Only with the route lease
        active, under ``_core_transition_lock`` after ``ladder_check``
        passes (no authority change, no D4 transaction).  Then one route
        refresh, and the ladder authority is re-baselined: this write is the
        judgement's own.  Never writes dead, closes nothing, settles nothing.
        Returns (moved, reason)."""

        ladder = getattr(job, "ladder", None)
        if ladder is None:
            return False, "no_ladder"
        try:
            policy = self._node_judgement_policy()
            if not (policy.acts and policy.post_dial_provisional_move):
                return False, "key_off"
            if not self._route_lease_active():
                return False, "lease_off"
            rung = self._runtime_ladder_current_rung(ladder)
            if (
                rung is None
                or int(rung.index) != 0
                or rung.kind is not tier_ladder.RungKind.LEAF
                or str(successor) not in tuple(rung.members)
                or str(successor) == str(rung.accused)
            ):
                return False, "not_rung1_leaf"
            if str(getattr(rung, "fixed0", "") or "") and str(rung.fixed0) == str(rung.accused):
                # The accused is pinned (an admission/recovery fixed pick): the
                # rung commit must clear that pin itself (sacrificial read), so
                # a provisional pin would leave it unsettled.  Refused.
                return False, "accused_pinned"
            deadline = float(getattr(ladder, "deadline", job.context.ticket.deadline_monotonic))
            if deadline - self._runtime_recovery_now() < 1.0:
                return False, "late"
            with self._core_transition_lock:
                refusal = self._runtime_post_dial_ladder_check(job)
                if refusal is not None:
                    return False, str(refusal)
                lock = getattr(self, "_runtime_failure_monitor_lock", None)
                with lock if lock is not None else nullcontext():
                    d4_lease = getattr(self, "_runtime_route_mutation_lease", None)
                if isinstance(d4_lease, dict):
                    # A D4 route-mutation lease (even a settled fixed one) owns
                    # the pick and will release it later; a provisional pin
                    # would be released or superseded under it.  Refused.
                    return False, "d4_lease_present"
                self._apply_runtime_automatic_selection(
                    {
                        "group": str(rung.group),
                        "target": str(successor),
                        "previous": str(rung.accused),
                        "mode": "fixed",
                        "alternative_leaf": str(successor),
                    },
                    deadline_monotonic=deadline,
                )
                remaining = deadline - self._runtime_recovery_now()
                self._refresh_runtime_route_snapshot(timeout_seconds=max(0.05, min(0.75, remaining - 0.05)))
                snapshot, _payload = self._runtime_post_dial_route_refs()
                if snapshot is None:
                    return True, "moved_refresh_pending"
                ladder.authority = self._runtime_post_dial_ladder_authority(
                    snapshot,
                    tuple(policy.ladder_policy_key),
                )
            return True, "moved"
        except Exception as exc:
            return False, "error_" + type(exc).__name__.lower()[:32]

    def _runtime_post_dial_ladder_end(self, job: PostDialJudgeJob, outcome: str) -> None:
        """``ladder_end`` hook: wake the lease watcher (Track H) and let a
        held overshoot candidate be re-evaluated (spec §6.2).  Never raises."""

        try:
            self._route_lease_wake("ladder_end")
        except Exception:
            pass
        try:
            self._runtime_overshoot_ladder_end_t = time.monotonic()
            if self._node_judgement_policy().overshoot_on:
                self._runtime_overshoot_ensure_worker()
            event = self.__dict__.get("_runtime_overshoot_event")
            if event is not None:
                event.set()
        except Exception:
            pass

    def _runtime_ladder_lease_field(self, group_names: Any) -> str:
        lock = getattr(self, "_runtime_failure_monitor_lock", None)
        with lock if lock is not None else nullcontext():
            lease = getattr(self, "_runtime_route_mutation_lease", None)
            mode = str(lease.get("mode") or "") if isinstance(lease, dict) else ""
            group = str(lease.get("group") or "") if isinstance(lease, dict) else ""
        if not mode or not group:
            return "none"
        return f"{mode}_{tier_ladder.group_code(group, group_names=group_names)}"

    def _log_runtime_post_dial_record(
        self,
        level: str,
        record: Any,
    ) -> None:
        """One observer record as a raw diagnostic (tokens and hashes only)."""

        logger = getattr(self, "logger", None)
        if not isinstance(logger, logging.Logger):
            return
        numeric = {
            "debug": logging.DEBUG,
            "warning": logging.WARNING,
        }.get(str(level), logging.INFO)
        if not logger.isEnabledFor(numeric):
            return
        fields = dict(record)
        enveloped = fields.pop("_arm_enveloped", False)
        local = self.__dict__.get("_node_judgement_arm_local")
        scope = getattr(local, "scope", None)
        if not enveloped and scope is not None and fields.get("ev") in {"trigger", "would_trigger"}:
            self._node_judgement_arm_observer_emit(level, fields, scope)
            return
        if fields.get("ev") == "gated" and scope is not None:
            with scope["state"]["lock"]:
                if self._node_judgement_arm_valid_locked(scope["ticket"], scope):
                    fields.update(instance=scope["instance"], observer=scope["observer"], scope=scope["scope"])
        if fields.get("ev") == "summary":
            judgement_state = self.__dict__.get("_node_judgement_runtime_state")
            judge = getattr(judgement_state, "judge", None)
            if judge is not None:
                fields["gated_not_armed_check_changes"] = int(judge.metrics.get("gated_not_armed_check_changes", 0))
            # rearm_on_stale_route counters: every key, zeros included,
            # whenever the judgement state exists (a running observer's
            # tokenizer lives there).
            if isinstance(judgement_state, _NodeJudgementRuntimeState):
                try:
                    with judgement_state.lock:
                        counts = dict(judgement_state.refresh_counts)
                    for counter in _JUDGE_REFRESH_COUNTER_KEYS:
                        fields[counter] = int(counts.get(counter, 0))
                except Exception:
                    pass
            diag_state = self.__dict__.get("_node_judgement_arm_diagnostics_state")
            if diag_state is not None:
                with diag_state["lock"]:
                    if diag_state.get("enabled"):
                        fields["arm_diagnostics_loss_total"] = int(diag_state["loss"])
                        fields["arm_refused_suppressed_total"] = int(diag_state["suppressed"])
        event = fields.pop("ev", "record") or "record"
        log_raw_diagnostic(
            logger,
            logging.getLevelName(numeric).lower(),
            "Post-dial observer %s (%s)",
            format_observer_value(event),
            format_observer_record(fields),
        )

    def _runtime_group_native_timeout_ms(self, group: str) -> int:
        """Mihomo's own URLTest timeout for one loaded fallback group.

        clash_formatter emits 5000 ms (Mihomo's default) for TIER3-AUTO and
        PROXY-FALLBACK; the inline Tier1/Tier2 groups use the configured
        primary-gateway latency ceiling as their ``timeout``.
        """

        name = str(group or "").strip()
        if name.startswith("TIER1-") or name.startswith("TIER2-"):
            try:
                testing = self._testing_block()
            except Exception:
                testing = {}
            return int(primary_gateway_max_latency_ms_from_testing(testing))
        return _NATIVE_GROUP_DEFAULT_TIMEOUT_MS

    def _run_native_group_round(
        self,
        group: str,
        *,
        probe_url: str,
        expected_status: str,
        timeout_ms: int,
        admission_seconds: float = _NATIVE_GROUP_ROUND_ADMISSION_SECONDS,
    ) -> dict[str, Any]:
        """One group URLTest on the owning group's exact contract (P0-2).

        Its execution window starts at broker admission (at most
        ``admission_seconds`` of queueing), so a round is never cut short by
        time spent waiting for a probe slot.
        """

        try:
            return self.test_group_delay(
                group,
                url=probe_url,
                timeout_ms=int(timeout_ms),
                expected_status=expected_status,
                native_admission_seconds=min(
                    _NATIVE_GROUP_ROUND_ADMISSION_SECONDS,
                    max(0.0, float(admission_seconds)),
                ),
            )
        except TypeError:
            # Narrow injected adapters predate the expected-status contract.
            return self.test_group_delay(
                group,
                url=probe_url,
                timeout_ms=int(timeout_ms),
            )

    @staticmethod
    def _native_group_round_not_issued(exc: BaseException) -> bool:
        """Whether a native round ended before its controller request left.

        Queue timeouts and rounds skipped for lack of a full window never
        reach Mihomo, so no member was written by them.
        """

        return bool(
            isinstance(exc, _RuntimeProbeBudgetUnavailable)
            and str(getattr(exc, "probe_indeterminate_reason", "") or "")
            # ProbeIndeterminateReason values; a skip raised before the
            # socket started reaches the caller as ``socket_not_started``.
            in {"queue_timeout", "socket_not_started", "group_round_skipped_queue"}
        )

    def _defer_native_group_round(
        self,
        *,
        group: str,
        probe_url: str,
        expected_status: str,
        timeout_ms: int,
        source: str,
    ) -> None:
        """Replace a round that would not fit its budget by one after READY.

        A shortened timeout writes every slower healthy member dead (Conf-6),
        so the round is never shortened.  At most one deferred round is held;
        it runs once, right after the next READY of the same Core generation.
        """

        # A plain int read, as _commit_runtime_monitoring_lease reads it.
        core_generation = int(getattr(self, "_core_generation", 0) or 0)
        record = {
            "group": str(group),
            "probe_url": str(probe_url),
            "expected_status": str(expected_status),
            "timeout_ms": int(timeout_ms),
            "core_generation": core_generation,
            "source": str(source),
        }
        state = self._node_judgement_state()
        with state.lock:
            state.deferred_group_round = record
        logger = getattr(self, "logger", None)
        if isinstance(logger, logging.Logger):
            log_raw_diagnostic(
                logger,
                "info",
                "Native group round deferred until READY (source=%s group=%s timeout_ms=%d)",
                str(source),
                str(group),
                int(timeout_ms),
            )
        try:
            ready = self._runtime_initial_activation_complete()
        except Exception:
            ready = False
        if ready:
            self._start_deferred_native_group_round()

    def _start_deferred_native_group_round(self) -> bool:
        """Start the one deferred native round, if any (no loop, no retry)."""

        state = self.__dict__.get("_node_judgement_runtime_state")
        if not isinstance(state, _NodeJudgementRuntimeState):
            return False
        with state.lock:
            record = state.deferred_group_round
            state.deferred_group_round = None
        if not isinstance(record, dict):
            return False
        stop_event = getattr(self, "stop_event", None)
        core_generation = int(getattr(self, "_core_generation", 0) or 0)
        if (
            (stop_event is not None and stop_event.is_set())
            or core_generation != int(record.get("core_generation") or 0)
        ):
            return False

        def run() -> None:
            if stop_event is not None and stop_event.is_set():
                return
            current_generation = int(getattr(self, "_core_generation", 0) or 0)
            if current_generation != int(record.get("core_generation") or 0):
                return
            try:
                self._run_native_group_round(
                    str(record["group"]),
                    probe_url=str(record["probe_url"]),
                    expected_status=str(record["expected_status"]),
                    timeout_ms=int(record["timeout_ms"]),
                )
            except Exception as exc:
                logger = getattr(self, "logger", None)
                if isinstance(logger, logging.Logger):
                    log_raw_diagnostic(
                        logger,
                        "warning",
                        "Deferred native group round did not complete (source=%s): %s",
                        str(record.get("source") or ""),
                        type(exc).__name__,
                    )

        threading.Thread(
            target=run,
            name="runtime-native-group-round",
            daemon=True,
        ).start()
        return True

    def _runtime_group_probe_contract(
        self,
        snapshot: CoreLoadedRouteSnapshot,
        group: str,
    ) -> tuple[str, str]:
        state = snapshot.group_state(group)
        try:
            default_url = self._default_probe_url()
        except (AttributeError, KeyError, TypeError, ValueError):
            # Narrow unit/integration adapters may omit the full config; the
            # production default is still an HTTPS-204 contract.
            default_url = "https://www.gstatic.com/generate_204"
        probe_url = str(
            getattr(state, "test_url", "") or default_url
        )
        expected_status = str(
            getattr(state, "expected_status", "") or "204"
        )
        return probe_url, expected_status

    def _runtime_hot_standby_contract_matches(
        self,
        evidence: _HotStandbyEvidence,
        snapshot: CoreLoadedRouteSnapshot,
        action: dict[str, Any],
    ) -> bool:
        """Return whether standby evidence is valid for this exact selection.

        Fallback groups key member liveness by their own URL/expected-status
        contract.  Reusing a node's unrelated diagnostic URL can make Mihomo
        synchronously URLTest during PUT and consume the recovery deadline.
        """

        group = str(action.get("group") or "")
        target = str(action.get("target") or "")
        mode = str(action.get("mode") or "")
        if (
            evidence.selection_group != group
            or evidence.selection_target != target
            or evidence.selection_mode != mode
        ):
            return False
        if mode != "fixed":
            return True
        # A fallback may select a nested group (for example TIER2-AUTO) while
        # the evidence was collected by probing only that group's eventual
        # leaf.  Mihomo keys AliveForTestUrl to the actual selected member, so
        # leaf evidence cannot prove the parent target was prewarmed. Force
        # the exact target URLTest before PUT in that case.
        if target != str(
            evidence.probed_proxy_name or evidence.ref.proxy_name
        ):
            return False
        probe_url, expected_status = self._runtime_group_probe_contract(
            snapshot,
            group,
        )
        return bool(
            evidence.probe_url == probe_url
            and evidence.expected_status == expected_status
        )

    @staticmethod
    def _runtime_probe_contract_accepts_204(expected_status: str | int) -> bool:
        text = str(expected_status or "").strip()
        if text == "204":
            return True
        for token in text.replace("/", ",").split(","):
            token = token.strip()
            if not token:
                continue
            if "-" in token:
                lower, _, upper = token.partition("-")
                try:
                    if int(lower.strip()) <= 204 <= int(upper.strip()):
                        return True
                except ValueError:
                    continue
        return False

    def _prewarm_runtime_switch_target(
        self,
        snapshot: CoreLoadedRouteSnapshot,
        action: dict[str, Any],
        *,
        deadline_monotonic: float,
        probe_priority: ProbePriority = ProbePriority.RUNTIME_MANUAL,
    ) -> dict[str, Any]:
        """Populate Mihomo's exact group-URL health before fallback Set()."""

        if str(action.get("mode") or "") != "fixed":
            return {"skipped": True, "reason": "selector_group"}
        remaining = self._runtime_recovery_remaining(deadline_monotonic)
        if remaining <= 0.0:
            raise TimeoutError("runtime alternative prewarm deadline expired")
        group = str(action.get("group") or "")
        target = str(action.get("target") or "")
        probe_url, expected_status = self._runtime_group_probe_contract(
            snapshot,
            group,
        )
        timeout_seconds = min(1.15, remaining)
        timeout_ms = max(100, int(timeout_seconds * 1000.0))
        self._register_runtime_internal_probe(
            probe_url,
            timeout_seconds=timeout_seconds,
        )
        result = self._probe_proxy_delay_with_urls(
            target,
            [probe_url],
            timeout_ms=timeout_ms,
            request_timeout_seconds=timeout_seconds,
            expected_status=expected_status,
            probe_priority=probe_priority,
        )
        return dict(result) if isinstance(result, dict) else {"result": result}

    def _apply_runtime_automatic_selection(
        self,
        action: dict[str, Any],
        *,
        deadline_monotonic: float,
    ) -> dict[str, Any]:
        remaining = self._runtime_recovery_remaining(deadline_monotonic)
        if remaining <= 0.0:
            raise TimeoutError("runtime alternative selection deadline expired")
        group = str(action.get("group") or "")
        target = str(action.get("target") or "")
        client = self._require_api_client()
        select_with_readback = getattr(
            client,
            "select_proxy_with_readback",
            None,
        )
        if callable(select_with_readback):
            put_budget = min(0.35, remaining)
            readback_budget = min(
                0.35,
                self._runtime_recovery_remaining(deadline_monotonic),
            )
            if readback_budget <= 0.0:
                raise TimeoutError("runtime selection readback deadline expired")
            selection_kwargs: dict[str, Any] = {
                "mode": (
                    "fixed"
                    if str(action.get("mode") or "") == "fixed"
                    else "selected"
                ),
                "timeout": put_budget,
                "readback_timeout": readback_budget,
            }
            try:
                selection_parameters = inspect.signature(
                    select_with_readback
                ).parameters
            except (TypeError, ValueError):
                selection_parameters = {}
            if "deadline_monotonic" in selection_parameters:
                selection_kwargs["deadline_monotonic"] = float(
                    deadline_monotonic
                )
            if "clock" in selection_parameters:
                selection_kwargs["clock"] = self._runtime_recovery_now
            result = select_with_readback(group, target, **selection_kwargs)
            if self._runtime_recovery_remaining(deadline_monotonic) <= 0.0:
                raise TimeoutError("runtime selection transaction deadline expired")
            result_payload = (
                asdict(result)
                if isinstance(result, MihomoSelectionCommit)
                else dict(result)
                if isinstance(result, dict)
                else {"result": result, "commit_state": "unknown"}
            )
            commit_state = str(result_payload.get("commit_state") or "")
            if commit_state == "not_committed":
                raise RuntimeError(
                    "runtime alternative selection was not authoritatively committed "
                    f"(group={group!r}, now={result_payload.get('now')!r}, "
                    f"fixed={result_payload.get('fixed')!r}, state={commit_state!r})"
                )
            if commit_state != "committed":
                if str(action.get("mode") or "") == "fixed":
                    # The fallback contract requires both now and fixed from
                    # the same authoritative GET.  An unknown fixed result
                    # cannot revoke the loaded snapshot and hope a later
                    # graph refresh guesses whether Set() committed.
                    raise RuntimeError(
                        "runtime alternative selection was not authoritatively committed "
                        f"(group={group!r}, state={commit_state!r})"
                    )
                # PUT may have committed before its response/readback timed
                # out. Do not issue another selection. The caller's immutable
                # full `/proxies` refresh is the second authoritative readback
                # and must prove both `now` and `fixed` before success.
                result_payload["readback_pending"] = True
        else:
            try:
                result = client.select_proxy(
                    group,
                    target,
                    timeout=min(0.35, remaining),
                )
            except TypeError:
                result = client.select_proxy(group, target)
            result_payload = (
                dict(result)
                if isinstance(result, dict)
                else {"result": result, "commit_state": "unknown"}
            )
            read_proxy = getattr(client, "proxy", None)
            if callable(read_proxy):
                readback_budget = min(
                    0.35,
                    self._runtime_recovery_remaining(deadline_monotonic),
                )
                if readback_budget <= 0.0:
                    raise TimeoutError("runtime selection readback deadline expired")
                try:
                    readback = read_proxy(group, timeout=readback_budget)
                except TypeError:
                    readback = read_proxy(group)
                if not isinstance(readback, dict):
                    raise RuntimeError(
                        "runtime alternative selection readback was not an object"
                    )
                now = str(readback.get("now") or "")
                fixed_observed = "fixed" in readback
                fixed = str(readback.get("fixed") or "")
                fixed_mode = str(action.get("mode") or "") == "fixed"
                committed = bool(
                    now == target
                    and (
                        not fixed_mode
                        or (fixed_observed and fixed == target)
                    )
                )
                result_payload.update(
                    {
                        "now": now,
                        "fixed": fixed if fixed_observed else None,
                        "commit_state": (
                            "committed" if committed else "not_committed"
                        ),
                        "readback": dict(readback),
                    }
                )
                if not committed:
                    raise RuntimeError(
                        "runtime alternative selection was not authoritatively committed "
                        f"(group={group!r}, now={now!r}, fixed={fixed!r})"
                    )
            else:
                # Compatibility adapters may only expose PUT. Keep the result
                # explicitly unknown; the caller must prove the exact route in
                # its bounded full `/proxies` snapshot before declaring success.
                result_payload["commit_state"] = "unknown"
                result_payload["readback_pending"] = True
        if self._runtime_recovery_remaining(deadline_monotonic) <= 0.0:
            raise TimeoutError("runtime selection transaction crossed its deadline")
        # This is an automatic incident-owned mutation, not user intent. Revoke
        # the old loaded snapshot but leave selector_intent_revision unchanged.
        with self._runtime_route_snapshot_lock:
            self._runtime_route_epoch += 1
            self._node_judgement_arm_epoch("apply_runtime_automatic_selection")
            self._mark_runtime_route_attribution_barrier_locked()
            self._runtime_route_snapshot = None
            self._runtime_route_snapshot_payload = None
            self._runtime_core_inventory_snapshot = None
            self._runtime_route_selection_signature = ()
        self._runtime_egress_coordinator.set_current_snapshot(None)
        # Route lease (lease-v1): start or renew the TTL clock of a committed
        # automatic fixed pick.  Leaf lock and Event.set only; no I/O.
        self._route_lease_note_pin(action, result_payload)
        return result_payload

    def _release_runtime_automatic_fixed_selection(
        self,
        lease_record: dict[str, Any],
        *,
        deadline_monotonic: float,
        readback_first: bool = False,
        ownership_check: Callable[[], bool] | None = None,
        before_release: Callable[[], Any] | None = None,
    ) -> dict[str, Any]:
        if str(lease_record.get("mode") or "") != "fixed":
            return {"skipped": True, "reason": "selector_lease"}
        remaining = self._runtime_recovery_remaining(deadline_monotonic)
        if remaining <= 0.0:
            raise TimeoutError("runtime fixed-route release deadline expired")
        group = str(lease_record.get("group") or "")
        if not group:
            raise RuntimeError("runtime fixed-route lease has no group")
        client = self._require_api_client()
        if readback_first:
            # A previous DELETE may have committed despite a lost response.
            # Reconcile that outcome before issuing another mutation.
            try:
                value = client.proxy(group, timeout=min(0.35, remaining))
            except Exception as exc:
                return {"group": group, "commit_state": "unknown", "readback_error": str(exc)}
            if not isinstance(value, dict) or "fixed" not in value:
                return {"group": group, "commit_state": "unknown", "readback": value}
            fixed = str(value.get("fixed") or "")
            if not fixed:
                return {"group": group, "commit_state": "committed", "readback": value}
            expected = str(lease_record.get("target_member") or lease_record.get("to") or "")
            if expected and fixed != expected:
                return {"group": group, "commit_state": "superseded", "readback": value}
        if ownership_check is not None and not ownership_check():
            return {"group": group, "commit_state": "superseded"}
        if before_release is not None:
            before_release()
        if ownership_check is not None and not ownership_check():
            return {"group": group, "commit_state": "superseded"}
        remaining = self._runtime_recovery_remaining(deadline_monotonic)
        if remaining <= 0.0:
            raise TimeoutError("runtime fixed-route release deadline expired before DELETE")
        request_error = ""
        try:
            try:
                result = client.unfix_proxy(
                    group,
                    timeout=min(0.35, remaining),
                )
            except TypeError:
                result = client.unfix_proxy(group)
        except Exception as exc:
            # DELETE may have committed before its response was interrupted.
            # Never retry it blindly; the one authoritative GET below decides.
            result = None
            request_error = str(exc)
        readback: dict[str, Any] | None = None
        readback_error = ""
        try:
            readback_budget = min(
                0.35,
                self._runtime_recovery_remaining(deadline_monotonic),
            )
            if readback_budget <= 0.0:
                raise TimeoutError("runtime fixed-route readback deadline expired")
            try:
                value = client.proxy(group, timeout=readback_budget)
            except TypeError:
                value = client.proxy(group)
            readback = dict(value) if isinstance(value, dict) else None
            if readback is None:
                readback_error = "fixed-route release readback was not an object"
        except Exception as exc:
            readback_error = str(exc)
        if readback is None:
            commit_state = "unknown"
        else:
            fixed_observed = "fixed" in readback
            fixed_value = str(readback.get("fixed") or "")
            commit_state = (
                "unknown"
                if not fixed_observed
                else "committed"
                if not fixed_value
                else "not_committed"
            )
        with self._runtime_route_snapshot_lock:
            self._runtime_route_epoch += 1
            self._node_judgement_arm_epoch("release_runtime_automatic_fixed_selection")
            self._mark_runtime_route_attribution_barrier_locked()
            self._runtime_route_snapshot = None
            self._runtime_route_snapshot_payload = None
            self._runtime_core_inventory_snapshot = None
            self._runtime_route_selection_signature = ()
        self._runtime_egress_coordinator.set_current_snapshot(None)
        return {
            "group": group,
            "commit_state": commit_state,
            "request": dict(result) if isinstance(result, dict) else result,
            "request_error": request_error,
            "readback": readback,
            "readback_error": readback_error,
        }

    # ------------------------------------------------------------------
    # Route lease (rules lease-v1, user decision 2026-10-26).
    #
    # Every automatic fixed pick written by _apply_runtime_automatic_selection
    # is a time-limited lease: it ends at its TTL, or earlier when the member
    # native fallback would pick next (ahead of the pin) passes Mihomo's own
    # health check, or as soon as Mihomo itself dropped the pick.  A user's
    # selection never becomes a lease.  One watcher thread runs only while
    # something is leased and reads only GET /providers/proxies/TIER3B-RUNTIME
    # (side-effect free).  enabled: false is today's code path exactly.

    _ROUTE_LEASE_PUT_SITES = {
        "_restore_runtime_automatic_route": "rollback",
        "_verify_capture_route_after_reload": "replay",
        "_activate_initial_unbound_candidate": "readmission",
    }

    def _route_lease_policy(self) -> RouteLeasePolicy:
        try:
            return RouteLeasePolicy.from_config(getattr(self, "config", None))
        except Exception:
            return RouteLeasePolicy.disabled()

    def _route_lease_active(self) -> bool:
        if self.__dict__.get("_route_lease_lock") is None:
            return False
        try:
            if not self._runtime_uses_early_single_coordinator():
                return False
        except Exception:
            return False
        return self._route_lease_policy().enabled

    def _route_lease_now(self) -> tuple[float, float]:
        clock = self.__dict__.get("_route_lease_clock")
        if callable(clock):
            mono, wall = clock()
            return float(mono), float(wall)
        return time.monotonic(), time.time()

    def _route_lease_tok(self, name: str) -> str:
        if not name:
            return "-"
        try:
            return str(self._node_judgement_state().tokenizer.leaf(str(name)))
        except Exception:
            return hashlib.sha256(str(name).encode("utf-8")).hexdigest()[:8]

    def _route_lease_queue_log(
        self,
        kind: str,
        fields: list[tuple[str, Any]],
        level: str = "info",
    ) -> None:
        """Called under the leaf lock: defer the log write to the watcher."""

        queue_ = self.__dict__.get("_route_lease_log_queue")
        if isinstance(queue_, list) and len(queue_) < 256:
            queue_.append((str(kind), str(level), list(fields)))

    def _route_lease_log(
        self,
        kind: str,
        fields: list[tuple[str, Any]],
        level: str = "info",
    ) -> None:
        logger = getattr(self, "logger", None)
        if not isinstance(logger, logging.Logger):
            return
        resolved = [
            (key, self._route_lease_tok(str(value)) if isinstance(value, route_lease.TokenName) else value)
            for key, value in fields
        ]
        log_raw_diagnostic(
            logger,
            level,
            "Runtime route lease %s (%s)",
            kind,
            route_lease.format_lease_fields(resolved),
        )

    def _route_lease_flush_logs(self) -> None:
        lock = self.__dict__.get("_route_lease_lock")
        if lock is None:
            return
        with lock:
            pending = list(self.__dict__.get("_route_lease_log_queue") or ())
            self._route_lease_log_queue = []
        for kind, level, fields in pending:
            self._route_lease_log(kind, fields, level)

    def _route_lease_watcher_alive(self) -> bool:
        thread = self.__dict__.get("_route_lease_thread")
        return bool(
            thread is not None
            and thread.is_alive()
            and getattr(thread, "route_lease_generation", None)
            == int(getattr(self, "_runtime_generation", 0) or 0)
        )

    def _route_lease_wake(self, reason: str = "") -> None:
        event = self.__dict__.get("_route_lease_event")
        if event is not None:
            event.set()
        if self.__dict__.get("_route_lease_lock") is not None and not self._route_lease_watcher_alive():
            # Lazily by the first wake (policy enabled later, or re-enabled
            # after the watcher exited): the health monitor creates it
            # outside every route lock.
            self._route_lease_thread_wanted = True

    def _route_lease_end_fields(
        self,
        clock: RouteLeaseClock,
        cause: str,
        *,
        by: str = "-",
        mono: float,
    ) -> list[tuple[str, Any]]:
        return [
            ("lease", clock.lease_id or "-"),
            ("cause", cause),
            ("by", by or "-"),
            ("age_s", max(0.0, float(mono) - float(clock.started_mono))),
            ("member", route_lease.TokenName(clock.member)),
            ("reads", int(clock.reads)),
            ("attempts", int(clock.attempts)),
            # An open deferral span counts up to this end line.
            ("deferred_s", self._route_lease_deferred_total(clock, mono)),
            ("verify", clock.last_verify or "skipped"),
            ("purge", "pending" if clock.purge_pending else "none"),
        ]

    @staticmethod
    def _route_lease_deferred_total(clock: RouteLeaseClock, mono: float) -> float:
        """Closed deferral spans plus the open one up to ``mono``."""

        total = float(clock.deferred_s)
        if clock.defer_reason:
            total += max(0.0, float(mono) - float(clock.defer_started_mono))
        return total

    def _route_lease_queue_replaced_end(
        self,
        clock: RouteLeaseClock,
        cause: str,
        mono: float,
    ) -> None:
        """A clock dropped for a new one: close its span, queue its end (leaf lock)."""

        if not (clock.live and clock.announced):
            return
        if clock.defer_reason:
            clock.deferred_s = self._route_lease_deferred_total(clock, mono)
            previous = clock.defer_reason
            clock.defer_reason = ""
            self._route_lease_queue_log(
                "deferred",
                [("lease", clock.lease_id or "-"), ("state", "end"), ("reason", previous), ("deferred_s", float(clock.deferred_s))],
            )
        self._route_lease_queue_log("end", self._route_lease_end_fields(clock, cause, mono=mono))

    def _route_lease_note_pin(
        self,
        action: dict[str, Any],
        result_payload: dict[str, Any] | None,
    ) -> None:
        """Start, renew or revive one group's TTL clock (leaf lock only)."""

        try:
            if str(action.get("mode") or "") != "fixed":
                return
            if not isinstance(result_payload, dict) or str(
                result_payload.get("commit_state") or ""
            ) != "committed":
                return
            lock = self.__dict__.get("_route_lease_lock")
            if lock is None or not self._route_lease_active():
                return
            group = str(action.get("group") or "")
            member = str(action.get("target") or "")
            if not group or not member:
                return
            caller = ""
            frame = inspect.currentframe()
            try:
                outer = frame.f_back.f_back if frame is not None and frame.f_back is not None else None
                caller = str(outer.f_code.co_name) if outer is not None else ""
            finally:
                del frame
            site = self._ROUTE_LEASE_PUT_SITES.get(caller, "recovery")
            policy = self._route_lease_policy()
            mono, wall = self._route_lease_now()
            intent_rev = int(getattr(self, "_runtime_selector_intent_revision", 0) or 0)
            core_generation = int(getattr(self, "_core_generation", 0) or 0)
            route_epoch = int(getattr(self, "_runtime_route_epoch", 0) or 0)
            with lock:
                clocks = self._route_lease_clocks
                clock = clocks.get(group)
                if clock is not None and clock.member == member and clock.live:
                    # Renew: a replay/rollback/readmission PUT never resets the TTL.
                    clock.last_put_mono = mono
                    clock.route_epoch = route_epoch
                    clock.core_generation = core_generation
                    if clock.announced:
                        self._route_lease_queue_log(
                            "renew",
                            [
                                ("lease", clock.lease_id or "-"),
                                ("member", route_lease.TokenName(member)),
                                ("age_s", max(0.0, mono - clock.started_mono)),
                                ("site", site if site != "recovery" else "readmission"),
                            ],
                        )
                elif (
                    clock is not None
                    and clock.member == member
                    and clock.ended in route_lease.DEATH_END_CAUSES
                    and mono - float(clock.ended_mono) <= float(policy.death_carry_seconds)
                ):
                    # Re-pin of the same member right after it died: keep the
                    # original start, so death never resets the TTL.
                    clock.ended = ""
                    clock.ended_by = ""
                    clock.purge_pending = False
                    clock.purge_attempts = 0
                    clock.verify_retry = False
                    clock.last_decision_mono = mono
                    clock.last_decision_wall = wall
                    clock.last_put_mono = mono
                    clock.intent_rev = intent_rev
                    clock.core_generation = core_generation
                    clock.route_epoch = route_epoch
                    clock.lease_obj = None
                    clock.announced = False
                    clock.orphan_since_mono = mono
                    clock.attempts = 0
                    clock.next_attempt_mono = 0.0
                    clock.mismatch_seq = -1
                    clock.backoff_checked = False
                    clock.skipped = set()
                    clock.carried = True
                else:
                    old = clocks.pop(group, None)
                    if old is not None:
                        # Recovery moved the pin to another member: the old
                        # lease ends here (its id never reaches collect).
                        self._route_lease_queue_replaced_end(old, "superseded", mono)
                    clocks[group] = RouteLeaseClock(
                        group=group,
                        member=member,
                        started_mono=mono,
                        started_wall=wall,
                        last_decision_mono=mono,
                        last_decision_wall=wall,
                        intent_rev=intent_rev,
                        core_generation=core_generation,
                        route_epoch=route_epoch,
                        origin={"readmission": "initial"}.get(site, site),
                        last_put_mono=mono,
                        orphan_since_mono=mono,
                    )
                    if len(clocks) > route_lease.MAX_CLOCKS:
                        ended = [key for key, value in clocks.items() if value.ended]
                        victims = ended or [key for key in clocks if key != group]
                        for key in victims[: len(clocks) - route_lease.MAX_CLOCKS]:
                            clocks.pop(key, None)
                thread = self.__dict__.get("_route_lease_thread")
                if thread is None or not thread.is_alive():
                    self._route_lease_thread_wanted = True
            self._route_lease_wake("note_pin")
        except Exception:
            logger = getattr(self, "logger", None)
            if isinstance(logger, logging.Logger):
                log_raw_diagnostic(logger, "debug", "Runtime route lease note was skipped", exc_info=True)

    def _route_lease_observe_snapshot(
        self,
        snapshot: CoreLoadedRouteSnapshot,
        proxies_payload: Any,
    ) -> None:
        """Keep each leased group's published fixed/alive state (no I/O)."""

        try:
            lock = self.__dict__.get("_route_lease_lock")
            if lock is None or not self._route_lease_active():
                return
            entries = mihomo_proxies_entries(proxies_payload)
            lease = getattr(self, "_runtime_route_mutation_lease", None)
            groups = {route_lease.TIER3_GROUP}
            if isinstance(lease, dict) and lease.get("group"):
                groups.add(str(lease.get("group")))
            mono, _wall = self._route_lease_now()
            restored: tuple[str, str] | None = None
            wake = False
            with lock:
                groups.update(self._route_lease_clocks)
                counters = self._route_lease_counters
                seq = int(counters.get("obs_seq", 0) or 0) + 1
                counters["obs_seq"] = seq
                for group in groups:
                    state = snapshot.group_state(group)
                    if state is None:
                        self._route_lease_obs.pop(group, None)
                        continue
                    fixed = str(state.fixed or "")
                    test_url = str(state.test_url or "")
                    alive = (
                        route_lease.member_alive_or_none(entries.get(fixed), test_url)
                        if fixed
                        else None
                    )
                    self._route_lease_obs[group] = RouteLeaseObservation(
                        group=group,
                        fixed=fixed,
                        fixed_alive=alive,
                        members=tuple(str(item) for item in state.members),
                        test_url=test_url,
                        route_epoch=int(snapshot.route_epoch),
                        core_generation=int(snapshot.core_generation),
                        seq=seq,
                        published_mono=mono,
                    )
                    clock = self._route_lease_clocks.get(group)
                    if clock is not None and (clock.live or clock.purge_pending) and fixed != clock.member:
                        wake = True
                    lease_owns = bool(
                        isinstance(lease, dict)
                        and str(lease.get("group") or "") == group
                    )
                    user_groups = counters.get("_user_groups")
                    user_owned = isinstance(user_groups, set) and bool(
                        {"*", group} & user_groups
                    )
                    if (
                        group == route_lease.TIER3_GROUP
                        and fixed
                        and fixed in tuple(state.members)
                        and clock is None
                        and not lease_owns
                        and not user_owned
                    ):
                        key = f"{int(snapshot.core_generation)}:{fixed}"
                        seen = counters.setdefault("_restored_seen", set())  # type: ignore[arg-type]
                        if isinstance(seen, set) and key not in seen and len(seen) < 64:
                            seen.add(key)
                            restored = (group, fixed)
            if restored is not None:
                self._route_lease_log(
                    "skipped",
                    [
                        ("lease", "-"),
                        ("reason", "restored_pin_unowned"),
                        ("group", restored[0]),
                        ("member", self._route_lease_tok(restored[1])),
                    ],
                )
            if wake:
                self._route_lease_wake("snapshot")
        except Exception:
            logger = getattr(self, "logger", None)
            if isinstance(logger, logging.Logger):
                log_raw_diagnostic(logger, "debug", "Runtime route lease observation was skipped", exc_info=True)

    def _route_lease_takes_passive_pass(self, lease: dict[str, Any]) -> bool:
        """TIER3-AUTO PASS events go to the lease watcher, not passive failback."""

        if not isinstance(lease, dict):
            return False
        if str(lease.get("group") or "") != route_lease.TIER3_GROUP:
            return False
        if self.__dict__.get("_route_lease_lock") is None:
            return False
        policy = self._route_lease_policy()
        if not (policy.enabled and policy.early_release):
            return False
        if not self._route_lease_watcher_alive():
            # No watcher yet: never swallow the PASS. Passive failback runs
            # as before and the health monitor creates the watcher.
            self._route_lease_thread_wanted = True
            return False
        return True

    def _route_lease_on_user_intent(self, group: str | None, revision: int) -> None:
        """User intent on ``group`` ends its lease clock; others become orphans."""

        lock = self.__dict__.get("_route_lease_lock")
        if lock is None:
            return
        mono, _wall = self._route_lease_now()
        with lock:
            user_groups = self._route_lease_counters.setdefault("_user_groups", set())  # type: ignore[arg-type]
            if isinstance(user_groups, set) and len(user_groups) < 64:
                user_groups.add("*" if group is None else str(group))
            clocks = self._route_lease_clocks
            for key, clock in list(clocks.items()):
                if group is None or key == group:
                    if clock.live and clock.announced:
                        self._route_lease_queue_log(
                            "end",
                            self._route_lease_end_fields(clock, "user_intent", mono=mono),
                        )
                    clocks.pop(key, None)
                else:
                    clock.intent_rev = int(revision)
        self._route_lease_wake("user_intent")

    def _route_lease_restamp(self, revision: int) -> None:
        """A user-graph reload keeps the clocks (as orphans) under the new intent."""

        lock = self.__dict__.get("_route_lease_lock")
        if lock is None:
            return
        with lock:
            for clock in self._route_lease_clocks.values():
                clock.intent_rev = int(revision)
        self._route_lease_wake("reload")

    def _route_lease_reset_for_start(self) -> None:
        lock = self.__dict__.get("_route_lease_lock")
        if lock is None:
            return
        with lock:
            self._route_lease_clocks = {}
            self._route_lease_obs = {}
            self._route_lease_backoff = {}
            self._route_lease_winners = {}
            self._route_lease_counters = {}
            self._route_lease_log_queue = []
        # The previous runtime's watcher exits on its next wake.
        self._route_lease_wake("start")

    def _route_lease_has_work(self) -> bool:
        lock = self.__dict__.get("_route_lease_lock")
        if lock is None:
            return False
        lease = getattr(self, "_runtime_route_mutation_lease", None)
        if isinstance(lease, dict) and str(lease.get("mode") or "") == "fixed":
            return True
        with lock:
            return any(
                clock.live or clock.purge_pending or clock.verify_retry
                for clock in self._route_lease_clocks.values()
            )

    def _route_lease_ensure_thread(self) -> None:
        """Create the watcher (never from a locked route/recovery context)."""

        self._route_lease_thread_wanted = False
        if self.__dict__.get("_route_lease_lock") is None or not self._route_lease_active():
            return
        if self.stop_event.is_set():
            return
        generation = int(getattr(self, "_runtime_generation", 0) or 0)
        thread = self.__dict__.get("_route_lease_thread")
        if (
            thread is not None
            and thread.is_alive()
            and getattr(thread, "route_lease_generation", None) == generation
        ):
            return
        previous = self.__dict__.get("_route_lease_event")
        event = threading.Event()
        self._route_lease_event = event
        if previous is not None:
            previous.set()
        thread = threading.Thread(
            target=self._route_lease_watch_loop,
            args=(generation, event),
            name="runtime-route-lease",
            daemon=True,
        )
        thread.route_lease_generation = generation  # type: ignore[attr-defined]
        self._route_lease_thread = thread
        thread.start()

    def _route_lease_should_exit(self, generation: int, event: threading.Event) -> bool:
        return bool(
            self.stop_event.is_set()
            or int(getattr(self, "_runtime_generation", 0) or 0) != int(generation)
            or self.__dict__.get("_route_lease_event") is not event
        )

    def _route_lease_watch_loop(self, generation: int, event: threading.Event) -> None:
        active = False
        idle = 0
        reason = "exit"
        try:
            while True:
                if self._route_lease_should_exit(generation, event):
                    reason = "stop"
                    break
                if not self._route_lease_policy().enabled:
                    self._route_lease_disable_all("disabled")
                    reason = "disabled"
                    break
                if not active:
                    if not self._route_lease_has_work():
                        # Nothing leased: block with no timeout (no ticks, no reads).
                        event.wait()
                        event.clear()
                        continue
                    active = True
                    idle = 0
                    self._route_lease_log_watcher("active", "lease")
                policy = self._route_lease_policy()
                event.wait(float(policy.watch_interval_seconds))
                event.clear()
                if self._route_lease_should_exit(generation, event):
                    reason = "stop"
                    break
                try:
                    summary = self._route_lease_tick()
                except Exception:
                    summary = {"managed": 1}
                    log_raw_diagnostic(
                        self.logger,
                        "warning",
                        "Runtime route lease tick failed",
                        exc_info=True,
                    )
                if int(summary.get("managed", 0) or 0) <= 0:
                    idle += 1
                    if idle >= route_lease.IDLE_TICKS:
                        active = False
                        self._route_lease_log_watcher("idle", "nothing_managed")
                else:
                    idle = 0
        finally:
            if self.__dict__.get("_route_lease_thread") is threading.current_thread():
                self._route_lease_thread = None
            if active or reason == "disabled":
                self._route_lease_log_watcher("stopped", reason)

    def _route_lease_log_watcher(self, state: str, reason: str) -> None:
        lock = self.__dict__.get("_route_lease_lock")
        counters: dict[str, Any] = {}
        if lock is not None:
            with lock:
                counters = dict(self._route_lease_counters)
        self._route_lease_log(
            "watcher",
            [
                ("state", state),
                ("reason", reason),
                ("ticks", int(counters.get("ticks", 0) or 0)),
                ("reads", int(counters.get("reads", 0) or 0)),
                ("leases", int(counters.get("leases", 0) or 0)),
                ("unleased_reads", int(counters.get("unleased_reads", 0) or 0)),
            ],
        )

    def _route_lease_disable_all(self, cause: str) -> None:
        lock = self.__dict__.get("_route_lease_lock")
        if lock is None:
            return
        mono, _wall = self._route_lease_now()
        with lock:
            for clock in self._route_lease_clocks.values():
                if clock.live and clock.announced:
                    self._route_lease_queue_log(
                        "end", self._route_lease_end_fields(clock, cause, mono=mono)
                    )
            self._route_lease_clocks = {}
        self._route_lease_flush_logs()

    def _route_lease_ladder_in_flight(self) -> bool:
        """Track H: a tier-ladder judgement is in flight (``ladder_on`` only).

        No lock beyond the judge's own; never raises (False on any error).
        """

        try:
            if not self._node_judgement_policy().ladder_on:
                return False
            state = self.__dict__.get("_node_judgement_runtime_state")
            judge = getattr(state, "judge", None)
            in_flight = getattr(judge, "ladder_in_flight", None)
            return bool(callable(in_flight) and in_flight())
        except Exception:
            return False

    def _route_lease_fail_closed(self, lease: dict[str, Any] | None) -> bool:
        if isinstance(lease, dict) and str(lease.get("to") or "") == "REJECT":
            return True
        return getattr(self, "_runtime_confirmed_fail_closed_snapshot_key", None) is not None

    def _route_lease_busy(
        self,
        lease: dict[str, Any] | None,
        *,
        own_release: bool = False,
    ) -> RouteLeaseBusy:
        """Hard reasons always defer; soft ones only until due + 120 s."""

        hard = ""
        probe_keys: list[Any] = []
        lock = getattr(self, "_runtime_failure_monitor_lock", None)
        with lock if lock is not None else nullcontext():
            if getattr(self, "_runtime_failure_recovery_bindings", None):
                hard = "recovery_worker"
            elif isinstance(lease, dict) and not own_release:
                requests = getattr(self, "_runtime_passive_failback_requests", None) or {}
                if str(lease.get("release_state") or "") == "releasing" or any(
                    isinstance(value, dict)
                    and value.get("lease") is lease
                    and value.get("running")
                    for value in requests.values()
                ):
                    hard = "releasing"
            probe_keys = list(getattr(self, "_runtime_failure_probe_bindings", ()) or ())
        if not hard and self._route_lease_ladder_in_flight():
            # Tier ladder Track H (spec §5.2 L5): read after the monitor lock
            # is released; ``ladder_end`` wakes the watcher again.
            hard = "post_dial_ladder"
        if not hard:
            runner = getattr(self, "core_runner", None)
            try:
                core_up = bool(runner is not None and runner.is_running())
            except Exception:
                core_up = False
            if not core_up or getattr(self, "api_client", None) is None:
                hard = "core_down"
        if not hard:
            try:
                ready = bool(self._runtime_initial_activation_was_completed())
            except Exception:
                ready = False
            if not ready:
                hard = "not_ready"
        soft = ""
        if not hard:
            route_lock = getattr(self, "_runtime_route_snapshot_lock", None)
            with route_lock if route_lock is not None else nullcontext():
                snapshot = getattr(self, "_runtime_route_snapshot", None)
            keys = [key for key in probe_keys if isinstance(key, tuple) and len(key) >= 6]
            if keys and (
                snapshot is None
                or any(
                    key[:4] == tuple(snapshot.snapshot_key)[:4]
                    and key[5] == int(snapshot.network_context_epoch)
                    for key in keys
                )
            ):
                soft = "probe_binding"
            else:
                try:
                    if self._tier3_initial_activation_transaction_active():
                        soft = "activation"
                except Exception:
                    pass
        return RouteLeaseBusy(hard=hard, soft=soft)

    def _route_lease_collect(
        self,
        policy: RouteLeasePolicy,
        mono: float,
        lease_obj: dict[str, Any] | None,
        lease_copy: dict[str, Any] | None,
    ) -> list[tuple[RouteLeaseClock, str]]:
        """Link the lease dict to its clock and list what this tick manages."""

        items: list[tuple[RouteLeaseClock, str]] = []
        lease_group = ""
        lease_member = ""
        if (
            isinstance(lease_copy, dict)
            and str(lease_copy.get("mode") or "") == "fixed"
            and lease_copy.get("automatic") is not False
        ):
            lease_group = str(lease_copy.get("group") or "")
            lease_member = str(lease_copy.get("target_member") or lease_copy.get("to") or "")
        lock = self._route_lease_lock
        with lock:
            clocks = self._route_lease_clocks
            obs = self._route_lease_obs
            for clock in list(clocks.values()):
                old = clock.lease_obj
                if old is None or old is lease_obj:
                    continue
                clock.lease_obj = None
                if clock.ended:
                    continue
                same_member = lease_group == clock.group and lease_member == clock.member
                if same_member:
                    # A new incident's lease on the same member: the TTL
                    # continues; only the lease identity changes.
                    if clock.announced:
                        self._route_lease_queue_log(
                            "end", self._route_lease_end_fields(clock, "recovery_replaced", mono=mono)
                        )
                    clock.announced = False
                elif isinstance(old, dict) and str(old.get("release_state") or "") == "released":
                    # The existing passive failback released it (non-TIER3 group
                    # or early_release: false): nothing is left to manage.
                    if clock.announced:
                        self._route_lease_queue_log(
                            "end", self._route_lease_end_fields(clock, "released", mono=mono)
                        )
                    clock.ended = "released"
                    clock.ended_mono = mono
                else:
                    # The lease dict was cleared without a release (user intent
                    # on another group, a reload, recovery): keep the TTL and
                    # manage the pin as an orphan.  Its open span closes with
                    # the old id, so the orphan pending phase accrues nothing.
                    self._route_lease_queue_replaced_end(clock, "superseded", mono)
                    clock.defer_reason = ""
                    clock.announced = False
                    clock.orphan_since_mono = mono
            linked: RouteLeaseClock | None = None
            if lease_group and lease_member:
                clock = clocks.get(lease_group)
                carried = False
                if clock is not None and clock.ended:
                    if (
                        clock.member == lease_member
                        and clock.ended in route_lease.DEATH_END_CAUSES
                        and mono - float(clock.ended_mono) <= float(policy.death_carry_seconds)
                    ):
                        clock.ended = ""
                        clock.ended_by = ""
                        clock.purge_pending = False
                        clock.verify_retry = False
                        clock.last_decision_mono = mono
                        clock.last_decision_wall = self._route_lease_now()[1]
                        clock.announced = False
                        clock.attempts = 0
                        clock.next_attempt_mono = 0.0
                        carried = True
                    else:
                        clock = None
                if clock is None:
                    verified = float(lease_copy.get("verified_at_monotonic") or 0.0)
                    _now_mono, now_wall = self._route_lease_now()
                    started = verified if 0.0 < verified <= mono else mono
                    clock = RouteLeaseClock(
                        group=lease_group,
                        member=lease_member,
                        started_mono=started,
                        started_wall=now_wall - (mono - started),
                        last_decision_mono=started,
                        last_decision_wall=now_wall - (mono - started),
                        intent_rev=int(lease_copy.get("selector_intent_revision") or 0),
                        core_generation=int(getattr(self, "_core_generation", 0) or 0),
                        route_epoch=int(lease_copy.get("route_epoch") or 0),
                        origin="recovery",
                        last_put_mono=started,
                        inherited=True,
                    )
                    clocks[lease_group] = clock
                if carried:
                    clock.carried = True
                if clock.member == lease_member and clock.live:
                    linked = clock
                    clock.lease_obj = lease_obj
                    clock.orphan_since_mono = 0.0
                    if not clock.announced:
                        incident = str(lease_copy.get("incident_id") or "")
                        clock.lease_id = route_lease.lease_identifier(
                            incident or f"lease:{lease_group}:{lease_member}:{clock.started_mono}"
                        )
                        if lease_copy.get("provisional"):
                            clock.origin = "provisional"
                        elif lease_copy.get("startup_admission") or incident.startswith("initial-admission:"):
                            clock.origin = "initial"
                        clock.previous_member = str(
                            lease_copy.get("previous_member") or lease_copy.get("from") or ""
                        )
                        self._route_lease_announce(clock, policy, mono, obs.get(lease_group))
                    items.append((clock, "lease"))
            for clock in clocks.values():
                if clock is linked:
                    continue
                if clock.ended:
                    if clock.purge_pending or clock.verify_retry:
                        items.append((clock, "ended"))
                    continue
                if not clock.orphan_since_mono:
                    clock.orphan_since_mono = mono
                if mono - float(clock.orphan_since_mono) < route_lease.ORPHAN_ADOPT_S:
                    items.append((clock, "pending"))
                    continue
                if not clock.announced:
                    clock.origin = "orphan"
                    clock.lease_id = route_lease.lease_identifier(
                        f"orphan:{clock.group}{clock.member}{clock.started_mono}"
                    )
                    self._route_lease_announce(clock, policy, mono, obs.get(clock.group))
                items.append((clock, "orphan"))
        return items

    def _route_lease_announce(
        self,
        clock: RouteLeaseClock,
        policy: RouteLeasePolicy,
        mono: float,
        observation: Any,
    ) -> None:
        """Queue the start line and apply the incident-member backoff (leaf lock)."""

        clock.announced = True
        counters = self._route_lease_counters
        counters["leases"] = int(counters.get("leases", 0) or 0) + 1
        if not clock.backoff_checked:
            clock.backoff_checked = True
            previous = clock.previous_member
            winner_at = self._route_lease_winners.get(previous) if previous else None
            if winner_at is not None and mono - float(winner_at) < route_lease.BACKOFF_WINDOW_S:
                self._route_lease_backoff[previous] = int(self._route_lease_backoff.get(previous, 0) or 0) + 1
        index: Any = None
        if observation is not None:
            order = route_lease.contract_members(observation.members)
            if clock.member in order:
                index = order.index(clock.member)
        carried = bool(clock.carried)
        self._route_lease_queue_log(
            "start",
            [
                ("lease", clock.lease_id),
                ("group", clock.group),
                ("member", route_lease.TokenName(clock.member)),
                ("index", index),
                ("ttl_s", int(policy.ttl_seconds)),
                # 0 when this id starts already due (a carried clock).
                ("due_s", max(0.0, route_lease.due_time(clock, policy) - mono)),
                ("early", bool(policy.early_release and clock.group == route_lease.TIER3_GROUP)),
                ("stable_s", int(policy.stable_seconds)),
                ("backoff_s", int(self._route_lease_stable_required(policy, clock.previous_member))),
                ("origin", clock.origin),
                ("inherited", bool(clock.inherited)),
                ("carried_s", (mono - clock.started_mono) if carried else None),
                ("intent_rev", int(clock.intent_rev)),
                ("core_generation", int(clock.core_generation)),
                ("route_epoch", int(clock.route_epoch)),
            ],
        )
        # deferred_s is per lease id: deferral before this start line cannot
        # delay this id's release (due_s is measured from here), so a new id on
        # a carried clock (recovery_replaced, superseded -> orphan, death carry)
        # starts at 0; a still-open span begins again here.
        clock.deferred_s = 0.0
        if clock.defer_reason:
            clock.defer_started_mono = mono
            self._route_lease_queue_log(
                "deferred",
                [("lease", clock.lease_id), ("state", "begin"), ("reason", clock.defer_reason), ("deferred_s", 0.0)],
            )

    def _route_lease_stable_required(self, policy: RouteLeasePolicy, member: str) -> float:
        level = int((self.__dict__.get("_route_lease_backoff") or {}).get(member, 0) or 0)
        return route_lease.stable_requirement(policy, level)

    def _route_lease_tick(
        self,
        now_mono: float | None = None,
        now_wall: float | None = None,
    ) -> dict[str, Any]:
        """One watcher tick: at most one provider read, one mutation."""

        summary: dict[str, Any] = {"managed": 0, "reads": 0, "actions": []}
        lock = self.__dict__.get("_route_lease_lock")
        if lock is None:
            return summary
        policy = self._route_lease_policy()
        if not policy.enabled or not self._runtime_uses_early_single_coordinator():
            self._route_lease_disable_all("disabled")
            return summary
        mono, wall = self._route_lease_now()
        mono = float(mono if now_mono is None else now_mono)
        wall = float(wall if now_wall is None else now_wall)
        with self._runtime_failure_monitor_lock:
            lease = getattr(self, "_runtime_route_mutation_lease", None)
            lease_obj = lease if isinstance(lease, dict) else None
            lease_copy = dict(lease_obj) if lease_obj is not None else None
        items = self._route_lease_collect(policy, mono, lease_obj, lease_copy)
        with lock:
            counters = self._route_lease_counters
            counters["ticks"] = int(counters.get("ticks", 0) or 0) + 1
            observations = dict(self._route_lease_obs)
        self._route_lease_flush_logs()
        summary["managed"] = len(items)
        if not items:
            return summary
        busy = self._route_lease_busy(lease_obj)
        actionable = [item for item in items if item[1] in {"lease", "orphan", "ended"}]
        provider: dict[str, Any] | None = None
        read_wanted = any(
            clock.group == route_lease.TIER3_GROUP and role in {"lease", "orphan"}
            for clock, role in actionable
        )
        last_read = float(counters.get("last_read_mono", 0.0) or 0.0)
        if (
            read_wanted
            and not busy.hard
            and (not last_read or mono - last_read >= 0.9 * float(policy.watch_interval_seconds) or mono < last_read)
        ):
            client = getattr(self, "api_client", None)
            reader = getattr(client, "provider_proxies_one", None)
            if callable(reader):
                with lock:
                    counters["last_read_mono"] = mono
                    counters["reads"] = int(counters.get("reads", 0) or 0) + 1
                    for clock, role in actionable:
                        if clock.group == route_lease.TIER3_GROUP and role in {"lease", "orphan"}:
                            clock.reads += 1
                summary["reads"] = 1
                try:
                    value = reader(route_lease.TIER3_PROVIDER, timeout=route_lease.PROVIDER_READ_TIMEOUT_S)
                    provider = value if isinstance(value, dict) else None
                except Exception:
                    provider = None
                if provider is None:
                    for clock, role in actionable:
                        if clock.group == route_lease.TIER3_GROUP and role in {"lease", "orphan"}:
                            self._route_lease_skip(clock, "provider_read_failed")
        windows: dict[str, Any] = {}
        if provider is not None:
            try:
                from mihomo_api import recent_delay_windows

                windows = recent_delay_windows(str(getattr(getattr(self, "api_client", None), "base_url", "") or ""))
            except Exception:
                windows = {}
        try:
            from runtime_settings import route_health_check_url

            fallback_url = str(route_health_check_url(self.config) or "")
        except Exception:
            fallback_url = ""
        core_generation = int(getattr(self, "_core_generation", 0) or 0)
        orphan_blocked = bool(
            self._route_lease_fail_closed(lease_copy)
            or (
                isinstance(lease_copy, dict)
                and str(lease_copy.get("mode") or "selector") != "fixed"
                and not lease_copy.get("startup_admission")
            )
        )
        mutated = False
        for clock, role in actionable:
            observation = observations.get(clock.group)
            item_busy = busy
            if role == "orphan" and not busy.hard and orphan_blocked:
                item_busy = RouteLeaseBusy(hard="fail_closed")
            if role == "ended" and clock.verify_retry and not clock.purge_pending:
                if int(clock.core_generation) != core_generation:
                    # The Core was replaced: its own admission verifies it.
                    with lock:
                        clock.verify_retry = False
                    continue
                if busy.hard == "not_ready":
                    # The failed verification itself made egress pending;
                    # the one retry is what may restore it.
                    item_busy = RouteLeaseBusy()
            incident = clock.previous_member
            decision = route_lease.evaluate_route_lease(
                now_mono=mono,
                now_wall=wall,
                policy=policy,
                clock=clock,
                lease_route_epoch=(
                    int(lease_copy.get("route_epoch") or 0)
                    if role == "lease" and isinstance(lease_copy, dict)
                    else None
                ),
                observation=observation,
                provider=provider if clock.group == route_lease.TIER3_GROUP else None,
                test_url=(observation.test_url if observation is not None and observation.test_url else fallback_url),
                app_windows=windows,
                busy=item_busy,
                core_generation=core_generation,
                # Backoff belongs to the predicted winner W (per member).
                stable_required=lambda member, _policy=policy: self._route_lease_stable_required(_policy, member),
                incident_member=incident,
            )
            summary["actions"].append((clock.group, decision.action, decision.cause or decision.reason))
            if decision.action == "defer":
                self._route_lease_defer(clock, decision.reason, mono)
                continue
            self._route_lease_defer(clock, "", mono)
            if decision.action != "mismatch":
                clock.mismatch_seq = -1
            if decision.skipped:
                self._route_lease_skip(clock, decision.skipped)
            if decision.action == "mismatch":
                if clock.mismatch_seq < 0 and observation is not None:
                    clock.mismatch_seq = int(observation.seq)
                    clock.mismatch_mono = mono
                continue
            if decision.action == "end":
                self._route_lease_end(
                    clock,
                    decision.cause,
                    by="ghost",
                    purge=bool(decision.purge),
                    mono=mono,
                    clear_lease=(role == "lease"),
                )
                continue
            if decision.action not in {"release", "purge", "verify"} or mutated:
                continue
            if mono < float(clock.next_attempt_mono):
                continue
            mutated = True
            if decision.action == "purge":
                self._route_lease_purge(clock, mono)
            elif decision.action == "verify":
                self._route_lease_verify_retry(clock, mono)
            else:
                self._route_lease_release(
                    clock,
                    role,
                    lease_copy if role == "lease" else None,
                    decision,
                    policy,
                    mono,
                )
        if not read_wanted and summary["reads"]:
            with lock:
                counters["unleased_reads"] = int(counters.get("unleased_reads", 0) or 0) + 1
        self._route_lease_flush_logs()
        return summary

    def _route_lease_skip(self, clock: RouteLeaseClock, reason: str) -> None:
        if reason in clock.skipped:
            return
        clock.skipped.add(reason)
        self._route_lease_log("skipped", [("lease", clock.lease_id or "-"), ("reason", reason)])

    def _route_lease_defer(self, clock: RouteLeaseClock, reason: str, mono: float) -> None:
        """One line when a deferral span begins and one when it ends."""

        if reason and not clock.defer_reason:
            clock.defer_reason = reason
            clock.defer_started_mono = mono
            if clock.announced:
                self._route_lease_log(
                    "deferred",
                    [("lease", clock.lease_id or "-"), ("state", "begin"), ("reason", reason), ("deferred_s", float(clock.deferred_s))],
                )
        elif not reason and clock.defer_reason:
            span = max(0.0, mono - float(clock.defer_started_mono))
            clock.deferred_s += span
            previous = clock.defer_reason
            clock.defer_reason = ""
            if clock.announced:
                self._route_lease_log(
                    "deferred",
                    [("lease", clock.lease_id or "-"), ("state", "end"), ("reason", previous), ("deferred_s", float(clock.deferred_s))],
                )

    def _route_lease_end(
        self,
        clock: RouteLeaseClock,
        cause: str,
        *,
        by: str = "-",
        purge: bool = False,
        mono: float,
        clear_lease: bool = True,
    ) -> None:
        """End one lease locally (no controller call, no epoch bump)."""

        lease_obj = clock.lease_obj
        if clear_lease and lease_obj is not None:
            with self._runtime_failure_monitor_lock:
                if getattr(self, "_runtime_route_mutation_lease", None) is lease_obj:
                    lease_obj["release_state"] = "released" if cause == "released" else "ended"
                    self._runtime_route_mutation_lease = None
        if clock.defer_reason:
            self._route_lease_defer(clock, "", mono)
        with self._route_lease_lock:
            clock.ended = str(cause)
            clock.ended_by = str(by or "-")
            clock.ended_mono = float(mono)
            clock.purge_pending = bool(purge)
            clock.purge_attempts = 0
            clock.lease_obj = None
            clock.next_attempt_mono = 0.0
        if clock.announced:
            self._route_lease_log("end", self._route_lease_end_fields(clock, cause, by=by, mono=mono))

    def _route_lease_release_current(
        self,
        clock: RouteLeaseClock,
        lease_obj: dict[str, Any] | None,
        signature: Any,
        worker_token: tuple[int, ...],
    ) -> bool:
        if not self._runtime_worker_token_is_current(worker_token):
            return False
        with self._runtime_failure_monitor_lock:
            revision = int(getattr(self, "_runtime_selector_intent_revision", 0) or 0)
            current = getattr(self, "_runtime_route_mutation_lease", None)
            if lease_obj is not None:
                if current is not lease_obj:
                    return False
                if self._runtime_route_lease_cas_signature(current) != signature:
                    return False
                if int(lease_obj.get("selector_intent_revision", -1)) != revision:
                    return False
            else:
                if (
                    isinstance(current, dict)
                    and str(current.get("mode") or "") == "fixed"
                    and str(current.get("group") or "") == clock.group
                ):
                    return False
                if int(clock.intent_rev) != revision:
                    return False
        with self._route_lease_lock:
            return bool(self._route_lease_clocks.get(clock.group) is clock and clock.live)

    def _route_lease_release(
        self,
        clock: RouteLeaseClock,
        role: str,
        lease_copy: dict[str, Any] | None,
        decision: Any,
        policy: RouteLeasePolicy,
        mono: float,
    ) -> str:
        """DELETE the pick once (readback first); never re-pin, never prewarm."""

        lease_obj = clock.lease_obj if role == "lease" else None
        group = clock.group
        member = clock.member
        record: dict[str, Any] = (
            dict(lease_copy)
            if lease_obj is not None and isinstance(lease_copy, dict)
            else {"group": group, "target_member": member, "to": member}
        )
        record["mode"] = "fixed"
        record["group"] = group
        record["target_member"] = member
        signature = self._runtime_route_lease_cas_signature(lease_obj) if lease_obj is not None else None
        worker_token = self._runtime_worker_token()
        due = route_lease.due_time(clock, policy)
        clock.attempts += 1
        attempt = int(clock.attempts)
        result_name = "busy"
        deletes = 0
        verify = "skipped"
        unbound = False
        now_after = ""
        epoch_after = int(getattr(self, "_runtime_route_epoch", 0) or 0)
        deferred_reason = ""

        def current() -> bool:
            return self._route_lease_release_current(clock, lease_obj, signature, worker_token)

        def mutation_current() -> bool:
            if not current():
                return False
            busy = self._route_lease_busy(lease_obj, own_release=True)
            reason = busy.hard or (
                busy.soft if self._route_lease_now()[0] < due + route_lease.SOFT_DEFER_CAP_S else ""
            )
            if reason:
                raise RouteLeaseDeferred(reason)
            return True

        try:
            if not mutation_current():
                result_name = "superseded"
                return result_name
            snapshot = self._refresh_runtime_route_snapshot(timeout_seconds=0.35)
            _snapshot, payload = self._runtime_route_snapshot_state()
            if snapshot is None or not isinstance(payload, dict):
                result_name = "core_down"
                return result_name
            binding = self._runtime_route_binding_for_outbound(snapshot, payload, "FINAL-EXIT")
            if binding is None:
                if self._route_lease_fail_closed(lease_copy):
                    raise RouteLeaseDeferred("fail_closed")
                unbound = True
            deadline = self._runtime_recovery_now() + route_lease.RELEASE_BUDGET_S
            transaction = (
                self._runtime_egress_coordinator.core_mutation_transaction(
                    binding, expected_snapshot=snapshot, timeout_seconds=0.0
                )
                if binding is not None
                else nullcontext(True)
            )
            with transaction as mutation:
                if mutation is None:
                    deferred_reason = "busy"
                    result_name = "busy"
                    return result_name
                with self._bounded_core_transition(
                    time.monotonic() + route_lease.RELEASE_BUDGET_S,
                    "route lease release",
                ):
                    if not mutation_current():
                        result_name = "superseded"
                        return result_name
                    if lease_obj is not None:
                        lease_obj["release_state"] = "releasing"
                    try:
                        result = self._release_runtime_automatic_fixed_selection(
                            record,
                            deadline_monotonic=self._runtime_recovery_now() + route_lease.DELETE_BUDGET_S,
                            readback_first=True,
                            ownership_check=mutation_current,
                            before_release=None,
                        )
                    except BaseException:
                        if lease_obj is not None and lease_obj.get("release_state") == "releasing":
                            lease_obj["release_state"] = "pending"
                        raise
                    state = str(result.get("commit_state") or "unknown")
                    deletes = 1 if ("request" in result or "request_error" in result) else 0
                    epoch_after = int(getattr(self, "_runtime_route_epoch", 0) or 0)
                    if state == "committed" and deletes:
                        result_name = "committed"
                        promoted = None
                        promoted_payload: Any = None
                        try:
                            promoted = self._refresh_runtime_route_snapshot(timeout_seconds=0.35)
                            _promoted, promoted_payload = self._runtime_route_snapshot_state()
                        except Exception:
                            promoted = None
                        if promoted is not None:
                            group_state = promoted.group_state(group)
                            now_after = str(group_state.now or "") if group_state is not None else ""
                        verified: Any = None
                        winner_leaf = ""
                        if not unbound:
                            try:
                                if promoted is None or not isinstance(promoted_payload, dict):
                                    raise RuntimeControllerReadbackError("route lease release readback unavailable")
                                winner = self._runtime_route_binding_for_outbound(
                                    promoted, promoted_payload, "FINAL-EXIT"
                                )
                                if winner is None:
                                    raise RuntimeControllerReadbackError("route lease release route is not managed")
                                winner_leaf = winner.node.proxy_name
                                remaining = self._runtime_recovery_remaining(deadline)
                                if remaining < 0.2:
                                    raise TimeoutError("route lease verification budget exhausted")
                                verified = self._verify_runtime_final_exit(
                                    expected_worker_token=worker_token,
                                    expected_snapshot=promoted,
                                    timeout_seconds=remaining,
                                    recovery_deadline_monotonic=deadline,
                                )
                                verify = "ok"
                            except Exception:
                                verify = "failed"
                        # Mihomo no longer holds the pin: the lease ends either way.
                        with self._runtime_failure_monitor_lock:
                            if lease_obj is not None and getattr(self, "_runtime_route_mutation_lease", None) is lease_obj:
                                lease_obj["release_state"] = "released"
                                self._runtime_route_mutation_lease = None
                            if verify == "ok":
                                self._runtime_last_verified_route = {
                                    "incident_id": str(record.get("incident_id") or clock.lease_id),
                                    "leaf_proxy": winner_leaf,
                                    "verified_at_monotonic": self._runtime_recovery_now(),
                                    "result": verified,
                                }
                        clock.lease_obj = None
                        clock.last_verify = verify
                        if verify == "ok":
                            self._set_effective_egress_state(True, "")
                            self._try_arm_runtime_recovery()
                            publish = getattr(self, "_publish_verified_runtime_source_proof", None)
                            if callable(publish) and promoted is not None:
                                publish(expected_route_epoch=promoted.route_epoch)
                        elif verify == "failed":
                            self._set_effective_egress_state(
                                None,
                                "route lease release requires route verification",
                            )
                        with self._route_lease_lock:
                            if decision.cause in route_lease.LEASE_RELEASE_CAUSES and now_after:
                                self._route_lease_winners[now_after] = mono
                            clock.verify_retry = verify == "failed"
                            clock.core_generation = int(getattr(self, "_core_generation", 0) or 0)
                        return result_name
                    if state == "committed":
                        # Readback-first found the pick already gone: no DELETE.
                        result_name = "committed"
                        return result_name
                    if state == "superseded":
                        result_name = "superseded"
                        return result_name
                    result_name = "unknown" if state == "unknown" else "not_committed"
                    if lease_obj is not None:
                        lease_obj["release_state"] = (
                            "readback_pending" if state == "unknown" else "pending"
                        )
                    return result_name
        except RouteLeaseDeferred as exc:
            deferred_reason = exc.reason
            result_name = "busy"
            if lease_obj is not None and lease_obj.get("release_state") == "releasing":
                lease_obj["release_state"] = "pending"
            return result_name
        except TimeoutError:
            result_name = "timeout"
            if lease_obj is not None:
                lease_obj["release_state"] = "pending"
            return result_name
        except Exception:
            result_name = "not_committed"
            if lease_obj is not None and lease_obj.get("release_state") == "releasing":
                lease_obj["release_state"] = "pending"
            log_raw_diagnostic(self.logger, "debug", "Runtime route lease release failed", exc_info=True)
            return result_name
        finally:
            self._route_lease_release_finish(
                clock,
                decision,
                result_name=result_name,
                deletes=deletes,
                verify=verify,
                unbound=unbound,
                now_after=now_after,
                epoch_after=epoch_after,
                attempt=attempt,
                mono=mono,
                due=due,
                deferred_reason=deferred_reason,
            )
            try:
                self._queue_runtime_route_snapshot_refresh()
            except Exception:
                pass

    def _route_lease_release_finish(
        self,
        clock: RouteLeaseClock,
        decision: Any,
        *,
        result_name: str,
        deletes: int,
        verify: str,
        unbound: bool,
        now_after: str,
        epoch_after: int,
        attempt: int,
        mono: float,
        due: float,
        deferred_reason: str,
    ) -> None:
        cause = str(decision.cause or "")
        self._route_lease_log(
            "release",
            [
                ("lease", clock.lease_id or "-"),
                ("cause", cause),
                ("attempt", attempt),
                ("result", result_name),
                ("deletes", int(deletes)),
                ("age_s", max(0.0, mono - clock.started_mono)),
                ("due_s", due - mono),
                ("trigger", self._route_lease_tok(decision.trigger) if decision.trigger else None),
                ("trigger_index", decision.trigger_index),
                ("pinned_index", decision.pinned_index),
                ("predicted", self._route_lease_tok(decision.predicted) if decision.predicted else None),
                ("pass_age_s", decision.pass_age_s),
                ("stable_s", decision.stable_s),
                ("pass_app", decision.pass_app),
                ("higher_alive", int(decision.higher_alive)),
                ("now_after", self._route_lease_tok(now_after) if now_after else ("none" if result_name == "committed" and deletes else None)),
                ("verify", verify),
                ("unbound", bool(unbound)),
                ("route_epoch", int(epoch_after)),
            ],
            "warning" if result_name in {"unknown", "not_committed"} else "info",
        )
        if result_name == "committed":
            if deletes:
                self._route_lease_end(clock, "released", by=cause, purge=False, mono=mono, clear_lease=True)
            else:
                end_cause = "pinned_dead" if cause == "pinned_dead" else "core_cleared"
                self._route_lease_end(clock, end_cause, by=cause, purge=True, mono=mono, clear_lease=True)
            return
        if result_name == "superseded":
            # Another owner's pick or a newer lease: never DELETE it.
            clock.next_attempt_mono = mono + float(route_lease.SLOW_RETRY_S) if clock.attempts >= route_lease.FAST_ATTEMPTS else 0.0
            return
        if deferred_reason:
            self._route_lease_defer(clock, deferred_reason, mono)
        if result_name == "unknown":
            clock.next_attempt_mono = 0.0
        elif clock.attempts >= route_lease.FAST_ATTEMPTS:
            clock.next_attempt_mono = mono + float(route_lease.SLOW_RETRY_S)
        else:
            clock.next_attempt_mono = 0.0

    def _route_lease_purge(self, clock: RouteLeaseClock, mono: float) -> str:
        """Clear a Mihomo-dropped pick from cache.db (one DELETE, no epoch bump)."""

        clock.purge_attempts += 1
        attempt = int(clock.purge_attempts)
        result_name = "failed"
        try:
            client = self._require_api_client()
            snapshot, payload = self._runtime_route_snapshot_state()
            binding = (
                self._runtime_route_binding_for_outbound(snapshot, payload, "FINAL-EXIT")
                if snapshot is not None and isinstance(payload, dict)
                else None
            )
            transaction = (
                self._runtime_egress_coordinator.core_mutation_transaction(
                    binding, expected_snapshot=snapshot, timeout_seconds=0.0
                )
                if binding is not None
                else nullcontext(True)
            )
            with transaction as mutation:
                if mutation is not None:
                    with self._bounded_core_transition(
                        time.monotonic() + route_lease.PURGE_BUDGET_S,
                        "route lease purge",
                    ):
                        with self._route_lease_lock:
                            still_ours = bool(
                                self._route_lease_clocks.get(clock.group) is clock
                                and clock.ended
                                and clock.purge_pending
                            )
                        if not still_ours:
                            result_name = "skipped_fixed_set"
                        else:
                            value = client.proxy(clock.group, timeout=0.35)
                            if isinstance(value, dict) and "fixed" in value:
                                fixed = str(value.get("fixed") or "")
                                if fixed and fixed != clock.member:
                                    result_name = "skipped_fixed_set"
                                else:
                                    client.unfix_proxy(clock.group, timeout=0.35)
                                    result_name = "sent"
                                    counters = self._route_lease_counters
                                    counters["purges"] = int(counters.get("purges", 0) or 0) + 1
        except Exception:
            result_name = "failed"
        if result_name == "failed" and attempt >= route_lease.PURGE_MAX_ATTEMPTS:
            result_name = "gave_up"
        with self._route_lease_lock:
            if result_name != "failed":
                clock.purge_pending = False
            if result_name == "gave_up" and self._route_lease_clocks.get(clock.group) is clock:
                self._route_lease_clocks.pop(clock.group, None)
        self._route_lease_log(
            "purge",
            [
                ("lease", clock.lease_id or "-"),
                ("group", clock.group),
                ("result", result_name),
                ("attempt", attempt),
            ],
            "info",
        )
        return result_name

    def _route_lease_verify_retry(self, clock: RouteLeaseClock, mono: float) -> str:
        """The one verification retry after a release whose verify failed (no PUT)."""

        with self._route_lease_lock:
            clock.verify_retry = False
        verify = "failed"
        try:
            snapshot = self._refresh_runtime_route_snapshot(timeout_seconds=0.35)
            _snapshot, payload = self._runtime_route_snapshot_state()
            if snapshot is not None and isinstance(payload, dict):
                binding = self._runtime_route_binding_for_outbound(snapshot, payload, "FINAL-EXIT")
                if binding is not None:
                    deadline = self._runtime_recovery_now() + 3.0
                    self._verify_runtime_final_exit(
                        expected_worker_token=self._runtime_worker_token(),
                        expected_snapshot=snapshot,
                        timeout_seconds=3.0,
                        recovery_deadline_monotonic=deadline,
                    )
                    verify = "retry_ok"
                else:
                    verify = "skipped"
        except Exception:
            verify = "failed"
        if verify == "retry_ok":
            self._set_effective_egress_state(True, "")
            self._try_arm_runtime_recovery()
        else:
            self._queue_runtime_route_snapshot_refresh()
        clock.last_verify = verify
        self._route_lease_log(
            "release",
            [
                ("lease", clock.lease_id or "-"),
                ("cause", clock.ended_by or "-"),
                ("attempt", int(clock.attempts)),
                ("result", "committed"),
                ("deletes", 0),
                ("age_s", max(0.0, mono - clock.started_mono)),
                ("verify", verify),
                ("route_epoch", int(getattr(self, "_runtime_route_epoch", 0) or 0)),
            ],
        )
        return verify

    def _route_lease_release_for_shutdown(self, remaining_seconds: float) -> int:
        """Orderly exit: DELETE our own pins so cache.db never restores them."""

        deletes = 0
        try:
            self._route_lease_wake("stop")
            lock = self.__dict__.get("_route_lease_lock")
            if lock is None or not self._route_lease_active():
                return 0
            if float(remaining_seconds) < route_lease.SHUTDOWN_MIN_REMAINING_S:
                return 0
            runner = getattr(self, "core_runner", None)
            client = getattr(self, "api_client", None)
            if runner is None or client is None or not runner.is_running():
                return 0
            budget = min(
                route_lease.SHUTDOWN_BUDGET_S,
                float(remaining_seconds) - route_lease.SHUTDOWN_RESERVE_S,
            )
            if budget <= 0.0:
                return 0
            deadline = time.monotonic() + budget
            pid = runner.status().get("pid")
            with lock:
                targets = [
                    clock
                    for clock in self._route_lease_clocks.values()
                    if clock.live or clock.purge_pending
                ]
            if not targets:
                return 0
            transition_lock = self._core_transition_lock
            if not transition_lock.acquire(timeout=max(0.0, deadline - time.monotonic())):
                return 0
            try:
                for clock in targets:
                    remaining = deadline - time.monotonic()
                    if remaining <= 0.05:
                        break
                    with lock:
                        if self._route_lease_clocks.get(clock.group) is not clock:
                            continue
                    if runner.status().get("pid") != pid:
                        break
                    value = client.proxy(clock.group, timeout=min(0.35, remaining))
                    if not isinstance(value, dict) or "fixed" not in value:
                        continue
                    fixed = str(value.get("fixed") or "")
                    if (clock.live and fixed == clock.member) or (
                        clock.purge_pending and not fixed
                    ):
                        remaining = deadline - time.monotonic()
                        if remaining <= 0.02:
                            break
                        client.unfix_proxy(clock.group, timeout=min(0.35, remaining))
                        deletes += 1
                        if clock.live and clock.announced:
                            mono, _wall = self._route_lease_now()
                            clock.last_verify = "skipped"
                            self._route_lease_log(
                                "end",
                                self._route_lease_end_fields(clock, "shutdown", by="shutdown", mono=mono),
                            )
            finally:
                transition_lock.release()
        except Exception:
            pass
        return deletes

    def _restore_runtime_automatic_route(
        self,
        *,
        incident_binding: RuntimeRouteBinding,
        previous_binding: RuntimeRouteBinding | None,
        previous_payload: dict[str, Any],
        lease_record: dict[str, Any],
        incident_id: str,
        deadline_monotonic: float,
        expected_gateway_key: tuple[str, str, str, str] | None = None,
    ) -> tuple[CoreLoadedRouteSnapshot, dict[str, Any], RuntimeRouteBinding | None]:
        """Restore the incident-owned route after a failed promotion.

        Selector leases are restored along the previously loaded selector
        path. Fallback/URL-test leases must be explicitly fixed back to the
        last verified member because releasing their temporary fixed choice
        may immediately pick the just-recovered (but promotion-failing) leaf.
        """

        snapshot, snapshot_payload = self._runtime_route_snapshot_state()
        if snapshot is None or not isinstance(snapshot_payload, dict):
            raise RuntimeError("rollback route snapshot is unavailable")
        mode = str(lease_record.get("mode") or "selector")
        if mode == "fixed":
            group = str(lease_record.get("group") or "")
            target_member = str(
                lease_record.get("target_member")
                or lease_record.get("to")
                or ""
            )
            if not group or not target_member:
                raise RuntimeError("fixed rollback lease is incomplete")
            action = {
                "group": group,
                "target": target_member,
                "previous": "",
                "mode": "fixed",
                "alternative_leaf": str(lease_record.get("to") or ""),
            }
            self._prewarm_runtime_switch_target(
                snapshot,
                action,
                deadline_monotonic=deadline_monotonic,
            )
            self._apply_runtime_automatic_selection(
                action,
                deadline_monotonic=deadline_monotonic,
            )
        else:
            group = str(lease_record.get("group") or "")
            target_member = str(lease_record.get("target_member") or "")
            if group and target_member:
                self._apply_runtime_automatic_selection(
                    {
                        "group": group,
                        "target": target_member,
                        "previous": "",
                        "mode": "selector",
                        "alternative_leaf": str(
                            lease_record.get("to") or ""
                        ),
                    },
                    deadline_monotonic=deadline_monotonic,
                )
            elif previous_binding is None:
                raise RuntimeError("selector rollback has no verified binding")
            else:
                self._restore_runtime_selector_path(
                    previous_binding,
                    previous_payload,
                    incident_id=incident_id,
                    deadline_monotonic=deadline_monotonic,
                    current_snapshot_payload=snapshot_payload,
                )

        remaining = max(
            0.0,
            min(0.35, float(deadline_monotonic) - time.monotonic()),
        )
        if remaining <= 0.0:
            raise TimeoutError("rollback route readback deadline expired")
        refreshed = self._refresh_runtime_route_snapshot(timeout_seconds=remaining)
        _snapshot, refreshed_payload = self._runtime_route_snapshot_state()
        if refreshed is None or not isinstance(refreshed_payload, dict):
            raise RuntimeError("rollback route readback is unavailable")
        target_leaf = str(lease_record.get("to") or "")
        restored_route = inspect_runtime_route(
            refreshed_payload.get("proxies"),
            start=incident_binding.observed_outbound,
        )
        if (
            not target_leaf
            or str(restored_route.get("leaf_proxy") or "") != target_leaf
        ):
            raise RuntimeError("last verified incident route was not restored")
        final_binding = self._runtime_route_binding_for_outbound(
            refreshed,
            refreshed_payload,
            "FINAL-EXIT",
        )
        if expected_gateway_key is not None and (
            final_binding is None
            or tuple(final_binding.node.key) != tuple(expected_gateway_key)
        ):
            raise RuntimeError(
                "Gateway identity changed while restoring its underlay route"
            )
        return refreshed, refreshed_payload, final_binding

    def _fast_recover_confirmed_alternative(
        self,
        failure: BoundRuntimeFailure,
        snapshot: CoreLoadedRouteSnapshot,
        snapshot_payload: dict[str, Any],
        alternative: RuntimeNodeRef,
        *,
        incident_id: str,
        selector_intent_revision: int,
        deadline_monotonic: float,
        expected_worker_token: tuple[int, ...] | None = None,
        prewarmed_result: dict[str, Any] | None = None,
        prewarmed_evidence: _HotStandbyEvidence | None = None,
        on_selection_committed: Callable[[], None] | None = None,
        recovery_ticket: _RuntimeRecoveryTicket | None = None,
        required_successes: int = 1,
    ) -> dict[str, Any]:
        """Move new dials to one already-proven managed alternative."""

        expected_gateway_key: tuple[str, str, str, str] | None = None
        if "FINAL-EXIT" not in failure.binding.route_chain:
            # A Gateway-underlay incident is allowed to mutate only the
            # dialer-proxy group.  Bind the externally selected Gateway before
            # the write and prove the same identity after controller readback;
            # an arbitrary full-chain 204 through another Gateway is not a
            # valid recovery.
            gateway_binding = self._runtime_route_binding_for_outbound(
                snapshot,
                snapshot_payload,
                "FINAL-EXIT",
            )
            if (
                gateway_binding is None
                or gateway_binding.node.pool_kind != "gateway"
            ):
                return {
                    "fast_path_available": False,
                    "effective_egress_ok": False,
                    "reason": "Gateway underlay recovery lost its fixed Gateway binding",
                }
            expected_gateway_key = tuple(gateway_binding.node.key)

        action = self._runtime_alternative_switch_action(
            failure,
            alternative,
            snapshot_payload,
        )
        if action is None:
            return {
                "fast_path_available": False,
                "effective_egress_ok": False,
                "reason": "confirmed alternative has no loaded selectable parent",
            }
        exact_evidence = bool(
            prewarmed_evidence is not None
            and prewarmed_evidence.ref.key == alternative.key
            and prewarmed_evidence.snapshot_key == snapshot.snapshot_key
            and self._runtime_hot_standby_contract_matches(
                prewarmed_evidence,
                snapshot,
                action,
            )
        )
        if (
            recovery_ticket is not None
            and not self._runtime_recovery_ticket_is_current(
                recovery_ticket,
                require_open=True,
                deadline_monotonic=deadline_monotonic,
            )
        ):
            return {
                "fast_path_available": True,
                "stale": True,
                "effective_egress_ok": False,
                "reason": "runtime recovery ticket was superseded",
            }
        # ``prewarmed_result`` alone is intentionally insufficient: older
        # callers pass a node-default delay that does not populate the loaded
        # fallback group's URLTest state.  Keep the argument for compatibility,
        # but only an exact, snapshot-bound evidence record may reuse it.
        prewarm = (
            dict(prewarmed_result)
            if exact_evidence and isinstance(prewarmed_result, dict)
            else self._prewarm_runtime_switch_target(
                snapshot,
                action,
                deadline_monotonic=deadline_monotonic,
            )
        )
        hold_getter = (
            None
            if self._runtime_uses_early_single_coordinator()
            else getattr(self, "_runtime_facility_hold_reason", None)
        )

        def execution_is_current() -> bool:
            return bool(
                int(
                    getattr(self, "_runtime_selector_intent_revision", 0) or 0
                )
                == int(selector_intent_revision)
                and (
                    expected_worker_token is None
                    or self._runtime_worker_token_is_current(
                        expected_worker_token
                    )
                )
                and not (
                    callable(hold_getter)
                    and str(hold_getter() or "")
                )
                and (
                    recovery_ticket is None
                    or self._runtime_recovery_ticket_is_current(
                        recovery_ticket,
                        require_open=True,
                        deadline_monotonic=deadline_monotonic,
                    )
                )
            )

        if not execution_is_current():
            return {
                "fast_path_available": True,
                "stale": True,
                "effective_egress_ok": False,
                "reason": "user selector intent superseded runtime recovery",
            }
        # Linearize the bounded selector PUT/readback against terminal outcome
        # publication.  Without this lock, controller_hold could commit after
        # the open check but before PUT, allowing an already-terminal incident
        # to mutate the live route.  The controller transaction is capped at
        # 350 ms per phase and never acquires a runtime/Core lock itself.
        monitor_lock = getattr(self, "_runtime_failure_monitor_lock", None)

        def selection_authority_is_current_locked() -> bool:
            return bool(
                (
                    not isinstance(recovery_ticket, _RuntimeRecoveryTicket)
                    or (
                        monitor_lock is not None
                        and self._runtime_recovery_ticket_matches_locked(
                            recovery_ticket,
                            require_open=True,
                            deadline_monotonic=deadline_monotonic,
                        )
                    )
                )
                and int(
                    getattr(
                        self,
                        "_runtime_selector_intent_revision",
                        0,
                    )
                    or 0
                )
                == int(selector_intent_revision)
                and (
                    expected_worker_token is None
                    or self._runtime_worker_token_is_current(
                        expected_worker_token
                    )
                )
                and not (
                    callable(hold_getter) and str(hold_getter() or "")
                )
            )

        if isinstance(recovery_ticket, _RuntimeRecoveryTicket):
            if monitor_lock is None:
                selection_authority_current = False
            else:
                with monitor_lock:
                    selection_authority_current = (
                        selection_authority_is_current_locked()
                    )
                    if selection_authority_current:
                        selection = self._apply_runtime_automatic_selection(
                            action,
                            deadline_monotonic=deadline_monotonic,
                        )
        else:
            selection_authority_current = (
                selection_authority_is_current_locked()
            )
            if selection_authority_current:
                selection = self._apply_runtime_automatic_selection(
                    action,
                    deadline_monotonic=deadline_monotonic,
                )
        if not selection_authority_current:
            return {
                "fast_path_available": True,
                "stale": True,
                "effective_egress_ok": False,
                "reason": "runtime recovery lost selector authority",
            }
        if not execution_is_current():
            raise RuntimeError("runtime selection lost transaction authority")
        refresh_budget = self._runtime_recovery_remaining(
            deadline_monotonic,
            cap=0.35,
        )
        if refresh_budget <= 0.0:
            raise TimeoutError("runtime route readback deadline expired")
        refreshed = self._refresh_runtime_route_snapshot(
            timeout_seconds=refresh_budget
        )
        refreshed_snapshot, refreshed_payload = self._runtime_route_snapshot_state()
        if refreshed is None or not isinstance(refreshed_payload, dict):
            raise RuntimeError("runtime alternative selection could not be read back")
        group_state = refreshed.group_state(str(action.get("group") or ""))
        if group_state is None:
            # Older/fake controller payloads may omit the immutable group-state
            # projection even though the raw `/proxies` readback is complete.
            # The raw entry is still snapshot-owned and is therefore a valid
            # readback source; never infer selection from Manager state.
            raw_group = self._runtime_proxy_entries(refreshed_payload).get(
                str(action.get("group") or "")
            )
            selected_member = (
                str(raw_group.get("now") or "")
                if isinstance(raw_group, dict)
                else ""
            )
        else:
            selected_member = group_state.now
        target_member = str(action.get("target") or "")
        if selected_member != target_member:
            raise RuntimeError("runtime alternative group selection was not confirmed")
        if str(action.get("mode") or "") == "fixed":
            if group_state is not None:
                fixed_member = str(group_state.fixed or "")
            else:
                raw_group = self._runtime_proxy_entries(refreshed_payload).get(
                    str(action.get("group") or "")
                )
                fixed_member = (
                    str(raw_group.get("fixed") or "")
                    if isinstance(raw_group, dict) and "fixed" in raw_group
                    else ""
                )
            if fixed_member != target_member:
                raise RuntimeError(
                    "runtime fallback target was selected but not fixed"
                )
        if callable(on_selection_committed):
            on_selection_committed()
        selected_route = inspect_runtime_route(
            refreshed_payload.get("proxies"),
            start=failure.binding.observed_outbound,
        )
        if str(selected_route.get("leaf_proxy") or "") != alternative.proxy_name:
            raise RuntimeError("runtime alternative did not own the failed route domain")
        if not execution_is_current():
            raise RuntimeError("runtime alternative selection was superseded")
        if expected_gateway_key is not None:
            post_switch_gateway = self._runtime_route_binding_for_outbound(
                refreshed,
                refreshed_payload,
                "FINAL-EXIT",
            )
            if (
                post_switch_gateway is None
                or tuple(post_switch_gateway.node.key)
                != expected_gateway_key
            ):
                raise RuntimeError(
                    "Gateway identity changed during underlay diversion"
                )
        remaining_for_proof = self._runtime_recovery_remaining(
            deadline_monotonic
        )
        host_capture_reserve = (
            min(0.75, max(0.25, remaining_for_proof * 0.4))
            if self._runtime_uses_early_single_coordinator()
            and self._system_proxy_capture_proof_required()
            else 0.0
        )
        verify_seconds = min(
            1.5,
            max(0.0, remaining_for_proof - host_capture_reserve),
        )
        if verify_seconds <= 0.0:
            raise TimeoutError("runtime alternative 204 deadline expired")
        verify_kwargs: dict[str, Any] = {
            "expected_snapshot": refreshed,
            "timeout_seconds": verify_seconds,
            "required_successes": max(1, int(required_successes)),
        }
        if expected_worker_token is not None:
            verify_kwargs["expected_worker_token"] = expected_worker_token
        if isinstance(recovery_ticket, _RuntimeRecoveryTicket):
            verify_kwargs["recovery_ticket"] = recovery_ticket
            verify_kwargs["recovery_deadline_monotonic"] = (
                deadline_monotonic
            )
        verified = self._verify_runtime_final_exit(**verify_kwargs)
        if self._runtime_recovery_remaining(deadline_monotonic) <= 0.0:
            raise TimeoutError("runtime alternative 204 crossed its deadline")
        if not execution_is_current():
            raise RuntimeError("runtime alternative verification was superseded")
        host_capture_proof: dict[str, Any] = {
            "required": False,
            "verified": True,
        }
        if self._runtime_uses_early_single_coordinator():
            host_capture_proof = self._verify_system_proxy_host_capture(
                deadline_monotonic=deadline_monotonic,
                priority=ProbePriority.RUNTIME_MANUAL,
                recovery_ticket=recovery_ticket,
            )
            if not execution_is_current():
                raise RuntimeError(
                    "runtime host-capture verification was superseded"
                )
        final_route = inspect_runtime_route(
            refreshed_payload.get("proxies"),
            start="FINAL-EXIT",
        )
        return {
            "fast_path_available": True,
            "fast_runtime_switch": True,
            "effective_egress_ok": True,
            "post_switch_connectivity_verified": True,
            "post_switch_result": verified,
            "system_proxy_capture_proof": host_capture_proof,
            "selected_chain": list(final_route.get("selected_chain") or []),
            "leaf_proxy": str(final_route.get("leaf_proxy") or ""),
            "alternative_leaf": alternative.proxy_name,
            "selection_action": dict(action),
            "selection_result": selection,
            "prewarm_result": prewarm,
            "loaded_route_epoch": refreshed_snapshot.route_epoch
            if refreshed_snapshot is not None
            else 0,
            "incident_id": str(incident_id),
            "reason": "confirmed managed alternative restored FINAL-EXIT",
        }

    def _runtime_gateway_underlay_binding(
        self,
        snapshot: CoreLoadedRouteSnapshot,
        snapshot_payload: dict[str, Any],
        gateway_ref: RuntimeNodeRef,
    ) -> RuntimeRouteBinding | None:
        info = self._runtime_proxy_info_for_ref(snapshot_payload, gateway_ref)
        proxy = info.get("proxy") if isinstance(info, dict) else None
        dialer_proxy = (
            str(proxy.get("dialer-proxy") or "").strip()
            if isinstance(proxy, dict)
            else ""
        )
        if not dialer_proxy:
            return None
        return self._runtime_route_binding_for_outbound(
            snapshot,
            snapshot_payload,
            dialer_proxy,
            require_final_exit=False,
        )

    def _start_runtime_facility_confirmation(self, reason: str) -> None:
        """Confirm an unbound/controller signal through the neutral data plane."""

        worker_token = self._runtime_worker_token()
        with self._runtime_failure_monitor_lock:
            if worker_token in self._runtime_facility_confirmation_tokens:
                return
            self._runtime_facility_confirmation_tokens.add(worker_token)

        def worker() -> None:
            try:
                if not self._runtime_worker_token_is_current(worker_token):
                    return
                try:
                    self._probe_mihomo_mixed_port_once(timeout_seconds=1.5)
                except _RuntimeProbeBudgetUnavailable:
                    # Capacity saturation is not a failed neutral socket.
                    # Releasing this admission token lets the next bounded
                    # maintenance turn retry without opening a facility hold.
                    return
                except Exception as exc:
                    if self._runtime_worker_token_is_current(worker_token):
                        self._record_runtime_facility_degradation(
                            f"{reason}; neutral FINAL-EXIT confirmation failed: {exc}"
                        )
            finally:
                with self._runtime_failure_monitor_lock:
                    self._runtime_facility_confirmation_tokens.discard(
                        worker_token
                    )
                    self._runtime_failure_recovery_threads.discard(
                        threading.current_thread()
                    )

        thread = threading.Thread(
            target=worker,
            name="runtime-egress-facility-confirmation",
            daemon=True,
        )
        with self._runtime_failure_monitor_lock:
            self._runtime_failure_recovery_threads.add(thread)
        thread.start()

    def _record_runtime_facility_degradation(self, reason: str) -> dict[str, Any]:
        self._enter_runtime_facility_hold(
            reason,
            publish_readiness=False,
        )
        result = self._runtime_audit_base_result(
            reason=str(reason or "runtime egress facility degraded"),
            trigger="runtime_facility",
        )
        result.update(
            {
                "facility_failure": str(reason or "runtime egress facility degraded"),
                "failure_domain": "facility",
                "facility_hold": True,
                # A WAN/NIC/DNS/Core observation cannot prove that the
                # currently selected managed chain should be replaced. Keep
                # the physical route and all existing connections while its
                # network context is re-baselined.
                "effective_egress_ok": None,
            }
        )
        return self._set_runtime_audit_result(result, readiness_only=True)

    @staticmethod
    def _runtime_payload_has_reject_final_exit(payload: Any) -> bool:
        state = DesktopRuntime._mihomo_selected_routes_ready(payload)
        routes = state.get("routes") if isinstance(state, dict) else None
        final_route = (
            routes.get("FINAL-EXIT")
            if isinstance(routes, dict)
            else None
        )
        return bool(
            isinstance(final_route, dict)
            and str(final_route.get("terminal") or "") == "fail_closed"
            and str(final_route.get("leaf") or "").upper() == "REJECT"
        )

    @staticmethod
    def _runtime_physical_fail_closed_allowed(
        binding: RuntimeRouteBinding | None,
        *,
        gateway_failure_confirmed: bool,
    ) -> bool:
        """Reserve FINAL-EXIT=REJECT/Core-stop for a fixed Gateway body fault."""

        return bool(
            isinstance(binding, RuntimeRouteBinding)
            and binding.node.pool_kind == "gateway"
            and gateway_failure_confirmed
        )

    def _enforce_runtime_fail_closed(
        self,
        reason: str,
        *,
        failure_binding: RuntimeRouteBinding | None = None,
        gateway_failure_confirmed: bool = False,
        deadline_monotonic: float | None = None,
        expected_worker_token: tuple[int, ...] | None = None,
        expected_route_epoch: int | None = None,
        expected_selector_intent_revision: int | None = None,
        expected_facility_epoch: int | None = None,
    ) -> dict[str, Any]:
        """Physically close FINAL-EXIT, stopping Core if REJECT cannot be proven."""

        outcome: dict[str, Any] = {
            "attempted": True,
            "selected_reject": False,
            "route_verified": False,
            "core_stopped": False,
            "enforced": False,
            "reason": str(reason or "runtime egress failure"),
        }
        if not self._runtime_physical_fail_closed_allowed(
            failure_binding,
            gateway_failure_confirmed=gateway_failure_confirmed,
        ):
            outcome.update(
                {
                    "attempted": False,
                    "blocked": True,
                    "reason": (
                        "physical fail-closed is reserved for a confirmed "
                        "fixed Gateway failure"
                    ),
                }
            )
            return outcome

        def remaining(default_seconds: float) -> float:
            if deadline_monotonic is None:
                return max(0.05, float(default_seconds))
            return max(
                0.0,
                min(
                    float(default_seconds),
                    float(deadline_monotonic) - time.monotonic(),
                ),
            )

        with self._core_transition_lock:
            # An emergency action may wait behind a reload, selector write, or
            # Core lifecycle transition.  Revalidate the exact process and
            # route authority only after acquiring the shared Core lock; an
            # old incident must never close a replacement process or overwrite
            # a user's newer selector intent.
            with self._runtime_route_snapshot_lock:
                current_route_epoch = int(self._runtime_route_epoch)
            stale = bool(
                (
                    expected_worker_token is not None
                    and not self._runtime_worker_token_is_current(
                        expected_worker_token
                    )
                )
                or (
                    expected_route_epoch is not None
                    and current_route_epoch != int(expected_route_epoch)
                )
                or (
                    expected_selector_intent_revision is not None
                    and int(
                        getattr(
                            self,
                            "_runtime_selector_intent_revision",
                            0,
                        )
                        or 0
                    )
                    != int(expected_selector_intent_revision)
                )
                or (
                    expected_facility_epoch is not None
                    and int(
                        getattr(self, "_runtime_facility_epoch", 0) or 0
                    )
                    != int(expected_facility_epoch)
                )
            )
            if stale:
                outcome.update(
                    {
                        "attempted": False,
                        "stale": True,
                        "reason": (
                            "runtime fail-closed callback lost process or "
                            "route authority"
                        ),
                    }
                )
                return outcome

            killswitch_activated = bool(
                self._activate_killswitch_for_egress_failure(
                    str(reason or "FINAL-EXIT fail-closed")
                )
            )
            outcome["killswitch_activated"] = killswitch_activated
            runner = self.core_runner
            if runner is None or not runner.is_running():
                outcome["core_stopped"] = True
                outcome["enforced"] = killswitch_activated
                if outcome["enforced"]:
                    self._set_effective_egress_state(
                        False,
                        str(reason or "FINAL-EXIT is fail-closed"),
                    )
                return outcome

            selection_budget = remaining(0.35)
            if selection_budget > 0.0:
                try:
                    client = self._require_api_client()
                    select_with_readback = getattr(
                        client,
                        "select_proxy_with_readback",
                        None,
                    )
                    if callable(select_with_readback):
                        selection_value = select_with_readback(
                            "FINAL-EXIT",
                            "REJECT",
                            mode="selected",
                            timeout=selection_budget,
                            readback_timeout=remaining(0.35),
                        )
                        selection = (
                            asdict(selection_value)
                            if isinstance(
                                selection_value,
                                MihomoSelectionCommit,
                            )
                            else dict(selection_value)
                            if isinstance(selection_value, dict)
                            else {
                                "result": selection_value,
                                "commit_state": "unknown",
                            }
                        )
                    else:
                        try:
                            selection = client.select_proxy(
                                "FINAL-EXIT",
                                "REJECT",
                                timeout=selection_budget,
                            )
                        except TypeError:
                            # Test/integration clients may still implement the
                            # old two-argument surface.
                            selection = client.select_proxy(
                                "FINAL-EXIT",
                                "REJECT",
                            )
                    outcome["selection"] = selection
                    outcome["selected_reject"] = bool(
                        not isinstance(selection, dict)
                        or str(selection.get("commit_state") or "")
                        in {"", "committed"}
                    )
                    with self._runtime_route_snapshot_lock:
                        self._runtime_route_epoch += 1
                        self._node_judgement_arm_epoch("enforce_runtime_fail_closed")
                        self._mark_runtime_route_attribution_barrier_locked()
                        self._runtime_route_snapshot = None
                        self._runtime_route_snapshot_payload = None
                        self._runtime_core_inventory_snapshot = None
                        self._runtime_route_selection_signature = ()
                    self._runtime_egress_coordinator.set_current_snapshot(None)
                    snapshot = self._refresh_runtime_route_snapshot(
                        timeout_seconds=remaining(0.35)
                    )
                    _current, payload = self._runtime_route_snapshot_state()
                    controller_payload = (
                        payload.get("proxies")
                        if isinstance(payload, dict)
                        else None
                    )
                    if (
                        snapshot is not None
                        and self._runtime_payload_has_reject_final_exit(
                            controller_payload
                        )
                    ):
                        with self._runtime_route_snapshot_lock:
                            self._runtime_confirmed_fail_closed_snapshot_key = (
                                tuple(snapshot.snapshot_key)
                            )
                        outcome["route_verified"] = True
                        outcome["enforced"] = True
                        self._set_effective_egress_state(
                            False,
                            str(reason or "FINAL-EXIT selected REJECT"),
                        )
                        return outcome
                    outcome["selection_error"] = (
                        "FINAL-EXIT REJECT selection was not confirmed by the "
                        "Core-loaded route snapshot"
                    )
                except Exception as exc:
                    outcome["selection_error"] = str(exc)
            else:
                outcome["selection_error"] = (
                    "runtime recovery deadline expired before REJECT selection"
                )

            # Controller selection is not a fail-closed proof. If it cannot be
            # read back from the same Core-loaded route authority, stop Mihomo;
            # the system proxy/capture remains pointed at the closed local path
            # and must never be restored to DIRECT here.
            try:
                stop_result = self.stop_core(
                    actor="runtime_egress_coordinator",
                    reason=str(reason or "FINAL-EXIT emergency fail-closed"),
                    timeout=remaining(1.0),
                )
                outcome["stop"] = stop_result
            except Exception as exc:
                outcome["stop_error"] = str(exc)
            try:
                runner = self.core_runner
                outcome["core_stopped"] = bool(
                    runner is None or not runner.is_running()
                )
            except Exception:
                outcome["core_stopped"] = False
            outcome["enforced"] = bool(
                outcome["core_stopped"] and killswitch_activated
            )
            if outcome["enforced"]:
                self._set_effective_egress_state(
                    False,
                    str(reason or "Mihomo Core was stopped fail-closed"),
                )
            return outcome

    def _commit_runtime_fail_closed_outcome(
        self,
        *,
        physical: dict[str, Any],
        incident_id: str,
        from_proxy: str,
        selector_intent_revision: int,
        expected_ticket: _RuntimeRecoveryTicket | None = None,
    ) -> str:
        """Record physical REJECT or Core-stop truth without conflating them."""

        incident_id = str(incident_id or "")
        if not incident_id:
            return "indeterminate"
        if (
            not isinstance(expected_ticket, _RuntimeRecoveryTicket)
            or expected_ticket.from_ref.pool_kind != "gateway"
        ):
            return "indeterminate"
        with self._runtime_failure_monitor_lock:
            recovery_state = getattr(
                self,
                "_runtime_incident_recovery_state",
                None,
            )
            if not isinstance(recovery_state, dict):
                recovery_state = {}
                self._runtime_incident_recovery_state = recovery_state
            owners = getattr(
                self,
                "_runtime_core_stopped_recovery_owners",
                None,
            )
            if not isinstance(owners, dict):
                owners = {}
                self._runtime_core_stopped_recovery_owners = owners
            if int(
                getattr(self, "_runtime_selector_intent_revision", 0) or 0
            ) != int(selector_intent_revision):
                return "superseded"
            if isinstance(expected_ticket, _RuntimeRecoveryTicket):
                tickets = getattr(self, "_runtime_recovery_tickets", {})
                current_ticket = (
                    tickets.get(incident_id)
                    if isinstance(tickets, dict)
                    else None
                )
                if not (
                    isinstance(current_ticket, _RuntimeRecoveryTicket)
                    and current_ticket.generation
                    == expected_ticket.generation
                ):
                    return "superseded"
                outcomes = getattr(self, "_runtime_recovery_outcomes", {})
                if isinstance(outcomes, dict) and isinstance(
                    outcomes.get(incident_id),
                    RuntimeRecoveryOutcome,
                ):
                    return "superseded"
            committed_at = self._runtime_recovery_now()
            if bool(physical.get("route_verified")):
                with self._runtime_route_snapshot_lock:
                    route_epoch = int(
                        getattr(self, "_runtime_route_epoch", 0) or 0
                    )
                self._runtime_route_mutation_lease = {
                    "group": "FINAL-EXIT",
                    "from": str(from_proxy or ""),
                    "to": "REJECT",
                    "target_member": "REJECT",
                    "mode": "selector",
                    "incident_id": incident_id,
                    "route_epoch": route_epoch,
                    "selector_intent_revision": int(
                        selector_intent_revision
                    ),
                    "recovery_ticket_generation": int(
                        expected_ticket.generation
                        if isinstance(expected_ticket, _RuntimeRecoveryTicket)
                        else 0
                    ),
                    "verified_at_monotonic": committed_at,
                    "provisional": False,
                }
                owners.pop(incident_id, None)
                recovery_state[incident_id] = "ready"
                disposition = "route_verified"
            elif bool(physical.get("enforced")) and bool(
                physical.get("core_stopped")
            ):
                self._runtime_route_mutation_lease = None
                owners[incident_id] = {
                    "incident_id": incident_id,
                    "from": str(from_proxy or ""),
                    "selector_intent_revision": int(
                        selector_intent_revision
                    ),
                    "recovery_ticket_generation": int(
                        expected_ticket.generation
                        if isinstance(expected_ticket, _RuntimeRecoveryTicket)
                        else 0
                    ),
                    "fail_closed_at_monotonic": committed_at,
                }
                recovery_state[incident_id] = "core_stopped_fail_closed"
                disposition = "core_stopped"
            else:
                self._runtime_route_mutation_lease = None
                owners.pop(incident_id, None)
                recovery_state[incident_id] = "indeterminate"
                disposition = "indeterminate"
        self._invalidate_exit_route_context()
        if disposition in {"route_verified", "core_stopped"}:
            self._complete_runtime_recovery_outcome(
                incident_id,
                RuntimeRecoveryStatus.FAIL_CLOSED,
                reason_code=(
                    "verified_reject"
                    if disposition == "route_verified"
                    else "verified_core_stop"
                ),
                expected_ticket=expected_ticket,
                facts={
                    "put": disposition == "route_verified",
                    "readback": disposition == "route_verified",
                    "final_204": False,
                },
            )
        return disposition

    def _start_runtime_facility_fail_closed(self, reason: str) -> None:
        worker_token = self._runtime_worker_token()
        with self._runtime_route_snapshot_lock:
            route_epoch = int(self._runtime_route_epoch)
        selector_intent_revision = int(
            getattr(self, "_runtime_selector_intent_revision", 0) or 0
        )
        with self._runtime_failure_monitor_lock:
            # Keep the newest generation in a one-slot mailbox.  A bool-only
            # coalescer can drop a new Core's facility incident while an old,
            # now-stale worker is still queued behind the Core lock.
            self._runtime_facility_fail_closed_pending = {
                "reason": str(reason or ""),
                "worker_token": worker_token,
                "route_epoch": route_epoch,
                "selector_intent_revision": selector_intent_revision,
            }
            if self._runtime_facility_fail_closed_running:
                return
            self._runtime_facility_fail_closed_running = True

        def worker() -> None:
            normal_exit = False
            try:
                while True:
                    with self._runtime_failure_monitor_lock:
                        pending = self._runtime_facility_fail_closed_pending
                        self._runtime_facility_fail_closed_pending = None
                    if isinstance(pending, dict):
                        pending_reason = str(pending.get("reason") or "")
                        physical = self._enforce_runtime_fail_closed(
                            pending_reason,
                            expected_worker_token=tuple(
                                pending.get("worker_token") or ()
                            ),
                            expected_route_epoch=int(
                                pending.get("route_epoch") or 0
                            ),
                            expected_selector_intent_revision=int(
                                pending.get("selector_intent_revision") or 0
                            ),
                        )
                        if not physical.get("stale"):
                            current = (
                                dict(self.last_runtime_route_audit)
                                if isinstance(self.last_runtime_route_audit, dict)
                                else self._runtime_audit_base_result(
                                    reason=(
                                        pending_reason
                                        or "runtime facility failure"
                                    ),
                                    trigger="runtime_facility",
                                )
                            )
                            current["fail_closed_apply"] = physical
                            current["fail_closed_terminal"] = bool(
                                physical.get("enforced")
                            )
                            self._set_runtime_audit_result(current)
                    with self._runtime_failure_monitor_lock:
                        if self._runtime_facility_fail_closed_pending is None:
                            self._runtime_facility_fail_closed_running = False
                            self._runtime_failure_recovery_threads.discard(
                                threading.current_thread()
                            )
                            normal_exit = True
                            return
            finally:
                if normal_exit:
                    return
                replacement: threading.Thread | None = None
                with self._runtime_failure_monitor_lock:
                    self._runtime_failure_recovery_threads.discard(
                        threading.current_thread()
                    )
                    if self._runtime_facility_fail_closed_pending is None:
                        self._runtime_facility_fail_closed_running = False
                    else:
                        # Preserve the already captured newest-generation
                        # mailbox item.  Mark the replacement active under the
                        # same lock so a concurrent submitter can only replace
                        # that item, never create a second owner.
                        self._runtime_facility_fail_closed_running = True
                        replacement = threading.Thread(
                            target=worker,
                            name="runtime-egress-facility-fail-closed",
                            daemon=True,
                        )
                        self._runtime_failure_recovery_threads.add(replacement)
                if replacement is not None:
                    replacement.start()

        thread = threading.Thread(
            target=worker,
            name="runtime-egress-facility-fail-closed",
            daemon=True,
        )
        with self._runtime_failure_monitor_lock:
            self._runtime_failure_recovery_threads.add(thread)
        thread.start()

    def _runtime_origin_diagnostic_binding_for_probe(
        self,
        failure: BoundRuntimeFailure,
        snapshot: CoreLoadedRouteSnapshot,
        *,
        incident_id: str,
        probe_token: str,
        worker_token: tuple[int, ...],
    ) -> OriginDiagnosticBinding | None:
        """Return a still-owned origin after our own provisional route move.

        The route epoch is expected to change when new dials are diverted.  An
        origin result is nevertheless authoritative when the Core process,
        semantic graph, network context, probe token and user intent all still
        match the immutable pre-diversion binding.
        """

        if not incident_id or not probe_token:
            return None
        if not self._runtime_worker_token_is_current(worker_token):
            return None
        with self._runtime_failure_monitor_lock:
            record = getattr(
                self,
                "_runtime_origin_diagnostic_bindings",
                {},
            ).get(str(incident_id))
            if not isinstance(record, OriginDiagnosticBinding):
                return None
            if (
                record.binding.circuit_key != failure.binding.circuit_key
                or record.snapshot_key != snapshot.snapshot_key
                or record.owner_token != str(probe_token)
                or record.expires_at_monotonic <= time.monotonic()
                or record.selector_intent_revision
                != int(getattr(self, "_runtime_selector_intent_revision", 0) or 0)
                or record.binding.network_context_epoch
                != int(getattr(self, "_runtime_network_context_epoch", 0) or 0)
            ):
                return None
            lease = getattr(self, "_runtime_route_mutation_lease", None)
            if not (
                isinstance(lease, dict)
                and str(lease.get("incident_id") or "") == str(incident_id)
                and str(lease.get("owner_token") or "") == str(probe_token)
                and str(lease.get("from") or "")
                == failure.binding.node.proxy_name
                and str(lease.get("to") or "")
                and str(lease.get("to") or "")
                != failure.binding.node.proxy_name
                and float(lease.get("verified_at_monotonic") or 0.0) > 0.0
                and (
                    not record.target_proxy
                    or record.target_proxy == str(lease.get("to") or "")
                )
                and (
                    record.committed_route_epoch <= 0
                    or record.committed_route_epoch
                    == int(lease.get("route_epoch") or 0)
                )
            ):
                return None
            return record

    def _rollback_runtime_provisional_selection(
        self,
        action: dict[str, Any],
        *,
        worker_token: tuple[int, ...],
        selector_intent_revision: int,
        timeout_seconds: float = 1.0,
        deadline_monotonic: float | None = None,
    ) -> tuple[RuntimeRouteBinding | None, str]:
        """Best-effort rollback for an unverified provisional selector write.

        Controller timeouts are three-state outcomes: they do not prove that
        the PUT committed, nor that it did not.  We therefore perform one
        inverse mutation and one readback, never retry blindly, and classify a
        missing binding as ``unknown`` rather than converting it to REJECT.
        """

        if (
            not self._runtime_worker_token_is_current(worker_token)
            or int(getattr(self, "_runtime_selector_intent_revision", 0) or 0)
            != int(selector_intent_revision)
        ):
            return None, "superseded"
        deadline = (
            float(deadline_monotonic)
            if deadline_monotonic is not None
            else self._runtime_recovery_now() + max(0.2, float(timeout_seconds))
        )
        if self._runtime_recovery_remaining(deadline) <= 0.0:
            return None, "unknown"
        outcome = "unknown"
        try:
            with self._core_transition_lock:
                if (
                    not self._runtime_worker_token_is_current(worker_token)
                    or int(
                        getattr(self, "_runtime_selector_intent_revision", 0) or 0
                    )
                    != int(selector_intent_revision)
                ):
                    return None, "superseded"
                mode = str(action.get("mode") or "selector")
                if mode == "fixed":
                    released = self._release_runtime_automatic_fixed_selection(
                        {
                            "mode": "fixed",
                            "group": str(action.get("group") or ""),
                        },
                        deadline_monotonic=deadline,
                    )
                    outcome = str(released.get("commit_state") or "unknown")
                else:
                    previous = str(action.get("previous") or "")
                    if not previous:
                        return None, "unknown"
                    self._apply_runtime_automatic_selection(
                        {
                            "group": str(action.get("group") or ""),
                            "target": previous,
                            "previous": str(action.get("target") or ""),
                            "mode": "selector",
                            "alternative_leaf": previous,
                        },
                        deadline_monotonic=deadline,
                    )
                    outcome = "committed"
                remaining = self._runtime_recovery_remaining(deadline, cap=0.35)
                if remaining <= 0.0:
                    return None, "unknown"
                self._refresh_runtime_route_snapshot(timeout_seconds=remaining)
        except Exception:
            self._queue_runtime_route_snapshot_refresh()
            return None, "unknown"
        readback_remaining = self._runtime_recovery_remaining(deadline, cap=0.25)
        if readback_remaining <= 0.0:
            return None, "unknown"
        state = self._current_runtime_failure_binding_state(
            timeout_seconds=readback_remaining,
        )
        if state is None:
            self._queue_runtime_route_snapshot_refresh()
            return None, "unknown"
        return state[0], outcome

    @staticmethod
    def _runtime_route_lease_cas_signature(
        lease: dict[str, Any] | None,
    ) -> tuple[Any, ...] | None:
        if not isinstance(lease, dict):
            return None
        return (
            str(lease.get("incident_id") or ""),
            str(lease.get("owner_token") or ""),
            str(lease.get("from") or ""),
            str(lease.get("to") or ""),
            int(lease.get("route_epoch") or 0),
            int(lease.get("selector_intent_revision") or 0),
            int(lease.get("recovery_ticket_generation") or 0),
            float(lease.get("verified_at_monotonic") or 0.0),
        )

    def _runtime_successor_parent_lease_locked(
        self,
        failure: BoundRuntimeFailure,
        *,
        selector_intent_revision: int,
    ) -> dict[str, Any] | None:
        """Return the verified automatic A->B lease eligible for B->C CAS."""

        lease = getattr(self, "_runtime_route_mutation_lease", None)
        if not isinstance(lease, dict):
            return None
        if (
            lease.get("automatic") is False
            or not str(lease.get("incident_id") or "")
            or str(lease.get("to") or "")
            != failure.binding.node.proxy_name
            or float(lease.get("verified_at_monotonic") or 0.0) <= 0.0
            or int(lease.get("route_epoch") or -1)
            != int(failure.binding.route_epoch)
            or int(lease.get("selector_intent_revision") or -1)
            != int(selector_intent_revision)
        ):
            return None
        return dict(lease)

    def _runtime_commit_successor_lease_locked(
        self,
        new_lease: dict[str, Any],
        parent_lease: dict[str, Any] | None,
    ) -> bool:
        current = getattr(self, "_runtime_route_mutation_lease", None)
        if parent_lease is None:
            if isinstance(current, dict):
                return False
        elif self._runtime_route_lease_cas_signature(current) != (
            self._runtime_route_lease_cas_signature(parent_lease)
        ):
            return False
        if parent_lease is not None:
            parent_incident = str(parent_lease.get("incident_id") or "")
            new_lease["parent_incident_id"] = parent_incident
            if parent_incident:
                self._runtime_incident_recovery_state[parent_incident] = (
                    "route_superseded"
                )
                self._runtime_pending_confirmed_incidents.pop(
                    parent_incident,
                    None,
                )
                self._runtime_pending_recovered_payloads.pop(
                    parent_incident,
                    None,
                )
                self._runtime_origin_diagnostic_bindings.pop(
                    parent_incident,
                    None,
                )
                getattr(
                    self,
                    "_runtime_deferred_provisional_confirmations",
                    {},
                ).pop(parent_incident, None)
        new_lease["automatic"] = True
        self._runtime_route_mutation_lease = new_lease
        return True

    def _start_runtime_provisional_diversion(
        self,
        failure: BoundRuntimeFailure,
        snapshot: CoreLoadedRouteSnapshot,
        snapshot_payload: dict[str, Any],
        *,
        incident_id: str,
        probe_token: str,
        evidence: _HotStandbyEvidence,
    ) -> bool:
        """Move only future dials while the failed origin is confirmed.

        No Manager health observation is emitted here.  The exact origin
        remains diagnosable through ``OriginDiagnosticBinding`` after the
        selector changes, while established connections are left untouched.
        """

        incident_id = str(incident_id or "").strip()
        probe_token = str(probe_token or "").strip()
        if (
            not incident_id
            or not probe_token
            or failure.binding.node.pool_kind == "gateway"
            or bool(self._runtime_facility_hold_reason())
            or evidence.snapshot_key != snapshot.snapshot_key
            or evidence.network_context_epoch
            != int(getattr(self, "_runtime_network_context_epoch", 0) or 0)
            or self._runtime_recovery_now() - evidence.verified_at_monotonic > 45.0
        ):
            return False
        recovery_ticket = self._ensure_runtime_recovery_ticket(
            failure,
            snapshot,
            incident_id,
        )
        if not isinstance(recovery_ticket, _RuntimeRecoveryTicket):
            return False
        action = self._runtime_alternative_switch_action(
            failure,
            evidence.ref,
            snapshot_payload,
        )
        if action is None or not self._runtime_hot_standby_contract_matches(
            evidence,
            snapshot,
            action,
        ):
            return False
        key = ("provisional", *failure.circuit_key)
        worker_token = self._runtime_worker_token()
        facility_epoch = int(
            getattr(self, "_runtime_facility_epoch", 0) or 0
        )
        selector_intent_revision = int(
            getattr(self, "_runtime_selector_intent_revision", 0) or 0
        )
        parent_lease: dict[str, Any] | None = None
        with self._runtime_failure_monitor_lock:
            current_lease = getattr(self, "_runtime_route_mutation_lease", None)
            if isinstance(current_lease, dict):
                parent_lease = self._runtime_successor_parent_lease_locked(
                    failure,
                    selector_intent_revision=selector_intent_revision,
                )
            if (
                key in self._runtime_failure_recovery_bindings
                or failure.circuit_key
                in getattr(self, "_runtime_failure_probe_bindings", set())
                or (
                    isinstance(current_lease, dict)
                    and parent_lease is None
                )
                or bool(self._runtime_facility_hold_reason())
                or int(getattr(self, "_runtime_facility_epoch", 0) or 0)
                != facility_epoch
            ):
                return False
            self._runtime_failure_recovery_bindings.add(key)

        def worker() -> None:
            mutation = None
            recovery_lease: RuntimeRecoveryLease | None = None
            route_changed_without_verification = False
            # Hot evidence has one two-second budget measured from the failed
            # execution binding. It covers PUT, authoritative readbacks,
            # route-epoch publication and the complete FINAL-EXIT 204; worker
            # scheduling never grants a fresh allowance.
            deadline = min(
                float(failure.observed_at_monotonic) + 2.0,
                recovery_ticket.deadline_monotonic,
            )
            try:
                if not self._runtime_recovery_ticket_is_current(
                    recovery_ticket,
                    require_open=True,
                    deadline_monotonic=deadline,
                ):
                    return
                if (
                    not self._runtime_worker_token_is_current(worker_token)
                    or bool(self._runtime_facility_hold_reason())
                    or int(getattr(self, "_runtime_facility_epoch", 0) or 0)
                    != facility_epoch
                    or int(
                        getattr(self, "_runtime_selector_intent_revision", 0) or 0
                    )
                    != selector_intent_revision
                    or not self._runtime_egress_coordinator.snapshot_ownership_matches(
                        failure.binding,
                        expected_snapshot=snapshot,
                    )
                ):
                    return
                reload_gate = getattr(self, "_runtime_reload_gate", None)
                if reload_gate is not None:
                    recovery_lease = reload_gate.begin_recovery(
                        f"runtime-egress:{incident_id}"
                    )
                    if recovery_lease is None:
                        return
                if not self._runtime_recovery_ticket_is_current(
                    recovery_ticket,
                    require_open=True,
                    deadline_monotonic=deadline,
                ):
                    return
                mutation = self._runtime_egress_coordinator.begin_core_mutation(
                    failure.binding,
                    expected_snapshot=snapshot,
                    timeout_seconds=max(
                        0.0,
                        min(0.2, deadline - self._runtime_recovery_now()),
                    ),
                )
                if mutation is None:
                    return
                if not self._runtime_recovery_ticket_is_current(
                    recovery_ticket,
                    require_open=True,
                    deadline_monotonic=deadline,
                ):
                    return
                with self._core_transition_lock:
                    if (
                        not self._runtime_worker_token_is_current(worker_token)
                        or bool(self._runtime_facility_hold_reason())
                        or int(
                            getattr(self, "_runtime_facility_epoch", 0) or 0
                        )
                        != facility_epoch
                        or int(
                            getattr(
                                self,
                                "_runtime_selector_intent_revision",
                                0,
                            )
                            or 0
                        )
                        != selector_intent_revision
                        or not self._runtime_egress_coordinator.core_mutation_lease_is_current(
                            mutation
                        )
                        or not self._runtime_recovery_ticket_is_current(
                            recovery_ticket,
                            require_open=True,
                            deadline_monotonic=deadline,
                        )
                    ):
                        return
                    def mark_selection_committed() -> None:
                        nonlocal route_changed_without_verification
                        route_changed_without_verification = True

                    audit = self._fast_recover_confirmed_alternative(
                        failure,
                        snapshot,
                        snapshot_payload,
                        evidence.ref,
                        incident_id=incident_id,
                        selector_intent_revision=selector_intent_revision,
                        deadline_monotonic=deadline,
                        expected_worker_token=worker_token,
                        prewarmed_result=evidence.probe_result,
                        prewarmed_evidence=evidence,
                        on_selection_committed=mark_selection_committed,
                        recovery_ticket=recovery_ticket,
                    )
                    if not (
                        audit.get("post_switch_connectivity_verified")
                        and audit.get("effective_egress_ok") is True
                    ):
                        raise RuntimeError(
                            str(
                                audit.get("reason")
                                or "provisional route was not verified"
                            )
                        )
                    selection_action = audit.get("selection_action")
                    selection_action = (
                        selection_action
                        if isinstance(selection_action, dict)
                        else dict(action)
                    )
                    now = self._runtime_recovery_now()
                    managed_lease = ManagedFixedLease(
                        incident_id=incident_id,
                        group=str(selection_action.get("group") or "FINAL-EXIT"),
                        from_proxy=failure.binding.node.proxy_name,
                        to_proxy=evidence.ref.proxy_name,
                        target_member=str(selection_action.get("target") or ""),
                        mode=str(selection_action.get("mode") or "selector"),
                        route_epoch=int(
                            audit.get("loaded_route_epoch")
                            or failure.binding.route_epoch
                        ),
                        owner_token=probe_token,
                        minimum_dwell_until=now + 30.0,
                        user_intent_revision=selector_intent_revision,
                        verified_at_monotonic=now,
                        provisional=True,
                        parent_incident_id=str(
                            (parent_lease or {}).get("incident_id") or ""
                        ),
                    )
                    lease_payload = managed_lease.to_dict()
                    lease_payload["recovery_ticket_generation"] = (
                        recovery_ticket.generation
                    )
                    lease_payload["recovery_deadline_monotonic"] = deadline
                    with self._runtime_failure_monitor_lock:
                        if (
                            not self._runtime_worker_token_is_current(worker_token)
                            or bool(self._runtime_facility_hold_reason())
                            or int(
                                getattr(self, "_runtime_facility_epoch", 0) or 0
                            )
                            != facility_epoch
                            or
                            int(
                                getattr(
                                    self,
                                    "_runtime_selector_intent_revision",
                                    0,
                                )
                                or 0
                            )
                            != selector_intent_revision
                            or not self._runtime_recovery_ticket_is_current(
                                recovery_ticket,
                                require_open=True,
                                deadline_monotonic=deadline,
                            )
                        ):
                            raise RuntimeError(
                                "provisional route verification crossed a "
                                "facility or selector epoch"
                            )
                        if not self._runtime_commit_successor_lease_locked(
                            lease_payload,
                            parent_lease,
                        ):
                            raise RuntimeError(
                                "automatic route lease changed before successor CAS"
                            )
                        # The physical hot-standby switch completed inside its
                        # two-second budget, but the same incident still owns
                        # exact origin confirmation.  Keep the ticket open so
                        # a waiter cannot publish RECOVERED before the circuit
                        # and health writeback is complete.
                        self._runtime_egress_coordinator.mark_diverted(
                            failure.binding,
                            incident_id=incident_id,
                            quarantine_token=probe_token,
                        )
                        # Publish origin authority only after PUT/readback/204
                        # has committed a verified replacement.  Publishing it
                        # before the selector write allowed a racing failed
                        # probe to punish the origin while no replacement had
                        # actually taken ownership.
                        self._runtime_origin_diagnostic_bindings[incident_id] = (
                            OriginDiagnosticBinding(
                                incident_id=incident_id,
                                binding=failure.binding,
                                snapshot_key=snapshot.snapshot_key,
                                selector_intent_revision=(
                                    selector_intent_revision
                                ),
                                owner_token=probe_token,
                                expires_at_monotonic=now + 90.0,
                                committed_route_epoch=managed_lease.route_epoch,
                                target_proxy=managed_lease.to_proxy,
                            )
                        )
                        self._runtime_incident_bindings[incident_id] = failure.binding
                        self._runtime_incident_route_payloads[incident_id] = (
                            snapshot_payload
                        )
                        self._runtime_incident_recovery_state[incident_id] = (
                            "diverted"
                        )
                        self._runtime_route_stable_since = now
                        self._runtime_last_verified_route = {
                            "verified_at_monotonic": now,
                            "incident_id": incident_id,
                            "leaf_proxy": evidence.ref.proxy_name,
                            "route": list(audit.get("selected_chain") or []),
                            "result": dict(audit.get("post_switch_result") or {}),
                            "provisional": True,
                        }
                        # Facility boundary writers share this monitor lock, so
                        # lease + readiness is one publication transaction.
                        self._set_effective_egress_state(True, "")
                    route_changed_without_verification = False
            except Exception:
                # An unverified selector write is recoverable ambiguity, not a
                # proof that the complete route or facility is dead.  The old
                # path converted a 250ms readback miss into ownerless REJECT,
                # then its facility hold blocked every later confirmation and
                # manual check.  Perform one inverse transaction/readback and
                # leave readiness indeterminate; never punish a node or enter
                # global hold from this provisional phase.
                rollback_binding: RuntimeRouteBinding | None = None
                rollback_state = "not_needed"
                if not route_changed_without_verification:
                    rebound_budget = self._runtime_recovery_remaining(
                        deadline,
                        cap=0.2,
                    )
                    if rebound_budget > 0.0:
                        try:
                            rebound = self._current_runtime_failure_binding_state(
                                timeout_seconds=rebound_budget
                            )
                        except Exception:
                            rebound = None
                    else:
                        rebound = None
                    rebound_binding = (
                        rebound[0]
                        if isinstance(rebound, tuple) and len(rebound) >= 1
                        else None
                    )
                    route_changed_without_verification = bool(
                        isinstance(rebound_binding, RuntimeRouteBinding)
                        and rebound_binding.node.proxy_name
                        == str(action.get("target") or "")
                        and rebound_binding.node.proxy_name
                        != failure.binding.node.proxy_name
                    )
                if route_changed_without_verification:
                    rollback_binding, rollback_state = (
                        self._rollback_runtime_provisional_selection(
                            action,
                            worker_token=worker_token,
                            selector_intent_revision=selector_intent_revision,
                            deadline_monotonic=deadline,
                        )
                    )
                    self._complete_runtime_recovery_hold(
                        recovery_ticket,
                        reason_code="hot_selection_not_authoritatively_verified",
                    )
                readiness = getattr(
                    self,
                    "_set_effective_egress_readiness_state",
                    None,
                )
                reason = (
                    "Provisional route verification is pending"
                    if rollback_binding is None or rollback_state == "unknown"
                    else "Provisional route was restored after inconclusive verification"
                )
                if callable(readiness):
                    readiness(None, reason)
                else:
                    # Compatibility for narrow fixtures; production always has
                    # the three-state readiness publisher.
                    self._set_effective_egress_state(None, reason)
                log_raw_diagnostic(
                    self.logger,
                    "warning",
                    "Runtime provisional diversion failed safely",
                    exc_info=True,
                )
            finally:
                if mutation is not None:
                    self._runtime_egress_coordinator.end_core_mutation(mutation)
                if recovery_lease is not None:
                    reload_gate = getattr(self, "_runtime_reload_gate", None)
                    if reload_gate is not None:
                        reload_gate.end_recovery(recovery_lease)
                pending_confirmation: dict[str, Any] | None = None
                with self._runtime_failure_monitor_lock:
                    self._runtime_failure_recovery_bindings.discard(key)
                    self._runtime_failure_recovery_threads.discard(
                        threading.current_thread()
                    )
                    lease_record = self._runtime_route_mutation_lease
                    if not (
                        isinstance(lease_record, dict)
                        and str(lease_record.get("incident_id") or "")
                        == incident_id
                    ):
                        self._runtime_origin_diagnostic_bindings.pop(
                            incident_id,
                            None,
                        )
                    pending_confirmation = (
                        self._runtime_pending_confirmed_incidents.pop(
                            incident_id,
                            None,
                        )
                    )
                if isinstance(pending_confirmation, dict):
                    with self._runtime_failure_monitor_lock:
                        lease_record = self._runtime_route_mutation_lease
                        diversion_committed = bool(
                            isinstance(lease_record, dict)
                            and str(lease_record.get("incident_id") or "")
                            == incident_id
                            and str(lease_record.get("owner_token") or "")
                            == probe_token
                            and float(
                                lease_record.get("verified_at_monotonic") or 0.0
                            )
                            > 0.0
                        )
                    ticket_open = self._runtime_recovery_ticket_is_current(
                        recovery_ticket,
                        require_open=True,
                    )
                    if not diversion_committed or not ticket_open:
                        # The provisional inverse transaction advanced the
                        # route epoch.  A confirmation captured against the
                        # pre-write snapshot cannot quarantine the freshly
                        # restored binding, even when it resolves to the same
                        # identity. Re-enter through the fresh current-route
                        # evidence path instead of silently consuming the
                        # pending incident with a stale health CAS.
                        self._submit_current_route_probe_failure(
                            "confirmed incident crossed provisional rollback",
                            source="provisional_pending_rebind",
                        )
                    else:
                        self._start_runtime_recovery(
                            failure,
                            snapshot,
                            snapshot_payload,
                            incident_id=incident_id,
                            quarantine_token=str(
                                pending_confirmation.get("quarantine_token")
                                or probe_token
                            ),
                            confirmed_alternative=pending_confirmation.get(
                                "confirmed_alternative"
                            ),
                            already_diverted=True,
                            confirmed_alternative_probe_result=(
                                pending_confirmation.get(
                                    "confirmed_alternative_probe_result"
                                )
                            ),
                            confirmed_alternative_evidence=(
                                pending_confirmation.get(
                                    "confirmed_alternative_evidence"
                                )
                            ),
                        )
                else:
                    # Serialize this incident's phases.  Once selector
                    # commit/readback/204 has released the two global sockets,
                    # confirm the origin (or the restored current route) rather
                    # than racing both pairs against each other.
                    with self._runtime_failure_monitor_lock:
                        lease_record = self._runtime_route_mutation_lease
                        diversion_committed = bool(
                            isinstance(lease_record, dict)
                            and str(lease_record.get("incident_id") or "")
                            == incident_id
                            and str(lease_record.get("owner_token") or "")
                            == probe_token
                        )
                    ticket_open = self._runtime_recovery_ticket_is_current(
                        recovery_ticket,
                        require_open=True,
                    )
                    if diversion_committed and ticket_open:
                        self._start_runtime_independent_probe(
                            failure,
                            snapshot,
                            snapshot_payload,
                            probe_token=probe_token,
                        )
                    elif route_changed_without_verification:
                        # Rollback may have advanced route_epoch. Bind any
                        # follow-up evidence to the fresh loaded snapshot.
                        self._submit_current_route_probe_failure(
                            "provisional diversion was inconclusive",
                            source="provisional_reconcile",
                        )
                    elif ticket_open:
                        # No selector write occurred inside the two-second hot
                        # window. Continue cold confirmation under the same
                        # incident ticket and its original six-second clock.
                        self._start_runtime_independent_probe(
                            failure,
                            snapshot,
                            snapshot_payload,
                            probe_token=probe_token,
                        )

        thread = threading.Thread(
            target=worker,
            name="runtime-egress-provisional-diversion",
            daemon=True,
        )
        with self._runtime_failure_monitor_lock:
            self._runtime_failure_recovery_threads.add(thread)
        thread.start()
        return True

    def _defer_runtime_provisional_confirmation(
        self,
        failure: BoundRuntimeFailure,
        snapshot_payload: dict[str, Any],
        *,
        incident_id: str,
        probe_token: str,
        reason: str,
    ) -> bool:
        """Keep one exact-origin confirmation across a facility epoch.

        The mailbox owns evidence only; it never mutates Manager health while a
        facility hold is active.  A fresh-context worker consumes it after the
        currently diverted route has passed FINAL-EXIT verification.
        """

        incident_id = str(incident_id or "").strip()
        if not incident_id:
            return False
        with self._runtime_failure_monitor_lock:
            lease_record = getattr(self, "_runtime_route_mutation_lease", None)
            if not (
                isinstance(lease_record, dict)
                and bool(lease_record.get("provisional"))
                and str(lease_record.get("incident_id") or "") == incident_id
                and str(lease_record.get("from") or "")
                == failure.binding.node.proxy_name
                and str(lease_record.get("to") or "")
                and float(lease_record.get("verified_at_monotonic") or 0.0) > 0.0
            ):
                return False
            deferred = getattr(
                self,
                "_runtime_deferred_provisional_confirmations",
                None,
            )
            if not isinstance(deferred, dict):
                deferred = {}
                self._runtime_deferred_provisional_confirmations = deferred
            deferred[incident_id] = {
                "incident_id": incident_id,
                "binding": failure.binding,
                "snapshot_payload": dict(snapshot_payload),
                "owner_token": str(
                    probe_token or lease_record.get("owner_token") or ""
                ),
                "selector_intent_revision": int(
                    lease_record.get(
                        "selector_intent_revision",
                        getattr(self, "_runtime_selector_intent_revision", 0),
                    )
                    or 0
                ),
                "from_proxy": failure.binding.node.proxy_name,
                "to_proxy": str(lease_record.get("to") or ""),
                "reason": str(reason or "facility_hold"),
            }
            return True

    @staticmethod
    def _runtime_rebound_origin_binding(
        binding: RuntimeRouteBinding,
        snapshot: CoreLoadedRouteSnapshot,
    ) -> RuntimeRouteBinding | None:
        """Rebind the same configured origin to a fresh execution snapshot."""

        matches = [
            ref
            for ref in snapshot.proxy_nodes
            if ref.proxy_name == binding.node.proxy_name
            and ref.key == binding.node.key
        ]
        if len(matches) != 1:
            return None
        graph = {str(name): tuple(members) for name, members in snapshot.group_graph}
        chain = tuple(binding.route_chain)
        for parent, child in zip(chain, chain[1:]):
            members = graph.get(str(parent))
            if members is not None and str(child) not in {
                str(member) for member in members
            }:
                return None
        return RuntimeRouteBinding(
            process_pid=snapshot.process_pid,
            process_generation=snapshot.process_generation,
            core_generation=snapshot.core_generation,
            semantic_digest=snapshot.semantic_digest,
            route_epoch=snapshot.route_epoch,
            observed_outbound=binding.observed_outbound,
            route_chain=chain,
            node=matches[0],
            network_context_epoch=snapshot.network_context_epoch,
        )

    def _retire_runtime_provisional_confirmation(
        self,
        incident_id: str,
        *,
        reason: str,
    ) -> bool:
        """Make an unresolvable provisional lease explicit, never sticky."""

        with self._runtime_failure_monitor_lock:
            lease_record = getattr(self, "_runtime_route_mutation_lease", None)
            if not (
                isinstance(lease_record, dict)
                and str(lease_record.get("incident_id") or "")
                == str(incident_id)
                and bool(lease_record.get("provisional"))
            ):
                getattr(
                    self,
                    "_runtime_deferred_provisional_confirmations",
                    {},
                ).pop(str(incident_id), None)
                return False
            # The diverted route has just passed a fresh full-chain baseline.
            # If the old exact proxy/path no longer exists, keeping the word
            # provisional would create an owner that no future probe can
            # complete.  Retain the automatic lease for higher-layer recovery,
            # but record why the former same-leaf return is no longer possible.
            lease_record["provisional"] = False
            lease_record["reconcile_state"] = str(reason)
            recovery_states = getattr(
                self,
                "_runtime_incident_recovery_state",
                None,
            )
            if not isinstance(recovery_states, dict):
                recovery_states = {}
                self._runtime_incident_recovery_state = recovery_states
            recovery_states[str(incident_id)] = "origin_unavailable"
            self._runtime_origin_diagnostic_bindings.pop(str(incident_id), None)
            getattr(
                self,
                "_runtime_deferred_provisional_confirmations",
                {},
            ).pop(str(incident_id), None)
            return True

    def _resume_deferred_runtime_provisional_confirmations(self) -> None:
        """Revalidate provisional origins only after a fresh route baseline."""

        if self._runtime_facility_hold_reason():
            return
        with self._runtime_failure_monitor_lock:
            pending = list(
                getattr(
                    self,
                    "_runtime_deferred_provisional_confirmations",
                    {},
                ).items()
            )
        if not pending:
            return
        snapshot, snapshot_payload = self._runtime_route_snapshot_state()
        if snapshot is None or not isinstance(snapshot_payload, dict):
            for incident_id, _item in pending:
                self._retire_runtime_provisional_confirmation(
                    str(incident_id),
                    reason="fresh_route_snapshot_unavailable_after_hold",
                )
            return
        phase_getter = getattr(self, "_current_core_runtime_phase", None)
        capture_current = bool(
            not callable(phase_getter) or phase_getter() == "formal_capture"
        )
        for incident_id, item in pending:
            if not isinstance(item, dict):
                self._retire_runtime_provisional_confirmation(
                    str(incident_id),
                    reason="invalid_deferred_origin_record",
                )
                continue
            with self._runtime_failure_monitor_lock:
                lease_record = getattr(
                    self,
                    "_runtime_route_mutation_lease",
                    None,
                )
                expected_revision = int(
                    item.get("selector_intent_revision", 0) or 0
                )
                lease_current = bool(
                    isinstance(lease_record, dict)
                    and bool(lease_record.get("provisional"))
                    and str(lease_record.get("incident_id") or "")
                    == str(incident_id)
                    and str(lease_record.get("from") or "")
                    == str(item.get("from_proxy") or "")
                    and str(lease_record.get("to") or "")
                    == str(item.get("to_proxy") or "")
                    and int(
                        lease_record.get(
                            "selector_intent_revision",
                            expected_revision,
                        )
                        or 0
                    )
                    == expected_revision
                    and int(
                        getattr(
                            self,
                            "_runtime_selector_intent_revision",
                            expected_revision,
                        )
                        or 0
                    )
                    == expected_revision
                )
            if not lease_current:
                with self._runtime_failure_monitor_lock:
                    getattr(
                        self,
                        "_runtime_deferred_provisional_confirmations",
                        {},
                    ).pop(str(incident_id), None)
                continue
            old_binding = item.get("binding")
            rebound = (
                self._runtime_rebound_origin_binding(old_binding, snapshot)
                if isinstance(old_binding, RuntimeRouteBinding)
                else None
            )
            if rebound is None:
                self._retire_runtime_provisional_confirmation(
                    str(incident_id),
                    reason="origin_not_in_fresh_loaded_graph",
                )
                continue
            if not capture_current:
                continue
            key = ("provisional_reconfirm", str(incident_id))
            with self._runtime_failure_monitor_lock:
                if key in self._runtime_failure_recovery_bindings:
                    continue
                self._runtime_failure_recovery_bindings.add(key)

            def worker(
                *,
                old_incident_id: str = str(incident_id),
                old_item: dict[str, Any] = dict(item),
                fresh_snapshot: CoreLoadedRouteSnapshot = snapshot,
                fresh_payload: dict[str, Any] = snapshot_payload,
                fresh_binding: RuntimeRouteBinding = rebound,
                admission_key: tuple[Any, ...] = key,
            ) -> None:
                worker_token = self._runtime_worker_token()
                terminal = False
                try:
                    if (
                        self._runtime_facility_hold_reason()
                        or not self._runtime_worker_token_is_current(worker_token)
                    ):
                        return
                    try:
                        self._probe_runtime_leaf(
                            fresh_binding.node,
                            fresh_payload,
                            timeout_ms=self._runtime_confirmation_timeout_ms(
                                fresh_binding.node,
                                fresh_payload,
                            ),
                            probe_priority=ProbePriority.RUNTIME_MANUAL,
                        )
                    except _RuntimeProbeBudgetUnavailable:
                        return
                    except Exception:
                        # The diverted path must still succeed in this same
                        # context before a failed origin probe can become node
                        # evidence rather than WAN/facility evidence.
                        try:
                            self._verify_runtime_final_exit(
                                expected_worker_token=worker_token,
                                expected_snapshot=fresh_snapshot,
                                timeout_seconds=1.5,
                            )
                        except _RuntimeProbeBudgetUnavailable:
                            return
                        except Exception:
                            self._record_runtime_facility_degradation(
                                "Deferred provisional origin and diverted route "
                                "could not be differentially verified"
                            )
                            return
                        if (
                            self._runtime_facility_hold_reason()
                            or not self._runtime_worker_token_is_current(
                                worker_token
                            )
                        ):
                            return
                        event = BoundRuntimeFailure(
                            binding=fresh_binding,
                            protocol="PROBE",
                            observed_outbound=fresh_binding.observed_outbound,
                            destination_token=runtime_destination_token(
                                "provisional-origin-reconfirm"
                            ),
                            error_type="fresh_origin_probe_failed",
                            observed_at_monotonic=time.monotonic(),
                            flow_token=(
                                f"provisional:{old_incident_id}:fresh-context"
                            ),
                        )
                        first = self._runtime_egress_coordinator.observe(
                            event,
                            current_snapshot=fresh_snapshot,
                        )
                        decision = self._runtime_egress_coordinator.record_probe(
                            event,
                            succeeded=False,
                            probe_token=first.probe_token,
                            current_snapshot=fresh_snapshot,
                        )
                        if not decision.confirmed:
                            return
                        current_domain = self._runtime_route_binding_for_outbound(
                            fresh_snapshot,
                            fresh_payload,
                            fresh_binding.observed_outbound,
                            require_final_exit=bool(
                                fresh_binding.observed_outbound == "FINAL-EXIT"
                                or "FINAL-EXIT" in fresh_binding.route_chain
                            ),
                        )
                        if current_domain is None:
                            return
                        with self._runtime_failure_monitor_lock:
                            lease_record = self._runtime_route_mutation_lease
                            if not (
                                isinstance(lease_record, dict)
                                and bool(lease_record.get("provisional"))
                                and str(lease_record.get("incident_id") or "")
                                == old_incident_id
                                and str(lease_record.get("to") or "")
                                == current_domain.node.proxy_name
                            ):
                                return
                            lease_record["incident_id"] = decision.incident_id
                            lease_record["owner_token"] = decision.probe_token
                            lease_record["route_epoch"] = fresh_snapshot.route_epoch
                            self._runtime_origin_diagnostic_bindings[
                                decision.incident_id
                            ] = OriginDiagnosticBinding(
                                incident_id=decision.incident_id,
                                binding=fresh_binding,
                                snapshot_key=fresh_snapshot.snapshot_key,
                                selector_intent_revision=int(
                                    getattr(
                                        self,
                                        "_runtime_selector_intent_revision",
                                        0,
                                    )
                                    or 0
                                ),
                                owner_token=decision.probe_token,
                                expires_at_monotonic=time.monotonic() + 90.0,
                                committed_route_epoch=int(
                                    lease_record.get("route_epoch") or 0
                                ),
                                target_proxy=current_domain.node.proxy_name,
                            )
                            self._runtime_incident_bindings[
                                decision.incident_id
                            ] = fresh_binding
                            self._runtime_incident_route_payloads[
                                decision.incident_id
                            ] = fresh_payload
                            self._runtime_incident_recovery_state[
                                decision.incident_id
                            ] = "diverted"
                            getattr(
                                self,
                                "_runtime_deferred_provisional_confirmations",
                                {},
                            ).pop(old_incident_id, None)
                        terminal = True
                        self._start_runtime_recovery(
                            event,
                            fresh_snapshot,
                            fresh_payload,
                            incident_id=decision.incident_id,
                            quarantine_token=decision.probe_token,
                            confirmed_alternative=current_domain.node,
                            already_diverted=True,
                        )
                        return

                    if (
                        self._runtime_facility_hold_reason()
                        or not self._runtime_worker_token_is_current(worker_token)
                    ):
                        return
                    now = time.monotonic()
                    with self._runtime_failure_monitor_lock:
                        lease_record = self._runtime_route_mutation_lease
                        if not (
                            isinstance(lease_record, dict)
                            and bool(lease_record.get("provisional"))
                            and str(lease_record.get("incident_id") or "")
                            == old_incident_id
                        ):
                            return
                        history = list(
                            self._runtime_failback_pass_history.get(
                                fresh_binding.node.key,
                                [],
                            )
                        )
                        history.append(now)
                        self._runtime_failback_pass_history[
                            fresh_binding.node.key
                        ] = history[-4:]
                        self._runtime_incident_bindings[
                            old_incident_id
                        ] = fresh_binding
                        self._runtime_incident_route_payloads[
                            old_incident_id
                        ] = fresh_payload
                        self._runtime_incident_recovery_state[
                            old_incident_id
                        ] = "ready"
                        getattr(
                            self,
                            "_runtime_deferred_provisional_confirmations",
                            {},
                        ).pop(old_incident_id, None)
                    terminal = True
                    self._start_runtime_failback(
                        {
                            "incident_id": old_incident_id,
                            "tier": fresh_binding.node.tier,
                            "pool_kind": fresh_binding.node.pool_kind,
                            "identity": fresh_binding.node.identity,
                            "proxy_name": fresh_binding.node.proxy_name,
                            "transition": {"action": "recovered"},
                            "provisional": True,
                        },
                        fresh_binding.node,
                    )
                finally:
                    with self._runtime_failure_monitor_lock:
                        self._runtime_failure_recovery_bindings.discard(
                            admission_key
                        )
                        self._runtime_failure_recovery_threads.discard(
                            threading.current_thread()
                        )
                        if terminal:
                            getattr(
                                self,
                                "_runtime_deferred_provisional_confirmations",
                                {},
                            ).pop(old_incident_id, None)

            thread = threading.Thread(
                target=worker,
                name="runtime-egress-provisional-reconfirm",
                daemon=True,
            )
            with self._runtime_failure_monitor_lock:
                self._runtime_failure_recovery_threads.add(thread)
            thread.start()

    def _complete_runtime_early_indeterminate(
        self,
        failure: BoundRuntimeFailure,
        ticket: _RuntimeRecoveryTicket,
        *,
        probe_token: str,
        reason_code: str,
    ) -> RuntimeRecoveryOutcome | None:
        """Finish one bounded attempt without creating a hold or retry loop."""

        with self._runtime_failure_monitor_lock:
            self._runtime_incident_bindings[ticket.incident_id] = failure.binding
            self._runtime_incident_recovery_state[
                ticket.incident_id
            ] = "indeterminate"
        outcome = self._complete_runtime_recovery_outcome(
            ticket.incident_id,
            RuntimeRecoveryStatus.CONTROLLER_HOLD,
            reason_code=f"indeterminate_{reason_code}",
            expected_ticket=ticket,
        )
        self._runtime_egress_coordinator.finish_indeterminate(
            failure.binding,
            incident_id=ticket.incident_id,
            quarantine_token=str(probe_token),
        )
        return outcome

    def _run_runtime_early_confirmed_recovery(
        self,
        failure: BoundRuntimeFailure,
        snapshot: CoreLoadedRouteSnapshot,
        snapshot_payload: dict[str, Any],
        *,
        ticket: _RuntimeRecoveryTicket,
        probe_token: str,
        alternative: RuntimeNodeRef,
        alternative_probe_result: dict[str, Any] | None = None,
        alternative_probe_evidence: _HotStandbyEvidence | None = None,
        startup_admission: bool = False,
    ) -> RuntimeRecoveryOutcome | None:
        """Commit one proven A-failed/B-passed route change and then stop."""

        deadline = float(ticket.deadline_monotonic)
        replacement_verified = False
        if not self._runtime_recovery_ticket_is_current(
            ticket,
            require_open=True,
            deadline_monotonic=deadline,
        ):
            return self._complete_runtime_early_indeterminate(
                failure,
                ticket,
                probe_token=probe_token,
                reason_code="ticket_stale",
            )
        confirmed = self._runtime_egress_coordinator.record_probe(
            failure,
            succeeded=False,
            probe_token=str(probe_token),
            current_snapshot=snapshot,
        )
        if not confirmed.confirmed:
            return self._complete_runtime_early_indeterminate(
                failure,
                ticket,
                probe_token=probe_token,
                reason_code="confirmation_rejected",
            )
        health = self._apply_confirmed_runtime_health(
            failure,
            snapshot,
            snapshot_payload,
            incident_id=ticket.incident_id,
            quarantine_token=str(probe_token),
            expected_ticket=ticket,
            deadline_monotonic=deadline,
        )
        if not bool(health.get("accepted")):
            return self._complete_runtime_early_indeterminate(
                failure,
                ticket,
                probe_token=probe_token,
                reason_code="health_cas_rejected",
            )
        self._mark_runtime_recovery_quarantined(
            failure.binding,
            recovery_ticket=ticket,
            coordinator_incident_id=ticket.incident_id,
            coordinator_quarantine_token=str(probe_token),
            deadline_monotonic=deadline,
        )
        with self._runtime_failure_monitor_lock:
            self._runtime_incident_recovery_state[ticket.incident_id] = (
                "recovering"
            )
        try:
            with self._runtime_egress_coordinator.core_mutation_transaction(
                failure.binding,
                expected_snapshot=snapshot,
                timeout_seconds=0.0,
            ) as mutation_lease:
                if mutation_lease is None:
                    raise RuntimeError("runtime route transaction is busy")
                with self._bounded_core_transition(
                    deadline,
                    "runtime FINAL-EXIT replacement",
                ):
                    result = self._fast_recover_confirmed_alternative(
                        failure,
                        snapshot,
                        snapshot_payload,
                        alternative,
                        incident_id=ticket.incident_id,
                        selector_intent_revision=ticket.selector_intent_revision,
                        deadline_monotonic=deadline,
                        expected_worker_token=ticket.worker_token,
                        prewarmed_result=alternative_probe_result,
                        prewarmed_evidence=alternative_probe_evidence,
                        recovery_ticket=ticket,
                        required_successes=2 if startup_admission else 1,
                    )
            if not bool(
                isinstance(result, dict)
                and result.get("effective_egress_ok") is True
                and result.get("post_switch_connectivity_verified") is True
            ):
                raise RuntimeError(
                    str(
                        result.get("reason")
                        if isinstance(result, dict)
                        else "replacement was not verified"
                    )
                )
            replacement_verified = True
            action = result.get("selection_action")
            action = action if isinstance(action, dict) else {}
            route_epoch = int(
                result.get("loaded_route_epoch")
                or getattr(self, "_runtime_route_epoch", 0)
                or 0
            )
            verified_at = self._runtime_recovery_now()
            with self._runtime_failure_monitor_lock:
                self._runtime_route_mutation_lease = {
                    "incident_id": ticket.incident_id,
                    "owner_token": str(probe_token),
                    "group": str(action.get("group") or ""),
                    "mode": str(action.get("mode") or "selector"),
                    "from": failure.binding.node.proxy_name,
                    "to": alternative.proxy_name,
                    "target_member": str(action.get("target") or ""),
                    "previous_member": str(action.get("previous") or ""),
                    "route_epoch": route_epoch,
                    "selector_intent_revision": ticket.selector_intent_revision,
                    "verified_at_monotonic": verified_at,
                    "recovery_ticket_generation": ticket.generation,
                    "release_state": "pending",
                    "startup_admission": bool(startup_admission),
                    "activation_generation": int(
                        getattr(self, "_tier3_egress_activation_generation", 0)
                        or 0
                    ) if startup_admission else 0,
                    "lifecycle_revision": int(
                        getattr(self, "_lifecycle_revision", 0) or 0
                    ) if startup_admission else 0,
                    "runtime_generation": int(
                        getattr(self, "_runtime_generation", 0) or 0
                    ) if startup_admission else 0,
                    "core_generation": int(
                        getattr(self, "_core_generation", 0) or 0
                    ) if startup_admission else 0,
                }
                self._runtime_incident_recovery_state[ticket.incident_id] = (
                    "ready"
                )
                self._runtime_last_verified_route = {
                    "incident_id": ticket.incident_id,
                    "leaf_proxy": alternative.proxy_name,
                    "result": dict(result.get("post_switch_result") or {}),
                    "verified_at_monotonic": verified_at,
                }
            if not startup_admission:
                self._set_effective_egress_state(True, "")
                self._publish_runtime_egress_readiness(
                    RuntimeEgressReadinessState.READY,
                    validation_active=False,
                )
                if not self._try_arm_runtime_recovery():
                    raise RuntimeControllerReadbackError(
                        "verified replacement could not arm its managed route binding"
                    )
            outcome = self._complete_runtime_recovery_outcome(
                ticket.incident_id,
                RuntimeRecoveryStatus.RECOVERED,
                reason_code="replacement_selected_and_verified",
                to_ref=alternative,
                route_epoch=route_epoch,
                expected_ticket=ticket,
                deadline_monotonic=deadline,
                facts={"put": True, "readback": True, "final_204": True},
            )
            if outcome is None:
                raise RuntimeControllerReadbackError(
                    "verified replacement lost canonical incident ownership"
                )
            self._publish_verified_runtime_source_proof(expected_route_epoch=route_epoch)
            resume_failback = getattr(self, "_resume_runtime_passive_failback", None)
            if callable(resume_failback):
                resume_failback()
            return outcome
        except Exception as exc:
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Bounded FINAL-EXIT replacement ended without a verified route "
                "(error_type=%s)",
                type(exc).__name__,
            )
            terminal_reason = (
                "Verified FINAL-EXIT replacement lost controller authority"
                if replacement_verified
                else "Confirmed FINAL-EXIT replacement was not verified"
            )
            if not startup_admission:
                self._set_effective_egress_readiness_state(False, terminal_reason)
                self._publish_runtime_egress_readiness(
                    RuntimeEgressReadinessState.CONTROLLER_HOLD
                    if replacement_verified
                    else RuntimeEgressReadinessState.DATA_PLANE_FAILED,
                    validation_active=False,
                    reason=terminal_reason,
                )
            return self._complete_runtime_early_indeterminate(
                failure,
                ticket,
                probe_token=probe_token,
                reason_code="replacement_unverified",
            )

    def _start_runtime_early_confirmation(
        self,
        failure: BoundRuntimeFailure,
        snapshot: CoreLoadedRouteSnapshot,
        snapshot_payload: dict[str, Any],
        *,
        probe_token: str,
        incident_id: str,
        deadline_monotonic: float | None = None,
        startup_admission: bool = False,
        gateway_ref: RuntimeNodeRef | None = None,
    ) -> _RuntimeRecoveryTicket | None:
        """Launch one current/ordered-backup differential confirmation."""

        ticket = self._ensure_runtime_recovery_ticket(
            failure,
            snapshot,
            str(incident_id),
            deadline_monotonic=deadline_monotonic,
        )
        if not isinstance(ticket, _RuntimeRecoveryTicket):
            return None
        key = failure.circuit_key
        with self._runtime_failure_monitor_lock:
            if key in self._runtime_failure_probe_bindings:
                return ticket
            self._runtime_failure_probe_bindings.add(key)
            self._runtime_incident_bindings[ticket.incident_id] = failure.binding
            self._runtime_incident_route_payloads[ticket.incident_id] = (
                snapshot_payload
            )

        def worker() -> None:
            evidence_deadline = min(
                float(ticket.deadline_monotonic),
                float(ticket.deadline_monotonic) - min(
                    2.0, max(0.0, float(ticket.deadline_monotonic) - self._runtime_recovery_now()) / 3.0,
                ),
            )
            # Reuse only same-contract current-leaf evidence in this incident.
            # Reprobing the dead leaf for every backup consumed the entire
            # budget before later fallback members could be considered.
            current_evidence: dict[tuple[str, str], tuple[str, Any]] = {}
            try:
                plans = self._runtime_early_differential_plans(
                    failure,
                    snapshot,
                    snapshot_payload,
                )
                if not plans:
                    if gateway_ref is None:
                        self._enqueue_passive_node_health_check(
                            failure.binding.node, reason="runtime_no_alternative",
                        )
                    else:
                        # A full-chain error does not identify whether the
                        # fixed Gateway or its dialer failed. Prove the dialer
                        # before requesting the Gateway's own policy check.
                        try:
                            remaining = max(0.0, evidence_deadline - self._runtime_recovery_now())
                            if remaining < 0.05:
                                raise _RuntimeProbeBudgetUnavailable("confirmation deadline expired")
                            underlay_result = self._probe_runtime_leaf(
                                failure.binding.node, snapshot_payload,
                                timeout_ms=min(1500, max(1, int(remaining * 1000))),
                                probe_priority=ProbePriority.RUNTIME_MANUAL,
                                recovery_ticket=ticket,
                                recovery_deadline_monotonic=evidence_deadline,
                            )
                        except _RuntimeProbeBudgetUnavailable:
                            underlay_result = "indeterminate"
                        except Exception as exc:
                            underlay_result = (
                                "indeterminate"
                                if isinstance(exc, (TypeError, AttributeError))
                                or self._proxy_delay_failure_is_transient(exc)
                                else None
                            )
                        if isinstance(underlay_result, dict):
                            self._enqueue_passive_node_health_check(
                                gateway_ref, reason="gateway_runtime_error",
                            )
                        elif underlay_result is None:
                            self._enqueue_passive_node_health_check(
                                failure.binding.node, reason="runtime_no_alternative",
                            )
                    self._complete_runtime_early_indeterminate(
                        failure,
                        ticket,
                        probe_token=probe_token,
                        reason_code="alternative_unbound",
                    )
                    return
                for plan in plans:
                    remaining = max(
                        0.0,
                        evidence_deadline - self._runtime_recovery_now(),
                    )
                    if remaining < 0.05:
                        self._complete_runtime_early_indeterminate(
                            failure,
                            ticket,
                            probe_token=probe_token,
                            reason_code="confirmation_deadline",
                        )
                        return
                    alternative = plan.get("ref")
                    if not isinstance(alternative, RuntimeNodeRef):
                        continue
                    probe_url = str(plan.get("probe_url") or "")
                    expected_status = str(plan.get("expected_status") or "204")
                    results: dict[str, tuple[str, Any]] = {}
                    results_lock = threading.Lock()
                    contract = (probe_url, expected_status)
                    if contract in current_evidence:
                        results["current"] = current_evidence[contract]
                    pair_deadline = min(
                        evidence_deadline,
                        self._runtime_recovery_now() + 0.3 + max(
                            self._runtime_confirmation_timeout_ms(ref, snapshot_payload)
                            for ref in (failure.binding.node, alternative)
                        ) / 1000.0,
                    )

                    def probe_pair(
                        label: str, ref: RuntimeNodeRef, *,
                        pair_deadline: float = pair_deadline,
                        probe_url: str = probe_url,
                        expected_status: str = expected_status,
                        results: dict[str, tuple[str, Any]] = results,
                        results_lock: Any = results_lock,
                    ) -> None:
                        state = "failed"
                        value: dict[str, Any] | None = None
                        pair_remaining = max(
                            0.0,
                            pair_deadline - self._runtime_recovery_now(),
                        )
                        try:
                            if pair_remaining < 0.05:
                                raise _RuntimeProbeBudgetUnavailable(
                                    "confirmation deadline expired"
                                )
                            value = self._probe_runtime_leaf(
                                ref,
                                snapshot_payload,
                                timeout_ms=min(
                                    self._runtime_confirmation_timeout_ms(
                                        ref,
                                        snapshot_payload,
                                    ),
                                    max(1, int(pair_remaining * 1000.0)),
                                ),
                                probe_url=probe_url,
                                expected_status=expected_status,
                                probe_priority=ProbePriority.RUNTIME_MANUAL,
                                recovery_ticket=ticket,
                                recovery_deadline_monotonic=pair_deadline,
                            )
                            state = "passed" if value is not None else "failed"
                        except _RuntimeProbeBudgetUnavailable:
                            state = "indeterminate"
                        except Exception as exc:
                            if isinstance(exc, (TypeError, AttributeError)) or (
                                self._proxy_delay_failure_is_transient(exc)
                            ):
                                state = "indeterminate"
                        with results_lock:
                            results[label] = (state, value)

                    companions = (
                        threading.Thread(
                            target=probe_pair,
                            args=("current", failure.binding.node),
                            name="runtime-egress-current-confirmation",
                            daemon=True,
                        ),
                        threading.Thread(
                            target=probe_pair,
                            args=("alternative", alternative),
                            name="runtime-egress-alternative-confirmation",
                            daemon=True,
                        ),
                    )
                    if "current" in results:
                        companions = companions[1:]
                    for companion in companions:
                        companion.start()
                    for companion in companions:
                        pair_remaining = max(
                            0.0,
                            pair_deadline - self._runtime_recovery_now(),
                        )
                        if pair_remaining <= 0.0:
                            break
                        companion.join(timeout=pair_remaining)
                    with results_lock:
                        current_result = results.get("current")
                        alternative_result = results.get("alternative")
                    if not (
                        isinstance(current_result, tuple)
                        and isinstance(alternative_result, tuple)
                    ):
                        self._complete_runtime_early_indeterminate(
                            failure,
                            ticket,
                            probe_token=probe_token,
                            reason_code="confirmation_deadline",
                        )
                        return
                    current_state, _current_value = current_result
                    current_evidence[contract] = current_result
                    alternative_state, alternative_value = alternative_result
                    if current_state == "passed":
                        if gateway_ref is not None:
                            self._enqueue_passive_node_health_check(
                                gateway_ref, reason="gateway_runtime_error",
                            )
                        self._complete_runtime_early_indeterminate(
                            failure,
                            ticket,
                            probe_token=probe_token,
                            reason_code="current_leaf_healthy",
                        )
                        return
                    if current_state == "indeterminate" or alternative_state == "indeterminate":
                        self._complete_runtime_early_indeterminate(
                            failure,
                            ticket,
                            probe_token=probe_token,
                            reason_code="differential_indeterminate",
                        )
                        return
                    if alternative_state != "passed":
                        continue
                    action = plan.get("action")
                    alternative_evidence = (
                        _HotStandbyEvidence(
                            ref=alternative,
                            action=dict(action),
                            snapshot_key=snapshot.snapshot_key,
                            network_context_epoch=snapshot.network_context_epoch,
                            verified_at_monotonic=(
                                self._runtime_recovery_now()
                            ),
                            latency_ms=(
                                float(alternative_value.get("delay") or 0.0)
                                if isinstance(alternative_value, dict)
                                and isinstance(
                                    alternative_value.get("delay"),
                                    (int, float),
                                )
                                else 0.0
                            ),
                            probe_result=(
                                dict(alternative_value)
                                if isinstance(alternative_value, dict)
                                else {}
                            ),
                            selection_group=str(action.get("group") or ""),
                            selection_target=str(action.get("target") or ""),
                            selection_mode=str(action.get("mode") or ""),
                            probe_url=probe_url,
                            expected_status=expected_status,
                            probed_proxy_name=alternative.proxy_name,
                        )
                        if isinstance(action, dict)
                        else None
                    )
                    self._run_runtime_early_confirmed_recovery(
                        failure,
                        snapshot,
                        snapshot_payload,
                        ticket=ticket,
                        probe_token=probe_token,
                        alternative=alternative,
                        alternative_probe_result=(
                            dict(alternative_value)
                            if isinstance(alternative_value, dict)
                            else None
                        ),
                        alternative_probe_evidence=alternative_evidence,
                        startup_admission=startup_admission,
                    )
                    return
                self._enqueue_passive_node_health_check(
                    failure.binding.node, reason="runtime_alternatives_failed",
                )
                self._complete_runtime_early_indeterminate(
                    failure,
                    ticket,
                    probe_token=probe_token,
                    reason_code="differential_unproven",
                )
            finally:
                with self._runtime_failure_monitor_lock:
                    self._runtime_failure_probe_bindings.discard(key)
                    self._runtime_failure_recovery_threads.discard(
                        threading.current_thread()
                    )

        thread = threading.Thread(
            target=worker,
            name="runtime-egress-bounded-confirmation",
            daemon=True,
        )
        with self._runtime_failure_monitor_lock:
            self._runtime_failure_recovery_threads.add(thread)
        thread.start()
        return ticket

    def _start_runtime_independent_probe(
        self,
        failure: BoundRuntimeFailure,
        snapshot: CoreLoadedRouteSnapshot,
        snapshot_payload: dict[str, Any],
        *,
        probe_token: str = "",
    ) -> None:
        key = failure.circuit_key
        worker_token = self._runtime_worker_token()
        circuit_snapshot = self._runtime_egress_coordinator.current_snapshot_for(
            failure.binding
        )
        incident_id = str(
            getattr(circuit_snapshot, "incident_id", "") or ""
        )
        recovery_ticket = self._ensure_runtime_recovery_ticket(
            failure,
            snapshot,
            incident_id,
        )
        if not isinstance(recovery_ticket, _RuntimeRecoveryTicket):
            return
        incident_deadline = float(failure.observed_at_monotonic) + 6.0
        if self._runtime_facility_hold_reason():
            self._complete_runtime_recovery_hold(
                recovery_ticket,
                reason_code="facility_hold_before_origin_confirmation",
            )
            self._defer_runtime_provisional_confirmation(
                failure,
                snapshot_payload,
                incident_id=incident_id,
                probe_token=probe_token,
                reason="facility_hold_before_origin_confirmation",
            )
            return
        with self._runtime_failure_monitor_lock:
            if not self._runtime_recovery_ticket_matches_locked(
                recovery_ticket,
                require_open=True,
                deadline_monotonic=incident_deadline,
            ):
                return
            recovery_bindings = getattr(
                self,
                "_runtime_failure_recovery_bindings",
                set(),
            )
            if (
                key in recovery_bindings
                or ("provisional", *key) in recovery_bindings
            ):
                return
            probe_bindings = getattr(
                self,
                "_runtime_failure_probe_bindings",
                None,
            )
            if probe_bindings is None:
                probe_bindings = set()
                self._runtime_failure_probe_bindings = probe_bindings
            if key in probe_bindings:
                return
            probe_bindings.add(key)

        def worker() -> None:
            companion_threads: list[threading.Thread] = []
            recovery_started = False
            # Leave a bounded tail for selector PUT, authoritative readback,
            # route-epoch publication and the complete FINAL-EXIT 204.  The
            # candidate phase and commit phase share this one incident clock.
            candidate_deadline = incident_deadline - 1.75

            def direct_owner_is_current() -> bool:
                return bool(
                    self._runtime_worker_token_is_current(worker_token)
                    and self._runtime_egress_coordinator.snapshot_ownership_matches(
                        failure.binding,
                        expected_snapshot=snapshot,
                    )
                )

            def origin_owner() -> OriginDiagnosticBinding | None:
                return self._runtime_origin_diagnostic_binding_for_probe(
                    failure,
                    snapshot,
                    incident_id=incident_id,
                    probe_token=probe_token,
                    worker_token=worker_token,
                )

            def owner_is_current() -> bool:
                return bool(
                    not self._runtime_facility_hold_reason()
                    and self._runtime_recovery_ticket_is_current(
                        recovery_ticket,
                        require_open=True,
                        deadline_monotonic=incident_deadline,
                    )
                    and (
                        direct_owner_is_current()
                        or origin_owner() is not None
                    )
                )

            def current_diverted_alternative() -> RuntimeNodeRef | None:
                with self._runtime_failure_monitor_lock:
                    lease_record = self._runtime_route_mutation_lease
                    if not (
                        isinstance(lease_record, dict)
                        and str(lease_record.get("incident_id") or "")
                        == incident_id
                    ):
                        return None
                    proxy_name = str(lease_record.get("to") or "")
                return self._runtime_snapshot_node(snapshot, proxy_name)

            def record_probe_result(
                *,
                succeeded: bool,
                facility_failure: bool = False,
            ) -> RuntimeFailureCircuitDecision:
                allow_origin = bool(
                    not direct_owner_is_current() and origin_owner() is not None
                )
                with self._runtime_failure_monitor_lock:
                    if not self._runtime_recovery_ticket_matches_locked(
                        recovery_ticket,
                        require_open=True,
                        deadline_monotonic=incident_deadline,
                    ):
                        return RuntimeFailureCircuitDecision(
                            accepted=False,
                            reason="terminal_outcome_superseded_probe",
                        )
                    if self._runtime_facility_hold_reason():
                        return RuntimeFailureCircuitDecision(
                            accepted=False,
                            facility=True,
                            reason="facility_hold_superseded_probe",
                        )
                    return self._runtime_egress_coordinator.record_probe(
                        failure,
                        succeeded=succeeded,
                        facility_failure=facility_failure,
                        probe_token=probe_token,
                        current_snapshot=snapshot,
                        allow_origin_binding=allow_origin,
                    )

            def record_underlay_probe_result(
                underlay_failure: BoundRuntimeFailure,
                *,
                succeeded: bool,
                probe_token_value: str,
            ) -> RuntimeFailureCircuitDecision:
                with self._runtime_failure_monitor_lock:
                    if not self._runtime_recovery_ticket_matches_locked(
                        recovery_ticket,
                        require_open=True,
                        deadline_monotonic=incident_deadline,
                    ):
                        return RuntimeFailureCircuitDecision(
                            accepted=False,
                            reason="terminal_outcome_superseded_probe",
                        )
                    return self._runtime_egress_coordinator.record_probe(
                        underlay_failure,
                        succeeded=succeeded,
                        probe_token=probe_token_value,
                        current_snapshot=snapshot,
                    )

            def schedule_provisional_return() -> None:
                if (
                    self._runtime_facility_hold_reason()
                    or not self._runtime_recovery_ticket_is_current(
                        recovery_ticket,
                        require_open=True,
                        deadline_monotonic=incident_deadline,
                    )
                ):
                    return
                origin = origin_owner()
                if origin is None:
                    # A provisional selector write may have been rolled back
                    # before this fresh reconciliation probe started.  In that
                    # case there is deliberately no OriginDiagnosticBinding,
                    # but an exact current-leaf PASS must not leave readiness
                    # stuck at None forever.  Prove the complete FINAL-EXIT
                    # route once, then publish under the fresh snapshot/facility
                    # CAS without creating a health or selector transition.
                    if not direct_owner_is_current():
                        return
                    publish_facility_epoch = int(
                        getattr(self, "_runtime_facility_epoch", 0) or 0
                    )
                    mutation_binding = (
                        self._runtime_mutation_binding_for_snapshot(snapshot)
                    )
                    verify_seconds = self._runtime_recovery_remaining(
                        incident_deadline,
                        cap=1.5,
                    )
                    if verify_seconds <= 0.0:
                        self._complete_runtime_recovery_hold(
                            recovery_ticket,
                            reason_code="incident_budget_expired_before_final_204",
                        )
                        return
                    try:
                        verified = self._verify_runtime_final_exit(
                            expected_worker_token=worker_token,
                            expected_snapshot=snapshot,
                            timeout_seconds=verify_seconds,
                            recovery_ticket=recovery_ticket,
                            recovery_deadline_monotonic=incident_deadline,
                        )
                    except Exception:
                        self._complete_runtime_recovery_hold(
                            recovery_ticket,
                            reason_code="origin_pass_final_204_indeterminate",
                        )
                        return
                    if self._runtime_recovery_now() >= incident_deadline:
                        self._complete_runtime_recovery_hold(
                            recovery_ticket,
                            reason_code="final_204_crossed_incident_deadline",
                        )
                        return
                    published_at = self._publish_verified_incremental_egress(
                        mutation_binding=mutation_binding,
                        facility_epoch=publish_facility_epoch,
                        recovery_ticket=recovery_ticket,
                        deadline_monotonic=incident_deadline,
                    )
                    if published_at is not None:
                        self._runtime_last_verified_route = {
                            "verified_at_monotonic": published_at,
                            "incident_id": incident_id,
                            "leaf_proxy": failure.binding.node.proxy_name,
                            "route": list(failure.binding.route_chain),
                            "result": dict(verified),
                            "provisional_rollback_reconciled": True,
                        }
                        self._complete_runtime_recovery_outcome(
                            incident_id,
                            RuntimeRecoveryStatus.RECOVERED,
                            reason_code="origin_route_verified",
                            to_ref=failure.binding.node,
                            route_epoch=snapshot.route_epoch,
                            expected_ticket=recovery_ticket,
                            deadline_monotonic=incident_deadline,
                            completed_at_monotonic=published_at,
                            facts={
                                "put": False,
                                "readback": True,
                                "final_204": True,
                            },
                        )
                    return
                now = self._runtime_recovery_now()
                with self._runtime_failure_monitor_lock:
                    history_map = getattr(
                        self,
                        "_runtime_failback_pass_history",
                        None,
                    )
                    if history_map is None:
                        history_map = {}
                        self._runtime_failback_pass_history = history_map
                    history = list(history_map.get(failure.binding.node.key, []))
                    history.append(now)
                    history_map[failure.binding.node.key] = history[-4:]
                    self._runtime_incident_recovery_state[incident_id] = "ready"
                self._start_runtime_failback(
                    {
                        "incident_id": incident_id,
                        "tier": failure.binding.node.tier,
                        "pool_kind": failure.binding.node.pool_kind,
                        "identity": failure.binding.node.identity,
                        "proxy_name": failure.binding.node.proxy_name,
                        "transition": {"action": "recovered"},
                        "provisional": True,
                    },
                    failure.binding.node,
                )

            try:
                if (
                    not self._runtime_recovery_ticket_is_current(
                        recovery_ticket,
                        require_open=True,
                        deadline_monotonic=incident_deadline,
                    )
                ):
                    self._complete_runtime_recovery_hold(
                        recovery_ticket,
                        reason_code="incident_budget_expired_before_confirmation",
                    )
                    return
                if not owner_is_current():
                    self._complete_runtime_recovery_hold(
                        recovery_ticket,
                        reason_code="origin_confirmation_lost_route_authority",
                    )
                    return

                precomputed_leaf_probe_succeeded: bool | None = None
                if failure.binding.node.pool_kind == "gateway":
                    underlay = self._runtime_gateway_underlay_binding(
                        snapshot,
                        snapshot_payload,
                        failure.binding.node,
                    )
                    if underlay is None:
                        self._record_runtime_facility_degradation(
                            "Gateway dialer route could not be bound to a managed leaf"
                        )
                        self._complete_runtime_recovery_hold(
                            recovery_ticket,
                            reason_code="gateway_underlay_binding_unavailable",
                        )
                        return
                    shared_probe_url, shared_expected_status = (
                        self._runtime_group_probe_contract(snapshot, "FINAL-EXIT")
                    )
                    if (
                        urlsplit(shared_probe_url).scheme.casefold() != "https"
                        or not self._runtime_probe_contract_accepts_204(
                            shared_expected_status
                        )
                    ):
                        self._record_runtime_facility_degradation(
                            "Gateway attribution requires one shared HTTPS-204 contract"
                        )
                        self._complete_runtime_recovery_hold(
                            recovery_ticket,
                            reason_code="gateway_probe_contract_invalid",
                        )
                        return
                    gateway_remaining = self._runtime_recovery_remaining(
                        candidate_deadline
                    )
                    if gateway_remaining < 0.5:
                        self._complete_runtime_recovery_hold(
                            recovery_ticket,
                            reason_code="gateway_probe_budget_expired",
                        )
                        return
                    gateway_timeout_ms = min(
                        self._runtime_confirmation_timeout_ms(
                            failure.binding.node,
                            snapshot_payload,
                        ),
                        max(1, int(gateway_remaining * 1000.0)),
                    )
                    gateway_probe_results: queue.Queue[bool | None] = queue.Queue(
                        maxsize=1
                    )
                    gateway_probe_started = self._runtime_recovery_now()

                    def probe_gateway_leaf() -> None:
                        if not self._runtime_recovery_ticket_is_current(
                            recovery_ticket,
                            require_open=True,
                            deadline_monotonic=incident_deadline,
                        ):
                            try:
                                gateway_probe_results.put_nowait(None)
                            except queue.Full:
                                pass
                            return
                        try:
                            self._probe_runtime_leaf(
                                failure.binding.node,
                                snapshot_payload,
                                timeout_ms=gateway_timeout_ms,
                                probe_url=shared_probe_url,
                                expected_status=shared_expected_status,
                                recovery_ticket=recovery_ticket,
                                recovery_deadline_monotonic=(
                                    incident_deadline
                                ),
                            )
                        except _RuntimeProbeBudgetUnavailable:
                            succeeded = None
                        except Exception:
                            succeeded = False
                        else:
                            succeeded = True
                        try:
                            gateway_probe_results.put_nowait(succeeded)
                        except queue.Full:
                            pass

                    gateway_thread = threading.Thread(
                        target=probe_gateway_leaf,
                        name="runtime-egress-gateway-probe",
                        daemon=True,
                    )
                    companion_threads.append(gateway_thread)
                    gateway_thread.start()
                    underlay_remaining = self._runtime_recovery_remaining(
                        candidate_deadline
                    )
                    if not owner_is_current():
                        return
                    if underlay_remaining < 0.5:
                        self._complete_runtime_recovery_hold(
                            recovery_ticket,
                            reason_code="gateway_underlay_probe_budget_expired",
                        )
                        return
                    try:
                        self._probe_runtime_leaf(
                            underlay.node,
                            snapshot_payload,
                            timeout_ms=min(
                                self._runtime_confirmation_timeout_ms(
                                    underlay.node,
                                    snapshot_payload,
                                ),
                                max(
                                    1,
                                    int(
                                        underlay_remaining
                                        * 1000.0
                                    ),
                                ),
                            ),
                            probe_url=shared_probe_url,
                            expected_status=shared_expected_status,
                            recovery_ticket=recovery_ticket,
                            recovery_deadline_monotonic=incident_deadline,
                        )
                    except _RuntimeProbeBudgetUnavailable:
                        self._complete_runtime_recovery_hold(
                            recovery_ticket,
                            reason_code="gateway_underlay_probe_indeterminate",
                        )
                        return
                    except Exception:
                        if not owner_is_current():
                            return
                        underlay_failure = BoundRuntimeFailure(
                            binding=underlay,
                            protocol=failure.protocol,
                            observed_outbound=underlay.observed_outbound,
                            destination_token=failure.destination_token,
                            error_type="gateway_underlay_probe_failed",
                            observed_at_monotonic=self._runtime_recovery_now(),
                        )
                        with self._runtime_failure_monitor_lock:
                            if not self._runtime_recovery_ticket_matches_locked(
                                recovery_ticket,
                                require_open=True,
                                deadline_monotonic=incident_deadline,
                            ):
                                return
                            first = self._runtime_egress_coordinator.observe(
                                underlay_failure,
                                current_snapshot=snapshot,
                            )
                        if not owner_is_current():
                            return
                        hot_underlay = self._fresh_runtime_hot_standby(
                            underlay_failure,
                            snapshot,
                            snapshot_payload,
                        )
                        if hot_underlay is not None:
                            alternative = hot_underlay.ref
                            _alternative_result = dict(
                                hot_underlay.probe_result
                            )
                        else:
                            alternative, _alternative_result = (
                                self._probe_managed_alternative(
                                    underlay_failure,
                                    snapshot,
                                    snapshot_payload,
                                    max_parallel=1,
                                    deadline_monotonic=candidate_deadline,
                                    recovery_ticket=recovery_ticket,
                                )
                            )
                        if not owner_is_current():
                            return
                        if bool(
                            isinstance(_alternative_result, dict)
                            and _alternative_result.get("probe_indeterminate")
                        ):
                            self._complete_runtime_recovery_hold(
                                recovery_ticket,
                                reason_code="gateway_alternative_probe_indeterminate",
                            )
                            return
                        recovery_snapshot = snapshot
                        recovery_payload = snapshot_payload
                        if alternative is None:
                            (
                                rebased_snapshot,
                                rebased_payload,
                                rebase_result,
                            ) = self._try_runtime_incident_provider_rebase(
                                underlay_failure,
                                snapshot,
                                snapshot_payload,
                                recovery_ticket=recovery_ticket,
                                deadline_monotonic=candidate_deadline,
                            )
                            if rebase_result.get("attempted"):
                                if (
                                    rebased_snapshot is None
                                    or not isinstance(rebased_payload, dict)
                                ):
                                    self._complete_runtime_recovery_hold(
                                        recovery_ticket,
                                        reason_code=(
                                            "gateway_capacity_rebase_not_committed"
                                        ),
                                    )
                                    return
                                recovery_snapshot = rebased_snapshot
                                recovery_payload = rebased_payload
                                alternative, _alternative_result = (
                                    self._probe_managed_alternative(
                                        underlay_failure,
                                        recovery_snapshot,
                                        recovery_payload,
                                        max_parallel=1,
                                        deadline_monotonic=candidate_deadline,
                                        recovery_ticket=recovery_ticket,
                                    )
                                )
                                if bool(
                                    isinstance(_alternative_result, dict)
                                    and _alternative_result.get(
                                        "probe_indeterminate"
                                    )
                                ):
                                    self._complete_runtime_recovery_hold(
                                        recovery_ticket,
                                        reason_code=(
                                            "gateway_rebased_candidate_indeterminate"
                                        ),
                                    )
                                    return
                        underlay_decision = record_underlay_probe_result(
                            underlay_failure,
                            succeeded=False,
                            probe_token_value=first.probe_token,
                        )
                        if not underlay_decision.accepted:
                            return
                        if underlay_decision.confirmed and alternative is not None:
                            # The exact dialer-proxy domain now explains the
                            # failed full Gateway chain. Clear the outer
                            # Gateway suspect circuit; it is neither a Gateway
                            # strike nor a facility incident.
                            outer_decision = record_probe_result(succeeded=True)
                            if not outer_decision.accepted:
                                return
                            recovery_started = True
                            self._start_runtime_recovery(
                                underlay_failure,
                                recovery_snapshot,
                                recovery_payload,
                                incident_id=incident_id,
                                quarantine_token=probe_token,
                                confirmed_alternative=alternative,
                                confirmed_alternative_probe_result=(
                                    _alternative_result
                                ),
                                confirmed_alternative_evidence=hot_underlay,
                                incident_deadline_monotonic=incident_deadline,
                                recovery_ticket_override=recovery_ticket,
                                circuit_incident_id=(
                                    underlay_decision.incident_id
                                ),
                                circuit_quarantine_token=(
                                    underlay_decision.probe_token
                                ),
                            )
                        elif alternative is None:
                            outer_decision = record_probe_result(
                                succeeded=False,
                                facility_failure=True,
                            )
                            if not outer_decision.accepted:
                                return
                            self._record_runtime_facility_degradation(
                                "Gateway underlay and managed alternatives failed confirmation"
                            )
                            self._complete_runtime_recovery_hold(
                                recovery_ticket,
                                reason_code="gateway_no_managed_underlay_replacement",
                            )
                        return
                    try:
                        precomputed_leaf_probe_succeeded = (
                            gateway_probe_results.get(
                                timeout=min(
                                    max(
                                        0.0,
                                        1.55
                                        - (
                                            self._runtime_recovery_now()
                                            - gateway_probe_started
                                        ),
                                    ),
                                    self._runtime_recovery_remaining(
                                        candidate_deadline
                                    ),
                                )
                            )
                        )
                    except queue.Empty:
                        precomputed_leaf_probe_succeeded = None
                    if precomputed_leaf_probe_succeeded is None:
                        # A companion that did not return before its bounded
                        # deadline has no Gateway health verdict.
                        self._complete_runtime_recovery_hold(
                            recovery_ticket,
                            reason_code="gateway_probe_result_indeterminate",
                        )
                        return

                alternative_results: queue.Queue[
                    tuple[RuntimeNodeRef | None, dict[str, Any] | None]
                ] | None = None
                alternative_probe_result: dict[str, Any] | None = None
                alternative_started = 0.0
                # After a provisional diversion the already verified lease is
                # the only alternative needed to confirm the origin. Starting
                # another cold alternative thread here leaves an uncancelled
                # broker occupant when the origin quickly PASSes, starving the
                # next incident's atomic pair for up to 1.5 seconds.
                origin_was_diverted = origin_owner() is not None
                if (
                    failure.binding.node.pool_kind != "gateway"
                    and not origin_was_diverted
                ):
                    alternative_results = queue.Queue(maxsize=1)
                    alternative_started = self._runtime_recovery_now()

                    def probe_alternative() -> None:
                        if not self._runtime_recovery_ticket_is_current(
                            recovery_ticket,
                            require_open=True,
                            deadline_monotonic=incident_deadline,
                        ):
                            value = (
                                None,
                                {
                                    "probe_indeterminate": True,
                                    "reason": "terminal_outcome_superseded_probe",
                                },
                            )
                        else:
                            value = self._probe_managed_alternative(
                                failure,
                                snapshot,
                                snapshot_payload,
                                max_parallel=1,
                                deadline_monotonic=candidate_deadline,
                                recovery_ticket=recovery_ticket,
                            )
                        try:
                            alternative_results.put_nowait(value)  # type: ignore[union-attr]
                        except queue.Full:
                            pass

                    alternative_thread = threading.Thread(
                        target=probe_alternative,
                        name="runtime-egress-alternative-set",
                        daemon=True,
                    )
                    companion_threads.append(alternative_thread)
                    alternative_thread.start()

                try:
                    if precomputed_leaf_probe_succeeded is None:
                        if not owner_is_current():
                            return
                        origin_remaining = self._runtime_recovery_remaining(
                            candidate_deadline
                        )
                        if origin_remaining < 0.5:
                            self._complete_runtime_recovery_hold(
                                recovery_ticket,
                                reason_code="origin_probe_budget_expired",
                            )
                            return
                        self._probe_runtime_leaf(
                            failure.binding.node,
                            snapshot_payload,
                            timeout_ms=min(
                                self._runtime_confirmation_timeout_ms(
                                    failure.binding.node,
                                    snapshot_payload,
                                ),
                                max(1, int(origin_remaining * 1000.0)),
                            ),
                            recovery_ticket=recovery_ticket,
                            recovery_deadline_monotonic=incident_deadline,
                        )
                    elif not precomputed_leaf_probe_succeeded:
                        raise RuntimeError("Gateway leaf probe failed")
                except _RuntimeProbeBudgetUnavailable:
                    self._complete_runtime_recovery_hold(
                        recovery_ticket,
                        reason_code="origin_probe_capacity_unavailable",
                    )
                    return
                except Exception:
                    if not owner_is_current():
                        return
                    origin_is_current = origin_owner() is not None
                    alternative: RuntimeNodeRef | None = (
                        current_diverted_alternative()
                        if origin_is_current
                        else None
                    )
                    if alternative is None and alternative_results is not None:
                        remaining = max(
                            0.0,
                            candidate_deadline - self._runtime_recovery_now(),
                        )
                        try:
                            alternative, alternative_probe_result = (
                                alternative_results.get(timeout=remaining)
                            )
                        except queue.Empty:
                            alternative = None
                            alternative_probe_result = {
                                "probe_indeterminate": True
                            }
                    if bool(
                        isinstance(alternative_probe_result, dict)
                        and alternative_probe_result.get("probe_indeterminate")
                    ):
                        self._complete_runtime_recovery_hold(
                            recovery_ticket,
                            reason_code="candidate_probe_indeterminate",
                        )
                        return
                    recovery_snapshot = snapshot
                    recovery_payload = snapshot_payload
                    if alternative is None and not origin_is_current:
                        (
                            rebased_snapshot,
                            rebased_payload,
                            rebase_result,
                        ) = self._try_runtime_incident_provider_rebase(
                            failure,
                            snapshot,
                            snapshot_payload,
                            recovery_ticket=recovery_ticket,
                            deadline_monotonic=candidate_deadline,
                        )
                        if rebase_result.get("attempted"):
                            if (
                                rebased_snapshot is None
                                or not isinstance(rebased_payload, dict)
                            ):
                                self._complete_runtime_recovery_hold(
                                    recovery_ticket,
                                    reason_code="capacity_rebase_not_committed",
                                )
                                return
                            recovery_snapshot = rebased_snapshot
                            recovery_payload = rebased_payload
                            alternative, alternative_probe_result = (
                                self._probe_managed_alternative(
                                    failure,
                                    recovery_snapshot,
                                    recovery_payload,
                                    max_parallel=1,
                                    deadline_monotonic=candidate_deadline,
                                    recovery_ticket=recovery_ticket,
                                )
                            )
                            if bool(
                                isinstance(alternative_probe_result, dict)
                                and alternative_probe_result.get(
                                    "probe_indeterminate"
                                )
                            ):
                                self._complete_runtime_recovery_hold(
                                    recovery_ticket,
                                    reason_code=(
                                        "rebased_candidate_probe_indeterminate"
                                    ),
                                )
                                return
                    if not owner_is_current():
                        return
                    decision = record_probe_result(succeeded=False)
                    node_domain_confirmed = bool(
                        failure.binding.node.pool_kind == "gateway"
                        or alternative is not None
                    )
                    if decision.confirmed and node_domain_confirmed:
                        recovery_started = True
                        self._start_runtime_recovery(
                            failure,
                            recovery_snapshot,
                            recovery_payload,
                            incident_id=decision.incident_id,
                            quarantine_token=decision.probe_token,
                            confirmed_alternative=alternative,
                            already_diverted=origin_is_current,
                            confirmed_alternative_probe_result=(
                                alternative_probe_result
                            ),
                            incident_deadline_monotonic=incident_deadline,
                        )
                    elif decision.confirmed:
                        self._record_runtime_facility_degradation(
                            "Selected leaf and all managed alternatives failed; node attribution withheld"
                        )
                        self._complete_runtime_recovery_hold(
                            recovery_ticket,
                            reason_code="no_managed_replacement_available",
                        )
                    return

                if not owner_is_current():
                    return
                decision = record_probe_result(succeeded=True)
                if decision.cleared:
                    schedule_provisional_return()
                    return
                if not decision.confirmed:
                    return
                alternative: RuntimeNodeRef | None = None
                if alternative_results is not None:
                    remaining = max(
                        0.0,
                        candidate_deadline - self._runtime_recovery_now(),
                    )
                    try:
                        alternative, alternative_probe_result = (
                            alternative_results.get(timeout=remaining)
                        )
                    except queue.Empty:
                        alternative = None
                        alternative_probe_result = {
                            "probe_indeterminate": True
                        }
                if bool(
                    isinstance(alternative_probe_result, dict)
                    and alternative_probe_result.get("probe_indeterminate")
                ):
                    self._complete_runtime_recovery_hold(
                        recovery_ticket,
                        reason_code="candidate_probe_indeterminate",
                    )
                    return
                if not owner_is_current():
                    return
                node_domain_confirmed = bool(
                    failure.binding.node.pool_kind == "gateway"
                    or alternative is not None
                )
                if node_domain_confirmed:
                    recovery_started = True
                    self._start_runtime_recovery(
                        failure,
                        snapshot,
                        snapshot_payload,
                        incident_id=decision.incident_id,
                        quarantine_token=decision.probe_token,
                        confirmed_alternative=alternative,
                        already_diverted=(origin_owner() is not None),
                        confirmed_alternative_probe_result=(
                            alternative_probe_result
                        ),
                        incident_deadline_monotonic=incident_deadline,
                    )
                else:
                    self._record_runtime_facility_degradation(
                        "Business destinations failed but no managed replacement proved the leaf failure domain"
                    )
                    self._complete_runtime_recovery_hold(
                        recovery_ticket,
                        reason_code="failure_domain_unattributed",
                    )
            finally:
                # The companion socket is part of this incident's one probe
                # phase.  Keep the circuit admission claimed until its bounded
                # controller timeout returns; otherwise a fast origin PASS can
                # leave an orphan occupying the global broker while the next
                # incident starts. A brokered companion may spend up to 1.5s
                # queued and then up to 1.5s in its controller request, so the
                # ownership bound must cover both phases. Releasing after only
                # 1.6s allowed an old probe to occupy a slot in the next
                # incident and reproduce the apparent permanent lock.  Never
                # join past the same six-second incident transaction.
                for companion in companion_threads:
                    if companion is threading.current_thread():
                        continue
                    companion.join(
                        timeout=max(
                            0.0,
                            incident_deadline - self._runtime_recovery_now(),
                        )
                    )
                if self._runtime_facility_hold_reason():
                    self._defer_runtime_provisional_confirmation(
                        failure,
                        snapshot_payload,
                        incident_id=incident_id,
                        probe_token=probe_token,
                        reason="facility_hold_crossed_origin_confirmation",
                    )
                    self._complete_runtime_recovery_hold(
                        recovery_ticket,
                        reason_code="facility_hold_crossed_origin_confirmation",
                    )
                elif (
                    isinstance(recovery_ticket, _RuntimeRecoveryTicket)
                    and self._runtime_recovery_now() >= incident_deadline
                ):
                    self._complete_runtime_recovery_hold(
                        recovery_ticket,
                        reason_code="incident_budget_expired",
                    )
                elif (
                    not recovery_started
                    and isinstance(recovery_ticket, _RuntimeRecoveryTicket)
                    and self._runtime_recovery_ticket_is_current(
                        recovery_ticket,
                        require_open=True,
                    )
                ):
                    self._complete_runtime_recovery_hold(
                        recovery_ticket,
                        reason_code="confirmation_ended_without_authoritative_result",
                    )
                with self._runtime_failure_monitor_lock:
                    self._runtime_failure_probe_bindings.discard(key)

        threading.Thread(
            target=worker,
            name="runtime-egress-neutral-confirmation",
            daemon=True,
        ).start()

    def _current_runtime_failure_binding_state(
        self,
        *,
        timeout_seconds: float | None = None,
        refresh: bool = True,
    ) -> tuple[RuntimeRouteBinding, CoreLoadedRouteSnapshot, dict[str, Any]] | None:
        # Guard/manual signals do not carry a stdout-time binding. Refresh the
        # controller selection unconditionally so an automatic fallback that
        # happened since the last snapshot cannot make us penalize its former
        # leaf (or whichever leaf took over later).
        if refresh:
            try:
                try:
                    self._refresh_runtime_route_snapshot(
                        timeout_seconds=timeout_seconds
                    )
                except TypeError:
                    self._refresh_runtime_route_snapshot()
            except Exception:
                return None
        snapshot, payload = self._runtime_route_snapshot_state()
        if snapshot is None or payload is None:
            return None
        coordinator_snapshot = self._runtime_egress_coordinator.current_route_snapshot()
        if (
            coordinator_snapshot is None
            or coordinator_snapshot.snapshot_key != snapshot.snapshot_key
        ):
            return None
        binding = self._runtime_route_binding_for_outbound(
            snapshot,
            payload,
            "FINAL-EXIT",
        )
        if binding is None:
            return None
        return binding, snapshot, payload

    def _runtime_mutation_binding_for_snapshot(
        self,
        snapshot: CoreLoadedRouteSnapshot,
    ) -> CurrentMutationBinding:
        return CurrentMutationBinding(
            snapshot_key=tuple(snapshot.snapshot_key),
            route_epoch=int(snapshot.route_epoch),
            network_context_epoch=int(snapshot.network_context_epoch),
            facility_epoch=int(
                getattr(self, "_runtime_facility_epoch", 0) or 0
            ),
            selector_intent_revision=int(
                getattr(self, "_runtime_selector_intent_revision", 0) or 0
            ),
        )

    def _runtime_mutation_binding_is_current(
        self,
        binding: CurrentMutationBinding,
    ) -> bool:
        if not isinstance(binding, CurrentMutationBinding):
            return False
        coordinator = getattr(self, "_runtime_egress_coordinator", None)
        current_snapshot = getattr(coordinator, "current_route_snapshot", None)
        if not callable(current_snapshot):
            return False
        snapshot = current_snapshot()
        if snapshot is None or tuple(snapshot.snapshot_key) != tuple(
            binding.snapshot_key
        ):
            return False
        with self._runtime_route_snapshot_lock:
            route_epoch = int(getattr(self, "_runtime_route_epoch", 0) or 0)
            network_epoch = int(
                getattr(self, "_runtime_network_context_epoch", 0) or 0
            )
        return bool(
            route_epoch == int(binding.route_epoch)
            and network_epoch == int(binding.network_context_epoch)
            and int(getattr(self, "_runtime_facility_epoch", 0) or 0)
            == int(binding.facility_epoch)
            and int(
                getattr(self, "_runtime_selector_intent_revision", 0) or 0
            )
            == int(binding.selector_intent_revision)
        )

    def _log_runtime_recovery_phase(
        self,
        phase: str,
        *,
        ticket: _RuntimeRecoveryTicket | None = None,
        outcome: RuntimeRecoveryOutcome | None = None,
        candidate: RuntimeNodeRef | None = None,
        candidate_index: int | None = None,
        candidate_total: int | None = None,
        budget_ms: int | None = None,
        reason_code: str = "",
        facts: dict[str, Any] | None = None,
    ) -> None:
        """Emit one privacy-safe structured recovery diagnostic."""

        logger = getattr(self, "logger", None)
        if logger is None:
            return
        diag_ticket = self._node_judgement_arm_permit()
        payload: dict[str, Any] = {
            "phase": str(phase or "unknown"),
            "incident_hash": (
                runtime_identity_hash(ticket.incident_id)
                if ticket is not None and ticket.incident_id
                else ""
            ),
            "route_epoch": int(
                ticket.route_epoch
                if ticket is not None
                else getattr(self, "_runtime_route_epoch", 0) or 0
            ),
            "reason_code": str(reason_code or ""),
        }
        payload["origin"] = "post_dial" if ticket is not None and str(ticket.incident_id).startswith("post-dial-") else "recovery"
        if candidate is not None:
            payload["candidate_hash"] = runtime_identity_hash(
                "\0".join(str(item) for item in candidate.key)
            )
            payload["candidate_tier"] = str(candidate.tier)
            payload["candidate_pool_kind"] = str(candidate.pool_kind)
        if candidate_index is not None:
            payload["candidate_index"] = int(candidate_index)
        if candidate_total is not None:
            payload["candidate_total"] = int(candidate_total)
        if budget_ms is not None:
            payload["budget_ms"] = max(0, int(budget_ms))
        if isinstance(facts, dict):
            for key, value in facts.items():
                if key in {
                    "put",
                    "readback",
                    "final_204",
                    "health_revision",
                    "result",
                }:
                    payload[str(key)] = value
        if outcome is not None:
            payload["outcome"] = outcome.to_dict()
        logger.info(
            "Runtime recovery phase completed",
            extra={
                "event_key": "routing.runtime_recovery",
                "category": "routing",
                "event_params": payload,
                "runtime_recovery_event": payload,
                "event_match_kind": "event_key",
                "is_key_event": phase == "terminal",
                "log_source": "TESSERACT",
            },
        )

        if diag_ticket is not None:
            self._node_judgement_arm_submit({"ev": "recovery_phase", "origin": payload["origin"],
                "phase": str(phase or "unknown"), "incident": payload["incident_hash"],
                "reason": str(reason_code) if str(reason_code) in {
                    "post_dial_native_rebind", "post_dial_native_commit", "post_dial_authority_changed",
                    "post_dial_unjudged", "post_dial_superseded", "post_dial_aborted", "committed",
                    "recovered", "superseded", "deadline_exhausted", "controller_hold",
                } else "none" if not reason_code else "reason-" + runtime_identity_hash(str(reason_code))}, ticket=diag_ticket)

    def _runtime_recovery_authority_key(
        self,
        snapshot: CoreLoadedRouteSnapshot,
    ) -> tuple[Any, ...]:
        """Return the material authority revision that may reopen a ticket."""

        if not (
            hasattr(self, "_core_lifecycle_lock")
            and hasattr(self, "_runtime_route_snapshot_lock")
        ):
            # Compatibility for narrow pure-recovery fixtures. Production
            # always uses the complete activation key below.
            return (
                "snapshot",
                tuple(snapshot.snapshot_key),
                int(getattr(self, "_runtime_selector_intent_revision", 0) or 0),
            )
        return ("activation", *self._tier3_standby_activation_key())

    def _register_runtime_recovery_ticket(
        self,
        failure: BoundRuntimeFailure,
        snapshot: CoreLoadedRouteSnapshot,
        incident_id: str,
        *,
        force_rebind: bool = False,
        deadline_monotonic: float | None = None,
        window_s: float = 6.0,
    ) -> _RuntimeRecoveryTicket:
        incident_id = str(incident_id)
        snapshot_key = tuple(snapshot.snapshot_key)
        from_ref = failure.binding.node
        observed_at = float(failure.observed_at_monotonic)
        route_epoch = int(failure.binding.route_epoch)
        facility_epoch = int(getattr(self, "_runtime_facility_epoch", 0) or 0)
        selector_intent_revision = int(
            getattr(self, "_runtime_selector_intent_revision", 0) or 0
        )
        worker_token = tuple(self._runtime_worker_token())
        authority_key = self._runtime_recovery_authority_key(snapshot)
        with self._runtime_failure_monitor_lock:
            tickets = getattr(self, "_runtime_recovery_tickets", None)
            if not isinstance(tickets, dict):
                tickets = {}
                self._runtime_recovery_tickets = tickets
            outcomes = getattr(self, "_runtime_recovery_outcomes", None)
            if not isinstance(outcomes, dict):
                outcomes = {}
                self._runtime_recovery_outcomes = outcomes
            events = getattr(self, "_runtime_recovery_outcome_events", None)
            if not isinstance(events, dict):
                events = {}
                self._runtime_recovery_outcome_events = events
            existing = tickets.get(incident_id)
            if (
                isinstance(existing, _RuntimeRecoveryTicket)
                and existing.snapshot_key == snapshot_key
                and existing.from_ref.key == from_ref.key
                and not force_rebind
            ):
                return existing
            revision = int(
                getattr(self, "_runtime_recovery_ticket_revision", 0) or 0
            ) + 1
            self._runtime_recovery_ticket_revision = revision
            ticket = _RuntimeRecoveryTicket(
                generation=revision,
                incident_id=incident_id,
                observed_at_monotonic=observed_at,
                deadline_monotonic=min(
                    observed_at + window_s,
                    float(deadline_monotonic)
                    if deadline_monotonic is not None
                    else observed_at + window_s,
                ),
                snapshot_key=snapshot_key,
                route_epoch=route_epoch,
                facility_epoch=facility_epoch,
                selector_intent_revision=selector_intent_revision,
                worker_token=worker_token,
                from_ref=from_ref,
                authority_key=authority_key,
            )
            # An incident may only carry a terminal outcome for the exact route
            # binding that registered it.  Rebinding the identifier must not let
            # a late waiter observe the previous route's READY/fail-closed state.
            old_event = events.get(ticket.incident_id)
            if isinstance(old_event, threading.Event):
                old_event.set()
            outcomes.pop(ticket.incident_id, None)
            if force_rebind:
                states = getattr(
                    self,
                    "_runtime_incident_recovery_state",
                    None,
                )
                if isinstance(states, dict):
                    states.pop(ticket.incident_id, None)
            tickets[ticket.incident_id] = ticket
            events[ticket.incident_id] = threading.Event()
            if len(tickets) > 256:
                for old_incident in tuple(tickets):
                    if old_incident == ticket.incident_id:
                        continue
                    if old_incident in outcomes:
                        tickets.pop(old_incident, None)
                        outcomes.pop(old_incident, None)
                        events.pop(old_incident, None)
                    if len(tickets) <= 192:
                        break
        self._log_runtime_recovery_phase("incident_bound", ticket=ticket)
        return ticket

    def _runtime_recovery_ticket_matches_locked(
        self,
        ticket: _RuntimeRecoveryTicket | None,
        *,
        require_open: bool = False,
        deadline_monotonic: float | None = None,
        allow_recovered_terminal: bool = False,
    ) -> bool:
        """Check one ticket while the failure-monitor lock is held.

        Probe admission, circuit mutation and health writeback use this same
        predicate under one lock.  That closes the window where a terminal
        controller/facility outcome could be committed after a caller checked
        it but before a late probe changed the circuit or node overlay.
        """

        if not isinstance(ticket, _RuntimeRecoveryTicket):
            return False
        tickets = getattr(self, "_runtime_recovery_tickets", {})
        current = (
            tickets.get(ticket.incident_id)
            if isinstance(tickets, dict)
            else None
        )
        if not (
            isinstance(current, _RuntimeRecoveryTicket)
            and current.generation == ticket.generation
        ):
            return False
        if require_open:
            outcomes = getattr(self, "_runtime_recovery_outcomes", {})
            outcome = (
                outcomes.get(ticket.incident_id)
                if isinstance(outcomes, dict)
                else None
            )
            if isinstance(outcome, RuntimeRecoveryOutcome) and not (
                allow_recovered_terminal
                and outcome.status is RuntimeRecoveryStatus.RECOVERED
            ):
                return False
        deadline = float(ticket.deadline_monotonic)
        if deadline_monotonic is not None:
            deadline = min(deadline, float(deadline_monotonic))
        return self._runtime_recovery_now() < deadline

    def _runtime_recovery_ticket_is_current(
        self,
        ticket: _RuntimeRecoveryTicket | None,
        *,
        require_open: bool = False,
        deadline_monotonic: float | None = None,
        allow_recovered_terminal: bool = False,
    ) -> bool:
        with self._runtime_failure_monitor_lock:
            return self._runtime_recovery_ticket_matches_locked(
                ticket,
                require_open=require_open,
                deadline_monotonic=deadline_monotonic,
                allow_recovered_terminal=allow_recovered_terminal,
            )

    def _mark_runtime_recovery_quarantined(
        self,
        binding: RuntimeRouteBinding,
        *,
        recovery_ticket: _RuntimeRecoveryTicket,
        coordinator_incident_id: str,
        coordinator_quarantine_token: str,
        deadline_monotonic: float,
        allow_recovered_terminal: bool = False,
    ) -> bool:
        """Order a circuit mutation before the incident's terminal result."""

        with self._runtime_failure_monitor_lock:
            if not self._runtime_recovery_ticket_matches_locked(
                recovery_ticket,
                require_open=True,
                deadline_monotonic=deadline_monotonic,
                allow_recovered_terminal=allow_recovered_terminal,
            ):
                return False
            self._runtime_egress_coordinator.mark_quarantined(
                binding,
                ttl_seconds=30.0,
                incident_id=str(coordinator_incident_id),
                quarantine_token=str(coordinator_quarantine_token),
            )
            return True

    def _admit_runtime_fail_closed_mutation(
        self,
        ticket: _RuntimeRecoveryTicket,
        *,
        deadline_monotonic: float,
        failure_binding: RuntimeRouteBinding | None = None,
        gateway_failure_confirmed: bool = False,
        expected_facility_epoch: int | None = None,
    ) -> bool:
        """Linearize physical REJECT/Core-stop before any competing hold."""

        with self._runtime_failure_monitor_lock:
            if not self._runtime_physical_fail_closed_allowed(
                failure_binding,
                gateway_failure_confirmed=gateway_failure_confirmed,
            ):
                return False
            if (
                expected_facility_epoch is not None
                and int(getattr(self, "_runtime_facility_epoch", 0) or 0)
                != int(expected_facility_epoch)
            ):
                return False
            if not self._runtime_recovery_ticket_matches_locked(
                ticket,
                require_open=True,
                deadline_monotonic=deadline_monotonic,
            ):
                return False
            admissions = getattr(
                self,
                "_runtime_fail_closed_admissions",
                None,
            )
            if not isinstance(admissions, dict):
                admissions = {}
                self._runtime_fail_closed_admissions = admissions
            existing = admissions.get(ticket.incident_id)
            if existing is not None and int(existing) != ticket.generation:
                return False
            admissions[ticket.incident_id] = ticket.generation
            return True

    def _release_runtime_fail_closed_admission(
        self,
        ticket: _RuntimeRecoveryTicket,
    ) -> None:
        with self._runtime_failure_monitor_lock:
            admissions = getattr(
                self,
                "_runtime_fail_closed_admissions",
                None,
            )
            if (
                isinstance(admissions, dict)
                and int(admissions.get(ticket.incident_id, -1))
                == ticket.generation
            ):
                admissions.pop(ticket.incident_id, None)

    def _ensure_runtime_recovery_ticket(
        self,
        failure: BoundRuntimeFailure,
        snapshot: CoreLoadedRouteSnapshot,
        incident_id: str,
        *,
        deadline_monotonic: float | None = None,
        window_s: float = 6.0,
    ) -> _RuntimeRecoveryTicket | None:
        incident_id = str(incident_id or "")
        if not incident_id:
            return None
        with self._runtime_failure_monitor_lock:
            tickets = getattr(self, "_runtime_recovery_tickets", {})
            existing = (
                tickets.get(incident_id)
                if isinstance(tickets, dict)
                else None
            )
            if (
                isinstance(existing, _RuntimeRecoveryTicket)
                and existing.snapshot_key == tuple(snapshot.snapshot_key)
                and existing.from_ref.key == failure.binding.node.key
            ):
                return existing
        if float(window_s) != 6.0:
            # Tier ladder only (spec §4.5); the default call stays unchanged.
            return self._register_runtime_recovery_ticket(
                failure,
                snapshot,
                incident_id,
                deadline_monotonic=deadline_monotonic,
                window_s=window_s,
            )
        return self._register_runtime_recovery_ticket(
            failure,
            snapshot,
            incident_id,
            deadline_monotonic=deadline_monotonic,
        )

    def _complete_runtime_recovery_hold(
        self,
        ticket: _RuntimeRecoveryTicket | None,
        *,
        reason_code: str,
    ) -> RuntimeRecoveryOutcome | None:
        """Map missing authority to one explicit non-recovered terminal state."""

        if not isinstance(ticket, _RuntimeRecoveryTicket):
            return None
        if int(
            getattr(self, "_runtime_selector_intent_revision", 0) or 0
        ) != int(ticket.selector_intent_revision):
            status = RuntimeRecoveryStatus.MANUAL_SUPERSEDED
            reason = "selector_intent_changed"
        elif (
            int(getattr(self, "_runtime_facility_epoch", 0) or 0)
            != int(ticket.facility_epoch)
            or bool(self._runtime_facility_hold_reason())
        ):
            status = RuntimeRecoveryStatus.FACILITY_HOLD
            reason = "facility_epoch_changed"
        elif not self._runtime_worker_token_is_current(ticket.worker_token):
            status = RuntimeRecoveryStatus.STALE
            reason = "runtime_generation_changed"
        else:
            status = RuntimeRecoveryStatus.CONTROLLER_HOLD
            reason = str(reason_code or "authoritative_recovery_indeterminate")
        return self._complete_runtime_recovery_outcome(
            ticket.incident_id,
            status,
            reason_code=reason,
            expected_ticket=ticket,
        )

    def _complete_runtime_recovery_outcome(
        self,
        incident_id: str,
        status: RuntimeRecoveryStatus | str,
        *,
        reason_code: str,
        to_ref: RuntimeNodeRef | None = None,
        route_epoch: int | None = None,
        expected_ticket: _RuntimeRecoveryTicket | None = None,
        deadline_monotonic: float | None = None,
        completed_at_monotonic: float | None = None,
        facts: dict[str, Any] | None = None,
    ) -> RuntimeRecoveryOutcome | None:
        incident_id = str(incident_id or "")
        if not incident_id or not isinstance(
            expected_ticket,
            _RuntimeRecoveryTicket,
        ):
            return None
        normalized_status = (
            status
            if isinstance(status, RuntimeRecoveryStatus)
            else RuntimeRecoveryStatus(str(status))
        )
        with self._runtime_failure_monitor_lock:
            tickets = getattr(self, "_runtime_recovery_tickets", {})
            ticket = tickets.get(incident_id) if isinstance(tickets, dict) else None
            if not isinstance(ticket, _RuntimeRecoveryTicket):
                return None
            if ticket.generation != expected_ticket.generation:
                return None
            outcomes = getattr(self, "_runtime_recovery_outcomes", None)
            if not isinstance(outcomes, dict):
                outcomes = {}
                self._runtime_recovery_outcomes = outcomes
            existing = outcomes.get(incident_id)
            if isinstance(existing, RuntimeRecoveryOutcome):
                return existing
            admissions = getattr(
                self,
                "_runtime_fail_closed_admissions",
                {},
            )
            admitted_generation = (
                admissions.get(incident_id)
                if isinstance(admissions, dict)
                else None
            )
            if (
                admitted_generation is not None
                and int(admitted_generation) == ticket.generation
                and normalized_status is not RuntimeRecoveryStatus.FAIL_CLOSED
            ):
                # The physical mutation won the monitor-lock admission CAS.
                # A concurrent activation waiter must observe its result (or
                # the later explicit indeterminate release), never publish a
                # controller hold in the gap before selector/Core readback.
                return None
            now = self._runtime_recovery_now()
            terminal_at = (
                now
                if completed_at_monotonic is None
                else float(completed_at_monotonic)
            )
            if (
                not math.isfinite(terminal_at)
                or terminal_at < ticket.observed_at_monotonic
                or terminal_at > now
            ):
                terminal_at = now
            effective_deadline = float(ticket.deadline_monotonic)
            if deadline_monotonic is not None:
                effective_deadline = min(
                    effective_deadline,
                    float(deadline_monotonic),
                )
            effective_reason = str(
                reason_code or "runtime_recovery_terminal"
            )
            effective_facts = dict(facts or {})
            if (
                normalized_status is RuntimeRecoveryStatus.FAIL_CLOSED
                and ticket.from_ref.pool_kind != "gateway"
            ):
                normalized_status = RuntimeRecoveryStatus.CONTROLLER_HOLD
                effective_reason = "non_gateway_fail_closed_blocked"
                to_ref = None
                effective_facts = {}
            if (
                normalized_status is RuntimeRecoveryStatus.RECOVERED
                and terminal_at >= effective_deadline
            ):
                normalized_status = RuntimeRecoveryStatus.CONTROLLER_HOLD
                effective_reason = "incident_budget_expired"
                to_ref = None
                effective_facts = {}
            elapsed_ms = max(
                0,
                int(
                    min(
                        6.0,
                        terminal_at - ticket.observed_at_monotonic,
                    )
                    * 1000.0
                ),
            )
            outcome = RuntimeRecoveryOutcome(
                status=normalized_status,
                incident_id=incident_id,
                route_epoch=int(
                    route_epoch
                    if route_epoch is not None
                    else getattr(self, "_runtime_route_epoch", ticket.route_epoch)
                    or 0
                ),
                budget_ms=elapsed_ms,
                reason=effective_reason,
                from_ref=ticket.from_ref,
                to_ref=to_ref,
            )
            outcomes[incident_id] = outcome
            events = getattr(self, "_runtime_recovery_outcome_events", None)
            if not isinstance(events, dict):
                events = {}
                self._runtime_recovery_outcome_events = events
            event = events.setdefault(incident_id, threading.Event())
            event.set()
        self._log_runtime_recovery_phase(
            "terminal",
            ticket=ticket,
            outcome=outcome,
            budget_ms=outcome.budget_ms,
            reason_code=effective_reason,
            facts={
                "put": bool(effective_facts.get("put")),
                "readback": bool(effective_facts.get("readback")),
                "final_204": bool(effective_facts.get("final_204")),
                "result": outcome.status.value,
            },
        )
        binding = getattr(self, "_runtime_incident_bindings", {}).get(
            incident_id
        )
        if isinstance(binding, RuntimeRouteBinding):
            try:
                circuit = self._runtime_egress_coordinator.current_snapshot_for(
                    binding
                )
                quarantine_token = str(
                    getattr(circuit, "probe_token", "") or ""
                )
                if quarantine_token:
                    self._runtime_egress_coordinator.mark_terminal_outcome(
                        binding,
                        outcome,
                        quarantine_token=quarantine_token,
                    )
            except Exception:
                log_raw_diagnostic(
                    self.logger,
                    "warning",
                    "Could not freeze runtime recovery terminal outcome",
                    exc_info=True,
                )
        return outcome

    def _runtime_recovery_ref_for_proxy(
        self,
        proxy_name: str,
    ) -> RuntimeNodeRef | None:
        try:
            snapshot, _payload = self._runtime_route_snapshot_state()
        except (AttributeError, TypeError):
            # Narrow recovery fixtures may omit the controller snapshot; the
            # outcome status remains valid and ``to_ref`` is optional.
            return None
        if snapshot is None:
            return None
        return self._runtime_snapshot_node(snapshot, str(proxy_name or ""))

    def _wait_runtime_recovery_outcome(
        self,
        ticket: _RuntimeRecoveryTicket,
    ) -> RuntimeRecoveryOutcome | None:
        """Wait outside route/Core locks for this incident's six-state result."""

        while True:
            inferred: tuple[RuntimeRecoveryStatus, str, RuntimeNodeRef | None] | None = None
            inferred_completed_at: float | None = None
            inferred_deadline: float | None = None
            rebound = False
            with self._runtime_failure_monitor_lock:
                tickets = getattr(self, "_runtime_recovery_tickets", {})
                current_ticket = (
                    tickets.get(ticket.incident_id)
                    if isinstance(tickets, dict)
                    else None
                )
                rebound = bool(
                    not isinstance(current_ticket, _RuntimeRecoveryTicket)
                    or current_ticket.generation != ticket.generation
                )
                outcomes = getattr(self, "_runtime_recovery_outcomes", {})
                outcome = outcomes.get(ticket.incident_id) if isinstance(outcomes, dict) else None
                if not rebound and isinstance(outcome, RuntimeRecoveryOutcome):
                    return outcome
                states = getattr(self, "_runtime_incident_recovery_state", {})
                state = str(states.get(ticket.incident_id) or "") if isinstance(states, dict) else ""
                lease = getattr(self, "_runtime_route_mutation_lease", None)
                owners = getattr(self, "_runtime_core_stopped_recovery_owners", {})
                if (
                    isinstance(lease, dict)
                    and str(lease.get("incident_id") or "") == ticket.incident_id
                    and int(
                        lease.get(
                            "recovery_ticket_generation",
                            0,
                        )
                        or 0
                    )
                    == ticket.generation
                    and float(lease.get("verified_at_monotonic") or 0.0) > 0.0
                    and (
                        str(lease.get("to") or "") == "REJECT"
                        or not bool(lease.get("provisional"))
                    )
                ):
                    target = str(lease.get("to") or "")
                    inferred_completed_at = float(
                        lease.get("verified_at_monotonic") or 0.0
                    )
                    inferred_deadline = min(
                        float(ticket.deadline_monotonic),
                        float(
                            lease.get("recovery_deadline_monotonic")
                            or ticket.deadline_monotonic
                        ),
                    )
                    if (
                        target == "REJECT"
                        or inferred_completed_at < inferred_deadline
                    ):
                        inferred = (
                            RuntimeRecoveryStatus.FAIL_CLOSED
                            if target == "REJECT"
                            else RuntimeRecoveryStatus.RECOVERED,
                            "verified_reject"
                            if target == "REJECT"
                            else "verified_route",
                            None,
                        )
                elif (
                    isinstance(owners, dict)
                    and ticket.incident_id in owners
                    and isinstance(owners[ticket.incident_id], dict)
                    and int(
                        owners[ticket.incident_id].get(
                            "recovery_ticket_generation",
                            0,
                        )
                        or 0
                    )
                    == ticket.generation
                ):
                    inferred_completed_at = float(
                        owners[ticket.incident_id].get(
                            "fail_closed_at_monotonic",
                            0.0,
                        )
                        or 0.0
                    )
                    inferred = (
                        RuntimeRecoveryStatus.FAIL_CLOSED,
                        "verified_core_stop",
                        None,
                    )
                elif state == "manual_superseded":
                    inferred = (
                        RuntimeRecoveryStatus.MANUAL_SUPERSEDED,
                        "selector_intent_changed",
                        None,
                    )
                elif state in {"route_superseded", "stale"}:
                    inferred = (
                        RuntimeRecoveryStatus.STALE,
                        "route_authority_changed",
                        None,
                    )
                events = getattr(self, "_runtime_recovery_outcome_events", {})
                event = events.get(ticket.incident_id) if isinstance(events, dict) else None
            if rebound:
                return RuntimeRecoveryOutcome(
                    status=RuntimeRecoveryStatus.STALE,
                    incident_id=ticket.incident_id,
                    route_epoch=ticket.route_epoch,
                    budget_ms=max(
                        0,
                        int(
                            min(
                                6.0,
                                self._runtime_recovery_now()
                                - ticket.observed_at_monotonic,
                            )
                            * 1000.0
                        ),
                    ),
                    reason="ticket_rebound",
                    from_ref=ticket.from_ref,
                )
            if inferred is not None:
                status, reason_code, _unused_ref = inferred
                to_ref = None
                if status is RuntimeRecoveryStatus.RECOVERED and isinstance(lease, dict):
                    to_ref = self._runtime_recovery_ref_for_proxy(
                        str(lease.get("to") or "")
                    )
                completed = self._complete_runtime_recovery_outcome(
                    ticket.incident_id,
                    status,
                    reason_code=reason_code,
                    to_ref=to_ref,
                    expected_ticket=ticket,
                    deadline_monotonic=inferred_deadline,
                    completed_at_monotonic=inferred_completed_at,
                    facts={
                        "put": reason_code in {"verified_route", "verified_reject"},
                        "readback": reason_code in {"verified_route", "verified_reject"},
                        "final_204": status is RuntimeRecoveryStatus.RECOVERED,
                    },
                )
                if completed is not None:
                    return completed
                # A physical fail-closed mutation may already own this
                # incident.  In that case completion is deliberately
                # deferred until its REJECT/Core-stop truth is committed.
                completion_deferred = True
            else:
                completion_deferred = False

            pending_status: RuntimeRecoveryStatus | None = None
            pending_reason = ""
            if not completion_deferred:
                if int(
                    getattr(self, "_runtime_selector_intent_revision", 0) or 0
                ) != int(ticket.selector_intent_revision):
                    pending_status = RuntimeRecoveryStatus.MANUAL_SUPERSEDED
                    pending_reason = "selector_intent_changed"
                elif (
                    not self._runtime_uses_early_single_coordinator()
                    and (
                        int(getattr(self, "_runtime_facility_epoch", 0) or 0)
                        != int(ticket.facility_epoch)
                        or bool(self._runtime_facility_hold_reason())
                    )
                ):
                    pending_status = RuntimeRecoveryStatus.FACILITY_HOLD
                    pending_reason = "facility_epoch_changed"
                elif not self._runtime_worker_token_is_current(
                    ticket.worker_token
                ):
                    pending_status = RuntimeRecoveryStatus.STALE
                    pending_reason = "runtime_generation_changed"
                elif (
                    not self._runtime_uses_early_single_coordinator()
                    and self._runtime_node_attribution_hold_reason()
                ):
                    pending_status = RuntimeRecoveryStatus.CONTROLLER_HOLD
                    pending_reason = "controller_authority_unavailable"
            if pending_status is not None:
                completed = self._complete_runtime_recovery_outcome(
                    ticket.incident_id,
                    pending_status,
                    reason_code=pending_reason,
                    expected_ticket=ticket,
                )
                if completed is not None:
                    return completed
                completion_deferred = True

            remaining = ticket.deadline_monotonic - self._runtime_recovery_now()
            if remaining <= 0.0 and not completion_deferred:
                completed = self._complete_runtime_recovery_outcome(
                    ticket.incident_id,
                    RuntimeRecoveryStatus.CONTROLLER_HOLD,
                    reason_code="incident_budget_expired",
                    expected_ticket=ticket,
                )
                if completed is not None:
                    return completed
                completion_deferred = True

            wait_seconds = (
                0.05
                if completion_deferred
                else min(0.05, max(0.0, remaining))
            )
            if isinstance(event, threading.Event):
                event.wait(wait_seconds)
            else:
                time.sleep(wait_seconds)

    def _submit_current_route_probe_failure_early(
        self,
        reason: str,
        *,
        source: str,
        binding_state: tuple[
            RuntimeRouteBinding,
            CoreLoadedRouteSnapshot,
            dict[str, Any],
        ] | None,
        binding_captured: bool,
        activation_owner: _RuntimeActivationRecoveryOwner | None,
    ) -> bool | _RuntimeRecoveryTicket:
        # The rollback profile deliberately has no application-level automatic
        # failover authority.  Startup and manual validation are finite
        # data-plane checks and never enter the old incident coordinator.
        del (
            reason,
            source,
            binding_state,
            binding_captured,
            activation_owner,
        )
        return False

    def _submit_current_route_probe_failure(
        self,
        reason: str,
        *,
        source: str = "runtime_probe",
        binding_state: tuple[
            RuntimeRouteBinding,
            CoreLoadedRouteSnapshot,
            dict[str, Any],
        ] | None = None,
        binding_captured: bool = False,
        activation_owner: _RuntimeActivationRecoveryOwner | None = None,
    ) -> bool | _RuntimeRecoveryTicket:
        if self._runtime_uses_early_single_coordinator():
            return self._submit_current_route_probe_failure_early(
                reason,
                source=str(source or "runtime_probe"),
                binding_state=binding_state,
                binding_captured=bool(binding_captured),
                activation_owner=activation_owner,
            )
        activation_submission = bool(
            str(source or "") == "activation_final_exit"
            and isinstance(
                activation_owner,
                _RuntimeActivationRecoveryOwner,
            )
        )
        if not self._runtime_recovery_is_armed() and not activation_submission:
            if self._runtime_initial_activation_complete():
                self._queue_runtime_route_snapshot_refresh()
            return False
        facility_hold = self._runtime_facility_hold_reason()
        if facility_hold:
            self._record_runtime_facility_degradation(
                f"{facility_hold}; {reason}"
            )
            self._queue_runtime_route_snapshot_refresh()
            return False
        if self._runtime_node_attribution_hold_reason():
            self._queue_runtime_route_snapshot_refresh()
            return False
        # Manual/guard probes have already failed on the data plane. Submit
        # against the most recent immutable loaded binding immediately; a
        # controller refresh is queued separately and can only invalidate the
        # incident through the normal snapshot CAS.
        if binding_state is not None:
            supplied_binding, supplied_snapshot, _supplied_payload = binding_state
            if not self._runtime_egress_coordinator.snapshot_ownership_matches(
                supplied_binding,
                expected_snapshot=supplied_snapshot,
            ):
                # Explicit evidence is a CAS contract, not a hint. If its
                # ownership has already moved from A to B, attributing the old
                # A failure to the current B leaf would create a false incident.
                self._queue_runtime_route_snapshot_refresh()
                return False
            state = binding_state
        elif binding_captured:
            # The caller froze authority before starting its probe but could
            # not obtain a complete binding. Never replace that absence with
            # whichever leaf happens to be current after the request fails.
            state = None
        else:
            state = self._current_runtime_failure_binding_state(refresh=False)
        if state is None:
            unavailable_reason = (
                f"{reason}: current FINAL-EXIT route is not stably bound"
            )
            if str(source or "") in {
                "manual_exit_quality",
                "proxy_delay",
                "stdout_guard",
                "replacement_verification",
            }:
                # These callers arrive only after their own neutral/proxy
                # data-plane request has already failed.
                self._record_runtime_facility_degradation(unavailable_reason)
            else:
                self._start_runtime_facility_confirmation(unavailable_reason)
            self._queue_runtime_route_snapshot_refresh()
            return False
        binding, snapshot, payload = state
        if activation_submission and not self._runtime_activation_recovery_owner_is_current(
            activation_owner,
            binding=binding,
            snapshot=snapshot,
        ):
            return False
        observed = time.monotonic()
        token = hashlib.sha256(
            f"{source}\0{binding.circuit_key!r}\0{time.monotonic_ns()}".encode(
                "utf-8"
            )
        ).hexdigest()
        failure = BoundRuntimeFailure(
            binding=binding,
            protocol="PROBE",
            observed_outbound=binding.observed_outbound,
            destination_token=token,
            error_type=str(source or "runtime_probe"),
            observed_at_monotonic=observed,
            deterministic_proxy_endpoint=str(source or "")
            in {
                "activation_final_exit",
                "manual_exit_quality",
                "proxy_delay",
                "stdout_guard",
                "replacement_verification",
                "runtime_probe",
            },
        )
        current_authority_key = self._runtime_recovery_authority_key(snapshot)
        with self._runtime_failure_monitor_lock:
            # Terminal dedupe must precede coordinator.observe().  Otherwise a
            # heartbeat arriving after controller_hold/fail_closed can still
            # increment or reopen the circuit before discovering that the same
            # immutable authority already owns a terminal result.
            existing_circuit = (
                self._runtime_egress_coordinator.current_snapshot_for(binding)
            )
            existing_incident = str(
                getattr(existing_circuit, "incident_id", "") or ""
            )
            tickets = getattr(self, "_runtime_recovery_tickets", {})
            existing_ticket = (
                tickets.get(existing_incident)
                if existing_incident and isinstance(tickets, dict)
                else None
            )
            terminal_outcomes = getattr(
                self,
                "_runtime_recovery_outcomes",
                {},
            )
            existing_outcome = (
                terminal_outcomes.get(existing_incident)
                if existing_incident and isinstance(terminal_outcomes, dict)
                else None
            )
            recovery_states = getattr(
                self,
                "_runtime_incident_recovery_state",
                {},
            )
            existing_state = (
                str(recovery_states.get(existing_incident) or "")
                if existing_incident and isinstance(recovery_states, dict)
                else ""
            )
            if (
                isinstance(existing_ticket, _RuntimeRecoveryTicket)
                and (
                    isinstance(existing_outcome, RuntimeRecoveryOutcome)
                    or existing_state == "indeterminate"
                )
                and tuple(existing_ticket.authority_key)
                == tuple(current_authority_key)
            ):
                return existing_ticket
            decision = self._runtime_egress_coordinator.observe(
                failure,
                current_snapshot=snapshot,
            )
        if not bool(decision.accepted):
            self._queue_runtime_route_snapshot_refresh()
            return False
        ticket = self._ensure_runtime_recovery_ticket(
            failure,
            snapshot,
            str(decision.incident_id),
            deadline_monotonic=(
                activation_owner.deadline_monotonic
                if activation_submission
                and isinstance(
                    activation_owner,
                    _RuntimeActivationRecoveryOwner,
                )
                else None
            ),
        )
        if ticket is None:
            self._queue_runtime_route_snapshot_refresh()
            return False
        with self._runtime_failure_monitor_lock:
            terminal_outcomes = getattr(
                self,
                "_runtime_recovery_outcomes",
                {},
            )
            terminal_outcome = (
                terminal_outcomes.get(ticket.incident_id)
                if isinstance(terminal_outcomes, dict)
                else None
            )
            recovery_states = getattr(
                self,
                "_runtime_incident_recovery_state",
                {},
            )
            recovery_state = (
                str(recovery_states.get(ticket.incident_id) or "")
                if isinstance(recovery_states, dict)
                else ""
            )
        if (
            isinstance(terminal_outcome, RuntimeRecoveryOutcome)
            or recovery_state == "indeterminate"
        ):
            current_authority_key = self._runtime_recovery_authority_key(snapshot)
            if tuple(ticket.authority_key) == tuple(current_authority_key):
                # The same immutable circuit already owns a terminal/neutral
                # recovery result. Monitor and heartbeat observations may
                # reuse the ticket for auditing, but cannot open another
                # transaction without a material authority revision.
                return ticket
            ticket = self._register_runtime_recovery_ticket(
                failure,
                snapshot,
                str(decision.incident_id),
                force_rebind=True,
                deadline_monotonic=(
                    activation_owner.deadline_monotonic
                    if activation_submission
                    and isinstance(
                        activation_owner,
                        _RuntimeActivationRecoveryOwner,
                    )
                    else None
                ),
            )
        provisional_started = False
        if (
            decision.divert_recommended
            and not decision.confirmed
            and failure.binding.node.pool_kind != "gateway"
        ):
            hot_standby = self._fresh_runtime_hot_standby(
                failure,
                snapshot,
                payload,
            )
            if hot_standby is not None:
                provisional_started = self._start_runtime_provisional_diversion(
                    failure,
                    snapshot,
                    payload,
                    incident_id=decision.incident_id,
                    probe_token=decision.probe_token,
                    evidence=hot_standby,
                )
        if not provisional_started:
            self._start_runtime_independent_probe(
                failure,
                snapshot,
                payload,
                probe_token=decision.probe_token,
            )
        self._queue_runtime_route_snapshot_refresh()
        return ticket

    def _maybe_probe_runtime_failure_guard(self) -> None:
        if self._runtime_uses_early_single_coordinator():
            # This profile is strictly event-driven.  The monitor heartbeat
            # never re-arms recovery, repairs a dropped burst, or reopens an
            # indeterminate incident on its own.
            return
        if not self._runtime_recovery_is_armed():
            if self._runtime_initial_activation_complete():
                now = time.monotonic()
                with self._runtime_failure_monitor_lock:
                    retry_at = float(
                        getattr(self, "_runtime_recovery_arm_refresh_at", 0.0)
                        or 0.0
                    )
                    if now >= retry_at:
                        self._runtime_recovery_arm_refresh_at = now + 5.0
                        refresh_due = True
                    else:
                        refresh_due = False
                if refresh_due:
                    self._queue_runtime_route_snapshot_refresh()
            return
        runner = self.core_runner
        reader = getattr(runner, "_reader_thread", None) if runner is not None else None
        reader_missing = bool(
            runner is not None
            and runner.is_running()
            and (reader is None or not reader.is_alive())
        )
        if reader_missing:
            self._runtime_egress_coordinator.request_guard("reader_missing")
        guard_pending = (
            self._runtime_egress_coordinator.queue_snapshot().overflow_guard_required
        )
        if not guard_pending:
            return
        now = time.monotonic()
        with self._runtime_failure_monitor_lock:
            if now - self._runtime_failure_guard_probe_last_at < 10.0:
                return
            self._runtime_failure_guard_probe_last_at = now
        guard_token = self._runtime_egress_coordinator.claim_guard()
        if guard_token is None:
            return
        facility_hold = self._runtime_facility_hold_reason()
        if facility_hold or "local_listener_bind_failed" in set(
            guard_token.reasons
        ):
            self._record_runtime_facility_degradation(
                facility_hold or "mihomo local listener bind failed"
            )
            self._runtime_egress_coordinator.acknowledge_guard(
                guard_token,
                completed=True,
            )
            return
        worker_token = self._runtime_worker_token()

        def worker() -> None:
            completed = False
            try:
                binding_state = self._current_runtime_failure_binding_state(
                    timeout_seconds=0.75,
                    refresh=True,
                )
            except Exception:
                binding_state = None
                self._queue_runtime_route_snapshot_refresh()
            try:
                self._probe_mihomo_mixed_port_once(timeout_seconds=1.5)
                completed = True
            except _RuntimeProbeBudgetUnavailable:
                # Keep the overflow/reader guard pending. No actual socket
                # result exists, so neither a leaf incident nor facility state
                # may be derived from this attempt.
                with self._runtime_failure_monitor_lock:
                    self._runtime_failure_guard_probe_last_at = 0.0
                return
            except Exception as exc:
                if not self._runtime_worker_token_is_current(worker_token):
                    return
                self._submit_current_route_probe_failure(
                    f"runtime stdout guard probe failed: {exc}",
                    source="stdout_guard",
                    binding_state=binding_state,
                    binding_captured=True,
                )
                completed = True
            finally:
                self._runtime_egress_coordinator.acknowledge_guard(
                    guard_token,
                    completed=completed,
                )

        try:
            threading.Thread(
                target=worker,
                name="runtime-egress-stdout-guard",
                daemon=True,
            ).start()
        except Exception:
            self._runtime_egress_coordinator.acknowledge_guard(
                guard_token,
                completed=False,
            )
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Runtime egress guard worker could not start",
                exc_info=True,
            )

    def _close_runtime_connections_for_binding(
        self,
        binding: RuntimeRouteBinding,
        *,
        terminal_connection_ids: set[str] | None = None,
        deadline_monotonic: float | None = None,
        expected_worker_token: tuple[int, ...] | None = None,
        closed_connection_ids: set[str] | None = None,
    ) -> int:
        """Close explicitly correlated terminal connections only.

        A route chain proves which leaf a connection used, but it does not
        prove that the connection is failed: downloads, WebSockets, HTTP/2,
        QUIC and idle control channels may remain healthy after the selector
        changes.  Runtime recovery therefore supplies an exact controller
        connection id only when a terminal stdout flow token was correlated
        to that id.  Without that evidence this method is deliberately a
        no-op.  ``closed_connection_ids``, when given, receives each id whose
        DELETE succeeded (the post-dial judge retries the others).
        """

        allowed_ids = {
            str(connection_id).strip()
            for connection_id in (terminal_connection_ids or set())
            if str(connection_id).strip()
        }
        if not allowed_ids:
            return 0

        deadline = (
            float(deadline_monotonic)
            if deadline_monotonic is not None
            else time.monotonic() + 2.0
        )
        if deadline <= time.monotonic():
            return 0
        if (
            expected_worker_token is not None
            and not self._runtime_worker_token_is_current(expected_worker_token)
        ):
            return 0
        try:
            try:
                payload = self.mihomo_connections(
                    timeout_seconds=max(
                        0.05,
                        min(0.35, deadline - time.monotonic()),
                    )
                )
            except TypeError:
                payload = self.mihomo_connections()
        except Exception:
            return 0
        connections = payload.get("connections") if isinstance(payload, dict) else None
        if not isinstance(connections, list):
            return 0
        closed = 0
        for connection in connections[:512]:
            if (
                expected_worker_token is not None
                and not self._runtime_worker_token_is_current(
                    expected_worker_token
                )
            ):
                break
            remaining = deadline - time.monotonic()
            if remaining <= 0.0:
                break
            if not isinstance(connection, dict):
                continue
            chains = connection.get("chains")
            if not isinstance(chains, (list, tuple)):
                continue
            if binding.node.proxy_name not in {str(item) for item in chains}:
                continue
            connection_id = str(connection.get("id") or "").strip()
            if not connection_id or connection_id not in allowed_ids:
                continue
            try:
                try:
                    self.close_mihomo_connection(
                        connection_id,
                        timeout_seconds=max(0.05, min(0.2, remaining)),
                    )
                except TypeError:
                    self.close_mihomo_connection(connection_id)
                closed += 1
                if closed_connection_ids is not None:
                    closed_connection_ids.add(connection_id)
            except Exception:
                continue
        return closed

    def _start_runtime_connection_cleanup(
        self,
        binding: RuntimeRouteBinding,
        *,
        terminal_connection_ids: set[str] | None = None,
    ) -> None:
        """Drain by default; schedule only exact terminal-id cleanup.

        Existing connections are intentionally retained on the old leaf.  A
        selector mutation affects only new dials and must not turn recovery
        into a user-visible download/WebSocket/meeting interruption.
        """

        exact_ids = {
            str(connection_id).strip()
            for connection_id in (terminal_connection_ids or set())
            if str(connection_id).strip()
        }
        if not exact_ids:
            return

        worker_token = self._runtime_worker_token()

        def worker() -> None:
            try:
                if not self._runtime_worker_token_is_current(worker_token):
                    return
                try:
                    self._close_runtime_connections_for_binding(
                        binding,
                        terminal_connection_ids=exact_ids,
                        deadline_monotonic=time.monotonic() + 2.0,
                        expected_worker_token=worker_token,
                    )
                except TypeError:
                    self._close_runtime_connections_for_binding(
                        binding,
                        terminal_connection_ids=exact_ids,
                    )
            finally:
                with self._runtime_failure_monitor_lock:
                    self._runtime_failure_recovery_threads.discard(
                        threading.current_thread()
                    )

        thread = threading.Thread(
            target=worker,
            name="runtime-egress-connection-cleanup",
            daemon=True,
        )
        with self._runtime_failure_monitor_lock:
            self._runtime_failure_recovery_threads.add(thread)
        thread.start()

    def _runtime_required_pass_count(
        self,
        binding: RuntimeRouteBinding,
        *,
        confirmed_at: float,
    ) -> int:
        key = binding.node.key
        history = [
            value
            for value in self._runtime_flap_history.get(key, [])
            if confirmed_at - value <= 120.0
        ]
        history.append(confirmed_at)
        self._runtime_flap_history[key] = history[-8:]
        return 2 if len(history) >= 2 else 1

    def _apply_confirmed_runtime_health(
        self,
        failure: BoundRuntimeFailure,
        expected_snapshot: CoreLoadedRouteSnapshot,
        snapshot_payload: dict[str, Any],
        *,
        incident_id: str,
        quarantine_token: str,
        allow_origin_binding: bool = False,
        expected_facility_epoch: int | None = None,
        expected_ticket: _RuntimeRecoveryTicket | None = None,
        allow_recovered_terminal: bool = False,
        deadline_monotonic: float | None = None,
    ) -> dict[str, Any]:
        manager = self.manager
        apply_observation = getattr(
            manager,
            "apply_runtime_health_observation",
            None,
        ) if manager is not None else None
        if not callable(apply_observation):
            return {
                "accepted": False,
                "changed": False,
                "action": "manager_unavailable",
            }
        observed = float(failure.observed_at_monotonic or time.monotonic())
        observation = {
            "node": failure.binding.node,
            "tier": failure.binding.node.tier,
            "pool_kind": failure.binding.node.pool_kind,
            "identity": failure.binding.node.identity,
            "proxy_name": failure.binding.node.proxy_name,
            "source": "business_transport",
            "verdict": "confirmed",
            "failure_domain": "node",
            "incident_id": str(incident_id or ""),
            "failure_epoch": int(observed * 1_000_000),
            "quarantine_token": str(quarantine_token or incident_id or ""),
            "runtime_generation": int(
                getattr(manager, "runtime_generation", self._runtime_generation) or 0
            ),
            "core_generation": failure.binding.core_generation,
            "semantic_digest": failure.binding.semantic_digest,
            "observed_at": utc_now_iso(),
            "observed_monotonic": observed,
            "required_passes": 1,
            "reason": (
                f"runtime {failure.protocol} {failure.error_type} transport failure"
            ),
        }
        with self._runtime_route_snapshot_lock:
            current_snapshot = self._runtime_route_snapshot
            direct_binding_is_current = bool(
                current_snapshot is not None
                and current_snapshot.snapshot_key
                == expected_snapshot.snapshot_key
                and current_snapshot.owns(failure.binding)
                and self._runtime_egress_coordinator.snapshot_ownership_matches(
                    failure.binding,
                    expected_snapshot=expected_snapshot,
                )
            )
        origin_binding_is_current = False
        if allow_origin_binding and not direct_binding_is_current:
            with self._runtime_failure_monitor_lock:
                origin = getattr(
                    self,
                    "_runtime_origin_diagnostic_bindings",
                    {},
                ).get(str(incident_id))
                lease = getattr(self, "_runtime_route_mutation_lease", None)
                origin_binding_is_current = bool(
                    isinstance(origin, OriginDiagnosticBinding)
                    and origin.binding.circuit_key
                    == failure.binding.circuit_key
                    and origin.snapshot_key == expected_snapshot.snapshot_key
                    and origin.owner_token == str(quarantine_token)
                    and origin.expires_at_monotonic > time.monotonic()
                    and origin.selector_intent_revision
                    == int(
                        getattr(self, "_runtime_selector_intent_revision", 0)
                        or 0
                    )
                    and origin.binding.network_context_epoch
                    == int(
                        getattr(self, "_runtime_network_context_epoch", 0) or 0
                    )
                    and isinstance(lease, dict)
                    and str(lease.get("incident_id") or "")
                    == str(incident_id)
                    and str(lease.get("owner_token") or "")
                    == str(quarantine_token)
                    and str(lease.get("from") or "")
                    == failure.binding.node.proxy_name
                    and str(lease.get("to") or "")
                    and str(lease.get("to") or "")
                    != failure.binding.node.proxy_name
                    and float(lease.get("verified_at_monotonic") or 0.0) > 0.0
                    and (
                        not origin.target_proxy
                        or origin.target_proxy
                        == str(lease.get("to") or "")
                    )
                    and (
                        origin.committed_route_epoch <= 0
                        or origin.committed_route_epoch
                        == int(lease.get("route_epoch") or 0)
                    )
                )
        if not (direct_binding_is_current or origin_binding_is_current):
            return {
                "accepted": False,
                "changed": False,
                "action": "stale",
                "reason": "Core route changed before health commit",
            }
        core_transition_lock = getattr(
            self,
            "_core_transition_lock",
            nullcontext(),
        )
        with core_transition_lock:
            with self._runtime_failure_monitor_lock:
                if isinstance(expected_ticket, _RuntimeRecoveryTicket) and (
                    not self._runtime_recovery_ticket_matches_locked(
                        expected_ticket,
                        require_open=True,
                        deadline_monotonic=deadline_monotonic,
                        allow_recovered_terminal=allow_recovered_terminal,
                    )
                    or int(
                        getattr(
                            self,
                            "_runtime_selector_intent_revision",
                            0,
                        )
                        or 0
                    )
                    != int(expected_ticket.selector_intent_revision)
                    or not self._runtime_worker_token_is_current(
                        expected_ticket.worker_token
                    )
                ):
                    return {
                        "accepted": False,
                        "changed": False,
                        "action": "terminal",
                        "reason": (
                            "terminal or route authority superseded health commit"
                        ),
                    }
                if (
                    (
                        expected_facility_epoch is not None
                        and int(
                            getattr(self, "_runtime_facility_epoch", 0) or 0
                        )
                        != int(expected_facility_epoch)
                    )
                    or (
                        not self._runtime_uses_early_single_coordinator()
                        and bool(self._runtime_facility_hold_reason())
                    )
                ):
                    return {
                        "accepted": False,
                        "changed": False,
                        "action": "facility_hold",
                        "reason": "facility hold superseded leaf health commit",
                    }
                if direct_binding_is_current:
                    loaded_snapshot = getattr(
                        self,
                        "_runtime_route_snapshot",
                        None,
                    )
                    coordinator_snapshot = (
                        self._runtime_egress_coordinator.current_route_snapshot()
                    )
                    direct_binding_is_current = bool(
                        isinstance(
                            loaded_snapshot,
                            CoreLoadedRouteSnapshot,
                        )
                        and tuple(loaded_snapshot.snapshot_key)
                        == tuple(expected_snapshot.snapshot_key)
                        and loaded_snapshot.owns(failure.binding)
                        and coordinator_snapshot is not None
                        and tuple(coordinator_snapshot.snapshot_key)
                        == tuple(expected_snapshot.snapshot_key)
                    )
                if origin_binding_is_current:
                    current_origin = getattr(
                        self,
                        "_runtime_origin_diagnostic_bindings",
                        {},
                    ).get(str(incident_id))
                    current_lease = getattr(
                        self,
                        "_runtime_route_mutation_lease",
                        None,
                    )
                    origin_binding_is_current = bool(
                        isinstance(
                            current_origin,
                            OriginDiagnosticBinding,
                        )
                        and current_origin.binding.circuit_key
                        == failure.binding.circuit_key
                        and current_origin.owner_token
                        == str(quarantine_token)
                        and isinstance(current_lease, dict)
                        and str(current_lease.get("incident_id") or "")
                        == str(incident_id)
                        and str(current_lease.get("owner_token") or "")
                        == str(quarantine_token)
                        and str(current_lease.get("from") or "")
                        == failure.binding.node.proxy_name
                    )
                if not (
                    direct_binding_is_current or origin_binding_is_current
                ):
                    return {
                        "accepted": False,
                        "changed": False,
                        "action": "stale",
                        "reason": "Core route changed before health commit",
                    }
                observation["required_passes"] = (
                    self._runtime_required_pass_count(
                        failure.binding,
                        confirmed_at=self._runtime_recovery_now(),
                    )
                )
                transition = apply_observation(observation)
        if not isinstance(transition, dict):
            transition = {"accepted": bool(transition), "changed": bool(transition)}
        if not transition.get("accepted"):
            return transition
        self._runtime_incident_bindings[str(incident_id)] = failure.binding
        self._runtime_incident_route_payloads[str(incident_id)] = snapshot_payload
        if failure.binding.node.pool_kind == "tier3b":
            self._revoke_tier3_runtime_leaf_qualification(
                failure.binding.node.identity
            )
        enqueue = getattr(manager, "enqueue_runtime_leaf_recheck", None)
        if callable(enqueue):
            try:
                enqueue(
                    failure.binding.node,
                    reason=str(observation["reason"]),
                    source="runtime_coordinator",
                    incident_id=str(incident_id),
                    quarantine_token=str(quarantine_token or incident_id),
                    runtime_generation=int(observation["runtime_generation"]),
                    semantic_digest=failure.binding.semantic_digest,
                    failure_epoch=observation["failure_epoch"],
                )
            except Exception:
                log_raw_diagnostic(
                    self.logger,
                    "warning",
                    "Failed to queue exact runtime leaf recheck",
                    exc_info=True,
                )
        return transition

    def _start_runtime_recovery(
        self,
        failure: BoundRuntimeFailure,
        snapshot: CoreLoadedRouteSnapshot,
        snapshot_payload: dict[str, Any],
        *,
        incident_id: str,
        quarantine_token: str,
        confirmed_alternative: RuntimeNodeRef | None,
        already_diverted: bool = False,
        confirmed_alternative_probe_result: dict[str, Any] | None = None,
        confirmed_alternative_evidence: _HotStandbyEvidence | None = None,
        incident_deadline_monotonic: float | None = None,
        recovery_ticket_override: _RuntimeRecoveryTicket | None = None,
        circuit_incident_id: str | None = None,
        circuit_quarantine_token: str | None = None,
    ) -> None:
        recovery_ticket = (
            recovery_ticket_override
            if isinstance(recovery_ticket_override, _RuntimeRecoveryTicket)
            and recovery_ticket_override.incident_id == str(incident_id)
            else self._ensure_runtime_recovery_ticket(
                failure,
                snapshot,
                str(incident_id),
            )
        )
        if not isinstance(recovery_ticket, _RuntimeRecoveryTicket):
            return
        coordinator_incident_id = str(circuit_incident_id or incident_id)
        coordinator_quarantine_token = str(
            circuit_quarantine_token or quarantine_token
        )
        if self._runtime_facility_hold_reason():
            self._complete_runtime_recovery_hold(
                recovery_ticket,
                reason_code="facility_hold_before_recovery",
            )
            return
        key = failure.circuit_key
        worker_token = self._runtime_worker_token()
        # Capture the user's selector intent before the recovery thread is
        # started.  The worker may wait for probes or the shared Core lock; any
        # manual selection completed in that interval must make this automatic
        # transaction stale instead of being overwritten by it.
        selector_intent_revision = int(
            getattr(self, "_runtime_selector_intent_revision", 0) or 0
        )
        facility_epoch = int(
            getattr(self, "_runtime_facility_epoch", 0) or 0
        )
        gateway_failure_confirmed = bool(
            failure.binding.node.pool_kind == "gateway"
            and confirmed_alternative is None
        )
        # The hard recovery budget starts when the failed execution binding was
        # observed, not when a later worker happens to confirm or schedule it.
        # A caller may pass the already-frozen deadline, but never extend it.
        observed_deadline = float(failure.observed_at_monotonic) + 6.0
        recovery_deadline = (
            min(observed_deadline, float(incident_deadline_monotonic))
            if incident_deadline_monotonic is not None
            else observed_deadline
        )
        recovery_route_deadline = recovery_deadline
        parent_lease: dict[str, Any] | None = None
        successor_lease_blocked = False
        with self._runtime_failure_monitor_lock:
            if not self._runtime_recovery_ticket_matches_locked(
                recovery_ticket,
                require_open=True,
                deadline_monotonic=recovery_deadline,
            ):
                return
            active_lease = getattr(self, "_runtime_route_mutation_lease", None)
            if isinstance(active_lease, dict):
                parent_lease = self._runtime_successor_parent_lease_locked(
                    failure,
                    selector_intent_revision=selector_intent_revision,
                )
                successor_lease_blocked = parent_lease is None
        if successor_lease_blocked:
            self._complete_runtime_recovery_outcome(
                str(incident_id),
                RuntimeRecoveryStatus.STALE,
                reason_code="automatic_lease_cas_rejected",
                expected_ticket=recovery_ticket,
            )
            return
        circuit_snapshot = self._runtime_egress_coordinator.current_snapshot_for(
            failure.binding
        )
        with self._runtime_failure_monitor_lock:
            if not self._runtime_recovery_ticket_matches_locked(
                recovery_ticket,
                require_open=True,
                deadline_monotonic=recovery_deadline,
            ):
                return
            provisional_key = ("provisional", *key)
            if provisional_key in self._runtime_failure_recovery_bindings:
                # Confirmation and provisional diversion are two phases of one
                # incident, not two Core transaction owners.  Let the selector
                # phase finish, then consume this exact confirmation with the
                # verified lease (or retry against the still-current origin).
                self._runtime_pending_confirmed_incidents[str(incident_id)] = {
                    "quarantine_token": str(quarantine_token),
                    "confirmed_alternative": confirmed_alternative,
                    "confirmed_alternative_probe_result": (
                        confirmed_alternative_probe_result
                    ),
                    "confirmed_alternative_evidence": (
                        confirmed_alternative_evidence
                    ),
                }
                return
            if key in self._runtime_failure_recovery_bindings:
                return
            self._runtime_failure_recovery_bindings.add(key)
            self._runtime_incident_recovery_state[str(incident_id)] = "pending"

        def worker() -> None:
            recovery_gate_lease: RuntimeRecoveryLease | None = None
            recovery_pressure_lease = None
            fail_closed_admitted = False
            try:
                if not self._runtime_recovery_ticket_is_current(
                    recovery_ticket,
                    require_open=True,
                    deadline_monotonic=recovery_deadline,
                ):
                    self._complete_runtime_recovery_hold(
                        recovery_ticket,
                        reason_code="recovery_ticket_not_current",
                    )
                    return
                if not self._runtime_worker_token_is_current(worker_token):
                    self._complete_runtime_recovery_outcome(
                        str(incident_id),
                        RuntimeRecoveryStatus.STALE,
                        reason_code="runtime_generation_changed",
                        expected_ticket=recovery_ticket,
                    )
                    return
                recovery_pressure = (
                    None
                    if self._runtime_uses_early_single_coordinator()
                    else getattr(
                        self,
                        "_runtime_recovery_pressure",
                        None,
                    )
                )
                if recovery_pressure is not None:
                    recovery_pressure_lease = recovery_pressure.acquire(
                        f"runtime-recovery:{incident_id}",
                        RuntimeRecoveryPressurePriority.RUNTIME_RECOVERY,
                        lifecycle_generation=(
                            recovery_pressure.lifecycle_generation
                        ),
                    )
                    if recovery_pressure_lease is None:
                        with self._runtime_failure_monitor_lock:
                            self._runtime_incident_recovery_state[
                                str(incident_id)
                            ] = "indeterminate"
                        self._complete_runtime_recovery_hold(
                            recovery_ticket,
                            reason_code="recovery_pressure_unavailable",
                        )
                        return
                reload_gate = getattr(self, "_runtime_reload_gate", None)
                if reload_gate is not None:
                    gate_deadline = min(
                        recovery_route_deadline,
                        self._runtime_recovery_now() + 0.5,
                    )
                    while recovery_gate_lease is None:
                        recovery_gate_lease = reload_gate.begin_recovery(
                            f"runtime-egress:{incident_id}"
                        )
                        if (
                            recovery_gate_lease is not None
                            or self._runtime_recovery_now() >= gate_deadline
                        ):
                            break
                        if self.stop_event.wait(0.01):
                            return
                    if recovery_gate_lease is None:
                        self._record_runtime_facility_degradation(
                            "Core reload transaction prevented safe runtime recovery"
                        )
                        self._complete_runtime_recovery_outcome(
                            str(incident_id),
                            RuntimeRecoveryStatus.CONTROLLER_HOLD,
                            reason_code="reload_gate_unavailable",
                            expected_ticket=recovery_ticket,
                        )
                        return
                if not self._runtime_recovery_ticket_is_current(
                    recovery_ticket,
                    require_open=True,
                    deadline_monotonic=recovery_deadline,
                ):
                    self._complete_runtime_recovery_hold(
                        recovery_ticket,
                        reason_code="recovery_budget_or_ticket_expired",
                    )
                    return
                with self._runtime_failure_monitor_lock:
                    if not self._runtime_recovery_ticket_matches_locked(
                        recovery_ticket,
                        require_open=True,
                        deadline_monotonic=recovery_deadline,
                    ):
                        return
                    self._runtime_egress_coordinator.mark_recovering(
                        failure.binding,
                        incident_id=coordinator_incident_id,
                        quarantine_token=coordinator_quarantine_token,
                    )
                transition = self._apply_confirmed_runtime_health(
                    failure,
                    snapshot,
                    snapshot_payload,
                    incident_id=incident_id,
                    quarantine_token=quarantine_token,
                    allow_origin_binding=already_diverted,
                    expected_facility_epoch=facility_epoch,
                    expected_ticket=recovery_ticket,
                    deadline_monotonic=recovery_deadline,
                )
                if not transition.get("accepted"):
                    with self._runtime_failure_monitor_lock:
                        self._runtime_incident_recovery_state.pop(
                            str(incident_id),
                            None,
                        )
                        self._runtime_pending_recovered_payloads.pop(
                            str(incident_id),
                            None,
                        )
                    if int(
                        getattr(self, "_runtime_selector_intent_revision", 0)
                        or 0
                    ) != selector_intent_revision:
                        rejected_status = (
                            RuntimeRecoveryStatus.MANUAL_SUPERSEDED
                        )
                        rejected_reason = "selector_intent_changed"
                    elif (
                        int(getattr(self, "_runtime_facility_epoch", 0) or 0)
                        != facility_epoch
                        or bool(self._runtime_facility_hold_reason())
                    ):
                        rejected_status = RuntimeRecoveryStatus.FACILITY_HOLD
                        rejected_reason = "facility_epoch_changed"
                    else:
                        rejected_status = RuntimeRecoveryStatus.STALE
                        rejected_reason = "health_cas_rejected"
                    self._complete_runtime_recovery_outcome(
                        str(incident_id),
                        rejected_status,
                        reason_code=rejected_reason,
                        expected_ticket=recovery_ticket,
                    )
                    return
                with self._runtime_failure_monitor_lock:
                    self._runtime_incident_recovery_state[str(incident_id)] = (
                        "recovering"
                    )
                if already_diverted:
                    # The incident-owned provisional lease has already moved
                    # future dials to a verified route.  Confirmation now only
                    # changes the failed origin's health truth and schedules
                    # its layer-specific recheck; it must not mutate Core a
                    # second time or interrupt established connections.
                    pending_recovered: dict[str, Any] | None = None
                    diverted_to = ""
                    diverted_verified_at = 0.0
                    diverted_deadline = recovery_deadline
                    with self._runtime_failure_monitor_lock:
                        if (
                            not self._runtime_recovery_ticket_matches_locked(
                                recovery_ticket,
                                require_open=True,
                                deadline_monotonic=recovery_deadline,
                            )
                            or int(
                                getattr(self, "_runtime_facility_epoch", 0) or 0
                            )
                            != facility_epoch
                            or bool(self._runtime_facility_hold_reason())
                            or int(
                                getattr(
                                    self,
                                    "_runtime_selector_intent_revision",
                                    0,
                                )
                                or 0
                            )
                            != selector_intent_revision
                        ):
                            self._runtime_incident_recovery_state[
                                str(incident_id)
                            ] = "indeterminate"
                            return
                        lease_record = self._runtime_route_mutation_lease
                        if not (
                            isinstance(lease_record, dict)
                            and str(lease_record.get("incident_id") or "")
                            == str(incident_id)
                            and int(
                                lease_record.get(
                                    "recovery_ticket_generation",
                                    0,
                                )
                                or 0
                            )
                            == recovery_ticket.generation
                        ):
                            self._runtime_incident_recovery_state[
                                str(incident_id)
                            ] = "indeterminate"
                            return
                        diverted_to = str(lease_record.get("to") or "")
                        diverted_verified_at = float(
                            lease_record.get("verified_at_monotonic") or 0.0
                        )
                        diverted_deadline = min(
                            float(recovery_ticket.deadline_monotonic),
                            float(
                                lease_record.get(
                                    "recovery_deadline_monotonic"
                                )
                                or recovery_deadline
                            ),
                        )
                        if not (
                            diverted_verified_at > 0.0
                            and diverted_verified_at < diverted_deadline
                        ):
                            self._runtime_incident_recovery_state[
                                str(incident_id)
                            ] = "indeterminate"
                            return
                        self._runtime_egress_coordinator.mark_quarantined(
                            failure.binding,
                            ttl_seconds=30.0,
                            incident_id=coordinator_incident_id,
                            quarantine_token=coordinator_quarantine_token,
                        )
                        terminal_outcome = (
                            self._complete_runtime_recovery_outcome(
                                str(incident_id),
                                RuntimeRecoveryStatus.RECOVERED,
                                reason_code="verified_route",
                                to_ref=(
                                    self._runtime_recovery_ref_for_proxy(
                                        diverted_to
                                    )
                                ),
                                expected_ticket=recovery_ticket,
                                deadline_monotonic=diverted_deadline,
                                completed_at_monotonic=(
                                    diverted_verified_at
                                ),
                                facts={
                                    "put": True,
                                    "readback": True,
                                    "final_204": True,
                                },
                            )
                        )
                        if not (
                            isinstance(
                                terminal_outcome,
                                RuntimeRecoveryOutcome,
                            )
                            and terminal_outcome.status
                            is RuntimeRecoveryStatus.RECOVERED
                        ):
                            return
                        lease_record["provisional"] = False
                        self._runtime_incident_recovery_state[
                            str(incident_id)
                        ] = "ready"
                        value = self._runtime_pending_recovered_payloads.pop(
                            str(incident_id),
                            None,
                        )
                        if isinstance(value, dict):
                            pending_recovered = value
                        self._set_effective_egress_state(True, "")
                    if pending_recovered is not None:
                        self._on_runtime_leaf_recheck_result(pending_recovered)
                    # The provisional selector write invalidated the old arm.
                    # At this point the incident is terminal RECOVERED, the
                    # verified lease is committed, and the state is READY, so
                    # the new leaf must immediately be eligible for B->C.
                    if not self._try_arm_runtime_recovery():
                        self._queue_runtime_route_snapshot_refresh()
                    return
                if not self._runtime_recovery_ticket_is_current(
                    recovery_ticket,
                    require_open=True,
                    deadline_monotonic=recovery_deadline,
                ):
                    with self._runtime_failure_monitor_lock:
                        self._runtime_incident_recovery_state[
                            str(incident_id)
                        ] = "indeterminate"
                    self._complete_runtime_recovery_hold(
                        recovery_ticket,
                        reason_code="recovery_budget_expired_before_core_mutation",
                    )
                    return
                if gateway_failure_confirmed:
                    self._activate_killswitch_for_egress_failure(
                        "Fixed Gateway runtime transport failure confirmed"
                    )
                mutation_wait = max(
                    0.0,
                    recovery_route_deadline - self._runtime_recovery_now(),
                )
                lease = self._runtime_egress_coordinator.begin_core_mutation(
                    failure.binding,
                    expected_snapshot=snapshot,
                    timeout_seconds=mutation_wait,
                )
                if lease is None:
                    selector_superseded = bool(
                        int(
                            getattr(
                                self,
                                "_runtime_selector_intent_revision",
                                0,
                            )
                            or 0
                        )
                        != selector_intent_revision
                    )
                    if selector_superseded:
                        with self._runtime_failure_monitor_lock:
                            self._runtime_incident_recovery_state[
                                str(incident_id)
                            ] = "manual_superseded"
                            self._runtime_pending_recovered_payloads.pop(
                                str(incident_id),
                                None,
                            )
                        return

                    def emergency_after_cas_loss(emergency_reason: str) -> None:
                        if not gateway_failure_confirmed:
                            self._mark_runtime_recovery_quarantined(
                                failure.binding,
                                recovery_ticket=recovery_ticket,
                                coordinator_incident_id=(
                                    coordinator_incident_id
                                ),
                                coordinator_quarantine_token=(
                                    coordinator_quarantine_token
                                ),
                                deadline_monotonic=recovery_deadline,
                            )
                            with self._runtime_failure_monitor_lock:
                                self._runtime_incident_recovery_state[
                                    str(incident_id)
                                ] = "indeterminate"
                            self._complete_runtime_recovery_hold(
                                recovery_ticket,
                                reason_code="route_cas_lost_without_gateway_authority",
                            )
                            self._set_effective_egress_readiness_state(
                                None,
                                emergency_reason,
                            )
                            self._queue_runtime_route_snapshot_refresh()
                            return
                        if not self._admit_runtime_fail_closed_mutation(
                            recovery_ticket,
                            deadline_monotonic=recovery_deadline,
                            failure_binding=failure.binding,
                            gateway_failure_confirmed=(
                                gateway_failure_confirmed
                            ),
                            expected_facility_epoch=facility_epoch,
                        ):
                            return
                        physical: dict[str, Any] = {}
                        try:
                            if not self._mark_runtime_recovery_quarantined(
                                failure.binding,
                                recovery_ticket=recovery_ticket,
                                coordinator_incident_id=(
                                    coordinator_incident_id
                                ),
                                coordinator_quarantine_token=(
                                    coordinator_quarantine_token
                                ),
                                deadline_monotonic=recovery_deadline,
                            ):
                                return
                            with self._runtime_route_snapshot_lock:
                                expected_route_epoch = int(
                                    self._runtime_route_epoch
                                )
                            with self._core_transition_lock:
                                physical = self._enforce_runtime_fail_closed(
                                    emergency_reason,
                                    failure_binding=failure.binding,
                                    gateway_failure_confirmed=(
                                        gateway_failure_confirmed
                                    ),
                                    deadline_monotonic=recovery_deadline,
                                    expected_worker_token=worker_token,
                                    expected_route_epoch=expected_route_epoch,
                                    expected_selector_intent_revision=(
                                        selector_intent_revision
                                    ),
                                    expected_facility_epoch=facility_epoch,
                                )
                            if physical.get("stale"):
                                with self._runtime_failure_monitor_lock:
                                    self._runtime_incident_recovery_state[
                                        str(incident_id)
                                    ] = "route_superseded"
                                return
                            self._commit_runtime_fail_closed_outcome(
                                physical=physical,
                                incident_id=str(incident_id),
                                from_proxy=(
                                    failure.binding.node.proxy_name
                                ),
                                selector_intent_revision=(
                                    selector_intent_revision
                                ),
                                expected_ticket=recovery_ticket,
                            )
                        finally:
                            self._release_runtime_fail_closed_admission(
                                recovery_ticket
                            )
                        audit = self._runtime_audit_base_result(
                            reason=emergency_reason,
                            trigger="runtime_global_circuit",
                        )
                        audit.update(
                            {
                                "effective_egress_ok": (
                                    False
                                    if physical.get("enforced")
                                    else None
                                ),
                                "fail_closed_apply": physical,
                                "fail_closed_terminal": bool(
                                    physical.get("enforced")
                                ),
                            }
                        )
                        self._set_runtime_audit_result(
                            audit,
                            readiness_only=not bool(
                                physical.get("enforced")
                            ),
                        )
                        with self._runtime_failure_monitor_lock:
                            self._runtime_incident_recovery_state[
                                str(incident_id)
                            ] = (
                                "ready"
                                if physical.get("enforced")
                                else "indeterminate"
                            )
                        if not physical.get("enforced"):
                            self._queue_runtime_route_snapshot_refresh()

                    # A user/Core route change may have won the CAS, or another
                    # global recovery transaction may have consumed the entire
                    # deadline.  Only a *different*, freshly bound managed leaf
                    # may restore effective egress here.  A stray 204 through
                    # the still-quarantined leaf must never reopen the route.
                    state_refresh_budget = self._runtime_recovery_remaining(
                        recovery_route_deadline,
                        cap=0.35,
                    )
                    current_state = (
                        None
                        if state_refresh_budget <= 0.0
                        else self._current_runtime_failure_binding_state(
                            timeout_seconds=state_refresh_budget
                        )
                    )
                    if current_state is None:
                        emergency_after_cas_loss(
                            "FINAL-EXIT route became unavailable after recovery CAS loss"
                        )
                        return
                    current_binding, _current_snapshot, _current_payload = (
                        current_state
                    )
                    underlay_domain = bool(
                        "FINAL-EXIT" not in failure.binding.route_chain
                    )
                    replacement_binding = (
                        self._runtime_route_binding_for_outbound(
                            _current_snapshot,
                            _current_payload,
                            failure.binding.observed_outbound,
                            require_final_exit=not underlay_domain,
                        )
                        if underlay_domain
                        else current_binding
                    )
                    if replacement_binding is None:
                        emergency_after_cas_loss(
                            "Failed route domain could not be rebound after recovery CAS loss"
                        )
                        return
                    if underlay_domain:
                        original_gateway = (
                            self._runtime_route_binding_for_outbound(
                                snapshot,
                                snapshot_payload,
                                "FINAL-EXIT",
                            )
                        )
                        if (
                            original_gateway is None
                            or original_gateway.node.pool_kind != "gateway"
                            or current_binding.node.pool_kind != "gateway"
                            or tuple(current_binding.node.key)
                            != tuple(original_gateway.node.key)
                        ):
                            emergency_after_cas_loss(
                                "Gateway identity changed after underlay recovery CAS loss"
                            )
                            return
                    if (
                        replacement_binding.node.key
                        == failure.binding.node.key
                    ):
                        emergency_after_cas_loss(
                            "Confirmed runtime leaf still owns its route domain after recovery CAS loss"
                        )
                        return
                    probe_seconds = self._runtime_recovery_remaining(
                        recovery_route_deadline,
                        cap=1.5,
                    )
                    if probe_seconds <= 0.0:
                        emergency_after_cas_loss(
                            "Replacement route could not be verified before the recovery deadline"
                        )
                        return
                    try:
                        verified = self._probe_mihomo_mixed_port_once(
                            timeout_seconds=probe_seconds
                        )
                    except _RuntimeProbeBudgetUnavailable:
                        with self._runtime_failure_monitor_lock:
                            self._runtime_incident_recovery_state[
                                str(incident_id)
                            ] = "indeterminate"
                        self._set_effective_egress_readiness_state(
                            None,
                            "Replacement route is awaiting neutral probe capacity",
                        )
                        self._queue_runtime_route_snapshot_refresh()
                        return
                    except Exception as exc:
                        emergency_after_cas_loss(
                            f"Replacement route failed neutral verification after recovery CAS loss: {exc}"
                        )
                        return
                    if not self._runtime_worker_token_is_current(worker_token):
                        return
                    post_verify_budget = self._runtime_recovery_remaining(
                        recovery_route_deadline,
                        cap=0.35,
                    )
                    post_verify_state = (
                        None
                        if post_verify_budget <= 0.0
                        else self._current_runtime_failure_binding_state(
                            timeout_seconds=post_verify_budget
                        )
                    )
                    if post_verify_state is None:
                        emergency_after_cas_loss(
                            "Replacement route lost authoritative readback after verification"
                        )
                        return
                    (
                        post_final_binding,
                        post_snapshot,
                        post_payload,
                    ) = post_verify_state
                    post_replacement_binding = (
                        self._runtime_route_binding_for_outbound(
                            post_snapshot,
                            post_payload,
                            failure.binding.observed_outbound,
                            require_final_exit=not underlay_domain,
                        )
                        if underlay_domain
                        else post_final_binding
                    )
                    if (
                        post_replacement_binding is None
                        or post_replacement_binding.node.key
                        != replacement_binding.node.key
                    ):
                        emergency_after_cas_loss(
                            "Replacement route changed during neutral verification"
                        )
                        return
                    if underlay_domain and (
                        post_final_binding.node.pool_kind != "gateway"
                        or original_gateway is None
                        or tuple(post_final_binding.node.key)
                        != tuple(original_gateway.node.key)
                    ):
                        emergency_after_cas_loss(
                            "Gateway identity changed during underlay verification"
                        )
                        return
                    replacement_binding = post_replacement_binding
                    _current_snapshot = post_snapshot
                    replacement_committed = False
                    with self._core_transition_lock:
                        with self._runtime_failure_monitor_lock:
                            if (
                                int(
                                    getattr(
                                        self,
                                        "_runtime_selector_intent_revision",
                                        0,
                                    )
                                    or 0
                                )
                                == selector_intent_revision
                                and int(
                                    getattr(
                                        self,
                                        "_runtime_facility_epoch",
                                        0,
                                    )
                                    or 0
                                )
                                == facility_epoch
                                and self._runtime_worker_token_is_current(
                                    worker_token
                                )
                                and self._runtime_recovery_ticket_is_current(
                                    recovery_ticket,
                                    require_open=True,
                                    deadline_monotonic=recovery_route_deadline,
                                )
                                and not self._runtime_facility_hold_reason()
                                and self._runtime_route_mutation_lease is None
                                and self._runtime_egress_coordinator.snapshot_ownership_matches(
                                    replacement_binding,
                                    expected_snapshot=_current_snapshot,
                                )
                            ):
                                # Mihomo itself may have moved to a healthy
                                # fallback while this worker waited for the
                                # global lease. Record automatic ownership so
                                # an exact PASS can still promote the original
                                # higher-priority path; never overwrite another
                                # incident's or the user's selector lease.
                                self._runtime_route_mutation_lease = {
                                    "group": (
                                        failure.binding.observed_outbound
                                        if underlay_domain
                                        else "FINAL-EXIT"
                                    ),
                                    "from": failure.binding.node.proxy_name,
                                    "to": replacement_binding.node.proxy_name,
                                    "incident_id": str(incident_id),
                                    "route_epoch": (
                                        replacement_binding.route_epoch
                                    ),
                                    "selector_intent_revision": (
                                        selector_intent_revision
                                    ),
                                    "recovery_ticket_generation": (
                                        recovery_ticket.generation
                                    ),
                                    "verified_at_monotonic": self._runtime_recovery_now(),
                                    "automatic": True,
                                }
                                verified_at = self._runtime_recovery_now()
                                self._runtime_last_verified_route = {
                                    "verified_at_monotonic": verified_at,
                                    "result": verified,
                                    "incident_id": str(incident_id),
                                    "leaf_proxy": (
                                        replacement_binding.node.proxy_name
                                    ),
                                }
                                self._set_effective_egress_state(True, "")
                                replacement_committed = True
                    if not replacement_committed:
                        with self._runtime_failure_monitor_lock:
                            self._runtime_incident_recovery_state[
                                str(incident_id)
                            ] = "indeterminate"
                        if not self._mark_runtime_recovery_quarantined(
                            failure.binding,
                            recovery_ticket=recovery_ticket,
                            coordinator_incident_id=(
                                coordinator_incident_id
                            ),
                            coordinator_quarantine_token=(
                                coordinator_quarantine_token
                            ),
                            deadline_monotonic=recovery_route_deadline,
                        ):
                            return
                        self._set_effective_egress_readiness_state(
                            None,
                            "Replacement route verification lost publication authority",
                        )
                        self._queue_runtime_route_snapshot_refresh()
                        return
                    # The replacement repaired effective traffic, not the
                    # failed leaf.  Keep its circuit quarantined until the
                    # exact authoritative recheck reports PASS.
                    if not self._mark_runtime_recovery_quarantined(
                        failure.binding,
                        recovery_ticket=recovery_ticket,
                        coordinator_incident_id=coordinator_incident_id,
                        coordinator_quarantine_token=(
                            coordinator_quarantine_token
                        ),
                        deadline_monotonic=recovery_route_deadline,
                    ):
                        return
                    self._start_runtime_connection_cleanup(failure.binding)
                    self._mark_runtime_incident_recovery_ready(
                        str(incident_id),
                        expected_ticket=recovery_ticket,
                    )
                    return
                try:
                    remaining_budget = self._runtime_recovery_remaining(
                        recovery_route_deadline
                    )
                    with self._core_transition_lock:
                        # The coordinator lease is acquired before the shared
                        # Core lock. A user selector/reload may have completed
                        # while this worker was waiting for that lock and
                        # revoked the loaded snapshot. Recheck after the wait
                        # so the automatic transaction cannot overwrite it.
                        if (
                            not self._runtime_worker_token_is_current(
                                worker_token
                            )
                            or int(
                                getattr(
                                    self,
                                    "_runtime_selector_intent_revision",
                                    0,
                                )
                                or 0
                            )
                            != selector_intent_revision
                            or not self._runtime_egress_coordinator.core_mutation_lease_is_current(
                                lease
                            )
                            or not self._runtime_recovery_ticket_is_current(
                                recovery_ticket,
                                require_open=True,
                                deadline_monotonic=recovery_route_deadline,
                            )
                        ):
                            with self._runtime_failure_monitor_lock:
                                self._runtime_incident_recovery_state[
                                    str(incident_id)
                                ] = "manual_superseded"
                                self._runtime_pending_recovered_payloads.pop(
                                    str(incident_id),
                                    None,
                                )
                            return
                        if remaining_budget <= 0.0:
                            audit = self._runtime_audit_base_result(
                                reason="runtime recovery reached its hard deadline",
                                trigger="runtime_global_circuit",
                            )
                            audit["deadline_exceeded"] = True
                        elif confirmed_alternative is not None:
                            try:
                                audit = self._fast_recover_confirmed_alternative(
                                    failure,
                                    snapshot,
                                    snapshot_payload,
                                    confirmed_alternative,
                                    incident_id=str(incident_id),
                                    selector_intent_revision=(
                                        selector_intent_revision
                                    ),
                                    deadline_monotonic=(
                                        recovery_route_deadline
                                    ),
                                    expected_worker_token=worker_token,
                                    prewarmed_result=(
                                        confirmed_alternative_probe_result
                                    ),
                                    prewarmed_evidence=(
                                        confirmed_alternative_evidence
                                    ),
                                    recovery_ticket=recovery_ticket,
                                )
                                if not audit.get("fast_path_available"):
                                    # Runtime health never rewrites the Core
                                    # graph. If the loaded graph cannot express
                                    # this selection dynamically, keep the
                                    # incident fail-closed and let a later
                                    # explicit inventory transaction reconcile
                                    # membership.
                                    audit = self._runtime_audit_base_result(
                                        reason=(
                                            "Loaded Mihomo graph has no dynamic "
                                            "selection path for the verified alternative"
                                        ),
                                        trigger="runtime_global_circuit",
                                    )
                                    audit["reload_blocked"] = True
                            except _RuntimeProbeBudgetUnavailable as exc:
                                # A selected route may already be live, but no
                                # authoritative full-chain socket verdict was
                                # obtained. Preserve that physical route and
                                # the failed-leaf quarantine; capacity pressure
                                # must never be upgraded to REJECT/Core stop.
                                audit = self._runtime_audit_base_result(
                                    reason=(
                                        "Confirmed alternative selection is awaiting "
                                        "full-chain probe capacity"
                                    ),
                                    trigger="runtime_global_circuit",
                                )
                                audit["probe_budget_indeterminate"] = True
                                audit["fast_switch_error"] = str(exc)
                            except Exception as exc:
                                audit = self._runtime_audit_base_result(
                                    reason=(
                                        "Confirmed alternative fast switch failed: "
                                        f"{exc}"
                                    ),
                                    trigger="runtime_global_circuit",
                                )
                                audit["fast_switch_error"] = str(exc)
                        else:
                            # The only confirmed node-domain event without an
                            # alternative is a fixed Gateway failure. It must
                            # fail closed rather than audit into another
                            # Gateway or the ordinary exit chain.
                            audit = self._runtime_audit_base_result(
                                reason=(
                                    "Fixed Gateway failed while its managed "
                                    "underlay remained healthy"
                                ),
                                trigger="runtime_global_circuit",
                            )
                            audit["gateway_fail_closed"] = True
                        recovered = bool(
                            audit.get("post_switch_connectivity_verified")
                            and audit.get("effective_egress_ok") is True
                        )
                        recovery_publication_superseded = bool(
                            audit.get("probe_budget_indeterminate")
                            or (
                                recovered
                                and (
                                not self._runtime_worker_token_is_current(
                                    worker_token
                                )
                                or bool(self._runtime_facility_hold_reason())
                                or int(
                                    getattr(
                                        self,
                                        "_runtime_selector_intent_revision",
                                        0,
                                    )
                                    or 0
                                )
                                    != selector_intent_revision
                                )
                            )
                        )
                        if recovery_publication_superseded:
                            # A successful socket that crossed a facility/user
                            # epoch is useful diagnostic evidence, but it has no
                            # authority to publish a verified route lease in the
                            # new context.  Leave the physical route untouched;
                            # the facility baseline/current snapshot will
                            # reconcile it without another selector write.
                            recovered = False
                            audit["effective_egress_ok"] = None
                            audit["route_commit_superseded"] = True
                            manual_superseded = bool(
                                int(
                                    getattr(
                                        self,
                                        "_runtime_selector_intent_revision",
                                        0,
                                    )
                                    or 0
                                )
                                != selector_intent_revision
                            )
                            if manual_superseded:
                                with self._runtime_failure_monitor_lock:
                                    self._runtime_incident_recovery_state[
                                        str(incident_id)
                                    ] = "manual_superseded"
                            if not audit.get("probe_budget_indeterminate"):
                                audit["reason"] = (
                                    "Replacement route verification crossed a "
                                    "facility or selector epoch"
                                )
                            if audit.get("probe_budget_indeterminate"):
                                # The alternative has no socket verdict, but
                                # the origin was confirmed in this same
                                # facility context. Keep that exact leaf
                                # quarantined. A facility epoch change is
                                # different: it revokes the old attribution
                                # and must not carry node punishment forward.
                                if not self._mark_runtime_recovery_quarantined(
                                    failure.binding,
                                    recovery_ticket=recovery_ticket,
                                    coordinator_incident_id=(
                                        coordinator_incident_id
                                    ),
                                    coordinator_quarantine_token=(
                                        coordinator_quarantine_token
                                    ),
                                    deadline_monotonic=(
                                        recovery_route_deadline
                                    ),
                                ):
                                    return
                        physical_fail_closed: dict[str, Any] = {}
                        physical_fail_closed_allowed = (
                            self._runtime_physical_fail_closed_allowed(
                                failure.binding,
                                gateway_failure_confirmed=(
                                    gateway_failure_confirmed
                                    and bool(audit.get("gateway_fail_closed"))
                                ),
                            )
                        )
                        if (
                            not recovered
                            and not recovery_publication_superseded
                            and physical_fail_closed_allowed
                        ):
                            # Keep the failed member quarantined even if the
                            # emergency action revokes the loaded snapshot or
                            # stops Core and therefore invalidates worker PID
                            # ownership before this thread exits.
                            if not self._admit_runtime_fail_closed_mutation(
                                recovery_ticket,
                                deadline_monotonic=(
                                    recovery_route_deadline
                                ),
                                failure_binding=failure.binding,
                                gateway_failure_confirmed=True,
                                expected_facility_epoch=facility_epoch,
                            ):
                                return
                            fail_closed_admitted = True
                            if not self._mark_runtime_recovery_quarantined(
                                failure.binding,
                                recovery_ticket=recovery_ticket,
                                coordinator_incident_id=(
                                    coordinator_incident_id
                                ),
                                coordinator_quarantine_token=(
                                    coordinator_quarantine_token
                                ),
                                deadline_monotonic=(
                                    recovery_route_deadline
                                ),
                            ):
                                return
                            with self._runtime_route_snapshot_lock:
                                fail_closed_route_epoch = int(
                                    self._runtime_route_epoch
                                )
                            physical_fail_closed = (
                                self._enforce_runtime_fail_closed(
                                    str(
                                        audit.get("reason")
                                        or "FINAL-EXIT fail-closed"
                                    ),
                                    failure_binding=failure.binding,
                                    gateway_failure_confirmed=True,
                                    deadline_monotonic=recovery_deadline,
                                    expected_worker_token=worker_token,
                                    expected_route_epoch=(
                                        fail_closed_route_epoch
                                    ),
                                    expected_selector_intent_revision=(
                                        selector_intent_revision
                                    ),
                                    expected_facility_epoch=facility_epoch,
                                )
                            )
                            audit["fail_closed_apply"] = physical_fail_closed
                            audit["fail_closed_terminal"] = bool(
                                physical_fail_closed.get("enforced")
                            )
                            if not physical_fail_closed.get("enforced"):
                                audit["reason"] = (
                                    f"{audit.get('reason') or 'FINAL-EXIT failure'}; "
                                    "physical fail-closed enforcement failed"
                                )
                                audit["effective_egress_ok"] = None
                            self._set_runtime_audit_result(
                                audit,
                                readiness_only=not bool(
                                    physical_fail_closed.get("enforced")
                                ),
                            )
                        elif not recovered and not recovery_publication_superseded:
                            # The failed leaf has been confirmed, but selector
                            # PUT/readback/deadline uncertainty is not proof
                            # that the whole Core should be replaced by REJECT.
                            # Preserve the current physical route and leak
                            # protection; only the exact leaf remains suspect.
                            self._mark_runtime_recovery_quarantined(
                                failure.binding,
                                recovery_ticket=recovery_ticket,
                                coordinator_incident_id=(
                                    coordinator_incident_id
                                ),
                                coordinator_quarantine_token=(
                                    coordinator_quarantine_token
                                ),
                                deadline_monotonic=recovery_route_deadline,
                            )
                            audit["effective_egress_ok"] = None
                            audit["physical_route_preserved"] = True
                            self._set_runtime_audit_result(
                                audit,
                                readiness_only=True,
                            )
                        # Publish the automatic selector lease before releasing
                        # the shared Core lock.  The audit may legitimately load
                        # a new route snapshot, so the pre-audit coordinator
                        # lease is not expected to own that new snapshot.  What
                        # matters here is that no manual selector transaction can
                        # interleave between the successful apply and this lease.
                        selection_action = audit.get("selection_action")
                        selection_action = (
                            selection_action
                            if isinstance(selection_action, dict)
                            else {}
                        )
                        recovered_publication_committed = False
                        if recovered:
                            with self._runtime_failure_monitor_lock:
                                if (
                                    int(
                                        getattr(
                                            self,
                                            "_runtime_facility_epoch",
                                            0,
                                        )
                                        or 0
                                    )
                                    == facility_epoch
                                    and not self._runtime_facility_hold_reason()
                                    and int(
                                        getattr(
                                            self,
                                            "_runtime_selector_intent_revision",
                                            0,
                                        )
                                        or 0
                                    )
                                    == selector_intent_revision
                                    and self._runtime_worker_token_is_current(
                                        worker_token
                                    )
                                    and self._runtime_recovery_ticket_matches_locked(
                                        recovery_ticket,
                                        require_open=True,
                                        deadline_monotonic=recovery_route_deadline,
                                    )
                                ):
                                    verified_at = self._runtime_recovery_now()
                                    new_lease = {
                                        "group": str(
                                            selection_action.get("group")
                                            or "FINAL-EXIT"
                                        ),
                                        "from": failure.binding.node.proxy_name,
                                        "to": str(
                                            audit.get("alternative_leaf")
                                            or audit.get("leaf_proxy")
                                            or ""
                                        ),
                                        "target_member": str(
                                            selection_action.get("target")
                                            or ""
                                        ),
                                        "mode": str(
                                            selection_action.get("mode")
                                            or "selector"
                                        ),
                                        "incident_id": str(incident_id),
                                        "route_epoch": int(
                                            audit.get("loaded_route_epoch")
                                            or failure.binding.route_epoch
                                        ),
                                        "selector_intent_revision": (
                                            selector_intent_revision
                                        ),
                                        "recovery_ticket_generation": (
                                            recovery_ticket.generation
                                        ),
                                        "recovery_deadline_monotonic": (
                                            recovery_route_deadline
                                        ),
                                        "verified_at_monotonic": verified_at,
                                        "automatic": True,
                                    }
                                    if self._runtime_commit_successor_lease_locked(
                                        new_lease,
                                        parent_lease,
                                    ):
                                        self._runtime_egress_coordinator.mark_quarantined(
                                            failure.binding,
                                            ttl_seconds=30.0,
                                            incident_id=(
                                                coordinator_incident_id
                                            ),
                                            quarantine_token=(
                                                coordinator_quarantine_token
                                            ),
                                        )
                                        terminal_outcome = (
                                            self._complete_runtime_recovery_outcome(
                                                str(incident_id),
                                                RuntimeRecoveryStatus.RECOVERED,
                                                reason_code="verified_route",
                                                to_ref=confirmed_alternative,
                                                route_epoch=int(
                                                    new_lease["route_epoch"]
                                                ),
                                                expected_ticket=recovery_ticket,
                                                deadline_monotonic=(
                                                    recovery_route_deadline
                                                ),
                                                completed_at_monotonic=(
                                                    verified_at
                                                ),
                                                facts={
                                                    "put": True,
                                                    "readback": True,
                                                    "final_204": True,
                                                },
                                            )
                                        )
                                        if (
                                            isinstance(
                                                terminal_outcome,
                                                RuntimeRecoveryOutcome,
                                            )
                                            and terminal_outcome.status
                                            is RuntimeRecoveryStatus.RECOVERED
                                        ):
                                            self._runtime_last_verified_route = {
                                                "verified_at_monotonic": verified_at,
                                                "incident_id": str(incident_id),
                                                "route": list(
                                                    audit.get("selected_chain") or []
                                                ),
                                                "leaf_proxy": str(
                                                    audit.get("alternative_leaf")
                                                    or audit.get("leaf_proxy")
                                                    or ""
                                                ),
                                                "result": dict(
                                                    audit.get("post_switch_result") or {}
                                                ),
                                                "worker_token": tuple(worker_token),
                                            }
                                            self._set_effective_egress_state(True, "")
                                            recovered_publication_committed = True
                            if not recovered_publication_committed:
                                recovered = False
                                recovery_publication_superseded = True
                                audit["effective_egress_ok"] = None
                                audit["route_commit_superseded"] = True
                        elif not physical_fail_closed.get("enforced"):
                            with self._runtime_failure_monitor_lock:
                                current_lease = self._runtime_route_mutation_lease
                                if not isinstance(current_lease, dict) or str(
                                    current_lease.get("incident_id") or ""
                                ) == str(incident_id):
                                    self._runtime_route_mutation_lease = None
                                if (
                                    self._runtime_incident_recovery_state.get(
                                        str(incident_id)
                                    )
                                    != "manual_superseded"
                                ):
                                    self._runtime_incident_recovery_state[
                                        str(incident_id)
                                    ] = "indeterminate"
                    if recovered:
                        # Replacement success repairs effective traffic only.
                        # Its circuit was quarantined in the same monitor-lock
                        # transaction immediately before the RECOVERED outcome
                        # was published, so no late circuit mutation follows a
                        # terminal result.
                        self._refresh_runtime_route_snapshot(
                            timeout_seconds=self._runtime_recovery_remaining(
                                recovery_deadline,
                                cap=0.35,
                            )
                        )
                    elif physical_fail_closed.get("enforced"):
                        self._set_effective_egress_state(
                            False,
                            str(audit.get("reason") or "FINAL-EXIT fail-closed"),
                        )
                finally:
                    self._runtime_egress_coordinator.end_core_mutation(lease)
                try:
                    if physical_fail_closed.get("enforced"):
                        self._commit_runtime_fail_closed_outcome(
                            physical=physical_fail_closed,
                            incident_id=str(incident_id),
                            from_proxy=failure.binding.node.proxy_name,
                            selector_intent_revision=(
                                selector_intent_revision
                            ),
                            expected_ticket=recovery_ticket,
                        )
                finally:
                    if fail_closed_admitted:
                        self._release_runtime_fail_closed_admission(
                            recovery_ticket
                        )
                        fail_closed_admitted = False
                if not recovered and not physical_fail_closed.get("enforced"):
                    with self._runtime_failure_monitor_lock:
                        manual_superseded = bool(
                            self._runtime_incident_recovery_state.get(
                                str(incident_id)
                            )
                            == "manual_superseded"
                        )
                    if manual_superseded:
                        return
                    self._complete_runtime_recovery_hold(
                        recovery_ticket,
                        reason_code="replacement_not_authoritatively_committed",
                    )
                    self._set_effective_egress_readiness_state(
                        None,
                        str(
                            audit.get("reason")
                            or "FINAL-EXIT route ownership is indeterminate"
                        ),
                    )
                    self._queue_runtime_route_snapshot_refresh()
                    return
                self._start_runtime_connection_cleanup(failure.binding)
                self._mark_runtime_incident_recovery_ready(
                    str(incident_id),
                    expected_ticket=recovery_ticket,
                )
            finally:
                if fail_closed_admitted:
                    self._release_runtime_fail_closed_admission(
                        recovery_ticket
                    )
                    fail_closed_admitted = False
                if recovery_pressure_lease is not None:
                    recovery_pressure_lease.release()
                if recovery_gate_lease is not None:
                    reload_gate = getattr(self, "_runtime_reload_gate", None)
                    if reload_gate is not None:
                        reload_gate.end_recovery(recovery_gate_lease)
                release_pending_recovery = False
                if (
                    self._runtime_worker_token_is_current(worker_token)
                    and int(
                        getattr(
                            self,
                            "_runtime_selector_intent_revision",
                            0,
                        )
                        or 0
                    )
                    == selector_intent_revision
                ):
                    with self._runtime_failure_monitor_lock:
                        release_pending_recovery = (
                            str(
                                self._runtime_incident_recovery_state.get(
                                    str(incident_id)
                                )
                                or ""
                            )
                            in {"pending", "recovering"}
                        )
                        if release_pending_recovery:
                            # An exception before physical selection proves
                            # neither REJECT nor a replacement. Never invent a
                            # route lease from coordinator bookkeeping; leave
                            # the physical route untouched and rebuild its
                            # authoritative snapshot instead.
                            self._runtime_incident_recovery_state[
                                str(incident_id)
                            ] = "indeterminate"
                if release_pending_recovery:
                    self._set_effective_egress_readiness_state(
                        None,
                        "FINAL-EXIT recovery transaction ended before a "
                        "route commit was verified",
                    )
                    self._queue_runtime_route_snapshot_refresh()
                reconcile_indeterminate = False
                reconcile_after_facility_change = bool(
                    int(getattr(self, "_runtime_facility_epoch", 0) or 0)
                    != facility_epoch
                )
                terminal_state = ""
                with self._runtime_failure_monitor_lock:
                    # This thread owns the admission key it inserted.  A
                    # facility/network/user epoch change revokes its right to
                    # publish, but must never revoke its duty to release that
                    # key; otherwise the same circuit is rejected forever.
                    self._runtime_failure_recovery_bindings.discard(key)
                    reconcile_indeterminate = bool(
                        str(
                            self._runtime_incident_recovery_state.get(
                                str(incident_id)
                            )
                            or ""
                        )
                        == "indeterminate"
                    )
                    terminal_state = str(
                        self._runtime_incident_recovery_state.get(
                            str(incident_id)
                        )
                        or ""
                    )
                    self._runtime_failure_recovery_threads.discard(
                        threading.current_thread()
                    )
                if terminal_state == "manual_superseded":
                    self._complete_runtime_recovery_outcome(
                        str(incident_id),
                        RuntimeRecoveryStatus.MANUAL_SUPERSEDED,
                        reason_code="selector_intent_changed",
                        expected_ticket=recovery_ticket,
                    )
                elif terminal_state in {"route_superseded", "stale"}:
                    self._complete_runtime_recovery_outcome(
                        str(incident_id),
                        RuntimeRecoveryStatus.STALE,
                        reason_code="route_authority_changed",
                        expected_ticket=recovery_ticket,
                    )
                elif reconcile_indeterminate:
                    self._complete_runtime_recovery_hold(
                        recovery_ticket,
                        reason_code="recovery_ended_without_authoritative_commit",
                    )
                    # A facility generation change revokes this worker's
                    # publication lease, but it also means the route must be
                    # rebound against the new generation.  Submit exactly one
                    # fresh neutral confirmation after releasing the old
                    # circuit admission; ordinary indeterminate outcomes stay
                    # held and cannot spin into an unbounded retry loop.
                    if (
                        reconcile_after_facility_change
                        and not self._runtime_facility_hold_reason()
                    ):
                        reconcile = getattr(
                            self,
                            "_submit_current_route_probe_failure",
                            None,
                        )
                        if callable(reconcile):
                            reconcile(
                                "runtime recovery ended with indeterminate "
                                "route ownership",
                                source="recovery_indeterminate_reconcile",
                            )

        thread = threading.Thread(
            target=worker,
            name="runtime-egress-recovery",
            daemon=True,
        )
        with self._runtime_failure_monitor_lock:
            self._runtime_failure_recovery_threads.add(thread)
        thread.start()

    @staticmethod
    def _runtime_recheck_ref(payload: dict[str, Any]) -> RuntimeNodeRef | None:
        tier = str(payload.get("tier") or "")
        identity = str(payload.get("identity") or "")
        proxy_name = str(payload.get("proxy_name") or "")
        if not tier or not identity or not proxy_name:
            return None
        return RuntimeNodeRef(
            tier=tier,
            pool_kind=str(payload.get("pool_kind") or ""),
            identity=identity,
            proxy_name=proxy_name,
        )

    @staticmethod
    def _runtime_leaf_export_hold_key(
        ref: RuntimeNodeRef,
    ) -> tuple[str, str, str]:
        # Manager identities include protocol and the complete connection
        # configuration.  This is the same exact-leaf key consumed by the Core
        # export view; Core proxy_name may be presentation-normalized or gain a
        # duplicate suffix and therefore is not a stable Manager inventory key.
        return (str(ref.tier), str(ref.pool_kind), str(ref.identity))

    def _schedule_runtime_leaf_recheck(
        self,
        payload: dict[str, Any],
        *,
        delay_seconds: float,
    ) -> None:
        ref = self._runtime_recheck_ref(payload)
        manager = self.manager
        has_incident = bool(str(payload.get("incident_id") or ""))
        enqueue = getattr(
            manager,
            "enqueue_runtime_leaf_recheck" if has_incident else "enqueue_node_health_check",
            None,
        )
        if ref is None or not callable(enqueue):
            return
        worker_token = self._runtime_worker_token()

        def worker() -> None:
            if self.stop_event.wait(max(0.0, float(delay_seconds))):
                return
            if not self._runtime_worker_token_is_current(worker_token):
                return
            try:
                if not has_incident:
                    enqueue(
                        ref, reason="runtime neutral leaf check retry",
                        source="runtime_recovery",
                    )
                    return
                enqueue(
                    ref,
                    reason="runtime recovery-only leaf recheck",
                    source="runtime_recovery",
                    incident_id=str(payload.get("incident_id") or ""),
                    quarantine_token=str(payload.get("quarantine_token") or ""),
                    runtime_generation=int(payload.get("runtime_generation") or 0),
                    semantic_digest=str(payload.get("semantic_digest") or ""),
                    failure_epoch=payload.get("failure_epoch"),
                )
            except Exception:
                log_raw_diagnostic(
                    self.logger,
                    "warning",
                    "Runtime recovery-only recheck could not be queued",
                    exc_info=True,
                )

        threading.Thread(
            target=worker,
            name="runtime-leaf-recheck-scheduler",
            daemon=True,
        ).start()

    def _mark_runtime_incident_recovery_ready(
        self,
        incident_id: str,
        *,
        expected_ticket: _RuntimeRecoveryTicket | None = None,
    ) -> None:
        if not isinstance(expected_ticket, _RuntimeRecoveryTicket):
            return
        pending: dict[str, Any] | None = None
        terminal_status: RuntimeRecoveryStatus | None = None
        terminal_reason = ""
        target_proxy = ""
        completed_at: float | None = None
        recovery_deadline: float | None = None
        with self._runtime_failure_monitor_lock:
            tickets = getattr(self, "_runtime_recovery_tickets", {})
            current_ticket = (
                tickets.get(str(incident_id))
                if isinstance(tickets, dict)
                else None
            )
            if not (
                isinstance(current_ticket, _RuntimeRecoveryTicket)
                and current_ticket.generation == expected_ticket.generation
            ):
                return
            lease = getattr(self, "_runtime_route_mutation_lease", None)
            owners = getattr(self, "_runtime_core_stopped_recovery_owners", {})
            if (
                isinstance(lease, dict)
                and str(lease.get("incident_id") or "") == str(incident_id)
                and int(
                    lease.get(
                        "recovery_ticket_generation",
                        0,
                    )
                    or 0
                )
                == expected_ticket.generation
                and float(lease.get("verified_at_monotonic") or 0.0) > 0.0
            ):
                target_proxy = str(lease.get("to") or "")
                completed_at = float(
                    lease.get("verified_at_monotonic") or 0.0
                )
                recovery_deadline = min(
                    float(expected_ticket.deadline_monotonic),
                    float(
                        lease.get("recovery_deadline_monotonic")
                        or expected_ticket.deadline_monotonic
                    ),
                )
                terminal_status = (
                    RuntimeRecoveryStatus.FAIL_CLOSED
                    if target_proxy == "REJECT"
                    else RuntimeRecoveryStatus.RECOVERED
                )
                terminal_reason = (
                    "verified_reject"
                    if target_proxy == "REJECT"
                    else "verified_route"
                )
            elif (
                isinstance(owners, dict)
                and str(incident_id) in owners
                and isinstance(owners[str(incident_id)], dict)
                and int(
                    owners[str(incident_id)].get(
                        "recovery_ticket_generation",
                        0,
                    )
                    or 0
                )
                == expected_ticket.generation
            ):
                completed_at = float(
                    owners[str(incident_id)].get(
                        "fail_closed_at_monotonic",
                        0.0,
                    )
                    or 0.0
                )
                terminal_status = RuntimeRecoveryStatus.FAIL_CLOSED
                terminal_reason = "verified_core_stop"
        if terminal_status is None:
            return
        to_ref = (
            self._runtime_recovery_ref_for_proxy(target_proxy)
            if terminal_status is RuntimeRecoveryStatus.RECOVERED
            else None
        )
        outcome = self._complete_runtime_recovery_outcome(
            str(incident_id),
            terminal_status,
            reason_code=terminal_reason,
            to_ref=to_ref,
            expected_ticket=expected_ticket,
            deadline_monotonic=recovery_deadline,
            completed_at_monotonic=completed_at,
            facts={
                "put": terminal_reason in {"verified_route", "verified_reject"},
                "readback": terminal_reason in {"verified_route", "verified_reject"},
                "final_204": terminal_status is RuntimeRecoveryStatus.RECOVERED,
            },
        )
        if not (
            isinstance(outcome, RuntimeRecoveryOutcome)
            and outcome.status is terminal_status
        ):
            return
        with self._runtime_failure_monitor_lock:
            tickets = getattr(self, "_runtime_recovery_tickets", {})
            current_ticket = (
                tickets.get(str(incident_id))
                if isinstance(tickets, dict)
                else None
            )
            if not (
                isinstance(current_ticket, _RuntimeRecoveryTicket)
                and current_ticket.generation == expected_ticket.generation
            ):
                return
            self._runtime_incident_recovery_state[str(incident_id)] = (
                "core_stopped_fail_closed"
                if terminal_reason == "verified_core_stop"
                else "ready"
            )
            value = self._runtime_pending_recovered_payloads.pop(
                str(incident_id),
                None,
            )
            if isinstance(value, dict):
                pending = value
        if pending is not None:
            self._on_runtime_leaf_recheck_result(pending)
        if terminal_status is RuntimeRecoveryStatus.RECOVERED:
            # Automatic selector mutation increments route_epoch and revokes
            # the old arm.  Only recreate it after the terminal RECOVERED
            # outcome and READY state above; _try_arm_runtime_recovery then
            # performs the full snapshot/binding/facility/worker CAS.
            if not self._try_arm_runtime_recovery():
                self._queue_runtime_route_snapshot_refresh()

    def _on_runtime_leaf_recheck_result_early(
        self,
        payload: dict[str, Any],
    ) -> None:
        """Let authoritative checks resume native fallback, with bounded repair."""
        if not isinstance(payload, dict) or self.stop_event.is_set():
            return
        transition = payload.get("transition")
        transition = transition if isinstance(transition, dict) else {}
        action = str(transition.get("action") or "")
        incident_id = str(payload.get("incident_id") or "")
        ref = self._runtime_recheck_ref(payload)
        if ref is None:
            return
        retry_key = incident_id or repr(ref.key)
        if action == "pass_confirmation_pending":
            self._schedule_runtime_leaf_recheck(payload, delay_seconds=2.0)
            return
        if action == "pending":
            with self._runtime_failure_monitor_lock:
                attempts = self._runtime_recheck_retry_attempts
                attempt = int(attempts.get(retry_key, 0))
                if attempt >= 3:
                    return
                attempts[retry_key] = attempt + 1
            self._schedule_runtime_leaf_recheck(payload, delay_seconds=(5.0, 15.0, 30.0)[attempt])
            return
        # An authoritative FAIL waits for ordinary health checking. It must
        # not create a perpetual node-specific recovery polling loop.
        if action != "recovered" or payload.get("authoritative") is False:
            return
        with self._runtime_failure_monitor_lock:
            self._runtime_recheck_retry_attempts.pop(retry_key, None)
            lease = self._runtime_route_mutation_lease
            if not isinstance(lease, dict):
                # The check can finish before the A->B transaction publishes
                # its lease. Its completion hook drains this bounded mailbox.
                if any(value in {"pending", "recovering"} for value in self._runtime_incident_recovery_state.values()):
                    pending = self._runtime_pending_recovered_payloads
                    if len(pending) < 32:
                        pending[incident_id or repr(ref.key)] = dict(payload)
                return
            if str(lease.get("mode") or "") != "fixed":
                return
            if int(lease.get("selector_intent_revision", -1)) != int(getattr(self, "_runtime_selector_intent_revision", 0) or 0):
                lease["release_state"] = "superseded"
                return
            if self._route_lease_takes_passive_pass(lease):
                # Route lease: a TIER3-AUTO pin ends by TTL or by Mihomo's own
                # check of the predicted winner; the PASS only wakes the watcher
                # (no prewarm /delay, never a rollback re-pin).
                self._route_lease_wake("leaf_recheck_pass")
                return
            owner = str(lease.get("incident_id") or "")
            binding = self._runtime_incident_bindings.get(owner)
            if not isinstance(binding, RuntimeRouteBinding):
                return
            lease_record = dict(lease)
        snapshot, loaded_payload = self._runtime_route_snapshot_state()
        if snapshot is None or not isinstance(loaded_payload, dict):
            self._queue_runtime_route_snapshot_refresh()
            self._defer_runtime_passive_failback_readback(payload, lease)
            return
        target = self._runtime_passive_failback_target(snapshot, loaded_payload, lease_record, ref)
        if target is None:
            return
        worker_token = self._runtime_worker_token()
        with self._runtime_failure_monitor_lock:
            if self._runtime_route_mutation_lease is not lease:
                return
            requests = getattr(self, "_runtime_passive_failback_requests", None)
            if requests is None:
                requests = self._runtime_passive_failback_requests = {}
            previous = requests.get(owner)
            same_owner = bool(
                isinstance(previous, dict) and previous.get("lease") is lease
                and previous.get("signature") == self._runtime_route_lease_cas_signature(lease)
                and previous.get("worker_token") == worker_token
            )
            if same_owner and previous.get("running"):
                return
            check_run_id = str(payload.get("check_run_id") or "")
            if check_run_id and same_owner and previous.get("check_run_id") == check_run_id:
                return
            for key, value in list(requests.items()):
                if key != owner and not value.get("running"):
                    requests.pop(key, None)
            request = {
                "lease": lease, "signature": self._runtime_route_lease_cas_signature(lease),
                "binding": binding, "ref": target[0], "target": target[1],
                "payload": dict(payload), "worker_token": worker_token,
                "running": True, "attempt": 0, "check_run_id": check_run_id,
            }
            requests[owner] = request
            lease["release_state"] = "pending"
        thread = threading.Thread(target=self._run_runtime_passive_failback, args=(request,), name="runtime-passive-failback", daemon=True)
        with self._runtime_failure_monitor_lock:
            self._runtime_failure_recovery_threads.add(thread)
        thread.start()

    def _defer_runtime_passive_failback_readback(
        self, payload: dict[str, Any], lease: dict[str, Any],
    ) -> None:
        """Give a PASS three controller-only retries when route authority is absent."""
        owner = str(lease.get("incident_id") or "")
        check_id = str(payload.get("check_run_id") or "")
        ref = self._runtime_recheck_ref(payload)
        if ref is None:
            return
        payload_key = repr(ref.key)
        worker_token = self._runtime_worker_token()
        with self._runtime_failure_monitor_lock:
            if self._runtime_route_mutation_lease is not lease:
                return
            records = getattr(self, "_runtime_passive_failback_readbacks", None)
            if records is None:
                records = self._runtime_passive_failback_readbacks = {}
            previous = records.get(owner)
            same_owner = bool(
                isinstance(previous, dict) and previous.get("lease") is lease
                and previous.get("signature") == self._runtime_route_lease_cas_signature(lease)
                and previous.get("worker_token") == worker_token
            )
            if same_owner and previous.get("running"):
                # A lower-priority PASS must not replace an earlier recovery
                # notification while controller authority is unavailable.
                pending = previous["payloads"]
                if payload_key in pending or len(pending) < 32:
                    pending[payload_key] = dict(payload)
                previous["check_run_id"] = check_id
                return
            if check_id and same_owner and previous.get("check_run_id") == check_id:
                return
            for key, value in list(records.items()):
                if key != owner and not value.get("running"):
                    records.pop(key, None)
            record = {
                "lease": lease, "signature": self._runtime_route_lease_cas_signature(lease),
                "worker_token": worker_token, "check_run_id": check_id,
                "payloads": {payload_key: dict(payload)}, "running": True,
            }
            records[owner] = record
            lease["release_state"] = "readback_pending"

        def worker() -> None:
            try:
                for delay in (5.0, 15.0, 30.0):
                    if self.stop_event.wait(delay):
                        return
                    if not self._runtime_passive_failback_is_current(record):
                        lease["release_state"] = "superseded"
                        return
                    try:
                        self._refresh_runtime_route_snapshot(timeout_seconds=0.35)
                        snapshot, loaded = self._runtime_route_snapshot_state()
                    except Exception:
                        continue
                    if snapshot is None or not isinstance(loaded, dict):
                        continue
                    if not self._runtime_passive_failback_is_current(record):
                        lease["release_state"] = "superseded"
                        return
                    with self._runtime_failure_monitor_lock:
                        pending = list(record["payloads"].values())
                    for latest in pending:
                        self._on_runtime_leaf_recheck_result_early(latest)
                    snapshot, loaded = self._runtime_route_snapshot_state()
                    if snapshot is not None and isinstance(loaded, dict):
                        return
            finally:
                with self._runtime_failure_monitor_lock:
                    record["running"] = False
                    record.pop("payloads", None)
                    self._runtime_failure_recovery_threads.discard(threading.current_thread())

        thread = threading.Thread(target=worker, name="runtime-passive-readback", daemon=True)
        with self._runtime_failure_monitor_lock:
            self._runtime_failure_recovery_threads.add(thread)
        thread.start()

    def _resume_runtime_passive_failback(self) -> None:
        """Consume PASS events deferred until the current recovery commits."""
        with self._runtime_failure_monitor_lock:
            pending = list(self._runtime_pending_recovered_payloads.values())
            self._runtime_pending_recovered_payloads.clear()
        for payload in pending:
            self._on_runtime_leaf_recheck_result_early(payload)

    def _runtime_passive_failback_target(
        self, snapshot: CoreLoadedRouteSnapshot, payload: dict[str, Any],
        lease: dict[str, Any], ref: RuntimeNodeRef,
    ) -> tuple[RuntimeNodeRef, str] | None:
        """Resolve an earlier member of this exact loaded fallback domain."""
        matches = [node for node in snapshot.proxy_nodes if (node.tier, node.pool_kind, node.identity) == (ref.tier, ref.pool_kind, ref.identity)]
        if len(matches) != 1 or matches[0].pool_kind == "gateway":
            return None
        ref = matches[0]
        if not self._runtime_candidate_is_eligible(self._runtime_candidate_health_snapshot(), ref):
            return None
        from runtime_fallback_paths import preferred_fallback_path

        path = preferred_fallback_path(
            self._runtime_proxy_entries(payload), str(lease.get("group") or ""),
            str(lease.get("target_member") or lease.get("to") or ""), ref.proxy_name,
        )
        return (ref, path[1]) if path is not None else None

    def _prewarm_runtime_passive_fallback_path(
        self, snapshot: CoreLoadedRouteSnapshot, payload: dict[str, Any],
        lease: dict[str, Any], ref: RuntimeNodeRef, *, deadline_monotonic: float,
        ownership_check: Callable[[], bool],
    ) -> None:
        """Refresh nested native health from the inside out, without selection."""
        from runtime_fallback_paths import preferred_fallback_path

        entries = self._runtime_proxy_entries(payload)
        group = str(lease.get("group") or "")
        path = preferred_fallback_path(entries, group, str(lease.get("target_member") or lease.get("to") or ""), ref.proxy_name)
        if path is None or not ownership_check():
            raise RuntimeControllerReadbackError("recovered fallback path was superseded")
        selected = inspect_runtime_route(payload.get("proxies"), start=path[1])
        groups = [name for name in reversed(path[1:-1]) if "fallback" in str(entries[name].get("typeName") or entries[name].get("type") or "").casefold()] if str(selected.get("leaf_proxy") or "") != ref.proxy_name else []
        for index, inner in enumerate(groups):
            # Check only this path's immediate child using the owning group's
            # URL contract. Whole-group health rounds would open unrelated
            # sockets outside the shared two-probe broker.
            remaining = self._runtime_recovery_remaining(deadline_monotonic)
            seconds = min(1.0, (remaining - 1.5) / (len(groups) - index))
            if seconds < 0.1:
                raise _RuntimeProbeBudgetUnavailable("nested fallback refresh budget exhausted")
            child = path[path.index(inner) + 1]
            self._prewarm_runtime_switch_target(
                snapshot, {"mode": "fixed", "group": inner, "target": child},
                deadline_monotonic=min(deadline_monotonic, self._runtime_recovery_now() + seconds),
            )
            if not ownership_check():
                raise RuntimeControllerReadbackError("nested fallback refresh was superseded")
        if groups:
            refreshed = self._refresh_runtime_route_snapshot(timeout_seconds=0.35)
            _snapshot, refreshed_payload = self._runtime_route_snapshot_state()
            if refreshed is None or not isinstance(refreshed_payload, dict):
                raise RuntimeControllerReadbackError("nested fallback health readback unavailable")
            lawful = self._runtime_passive_failback_target(refreshed, refreshed_payload, lease, ref)
            if lawful is None or not ownership_check():
                raise RuntimeControllerReadbackError("nested selector intent changed during health refresh")
            snapshot = refreshed
        self._prewarm_runtime_switch_target(
            snapshot, {"mode": "fixed", "group": group, "target": path[1]},
            deadline_monotonic=deadline_monotonic,
        )

    def _runtime_passive_failback_is_current(self, request: dict[str, Any]) -> bool:
        if not self._runtime_worker_token_is_current(request["worker_token"]):
            return False
        with self._runtime_failure_monitor_lock:
            lease = self._runtime_route_mutation_lease
            return bool(lease is request["lease"] and self._runtime_route_lease_cas_signature(lease) == request["signature"] and int(lease.get("selector_intent_revision", -1)) == int(getattr(self, "_runtime_selector_intent_revision", 0) or 0))

    def _runtime_passive_failback_confirmation_pending(self, request: dict[str, Any]) -> bool:
        binding = request["binding"]
        with self._runtime_failure_monitor_lock:
            return any(
                key[:4] == binding.snapshot_key[:4]
                and key[5] == binding.network_context_epoch
                for key in getattr(self, "_runtime_failure_probe_bindings", ())
                if isinstance(key, tuple) and len(key) >= 6
            )

    def _run_runtime_passive_failback(self, request: dict[str, Any]) -> None:
        """A PASS starts at most four bounded transactions, then waits for events."""
        lease = request["lease"]
        try:
            for attempt, delay in enumerate((0.0, 5.0, 15.0, 30.0)):
                if delay and self.stop_event.wait(delay):
                    return
                if not self._runtime_passive_failback_is_current(request):
                    lease["release_state"] = "superseded"
                    return
                request["attempt"] = attempt
                result = self._attempt_runtime_passive_failback(request)
                if result in {"released", "superseded", "failed"}:
                    return
        finally:
            with self._runtime_failure_monitor_lock:
                request["running"] = False
                self._runtime_failure_recovery_threads.discard(threading.current_thread())

    def _attempt_runtime_passive_failback(self, request: dict[str, Any]) -> str:
        lease = request["lease"]
        binding = request["binding"]
        deadline = self._runtime_recovery_now() + 4.5
        promotion_deadline = deadline - 2.0
        changed = False
        rollback_verified = False
        final_gateway_key = None

        def current() -> bool:
            return self._runtime_passive_failback_is_current(request)

        def mutation_current() -> bool:
            if not current():
                return False
            # A recheck PASS is not permission to invalidate the snapshot of
            # another in-flight confirmation on this same Core/network epoch.
            if self._runtime_passive_failback_confirmation_pending(request):
                raise _RuntimeFailbackDeferred()
            return True

        try:
            if not mutation_current():
                lease["release_state"] = "superseded"
                return "superseded"
            snapshot = self._refresh_runtime_route_snapshot(timeout_seconds=0.35)
            _snapshot, payload = self._runtime_route_snapshot_state()
            if snapshot is None or not isinstance(payload, dict):
                raise RuntimeControllerReadbackError("PASS release route readback unavailable")
            if not mutation_current():
                lease["release_state"] = "superseded"
                return "superseded"
            selected = self._runtime_route_binding_for_outbound(snapshot, payload, binding.observed_outbound)
            final = self._runtime_route_binding_for_outbound(snapshot, payload, "FINAL-EXIT")
            if selected is None or final is None:
                raise RuntimeControllerReadbackError("PASS release route is not managed")
            if final.node.pool_kind == "gateway":
                final_gateway_key = final.node.key
            target = self._runtime_passive_failback_target(snapshot, payload, lease, request["ref"])
            if target is None:
                return "failed"
            if target[1] != target[0].proxy_name:
                # Nested native groups need one bounded inside-out health
                # refresh before the outer temporary pin can be released.
                deadline += 1.5
                promotion_deadline += 1.5
            with self._runtime_egress_coordinator.core_mutation_transaction(selected, expected_snapshot=snapshot, timeout_seconds=0.0) as mutation:
                if mutation is None:
                    raise RuntimeControllerReadbackError("PASS release route transaction busy")
                with self._bounded_core_transition(deadline, "authoritative PASS fallback restoration"):
                    if not mutation_current():
                        lease["release_state"] = "superseded"
                        return "superseded"
                    # Populate native health only for the exact promoted member.
                    # This is a bounded response to PASS, never periodic traffic.
                    lease["release_state"] = "releasing"
                    result = self._release_runtime_automatic_fixed_selection(
                        dict(lease), deadline_monotonic=promotion_deadline,
                        readback_first=True, ownership_check=mutation_current,
                        before_release=lambda: self._prewarm_runtime_passive_fallback_path(
                            snapshot, payload, lease, target[0],
                            deadline_monotonic=promotion_deadline, ownership_check=mutation_current,
                        ),
                    )
                    state = str(result.get("commit_state") or "unknown")
                    if state == "superseded" or not mutation_current():
                        lease["release_state"] = "superseded"
                        return "superseded"
                    if state != "committed":
                        lease["release_state"] = "readback_pending" if state == "unknown" else "pending"
                        return lease["release_state"]
                    changed = True
                    promoted = self._refresh_runtime_route_snapshot(timeout_seconds=0.35)
                    _snapshot, promoted_payload = self._runtime_route_snapshot_state()
                    winner = self._runtime_route_binding_for_outbound(promoted, promoted_payload, binding.observed_outbound) if promoted is not None and isinstance(promoted_payload, dict) else None
                    winner_final = self._runtime_route_binding_for_outbound(promoted, promoted_payload, "FINAL-EXIT") if winner is not None else None
                    if winner is None or winner_final is None or (winner.node.key != target[0].key and self._runtime_passive_failback_target(promoted, promoted_payload, lease, winner.node) is None):
                        raise RuntimeControllerReadbackError("native fallback selected an unverified or nonpreferred member")
                    if final_gateway_key is not None and winner_final.node.key != final_gateway_key:
                        raise RuntimeControllerReadbackError("Gateway identity changed during PASS release")
                    if self._runtime_recovery_remaining(promotion_deadline) < 0.2:
                        raise TimeoutError("PASS promotion verification budget exhausted")
                    verified = self._verify_runtime_final_exit(expected_worker_token=request["worker_token"], expected_snapshot=promoted, timeout_seconds=promotion_deadline-self._runtime_recovery_now(), recovery_deadline_monotonic=promotion_deadline)
                    if self._runtime_recovery_remaining(promotion_deadline) <= 0.0:
                        raise TimeoutError("PASS promotion verification exceeded its deadline")
                    if not mutation_current():
                        lease["release_state"] = "superseded"
                        return "superseded"
                    with self._runtime_failure_monitor_lock:
                        if not mutation_current():
                            return "superseded"
                        lease["release_state"] = "released"
                        self._runtime_route_mutation_lease = None
                        self._runtime_last_verified_route = {"incident_id": lease["incident_id"], "leaf_proxy": winner.node.proxy_name, "verified_at_monotonic": self._runtime_recovery_now(), "result": verified}
                    self._clear_runtime_audit_export_identity(target[0].identity)
                    self._set_effective_egress_state(True, "")
                    self._try_arm_runtime_recovery()
                    publish = getattr(self, "_publish_verified_runtime_source_proof", None)
                    if callable(publish):
                        publish(expected_route_epoch=promoted.route_epoch)
                    return "released"
        except _RuntimeFailbackDeferred:
            lease["release_state"] = "pending"
            return "recovery_pending"
        except Exception as exc:
            if not current():
                lease["release_state"] = "superseded"
                return "superseded"
            if self._runtime_passive_failback_confirmation_pending(request):
                lease["release_state"] = "pending"
                return "recovery_pending"
            # A failed promotion must keep the previous verified backup. A
            # separate transaction is safe only while the same lease owns it.
            if changed:
                try:
                    remaining = self._runtime_recovery_remaining(deadline)
                    if remaining < 0.2:
                        raise TimeoutError("PASS restoration rollback budget exhausted")
                    snapshot = self._refresh_runtime_route_snapshot(timeout_seconds=min(0.35, remaining))
                    _snapshot, payload = self._runtime_route_snapshot_state()
                    route = self._runtime_route_binding_for_outbound(snapshot, payload, binding.observed_outbound) if snapshot is not None and isinstance(payload, dict) else None
                    if route is None:
                        raise RuntimeControllerReadbackError("rollback authority unavailable")
                    with self._runtime_egress_coordinator.core_mutation_transaction(route, expected_snapshot=snapshot, timeout_seconds=0.0) as mutation:
                        if mutation is None:
                            raise RuntimeControllerReadbackError("rollback transaction busy")
                        with self._bounded_core_transition(deadline, "PASS restoration rollback"):
                            if not mutation_current():
                                return "superseded"
                            restored, _payload, _final = self._restore_runtime_automatic_route(incident_binding=binding, previous_binding=selected, previous_payload=payload, lease_record=dict(lease), incident_id=str(lease["incident_id"]), deadline_monotonic=deadline, expected_gateway_key=final_gateway_key)
                            if self._runtime_recovery_remaining(deadline) < 0.2:
                                raise TimeoutError("PASS rollback verification budget exhausted")
                            verified = self._verify_runtime_final_exit(expected_worker_token=request["worker_token"], expected_snapshot=restored, timeout_seconds=deadline-self._runtime_recovery_now(), recovery_deadline_monotonic=deadline)
                            if self._runtime_recovery_remaining(deadline) <= 0.0:
                                raise TimeoutError("PASS rollback verification exceeded its deadline")
                            if current():
                                with self._runtime_failure_monitor_lock:
                                    lease["route_epoch"] = restored.route_epoch
                                    lease["verified_at_monotonic"] = self._runtime_recovery_now()
                                    request["signature"] = self._runtime_route_lease_cas_signature(lease)
                                    self._runtime_last_verified_route = {"incident_id": lease["incident_id"], "leaf_proxy": lease["to"], "verified_at_monotonic": lease["verified_at_monotonic"], "result": verified}
                                rollback_verified = True
                                self._set_effective_egress_state(True, "")
                                self._try_arm_runtime_recovery()
                                publish = getattr(self, "_publish_verified_runtime_source_proof", None)
                                if callable(publish):
                                    publish(expected_route_epoch=restored.route_epoch)
                except Exception:
                    self._queue_runtime_route_snapshot_refresh()
            if not current():
                lease["release_state"] = "superseded"
                return "superseded"
            lease["release_state"] = "pending"
            log_raw_diagnostic(self.logger, "warning", "Authoritative PASS fallback restoration remains pending", exc_info=True)
            if changed and not rollback_verified:
                self._set_effective_egress_state(None, "PASS restoration requires route readback")
            return "pending"
        finally:
            # DELETE/readback ambiguity always has an observation path; never
            # consume the only PASS and leave a revoked snapshot unobserved.
            self._queue_runtime_route_snapshot_refresh()

    def _on_runtime_leaf_recheck_result(self, payload: dict[str, Any]) -> None:
        if self._runtime_uses_early_single_coordinator():
            self._on_runtime_leaf_recheck_result_early(payload)
            return
        if not isinstance(payload, dict) or self.stop_event.is_set():
            return
        transition = payload.get("transition")
        transition = transition if isinstance(transition, dict) else {}
        action = str(transition.get("action") or "")
        incident_id = str(payload.get("incident_id") or "")
        if action == "pass_confirmation_pending":
            self._schedule_runtime_leaf_recheck(payload, delay_seconds=2.0)
            return
        if action in {"pending", "transferred"}:
            attempt = int(self._runtime_recheck_retry_attempts.get(incident_id, 0))
            delays = (5.0, 15.0, 30.0)
            if attempt < len(delays):
                self._runtime_recheck_retry_attempts[incident_id] = attempt + 1
                self._schedule_runtime_leaf_recheck(
                    payload,
                    delay_seconds=delays[attempt],
                )
            return
        if action != "recovered":
            return
        self._runtime_recheck_retry_attempts.pop(incident_id, None)
        with self._runtime_failure_monitor_lock:
            recovery_state = str(
                self._runtime_incident_recovery_state.get(incident_id) or ""
            )
            if recovery_state in {"pending", "recovering"}:
                self._runtime_pending_recovered_payloads[incident_id] = dict(
                    payload
                )
                return
            if recovery_state == "manual_superseded":
                return
        ref = self._runtime_recheck_ref(payload)
        if ref is None:
            return
        # Manager has released the health overlay, but health recovery and
        # route promotion are separate.  Record the first authoritative PASS;
        # promotion performs a second direct PASS after the dwell window.
        with self._runtime_failure_monitor_lock:
            if (
                incident_id not in self._runtime_incident_bindings
                or not isinstance(
                    self._runtime_incident_route_payloads.get(incident_id),
                    dict,
                )
            ):
                return
            history_map = getattr(
                self,
                "_runtime_failback_pass_history",
                None,
            )
            if history_map is None:
                history_map = {}
                self._runtime_failback_pass_history = history_map
            history = history_map.setdefault(
                ref.key,
                [],
            )
            history.append(time.monotonic())
            history_map[ref.key] = history[-4:]
        self._clear_runtime_audit_export_identity(ref.identity)
        self._start_runtime_failback(payload, ref)

    def _restore_runtime_selector_path(
        self,
        binding: RuntimeRouteBinding,
        snapshot_payload: dict[str, Any],
        *,
        incident_id: str,
        deadline_monotonic: float | None = None,
        current_snapshot_payload: dict[str, Any] | None = None,
    ) -> list[dict[str, str]]:
        lease = self._runtime_route_mutation_lease
        if not isinstance(lease, dict) or str(lease.get("incident_id") or "") != incident_id:
            return []
        proxies_payload = snapshot_payload.get("proxies")
        if not isinstance(proxies_payload, dict):
            return []
        entries = proxies_payload.get("proxies")
        if not isinstance(entries, dict):
            entries = proxies_payload
        current_proxies = (
            current_snapshot_payload.get("proxies")
            if isinstance(current_snapshot_payload, dict)
            else None
        )
        current_entries = (
            current_proxies.get("proxies")
            if isinstance(current_proxies, dict)
            else None
        )
        if not isinstance(current_entries, dict):
            current_entries = current_proxies if isinstance(current_proxies, dict) else {}
        chain = list(binding.route_chain)
        actions: list[dict[str, str]] = []
        # Restore the deepest selector first. Exposing an outer selector before
        # its child points at the verified member can momentarily route new
        # connections through a half-restored chain.
        for index in reversed(range(max(0, len(chain) - 1))):
            group = chain[index]
            remaining = (
                None
                if deadline_monotonic is None
                else float(deadline_monotonic) - time.monotonic()
            )
            if remaining is not None and remaining <= 0.0:
                raise TimeoutError(
                    "failback deadline expired during selector restoration"
                )
            entry = entries.get(group) if isinstance(entries, dict) else None
            if not isinstance(entry, dict):
                continue
            type_name = str(entry.get("typeName") or entry.get("type") or "").casefold()
            if "select" not in type_name and "selector" not in type_name:
                continue
            candidate = str(chain[index + 1])
            members = entry.get("all")
            if members is None:
                members = entry.get("proxies")
            if isinstance(members, (list, tuple)) and candidate not in {
                str(item) for item in members
            }:
                continue
            current_entry = current_entries.get(group)
            if (
                isinstance(current_entry, dict)
                and str(current_entry.get("now") or "") == candidate
            ):
                continue
            action_deadline = (
                float(deadline_monotonic)
                if deadline_monotonic is not None
                else time.monotonic() + 1.5
            )
            self._apply_runtime_automatic_selection(
                {
                    "group": str(group),
                    "target": candidate,
                    "previous": str(
                        current_entry.get("now")
                        if isinstance(current_entry, dict)
                        else ""
                    ),
                    "mode": "selector",
                    "alternative_leaf": binding.node.proxy_name,
                },
                deadline_monotonic=action_deadline,
            )
            actions.append({"group": str(group), "proxy": candidate})
        return actions

    def _defer_runtime_failback(
        self,
        payload: dict[str, Any],
        ref: RuntimeNodeRef,
    ) -> None:
        incident_id = str(payload.get("incident_id") or "")
        if not incident_id:
            return
        with self._runtime_failure_monitor_lock:
            self._runtime_deferred_failbacks[incident_id] = {
                "payload": dict(payload),
                "ref": ref,
            }

    def _resume_deferred_runtime_failbacks(self) -> None:
        if self._current_core_runtime_phase() != "formal_capture":
            return
        with self._runtime_failure_monitor_lock:
            lease = self._runtime_route_mutation_lease
            if not (
                isinstance(lease, dict)
                and float(
                    lease.get("verified_at_monotonic", 0.0) or 0.0
                )
                > 0.0
            ):
                # Activation success proves the route it actually traversed;
                # it must never retroactively stamp an unknown/REJECT lease
                # whose target was not read back. Keep deferred promotions
                # parked until a real lease contract is verified.
                return
            pending = list(self._runtime_deferred_failbacks.values())
            self._runtime_deferred_failbacks.clear()
        for item in pending:
            payload = item.get("payload")
            ref = item.get("ref")
            if isinstance(payload, dict) and isinstance(ref, RuntimeNodeRef):
                self._start_runtime_failback(payload, ref)

    def _start_runtime_core_reconcile_for_failback(
        self,
        payload: dict[str, Any],
        ref: RuntimeNodeRef,
    ) -> None:
        """Restart a fail-closed Core after an exact recovered-leaf PASS.

        Core startup can legitimately exceed the three-second selector
        promotion budget, so it runs as a lifecycle transaction while the kill
        switch remains active.  Completion re-enters failback with a fresh
        process token; failure retains the incident lease and uses the normal
        30/60/120/300 promotion backoff.
        """

        incident_id = str(payload.get("incident_id") or "")
        key = ("failback_core_reconcile", *ref.key)

        def current_recovery_owner_locked() -> tuple[str, dict[str, Any]] | None:
            selector_revision = int(
                getattr(self, "_runtime_selector_intent_revision", 0) or 0
            )
            tickets = getattr(self, "_runtime_recovery_tickets", {})
            current_ticket = (
                tickets.get(incident_id)
                if isinstance(tickets, dict)
                else None
            )
            ticket_generation = int(
                current_ticket.generation
                if isinstance(current_ticket, _RuntimeRecoveryTicket)
                else 0
            )
            owners = getattr(
                self,
                "_runtime_core_stopped_recovery_owners",
                {},
            )
            owner = (
                owners.get(incident_id)
                if isinstance(owners, dict)
                else None
            )
            if (
                isinstance(owner, dict)
                and str(owner.get("incident_id") or incident_id) == incident_id
                and int(
                    owner.get(
                        "selector_intent_revision",
                        selector_revision,
                    )
                    or 0
                )
                == selector_revision
                and int(
                    owner.get("recovery_ticket_generation", 0) or 0
                )
                == ticket_generation
            ):
                return "core_stopped", dict(owner)
            lease = getattr(self, "_runtime_route_mutation_lease", None)
            if (
                isinstance(lease, dict)
                and str(lease.get("incident_id") or "") == incident_id
                and int(
                    lease.get(
                        "selector_intent_revision",
                        selector_revision,
                    )
                    or 0
                )
                == selector_revision
                and int(
                    lease.get("recovery_ticket_generation", 0) or 0
                )
                == ticket_generation
                and float(lease.get("verified_at_monotonic", 0.0) or 0.0)
                > 0.0
            ):
                # A physically verified automatic route remains the recovery
                # owner if Core subsequently dies. This includes a verified
                # REJECT lease; it is replaced only after the restarted Core's
                # exact managed FINAL-EXIT chain passes a fresh 204.
                return "route_lease", dict(lease)
            return None

        def recovery_owner_matches_locked(
            expected: tuple[str, dict[str, Any]],
        ) -> bool:
            current = current_recovery_owner_locked()
            if current is None or current[0] != expected[0]:
                return False
            kind, expected_record = expected
            _current_kind, current_record = current
            if kind == "core_stopped":
                fields = (
                    "incident_id",
                    "from",
                    "selector_intent_revision",
                    "recovery_ticket_generation",
                    "fail_closed_at_monotonic",
                )
            else:
                fields = (
                    "incident_id",
                    "from",
                    "to",
                    "owner_token",
                    "selector_intent_revision",
                    "recovery_ticket_generation",
                    "verified_at_monotonic",
                )
            return all(
                current_record.get(field) == expected_record.get(field)
                for field in fields
            )

        with self._runtime_failure_monitor_lock:
            recovery_owner = current_recovery_owner_locked()
            if key in self._runtime_failure_recovery_bindings or recovery_owner is None:
                return
            with self._runtime_route_snapshot_lock:
                admission_network_epoch = int(
                    getattr(self, "_runtime_network_context_epoch", 0) or 0
                )
                admission_facility_epoch = int(
                    getattr(self, "_runtime_facility_epoch", 0) or 0
                )
                with self._runtime_hot_standby_lock:
                    if bool(
                        getattr(
                            self,
                            "_runtime_network_context_hold_active",
                            False,
                        )
                    ):
                        return
            self._runtime_failure_recovery_bindings.add(key)

        def worker() -> None:
            retry = False
            startup_succeeded = False
            probe_indeterminate = False
            publication_committed = False
            try:
                if self.stop_event.is_set() or not bool(self.running):
                    return
                with self._runtime_failure_monitor_lock:
                    if not recovery_owner_matches_locked(recovery_owner):
                        return
                self._activate_killswitch_for_egress_failure(
                    "Recovered runtime leaf is reconciling a fail-closed Core"
                )
                try:
                    result = self._start_core_for_runtime_recovery()
                    runner = self.core_runner
                    startup_succeeded = bool(
                        runner is not None
                        and runner.is_running()
                        and not bool(
                            isinstance(result, dict)
                            and result.get("still_running") is False
                            and result.get("stopped") is True
                        )
                    )
                    if startup_succeeded:
                        refreshed = self._refresh_runtime_route_snapshot(
                            timeout_seconds=0.35
                        )
                        current_snapshot, current_payload = (
                            self._runtime_route_snapshot_state()
                        )
                        current_binding = (
                            self._runtime_route_binding_for_outbound(
                                current_snapshot,
                                current_payload,
                                "FINAL-EXIT",
                            )
                            if refreshed is not None
                            and current_snapshot is not None
                            and isinstance(current_payload, dict)
                            else None
                        )
                        if current_binding is None:
                            raise RuntimeError(
                                "restarted Core has no managed FINAL-EXIT binding"
                            )
                        verified = self._verify_runtime_final_exit(
                            expected_snapshot=current_snapshot,
                            timeout_seconds=1.5,
                        )
                        with self._runtime_failure_monitor_lock:
                            selector_revision = int(
                                getattr(
                                    self,
                                    "_runtime_selector_intent_revision",
                                    0,
                                )
                                or 0
                            )
                            with self._runtime_route_snapshot_lock:
                                loaded_snapshot = getattr(
                                    self,
                                    "_runtime_route_snapshot",
                                    None,
                                )
                                with self._runtime_hot_standby_lock:
                                    if not (
                                        recovery_owner_matches_locked(
                                            recovery_owner
                                        )
                                        and selector_revision
                                        == int(
                                            recovery_owner[1].get(
                                                "selector_intent_revision",
                                                selector_revision,
                                            )
                                            or 0
                                        )
                                        and int(
                                            getattr(
                                                self,
                                                "_runtime_facility_epoch",
                                                0,
                                            )
                                            or 0
                                        )
                                        == admission_facility_epoch
                                        and int(
                                            getattr(
                                                self,
                                                "_runtime_network_context_epoch",
                                                0,
                                            )
                                            or 0
                                        )
                                        == admission_network_epoch
                                        and not bool(
                                            getattr(
                                                self,
                                                "_runtime_network_context_hold_active",
                                                False,
                                            )
                                        )
                                        and int(
                                            current_snapshot.network_context_epoch
                                        )
                                        == admission_network_epoch
                                        and isinstance(
                                            loaded_snapshot,
                                            CoreLoadedRouteSnapshot,
                                        )
                                        and tuple(loaded_snapshot.snapshot_key)
                                        == tuple(current_snapshot.snapshot_key)
                                    ):
                                        raise RuntimeError(
                                            "Core recovery publication was superseded"
                                        )
                                    now = time.monotonic()
                                    self._runtime_route_mutation_lease = {
                                        "group": "FINAL-EXIT",
                                        "from": str(
                                            recovery_owner[1].get("from") or ""
                                        ),
                                        "to": current_binding.node.proxy_name,
                                        "target_member": "",
                                        "mode": "selector",
                                        "incident_id": incident_id,
                                        "route_epoch": current_binding.route_epoch,
                                        "selector_intent_revision": (
                                            selector_revision
                                        ),
                                        "recovery_ticket_generation": int(
                                            recovery_owner[1].get(
                                                "recovery_ticket_generation",
                                                0,
                                            )
                                            or 0
                                        ),
                                        "verified_at_monotonic": now,
                                        "provisional": False,
                                    }
                                    owners = getattr(
                                        self,
                                        "_runtime_core_stopped_recovery_owners",
                                        {},
                                    )
                                    if isinstance(owners, dict):
                                        owners.pop(incident_id, None)
                                    self._runtime_last_verified_route = {
                                        "verified_at_monotonic": now,
                                        "incident_id": incident_id,
                                        "leaf_proxy": (
                                            current_binding.node.proxy_name
                                        ),
                                        "route": list(
                                            current_binding.route_chain
                                        ),
                                        "result": dict(verified),
                                        "core_restart_baseline": True,
                                    }
                            # Keep the monitor lock through readiness
                            # publication so a new facility interval cannot be
                            # overwritten by this old Core-restart callback.
                            self._set_effective_egress_state(True, "")
                            publication_committed = True
                except _RuntimeProbeBudgetUnavailable:
                    probe_indeterminate = True
                    self._set_effective_egress_readiness_state(
                        None,
                        "Recovered Core is waiting for full-chain probe capacity",
                    )
                except Exception:
                    startup_succeeded = False
                    log_raw_diagnostic(
                        self.logger,
                        "warning",
                        "Recovered runtime leaf could not restart fail-closed Core",
                        exc_info=True,
                    )
                retry = True
                if not startup_succeeded and not probe_indeterminate:
                    self._runtime_failback_failures[ref.key] = max(
                        1,
                        int(self._runtime_failback_failures.get(ref.key, 0)),
                    )
            finally:
                with self._runtime_failure_monitor_lock:
                    self._runtime_failure_recovery_bindings.discard(key)
                    self._runtime_failure_recovery_threads.discard(
                        threading.current_thread()
                    )
                    if publication_committed:
                        current_lease = getattr(
                            self,
                            "_runtime_route_mutation_lease",
                            None,
                        )
                        lease_current = bool(
                            isinstance(current_lease, dict)
                            and str(current_lease.get("incident_id") or "")
                            == incident_id
                            and int(
                                current_lease.get(
                                    "recovery_ticket_generation",
                                    0,
                                )
                                or 0
                            )
                            == int(
                                recovery_owner[1].get(
                                    "recovery_ticket_generation",
                                    0,
                                )
                                or 0
                            )
                            and int(
                                current_lease.get(
                                    "selector_intent_revision",
                                    getattr(
                                        self,
                                        "_runtime_selector_intent_revision",
                                        0,
                                    ),
                                )
                                or 0
                            )
                            == int(
                                getattr(
                                    self,
                                    "_runtime_selector_intent_revision",
                                    0,
                                )
                                or 0
                            )
                        )
                    else:
                        lease_current = recovery_owner_matches_locked(
                            recovery_owner
                        )
                if retry and lease_current and not self.stop_event.is_set():
                    self._start_runtime_failback(payload, ref)

        thread = threading.Thread(
            target=worker,
            name="runtime-egress-core-reconcile",
            daemon=True,
        )
        with self._runtime_failure_monitor_lock:
            self._runtime_failure_recovery_threads.add(thread)
        thread.start()

    def _start_runtime_failback(
        self,
        payload: dict[str, Any],
        ref: RuntimeNodeRef,
    ) -> None:
        incident_id = str(payload.get("incident_id") or "")
        binding = self._runtime_incident_bindings.get(incident_id)
        loaded_payload = self._runtime_incident_route_payloads.get(incident_id)
        if binding is None or not isinstance(loaded_payload, dict):
            return
        key = ("failback", *ref.key)
        worker_token = self._runtime_worker_token()
        worker_facility_epoch = int(
            getattr(self, "_runtime_facility_epoch", 0) or 0
        )
        selector_intent_revision = int(
            getattr(self, "_runtime_selector_intent_revision", 0) or 0
        )
        recovery_ticket: _RuntimeRecoveryTicket | None = None
        with self._runtime_failure_monitor_lock:
            if key in self._runtime_failure_recovery_bindings:
                return
            tickets = getattr(self, "_runtime_recovery_tickets", {})
            ticket_value = (
                tickets.get(incident_id)
                if isinstance(tickets, dict)
                else None
            )
            if isinstance(ticket_value, _RuntimeRecoveryTicket):
                recovery_ticket = ticket_value
            self._runtime_failure_recovery_bindings.add(key)

        def worker() -> None:
            retry_requested = False
            core_reconcile_requested = False
            park_deferred = False
            promotion_selection_attempted = False

            def automatic_lease_is_current() -> bool:
                with self._runtime_failure_monitor_lock:
                    lease_record = self._runtime_route_mutation_lease
                    owners = getattr(
                        self,
                        "_runtime_core_stopped_recovery_owners",
                        {},
                    )
                    owner = (
                        owners.get(incident_id)
                        if isinstance(owners, dict)
                        else None
                    )
                    current_revision = int(
                        getattr(
                            self,
                            "_runtime_selector_intent_revision",
                            0,
                        )
                        or 0
                    )
                    tickets = getattr(self, "_runtime_recovery_tickets", {})
                    current_ticket = (
                        tickets.get(incident_id)
                        if isinstance(tickets, dict)
                        else None
                    )
                    expected_generation = int(
                        recovery_ticket.generation
                        if isinstance(recovery_ticket, _RuntimeRecoveryTicket)
                        else 0
                    )
                    if not (
                        (
                            isinstance(current_ticket, _RuntimeRecoveryTicket)
                            and current_ticket.generation
                            == expected_generation
                        )
                        or (
                            current_ticket is None
                            and expected_generation == 0
                        )
                    ):
                        return False
                    return bool(
                        current_revision == selector_intent_revision
                        and (
                            (
                                isinstance(lease_record, dict)
                                and str(
                                    lease_record.get("incident_id") or ""
                                )
                                == incident_id
                                and int(
                                    lease_record.get(
                                        "selector_intent_revision",
                                        selector_intent_revision,
                                    )
                                    or 0
                                )
                                == selector_intent_revision
                                and int(
                                    lease_record.get(
                                        "recovery_ticket_generation",
                                        0,
                                    )
                                    or 0
                                )
                                == expected_generation
                            )
                            or (
                                isinstance(owner, dict)
                                and int(
                                    owner.get(
                                        "selector_intent_revision",
                                        selector_intent_revision,
                                    )
                                    or 0
                                )
                                == selector_intent_revision
                                and int(
                                    owner.get(
                                        "recovery_ticket_generation",
                                        0,
                                    )
                                    or 0
                                )
                                == expected_generation
                            )
                        )
                    )

            try:
                with self._runtime_failure_monitor_lock:
                    lease_record = self._runtime_route_mutation_lease
                    owners = getattr(
                        self,
                        "_runtime_core_stopped_recovery_owners",
                        {},
                    )
                    owner_record = (
                        owners.get(incident_id)
                        if isinstance(owners, dict)
                        else None
                    )
                    last_verified_at = float(
                        lease_record.get("verified_at_monotonic", 0.0) or 0.0
                    ) if isinstance(lease_record, dict) else float(
                        owner_record.get("fail_closed_at_monotonic", 0.0) or 0.0
                    ) if isinstance(owner_record, dict) else 0.0
                last_attempt = float(self._runtime_failback_last_attempt.get(ref.key, 0.0))
                pass_history = list(
                    self._runtime_failback_pass_history.get(ref.key, [])
                )
                first_pass_at = float(pass_history[-1]) if pass_history else 0.0
                recurrence_count = len(
                    [
                        confirmed
                        for confirmed in self._runtime_flap_history.get(ref.key, [])
                        if time.monotonic() - float(confirmed) <= 600.0
                    ]
                )
                promotion_hold = (
                    300.0
                    if recurrence_count >= 3
                    else 120.0
                    if recurrence_count >= 2
                    else 30.0
                )
                wait_seconds = max(
                    0.0,
                    promotion_hold - (time.monotonic() - last_verified_at),
                    5.0 - (time.monotonic() - first_pass_at)
                    if first_pass_at > 0.0
                    else 5.0,
                    10.0 - (time.monotonic() - last_attempt),
                )
                failure_count = int(self._runtime_failback_failures.get(ref.key, 0))
                if failure_count:
                    backoff = (60.0, 120.0, 300.0)[
                        min(failure_count - 1, 2)
                    ]
                    wait_seconds = max(wait_seconds, backoff)
                if self.stop_event.wait(wait_seconds):
                    return
                if not automatic_lease_is_current():
                    return
                if not self._runtime_worker_token_is_current(worker_token):
                    # A facility/network epoch deliberately revokes the old
                    # worker.  It must not consume the sole recovered PASS and
                    # disappear. Defer only after finally releases this key;
                    # otherwise a concurrent hold-release can consume the
                    # mailbox while the old key still rejects the new worker.
                    park_deferred = True
                    return
                runner = self.core_runner
                if runner is None or not runner.is_running():
                    core_reconcile_requested = bool(
                        self.running and not self.stop_event.is_set()
                    )
                    if not core_reconcile_requested:
                        self._runtime_failback_failures[ref.key] = max(
                            1,
                            failure_count + 1,
                        )
                        retry_requested = True
                    return
                if (
                    self._current_core_runtime_phase() != "formal_capture"
                    or not self._revalidation_capture_active("formal_capture")
                    or last_verified_at <= 0.0
                ):
                    # A PASS updates Manager health immediately, but route
                    # promotion is event-driven from a verified capture. Never
                    # reload/rollback/fail-close inside formal_no_capture.
                    # The activation/release callback is allowed to resume the
                    # mailbox as soon as capture becomes verified. Do not put
                    # this item there until finally has released the existing
                    # failback key, or that callback can consume-and-drop it.
                    park_deferred = True
                    return

                # Stability/backoff waiting is outside the promotion SLA. Once
                # the recovered leaf is eligible and the automatic lease still
                # owns the route, every controller/Core/probe step shares this
                # single three-second deadline.
                failback_started = time.monotonic()
                promotion_deadline = failback_started + 1.75
                rollback_deadline = failback_started + 2.5
                failback_deadline = failback_started + 3.0

                def remaining_until(
                    deadline: float,
                    default_seconds: float,
                ) -> float:
                    return max(
                        0.0,
                        min(
                            float(default_seconds),
                            float(deadline) - time.monotonic(),
                        ),
                    )

                def remaining_promotion(default_seconds: float) -> float:
                    return remaining_until(
                        promotion_deadline,
                        default_seconds,
                    )

                def remaining_rollback(default_seconds: float) -> float:
                    return remaining_until(
                        rollback_deadline,
                        default_seconds,
                    )

                current_snapshot, current_payload = self._runtime_route_snapshot_state()
                if current_snapshot is None or not isinstance(current_payload, dict):
                    try:
                        self._refresh_runtime_route_snapshot(
                            timeout_seconds=remaining_promotion(0.35)
                        )
                    except Exception:
                        self._runtime_failback_failures[ref.key] = max(
                            1,
                            failure_count + 1,
                        )
                        retry_requested = True
                        return
                    current_snapshot, current_payload = (
                        self._runtime_route_snapshot_state()
                    )
                if current_snapshot is None or not isinstance(current_payload, dict):
                    self._runtime_failback_failures[ref.key] = max(
                        1,
                        failure_count + 1,
                    )
                    retry_requested = True
                    return

                current_binding = self._runtime_route_binding_for_outbound(
                    current_snapshot,
                    current_payload,
                    "FINAL-EXIT",
                )
                underlay_domain = bool(
                    "FINAL-EXIT" not in binding.route_chain
                )
                current_domain_binding = (
                    self._runtime_route_binding_for_outbound(
                        current_snapshot,
                        current_payload,
                        binding.observed_outbound,
                        require_final_exit=not underlay_domain,
                    )
                    if underlay_domain
                    else current_binding
                )
                confirmed_fail_closed_key = None
                if current_binding is None:
                    route_snapshot_lock = getattr(
                        self,
                        "_runtime_route_snapshot_lock",
                        None,
                    )
                    if route_snapshot_lock is not None:
                        with route_snapshot_lock:
                            confirmed_fail_closed_key = getattr(
                                self,
                                "_runtime_confirmed_fail_closed_snapshot_key",
                                None,
                            )
                incident_owned_fail_closed = bool(
                    current_binding is None
                    and isinstance(lease_record, dict)
                    and str(lease_record.get("incident_id") or "")
                    == incident_id
                    and str(lease_record.get("to") or "").upper()
                    == "REJECT"
                    and float(
                        lease_record.get("verified_at_monotonic", 0.0) or 0.0
                    )
                    > 0.0
                    and confirmed_fail_closed_key is not None
                    and tuple(current_snapshot.snapshot_key)
                    == tuple(confirmed_fail_closed_key)
                    and self._runtime_payload_has_reject_final_exit(
                        current_payload.get("proxies")
                    )
                )
                if current_domain_binding is None and not incident_owned_fail_closed:
                    self._runtime_failback_failures[ref.key] = max(
                        1,
                        failure_count + 1,
                    )
                    retry_requested = True
                    return
                rollback_expected_gateway_key = (
                    tuple(current_binding.node.key)
                    if (
                        "FINAL-EXIT" not in binding.route_chain
                        and current_binding is not None
                        and current_binding.node.pool_kind == "gateway"
                    )
                    else None
                )
                # A strict fail-closed route intentionally has no managed
                # current leaf.  Use a snapshot-owned reconciliation binding
                # solely to acquire the global Core transaction; it is never
                # fed back into node-failure attribution.
                mutation_binding = current_binding or RuntimeRouteBinding(
                    process_pid=current_snapshot.process_pid,
                    process_generation=current_snapshot.process_generation,
                    core_generation=current_snapshot.core_generation,
                    semantic_digest=current_snapshot.semantic_digest,
                    route_epoch=current_snapshot.route_epoch,
                    observed_outbound="FINAL-EXIT",
                    route_chain=("FINAL-EXIT", "REJECT"),
                    node=ref,
                    network_context_epoch=(
                        current_snapshot.network_context_epoch
                    ),
                )
                reload_gate = getattr(self, "_runtime_reload_gate", None)
                recovery_gate_lease: RuntimeRecoveryLease | None = None
                if reload_gate is not None:
                    recovery_gate_lease = reload_gate.begin_recovery(
                        f"failback:{incident_id}"
                    )
                    if recovery_gate_lease is None:
                        self._runtime_failback_failures[ref.key] = max(
                            1,
                            failure_count + 1,
                        )
                        retry_requested = True
                        return
                try:
                    mutation = self._runtime_egress_coordinator.begin_core_mutation(
                        mutation_binding,
                        expected_snapshot=current_snapshot,
                        timeout_seconds=remaining_promotion(1.75),
                    )
                except Exception:
                    if reload_gate is not None and recovery_gate_lease is not None:
                        reload_gate.end_recovery(recovery_gate_lease)
                    raise
                if mutation is None:
                    if reload_gate is not None and recovery_gate_lease is not None:
                        reload_gate.end_recovery(recovery_gate_lease)
                    self._runtime_failback_failures[ref.key] = max(
                        1,
                        failure_count + 1,
                    )
                    retry_requested = True
                    return
                self._runtime_failback_last_attempt[ref.key] = time.monotonic()
                try:
                    with self._core_transition_lock:
                        if (
                            remaining_promotion(1.75) <= 0.0
                            or
                            not self._runtime_worker_token_is_current(worker_token)
                            or not automatic_lease_is_current()
                            or not self._runtime_egress_coordinator.core_mutation_lease_is_current(
                                mutation
                            )
                        ):
                            return

                        # The failed leaf remains in the Core inventory for
                        # existing-connection drain and later promotion. A
                        # health PASS must never reload Mihomo merely to make
                        # it selectable again.
                        refreshed = self._refresh_runtime_route_snapshot(
                            timeout_seconds=remaining_promotion(0.35)
                        )
                        _snapshot, refreshed_payload = (
                            self._runtime_route_snapshot_state()
                        )
                        if refreshed is None or not isinstance(
                            refreshed_payload,
                            dict,
                        ):
                            raise RuntimeError(
                                "failback loaded snapshot is unavailable"
                            )
                        refreshed_ref = self._runtime_snapshot_node(
                            refreshed,
                            ref.proxy_name,
                        )
                        if refreshed_ref is None or refreshed_ref.key != ref.key:
                            raise RuntimeError(
                                "recovered leaf is not in the loaded dynamic inventory"
                            )
                        leaf_probe_seconds = remaining_promotion(1.0)
                        if leaf_probe_seconds <= 0.0:
                            raise TimeoutError(
                                "failback deadline expired before leaf validation"
                            )
                        promotion_action: dict[str, Any] | None = None
                        if (
                            current_domain_binding is not None
                            and (
                                str(lease_record.get("mode") or "")
                                == "fixed"
                                or current_domain_binding.node.key
                                != refreshed_ref.key
                                or self._runtime_policy_rank(refreshed_ref)
                                < self._runtime_policy_rank(
                                    current_domain_binding.node
                                )
                            )
                        ):
                            promotion_failure = BoundRuntimeFailure(
                                binding=current_domain_binding,
                                protocol="PROBE",
                                observed_outbound=(
                                    current_domain_binding.observed_outbound
                                ),
                                destination_token=runtime_destination_token(
                                    "higher-priority-failback"
                                ),
                                error_type="higher_priority_recovery",
                                observed_at_monotonic=time.monotonic(),
                            )
                            promotion_action = (
                                self._runtime_alternative_switch_action(
                                    promotion_failure,
                                    refreshed_ref,
                                    refreshed_payload,
                                )
                            )
                        if (
                            promotion_action is not None
                            and str(promotion_action.get("mode") or "")
                            == "fixed"
                        ):
                            self._prewarm_runtime_switch_target(
                                refreshed,
                                promotion_action,
                                deadline_monotonic=promotion_deadline,
                            )
                        else:
                            self._probe_runtime_leaf(
                                refreshed_ref,
                                refreshed_payload,
                                timeout_ms=max(
                                    100,
                                    int(leaf_probe_seconds * 1000),
                                ),
                            )
                        if (
                            not automatic_lease_is_current()
                            or not self._runtime_worker_token_is_current(
                                worker_token
                            )
                            or bool(self._runtime_facility_hold_reason())
                            or not self._runtime_egress_coordinator.core_mutation_lease_is_current(
                                mutation
                            )
                        ):
                            park_deferred = bool(automatic_lease_is_current())
                            return
                        with self._runtime_failure_monitor_lock:
                            lease_record = dict(
                                self._runtime_route_mutation_lease or {}
                            )
                        if str(lease_record.get("mode") or "") == "fixed":
                            promotion_selection_attempted = True
                            self._release_runtime_automatic_fixed_selection(
                                lease_record,
                                deadline_monotonic=promotion_deadline,
                            )
                        else:
                            promotion_selection_attempted = True
                            self._restore_runtime_selector_path(
                                binding,
                                loaded_payload,
                                incident_id=incident_id,
                                deadline_monotonic=promotion_deadline,
                                current_snapshot_payload=refreshed_payload,
                            )
                        promoted_snapshot = self._refresh_runtime_route_snapshot(
                            timeout_seconds=remaining_promotion(0.35)
                        )
                        _current_snapshot, promoted_payload = (
                            self._runtime_route_snapshot_state()
                        )
                        if promoted_snapshot is None or not isinstance(
                            promoted_payload,
                            dict,
                        ):
                            raise RuntimeError(
                                "promoted FINAL-EXIT snapshot is unavailable"
                            )
                        promoted_binding = self._runtime_route_binding_for_outbound(
                            promoted_snapshot,
                            promoted_payload,
                            binding.observed_outbound,
                            require_final_exit=bool(
                                binding.observed_outbound == "FINAL-EXIT"
                                or "FINAL-EXIT" in binding.route_chain
                            ),
                        )
                        if promoted_binding is None or not (
                            self._runtime_natural_winner_is_acceptable(
                                promoted_binding.node,
                                ref,
                            )
                        ):
                            raise RuntimeError(
                                "recovered route domain selected a lower-priority or unmanaged leaf"
                            )
                        promoted_final_binding = (
                            self._runtime_route_binding_for_outbound(
                                promoted_snapshot,
                                promoted_payload,
                                "FINAL-EXIT",
                            )
                        )
                        if promoted_final_binding is None:
                            raise RuntimeError(
                                "promoted FINAL-EXIT route is not bound to a managed leaf"
                            )
                        # Gateway-underlay recovery is scoped to the Gateway's
                        # dialer-proxy chain.  The externally selected Gateway
                        # identity must remain byte-for-byte the same while the
                        # recovered underlay is validated independently.
                        if (
                            "FINAL-EXIT" not in binding.route_chain
                            and current_binding is not None
                            and current_binding.node.pool_kind == "gateway"
                            and promoted_final_binding.node.key
                            != current_binding.node.key
                        ):
                            raise RuntimeError(
                                "Gateway identity changed during underlay failback"
                            )
                        verify_seconds = remaining_promotion(1.0)
                        if verify_seconds <= 0.0:
                            raise TimeoutError(
                                "failback deadline expired before FINAL-EXIT verification"
                            )
                        verified = self._verify_runtime_final_exit(
                            expected_worker_token=worker_token,
                            expected_snapshot=promoted_snapshot,
                            timeout_seconds=verify_seconds,
                        )
                        if (
                            not automatic_lease_is_current()
                            or not self._runtime_worker_token_is_current(
                                worker_token
                            )
                            or bool(self._runtime_facility_hold_reason())
                            or not self._runtime_egress_coordinator.core_mutation_lease_is_current(
                                mutation
                            )
                        ):
                            park_deferred = bool(automatic_lease_is_current())
                            return
                        self._runtime_failback_failures.pop(ref.key, None)
                        committed = False
                        with self._runtime_failure_monitor_lock:
                            lease_record = self._runtime_route_mutation_lease
                            if (
                                isinstance(lease_record, dict)
                                and str(lease_record.get("incident_id") or "")
                                == incident_id
                                and int(
                                    getattr(
                                        self,
                                        "_runtime_facility_epoch",
                                        0,
                                    )
                                    or 0
                                )
                                == worker_facility_epoch
                                and int(
                                    getattr(
                                        self,
                                        "_runtime_selector_intent_revision",
                                        0,
                                    )
                                    or 0
                                )
                                == selector_intent_revision
                                and not self._runtime_facility_hold_reason()
                                and self._runtime_worker_token_is_current(
                                    worker_token
                                )
                            ):
                                self._runtime_route_mutation_lease = None
                                self._runtime_incident_recovery_state[
                                    incident_id
                                ] = "promoted"
                                self._runtime_origin_diagnostic_bindings.pop(
                                    incident_id,
                                    None,
                                )
                                self._runtime_failback_export_holds.discard(
                                    self._runtime_leaf_export_hold_key(ref)
                                )
                                self._runtime_last_verified_route = {
                                    "verified_at_monotonic": time.monotonic(),
                                    "incident_id": incident_id,
                                    "leaf_proxy": (
                                        promoted_binding.node.proxy_name
                                    ),
                                    "route": list(
                                        promoted_final_binding.route_chain
                                    ),
                                    "result": verified,
                                }
                                self._set_effective_egress_state(True, "")
                                committed = True
                        if not committed:
                            park_deferred = bool(automatic_lease_is_current())
                            return
                except Exception as exc:
                    budget_indeterminate = isinstance(
                        exc,
                        _RuntimeProbeBudgetUnavailable,
                    )
                    rollback_verified = False
                    rollback_probe_indeterminate = False
                    rollback_result: dict[str, Any] | None = None
                    rollback_lease: dict[str, Any] = {}
                    rollback_binding: RuntimeRouteBinding | None = None
                    if (
                        not self._runtime_worker_token_is_current(worker_token)
                        or not automatic_lease_is_current()
                        or int(
                            getattr(
                                self,
                                "_runtime_selector_intent_revision",
                                0,
                            )
                            or 0
                        )
                        != selector_intent_revision
                    ):
                        park_deferred = bool(automatic_lease_is_current())
                        return
                    if budget_indeterminate and not promotion_selection_attempted:
                        retry_requested = True
                        return
                    if not budget_indeterminate:
                        self._runtime_failback_failures[ref.key] = failure_count + 1
                    try:
                        with self._core_transition_lock:
                            if automatic_lease_is_current():
                                if remaining_rollback(0.75) <= 0.0:
                                    raise TimeoutError(
                                        "failback deadline expired before rollback"
                                    )
                                self._refresh_runtime_route_snapshot(
                                    timeout_seconds=remaining_rollback(0.25)
                                )
                                with self._runtime_failure_monitor_lock:
                                    rollback_lease = dict(
                                        self._runtime_route_mutation_lease or {}
                                    )
                                rollback_snapshot, _rollback_payload, rollback_binding = (
                                    self._restore_runtime_automatic_route(
                                        incident_binding=binding,
                                        previous_binding=current_binding,
                                        previous_payload=current_payload,
                                        lease_record=rollback_lease,
                                        incident_id=incident_id,
                                        deadline_monotonic=rollback_deadline,
                                        expected_gateway_key=(
                                            rollback_expected_gateway_key
                                        ),
                                    )
                                )
                                rollback_probe_seconds = remaining_rollback(0.5)
                                if rollback_probe_seconds <= 0.0:
                                    raise TimeoutError(
                                        "failback deadline expired before rollback verification"
                                    )
                                rollback_result = self._verify_runtime_final_exit(
                                    expected_worker_token=worker_token,
                                    expected_snapshot=rollback_snapshot,
                                    timeout_seconds=rollback_probe_seconds,
                                )
                                rollback_verified = True
                    except _RuntimeProbeBudgetUnavailable:
                        rollback_probe_indeterminate = True
                    except Exception:
                        log_raw_diagnostic(
                            self.logger,
                            "warning",
                            "Recovered route promotion rollback failed",
                            exc_info=True,
                        )

                    if (
                        not rollback_verified
                        and not rollback_probe_indeterminate
                        and automatic_lease_is_current()
                    ):
                        # A readback or helper step can lose its narrow rollback
                        # budget after Mihomo has already restored the previous
                        # route. Before converting that into a Core stop, prove
                        # the incident-owned route and one neutral 204 under the
                        # remaining hard deadline. This never accepts an
                        # arbitrary route or the recovered leaf itself.
                        try:
                            with self._runtime_failure_monitor_lock:
                                rollback_lease = dict(
                                    self._runtime_route_mutation_lease or {}
                                )
                            salvage_snapshot, salvage_payload = (
                                self._runtime_route_snapshot_state()
                            )
                            expected_leaf = str(rollback_lease.get("to") or "")
                            salvage_route = (
                                inspect_runtime_route(
                                    salvage_payload.get("proxies"),
                                    start=binding.observed_outbound,
                                )
                                if salvage_snapshot is not None
                                and isinstance(salvage_payload, dict)
                                else {}
                            )
                            salvage_final_binding = (
                                self._runtime_route_binding_for_outbound(
                                    salvage_snapshot,
                                    salvage_payload,
                                    "FINAL-EXIT",
                                )
                                if salvage_snapshot is not None
                                and isinstance(salvage_payload, dict)
                                else None
                            )
                            salvage_gateway_matches = bool(
                                rollback_expected_gateway_key is None
                                or (
                                    salvage_final_binding is not None
                                    and tuple(salvage_final_binding.node.key)
                                    == tuple(rollback_expected_gateway_key)
                                )
                            )
                            salvage_seconds = max(
                                0.0,
                                min(
                                    0.5,
                                    failback_deadline - time.monotonic(),
                                ),
                            )
                            if (
                                expected_leaf
                                and str(salvage_route.get("leaf_proxy") or "")
                                == expected_leaf
                                and salvage_gateway_matches
                                and salvage_seconds >= 0.2
                            ):
                                rollback_result = self._verify_runtime_final_exit(
                                    expected_worker_token=worker_token,
                                    expected_snapshot=salvage_snapshot,
                                    timeout_seconds=salvage_seconds,
                                )
                                rollback_verified = True
                        except _RuntimeProbeBudgetUnavailable:
                            rollback_probe_indeterminate = True
                        except Exception:
                            pass

                    if (
                        not rollback_verified
                        and (budget_indeterminate or rollback_probe_indeterminate)
                    ):
                        # A selector may already have moved, but the missing
                        # socket verdict grants no authority to REJECT or stop
                        # Core. Preserve the incident owner, rebuild controller
                        # truth, and retry once capacity is available.
                        self._set_effective_egress_readiness_state(
                            None,
                            "Recovered route promotion is awaiting probe capacity",
                        )
                        self._queue_runtime_route_snapshot_refresh()
                        retry_requested = True
                        return

                    if rollback_verified:
                        rollback_published = False
                        with self._runtime_failure_monitor_lock:
                            current_lease = self._runtime_route_mutation_lease
                            if (
                                isinstance(current_lease, dict)
                                and str(current_lease.get("incident_id") or "")
                                == incident_id
                                and int(
                                    getattr(
                                        self,
                                        "_runtime_facility_epoch",
                                        0,
                                    )
                                    or 0
                                )
                                == worker_facility_epoch
                                and not self._runtime_facility_hold_reason()
                                and int(
                                    getattr(
                                        self,
                                        "_runtime_selector_intent_revision",
                                        0,
                                    )
                                    or 0
                                )
                                == selector_intent_revision
                            ):
                                self._runtime_last_verified_route = {
                                    "verified_at_monotonic": time.monotonic(),
                                    "incident_id": incident_id,
                                    "leaf_proxy": str(
                                        rollback_lease.get("to") or ""
                                    ),
                                    "route": (
                                        list(rollback_binding.route_chain)
                                        if rollback_binding is not None
                                        else list(current_binding.route_chain)
                                        if current_binding is not None
                                        else []
                                    ),
                                    "result": rollback_result or {},
                                    "promotion_rollback": True,
                                }
                                self._set_effective_egress_state(True, "")
                                rollback_published = True
                        if not rollback_published:
                            park_deferred = bool(automatic_lease_is_current())
                            return
                    else:
                        # A failed automatic promotion/rollback is controller
                        # uncertainty, not proof that a fixed Gateway body is
                        # bad.  Preserve the closed local capture boundary but
                        # never rewrite FINAL-EXIT to REJECT or stop Core for a
                        # non-Gateway route.
                        with self._runtime_failure_monitor_lock:
                            current_lease = self._runtime_route_mutation_lease
                            if (
                                isinstance(current_lease, dict)
                                and str(current_lease.get("incident_id") or "")
                                == incident_id
                            ):
                                self._runtime_route_mutation_lease = None
                                self._runtime_incident_recovery_state[
                                    incident_id
                                ] = "indeterminate"
                        self._set_effective_egress_readiness_state(
                            None,
                            "Recovered route promotion left route ownership indeterminate",
                        )
                        self._set_effective_egress_state(
                            None,
                            f"Recovered route promotion failed: {exc}",
                        )
                        self._queue_runtime_route_snapshot_refresh()
                    # Promotion failure is not evidence that the node failed
                    # another authoritative self-check.  Keep the incident's
                    # automatic lease and retry with 30/60/120/300 backoff.
                    retry_requested = bool(
                        self._runtime_worker_token_is_current(worker_token)
                        and automatic_lease_is_current()
                    )
                finally:
                    self._runtime_egress_coordinator.end_core_mutation(mutation)
                    if reload_gate is not None and recovery_gate_lease is not None:
                        reload_gate.end_recovery(recovery_gate_lease)
            finally:
                with self._runtime_failure_monitor_lock:
                    self._runtime_failure_recovery_bindings.discard(key)
                    self._runtime_failure_recovery_threads.discard(
                        threading.current_thread()
                    )
                if (
                    park_deferred
                    and not self.stop_event.is_set()
                    and automatic_lease_is_current()
                ):
                    self._defer_runtime_failback(payload, ref)
                    hold_reason_getter = getattr(
                        self,
                        "_runtime_facility_hold_reason",
                        None,
                    )
                    hold_reason = (
                        str(hold_reason_getter() or "")
                        if callable(hold_reason_getter)
                        else ""
                    )
                    phase_getter = getattr(
                        self,
                        "_current_core_runtime_phase",
                        None,
                    )
                    capture_ready = bool(
                        callable(phase_getter)
                        and phase_getter() == "formal_capture"
                    )
                    if not hold_reason and capture_ready:
                        self._resume_deferred_runtime_failbacks()
                    return
                if (
                    core_reconcile_requested
                    and not self.stop_event.is_set()
                    and automatic_lease_is_current()
                ):
                    self._start_runtime_core_reconcile_for_failback(
                        payload,
                        ref,
                    )
                elif (
                    retry_requested
                    and not self.stop_event.is_set()
                    and self._runtime_worker_token_is_current(worker_token)
                ):
                    self._start_runtime_failback(payload, ref)

        thread = threading.Thread(
            target=worker,
            name="runtime-egress-failback",
            daemon=True,
        )
        with self._runtime_failure_monitor_lock:
            self._runtime_failure_recovery_threads.add(thread)
        thread.start()

    def _revoke_tier3_runtime_leaf_qualification(self, identity: str) -> None:
        identity = str(identity or "").strip()
        with self._tier3_runtime_qualification_lock:
            if identity:
                self._tier3_runtime_qualified.pop(identity, None)
            self._tier3_runtime_final_exit_ok = False
            self._tier3_runtime_final_exit_core_generation = -1
            self._tier3_selected_leaf_evidence = None
            self._tier3_runtime_qualification_monitor_at = 0.0
            self._tier3_runtime_last_revalidation_key = None
        self._publish_tier3_runtime_qualification()

    # Compatibility surface for callers that still use the former Tier3 names;
    # every entry delegates to the sole global coordinator.
    def _reset_tier3_runtime_failure_monitor_state(self) -> None:
        self._reset_runtime_failure_monitor_state()

    def _tier3_runtime_circuit_snapshot(self) -> Tier3RuntimeCircuitSnapshot:
        for snapshot in reversed(
            self._runtime_egress_coordinator.current_snapshots()
        ):
            binding = snapshot.binding
            if (
                binding is None
                or binding.node.tier != "tier3"
                or binding.node.pool_kind != "tier3b"
            ):
                continue
            return Tier3RuntimeCircuitSnapshot(
                state=snapshot.state,
                core_generation=binding.core_generation,
                semantic_digest=binding.semantic_digest,
                selected_leaf=binding.node.proxy_name,
                selected_identity=binding.node.identity,
                destinations=(),
                first_failure_monotonic=snapshot.first_failure_monotonic,
                confirmed_monotonic=snapshot.confirmed_monotonic,
                recovered_monotonic=snapshot.recovered_monotonic,
                quarantine_until_monotonic=snapshot.quarantine_until_monotonic,
                failure_count=snapshot.failure_count,
                confirmation_reason=snapshot.confirmation_reason,
                recovery_latency_ms=snapshot.recovery_latency_ms,
            )
        return Tier3RuntimeCircuitSnapshot()

    def _reconcile_tier3_runtime_suspects(self) -> int:
        manager = self.manager
        snapshot = getattr(manager, "runtime_health_snapshot", None)
        if not callable(snapshot):
            return 0
        try:
            return sum(
                1
                for entry in snapshot().get("entries", [])
                if isinstance(entry, dict)
                and entry.get("tier") == "tier3"
                and entry.get("pool_kind") == "tier3b"
            )
        except Exception:
            return 0

    def _publish_tier3_runtime_circuit_snapshot(self) -> None:
        # Manager's canonical runtime-health ledger is the sole m/n truth.
        return

    def _current_tier3_runtime_failure_binding(
        self,
    ) -> tuple[int, str, str, str] | None:
        state = self._current_runtime_failure_binding_state()
        if state is None:
            return None
        binding, _snapshot, _payload = state
        if binding.node.tier != "tier3" or binding.node.pool_kind != "tier3b":
            return None
        return (
            binding.core_generation,
            binding.semantic_digest,
            binding.node.proxy_name,
            binding.node.identity,
        )

    def _start_tier3_runtime_failure_monitor(self) -> None:
        self._start_runtime_failure_monitor()

    def _tier3_runtime_failure_monitor_loop(self) -> None:
        self._runtime_failure_monitor_loop()

    def _handle_tier3_runtime_log_record(self, record: Any) -> None:
        snapshot, payload = self._runtime_route_snapshot_state()
        if snapshot is None or payload is None:
            return
        text = (
            str(record.get("payload") or record.get("message") or "")
            if isinstance(record, dict)
            else str(record or "")
        )
        event = CoreOutputEvent(
            raw_line=text,
            pid=snapshot.process_pid,
            process_generation=snapshot.process_generation,
            received_at_monotonic=time.monotonic(),
        )
        self._handle_runtime_output_event(event, snapshot, payload)

    def _maybe_probe_tier3_runtime_log_guard(self) -> None:
        self._maybe_probe_runtime_failure_guard()

    def _start_tier3_runtime_independent_probe(self, _event: Any) -> None:
        self._submit_current_route_probe_failure(
            "legacy Tier3 runtime confirmation",
            source="tier3_compat_probe",
        )

    def _start_tier3_runtime_failover(self, _event: Any) -> None:
        self._submit_current_route_probe_failure(
            "legacy Tier3 runtime failover request",
            source="tier3_compat_failover",
        )

    def _runtime_audit_base_result(self, *, reason: str, trigger: str) -> dict[str, Any]:
        return {
            "attempted": True,
            "trigger": str(trigger or "runtime_egress"),
            "selected_chain": [],
            "route_marker": "",
            "leaf_proxy": "",
            "leaf_identity": "",
            "facility_failure": "",
            "confirmed_failure": False,
            "switch_actions": [],
            "recovery_steps": 0,
            "post_switch_verified": False,
            "effective_egress_ok": False,
            "reason": str(reason or "runtime egress verification failed"),
        }

    def _active_gateway_policy_enabled(self) -> bool:
        manager = getattr(self, "manager", None)
        active = getattr(manager, "_exit_active", None)
        if callable(active):
            try:
                return bool(active())
            except Exception:
                return False
        return False

    def _gateway_selection(self) -> GatewaySelection | None:
        """The saved Gateway selection, or None when it cannot be read."""

        try:
            return selection_from_manager(getattr(self, "manager", None))
        except Exception:
            return None

    def _loaded_gateway_member(
        self,
        selection: GatewaySelection | None,
        proxy_map: Any = None,
        members: Any = None,
    ) -> str:
        """The loaded EXIT-SELECT member a saved Gateway selection names.

        The renderer resolves the selection (the node's identity; an old
        name-only selection under the stricter name rule) and records its
        decision on the member (``selected_for`` = the selection key, kept
        with the loaded main graph across provider-only commits).  Readers of
        the loaded route take that record.  Without it, a bound selection is
        found by its identity and a name-only one is resolved the renderer's
        way over ``proxy_map`` (default: the loaded export contract's).
        ``members`` limits the answer to the loaded EXIT-SELECT members.  ""
        when the selection names no loaded member.  No Mihomo request, no
        config render, no write; with a map passed, no runtime lock.
        """

        if selection is None or not selection.active:
            return ""
        if not isinstance(proxy_map, dict):
            route_lock = getattr(self, "_runtime_route_snapshot_lock", None)
            with route_lock if route_lock is not None else nullcontext():
                loaded = getattr(self, "_runtime_loaded_export_contract", None)
                proxy_map = (
                    dict(loaded.get("proxy_map") or {})
                    if isinstance(loaded, dict)
                    else {}
                )
        allowed = None if members is None else {str(member) for member in members}

        def admitted(name: str) -> bool:
            return allowed is None or name in allowed

        if not proxy_map:
            return selection.label if selection.state == "legacy" else ""
        exits = [
            (str(name), info)
            for name, info in proxy_map.items()
            if isinstance(info, dict) and str(info.get("tier") or "") == "exit"
        ]
        for name, info in exits:
            if str(info.get("selected_for") or "") == selection.key and admitted(name):
                # The renderer's own decision for this loaded main graph.
                return name
        if selection.state == "bound":
            carriers = [
                name
                for name, info in exits
                if admitted(name)
                and info.get("node") is not None
                and gateway_identity(info["node"]) == selection.identity
            ]
            return carriers[0] if len(carriers) == 1 else ""
        if selection.state != "legacy":
            return ""
        if not any(info.get("node") is not None for _name, info in exits):
            # A map without nodes (no render receipt) proves nothing about
            # identities: the loaded exit named exactly as saved, as before.
            return selection.label if any(
                name == selection.label and admitted(name) for name, _info in exits
            ) else ""
        tier_nodes: dict[str, list[Any]] = {"tier1": [], "tier2": [], "tier3": [], "exit": []}
        for info in proxy_map.values():
            if isinstance(info, dict) and info.get("node") is not None:
                tier_id = str(info.get("tier") or "")
                if tier_id in tier_nodes:
                    tier_nodes[tier_id].append(info["node"])
        pairs = [(info["node"], name) for name, info in exits if info.get("node") is not None]
        inventory: list[Any] = [node for node, _name in pairs]
        inventory_getter = getattr(getattr(self, "manager", None), "gateway_exit_inventory", None)
        if callable(inventory_getter):
            try:
                inventory = list(inventory_getter())
            except Exception:
                pass
        member, _decision = resolve_gateway_member(
            selection,
            pairs,
            tier_nodes,
            inventory=inventory,
            stable_tier3_names=self._tier3_verified_provider_writes_enabled(),
        )
        return member if member and admitted(member) else ""

    def _persist_gateway_selection_binding(self) -> bool:
        """Bind an old name-only Gateway selection to the node Core serves.

        Selections saved before identities (or by a name-only pick) are
        served by the stricter name rule.  Once the published route of the
        loaded contract serves the member the renderer chose for that name,
        every enabled Gateway subscription is accounted for (its nodes are
        present, or the last completed exit refresh covered it), and no other
        exit node (any status, manual or cached) shares the name's family,
        that member's identity is saved with its name: no Core
        reload, both Tier3 namings.  A name the family proves ambiguous is
        saved as "must be picked again", so a later node-list change can
        never resolve it to a survivor.  A pick made meanwhile wins.  Returns
        whether a selection was saved; never raises.
        """

        try:
            selection = self._gateway_selection()
            if selection is None or selection.state != "legacy":
                return False
            route_lock = getattr(self, "_runtime_route_snapshot_lock", None)
            with route_lock if route_lock is not None else nullcontext():
                snapshot = getattr(self, "_runtime_route_snapshot", None)
                contract = getattr(self, "_runtime_loaded_export_contract", None)
                proxy_map = contract.get("proxy_map") if isinstance(contract, dict) else None
                entries = dict(proxy_map) if isinstance(proxy_map, dict) else None
            if snapshot is None or not entries:
                return False
            receipt_digest = str(
                contract.get("route_authority_semantic_digest")
                or contract.get("semantic_digest")
                or ""
            )
            if receipt_digest != str(getattr(snapshot, "semantic_digest", "") or ""):
                # The published route is not this contract's yet: no verdict,
                # a later tick checks again once it is.
                return False
            signature = (receipt_digest, int(contract.get("revision") or 0), selection.key)
            if signature == getattr(self, "_gateway_selection_binding_signature", None):
                return False
            exit_select = {row.name: row for row in snapshot.group_states}.get("EXIT-SELECT")
            served = set(exit_select.members) if exit_select is not None else set()
            member, member_node = "", None
            for name, info in entries.items():
                if (
                    isinstance(info, dict)
                    and str(info.get("tier") or "") == "exit"
                    and str(info.get("selected_for") or "") == selection.key
                    and str(name) in served
                    and info.get("node") is not None
                ):
                    member, member_node = str(name), info["node"]
                    break
            inventory_getter = getattr(self.manager, "gateway_legacy_exit_inventory", None)
            if callable(inventory_getter):
                inventory, settled = inventory_getter()
            else:
                inventory, settled = list(getattr(self.manager, "runtime_nodes", {}).get("exit", [])), True
            family = gateway_legacy_family(
                selection.label,
                [*inventory, *([member_node] if member_node is not None else [])],
            )
            if len(family) >= 2:
                write: tuple[str, str, str] = ("unresolved", selection.label, "ambiguous")
            elif member_node is not None and not settled:
                # A twin may still hide in a subscription not fetched yet.
                return False
            elif member_node is not None and family == {gateway_identity(member_node)}:
                write = ("bound", member, gateway_identity(member_node))
            else:
                # Once per published contract and selection: nothing to save.
                self._gateway_selection_binding_signature = signature
                return False
            kind, label, value = write
            with self._config_change_lock:
                # A Gateway the user picked meanwhile wins.
                if selection_from_manager(self.manager).key != selection.key:
                    return False
                # Once per published contract and selection, even when the
                # write fails: an unwritable file is not retried (and logged)
                # every tick.
                self._gateway_selection_binding_signature = signature
                try:
                    saved = self.config_store.compare_and_set_exit_selection(
                        selection.key,
                        label,
                        identity=value if kind == "bound" else None,
                        unresolved=value if kind == "unresolved" else None,
                    )
                except Exception as exc:
                    log_raw_diagnostic(
                        self.logger,
                        "warning",
                        "Gateway selection could not be bound to its node identity: %s",
                        type(exc).__name__,
                    )
                    return False
                if saved:
                    tiers = self.config.get("tiers") if isinstance(self.config, dict) else None
                    block = tiers.get("exit") if isinstance(tiers, dict) else None
                    if isinstance(block, dict):
                        # Replaced, not mutated: readers copy the config unlocked.
                        updated = dict(block)
                        if kind == "bound":
                            write_bound_selection(updated, label, value)
                        else:
                            write_unresolved_selection(updated, label, value)
                        tiers["exit"] = updated
            if not saved:
                return False
            self.logger.info(
                "Gateway selection bound to its node identity"
                if kind == "bound"
                else "Gateway selection needs to be picked again (its name is ambiguous)"
            )
            return True
        except Exception:
            log_raw_diagnostic(
                self.logger,
                "exception",
                "Gateway selection could not be bound to its node identity",
            )
            return False

    def _runtime_audit_leaf_info(self, leaf: str) -> dict[str, Any] | None:
        """The node Core loaded under a live route leaf name.

        The proxy map published with the route first: same-named Gateways
        swap their names with order and status, so a naming replay over the
        runtime list can name the twin.  The replay only when the published
        map has no such entry.
        """

        route_lock = getattr(self, "_runtime_route_snapshot_lock", None)
        with route_lock if route_lock is not None else nullcontext():
            published = getattr(self, "_runtime_route_snapshot_payload", None)
            published_map = published.get("proxy_map") if isinstance(published, dict) else None
            published_info = published_map.get(leaf) if isinstance(published_map, dict) else None
        if isinstance(published_info, dict):
            return dict(published_info)
        return self._runtime_proxy_name_map(include_runtime_unusable=True).get(leaf)

    def _runtime_audit_cooldown_key(self, trigger: str, route: dict[str, Any]) -> str:
        chain = ">".join(str(item) for item in route.get("selected_chain", []) or [])
        return "|".join(
            [
                str(trigger or "runtime_egress"),
                str(route.get("route_marker") or ""),
                chain,
                str(route.get("leaf_proxy") or ""),
            ]
        )

    def _runtime_audit_cooldown_active(self, key: str, *, now: float, cooldown_seconds: float = 2.0) -> bool:
        if not key:
            return False
        expires_at = self._runtime_route_audit_cooldowns.get(key, 0.0)
        return bool(expires_at and expires_at > now)

    def _mark_runtime_audit_cooldown(self, key: str, *, now: float, cooldown_seconds: float = 2.0) -> None:
        if key:
            self._runtime_route_audit_cooldowns[key] = now + max(0.1, float(cooldown_seconds))
        expired = [item for item, expires_at in self._runtime_route_audit_cooldowns.items() if expires_at <= now]
        for item in expired:
            self._runtime_route_audit_cooldowns.pop(item, None)

    def _probe_proxy_delay_with_urls(
        self,
        proxy_name: str,
        probe_urls: list[str],
        *,
        timeout_ms: int | None = None,
        request_timeout_seconds: float | None = None,
        expected_status: str | int | None = None,
        probe_priority: ProbePriority = ProbePriority.RUNTIME_MANUAL,
        recovery_ticket: _RuntimeRecoveryTicket | None = None,
        recovery_deadline_monotonic: float | None = None,
    ) -> dict[str, Any]:
        effective_timeout_ms = (
            self._default_probe_timeout_ms()
            if timeout_ms is None
            else max(100, int(timeout_ms))
        )
        total_budget_seconds = max(
            0.1,
            float(request_timeout_seconds)
            if request_timeout_seconds is not None
            else effective_timeout_ms / 1000.0,
        )
        return self._run_brokered_runtime_probe(
            lambda context: self._probe_proxy_delay_with_urls_leased(
                proxy_name,
                probe_urls,
                timeout_ms=effective_timeout_ms,
                request_timeout_seconds=total_budget_seconds,
                expected_status=expected_status,
                execution_context=context,
                recovery_ticket=recovery_ticket,
                recovery_deadline_monotonic=(
                    recovery_deadline_monotonic
                ),
            ),
            priority=probe_priority,
            queue_timeout_seconds=min(1.5, total_budget_seconds),
            socket_start_timeout_seconds=min(0.5, total_budget_seconds),
            execution_deadline_monotonic=(
                time.monotonic() + total_budget_seconds
            ),
        )

    def _probe_proxy_delay_with_urls_leased(
        self,
        proxy_name: str,
        probe_urls: list[str],
        *,
        timeout_ms: int,
        request_timeout_seconds: float,
        expected_status: str | int | None = None,
        execution_context: ProbeExecutionContext | None = None,
        recovery_ticket: _RuntimeRecoveryTicket | None = None,
        recovery_deadline_monotonic: float | None = None,
    ) -> dict[str, Any]:
        failures: list[str] = []
        failure_exceptions: list[Exception] = []
        client = self._require_api_client()
        deadline = time.monotonic() + max(
            0.1,
            float(request_timeout_seconds),
        )
        if execution_context is not None and execution_context.execution_deadline_monotonic is not None:
            deadline = min(deadline, execution_context.execution_deadline_monotonic)
        socket_marked = False
        abort_owner = _RuntimeAbortHandle()
        if (
            execution_context is not None
            and execution_context.execution_deadline_monotonic is not None
            and not execution_context.register_abort_callback(abort_owner.abort)
        ):
            raise _RuntimeProbeBudgetUnavailable(
                "runtime controller probe expired before abort registration"
            )

        def connection_abort_sink(close: Callable[[], None]) -> None:
            nonlocal socket_marked
            abort_owner.bind(close)
            if not socket_marked:
                self._mark_runtime_probe_socket_started_for_ticket(
                    execution_context,
                    recovery_ticket=recovery_ticket,
                    deadline_monotonic=recovery_deadline_monotonic,
                )
                socket_marked = True

        for probe_url in probe_urls or [self._default_probe_url()]:
            remaining = deadline - time.monotonic()
            if remaining <= 0.05:
                break
            # Core must finish its URL test before the HTTP client times out,
            # and that client must return before the broker cancels its slot.
            # Equal deadlines lose the Core's negative 504 verdict and turn
            # every black-holed node into permanent controller uncertainty.
            cleanup_margin = 0.1 if execution_context is not None else 0.0
            request_timeout = max(0.05, remaining - cleanup_margin)
            request_timeout_ms = max(
                50,
                min(int(timeout_ms), int(max(0.05, request_timeout - 0.15) * 1000.0)),
            )
            self._register_runtime_internal_probe(
                probe_url,
                timeout_seconds=request_timeout,
            )
            try:
                expected_verified = False
                try:
                    result = client.proxy_delay(
                        proxy_name,
                        url=probe_url,
                        timeout_ms=request_timeout_ms,
                        expected_status=expected_status,
                        request_timeout=request_timeout,
                        connection_abort_sink=connection_abort_sink,
                        verify_expected_status=expected_status is not None,
                    )
                    expected_verified = expected_status is not None
                except TypeError:
                    # Injected legacy test clients do not expose the abortable
                    # controller adapter.  Production MihomoAPIClient always
                    # invokes ``connection_abort_sink`` before it can dial.
                    if not socket_marked:
                        self._mark_runtime_probe_socket_started_for_ticket(
                            execution_context,
                            recovery_ticket=recovery_ticket,
                            deadline_monotonic=(
                                recovery_deadline_monotonic
                            ),
                        )
                        socket_marked = True
                    try:
                        result = client.proxy_delay(
                            proxy_name,
                            url=probe_url,
                            timeout_ms=request_timeout_ms,
                            expected_status=expected_status,
                            request_timeout=request_timeout,
                        )
                        expected_verified = expected_status is not None
                    except TypeError:
                        result = client.proxy_delay(
                            proxy_name,
                            url=probe_url,
                            timeout_ms=request_timeout_ms,
                        )
                if isinstance(result, dict):
                    result = dict(result)
                    result.setdefault("probe_url", probe_url)
                    if expected_verified:
                        result["expected_status_verified"] = True
                        if str(expected_status).strip() == "204":
                            result.setdefault("status", 204)
                return result
            except _RuntimeProbeBudgetUnavailable:
                raise
            except Exception as exc:
                failures.append(f"{probe_url}: {exc}")
                failure_exceptions.append(exc)
        if failure_exceptions and all(isinstance(exc, MihomoDelayTestFailed) for exc in failure_exceptions):
            raise failure_exceptions[-1]
        if any(isinstance(exc, MihomoAPIError) for exc in failure_exceptions):
            raise MihomoAPIError("; ".join(failures[:3]))
        raise RuntimeError(
            "; ".join(failures[:3])
            or f"{proxy_name} proxy delay deadline expired"
        )

    @staticmethod
    def _proxy_delay_failure_is_transient(exc: Exception) -> bool:
        if isinstance(exc, MihomoDelayTestFailed):
            return False
        if isinstance(exc, MihomoAPIError):
            return True
        if isinstance(exc, _RuntimeProbeBudgetUnavailable):
            return True
        text = str(exc or "").lower()
        transient_markers = (
            " 503",
            "503",
            " 504",
            "504",
            "service unavailable",
            "gateway timeout",
            "controller unavailable",
            "controller transient",
        )
        return any(marker in text for marker in transient_markers)

    def _probe_final_exit_delay(self) -> dict[str, Any]:
        return self._probe_proxy_delay_with_urls("FINAL-EXIT", self._default_probe_urls())

    def _set_runtime_audit_result(
        self,
        result: dict[str, Any],
        *,
        readiness_only: bool = False,
    ) -> dict[str, Any]:
        self.last_runtime_route_audit = dict(result)
        state_setter = (
            self._set_effective_egress_readiness_state
            if readiness_only
            else self._set_effective_egress_state
        )
        state_setter(
            result.get("effective_egress_ok"),
            str(result.get("reason") or ""),
        )
        evaluator = getattr(self.manager, "evaluate_state", None)
        if callable(evaluator):
            try:
                evaluator()
            except Exception:
                log_raw_diagnostic(
                    self.logger,
                    "warning",
                    "Runtime route audit state evaluation failed",
                    exc_info=True,
                )
        return result

    def _confirm_runtime_leaf(self, leaf_info: dict[str, Any], *, reason: str, route_marker: str) -> tuple[bool, Any | None]:
        manager = self.manager
        if not manager:
            return False, None
        tier = str(leaf_info.get("tier") or "")
        identity = str(leaf_info.get("identity") or "")
        if not tier or not identity:
            return False, None
        if tier == "tier3":
            try:
                result = self._probe_proxy_delay_with_urls(
                    str(leaf_info.get("proxy_name") or ""),
                    self._probe_urls_for_node(leaf_info.get("node")),
                )
                delay = tier3_core_delay_from_probe_result(result)
                return True, {"delay": delay}
            except Exception as exc:
                if self._proxy_delay_failure_is_transient(exc):
                    return False, {
                        "facility_failure": f"leaf proxy-delay transient failure: {exc}",
                        "transient": True,
                    }
                try:
                    with manager.lock:
                        report = ensure_tier3_collection_report(manager)
                        report["background_expansion_due"] = True
                        manager.last_collect_tier3 = 0.0
                except Exception:
                    log_raw_diagnostic(
                        self.logger,
                        "warning",
                        "Failed to mark Bastion Layer runtime audit refill due",
                        exc_info=True,
                    )
                return False, None
        tester = getattr(manager, "_test_runtime_node_by_identity", None)
        if not callable(tester):
            return False, None
        try:
            tested = tester(
                tier,
                identity,
                mark_layer_check=False,
                persist_result=False,
            )
        except TypeError:
            try:
                tested = tester(tier, identity, mark_layer_check=False)
            except TypeError:
                tested = tester(tier, identity)
        healthy = getattr(tested, "status", None) in {NodeStatus.ALIVE, NodeStatus.SLOW}
        return bool(healthy), tested

    def _hot_reload_runtime_audit_overlay(
        self,
        *,
        queue_revalidation: bool = True,
        timeout_seconds: float | None = None,
        deadline_monotonic: float | None = None,
    ) -> dict[str, Any]:
        # Runtime health is an eligibility/selection concern, never a Core
        # graph lifecycle event. ApplyConfig can suspend listeners and rebuild
        # runtime components, so using it here would trade one failed new dial
        # for interruptions across unrelated healthy connections. The loaded
        # leaf definition remains available for drain and authoritative PASS.
        del queue_revalidation, timeout_seconds, deadline_monotonic
        return {
            "reloaded": False,
            "reload_blocked": True,
            "reason": "runtime health hot-path Core reload is forbidden",
        }

        # Kept below temporarily as a source-compatible reference for older
        # focused adapters; the unconditional gate above is authoritative.
        with self._core_transition_lock:
            def remaining(default_seconds: float) -> float:
                value = float(default_seconds)
                if timeout_seconds is not None:
                    value = min(value, float(timeout_seconds))
                if deadline_monotonic is not None:
                    value = min(
                        value,
                        float(deadline_monotonic) - time.monotonic(),
                    )
                return max(0.0, value)

            if remaining(float(timeout_seconds or 5.0)) <= 0.0:
                return {
                    "reloaded": False,
                    "reason": "runtime recovery deadline expired before Core reload",
                }
            runner = self.core_runner
            if not runner or not runner.is_running():
                return {"reloaded": False, "reason": "mihomo core is not running"}
            if self._current_core_runtime_phase() in {
                "bootstrap",
                "formal_no_capture",
            }:
                return {
                    "reloaded": False,
                    "reason": "mihomo core is still in a no-capture phase",
                }
            self._begin_core_route_mutation(
                "Mihomo runtime audit route mutation; FINAL-EXIT 204 verification is pending"
            )
            try:
                runtime_config_path = self.write_mihomo_runtime_config()
                if remaining(float(timeout_seconds or 5.0)) <= 0.0:
                    self._settle_failed_core_route_mutation(
                        "runtime recovery deadline expired during config render"
                    )
                    return {
                        "reloaded": False,
                        "reason": (
                            "runtime recovery deadline expired during config render"
                        ),
                    }
                controller = self._mihomo_controller_config()
                if not mihomo_controller_enabled(controller):
                    if deadline_monotonic is not None:
                        self._settle_failed_core_route_mutation(
                            "bounded runtime recovery requires the Mihomo controller"
                        )
                        return {
                            "reloaded": False,
                            "reason": (
                                "bounded runtime recovery cannot restart Core "
                                "without the Mihomo controller"
                            ),
                        }
                    restart_result = self.restart_core()
                    reloaded = bool(
                        restart_result.get("running")
                        or restart_result.get("core", {}).get("running")
                    )
                    if reloaded:
                        self._mark_core_export_sync_success()
                        self._invalidate_exit_route_context()
                    elif self._core_route_mutation_is_pending():
                        self._settle_failed_core_route_mutation(
                            "Mihomo runtime audit restart failed"
                        )
                    return {"reloaded": reloaded, "restart": restart_result}
                reload_kwargs = hot_reload_kwargs_from_controller(controller)
                reload_budget = remaining(
                    float(reload_kwargs.get("timeout") or 5.0)
                )
                if reload_budget <= 0.0:
                    self._settle_failed_core_route_mutation(
                        "runtime recovery deadline expired before controller reload"
                    )
                    return {
                        "reloaded": False,
                        "reason": (
                            "runtime recovery deadline expired before controller reload"
                        ),
                    }
                reload_kwargs["timeout"] = reload_budget
                result = runner.hot_reload(**reload_kwargs)
            except Exception:
                self._settle_failed_core_route_mutation(
                    "Mihomo runtime audit mutation failed"
                )
                raise
            result["runtime_config_path"] = str(runtime_config_path)
            if result.get("reloaded"):
                with self._runtime_route_snapshot_lock:
                    self._runtime_route_epoch += 1
                    self._node_judgement_arm_epoch("hot_reload_runtime_audit_overlay")
                    self._mark_runtime_route_attribution_barrier_locked()
                    self._runtime_route_snapshot = None
                    self._runtime_route_snapshot_payload = None
                    self._runtime_core_inventory_snapshot = None
                self._runtime_egress_coordinator.set_current_snapshot(None)
                self._mark_core_export_sync_success()
                self._invalidate_exit_route_context()
                self._queue_runtime_route_snapshot_refresh()
                self._set_effective_egress_state(
                    None,
                    "Mihomo route rotated; FINAL-EXIT 204 verification is pending",
                )
                if queue_revalidation:
                    self._queue_incremental_egress_recheck()
            else:
                self._settle_failed_core_route_mutation(
                    "Mihomo runtime audit hot reload failed"
                )
            return result

    def audit_runtime_egress(
        self,
        reason: str = "runtime egress verification failed",
        *,
        trigger: str = "final_exit_delay",
        confirmed_transport_failure: bool = False,
        corroborated_transport_failure: bool = False,
        canonical_health_applied: bool = False,
        canonical_failed_binding: RuntimeRouteBinding | None = None,
        max_steps: int | None = None,
        exclusion_ttl_seconds: float | None = None,
        bounded_probe_seconds: float | None = None,
        deadline_monotonic: float | None = None,
    ) -> dict[str, Any]:
        """Runtime audit overlay for the currently selected Mihomo route."""
        if self.stop_event.is_set():
            return {"attempted": False, "reason": "runtime stopping"}
        if self._runtime_uses_early_single_coordinator():
            result = self._runtime_audit_base_result(
                reason=reason,
                trigger=trigger,
            )
            result["effective_egress_ok"] = bool(
                getattr(self.manager, "effective_egress_ok", False) is True
            )
            result["identity_diagnostic_only"] = bool(
                str(trigger or "").strip().casefold()
                == "exit_identity_transport"
            )
            try:
                payload = self._mihomo_proxies_bounded(
                    min(0.35, max(0.05, float(bounded_probe_seconds or 0.35)))
                )
                route = inspect_runtime_route(payload)
                result.update(
                    {
                        "attempted": False,
                        "diagnostic_only": True,
                        "selected_chain": route.get("selected_chain", []),
                        "route_marker": route.get("route_marker", ""),
                        "leaf_proxy": str(route.get("leaf_proxy") or ""),
                        "reason": "automatic runtime recovery is disabled",
                    }
                )
            except Exception as exc:
                result.update(
                    {
                        "attempted": False,
                        "diagnostic_only": True,
                        "reason": (
                            "automatic runtime recovery is disabled; controller "
                            f"diagnostic failed ({type(exc).__name__})"
                        ),
                    }
                )
            return self._set_runtime_audit_result(result)
        if str(trigger or "").strip().casefold() == "exit_identity_transport":
            result = self._runtime_audit_base_result(
                reason=reason,
                trigger=trigger,
            )
            result.update(
                {
                    "attempted": False,
                    "identity_diagnostic_only": True,
                    "effective_egress_ok": bool(
                        getattr(self.manager, "effective_egress_ok", False)
                        is True
                    ),
                    "reason": (
                        "identity diagnostics are isolated from runtime "
                        "egress recovery"
                    ),
                }
            )
            return self._set_runtime_audit_result(result)
        manager = self.manager
        if (
            self._tier3_required_for_start
            and manager
            and not bool(getattr(manager, "tier3_startup_gate_satisfied", False))
        ):
            return {
                "attempted": False,
                "reason": "Bastion Layer startup gate is pending; runtime audit is disabled before core start",
                "pre_gate_runtime_audit_suppressed": True,
            }
        if not self._runtime_route_audit_lock.acquire(blocking=False):
            return {"attempted": False, "reason": "runtime route audit already running"}
        result = self._runtime_audit_base_result(reason=reason, trigger=trigger)
        failed_proxies: set[str] = set()
        handled_route_keys: set[str] = set()
        active_gateway = self._active_gateway_policy_enabled()
        canonical_reconciled = False
        canonical_replacement_binding_state: tuple[
            RuntimeRouteBinding,
            CoreLoadedRouteSnapshot,
            dict[str, Any],
        ] | None = None
        hard_deadline = (
            float(deadline_monotonic)
            if deadline_monotonic is not None
            else None
        )

        def remaining_deadline(default_seconds: float) -> float:
            if hard_deadline is None:
                return max(0.05, float(default_seconds))
            return max(
                0.0,
                min(float(default_seconds), hard_deadline - time.monotonic()),
            )

        try:
            step_limit = 4 if max_steps is None else max(0, min(4, int(max_steps)))
            for step in range(1, step_limit + 1):
                if hard_deadline is not None and time.monotonic() >= hard_deadline:
                    result["reason"] = "runtime recovery reached its hard deadline"
                    result["deadline_exceeded"] = True
                    return self._set_runtime_audit_result(result)
                result["recovery_steps"] = step
                try:
                    proxies_payload = self._mihomo_proxies_bounded(
                        remaining_deadline(0.35)
                    )
                except Exception as exc:
                    result["facility_failure"] = f"mihomo controller /proxies failed: {exc}"
                    result["reason"] = result["facility_failure"]
                    return self._set_runtime_audit_result(result)
                route = inspect_runtime_route(proxies_payload)
                result["selected_chain"] = route.get("selected_chain", [])
                result["route_marker"] = route.get("route_marker", "")
                result["leaf_proxy"] = str(route.get("leaf_proxy") or "")
                if route.get("facility_failure"):
                    result["facility_failure"] = str(route["facility_failure"])
                    result["reason"] = result["facility_failure"]
                    return self._set_runtime_audit_result(result)

                leaf = result["leaf_proxy"]
                if not leaf:
                    result["facility_failure"] = "runtime route has no leaf proxy"
                    result["reason"] = result["facility_failure"]
                    return self._set_runtime_audit_result(result)
                terminal_kind = builtin_terminal_kind(leaf)
                if terminal_kind:
                    result["terminal_kind"] = terminal_kind
                    if terminal_kind == "fail_closed":
                        result["fail_closed_terminal"] = True
                        result["reason"] = f"runtime route reached fail-closed terminal: {leaf}"
                    else:
                        result["facility_failure"] = (
                            "runtime route selected unsafe direct-equivalent terminal: "
                            f"{leaf}"
                        )
                        result["reason"] = result["facility_failure"]
                    return self._set_runtime_audit_result(result)

                key = self._runtime_audit_cooldown_key(str(trigger), route)
                now = time.monotonic()
                if key not in handled_route_keys and self._runtime_audit_cooldown_active(key, now=now):
                    result["reason"] = "runtime route audit recently handled the same selected chain"
                    return self._set_runtime_audit_result(result)
                self._mark_runtime_audit_cooldown(key, now=now)
                handled_route_keys.add(key)

                leaf_info = self._runtime_audit_leaf_info(leaf)
                if leaf_info is None:
                    result["facility_failure"] = f"runtime leaf proxy is not mapped to a managed node: {leaf}"
                    result["reason"] = result["facility_failure"]
                    return self._set_runtime_audit_result(result)
                result["leaf_identity"] = str(leaf_info.get("identity") or "")

                if (
                    canonical_health_applied
                    and canonical_failed_binding is not None
                    and not canonical_reconciled
                ):
                    failed_ref = canonical_failed_binding.node
                    reload_result = self._hot_reload_runtime_audit_overlay(
                        queue_revalidation=False,
                        timeout_seconds=remaining_deadline(1.0),
                        deadline_monotonic=hard_deadline,
                    )
                    result["switch_actions"].append(
                        {
                            "type": "hot_reload_canonical_failed_binding",
                            "leaf_proxy": failed_ref.proxy_name,
                            "leaf_identity": failed_ref.identity,
                            "failed_tier": failed_ref.tier,
                            "failed_pool_kind": failed_ref.pool_kind,
                            "reload": reload_result,
                        }
                    )
                    canonical_reconciled = True
                    if not reload_result.get("reloaded"):
                        result["reason"] = (
                            "Runtime failover reload failed: "
                            f"{reload_result.get('reason')}"
                        )
                        return self._set_runtime_audit_result(result)
                    authority_budget = remaining_deadline(0.75)
                    if authority_budget <= 0.0:
                        result["reason"] = (
                            "runtime recovery reached its hard deadline before "
                            "replacement route readback"
                        )
                        result["deadline_exceeded"] = True
                        return self._set_runtime_audit_result(result)
                    canonical_replacement_binding_state = (
                        self._current_runtime_failure_binding_state(
                            timeout_seconds=authority_budget,
                            refresh=True,
                        )
                    )
                    if canonical_replacement_binding_state is None:
                        hold_reason = (
                            "Replacement route authority could not be read back "
                            "within the bounded recovery transaction"
                        )
                        self._publish_tier3_controller_hold(hold_reason)
                        result["controller_hold"] = True
                        result["reason"] = hold_reason
                        return self._set_runtime_audit_result(result)
                    try:
                        probe_budget = remaining_deadline(
                            float(bounded_probe_seconds or 1.5)
                        )
                        if probe_budget <= 0.0:
                            result["reason"] = (
                                "runtime recovery reached its hard deadline before 204 verification"
                            )
                            result["deadline_exceeded"] = True
                            return self._set_runtime_audit_result(result)
                        final_result = self._probe_mihomo_mixed_port_once(
                            timeout_seconds=probe_budget
                        )
                        result["post_switch_result"] = final_result
                        result["post_switch_connectivity_verified"] = True
                        result["post_switch_verified"] = True
                        result["effective_egress_ok"] = True
                        result["reason"] = "FINAL-EXIT 204 connectivity recovered"
                        return self._set_runtime_audit_result(result)
                    except Exception as exc:
                        result["reason"] = (
                            "FINAL-EXIT still failed after canonical route reconcile: "
                            f"{exc}"
                        )
                        continue

                if canonical_reconciled:
                    # The replacement is a different immutable binding.  A
                    # failed chain verification cannot reuse the original
                    # leaf's confirmation.  Start a fresh neutral/direct
                    # confirmation and keep this transaction fail-closed.
                    self._submit_current_route_probe_failure(
                        "replacement route failed post-switch verification",
                        source="replacement_verification",
                        binding_state=canonical_replacement_binding_state,
                        binding_captured=True,
                    )
                    result["reason"] = (
                        "replacement route requires an independent binding confirmation"
                    )
                    return self._set_runtime_audit_result(result)

                tier = str(leaf_info.get("tier") or "")
                definitive_leaf_failure = bool(confirmed_transport_failure)
                if not confirmed_transport_failure:
                    healthy, tested = self._confirm_runtime_leaf(
                        leaf_info,
                        reason=str(reason or "runtime egress verification failed"),
                        route_marker=str(route.get("route_marker") or ""),
                    )
                    if healthy:
                        self._clear_runtime_audit_export_identity(
                            str(leaf_info.get("identity") or "")
                        )
                        result["facility_failure"] = "leaf proxy passed targeted validation but FINAL-EXIT failed"
                        result["reason"] = result["facility_failure"]
                        return self._set_runtime_audit_result(result)
                    if isinstance(tested, dict) and tested.get("facility_failure"):
                        result["facility_failure"] = str(tested.get("facility_failure") or "")
                        result["reason"] = result["facility_failure"]
                        result["confirmed_failure"] = False
                        return self._set_runtime_audit_result(result)
                    if tier == "tier3" and tested is None:
                        definitive_leaf_failure = True
                    elif getattr(tested, "status", None) is NodeStatus.DEAD:
                        definitive_leaf_failure = True
                result["confirmed_failure"] = True
                failed_proxies.add(leaf)

                if active_gateway and tier == "exit":
                    # A fixed Gateway is a strict fail-closed policy.  Once
                    # its canonical health overlay is applied, reload the
                    # generated route so EXIT-SELECT contains REJECT instead
                    # of leaving the failed Gateway live in Core.  Never pick
                    # another Gateway or fall through to PROXY-FALLBACK.
                    if confirmed_transport_failure and canonical_health_applied:
                        reload_result = self._hot_reload_runtime_audit_overlay(
                            queue_revalidation=False,
                            timeout_seconds=remaining_deadline(1.0),
                            deadline_monotonic=hard_deadline,
                        )
                        result["switch_actions"].append(
                            {
                                "type": "hot_reload_fail_closed_gateway",
                                "leaf_proxy": leaf,
                                "leaf_identity": result["leaf_identity"],
                                "reload": reload_result,
                            }
                        )
                        result["fail_closed_terminal"] = True
                        if not reload_result.get("reloaded"):
                            result["reason"] = (
                                "Fixed Gateway fail-closed reload failed: "
                                f"{reload_result.get('reason')}"
                            )
                            return self._set_runtime_audit_result(result)
                    result["reason"] = (
                        f"selected Gateway exit failed targeted validation: {leaf}; "
                        "fixed Gateway policy remains fail-closed"
                    )
                    return self._set_runtime_audit_result(result)

                if confirmed_transport_failure:
                    leaf_identity = str(leaf_info.get("identity") or "")
                    if canonical_health_applied:
                        exclusion_confirmed = True
                    elif corroborated_transport_failure:
                        self._exclude_runtime_audit_export_identity(
                            leaf_identity,
                            ttl_seconds=exclusion_ttl_seconds,
                            reason="corroborated_transport_failure",
                            release_on_healthy=True,
                            require_health_recheck=True,
                        )
                        exclusion_confirmed = True
                    else:
                        exclusion_confirmed = self._record_runtime_audit_export_failure(
                            leaf_identity,
                            definitive=definitive_leaf_failure,
                            ttl_seconds=exclusion_ttl_seconds,
                            reason="identity_transport_failure",
                        )
                    if not exclusion_confirmed:
                        result["confirmed_failure"] = False
                        result["reason"] = (
                            "runtime leaf failure is awaiting a second "
                            "deterministic result in the current config generation"
                        )
                        return self._set_runtime_audit_result(result)
                    reload_result = self._hot_reload_runtime_audit_overlay(
                        queue_revalidation=False,
                        timeout_seconds=remaining_deadline(1.0),
                        deadline_monotonic=hard_deadline,
                    )
                    result["switch_actions"].append(
                        {
                            "type": "hot_reload_excluding_transport_failed_leaf",
                            "leaf_proxy": leaf,
                            "leaf_identity": result["leaf_identity"],
                            "reload": reload_result,
                        }
                    )
                    if not reload_result.get("reloaded"):
                        result["reason"] = f"Runtime failover reload failed: {reload_result.get('reason')}"
                        return self._set_runtime_audit_result(result)
                elif tier == "tier3" and self._tier3_is_primary_export():
                    if not self._record_runtime_audit_export_failure(
                        str(leaf_info.get("identity") or ""),
                        definitive=definitive_leaf_failure,
                        reason="tier3_runtime_leaf_failure",
                    ):
                        result["confirmed_failure"] = False
                        result["reason"] = (
                            "Bastion Layer leaf remains pending after the first "
                            "deterministic runtime failure"
                        )
                        return self._set_runtime_audit_result(result)
                    reload_result = self._hot_reload_runtime_audit_overlay(
                        queue_revalidation=False,
                        timeout_seconds=remaining_deadline(1.0),
                        deadline_monotonic=hard_deadline,
                    )
                    result["switch_actions"].append(
                        {
                            "type": "hot_reload_excluding_tier3_leaf",
                            "leaf_proxy": leaf,
                            "leaf_identity": result["leaf_identity"],
                            "reload": reload_result,
                        }
                    )
                    if not reload_result.get("reloaded"):
                        result["reason"] = f"Bastion Layer runtime failover reload failed: {reload_result.get('reason')}"
                        return self._set_runtime_audit_result(result)
                else:
                    action = next_viable_candidate(route, failed_proxies=failed_proxies, active_gateway=active_gateway)
                    if action:
                        selection = self.select_mihomo_proxy(
                            action["group"],
                            action["proxy"],
                            revalidate=False,
                        )
                        result["switch_actions"].append({"type": "select_proxy", **action, "selection": selection})
                    else:
                        if not self._record_runtime_audit_export_failure(
                            str(leaf_info.get("identity") or ""),
                            definitive=definitive_leaf_failure,
                            reason="runtime_leaf_failure",
                        ):
                            result["confirmed_failure"] = False
                            result["reason"] = (
                                "runtime leaf remains pending after a non-terminal "
                                "or first deterministic failure"
                            )
                            return self._set_runtime_audit_result(result)
                        reload_result = self._hot_reload_runtime_audit_overlay(
                            queue_revalidation=False,
                            timeout_seconds=remaining_deadline(1.0),
                            deadline_monotonic=hard_deadline,
                        )
                        result["switch_actions"].append(
                            {
                                "type": "hot_reload_excluding_leaf",
                                "leaf_proxy": leaf,
                                "leaf_identity": result["leaf_identity"],
                                "reload": reload_result,
                            }
                        )
                        if not reload_result.get("reloaded"):
                            result["reason"] = (
                                "Runtime audit overlay reload was blocked: "
                                f"{reload_result.get('reason')}"
                            )
                            return self._set_runtime_audit_result(result)

                try:
                    probe_budget = remaining_deadline(
                        float(bounded_probe_seconds)
                        if bounded_probe_seconds is not None
                        else self._startup_probe_timeout_seconds()
                    )
                    if probe_budget <= 0.0:
                        result["reason"] = (
                            "runtime recovery reached its hard deadline before 204 verification"
                        )
                        result["deadline_exceeded"] = True
                        return self._set_runtime_audit_result(result)
                    final_result = (
                        self._probe_mihomo_mixed_port_once(
                            timeout_seconds=probe_budget
                        )
                        if bounded_probe_seconds is not None
                        else self._probe_mihomo_mixed_port()
                    )
                    result["post_switch_result"] = final_result
                    result["post_switch_connectivity_verified"] = True
                    result["post_switch_verified"] = True
                    result["effective_egress_ok"] = True
                    result["reason"] = "FINAL-EXIT 204 connectivity recovered"
                    return self._set_runtime_audit_result(result)
                except Exception as exc:
                    result["reason"] = f"FINAL-EXIT still failed after runtime audit step {step}: {exc}"
                    continue
            result["reason"] = result["reason"] or "runtime route audit reached recovery step limit"
            return self._set_runtime_audit_result(result)
        finally:
            self._runtime_route_audit_lock.release()

    def audit_tier3_runtime_egress(self, *, reason: str = "runtime egress verification failed") -> dict[str, Any]:
        """Audit the runtime overlay without mutating the committed Tier3 pool."""
        if self.stop_event.is_set():
            return {"attempted": False, "reason": "runtime stopping"}
        if not self._tier3_is_primary_export():
            return {"attempted": False, "reason": "current export is not Bastion Layer"}
        runner = self.core_runner
        if not runner or not runner.is_running():
            return {"attempted": False, "reason": "mihomo core is not running"}
        if not self.manager:
            return {"attempted": False, "reason": "manager service is not running"}
        queued = self._submit_current_route_probe_failure(
            str(reason or "runtime egress verification failed"),
            source="tier3_runtime_egress",
        )
        return {
            "attempted": True,
            "reloaded": False,
            "failover": False,
            "connectivity_recovered": False,
            "verification_pending": bool(queued),
            "reason": (
                "global runtime egress confirmation queued"
                if queued
                else "global runtime egress confirmation could not bind the route"
            ),
            "reload": {},
            "route_audit": {
                "attempted": False,
                "delegated_to_global_coordinator": bool(queued),
            },
        }

    def _recover_runtime_source_transport_failure(
        self,
        payload: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        policy = egress_recovery_policy(self.config)
        if not policy.enabled or not policy.retry_source_refresh or policy.max_rotations <= 0:
            return {
                "recovered": False,
                "reason": "runtime source egress recovery is disabled",
            }
        manager = self.manager
        if manager is None or getattr(manager, "effective_egress_ok", None) is not True:
            return {
                "recovered": False,
                "reason": "runtime source retry requires verified FINAL-EXIT",
            }
        detail = payload if isinstance(payload, dict) else {}
        reason = str(
            detail.get("reason")
            or "runtime source transport failed through FINAL-EXIT"
        )
        queued = self._submit_current_route_probe_failure(
            reason,
            source="runtime_source_transport",
        )
        return {
            "recovered": False,
            "queued": queued,
            "reason": "runtime source recovery confirmation queued"
            if queued
            else reason,
        }

    def _verify_tier3_after_core_reload(self, *, save_snapshot: bool = True) -> bool:
        try:
            if self._tier3_is_primary_export():
                self._verify_tier3_final_exit_for_activation()
            else:
                self._probe_mihomo_mixed_port()
        except Exception as exc:
            # Group delay is useful diagnostics, but it is not an authority for
            # enabling traffic or source refresh. In particular, it may accept
            # a captive-portal 200/203 or exercise a different route.
            try:
                self._warm_tier3_group_after_core_start(strict=False)
            except Exception:
                pass
            reason = f"Mihomo reload FINAL-EXIT 204 verification failed: {exc}"
            self._set_effective_egress_state(False, reason)
            raise RuntimeError(reason) from exc
        # Decision D option A: the authoritative 204 passed on this Core at
        # these epochs; the strict reload's success tail may republish READY
        # at exactly them, and at no later route (the warm-up may move it).
        self._core_reload_final_exit_proof = self._core_reload_proof_stamp()
        try:
            self._warm_tier3_group_after_core_start(strict=False)
        except Exception as exc:
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Mihomo group warmup remained partial after authoritative 204: %s",
                exc,
            )
        self._set_effective_egress_state(True, "")
        if save_snapshot and self._tier3_is_primary_export():
            self._save_tier3_verified_snapshot()
        return True

    def _repair_and_retry_tier3_reload_after_verification_failure(
        self,
        runner: Any,
        controller: dict[str, Any],
    ) -> dict[str, Any]:
        if self._tier3_is_primary_export() or not self._repair_tier3_export_order_from_core_delays():
            return build_tier3_core_reload_failure_result(
                reason="Bastion Layer verification failed after hot reload",
                stop_sensitive=False,
            )
        # T-P2-RT3 fix 1: the mode this re-render loads (recorded by the caller,
        # also when the verification below fails: the Core has loaded it).
        loaded_network_mode = str(getattr(self, "network_mode", "") or "").strip().lower()
        self.write_mihomo_runtime_config()
        retry = runner.hot_reload(**hot_reload_kwargs_from_controller(controller))
        if not retry.get("reloaded"):
            return build_tier3_core_reload_failure_result(
                reason=f"hot reload after Bastion Layer repair failed: {retry.get('reason')}",
                stop_sensitive=True,
                reload_result=retry,
            )
        retry["_loaded_network_mode"] = loaded_network_mode
        try:
            self._verify_tier3_after_core_reload()
        except Exception:
            return build_tier3_core_reload_failure_result(
                reason="Bastion Layer verification failed after repair reload",
                stop_sensitive=False,
                reload_result=retry,
            )
        return retry

    def _capture_core_reload_context(self) -> CoreReloadContext:
        runtime_config_path = self._runtime_config_path_for_client()
        previous_config_text = read_existing_runtime_config_text(runtime_config_path)
        provider_path = self._tier3_core_provider_file_path()
        try:
            previous_provider_bytes = provider_path.read_bytes()
            previous_provider_exists = True
        except FileNotFoundError:
            previous_provider_bytes = b""
            previous_provider_exists = False
        controller = self._mihomo_controller_config()
        manager_nodes = getattr(self.manager, "runtime_nodes", {}) if self.manager else {}
        current_tier3_nodes = list(manager_nodes.get("tier3", []))
        return build_core_reload_context(
            runtime_config_path=runtime_config_path,
            previous_config_text=previous_config_text,
            controller=controller,
            current_tier3_nodes=current_tier3_nodes,
            last_synced_tier3_nodes=self._last_synced_tier3_nodes,
            clone_nodes=self._clone_runtime_nodes,
            provider_path=provider_path,
            previous_provider_bytes=previous_provider_bytes,
            previous_provider_exists=previous_provider_exists,
            previous_provider_projection=getattr(
                self,
                "_tier3_core_provider_last_projection",
                None,
            ),
        )

    def _core_reload_owner(self) -> tuple[int, int, int] | None:
        """The running Core's (pid, process_generation, core_generation), or None."""

        core = self.core_fact()
        if not core["running"]:
            return None
        owner = (
            int(core["pid"] or 0),
            int(core["process_generation"] or 0),
            int(core["core_generation"] or 0),
        )
        return owner if min(owner) > 0 else None

    def _core_reload_proof_stamp(self) -> tuple[Any, ...] | None:
        """Decision D option A: (route epoch, network epoch, Core owner, physical route) now.

        Never raises: it runs right after a passed 204 and must never turn
        that verification into a failure.
        """

        try:
            owner = self._core_reload_owner()
            if owner is None:
                return None
            # The route the 204 ran on: the controller view the probe's
            # route-ready wait accepted in this reload (the app's snapshot is
            # still the pre-reload one); the published route only without it.
            physical: tuple[Any, ...] = ()
            view = getattr(self, "_route_ready_view", None)
            if isinstance(view, dict):
                contract = (
                    getattr(self, "_runtime_pending_export_contract", None)
                    or getattr(self, "_runtime_loaded_export_contract", None)
                    or {}
                )
                proxy_map = contract.get("proxy_map") if isinstance(contract, dict) else None
                physical = _route_physical_signature(
                    self._runtime_final_exit_selection_signature(
                        view,
                        proxy_map if isinstance(proxy_map, dict) else {},
                    )
                )
            with self._runtime_route_snapshot_lock:
                if not physical:
                    physical = _route_physical_signature(
                        getattr(self, "_runtime_route_selection_signature", ())
                    )
                return (
                    int(self._runtime_route_epoch),
                    int(self._runtime_network_context_epoch),
                    owner,
                    physical,
                )
        except Exception:
            return None

    def _verified_reload_ready_seen(self) -> tuple[Any, ...] | None:
        """Decision D option A: the READY a strict reload may re-prove.

        Read before the reload starts: ``(ready, publication revision,
        activation generation, Core owner)``, or None when the record is not
        a settled READY, an activation or a controller hold owns readiness,
        or no running Core owner is known.  Never raises: the reload goes on
        without it.
        """

        try:
            with self._tier3_egress_activation_lock:
                ready = self._runtime_egress_readiness
                revision = int(self._runtime_egress_readiness_publication_revision or 0)
                generation = int(getattr(self, "_tier3_egress_activation_generation", -1))
                busy = bool(getattr(self, "_tier3_egress_activation_pending", False)) or bool(
                    getattr(self, "_tier3_egress_activation_worker_running", False)
                )
                hold_kind = str(getattr(self, "_tier3_standby_activation_hold_kind", "") or "")
            if (
                not isinstance(ready, RuntimeEgressReadiness)
                or ready.state is not RuntimeEgressReadinessState.READY
                or ready.validation_active
                or busy
                or hold_kind == "controller_hold"
            ):
                return None
            owner = self._core_reload_owner()
            if owner is None:
                return None
            return (ready, revision, generation, owner)
        except Exception:
            return None

    def _republish_ready_after_verified_reload(self, basis: tuple[Any, ...]) -> str:
        """Decision D option A: READY at the epoch a strict reload's own 204 proved.

        A user graph reload during an automatic route lease bumps the user
        intent, so the READY carry can never re-stamp the old READY; the
        reload's own FINAL-EXIT 204 is proof enough to publish it again,
        with the new intent, the same Core owner and exactly the route and
        network epoch that 204 saw.  No probe, no controller request: only
        the existing publisher, guarded to replace exactly the READY seen
        before the reload.  Runs on the reload thread under the Core lock;
        never raises.
        """

        def attempt() -> tuple[str, int]:
            ready, revision, generation, intent_after, entry_owner = basis
            proof = getattr(self, "_core_reload_final_exit_proof", None)
            self._core_reload_final_exit_proof = None
            if proof is None:
                return "no_proof", 0
            proof_epoch, proof_network, proof_owner, proof_physical = proof
            if self.stop_event.is_set() or not bool(getattr(self, "running", False)):
                return "stopping", 0
            if self._current_core_runtime_phase() != "formal_capture":
                return "phase", 0
            if tuple(proof_owner) != tuple(entry_owner):
                return "owner_changed", 0
            if self._core_reload_owner() != tuple(proof_owner):
                return "core_owner", 0
            if ready.route_owner and tuple(ready.route_owner) != tuple(proof_owner):
                return "ready_owner", 0  # T-P1-10
            if int(ready.network_context_epoch) != int(proof_network):
                return "network", 0
            initial = self._node_judgement_arm_initial_refusal()
            if initial is not None:
                return "initial:" + initial, 0
            if self._core_route_mutation_is_pending():
                return "route_mutation", 0
            if self._runtime_recovery_transaction_active():
                return "recovery", 0
            with self._runtime_route_snapshot_lock:
                fail_closed = getattr(self, "_runtime_confirmed_fail_closed_snapshot_key", None)
            if fail_closed:
                return "fail_closed", 0
            with self._tier3_egress_activation_lock:
                running = bool(getattr(self, "_tier3_egress_activation_worker_running", False))
                hold_kind = str(getattr(self, "_tier3_standby_activation_hold_kind", "") or "")
            if running:
                return "activation", 0
            if hold_kind == "controller_hold":
                return "controller_hold", 0
            # The epoch the 204 saw, or a later one that only the user-intent
            # bump moved: a re-read in between finds the physically same
            # route (same Core owner, same network) and re-signs it with the
            # new intent.  Any physical move refuses.
            with self._runtime_route_snapshot_lock:
                current_epoch = int(self._runtime_route_epoch)
                current_network = int(self._runtime_network_context_epoch)
                current_snapshot = self._runtime_route_snapshot
                current_physical = _route_physical_signature(
                    getattr(self, "_runtime_route_selection_signature", ())
                )
            target_epoch = int(proof_epoch)
            if current_epoch != int(proof_epoch):
                if not (
                    proof_physical
                    and current_physical == tuple(proof_physical)
                    and current_network == int(proof_network)
                    and isinstance(current_snapshot, CoreLoadedRouteSnapshot)
                    and int(current_snapshot.route_epoch) == current_epoch
                    and (
                        int(current_snapshot.process_pid),
                        int(current_snapshot.process_generation),
                        int(current_snapshot.core_generation),
                    )
                    == tuple(proof_owner)
                ):
                    return "route_moved", 0
                target_epoch = current_epoch
            receipt: list[Any] = []
            published = self._publish_runtime_egress_readiness(
                RuntimeEgressReadinessState.READY,
                validation_active=False,
                reason=str(ready.reason or ""),
                expected_publication_revision=int(revision),
                expected_activation_generation=int(generation),
                expected_lifecycle_revision=int(ready.lifecycle_revision),
                expected_selector_intent_revision=int(intent_after),
                require_no_activation_successor=True,
                expected_route_epoch=target_epoch,
                expected_route_owner=tuple(proof_owner),
                expected_network_context_epoch=int(proof_network),
                store_receipt=receipt,
                # The route the 204 ran on, so the reload's own re-read of it
                # is a same-route move for the carry.
                route_physical_override=tuple(proof_physical) if proof_physical else None,
            )
            if not receipt or receipt[0] is not published:
                return "publication_moved", 0
            return "published", target_epoch

        try:
            outcome, epoch = attempt()
        except Exception:
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Runtime READY after a verified Core reload was skipped",
                exc_info=True,
            )
            outcome, epoch = "error", 0
        counts = getattr(self, "_runtime_reload_ready_counts", None)
        if counts is None:
            counts = {}
            self._runtime_reload_ready_counts = counts
        counts[outcome] = int(counts.get(outcome, 0)) + 1
        if outcome == "published":
            log_raw_diagnostic(
                self.logger,
                "info",
                "Runtime READY republished after a verified Core reload (route_epoch=%d)",
                epoch,
            )
        else:
            log_raw_diagnostic(
                self.logger,
                "debug",
                "Runtime READY not republished after a Core reload (reason=%s)",
                outcome,
            )
        return outcome

    def reload_core_config(
        self,
        *,
        mode: str = "strict",
        reason: RuntimeReloadReason | str | None = None,
        user_commit_id: str = "",
        publish_verified_ready: bool = True,
    ) -> dict[str, Any]:
        with self._core_transition_lock:
            normalized_mode = str(mode or "strict").strip().lower()
            if reason is None:
                runtime_logger = getattr(self, "logger", None)
                if runtime_logger is not None:
                    log_raw_diagnostic(
                        runtime_logger,
                        "warning",
                        "Core reload refused: no reload reason was supplied (mode=%s)",
                        normalized_mode,
                    )
                return {
                    "reloaded": False,
                    "mode": normalized_mode,
                    "reload_blocked": True,
                    "reason": "explicit_reload_reason_required",
                }
            normalized_reason = (
                reason
                if isinstance(reason, RuntimeReloadReason)
                else str(reason or "").strip().lower().replace("-", "_")
            )
            if normalized_reason in {
                RuntimeReloadReason.RUNTIME_HEALTH,
                RuntimeReloadReason.RUNTIME_FAILOVER,
                RuntimeReloadReason.RUNTIME_RECHECK,
                RuntimeReloadReason.RUNTIME_FAILBACK,
                RuntimeReloadReason.RUNTIME_FACILITY,
                RuntimeReloadReason.COLD_SAME_DIGEST,
                RuntimeReloadReason.RUNTIME_HEALTH.value,
                RuntimeReloadReason.RUNTIME_FAILOVER.value,
                RuntimeReloadReason.RUNTIME_RECHECK.value,
                RuntimeReloadReason.RUNTIME_FAILBACK.value,
                RuntimeReloadReason.RUNTIME_FACILITY.value,
                RuntimeReloadReason.COLD_SAME_DIGEST.value,
            }:
                return {
                    "reloaded": False,
                    "mode": normalized_mode,
                    "reload_blocked": True,
                    "reason": "runtime_hot_path_reload_forbidden",
                }
            user_graph_reload = normalized_reason in {
                RuntimeReloadReason.USER_GRAPH_CONFIG,
                RuntimeReloadReason.USER_GRAPH_CONFIG.value,
            }
            # Decision D option A: the READY a verified strict reload may
            # publish again (read before anything below can move it).
            ready_seen = (
                self._verified_reload_ready_seen()
                if normalized_mode == "strict"
                and publish_verified_ready
                and self._runtime_uses_early_single_coordinator()
                else None
            )
            with self._runtime_failure_monitor_lock:
                intent_before = int(
                    getattr(self, "_runtime_selector_intent_revision", 0) or 0
                )
                automatic_route_lease = self._runtime_route_mutation_lease
                if isinstance(automatic_route_lease, dict):
                    if not user_graph_reload:
                        return {
                            "reloaded": False,
                            "mode": normalized_mode,
                            "reload_blocked": True,
                            "deferred": True,
                            "reason": "automatic_route_lease_is_active",
                        }
                    # Explicit user graph changes supersede automatic
                    # diversion/failback.  The intent revision invalidates
                    # every in-flight callback before ApplyConfig begins.
                    self._runtime_selector_intent_revision = int(
                        getattr(
                            self,
                            "_runtime_selector_intent_revision",
                            0,
                        )
                        or 0
                    ) + 1
                    self._disarm_runtime_recovery("user graph configuration changed")
                    self._runtime_route_mutation_lease = None
                    self._runtime_origin_diagnostic_bindings.clear()
                    # Route lease: automatic pins keep their TTL (as orphans).
                    self._route_lease_restamp(
                        int(self._runtime_selector_intent_revision)
                    )
                intent_after = int(
                    getattr(self, "_runtime_selector_intent_revision", 0) or 0
                )
            # Only a READY of the intent current before this reload (no
            # declared user selection still waiting), of this lifecycle and
            # proved on this Core (or not anchored yet) is ever re-proved.
            ready_basis: tuple[Any, ...] | None = None
            if ready_seen is not None:
                seen_ready, seen_revision, seen_generation, entry_owner = ready_seen
                if (
                    int(seen_ready.selector_intent_revision) == intent_before
                    and int(seen_ready.lifecycle_revision)
                    == int(getattr(self, "_lifecycle_revision", 0) or 0)
                    and (
                        not seen_ready.route_owner
                        or tuple(seen_ready.route_owner) == tuple(entry_owner)
                    )
                ):
                    ready_basis = (
                        seen_ready,
                        seen_revision,
                        seen_generation,
                        intent_after,
                        entry_owner,
                    )
            runner_known = hasattr(self, "core_runner")
            runner_now = getattr(self, "core_runner", None)
            core_running_now = bool(
                runner_now is not None and runner_now.is_running()
            )
            if normalized_mode == "incremental_export":
                current_marker = self._core_export_sync_marker()
                if (
                    core_running_now
                    and self._last_core_export_sync_marker is not None
                    and current_marker == self._last_core_export_sync_marker
                ):
                    return {
                        "reloaded": True,
                        "mode": normalized_mode,
                        "unchanged": True,
                        "core": (
                            self.core_runner.status()
                            if self.core_runner is not None
                            else {"running": False}
                        ),
                    }
            reload_gate = getattr(self, "_runtime_reload_gate", None)
            reload_gate_lease = None
            if reload_gate is not None:
                try:
                    if runner_known and not core_running_now:
                        # A semantic digest describes one running Core process.
                        # Reusing it after that process exited would let the
                        # same-digest shortcut report success without starting
                        # or applying anything.
                        reload_gate.reset_for_new_core()
                        loaded_digest = ""
                    else:
                        loaded_digest = self._runtime_loaded_semantic_digest()
                    if (
                        core_running_now
                        and loaded_digest
                        and reload_gate.loaded_semantic_digest != loaded_digest
                    ):
                        gate_snapshot = reload_gate.snapshot()
                        if (
                            gate_snapshot.active_recovery_transaction_id
                            or gate_snapshot.active_reload_reason
                        ):
                            return {
                                "reloaded": False,
                                "mode": normalized_mode,
                                "reload_blocked": True,
                                "deferred": True,
                                "reason": "reload_gate_loaded_contract_is_busy",
                            }
                        reload_gate.set_loaded_semantic_digest(loaded_digest)
                    if self._current_core_runtime_phase() == "bootstrap":
                        target_contract = self._bootstrap_source_export_contract_snapshot()
                    else:
                        target_payload = self._render_mihomo_runtime_payload_snapshot()
                        target_contract = self._runtime_export_contract_for_payload(target_payload)
                    target_digest = str(target_contract.get("semantic_digest") or "")
                except Exception:
                    target_digest = self._core_semantic_digest_from_marker(
                        self._core_export_sync_marker()
                    )
                requested_reason = reason
                reload_request = RuntimeReloadRequest(
                    semantic_digest=target_digest,
                    reason=requested_reason,
                    request_id=(
                        str(user_commit_id or "")
                        or f"{normalized_mode}:{target_digest}"
                    ),
                    user_commit_id=str(user_commit_id or ""),
                    wait_if_busy=True,
                    dynamic_update_supported=False,
                )
                decision = reload_gate.request_reload(reload_request)
                if decision.code in {
                    "same_semantic_digest",
                    "user_commit_already_completed",
                }:
                    runner_now = getattr(self, "core_runner", None)
                    if (
                        not runner_known
                        or (runner_now is not None and runner_now.is_running())
                    ):
                        return {
                            "reloaded": True,
                            "mode": normalized_mode,
                            "unchanged": True,
                            "reload_gate": decision.code,
                            "core": (
                                runner_now.status()
                                if runner_now is not None
                                else {"running": False}
                            ),
                        }
                    reload_gate.reset_for_new_core()
                    decision = reload_gate.request_reload(reload_request)
                if not decision.allowed or decision.lease is None:
                    if decision.deferred_token:
                        reload_gate.cancel_deferred_user_commit(
                            decision.deferred_token
                        )
                    return {
                        "reloaded": False,
                        "mode": normalized_mode,
                        "reload_blocked": True,
                        "deferred": decision.should_wait,
                        "reason": decision.code,
                    }
                reload_gate_lease = decision.lease
            # A formal-capture incremental export may only append unrelated
            # members while the selected, qualified leaf remains byte-for-byte
            # identical.  Defer route invalidation until the serialized reload
            # has captured that evidence; eagerly publishing ``pending`` here
            # made every admission burst revoke a healthy source/egress route.
            if normalized_mode != "incremental_export":
                self._begin_core_route_mutation(
                    "Mihomo configuration mutation; FINAL-EXIT 204 verification is pending"
                )
            # A proof, and the view it reads, are valid for this reload only.
            self._core_reload_final_exit_proof = None
            self._route_ready_view = None
            try:
                result = self._reload_core_config_serialized(
                    mode=mode,
                    ready_basis=ready_basis,
                )
            except Exception:
                if reload_gate is not None and reload_gate_lease is not None:
                    reload_gate.cancel_reload(reload_gate_lease)
                self._settle_failed_core_route_mutation(
                    "Mihomo configuration mutation failed before apply"
                )
                raise
            if reload_gate is not None and reload_gate_lease is not None:
                gate_settled = reload_gate.complete_reload(
                    reload_gate_lease,
                    applied=reload_core_config_succeeded(result),
                )
                if not gate_settled:
                    result = dict(result)
                    result["reload_gate_commit_lost"] = True
                    result["authority_unknown"] = True
                    result["reason"] = (
                        "Core apply completed but reload-gate authority could "
                        "not be settled"
                    )
                    self._record_runtime_facility_degradation(
                        str(result["reason"])
                    )
            if not reload_core_config_succeeded(result):
                if result.get("kept_existing_core"):
                    restore_reload = result.get("restore_reload")
                    rollback_confirmable = bool(
                        result.get("restored_config")
                        and result.get("restored_provider", True)
                        and isinstance(restore_reload, dict)
                        and restore_reload.get("reloaded")
                    )
                    if not rollback_confirmable:
                        return self._fail_closed_after_core_export_removal_failure(
                            runner=self._get_core_runner(),
                            reason=(
                                str(result.get("reason") or "core reload failed")
                                + "; rollback could not be confirmed"
                            ),
                        )
                if self._core_route_mutation_is_pending():
                    self._settle_failed_core_route_mutation(
                        str(result.get("reason") or "Mihomo configuration mutation failed")
                    )
            return result

    def _reload_core_config_serialized(
        self,
        *,
        mode: str = "strict",
        ready_basis: tuple[Any, ...] | None = None,
    ) -> dict[str, Any]:
        """Regenerate the runtime config file and ask mihomo to hot-reload.

        Falls back to ``restart_core`` if the core is not running, the
        external controller is disabled, or the PUT /configs call fails.
        Used after node/subscription changes so selection of active proxies
        stays continuous.
        """
        reload_mode = str(mode or "strict").strip().lower()
        if reload_mode not in {"strict", "incremental_export"}:
            raise ValueError(f"Unsupported core reload mode: {mode}")
        if self.stop_event.is_set():
            raise RuntimeError("runtime is stopping")
        if not self.manager:
            raise RuntimeError("manager service is not running")
        runner = self._get_core_runner()

        def report_applied(payload: dict[str, Any]) -> dict[str, Any]:
            log_event(
                self.logger,
                "INFO",
                "configuration.applied",
                f"Mihomo runtime configuration applied ({reload_mode})",
                params={"scope_name": reload_mode},
            )
            return payload

        if not runner.is_running():
            return report_applied(self.restart_core())
        reload_context = self._capture_core_reload_context()
        controller = reload_context.controller
        runtime_phase = self._current_core_runtime_phase()

        if runtime_phase in {"bootstrap", "formal_no_capture"}:
            capture_wanted = self._runtime_traffic_capture_wanted()
            current_export_marker = self._core_export_sync_marker()
            selected_leaf_before = (
                self._tier3_selected_leaf_qualification_evidence()
                if runtime_phase == "formal_no_capture"
                and reload_mode == "incremental_export"
                else None
            )
            if (
                reload_mode == "incremental_export"
                and (capture_wanted or selected_leaf_before is None)
            ):
                self._begin_core_route_mutation(
                    "Mihomo no-capture configuration mutation; "
                    "FINAL-EXIT 204 verification is pending"
                )
            if (
                runtime_phase == "bootstrap"
                and self.manager is not None
                and self._fail_terminal_tier3_bootstrap(self.manager)
            ):
                return build_tier3_core_reload_failure_result(
                    reason=(
                        self._last_tier3_startup_error
                        or "Bastion Layer startup source supply is exhausted"
                    ),
                    stop_sensitive=False,
                )
            if not mihomo_controller_enabled(controller):
                return build_tier3_core_reload_failure_result(
                    reason=(
                        "controller disabled; refusing to restart a no-capture "
                        "standby with capture enabled"
                    ),
                    stop_sensitive=False,
                )
            # T-P2-RT3 (Fallback 10-07): the mode this reload renders.
            loaded_network_mode = str(getattr(self, "network_mode", "") or "").strip().lower()
            try:
                if runtime_phase == "bootstrap":
                    runtime_config_path = self.write_mihomo_bootstrap_runtime_config()
                    self._ensure_bootstrap_prerequisites(
                        runtime_config_path,
                        bootstrap_outbound_available=(
                            self._bootstrap_config_has_outbound(
                                runtime_config_path
                            )
                        ),
                    )
                else:
                    runtime_config_path = self.write_mihomo_no_capture_runtime_config()
                    self._ensure_geodata_ready_for_core_start(runtime_config_path)
                standby_reload = runner.hot_reload(
                    **hot_reload_kwargs_from_controller(controller)
                )
            except Exception as exc:
                self._restore_previous_provider_config(reload_context)
                self._restore_previous_runtime_config(
                    reload_context.runtime_config_path,
                    reload_context.previous_config_text,
                )
                return build_tier3_core_reload_failure_result(
                    reason=f"no-capture standby reload failed: {exc}",
                    stop_sensitive=False,
                )
            if not standby_reload.get("reloaded"):
                self._restore_previous_provider_config(reload_context)
                self._restore_previous_runtime_config(
                    reload_context.runtime_config_path,
                    reload_context.previous_config_text,
                )
                return build_tier3_core_reload_failure_result(
                    reason=(
                        "no-capture standby reload failed: "
                        f"{standby_reload.get('reason')}"
                    ),
                    stop_sensitive=False,
                    reload_result=standby_reload,
                )
            self._record_reloaded_network_mode(loaded_network_mode)
            self._mark_loaded_runtime_export_contract()
            self._mark_runtime_source_transport_loaded()
            selected_leaf_after = (
                self._tier3_preserved_leaf_qualification_evidence(
                    selected_leaf_before
                )
                if selected_leaf_before is not None
                else None
            )
            preserve_final_exit = bool(
                selected_leaf_before is not None
                and selected_leaf_after == selected_leaf_before
                and self._runtime_initial_activation_was_completed()
            )
            if (
                runtime_phase == "formal_no_capture"
                and reload_mode == "incremental_export"
            ):
                self._advance_tier3_runtime_config_generation(
                    current_export_marker,
                    preserve_final_exit=preserve_final_exit,
                )
            pending_reason = (
                "Mihomo no-capture standby changed; "
                "FINAL-EXIT 204 verification is pending"
            )
            if runtime_phase == "formal_no_capture":
                if preserve_final_exit and not capture_wanted:
                    self._record_tier3_core_sync_event("append_only")
                    self._set_effective_egress_state(True, "")
                else:
                    self._record_tier3_core_sync_event(
                        "selected_leaf_change"
                        if selected_leaf_before is not None
                        else "semantic_change"
                    )
                    if not self._core_route_mutation_is_pending():
                        self._begin_core_route_mutation(pending_reason)
                    else:
                        self._invalidate_exit_route_context()
                    self._queue_tier3_egress_activation()
            else:
                self._invalidate_exit_route_context()
                self._set_effective_egress_state(False, pending_reason)
            return report_applied(
                {
                    "reloaded": True,
                    "mode": reload_mode,
                    "capture_enabled": False,
                    "egress_available": bool(
                        preserve_final_exit and not capture_wanted
                    ),
                    "core": runner.status(),
                }
            )

        unsafe_export_removal = False
        # T-P2-RT3 fix 1: [(mode this call recorded last, value before this
        # call's first record)]; keep_existing undoes it once the previous
        # runtime config has been reloaded into the Core.
        recorded_network_mode: list[tuple[str, str | None]] = []

        def record_loaded_network_mode(mode: Any) -> None:
            if not isinstance(mode, str):
                return
            written, replaced = self._record_reloaded_network_mode(mode)
            if written:
                before = recorded_network_mode[0][1] if recorded_network_mode else replaced
                recorded_network_mode[:] = [(mode, before)]

        def record_stage_reload(stage_result: Any) -> None:
            # Pruned / repair re-render: the helper tags the runner result it
            # got from a successful hot reload with the mode it rendered.
            for candidate in (
                stage_result,
                stage_result.get("reload") if isinstance(stage_result, dict) else None,
            ):
                if isinstance(candidate, dict) and candidate.get("reloaded"):
                    record_loaded_network_mode(candidate.get("_loaded_network_mode"))
                    return

        def revert_recorded_network_mode(result: Any) -> None:
            restore_reload = (
                result.get("restore_reload") if isinstance(result, dict) else None
            )
            if (
                recorded_network_mode
                and isinstance(restore_reload, dict)
                and restore_reload.get("reloaded")
            ):
                expected, previous = recorded_network_mode[0]
                self._revert_reloaded_network_mode(
                    expected=expected,
                    previous=previous,
                )

        def keep_existing(reason: str) -> dict[str, Any]:
            log_event(
                self.logger,
                "ERROR",
                "configuration.failed",
                f"Mihomo runtime configuration was not applied ({reload_mode}): {reason}",
                params={"scope_name": reload_mode, "reason": reason},
            )
            if unsafe_export_removal:
                return self._fail_closed_after_core_export_removal_failure(
                    runner=runner,
                    reason=reason,
                )
            if reload_mode == "incremental_export":
                result = self._keep_existing_core_after_incremental_export_failure(
                    runner=runner,
                    reload_context=reload_context,
                    reason=reason,
                )
            else:
                result = self._keep_existing_core_reload_context(
                    runner=runner,
                    reload_context=reload_context,
                    reason=reason,
                )
            revert_recorded_network_mode(result)
            return result

        if (
            reload_mode != "incremental_export"
            and should_prime_tier3_pool_before_hot_reload(
                reload_context.current_tier3_nodes
            )
        ):
            self._prime_tier3_pool_before_core_start()
        if self.stop_event.is_set():
            return self._core_reload_unavailable(runner, "runtime stopping")
        if not self.manager:
            return self._core_reload_unavailable(runner, "manager service is not running")
        marker = self._tier3_core_sync_marker()
        empty_required_export = should_keep_existing_core_for_empty_tier3_marker(
            marker=marker,
            keep_existing_for_empty_export=self._should_keep_existing_core_for_empty_tier3_export(),
        )
        current_export_marker = self._core_export_sync_marker()
        unsafe_export_removal = bool(
            empty_required_export
            or self._core_export_removes_loaded_proxy(current_export_marker)
            or self._tier3_export_removes_last_synced_proxy()
        )
        capture_was_active = bool(
            reload_mode == "incremental_export"
            and self._current_core_runtime_phase() == "formal_capture"
            and self._revalidation_capture_active("formal_capture")
        )
        selected_leaf_before = (
            self._tier3_selected_leaf_qualification_evidence()
            if capture_was_active
            else None
        )
        if reload_mode == "incremental_export" and selected_leaf_before is None:
            self._begin_core_route_mutation(
                "Mihomo configuration mutation; FINAL-EXIT 204 verification is pending"
            )
        # T-P2-RT3 (Fallback 10-07): the mode this reload renders.
        loaded_network_mode = str(getattr(self, "network_mode", "") or "").strip().lower()
        try:
            runtime_config_path = self.write_mihomo_runtime_config()
        except Exception as exc:
            if unsafe_export_removal:
                return keep_existing(f"runtime config write failed: {exc}")
            raise
        if not mihomo_controller_enabled(controller):
            self.logger.info("Controller disabled; falling back to full restart for reload")
            return report_applied(self.restart_core())
        result = runner.hot_reload(**hot_reload_kwargs_from_controller(controller))
        if not result.get("reloaded"):
            if self.stop_event.is_set():
                return self._core_reload_unavailable(runner, "runtime stopping")
            return keep_existing(f"hot reload failed: {result.get('reason')}")
        record_loaded_network_mode(loaded_network_mode)
        self._mark_runtime_source_transport_loaded()
        selected_leaf_after = (
            self._tier3_selected_leaf_qualification_evidence()
            if capture_was_active and selected_leaf_before is not None
            else None
        )
        if (
            selected_leaf_before is not None
            and selected_leaf_after != selected_leaf_before
        ):
            selected_leaf_after = self._tier3_preserved_leaf_qualification_evidence(
                selected_leaf_before
            )
        preserve_final_exit = bool(
            selected_leaf_before is not None
            and selected_leaf_after == selected_leaf_before
            and self._runtime_initial_activation_was_completed()
        )
        if reload_mode == "incremental_export":
            self._advance_tier3_runtime_config_generation(
                current_export_marker,
                preserve_final_exit=preserve_final_exit,
            )
        if preserve_final_exit:
            self._record_tier3_core_sync_event("append_only")
            self._set_effective_egress_state(True, "")
        else:
            self._record_tier3_core_sync_event(
                "selected_leaf_change"
                if selected_leaf_before is not None
                else "semantic_change"
            )
            pending_reason = (
                "Mihomo configuration reloaded; FINAL-EXIT 204 verification is pending"
            )
            if (
                reload_mode == "incremental_export"
                and not self._core_route_mutation_is_pending()
            ):
                self._begin_core_route_mutation(pending_reason)
            else:
                self._invalidate_exit_route_context()
            if capture_was_active:
                self._rollback_to_formal_no_capture(runner, pending_reason)
                manager = self.manager
                capture_marker = getattr(
                    manager,
                    "mark_tier3_traffic_capture_active",
                    None,
                ) if manager is not None else None
                if callable(capture_marker):
                    capture_marker(False)
                if not runner.is_running():
                    self._set_effective_egress_state(
                        False,
                        "Mihomo stopped while revoking stale traffic capture",
                    )
                    return self._core_reload_unavailable(
                        runner,
                        "Mihomo stopped while revoking stale traffic capture",
                    )
            self._set_effective_egress_state(None, pending_reason)
        if reload_mode == "incremental_export" or empty_required_export:
            # Incremental pool growth only refreshes the runtime export. Core repair,
            # group-wide delay probes and strict final-egress verification are
            # inventory/runtime-maintenance work and must not sit on the admission
            # side-effect path.
            self._last_synced_tier3_nodes = self._clone_runtime_nodes(
                self._tier3_nodes_for_core_export(
                    self._mihomo_tier3_export_limit()
                )
            )
            self._mark_tier3_export_sync_complete()
            if preserve_final_exit:
                self.logger.info(
                    "Bastion Layer append-only runtime sync preserved the "
                    "qualified FINAL-EXIT leaf; revalidation skipped"
                )
            else:
                self._queue_incremental_egress_recheck()
            return report_applied({
                "reloaded": True,
                "mode": reload_mode,
                "fail_closed": bool(empty_required_export),
                "egress_available": not empty_required_export,
                "core": runner.status(),
            })
        pending_tier3_repair_plan: _Tier3CoreRepairPlan | None = None
        if self._tier3_is_primary_export():
            primary_reload = self._reload_pruned_primary_tier3_export(runner, controller)
            record_stage_reload(primary_reload)
            if not primary_reload.get("reloaded"):
                return self._stop_sensitive_reload_failure_response(
                    runner=runner,
                    reload_result=primary_reload,
                    keep_existing=keep_existing,
                )
            candidate_plan = primary_reload.get("_tier3_core_repair_plan")
            if isinstance(candidate_plan, _Tier3CoreRepairPlan):
                pending_tier3_repair_plan = candidate_plan
        try:
            self._verify_tier3_after_core_reload(save_snapshot=pending_tier3_repair_plan is None)
        except Exception:
            if pending_tier3_repair_plan is not None:
                self._clear_tier3_core_export_override()
            repair_reload = self._repair_and_retry_tier3_reload_after_verification_failure(runner, controller)
            record_stage_reload(repair_reload)
            if not repair_reload.get("reloaded"):
                return self._stop_sensitive_reload_failure_response(
                    runner=runner,
                    reload_result=repair_reload,
                    keep_existing=keep_existing,
                )
        if pending_tier3_repair_plan is not None:
            self._commit_tier3_core_repair_plan(pending_tier3_repair_plan, save_snapshot=True)
        if ready_basis is not None:
            # Decision D option A.  Only this tail follows a passed 204,
            # directly or through the repair retry; it runs before the new
            # loaded contract is committed and the reload's readback queued.
            self._republish_ready_after_verified_reload(ready_basis)
        self._mark_tier3_core_sync_success()
        return report_applied({"reloaded": True, "core": runner.status()})

    def set_network_mode(self, mode: str) -> dict[str, Any]:
        """Switch between system_proxy / tun / mixed. Always triggers a full restart.

        Persists the new value into config.local.yaml so it survives restarts.
        TUN/mixed modes warn if the process is not elevated.

        ``core_generation_before`` / ``core_generation_after`` (T-P2-RT2, added
        fields only) are the Core generations sampled at entry and at return;
        a caller treats ``after != before + 1`` after a restart as "restart
        not attributable to this call".
        """
        def core_generation() -> int:
            lock = getattr(self, "_core_lifecycle_lock", None)
            with lock if lock is not None else nullcontext():
                return int(getattr(self, "_core_generation", 0) or 0)

        generation_before = core_generation()
        normalized = _normalize_network_mode(mode)
        if normalized == self.network_mode:
            return {"mode": normalized, "changed": False,
                    "core_generation_before": generation_before,
                    "core_generation_after": core_generation()}
        if normalized in {"tun", "mixed"} and not self._process_is_admin():
            raise PermissionError(
                "TUN mode requires running Tesseract as Administrator (WinTun driver)"
            )
        def apply_mode(local: dict[str, Any]) -> dict[str, Any]:
            client_block = ensure_mapping_section(local, "client")
            client_block["network_mode"] = normalized
            return local

        self.update_local_config(apply_mode)
        # update_local_config -> reload_config already updates self.network_mode.
        core_running = bool(self.core_runner and self.core_runner.is_running())
        if core_running:
            self.restart_core()
        return {"mode": normalized, "changed": True, "restarted": core_running,
                "core_generation_before": generation_before,
                "core_generation_after": core_generation()}

    @staticmethod
    def _process_is_admin() -> bool:
        try:
            import ctypes

            return bool(ctypes.windll.shell32.IsUserAnAdmin())  # type: ignore[attr-defined]
        except Exception:
            return False

    def _core_program_path_for_killswitch(self) -> str | None:
        """Return the absolute mihomo binary path only when TUN is active.

        In TUN/mixed mode the kill switch must allowlist the mihomo process
        itself, because that is the source of all outbound traffic when TUN
        routes user traffic through the virtual adapter. In pure system_proxy
        mode we keep the legacy tier1-IP-only allowlist.
        """
        if self.network_mode not in {"tun", "mixed"}:
            return None
        resolved = self._resolve_path(mihomo_client_paths(self._client_config()).binary_path)
        return str(resolved) if resolved.exists() else None

    def enable_system_proxy(self) -> dict[str, Any]:
        return self.system_proxy.enable_transaction(self.runtime_state)

    def apply_system_proxy_override(self) -> dict[str, Any]:
        """Apply the saved bypass list to a live Tesseract system proxy capture.

        Call after the list has been persisted and reloaded.  Only
        ProxyOverride is rewritten, and only while Windows still points at our
        own target; the server is never re-captured.  The list is not part of
        the Mihomo config, so Core is not reloaded.
        """
        with self._config_change_lock:
            try:
                return self.system_proxy.apply_proxy_override()
            except Exception as exc:
                log_raw_diagnostic(
                    self.logger,
                    "warning",
                    "System proxy bypass list could not be applied: %s",
                    str(exc),
                    exc_info=True,
                )
                return {"applied": False, "reason": "write_failed"}

    def disable_system_proxy(self) -> dict[str, Any]:
        return self.system_proxy.restore_transaction(self.runtime_state)

    def restore_system_proxy(self) -> dict[str, Any]:
        try:
            return self.system_proxy.restore()
        finally:
            if not self.system_proxy.get_state().get("restorable"):
                self.runtime_state.clear()

    def check_proxy_port(self) -> bool:
        proxy_config = self._system_proxy_config()
        host = str(proxy_config.get("host", "127.0.0.1"))
        port = self._client_mixed_port()
        if not self.core_runner:
            return False
        return self.core_runner.check_proxy_port(host=host, port=port)

    def trigger_tier3_discover(self) -> dict[str, Any]:
        if not self.manager:
            raise RuntimeError("manager service is not running")
        return self.manager.trigger_tier3_collect()

    def trigger_tier3_prune(self) -> dict[str, Any]:
        if not self.manager:
            raise RuntimeError("manager service is not running")
        return self.manager.trigger_tier3_prune()

    def reload_config(self, *, target_tier: str | None = None) -> dict[str, Any]:
        self._clear_runtime_audit_export_overlay()
        bootstrap_user_files(self.app_paths)
        self.config = self._disable_external_desktop_notifications(
            apply_release_path_overrides(
                load_config(str(self.app_paths.config_path), local_path=str(self.app_paths.local_config_path)),
                self.app_paths,
            )
        )
        latched = getattr(self, "_tier3_verified_provider_writes_latched", None)
        if latched is not None and bool(latched) != self._tier3_verified_provider_writes_configured():
            # Bastion naming and the provider lane are latched per runtime start.
            self.logger.info(
                "tiers.tier3.verified_provider_writes changed; it applies at the next runtime start"
            )
        self.alerts_config = alerts_block(self.config)
        self.alerts.config = self.alerts_config
        self.alerts.set_language(self._configured_ui_language())
        client_config = self._client_config()
        self._sync_system_proxy_config(client_config)
        self.network_mode = _normalize_network_mode(
            client_config.get("network_mode", "system_proxy")
        )
        self.api_client = self._build_api_client()
        core_running = bool(self.core_runner and self.core_runner.is_running())
        self.traffic_monitor.stop()
        self.traffic_monitor = self._build_traffic_monitor()
        runtime_phase = self._current_core_runtime_phase()
        capture_wanted = self._runtime_traffic_capture_wanted()
        verified_capture_ready = bool(
            self._runtime_initial_activation_complete()
            and runtime_phase in {"formal_no_capture", "formal_capture"}
            and (
                not capture_wanted
                or (
                    runtime_phase == "formal_capture"
                    and self._revalidation_capture_active(runtime_phase)
                )
            )
        )
        with self._runtime_intent_lock:
            if (
                core_running
                and verified_capture_ready
                and not self.stop_event.is_set()
            ):
                self.traffic_monitor.start()
        self.geo_updater.reconfigure(
            geo_update_block(self.config),
            egress_proxy=self._remote_refresh_egress_proxy_config() or {},
        )
        if self.manager:
            self._reconfigure_manager_after_config_reload(target_tier=target_tier)
        self._sync_subscription_server_config()
        result = self.status()
        log_event(
            self.logger,
            "INFO",
            "configuration.applied",
            "Tesseract configuration reloaded",
            params={"scope_name": target_tier or "application"},
        )
        return result

    def _reconfigure_manager_after_config_reload(self, *, target_tier: str | None = None) -> None:
        if not self.manager:
            return
        if self.kill_switch:
            self.kill_switch.reconfigure(
                killswitch_block(self.config),
                self._tier_nodes_config("tier1"),
                core_program_path=self._core_program_path_for_killswitch(),
            )
            self._warn_if_killswitch_unavailable()
        with self.manager.operation_lock:
            with self.manager.lock:
                self.manager.config = self.config
                self.manager.client_config = dict(self._client_config())
                self.manager.paths = paths_block(self.config)
                self.manager.sources_file = self.manager.paths.get("sources_file", "sources.yaml")
                self.manager.tier3_nodes_file = self.manager.paths.get("tier3_nodes_file", "data/nodes.json")
                self.manager.tier2_cache_file = (
                    self._tier_config("tier2").get("cache_file")
                    or self.manager.paths.get("tier2_cache_file", "data/tier2_cache.json")
                )
                self.manager.exit_cache_file = (
                    self._tier_config("exit").get("cache_file")
                    or self.manager.paths.get("exit_cache_file", "data/exit_cache.json")
                )
                self.manager.tier_observation_cache_file = self.manager.paths.get("tier_observation_cache_file", "data/tier_observation_cache.json")
                self.manager.observation_cache = self.manager._build_observation_cache()
                self.manager.testing_config = dict(self._testing_block())
                self.manager.validation_mode = str(self.manager.testing_config.get("validation_mode", "optional")).lower()
                self.manager.tier3_controller.config = self.manager._tier3_controller_config()
                reloader = getattr(self.manager, "reload_tier_state", None)
                tier = str(target_tier or "").strip()
                if tier and callable(reloader):
                    reloader(tier)
                else:
                    self.manager._load_initial_state()

    def _client_mixed_port(self, client_config: dict[str, Any] | None = None) -> int:
        client = client_config if isinstance(client_config, dict) else self._client_config()
        return client_mixed_port(client)

    @staticmethod
    def _runtime_listener_endpoint(
        value: object,
        *,
        default_host: str,
        default_port: int,
    ) -> tuple[str, int]:
        text = str(value or "").strip()
        host = str(default_host or "127.0.0.1").strip() or "127.0.0.1"
        port = int(default_port)
        if not text:
            return host, port
        if text.startswith("[") and "]" in text:
            closing = text.find("]")
            host = text[1:closing].strip() or host
            suffix = text[closing + 1 :].strip()
            raw_port = suffix[1:] if suffix.startswith(":") else ""
        elif text.count(":") == 1:
            raw_host, raw_port = text.rsplit(":", 1)
            host = raw_host.strip() or host
        else:
            try:
                ipaddress.ip_address(text)
            except ValueError:
                raw_port = ""
                host = text
            else:
                raw_port = ""
                host = text
        if raw_port:
            try:
                candidate = int(raw_port)
            except (TypeError, ValueError):
                candidate = port
            if 1 <= candidate <= 65535:
                port = candidate
        return host, port

    def _required_runtime_listener_kinds(
        self,
        client_config: dict[str, Any] | None = None,
    ) -> frozenset[RuntimeListenerKind]:
        """Return listeners whose bind failure prevents this mode from serving."""

        client = (
            client_config
            if isinstance(client_config, dict)
            else self._client_config()
        )
        required = {RuntimeListenerKind.MIXED}
        if mihomo_controller_enabled(self._mihomo_controller_config()):
            required.add(RuntimeListenerKind.CONTROLLER)
        network_mode = _normalize_network_mode(
            client.get(
                "network_mode",
                getattr(self, "network_mode", "system_proxy"),
            )
        )
        dns = client_dns_block(client)
        if (
            network_mode in {"tun", "mixed"}
            and coerce_bool(dns.get("enable"), True)
        ):
            required.add(RuntimeListenerKind.DNS)
        return frozenset(required)

    def _runtime_listener_preflight_specs(
        self,
    ) -> tuple[RuntimeListenerSpec, ...]:
        client = self._client_config()
        required_kinds = self._required_runtime_listener_kinds(client)
        specs: list[RuntimeListenerSpec] = [
            RuntimeListenerSpec(
                kind="mixed",
                transport="tcp",
                host=self._core_proxy_host(),
                port=self._client_mixed_port(client),
            )
        ]
        controller = self._mihomo_controller_config()
        if RuntimeListenerKind.CONTROLLER in required_kinds:
            controller_url = urlsplit(
                build_mihomo_controller_base_url(controller)
            )
            specs.append(
                RuntimeListenerSpec(
                    kind="controller",
                    transport="tcp",
                    host=str(controller_url.hostname or "127.0.0.1"),
                    port=int(controller_url.port or 9090),
                )
            )
        dns = client_dns_block(client)
        if RuntimeListenerKind.DNS in required_kinds:
            dns_host, dns_port = self._runtime_listener_endpoint(
                dns.get("listen"),
                default_host="127.0.0.1",
                default_port=1053,
            )
            specs.extend(
                (
                    RuntimeListenerSpec("dns", "tcp", dns_host, dns_port),
                    RuntimeListenerSpec("dns", "udp", dns_host, dns_port),
                )
            )
        return tuple(specs)

    @staticmethod
    def _runtime_listener_failure_codes(
        result: RuntimeListenerPreflightResult,
    ) -> str:
        codes = sorted(
            {
                str(
                    failure.windows_error
                    if failure.windows_error is not None
                    else failure.error_number
                    if failure.error_number is not None
                    else "unknown"
                )
                for failure in result.failures
            }
        )
        return ",".join(codes) or "none"

    def _runtime_listener_preflight_report(
        self,
    ) -> RuntimeListenerPreflightResult:
        return preflight_runtime_listeners(
            self._runtime_listener_preflight_specs()
        )

    def _preflight_runtime_listeners(self) -> RuntimeListenerPreflightResult:
        """Block only a proven listener owner before creating runtime owners."""

        runner = getattr(self, "core_runner", None)
        if runner is not None:
            try:
                if bool(runner.is_running()):
                    # A listener already owned by this lifecycle is not an
                    # external conflict. ``start_core`` will return its state.
                    return RuntimeListenerPreflightResult(
                        state=RuntimeListenerPreflightState.AVAILABLE,
                        specs=(),
                    )
            except Exception:
                pass
        result = self._runtime_listener_preflight_report()
        log_raw_diagnostic(
            self.logger,
            "info" if result.state is RuntimeListenerPreflightState.AVAILABLE else "warning",
            "Runtime listener preflight completed "
            "(state=%s specs=%s attempts=%s snapshot=%s failures=%s)",
            result.state.value,
            len(result.specs),
            result.attempts,
            result.endpoint_snapshot_available,
            self._runtime_listener_failure_codes(result),
        )
        if result.state is RuntimeListenerPreflightState.OCCUPIED:
            conflicts = tuple(
                (
                    spec.kind,
                    spec.transport,
                    spec.host,
                    int(spec.port),
                )
                for spec in result.conflicts
            )
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Runtime listener preflight found occupied endpoints: %s",
                ", ".join(
                    f"{kind}/{transport}@{host}:{port}"
                    for kind, transport, host, port in conflicts
                ),
            )
            raise RuntimeListenerPreflightError(tuple(conflicts))
        if result.state is RuntimeListenerPreflightState.CONFIGURATION_ERROR:
            raise RuntimeListenerSetupError(result)
        # An unconfirmed bind/setup error is not evidence that another proxy
        # owns the endpoint. Let the bundled Core make the authoritative bind;
        # its output is classified separately if it also fails.
        return result

    def _required_runtime_listener_bind_fault(
        self,
        runner: Any,
    ) -> RuntimeListenerFault | None:
        get_logs = getattr(runner, "get_recent_logs", None)
        if not callable(get_logs):
            return None
        try:
            recent = [str(line or "") for line in get_logs(limit=200)]
        except Exception:
            return None
        required_kinds = self._required_runtime_listener_kinds()
        # MihomoCoreRunner retains a bounded history across launches. Only the
        # suffix after the most recent launch belongs to this authoritative
        # bind attempt.
        start_index = 0
        for index, line in enumerate(recent):
            if line.startswith("Started mihomo:"):
                start_index = index + 1
        for line in reversed(recent[start_index:]):
            fault = self._runtime_local_listener_fault_from_core_output(line)
            if fault is not None and fault.kind in required_kinds:
                return fault
        return None

    def _authoritative_runtime_listener_start_error(
        self,
        runner: Any,
    ) -> RuntimeError | None:
        fault = self._required_runtime_listener_bind_fault(runner)
        if fault is None:
            return None
        result = self._runtime_listener_preflight_report()
        log_raw_diagnostic(
            self.logger,
            "warning",
            "Authoritative runtime listener bind failed "
            "(kind=%s state=%s snapshot=%s failures=%s)",
            fault.kind.value,
            result.state.value,
            result.endpoint_snapshot_available,
            self._runtime_listener_failure_codes(result),
        )
        if result.state is RuntimeListenerPreflightState.OCCUPIED:
            conflicts = tuple(
                (
                    spec.kind,
                    spec.transport,
                    spec.host,
                    int(spec.port),
                )
                for spec in result.conflicts
            )
            return RuntimeListenerPreflightError(conflicts)
        return RuntimeListenerSetupError(result, fault_kind=fault.kind.value)

    def _set_core_runtime_phase(self, phase: str) -> None:
        normalized = str(phase or "stopped").strip().lower() or "stopped"
        with self._core_lifecycle_lock:
            self._core_runtime_phase = normalized
            if normalized in {"stopped", "bootstrap"}:
                # T-P2-RT2: no Core (or a new bootstrap Core that has not been
                # promoted yet), no Core-loaded network mode.
                self._core_loaded_network_mode = None
        if normalized in {"formal_capture", "formal_no_capture"}:
            self._queue_runtime_route_snapshot_refresh()
        elif normalized == "stopped":
            with self._runtime_route_snapshot_lock:
                self._runtime_route_snapshot = None
                self._runtime_route_snapshot_payload = None
                self._runtime_core_inventory_snapshot = None
            self._runtime_egress_coordinator.set_current_snapshot(None)
        if normalized in {"stopping", "stopped"}:
            # Node judgement P1-3: the observer's lease ends with this Core
            # (stop and restart both pass through here).  Signal only; the
            # next monitor reset joins the thread.
            self._stop_runtime_post_dial_observer(f"core_{normalized}")

    def _current_core_runtime_phase(self) -> str:
        with self._core_lifecycle_lock:
            return str(getattr(self, "_core_runtime_phase", "stopped") or "stopped")

    def _core_proxy_host(self) -> str:
        host = str(self._system_proxy_config().get("host") or "127.0.0.1").strip()
        return "127.0.0.1" if host in {"", "0.0.0.0", "::"} else host

    def _core_mixed_port_is_ready(self, runner: Any) -> bool:
        try:
            if not runner.is_running():
                return False
        except Exception:
            return False
        checker = getattr(runner, "check_proxy_port", None)
        if callable(checker):
            try:
                return bool(
                    checker(
                        host=self._core_proxy_host(),
                        port=self._client_mixed_port(),
                    )
                )
            except TypeError:
                try:
                    return bool(checker())
                except Exception:
                    return False
            except Exception:
                return False
        try:
            status = runner.status()
        except Exception:
            return False
        return bool(
            isinstance(status, dict)
            and status.get("running")
            and status.get("proxy_ready", True)
        )

    def _wait_for_core_mixed_port_ready(
        self,
        runner: Any,
        *,
        timeout_seconds: float,
    ) -> bool:
        """Bound admission on the formal listener without stopping Core."""

        if self._core_mixed_port_is_ready(runner):
            return True
        wait_for_proxy = getattr(runner, "wait_for_proxy", None)
        if not callable(wait_for_proxy):
            return False
        wait_kwargs: dict[str, Any] = {
            "host": self._core_proxy_host(),
            "port": self._client_mixed_port(),
            "timeout": max(0.05, float(timeout_seconds)),
        }
        try:
            parameters = inspect.signature(wait_for_proxy).parameters.values()
        except (TypeError, ValueError):
            parameters = ()
        if any(
            parameter.kind is inspect.Parameter.VAR_KEYWORD
            or parameter.name == "cancel_event"
            for parameter in parameters
        ):
            wait_kwargs["cancel_event"] = self.stop_event
        try:
            return bool(wait_for_proxy(**wait_kwargs))
        except Exception:
            return False

    def _record_bootstrap_source_proxy_state(
        self,
        status: str,
        reason: str = "",
    ) -> None:
        manager = self.manager
        if manager is None:
            return
        lock = getattr(manager, "lock", None)
        context = lock if hasattr(lock, "__enter__") else nullcontext()
        try:
            with context:
                report = ensure_tier3_collection_report(manager)
                report["runtime_source_bootstrap_status"] = str(status or "")
                report["runtime_source_bootstrap_ready"] = status == "ready"
                if reason:
                    report["runtime_source_bootstrap_reason"] = str(reason)
                else:
                    report.pop("runtime_source_bootstrap_reason", None)
                if status == "prerequisite_missing":
                    report["source_retry_blocked_reason"] = "prerequisite_missing"
                elif report.get("source_retry_blocked_reason") == "prerequisite_missing":
                    report.pop("source_retry_blocked_reason", None)
        except Exception:
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Failed to publish runtime bootstrap source-proxy state",
                exc_info=True,
            )

    def _valid_explicit_collection_proxy(self) -> bool:
        try:
            return bool(
                proxy_url_from_config(
                    egress_proxy_block(self.config),
                    purpose="collection",
                )
            )
        except (TypeError, ValueError):
            return False

    def _ensure_bootstrap_rule_provider_prerequisites(
        self,
        runtime_config_path: Path,
        *,
        bootstrap_outbound_available: bool,
    ) -> None:
        try:
            payload = yaml.safe_load(runtime_config_path.read_text(encoding="utf-8"))
        except Exception as exc:
            raise BootstrapPrerequisiteError(
                f"could not inspect bootstrap rule providers: {exc}"
            ) from exc
        providers = payload.get("rule-providers") if isinstance(payload, dict) else None
        if not isinstance(providers, dict):
            return
        work_dir = self._resolve_path(
            mihomo_client_paths(self._client_config()).work_dir
        )
        missing_remote: list[str] = []
        missing_local: list[str] = []
        for name, raw_provider in providers.items():
            if not isinstance(raw_provider, dict):
                raise BootstrapPrerequisiteError(
                    f"rule-provider {name!s} is not a mapping"
                )
            provider_type = str(raw_provider.get("type") or "").strip().lower()
            raw_path = str(raw_provider.get("path") or "").strip()
            provider_path = Path(raw_path) if raw_path else None
            if provider_path is not None and not provider_path.is_absolute():
                provider_path = work_dir / provider_path
            provider_ready = bool(provider_path and provider_path.is_file())
            if provider_type == "file":
                if not provider_ready:
                    missing_local.append(str(name))
                continue
            if provider_type != "http":
                raise BootstrapPrerequisiteError(
                    f"rule-provider {name!s} has unsupported type {provider_type or 'missing'}"
                )
            provider_proxy = str(raw_provider.get("proxy") or "").strip().upper()
            if provider_proxy in {"DIRECT", "COMPATIBLE"}:
                raise BootstrapPrerequisiteError(
                    f"rule-provider {name!s} is not routed through FINAL-EXIT"
                )
            if not provider_ready:
                missing_remote.append(str(name))
        if missing_local:
            raise BootstrapPrerequisiteError(
                "required local rule-provider assets are missing: "
                + ", ".join(missing_local)
            )
        if missing_remote and not bootstrap_outbound_available:
            raise BootstrapPrerequisiteError(
                "required rule-provider assets are missing before bootstrap; "
                "a healthy proxy or explicit collection egress proxy is required: "
                + ", ".join(missing_remote)
            )

    def _ensure_bootstrap_prerequisites(
        self,
        runtime_config_path: Path,
        *,
        bootstrap_outbound_available: bool,
    ) -> None:
        explicit_proxy_available = self._valid_explicit_collection_proxy()
        if self._runtime_config_uses_geodata(runtime_config_path):
            missing = self._missing_geodata_assets()
            if missing and not explicit_proxy_available:
                raise BootstrapPrerequisiteError(
                    "required GeoData is missing before bootstrap and no explicit "
                    "collection egress proxy is available: " + ", ".join(missing)
                )
        try:
            self._ensure_geodata_ready_for_core_start(runtime_config_path)
        except BootstrapPrerequisiteError:
            raise
        except Exception as exc:
            raise BootstrapPrerequisiteError(str(exc)) from exc
        self._ensure_bootstrap_rule_provider_prerequisites(
            runtime_config_path,
            bootstrap_outbound_available=bootstrap_outbound_available,
        )

    def _bootstrap_config_has_outbound(self, runtime_config_path: Path) -> bool:
        try:
            payload = yaml.safe_load(runtime_config_path.read_text(encoding="utf-8"))
        except Exception:
            return False
        groups = payload.get("proxy-groups") if isinstance(payload, dict) else None
        if not isinstance(groups, list):
            return False
        fallback = next(
            (
                group
                for group in groups
                if isinstance(group, dict)
                and str(group.get("name") or "") == "PROXY-FALLBACK"
            ),
            None,
        )
        candidates = fallback.get("proxies") if isinstance(fallback, dict) else None
        return bool(
            isinstance(candidates, list)
            and any(str(candidate).upper() != "REJECT" for candidate in candidates)
        )

    def _reset_runtime_source_transport(self, *, runtime_generation: int) -> None:
        """Start a fresh private source-transport identity for one runtime run."""

        with self._runtime_source_transport_lock:
            self._runtime_source_transport = None
            self._runtime_source_loaded_transport = None
            self._runtime_source_config_generation = 0
        # A new runtime run re-qualifies resolvers for whatever network it finds.
        self._reset_dns_resolver_runtime_state()
        resume = getattr(self.manager, "resume_tier3_source_supply", None)
        if callable(resume):
            try:
                resume("runtime_start")
            except Exception:
                pass

    def _runtime_source_egress_enabled(self) -> bool:
        try:
            return bool(
                proxy_url_from_config(
                    egress_proxy_block(self.config),
                    purpose="collection",
                )
            )
        except Exception:
            return False

    def _runtime_source_transport_enabled(self) -> bool:
        """Return whether Tier3 has authorised its private source transport."""

        manager = self.manager
        enabled = getattr(manager, "_tier3_enabled", None) if manager else None
        if callable(enabled):
            try:
                return bool(enabled())
            except Exception:
                return False
        return coerce_bool(
            tier_block(self.config, "tier3").get("enabled", False),
            False,
        )

    def _runtime_source_excluded_ports(self) -> set[int]:
        excluded = {int(self._client_mixed_port())}
        controller = self._mihomo_controller_config()
        try:
            controller_port = int(controller.get("port", 9090))
        except (TypeError, ValueError):
            controller_port = 9090
        if 1 <= controller_port <= 65535:
            excluded.add(controller_port)
        try:
            subscription_port = int(
                subscription_server_runtime_config(self.config).port
            )
        except (TypeError, ValueError):
            subscription_port = 0
        if 1 <= subscription_port <= 65535:
            excluded.add(subscription_port)
        return excluded

    @staticmethod
    def _runtime_source_candidate_ports(count: int) -> tuple[int, ...]:
        """Reserve a unique loopback candidate set long enough to choose it safely."""

        sockets: list[socket.socket] = []
        ports: list[int] = []
        try:
            for _index in range(max(1, int(count))):
                listener = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                if hasattr(socket, "SO_EXCLUSIVEADDRUSE"):
                    try:
                        listener.setsockopt(
                            socket.SOL_SOCKET,
                            socket.SO_EXCLUSIVEADDRUSE,
                            1,
                        )
                    except OSError:
                        pass
                listener.bind(("127.0.0.1", 0))
                sockets.append(listener)
                ports.append(int(listener.getsockname()[1]))
            return tuple(ports)
        finally:
            for listener in sockets:
                try:
                    listener.close()
                except OSError:
                    pass

    @staticmethod
    def _runtime_source_listener_ports(
        transport: RuntimeSourceTransportGeneration,
    ) -> RuntimeSourceListenerPorts:
        by_route = {
            listener.route_kind: int(listener.port)
            for listener in transport.listeners
        }
        return RuntimeSourceListenerPorts(
            final_exit=by_route[RuntimeSourceRouteKind.FINAL_EXIT],
            egress=by_route.get(RuntimeSourceRouteKind.EGRESS),
            direct=by_route[RuntimeSourceRouteKind.DIRECT],
        )

    def _runtime_source_transport_for_config(
        self,
        *,
        force_reallocate: bool = False,
    ) -> RuntimeSourceTransportGeneration:
        """Return the private listener set for the next Core config generation.

        Ports and credentials remain stable for the runtime generation.  Only
        the config generation advances across hot reloads.  A first-load bind
        collision may explicitly request a fresh port set, bounded by the
        caller's three-attempt startup loop.
        """

        with self._runtime_source_transport_lock:
            runtime_generation = int(self._runtime_generation)
            existing = self._runtime_source_transport
            include_egress = self._runtime_source_egress_enabled()
            existing_has_egress = bool(
                existing is not None
                and any(
                    listener.route_kind is RuntimeSourceRouteKind.EGRESS
                    for listener in existing.listeners
                )
            )
            preserve_existing = bool(
                existing is not None
                and int(existing.runtime_generation) == runtime_generation
                and existing_has_egress == include_egress
                and not force_reallocate
            )
            credentials: dict[
                RuntimeSourceRouteKind,
                RuntimeSourceListenerCredentials,
            ] = {}
            if existing is not None and int(existing.runtime_generation) == runtime_generation:
                credentials = {
                    listener.route_kind: listener.credentials
                    for listener in existing.listeners
                }
            if preserve_existing:
                ports = self._runtime_source_listener_ports(existing)
            else:
                required_count = 3 if include_egress else 2
                candidate_attempts = (
                    self._runtime_source_candidate_ports(required_count)
                    for _attempt in range(
                        max(
                            1,
                            min(
                                RUNTIME_SOURCE_MAX_ROUTE_ATTEMPTS,
                                int(self._runtime_source_listener_allocation_attempts),
                            ),
                        )
                    )
                )
                ports = choose_runtime_source_listener_ports(
                    candidate_attempts,
                    excluded_ports=self._runtime_source_excluded_ports(),
                    include_egress=include_egress,
                    max_attempts=self._runtime_source_listener_allocation_attempts,
                )
            self._runtime_source_config_generation += 1
            transport = build_runtime_source_transport_generation(
                runtime_generation=runtime_generation,
                config_generation=self._runtime_source_config_generation,
                ports=ports,
                egress_proxy_name=(
                    RUNTIME_SOURCE_EGRESS_PROXY_NAME if include_egress else None
                ),
                credentials=credentials,
            )
            self._runtime_source_transport = transport
            return transport

    def _runtime_source_transport_snapshot(
        self,
    ) -> RuntimeSourceTransportGeneration | None:
        with self._runtime_source_transport_lock:
            return self._runtime_source_transport

    def _runtime_source_loaded_transport_snapshot(
        self,
    ) -> RuntimeSourceTransportGeneration | None:
        """Return the listener generation confirmed loaded by the running Core."""

        with self._runtime_source_transport_lock:
            return self._runtime_source_loaded_transport

    def _mark_runtime_source_transport_loaded(self) -> None:
        """Publish the rendered listener generation after a successful Core load."""

        transport_lock = getattr(self, "_runtime_source_transport_lock", None)
        if transport_lock is None:
            return
        with transport_lock:
            transport = getattr(self, "_runtime_source_transport", None)
            if transport is None:
                return
            changed = transport != getattr(
                self,
                "_runtime_source_loaded_transport",
                None,
            )
            self._runtime_source_loaded_transport = transport
        if not changed:
            return
        manager = getattr(self, "manager", None)
        notify = getattr(
            manager,
            "notify_tier3_source_supply_route_changed",
            None,
        ) if manager is not None else None
        if callable(notify):
            notify("runtime_source_listener_generation_loaded")

    def _runtime_source_listener_bind_conflict(
        self,
        runner: Any,
        error: BaseException,
    ) -> bool:
        """Recognize a first-load bind failure for one of our private ports."""

        if isinstance(error, RuntimeSourceListenerReadinessError):
            return True
        transport = self._runtime_source_transport_snapshot()
        if transport is None:
            return False
        evidence = [str(error or "")]
        try:
            recent = runner.get_recent_logs(limit=80)
        except Exception:
            recent = []
        evidence.extend(str(line or "") for line in recent)
        combined = "\n".join(evidence).lower()
        bind_failure = any(
            marker in combined
            for marker in (
                "address already in use",
                "only one usage of each socket address",
                "bind:",
                "failed to listen",
                "listener create failed",
            )
        )
        if not bind_failure:
            return False
        return any(
            str(listener.port) in combined or listener.name.lower() in combined
            for listener in transport.listeners
        )

    def _runtime_source_listener_requires_auth(
        self,
        endpoint: RuntimeSourceFetchEndpoint,
    ) -> bool:
        """Prove that the bound loopback port is the authenticated Mihomo listener."""

        timeout = max(
            0.05,
            min(1.0, float(self._runtime_source_listener_probe_timeout_seconds)),
        )
        try:
            with socket.create_connection(
                (endpoint.host, int(endpoint.port)),
                timeout=timeout,
            ) as connection:
                connection.settimeout(timeout)
                connection.sendall(
                    b"GET http://127.0.0.1/ HTTP/1.1\r\n"
                    b"Host: 127.0.0.1\r\n"
                    b"Connection: close\r\n\r\n"
                )
                response = connection.recv(256)
        except OSError:
            return False
        status_line = response.split(b"\r\n", 1)[0].strip()
        return bool(status_line.startswith(b"HTTP/") and b" 407 " in status_line)

    def _wait_for_runtime_source_listeners_or_stop(
        self,
        runner: Any,
        *,
        timeout: float,
    ) -> None:
        """Wait until every generation-owned listener proves its auth boundary."""

        if not self._runtime_source_transport_enabled():
            return
        transport = self._runtime_source_transport_snapshot()
        if transport is None:
            raise RuntimeSourceListenerReadinessError(
                "private Tier3 source listeners were not rendered"
            )
        endpoints = transport.fetch_endpoints(
            phase="formal",
            readiness=True,
        )
        deadline = time.monotonic() + max(0.05, float(timeout))
        while True:
            if self.stop_event.is_set():
                raise RuntimeStartCancelled(
                    "runtime stop requested while waiting for private source listeners"
                )
            try:
                core_running = bool(runner.is_running())
            except Exception:
                core_running = False
            if not core_running:
                raise RuntimeSourceListenerReadinessError(
                    "Mihomo stopped before private Tier3 source listeners became ready"
                )
            if all(
                self._runtime_source_listener_requires_auth(endpoint)
                for endpoint in endpoints
            ):
                return
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                raise RuntimeSourceListenerReadinessError(
                    "private Tier3 source listener authentication boundary did not become ready"
                )
            if self.stop_event.wait(min(0.05, remaining)):
                raise RuntimeStartCancelled(
                    "runtime stop requested while waiting for private source listeners"
                )

    def _runtime_source_fetch_endpoints_provider(
        self,
        phase: str,
        last_successful_route: RuntimeSourceRouteKind | str | None = None,
    ) -> tuple[RuntimeSourceFetchEndpoint, ...]:
        """Publish only ready, generation-owned Tier3 source-control lanes."""

        if (
            not self._runtime_source_transport_enabled()
            or self.stop_event.is_set()
            or self._core_route_mutation_is_pending()
        ):
            return ()
        normalized_phase = str(phase or "").strip().lower()
        runtime_phase = self._current_core_runtime_phase()
        if normalized_phase == "bootstrap":
            if runtime_phase != "bootstrap":
                return ()
            endpoint_phase = "bootstrap"
        elif normalized_phase in {"core", "formal"}:
            if runtime_phase not in {"formal_no_capture", "formal_capture"}:
                return ()
            endpoint_phase = "formal"
        else:
            return ()
        runner = self.core_runner
        if runner is None:
            return ()
        try:
            if not runner.is_running():
                return ()
        except Exception:
            return ()
        transport = self._runtime_source_loaded_transport_snapshot()
        if (
            transport is None
            or int(transport.runtime_generation) != int(self._runtime_generation)
        ):
            return ()
        probe_endpoints = transport.fetch_endpoints(
            phase=endpoint_phase,
            readiness=True,
            last_successful_route=last_successful_route,
        )
        listener_ready = {
            endpoint.route_kind: self._runtime_source_listener_requires_auth(endpoint)
            for endpoint in probe_endpoints
        }
        manager = self.manager
        final_exit_ready = self._source_control_final_exit_ready(manager)
        readiness = {
            route: bool(ready)
            and (
                route is not RuntimeSourceRouteKind.FINAL_EXIT
                or final_exit_ready
            )
            for route, ready in listener_ready.items()
        }
        return transport.fetch_endpoints(
            phase=endpoint_phase,
            readiness=readiness,
            last_successful_route=last_successful_route,
        )

    def _notify_tier3_source_control_route_changed(self, reason: str) -> None:
        manager = getattr(self, "manager", None)
        notify = (
            getattr(manager, "notify_tier3_source_supply_route_changed", None)
            if manager is not None
            else None
        )
        if not callable(notify):
            return
        try:
            notify(str(reason or "runtime_source_route_changed"))
        except Exception:
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Could not notify source supply about FINAL-EXIT authority",
                exc_info=True,
            )

    def _publish_verified_runtime_source_proof(
        self, *, expected_route_epoch: int | None = None,
    ) -> bool:
        """Reuse a just-verified FINAL-EXIT transaction, without a second probe."""
        snapshot, payload = self._runtime_route_snapshot_state()
        if (
            not isinstance(snapshot, CoreLoadedRouteSnapshot)
            or not isinstance(payload, dict)
            or (expected_route_epoch is not None and snapshot.route_epoch != expected_route_epoch)
        ):
            return False
        binding = self._runtime_route_binding_for_outbound(snapshot, payload, "FINAL-EXIT")
        if not isinstance(binding, RuntimeRouteBinding):
            return False
        return self._set_tier3_source_control_qualification(snapshot, binding)

    def _probe_runtime_source_pool_once(self) -> None:
        """Verify the private bootstrap pool without opening ordinary routes."""
        transport = self._runtime_source_loaded_transport_snapshot()
        if transport is None or self._current_core_runtime_phase() != "bootstrap":
            raise RuntimeControllerReadbackError("bootstrap source transport is not loaded")
        endpoint = next((item for item in transport.fetch_endpoints(
            phase="bootstrap", readiness=True,
        ) if item.route_kind is RuntimeSourceRouteKind.FINAL_EXIT), None)
        if endpoint is None or not self._runtime_source_listener_requires_auth(endpoint):
            raise RuntimeSourceListenerReadinessError("private bootstrap listener is not ready")
        probe_urls = self._bootstrap_source_probe_urls()
        for probe_url in probe_urls:
            self._register_runtime_internal_probe(probe_url, timeout_seconds=1.5)

        def probe(context: ProbeExecutionContext | None) -> None:
            if (
                self.stop_event.is_set()
                or self._current_core_runtime_phase() != "bootstrap"
                or self._core_route_mutation_is_pending()
                or self._runtime_source_loaded_transport_snapshot() != transport
            ):
                raise RuntimeControllerReadbackError("bootstrap source transport changed")
            deadline = (
                float(context.execution_deadline_monotonic)
                if context is not None and context.execution_deadline_monotonic is not None
                else time.monotonic() + 1.5
            )
            if deadline - time.monotonic() <= .25:
                raise _RuntimeProbeBudgetUnavailable("bootstrap source probe budget unavailable")
            owner = self._prepare_abortable_probe(context)
            failures: list[str] = []
            # One proof, several configured endpoints: a bootstrap node that
            # answers any of them can carry source traffic.  The budget is
            # shared, so a stalled first endpoint leaves the others a chance.
            for index, probe_url in enumerate(probe_urls):
                remaining = deadline - time.monotonic() - .25
                if remaining <= 0.05:
                    break
                urls_left = len(probe_urls) - index
                budget = remaining if urls_left == 1 else max(0.4, min(remaining, remaining / urls_left + .2))
                try:
                    status, body = self._abortable_https_204_via_http_proxy(
                        proxy_host=endpoint.host, proxy_port=endpoint.port,
                        proxy_authorization=endpoint.proxy_authorization,
                        probe_url=probe_url, timeout_seconds=budget,
                        abort_owner=owner,
                    )
                except Exception as exc:
                    failures.append(f"{self._safe_probe_endpoint_label(probe_url)}: {exc}")
                    continue
                if status == 204 and not body:
                    return
                failures.append(f"{self._safe_probe_endpoint_label(probe_url)}: status={status}")
            raise RuntimeError(
                "private bootstrap source probe did not return empty 204 ("
                + "; ".join(failures[:3])
                + ")"
            )

        self._run_brokered_runtime_probe(
            probe, priority=ProbePriority.BACKGROUND,
            queue_timeout_seconds=1.5, socket_start_timeout_seconds=.5,
            execution_deadline_monotonic=time.monotonic() + 1.5,
        )

    def _request_runtime_source_qualification(self, phase: str) -> None:
        """Qualify a changed route only on real source demand, never a timer.

        Failed attempts back off until another source request arrives. An
        unchanged proof needs no external request, regardless of its age.
        """
        requested_phase = str(phase).strip().lower()
        runtime_phase = self._current_core_runtime_phase()
        allowed_phases = (
            {"bootstrap"} if requested_phase == "bootstrap"
            else {"formal_no_capture", "formal_capture"}
        )
        source_outbound = (
            RUNTIME_SOURCE_BOOTSTRAP_POOL_PROXY
            if requested_phase == "bootstrap" else "FINAL-EXIT"
        )
        if (
            requested_phase not in {"bootstrap", "core", "formal"}
            or self.stop_event.is_set()
            or runtime_phase not in allowed_phases
            or self._core_route_mutation_is_pending()
        ):
            return
        worker_token = self._runtime_worker_token()
        snapshot, _ = self._runtime_route_snapshot_state()
        request_key = (
            tuple(worker_token),
            snapshot.snapshot_key if isinstance(snapshot, CoreLoadedRouteSnapshot) else None,
            int(getattr(self, "_runtime_selector_intent_revision", 0)),
            runtime_phase,
        )
        now = time.monotonic()
        with self._runtime_failure_monitor_lock:
            current_worker = getattr(self, "_runtime_source_demand_worker", None)
            if current_worker is not None and current_worker.is_alive():
                return
            state = getattr(self, "_runtime_source_demand_state", {})
            if state.get("key") == request_key and now < state.get("not_before", 0.0):
                return
            attempts = int(state.get("attempts", 0)) if state.get("key") == request_key else 0

            def current() -> bool:
                return bool(
                    not self.stop_event.is_set()
                    and self._runtime_worker_token_is_current(worker_token)
                    and int(getattr(self, "_runtime_selector_intent_revision", 0)) == request_key[2]
                    and self._current_core_runtime_phase() == runtime_phase
                    and not self._core_route_mutation_is_pending()
                )

            def qualify() -> None:
                succeeded = False
                transport_started = False
                transport_failed = False
                outcome = "authority_pending"
                error_type = ""
                try:
                    if not current():
                        return
                    # Every source-demand round is a health sample for the
                    # resolver ladder and the no-egress terminal, in any phase.
                    try:
                        self._observe_source_supply_health()
                    except Exception:
                        log_raw_diagnostic(
                            self.logger, "warning",
                            "Source supply health observation failed", exc_info=True,
                        )
                    if not current():
                        return
                    authority = self._refresh_loaded_runtime_authority(
                        timeout_seconds=0.5, require_managed_final_exit=requested_phase != "bootstrap",
                        worker_token=worker_token,
                    )
                    if authority is None or not current():
                        return
                    before, before_payload, binding = authority
                    if requested_phase == "bootstrap":
                        binding = self._runtime_route_binding_for_outbound(
                            before, before_payload, source_outbound, require_final_exit=False,
                        )
                    if binding is None:
                        return
                    if self._tier3_source_control_qualification_is_current():
                        succeeded = True
                        outcome = "qualified"
                        return
                    transport_started = True
                    if requested_phase == "bootstrap":
                        self._probe_runtime_source_pool_once()
                    else:
                        self._probe_mihomo_mixed_port_once(
                            timeout_seconds=1.5, probe_priority=ProbePriority.BACKGROUND,
                        )
                    transport_started = False
                    outcome = "authority_changed"
                    verified = self._refresh_loaded_runtime_authority(
                        timeout_seconds=0.5, require_managed_final_exit=requested_phase != "bootstrap",
                        worker_token=worker_token,
                    )
                    verified_binding = (
                        self._runtime_route_binding_for_outbound(
                            verified[0], verified[1], source_outbound, require_final_exit=False,
                        )
                        if verified is not None else None
                    ) if requested_phase == "bootstrap" else (verified[2] if verified else None)
                    if (
                        verified is not None and verified_binding is not None
                        and verified[0].snapshot_key == before.snapshot_key
                        and verified_binding.node.key == binding.node.key
                        and current()
                    ):
                        succeeded = self._set_tier3_source_control_qualification(verified[0], verified_binding)
                        if succeeded:
                            outcome = "qualified"
                except _RuntimeProbeBudgetUnavailable:
                    outcome = "probe_budget_pending"
                except Exception as exc:
                    # Source-request uncertainty is not evidence of a bad node.
                    transport_failed = transport_started
                    outcome = "transport_uncertain" if transport_failed else "authority_pending"
                    error_type = type(exc).__name__
                finally:
                    with self._runtime_failure_monitor_lock:
                        if getattr(self, "_runtime_source_demand_worker", None) is threading.current_thread():
                            self._runtime_source_demand_worker = None
                            # A missing/changed controller lease made no failed
                            # source request. Let the next supply revision retry.
                            delay = (2.0 if succeeded else
                                     (5.0, 15.0, 30.0)[min(attempts, 2)]
                                     if transport_failed else 0.25)
                            self._runtime_source_demand_state = {
                                "key": request_key,
                                "attempts": 0 if succeeded else attempts + int(transport_failed),
                                "not_before": time.monotonic() + delay,
                                "outcome": outcome,
                                "error_type": error_type,
                            }
                        self._runtime_failure_recovery_threads.discard(threading.current_thread())

            worker = threading.Thread(target=qualify, name="runtime-source-route-demand", daemon=True)
            self._runtime_source_demand_worker = worker
            self._runtime_failure_recovery_threads.add(worker)
        try:
            worker.start()
        except Exception:
            with self._runtime_failure_monitor_lock:
                if self._runtime_source_demand_worker is worker:
                    self._runtime_source_demand_worker = None
                self._runtime_failure_recovery_threads.discard(worker)
            raise

    def _set_tier3_source_control_qualification(
        self,
        snapshot: CoreLoadedRouteSnapshot,
        binding: RuntimeRouteBinding,
    ) -> bool:
        """Publish a generation-bound proof for private source traffic only."""

        try:
            route_mutation_pending = self._core_route_mutation_is_pending()
        except (AttributeError, TypeError):
            route_mutation_pending = bool(
                getattr(self, "_core_route_mutation_pending", False)
            )
        if (
            not isinstance(snapshot, CoreLoadedRouteSnapshot)
            or not isinstance(binding, RuntimeRouteBinding)
            or not snapshot.owns(binding)
            or route_mutation_pending
            or self.stop_event.is_set()
        ):
            return False
        expected_outbound = (
            RUNTIME_SOURCE_BOOTSTRAP_POOL_PROXY
            if self._current_core_runtime_phase() == "bootstrap" else "FINAL-EXIT"
        )
        if binding.observed_outbound != expected_outbound:
            return False
        current_snapshot, _ = self._runtime_route_snapshot_state()
        if (
            not isinstance(current_snapshot, CoreLoadedRouteSnapshot)
            or current_snapshot.snapshot_key != snapshot.snapshot_key
        ):
            return False
        runner = getattr(self, "core_runner", None)
        try:
            status = runner.status() if runner is not None and runner.is_running() else {}
        except Exception:
            return False
        if (
            int(status.get("pid") or 0) != int(snapshot.process_pid)
            or int(status.get("process_generation") or 0)
            != int(snapshot.process_generation)
        ):
            return False
        core_lock = getattr(self, "_core_lifecycle_lock", None)
        with core_lock if core_lock is not None else nullcontext():
            if int(getattr(self, "_core_generation", -1)) != int(
                snapshot.core_generation
            ):
                return False
            runtime_generation = int(getattr(self, "_runtime_generation", -1))
        qualification = _Tier3SourceControlQualification(
            runtime_generation=runtime_generation,
            snapshot_key=tuple(snapshot.snapshot_key),
            binding_key=tuple(binding.node.key),
            qualified_at_monotonic=time.monotonic(),
            observed_outbound=binding.observed_outbound,
        )
        monitor_lock = getattr(self, "_runtime_failure_monitor_lock", None)
        with monitor_lock if monitor_lock is not None else nullcontext():
            previous = getattr(
                self,
                "_tier3_source_control_qualification",
                None,
            )
            changed = not isinstance(
                previous,
                _Tier3SourceControlQualification,
            ) or (
                previous.runtime_generation != qualification.runtime_generation
                or previous.snapshot_key != qualification.snapshot_key
                or previous.binding_key != qualification.binding_key
                or previous.observed_outbound != qualification.observed_outbound
            )
            self._tier3_source_control_qualification = qualification
            self._source_control_final_exit_was_ready = True
        if changed:
            self._notify_tier3_source_control_route_changed(
                "verified_source_pool_ready"
                if expected_outbound == RUNTIME_SOURCE_BOOTSTRAP_POOL_PROXY
                else "verified_final_exit_ready"
            )
        return True

    def _refresh_tier3_source_control_qualification(self) -> bool:
        snapshot, payload = self._runtime_route_snapshot_state()
        binding = (
            self._runtime_route_binding_for_outbound(
                snapshot,
                payload,
                "FINAL-EXIT",
            )
            if isinstance(snapshot, CoreLoadedRouteSnapshot)
            and isinstance(payload, dict)
            else None
        )
        if not isinstance(binding, RuntimeRouteBinding):
            return False
        return self._set_tier3_source_control_qualification(snapshot, binding)

    def _revoke_tier3_source_control_qualification(self, reason: str) -> None:
        monitor_lock = getattr(self, "_runtime_failure_monitor_lock", None)
        with monitor_lock if monitor_lock is not None else nullcontext():
            had_qualification = isinstance(
                getattr(self, "_tier3_source_control_qualification", None),
                _Tier3SourceControlQualification,
            ) or bool(
                getattr(self, "_source_control_final_exit_was_ready", False)
            )
            self._tier3_source_control_qualification = None
            self._source_control_final_exit_was_ready = False
        if had_qualification:
            self._notify_tier3_source_control_route_changed(reason)

    def _tier3_source_control_qualification_is_current(self) -> bool:
        monitor_lock = getattr(self, "_runtime_failure_monitor_lock", None)
        with monitor_lock if monitor_lock is not None else nullcontext():
            qualification = getattr(
                self,
                "_tier3_source_control_qualification",
                None,
            )
        if not isinstance(qualification, _Tier3SourceControlQualification):
            return False
        try:
            route_mutation_pending = self._core_route_mutation_is_pending()
        except (AttributeError, TypeError):
            route_mutation_pending = bool(
                getattr(self, "_core_route_mutation_pending", False)
            )
        if (
            int(getattr(self, "_runtime_generation", -1))
            != qualification.runtime_generation
            or self.stop_event.is_set()
            or route_mutation_pending
            or self._current_core_runtime_phase()
            not in {"bootstrap", "formal_no_capture", "formal_capture"}
        ):
            return False
        runner = getattr(self, "core_runner", None)
        try:
            if runner is None or not runner.is_running():
                return False
            status = runner.status()
        except Exception:
            return False
        snapshot, payload = self._runtime_route_snapshot_state()
        if not isinstance(snapshot, CoreLoadedRouteSnapshot):
            return False
        expected_outbound = (
            RUNTIME_SOURCE_BOOTSTRAP_POOL_PROXY
            if self._current_core_runtime_phase() == "bootstrap" else "FINAL-EXIT"
        )
        if qualification.observed_outbound != expected_outbound:
            return False
        current_binding = self._runtime_route_binding_for_outbound(
            snapshot, payload, expected_outbound,
            require_final_exit=expected_outbound == "FINAL-EXIT",
        )
        if current_binding is None or current_binding.node.key != qualification.binding_key:
            return False
        return bool(
            tuple(snapshot.snapshot_key) == qualification.snapshot_key
            and int(status.get("pid") or 0) == int(snapshot.process_pid)
            and int(status.get("process_generation") or 0)
            == int(snapshot.process_generation)
        )

    def _source_control_final_exit_ready(self, manager: Any | None) -> bool:
        """Return whether private source traffic has current FINAL-EXIT proof."""

        return bool(
            manager is not None
            and self._tier3_source_control_qualification_is_current()
        )

    def _runtime_source_fetch_proxy_provider(self, phase: str) -> str | None:
        if self.stop_event.is_set():
            return None
        normalized_phase = str(phase or "").strip().lower()
        if normalized_phase == "bootstrap":
            return self._ensure_bootstrap_core_proxy()
        if normalized_phase != "core":
            return None
        runner = self.core_runner
        manager = self.manager
        with self._core_lifecycle_lock:
            route_mutation_pending = bool(self._core_route_mutation_pending)
        if (
            runner is None
            or manager is None
            or route_mutation_pending
            or self._current_core_runtime_phase() != "formal_capture"
            or not self._core_mixed_port_is_ready(runner)
            or getattr(manager, "effective_egress_ok", None) is not True
        ):
            return None
        return f"http://{self._core_proxy_host()}:{self._client_mixed_port()}"

    def _runtime_source_supply_proxy_provider(self, phase: str) -> str | None:
        """Compatibility provider for Tier3 source-supply threads.

        Supply threads call this only for its side effects (start a missing
        bootstrap Core, apply a pending bootstrap reload): with private lanes
        wired they discard the URL and re-read the lanes.  They must never
        queue behind a Core transition they do not own.  ``start_core`` holds
        ``_core_transition_lock`` across the Tier1/Tier2 checks and the
        bootstrap promotion, and a supply thread waiting there delayed the
        first source transport by 5.9-8.2 s in 6 of 27 recorded sessions --
        longest exactly when every configured Tier1/Tier2 node is dead, the
        case Tier3 exists for.  While another owner holds the lock this
        returns None, the neutral no-route answer; the caller's own poll
        (prefetch 50 ms, supplier one control interval) retries, and the
        owner's completion republishes the lanes.  A thread that already owns
        the RLock re-enters and behaves exactly as before.  Preview and
        discovery keep the blocking ``_runtime_source_fetch_proxy_provider``.
        """

        if str(phase or "").strip().lower() != "bootstrap":
            return self._runtime_source_fetch_proxy_provider(phase)
        lock = self._core_transition_lock
        if not lock.acquire(blocking=False):
            return None
        try:
            return self._runtime_source_fetch_proxy_provider(phase)
        finally:
            lock.release()

    def _ensure_bootstrap_core_proxy(self) -> str | None:
        if self.stop_event.is_set() or self.manager is None:
            return None
        with self._core_transition_lock:
            if self.stop_event.is_set() or self.manager is None:
                return None
            if self._fail_terminal_tier3_bootstrap(self.manager):
                return None
            runner = self._get_core_runner()
            phase = self._current_core_runtime_phase()
            if runner.is_running():
                if phase == "bootstrap" and self._core_mixed_port_is_ready(runner):
                    manager = self.manager
                    required = self._tier3_startup_target_alive(manager)
                    healthy = count_healthy_nodes(
                        getattr(manager, "runtime_nodes", {}).get("tier3", [])
                    )
                    if self._tier3_required_for_start and healthy >= required:
                        self._queue_tier3_core_gate_attempt()
                        return None
                    current_marker = self._core_export_sync_marker()
                    if current_marker != self._last_core_export_sync_marker:
                        result = self.reload_core_config(
                            mode="incremental_export",
                            reason=RuntimeReloadReason.MEMBERSHIP_UNREPRESENTABLE,
                        )
                        if not reload_core_config_succeeded(result):
                            self._record_bootstrap_source_proxy_state(
                                "unavailable",
                                "bootstrap export reload failed",
                            )
                            return None
                        self._mark_core_export_sync_success(current_marker)
                    try:
                        self._wait_for_mihomo_route_ready(
                            timeout=self._startup_probe_timeout_seconds(),
                            runtime_config_path=self._current_mihomo_runtime_config_path(),
                        )
                    except Exception as exc:
                        try:
                            runner.stop()
                        finally:
                            self._set_core_runtime_phase("stopped")
                            self._last_core_export_sync_marker = None
                        self._record_bootstrap_source_proxy_state(
                            "unavailable",
                            "bootstrap route initialization timed out",
                        )
                        log_raw_diagnostic(
                            self.logger,
                            "warning",
                            "Mihomo bootstrap route stayed unavailable: %s",
                            exc,
                        )
                        return None
                    return f"http://{self._core_proxy_host()}:{self._client_mixed_port()}"
                return None

            started_here = False
            try:
                controller = self._mihomo_controller_config()
                if not mihomo_controller_enabled(controller):
                    raise BootstrapPrerequisiteError(
                        "mihomo controller is required for same-process bootstrap promotion"
                    )
                runner.get_version()
                runtime_config: Path | None = None
                for listener_attempt in range(
                    max(
                        1,
                        min(
                            RUNTIME_SOURCE_MAX_ROUTE_ATTEMPTS,
                            int(self._runtime_source_listener_allocation_attempts),
                        ),
                    )
                ):
                    if listener_attempt:
                        self._runtime_source_transport_for_config(
                            force_reallocate=True
                        )
                    runtime_config = self.write_mihomo_bootstrap_runtime_config()
                    bootstrap_outbound_available = (
                        self._bootstrap_config_has_outbound(runtime_config)
                    )
                    self._ensure_bootstrap_prerequisites(
                        runtime_config,
                        bootstrap_outbound_available=bootstrap_outbound_available,
                    )
                    try:
                        runner.start()
                        started_here = True
                        timeout = self._core_startup_timeout(
                            self._system_proxy_config(),
                            runtime_config,
                        )
                        self._wait_for_core_proxy_or_stop(
                            runner,
                            host=self._core_proxy_host(),
                            port=self._client_mixed_port(),
                            timeout=timeout,
                        )
                        self._wait_for_runtime_source_listeners_or_stop(
                            runner,
                            timeout=min(
                                max(
                                    0.25,
                                    float(
                                        self._runtime_source_listener_ready_timeout_seconds
                                    ),
                                ),
                                max(0.25, float(timeout)),
                            ),
                        )
                        self._mark_runtime_source_transport_loaded()
                        break
                    except Exception as exc:
                        listener_conflict = self._runtime_source_listener_bind_conflict(
                            runner,
                            exc,
                        )
                        if listener_conflict:
                            try:
                                runner.stop()
                            except Exception:
                                log_raw_diagnostic(
                                    self.logger,
                                    "warning",
                                    "Could not stop Mihomo after bootstrap private listener bind failure",
                                    exc_info=True,
                                )
                        if (
                            listener_attempt + 1
                            >= int(self._runtime_source_listener_allocation_attempts)
                            or not listener_conflict
                        ):
                            raise
                        started_here = False
                        log_raw_diagnostic(
                            self.logger,
                            "warning",
                            "Retrying Mihomo bootstrap with fresh private source listener "
                            "ports (attempt=%s/%s)",
                            listener_attempt + 2,
                            self._runtime_source_listener_allocation_attempts,
                        )
                if runtime_config is None:
                    raise RuntimeError(
                        "Mihomo bootstrap private source listeners were not configured"
                    )
                with self._core_lifecycle_lock:
                    self._core_generation += 1
                    self._bridge_core_launch_fact = (int(self._core_generation), str(getattr(self, "network_mode", "") or ""), time.time_ns() // 1_000_000)
                self._wait_for_mihomo_route_ready(
                    timeout=timeout,
                    runtime_config_path=runtime_config,
                )
                self._set_core_runtime_phase("bootstrap")
                self._mark_loaded_runtime_export_contract()
                self._last_core_export_sync_marker = self._core_export_sync_marker()
                self._record_bootstrap_source_proxy_state("ready")
                self.logger.info(
                    "Mihomo bootstrap mixed-port is ready without host traffic capture"
                )
                return f"http://{self._core_proxy_host()}:{self._client_mixed_port()}"
            except BootstrapPrerequisiteError as exc:
                if started_here and runner.is_running():
                    runner.stop()
                self._set_core_runtime_phase("stopped")
                self._last_core_export_sync_marker = None
                self._record_bootstrap_source_proxy_state(
                    "prerequisite_missing",
                    str(exc),
                )
                log_raw_diagnostic(
                    self.logger,
                    "warning",
                    "Mihomo bootstrap source proxy unavailable: %s",
                    exc,
                )
                return None
            except Exception as exc:
                if started_here and runner.is_running():
                    runner.stop()
                self._set_core_runtime_phase("stopped")
                self._last_core_export_sync_marker = None
                self._record_bootstrap_source_proxy_state("unavailable", str(exc))
                log_raw_diagnostic(
                    self.logger,
                    "warning",
                    "Mihomo bootstrap source proxy failed safely: %s",
                    exc,
                )
                return None

    def _running_core_mixed_proxy_url(self) -> str:
        """Return only a verified formal route before any public request starts."""
        proxy_url = self._runtime_source_fetch_proxy_provider("core")
        if not proxy_url:
            raise RuntimeError(
                "exit-quality network access requires verified formal FINAL-EXIT"
            )
        return proxy_url

    def _sync_system_proxy_config(self, client_config: dict[str, Any] | None = None) -> None:
        client = client_config if isinstance(client_config, dict) else self._client_config()
        proxy_runtime = system_proxy_runtime_config(client)
        self.system_proxy.config = proxy_runtime.raw_config
        self.system_proxy.enabled = proxy_runtime.enabled
        self.system_proxy.host = proxy_runtime.host
        self.system_proxy.port = proxy_runtime.port
        self.system_proxy.bypass = proxy_runtime.bypass

    def _sync_subscription_server_config(self) -> None:
        if not self.subscription_server or not self.manager:
            return
        desired = subscription_server_runtime_config(self.config)
        if subscription_server_matches(self.subscription_server, desired):
            return
        self.subscription_server.stop()
        self._start_subscription_server()

    def _configured_ui_language(self) -> str:
        ui = self.config.get("ui") if isinstance(self.config, dict) else None
        if not isinstance(ui, dict):
            return "en_US"
        return str(ui.get("language") or "en_US")

    def _disable_external_desktop_notifications(self, config: dict[str, Any]) -> dict[str, Any]:
        desktop_config = alerts_block(config).get("desktop")
        if not isinstance(desktop_config, dict):
            return config
        desktop_config["enabled"] = False
        desktop_config["disabled_in_native_ui"] = True
        return config

    def recover_stale_system_proxy(self) -> bool:
        result = self.system_proxy.restore_transaction(self.runtime_state)
        if result.get("state") != "restored":
            return False
        log_raw_diagnostic(
            self.logger,
            "warning",
            "Recovered stale system proxy left by a previous run",
        )
        return True

    def _write_mihomo_runtime_payload(
        self,
        payload: str,
        runtime_config_path: Path | None = None,
    ) -> Path:
        runtime_config_path = runtime_config_path or self._runtime_config_path_for_client()
        runtime_config_path.parent.mkdir(parents=True, exist_ok=True)
        temp_path = ""
        try:
            with tempfile.NamedTemporaryFile(
                "w",
                encoding="utf-8",
                dir=runtime_config_path.parent,
                prefix=f".{runtime_config_path.name}.",
                suffix=".tmp",
                delete=False,
            ) as handle:
                temp_path = handle.name
                handle.write(payload)
                handle.flush()
                os.fsync(handle.fileno())
            replace_with_retry(
                temp_path,
                runtime_config_path,
                attempts=4,
                initial_delay_seconds=0.01,
            )
            try:
                # Match the bytes emitted by Python's platform text newline
                # translation without rereading/parsing the file on the
                # authoritative config-write path.
                pending_runtime_config = payload.replace("\n", os.linesep).encode("utf-8")
                with self._node_diagnostic_binding_lock_ref():
                    self._node_diagnostic_pending_runtime_config = pending_runtime_config
                    self._node_diagnostic_pending_runtime_config_path = runtime_config_path
            except Exception:
                # Tracking is optional and must never change config-write
                # success or failure semantics.
                self._node_diagnostic_pending_runtime_config = None
                self._node_diagnostic_pending_runtime_config_path = None
        finally:
            if temp_path and Path(temp_path).exists():
                try:
                    Path(temp_path).unlink()
                except OSError:
                    pass
        return runtime_config_path

    def _tier3_core_provider_file_path(self) -> Path:
        filename = str(
            getattr(
                self,
                "_tier3_core_provider_filename",
                "tier3b-runtime.yaml",
            )
            or "tier3b-runtime.yaml"
        )
        # Mihomo resolves a file-provider's relative ``path`` against the
        # process HomeDir supplied by ``-d``, not against the main config's
        # directory.  Keep the writer and the Core parser on the same physical
        # file even when those two directories differ (the default layout is
        # data/mihomo-runtime.yaml plus -d data/mihomo).
        work_dir = self._resolve_path(
            mihomo_client_paths(self._client_config()).work_dir
        )
        return work_dir / filename

    def _render_mihomo_runtime_payload_base_with_provider(
        self,
        *,
        include_proxy_map: bool = False,
    ) -> (
        tuple[str, Tier3CoreProviderProjection | None]
        | tuple[
            str,
            Tier3CoreProviderProjection | None,
            dict[str, dict[str, Any]],
        ]
    ):
        if not self.manager:
            raise RuntimeError("manager service is not running")
        runtime_view = self._manager_for_mihomo_runtime_config()
        render_receipt: dict[str, Any] = {}
        try:
            _, payload = render_subscription_route(
                runtime_view,
                "/clash/config",
                {"tier3_limit": self._mihomo_tier3_export_limit()},
                render_receipt=render_receipt,
            )
        except TypeError as exc:
            if "render_receipt" not in str(exc):
                raise
            # Legacy in-process render shims predate immutable receipts. The
            # production renderer always takes the branch above; keep narrow
            # embedders source-compatible without weakening that path.
            _, payload = render_subscription_route(
                runtime_view,
                "/clash/config",
                {"tier3_limit": self._mihomo_tier3_export_limit()},
            )
            try:
                rendered_proxy_map = self._runtime_proxy_name_map(
                    runtime_view=runtime_view,
                )
            except TypeError:
                rendered_proxy_map = self._runtime_proxy_name_map()
        else:
            rendered_proxy_map = self._runtime_proxy_map_from_render_receipt(
                render_receipt,
            )
        payload = ensure_final_exit_probe_rules(
            payload,
            self._default_probe_urls(),
        )
        # Single seam for the resolver rung: writer, digest snapshot, bootstrap
        # builder and promotion all render from this payload.
        payload = self._apply_dns_resolver_plan_to_payload(payload)
        try:
            document = yaml.safe_load(payload)
            groups = (
                document.get("proxy-groups")
                if isinstance(document, dict)
                else None
            )
            tier3_group = next(
                (
                    group
                    for group in (groups or [])
                    if isinstance(group, dict)
                    and str(group.get("name") or "") == "TIER3-AUTO"
                ),
                None,
            )
            if tier3_group is None:
                if include_proxy_map:
                    return payload, None, rendered_proxy_map
                return payload, None
            member_names = [
                str(name)
                for name in (
                    tier3_group.get("proxies", [])
                    if isinstance(tier3_group, dict)
                    else []
                )
                if str(name or "").strip()
                and str(name or "").upper() != "REJECT"
            ]
        except Exception:
            member_names = []
        provider_name = str(
            getattr(self, "_tier3_core_provider_name", "TIER3B-RUNTIME")
            or "TIER3B-RUNTIME"
        )
        filename = str(
            getattr(
                self,
                "_tier3_core_provider_filename",
                "tier3b-runtime.yaml",
            )
            or "tier3b-runtime.yaml"
        )
        projection = project_tier3b_file_provider(
            payload,
            member_names,
            provider_name=provider_name,
            provider_path=f"./{filename}",
            group_name="TIER3-AUTO",
            provider_health_check=self._tier3_verified_provider_writes_enabled(),
        )
        if include_proxy_map:
            return projection.main_yaml, projection, rendered_proxy_map
        return projection.main_yaml, projection

    def _render_mihomo_runtime_payload_base(self) -> str:
        payload, _projection = (
            self._render_mihomo_runtime_payload_base_with_provider()
        )
        return payload

    def _inject_runtime_source_transport(
        self,
        payload: str,
        transport: RuntimeSourceTransportGeneration | None,
    ) -> str:
        if transport is None:
            return payload
        return inject_runtime_source_listeners(
            payload,
            transport.listeners,
            egress_proxy=egress_proxy_block(self.config),
        )

    def _render_mihomo_runtime_payload_snapshot(self) -> str:
        """Render semantic state without allocating or advancing listener authority."""

        payload = self._render_mihomo_runtime_payload_base()
        if not self._runtime_source_transport_enabled():
            return payload
        return self._inject_runtime_source_transport(
            payload,
            self._runtime_source_transport_snapshot(),
        )

    def _bootstrap_source_export_contract_snapshot(self) -> dict[str, Any]:
        """Include pending provider members without writing a file or starting I/O."""
        payload, projection, proxy_map = self._render_mihomo_runtime_payload_base_with_provider(
            include_proxy_map=True,
        )
        if self._runtime_source_transport_enabled():
            payload = self._inject_runtime_source_transport(
                payload, self._runtime_source_transport_snapshot(),
            )
        defer_geodata_rules = self._bootstrap_geodata_rules_deferred()
        payload = build_bootstrap_clash_config(
            payload, egress_proxy=egress_proxy_block(self.config),
            defer_geodata_rules=defer_geodata_rules,
            # The writer's listener for this run, never a new one: this
            # snapshot must render the bytes the writer rendered.
            geodata_listener=(
                self._bootstrap_geodata_listener_spec(allocate=False)
                if defer_geodata_rules else None
            ),
        )
        return self._runtime_export_contract_for_payload(
            payload,
            provider_payload=projection.provider_yaml if projection is not None else "",
            rendered_proxy_map=proxy_map,
        )

    def _render_mihomo_runtime_payload(self) -> str:
        payload, _projection = (
            self._render_mihomo_runtime_payload_base_with_provider()
        )
        if self._runtime_source_transport_enabled():
            transport = self._runtime_source_transport_for_config()
            payload = self._inject_runtime_source_transport(
                payload,
                transport,
            )
        else:
            with self._runtime_source_transport_lock:
                self._runtime_source_transport = None
                self._runtime_source_loaded_transport = None
        return payload

    def write_mihomo_runtime_config(self) -> Path:
        payload, projection, rendered_proxy_map = (
            self._render_mihomo_runtime_payload_base_with_provider(
                include_proxy_map=True,
            )
        )
        if self._runtime_source_transport_enabled():
            transport = self._runtime_source_transport_for_config()
            payload = self._inject_runtime_source_transport(payload, transport)
        else:
            with self._runtime_source_transport_lock:
                self._runtime_source_transport = None
                self._runtime_source_loaded_transport = None
        provider_payload = ""
        provider_path = self._tier3_core_provider_file_path()
        if projection is not None and self._tier3_verified_provider_writes_enabled():
            # A full config load rebuilds every member alive-by-default
            # whatever the provider bytes, and an unfixed fallback then serves
            # its first member: put the published pick first, so the reloaded
            # group keeps serving it until the startup check has run.  Any
            # verified member round still in flight is orphaned by this load.
            projection = self._tier3_pick_first_projection(projection)
            self._tier3_provider_write_generation = (
                int(getattr(self, "_tier3_provider_write_generation", 0) or 0) + 1
            )
        previous_pending_projection = getattr(
            self,
            "_tier3_core_provider_pending_projection",
            None,
        )
        try:
            previous_provider_bytes = provider_path.read_bytes()
            previous_provider_exists = True
        except FileNotFoundError:
            previous_provider_bytes = b""
            previous_provider_exists = False
        if projection is not None:
            atomic_replace_if_changed(
                provider_path,
                projection.provider_yaml,
            )
            provider_payload = projection.provider_yaml
            self._tier3_core_provider_pending_projection = projection
        else:
            self._tier3_core_provider_pending_projection = None
        contract = self._runtime_export_contract_for_payload(
            payload,
            provider_payload=provider_payload or None,
            rendered_proxy_map=rendered_proxy_map,
        )
        contract["provider_projection"] = projection
        try:
            runtime_config_path = self._write_mihomo_runtime_payload(payload)
            self._record_pending_runtime_export_contract(
                payload,
                runtime_config_path,
                contract=contract,
            )
        except Exception:
            self._tier3_core_provider_pending_projection = (
                previous_pending_projection
            )
            if previous_provider_exists:
                atomic_replace_if_changed(provider_path, previous_provider_bytes)
            else:
                provider_path.unlink(missing_ok=True)
            raise
        return runtime_config_path

    def write_mihomo_no_capture_runtime_config(self) -> Path:
        # T-P2-RT3: the mode the formal payload below is rendered with.
        rendered_network_mode = str(getattr(self, "network_mode", "") or "").strip().lower()
        runtime_config_path = self.write_mihomo_runtime_config()
        if not runtime_config_path.is_file():
            # Runtime-config writers are intentionally replaceable in focused
            # lifecycle adapters. A production writer always materializes the
            # file before returning.
            return runtime_config_path
        formal_payload = runtime_config_path.read_text(encoding="utf-8")
        with self._runtime_route_snapshot_lock:
            formal_contract = copy.deepcopy(
                self._runtime_pending_export_contract
                if isinstance(self._runtime_pending_export_contract, dict)
                else None
            )
        with self._core_lifecycle_lock:
            self._staged_capture_runtime_config_payload = formal_payload
            self._staged_capture_runtime_config_path = runtime_config_path
            self._staged_capture_runtime_export_contract = formal_contract
            self._staged_capture_runtime_network_mode = rendered_network_mode
        payload = build_capture_disabled_clash_config(formal_payload)
        contract = self._runtime_export_contract_for_payload(
            payload,
            rendered_proxy_map=(
                formal_contract.get("proxy_map")
                if isinstance(formal_contract, dict)
                and isinstance(formal_contract.get("proxy_map"), dict)
                else None
            ),
        )
        written = self._write_mihomo_runtime_payload(payload, runtime_config_path)
        self._record_pending_runtime_export_contract(
            payload,
            written,
            contract=contract,
        )
        return written

    # ------------------------------------------------------------------
    # DNS resolver plan: one rung per runtime run, rendered into every phase
    # ------------------------------------------------------------------

    def _dns_resolver_formal_block(self) -> dict[str, Any] | None:
        try:
            return resolved_client_dns_block(client_dns_block(self._client_config()))
        except Exception:
            return None

    def _dns_resolver_policy_inputs(
        self, formal_dns: dict[str, Any] | None,
    ) -> tuple[str, bool, bool]:
        """Return ``(mode, encrypted_only, user_custom)`` from ``client.dns``."""

        try:
            dns_config = client_dns_block(self._client_config())
        except Exception:
            dns_config = {}
        mode = normalize_dns_mode(dns_config if isinstance(dns_config, dict) else None)
        return mode, mode == DNS_MODE_ENCRYPTED_ONLY, mode == DNS_MODE_CUSTOM

    def _dns_resolver_excluded_adapter_names(self) -> tuple[str, ...]:
        names = ["tesseract", "mihomo", "meta", "clash"]
        try:
            tun_device = str(
                _runtime_client_subblock(self._client_config(), "tun").get("device") or ""
            ).strip().lower()
        except Exception:
            tun_device = ""
        if tun_device and tun_device not in names:
            names.append(tun_device)
        return tuple(names)

    def _current_dns_resolver_plan(self) -> DnsResolverPlan | None:
        lock = getattr(self, "_dns_resolver_plan_lock", None)
        if lock is None:
            return getattr(self, "_dns_resolver_plan", None)
        with lock:
            return getattr(self, "_dns_resolver_plan", None)

    def _prepare_dns_resolver_plan(
        self,
        *,
        reason: str,
        force: bool = False,
        budget_seconds: float | None = None,
    ) -> DnsResolverPlan | None:
        """Qualify resolvers for this network and publish the chosen rung.

        Positive evidence only: an inconclusive run keeps the encrypted pool.
        A fresh plan (≤ ``_DNS_RESOLVER_PLAN_CACHE_SECONDS``) is reused so the
        writer never probes under the Core transition lock on a warm path.
        """

        lock = getattr(self, "_dns_resolver_plan_lock", None)
        if lock is None:
            # Narrow lifecycle embedders predate the resolver ladder; they keep
            # the rendered policy and never probe the network.
            return None
        formal_dns = self._dns_resolver_formal_block()
        if formal_dns is None:
            with lock:
                self._dns_resolver_plan = None
            return None
        now = time.monotonic()
        with lock:
            existing = getattr(self, "_dns_resolver_plan", None)
            if (
                existing is not None
                and not force
                and now - float(existing.applied_at_monotonic) <= _DNS_RESOLVER_PLAN_CACHE_SECONDS
            ):
                return existing
            previous_revision = int(existing.revision) if existing is not None else 0
            fault_count = int(getattr(self, "_dns_resolver_fault_count", 0) or 0)
        mode, encrypted_only, user_custom = self._dns_resolver_policy_inputs(formal_dns)
        memory = getattr(self, "_dns_resolver_memory", None)
        excluded_names = self._dns_resolver_excluded_adapter_names()
        try:
            link = discover_link_resolvers(excluded_adapter_names=excluded_names)
            hint = None
            remembered = memory.hint(link.fingerprint) if memory is not None else None
            if remembered is not None:
                hint = QualificationHint(
                    encrypted_urls=remembered.encrypted_urls,
                    link_resolvers=remembered.link_resolvers,
                )
            qualification = qualify_resolvers(
                budget_seconds=(
                    QUALIFICATION_BUDGET_SECONDS if budget_seconds is None else float(budget_seconds)
                ),
                hint=hint,
                excluded_adapter_names=excluded_names,
                discovery=lambda **_kwargs: link,
            )
        except Exception:
            log_raw_diagnostic(
                self.logger,
                "warning",
                "DNS resolver qualification failed; keeping the current resolver policy",
                exc_info=True,
            )
            return self._current_dns_resolver_plan()
        decision = choose_rung(qualification, ladder=ladder_for_mode(mode))
        plan = DnsResolverPlan(
            decision=decision,
            qualification=qualification,
            block=render_dns_block(formal_dns, decision, qualification),
            revision=previous_revision + 1,
            applied_at_monotonic=time.monotonic(),
            fault_count_at_apply=fault_count,
            encrypted_only=encrypted_only,
            user_custom=user_custom,
            prepared_reason=str(reason or ""),
            mode=mode,
        )
        with lock:
            self._dns_resolver_plan = plan
            self._dns_resolver_fault_base = int(getattr(self, "_dns_resolver_fault_count", 0) or 0)
            self._dns_resolver_control_failures = 0
        publish_active_dns_block(plan.block)
        self._remember_dns_resolver_plan(plan)
        self._publish_dns_resolver_state(plan)
        self._start_dns_resolver_watch()
        log_event(
            self.logger,
            "INFO" if plan.rung == RUNG_ENCRYPTED else "WARNING",
            "dns.resolver_qualified",
            (
                f"DNS resolver plan ready (rung={plan.rung} reason={plan.reason} "
                f"revision={plan.revision} wall_ms={qualification.wall_time_ms} trigger={reason})"
            ),
            params={
                "summary": plan.summary(),
                "reason": plan.reason,
                "rung": plan.rung,
                "revision": plan.revision,
                "wall_time_ms": qualification.wall_time_ms,
                "fingerprint": qualification.fingerprint,
            },
        )
        return plan

    def _remember_dns_resolver_plan(self, plan: DnsResolverPlan) -> None:
        memory = getattr(self, "_dns_resolver_memory", None)
        if memory is None:
            return
        qualification = plan.qualification
        try:
            memory.record(
                qualification.fingerprint,
                rung=plan.rung,
                encrypted_urls=[item.candidate.url for item in qualification.qualified_candidates()],
                link_resolvers=[item.address for item in qualification.public_link_resolvers()],
            )
        except Exception:
            log_raw_diagnostic(
                self.logger, "warning", "Could not persist resolver memory", exc_info=True,
            )

    def _apply_dns_resolver_plan_to_payload(self, payload: str) -> str:
        """Render the current rung into a formal payload (all phases share it)."""

        plan = self._current_dns_resolver_plan()
        if plan is None:
            return payload
        try:
            document = yaml.safe_load(payload)
        except yaml.YAMLError:
            return payload
        if not isinstance(document, dict) or not isinstance(document.get("dns"), dict):
            return payload
        return yaml.safe_dump(
            apply_dns_block_to_payload(document, plan.block),
            allow_unicode=True,
            sort_keys=False,
        )

    def _publish_dns_resolver_state(self, plan: DnsResolverPlan) -> None:
        manager = self.manager
        if manager is None:
            return
        lock = getattr(manager, "lock", None)
        context = lock if hasattr(lock, "__enter__") else nullcontext()
        try:
            with context:
                report = ensure_tier3_collection_report(manager)
                report.update(plan.report_fields())
        except Exception:
            log_raw_diagnostic(
                self.logger, "warning", "Failed to publish DNS resolver state", exc_info=True,
            )

    def _dns_resolver_status_summary(self) -> dict[str, Any]:
        plan = self._current_dns_resolver_plan()
        if plan is None:
            return {}
        fields = plan.report_fields()
        return {
            "rung": plan.rung,
            "reason": plan.reason,
            "summary": plan.summary(),
            "revision": int(plan.revision),
            "encrypted": bool(fields.get("dns_resolver_encrypted")),
            "encrypted_only": bool(plan.encrypted_only),
            "link_resolvers": list(fields.get("dns_resolver_link_resolvers") or []),
            "ladder_remaining": int(plan.remaining),
        }

    def _note_dns_resolver_fault(self, event: CoreOutputEvent) -> None:
        """Count Core resolution failures per process; reader thread, no I/O."""

        lock = getattr(self, "_dns_resolver_plan_lock", None)
        if lock is None:
            return
        scope = (int(event.pid), int(event.process_generation))
        with lock:
            if getattr(self, "_dns_resolver_fault_scope", None) != scope:
                self._dns_resolver_fault_scope = scope
                self._dns_resolver_fault_count = 0
                self._dns_resolver_fault_base = 0
            plan = getattr(self, "_dns_resolver_plan", None)
            if plan is not None:
                try:
                    observed = float(event.received_at_monotonic)
                except (TypeError, ValueError, AttributeError):
                    observed = time.monotonic()
                if observed - float(plan.applied_at_monotonic) < _DNS_RESOLVER_FAULT_GRACE_SECONDS:
                    # Still the previous rung's dials timing out; not evidence
                    # against the rung that was just applied.
                    self._dns_resolver_fault_ignored = (
                        int(getattr(self, "_dns_resolver_fault_ignored", 0) or 0) + 1
                    )
                    return
            self._dns_resolver_fault_count = int(getattr(self, "_dns_resolver_fault_count", 0) or 0) + 1

    def _dns_resolver_faults_since_apply(self) -> int:
        lock = getattr(self, "_dns_resolver_plan_lock", None)
        if lock is None:
            return 0
        with lock:
            count = int(getattr(self, "_dns_resolver_fault_count", 0) or 0)
            base = int(getattr(self, "_dns_resolver_fault_base", 0) or 0)
        return max(0, count - base)

    def _dns_resolver_control_query_verdict(self, plan: DnsResolverPlan) -> str:
        """Ask the running Core to resolve a control name through its own resolver.

        ``ok`` and ``failed`` are positive evidence about the active rung; a
        controller that cannot be reached at all is ``unknown`` and never
        moves the ladder on its own.
        """

        client = getattr(self, "api_client", None)
        if client is None:
            return _DNS_CONTROL_UNKNOWN
        control = LINK_RESOLVER_CONTROL_NAMES[0]
        request = getattr(client, "_request", None)
        try:
            if callable(request):
                try:
                    request(
                        "GET", "/version",
                        timeout=_DNS_RESOLVER_CONTROL_LIVENESS_TIMEOUT_SECONDS,
                    )
                except TypeError:
                    client.version()
            else:
                client.version()
        except Exception:
            return _DNS_CONTROL_UNKNOWN
        try:
            try:
                payload = client._request(  # type: ignore[attr-defined]
                    "GET", "/dns/query", query={"name": control, "type": "A"},
                    timeout=_DNS_RESOLVER_CONTROL_QUERY_TIMEOUT_SECONDS,
                )
            except TypeError:
                payload = client.dns_query(control, "A")
        except Exception:
            # The controller is alive but the resolution did not complete in
            # time: the rung's upstreams are hanging.
            return _DNS_CONTROL_FAILED
        if not isinstance(payload, dict):
            return _DNS_CONTROL_UNKNOWN
        try:
            status = int(payload.get("Status", 0) or 0)
        except (TypeError, ValueError):
            status = 0
        answers = payload.get("Answer") or []
        data = {
            str(item.get("data") or "").strip()
            for item in answers
            if isinstance(item, dict)
        }
        if status != 0 or not data:
            return _DNS_CONTROL_FAILED
        if plan.qualification.outer_fake_ip:
            # An outer fake-IP tunnel answers with synthetic addresses by design.
            return _DNS_CONTROL_OK
        if data & LINK_RESOLVER_CONTROL_ANSWERS:
            return _DNS_CONTROL_OK
        return _DNS_CONTROL_FAILED

    def _dns_resolver_control_query_failed(self, plan: DnsResolverPlan) -> bool:
        return self._dns_resolver_control_query_verdict(plan) == _DNS_CONTROL_FAILED

    def _maybe_escalate_dns_resolver_rung(self, *, allow_control_query: bool = True) -> bool:
        """Move one rung down only on positive evidence against the active rung.

        Core ``dns resolve failed`` lines (outside the post-reload grace
        window) are the trigger; the controller's own resolution of a control
        name is the arbiter: an answer vetoes the faults (the names the Core
        could not resolve are the problem, not the resolver), a failure
        confirms them.  Without any Core faults the control query alone needs
        consecutive failures.  An unreachable controller decides nothing.
        """

        plan = self._current_dns_resolver_plan()
        if plan is None or plan.remaining <= 0 or self.stop_event.is_set():
            return False
        now = time.monotonic()
        if now - float(plan.applied_at_monotonic) < _DNS_RESOLVER_ESCALATION_MIN_SECONDS:
            return False
        faults = self._dns_resolver_faults_since_apply()
        faults_ready = faults >= _DNS_RESOLVER_ESCALATION_FAULTS
        verdict = _DNS_CONTROL_UNKNOWN
        checked_at = float(getattr(self, "_dns_resolver_control_checked_at", 0.0) or 0.0)
        if allow_control_query and (
            faults_ready or now - checked_at >= _DNS_RESOLVER_CONTROL_QUERY_INTERVAL_SECONDS
        ):
            self._dns_resolver_control_checked_at = now
            verdict = self._dns_resolver_control_query_verdict(plan)
        if verdict == _DNS_CONTROL_OK:
            self._dns_resolver_control_failures = 0
            if faults:
                lock = getattr(self, "_dns_resolver_plan_lock", None)
                if lock is not None:
                    with lock:
                        self._dns_resolver_fault_base = int(
                            getattr(self, "_dns_resolver_fault_count", 0) or 0
                        )
                log_raw_diagnostic(
                    self.logger,
                    "info",
                    "DNS resolver rung %s answers the control query; %d Core resolve "
                    "failures were not attributed to the resolver",
                    plan.rung,
                    faults,
                )
            return False
        if verdict == _DNS_CONTROL_FAILED:
            self._dns_resolver_control_failures = (
                int(getattr(self, "_dns_resolver_control_failures", 0) or 0) + 1
            )
        trigger = ""
        if faults_ready:
            trigger = REASON_ESCALATED_DNS_FAULTS
        elif (
            verdict == _DNS_CONTROL_FAILED
            and int(getattr(self, "_dns_resolver_control_failures", 0) or 0)
            >= _DNS_RESOLVER_CONTROL_QUERY_FAILURES
        ):
            trigger = REASON_ESCALATED_CONTROL_QUERY
        if not trigger:
            return False
        return self._escalate_dns_resolver_rung(plan, reason=trigger)

    def _escalate_dns_resolver_rung(self, plan: DnsResolverPlan, *, reason: str) -> bool:
        """Move exactly one rung down and hot-reload the Core with it."""

        decision = next_rung(plan.decision, plan.qualification, reason=reason)
        if decision is None:
            return False
        formal_dns = self._dns_resolver_formal_block()
        if formal_dns is None:
            return False
        lock = self._dns_resolver_plan_lock
        candidate = DnsResolverPlan(
            decision=decision,
            qualification=plan.qualification,
            block=render_dns_block(formal_dns, decision, plan.qualification),
            revision=plan.revision + 1,
            applied_at_monotonic=time.monotonic(),
            fault_count_at_apply=int(getattr(self, "_dns_resolver_fault_count", 0) or 0),
            encrypted_only=plan.encrypted_only,
            user_custom=plan.user_custom,
            prepared_reason=str(reason),
            mode=plan.mode,
        )
        with lock:
            if self._dns_resolver_plan is not plan:
                return False
            self._dns_resolver_plan = candidate
            self._dns_resolver_fault_base = int(getattr(self, "_dns_resolver_fault_count", 0) or 0)
            self._dns_resolver_control_failures = 0
        publish_active_dns_block(candidate.block)
        runner = self.core_runner
        core_running = False
        try:
            core_running = bool(runner is not None and runner.is_running())
        except Exception:
            core_running = False
        if core_running:
            try:
                result = self.reload_core_config(
                    mode="incremental_export",
                    reason=RuntimeReloadReason.DNS_LIFECYCLE,
                )
            except Exception as exc:
                result = {"reloaded": False, "reason": str(exc)}
            if not reload_core_config_succeeded(result):
                with lock:
                    if self._dns_resolver_plan is candidate:
                        self._dns_resolver_plan = plan
                publish_active_dns_block(plan.block)
                log_raw_diagnostic(
                    self.logger,
                    "warning",
                    "DNS resolver escalation reload failed (from=%s to=%s reason=%s): %s",
                    plan.rung,
                    candidate.rung,
                    reason,
                    result.get("reason") if isinstance(result, dict) else result,
                )
                return False
            try:
                self._mark_core_export_sync_success()
            except Exception:
                pass
        self._publish_dns_resolver_state(candidate)
        self._notify_tier3_source_control_route_changed("dns_rung_changed")
        log_event(
            self.logger,
            "WARNING",
            "dns.resolver_degraded",
            f"DNS resolver degraded from {plan.rung} to {candidate.rung} ({reason})",
            params={
                "summary": candidate.summary(),
                "reason": reason,
                "rung": candidate.rung,
                "revision": candidate.revision,
                "previous_rung": plan.rung,
            },
        )
        return True

    # ------------------------------------------------------------------
    # Source supply without egress: bounded, visible, revocable terminal
    # ------------------------------------------------------------------

    def _observe_source_supply_health(self) -> None:
        """Per source-demand round: escalate the resolver rung or park supply.

        Rounds are counted from the manager's retry counters, so this applies
        equally to cold start and to background expansion after every node
        died; only the Core start gate differs between the two.
        """

        if self.stop_event.is_set() or self.manager is None:
            return
        state = getattr(self, "_source_supply_no_egress_state", None)
        if state is None:
            state = self._source_supply_no_egress_state = {}
        if state.get("active"):
            return
        if self._maybe_escalate_dns_resolver_rung():
            state["rounds"] = 0
            return
        report = getattr(self.manager, "tier3_last_collection_report", None)
        if not isinstance(report, dict):
            return

        def _count(key: str) -> int:
            try:
                return max(0, int(report.get(key) or 0))
            except (TypeError, ValueError):
                return 0

        retry_count = _count("runtime_proxy_retry_count")
        success_count = _count("runtime_proxy_retry_success_count")
        fetched_ok = _count("source_fetch_ok")
        last_retry = state.get("last_retry_count")
        last_success = state.get("last_success_count")
        if last_retry is None:
            state.update(last_retry_count=retry_count, last_success_count=success_count, rounds=0)
            return
        if success_count > int(last_success or 0) or fetched_ok > 0:
            state["rounds"] = 0
        elif retry_count > int(last_retry):
            state["rounds"] = int(state.get("rounds", 0) or 0) + 1
        state.update(last_retry_count=retry_count, last_success_count=success_count)
        rounds = int(state.get("rounds", 0) or 0)
        if rounds <= 0 or fetched_ok > 0:
            return
        plan = self._current_dns_resolver_plan()
        exhausted = plan is None or plan.remaining <= 0
        threshold = (
            1 if plan is not None and plan.rung == RUNG_INTRANET_ONLY
            else _SOURCE_SUPPLY_NO_EGRESS_ROUNDS if exhausted
            else _SOURCE_SUPPLY_NO_EGRESS_ROUNDS_DNS_OK
        )
        if rounds < threshold:
            return
        self._fail_no_egress_source_supply(self._classify_source_supply_no_egress(plan, report))

    def _classify_source_supply_no_egress(
        self, plan: DnsResolverPlan | None, report: dict[str, Any],
    ) -> str:
        blocked = str(report.get("source_retry_blocked_reason") or "").strip().lower()
        if blocked in {"blocked_no_route", "runtime_proxy_unavailable_after_recovery"}:
            return "no_route"
        if plan is not None:
            if plan.encrypted_only and plan.remaining <= 0 and plan.rung == RUNG_ENCRYPTED:
                return "encrypted_dns_unreachable"
            if plan.qualification.captive_suspected:
                return "captive_portal_suspected"
            if plan.rung == RUNG_INTRANET_ONLY or self._dns_resolver_faults_since_apply() > 0:
                return "dns_unresolvable"
        return "sources_unreachable"

    def _fail_no_egress_source_supply(self, detail: str) -> bool:
        manager = self.manager
        if manager is None or self.stop_event.is_set():
            return False
        state = getattr(self, "_source_supply_no_egress_state", None)
        if state is None:
            state = self._source_supply_no_egress_state = {}
        if state.get("active"):
            return False
        plan = self._current_dns_resolver_plan()
        rung = plan.rung if plan is not None else ""
        detail = str(detail or "sources_unreachable")
        state.update(active=True, detail=detail, since=time.monotonic(), rounds=0)
        phase = self._current_core_runtime_phase()
        required = self._tier3_startup_target_alive(manager)
        healthy = count_healthy_nodes(getattr(manager, "runtime_nodes", {}).get("tier3", []))
        pre_gate = bool(
            self._tier3_required_for_start
            and healthy < required
            and phase in {"bootstrap", "stopped"}
        )
        lock = getattr(manager, "lock", None)
        context = lock if hasattr(lock, "__enter__") else nullcontext()
        with context:
            report = ensure_tier3_collection_report(manager)
            report["source_supply_terminal"] = True
            report["source_supply_terminal_reason"] = "no_egress"
            report["source_stream_sampling_diagnosis"] = "source_supply_no_egress"
            report["startup_deferred_reason"] = "source_supply_no_egress"
            report["startup_failure_detail"] = detail
            report["runtime_source_bootstrap_reason"] = "source_supply_no_egress"
            if pre_gate:
                report["startup_supply_exhausted"] = True
        if pre_gate:
            # The under-floor bootstrap Core stops exactly as any other terminal
            # supply outcome; only the reason and the retry differ.
            self._fail_terminal_tier3_bootstrap(manager)
            with context:
                report = ensure_tier3_collection_report(manager)
                report["startup_failure_reason"] = "source_supply_no_egress"
                report["startup_failure_detail"] = detail
            self._source_supply_no_egress_reason = "source_supply_no_egress"
            self._source_supply_no_egress_detail = detail
        park = getattr(manager, "park_tier3_source_supply", None)
        if callable(park):
            try:
                park(_SOURCE_SUPPLY_NO_EGRESS_RETRY_SECONDS, "no_egress")
            except Exception:
                log_raw_diagnostic(self.logger, "warning", "Could not park source supply", exc_info=True)
        send_event = getattr(getattr(manager, "alerts", None), "send_event", None)
        alert_logged = False
        if callable(send_event):
            try:
                alert_logged = bool(send_event(tier3_source_supply_no_egress_event(detail, rung=rung)))
            except Exception:
                log_raw_diagnostic(self.logger, "warning", "Could not send no-egress alert", exc_info=True)
        no_egress_evidence = (
            f"Source supply has no usable egress on this network (detail={detail} rung={rung}); "
            f"retry in {_SOURCE_SUPPLY_NO_EGRESS_RETRY_SECONDS:.0f}s"
        )
        if alert_logged:
            # The dispatched alert already logged this event; a second key
            # event made every episode appear twice in the event flow.
            log_raw_diagnostic(self.logger, "warning", no_egress_evidence)
        else:
            log_event(
                self.logger,
                "ERROR",
                "tier3.source_supply_no_egress",
                no_egress_evidence,
                params={
                    "detail": detail,
                    "rung": rung,
                    "retry_after_seconds": _SOURCE_SUPPLY_NO_EGRESS_RETRY_SECONDS,
                },
            )
        timer = getattr(self, "_source_supply_no_egress_timer", None)
        if timer is not None:
            timer.cancel()
        timer = threading.Timer(
            _SOURCE_SUPPLY_NO_EGRESS_RETRY_SECONDS,
            self._retry_after_source_supply_no_egress,
        )
        timer.daemon = True
        timer.name = "tier3-source-supply-no-egress-retry"
        self._source_supply_no_egress_timer = timer
        timer.start()
        return True

    def _clear_source_supply_no_egress(self, reason: str) -> None:
        state = getattr(self, "_source_supply_no_egress_state", None)
        if isinstance(state, dict):
            state.clear()
        timer = getattr(self, "_source_supply_no_egress_timer", None)
        if timer is not None:
            timer.cancel()
            self._source_supply_no_egress_timer = None
        self._source_supply_no_egress_reason = ""
        self._source_supply_no_egress_detail = ""

    def _on_runtime_source_supply_observed(self, evidence: dict[str, Any]) -> None:
        """A parked network just delivered: the no-egress verdict is disproven.

        The verdict is drawn from rounds that fetched nothing, so a report that
        carries a fetched source outranks it.  Waiting out the retry timer here
        would idle the whole pipeline on evidence already known to be stale.
        """

        manager = self.manager
        state = getattr(self, "_source_supply_no_egress_state", None)
        if (
            self.stop_event.is_set()
            or manager is None
            or not isinstance(state, dict)
            or not state.get("active")
        ):
            return
        detail = str(state.get("detail") or "")
        parked_for = max(0.0, time.monotonic() - float(state.get("since") or 0.0))
        log_event(
            self.logger,
            "INFO",
            "tier3.source_supply_restored",
            "Source supply resumed after delivery contradicted the no-egress verdict "
            f"(detail={detail} parked_seconds={parked_for:.1f} "
            f"source_fetch_ok={evidence.get('source_fetch_ok')} node_count={evidence.get('node_count')})",
            params={"detail": detail, "parked_seconds": round(parked_for, 1)},
        )
        self._resume_source_supply_after_no_egress(
            manager, clear_reason="supply_observed", resume_reason="supply_observed",
        )

    def _retry_after_source_supply_no_egress(self) -> None:
        """Re-qualify and resume; a changed network may make supply possible."""

        manager = self.manager
        state = getattr(self, "_source_supply_no_egress_state", None)
        if (
            self.stop_event.is_set()
            or manager is None
            or not isinstance(state, dict)
            or not state.get("active")
        ):
            return
        try:
            self._prepare_dns_resolver_plan(reason="no_egress_retry", force=True)
        except Exception:
            log_raw_diagnostic(self.logger, "warning", "No-egress retry qualification failed", exc_info=True)
        self._resume_source_supply_after_no_egress(
            manager, clear_reason="retry_timer", resume_reason="no_egress_retry",
        )

    def _resume_source_supply_after_no_egress(
        self, manager: Any, *, clear_reason: str, resume_reason: str,
    ) -> None:
        """Clear the terminal supply state and let retries dispatch again."""

        self._clear_source_supply_no_egress(clear_reason)
        lock = getattr(manager, "lock", None)
        context = lock if hasattr(lock, "__enter__") else nullcontext()
        with context:
            report = ensure_tier3_collection_report(manager)
            report["source_supply_terminal"] = False
            report["startup_supply_exhausted"] = False
            report["startup_failed"] = False
            for key in (
                "source_supply_terminal_reason",
                "startup_failure_reason",
                "startup_failure_detail",
            ):
                report.pop(key, None)
        was_terminal = bool(getattr(self, "_tier3_startup_terminal_failure", False))
        if was_terminal:
            self._clear_tier3_terminal_startup_failure()
        resume = getattr(manager, "resume_tier3_source_supply", None)
        if callable(resume):
            try:
                resume(resume_reason)
            except Exception:
                log_raw_diagnostic(self.logger, "warning", "Could not resume source supply", exc_info=True)
        if (
            was_terminal
            and self._tier3_required_for_start
            and self._current_core_runtime_phase() == "stopped"
        ):
            try:
                self._ensure_bootstrap_core_proxy()
            except Exception:
                log_raw_diagnostic(
                    self.logger, "warning", "Bootstrap Core restart after no-egress retry failed", exc_info=True,
                )

    def _schedule_dns_resolver_plan(self, *, reason: str) -> None:
        """Qualify in the background and apply the rung to a running Core.

        Used where waiting would delay a Core that can already serve (formal
        starts).  When the plan lands after the Core was rendered without it,
        the same ``DNS_LIFECYCLE`` reload as an escalation applies it.
        """

        if getattr(self, "_dns_resolver_plan_lock", None) is None:
            return
        existing = self._current_dns_resolver_plan()
        if (
            existing is not None
            and time.monotonic() - float(existing.applied_at_monotonic) <= _DNS_RESOLVER_PLAN_CACHE_SECONDS
        ):
            return
        worker = getattr(self, "_dns_resolver_plan_worker", None)
        if worker is not None and worker.is_alive():
            return

        def run() -> None:
            try:
                before = self._current_dns_resolver_plan()
                plan = self._prepare_dns_resolver_plan(reason=reason)
                if plan is None or self.stop_event.is_set():
                    return
                if before is not None and dict(before.block) == dict(plan.block):
                    return
                self._apply_dns_resolver_plan_to_running_core(plan)
            except Exception:
                log_raw_diagnostic(
                    self.logger, "warning", "Background DNS resolver qualification failed", exc_info=True,
                )

        thread = threading.Thread(target=run, name="dns-resolver-plan", daemon=True)
        self._dns_resolver_plan_worker = thread
        thread.start()

    def _rendered_dns_block_matches(self, plan: DnsResolverPlan) -> bool | None:
        """Compare the loaded runtime config's dns block with the plan; None if unknown."""

        try:
            path = self._current_mihomo_runtime_config_path()
            document = yaml.safe_load(Path(path).read_text(encoding="utf-8"))
        except Exception:
            return None
        if not isinstance(document, dict):
            return None
        rendered = document.get("dns")
        if not isinstance(rendered, dict):
            # DNS disabled by policy: nothing to apply.
            return True
        return dict(rendered) == dict(plan.block)

    def _apply_dns_resolver_plan_to_running_core(self, plan: DnsResolverPlan) -> bool:
        runner = self.core_runner
        try:
            if runner is None or not runner.is_running():
                return False
        except Exception:
            return False
        if self._rendered_dns_block_matches(plan) is not False:
            return False
        try:
            result = self.reload_core_config(
                mode="incremental_export",
                reason=RuntimeReloadReason.DNS_LIFECYCLE,
            )
        except Exception as exc:
            result = {"reloaded": False, "reason": str(exc)}
        if not reload_core_config_succeeded(result):
            log_raw_diagnostic(
                self.logger,
                "warning",
                "DNS resolver plan could not be applied to the running Core (rung=%s): %s",
                plan.rung,
                result.get("reason") if isinstance(result, dict) else result,
            )
            return False
        try:
            self._mark_core_export_sync_success()
        except Exception:
            pass
        self._notify_tier3_source_control_route_changed("dns_plan_applied")
        return True

    def _reset_dns_resolver_runtime_state(self) -> None:
        lock = getattr(self, "_dns_resolver_plan_lock", None)
        if lock is not None:
            with lock:
                self._dns_resolver_plan = None
                self._dns_resolver_fault_count = 0
                self._dns_resolver_fault_base = 0
                self._dns_resolver_fault_scope = None
                self._dns_resolver_fault_ignored = 0
                self._dns_resolver_control_failures = 0
                self._dns_resolver_control_checked_at = 0.0
        publish_active_dns_block(None)
        self._clear_source_supply_no_egress("runtime_reset")

    # ------------------------------------------------------------------
    # Network change watch: re-qualify when the link changes
    # ------------------------------------------------------------------

    def _start_dns_resolver_watch(self) -> None:
        if getattr(self, "_dns_resolver_plan_lock", None) is None:
            return
        worker = getattr(self, "_dns_resolver_watch_thread", None)
        if worker is not None and worker.is_alive():
            return
        thread = threading.Thread(
            target=self._dns_resolver_watch_loop, name="dns-resolver-watch", daemon=True,
        )
        self._dns_resolver_watch_thread = thread
        thread.start()

    def _dns_resolver_watch_loop(self) -> None:
        while not self.stop_event.wait(_DNS_RESOLVER_WATCH_INTERVAL_SECONDS):
            try:
                self._dns_resolver_watch_once()
            except Exception:
                log_raw_diagnostic(
                    self.logger, "warning", "DNS resolver network watch failed", exc_info=True,
                )

    def _dns_resolver_watch_once(self) -> bool:
        """Re-qualify after a link change; apply the rung by hot reload if needed."""

        plan = self._current_dns_resolver_plan()
        if plan is None or self.stop_event.is_set():
            return False
        link = discover_link_resolvers(
            excluded_adapter_names=self._dns_resolver_excluded_adapter_names(),
        )
        if link.error or not link.fingerprint or link.fingerprint == plan.qualification.fingerprint:
            return False
        renewed = self._prepare_dns_resolver_plan(reason="network_changed", force=True)
        if renewed is None or renewed is plan:
            return False
        state = getattr(self, "_source_supply_no_egress_state", None)
        if isinstance(state, dict) and state.get("active"):
            # A new network deserves an immediate retry, not the 300 s timer.
            self._retry_after_source_supply_no_egress()
            return True
        if dict(renewed.block) != dict(plan.block):
            self._apply_dns_resolver_plan_to_running_core(renewed)
        return True

    def refresh_dns_resolver_policy(self, reason: str = "settings_changed") -> dict[str, Any]:
        """Re-qualify after ``client.dns`` changed; the caller reloads the Core."""

        plan = self._prepare_dns_resolver_plan(reason=reason, force=True)
        if plan is None:
            return {}
        return self._dns_resolver_status_summary()

    def write_mihomo_bootstrap_runtime_config(self) -> Path:
        runtime_config_path = self.write_mihomo_runtime_config()
        if not runtime_config_path.is_file():
            raise RuntimeError("mihomo bootstrap config writer returned no file")
        formal_payload = runtime_config_path.read_text(encoding="utf-8")
        # The formal payload already carries this run's resolver rung, so the
        # bootstrap Core and the formal Core resolve names the same way.
        defer_geodata_rules = self._bootstrap_geodata_rules_deferred()
        payload = build_bootstrap_clash_config(
            formal_payload,
            egress_proxy=egress_proxy_block(self.config),
            defer_geodata_rules=defer_geodata_rules,
            # While GeoData is still to be downloaded through the pool, the
            # bootstrap Core also serves the listener that download uses.
            geodata_listener=(
                self._bootstrap_geodata_listener_spec(allocate=True)
                if defer_geodata_rules else None
            ),
        )
        if (
            defer_geodata_rules
            and runtime_config_text_uses_geodata(formal_payload)
            and not getattr(self, "_bootstrap_geodata_deferral_logged", False)
        ):
            self._bootstrap_geodata_deferral_logged = True
            self.logger.info(
                "GeoData is not downloaded yet; the bootstrap Core starts without "
                "GEOIP/GEOSITE rules and GeoData is fetched through the Bastion "
                "Layer pool before the formal Core loads the full rule list"
            )
        # The formal render's receipt map (its Gateway entries and their
        # selection decision), as the no-capture writer passes it: a map
        # replayed without the renderer's dialer-proxy drops every exit.
        route_lock = getattr(self, "_runtime_route_snapshot_lock", None)
        with route_lock if route_lock is not None else nullcontext():
            pending = getattr(self, "_runtime_pending_export_contract", None)
            formal_map = (
                copy.deepcopy(pending.get("proxy_map"))
                if isinstance(pending, dict) and isinstance(pending.get("proxy_map"), dict)
                else None
            )
        contract = (
            self._runtime_export_contract_for_payload(payload, rendered_proxy_map=formal_map)
            if formal_map is not None
            else self._runtime_export_contract_for_payload(payload)
        )
        written = self._write_mihomo_runtime_payload(payload, runtime_config_path)
        self._record_pending_runtime_export_contract(
            payload,
            written,
            contract=contract,
        )
        return written

    @staticmethod
    def _exit_route_binding_marker(route: dict[str, Any]) -> str:
        """Return the process-independent identity of one logical exit route."""

        selected_chain = (
            [str(item) for item in route.get("selected_chain", [])]
            if isinstance(route.get("selected_chain"), (list, tuple))
            else []
        )
        payload = {
            "route_marker": str(route.get("route_marker") or ""),
            "selected_chain": selected_chain,
            "leaf_proxy": str(route.get("leaf_proxy") or ""),
            "path_kind": str(route.get("path_kind") or "unknown"),
        }
        if not payload["route_marker"] and not selected_chain and not payload["leaf_proxy"]:
            existing = str(
                route.get("logical_binding_marker")
                or route.get("binding_marker")
                or ""
            ).strip()
            if existing:
                return existing
            return ""
        encoded = json.dumps(payload, ensure_ascii=True, sort_keys=True, separators=(",", ":"))
        return hashlib.sha256(encoded.encode("utf-8")).hexdigest()[:24]

    @staticmethod
    def _exit_route_execution_binding_marker(route: dict[str, Any]) -> str:
        """Return the generation-bound marker used only for stale-work CAS."""

        payload = {
            "logical_binding_marker": DesktopRuntime._exit_route_binding_marker(route),
            "core_instance": str(route.get("core_instance") or ""),
        }
        encoded = json.dumps(
            payload,
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
        )
        return hashlib.sha256(encoded.encode("utf-8")).hexdigest()[:24]

    @classmethod
    def _exit_routes_logically_match(
        cls,
        left: dict[str, Any],
        right: dict[str, Any],
    ) -> bool:
        if not isinstance(left, dict) or not isinstance(right, dict):
            return False
        left_marker = cls._exit_route_binding_marker(left)
        right_marker = cls._exit_route_binding_marker(right)
        return bool(left_marker and right_marker and left_marker == right_marker)

    @classmethod
    def _exit_quality_route_for_display(
        cls,
        route: dict[str, Any],
    ) -> dict[str, Any]:
        normalized = copy.deepcopy(route) if isinstance(route, dict) else {}
        existing_execution_marker = str(
            normalized.get("execution_binding_marker")
            or normalized.get("binding_marker")
            or ""
        ).strip()
        normalized["binding_marker"] = cls._exit_route_binding_marker(normalized)
        normalized["logical_binding_marker"] = normalized["binding_marker"]
        normalized["execution_binding_marker"] = (
            existing_execution_marker
            or cls._exit_route_execution_binding_marker(normalized)
        )
        return normalized

    def _invalidate_exit_route_context(self) -> None:
        lock = getattr(self, "_exit_quality_route_lock", None)
        if lock is None:
            self._exit_quality_route_cache = {}
            self._exit_quality_route_cache_at = 0.0
            self._exit_quality_route_cache_route_epoch = -1
            return
        with lock:
            self._exit_quality_route_cache = {}
            self._exit_quality_route_cache_at = 0.0
            self._exit_quality_route_cache_route_epoch = -1

    @staticmethod
    def _exit_quality_has_confirmed_identity(payload: dict[str, Any]) -> bool:
        identity = payload.get("identity")
        identity = identity if isinstance(identity, dict) else {}
        return any(
            isinstance(identity.get(family_name), dict)
            and str(identity[family_name].get("state") or "").strip().lower()
            == "confirmed"
            and bool(identity[family_name].get("ip"))
            for family_name in ("ipv4", "ipv6")
        )

    @staticmethod
    def _exit_quality_route_was_stable_and_confirmed(payload: dict[str, Any]) -> bool:
        route = payload.get("route")
        route = route if isinstance(route, dict) else {}
        confirmed = bool(
            route.get("confirmed")
            or (route.get("confirmed_before") and route.get("confirmed_after"))
        )
        return bool(confirmed and route.get("stable_during_check") is True)

    def _verify_final_exit_identity(self, *, request_id: str) -> dict[str, Any]:
        core_proxy_url = self._running_core_mixed_proxy_url()
        checked = self.exit_quality_service.check(
            proxy_url=core_proxy_url,
            request_id=request_id,
        )
        payload = (
            checked.to_dict()
            if hasattr(checked, "to_dict")
            else dict(checked)
        )
        if (
            self._exit_quality_has_confirmed_identity(payload)
            and self._exit_quality_route_was_stable_and_confirmed(payload)
        ):
            return payload
        diagnostics = payload.get("diagnostics")
        diagnostics = diagnostics if isinstance(diagnostics, dict) else {}
        recovery = diagnostics.get("egress_recovery")
        recovery = recovery if isinstance(recovery, dict) else {}
        source_errors = diagnostics.get("source_errors")
        source_error_text = ", ".join(
            str(item) for item in source_errors[:3]
        ) if isinstance(source_errors, list) else ""
        detail = str(
            recovery.get("state")
            or diagnostics.get("reason")
            or source_error_text
            or payload.get("state")
            or "identity unavailable"
        )
        raise RuntimeError(
            "FINAL-EXIT identity could not be confirmed on one stable route: "
            f"{detail}"
        )

    def _queue_final_exit_identity_diagnostic(self, *, request_id: str) -> None:
        """Run identity evidence after data-plane publication, never in its owner."""

        identity_lock = getattr(
            self,
            "_runtime_identity_diagnostic_lock",
            None,
        )
        if identity_lock is None:
            identity_lock = threading.Lock()
            self._runtime_identity_diagnostic_lock = identity_lock
        with identity_lock:
            current = getattr(
                self,
                "_runtime_identity_diagnostic_thread",
                None,
            )
            if current is not None and current.is_alive():
                return
            self._runtime_identity_diagnostic_generation = int(
                getattr(self, "_runtime_identity_diagnostic_generation", 0) or 0
            ) + 1
            generation = self._runtime_identity_diagnostic_generation
        try:
            worker_token: tuple[int, ...] | None = self._runtime_worker_token()
        except Exception:
            worker_token = None

        def worker() -> None:
            if (
                worker_token is not None
                and not self._runtime_worker_token_is_current(worker_token)
            ):
                return
            try:
                self._verify_final_exit_identity(request_id=request_id)
            except RuntimeError:
                # Missing/partial identity is a normal diagnostic outcome and
                # never changes data-plane health or user-visible recovery.
                return
            except Exception as exc:
                if self.stop_event.is_set():
                    return
                log_raw_diagnostic(
                    self.logger,
                    "warning",
                    "FINAL-EXIT identity diagnostic remained partial after "
                    "data-plane verification (generation=%s): %s",
                    generation,
                    exc,
                )
            finally:
                with identity_lock:
                    if (
                        getattr(
                            self,
                            "_runtime_identity_diagnostic_thread",
                            None,
                        )
                        is threading.current_thread()
                    ):
                        self._runtime_identity_diagnostic_thread = None

        thread = threading.Thread(
            target=worker,
            name="runtime-final-exit-identity",
            daemon=True,
        )
        with identity_lock:
            self._runtime_identity_diagnostic_thread = thread
        thread.start()

    def current_route_context(
        self,
        *,
        force: bool = False,
        timeout_seconds: float | None = None,
    ) -> dict[str, Any]:
        """Return the runtime-owned route binding used by exit-quality results."""
        now = time.monotonic()
        core_status = (
            self.core_runner.status()
            if self.core_runner
            else default_core_status()
        )
        core_running = (
            bool(core_status.get("running"))
            if isinstance(core_status, dict)
            else False
        )
        pid = core_status.get("pid") if isinstance(core_status, dict) else None
        core_instance = (
            f"{self._runtime_generation}:{self._core_generation}:{pid or '-'}"
        )
        route_snapshot_lock = getattr(self, "_runtime_route_snapshot_lock", None)
        if route_snapshot_lock is None:
            route_epoch_at_start = int(
                getattr(self, "_runtime_route_epoch", 0) or 0
            )
        else:
            with route_snapshot_lock:
                route_epoch_at_start = int(
                    getattr(self, "_runtime_route_epoch", 0) or 0
                )
        with self._exit_quality_route_lock:
            if (
                not force
                and self._exit_quality_route_cache
                and now - self._exit_quality_route_cache_at < 1.0
                and self._exit_quality_route_cache.get("core_instance") == core_instance
                and bool(self._exit_quality_route_cache.get("core_running"))
                == core_running
                and int(
                    getattr(
                        self,
                        "_exit_quality_route_cache_route_epoch",
                        -1,
                    )
                )
                == route_epoch_at_start
            ):
                return dict(self._exit_quality_route_cache)
        # Never hold the cache lock across controller I/O. An asynchronous
        # identity refresh may use an ordinary controller timeout, while the
        # manual data-plane path has a strict 1.5 second wall-clock budget.
        if core_running:
            try:
                route = dict(
                    inspect_runtime_route(
                        self.mihomo_proxies(
                            timeout_seconds=timeout_seconds
                        )
                        if timeout_seconds is not None
                        else self.mihomo_proxies()
                    )
                )
                route.update(
                    {
                        "path_kind": "mihomo_proxy",
                        "core_instance": core_instance,
                        "core_running": core_running,
                        "confirmed": not bool(route.get("facility_failure")),
                    }
                )
            except Exception as exc:
                route = {
                    "selected_chain": [],
                    "route_marker": "",
                    "leaf_proxy": "",
                    "path_kind": "mihomo_proxy",
                    "core_instance": core_instance,
                    "core_running": core_running,
                    "confirmed": False,
                    "facility_failure": str(exc),
                }
        else:
            marker_source = f"UNAVAILABLE|{self.network_mode}"
            route = {
                "selected_chain": [],
                "route_marker": hashlib.sha256(
                    marker_source.encode("utf-8")
                ).hexdigest()[:16],
                "leaf_proxy": "",
                "path_kind": "unavailable",
                "core_instance": core_instance,
                "core_running": core_running,
                "confirmed": False,
                "facility_failure": "mihomo core is not running",
            }
        latest_status = (
            self.core_runner.status()
            if self.core_runner
            else default_core_status()
        )
        latest_pid = (
            latest_status.get("pid")
            if isinstance(latest_status, dict)
            else None
        )
        latest_running = bool(
            latest_status.get("running")
            if isinstance(latest_status, dict)
            else False
        )
        latest_instance = (
            f"{self._runtime_generation}:{self._core_generation}:"
            f"{latest_pid or '-'}"
        )
        if latest_instance != core_instance or latest_running != core_running:
            route["confirmed"] = False
            route["facility_failure"] = (
                "mihomo Core changed during route snapshot"
            )
            route["core_instance"] = latest_instance
            route["core_running"] = latest_running
        if route_snapshot_lock is None:
            route_epoch_at_end = int(
                getattr(self, "_runtime_route_epoch", 0) or 0
            )
        else:
            with route_snapshot_lock:
                route_epoch_at_end = int(
                    getattr(self, "_runtime_route_epoch", 0) or 0
                )
        if route_epoch_at_end != route_epoch_at_start:
            route["confirmed"] = False
            route["facility_failure"] = (
                "FINAL-EXIT route changed during route snapshot"
            )
        route["runtime_route_epoch"] = route_epoch_at_end
        route_lock = getattr(self, "_runtime_route_snapshot_lock", None)
        if route_lock is None:
            # Keep the read-only route context usable for narrow diagnostic
            # adapters created without the full runtime constructor.  A
            # missing owner lock can never authorize fail-closed state.
            fail_closed_key = None
            loaded_snapshot = None
        else:
            with route_lock:
                fail_closed_key = getattr(
                    self,
                    "_runtime_confirmed_fail_closed_snapshot_key",
                    None,
                )
                loaded_snapshot = getattr(self, "_runtime_route_snapshot", None)
        route["fail_closed_confirmed"] = bool(
            str(route.get("leaf_proxy") or "").strip().upper() == "REJECT"
            and fail_closed_key is not None
            and loaded_snapshot is not None
            and tuple(loaded_snapshot.snapshot_key) == tuple(fail_closed_key)
        )
        leaf_proxy = str(route.get("leaf_proxy") or "").strip()
        if loaded_snapshot is not None and bool(route.get("confirmed")) and leaf_proxy:
            loaded_refs = [
                ref
                for ref in loaded_snapshot.proxy_nodes
                if ref.proxy_name == leaf_proxy
            ]
            if len(loaded_refs) == 1:
                # Manager policy may transiently report ``offline`` while the
                # running Core still has a verified managed leaf selected.
                # Expose that Core-loaded ownership independently; it is UI
                # truth only and grants no mutation or health authority.
                route["managed_tier"] = str(loaded_refs[0].tier)
                route["managed_pool_kind"] = str(loaded_refs[0].pool_kind)
        route["binding_marker"] = self._exit_route_binding_marker(route)
        route["logical_binding_marker"] = route["binding_marker"]
        route["execution_binding_marker"] = (
            self._exit_route_execution_binding_marker(route)
        )
        route["checked_at"] = utc_now_iso()
        with self._exit_quality_route_lock:
            if (
                self._exit_quality_route_cache_at > now
                and self._exit_quality_route_cache.get("core_instance")
                == route.get("core_instance")
                and bool(self._exit_quality_route_cache.get("core_running"))
                == bool(route.get("core_running"))
                and int(
                    getattr(
                        self,
                        "_exit_quality_route_cache_route_epoch",
                        -1,
                    )
                )
                == route_epoch_at_end
            ):
                return dict(self._exit_quality_route_cache)
            self._exit_quality_route_cache = dict(route)
            self._exit_quality_route_cache_at = now
            self._exit_quality_route_cache_route_epoch = route_epoch_at_end
        return dict(route)

    def _manual_identity_terminal_result(
        self,
        *,
        request_id: str,
        error: str,
        reason: str = "",
    ) -> dict[str, Any]:
        checked_at = utc_now_iso()
        return {
            "schema_version": 2,
            "request_id": str(request_id),
            "state": "unavailable",
            "checked_at": checked_at,
            "freshness": {
                "state": "fresh",
                "status": "failed",
                "reason": str(error or "data_plane_unavailable"),
            },
            "route": {},
            "identity": {},
            "error": str(error or "data_plane_unavailable"),
            "diagnostics": {
                "identity_pending": False,
                "data_plane_reason": str(reason or error or ""),
            },
        }

    def _manual_identity_needs_initial_admission(self) -> bool:
        if self._runtime_initial_activation_complete():
            return False
        if self._tier3_initial_activation_transaction_active():
            return True
        lifecycle_lock = getattr(self, "_core_lifecycle_lock", None)
        with lifecycle_lock if lifecycle_lock is not None else nullcontext():
            core_generation = int(getattr(self, "_core_generation", 0) or 0)
            admitted_generation = int(
                getattr(self, "_runtime_initial_activation_generation", -1) or -1
            )
        # Losing READY after a runtime failure does not undo this Core's
        # completed startup. The historical marker only selects the fresh
        # manual verifier; it grants neither READY nor identity authority.
        return core_generation <= 0 or admitted_generation != core_generation

    def _wait_for_manual_initial_egress_admission(
        self,
        *,
        deadline_monotonic: float,
    ) -> tuple[bool, str]:
        """Attach one overview request to the sole pre-READY lease."""

        if self._runtime_initial_activation_complete():
            return True, ""
        runner = getattr(self, "core_runner", None)
        if runner is None or not runner.is_running():
            return False, "core_not_running"
        admission_active = self._tier3_initial_activation_transaction_active()
        phase = self._current_core_runtime_phase()
        if phase != "formal_no_capture" and not (
            phase == "formal_capture" and admission_active
        ):
            return False, "runtime_route_not_ready"

        # A user request is explicit new evidence and may reopen a previously
        # terminal immutable startup key.  It still converges on the one active
        # lease, so repeated clicks cannot create another verifier.
        # Admission publishes capture just before READY. Attach to that
        # existing transaction even during its final capture commit.
        if not admission_active:
            self._reset_tier3_standby_activation_failure()
            self._request_initial_egress_admission()
        while time.monotonic() < float(deadline_monotonic):
            if self._runtime_initial_activation_complete():
                return True, ""
            readiness = getattr(self, "_runtime_egress_readiness", None)
            with self._tier3_egress_activation_lock:
                admission_active = bool(
                    self._tier3_egress_activation_pending
                    or self._tier3_egress_activation_worker_running
                    or self._tier3_egress_activation_active_mode
                )
            if not admission_active and not bool(
                getattr(readiness, "validation_active", False)
            ):
                reason = str(getattr(readiness, "reason", "") or "")
                return False, reason or "initial_egress_admission_failed"
            remaining = float(deadline_monotonic) - time.monotonic()
            if remaining <= 0.0:
                break
            if self.stop_event.wait(min(0.02, remaining)):
                return False, "runtime_stop_requested"
        return False, "initial_egress_admission_pending"

    @staticmethod
    def _overview_identity_progress(
        callback: Callable[[dict[str, Any]], None] | None,
        *,
        request_id: str,
        phase: str,
        attempt: int,
        reason: str = "",
    ) -> None:
        if callback is None:
            return
        payload: dict[str, Any] = {
            "request_id": str(request_id), "phase": phase, "attempt": int(attempt),
        }
        if reason:
            payload["reason"] = reason
        try:
            callback(payload)
        except Exception:
            # Presentation callbacks cannot alter the authoritative validation.
            pass

    def _check_current_exit_identity_early(
        self,
        *,
        proxy_url: str | None,
        request_id: str,
        timeout_seconds: float,
        deadline_monotonic: float | None = None,
        progress_callback: Callable[[dict[str, Any]], None] | None = None,
    ) -> dict[str, Any]:
        """Reprove an automatically settled route within this one request."""

        started = time.monotonic()
        deadline = started + min(8.0, max(0.0, float(timeout_seconds)))
        if deadline_monotonic is not None:
            deadline = min(deadline, float(deadline_monotonic))
        execution_epoch = self._manual_identity_execution_epoch()
        selector_intent = int(
            getattr(self, "_runtime_selector_intent_revision", 0) or 0
        )

        def core_process_owner() -> tuple[Any, ...] | None:
            runner = getattr(self, "core_runner", None)
            status_reader = getattr(runner, "status", None)
            if not callable(status_reader):
                return None
            try:
                status = status_reader()
                return (
                    bool(status.get("running")), status.get("pid"),
                    status.get("process_generation"),
                )
            except Exception:
                return None

        process_owner = core_process_owner()
        retry_reasons: list[str] = []
        for attempt in range(1, 4):
            if time.monotonic() >= deadline:
                return self._manual_identity_terminal_result(
                    request_id=request_id, error="validation_timeout",
                )
            result = self._check_current_exit_identity_early_once(
                proxy_url=proxy_url,
                request_id=request_id,
                deadline_monotonic=deadline,
                progress_callback=progress_callback,
                attempt=attempt,
            )
            freshness = result.get("freshness") or {}
            reason = str(result.get("error") or freshness.get("reason") or "")
            state = str(result.get("state") or "")
            diagnostics = result.get("diagnostics") or {}
            probe_reasons = diagnostics.get("probe_indeterminate_reasons") or []
            transient_probe_busy = bool(
                state == "data_plane_indeterminate"
                and probe_reasons
                and all(value in {"queue_timeout", "started_timeout"} for value in probe_reasons)
            )
            ownership_unsettled = bool(
                (
                    state == "data_plane_indeterminate"
                    and reason in {
                        "route_settled_during_check",
                        "manual_execution_binding_unverified",
                    }
                )
                or (
                    state in {"stale", "unavailable", "route_changed"}
                    and reason in {
                        "validated_route_changed",
                        "route_unconfirmed",
                        "manual_validation_execution_changed",
                        "route_changed",
                    }
                )
            )
            request_current = bool(
                execution_epoch == self._manual_identity_execution_epoch()
                and process_owner == core_process_owner()
                and not bool(
                    (result.get("diagnostics") or {}).get(
                        "identity_execution_owner_changed"
                    )
                )
                and selector_intent == int(
                    getattr(self, "_runtime_selector_intent_revision", 0) or 0
                )
                and not (
                    getattr(self, "stop_event", None) is not None
                    and self.stop_event.is_set()
                )
            )
            if (
                (ownership_unsettled or transient_probe_busy) and request_current
                and not any(value in {"cancelled", "broker_stopped", "broker_poisoned"}
                            for value in probe_reasons)
                and attempt < 3 and deadline - time.monotonic() >= 1.0
            ):
                # A native fallback switch invalidates the old sockets and IP.
                # Start a fresh canonical proof for the new binding; never
                # reuse evidence, extend the UI deadline or alter tier policy.
                retry_reasons.append(reason)
                self._overview_identity_progress(
                    progress_callback, request_id=request_id, phase="retrying",
                    attempt=attempt + 1, reason="probe_busy" if transient_probe_busy else reason,
                )
                continue
            diagnostics = dict(result.get("diagnostics") or {})
            diagnostics["overview_validation_attempts"] = attempt
            if retry_reasons:
                diagnostics["overview_validation_retry_reasons"] = retry_reasons
            return {**result, "diagnostics": diagnostics}
        raise AssertionError("overview validation attempt limit was not enforced")

    def _check_current_exit_identity_early_once(
        self,
        *,
        proxy_url: str | None,
        request_id: str,
        deadline_monotonic: float,
        progress_callback: Callable[[dict[str, Any]], None] | None = None,
        attempt: int = 1,
    ) -> dict[str, Any]:
        """Run the overview action against the proven Windows host path.

        The previous observational implementation could obtain an IP through
        an explicit ``127.0.0.1`` proxy while Windows system proxy capture was
        inactive.  That made the button report success although normal browser
        traffic had no usable path.  An admitted Core uses the canonical
        two-contract validation/fallback transaction even after losing READY;
        startup requests attach to the sole admission instead of manufacturing
        an identity result.
        """

        started = time.monotonic()
        deadline = float(deadline_monotonic)
        execution_epoch = self._manual_identity_execution_epoch()
        selector_intent = int(getattr(self, "_runtime_selector_intent_revision", 0) or 0)
        speculation: _OverviewIdentitySpeculation | None = None
        if self._manual_identity_needs_initial_admission():
            self._overview_identity_progress(
                progress_callback, request_id=request_id,
                phase="waiting_connection", attempt=attempt,
            )
            # Stop waiting early enough that an admission committing late in
            # this window still leaves the identity lookup a real budget. The
            # admission keeps its own deadline and may finish after this
            # request; the UI then resumes the lookup on the status change.
            attached_deadline = max(
                started, deadline - _OVERVIEW_ADMISSION_ATTACH_IDENTITY_RESERVE_SECONDS,
            )
            ready, reason = self._wait_for_manual_initial_egress_admission(
                deadline_monotonic=attached_deadline,
            )
            if not ready:
                error = (
                    "initial_egress_admission_pending"
                    if reason == "initial_egress_admission_pending"
                    else "initial_egress_admission_failed"
                )
                return self._manual_identity_terminal_result(
                    request_id=request_id,
                    error=error,
                    reason=reason,
                )
            # This exact admission has already proved selector, full chain,
            # system-proxy readback and a fresh host connection.  Do not spend
            # the remainder of the overview deadline probing it a second time.
            execution_epoch = self._manual_identity_execution_epoch()
            route = self._exit_quality_route_for_display(
                self.current_route_context(force=True, timeout_seconds=0.05)
            )
            if (
                execution_epoch != self._manual_identity_execution_epoch()
                or not self._runtime_initial_activation_complete()
            ):
                return self._manual_identity_terminal_result(
                    request_id=request_id, error="manual_validation_execution_changed",
                )
            validation = {
                "schema_version": 2,
                "request_id": str(request_id),
                "state": "pending_identity",
                "checked_at": utc_now_iso(),
                "freshness": {"state": "fresh", "status": "partial"},
                "route": route,
                "identity": {},
                "diagnostics": {
                    "identity_pending": True,
                    "overview_validation_ms": round((time.monotonic() - started) * 1000),
                    "overview_validation_source": "admission",
                    "neutral_connectivity": {
                        "state": "ok",
                        "source": "initial_egress_admission",
                    },
                    "system_proxy_capture": {
                        "required": self._system_proxy_capture_proof_required(),
                        "target_active": True,
                        "host_path_verified": True,
                    },
                },
            }

        else:
            self._overview_identity_progress(
                progress_callback, request_id=request_id,
                phase="validating_route", attempt=attempt,
            )
            remaining = max(0.0, deadline - time.monotonic())
            if remaining <= 0.10:
                return self._manual_identity_terminal_result(
                    request_id=request_id,
                    error="manual_validation_deadline_expired",
                )
            lease = ManualValidationLease(
                request_id=str(request_id),
                lifecycle_revision=int(getattr(self, "_lifecycle_revision", 0) or 0),
                route_epoch=int(getattr(self, "_runtime_route_epoch", 0) or 0),
                network_context_epoch=int(
                    getattr(self, "_runtime_network_context_epoch", 0) or 0
                ),
                deadline_monotonic=deadline,
            )
            validation_started = time.monotonic()
            speculation = self._start_overview_identity_speculation(
                proxy_url=proxy_url, deadline_monotonic=deadline,
            )
            try:
                validation = self.check_exit_quality(
                    proxy_url=proxy_url,
                    request_id=request_id,
                    manual_validation_lease=lease,
                    queue_identity_diagnostic=False,
                )
            except BaseException:
                if speculation is not None:
                    speculation.abandon()
                raise
            if speculation is not None:
                speculation.release.set()
            validation = {
                **validation,
                "diagnostics": {
                    **(validation.get("diagnostics") or {}),
                    "overview_validation_ms": round(
                        (time.monotonic() - validation_started) * 1000
                    ),
                    "overview_validation_source": "canonical",
                },
            }

        # The overview owns one bounded request, not the asynchronous quality
        # service's cache. Never return its intermediate pending_identity state
        # or let a previous request's identity stand in for this observation.
        warning_reason = ""
        if str(validation.get("state") or "") != "pending_identity":
            warning_reason = self._overview_usable_exit_warning(validation)
            if not warning_reason:
                if speculation is not None:
                    # Never publish anything a failed proof's lookup saw.
                    speculation.abandon()
                    validation = {
                        **validation,
                        "diagnostics": {
                            **(validation.get("diagnostics") or {}),
                            "identity_speculation": {
                                "state": "discarded", "reason": "validation_not_usable",
                            },
                        },
                    }
                return {**validation, "identity": {}}
        neutral = (validation.get("diagnostics") or {}).get("neutral_connectivity") or {}
        if speculation is not None and neutral.get("switch_committed"):
            # The proof switched to another leaf; the speculation measured
            # the old one. Collect afresh on the new binding.
            speculation.abandon()
            speculation = None
        if (
            execution_epoch != self._manual_identity_execution_epoch()
            or selector_intent != int(getattr(self, "_runtime_selector_intent_revision", 0) or 0)
        ):
            if speculation is not None:
                speculation.abandon()
            return self._manual_identity_terminal_result(
                request_id=request_id, error="manual_validation_execution_changed",
            )
        remaining = deadline - time.monotonic() - 0.05
        if remaining <= 0.10:
            if speculation is not None:
                speculation.abandon()
            if warning_reason:
                return {**validation, "identity": {}}
            return {
                **validation, "state": "unavailable", "identity": {},
                "error": "identity_deadline_expired",
            }
        self._overview_identity_progress(
            progress_callback, request_id=request_id,
            phase="querying_identity", attempt=attempt,
        )
        try:
            result = self._collect_current_exit_identity(
                proxy_url=proxy_url,
                request_id=request_id,
                timeout_seconds=remaining,
                proven_route=validation.get("route") or {},
                deadline_monotonic=deadline - 0.05,
                speculation=speculation,
            )
        finally:
            if speculation is not None:
                speculation.abandon()
        diagnostics = dict(validation.get("diagnostics") or {})
        diagnostics.update(result.get("diagnostics") or {})
        diagnostics["identity_pending"] = False
        if warning_reason:
            result_state = str(result.get("state") or "")
            if result_state in {"route_changed", "stale"}:
                return {**validation, **result, "diagnostics": diagnostics}
            if result_state != "complete":
                # Without an identity, the failed proof remains the most
                # actionable explanation for this request.
                return {**validation, "identity": {}, "diagnostics": diagnostics}
            diagnostics["overview_warning_reason"] = warning_reason
            return {
                **validation, **result, "state": "partial",
                "diagnostics": diagnostics,
            }
        return {**validation, **result, "diagnostics": diagnostics}

    @staticmethod
    def _overview_usable_exit_warning(validation: dict[str, Any]) -> str:
        """Name a secondary proof failure on an exit that still carried traffic.

        At least one fresh HTTPS contract completed over the unchanged,
        confirmed execution binding, so an identity observed through that
        route is real. The overview shows it with this qualifier; it never
        promotes readiness or counts as a verified result.
        """

        if str(validation.get("state") or "") != "data_plane_failed":
            return ""
        route = validation.get("route")
        route = route if isinstance(route, dict) else {}
        if route.get("confirmed") is not True or route.get("stable_during_check") is False:
            return ""
        diagnostics = validation.get("diagnostics")
        diagnostics = diagnostics if isinstance(diagnostics, dict) else {}
        neutral = diagnostics.get("neutral_connectivity")
        neutral = neutral if isinstance(neutral, dict) else {}
        if (
            neutral.get("execution_binding_current") is not True
            or neutral.get("switch_committed")
        ):
            return ""
        try:
            success_count = int(neutral.get("success_count") or 0)
        except (TypeError, ValueError):
            return ""
        if success_count <= 0:
            return ""
        capture = diagnostics.get("system_proxy_capture")
        capture = capture if isinstance(capture, dict) else {}
        if capture.get("required") is True and capture.get("target_active") is False:
            return "system_proxy_capture_inactive"
        if success_count == 1:
            return (
                "partial_validation"
                if neutral.get("outcome") == "current_mixed"
                else ""
            )
        if capture.get("required") is True and capture.get("host_path_verified") is False:
            return "system_proxy_host_path_unverified"
        return ""

    def _manual_identity_execution_epoch(self) -> tuple[int, ...]:
        # A canonical manual check may legitimately switch the selected route.
        # Core/lifecycle/network changes still invalidate its proof entirely.
        return tuple(int(getattr(self, name, 0) or 0) for name in (
            "_lifecycle_revision", "_runtime_generation", "_core_generation",
            "_runtime_network_context_epoch",
        ))

    def check_current_exit_identity(
        self,
        *,
        proxy_url: str | None,
        request_id: str,
        timeout_seconds: float = 8.0,
        deadline_monotonic: float | None = None,
        progress_callback: Callable[[dict[str, Any]], None] | None = None,
        trigger: str = "manual",
        expected_binding_marker: str = "",
        route_source: str = "live",
    ) -> dict[str, Any]:
        """Return one request-bound exit result.

        The bounded recovery profile requires a fresh data-plane and host
        capture proof before identity is allowed to represent success.  Legacy
        profiles retain the observational compatibility behavior below.

        ``trigger`` records who asked: ``manual`` (a click), ``deferred`` (a
        click resumed once the connection was ready) or ``auto``. An automatic
        request never runs the canonical validation: it only reads identity
        through a route the runtime already holds READY (see
        ``_observe_current_exit_identity_once``).

        ``route_source`` (T-P2-RT2, Fallback 10-06 ruling) applies to
        automatic lookups only. ``"live"`` (the default, Qt) keeps the route
        readback of ``current_route_context``. ``"published"`` (the sidecar
        bridge) reads only the published route snapshot: no ``GET /proxies``
        and no route refresh; without a published route the lookup is
        ``route_unconfirmed`` and sends nothing.
        """

        started = time.monotonic()
        trigger = trigger if trigger in {"manual", "deferred", "auto"} else "manual"
        published_route = trigger == "auto" and route_source == "published"
        timeout = float(timeout_seconds)
        if not math.isfinite(timeout):
            raise ValueError("timeout_seconds must be finite")
        deadline = started + min(8.0, max(0.0, timeout))
        if deadline_monotonic is not None:
            absolute_deadline = float(deadline_monotonic)
            if not math.isfinite(absolute_deadline):
                raise ValueError("deadline_monotonic must be finite")
            deadline = min(deadline, absolute_deadline)
        if deadline <= started:
            result = self._manual_identity_terminal_result(
                request_id=request_id, error="validation_timeout",
            )
        elif trigger == "auto" and self._runtime_uses_early_single_coordinator():
            result = self._observe_current_exit_identity_once(
                proxy_url=proxy_url,
                request_id=request_id,
                deadline_monotonic=deadline,
                progress_callback=progress_callback,
                expected_binding_marker=expected_binding_marker,
                published_route=published_route,
            )
        elif self._runtime_uses_early_single_coordinator():
            result = self._check_current_exit_identity_early(
                proxy_url=proxy_url,
                request_id=request_id,
                timeout_seconds=max(0.0, deadline - time.monotonic()),
                deadline_monotonic=deadline,
                progress_callback=progress_callback,
            )
        elif published_route and self._published_exit_route_context() is None:
            # T-P2-RT2 (Fallback 10-06 ruling): without a published route an
            # automatic lookup is unknown and sends nothing.
            result = self._manual_identity_terminal_result(
                request_id=request_id, error="route_unconfirmed",
            )
        else:
            self._overview_identity_progress(
                progress_callback, request_id=request_id,
                phase="querying_identity", attempt=1,
            )
            result = self._collect_current_exit_identity(
                proxy_url=proxy_url, request_id=request_id,
                timeout_seconds=max(0.0, deadline - time.monotonic()),
                deadline_monotonic=deadline,
                published_route_only=published_route,
            )
        completed = time.monotonic()
        diagnostics = dict(result.get("diagnostics") or {})
        freshness = result.get("freshness") or {}
        reason = str(result.get("error") or freshness.get("reason") or "")
        probe_reasons = diagnostics.get("probe_indeterminate_reasons") or []
        neutral = diagnostics.get("neutral_connectivity") or {}
        if result.get("state") == "data_plane_failed":
            outcome = str(neutral.get("outcome") or "")
            if outcome in {"current_mixed", "non_node_failure"}:
                reason = "partial_validation" if outcome == "current_mixed" else "probe_target_error"
                result = {**result, "state": "partial", "error": reason}
            elif (
                neutral.get("route_contract_leaf_failure") is True
                and str(neutral.get("state") or "") == "mixed"
                and outcome in {"backup_required", "backup_unavailable", "invalid_contract"}
            ):
                # P0-4: the leaf failed its owning group's contract while the
                # neutral endpoint answered, and no backup was proven.
                reason = "route_contract_failed"
            elif not reason and str(neutral.get("state") or "") == "failed":
                # Both independent contracts failed and no backup took over.
                reason = "exit_unreachable"
        if probe_reasons and result.get("state") == "data_plane_indeterminate":
            if any(value in {"cancelled", "broker_stopped"} for value in probe_reasons):
                reason = "validation_cancelled"
            elif "broker_poisoned" in probe_reasons:
                reason = "probe_unavailable"
            elif all(value in {"queue_timeout", "started_timeout"} for value in probe_reasons):
                reason = "probe_busy"
        reason = {
            "manual_validation_deadline_expired": "validation_timeout",
            "identity_deadline_expired": "identity_timeout",
            "initial_egress_admission_pending": "waiting_connection",
            "initial_egress_admission_failed": "connection_not_ready",
            "validated_route_changed": "route_changed",
            "route_settled_during_check": "route_changed",
        }.get(reason, reason)
        if completed > deadline and (
            result.get("state") == "complete"
            or (result.get("state") == "partial" and diagnostics.get("overview_warning_reason"))
        ):
            result = {**result, "state": "unavailable", "identity": {}, "error": "validation_timeout"}
            diagnostics.pop("overview_warning_reason", None)
            reason = "validation_timeout"
        if reason and reason not in {"manual_lookup", "auto_lookup", "none"}:
            diagnostics["overview_failure_reason"] = reason
        diagnostics["overview_trigger"] = trigger
        result = {**result, "diagnostics": diagnostics, "completed_monotonic": completed}
        logger = getattr(self, "logger", None)
        if logger is not None:
            freshness = result.get("freshness") or {}
            route = result.get("route") or {}
            diagnostics = result.get("diagnostics") or {}
            neutral = diagnostics.get("neutral_connectivity") or {}
            collection = diagnostics.get("identity_collection") or {}
            # Keep manual results diagnosable without logging the public IP,
            # location, proxy URL or controller payload.
            log_raw_diagnostic(
                logger, "info",
                "Overview identity request completed (request=%s trigger=%s state=%s "
                "reason=%s route_confirmed=%s elapsed_ms=%d "
                "validation_attempts=%s validation_ms=%s validation_source=%s "
                "per_probe_ms=%s contract_failures=%s switch_reason=%s "
                "identity_attempts=%s providers=%s "
                "data_plane_reason=%s identity_ms=%s identity_completion=%s "
                "identity_first_ok_ms=%s identity_answer_family=%s "
                "identity_families=%s overview_reason=%s overview_warning=%s "
                "probe_reasons=%s provider_outcomes=%s)",
                str(request_id), trigger, str(result.get("state") or "unavailable"),
                str(result.get("error") or freshness.get("reason") or "none"),
                bool(route.get("confirmed")),
                round((time.monotonic() - started) * 1000),
                diagnostics.get("overview_validation_attempts", 1),
                diagnostics.get("overview_validation_ms", "none"),
                diagnostics.get("overview_validation_source", "none"),
                neutral.get("per_probe_ms", "none"),
                neutral.get("contract_failure_kinds", []),
                str(neutral.get("switch_reason") or "none"),
                diagnostics.get("identity_collection_attempts", 0),
                diagnostics.get("identity_provider_status", {}),
                str(diagnostics.get("data_plane_reason") or "none"),
                collection.get("elapsed_ms", "not_run"),
                collection.get("completion_reason", "not_run"),
                collection.get("first_ok_ms", "not_run"),
                collection.get("answer_family", "none"),
                diagnostics.get("identity_family_states", {}),
                diagnostics.get("overview_failure_reason", "none"),
                diagnostics.get("overview_warning_reason", "none"),
                diagnostics.get("probe_indeterminate_reasons", []),
                diagnostics.get("identity_provider_outcomes", []),
            )
        return result

    def _overview_identity_speculation_enabled(self) -> bool:
        override = getattr(self, "_overview_identity_speculation_override", None)
        if override is not None:
            return bool(override)
        value = str(os.environ.get(_OVERVIEW_IDENTITY_SPECULATION_ENV, "") or "")
        return value.strip().casefold() in {"1", "true", "yes", "on"}

    def _start_overview_identity_speculation(
        self,
        *,
        proxy_url: str | None,
        deadline_monotonic: float,
    ) -> _OverviewIdentitySpeculation | None:
        """Start the identity lookup alongside the canonical validation.

        Off by default. The lookup is held open until the validation returns
        (``release``) and is published only through the normal gates.
        """

        if not proxy_url or not self._overview_identity_speculation_enabled():
            return None
        deadline = float(deadline_monotonic)
        budget = deadline - 0.05 - 0.35 - time.monotonic()
        if budget <= 0.5:
            return None
        for _provider, _family, provider_url in OVERVIEW_IDENTITY_PROVIDERS:
            self._register_runtime_internal_probe(provider_url, timeout_seconds=budget)
        speculation = _OverviewIdentitySpeculation(
            execution_epoch=self._manual_identity_execution_epoch(),
            route_epoch=int(getattr(self, "_runtime_route_epoch", 0) or 0),
            selector_intent=int(getattr(self, "_runtime_selector_intent_revision", 0) or 0),
        )

        def run() -> None:
            try:
                try:
                    route = dict(self.current_route_context(force=True, timeout_seconds=0.35))
                except Exception:
                    route = {}
                if route.get("confirmed") is not True or speculation.cancel.is_set():
                    return
                speculation.route_before = route
                remaining = deadline - 0.05 - 0.35 - time.monotonic()
                if remaining <= 0.05:
                    return
                speculation.result = collect_exit_identity(
                    proxy_url=proxy_url,
                    timeout_seconds=remaining,
                    total_timeout_seconds=remaining,
                    providers=OVERVIEW_IDENTITY_PROVIDERS,
                    rounds=1,
                    max_workers=len(OVERVIEW_IDENTITY_PROVIDERS),
                    retry_transient_errors=True,
                    answer_policy=OVERVIEW_ANSWER_POLICY,
                    not_before=speculation.release,
                    cancel=speculation.cancel,
                )
            except Exception as exc:
                speculation.error = type(exc).__name__
            finally:
                speculation.done.set()

        threading.Thread(target=run, name="overview-identity-speculation", daemon=True).start()
        return speculation

    def _overview_deferral_status_fields(self) -> dict[str, Any]:
        """Hints that let a waiting overview click resume on the right event.

        They only feed a UI resume signature, so they are read without the
        lifecycle or admission locks: status() must never block on them.
        """
        try:
            return {
                "core_runtime_phase": str(getattr(self, "_core_runtime_phase", "") or ""),
                "initial_admission_active": bool(
                    getattr(self, "_tier3_egress_activation_pending", False)
                    or getattr(self, "_tier3_egress_activation_worker_running", False)
                    or str(getattr(self, "_tier3_egress_activation_active_mode", "") or "")
                    == "activation"
                ),
            }
        except Exception:
            return {}

    def _overview_auto_identity_token(self) -> tuple[Any, ...] | None:
        """Identity of the READY state an automatic lookup may rely on.

        None means no automatic lookup may run: the runtime has not committed
        READY for this Core, is re-validating, or is stopping. SERVING is not
        enough because controller attribution may still be catching up.
        """

        if not self._runtime_initial_activation_complete():
            return None
        runner = getattr(self, "core_runner", None)
        if runner is None or not runner.is_running():
            return None
        stop_event = getattr(self, "stop_event", None)
        if stop_event is not None and stop_event.is_set():
            return None
        readiness = getattr(self, "_runtime_egress_readiness", None)
        return (
            int(getattr(readiness, "lifecycle_revision", 0) or 0),
            int(getattr(readiness, "route_epoch", 0) or 0),
            int(getattr(readiness, "network_context_epoch", 0) or 0),
            *self._manual_identity_execution_epoch(),
            int(getattr(self, "_runtime_selector_intent_revision", 0) or 0),
        )

    def _observe_current_exit_identity_once(
        self,
        *,
        proxy_url: str | None,
        request_id: str,
        deadline_monotonic: float,
        progress_callback: Callable[[dict[str, Any]], None] | None = None,
        expected_binding_marker: str = "",
        published_route: bool = False,
    ) -> dict[str, Any]:
        """Read the exit identity of the READY route without validating it.

        Used for automatic lookups only. It never runs the two-contract
        validation, never switches a selector and never promotes or demotes
        readiness. The READY token must be the same before and after, and the
        identity keeps the usual before/after route readback.

        ``published_route`` (T-P2-RT2, sidecar bridge only): every route read
        comes from the published route snapshot instead of
        ``current_route_context``; the default keeps the Qt behavior.
        """

        deadline = float(deadline_monotonic)
        token = self._overview_auto_identity_token()
        if token is None:
            return self._manual_identity_terminal_result(
                request_id=request_id, error="auto_not_ready",
            )
        remaining = deadline - time.monotonic()
        try:
            if published_route:
                # T-P2-RT2 (Fallback 10-06 ruling): the bridge's automatic
                # lookup reads only the published route snapshot -- never
                # GET /proxies or a route refresh; its only network traffic
                # is the IP echo through the mixed port.
                published = self._published_exit_route_context()
                route = self._exit_quality_route_for_display(published) if published else {}
            else:
                route = self._exit_quality_route_for_display(
                    self.current_route_context(
                        force=True, timeout_seconds=max(0.0, min(0.35, remaining)),
                    )
                )
        except Exception:
            route = {}
        if (
            route.get("confirmed") is not True
            or route.get("facility_failure")
            or str(route.get("path_kind") or "") == "unavailable"
            or str(route.get("leaf_proxy") or "").strip().upper() == "REJECT"
        ):
            return self._manual_identity_terminal_result(
                request_id=request_id, error="route_unconfirmed",
            )
        expected = str(expected_binding_marker or "").strip()
        if expected and expected != str(route.get("binding_marker") or "").strip():
            # The route the UI asked about is gone; never measure another one.
            return {
                **self._manual_identity_terminal_result(
                    request_id=request_id, error="route_changed",
                ),
                "state": "stale",
            }
        warning_reason = ""
        if self._system_proxy_capture_proof_required():
            try:
                capture_active = bool(self.system_proxy.is_target_active())
            except Exception:
                capture_active = False
            if not capture_active:
                warning_reason = "system_proxy_capture_inactive"
        self._overview_identity_progress(
            progress_callback, request_id=request_id,
            phase="querying_identity", attempt=1,
        )
        result = self._collect_current_exit_identity(
            proxy_url=proxy_url,
            request_id=request_id,
            timeout_seconds=max(0.0, deadline - time.monotonic() - 0.05),
            proven_route=route,
            deadline_monotonic=deadline - 0.05,
            published_route_only=published_route,
        )
        diagnostics = {
            **(result.get("diagnostics") or {}),
            "overview_validation_source": "readiness",
        }
        if self._overview_auto_identity_token() != token:
            return {
                **result,
                "state": "unavailable",
                "identity": {},
                "error": "auto_ready_lost",
                "diagnostics": diagnostics,
            }
        freshness = dict(result.get("freshness") or {})
        if freshness.get("reason") == "manual_lookup":
            freshness["reason"] = "auto_lookup"
        if str(result.get("state") or "") == "complete" and warning_reason:
            diagnostics["overview_warning_reason"] = warning_reason
            return {**result, "state": "partial", "freshness": freshness, "diagnostics": diagnostics}
        return {**result, "freshness": freshness, "diagnostics": diagnostics}

    def _collect_current_exit_identity(
        self,
        *,
        proxy_url: str | None,
        request_id: str,
        timeout_seconds: float,
        proven_route: dict[str, Any] | None = None,
        deadline_monotonic: float | None = None,
        speculation: _OverviewIdentitySpeculation | None = None,
        published_route_only: bool = False,
    ) -> dict[str, Any]:
        """Collect a terminal identity bound to the route that was validated.

        A ``speculation`` already running for this request is consumed only
        when its route and execution snapshot equal the proven ones; any
        mismatch cancels it and collects afresh.

        ``published_route_only`` (T-P2-RT2, automatic lookups): the
        before/after route readbacks come from the published route snapshot
        (``_published_exit_route_context``) instead of
        ``current_route_context`` (GET /proxies); unknown reads as {}.
        """

        started = time.monotonic()
        # The canonical overview has already budgeted the entire request. Use
        # its remaining window rather than imposing a second, shorter deadline
        # that turns a healthy but slow identity endpoint into a failed check.
        total_timeout = min(
            8.0 if proven_route is not None else 3.0,
            max(0.0, float(timeout_seconds)),
        )
        deadline = started + total_timeout
        if deadline_monotonic is not None:
            deadline = min(deadline, float(deadline_monotonic))
        if deadline <= started:
            return self._manual_identity_terminal_result(
                request_id=request_id, error="identity_deadline_expired",
            )
        execution_epoch = self._manual_identity_execution_epoch()
        route_epoch = int(getattr(self, "_runtime_route_epoch", 0) or 0)
        selector_intent = int(getattr(self, "_runtime_selector_intent_revision", 0) or 0)

        def remaining(cap: float) -> float:
            return max(0.0, min(float(cap), deadline - time.monotonic()))

        def route_context(cap: float) -> dict[str, Any]:
            available = remaining(cap)
            if available <= 0.0:
                return {}
            if published_route_only:
                try:
                    return dict(self._published_exit_route_context() or {})
                except Exception:
                    return {}
            try:
                return dict(
                    self.current_route_context(
                        force=True,
                        timeout_seconds=available,
                    )
                )
            except TypeError:
                # Narrow test adapters may still expose the old signature.
                return dict(self.current_route_context(force=True))
            except Exception:
                return {}

        speculative: _OverviewIdentitySpeculation | None = None
        speculation_state: dict[str, Any] | None = None
        if speculation is not None:
            spec_route = speculation.route_before
            if (
                proven_route is not None
                and proxy_url
                and spec_route
                and proven_route.get("confirmed")
                and speculation.execution_epoch == execution_epoch
                and speculation.route_epoch == route_epoch
                and speculation.selector_intent == selector_intent
                and self._exit_routes_logically_match(proven_route, spec_route)
                and self._exit_route_execution_binding_marker(proven_route)
                == self._exit_route_execution_binding_marker(spec_route)
            ):
                speculative = speculation
                speculation_state = {"state": "used"}
            else:
                speculation.abandon()
                speculation_state = {"state": "discarded", "reason": "binding_changed"}
        route_before = speculative.route_before if speculative is not None else route_context(0.35)
        if proven_route is not None and (
            not proven_route.get("confirmed")
            or not self._exit_routes_logically_match(proven_route, route_before)
            or self._exit_route_execution_binding_marker(proven_route)
            != self._exit_route_execution_binding_marker(route_before)
        ):
            return {
                "schema_version": 2, "request_id": str(request_id),
                "state": "stale", "checked_at": utc_now_iso(), "identity": {},
                "route": {}, "error": "validated_route_changed",
                "freshness": {"state": "stale", "reason": "validated_route_changed"},
                "diagnostics": {"identity_execution_owner_changed": bool(
                    execution_epoch != self._manual_identity_execution_epoch()
                    or (proven_route.get("core_instance") and route_before.get("core_instance")
                        and proven_route["core_instance"] != route_before["core_instance"])
                )},
            }
        providers = (
            OVERVIEW_IDENTITY_PROVIDERS if proven_route is not None else EXIT_IDENTITY_PROVIDERS
        )
        if speculative is None:
            # A speculation registered its providers before opening sockets.
            for _provider, _family, provider_url in providers:
                self._register_runtime_internal_probe(
                    provider_url,
                    timeout_seconds=total_timeout,
                )

        identity_result: dict[str, Any] = {"identity": {}}
        collection_attempts = 0
        provider_status: dict[str, int] = {}
        # Even partial IPv4 success needs a final authoritative route readback.
        # A slow IPv6/provider must not consume that reserved return window.
        identity_budget = max(0.0, deadline - time.monotonic() - 0.35)
        if proven_route is None:
            identity_budget = min(2.2, identity_budget)
        if speculative is not None:
            collection_attempts = 1
            # The speculation's own budget ends at this same identity
            # deadline; wait for it rather than opening new connections.
            speculative.done.wait(max(0.0, deadline - 0.35 - time.monotonic()) + 0.05)
            if speculative.done.is_set() and isinstance(speculative.result, dict):
                identity_result = speculative.result
            else:
                speculative.abandon()
                speculation_state = {"state": "used", "reason": "unfinished"}
        elif proxy_url and identity_budget > 0.05:
            collection_attempts = 1
            try:
                if proven_route is not None:
                    # Return shortly after the first usable answer instead of
                    # waiting for a hung sibling until the deadline.
                    identity_result = collect_exit_identity(
                        proxy_url=proxy_url,
                        timeout_seconds=identity_budget,
                        total_timeout_seconds=identity_budget,
                        providers=providers,
                        rounds=1,
                        max_workers=len(providers),
                        retry_transient_errors=True,
                        answer_policy=OVERVIEW_ANSWER_POLICY,
                    )
                else:
                    identity_result = collect_exit_identity(
                        proxy_url=proxy_url,
                        timeout_seconds=identity_budget,
                        total_timeout_seconds=identity_budget,
                        rounds=1,
                        max_workers=4,
                        retry_transient_errors=False,
                        completed_family_grace_seconds=0.35,
                    )
            except Exception as exc:
                log_raw_diagnostic(
                    self.logger,
                    "info",
                    "Manual exit identity lookup was unavailable (%s)",
                    type(exc).__name__,
                )
                identity_result = {"identity": {}}

        # Each provider retries independently, so unreachable IPv6 cannot block
        # an IPv4 retry. Retain only status counts in the runtime log, and keep
        # all observations bound to the final route readback below.
        identity = identity_result.get("identity")
        identity = identity if isinstance(identity, dict) else {}
        observations = [
            observation
            for family in ("ipv4", "ipv6")
            if isinstance(identity.get(family), dict)
            for source in identity[family].get("evidence", [])
            for observation in source.get("attempts", [])
        ]
        for observation in observations:
            for transport in [*observation.get("transport_retries", []), observation]:
                status = str(transport.get("status") or "")
                if status in {"ok", "error", "timeout", "invalid", "abandoned"}:
                    provider_status[status] = provider_status.get(status, 0) + 1
        provider_outcomes = _overview_provider_outcomes(identity)

        route_after = route_context(0.35)
        # Process/Core generation is a stale-work CAS token, not a route
        # identity.  Comparing execution markers here made every Core restart
        # look like a user-visible exit change even when the logical selected
        # chain and leaf were identical.
        before_marker = self._exit_route_binding_marker(route_before)
        after_marker = self._exit_route_binding_marker(route_after)
        before_confirmed = bool(
            route_before.get("confirmed")
            and not route_before.get("facility_failure")
            and str(route_before.get("path_kind") or "") != "unavailable"
        )
        after_confirmed = bool(
            route_after.get("confirmed")
            and not route_after.get("facility_failure")
            and str(route_after.get("path_kind") or "") != "unavailable"
        )
        route_changed = bool(
            before_confirmed
            and after_confirmed
            and before_marker
            and after_marker
            and before_marker != after_marker
        )
        route_confirmed = bool(
            before_confirmed and after_confirmed and not route_changed
        )
        execution_owner_changed = bool(
            execution_epoch != self._manual_identity_execution_epoch()
            or (route_before.get("core_instance") and route_after.get("core_instance")
                and route_before["core_instance"] != route_after["core_instance"])
        )
        execution_current = bool(
            proven_route is None
            or (
                execution_epoch == self._manual_identity_execution_epoch()
                and route_epoch == int(getattr(self, "_runtime_route_epoch", 0) or 0)
                and selector_intent == int(getattr(self, "_runtime_selector_intent_revision", 0) or 0)
                and self._exit_route_execution_binding_marker(route_before)
                == self._exit_route_execution_binding_marker(route_after)
            )
        )
        route_confirmed = route_confirmed and execution_current
        identity = identity_result.get("identity")
        identity = identity if isinstance(identity, dict) else {}
        if not route_confirmed:
            identity = {}
        family_states = {
            family: str(identity[family].get("state") or "unavailable")
            for family in ("ipv4", "ipv6") if isinstance(identity.get(family), dict)
        }
        has_identity = any(
            isinstance(identity.get(family), dict)
            and bool(identity[family].get("ip"))
            for family in ("ipv4", "ipv6")
        )
        identity_reason = ""
        if "conflict" in family_states.values():
            identity_reason = "identity_conflict"
        elif "rotating" in family_states.values():
            identity_reason = "identity_rotating"
        elif not has_identity:
            attempts = [
                transport
                for observation in observations
                for transport in [*observation.get("transport_retries", []), observation]
            ]
            if any(item.get("error_code") == "rate_limited" or item.get("http_status") == 429
                   for item in attempts):
                identity_reason = "identity_rate_limited"
            elif any(item.get("status") == "timeout" or item.get("error_code") == "timeout"
                     for item in attempts):
                identity_reason = "identity_timeout"
            else:
                identity_reason = "identity_unavailable"
        checked_at = utc_now_iso()
        safe_route = {
            "binding_marker": (
                after_marker or before_marker if route_confirmed else ""
            ),
            "confirmed": route_confirmed,
            "stable_during_check": route_confirmed,
        }
        if route_confirmed:
            for field_name in ("runtime_route_epoch", "core_instance", "checked_at"):
                if field_name in route_after:
                    safe_route[field_name] = route_after[field_name]
        state = (
            "route_changed"
            if route_changed
            else "complete"
            if has_identity and route_confirmed
            else "unavailable"
        )
        payload: dict[str, Any] = {
            "schema_version": 2,
            "request_id": str(request_id),
            "state": state,
            "checked_at": checked_at,
            "freshness": {
                "state": "stale" if route_changed else "fresh",
                "reason": "route_changed" if route_changed else "manual_lookup",
            },
            "route": safe_route,
            "identity": identity,
            "diagnostics": {
                "identity_collection_attempts": collection_attempts,
                "identity_provider_status": provider_status,
                "identity_provider_outcomes": provider_outcomes,
                **({"identity_speculation": speculation_state} if speculation_state else {}),
                "identity_collection": dict(identity_result.get("collection") or {}),
                "identity_family_states": family_states,
                "identity_execution_owner_changed": execution_owner_changed,
            },
        }
        if route_changed:
            payload["route_changed"] = True
        elif not route_confirmed:
            payload["error"] = (
                "route_unconfirmed" if execution_current else "manual_validation_execution_changed"
            )
        elif not has_identity:
            payload["error"] = identity_reason
        if route_confirmed and identity_reason:
            payload["diagnostics"]["overview_failure_reason"] = identity_reason
        return payload

    def _manual_exit_quality_contract_urls(self) -> tuple[str, str] | None:
        selected: list[str] = []
        seen_hosts: set[str] = set()
        for raw_url in self._default_probe_urls():
            url = str(raw_url or "").strip()
            try:
                parsed = urlsplit(url)
            except ValueError:
                continue
            host = str(parsed.hostname or "").strip().casefold()
            if parsed.scheme.casefold() != "https" or not host or host in seen_hosts:
                continue
            selected.append(url)
            seen_hosts.add(host)
            if len(selected) == 2:
                return selected[0], selected[1]
        return None

    def _run_manual_exit_quality_contracts(
        self,
        session: RuntimeManualValidation,
        *,
        probe: Callable[
            [str, str, float, ProbeExecutionContext | None],
            dict[str, Any],
        ],
        phase_timeout_seconds: float,
        contract_urls: tuple[str, str] | None = None,
        contract_ids: tuple[str, str] | None = None,
        typed_error_slots: tuple[int, ...] = (),
    ) -> tuple[ManualDataPlaneProbeResult, ManualDataPlaneProbeResult]:
        # Contract ids per slot: the neutral pair keeps ``neutral-{index}``;
        # the route-contract pair (P0-4) labels each slot by its contract.
        # Errors in ``typed_error_slots`` come from a controller URL test and
        # are classified by exception type, never by their text.
        ids = (
            (str(contract_ids[0]), str(contract_ids[1]))
            if contract_ids is not None
            else ("neutral-0", "neutral-1")
        )
        urls = contract_urls or self._manual_exit_quality_contract_urls()
        if urls is None:
            now = time.monotonic()
            return (
                ManualDataPlaneProbeResult(
                    contract_id=ids[0],
                    succeeded=False,
                    failure_kind=ManualProbeFailureKind.FACILITY,
                    completed_at_monotonic=now,
                ),
                ManualDataPlaneProbeResult(
                    contract_id=ids[1],
                    succeeded=False,
                    failure_kind=ManualProbeFailureKind.FACILITY,
                    completed_at_monotonic=now,
                ),
            )
        if float(phase_timeout_seconds) <= 0.05:
            now = time.monotonic()
            return (
                ManualDataPlaneProbeResult(
                    contract_id=ids[0],
                    succeeded=False,
                    failure_kind=ManualProbeFailureKind.FACILITY,
                    completed_at_monotonic=now,
                ),
                ManualDataPlaneProbeResult(
                    contract_id=ids[1],
                    succeeded=False,
                    failure_kind=ManualProbeFailureKind.FACILITY,
                    completed_at_monotonic=now,
                ),
            )

        def execute(
            index: int,
            url: str,
            context: ProbeExecutionContext,
        ) -> dict[str, Any]:
            contract_id = ids[index]
            timeout_seconds = session.probe_timeout_seconds(
                requested_seconds=phase_timeout_seconds,
            )
            return probe(contract_id, url, timeout_seconds, context)

        broker = getattr(self, "_runtime_probe_broker", None)
        if broker is None:
            broker = RuntimeProbeBroker(max_active_sockets=2)
        remaining = session.budget.remaining()
        executions = broker.run_pair(
            ProbePriority.RUNTIME_MANUAL,
            lambda context: execute(0, urls[0], context),
            lambda context: execute(1, urls[1], context),
            queue_timeout_seconds=min(
                1.5,
                remaining,
            ),
            socket_start_timeout_seconds=min(
                0.5,
                max(0.05, float(phase_timeout_seconds)),
            ),
            cancel_event=getattr(self, "stop_event", None),
            execution_deadline_monotonic=session.budget.deadline_monotonic,
            execution_timeout_seconds=max(0.05, float(phase_timeout_seconds)),
        )

        def result_for(index: int) -> ManualDataPlaneProbeResult:
            contract_id = ids[index]
            execution = executions[index]
            if execution.disposition is not ProbeDisposition.EXECUTED:
                return ManualDataPlaneProbeResult(
                    contract_id=contract_id,
                    succeeded=False,
                    failure_kind=ManualProbeFailureKind.FACILITY,
                    completed_at_monotonic=time.monotonic(),
                    probe_indeterminate_reason=(
                        execution.indeterminate_reason.value
                        if execution.indeterminate_reason is not None else None
                    ),
                )
            if execution.error is not None:
                if index in typed_error_slots:
                    return manual_result_from_delay_error(
                        execution.error,
                        contract_id=contract_id,
                        completed_at_monotonic=time.monotonic(),
                    )
                return ManualDataPlaneProbeResult.transport_failure(
                    contract_id,
                    normalise_manual_probe_failure(execution.error),
                    completed_at_monotonic=time.monotonic(),
                )
            try:
                value = execution.value
                if isinstance(value, dict):
                    raw_status = value.get("status")
                    status = (
                        204
                        if value.get("expected_status_verified") is True
                        else int(raw_status)
                        if raw_status is not None
                        else 0
                    )
                else:
                    status = 0
                if status == 204:
                    return ManualDataPlaneProbeResult.https_204(
                        contract_id,
                        completed_at_monotonic=time.monotonic(),
                    )
                return ManualDataPlaneProbeResult(
                    contract_id=contract_id,
                    succeeded=False,
                    status_code=status,
                    failure_kind=ManualProbeFailureKind.HTTP_STATUS,
                    completed_at_monotonic=time.monotonic(),
                )
            except Exception as exc:
                return ManualDataPlaneProbeResult.transport_failure(
                    contract_id,
                    normalise_manual_probe_failure(exc),
                    completed_at_monotonic=time.monotonic(),
                )
        return result_for(0), result_for(1)

    def _manual_current_exit_quality_contracts(
        self,
        session: RuntimeManualValidation,
    ) -> tuple[ManualDataPlaneProbeResult, ManualDataPlaneProbeResult]:
        def probe(
            _contract_id: str,
            url: str,
            timeout_seconds: float,
            context: ProbeExecutionContext | None,
        ) -> dict[str, Any]:
            adapter = self._probe_mihomo_mixed_port_once_leased
            if (
                context is not None
                and context.execution_deadline_monotonic is not None
                and not context.abort_registered
                and getattr(adapter, "__func__", None)
                is not DesktopRuntime._probe_mihomo_mixed_port_once_leased
            ):
                # Narrow compatibility for injected test/diagnostic adapters.
                # A blocking fake still poisons the broker when this no-op
                # cannot make its worker exit; production must register the
                # actual socket owner inside the bound adapter.
                context.register_abort_callback(lambda: None)
            return adapter(
                timeout_seconds=max(0.1, timeout_seconds),
                probe_url=url,
                execution_context=context,
            )

        return self._run_manual_exit_quality_contracts(
            session,
            probe=probe,
            phase_timeout_seconds=min(
                session.budget.per_probe_timeout_seconds,
                session.budget.remaining(),
            ),
        )

    def _manual_backup_exit_quality_contract_urls(
        self,
        snapshot: CoreLoadedRouteSnapshot,
        action: dict[str, Any],
    ) -> tuple[tuple[str, str] | None, str, str]:
        """Pair the loaded fallback URL with one independent neutral URL."""

        defaults = self._manual_exit_quality_contract_urls()
        if defaults is None:
            return None, "", ""
        group = str(action.get("group") or "")
        if not group:
            return defaults, "", ""
        probe_url, expected_status = self._runtime_group_probe_contract(
            snapshot,
            group,
        )
        if not self._runtime_probe_contract_accepts_204(expected_status):
            return defaults, "", ""
        try:
            parsed = urlsplit(probe_url)
        except ValueError:
            return defaults, "", ""
        probe_host = str(parsed.hostname or "").strip().casefold()
        if parsed.scheme.casefold() != "https" or not probe_host:
            return defaults, "", ""
        independent = next(
            (
                url
                for url in defaults
                if str(urlsplit(url).hostname or "").strip().casefold()
                != probe_host
            ),
            "",
        )
        if not independent:
            return defaults, "", ""
        return (probe_url, independent), probe_url, expected_status

    def _manual_backup_exit_quality_contracts(
        self,
        session: RuntimeManualValidation,
        ref: RuntimeNodeRef,
        *,
        phase_timeout_seconds: float | None = None,
        contract_urls: tuple[str, str] | None = None,
        contract_ids: tuple[str, str] | None = None,
        typed_controller_errors: bool = False,
        commit_reserve_seconds: float = _MANUAL_SELECTOR_COMMIT_RESERVE_SECONDS,
    ) -> tuple[ManualDataPlaneProbeResult, ManualDataPlaneProbeResult]:
        def probe(
            _contract_id: str,
            url: str,
            timeout_seconds: float,
            context: ProbeExecutionContext | None,
        ) -> dict[str, Any]:
            adapter = self._probe_proxy_delay_with_urls_leased
            if (
                context is not None
                and context.execution_deadline_monotonic is not None
                and not context.abort_registered
                and getattr(adapter, "__func__", None)
                is not DesktopRuntime._probe_proxy_delay_with_urls_leased
            ):
                context.register_abort_callback(lambda: None)
            return adapter(
                ref.proxy_name,
                [url],
                timeout_ms=max(100, int(timeout_seconds * 1000.0)),
                request_timeout_seconds=max(0.1, timeout_seconds),
                expected_status=204,
                execution_context=context,
            )

        return self._run_manual_exit_quality_contracts(
            session,
            probe=probe,
            phase_timeout_seconds=min(
                (
                    session.budget.per_probe_timeout_seconds
                    if phase_timeout_seconds is None
                    else max(0.0, float(phase_timeout_seconds))
                ),
                max(
                    0.0,
                    session.budget.remaining()
                    - max(0.0, float(commit_reserve_seconds)),
                ),
            ),
            contract_urls=contract_urls,
            contract_ids=contract_ids,
            typed_error_slots=(0, 1) if typed_controller_errors else (),
        )

    def _manual_route_contract_plan(
        self,
        binding_state: tuple[
            RuntimeRouteBinding,
            CoreLoadedRouteSnapshot,
            dict[str, Any],
        ] | None,
    ) -> _ManualRouteContractPlan | None:
        """The owning fallback group's contract for the current leaf (P0-4).

        Only a non-Gateway leaf whose directly owning group is a loaded
        fallback group with an HTTPS contract accepting 204, and for which an
        independent neutral URL (a different host) exists.  Every other route
        keeps today's neutral pair.
        """

        if binding_state is None:
            return None
        binding, snapshot, _payload = binding_state
        if binding.node.pool_kind == "gateway":
            return None
        chain = tuple(binding.route_chain)
        leaf = str(binding.node.proxy_name)
        if len(chain) < 2 or chain[-1] != leaf:
            return None
        group = str(chain[-2])
        state = snapshot.group_state(group)
        if (
            state is None
            or "fallback" not in str(state.type_name or "").casefold()
            or str(state.now or "") != leaf
            or not str(state.test_url or "").strip()
        ):
            return None
        probe_url, expected_status = self._runtime_group_probe_contract(
            snapshot,
            group,
        )
        if not self._runtime_probe_contract_accepts_204(expected_status):
            return None
        try:
            parsed = urlsplit(probe_url)
        except ValueError:
            return None
        probe_host = str(parsed.hostname or "").strip().casefold()
        if parsed.scheme.casefold() != "https" or not probe_host:
            return None
        defaults = self._manual_exit_quality_contract_urls()
        if defaults is None:
            return None
        for index, url in enumerate(defaults):
            try:
                host = str(urlsplit(url).hostname or "").strip().casefold()
            except ValueError:
                continue
            if host and host != probe_host:
                return _ManualRouteContractPlan(
                    group=group,
                    leaf=leaf,
                    probe_url=probe_url,
                    expected_status=str(expected_status),
                    neutral_url=str(url),
                    neutral_contract_id=f"neutral-{index}",
                )
        return None

    def _manual_route_contract_current_contracts(
        self,
        session: RuntimeManualValidation,
        plan: _ManualRouteContractPlan,
    ) -> tuple[ManualDataPlaneProbeResult, ManualDataPlaneProbeResult]:
        """Current pair = (owning-group contract on the leaf, one neutral).

        The route contract is the controller URL test on the leaf's exact key,
        so a failure is Mihomo's own demotion.  It starts only after the
        neutral CONNECT was answered, plus a grace.  That ordering is a
        heuristic, not proof that the neutral was bound to this leaf: Mihomo
        answers the CONNECT before it matches rules and dials, and the
        fallback picks its member at dial time.  A neutral dialled after a
        fast failed URL test would go through the successor and be counted
        for the leaf; the rare wrong outcome is a non-node verdict when that
        successor answers with an HTTP or certificate error.  A neutral whose
        CONNECT answer came after the URL test started is never attributed.
        """

        per_probe = session.budget.per_probe_timeout_seconds
        neutral_phase = min(per_probe, session.budget.remaining())
        route_requested = max(_OVERVIEW_MIN_CONTRACT_PROBE_SECONDS, per_probe)
        gate = (
            _MANUAL_ROUTE_CONTRACT_NEUTRAL_GATE_SECONDS
            + _MANUAL_ROUTE_CONTRACT_NEUTRAL_GRACE_SECONDS
        )
        pair_phase = min(
            session.budget.remaining(),
            max(neutral_phase, route_requested + gate),
        )
        tunnel_ready = threading.Event()
        timing_lock = threading.Lock()
        timing: dict[str, float | None] = {"tunnel": None, "route": None}

        def mark_tunnel() -> None:
            with timing_lock:
                if timing["tunnel"] is None:
                    timing["tunnel"] = time.monotonic()
            tunnel_ready.set()

        def probe(
            contract_id: str,
            url: str,
            _timeout_seconds: float,
            context: ProbeExecutionContext | None,
        ) -> dict[str, Any]:
            if contract_id == plan.route_contract_id:
                if tunnel_ready.wait(_MANUAL_ROUTE_CONTRACT_NEUTRAL_GATE_SECONDS):
                    stop_event = getattr(self, "stop_event", None)
                    if stop_event is not None:
                        stop_event.wait(_MANUAL_ROUTE_CONTRACT_NEUTRAL_GRACE_SECONDS)
                    else:
                        time.sleep(_MANUAL_ROUTE_CONTRACT_NEUTRAL_GRACE_SECONDS)
                with timing_lock:
                    timing["route"] = time.monotonic()
                timeout_seconds = session.probe_timeout_seconds(
                    requested_seconds=route_requested,
                )
                return self._probe_proxy_delay_with_urls_leased(
                    plan.leaf,
                    [url],
                    timeout_ms=max(
                        100,
                        int(
                            (
                                timeout_seconds
                                - _MANUAL_ROUTE_CONTRACT_REPLY_SLACK_SECONDS
                            )
                            * 1000.0
                        ),
                    ),
                    request_timeout_seconds=max(0.1, timeout_seconds),
                    expected_status=plan.expected_status,
                    execution_context=context,
                )
            adapter = self._probe_mihomo_mixed_port_once_leased
            real_adapter = bool(
                getattr(adapter, "__func__", None)
                is DesktopRuntime._probe_mihomo_mixed_port_once_leased
            )
            try:
                if (
                    context is not None
                    and context.execution_deadline_monotonic is not None
                    and not context.abort_registered
                    and not real_adapter
                ):
                    context.register_abort_callback(lambda: None)
                timeout_seconds = session.probe_timeout_seconds(
                    requested_seconds=neutral_phase,
                )
                if real_adapter:
                    return adapter(
                        timeout_seconds=max(0.1, timeout_seconds),
                        probe_url=url,
                        execution_context=context,
                        on_tunnel_established=mark_tunnel,
                    )
                return adapter(
                    timeout_seconds=max(0.1, timeout_seconds),
                    probe_url=url,
                    execution_context=context,
                )
            finally:
                # A neutral that ends before its tunnel (or an adapter without
                # the callback) releases the gate when it ends.
                mark_tunnel()

        route_result, neutral_result = self._run_manual_exit_quality_contracts(
            session,
            probe=probe,
            phase_timeout_seconds=pair_phase,
            contract_urls=(plan.probe_url, plan.neutral_url),
            contract_ids=(plan.route_contract_id, plan.neutral_contract_id),
            typed_error_slots=(0,),
        )
        with timing_lock:
            tunnel_at = timing["tunnel"]
            route_at = timing["route"]
        if (
            route_at is not None
            and (tunnel_at is None or tunnel_at > route_at)
            and not route_result.is_https_204_success(session.budget)
        ):
            # A failed URL test demotes the leaf, so Mihomo may have routed
            # this late neutral via the successor: it is not evidence about
            # the leaf either way.  (A passing test leaves the pick alone.)
            neutral_result = ManualDataPlaneProbeResult(
                contract_id=plan.neutral_contract_id,
                succeeded=False,
                failure_kind=ManualProbeFailureKind.FACILITY,
                completed_at_monotonic=neutral_result.completed_at_monotonic,
                probe_indeterminate_reason="neutral_unattributed",
            )
        return route_result, neutral_result

    def _manual_route_contract_native_rebind(
        self,
        plan: _ManualRouteContractPlan,
        binding_state: tuple[
            RuntimeRouteBinding,
            CoreLoadedRouteSnapshot,
            dict[str, Any],
        ],
        probe_end_state: tuple[
            RuntimeRouteBinding,
            CoreLoadedRouteSnapshot,
            dict[str, Any],
        ] | None,
        mutation_binding: CurrentMutationBinding | None,
    ) -> tuple[
        tuple[RuntimeRouteBinding, CoreLoadedRouteSnapshot, dict[str, Any]],
        CurrentMutationBinding,
        RuntimeNodeRef,
    ] | None:
        """Rebind after the route contract's own native move (P0-4).

        A failed exact-key URL test is Mihomo's demotion: the owning group
        moves to its next alive member, which bumps the route epoch.  Accept
        the new snapshot only when that is the sole change: same process,
        Core generation, config digest, network context, selector intent and
        facility epoch; the same route above the owning group; the group's own
        membership and contract unchanged; the leaf Core-dead for the
        contract; and the group now on a different managed member.
        """

        if probe_end_state is None or mutation_binding is None:
            return None
        binding0, snapshot0, _payload0 = binding_state
        binding1, snapshot1, payload1 = probe_end_state
        if (
            snapshot1.process_pid,
            snapshot1.process_generation,
            snapshot1.core_generation,
            snapshot1.semantic_digest,
            snapshot1.network_context_epoch,
        ) != (
            snapshot0.process_pid,
            snapshot0.process_generation,
            snapshot0.core_generation,
            snapshot0.semantic_digest,
            snapshot0.network_context_epoch,
        ):
            return None
        if int(
            getattr(self, "_runtime_selector_intent_revision", 0) or 0
        ) != int(mutation_binding.selector_intent_revision) or int(
            getattr(self, "_runtime_facility_epoch", 0) or 0
        ) != int(mutation_binding.facility_epoch):
            return None
        if tuple(snapshot1.group_graph) != tuple(snapshot0.group_graph):
            return None
        group0 = snapshot0.group_state(plan.group)
        group1 = snapshot1.group_state(plan.group)
        if group0 is None or group1 is None or str(group0.now) != plan.leaf:
            return None
        if (
            group1.type_name,
            tuple(group1.members),
            group1.test_url,
            group1.expected_status,
        ) != (
            group0.type_name,
            tuple(group0.members),
            group0.test_url,
            group0.expected_status,
        ):
            return None
        if str(group1.fixed or "") not in {str(group0.fixed or ""), ""}:
            return None
        successor = str(group1.now or "")
        if not successor or successor == plan.leaf:
            return None
        chain0 = tuple(binding0.route_chain)
        chain1 = tuple(binding1.route_chain)
        depth = len(chain0) - 1
        if (
            binding1.observed_outbound != binding0.observed_outbound
            or len(chain1) <= depth
            or chain1[:depth] != chain0[:depth]
            or chain1[depth] != successor
            or len(chain1) != depth + 1
            or binding1.node.pool_kind == "gateway"
            or binding1.node.proxy_name == plan.leaf
        ):
            return None
        entries = self._runtime_proxy_entries(payload1)
        if node_judgement_member_alive(entries.get(plan.leaf), plan.probe_url):
            return None
        rebound = _dataclass_replace(
            binding0,
            route_epoch=int(snapshot1.route_epoch),
            network_context_epoch=int(snapshot1.network_context_epoch),
        )
        rebound_mutation = self._runtime_mutation_binding_for_snapshot(snapshot1)
        if not self._runtime_mutation_binding_is_current(rebound_mutation):
            return None
        return (rebound, snapshot1, payload1), rebound_mutation, binding1.node

    def _manual_verify_native_successor(
        self,
        session: RuntimeManualValidation,
        plan: _ManualRouteContractPlan,
        successor: RuntimeNodeRef,
    ) -> tuple[ManualDataPlaneProbeResult, ManualDataPlaneProbeResult] | None:
        """Prove Mihomo's own successor on the same contract pair (P0-4).

        There is no selector write afterwards (no pin, natural failback), so
        the pair keeps only readback room.  None when the budget cannot give
        the successor's URL tests the floor timeout.
        """

        available = (
            session.budget.remaining() - _MANUAL_NATIVE_SUCCESSOR_RESERVE_SECONDS
        )
        phase = min(
            max(
                _OVERVIEW_MIN_CONTRACT_PROBE_SECONDS,
                session.budget.per_probe_timeout_seconds,
            ),
            available,
        )
        if phase < _MANUAL_NATIVE_SUCCESSOR_MIN_PROBE_SECONDS:
            return None
        return self._manual_backup_exit_quality_contracts(
            session,
            successor,
            phase_timeout_seconds=phase,
            contract_urls=(plan.probe_url, plan.neutral_url),
            contract_ids=(plan.route_contract_id, plan.neutral_contract_id),
            typed_controller_errors=True,
            commit_reserve_seconds=_MANUAL_NATIVE_SUCCESSOR_RESERVE_SECONDS,
        )

    def _manual_route_contract_native_commit(
        self,
        session: RuntimeManualValidation,
        *,
        binding_state: tuple[
            RuntimeRouteBinding,
            CoreLoadedRouteSnapshot,
            dict[str, Any],
        ],
        plan: _ManualRouteContractPlan,
        successor: RuntimeNodeRef,
        request_id: str,
        expected_mutation_binding: CurrentMutationBinding | None,
    ) -> tuple[bool, str]:
        """Design v3 §18.7 ``native_commit`` after a verified native move.

        Mihomo already moved the owning group to ``successor`` and the
        successor passed the same contract pair.  The app makes no selector
        write (no PUT, pin, reload or connection close) and publishes no
        readiness; only the failed leaf enters the existing pool rules, as
        today's switch does: one coordinator confirmation bound to the
        rebound snapshot, then ``_apply_confirmed_runtime_health`` (the
        effective-SUSPICIOUS overlay plus a targeted recheck).  A rejected
        commit is logged and changes nothing else.  Returns (accepted, reason).
        """

        binding, snapshot, snapshot_payload = binding_state
        reason = "commit_rejected"
        accepted = False
        try:
            if (
                expected_mutation_binding is None
                or not self._runtime_mutation_binding_is_current(
                    expected_mutation_binding
                )
            ):
                reason = "manual_execution_binding_stale"
                return False, reason
            if session.budget.remaining() <= 0.05:
                reason = "commit_late"
                return False, reason
            failure = BoundRuntimeFailure(
                binding=binding,
                protocol="HTTPS",
                observed_outbound=binding.observed_outbound,
                destination_token=runtime_destination_token(
                    f"manual-contract:{request_id}"
                ),
                error_type="manual_route_contract_failure",
                observed_at_monotonic=time.monotonic(),
            )
            coordinator = self._runtime_egress_coordinator
            first = coordinator.observe(failure, current_snapshot=snapshot)
            incident_id = str(first.incident_id or "")
            probe_token = str(first.probe_token or "")
            if not incident_id or not probe_token:
                current = coordinator.current_snapshot_for(binding)
                incident_id = str(getattr(current, "incident_id", "") or "")
                probe_token = str(getattr(current, "probe_token", "") or "")
            if not incident_id or not probe_token:
                reason = str(first.reason or "manual_confirmation_rejected")
                return False, reason
            ticket = self._ensure_runtime_recovery_ticket(
                failure,
                snapshot,
                incident_id,
                deadline_monotonic=session.budget.deadline_monotonic,
            )
            if not isinstance(ticket, _RuntimeRecoveryTicket):
                reason = "manual_recovery_ticket_unavailable"
                return False, reason
            deadline = float(ticket.deadline_monotonic)
            if not self._runtime_recovery_ticket_is_current(
                ticket,
                require_open=True,
                deadline_monotonic=deadline,
            ):
                self._complete_runtime_early_indeterminate(
                    failure,
                    ticket,
                    probe_token=probe_token,
                    reason_code="ticket_stale",
                )
                reason = "ticket_stale"
                return False, reason
            confirmed = coordinator.record_probe(
                failure,
                succeeded=False,
                probe_token=probe_token,
                current_snapshot=snapshot,
            )
            if not confirmed.confirmed:
                self._complete_runtime_early_indeterminate(
                    failure,
                    ticket,
                    probe_token=probe_token,
                    reason_code="confirmation_rejected",
                )
                reason = "confirmation_rejected"
                return False, reason
            health = self._apply_confirmed_runtime_health(
                failure,
                snapshot,
                snapshot_payload,
                incident_id=ticket.incident_id,
                quarantine_token=probe_token,
                expected_ticket=ticket,
                deadline_monotonic=deadline,
            )
            if not bool(health.get("accepted")):
                self._complete_runtime_early_indeterminate(
                    failure,
                    ticket,
                    probe_token=probe_token,
                    reason_code="health_cas_rejected",
                )
                reason = f"commit_rejected:{health.get('action') or 'rejected'}"
                return False, reason
            self._mark_runtime_recovery_quarantined(
                binding,
                recovery_ticket=ticket,
                coordinator_incident_id=ticket.incident_id,
                coordinator_quarantine_token=probe_token,
                deadline_monotonic=deadline,
            )
            self._complete_runtime_recovery_outcome(
                ticket.incident_id,
                RuntimeRecoveryStatus.RECOVERED,
                reason_code="native_fallback_verified",
                to_ref=successor,
                route_epoch=int(snapshot.route_epoch),
                expected_ticket=ticket,
                deadline_monotonic=deadline,
                facts={"put": False, "readback": True, "final_204": False},
            )
            accepted = True
            reason = "native_fallback_verified"
            return True, reason
        except Exception as exc:
            reason = f"commit_rejected:{type(exc).__name__}"
            return False, reason
        finally:
            logger = getattr(self, "logger", None)
            if isinstance(logger, logging.Logger):
                tokenizer = self._node_judgement_state().tokenizer
                log_raw_diagnostic(
                    logger,
                    "info" if accepted else "warning",
                    "Manual route-contract native commit (group=%s leaf=%s "
                    "successor=%s accepted=%s reason=%s)",
                    str(plan.group),
                    tokenizer.leaf(binding.node.proxy_name),
                    tokenizer.leaf(successor.proxy_name),
                    accepted,
                    reason,
                )

    @staticmethod
    def _manual_route_contract_align_backup(
        plan: _ManualRouteContractPlan,
        current_results: tuple[ManualDataPlaneProbeResult, ...],
        candidate_results: tuple[ManualDataPlaneProbeResult, ...],
        candidate_contract_urls: tuple[str, str] | None,
        group_probe_url: str,
    ) -> tuple[
        tuple[ManualDataPlaneProbeResult, ...],
        tuple[ManualDataPlaneProbeResult, ...],
        bool,
    ]:
        """Label a backup pair against the route-contract current pair.

        A candidate measured on the same pair (its group URL and the current
        neutral URL) takes the same ids.  Any other candidate is judged on the
        neutral contract alone: the current route result is relabelled to the
        candidate's missing neutral id, which restores today's double-failure
        rule and never switches on a route-contract failure alone.  Returns
        (candidate, current, relabelled_current).
        """

        candidate = tuple(candidate_results)
        current = tuple(current_results)
        urls = tuple(candidate_contract_urls or ())
        if len(candidate) != 2:
            return candidate, current, False
        if group_probe_url and len(urls) == 2 and urls[1] == plan.neutral_url:
            return (
                (
                    _dataclass_replace(
                        candidate[0],
                        contract_id=plan.route_contract_id,
                    ),
                    _dataclass_replace(
                        candidate[1],
                        contract_id=plan.neutral_contract_id,
                    ),
                ),
                current,
                False,
            )
        missing = [
            str(result.contract_id)
            for result in candidate
            if str(result.contract_id) != plan.neutral_contract_id
        ]
        if len(missing) != 1:
            return candidate, current, False
        return (
            candidate,
            tuple(
                _dataclass_replace(result, contract_id=missing[0])
                if str(result.contract_id) == plan.route_contract_id
                else result
                for result in current
            ),
            True,
        )

    def _manual_confirm_and_switch_before_return_early(
        self,
        session: RuntimeManualValidation,
        *,
        binding_state: tuple[
            RuntimeRouteBinding,
            CoreLoadedRouteSnapshot,
            dict[str, Any],
        ],
        alternative: RuntimeNodeRef | None,
        request_id: str,
        expected_mutation_binding: CurrentMutationBinding | None,
        alternative_probe_evidence: _HotStandbyEvidence | None = None,
    ) -> tuple[bool, str]:
        """Use the one bounded coordinator transaction before returning.

        The two failed current-route contracts and the already verified backup
        are sufficient differential evidence.  This path performs no REJECT,
        reload, retry scheduling or connection cleanup; a fixed Gateway whose
        own chain failed remains selected and is reported as a terminal failure.
        """

        if alternative is None:
            return False, "gateway_chain_failed_without_gateway_switch"
        if (
            expected_mutation_binding is not None
            and not self._runtime_mutation_binding_is_current(
                expected_mutation_binding
            )
        ):
            return False, "manual_execution_binding_stale"
        if session.budget.remaining() <= 0.05:
            return False, "replacement_commit_deadline_expired"

        binding, snapshot, snapshot_payload = binding_state
        failure = BoundRuntimeFailure(
            binding=binding,
            protocol="HTTPS",
            observed_outbound=binding.observed_outbound,
            destination_token=runtime_destination_token(
                f"manual-contract:{request_id}"
            ),
            error_type="manual_dual_204_transport_failure",
            observed_at_monotonic=time.monotonic(),
        )
        decision = self._runtime_egress_coordinator.observe(
            failure,
            current_snapshot=snapshot,
        )
        incident_id = str(decision.incident_id or "")
        probe_token = str(decision.probe_token or "")
        if not incident_id or not probe_token:
            current = self._runtime_egress_coordinator.current_snapshot_for(
                binding
            )
            incident_id = str(getattr(current, "incident_id", "") or "")
            probe_token = str(getattr(current, "probe_token", "") or "")
        if not incident_id or not probe_token:
            return False, str(decision.reason or "manual_confirmation_rejected")
        ticket = self._ensure_runtime_recovery_ticket(
            failure,
            snapshot,
            incident_id,
            deadline_monotonic=session.budget.deadline_monotonic,
        )
        if not isinstance(ticket, _RuntimeRecoveryTicket):
            return False, "manual_recovery_ticket_unavailable"
        outcome = self._run_runtime_early_confirmed_recovery(
            failure,
            snapshot,
            snapshot_payload,
            ticket=ticket,
            probe_token=probe_token,
            alternative=alternative,
            alternative_probe_result={
                "manual_contracts": 2,
                "verified": True,
            },
            alternative_probe_evidence=alternative_probe_evidence,
        )
        if (
            isinstance(outcome, RuntimeRecoveryOutcome)
            and outcome.status is RuntimeRecoveryStatus.RECOVERED
        ):
            return True, "replacement_selected_and_verified"
        if isinstance(outcome, RuntimeRecoveryOutcome):
            return False, str(outcome.reason or outcome.status.value)
        return False, "replacement_unverified"

    def _manual_confirm_and_switch_before_return(
        self,
        session: RuntimeManualValidation,
        *,
        binding_state: tuple[
            RuntimeRouteBinding,
            CoreLoadedRouteSnapshot,
            dict[str, Any],
        ],
        alternative: RuntimeNodeRef | None,
        request_id: str,
        expected_mutation_binding: CurrentMutationBinding | None = None,
        alternative_probe_evidence: _HotStandbyEvidence | None = None,
    ) -> tuple[bool, str]:
        if self._runtime_uses_early_single_coordinator():
            return self._manual_confirm_and_switch_before_return_early(
                session,
                binding_state=binding_state,
                alternative=alternative,
                request_id=request_id,
                expected_mutation_binding=expected_mutation_binding,
                alternative_probe_evidence=alternative_probe_evidence,
            )
        if (
            expected_mutation_binding is not None
            and not self._runtime_mutation_binding_is_current(
                expected_mutation_binding
            )
        ):
            return False, "manual_execution_binding_stale"
        binding, snapshot, snapshot_payload = binding_state
        failure = BoundRuntimeFailure(
            binding=binding,
            protocol="HTTPS",
            observed_outbound=binding.observed_outbound,
            destination_token=runtime_destination_token(
                f"manual-contract:{request_id}"
            ),
            error_type="manual_dual_204_transport_failure",
            observed_at_monotonic=time.monotonic(),
        )
        first = self._runtime_egress_coordinator.observe(
            failure,
            current_snapshot=snapshot,
        )
        probe_token = str(first.probe_token or "")
        if not probe_token:
            current = self._runtime_egress_coordinator.current_snapshot_for(
                binding
            )
            probe_token = str(getattr(current, "probe_token", "") or "")
        confirmed = self._runtime_egress_coordinator.record_probe(
            failure,
            succeeded=False,
            probe_token=probe_token,
            current_snapshot=snapshot,
        )
        if not confirmed.confirmed:
            return False, str(confirmed.reason or "manual_confirmation_rejected")
        if (
            expected_mutation_binding is not None
            and not self._runtime_mutation_binding_is_current(
                expected_mutation_binding
            )
        ):
            return False, "manual_execution_binding_stale"
        self._start_runtime_recovery(
            failure,
            snapshot,
            snapshot_payload,
            incident_id=confirmed.incident_id,
            quarantine_token=confirmed.probe_token,
            confirmed_alternative=alternative,
            confirmed_alternative_probe_result={
                "manual_contracts": 2,
                "verified": True,
            }
            if alternative is not None
            else None,
        )
        while session.budget.remaining() > 0.0:
            with self._runtime_failure_monitor_lock:
                lease_record = self._runtime_route_mutation_lease
                state = str(
                    self._runtime_incident_recovery_state.get(
                        str(confirmed.incident_id),
                        "",
                    )
                    or ""
                )
                committed = bool(
                    isinstance(lease_record, dict)
                    and str(lease_record.get("incident_id") or "")
                    == str(confirmed.incident_id)
                    and str(lease_record.get("to") or "")
                    == (
                        alternative.proxy_name
                        if alternative is not None
                        else "REJECT"
                    )
                    and float(
                        lease_record.get("verified_at_monotonic", 0.0) or 0.0
                    )
                    > 0.0
                )
                fail_closed_selected = bool(
                    alternative is None
                    and isinstance(lease_record, dict)
                    and str(lease_record.get("incident_id") or "")
                    == str(confirmed.incident_id)
                    and str(lease_record.get("to") or "") == "REJECT"
                )
            if committed:
                return True, "replacement_selected_and_verified"
            if alternative is None and state == "ready":
                audit = getattr(self, "last_runtime_route_audit", None)
                audit = audit if isinstance(audit, dict) else {}
                if fail_closed_selected and bool(
                    audit.get("gateway_fail_closed")
                ) and bool(
                    audit.get("fail_closed_terminal")
                ):
                    return False, "gateway_fail_closed_verified"
                return False, "gateway_fail_closed_unverified"
            if state in {"manual_superseded", "route_superseded"}:
                return False, state
            time.sleep(min(0.005, session.budget.remaining()))
        return False, "replacement_commit_deadline_expired"

    def _promote_manual_egress_after_verified_probe(
        self,
        *,
        mutation_binding: CurrentMutationBinding | None,
        clean_current_success: bool,
        expected_hold_epoch: int | None = None,
        expected_facility_epoch: int | None = None,
    ) -> bool:
        """Atomically authorize the manual data-plane success side effect.

        Facility entry owns ``_runtime_failure_monitor_lock`` before changing
        its epoch. Keeping the last CAS, optional hold release and readiness /
        activation publication under that same lock removes the window where
        a network-context transition could arrive between validation and the
        user-visible ready state.
        """

        if not clean_current_success or mutation_binding is None:
            return False
        monitor_lock = getattr(self, "_runtime_failure_monitor_lock", None)
        if monitor_lock is None:
            monitor_lock = threading.RLock()
            self._runtime_failure_monitor_lock = monitor_lock
        # Manager's route-truth callbacks already use Manager -> monitor.
        # Queueing revalidation can read Manager capture state, so take the
        # same order here while keeping the final CAS/publication atomic.
        manager_lock = getattr(getattr(self, "manager", None), "lock", None)
        with (manager_lock if manager_lock is not None else nullcontext()), monitor_lock:
            if not self._runtime_mutation_binding_is_current(
                mutation_binding
            ):
                return False
            if (
                not self._runtime_uses_early_single_coordinator()
                and self._runtime_local_data_plane_blocked()
            ):
                return False
            current_facility_hold = (
                ""
                if self._runtime_uses_early_single_coordinator()
                else self._runtime_facility_hold_reason()
            )
            if current_facility_hold and not (
                self._release_runtime_network_context_hold_after_verified_probe(
                    expected_mutation_binding=mutation_binding,
                    expected_hold_epoch=expected_hold_epoch,
                    expected_facility_epoch=expected_facility_epoch,
                )
            ):
                return False
            if (
                not self._runtime_uses_early_single_coordinator()
                and self._runtime_facility_hold_reason()
            ):
                return False
            if hasattr(self, "_tier3_egress_activation_lock"):
                self._reset_tier3_standby_activation_failure()
            phase = self._current_core_runtime_phase()
            if phase == "formal_no_capture":
                self._queue_tier3_egress_activation()
            elif phase == "formal_capture" and (
                self.manager is None
                or getattr(self.manager, "effective_egress_ok", None) is not True
            ):
                self._set_effective_egress_readiness_state(True, "")
            return True

    def _manual_exit_quality_probe_budget(
        self,
        *,
        min_per_probe_seconds: float = 0.0,
    ) -> tuple[float, float]:
        recent_rtt: float | None = None
        verified_route = getattr(self, "_runtime_last_verified_route", None)
        verified_result = (
            verified_route.get("result")
            if isinstance(verified_route, dict)
            and isinstance(verified_route.get("result"), dict)
            else {}
        )
        for field_name in ("latency_ms", "delay", "delay_ms"):
            value = verified_result.get(field_name)
            if isinstance(value, (int, float)) and float(value) > 0.0:
                recent_rtt = float(value)
                break
        try:
            configured_seconds = max(
                0.5,
                float(self._default_probe_timeout_ms()) / 1000.0,
            )
        except Exception:
            configured_seconds = MAX_MANUAL_VALIDATION_SECONDS
        per_probe = adaptive_manual_probe_timeout(
            recent_rtt,
            configured_timeout_seconds=configured_seconds,
            default_seconds=2.0,
        )
        # Raise-only floor for the overview request. A recorded RTT may come
        # from another leaf and must not shrink this click's contracts.
        per_probe = max(
            per_probe,
            min(configured_seconds, MAX_MANUAL_PROBE_SECONDS, float(min_per_probe_seconds)),
        )
        # Current and replacement pairs are sequential, while each pair opens
        # its two fresh sockets concurrently. Preserve selector/readback room
        # without redefining a slow healthy TLS handshake as a failed leaf.
        total = min(
            MAX_MANUAL_VALIDATION_SECONDS,
            # A fast current-route success still returns immediately, while a
            # double failure retains enough bounded time to examine more than
            # the first fallback member and commit/read back the winner.
            max(3.0, 2.0 * per_probe + 0.75),
        )
        return per_probe, total

    def check_exit_quality(
        self,
        *,
        proxy_url: str | None,
        request_id: str,
        manual_validation_lease: ManualValidationLease | None = None,
        queue_identity_diagnostic: bool = True,
    ) -> dict[str, Any]:
        if manual_validation_lease is not None:
            lease_is_current = bool(
                str(manual_validation_lease.request_id) == str(request_id)
                and int(manual_validation_lease.lifecycle_revision)
                == int(getattr(self, "_lifecycle_revision", 0) or 0)
                and float(manual_validation_lease.deadline_monotonic)
                > time.monotonic()
            )
            if not lease_is_current:
                checked_at = utc_now_iso()
                return {
                    "schema_version": 2,
                    "request_id": request_id,
                    "state": "controller_hold",
                    "checked_at": checked_at,
                    "freshness": {
                        "state": "fresh",
                        "status": "partial",
                        "reason": "manual_validation_lease_stale",
                    },
                    "route": {},
                    "identity": {},
                    "diagnostics": {"identity_pending": False},
                }
        pressure = getattr(self, "_runtime_recovery_pressure", None)
        pressure_lease = None
        if (
            pressure is not None
            and not self._runtime_uses_early_single_coordinator()
        ):
            pressure_lease = pressure.acquire(
                f"manual-validation:{request_id}",
                RuntimeRecoveryPressurePriority.MANUAL,
                lifecycle_generation=pressure.lifecycle_generation,
            )
            if pressure_lease is None:
                checked_at = utc_now_iso()
                return {
                    "schema_version": 2,
                    "request_id": request_id,
                    "state": "controller_hold",
                    "checked_at": checked_at,
                    "freshness": {
                        "state": "fresh",
                        "status": "partial",
                        "reason": "runtime_recovery_in_progress",
                    },
                    "route": {},
                    "identity": {},
                    "diagnostics": {
                        "data_plane_checked_at": checked_at,
                        "identity_pending": False,
                        "neutral_connectivity": {
                            "state": "not_run",
                            "reason": "runtime_recovery_in_progress",
                        },
                    },
                }
        try:
            return self._check_exit_quality_impl(
                proxy_url=proxy_url,
                request_id=request_id,
                manual_validation_lease=manual_validation_lease,
                queue_identity_diagnostic=queue_identity_diagnostic,
            )
        finally:
            if pressure_lease is not None:
                pressure_lease.release()

    def _check_exit_quality_impl(
        self,
        *,
        proxy_url: str | None,
        request_id: str,
        manual_validation_lease: ManualValidationLease | None = None,
        queue_identity_diagnostic: bool = True,
    ) -> dict[str, Any]:
        del proxy_url
        per_probe_timeout, total_timeout = (
            self._manual_exit_quality_probe_budget(
                # Only the overview click brings its own lease.
                min_per_probe_seconds=(
                    _OVERVIEW_MIN_CONTRACT_PROBE_SECONDS
                    if manual_validation_lease is not None
                    else 0.0
                ),
            )
        )
        if manual_validation_lease is not None:
            total_timeout = min(
                total_timeout,
                max(
                    0.0,
                    float(manual_validation_lease.deadline_monotonic)
                    - time.monotonic(),
                ),
            )
        session = RuntimeManualValidation(
            total_timeout_seconds=total_timeout,
            per_probe_timeout_seconds=per_probe_timeout,
            route_contract_enabled=bool(
                self._node_judgement_policy().manual_check_uses_route_contract
            ),
        )
        if manual_validation_lease is None:
            with self._runtime_route_snapshot_lock:
                manual_validation_lease = ManualValidationLease(
                    request_id=str(request_id),
                    lifecycle_revision=int(
                        getattr(self, "_lifecycle_revision", 0) or 0
                    ),
                    route_epoch=int(
                        getattr(self, "_runtime_route_epoch", 0) or 0
                    ),
                    network_context_epoch=int(
                        getattr(self, "_runtime_network_context_epoch", 0) or 0
                    ),
                    deadline_monotonic=float(
                        session.budget.deadline_monotonic
                    ),
                )
        core_running = bool(self.core_runner and self.core_runner.is_running())

        def bounded_route_context(max_seconds: float) -> dict[str, Any]:
            timeout_seconds = min(
                max(0.0, float(max_seconds)),
                session.budget.remaining(),
            )
            if timeout_seconds <= 0.0:
                return {}
            try:
                return self._exit_quality_route_for_display(
                    self.current_route_context(
                        force=True,
                        timeout_seconds=timeout_seconds,
                    )
                )
            except TypeError:
                # Narrow injected adapters may still implement the legacy
                # signature. Production always honors the bounded timeout.
                return self._exit_quality_route_for_display(
                    self.current_route_context(force=True)
                )

        # Freeze the exact execution owner immediately before opening the two
        # fresh sockets.  A later selector/Core/network change may keep the
        # same logical route label, but it must still make these probe results
        # ineligible to quarantine or reopen whichever leaf took over.
        binding_state: tuple[
            RuntimeRouteBinding,
            CoreLoadedRouteSnapshot,
            dict[str, Any],
        ] | None = None
        manual_mutation_binding: CurrentMutationBinding | None = None
        manual_probe_hold_epoch: int | None = None
        manual_probe_facility_epoch: int | None = None
        if core_running:
            try:
                binding_state = self._current_runtime_failure_binding_state(
                    timeout_seconds=min(
                        _MANUAL_BINDING_READBACK_SECONDS,
                        session.budget.remaining(),
                    ),
                )
            except Exception:
                binding_state = None
            if binding_state is not None:
                manual_mutation_binding = (
                    self._runtime_mutation_binding_for_snapshot(
                        binding_state[1]
                    )
                )
                (
                    manual_probe_hold_epoch,
                    manual_probe_facility_epoch,
                ) = self._runtime_facility_hold_cas_token()
        route_before: dict[str, Any] = {}
        if binding_state is not None:
            _origin_binding, origin_snapshot, origin_payload = binding_state
            controller_payload = (
                origin_payload.get("proxies")
                if isinstance(origin_payload, dict)
                else None
            )
            route_before = dict(
                inspect_runtime_route(
                    controller_payload,
                    start="FINAL-EXIT",
                )
            )
            route_before.update(
                {
                    "path_kind": "mihomo_proxy",
                    "core_instance": (
                        f"{int(getattr(self, '_runtime_generation', 0) or 0)}:"
                        f"{int(origin_snapshot.core_generation)}:"
                        f"{int(origin_snapshot.process_pid)}"
                    ),
                    "confirmed": not bool(
                        route_before.get("facility_failure")
                    ),
                }
            )
            route_before = self._exit_quality_route_for_display(route_before)
        elif core_running:
            try:
                route_before = bounded_route_context(
                    _MANUAL_BINDING_READBACK_SECONDS
                )
            except Exception:
                route_before = {}
        # Node judgement P0-4: judge a non-Gateway leaf by its owning group's
        # contract (plus one neutral) instead of two neutral URLs.
        route_contract_plan = (
            self._manual_route_contract_plan(binding_state)
            if core_running and session.route_contract_enabled
            else None
        )
        if core_running and route_contract_plan is not None:
            current_results = self._manual_route_contract_current_contracts(
                session,
                route_contract_plan,
            )
            decision = session.evaluate(current_results)
        elif core_running:
            current_results = self._manual_current_exit_quality_contracts(
                session
            )
            decision = session.evaluate(current_results)
        else:
            current_results = ()
            decision = session.evaluate(())
        route_contract_leaf_failure = bool(
            route_contract_plan is not None
            and decision.route_contract_leaf_failure
        )

        alternative: RuntimeNodeRef | None = None
        alternative_probe_evidence: _HotStandbyEvidence | None = None
        switch_committed = False
        switch_reason = ""
        backup_results: tuple[ManualDataPlaneProbeResult, ...] = ()
        gateway_underlay_results: tuple[ManualDataPlaneProbeResult, ...] = ()
        probe_end_state = None
        if manual_mutation_binding is not None:
            try:
                probe_end_state = self._current_runtime_failure_binding_state(
                    timeout_seconds=min(
                        _MANUAL_ROUTE_DISPLAY_READBACK_SECONDS,
                        session.budget.remaining(),
                    ),
                )
            except Exception:
                probe_end_state = None
        manual_execution_current = bool(
            binding_state is not None
            and probe_end_state is not None
            and manual_mutation_binding is not None
            and probe_end_state[0].circuit_key
            == binding_state[0].circuit_key
            and tuple(probe_end_state[1].snapshot_key)
            == tuple(binding_state[1].snapshot_key)
            and self._runtime_mutation_binding_is_current(
                manual_mutation_binding
            )
        )
        facility_hold_at_probe_end = (
            ""
            if self._runtime_uses_early_single_coordinator()
            else self._runtime_facility_hold_reason()
        )
        if decision.backup_required and facility_hold_at_probe_end:
            switch_reason = "facility_hold"
        native_successor: RuntimeNodeRef | None = None
        if (
            route_contract_plan is not None
            and route_contract_leaf_failure
            and decision.backup_required
            and core_running
            and binding_state is not None
            and not facility_hold_at_probe_end
            and not manual_execution_current
        ):
            # The route contract's failed URL test is Mihomo's own demotion,
            # so the owning group already moved.  Rebind to that one change.
            rebound = self._manual_route_contract_native_rebind(
                route_contract_plan,
                binding_state,
                probe_end_state,
                manual_mutation_binding,
            )
            if rebound is not None:
                binding_state, manual_mutation_binding, native_successor = (
                    rebound
                )
                manual_execution_current = True
        if (
            decision.backup_required
            and core_running
            and not facility_hold_at_probe_end
            and not manual_execution_current
        ):
            # Never bind failed sockets to a route discovered after they
            # completed.  The current route will establish its own evidence
            # on the next connection/guard cycle.
            binding_state = None
            switch_reason = "manual_execution_binding_stale"
        if (
            native_successor is not None
            and route_contract_plan is not None
            and decision.backup_required
            and binding_state is not None
            and manual_execution_current
            and not facility_hold_at_probe_end
        ):
            # No selector write (no pin, natural failback): the move is
            # Mihomo's.  Prove its successor on the same contract pair.
            successor_results = self._manual_verify_native_successor(
                session,
                route_contract_plan,
                native_successor,
            )
            if successor_results is None:
                switch_reason = "native_fallback_unverified_budget"
            else:
                backup_results = successor_results
                decision = session.evaluate(current_results, successor_results)
                if decision.switch_before_return:
                    # §18.7 native_commit: the failed leaf enters the pool
                    # rules exactly as today's verified switch does, without
                    # any selector write.  The verified move itself stands
                    # even when the health commit is rejected.
                    alternative = native_successor
                    commit_accepted, _commit_reason = (
                        self._manual_route_contract_native_commit(
                            session,
                            binding_state=binding_state,
                            plan=route_contract_plan,
                            successor=native_successor,
                            request_id=request_id,
                            expected_mutation_binding=manual_mutation_binding,
                        )
                    )
                    switch_committed = bool(
                        manual_mutation_binding is not None
                        and self._runtime_mutation_binding_is_current(
                            manual_mutation_binding
                        )
                    )
                    if not switch_committed:
                        # The route changed again after the successor's
                        # proof: nothing about the current route is known.
                        switch_reason = "manual_execution_binding_stale"
                    elif commit_accepted:
                        switch_reason = "native_fallback_verified"
                    else:
                        switch_reason = "native_fallback_verified_commit_rejected"
                else:
                    switch_reason = "native_fallback_unverified"
        elif (
            decision.backup_required
            and binding_state is not None
            and manual_execution_current
            and not facility_hold_at_probe_end
        ):
            original_binding, snapshot, snapshot_payload = binding_state
            binding = original_binding
            recovery_binding_state = binding_state
            if original_binding.node.pool_kind == "gateway":
                underlay = self._runtime_gateway_underlay_binding(
                    snapshot,
                    snapshot_payload,
                    original_binding.node,
                )
                if underlay is None:
                    switch_reason = "gateway_underlay_binding_unavailable"
                    if not self._runtime_uses_early_single_coordinator():
                        self._record_runtime_facility_degradation(
                            "Manual Gateway validation could not bind its managed underlay"
                        )
                else:
                    gateway_underlay_results = (
                        self._manual_backup_exit_quality_contracts(
                            session,
                            underlay.node,
                        )
                    )
                    gateway_decision = session.evaluate(
                        current_results,
                        gateway_underlay_results,
                    )
                    if gateway_decision.switch_before_return:
                        # The exact underlay passed both contracts while the
                        # complete fixed Gateway chain failed them.  Attribute
                        # the incident to the Gateway itself and fail closed;
                        # never quarantine or rotate its healthy underlay.
                        decision = gateway_decision
                        backup_results = gateway_underlay_results
                        _ignored, switch_reason = (
                            self._manual_confirm_and_switch_before_return(
                                session,
                                binding_state=binding_state,
                                alternative=None,
                                request_id=request_id,
                                expected_mutation_binding=(
                                    manual_mutation_binding
                                ),
                            )
                        )
                        binding = original_binding
                    else:
                        underlay_decision = session.evaluate(
                            gateway_underlay_results
                        )
                        if underlay_decision.backup_required:
                            # Only a direct double failure of the current
                            # underlay may move attribution below the fixed
                            # Gateway.  The Gateway identity remains selected.
                            binding = underlay
                            recovery_binding_state = (
                                underlay,
                                snapshot,
                                snapshot_payload,
                            )
                            decision = underlay_decision
                        else:
                            decision = gateway_decision
                            switch_reason = (
                                "gateway_underlay_differential_indeterminate"
                            )
                            if not self._runtime_uses_early_single_coordinator():
                                self._record_runtime_facility_degradation(
                                    "Gateway and underlay differential validation was indeterminate"
                                )
            if binding.node.pool_kind != "gateway":
                recovery_failure = BoundRuntimeFailure(
                    binding=binding,
                    protocol="HTTPS",
                    observed_outbound=binding.observed_outbound,
                    destination_token=runtime_destination_token(
                        f"manual-candidates:{request_id}"
                    ),
                    error_type="manual_dual_204_transport_failure",
                    observed_at_monotonic=time.monotonic(),
                )
                candidates = self._runtime_ordered_alternative_refs(
                    recovery_failure,
                    snapshot,
                    snapshot_payload,
                )
                base_results = (
                    gateway_underlay_results
                    if original_binding.node.pool_kind == "gateway"
                    else current_results
                )
                # Probe candidates in loaded policy order.  Each candidate's
                # two independent contracts reserve the two global slots as an
                # atomic pair; candidates themselves are sequential so a fast
                # lower-priority node can never overtake an earlier healthy
                # one.  Divide the remaining evidence budget so one dead first
                # backup cannot consume every future click indefinitely.
                for index, candidate in enumerate(candidates):
                    selection_action = self._runtime_alternative_switch_action(
                        recovery_failure,
                        candidate,
                        snapshot_payload,
                        allow_pf_subtree_select=True,
                    )
                    if not isinstance(selection_action, dict):
                        continue
                    (
                        candidate_contract_urls,
                        group_probe_url,
                        group_expected_status,
                    ) = self._manual_backup_exit_quality_contract_urls(
                        snapshot,
                        selection_action,
                    )
                    evidence_budget = max(
                        0.0,
                        session.budget.remaining()
                        - _MANUAL_SELECTOR_COMMIT_RESERVE_SECONDS,
                    )
                    if evidence_budget <= 0.1:
                        break
                    remaining_candidates = max(1, len(candidates) - index)
                    phase_timeout = min(
                        session.budget.per_probe_timeout_seconds,
                        max(0.1, evidence_budget / remaining_candidates),
                    )
                    candidate_results = (
                        self._manual_backup_exit_quality_contracts(
                            session,
                            candidate,
                            phase_timeout_seconds=phase_timeout,
                            contract_urls=candidate_contract_urls,
                        )
                    )
                    evaluation_base = base_results
                    relabelled_base = False
                    if route_contract_plan is not None:
                        # P0-4: backup ids must name the same contracts as
                        # the route-contract current pair.
                        (
                            candidate_results,
                            evaluation_base,
                            relabelled_base,
                        ) = self._manual_route_contract_align_backup(
                            route_contract_plan,
                            base_results,
                            candidate_results,
                            candidate_contract_urls,
                            group_probe_url,
                        )
                    candidate_decision = session.evaluate(
                        evaluation_base,
                        candidate_results,
                    )
                    backup_results = candidate_results
                    if (
                        not relabelled_base
                        or candidate_decision.switch_before_return
                    ):
                        # A decision taken on a relabelled current pair is
                        # reported only when it switches.
                        decision = candidate_decision
                    indeterminate_kinds = {
                        ManualProbeFailureKind.FACILITY,
                        ManualProbeFailureKind.CANCELLED,
                        ManualProbeFailureKind.UNKNOWN,
                    }
                    if any(
                        result.normalised_failure_kind
                        in indeterminate_kinds
                        for result in candidate_results
                    ):
                        # Admission/queue/controller uncertainty says nothing
                        # about this policy-ordered candidate.  Stop here: a
                        # later lower-priority PASS must not overtake an
                        # earlier member that never received an authoritative
                        # socket attempt.
                        switch_reason = (
                            "ordered_candidate_probe_indeterminate"
                        )
                        break
                    if not candidate_decision.switch_before_return:
                        continue
                    alternative = candidate
                    if group_probe_url:
                        alternative_probe_evidence = _HotStandbyEvidence(
                            ref=candidate,
                            action=dict(selection_action),
                            snapshot_key=snapshot.snapshot_key,
                            network_context_epoch=(
                                snapshot.network_context_epoch
                            ),
                            verified_at_monotonic=time.monotonic(),
                            latency_ms=0.0,
                            probe_result={
                                "manual_contracts": 2,
                                "verified": True,
                            },
                            selection_group=str(
                                selection_action.get("group") or ""
                            ),
                            selection_target=str(
                                selection_action.get("target") or ""
                            ),
                            selection_mode=str(
                                selection_action.get("mode") or ""
                            ),
                            probe_url=group_probe_url,
                            expected_status=group_expected_status,
                            probed_proxy_name=candidate.proxy_name,
                        )
                    break
            if alternative is not None and decision.switch_before_return:
                switch_committed, switch_reason = (
                    self._manual_confirm_and_switch_before_return(
                        session,
                        binding_state=recovery_binding_state,
                        alternative=alternative,
                        request_id=request_id,
                        expected_mutation_binding=(manual_mutation_binding),
                        alternative_probe_evidence=(
                            alternative_probe_evidence
                        ),
                    )
                )

        route_after: dict[str, Any] = {}
        if core_running:
            try:
                route_after = bounded_route_context(
                    _MANUAL_ROUTE_DISPLAY_READBACK_SECONDS
                )
            except Exception:
                route_after = {}

        route_before_comparable = bool(
            route_before
            and not route_before.get("facility_failure")
            and str(route_before.get("path_kind") or "") != "unavailable"
        )
        route_after_comparable = bool(
            route_after
            and not route_after.get("facility_failure")
            and str(route_after.get("path_kind") or "") != "unavailable"
        )
        execution_route_changed = bool(
            route_before_comparable
            and route_after_comparable
            and not self._exit_routes_logically_match(route_before, route_after)
        )
        intent_changed = bool(
            manual_mutation_binding is not None
            and int(
                getattr(self, "_runtime_selector_intent_revision", 0) or 0
            )
            != int(manual_mutation_binding.selector_intent_revision)
        )
        route_changed = bool(execution_route_changed and intent_changed)
        route_settled = bool(execution_route_changed and not intent_changed)
        current_route = route_after or route_before
        if current_route:
            current_route = self._exit_quality_route_for_display(current_route)
            current_route["stable_during_check"] = not execution_route_changed
            current_route["confirmed_before"] = bool(route_before.get("confirmed"))
            current_route["confirmed_after"] = bool(route_after.get("confirmed"))

        latest = getattr(self.exit_quality_service, "latest_result", None)
        try:
            cached = latest() if callable(latest) else None
        except Exception:
            cached = None
        checked_at = utc_now_iso()
        success_count = sum(
            result.is_https_204_success(session.budget)
            for result in current_results
        )
        capture_proof_required = self._system_proxy_capture_proof_required()
        capture_target_active = True
        capture_host_path_verified = not capture_proof_required
        capture_host_path_reason = ""
        capture_probe_indeterminate = False
        capture_probe_indeterminate_reason = ""
        if capture_proof_required:
            try:
                capture_target_active = bool(
                    self.system_proxy.is_target_active()
                )
            except Exception:
                capture_target_active = False
            if capture_target_active and success_count == 2:
                try:
                    if session.budget.remaining() <= 0.05:
                        raise _RuntimeProbeBudgetUnavailable(
                            "manual validation has no host proof budget remaining"
                        )
                    capture_proof = self._verify_system_proxy_host_capture(
                        deadline_monotonic=session.budget.deadline_monotonic,
                        priority=ProbePriority.RUNTIME_MANUAL,
                    )
                    capture_host_path_verified = bool(
                        isinstance(capture_proof, dict)
                        and capture_proof.get("verified") is True
                    )
                    if not capture_host_path_verified:
                        capture_host_path_reason = (
                            "system_proxy_host_path_unverified"
                        )
                except Exception as exc:
                    capture_host_path_verified = False
                    capture_host_path_reason = type(exc).__name__
                    capture_probe_indeterminate = isinstance(
                        exc, _RuntimeProbeBudgetUnavailable
                    )
                    capture_probe_indeterminate_reason = str(
                        getattr(exc, "probe_indeterminate_reason", "") or ""
                    )
        current_data_plane_success = bool(
            success_count == 2
            and capture_target_active
            and capture_host_path_verified
        )
        manual_execution_current = bool(
            manual_execution_current
            and manual_mutation_binding is not None
            and self._runtime_mutation_binding_is_current(
                manual_mutation_binding
            )
        )
        clean_current_success = bool(
            core_running
            and current_data_plane_success
            and not execution_route_changed
            and manual_execution_current
            and (
                self._runtime_uses_early_single_coordinator()
                or not self._runtime_local_data_plane_blocked()
            )
        )
        self._promote_manual_egress_after_verified_probe(
            mutation_binding=manual_mutation_binding,
            clean_current_success=clean_current_success,
            expected_hold_epoch=manual_probe_hold_epoch,
            expected_facility_epoch=manual_probe_facility_epoch,
        )
        execution_binding_unverified = bool(
            not switch_committed
            and not manual_execution_current
            and (
                self._runtime_uses_early_single_coordinator()
                or manual_mutation_binding is not None
            )
        )
        probe_indeterminate = bool(
            not current_results
            or any(
                result.normalised_failure_kind
                in {
                    ManualProbeFailureKind.FACILITY,
                    ManualProbeFailureKind.CANCELLED,
                }
                or not result.completed_within(session.budget)
                for result in current_results
            )
        )
        validation_indeterminate = bool(
            core_running
            and not switch_committed
            and (
                probe_indeterminate
                or capture_probe_indeterminate
                or execution_binding_unverified
            )
        )
        identity_pending = bool(
            core_running
            and (current_data_plane_success or switch_committed)
            and capture_target_active
            and (not execution_route_changed or switch_committed)
            and not execution_binding_unverified
        )
        payload: dict[str, Any] = {
            "schema_version": 2,
            "request_id": request_id,
            "state": (
                "pending_identity"
                if identity_pending
                else "data_plane_failed"
                if core_running
                else "unavailable"
            ),
            "checked_at": checked_at,
            "freshness": {
                "state": "fresh",
                "status": "partial" if identity_pending else "failed",
            },
            "route": current_route,
            "identity": {},
            "validation_lifecycle_revision": int(
                manual_validation_lease.lifecycle_revision
            ),
            "validation_route_epoch": int(
                manual_validation_lease.route_epoch
            ),
            "validation_network_context_epoch": int(
                manual_validation_lease.network_context_epoch
            ),
            "validation_deadline_monotonic": float(
                manual_validation_lease.deadline_monotonic
            ),
        }
        diagnostics: dict[str, Any] = {
            "data_plane_checked_at": checked_at,
            "probe_indeterminate_reasons": list(dict.fromkeys([
                str(result.probe_indeterminate_reason)
                for result in (*current_results, *backup_results, *gateway_underlay_results)
                if result.probe_indeterminate_reason
            ] + ([capture_probe_indeterminate_reason] if capture_probe_indeterminate_reason else []))),
            "route_before": route_before,
            "route_after": route_after,
            "system_proxy_capture": {
                "required": capture_proof_required,
                "target_active": capture_target_active,
                "host_path_verified": capture_host_path_verified,
                "host_path_reason": capture_host_path_reason,
            },
        }

        cached_route = (
            cached.get("route")
            if isinstance(cached, dict) and isinstance(cached.get("route"), dict)
            else {}
        )
        cached_route_matches = bool(
            current_route
            and cached_route
            and self._exit_routes_logically_match(cached_route, current_route)
        )
        if (
            isinstance(cached, dict)
            and cached_route_matches
            and not execution_route_changed
        ):
            for field_name in (
                "identity",
                "network",
                "reputation",
                "coverage",
                "evidence",
            ):
                if field_name in cached:
                    payload[field_name] = copy.deepcopy(cached[field_name])
            cached_checked_at = str(cached.get("checked_at") or "").strip()
            if cached_checked_at:
                payload["identity_checked_at"] = cached_checked_at
            if cached.get("expires_at"):
                payload["identity_expires_at"] = cached.get("expires_at")
            payload["identity_source"] = "cache"
            cached_diagnostics = (
                cached.get("diagnostics")
                if isinstance(cached.get("diagnostics"), dict)
                else {}
            )
            for field_name in (
                "identity",
                "identity_error",
                "all_identity_failed",
                "source_errors",
                "dns_reachability",
                "dns_leak_test",
            ):
                if field_name in cached_diagnostics:
                    diagnostics[field_name] = copy.deepcopy(
                        cached_diagnostics[field_name]
                    )
            diagnostics["identity_cache"] = {
                "state": "matched",
                "source_request_id": str(cached.get("request_id") or ""),
                "source_checked_at": cached_checked_at,
                "binding_marker": str(
                    current_route.get("binding_marker") or ""
                ),
            }
        else:
            diagnostics["identity_cache"] = {
                "state": (
                    "route_mismatch"
                    if isinstance(cached, dict) and cached_route and current_route
                    else "unavailable"
                )
            }

        diagnostics["neutral_connectivity"] = {
            "state": (
                "recovered"
                if switch_committed
                else "ok"
                if current_data_plane_success
                else "mixed"
                if success_count == 1
                else "failed"
                if core_running
                else "not_run"
            ),
            "contracts": len(current_results),
            "success_count": success_count,
            "outcome": decision.outcome.value,
            "switch_committed": switch_committed,
            "switch_reason": switch_reason,
            "per_probe_ms": round(session.budget.per_probe_timeout_seconds * 1000),
            "contract_failure_kinds": [
                result.normalised_failure_kind.value for result in current_results
            ],
            "execution_binding_current": manual_execution_current,
            "backup_verified": bool(
                backup_results and decision.backup_success_count == 2
            ),
            "gateway_underlay_contracts": len(gateway_underlay_results),
            "gateway_underlay_success_count": sum(
                result.is_https_204_success(session.budget)
                for result in gateway_underlay_results
            ),
        }
        if route_contract_plan is not None:
            # P0-4: the current pair was (owning-group contract, neutral).
            diagnostics["neutral_connectivity"].update(
                {
                    "route_contract": True,
                    "route_contract_leaf_failure": route_contract_leaf_failure,
                }
            )
        diagnostics["identity_pending"] = identity_pending
        if success_count == 2 and not capture_target_active:
            payload["freshness"] = {
                "state": "fresh",
                "status": "failed",
                "reason": "system_proxy_capture_inactive",
            }
        elif success_count == 2 and not capture_host_path_verified:
            payload["freshness"] = {
                "state": "fresh",
                "status": "failed",
                "reason": "system_proxy_host_path_unverified",
            }
        payload["diagnostics"] = diagnostics
        if validation_indeterminate:
            # Queue contention/cancellation and stale execution ownership do
            # not prove that a working route has failed. Keep those outcomes
            # separate from actual transport evidence and never attach an
            # identity result to sockets from a superseded runtime binding.
            payload["state"] = "data_plane_indeterminate"
            payload["freshness"] = {
                "state": "fresh",
                "status": "partial",
                "reason": (
                    "manual_execution_binding_unverified"
                    if execution_binding_unverified
                    else "system_proxy_host_probe_not_completed"
                    if capture_probe_indeterminate
                    else "manual_probe_not_completed"
                ),
            }
            diagnostics["neutral_connectivity"]["state"] = "indeterminate"
            diagnostics["identity_pending"] = False
        if route_settled and not switch_committed:
            # Mihomo fallback health settling is an internal ownership event,
            # not a sticky user-facing "chain changed" error. The sockets from
            # this check still belong to the old execution binding, so report
            # an indeterminate fresh result and let the next click/new flow use
            # the now-current route.
            payload["state"] = "data_plane_indeterminate"
            payload["freshness"] = {
                **(
                    payload.get("freshness")
                    if isinstance(payload.get("freshness"), dict)
                    else {}
                ),
                "state": "fresh",
                "status": "partial",
                "reason": "route_settled_during_check",
            }
            diagnostics["neutral_connectivity"]["route_settled"] = True
        if route_changed:
            payload["state"] = "route_changed"
            payload["route_changed"] = True
            payload["freshness"] = {
                **(
                    payload.get("freshness")
                    if isinstance(payload.get("freshness"), dict)
                    else {}
                ),
                "state": "stale",
                "status": "invalid",
                "reason": "route_changed",
            }
        if queue_identity_diagnostic and str(payload.get("state") or "") == "pending_identity":
            # This legacy API is an explicit caller-owned check.  Keep its
            # asynchronous identity result complete without reconnecting it
            # to startup, monitoring, readiness, or automatic recovery.
            self._queue_final_exit_identity_diagnostic(request_id=request_id)
        return payload

    def latest_exit_quality_result(self) -> dict[str, Any]:
        latest = getattr(self.exit_quality_service, "latest_result", None)
        if not callable(latest):
            return {}
        result = latest()
        if not isinstance(result, dict):
            return {}
        payload = dict(result)
        saved_route = (
            payload.get("route")
            if isinstance(payload.get("route"), dict)
            else {}
        )
        saved_route = self._exit_quality_route_for_display(saved_route)
        payload["route"] = saved_route
        current_route = self._exit_quality_route_for_display(
            self.current_route_context(force=True)
        )
        saved_binding = str(saved_route.get("binding_marker") or "").strip()
        current_binding = str(current_route.get("binding_marker") or "").strip()
        if (
            not saved_binding
            or not current_binding
            or not self._exit_routes_logically_match(saved_route, current_route)
        ):
            # A historical identity belongs to another logical chain.  It is
            # not a new validation attempt and therefore must not manufacture
            # a user-visible "route changed" result for the current session.
            return {}
        payload["identity_source"] = "cache"
        if (
            str(payload.get("state") or "") == "route_changed"
            or bool(payload.get("route_changed"))
        ):
            # Route change is an event scoped to one completed manual check,
            # never a property of cached identity data. Replaying that event
            # on every overview poll creates the exact sticky warning loop the
            # cache is meant to avoid.
            payload.pop("route_changed", None)
            payload["state"] = "partial"
            freshness = (
                dict(payload.get("freshness"))
                if isinstance(payload.get("freshness"), dict)
                else {}
            )
            freshness.pop("reason", None)
            freshness.update({"state": "cached", "status": "partial"})
            payload["freshness"] = freshness
        diagnostics = (
            payload.get("diagnostics")
            if isinstance(payload.get("diagnostics"), dict)
            else {}
        )
        payload["diagnostics"] = {
            **diagnostics,
            "identity_cache": {
                "state": "matched",
                "source_request_id": str(payload.get("request_id") or ""),
                "source_checked_at": str(payload.get("checked_at") or ""),
                "binding_marker": saved_binding,
            },
        }
        return payload

    def recent_exit_quality_results(self) -> list[dict[str, Any]]:
        recent = getattr(self.exit_quality_service, "recent_results", None)
        if not callable(recent):
            return []
        return [dict(item) for item in recent() if isinstance(item, dict)]

    def refresh_exit_quality_static_data_async(self, *, force: bool = False) -> bool:
        refresher = getattr(self.exit_quality_service, "refresh_static_sources", None)
        if not callable(refresher):
            return False
        stop_event = getattr(self, "stop_event", None)
        cancel_event = getattr(
            self,
            "_exit_quality_static_refresh_cancel_event",
            None,
        )
        if cancel_event is None:
            cancel_event = threading.Event()
            self._exit_quality_static_refresh_cancel_event = cancel_event
        if (
            (stop_event is not None and stop_event.is_set())
            or cancel_event.is_set()
        ):
            return False
        manager = getattr(self, "manager", None)
        if manager is None or getattr(manager, "effective_egress_ok", None) is not True:
            self.logger.info(
                "Deferring exit-quality static dataset refresh until FINAL-EXIT is verified"
            )
            return False
        try:
            core_proxy_url = self._running_core_mixed_proxy_url()
        except RuntimeError:
            self.logger.info(
                "Deferring exit-quality static dataset refresh because Mihomo core is unavailable"
            )
            return False
        with self._exit_quality_static_refresh_lock:
            if (
                (stop_event is not None and stop_event.is_set())
                or cancel_event.is_set()
            ):
                return False
            worker = self._exit_quality_static_refresh_thread
            if worker is not None and worker.is_alive():
                return False
            now = time.monotonic()
            if not force and now - self._exit_quality_static_refresh_started_at < 300.0:
                return False
            self._exit_quality_static_refresh_started_at = now

            def run() -> None:
                try:
                    parameters = inspect.signature(
                        refresher
                    ).parameters.values()
                    accepts_cancel_event = any(
                        parameter.kind is inspect.Parameter.VAR_KEYWORD
                        or parameter.name == "cancel_event"
                        for parameter in parameters
                    )
                except (TypeError, ValueError):
                    accepts_cancel_event = True
                try:
                    kwargs: dict[str, Any] = {"proxy_url": core_proxy_url}
                    if accepts_cancel_event:
                        kwargs["cancel_event"] = cancel_event
                    refresher(**kwargs)
                except Exception:
                    if cancel_event.is_set():
                        return
                    log_raw_diagnostic(
                        self.logger,
                        "warning",
                        "Exit-quality static dataset refresh failed",
                        exc_info=True,
                    )

            worker = threading.Thread(
                target=run,
                name="exit-quality-static-refresh",
                daemon=True,
            )
            self._exit_quality_static_refresh_thread = worker
            worker.start()
            return True

    def node_status_snapshot(self) -> dict[str, Any]:
        """Return live nodes or the read-only Tier2/Exit persisted inventory."""

        manager = self.manager
        if manager is not None:
            manager_lock = getattr(manager, "lock", None)
            lock_context = (
                manager_lock
                if hasattr(manager_lock, "__enter__")
                else nullcontext()
            )
            provenance: dict[
                str,
                tuple[set[str], dict[str, str | None], Any],
            ] = {}
            # Manager uses an RLock, so its snapshot method can safely re-enter
            # while raw source identities are captured from the same generation.
            with lock_context:
                payload = manager.get_node_status_snapshot()
                payload["snapshot_origin"] = "live"
                for tier_id, tier_payload in payload.get("tiers", {}).items():
                    if not isinstance(tier_payload, dict):
                        continue
                    tier_id = str(tier_id)
                    if tier_id not in {"tier2", "exit"}:
                        continue
                    subscription_urls = enabled_subscription_urls(
                        self._tier_config(tier_id).get(
                            "subscription_urls",
                            [],
                        )
                    )
                    cached_at = getattr(
                        manager,
                        f"{tier_id}_last_refresh_at",
                        None,
                    )
                    evidence_getter = getattr(
                        manager,
                        "subscription_source_check_snapshot",
                        None,
                    )
                    raw_evidence = (
                        evidence_getter(tier_id)
                        if callable(evidence_getter)
                        else {}
                    )
                    checked_sources: dict[str, str | None] = {}
                    manager_generation = getattr(
                        manager,
                        "runtime_generation",
                        None,
                    )
                    if isinstance(raw_evidence, dict):
                        for source_url, entry in raw_evidence.items():
                            url = str(source_url or "").strip()
                            if url not in subscription_urls or not isinstance(
                                entry,
                                dict,
                            ):
                                continue
                            if manager_generation is not None:
                                try:
                                    evidence_generation = int(
                                        entry.get("runtime_generation", -1)
                                    )
                                    current_generation = int(
                                        manager_generation
                                    )
                                except (TypeError, ValueError):
                                    continue
                                if evidence_generation != current_generation:
                                    continue
                            checked_sources[url] = (
                                str(entry.get("checked_at") or "").strip()
                                or None
                            )
                    subscription_identities: set[str] = set()
                    checked_identity_observed_at: dict[str, str | None] = {}
                    raw_nodes = getattr(manager, "runtime_nodes", {}).get(
                        tier_id,
                        [],
                    )
                    identity_getter = getattr(manager, "_node_identity", None)
                    for raw_node in raw_nodes:
                        matching_sources = [
                            url
                            for url in subscription_urls
                            if node_has_subscription_source(raw_node, url)
                        ]
                        if not matching_sources:
                            continue
                        if callable(identity_getter):
                            identity = str(identity_getter(raw_node))
                        else:
                            identity = "|".join(
                                [
                                    str(getattr(raw_node, "tier", "")),
                                    *map(
                                        str,
                                        getattr(raw_node, "dedupe_key", ()),
                                    ),
                                ]
                            )
                        subscription_identities.add(identity)
                        checked_at_values = [
                            checked_sources[url]
                            for url in matching_sources
                            if url in checked_sources and checked_sources[url]
                        ]
                        if any(url in checked_sources for url in matching_sources):
                            checked_identity_observed_at[identity] = max(
                                checked_at_values,
                                default=None,
                            )
                    provenance[tier_id] = (
                        subscription_identities,
                        checked_identity_observed_at,
                        cached_at,
                    )
            for tier_id, tier_payload in payload.get("tiers", {}).items():
                if not isinstance(tier_payload, dict):
                    continue
                tier_id = str(tier_id)
                tier_observed_at = tier_payload.get("last_check_at")
                (
                    subscription_identities,
                    checked_identity_observed_at,
                    cached_at,
                ) = provenance.get(
                    tier_id,
                    (set(), {}, None),
                )
                for node in tier_payload.get("nodes", []):
                    if not isinstance(node, dict):
                        continue
                    identity = str(node.get("identity") or "")
                    if (
                        identity in subscription_identities
                        and identity not in checked_identity_observed_at
                    ):
                        node["observation_origin"] = "persisted_cache"
                        node["cached_at"] = cached_at
                        node["observed_at"] = node.get("last_checked_at")
                    else:
                        node["observation_origin"] = "live"
                        node.pop("cached_at", None)
                        if identity in checked_identity_observed_at:
                            node["observed_at"] = (
                                node.get("last_checked_at")
                                or checked_identity_observed_at[identity]
                            )
                        else:
                            node["observed_at"] = (
                                node.get("last_checked_at")
                                or tier_observed_at
                            )
            return payload
        return persisted_subscription_node_snapshot(self.config)

    def status(self, *, include_runtime_nodes: bool = True) -> dict[str, Any]:
        clash_config_url = self.clash_config_url(include_token=False)
        raw_core_status = self.core_runner.status() if self.core_runner else None
        core_status = dict(raw_core_status) if isinstance(raw_core_status, dict) else default_core_status()
        runtime_snapshot = self.manager.get_runtime_snapshot(include_nodes=include_runtime_nodes) if self.manager else None
        core_running = bool(core_status.get("running")) if isinstance(core_status, dict) else False
        startup_terminal_failed = bool(
            self._tier3_startup_terminal_failure
            and self._tier3_required_for_start
        )
        core_status["loaded_protocol_counts"] = self._loaded_core_protocol_counts_snapshot(
            core_running=core_running,
        )
        core_cleanup_pending = bool(
            core_status.get("cleanup_pending")
        ) if isinstance(core_status, dict) else False
        last_stop_failed = str(self._last_runtime_stop.get("result") or "") == "failed"
        effective_last_error = (
            self.last_error
            if (not core_running or last_stop_failed or startup_terminal_failed)
            else None
        )
        payload = desktop_runtime_status_payload(
            running=self.running,
            last_error=effective_last_error,
            clash_config_url=clash_config_url,
            subscription_config=subscription_server_block(self.config),
            core_status=core_status,
            system_proxy_state=self.system_proxy.get_state(),
            network_mode=self.network_mode,
            is_admin=self._process_is_admin(),
            runtime_state_path=self.runtime_state.path,
            geo_update_status=self.geo_updater.status(),
            autostart_status=self.autostart.status(),
            runtime_snapshot=runtime_snapshot,
        )
        payload["runtime_service_running"] = bool(self.running)
        payload["core_running"] = core_running
        payload["core_cleanup_pending"] = core_cleanup_pending
        payload["dns_resolver"] = self._dns_resolver_status_summary()
        payload["startup_failure_reason"] = str(
            getattr(self, "_source_supply_no_egress_reason", "") or ""
        )
        payload["startup_failure_detail"] = str(
            getattr(self, "_source_supply_no_egress_detail", "") or ""
        )
        manager = self.manager
        monitor_alive = bool(
            self.monitor_thread and self.monitor_thread.is_alive()
        )
        runtime_background_activity = self._runtime_background_activity()
        runtime_background_active = any(
            runtime_background_activity.values()
        )
        shutdown_cleanup_pending = bool(
            last_stop_failed
            and (
                self.running
                or core_running
                or core_cleanup_pending
                or manager is not None
                or monitor_alive
                or runtime_background_active
            )
        )
        payload["shutdown_cleanup_pending"] = shutdown_cleanup_pending
        payload["runtime_background_activity"] = dict(
            runtime_background_activity
        )
        payload["runtime_background_active"] = runtime_background_active
        payload["exit_quality_refresh_active"] = bool(
            runtime_background_activity.get("exit_quality_refresh")
        )
        traffic_capture_active = bool(
            getattr(manager, "tier3_traffic_capture_active", False)
        ) if manager else bool(self.system_proxy.active)
        effective_egress_ok = getattr(manager, "effective_egress_ok", None) if manager else None
        payload["traffic_capture_active"] = traffic_capture_active
        payload["effective_egress_ok"] = effective_egress_ok
        readiness = getattr(self, "_runtime_egress_readiness", None)
        if isinstance(readiness, RuntimeEgressReadiness):
            payload["validation_active"] = bool(readiness.validation_active)
            payload["readiness_state"] = readiness.state.value
            payload["readiness_reason"] = str(readiness.reason or "")
            payload["validation_deadline_monotonic"] = float(
                readiness.deadline_monotonic or 0.0
            )
            payload["readiness_lifecycle_revision"] = int(
                readiness.lifecycle_revision
            )
            payload["readiness_route_epoch"] = int(readiness.route_epoch)
            payload["readiness_network_context_epoch"] = int(
                readiness.network_context_epoch
            )
        else:
            payload["validation_active"] = False
            payload["readiness_state"] = (
                "ready" if effective_egress_ok is True else "fail_closed"
            )
            payload["readiness_reason"] = ""
            payload["validation_deadline_monotonic"] = 0.0
            payload["readiness_lifecycle_revision"] = int(
                getattr(self, "_lifecycle_revision", 0) or 0
            )
            payload["readiness_route_epoch"] = int(
                getattr(self, "_runtime_route_epoch", 0) or 0
            )
            payload["readiness_network_context_epoch"] = int(
                getattr(self, "_runtime_network_context_epoch", 0) or 0
            )
        payload["core_standby"] = bool(
            core_running
            and not startup_terminal_failed
            and effective_egress_ok is not True
            and not traffic_capture_active
        )
        payload["core_generation"] = self._core_generation
        payload.update(self._overview_deferral_status_fields())
        payload["last_core_stop"] = dict(self._last_core_stop)
        payload["runtime_generation"] = self._runtime_generation
        last_runtime_stop = copy.deepcopy(self._last_runtime_stop)
        payload["last_runtime_stop"] = last_runtime_stop
        payload["stop_error_code"] = str(
            last_runtime_stop.get("error_code") or ""
        )
        stop_error_details = last_runtime_stop.get("error_details")
        payload["stop_error_details"] = (
            copy.deepcopy(stop_error_details)
            if isinstance(stop_error_details, dict)
            else {}
        )
        with self._runtime_intent_lock:
            stop_request_pending = bool(self._stop_request_pending)
            lifecycle_revision = int(self._lifecycle_revision)
        payload["stop_request_pending"] = stop_request_pending
        payload["lifecycle_revision"] = lifecycle_revision
        payload["route_context"] = self.current_route_context()
        start_deferred_reason = (
            str(self._start_deferred_reason or effective_last_error or "").strip()
            if self.running and not core_running and not startup_terminal_failed
            else ""
        )
        live_collection_reason = ""
        if self.running and not core_running and manager is not None:
            try:
                live_collection_reason = self._tier3_startup_live_collection_reason(manager)
            except Exception:
                live_collection_reason = ""
        if live_collection_reason:
            start_deferred_reason = live_collection_reason
            payload["last_error"] = None
        payload["start_deferred"] = bool(start_deferred_reason)
        payload["start_deferred_reason"] = start_deferred_reason
        if stop_request_pending:
            startup_phase = "stopping"
        elif (
            last_stop_failed
            and shutdown_cleanup_pending
        ):
            startup_phase = "failed"
        elif self.running and self.stop_event.is_set():
            startup_phase = "stopping"
        elif not self.running:
            startup_phase = "stopped"
        elif startup_terminal_failed:
            startup_phase = "failed"
        elif core_running and effective_egress_ok is True:
            startup_phase = "running"
        elif core_running:
            startup_phase = "core_standby"
        elif start_deferred_reason and (live_collection_reason or self._start_deferred_is_live):
            startup_phase = "collecting"
        elif effective_last_error:
            startup_phase = "failed"
        elif self._tier3_required_for_start:
            startup_phase = "collecting"
        else:
            startup_phase = "stopped"
        payload["startup_phase"] = startup_phase
        payload["last_runtime_route_audit"] = sanitize_diagnostic_payload(
            dict(self.last_runtime_route_audit or {}),
            namespace="runtime-route-audit",
        )
        payload["tier3_runtime_circuit"] = (
            self._tier3_runtime_circuit_snapshot().to_dict()
        )
        return payload

    def config_summary(self) -> dict[str, Any]:
        runtime_status = self.manager.get_node_status_snapshot() if self.manager else None
        summary = self.config_store.summary_with_status(runtime_status)
        manager = self.manager
        report = getattr(manager, "tier3_last_collection_report", None) if manager else None
        if isinstance(summary, dict):
            tier3 = dict(summary.get("tier3") or {})
            if not isinstance(report, dict) or not report:
                manager_source_count = 0
                try:
                    manager_source_count = max(0, int(getattr(manager, "tier3_source_count", 0) or 0))
                except (TypeError, ValueError):
                    manager_source_count = 0
                if manager_source_count > 0 and not isinstance(tier3.get("collection"), dict):
                    tier3["collection"] = {
                        "source_count": manager_source_count,
                        "configured_source_count": manager_source_count,
                        "source_fetch_ok": 0,
                        "source_fetch_failed": 0,
                        "source_fetch_pending": manager_source_count,
                    }
                    summary["tier3"] = tier3
                return summary

            def _count(*keys: str) -> int:
                for key in keys:
                    try:
                        return max(0, int(report.get(key) or 0))
                    except (TypeError, ValueError):
                        continue
                return 0

            tier3["collection"] = {
                "source_count": _count("source_count", "source_stream_source_count"),
                "configured_source_count": _count(
                    "configured_source_count",
                    "source_count",
                    "source_stream_source_count",
                ),
                "source_fetch_ok": _count("source_fetch_ok", "source_stream_source_fetch_ok"),
                "source_fetch_failed": _count("source_fetch_failed", "source_stream_source_fetch_failed"),
                "source_fetch_pending": _count("source_fetch_pending", "source_stream_source_fetch_pending"),
                "retryable_failed_sources": _count("retryable_failed_sources"),
                "source_retry_due_count": _count("source_retry_due_count"),
                "source_retry_due": bool(report.get("source_retry_due")),
                "runtime_proxy_retry_count": _count("runtime_proxy_retry_count"),
                "runtime_proxy_retry_success_count": _count("runtime_proxy_retry_success_count"),
                "dns_resolver_rung": str(report.get("dns_resolver_rung") or ""),
                "dns_resolver_reason": str(report.get("dns_resolver_reason") or ""),
                "dns_resolver_summary": str(report.get("dns_resolver_summary") or ""),
                "startup_failure_reason": str(report.get("startup_failure_reason") or ""),
                "startup_failure_detail": str(report.get("startup_failure_detail") or ""),
                "source_refill_trigger_reason": str(report.get("source_refill_trigger_reason") or ""),
                "discovered_source_units": _count(
                    "discovered_source_units",
                    "source_stream_discovered_source_unit_count",
                ),
                "fetched_source_units": _count(
                    "fetched_source_units",
                    "source_stream_fetched_source_unit_count",
                ),
                "failed_source_units": _count(
                    "failed_source_units",
                    "source_stream_failed_source_unit_count",
                ),
                "pending_source_units": _count(
                    "pending_source_units",
                    "source_stream_pending_source_unit_count",
                ),
            }
            summary["tier3"] = tier3
        return summary

    def configured_items(self) -> list[dict[str, Any]]:
        return self.config_store.configured_items()

    def read_local_config(self) -> dict[str, Any]:
        return self.config_store.read_local()

    def write_local_config(self, payload: dict[str, Any]) -> dict[str, Any]:
        return self._reload_after(lambda: self.config_store.write_local(payload))

    def update_local_config(
        self,
        updater: Callable[[dict[str, Any]], dict[str, Any] | None],
        *,
        target_tier: str | None = None,
    ) -> dict[str, Any]:
        """Atomically read, update, persist, and reload config.local.yaml.

        Structured settings editors must use this method instead of a separate
        ``read_local_config`` / ``write_local_config`` pair.  The latter can
        carry a stale full-document snapshot across a concurrent node draft
        transaction and overwrite its ``enabled`` state.
        """

        def action() -> dict[str, Any]:
            payload = self.config_store.read_local()
            updated = updater(payload)
            if updated is not None:
                if not isinstance(updated, dict):
                    raise TypeError("local configuration updater must return a mapping or None")
                payload = updated
            return self.config_store.write_local(payload)

        return self._reload_after(action, target_tier=target_tier)

    def apply_latency_policy_settings(self, max_latency_ms: int) -> dict[str, Any]:
        """Persist the shared primary/Gateway latency ceiling and, when live, recheck it.

        Saving while Core is stopped is deliberately persistence-only.  In
        particular, that path must not call any node self-check or Core reload.
        """

        maximum = validate_latency_policy_max_latency_ms(max_latency_ms)

        def apply(payload: dict[str, Any]) -> dict[str, Any]:
            return apply_latency_policy_config_payload(payload, maximum)

        saved = self.update_local_config(apply)
        core_running = bool(self.core_runner and self.core_runner.is_running())
        response: dict[str, Any] = {
            "saved": True,
            "save_result": saved,
            "maximum_ms": maximum,
            "core_running": core_running,
            "recheck_attempted": False,
            "recheck_order": [],
            "tier3_skipped": True,
            "status_counts": {"alive": 0, "slow": 0, "dead": 0},
            "checked": 0,
            "errors": [],
        }
        if not core_running:
            return response
        return self._recheck_latency_policy_into(response, commit_label=max_latency_ms)

    def recheck_latency_policy(self, *, user_commit_id: str = "") -> dict[str, Any]:
        """Recheck the already-saved latency ceiling; writes no configuration.

        Separate recheck entry (T-P2-10, approved by 决定_P2_ASK02 #2): the
        same exit/tier1/tier2 checks, evaluate_state and USER_GRAPH_CONFIG
        incremental_export reload as the live half of
        ``apply_latency_policy_settings``. While Core is stopped it does
        nothing, like that setter. An empty ``errors`` list means success.
        ``user_commit_id`` (optional) ties the Core reload to the caller's
        save; without it the setter's ``latency-policy:<max>:<ns>`` is used.
        The bridge runs the same two halves separately
        (``probe_latency_policy`` outside its network lock, then
        ``reload_latency_policy`` inside it); this entry runs both at once.
        """

        response = self._latency_recheck_response()
        if not response["core_running"]:
            return response
        return self._recheck_latency_policy_into(
            response, commit_label=response["maximum_ms"], user_commit_id=user_commit_id
        )

    def probe_latency_policy(self) -> dict[str, Any]:
        """Probe half of ``recheck_latency_policy`` (T-P2-RT2); no Core reload.

        Runs the exit/tier1/tier2 checks and evaluate_state only: no
        configuration write, no Core reload, no bridge lock. ``probe_owner``
        in the response records the runtime/Core the probe ran against;
        ``reload_latency_policy`` reloads only while that owner is unchanged
        and no stop was requested. Without a running, clean Core or while a
        stop is requested it probes nothing (no network check): ``probe_owner``
        is None and ``reload_latency_policy`` reports
        ``reload_skipped="not_running"``.
        """

        response = self._latency_recheck_response()
        owner = self._latency_recheck_owner() if response["core_running"] else None
        response["probe_owner"] = owner
        if owner is None:
            return response
        self._latency_recheck_probe_into(response)
        return response

    def reload_latency_policy(
        self, probe: dict[str, Any], *, user_commit_id: str = ""
    ) -> dict[str, Any]:
        """Reload half of ``recheck_latency_policy`` (T-P2-RT2).

        ``probe`` is a ``probe_latency_policy`` response. The USER_GRAPH_CONFIG
        incremental_export reload runs only when the probe ran and its
        runtime/Core owner is still current with no stop requested; otherwise
        the reload is abandoned: ``reload_skipped`` is ``"stopped"`` and
        ``errors`` is not empty (not applied). A probe taken without a
        running, clean Core (or while a stop was requested) probed nothing:
        ``reload_skipped`` is ``"not_running"``, also with ``errors``. An
        empty ``errors`` list means success, as for ``recheck_latency_policy``.
        """

        response = copy.deepcopy(dict(probe or {}))
        response["errors"] = list(response.get("errors") or [])
        owner = response.pop("probe_owner", None)
        if owner is None and not response.get("recheck_attempted"):
            response["reload_skipped"] = "not_running"
            response["errors"].append(
                {"scope": "core_reload", "error": "Core was not running at the probe"}
            )
            return response
        if not response.get("recheck_attempted"):
            return response
        if owner is None or owner != self._latency_recheck_owner():
            response["reload_skipped"] = "stopped"
            response["errors"].append(
                {"scope": "core_reload", "error": "stopped before the Core reload"}
            )
            return response
        return self._latency_recheck_reload_into(
            response,
            commit_label=response.get("maximum_ms"),
            user_commit_id=user_commit_id,
        )

    def _latency_recheck_response(self) -> dict[str, Any]:
        """Base response of the saved-value recheck entries (no side effects)."""

        try:
            maximum = int(primary_gateway_max_latency_ms_from_testing(self._testing_block()))
        except Exception:
            maximum = None
        core_running = bool(self.core_runner and self.core_runner.is_running())
        return {
            "saved": False,
            "maximum_ms": maximum,
            "core_running": core_running,
            "recheck_attempted": False,
            "recheck_order": [],
            "tier3_skipped": True,
            "status_counts": {"alive": 0, "slow": 0, "dead": 0},
            "checked": 0,
            "errors": [],
        }

    def _latency_recheck_owner(self) -> tuple[int, int, Any] | None:
        """(runtime generation, Core generation, Core pid), or None when stopping.

        None while a stop is requested / not desired or without a running,
        clean Core. No Mihomo read.
        """

        with self._runtime_intent_lock:
            if self._stop_request_pending or not self._desired_running:
                return None
            generation = int(self._runtime_generation)
        core = self.core_fact()
        if not core["running"] or core["cleanup_pending"]:
            return None
        return generation, int(core["core_generation"]), core["pid"]

    def _recheck_latency_policy_into(
        self, response: dict[str, Any], *, commit_label: Any, user_commit_id: str = ""
    ) -> dict[str, Any]:
        """Live recheck shared by the setter and ``recheck_latency_policy``."""

        if not self._latency_recheck_probe_into(response):
            return response
        return self._latency_recheck_reload_into(
            response, commit_label=commit_label, user_commit_id=user_commit_id
        )

    def _latency_recheck_probe_into(self, response: dict[str, Any]) -> bool:
        """Probe half: checks + evaluate_state. False when nothing could run."""

        manager = self.manager
        if manager is None:
            response["errors"].append(
                {"scope": "recheck", "error": "manager service is not running"}
            )
            return False

        response["recheck_attempted"] = True
        tested_nodes: list[Node] = []
        checks = (
            ("exit", lambda: manager.check_exit(force_remote_refresh=False)),
            ("tier1", manager.check_tier1),
            ("tier2", lambda: manager.check_tier2(force_remote_refresh=False)),
        )
        for scope, check in checks:
            response["recheck_order"].append(scope)
            try:
                tested_nodes.extend(list(check() or []))
            except Exception as exc:
                response["errors"].append({"scope": scope, "error": str(exc)})
                log_raw_diagnostic(
                    self.logger,
                    "warning",
                    "Latency policy recheck failed for %s: %s",
                    scope,
                    str(exc),
                    exc_info=True,
                )

        try:
            manager.evaluate_state()
        except Exception as exc:
            response["errors"].append({"scope": "evaluate", "error": str(exc)})
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Latency policy recheck state evaluation failed: %s",
                str(exc),
                exc_info=True,
            )

        alive = sum(node.status is NodeStatus.ALIVE for node in tested_nodes)
        slow = sum(node.status is NodeStatus.SLOW for node in tested_nodes)
        response["status_counts"] = {
            "alive": alive,
            "slow": slow,
            "dead": max(0, len(tested_nodes) - alive - slow),
        }
        response["checked"] = len(tested_nodes)
        return True

    def _latency_recheck_reload_into(
        self, response: dict[str, Any], *, commit_label: Any, user_commit_id: str = ""
    ) -> dict[str, Any]:
        """Reload half: the USER_GRAPH_CONFIG incremental_export Core reload."""

        try:
            reload_result = self.reload_core_config(
                mode="incremental_export",
                reason=RuntimeReloadReason.USER_GRAPH_CONFIG,
                user_commit_id=(
                    str(user_commit_id or "")
                    or f"latency-policy:{commit_label}:{time.monotonic_ns()}"
                ),
            )
            response["reload"] = reload_result
            if not bool(reload_result.get("reloaded")):
                response["errors"].append(
                    {
                        "scope": "core_reload",
                        "error": str(reload_result.get("reason") or "Core reload was not confirmed"),
                    }
                )
        except Exception as exc:
            response["errors"].append({"scope": "core_reload", "error": str(exc)})
            log_raw_diagnostic(
                self.logger,
                "warning",
                "Latency policy Core reload failed: %s",
                str(exc),
                exc_info=True,
            )
        return response

    def write_ui_preferences(self, preferences: dict[str, Any]) -> dict[str, Any]:
        # UI preferences share config.local.yaml with node drafts. Keep this
        # read-modify-write inside the same lock as node transactions so a
        # concurrent preference save cannot overwrite a node enable/disable.
        with self._config_change_lock:
            payload = self.config_store.read_local()
            ui = apply_ui_preferences_to_payload(payload, preferences)
            result = self.config_store.write_local(payload)
            apply_runtime_ui_preferences(self.config, ui)
            # T-P2-RT2: a runtime without an AlertManager has no language to sync.
            alerts = getattr(self, "alerts", None)
            if alerts is not None:
                alerts.set_language(self._configured_ui_language())
            return result

    def update_local_preferences(
        self,
        updater: Callable[[dict[str, Any]], dict[str, Any] | None],
    ) -> dict[str, Any]:
        """Locked read-update-write of config.local.yaml WITHOUT ``reload_config``.

        T-P2-RT2 (决定_第二波裁定 P2-10 #1): the bridge's ui and traffic
        sections (including D8 ``ui.start_in_tray_on_autostart``). Inside
        ``_config_change_lock``: read_local -> updater -> write_local; then the
        written ``ui`` block is merged into ``self.config`` with
        ``apply_runtime_ui_preferences`` (``traffic`` is merged the same way;
        nothing in the runtime consumes it) and the alert language is synced
        when an AlertManager exists. Never calls ``reload_config``, never
        touches Core, manager or the traffic monitor. Callers must only change
        ui/traffic keys: other edits are written but not loaded until the next
        reload. Qt never calls this.
        """
        with self._config_change_lock:
            payload = self.config_store.read_local()
            updated = updater(payload)
            if updated is not None:
                if not isinstance(updated, dict):
                    raise TypeError("local configuration updater must return a mapping or None")
                payload = updated
            result = self.config_store.write_local(payload)
            config = self.config if isinstance(self.config, dict) else None
            if config is not None:
                ui = payload.get("ui")
                if isinstance(ui, dict):
                    apply_runtime_ui_preferences(config, copy.deepcopy(ui))
                traffic = payload.get("traffic")
                if isinstance(traffic, dict):
                    merged = config.get("traffic")
                    merged = dict(merged) if isinstance(merged, dict) else {}
                    merged.update(copy.deepcopy(traffic))
                    config["traffic"] = merged
            alerts = getattr(self, "alerts", None)
            if alerts is not None:
                alerts.set_language(self._configured_ui_language())
            return result

    def read_sources_config(self) -> dict[str, Any]:
        return self.config_store.read_sources()

    def write_sources_config(self, payload: dict[str, Any]) -> dict[str, Any]:
        return self._reload_after(lambda: self.config_store.write_sources(payload))

    def delete_config_item(self, payload: dict[str, Any]) -> dict[str, Any]:
        target_tier = str(payload.get("tier") or "").strip() or None
        return self._reload_after(lambda: self.config_store.delete_config_item(payload), target_tier=target_tier)

    def update_config_item(self, item: dict[str, Any], updates: dict[str, Any]) -> dict[str, Any]:
        target_tier = str(item.get("tier") or "").strip() or None
        if str(item.get("kind") or "").strip() in {"node", "subscription"}:
            return self._update_node_config_item_transaction(
                item,
                updates,
                target_tier=target_tier,
            )
        return self._reload_after(lambda: self.config_store.update_config_item(item, updates), target_tier=target_tier)

    @staticmethod
    def _strict_core_reload_confirmed(result: Any) -> bool:
        if not isinstance(result, dict) or result.get("kept_existing_core"):
            return False
        if result.get("reloaded"):
            return True
        return bool(result.get("running"))

    def _manager_runtime_nodes_snapshot(self, manager: Any | None) -> dict[str, list[Any]] | None:
        if manager is None:
            return None
        manager_lock = getattr(manager, "lock", self._config_change_lock)
        with manager_lock:
            runtime_nodes = getattr(manager, "runtime_nodes", None)
            if not isinstance(runtime_nodes, dict):
                return None
            return {
                str(tier): self._clone_runtime_nodes(list(nodes))
                for tier, nodes in runtime_nodes.items()
                if isinstance(nodes, list)
            }

    def _restore_manager_runtime_snapshot(
        self,
        manager: Any | None,
        runtime_nodes: dict[str, list[Any]] | None,
    ) -> bool:
        if manager is None:
            return True
        try:
            manager_lock = getattr(manager, "lock", self._config_change_lock)
            with manager_lock:
                manager.config = self.config
                if runtime_nodes is not None:
                    manager.runtime_nodes = {
                        tier: self._clone_runtime_nodes(nodes)
                        for tier, nodes in runtime_nodes.items()
                    }
            return True
        except Exception:
            log_raw_diagnostic(
                self.logger,
                "error",
                "Failed to restore manager state after node configuration rollback",
                exc_info=True,
            )
            return False

    def _stop_core_after_unconfirmed_node_update(self, reason: str) -> None:
        log_raw_diagnostic(
            self.logger,
            "error",
            "Stopping mihomo because node configuration rollback could not be confirmed: %s",
            reason,
        )
        try:
            self.stop_core(actor="node-config-rollback", reason=reason)
        except Exception:
            log_raw_diagnostic(
                self.logger,
                "error",
                "Normal core stop failed after unconfirmed node configuration rollback",
                exc_info=True,
            )
        runner = self.core_runner
        if runner is None:
            return
        try:
            if runner.is_running():
                runner.stop()
        except Exception:
            log_raw_diagnostic(
                self.logger,
                "error",
                "Emergency core stop failed after unconfirmed node configuration rollback",
                exc_info=True,
            )

    def _rollback_node_config_item_update(
        self,
        *,
        local_config_snapshot: dict[str, Any],
        runtime_config_snapshot: dict[str, Any],
        manager: Any | None,
        manager_nodes_snapshot: dict[str, list[Any]] | None,
        target_tier: str | None,
    ) -> bool:
        config_file_restored = False
        runtime_reloaded = False
        try:
            self.config_store.write_local(copy.deepcopy(local_config_snapshot))
            config_file_restored = True
        except Exception:
            log_raw_diagnostic(
                self.logger,
                "error",
                "Failed to restore config.local.yaml after node configuration update failure",
                exc_info=True,
            )

        if config_file_restored:
            try:
                self.reload_config(target_tier=target_tier)
                runtime_reloaded = True
            except Exception:
                log_raw_diagnostic(
                    self.logger,
                    "error",
                    "Failed to reload restored node configuration",
                    exc_info=True,
                )
                self.config = copy.deepcopy(runtime_config_snapshot)
        else:
            self.config = copy.deepcopy(runtime_config_snapshot)

        manager_restored = self._restore_manager_runtime_snapshot(
            manager,
            manager_nodes_snapshot,
        )
        return config_file_restored and runtime_reloaded and manager_restored

    def _update_node_config_item_transaction(
        self,
        item: dict[str, Any],
        updates: dict[str, Any],
        *,
        target_tier: str | None,
    ) -> dict[str, Any]:
        with self._config_change_lock:
            manager = self.manager
            operation_lock = getattr(manager, "operation_lock", self._config_change_lock)
            with operation_lock:
                user_commit_id = f"node-config:{time.monotonic_ns()}"
                effective_updates = dict(updates)
                item_kind = str(item.get("kind") or "").strip()
                if (
                    item_kind == "subscription"
                    and str(item.get("tier") or "").strip() == "exit"
                    and "enabled" in effective_updates
                    and not config_entry_enabled(
                        {"enabled": effective_updates.get("enabled")}
                    )
                    and manager is not None
                ):
                    try:
                        selection = selection_from_manager(manager)
                    except Exception:
                        selection = None
                    source_matcher = getattr(manager, "_node_has_subscription_source", None)
                    exit_nodes = getattr(manager, "runtime_nodes", {}).get("exit", [])
                    # A bound selection's own node(s), by identity: disabling
                    # the subscription of a same-named twin keeps the Gateway.
                    # A name-only selection keeps the name rule: disabling the
                    # source of a node with its name turns it off (a surviving
                    # namesake was never proven to be the pick).
                    if selection is not None and selection.state == "bound":
                        selected_nodes = selected_gateway_nodes(selection, exit_nodes)
                    elif selection is not None and selection.active:
                        selected_nodes = [
                            node
                            for node in exit_nodes
                            if getattr(node, "name", "") == selection.label
                        ]
                    else:
                        selected_nodes = []
                    source_url = str(item.get("url") or item.get("key") or "").strip()
                    if selected_nodes and source_url and callable(source_matcher):
                        enabled_sources_getter = getattr(manager, "_exit_subscription_urls", None)
                        enabled_sources = (
                            list(enabled_sources_getter())
                            if callable(enabled_sources_getter)
                            else []
                        )
                        remaining_sources = {
                            str(url or "").strip()
                            for url in enabled_sources
                            if str(url or "").strip() and str(url or "").strip() != source_url
                        }
                        if any(
                            source_matcher(node, source_url)
                            and not any(
                                source_matcher(node, remaining_source)
                                for remaining_source in remaining_sources
                            )
                            for node in selected_nodes
                        ):
                            effective_updates["_clear_exit_selection"] = True
                local_config_snapshot = copy.deepcopy(self.config_store.read_local())
                runtime_config_snapshot = copy.deepcopy(self.config)
                manager_nodes_snapshot = self._manager_runtime_nodes_snapshot(manager)
                core_was_running = bool(
                    self.core_runner is not None
                    and self.core_runner.is_running()
                )
                persistent_update_completed = False
                try:
                    result = self.config_store.update_config_item(item, effective_updates)
                    persistent_update_completed = True
                    self.reload_config(target_tier=target_tier)
                    if core_was_running:
                        reload_result = self.reload_core_config(
                            mode="strict",
                            reason=RuntimeReloadReason.USER_GRAPH_CONFIG,
                            user_commit_id=user_commit_id,
                        )
                        if not self._strict_core_reload_confirmed(reload_result):
                            raise RuntimeError(
                                "strict core reload did not confirm the updated node configuration"
                            )
                    response = dict(result)
                    response["node_config_transaction"] = True
                    response["kind"] = item_kind
                    if "enabled" in effective_updates:
                        response["enabled"] = config_entry_enabled(
                            {"enabled": effective_updates.get("enabled")}
                        )
                    return response
                except Exception as exc:
                    if not persistent_update_completed:
                        try:
                            config_unchanged = (
                                self.config_store.read_local() == local_config_snapshot
                            )
                        except Exception:
                            config_unchanged = False
                        if config_unchanged:
                            raise
                    rollback_restored = self._rollback_node_config_item_update(
                        local_config_snapshot=local_config_snapshot,
                        runtime_config_snapshot=runtime_config_snapshot,
                        manager=manager,
                        manager_nodes_snapshot=manager_nodes_snapshot,
                        target_tier=target_tier,
                    )
                    rollback_core_confirmed = not core_was_running
                    if core_was_running and rollback_restored:
                        try:
                            rollback_reload = self.reload_core_config(
                                mode="strict",
                                reason=RuntimeReloadReason.USER_GRAPH_CONFIG,
                                user_commit_id=f"{user_commit_id}:rollback",
                            )
                            rollback_core_confirmed = self._strict_core_reload_confirmed(
                                rollback_reload
                            )
                        except Exception:
                            rollback_core_confirmed = False
                            log_raw_diagnostic(
                                self.logger,
                                "error",
                                "Failed to reapply restored node configuration to mihomo",
                                exc_info=True,
                            )
                    if core_was_running and (
                        not rollback_restored or not rollback_core_confirmed
                    ):
                        self._stop_core_after_unconfirmed_node_update(str(exc))
                    raise RuntimeError(
                        f"Node configuration update was rolled back: {exc}"
                    ) from exc

